(* ========================================================================= *)
(* Relative consistency of AC and GCH with ZF, via Godel's constructible     *)
(* universe L.                                                               *)
(*                                                                           *)
(* The object logic is first-order set theory whose only nonlogical symbol   *)
(* is the binary membership relation. There are no function symbols or       *)
(* constants, so terms are just variables, represented directly by their     *)
(* numeric indices; equality is a logical primitive with fixed identity      *)
(* semantics. All derived set-theoretic concepts are meta-level formula      *)
(* abbreviations, keeping structural inductions over formulas down to five   *)
(* cases.                                                                    *)
(*                                                                           *)
(* A model is a domain predicate D:A->bool together with a membership        *)
(* relation E:A->A->bool over some ambient type A. Inside any model of ZF    *)
(* we build the constructible hierarchy and the class L, and show that L,    *)
(* a submodel with the same membership relation, satisfies ZF + V=L, hence   *)
(* AC (ZF_MODEL_AC_MODEL) and GCH (ZF_MODEL_GCH_MODEL):                      *)
(*                                                                           *)
(*   |- !D E. model D E ZF_AX                                                *)
(*            ==> ?D'. D' SUBSET D /\                                        *)
(*                     model D' E (gch_ax INSERT choice_ax INSERT ZF_AX)     *)
(*                                                                           *)
(* The cardinal arithmetic needed for GCH comes from the condensation        *)
(* argument (Mostowski collapse of an elementary hull). As corollaries,      *)
(* MODEL_VL_CH states CH semantically in a model of ZF + V=L (the power set  *)
(* of omega has the successor cardinal of omega as its cardinality), and     *)
(* ZF_MODEL_CH_MODEL gives a submodel of ZF + AC + ch_ax, where ch_ax is the *)
(* object-language form of CH; godel_forcing.ml builds models of its         *)
(* negation.                                                                 *)
(* ========================================================================= *)

prioritize_num();;

(* ------------------------------------------------------------------------- *)
(* Syntax of formulas. Object variables are numbered, and since the          *)
(* language has no function symbols there is no separate type of terms:      *)
(* atomic formulas are just membership and equality of variables.            *)
(* ------------------------------------------------------------------------- *)

parse_as_infix("%%",(18,"right"));;
parse_as_infix("&&",(16,"right"));;
parse_as_infix("||",(15,"right"));;
parse_as_infix("-->",(14,"right"));;
parse_as_infix("<->",(13,"right"));;

let form_INDUCT,form_RECURSION = define_type
  "form = False
        | %% num num
        | Eq num num
        | --> form form
        | !! num form";;

(* ------------------------------------------------------------------------- *)
(* Definitions of the other connectives and quantifiers, including the       *)
(* bounded quantifiers ("for all x in y" and "for some x in y") that         *)
(* pervade set theory.                                                       *)
(* ------------------------------------------------------------------------- *)

let Not_DEF = new_definition
  `Not p = p --> False`;;

let True_DEF = new_definition
  `True = Not False`;;

let And_DEF = new_definition
  `p && q = Not(p --> Not q)`;;

let Or_DEF = new_definition
  `p || q = Not(p) --> q`;;

let Iff_DEF = new_definition
  `(p <-> q) = (p --> q) && (q --> p)`;;

let Exists_DEF = new_definition
  `?? x p = Not(!! x (Not p))`;;

let Forallmem_DEF = new_definition
  `!!- x y p = !! x ((x %% y) --> p)`;;

let Existsmem_DEF = new_definition
  `??- x y p = ?? x ((x %% y) && p)`;;

(* ------------------------------------------------------------------------- *)
(* Free variables of a formula, and their basic properties.                  *)
(* ------------------------------------------------------------------------- *)

let FV = new_recursive_definition form_RECURSION
  `(FV False = {}) /\
   (FV (i %% j) = {i,j}) /\
   (FV (Eq i j) = {i,j}) /\
   (FV (p --> q) = FV(p) UNION FV(q)) /\
   (FV (!! x p) = FV(p) DELETE x)`;;

let FV_CLAUSES = prove
 (`FV(True) = {} /\
   (!p. FV(Not p) = FV(p)) /\
   (!p q. FV(p && q) = FV(p) UNION FV(q)) /\
   (!p q. FV(p || q) = FV(p) UNION FV(q)) /\
   (!p q. FV(p <-> q) = FV(p) UNION FV(q)) /\
   (!x p. FV(?? x p) = FV(p) DELETE x) /\
   (!x y p. FV(!!- x y p) = (y INSERT FV(p)) DELETE x) /\
   (!x y p. FV(??- x y p) = (y INSERT FV(p)) DELETE x)`,
  REWRITE_TAC[True_DEF; Not_DEF; And_DEF; Or_DEF; Iff_DEF; Exists_DEF;
              Forallmem_DEF; Existsmem_DEF; FV] THEN
  SET_TAC[]);;

let FV_FINITE = prove
 (`!p. FINITE(FV p)`,
  MATCH_MP_TAC form_INDUCT THEN
  SIMP_TAC[FV; FINITE_EMPTY; FINITE_INSERT; FINITE_UNION; FINITE_DELETE]);;

(* ------------------------------------------------------------------------- *)
(* An inexhaustible supply of variables fresh for any finite set, hence in   *)
(* particular for the free variables of any formula. This is what lets us    *)
(* instantiate the axiom schemes without any syntactic freshness bureaucracy *)
(* at the point of use.                                                      *)
(* ------------------------------------------------------------------------- *)

let VARIANTS_EXIST = prove
 (`!s:num->bool. FINITE s ==> ?n. !k. n <= k ==> ~(k IN s)`,
  GEN_TAC THEN REWRITE_TAC[num_FINITE] THEN
  DISCH_THEN(X_CHOOSE_TAC `a:num`) THEN EXISTS_TAC `a + 1` THEN
  ASM_MESON_TAC[ARITH_RULE `~(a + 1 <= k /\ k <= a)`]);;

(* ------------------------------------------------------------------------- *)
(* Modification ("updating") of a valuation, as in Arithmetic/fol.ml.        *)
(* ------------------------------------------------------------------------- *)

parse_as_infix("|->",(22,"right"));;

let valmod = new_definition
  `(x |-> a) (v:A->B) = \y. if y = x then a else v(y)`;;

let VALMOD = prove
 (`!(v:A->B) x y a. ((x |-> y) v) a = if a = x then y else v(a)`,
  REWRITE_TAC[valmod]);;

let VALMOD_BASIC = prove
 (`!(v:A->B) x y. (x |-> y) v x = y`,
  REWRITE_TAC[valmod]);;

let VALMOD_OTHER = prove
 (`!v x y a. ~(y = x) ==> ((x |-> a) (v:A->B)) y = v y`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[valmod] THEN
  ASM_REWRITE_TAC[]);;

let VALMOD_SWAP = prove
 (`!(v:A->B) x y a b.
     ~(x = y) ==> ((x |-> a) ((y |-> b) v) = (y |-> b) ((x |-> a) v))`,
  REWRITE_TAC[valmod; FUN_EQ_THM] THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Semantics: satisfaction of a formula in a model, which is given by a      *)
(* domain D:A->bool and a binary relation E:A->A->bool interpreting          *)
(* membership. Equality is interpreted as actual equality on the domain      *)
(* ("normal models"). Only the values of a valuation inside D and of E on    *)
(* D ever matter.                                                            *)
(* ------------------------------------------------------------------------- *)

let holds = new_recursive_definition form_RECURSION
  `(holds D (E:A->A->bool) (v:num->A) False <=> F) /\
   (holds D E v (i %% j) <=> E (v i) (v j)) /\
   (holds D E v (Eq i j) <=> v(i) = v(j)) /\
   (holds D E v (p --> q) <=> holds D E v p ==> holds D E v q) /\
   (holds D E v (!! x p) <=> !a. a IN D ==> holds D E ((x |-> a) v) p)`;;

let HOLDS_TRUE = prove
 (`!D (E:A->A->bool) v. holds D E v True`,
  REWRITE_TAC[True_DEF; Not_DEF; holds]);;

let HOLDS_NOT = prove
 (`!D (E:A->A->bool) v p. holds D E v (Not p) <=> ~(holds D E v p)`,
  REWRITE_TAC[Not_DEF; holds]);;

let HOLDS_AND = prove
 (`!D (E:A->A->bool) v p q.
        holds D E v (p && q) <=> holds D E v p /\ holds D E v q`,
  REWRITE_TAC[And_DEF; Not_DEF; holds] THEN REPEAT GEN_TAC THEN
  CONV_TAC TAUT);;

let HOLDS_OR = prove
 (`!D (E:A->A->bool) v p q.
        holds D E v (p || q) <=> holds D E v p \/ holds D E v q`,
  REWRITE_TAC[Or_DEF; Not_DEF; holds] THEN REPEAT GEN_TAC THEN
  CONV_TAC TAUT);;

let HOLDS_IFF = prove
 (`!D (E:A->A->bool) v p q.
        holds D E v (p <-> q) <=> (holds D E v p <=> holds D E v q)`,
  REWRITE_TAC[Iff_DEF; And_DEF; Not_DEF; holds] THEN REPEAT GEN_TAC THEN
  CONV_TAC TAUT);;

let HOLDS_EX = prove
 (`!D (E:A->A->bool) v x p.
        holds D E v (?? x p) <=>
        ?a. a IN D /\ holds D E ((x |-> a) v) p`,
  REWRITE_TAC[Exists_DEF; Not_DEF; holds] THEN MESON_TAC[]);;

let HOLDS_FORALLMEM = prove
 (`!D (E:A->A->bool) v x y p.
        ~(x = y)
        ==> (holds D E v (!!- x y p) <=>
             !a. a IN D /\ E a (v y) ==> holds D E ((x |-> a) v) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[Forallmem_DEF; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN MESON_TAC[]);;

let HOLDS_EXISTSMEM = prove
 (`!D (E:A->A->bool) v x y p.
        ~(x = y)
        ==> (holds D E v (??- x y p) <=>
             ?a. a IN D /\ E a (v y) /\ holds D E ((x |-> a) v) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[Existsmem_DEF; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Satisfaction depends only on the values of the valuation at the free      *)
(* variables. This is the basic workhorse lemma about the semantics.         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_VALUATION = prove
 (`!D (E:A->A->bool) p v v'.
        (!x. x IN FV(p) ==> v'(x) = v(x))
        ==> (holds D E v' p <=> holds D E v p)`,
  GEN_TAC THEN GEN_TAC THEN MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[holds; FV; IN_UNION; IN_DELETE; IN_INSERT; NOT_IN_EMPTY] THEN
  REPEAT CONJ_TAC THENL
   [MESON_TAC[]; MESON_TAC[]; MESON_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`x:num`; `p:form`] THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  AP_TERM_TAC THEN ABS_TAC THEN AP_TERM_TAC THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN
  X_GEN_TAC `z:num` THEN REWRITE_TAC[VALMOD] THEN
  DISCH_TAC THEN COND_CASES_TAC THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Discarding an update at a variable not free in the formula, under one or  *)
(* two enclosing updates. These (with more layers added as needed) are the   *)
(* workhorses for cleaning up the valuations that arise when instantiating   *)
(* axiom schemes at fresh variables.                                         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_VALMOD_STRIP1 = prove
 (`!D (E:A->A->bool) p u c v x z.
        ~(u IN FV p)
        ==> (holds D E ((x |-> z) ((u |-> c) v)) p <=>
             holds D E ((x |-> z) v) p)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HOLDS_VALUATION THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
  REPEAT(COND_CASES_TAC THEN REWRITE_TAC[]) THEN ASM_MESON_TAC[]);;

let HOLDS_VALMOD_STRIP2 = prove
 (`!D (E:A->A->bool) p u c v x z y w.
        ~(u IN FV p)
        ==> (holds D E ((x |-> z) ((y |-> w) ((u |-> c) v))) p <=>
             holds D E ((x |-> z) ((y |-> w) v)) p)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC HOLDS_VALUATION THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
  REPEAT(COND_CASES_TAC THEN REWRITE_TAC[]) THEN ASM_MESON_TAC[]);;

let HOLDS_VALMOD_SWAP = prove
 (`!D (E:A->A->bool) p v x y a b.
        ~(x = y)
        ==> (holds D E ((x |-> a) ((y |-> b) v)) p <=>
             holds D E ((y |-> b) ((x |-> a) v)) p)`,
  SIMP_TAC[VALMOD_SWAP]);;

(* ------------------------------------------------------------------------- *)
(* Valuations into a domain, satisfaction of sets of formulas, and models.   *)
(* Note that satisfaction quantifies over all valuations into the domain,    *)
(* so free variables in a formula are effectively universally quantified;    *)
(* axiom schemes below exploit this by using open formulas, the free         *)
(* variables of the scheme's parameter formula acting as parameters.         *)
(* Nonemptiness of the domain is required in the notion of model, since an   *)
(* empty domain has no valuations and so vacuously satisfies everything.     *)
(* ------------------------------------------------------------------------- *)

let valuation = new_definition
  `valuation (D:A->bool) (v:num->A) <=> !x. v(x) IN D`;;

let VALUATION_VALMOD = prove
 (`!D (v:num->A) x a.
        valuation D v /\ a IN D ==> valuation D ((x |-> a) v)`,
  REWRITE_TAC[valuation; VALMOD] THEN REPEAT STRIP_TAC THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[]);;

let VALUATION_EXISTS = prove
 (`!D:A->bool. ~(D = {}) ==> ?v. valuation D v`,
  REPEAT STRIP_TAC THEN EXISTS_TAC `(\n:num. CHOICE(D:A->bool))` THEN
  ASM_SIMP_TAC[valuation; CHOICE_DEF]);;

let satisfies = new_definition
  `satisfies D (E:A->A->bool) s <=>
        !v p. valuation D v /\ p IN s ==> holds D E v p`;;

let model = new_definition
  `model D (E:A->A->bool) s <=> ~(D = {}) /\ satisfies D E s`;;

(* ------------------------------------------------------------------------- *)
(* The ZF axioms. The closed axioms are given with concrete variable         *)
(* indices; the separation and replacement schemes are parameterized by      *)
(* the variables used as well as the formula, with side conditions in the    *)
(* definition of the axiom set below exactly matching the usual textbook     *)
(* provisos (the distinguished variables are distinct and do not occur       *)
(* free in the scheme formula except as indicated). Since satisfaction       *)
(* quantifies over all valuations, other free variables of the scheme        *)
(* formula act as universally quantified parameters.                         *)
(*                                                                           *)
(* Note that replacement is formulated without any use of substitution:      *)
(* "there is at most one y such that p" is rendered as ?z. !y. p ==> y = z   *)
(* with z fresh, rather than the usual p /\ p[y'/y] ==> y = y', so no        *)
(* formula substitution operation is ever needed to state the axioms.        *)
(* ------------------------------------------------------------------------- *)

let extensionality_ax = new_definition
  `extensionality_ax =
      !! 0 (!! 1 ((!! 2 ((2 %% 0) <-> (2 %% 1))) --> Eq 0 1))`;;

let foundation_ax = new_definition
  `foundation_ax =
      !! 0 ((?? 1 (1 %% 0)) --> ??- 1 0 (!!- 2 1 (Not(2 %% 0))))`;;

let pairing_ax = new_definition
  `pairing_ax =
      !! 0 (!! 1 (?? 2 (!! 3 ((3 %% 2) <-> Eq 3 0 || Eq 3 1))))`;;

let union_ax = new_definition
  `union_ax =
      !! 0 (?? 1 (!! 2 ((2 %% 1) <-> ??- 3 0 (2 %% 3))))`;;

let powerset_ax = new_definition
  `powerset_ax =
      !! 0 (?? 1 (!! 2 ((2 %% 1) <-> !!- 3 2 (3 %% 0))))`;;

let infinity_ax = new_definition
  `infinity_ax =
      ?? 0 ((??- 1 0 (!! 2 (Not(2 %% 1)))) &&
            (!!- 1 0 (??- 2 0 (!! 3 ((3 %% 2) <-> (3 %% 1) || Eq 3 1)))))`;;

let separation_ax = new_definition
  `separation_ax x a s p =
      !! a (?? s (!! x ((x %% s) <-> (x %% a) && p)))`;;

let replacement_ax = new_definition
  `replacement_ax x y z a b p =
      !! a ((!!- x a (?? z (!! y (p --> Eq y z)))) -->
            ?? b (!! y ((y %% b) <-> ??- x a p)))`;;

let ZF_AX = new_definition
  `ZF_AX =
      {extensionality_ax, foundation_ax, pairing_ax,
       union_ax, powerset_ax, infinity_ax} UNION
      {separation_ax x a s p | x,a,s,p |
           ~(a IN FV p) /\ ~(s IN FV p) /\
           ~(a = x) /\ ~(s = x) /\ ~(a = s)} UNION
      {replacement_ax x y z a b p | x,y,z,a,b,p |
           ~(z IN FV p) /\ ~(a IN FV p) /\ ~(b IN FV p) /\
           ~(x = y) /\ ~(x = z) /\ ~(x = a) /\ ~(x = b) /\
           ~(y = z) /\ ~(y = a) /\ ~(y = b) /\
           ~(z = a) /\ ~(z = b) /\ ~(a = b)}`;;

(* ------------------------------------------------------------------------- *)
(* The axioms hold in a model under every valuation, and the members of      *)
(* ZF_AX.                                                                    *)
(* ------------------------------------------------------------------------- *)

let MODEL_HOLDS = prove
 (`!D (E:A->A->bool) s p.
        model D E s /\ p IN s ==> !v. valuation D v ==> holds D E v p`,
  REWRITE_TAC[model; satisfies] THEN MESON_TAC[]);;

let MODEL_NONEMPTY = prove
 (`!D (E:A->A->bool) s. model D E s ==> ~(D = {})`,
  SIMP_TAC[model]);;

let ZF_AX_MEMBERS = prove
 (`extensionality_ax IN ZF_AX /\
   foundation_ax IN ZF_AX /\
   pairing_ax IN ZF_AX /\
   union_ax IN ZF_AX /\
   powerset_ax IN ZF_AX /\
   infinity_ax IN ZF_AX /\
   (!x a s p. ~(a IN FV p) /\ ~(s IN FV p) /\
              ~(a = x) /\ ~(s = x) /\ ~(a = s)
              ==> separation_ax x a s p IN ZF_AX) /\
   (!x y z a b p.
        ~(z IN FV p) /\ ~(a IN FV p) /\ ~(b IN FV p) /\
        ~(x = y) /\ ~(x = z) /\ ~(x = a) /\ ~(x = b) /\
        ~(y = z) /\ ~(y = a) /\ ~(y = b) /\
        ~(z = a) /\ ~(z = b) /\ ~(a = b)
        ==> replacement_ax x y z a b p IN ZF_AX)`,
  REWRITE_TAC[ZF_AX; IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_ELIM_THM] THEN
  MESON_TAC[]);;

(* ========================================================================= *)
(* The finite fragment zfw_ax of ZF. The condensation argument for GCH works *)
(* in a submodel that is only known to satisfy finitely many axioms of ZF,   *)
(* since that is what reflection provides (REFLECT_MODEL_PLUS). So the parts *)
(* of the basic theory that it needs are proved for models of a fixed finite *)
(* fragment zfw_ax, defined in this section. In the sections that follow,    *)
(* each such lemma NAME about models of ZF_AX comes right after its version  *)
(* NAME_F for models of zfw_ax, from which it follows by ZF_OF_ZFW. Where    *)
(* the proof needs separation or replacement for an arbitrary formula        *)
(* (induction and recursion), NAME_F and NAME both follow from a version     *)
(* NAME_GEN for models of any axiom set containing zfw_ax and the instances  *)
(* needed (omega_ready, engine_ready).                                       *)
(* The fragment consists of the closed axioms and the instances of           *)
(* separation and replacement used by that part of the basic theory. These   *)
(* mention the formula macros, which are therefore defined here, with their  *)
(* free-variable lemmas; their semantics (the HOLDS_* lemmas) comes later,   *)
(* next to the semantic notions that they express.                           *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* The axiom-extraction layer for an arbitrary axiom set s. Each ZFG_* lemma *)
(* is the corresponding ZF_* lemma below with model D E ZF_AX replaced by    *)
(* model D E s plus the hypothesis that the axiom used is in s (and, for the *)
(* schemes, caller-supplied witness slots n with freshness side conditions). *)
(* These are the only lemmas that unpack the axioms of a model directly;     *)
(* everything else goes through them.                                        *)
(* ------------------------------------------------------------------------- *)

let ZFG_EXTENSIONALITY = prove
 (`!D (E:A->A->bool) s. model D E s /\ extensionality_ax IN s
     ==> !x y. x IN D /\ y IN D /\
               (!z. z IN D ==> (E z x <=> E z y))
               ==> x = y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v extensionality_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  REWRITE_TAC[extensionality_ax; holds; HOLDS_IFF; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_PAIRING = prove
 (`!D (E:A->A->bool) s. model D E s /\ pairing_ax IN s
     ==> !x y. x IN D /\ y IN D
               ==> ?p. p IN D /\
                       !z. z IN D ==> (E z p <=> z = x \/ z = y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v pairing_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  SIMP_TAC[pairing_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT; HOLDS_AND;
           HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_UNION = prove
 (`!D (E:A->A->bool) s. model D E s /\ union_ax IN s
     ==> !x. x IN D
             ==> ?u. u IN D /\
                     !z. z IN D
                         ==> (E z u <=> ?w. w IN D /\ E w x /\ E z w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v union_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  SIMP_TAC[union_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT; HOLDS_AND;
           HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_POWERSET = prove
 (`!D (E:A->A->bool) s. model D E s /\ powerset_ax IN s
     ==> !x. x IN D
             ==> ?pp. pp IN D /\
                      !z. z IN D
                          ==> (E z pp <=> !w. w IN D /\ E w z ==> E w x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v powerset_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  SIMP_TAC[powerset_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT; HOLDS_AND;
           HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_FOUNDATION = prove
 (`!D (E:A->A->bool) s. model D E s /\ foundation_ax IN s
     ==> !x. x IN D /\ (?u. u IN D /\ E u x)
             ==> ?y. y IN D /\ E y x /\
                     !z. z IN D /\ E z y ==> ~(E z x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v foundation_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  SIMP_TAC[foundation_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT; HOLDS_AND;
           HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_INFINITY = prove
 (`!D (E:A->A->bool) s. model D E s /\ infinity_ax IN s
     ==> ?i. i IN D /\
             (?e. e IN D /\ E e i /\ !z. z IN D ==> ~(E z e)) /\
             (!u. u IN D /\ E u i
                  ==> ?s. s IN D /\ E s i /\
                          !z. z IN D ==> (E z s <=> E z u \/ z = u))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v infinity_ax` MP_TAC THENL
   [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  SIMP_TAC[infinity_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT; HOLDS_AND;
           HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD; ARITH_EQ] THEN
  MESON_TAC[]);;

let ZFG_SEPARATION = prove
 (`!D (E:A->A->bool) s p x n v a.
        model D E s /\
        ~(n = x) /\ ~(n + 1 = x) /\ ~(n IN FV p) /\ ~(n + 1 IN FV p) /\
        separation_ax x n (n + 1) p IN s /\
        valuation D v /\ a IN D
        ==> ?ss. ss IN D /\
                 !z. z IN D
                     ==> (E z ss <=> E z a /\ holds D E ((x |-> z) v) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `~((n:num) = n + 1)` ASSUME_TAC THENL
   [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `holds D (E:A->A->bool) v (separation_ax x n (n+1) p)`
  MP_TAC THENL [ASM_MESON_TAC[MODEL_HOLDS]; ALL_TAC] THEN
  ASM_SIMP_TAC[separation_ax; holds; HOLDS_EX; HOLDS_IFF; HOLDS_AND;
               VALMOD_BASIC; VALMOD_OTHER; HOLDS_VALMOD_STRIP1]);;

let ZFG_REPLACEMENT = prove
 (`!D (E:A->A->bool) s p x y n v a.
        model D E s /\
        ~(x = y) /\
        ~((n:num) = x) /\ ~(n + 1 = x) /\ ~(n + 2 = x) /\
        ~((n:num) = y) /\ ~(n + 1 = y) /\ ~(n + 2 = y) /\
        ~(n IN FV p) /\ ~(n + 1 IN FV p) /\ ~(n + 2 IN FV p) /\
        replacement_ax x y n (n + 1) (n + 2) p IN s /\
        valuation D v /\ a IN D /\
        (!u. u IN D /\ E u a
             ==> ?w. w IN D /\
                     !w'. w' IN D /\
                          holds D E ((y |-> w') ((x |-> u) v)) p
                          ==> w' = w)
        ==> ?b. b IN D /\
                !w. w IN D
                    ==> (E w b <=>
                         ?u. u IN D /\ E u a /\
                             holds D E ((y |-> w) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `~((x:num) = n) /\ ~(x = n + 1) /\ ~(x = n + 2) /\
    ~((y:num) = n) /\ ~(y = n + 1) /\ ~(y = n + 2) /\
    ~(n:num = n + 1) /\ ~(n:num = n + 2) /\ ~(n + 1 = n + 2)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(GEN_REWRITE_TAC RAND_CONV [EQ_SYM_EQ] THEN FIRST_ASSUM ACCEPT_TAC) THEN
    TRY ARITH_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v (replacement_ax x y n (n+1) (n+2) p)`
  MP_TAC THENL
   [MATCH_MP_TAC(REWRITE_RULE[RIGHT_IMP_FORALL_THM; IMP_IMP] MODEL_HOLDS) THEN
    EXISTS_TAC `s:form->bool` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[replacement_ax; holds; HOLDS_EX; HOLDS_IFF; HOLDS_AND;
               HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD_BASIC; VALMOD_OTHER;
               HOLDS_VALMOD_STRIP1; HOLDS_VALMOD_STRIP2] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[IMP_IMP] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[] THEN ASM_MESON_TAC[HOLDS_VALMOD_SWAP]);;

(* ------------------------------------------------------------------------- *)
(* Formula macros: object formulas mirroring the semantic relations, for     *)
(* feeding to the separation/replacement schemes. Convention: a macro takes  *)
(* its free-variable indices as arguments and computes its own bound         *)
(* variables just beyond them (i + 1, MAX i j + 1 etc.), so its FV lemma is  *)
(* unconditional and its HOLDS characterization needs no freshness side      *)
(* conditions, just a valuation (and sometimes the model) hypothesis to fold *)
(* the semantic relation. First emptiness, inclusion, successor, inductive   *)
(* sets and ordinal-hood.                                                    *)
(* ------------------------------------------------------------------------- *)

let empty_form = new_definition
  `empty_form i = !! (i + 1) (Not((i + 1) %% i))`;;

let subset_form = new_definition
  `subset_form i j = !!- (MAX i j + 1) i ((MAX i j + 1) %% j)`;;

let suc_form = new_definition
  `suc_form i j =
     !! (MAX i j + 1)
        (((MAX i j + 1) %% j) <->
         ((MAX i j + 1) %% i) || Eq (MAX i j + 1) i)`;;

let inductive_form = new_definition
  `inductive_form i =
     (??- (i + 1) i (empty_form (i + 1))) &&
     (!!- (i + 1) i (??- (i + 2) i (suc_form (i + 1) (i + 2))))`;;

let FV_EMPTY_FORM = prove
 (`!i. FV(empty_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[empty_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_SUBSET_FORM = prove
 (`!i j. FV(subset_form i j) = {i,j}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[subset_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_SUC_FORM = prove
 (`!i j. FV(suc_form i j) = {i,j}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[suc_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_INDUCTIVE_FORM = prove
 (`!i. FV(inductive_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[inductive_form; FV; FV_CLAUSES; FV_EMPTY_FORM;
                           FV_SUC_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let transitive_form = new_definition
  `transitive_form i = !!- (i + 1) i (subset_form (i + 1) i)`;;

let linear_form = new_definition
  `linear_form i =
     !!- (i + 1) i (!!- (i + 2) i
        (((i + 1) %% (i + 2)) || Eq (i + 1) (i + 2) ||
         ((i + 2) %% (i + 1))))`;;

let ordinal_form = new_definition
  `ordinal_form i = transitive_form i && linear_form i`;;

let FV_TRANSITIVE_FORM = prove
 (`!i. FV(transitive_form i) = {i}`,
  GEN_TAC THEN
  REWRITE_TAC[transitive_form; FV_CLAUSES; FV_SUBSET_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_LINEAR_FORM = prove
 (`!i. FV(linear_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[linear_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_ORDINAL_FORM = prove
 (`!i. FV(ordinal_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[ordinal_form; FV_CLAUSES; FV_TRANSITIVE_FORM;
                           FV_LINEAR_FORM] THEN SET_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Formula macros for unordered and (Kuratowski) ordered pairs, for applying *)
(* a formula with distinguished variables 0 (input) and 1 (output) at two    *)
(* other variables (via quantified equalities rather than any substitution   *)
(* operation), for function-hood, domains and restrictions, attempts and     *)
(* graph application, and the replacement-step formula and the recursion     *)
(* relation of the transfinite recursion theorem.                            *)
(* ------------------------------------------------------------------------- *)

let pair_form = new_definition
  `pair_form i j k =
     !! (MAX (MAX i j) k + 1)
        (((MAX (MAX i j) k + 1) %% k) <->
         Eq (MAX (MAX i j) k + 1) i || Eq (MAX (MAX i j) k + 1) j)`;;

let opair_form = new_definition
  `opair_form i j k =
     ?? (MAX (MAX i j) k + 1)
        (?? (MAX (MAX i j) k + 2)
            (pair_form i i (MAX (MAX i j) k + 1) &&
             pair_form i j (MAX (MAX i j) k + 2) &&
             pair_form (MAX (MAX i j) k + 1) (MAX (MAX i j) k + 2) k))`;;

let FV_PAIR_FORM = prove
 (`!i j k. FV(pair_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pair_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_OPAIR_FORM = prove
 (`!i j k. FV(opair_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[opair_form; FV; FV_CLAUSES; FV_PAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let apply2_form = new_definition
  `apply2_form q i j = !! 0 (!! 1 ((Eq 0 i && Eq 1 j) --> q))`;;

let FV_APPLY2_FORM = prove
 (`!q i j. ~(i = 0) /\ ~(i = 1) /\ ~(j = 0) /\ ~(j = 1)
           ==> FV(apply2_form q i j) =
               {i,j} UNION (FV q DELETE 0 DELETE 1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[apply2_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `w:num` THEN ASM_MESON_TAC[]);;

let ispair_form = new_definition
  `ispair_form i = ?? (i + 1) (?? (i + 2) (opair_form (i + 1) (i + 2) i))`;;

let relset_form = new_definition
  `relset_form i = !!- (i + 1) i (ispair_form (i + 1))`;;

let functional_form = new_definition
  `functional_form i =
     !!- (i + 1) i (!!- (i + 2) i (!! (i + 3) (!! (i + 4) (!! (i + 5)
        ((opair_form (i + 3) (i + 4) (i + 1) &&
          opair_form (i + 3) (i + 5) (i + 2)) -->
         Eq (i + 4) (i + 5))))))`;;

let fun_form = new_definition
  `fun_form i = relset_form i && functional_form i`;;

let domain_form = new_definition
  `domain_form i j =
     !! (MAX i j + 1)
        (((MAX i j + 1) %% j) <->
         ?? (MAX i j + 2) (?? (MAX i j + 3)
            (((MAX i j + 3) %% i) &&
             opair_form (MAX i j + 1) (MAX i j + 2) (MAX i j + 3))))`;;

let FV_DOMAIN_FORM = prove
 (`!i j. FV(domain_form i j) = {i,j}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[domain_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let restrict_form = new_definition
  `restrict_form i j k =
     !! (MAX (MAX i j) k + 1)
        (((MAX (MAX i j) k + 1) %% k) <->
         ((MAX (MAX i j) k + 1) %% i) &&
         ?? (MAX (MAX i j) k + 2) (?? (MAX (MAX i j) k + 3)
            (((MAX (MAX i j) k + 2) %% j) &&
             opair_form (MAX (MAX i j) k + 2) (MAX (MAX i j) k + 3)
                        (MAX (MAX i j) k + 1))))`;;

let FV_RESTRICT_FORM = prove
 (`!i j k. FV(restrict_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[restrict_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let attempt_form = new_definition
  `attempt_form q i j n =
     fun_form i && domain_form i j &&
     !!- n j
       (!! (n + 1)
         (!! (n + 2)
           ((restrict_form i n (n + 1) &&
             ?? (n + 3) (((n + 3) %% i) && opair_form n (n + 2) (n + 3)))
            --> apply2_form q (n + 1) (n + 2))))`;;

let applyto_form = new_definition
  `applyto_form i j k =
     ?? (MAX (MAX i j) k + 1)
        (((MAX (MAX i j) k + 1) %% k) &&
         opair_form i j (MAX (MAX i j) k + 1))`;;

let FV_APPLYTO_FORM = prove
 (`!i j k. FV(applyto_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[applyto_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let recstep_form = new_definition
  `recstep_form q N =
     ?? (N + 2) (?? (N + 3) (?? (N + 4)
        (ordinal_form (N + 2) &&
         (attempt_form q (N + 3) (N + 2) (N + 5) &&
         ((N %% (N + 2)) &&
         (applyto_form N (N + 4) (N + 3) &&
          opair_form N (N + 4) (N + 1)))))))`;;

let rec_form = new_definition
  `rec_form q N =
     ?? (N + 2) (?? (N + 3)
        (ordinal_form (N + 2) &&
         (attempt_form q (N + 3) (N + 2) (N + 4) &&
         ((N %% (N + 2)) &&
          applyto_form N (N + 1) (N + 3)))))`;;

(* ------------------------------------------------------------------------- *)
(* Formula macros for the step of the cumulative hierarchy, for pointwise    *)
(* update of a function, and for the satisfaction machinery: internal        *)
(* numerals, function application, membership in the union of the range of a *)
(* set, verdicts, the five Tarski cases, the full Tarski clause and the      *)
(* satisfaction step.                                                        *)
(* ------------------------------------------------------------------------- *)

let vstep_form = new_definition
  `vstep_form =
     !! 2 ((2 %% 1) <->
           ?? 3 (?? 4 (applyto_form 3 4 0 && subset_form 2 4)))`;;

let FV_VSTEP_FORM = prove
 (`FV vstep_form SUBSET {0,1}`,
  REWRITE_TAC[vstep_form; FV; FV_CLAUSES; FV_APPLYTO_FORM;
              FV_SUBSET_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FVLT_VSTEP_FORM = prove
 (`!m. m IN FV vstep_form ==> m < 2`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_VSTEP_FORM) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let update_form = new_definition
  `update_form i j k l =
     !! (MAX (MAX i j) (MAX k l) + 1)
        ((MAX (MAX i j) (MAX k l) + 1) %% l <->
         (MAX (MAX i j) (MAX k l) + 1) %% i &&
         Not(?? (MAX (MAX i j) (MAX k l) + 2)
                (opair_form j (MAX (MAX i j) (MAX k l) + 2)
                            (MAX (MAX i j) (MAX k l) + 1))) ||
         opair_form j k (MAX (MAX i j) (MAX k l) + 1))`;;

let FV_UPDATE_FORM = prove
 (`!i j k l. FV(update_form i j k l) = {i,j,k,l}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[update_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let nat_form = new_recursive_definition num_RECURSION
  `(nat_form 0 i = empty_form i) /\
   (nat_form (SUC k) i =
      ?? (i + 1) (nat_form k (i + 1) && suc_form (i + 1) i))`;;

let FV_NAT_FORM = prove
 (`!k i. FV(nat_form k i) = {i}`,
  INDUCT_TAC THEN
  ASM_REWRITE_TAC[nat_form; FV_EMPTY_FORM; FV_SUC_FORM; FV_CLAUSES] THEN
  GEN_TAC THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let apply_form = new_definition
  `apply_form i j k =
     ?? (MAX (MAX i j) k + 1)
        ((MAX (MAX i j) k + 1) %% i &&
         opair_form j k (MAX (MAX i j) k + 1))`;;

let FV_APPLY_FORM = prove
 (`!i j k. FV(apply_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[apply_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let ranmem_form = new_definition
  `ranmem_form i j =
     ?? (MAX i j + 1) (?? (MAX i j + 2) (?? (MAX i j + 3)
        (i %% (MAX i j + 1) &&
         opair_form (MAX i j + 3) (MAX i j + 1) (MAX i j + 2) &&
         (MAX i j + 2) %% j)))`;;

let FV_RANMEM_FORM = prove
 (`!i j. FV(ranmem_form i j) = {i,j}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[ranmem_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let verdict_form = new_definition
  `verdict_form i j k l =
     ?? (MAX (MAX i j) (MAX k l) + 1)
        (?? (MAX (MAX i j) (MAX k l) + 2)
            (opair_form i j (MAX (MAX i j) (MAX k l) + 1) &&
             opair_form (MAX (MAX i j) (MAX k l) + 1) k
                        (MAX (MAX i j) (MAX k l) + 2) &&
             ranmem_form (MAX (MAX i j) (MAX k l) + 2) l))`;;

let FV_VERDICT_FORM = prove
 (`!i j k l. FV(verdict_form i j k l) = {i,j,k,l}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[verdict_form; FV; FV_CLAUSES; FV_OPAIR_FORM;
              FV_RANMEM_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let satfalse_form = new_definition
  `satfalse_form = nat_form 0 9 && Eq 10 9 && nat_form 0 6`;;

let FV_SATFALSE_FORM = prove
 (`FV satfalse_form SUBSET {6,9,10}`,
  REWRITE_TAC[satfalse_form; FV; FV_CLAUSES; FV_NAT_FORM] THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let satmem_form = new_definition
  `satmem_form =
     nat_form 1 9 &&
     ?? 11 (?? 12 (?? 13 (?? 14
        (opair_form 11 12 10 &&
         apply_form 8 11 13 &&
         apply_form 8 12 14 &&
         (nat_form 1 6 && 13 %% 14 ||
          nat_form 0 6 && Not(13 %% 14))))))`;;

let FV_SATMEM_FORM = prove
 (`FV satmem_form SUBSET {6,8,9,10}`,
  REWRITE_TAC[satmem_form; FV; FV_CLAUSES; FV_NAT_FORM; FV_OPAIR_FORM;
              FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let sateq_form = new_definition
  `sateq_form =
     nat_form 2 9 &&
     ?? 11 (?? 12 (?? 13 (?? 14
        (opair_form 11 12 10 &&
         apply_form 8 11 13 &&
         apply_form 8 12 14 &&
         (nat_form 1 6 && Eq 13 14 ||
          nat_form 0 6 && Not(Eq 13 14))))))`;;

let FV_SATEQ_FORM = prove
 (`FV sateq_form SUBSET {6,8,9,10}`,
  REWRITE_TAC[sateq_form; FV; FV_CLAUSES; FV_NAT_FORM; FV_OPAIR_FORM;
              FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let satimp_form = new_definition
  `satimp_form =
     nat_form 3 9 &&
     ?? 11 (?? 12 (?? 13 (?? 14
        (opair_form 11 12 10 &&
         nat_form 0 13 &&
         nat_form 1 14 &&
         (nat_form 1 6 && (verdict_form 11 8 13 0 || verdict_form 12 8 14 0) ||
          nat_form 0 6 && verdict_form 11 8 14 0 &&
            verdict_form 12 8 13 0)))))`;;

let FV_SATIMP_FORM = prove
 (`FV satimp_form SUBSET {0,6,8,9,10}`,
  REWRITE_TAC[satimp_form; FV; FV_CLAUSES; FV_NAT_FORM; FV_OPAIR_FORM;
              FV_VERDICT_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let satall_form = new_definition
  `satall_form =
     nat_form 4 9 &&
     ?? 11 (?? 12 (?? 13 (?? 14
        (opair_form 11 12 10 &&
         nat_form 0 13 &&
         nat_form 1 14 &&
         (nat_form 1 6 &&
          !!- 15 2 (!! 16 (update_form 8 11 15 16 -->
                           verdict_form 12 16 14 0)) ||
          nat_form 0 6 &&
          ??- 15 2 (?? 16 (update_form 8 11 15 16 &&
                           verdict_form 12 16 13 0)))))))`;;

let FV_SATALL_FORM = prove
 (`FV satall_form SUBSET {0,2,6,8,9,10}`,
  REWRITE_TAC[satall_form; FV; FV_CLAUSES; FV_NAT_FORM; FV_OPAIR_FORM;
              FV_VERDICT_FORM; FV_UPDATE_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let satbody_form = new_definition
  `satbody_form =
     ?? 5 (?? 6 (?? 7 (?? 8
        (opair_form 5 6 4 && opair_form 7 8 5 &&
         ?? 9 (?? 10 (opair_form 9 10 7 &&
            (satfalse_form || satmem_form || sateq_form ||
             satimp_form || satall_form)))))))`;;

let FV_SATBODY_FORM = prove
 (`FV satbody_form SUBSET {0,2,4}`,
  REWRITE_TAC[satbody_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_SATFALSE_FORM;
            REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_SATMEM_FORM;
            REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_SATEQ_FORM;
            REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_SATIMP_FORM;
            REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_SATALL_FORM]);;

let satstep_form = new_definition
  `satstep_form = !! 4 ((4 %% 1) <-> (4 %% 3) && satbody_form)`;;

let FV_SATSTEP_FORM = prove
 (`FV satstep_form SUBSET {0,1,2,3}`,
  REWRITE_TAC[satstep_form; FV; FV_CLAUSES] THEN
  MP_TAC FV_SATBODY_FORM THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The satisfaction apparatus internalized: recapp_form/recapp4_form apply a *)
(* formula with free variables among 2,3 (resp. 2..5) at other variables,    *)
(* and each set operation used in the stage universe gets a defining object  *)
(* formula: omega, cartesian product, function space, the hf universe, the   *)
(* stage universe, satisfaction stages and internal satisfaction; then       *)
(* definable membership.                                                     *)
(* ------------------------------------------------------------------------- *)

let recapp_form = new_definition
  `recapp_form q i j = !! 2 (!! 3 ((Eq 2 i && Eq 3 j) --> q))`;;

let recapp4_form = new_definition
  `recapp4_form q i j k l =
     !! 2 (!! 3 (!! 4 (!! 5
        ((Eq 2 i && Eq 3 j && Eq 4 k && Eq 5 l) --> q))))`;;

let omega_form = new_definition
  `omega_form i =
     inductive_form i &&
     !! (i + 1) (inductive_form (i + 1) --> subset_form i (i + 1))`;;

let cross_form = new_definition
  `cross_form i j k =
     !! (MAX (MAX i j) k + 1)
        ((MAX (MAX i j) k + 1) %% k <->
         ?? (MAX (MAX i j) k + 2) (?? (MAX (MAX i j) k + 3)
            ((MAX (MAX i j) k + 2) %% i &&
             (MAX (MAX i j) k + 3) %% j &&
             opair_form (MAX (MAX i j) k + 2) (MAX (MAX i j) k + 3)
                        (MAX (MAX i j) k + 1))))`;;

let funs_form = new_definition
  `funs_form i j k =
     !! (MAX (MAX i j) k + 1)
        ((MAX (MAX i j) k + 1) %% k <->
         fun_form (MAX (MAX i j) k + 1) &&
         domain_form (MAX (MAX i j) k + 1) i &&
         !!- (MAX (MAX i j) k + 2) (MAX (MAX i j) k + 1)
             (!! (MAX (MAX i j) k + 3) (!! (MAX (MAX i j) k + 4)
                (opair_form (MAX (MAX i j) k + 3) (MAX (MAX i j) k + 4)
                            (MAX (MAX i j) k + 2) -->
                 (MAX (MAX i j) k + 4) %% j))))`;;

let hfset_form = new_definition
  `hfset_form i j =
     !! (MAX (MAX i j) 5 + 1)
        ((MAX (MAX i j) 5 + 1) %% j <->
         ?? (MAX (MAX i j) 5 + 2) (?? (MAX (MAX i j) 5 + 3)
            ((MAX (MAX i j) 5 + 2) %% i &&
             recapp_form (rec_form vstep_form 2)
                         (MAX (MAX i j) 5 + 2) (MAX (MAX i j) 5 + 3) &&
             (MAX (MAX i j) 5 + 1) %% (MAX (MAX i j) 5 + 3))))`;;

let univ_form = new_definition
  `univ_form i j =
     ?? (MAX i j + 1) (?? (MAX i j + 2) (?? (MAX i j + 3)
        (?? (MAX i j + 4) (?? (MAX i j + 5)
           (omega_form (MAX i j + 1) &&
            hfset_form (MAX i j + 1) (MAX i j + 2) &&
            funs_form (MAX i j + 1) i (MAX i j + 3) &&
            cross_form (MAX i j + 2) (MAX i j + 3) (MAX i j + 4) &&
            nat_form 2 (MAX i j + 5) &&
            cross_form (MAX i j + 4) (MAX i j + 5) j)))))`;;

let FVLT_SATSTEP_FORM = prove
 (`!m. m IN FV satstep_form ==> m < 4`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_SATSTEP_FORM) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let satstage_form = new_definition
  `satstage_form i j k =
     ?? (MAX (MAX i j) (MAX k 5) + 1) (?? (MAX (MAX i j) (MAX k 5) + 2)
        (?? (MAX (MAX i j) (MAX k 5) + 3) (?? (MAX (MAX i j) (MAX k 5) + 4)
           (Eq (MAX (MAX i j) (MAX k 5) + 2) i &&
            Eq (MAX (MAX i j) (MAX k 5) + 3) j &&
            Eq (MAX (MAX i j) (MAX k 5) + 4) k &&
            univ_form (MAX (MAX i j) (MAX k 5) + 2)
                      (MAX (MAX i j) (MAX k 5) + 1) &&
            recapp4_form (rec_form satstep_form 4)
                         (MAX (MAX i j) (MAX k 5) + 2)
                         (MAX (MAX i j) (MAX k 5) + 1)
                         (MAX (MAX i j) (MAX k 5) + 3)
                         (MAX (MAX i j) (MAX k 5) + 4)))))`;;

let sat_form = new_definition
  `sat_form i j k =
     ?? (MAX (MAX i j) (MAX k 5) + 1)
       (?? (MAX (MAX i j) (MAX k 5) + 2)
        (?? (MAX (MAX i j) (MAX k 5) + 3)
         (?? (MAX (MAX i j) (MAX k 5) + 4)
          (?? (MAX (MAX i j) (MAX k 5) + 5)
           (?? (MAX (MAX i j) (MAX k 5) + 6)
            ((omega_form (MAX (MAX i j) (MAX k 5) + 1) &&
              (MAX (MAX i j) (MAX k 5) + 2) %% (MAX (MAX i j) (MAX k 5) + 1) &&
           satstage_form i (MAX (MAX i j) (MAX k 5) + 2)
             (MAX (MAX i j) (MAX k 5) + 3) &&
           nat_form 1 (MAX (MAX i j) (MAX k 5) + 4) &&
           opair_form j k (MAX (MAX i j) (MAX k 5) + 5) &&
           opair_form (MAX (MAX i j) (MAX k 5) + 5)
             (MAX (MAX i j) (MAX k 5) + 4) (MAX (MAX i j) (MAX k 5) + 6) &&
           (MAX (MAX i j) (MAX k 5) + 6) %%
             (MAX (MAX i j) (MAX k 5) + 3))))))))`;;

let defmem_form = new_definition
  `defmem_form =
     subset_form 0 1 &&
     (empty_form 0 ||
      ?? 2 (?? 3 (?? 4 (?? 5 (?? 6
         (omega_form 2 &&
          funs_form 2 1 3 &&
          5 %% 3 &&
          nat_form 0 6 &&
          !!- 7 1 (?? 8
             (update_form 5 6 7 8 &&
              (7 %% 0 <-> sat_form 1 4 8)))))))))`;;

(* ------------------------------------------------------------------------- *)
(* Free-variable bounds for the internalized satisfaction chain, needed so   *)
(* that the L-step formula lstep_form (built on defmem_form) has FV inside   *)
(* {0,1} and can be fed to the recursion theorem and its definability layer. *)
(* ------------------------------------------------------------------------- *)

let FV_ISPAIR_FORM = prove
 (`!i. FV(ispair_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[ispair_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_RELSET_FORM = prove
 (`!i. FV(relset_form i) = {i}`,
  GEN_TAC THEN REWRITE_TAC[relset_form; FV; FV_CLAUSES; FV_ISPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_FUNCTIONAL_FORM = prove
 (`!i. FV(functional_form i) = {i}`,
  GEN_TAC THEN
  REWRITE_TAC[functional_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_FUN_FORM = prove
 (`!i. FV(fun_form i) = {i}`,
  GEN_TAC THEN
  REWRITE_TAC[fun_form; FV_CLAUSES; FV_RELSET_FORM; FV_FUNCTIONAL_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

let FV_ATTEMPT_FORM_SUB = prove
 (`!q i j n.
        i < n /\ j < n /\ 1 < n /\ (!m. m IN FV q ==> m < n)
        ==> FV(attempt_form q i j n) SUBSET
            {i,j} UNION (FV q DELETE 0 DELETE 1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[attempt_form; FV; FV_CLAUSES; FV_FUN_FORM;
              FV_DOMAIN_FORM; FV_RESTRICT_FORM; FV_OPAIR_FORM] THEN
  MP_TAC(SPECL [`q:form`; `n + 1`; `n + 2`] FV_APPLY2_FORM) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN UNDISCH_TAC `1 < (n:num)` THEN ARITH_TAC;
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `m:num` THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  TRY(DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun tm -> is_const tm && name_of tm = "FV"))
            (concl th))) THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC) THEN
  ASM_ARITH_TAC);;

let FV_REC_FORM_SUB = prove
 (`!q N. 1 < N /\ (!m. m IN FV q ==> m < N)
         ==> FV(rec_form q N) SUBSET
             {N, N + 1} UNION (FV q DELETE 0 DELETE 1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[rec_form; FV; FV_CLAUSES; FV_ORDINAL_FORM;
              FV_APPLYTO_FORM] THEN
  MP_TAC(SPECL [`q:form`; `N + 3`; `N + 2`; `N + 4`]
        FV_ATTEMPT_FORM_SUB) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY ARITH_TAC THEN
    X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
      is_forall(concl th))) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  DISCH_TAC THEN X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  TRY(FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
       is_forall(concl th) &&
       can (find_term
         (fun tm -> is_const tm && name_of tm = "attempt_form"))
         (concl th))) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      TRY(FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
           is_forall(concl th))) THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC) THEN
      ASM_ARITH_TAC) THEN
  ASM_ARITH_TAC);;

let FV_RECAPP_FORM_SUB = prove
 (`!q i j. FV(recapp_form q i j) SUBSET
           {i,j} UNION (FV q DELETE 2 DELETE 3)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[recapp_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

let FV_RECAPP4_FORM_SUB = prove
 (`!q i j k l. FV(recapp4_form q i j k l) SUBSET
               {i,j,k,l} UNION
               (FV q DELETE 2 DELETE 3 DELETE 4 DELETE 5)`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[recapp4_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[]);;

let FV_OMEGA_FORM = prove
 (`!i. FV(omega_form i) = {i}`,
  GEN_TAC THEN
  REWRITE_TAC[omega_form; FV; FV_CLAUSES; FV_INDUCTIVE_FORM;
              FV_SUBSET_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_CROSS_FORM = prove
 (`!i j k. FV(cross_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[cross_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_FUNS_FORM = prove
 (`!i j k. FV(funs_form i j k) = {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[funs_form; FV; FV_CLAUSES; FV_FUN_FORM; FV_DOMAIN_FORM;
              FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FVLT_REC_VSTEP = prove
 (`!m. m IN FV(rec_form vstep_form 2) ==> m = 2 \/ m = 3`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MP (SPECL [`vstep_form`; `2`] FV_REC_FORM_SUB)
            (CONJ (ARITH_RULE `1 < 2`) FVLT_VSTEP_FORM)) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_VSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let FVLT_RECAPP_VSTEP = prove
 (`!a b m. m IN FV(recapp_form (rec_form vstep_form 2) a b)
           ==> m = a \/ m = b`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`rec_form vstep_form 2`; `a:num`; `b:num`]
        FV_RECAPP_FORM_SUB) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_REC_VSTEP) THEN ASM_REWRITE_TAC[]);;

let FV_HFSET_FORM_SUB = prove
 (`!i j. FV(hfset_form i j) SUBSET {i,j}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[hfset_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[FVLT_RECAPP_VSTEP]);;

let FV_UNIV_FORM_SUB = prove
 (`!i j. FV(univ_form i j) SUBSET {i,j}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[univ_form; FV; FV_CLAUSES; FV_OMEGA_FORM; FV_FUNS_FORM;
              FV_CROSS_FORM; FV_NAT_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
                         NOT_IN_EMPTY]
              (SPECL [`MAX i j + 1`; `MAX i j + 2`]
                     FV_HFSET_FORM_SUB)]);;

let FVLT_REC_SATSTEP = prove
 (`!m. m IN FV(rec_form satstep_form 4)
       ==> m = 2 \/ m = 3 \/ m = 4 \/ m = 5`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MP (SPECL [`satstep_form`; `4`] FV_REC_FORM_SUB)
            (CONJ (ARITH_RULE `1 < 4`) FVLT_SATSTEP_FORM)) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `4 + 1 = 5`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_SATSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let FVLT_RECAPP4_SATSTEP = prove
 (`!a b c d m.
        m IN FV(recapp4_form (rec_form satstep_form 4) a b c d)
        ==> m = a \/ m = b \/ m = c \/ m = d`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`rec_form satstep_form 4`; `a:num`; `b:num`;
                `c:num`; `d:num`] FV_RECAPP4_FORM_SUB) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_REC_SATSTEP) THEN ASM_REWRITE_TAC[]);;

let FV_SATSTAGE_FORM_SUB = prove
 (`!i j k. FV(satstage_form i j k) SUBSET {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[satstage_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[FVLT_RECAPP4_SATSTEP;
            REWRITE_RULE[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
                         NOT_IN_EMPTY]
              (SPECL [`MAX (MAX i j) (MAX k 5) + 2`;
                      `MAX (MAX i j) (MAX k 5) + 1`]
                     FV_UNIV_FORM_SUB)]);;

let FV_SAT_FORM_SUB = prove
 (`!i j k. FV(sat_form i j k) SUBSET {i,j,k}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[sat_form; FV; FV_CLAUSES; FV_OMEGA_FORM; FV_NAT_FORM;
              FV_OPAIR_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
                         NOT_IN_EMPTY]
              (SPECL [`i:num`; `MAX (MAX i j) (MAX k 5) + 2`;
                      `MAX (MAX i j) (MAX k 5) + 3`]
                     FV_SATSTAGE_FORM_SUB)]);;

let FV_DEFMEM_FORM_SUB = prove
 (`FV defmem_form SUBSET {0,1}`,
  REWRITE_TAC[defmem_form; FV; FV_CLAUSES; FV_SUBSET_FORM;
              FV_EMPTY_FORM; FV_OMEGA_FORM; FV_FUNS_FORM; FV_NAT_FORM;
              FV_UPDATE_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
                         NOT_IN_EMPTY]
              (SPECL [`1`; `4`; `8`] FV_SAT_FORM_SUB)]);;

let lstep_form = new_definition
  `lstep_form =
     ?? 2 ((!! 3 (3 %% 2 <-> ranmem_form 3 0)) &&
           (!! 3 (3 %% 1 <-> apply2_form defmem_form 3 2)))`;;

let FV_LSTEP_FORM_SUB = prove
 (`FV lstep_form SUBSET {0,1}`,
  REWRITE_TAC[lstep_form; FV; FV_CLAUSES; FV_RANMEM_FORM] THEN
  MP_TAC(SPECL [`defmem_form`; `3`; `2`] FV_APPLY2_FORM) THEN
  ANTS_TAC THENL [REPEAT CONJ_TAC THEN ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
              FV_DEFMEM_FORM_SUB]);;

let FVLT_LSTEP_FORM = prove
 (`!m. m IN FV lstep_form ==> m < 2`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(REWRITE_RULE[SUBSET] FV_LSTEP_FORM_SUB) THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Introduction rules for members of ZF_AX, and freshness side conditions.   *)
(* ------------------------------------------------------------------------- *)

let ZF_AX_SEP = prove
 (`!x a s p. ~(a IN FV p) /\ ~(s IN FV p) /\ ~(a = x) /\ ~(s = x) /\ ~(a = s)
            ==> separation_ax x a s p IN ZF_AX`,
  MESON_TAC[ZF_AX_MEMBERS]);;

let ZF_AX_REP = prove
 (`!x y z a b p.
       ~(z IN FV p) /\ ~(a IN FV p) /\ ~(b IN FV p) /\
       ~(x = y) /\ ~(x = z) /\ ~(x = a) /\ ~(x = b) /\
       ~(y = z) /\ ~(y = a) /\ ~(y = b) /\
       ~(z = a) /\ ~(z = b) /\ ~(a = b)
       ==> replacement_ax x y z a b p IN ZF_AX`,
  MESON_TAC[ZF_AX_MEMBERS]);;

let FV_REC_VSTEP_2 = prove
 (`FV(rec_form vstep_form 2) SUBSET {2,3}`,
  MP_TAC(SPECL [`vstep_form`; `2`] FV_REC_FORM_SUB) THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [ARITH_TAC;
      X_GEN_TAC `m:num` THEN
      DISCH_THEN(MP_TAC o MATCH_MP (REWRITE_RULE[SUBSET] FV_VSTEP_FORM)) THEN
      REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC];
    REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN
    MP_TAC FV_VSTEP_FORM THEN SET_TAC[]]);;

let FRESH_SATBODY = prove
 (`~(10 IN FV satbody_form) /\ ~(11 IN FV satbody_form)`,
  CONJ_TAC THEN
  DISCH_THEN(MP_TAC o MATCH_MP (REWRITE_RULE[SUBSET] FV_SATBODY_FORM)) THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let FRESH_DEFMEM = prove
 (`~(10 IN FV defmem_form) /\ ~(11 IN FV defmem_form)`,
  CONJ_TAC THEN
  DISCH_THEN(MP_TAC o MATCH_MP (REWRITE_RULE[SUBSET] FV_DEFMEM_FORM_SUB)) THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let FRESH_REC = prove
 (`~(10 IN FV(rec_form vstep_form 2)) /\ ~(11 IN FV(rec_form vstep_form 2)) /\
   ~(12 IN FV(rec_form vstep_form 2))`,
  REPEAT CONJ_TAC THEN
  DISCH_THEN(MP_TAC o MATCH_MP (REWRITE_RULE[SUBSET] FV_REC_VSTEP_2)) THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC);;

let FV_RECSTEP_FORM_SUB = prove
 (`!q N. 1 < N /\ (!m. m IN FV q ==> m < N)
         ==> FV(recstep_form q N) SUBSET
             {N, N + 1} UNION (FV q DELETE 0 DELETE 1)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recstep_form; FV; FV_CLAUSES; FV_ORDINAL_FORM;
              FV_APPLYTO_FORM; FV_OPAIR_FORM] THEN
  MP_TAC(SPECL [`q:form`; `N + 3`; `N + 2`; `N + 5`]
        FV_ATTEMPT_FORM_SUB) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THEN TRY ARITH_TAC THEN
    X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
      is_forall(concl th))) THEN
    ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  DISCH_TAC THEN X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  TRY(FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
       is_forall(concl th) &&
       can (find_term
         (fun tm -> is_const tm && name_of tm = "attempt_form"))
         (concl th))) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      TRY(FIRST_X_ASSUM(MP_TAC o SPEC `m:num` o check (fun th ->
           is_forall(concl th))) THEN
          ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC) THEN
      ASM_ARITH_TAC) THEN
  ASM_ARITH_TAC);;

