(* ------------------------------------------------------------------------- *)
(* The finite fragment zfw_ax, its members (ZFW_AX_MEMBERS) and its          *)
(* soundness (ZFW_SUBSET_ZFAX). Since a model of a set of axioms is a model  *)
(* of each of its subsets (MODEL_SUBSET), every model of ZF_AX is a model of *)
(* zfw_ax (MODEL_ZFW).                                                       *)
(* ------------------------------------------------------------------------- *)

let zfw_ax = new_definition
 `zfw_ax =
    {extensionality_ax, foundation_ax, pairing_ax, union_ax,
     powerset_ax, infinity_ax,
     separation_ax 0 10 11 False,
     separation_ax 0 10 11 (0 %% 1),
     separation_ax 0 10 11 (Not(0 %% 1)),
     separation_ax 0 10 11 (!! 1 (inductive_form 1 --> (0 %% 1))),
     separation_ax 0 10 11 (ordinal_form 0),
     separation_ax 0 10 11 (subset_form 0 1),
     separation_ax 0 10 11 (?? 3 (?? 4 ((3 %% 1) && opair_form 3 4 0))),
     separation_ax 0 10 11
       (?? 3 (?? 4
              (applyto_form 0 3 1 && (applyto_form 0 4 2 && Not(Eq 3 4))))),
     separation_ax 0 10 11
       (?? 2 (?? 3 (applyto_form 2 3 1 && subset_form 0 3))),
     separation_ax 0 10 11
       (?? 3 (?? 4 ((3 %% 1) && (4 %% 2) && opair_form 3 4 0))),
     separation_ax 0 10 11
       (fun_form 0 && domain_form 0 1 &&
        !!- 3 0 (!! 4 (!! 5 (opair_form 4 5 3 --> (5 %% 2))))),
     separation_ax 0 10 11
       (((0 %% 1) && Not(?? 4 (opair_form 2 4 0))) || opair_form 2 3 0),
     separation_ax 0 10 11 defmem_form,
     separation_ax 0 10 11 (ranmem_form 0 1),
     separation_ax 4 10 11 satbody_form,
     replacement_ax 2 3 10 11 12 (rec_form vstep_form 2),
     separation_ax 5 20 21 (Not(?? 6 (attempt_form lstep_form 6 5 7))),
     separation_ax 5 20 21 (Not(?? 6 (attempt_form vstep_form 6 5 7))),
     separation_ax 5 20 21 (Not(?? 6 (attempt_form satstep_form 6 5 7))),
     replacement_ax 5 6 20 21 22 (recstep_form lstep_form 5),
     replacement_ax 5 6 20 21 22 (recstep_form vstep_form 5),
     replacement_ax 5 6 20 21 22 (recstep_form satstep_form 5),
     separation_ax 7 10 11 (?? 8 (update_form 5 6 7 8 && sat_form 1 4 8))}`;;

let ZFW_AX_MEMBERS = prove
 (`extensionality_ax IN zfw_ax /\
   foundation_ax IN zfw_ax /\
   pairing_ax IN zfw_ax /\
   union_ax IN zfw_ax /\
   powerset_ax IN zfw_ax /\
   infinity_ax IN zfw_ax /\
   separation_ax 0 10 11 False IN zfw_ax /\
   separation_ax 0 10 11 (0 %% 1) IN zfw_ax /\
   separation_ax 0 10 11 (Not(0 %% 1)) IN zfw_ax /\
   separation_ax 0 10 11 (!! 1 (inductive_form 1 --> (0 %% 1))) IN zfw_ax /\
   separation_ax 0 10 11 (ordinal_form 0) IN zfw_ax /\
   separation_ax 0 10 11 (subset_form 0 1) IN zfw_ax /\
   separation_ax 0 10 11 (?? 3 (?? 4 ((3 %% 1) && opair_form 3 4 0)))
     IN zfw_ax /\
   separation_ax 0 10 11
     (?? 3 (?? 4 (applyto_form 0 3 1 && (applyto_form 0 4 2 && Not(Eq 3 4)))))
     IN zfw_ax /\
   separation_ax 0 10 11 (?? 2 (?? 3 (applyto_form 2 3 1 && subset_form 0 3)))
     IN zfw_ax /\
   separation_ax 0 10 11
     (?? 3 (?? 4 ((3 %% 1) && (4 %% 2) && opair_form 3 4 0)))
     IN zfw_ax /\
   separation_ax 0 10 11
     (fun_form 0 && domain_form 0 1 &&
      !!- 3 0 (!! 4 (!! 5 (opair_form 4 5 3 --> (5 %% 2))))) IN zfw_ax /\
   separation_ax 0 10 11
     (((0 %% 1) && Not(?? 4 (opair_form 2 4 0))) || opair_form 2 3 0)
       IN zfw_ax /\
   separation_ax 0 10 11 defmem_form IN zfw_ax /\
   separation_ax 0 10 11 (ranmem_form 0 1) IN zfw_ax /\
   separation_ax 4 10 11 satbody_form IN zfw_ax /\
   replacement_ax 2 3 10 11 12 (rec_form vstep_form 2) IN zfw_ax /\
   separation_ax 5 20 21 (Not(?? 6 (attempt_form lstep_form 6 5 7)))
     IN zfw_ax /\
   separation_ax 5 20 21 (Not(?? 6 (attempt_form vstep_form 6 5 7)))
     IN zfw_ax /\
   separation_ax 5 20 21 (Not(?? 6 (attempt_form satstep_form 6 5 7)))
     IN zfw_ax /\
   replacement_ax 5 6 20 21 22 (recstep_form lstep_form 5) IN zfw_ax /\
   replacement_ax 5 6 20 21 22 (recstep_form vstep_form 5) IN zfw_ax /\
   replacement_ax 5 6 20 21 22 (recstep_form satstep_form 5) IN zfw_ax /\
   separation_ax 7 10 11
     (?? 8 (update_form 5 6 7 8 && sat_form 1 4 8)) IN zfw_ax`,
  REWRITE_TAC[zfw_ax; IN_INSERT; NOT_IN_EMPTY]);;

let DMSEP_IN_ZFAX = prove
 (`separation_ax 7 10 11
   (?? 8 (update_form 5 6 7 8 && sat_form 1 4 8)) IN ZF_AX`,
  MATCH_MP_TAC ZF_AX_SEP THEN
  MP_TAC(ISPECL [`1`;`4`;`8`] FV_SAT_FORM_SUB) THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_UPDATE_FORM; SUBSET;
    IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[ARITH_EQ]);;

let FRESH_DMSEP = prove
 (`~(10 IN FV(?? 8 (update_form 5 6 7 8 && sat_form 1 4 8))) /\
   ~(11 IN FV(?? 8 (update_form 5 6 7 8 && sat_form 1 4 8)))`,
  MP_TAC(ISPECL [`1`;`4`;`8`] FV_SAT_FORM_SUB) THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_UPDATE_FORM; SUBSET;
    IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  MESON_TAC[ARITH_EQ]);;

let ZFW_SUBSET_ZFAX = prove
 (`zfw_ax SUBSET ZF_AX`,
  REWRITE_TAC[SUBSET; zfw_ax; IN_INSERT; NOT_IN_EMPTY] THEN
  GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[DMSEP_IN_ZFAX] THEN
  TRY(MATCH_MP_TAC ZF_AX_SEP) THEN TRY(MATCH_MP_TAC ZF_AX_REP) THEN
  REWRITE_TAC[FRESH_ENGINE_LSTEP; FRESH_ENGINE_VSTEP; FRESH_ENGINE_SATSTEP;
              ARITH_EQ] THEN
  REWRITE_TAC[ZF_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC;
    FV; FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
    FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM; FV_RANMEM_FORM;
    FV_ORDINAL_FORM; IN_INSERT; IN_UNION; IN_DELETE; NOT_IN_EMPTY; ARITH_EQ]);;

let MODEL_SUBSET = prove
 (`!D (E:A->A->bool) s t. model D E s /\ t SUBSET s ==> model D E t`,
  REWRITE_TAC[model; satisfies; SUBSET] THEN MESON_TAC[]);;

let MODEL_ZFW = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> model D E zfw_ax`,
  MESON_TAC[MODEL_SUBSET; ZFW_SUBSET_ZFAX]);;

(* ------------------------------------------------------------------------- *)
(* ZF_OF_ZFW turns a lemma about models of zfw_ax into the same lemma about  *)
(* models of ZF_AX, using MODEL_ZFW: given |- !x1 .. xk. A ==> C where model *)
(* D E zfw_ax occurs only as a conjunct of the antecedent A, it proves the   *)
(* same with ZF_AX for zfw_ax. A conjunction of such lemmas is treated       *)
(* componentwise.                                                            *)
(* ------------------------------------------------------------------------- *)

let ZF_OF_ZFW =
  let zf = `ZF_AX` and zfw = `zfw_ax` in
  let rec weaken th tm =
    if concl th = tm then th
    else if is_conj tm then
      CONJ (weaken (CONJUNCT1 th) (lhand tm)) (weaken (CONJUNCT2 th) (rand tm))
    else MATCH_MP MODEL_ZFW th in
  let rec rule th =
    if is_conj(concl th) then CONJ (rule(CONJUNCT1 th)) (rule(CONJUNCT2 th))
    else
      let vs,bod = strip_forall(concl th) in
      let ant,_ = dest_imp bod in
      let ant' = subst [zf,zfw] ant in
      GENL vs (DISCH ant' (MP (SPECL vs th) (weaken (ASSUME ant') ant))) in
  rule;;

(* ------------------------------------------------------------------------- *)
(* Side conditions for the fragment: engine_ready s q N n says that s        *)
(* contains the separation and replacement instances (with fresh slots)      *)
(* needed by the recursion theorem for the step formula q, and omega_ready s *)
(* p x n the separation instance needed for induction on p                   *)
(* (EOMEGA_INDUCT_GEN, EORDINAL_INDUCT_GEN). Their instances for zfw_ax, and *)
(* for ZF_AX at fresh slots.                                                 *)
(* ------------------------------------------------------------------------- *)

let engine_ready = new_definition
 `engine_ready s q N n <=>
    (!m. m IN FV q ==> m < N) /\ 1 < N /\
    ~(n = N) /\ ~(n + 1 = N) /\ ~(n + 2 = N) /\
    ~(n = N + 1) /\ ~(n + 1 = N + 1) /\ ~(n + 2 = N + 1) /\
    ~(n IN FV(Not(?? (N + 1) (attempt_form q (N + 1) N (N + 2))))) /\
    ~(n + 1 IN FV(Not(?? (N + 1) (attempt_form q (N + 1) N (N + 2))))) /\
    ~(n IN FV(recstep_form q N)) /\
    ~(n + 1 IN FV(recstep_form q N)) /\
    ~(n + 2 IN FV(recstep_form q N)) /\
    separation_ax N n (n + 1)
       (Not(?? (N + 1) (attempt_form q (N + 1) N (N + 2)))) IN s /\
    replacement_ax N (N + 1) n (n + 1) (n + 2) (recstep_form q N) IN s`;;

let ENGINE_READY_VSTEP = prove
 (`engine_ready zfw_ax vstep_form 5 20`,
  REWRITE_TAC[engine_ready;
    ARITH_RULE `5 + 1 = 6 /\ 5 + 2 = 7 /\ 20 + 1 = 21 /\ 20 + 2 = 22`] THEN
  REWRITE_TAC[FRESH_ENGINE_VSTEP; ZFW_AX_MEMBERS] THEN
  REPEAT CONJ_TAC THEN
  TRY(GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP FVLT_VSTEP_FORM) THEN
      ARITH_TAC) THEN
  ARITH_TAC);;

let ENGINE_READY_LSTEP = prove
 (`engine_ready zfw_ax lstep_form 5 20`,
  REWRITE_TAC[engine_ready;
    ARITH_RULE `5 + 1 = 6 /\ 5 + 2 = 7 /\ 20 + 1 = 21 /\ 20 + 2 = 22`] THEN
  REWRITE_TAC[FRESH_ENGINE_LSTEP; ZFW_AX_MEMBERS] THEN
  REPEAT CONJ_TAC THEN
  TRY(GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP FVLT_LSTEP_FORM) THEN
      ARITH_TAC) THEN
  ARITH_TAC);;

let ENGINE_READY_SATSTEP = prove
 (`engine_ready zfw_ax satstep_form 5 20`,
  REWRITE_TAC[engine_ready;
    ARITH_RULE `5 + 1 = 6 /\ 5 + 2 = 7 /\ 20 + 1 = 21 /\ 20 + 2 = 22`] THEN
  REWRITE_TAC[FRESH_ENGINE_SATSTEP; ZFW_AX_MEMBERS] THEN
  REPEAT CONJ_TAC THEN
  TRY(GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP FVLT_SATSTEP_FORM) THEN
      ARITH_TAC) THEN
  ARITH_TAC);;

let omega_ready = new_definition
 `omega_ready s p x n <=>
    ~(n = x) /\ ~(n + 1 = x) /\ ~(n IN FV p) /\ ~(n + 1 IN FV p) /\
    separation_ax x n (n + 1) p IN s`;;

let OMEGA_READY_ORD = prove
 (`omega_ready zfw_ax (ordinal_form 0) 0 10`,
  REWRITE_TAC[omega_ready; ARITH_RULE `10 + 1 = 11`] THEN
  REWRITE_TAC[FV_ORDINAL_FORM; IN_INSERT; NOT_IN_EMPTY] THEN
  REWRITE_TAC[ZFW_AX_MEMBERS] THEN ARITH_TAC);;

let OMEGA_READY_SUBSET = prove
 (`omega_ready zfw_ax (subset_form 0 1) 0 10`,
  REWRITE_TAC[omega_ready; ARITH_RULE `10 + 1 = 11`] THEN
  REWRITE_TAC[FV_SUBSET_FORM; IN_INSERT; NOT_IN_EMPTY] THEN
  REWRITE_TAC[ZFW_AX_MEMBERS] THEN ARITH_TAC);;

let OMEGA_READY_ZF = prove
 (`!p x. ?n. omega_ready ZF_AX p x n`,
  REPEAT GEN_TAC THEN
  MP_TAC(ISPEC `(x:num) INSERT FV p` VARIANTS_EXIST) THEN
  REWRITE_TAC[FINITE_INSERT; FV_FINITE] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(fun th ->
    MP_TAC(SPEC `n + 1` th) THEN MP_TAC(SPEC `n:num` th)) THEN
  REWRITE_TAC[omega_ready; IN_INSERT; DE_MORGAN_THM; LE_REFL;
              ARITH_RULE `n <= n + 1`] THEN
  REPEAT(DISCH_THEN STRIP_ASSUME_TAC) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ZF_AX_SEP THEN ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let ENGINE_READY_ZF = prove
 (`!q N. (!m. m IN FV q ==> m < N) /\ 1 < N
         ==> ?n. engine_ready ZF_AX q N n`,
  REPEAT STRIP_TAC THEN
  MP_TAC(ISPEC
   `{N, N + 1} UNION
    FV(Not(?? (N + 1) (attempt_form q (N + 1) N (N + 2)))) UNION
    FV(recstep_form q N)` VARIANTS_EXIST) THEN
  REWRITE_TAC[FINITE_UNION; FINITE_INSERT; FINITE_EMPTY; FV_FINITE] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `n:num` THEN
  DISCH_THEN(fun th -> MP_TAC(SPEC `n + 2` th) THEN
    MP_TAC(SPEC `n + 1` th) THEN MP_TAC(SPEC `n:num` th)) THEN
  REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; DE_MORGAN_THM; LE_REFL;
              ARITH_RULE `n <= n + 1 /\ n <= n + 2`] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[engine_ready] THEN
  REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
  TRY(MATCH_MP_TAC ZF_AX_SEP) THEN TRY(MATCH_MP_TAC ZF_AX_REP) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let ENGINE_READY_ZF_EXISTS = prove
 (`!q. ?N n. engine_ready ZF_AX q N n`,
  GEN_TAC THEN MP_TAC(ISPEC `FV q` VARIANTS_EXIST) THEN
  REWRITE_TAC[FV_FINITE] THEN DISCH_THEN(X_CHOOSE_TAC `k:num`) THEN
  EXISTS_TAC `k + 2` THEN MATCH_MP_TAC ENGINE_READY_ZF THEN
  CONJ_TAC THENL [ALL_TAC; ARITH_TAC] THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN `m < k` MP_TAC THENL [ASM_MESON_TAC[NOT_LT]; ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Separation and replacement in a model of zfw_ax, for the instances in     *)
(* zfw_ax with witness slots 10, 11 (and 12).                                *)
(* ------------------------------------------------------------------------- *)

let ZF_SEPARATION_W = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !p x v a.
         separation_ax x 10 11 p IN zfw_ax /\
         ~(10 IN FV p) /\ ~(11 IN FV p) /\ ~(10 = x) /\ ~(11 = x) /\
         valuation D v /\ a IN D
         ==> ?ss. ss IN D /\
                  !z. z IN D ==>
                    (E z ss <=> E z a /\ holds D E ((x |-> z) v) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`; `p:form`; `x:num`;
               `10`; `v:num->A`; `a:A`] ZFG_SEPARATION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `10 + 1 = 11`]; DISCH_THEN ACCEPT_TAC]);;

let ZF_REPLACEMENT_W = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !p x y v a.
         replacement_ax x y 10 11 12 p IN zfw_ax /\
         ~(x = y) /\ ~(10 = x) /\ ~(11 = x) /\ ~(12 = x) /\
         ~(10 = y) /\ ~(11 = y) /\ ~(12 = y) /\
         ~(10 IN FV p) /\ ~(11 IN FV p) /\ ~(12 IN FV p) /\
         valuation D v /\ a IN D /\
         (!u. u IN D /\ E u a
              ==> ?w. w IN D /\
                      !w'. w' IN D /\ holds D E ((y |-> w') ((x |-> u) v)) p
                           ==> w' = w)
         ==> ?b. b IN D /\
                 !w. w IN D
                     ==> (E w b <=>
                          ?u. u IN D /\ E u a /\
                              holds D E ((y |-> w) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`; `p:form`; `x:num`;
               `y:num`; `10`; `v:num->A`; `a:A`] ZFG_REPLACEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_RULE `10 + 1 = 11 /\ 10 + 2 = 12`];
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Unpacking what it means to be a model of ZF: each axiom becomes a         *)
(* directly usable semantic fact about the domain D and the membership       *)
(* relation E (for the closed axioms, via the versions for zfw_ax). The      *)
(* schemes become rules valid for every formula p and every choice of        *)
(* distinguished variables, with no syntactic side conditions at all: the    *)
(* freshness bureaucracy is handled here once and for all by instantiating   *)
(* the scheme at variables beyond those free in p.                           *)
(* ------------------------------------------------------------------------- *)

let ZF_EXTENSIONALITY_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !x y. x IN D /\ y IN D /\
               (!z. z IN D ==> (E z x <=> E z y))
               ==> x = y`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_EXTENSIONALITY = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x y. x IN D /\ y IN D /\
               (!z. z IN D ==> (E z x <=> E z y))
               ==> x = y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_EXTENSIONALITY_F));;

let ZF_PAIRING_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !x y. x IN D /\ y IN D
               ==> ?p. p IN D /\
                       !z. z IN D ==> (E z p <=> z = x \/ z = y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_PAIRING) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_PAIRING = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x y. x IN D /\ y IN D
               ==> ?p. p IN D /\
                       !z. z IN D ==> (E z p <=> z = x \/ z = y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_PAIRING_F));;

let ZF_UNION_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !x. x IN D
             ==> ?u. u IN D /\
                     !z. z IN D
                         ==> (E z u <=> ?w. w IN D /\ E w x /\ E z w)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_UNION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_UNION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN D
             ==> ?u. u IN D /\
                     !z. z IN D
                         ==> (E z u <=> ?w. w IN D /\ E w x /\ E z w)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_UNION_F));;

let ZF_POWERSET_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !x. x IN D
             ==> ?pp. pp IN D /\
                      !z. z IN D
                          ==> (E z pp <=> !w. w IN D /\ E w z ==> E w x)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_POWERSET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_POWERSET = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN D
             ==> ?pp. pp IN D /\
                      !z. z IN D
                          ==> (E z pp <=> !w. w IN D /\ E w z ==> E w x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_POWERSET_F));;

let ZF_FOUNDATION_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> !x. x IN D /\ (?u. u IN D /\ E u x)
             ==> ?y. y IN D /\ E y x /\
                     !z. z IN D /\ E z y ==> ~(E z x)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_FOUNDATION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN D /\ (?u. u IN D /\ E u x)
             ==> ?y. y IN D /\ E y x /\
                     !z. z IN D /\ E z y ==> ~(E z x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_FOUNDATION_F));;

let ZF_INFINITY_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax
     ==> ?i. i IN D /\
             (?e. e IN D /\ E e i /\ !z. z IN D ==> ~(E z e)) /\
             (!u. u IN D /\ E u i
                  ==> ?s. s IN D /\ E s i /\
                          !z. z IN D ==> (E z s <=> E z u \/ z = u))`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`] ZFG_INFINITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ZFW_AX_MEMBERS]; DISCH_THEN ACCEPT_TAC]);;

let ZF_INFINITY = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> ?i. i IN D /\
             (?e. e IN D /\ E e i /\ !z. z IN D ==> ~(E z e)) /\
             (!u. u IN D /\ E u i
                  ==> ?s. s IN D /\ E s i /\
                          !z. z IN D ==> (E z s <=> E z u \/ z = u))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ZF_INFINITY_F));;

let ZF_SEPARATION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p x v a.
           valuation D v /\ a IN D
           ==> ?s. s IN D /\
                   !z. z IN D
                       ==> (E z s <=> E z a /\ holds D E ((x |-> z) v) p)`,
  REPEAT STRIP_TAC THEN
  X_CHOOSE_TAC `n:num` (SPECL [`p:form`; `x:num`] OMEGA_READY_ZF) THEN
  MATCH_MP_TAC ZFG_SEPARATION THEN
  MAP_EVERY EXISTS_TAC [`ZF_AX`; `n:num`] THEN
  RULE_ASSUM_TAC(REWRITE_RULE[omega_ready]) THEN ASM_REWRITE_TAC[]);;

let ZF_REPLACEMENT = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p x y v a.
           ~(x = y) /\ valuation D v /\ a IN D /\
           (!u. u IN D /\ E u a
                ==> ?w. w IN D /\
                        !w'. w' IN D /\
                             holds D E ((y |-> w') ((x |-> u) v)) p
                             ==> w' = w)
           ==> ?b. b IN D /\
                   !w. w IN D
                       ==> (E w b <=>
                            ?u. u IN D /\ E u a /\
                                holds D E ((y |-> w) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPEC `(x:num) INSERT y INSERT FV p` VARIANTS_EXIST) THEN
  REWRITE_TAC[FINITE_INSERT; FV_FINITE] THEN
  DISCH_THEN(X_CHOOSE_THEN `n:num` (fun th ->
    MP_TAC(SPEC `n + 2` th) THEN MP_TAC(SPEC `n + 1` th) THEN
    MP_TAC(SPEC `n:num` th))) THEN
  REWRITE_TAC[IN_INSERT; DE_MORGAN_THM; LE_REFL;
              ARITH_RULE `n:num <= n + 1 /\ n <= n + 2`] THEN
  REPEAT(DISCH_THEN STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC ZFG_REPLACEMENT THEN
  MAP_EVERY EXISTS_TAC [`ZF_AX`; `n:num`] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC ZF_AX_REP THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Internal set-theoretic notions, as semantic relations over a model. The   *)
(* convention is that the "output" set is the last argument, and each        *)
(* relation asserts membership of that output in the domain together with    *)
(* the characterization of its E-members. Existence comes from the ZF        *)
(* axioms (in some cases through an inline separation formula), uniqueness   *)
(* from extensionality. The Kuratowski ordered pair then gets its crucial    *)
(* injectivity property.                                                     *)
(* ------------------------------------------------------------------------- *)

let esubset = new_definition
  `esubset D (E:A->A->bool) x y <=>
        !w. w IN D /\ E w x ==> E w y`;;

let etransitive = new_definition
  `etransitive D (E:A->A->bool) x <=>
        !y. y IN D /\ E y x ==> esubset D E y x`;;

let eempty = new_definition
  `eempty D (E:A->A->bool) z <=>
        z IN D /\ !w. w IN D ==> ~(E w z)`;;

let epair = new_definition
  `epair D (E:A->A->bool) x y z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> w = x \/ w = y)`;;

let eunion = new_definition
  `eunion D (E:A->A->bool) x z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> ?u. u IN D /\ E u x /\ E w u)`;;

let epow = new_definition
  `epow D (E:A->A->bool) x z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> esubset D E w x)`;;

let einter = new_definition
  `einter D (E:A->A->bool) x y z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> E w x /\ E w y)`;;

let ediff = new_definition
  `ediff D (E:A->A->bool) x y z <=>
        z IN D /\ !w. w IN D ==> (E w z <=> E w x /\ ~(E w y))`;;

let ebunion = new_definition
  `ebunion D (E:A->A->bool) x y z <=>
        ?p. epair D E x y p /\ eunion D E p z`;;

let esuc = new_definition
  `esuc D (E:A->A->bool) x z <=>
        ?s. epair D E x x s /\ ebunion D E x s z`;;

let eopair = new_definition
  `eopair D (E:A->A->bool) x y z <=>
        ?s p. epair D E x x s /\ epair D E x y p /\ epair D E s p z`;;

let ESUBSET_ANTISYM_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D /\
        esubset D E x y /\ esubset D E y x
        ==> x = y`,
  REWRITE_TAC[esubset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let ESUBSET_ANTISYM = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D /\
        esubset D E x y /\ esubset D E y x
        ==> x = y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESUBSET_ANTISYM_F));;

(* ------------------------------------------------------------------------- *)
(* The output of each operation is in the domain.                            *)
(* ------------------------------------------------------------------------- *)

let EEMPTY_IN = prove
 (`!D (E:A->A->bool) z. eempty D E z ==> z IN D`,
  SIMP_TAC[eempty]);;

let EPAIR_IN = prove
 (`!D (E:A->A->bool) x y z. epair D E x y z ==> z IN D`,
  SIMP_TAC[epair]);;

let EUNION_IN = prove
 (`!D (E:A->A->bool) x z. eunion D E x z ==> z IN D`,
  SIMP_TAC[eunion]);;

let EPOW_IN = prove
 (`!D (E:A->A->bool) x z. epow D E x z ==> z IN D`,
  SIMP_TAC[epow]);;

let EBUNION_IN = prove
 (`!D (E:A->A->bool) x y z. ebunion D E x y z ==> z IN D`,
  REWRITE_TAC[ebunion] THEN MESON_TAC[EUNION_IN]);;

let ESUC_IN = prove
 (`!D (E:A->A->bool) x z. esuc D E x z ==> z IN D`,
  REWRITE_TAC[esuc] THEN MESON_TAC[EBUNION_IN]);;

let EOPAIR_IN = prove
 (`!D (E:A->A->bool) x y z. eopair D E x y z ==> z IN D`,
  REWRITE_TAC[eopair] THEN MESON_TAC[EPAIR_IN]);;

(* ------------------------------------------------------------------------- *)
(* Uniqueness of each operation, from extensionality. The pattern            *)
(* FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) then simp is       *)
(* deterministic and fast, where a naive MESON with extensionality           *)
(* diverges.                                                                 *)
(* ------------------------------------------------------------------------- *)

let EEMPTY_UNIQUE_F = prove
 (`!D (E:A->A->bool) z z'.
        model D E zfw_ax /\ eempty D E z /\ eempty D E z' ==> z = z'`,
  REWRITE_TAC[eempty] THEN MESON_TAC[ZF_EXTENSIONALITY_F]);;

let EEMPTY_UNIQUE = prove
 (`!D (E:A->A->bool) z z'.
        model D E ZF_AX /\ eempty D E z /\ eempty D E z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EEMPTY_UNIQUE_F));;

let EPAIR_UNIQUE_F = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E zfw_ax /\ epair D E x y z /\ epair D E x y z' ==> z = z'`,
  REWRITE_TAC[epair] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let EPAIR_UNIQUE = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E ZF_AX /\ epair D E x y z /\ epair D E x y z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EPAIR_UNIQUE_F));;

let EUNION_UNIQUE_F = prove
 (`!D (E:A->A->bool) x z z'.
        model D E zfw_ax /\ eunion D E x z /\ eunion D E x z' ==> z = z'`,
  REWRITE_TAC[eunion] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let EUNION_UNIQUE = prove
 (`!D (E:A->A->bool) x z z'.
        model D E ZF_AX /\ eunion D E x z /\ eunion D E x z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EUNION_UNIQUE_F));;

let EPOW_UNIQUE = prove
 (`!D (E:A->A->bool) x z z'.
        model D E ZF_AX /\ epow D E x z /\ epow D E x z' ==> z = z'`,
  REWRITE_TAC[epow] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EDIFF_UNIQUE = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E ZF_AX /\ ediff D E x y z /\ ediff D E x y z' ==> z = z'`,
  REWRITE_TAC[ediff] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Existence of each operation. The intersection and difference cases go     *)
(* through the separation scheme with an inline formula (0 %% 1 resp.        *)
(* Not(0 %% 1)) and an explicitly built parameter valuation: this is the     *)
(* prototype for all future uses of separation.                              *)
(* ------------------------------------------------------------------------- *)

let EEMPTY_EXISTS_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax ==> ?z. eempty D E z`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`; `False`; `0`; `10`;
               `v:num->A`; `(v:num->A) 0`] ZFG_SEPARATION) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_RULE `10 + 1 = 11`] THEN
    ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FV; FV_CLAUSES; NOT_IN_EMPTY;
                    ARITH_EQ] THEN
    ASM_MESON_TAC[valuation];
    ALL_TAC] THEN
  REWRITE_TAC[holds; eempty] THEN MESON_TAC[]);;

let EEMPTY_EXISTS = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> ?z. eempty D E z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EEMPTY_EXISTS_F));;

let EPAIR_EXISTS_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ?z. epair D E x y z`,
  REWRITE_TAC[epair] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPECL [`x:A`; `y:A`] o MATCH_MP ZF_PAIRING_F) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let EPAIR_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. epair D E x y z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EPAIR_EXISTS_F));;

let EUNION_EXISTS_F = prove
 (`!D (E:A->A->bool) x.
        model D E zfw_ax /\ x IN D ==> ?z. eunion D E x z`,
  REWRITE_TAC[eunion] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `x:A` o MATCH_MP ZF_UNION_F) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let EUNION_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN D ==> ?z. eunion D E x z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EUNION_EXISTS_F));;

let EPOW_EXISTS_F = prove
 (`!D (E:A->A->bool) x.
        model D E zfw_ax /\ x IN D ==> ?z. epow D E x z`,
  REWRITE_TAC[epow; esubset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `x:A` o MATCH_MP ZF_POWERSET_F) THEN
  ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

let EPOW_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN D ==> ?z. epow D E x z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EPOW_EXISTS_F));;

let EINTER_EXISTS_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ?z. einter D E x y z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`;
    `0 %% 1`; `0`; `10`; `(1 |-> (y:A)) (\n. (x:A))`; `x:A`]
          ZFG_SEPARATION) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_RULE `10 + 1 = 11`] THEN
    ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FV; FV_CLAUSES; IN_INSERT; NOT_IN_EMPTY;
                    ARITH_EQ] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[valuation];
    ALL_TAC] THEN
  REWRITE_TAC[holds; VALMOD; ARITH_EQ; einter] THEN MESON_TAC[]);;

let EINTER_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. einter D E x y z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EINTER_EXISTS_F));;

let EDIFF_EXISTS_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ?z. ediff D E x y z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_ax`;
    `Not(0 %% 1)`; `0`; `10`; `(1 |-> (y:A)) (\n. (x:A))`; `x:A`]
    ZFG_SEPARATION) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_RULE `10 + 1 = 11`] THEN
    ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FV; FV_CLAUSES; IN_INSERT; NOT_IN_EMPTY;
                    ARITH_EQ] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[valuation];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_NOT; holds; VALMOD; ARITH_EQ; ediff] THEN MESON_TAC[]);;

let EDIFF_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. ediff D E x y z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EDIFF_EXISTS_F));;

(* ------------------------------------------------------------------------- *)
(* Two unordered pairs with the same elements and the resulting              *)
(* injectivity of the Kuratowski ordered pair, plus characterizations of     *)
(* binary union and successor directly in terms of membership.               *)
(* ------------------------------------------------------------------------- *)

let EPAIR_EQ_F = prove
 (`!D (E:A->A->bool) x y x' y' z.
        model D E zfw_ax /\ x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
        epair D E x y z /\ epair D E x' y' z
        ==> x = x' /\ y = y' \/ x = y' /\ y = x'`,
  REWRITE_TAC[epair] THEN MESON_TAC[]);;

let EPAIR_EQ = prove
 (`!D (E:A->A->bool) x y x' y' z.
        model D E ZF_AX /\ x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
        epair D E x y z /\ epair D E x' y' z
        ==> x = x' /\ y = y' \/ x = y' /\ y = x'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EPAIR_EQ_F));;

let EBUNION_ALT_F = prove
 (`!D (E:A->A->bool) x y z.
        model D E zfw_ax /\ x IN D /\ y IN D
        ==> (ebunion D E x y z <=>
             z IN D /\ !w. w IN D ==> (E w z <=> E w x \/ E w y))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebunion] THEN EQ_TAC THENL
   [REWRITE_TAC[epair; eunion] THEN ASM_MESON_TAC[];
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `y:A`]
           EPAIR_EXISTS_F) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
    X_GEN_TAC `p:A` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `epair D (E:A->A->bool) x y p` THEN
    REWRITE_TAC[epair; eunion] THEN ASM_MESON_TAC[]]);;

let EBUNION_ALT = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN D /\ y IN D
        ==> (ebunion D E x y z <=>
             z IN D /\ !w. w IN D ==> (E w z <=> E w x \/ E w y))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EBUNION_ALT_F));;

let EBUNION_EXISTS_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ?z. ebunion D E x y z`,
  REWRITE_TAC[ebunion] THEN
  MESON_TAC[EPAIR_EXISTS_F; EUNION_EXISTS_F; EPAIR_IN]);;

let EBUNION_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. ebunion D E x y z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EBUNION_EXISTS_F));;

let EBUNION_UNIQUE_F = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E zfw_ax /\ ebunion D E x y z /\
          ebunion D E x y z' ==> z = z'`,
  REWRITE_TAC[ebunion] THEN MESON_TAC[EPAIR_UNIQUE_F; EUNION_UNIQUE_F]);;

let EBUNION_UNIQUE = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E ZF_AX /\ ebunion D E x y z /\ ebunion D E x y z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EBUNION_UNIQUE_F));;

let ESUC_ALT_F = prove
 (`!D (E:A->A->bool) x z.
        model D E zfw_ax /\ x IN D
        ==> (esuc D E x z <=>
             z IN D /\ !w. w IN D ==> (E w z <=> E w x \/ w = x))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esuc] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `z IN D /\ !w:A. w IN D ==> (E w z <=> E w x \/ E w s)`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_ALT_F]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    ASM_SIMP_TAC[] THEN UNDISCH_TAC `epair D (E:A->A->bool) x x s` THEN
    REWRITE_TAC[epair] THEN ASM_MESON_TAC[];
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `x:A`]
           EPAIR_EXISTS_F) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
    X_GEN_TAC `s:A` THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    ASM_SIMP_TAC[EBUNION_ALT_F] THEN
    UNDISCH_TAC `epair D (E:A->A->bool) x x s` THEN
    REWRITE_TAC[epair] THEN ASM_MESON_TAC[]]);;

let ESUC_ALT = prove
 (`!D (E:A->A->bool) x z.
        model D E ZF_AX /\ x IN D
        ==> (esuc D E x z <=>
             z IN D /\ !w. w IN D ==> (E w z <=> E w x \/ w = x))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESUC_ALT_F));;

let ESUC_EXISTS_F = prove
 (`!D (E:A->A->bool) x.
        model D E zfw_ax /\ x IN D ==> ?z. esuc D E x z`,
  REWRITE_TAC[esuc] THEN
  MESON_TAC[EPAIR_EXISTS_F; EBUNION_EXISTS_F; EPAIR_IN]);;

let ESUC_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN D ==> ?z. esuc D E x z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESUC_EXISTS_F));;

let ESUC_UNIQUE_F = prove
 (`!D (E:A->A->bool) x z z'.
        model D E zfw_ax /\ esuc D E x z /\ esuc D E x z' ==> z = z'`,
  REWRITE_TAC[esuc] THEN MESON_TAC[EPAIR_UNIQUE_F; EBUNION_UNIQUE_F]);;

let ESUC_UNIQUE = prove
 (`!D (E:A->A->bool) x z z'.
        model D E ZF_AX /\ esuc D E x z /\ esuc D E x z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESUC_UNIQUE_F));;

let EOPAIR_EXISTS_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ?z. eopair D E x y z`,
  REWRITE_TAC[eopair] THEN MESON_TAC[EPAIR_EXISTS_F; EPAIR_IN]);;

let EOPAIR_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ?z. eopair D E x y z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOPAIR_EXISTS_F));;

let EOPAIR_UNIQUE_F = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E zfw_ax /\ eopair D E x y z /\ eopair D E x y z' ==> z = z'`,
  REWRITE_TAC[eopair] THEN MESON_TAC[EPAIR_UNIQUE_F]);;

let EOPAIR_UNIQUE = prove
 (`!D (E:A->A->bool) x y z z'.
        model D E ZF_AX /\ eopair D E x y z /\ eopair D E x y z' ==> z = z'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOPAIR_UNIQUE_F));;

let EOPAIR_INJ_F = prove
 (`!D (E:A->A->bool) x y x' y' z.
        model D E zfw_ax /\ x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
        eopair D E x y z /\ eopair D E x' y' z
        ==> x = x' /\ y = y'`,
  REWRITE_TAC[eopair] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D /\ (s':A) IN D /\ (p':A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) = s' /\ (p:A) = p' \/ s = p' /\ p = s'` MP_TAC THENL
   [ASM_MESON_TAC[EPAIR_EQ_F]; ALL_TAC] THEN
  STRIP_TAC THENL
   [SUBGOAL_THEN `(x:A) = x'` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_EQ_F]; ALL_TAC] THEN
    ASM_MESON_TAC[EPAIR_EQ_F];
    ASM_MESON_TAC[EPAIR_EQ_F]]);;

let EOPAIR_INJ = prove
 (`!D (E:A->A->bool) x y x' y' z.
        model D E ZF_AX /\ x IN D /\ y IN D /\ x' IN D /\ y' IN D /\
        eopair D E x y z /\ eopair D E x' y' z
        ==> x = x' /\ y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOPAIR_INJ_F));;

(* ------------------------------------------------------------------------- *)
(* Internal ordinals, Jech-style: transitive and linearly ordered by the     *)
(* membership relation. Wellfoundedness comes for free from the foundation   *)
(* axiom, which also yields the basic non-circularity of membership via      *)
(* explicitly constructed small sets, with no epsilon-induction machinery.   *)
(* The development goes: no cycles, members of ordinals are ordinals, a      *)
(* transitive proper subset of an ordinal is a member (via a minimal         *)
(* element of the difference), and hence trichotomy (via intersection).      *)
(* ------------------------------------------------------------------------- *)

let elinear = new_definition
  `elinear D (E:A->A->bool) x <=>
        !u w. u IN D /\ w IN D /\ E u x /\ E w x
              ==> E u w \/ u = w \/ E w u`;;

let eordinal = new_definition
  `eordinal D (E:A->A->bool) x <=>
        x IN D /\ etransitive D E x /\ elinear D E x`;;

let E_IRREFL_F = prove
 (`!D (E:A->A->bool) x. model D E zfw_ax /\ x IN D ==> ~(E x x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `x:A`] EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `s:A`) THEN
  FIRST_ASSUM(MP_TAC o SPEC `s:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ASM_MESON_TAC[epair; EPAIR_IN]);;

let E_IRREFL = prove
 (`!D (E:A->A->bool) x. model D E ZF_AX /\ x IN D ==> ~(E x x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW E_IRREFL_F));;

let E_NOCYCLE2_F = prove
 (`!D (E:A->A->bool) x y.
        model D E zfw_ax /\ x IN D /\ y IN D ==> ~(E x y /\ E y x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `y:A`] EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `s:A`) THEN
  FIRST_ASSUM(MP_TAC o SPEC `s:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ASM_MESON_TAC[epair; EPAIR_IN]);;

let E_NOCYCLE2 = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D ==> ~(E x y /\ E y x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW E_NOCYCLE2_F));;

let E_NOCYCLE3_F = prove
 (`!D (E:A->A->bool) x y z.
        model D E zfw_ax /\ x IN D /\ y IN D /\ z IN D
        ==> ~(E x y /\ E y z /\ E z x)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `y:A`] EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z:A`] EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `q:A`) THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `q:A`]
         EBUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `s:A`) THEN
  SUBGOAL_THEN
   `(s:A) IN D /\ !w:A. w IN D ==> (E w s <=> w = x \/ w = y \/ w = z)`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_ALT_F; EBUNION_IN; epair]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `s:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ASM_MESON_TAC[]);;

let E_NOCYCLE3 = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN D /\ y IN D /\ z IN D
        ==> ~(E x y /\ E y z /\ E z x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW E_NOCYCLE3_F));;

let EORDINAL_MEMBER_F = prove
 (`!D (E:A->A->bool) a x.
        model D E zfw_ax /\ eordinal D E a /\ x IN D /\ E x a
        ==> eordinal D E x`,
  REWRITE_TAC[eordinal] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) x a` ASSUME_TAC THENL
   [ASM_MESON_TAC[etransitive]; ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[etransitive; esubset] THEN
    X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) y a /\ E z a` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[esubset; etransitive]; ALL_TAC] THEN
    UNDISCH_TAC `elinear D (E:A->A->bool) a` THEN REWRITE_TAC[elinear] THEN
    DISCH_THEN(MP_TAC o SPECL [`z:A`; `x:A`]) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN ASM_MESON_TAC[E_NOCYCLE2_F; E_NOCYCLE3_F];
    REWRITE_TAC[elinear] THEN ASM_MESON_TAC[esubset; elinear]]);;

let EORDINAL_MEMBER = prove
 (`!D (E:A->A->bool) a x.
        model D E ZF_AX /\ eordinal D E a /\ x IN D /\ E x a
        ==> eordinal D E x`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EORDINAL_MEMBER_F));;

let EORDINAL_TRANS_SUBSET_F = prove
 (`!D (E:A->A->bool) a s.
        model D E zfw_ax /\ eordinal D E a /\ s IN D /\
        etransitive D E s /\ esubset D E s a /\ ~(s = a)
        ==> E s a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ etransitive D (E:A->A->bool) a /\
                elinear D E a` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `s:A`] EDIFF_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `d:A`) THEN
  SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `?w:A. w IN D /\ (E:A->A->bool) w d` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff; ESUBSET_ANTISYM_F; esubset]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `d:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) b a /\ ~(E b s)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) = b` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z a` ASSUME_TAC THENL
     [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
    UNDISCH_TAC `elinear D (E:A->A->bool) a` THEN REWRITE_TAC[elinear] THEN
    DISCH_THEN(MP_TAC o SPECL [`z:A`; `b:A`]) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN ASM_MESON_TAC[etransitive; esubset];
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z a` ASSUME_TAC THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    ASM_MESON_TAC[ediff]]);;

let EORDINAL_TRANS_SUBSET = prove
 (`!D (E:A->A->bool) a s.
        model D E ZF_AX /\ eordinal D E a /\ s IN D /\
        etransitive D E s /\ esubset D E s a /\ ~(s = a)
        ==> E s a`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EORDINAL_TRANS_SUBSET_F));;

let EORDINAL_TRICHOTOMY_F = prove
 (`!D (E:A->A->bool) a b.
        model D E zfw_ax /\ eordinal D E a /\ eordinal D E b
        ==> E a b \/ a = b \/ E b a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
         EINTER_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) c` ASSUME_TAC THENL
   [REWRITE_TAC[etransitive; esubset] THEN
    X_GEN_TAC `y:A` THEN STRIP_TAC THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) y a /\ E y b` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[einter]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z a /\ E z b` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
    ASM_MESON_TAC[einter];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) c a /\ esubset D E c b`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[einter; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `((c:A) = a \/ E c a) /\ ((c:A) = b \/ E c b)` MP_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_SUBSET_F]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_MESON_TAC[einter; E_IRREFL_F]);;

let EORDINAL_TRICHOTOMY = prove
 (`!D (E:A->A->bool) a b.
        model D E ZF_AX /\ eordinal D E a /\ eordinal D E b
        ==> E a b \/ a = b \/ E b a`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EORDINAL_TRICHOTOMY_F));;

let EORDINAL_EEMPTY_F = prove
 (`!D (E:A->A->bool) z. model D E zfw_ax /\ eempty D E z ==> eordinal D E z`,
  REWRITE_TAC[eempty; eordinal; etransitive; elinear; esubset] THEN
  MESON_TAC[]);;

let EORDINAL_EEMPTY = prove
 (`!D (E:A->A->bool) z. model D E ZF_AX /\ eempty D E z ==> eordinal D E z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EORDINAL_EEMPTY_F));;

let EORDINAL_ESUC_F = prove
 (`!D (E:A->A->bool) a z.
        model D E zfw_ax /\ eordinal D E a /\ esuc D E a z
        ==> eordinal D E z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(z:A) IN D /\ !w:A. w IN D ==> ((E:A->A->bool) w z <=> E w a \/ w = a)`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_ALT_F; ESUC_IN]; ALL_TAC] THEN
  REWRITE_TAC[eordinal] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[etransitive; esubset] THEN
    X_GEN_TAC `y:A` THEN STRIP_TAC THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w a` ASSUME_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    REWRITE_TAC[elinear] THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `elinear D (E:A->A->bool) a` MP_TAC THENL
     [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
    REWRITE_TAC[elinear] THEN DISCH_THEN(MP_TAC o SPECL [`u:A`; `w:A`]) THEN
    ASM_MESON_TAC[]]);;

let EORDINAL_ESUC = prove
 (`!D (E:A->A->bool) a z.
        model D E ZF_AX /\ eordinal D E a /\ esuc D E a z
        ==> eordinal D E z`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EORDINAL_ESUC_F));;

(* ------------------------------------------------------------------------- *)
(* The semantics of the formula macros, starting with emptiness, inclusion   *)
(* and successor. As a macro computes its bound variables beyond its free    *)
(* ones, its HOLDS characterization needs no freshness side conditions, just *)
(* a valuation (and sometimes the model) hypothesis to fold the semantic     *)
(* relation.                                                                 *)
(* ------------------------------------------------------------------------- *)

let HOLDS_EMPTY_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (empty_form i) <=> eempty D E (v i))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[empty_form; holds; HOLDS_NOT; eempty] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`] THEN
  ASM_MESON_TAC[valuation]);;

let HOLDS_SUBSET_FORM = prove
 (`!D (E:A->A->bool) v i j.
        holds D E v (subset_form i j) <=> esubset D E (v i) (v j)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[subset_form; esubset] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(MAX i j + 1 = i)`] THEN
  REWRITE_TAC[holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(j = MAX i j + 1)`]);;

let HOLDS_SUC_FORM_F = prove
 (`!D (E:A->A->bool) v i j.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (suc_form i j) <=> esuc D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o REWRITE_RULE[valuation]) THEN
  REWRITE_TAC[suc_form; holds; HOLDS_IFF; HOLDS_OR] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = MAX i j + 1) /\ ~(j = MAX i j + 1)`] THEN
  ASM_SIMP_TAC[ESUC_ALT_F] THEN ASM_MESON_TAC[]);;

let HOLDS_SUC_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (suc_form i j) <=> esuc D E (v i) (v j))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SUC_FORM_F));;

(* ------------------------------------------------------------------------- *)
(* Inductive sets, and the least one: omega. The existence proof separates   *)
(* out {x IN i0 | !j. inductive(j) ==> x IN j} using the macro layer, then   *)
(* shows the result is itself inductive (uniqueness of the empty set and     *)
(* successors transfers them into every inductive set) and least.            *)
(* ------------------------------------------------------------------------- *)

let einductive = new_definition
  `einductive D (E:A->A->bool) i <=>
        i IN D /\
        (?e. eempty D E e /\ E e i) /\
        (!u. u IN D /\ E u i ==> ?s. esuc D E u s /\ E s i)`;;

let HOLDS_INDUCTIVE_FORM_F = prove
 (`!D (E:A->A->bool) v i.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (inductive_form i) <=> einductive D E (v i))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o REWRITE_RULE[valuation]) THEN
  REWRITE_TAC[inductive_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_EXISTSMEM; HOLDS_FORALLMEM;
               ARITH_RULE `~(i + 1 = i) /\ ~(i + 2 = i)`] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = i + 1) /\ ~(i = i + 2) /\ ~(i + 1 = i + 2)`] THEN
  REWRITE_TAC[einductive] THEN
  SUBGOAL_THEN
   `(!a:A. a IN D
           ==> (holds D E (((i + 1) |-> a) v) (empty_form (i + 1)) <=>
                eempty D E a)) /\
    (!a a':A. a IN D /\ a' IN D
              ==> (holds D E (((i + 2) |-> a') (((i + 1) |-> a) v))
                         (suc_form (i + 1) (i + 2)) <=>
                   esuc D E a a'))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [REPEAT STRIP_TAC THEN
      ASM_SIMP_TAC[HOLDS_EMPTY_FORM; VALUATION_VALMOD; VALMOD_BASIC];
      REPEAT STRIP_TAC THEN
      ASM_SIMP_TAC[HOLDS_SUC_FORM_F; VALUATION_VALMOD; VALMOD_BASIC;
                   VALMOD_OTHER; ARITH_RULE `~(i + 1 = i + 2)`]];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN ASM_MESON_TAC[eempty; ESUC_IN]);;

let HOLDS_INDUCTIVE_FORM = prove
 (`!D (E:A->A->bool) v i.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (inductive_form i) <=> einductive D E (v i))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_INDUCTIVE_FORM_F));;

let EINDUCTIVE_EXISTS_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax ==> ?i. einductive D E i`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o MATCH_MP ZF_INFINITY_F) THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `i:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[einductive] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  ASM_SIMP_TAC[ESUC_ALT_F]);;

let EINDUCTIVE_EXISTS = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> ?i. einductive D E i`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EINDUCTIVE_EXISTS_F));;

let eomega = new_definition
  `eomega D (E:A->A->bool) w <=>
        einductive D E w /\ !i. einductive D E i ==> esubset D E w i`;;

let EOMEGA_EXISTS_F = prove
 (`!D (E:A->A->bool). model D E zfw_ax ==> ?w. eomega D E w`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `i0:A` o MATCH_MP EINDUCTIVE_EXISTS_F) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `(i0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[einductive]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`!! 1 (inductive_form 1 --> (0 %% 1))`; `0`; `v:num->A`; `i0:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> ((E:A->A->bool) z s <=>
                      E z i0 /\
                      !j:A. j IN D /\ einductive D E j ==> E z j)`
  ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[] THEN
    AP_TERM_TAC THEN REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[HOLDS_INDUCTIVE_FORM_F; VALUATION_VALMOD; VALMOD_BASIC;
                 VALMOD_OTHER; ARITH_RULE `~(0 = 1)`] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC
   `!z:A. z IN D
          ==> ((E:A->A->bool) z s <=>
               E z i0 /\
               holds D E ((0 |-> z) v)
                 (!! 1 (inductive_form 1 --> 0 %% 1)))` THEN
  DISCH_THEN(K ALL_TAC) THEN
  EXISTS_TAC `s:A` THEN REWRITE_TAC[eomega] THEN
  MATCH_MP_TAC(TAUT `p /\ (p ==> q) ==> p /\ q`) THEN CONJ_TAC THENL
   [REWRITE_TAC[einductive] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBGOAL_THEN `?e:A. eempty D E e` (X_CHOOSE_TAC `e:A`) THENL
       [ASM_MESON_TAC[EEMPTY_EXISTS_F]; ALL_TAC] THEN
      SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EEMPTY_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!j:A. j IN D /\ einductive D E j ==> (E:A->A->bool) e j`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[einductive; EEMPTY_UNIQUE_F]; ALL_TAC] THEN
      EXISTS_TAC `e:A` THEN ASM_SIMP_TAC[] THEN ASM_MESON_TAC[];
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `?t:A. esuc D E u t` (X_CHOOSE_TAC `t:A`) THENL
       [ASM_MESON_TAC[ESUC_EXISTS_F]; ALL_TAC] THEN
      SUBGOAL_THEN `(t:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!j:A. j IN D /\ einductive D E j ==> (E:A->A->bool) u j`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!j:A. j IN D /\ einductive D E j ==> (E:A->A->bool) t j`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[einductive; ESUC_UNIQUE_F]; ALL_TAC] THEN
      EXISTS_TAC `t:A` THEN ASM_SIMP_TAC[] THEN ASM_MESON_TAC[]];
    DISCH_TAC THEN X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[einductive]]);;

let EOMEGA_EXISTS = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> ?w. eomega D E w`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOMEGA_EXISTS_F));;

let EOMEGA_UNIQUE_F = prove
 (`!D (E:A->A->bool) w w'.
        model D E zfw_ax /\ eomega D E w /\ eomega D E w' ==> w = w'`,
  REWRITE_TAC[eomega] THEN MESON_TAC[ESUBSET_ANTISYM_F; einductive]);;

let EOMEGA_UNIQUE = prove
 (`!D (E:A->A->bool) w w'.
        model D E ZF_AX /\ eomega D E w /\ eomega D E w' ==> w = w'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOMEGA_UNIQUE_F));;

let EOMEGA_IN = prove
 (`!D (E:A->A->bool) w. eomega D E w ==> w IN D`,
  REWRITE_TAC[eomega; einductive] THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The generic internal induction principle for omega: for any formula p     *)
(* (with parameters via the ambient valuation), if it holds of the empty     *)
(* set and is preserved by successors within omega, it holds of every        *)
(* member of omega. All concrete inductions instantiate this.                *)
(* ------------------------------------------------------------------------- *)

let EOMEGA_INDUCT_GEN = prove
 (`!D (E:A->A->bool) ax w p x v n.
        model D E ax /\ zfw_ax SUBSET ax /\ omega_ready ax p x n /\
        eomega D E w /\ valuation D v /\
        (!e. eempty D E e ==> holds D E ((x |-> e) v) p) /\
        (!u s. u IN D /\ E u w /\ holds D E ((x |-> u) v) p /\
               esuc D E u s
               ==> holds D E ((x |-> s) v) p)
        ==> !m. m IN D /\ E m w ==> holds D E ((x |-> m) v) p`,
  REPEAT GEN_TAC THEN REWRITE_TAC[omega_ready] THEN STRIP_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) zfw_ax` ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `einductive D (E:A->A->bool) w /\ (w:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ax:form->bool`; `p:form`;
                `x:num`; `n:num`; `v:num->A`; `w:A`] ZFG_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `einductive D (E:A->A->bool) t` ASSUME_TAC THENL
   [REWRITE_TAC[einductive] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBGOAL_THEN `?e:A. eempty D E e` (X_CHOOSE_TAC `e:A`) THENL
       [ASM_MESON_TAC[EEMPTY_EXISTS_F]; ALL_TAC] THEN
      SUBGOAL_THEN `(e:A) IN D /\ (E:A->A->bool) e w`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EEMPTY_IN; einductive; EEMPTY_UNIQUE_F]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u w /\ holds D E ((x |-> u) v) p`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?tt:A. esuc D (E:A->A->bool) u tt /\ E tt w`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[einductive]; ALL_TAC] THEN
      EXISTS_TAC `tt:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(tt:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) w t` MP_TAC THENL
   [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN DISCH_TAC THEN
  X_GEN_TAC `m:A` THEN STRIP_TAC THEN ASM_MESON_TAC[]);;

let EOMEGA_INDUCT_F = prove
 (`!D (E:A->A->bool) w p x v n.
        model D E zfw_ax /\ omega_ready zfw_ax p x n /\
        eomega D E w /\ valuation D v /\
        (!e. eempty D E e ==> holds D E ((x |-> e) v) p) /\
        (!u s. u IN D /\ E u w /\ holds D E ((x |-> u) v) p /\
               esuc D E u s
               ==> holds D E ((x |-> s) v) p)
        ==> !m. m IN D /\ E m w ==> holds D E ((x |-> m) v) p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EOMEGA_INDUCT_GEN THEN
  MAP_EVERY EXISTS_TAC [`zfw_ax`; `n:num`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let EOMEGA_INDUCT = prove
 (`!D (E:A->A->bool) w p x v.
        model D E ZF_AX /\ eomega D E w /\ valuation D v /\
        (!e. eempty D E e ==> holds D E ((x |-> e) v) p) /\
        (!u s. u IN D /\ E u w /\ holds D E ((x |-> u) v) p /\
               esuc D E u s
               ==> holds D E ((x |-> s) v) p)
        ==> !n. n IN D /\ E n w ==> holds D E ((x |-> n) v) p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EOMEGA_INDUCT_GEN THEN
  EXISTS_TAC `ZF_AX` THEN ASM_REWRITE_TAC[ZFW_SUBSET_ZFAX; OMEGA_READY_ZF]);;

(* ------------------------------------------------------------------------- *)
(* Ordinal-hood as an object formula (ordinal_form), and the first           *)
(* applications of the induction principle: the members of omega are         *)
(* ordinals, and omega is itself an ordinal (transitivity by induction with  *)
(* omega itself as a valuation parameter, linearity from trichotomy of its   *)
(* ordinal members).                                                         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_TRANSITIVE_FORM = prove
 (`!D (E:A->A->bool) v i.
        holds D E v (transitive_form i) <=> etransitive D E (v i)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[transitive_form; etransitive] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(i + 1 = i)`] THEN
  REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`]);;

let HOLDS_LINEAR_FORM = prove
 (`!D (E:A->A->bool) v i.
        holds D E v (linear_form i) <=> elinear D E (v i)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[linear_form; elinear] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(i + 1 = i) /\ ~(i + 2 = i)`] THEN
  REWRITE_TAC[HOLDS_OR; holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = i + 1) /\ ~(i = i + 2) /\
                       ~(i + 1 = i + 2) /\ ~(i + 2 = i + 1)`] THEN
  MESON_TAC[]);;

let HOLDS_ORDINAL_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (ordinal_form i) <=> eordinal D E (v i))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ordinal_form; HOLDS_AND; HOLDS_TRANSITIVE_FORM;
              HOLDS_LINEAR_FORM; eordinal] THEN
  ASM_MESON_TAC[valuation]);;

let EOMEGA_ORDINALS_F = prove
 (`!D (E:A->A->bool) w n.
        model D E zfw_ax /\ eomega D E w /\ n IN D /\ E n w
        ==> eordinal D E n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `ordinal_form 0`;
                `0`; `v:num->A`; `10`] EOMEGA_INDUCT_F) THEN
  ASM_REWRITE_TAC[OMEGA_READY_ORD] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) v)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD; EEMPTY_IN]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD_BASIC] THEN
      ASM_MESON_TAC[EORDINAL_EEMPTY_F];
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D ((0 |-> (u:A)) v) /\ valuation D ((0 |-> (s:A)) v)`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD; ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
       [ASM_MESON_TAC[HOLDS_ORDINAL_FORM; VALMOD_BASIC]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD_BASIC] THEN
      ASM_MESON_TAC[EORDINAL_ESUC_F]];
    DISCH_THEN(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D ((0 |-> (n:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM; VALMOD_BASIC]]);;

let EOMEGA_ORDINALS = prove
 (`!D (E:A->A->bool) w n.
        model D E ZF_AX /\ eomega D E w /\ n IN D /\ E n w
        ==> eordinal D E n`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOMEGA_ORDINALS_F));;

let EOMEGA_ORDINAL_F = prove
 (`!D (E:A->A->bool) w.
        model D E zfw_ax /\ eomega D E w ==> eordinal D E w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  REWRITE_TAC[eordinal] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[etransitive] THEN X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
                MATCH_MP MODEL_NONEMPTY) THEN
    SUBGOAL_THEN `valuation D ((1 |-> (w:A)) v0)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `subset_form 0 1`;
                  `0`; `(1 |-> (w:A)) v0`; `10`] EOMEGA_INDUCT_F) THEN
    ASM_REWRITE_TAC[OMEGA_READY_SUBSET] THEN ANTS_TAC THENL
     [REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(1 = 0)`] THEN
      CONJ_TAC THENL
       [X_GEN_TAC `e:A` THEN DISCH_TAC THEN
        ASM_MESON_TAC[eempty; esubset];
        MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN STRIP_TAC THEN
        SUBGOAL_THEN
         `!z:A. z IN D ==> ((E:A->A->bool) z s <=> E z u \/ z = u)`
        ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_ALT_F]; ALL_TAC] THEN
        REWRITE_TAC[esubset] THEN
        UNDISCH_TAC `esubset D (E:A->A->bool) u w` THEN
        REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]];
      DISCH_THEN(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(1 = 0)`]];
    REWRITE_TAC[elinear] THEN
    ASM_MESON_TAC[EOMEGA_ORDINALS_F; EORDINAL_TRICHOTOMY_F]]);;

let EOMEGA_ORDINAL = prove
 (`!D (E:A->A->bool) w.
        model D E ZF_AX /\ eomega D E w ==> eordinal D E w`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOMEGA_ORDINAL_F));;

(* ------------------------------------------------------------------------- *)
(* Transfinite induction over the internal ordinals, again generic in an     *)
(* arbitrary formula with parameters. The proof takes a minimal violator     *)
(* inside the successor of a putative counterexample, using foundation on    *)
(* the separated set of violators.                                           *)
(* ------------------------------------------------------------------------- *)

let EORDINAL_IN = prove
 (`!D (E:A->A->bool) a. eordinal D E a ==> a IN D`,
  SIMP_TAC[eordinal]);;

let ESUC_MEMBER_F = prove
 (`!D (E:A->A->bool) a t. model D E zfw_ax /\ a IN D /\ esuc D E a t
        ==> E a t`,
  MESON_TAC[ESUC_ALT_F; ESUC_IN]);;

let ESUC_MEMBER = prove
 (`!D (E:A->A->bool) a t. model D E ZF_AX /\ a IN D /\ esuc D E a t
        ==> E a t`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESUC_MEMBER_F));;

let EORDINAL_INDUCT_GEN = prove
 (`!D (E:A->A->bool) ax p x v n.
        model D E ax /\ zfw_ax SUBSET ax /\ omega_ready ax (Not p) x n /\
        valuation D v /\
        (!a. eordinal D E a /\
             (!b. b IN D /\ E b a ==> holds D E ((x |-> b) v) p)
             ==> holds D E ((x |-> a) v) p)
        ==> !a. eordinal D E a ==> holds D E ((x |-> a) v) p`,
  REPEAT GEN_TAC THEN REWRITE_TAC[omega_ready] THEN STRIP_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) zfw_ax` ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_SUBSET]; ALL_TAC] THEN
  X_GEN_TAC `a0:A` THEN DISCH_TAC THEN
  REFUTE_THEN ASSUME_TAC THEN
  SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?t:A. esuc D E a0 t` (X_CHOOSE_TAC `t:A`) THENL
   [ASM_MESON_TAC[ESUC_EXISTS_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(t:A) IN D /\ eordinal D (E:A->A->bool) t /\ E a0 t`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC_F; ESUC_MEMBER_F]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ax:form->bool`; `Not p`;
                `x:num`; `n:num`; `v:num->A`; `t:A`] ZFG_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[HOLDS_NOT]) THEN
  SUBGOAL_THEN `?u:A. u IN D /\ (E:A->A->bool) u s` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `s:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `(E:A->A->bool) m t /\ ~holds D E ((x |-> m) v) p`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER_F]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D /\ (E:A->A->bool) b m ==> holds D E ((x |-> b) v) p`
  ASSUME_TAC THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) b t` ASSUME_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let EORDINAL_INDUCT_F = prove
 (`!D (E:A->A->bool) p x v n.
        model D E zfw_ax /\ omega_ready zfw_ax (Not p) x n /\
        valuation D v /\
        (!a. eordinal D E a /\
             (!b. b IN D /\ E b a ==> holds D E ((x |-> b) v) p)
             ==> holds D E ((x |-> a) v) p)
        ==> !a. eordinal D E a ==> holds D E ((x |-> a) v) p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EORDINAL_INDUCT_GEN THEN
  MAP_EVERY EXISTS_TAC [`zfw_ax`; `n:num`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let EORDINAL_INDUCT = prove
 (`!D (E:A->A->bool) p x v.
        model D E ZF_AX /\ valuation D v /\
        (!a. eordinal D E a /\
             (!b. b IN D /\ E b a ==> holds D E ((x |-> b) v) p)
             ==> holds D E ((x |-> a) v) p)
        ==> !a. eordinal D E a ==> holds D E ((x |-> a) v) p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EORDINAL_INDUCT_GEN THEN
  EXISTS_TAC `ZF_AX` THEN ASM_REWRITE_TAC[ZFW_SUBSET_ZFAX; OMEGA_READY_ZF]);;

(* ------------------------------------------------------------------------- *)
(* Unordered and (Kuratowski) ordered pairs as object formulas. Note that    *)
(* internal bound-variable shadowing inside composed macros is harmless      *)
(* because each HOLDS characterization is valuation-generic.                 *)
(* ------------------------------------------------------------------------- *)

let HOLDS_PAIR_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (pair_form i j k) <=>
             epair D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[pair_form; holds; HOLDS_IFF; HOLDS_OR; epair] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = MAX (MAX i j) k + 1) /\
                       ~(j = MAX (MAX i j) k + 1) /\
                       ~(k = MAX (MAX i j) k + 1)`] THEN
  ASM_MESON_TAC[valuation]);;

let HOLDS_OPAIR_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (opair_form i j k) <=>
             eopair D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[opair_form; HOLDS_EX; HOLDS_AND; eopair] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
            ==> valuation D
                 (((MAX (MAX i j) k + 2) |-> b)
                  (((MAX (MAX i j) k + 1) |-> a) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a a':A. a IN D /\ a' IN D
        ==> (holds D E (((MAX (MAX i j) k + 2) |-> a')
                        (((MAX (MAX i j) k + 1) |-> a) v))
                   (pair_form i i (MAX (MAX i j) k + 1)) <=>
             epair D E (v i) (v i) a) /\
            (holds D E (((MAX (MAX i j) k + 2) |-> a')
                        (((MAX (MAX i j) k + 1) |-> a) v))
                   (pair_form i j (MAX (MAX i j) k + 2)) <=>
             epair D E (v i) (v j) a') /\
            (holds D E (((MAX (MAX i j) k + 2) |-> a')
                        (((MAX (MAX i j) k + 1) |-> a) v))
                   (pair_form (MAX (MAX i j) k + 1)
                              (MAX (MAX i j) k + 2) k) <=>
             epair D E a a' (v k))`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN ASM_SIMP_TAC[HOLDS_PAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
             ARITH_RULE `~(i = MAX (MAX i j) k + 1) /\
                         ~(j = MAX (MAX i j) k + 1) /\
                         ~(k = MAX (MAX i j) k + 1) /\
                         ~(i = MAX (MAX i j) k + 2) /\
                         ~(j = MAX (MAX i j) k + 2) /\
                         ~(k = MAX (MAX i j) k + 2) /\
                         ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `a':A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `a':A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Internal functions as sets of ordered pairs, with graph application.      *)
(* ------------------------------------------------------------------------- *)

let eisfun = new_definition
  `eisfun D (E:A->A->bool) f <=>
        f IN D /\
        (!z. z IN D /\ E z f
             ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z) /\
        (!u w w' z z'. u IN D /\ w IN D /\ w' IN D /\
                       eopair D E u w z /\ E z f /\
                       eopair D E u w' z' /\ E z' f
                       ==> w = w')`;;

let eapply = new_definition
  `eapply D (E:A->A->bool) f u w <=>
        ?z. eopair D E u w z /\ E z f`;;

let eindom = new_definition
  `eindom D (E:A->A->bool) f u <=> ?w. w IN D /\ eapply D E f u w`;;

let EAPPLY_UNIQUE = prove
 (`!D (E:A->A->bool) f u w w'.
        model D E ZF_AX /\ eisfun D E f /\ u IN D /\ w IN D /\ w' IN D /\
        eapply D E f u w /\ eapply D E f u w'
        ==> w = w'`,
  REWRITE_TAC[eisfun; eapply] THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Domains and restrictions of (graphs of) internal functions, with          *)
(* existence of restrictions via separation directly on the graph.           *)
(* ------------------------------------------------------------------------- *)

let edomain = new_definition
  `edomain D (E:A->A->bool) g a <=>
        a IN D /\ !u. u IN D ==> (E u a <=> eindom D E g u)`;;

let erestrict = new_definition
  `erestrict D (E:A->A->bool) g b r <=>
        r IN D /\
        !z. z IN D
            ==> (E z r <=>
                 E z g /\ ?u w. u IN D /\ w IN D /\ E u b /\
                                eopair D E u w z)`;;

let EDOMAIN_UNIQUE = prove
 (`!D (E:A->A->bool) g a a'.
        model D E ZF_AX /\ edomain D E g a /\ edomain D E g a' ==> a = a'`,
  REWRITE_TAC[edomain] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let ERESTRICT_UNIQUE = prove
 (`!D (E:A->A->bool) g b r r'.
        model D E ZF_AX /\ erestrict D E g b r /\ erestrict D E g b r'
        ==> r = r'`,
  REWRITE_TAC[erestrict] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let ERESTRICT_EXISTS_F = prove
 (`!D (E:A->A->bool) g b.
        model D E zfw_ax /\ g IN D /\ b IN D ==> ?r. erestrict D E g b r`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (b:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`?? 3 (?? 4 ((3 %% 1) && opair_form 3 4 0))`; `0`;
     `(1 |-> (b:A)) v0`; `g:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `r:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[erestrict] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (z:A)) ((1 |-> b) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN AP_TERM_TAC THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
       ==> (holds D E ((4 |-> w) ((3 |-> u) ((0 |-> z) ((1 |-> b) v0))))
                  (opair_form 3 4 0) <=>
            eopair D E u w z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((4 |-> (w:A)) ((3 |-> u) ((0 |-> z) ((1 |-> b) v0))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ; ARITH_RULE
      `~(3 = 4) /\ ~(4 = 3) /\ ~(0 = 3) /\ ~(0 = 4)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let ERESTRICT_EXISTS = prove
 (`!D (E:A->A->bool) g b.
        model D E ZF_AX /\ g IN D /\ b IN D ==> ?r. erestrict D E g b r`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ERESTRICT_EXISTS_F));;

(* ------------------------------------------------------------------------- *)
(* The semantics of apply2_form, which applies a formula with distinguished  *)
(* variables 0 (input) and 1 (output) at two other variables, via quantified *)
(* equalities rather than any substitution operation. This is how generic    *)
(* "recursion data" formulas get composed into larger formulas.              *)
(* ------------------------------------------------------------------------- *)

let HOLDS_APPLY2_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 0) /\ ~(i = 1) /\ ~(j = 0) /\ ~(j = 1)
        ==> (holds D E v (apply2_form q i j) <=>
             holds D E ((1 |-> v j) ((0 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[apply2_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(0 = 1)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Function-hood as an object formula, factored through "is an ordered       *)
(* pair", "set of pairs" and "functional" pieces with matching semantic      *)
(* notions.                                                                  *)
(* ------------------------------------------------------------------------- *)

let eispair = new_definition
  `eispair D (E:A->A->bool) z <=>
        ?u w. u IN D /\ w IN D /\ eopair D E u w z`;;

let efunctional = new_definition
  `efunctional D (E:A->A->bool) f <=>
        !z z' u w w'.
            z IN D /\ z' IN D /\ u IN D /\ w IN D /\ w' IN D /\
            E z f /\ E z' f /\
            eopair D E u w z /\ eopair D E u w' z'
            ==> w = w'`;;

let HOLDS_ISPAIR_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (ispair_form i) <=> eispair D E (v i))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[ispair_form; HOLDS_EX; eispair] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
       ==> (holds D E (((i + 2) |-> w) (((i + 1) |-> u) v))
                  (opair_form (i + 1) (i + 2) i) <=>
            eopair D E u w (v i))`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((i + 2) |-> (w:A)) (((i + 1) |-> u) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
             ARITH_RULE `~(i + 1 = i + 2) /\ ~(i = i + 1) /\
                         ~(i = i + 2)`];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let HOLDS_RELSET_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (relset_form i) <=>
             !z. z IN D /\ E z (v i) ==> eispair D E z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[relset_form] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(i + 1 = i)`] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
        ==> (holds D E (((i + 1) |-> z) v) (ispair_form (i + 1)) <=>
             eispair D E z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((i + 1) |-> (z:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ISPAIR_FORM; VALMOD_BASIC];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let HOLDS_FUNCTIONAL_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (functional_form i) <=>
             efunctional D E (v i))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[functional_form] THEN
  SIMP_TAC[HOLDS_FORALLMEM; holds; HOLDS_AND;
           ARITH_RULE `~(i + 1 = i) /\ ~(i + 2 = i)`] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
    `~(i + 1 = i + 2) /\ ~(i + 2 = i + 1) /\ ~(i = i + 1) /\ ~(i = i + 2) /\
     ~(i + 4 = i + 5) /\ ~(i + 5 = i + 4) /\ ~(i + 4 = i + 3) /\
     ~(i + 5 = i + 3) /\ ~(i + 3 = i + 4) /\ ~(i + 3 = i + 5) /\
     ~(i = i + 3) /\ ~(i = i + 4) /\ ~(i = i + 5) /\
     ~(i + 1 = i + 3) /\ ~(i + 1 = i + 4) /\ ~(i + 1 = i + 5) /\
     ~(i + 2 = i + 3) /\ ~(i + 2 = i + 4) /\ ~(i + 2 = i + 5) /\
     ~(i + 3 = i + 1) /\ ~(i + 4 = i + 1) /\ ~(i + 5 = i + 1) /\
     ~(i + 3 = i + 2) /\ ~(i + 4 = i + 2) /\ ~(i + 5 = i + 2)`] THEN
  SUBGOAL_THEN
   `!a a' a'' a''' a'''':A.
        a IN D /\ a' IN D /\ a'' IN D /\ a''' IN D /\ a'''' IN D
        ==> (holds D E (((i + 5) |-> a'''') (((i + 4) |-> a''')
                        (((i + 3) |-> a'') (((i + 2) |-> a')
                        (((i + 1) |-> a) v)))))
                   (opair_form (i + 3) (i + 4) (i + 1)) <=>
             eopair D E a'' a''' a) /\
            (holds D E (((i + 5) |-> a'''') (((i + 4) |-> a''')
                        (((i + 3) |-> a'') (((i + 2) |-> a')
                        (((i + 1) |-> a) v)))))
                   (opair_form (i + 3) (i + 5) (i + 2)) <=>
             eopair D E a'' a'''' a')`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((i + 5) |-> (a'''':A)) (((i + 4) |-> a''')
                   (((i + 3) |-> a'') (((i + 2) |-> a')
                   (((i + 1) |-> a) v)))))`
    ASSUME_TAC THENL
     [SUBGOAL_THEN
       `valuation D (((i + 2) |-> (a':A)) (((i + 1) |-> a) v))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
     `~(i + 3 = i + 4) /\ ~(i + 3 = i + 5) /\ ~(i + 4 = i + 5) /\
      ~(i + 1 = i + 2) /\ ~(i + 1 = i + 3) /\ ~(i + 1 = i + 4) /\
      ~(i + 1 = i + 5) /\ ~(i + 2 = i + 3) /\ ~(i + 2 = i + 4) /\
      ~(i + 2 = i + 5)`];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN REWRITE_TAC[efunctional] THEN
  EQ_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let HOLDS_FUN_FORM = prove
 (`!D (E:A->A->bool) v i.
        valuation D v
        ==> (holds D E v (fun_form i) <=> eisfun D E (v i))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[fun_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_RELSET_FORM; HOLDS_FUNCTIONAL_FORM] THEN
  REWRITE_TAC[eisfun; eispair; efunctional] THEN
  SUBGOAL_THEN `(v:num->A) i IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN STRIP_TAC THEN CONJ_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_IN]);;

(* ------------------------------------------------------------------------- *)
(* Domain and restriction as object formulas.                                *)
(* ------------------------------------------------------------------------- *)

let HOLDS_DOMAIN_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (domain_form i j) <=>
             edomain D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[domain_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
    `~(j = MAX i j + 1) /\ ~(i = MAX i j + 1) /\ ~(i = MAX i j + 2) /\
     ~(i = MAX i j + 3) /\ ~(MAX i j + 1 = MAX i j + 2) /\
     ~(MAX i j + 1 = MAX i j + 3) /\ ~(MAX i j + 2 = MAX i j + 3) /\
     ~(MAX i j + 3 = MAX i j + 2) /\ ~(MAX i j + 3 = MAX i j + 1) /\
     ~(MAX i j + 2 = MAX i j + 1)`] THEN
  SUBGOAL_THEN
   `!u w z:A. u IN D /\ w IN D /\ z IN D
        ==> (holds D E (((MAX i j + 3) |-> z) (((MAX i j + 2) |-> w)
                        (((MAX i j + 1) |-> u) v)))
                   (opair_form (MAX i j + 1) (MAX i j + 2) (MAX i j + 3)) <=>
             eopair D E u w z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((MAX i j + 3) |-> (z:A)) (((MAX i j + 2) |-> w)
                   (((MAX i j + 1) |-> u) v)))`
    ASSUME_TAC THENL
     [SUBGOAL_THEN
       `valuation D (((MAX i j + 2) |-> (w:A)) (((MAX i j + 1) |-> u) v))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX i j + 1 = MAX i j + 2) /\ ~(MAX i j + 1 = MAX i j + 3) /\
       ~(MAX i j + 2 = MAX i j + 3)`];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN REWRITE_TAC[edomain; eindom; eapply] THEN
  ASM_SIMP_TAC[] THEN AP_TERM_TAC THEN ABS_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (q <=> r)) ==> (p ==> q <=> p ==> r)`) THEN
  DISCH_TAC THEN AP_TERM_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z:A` THEN ASM_MESON_TAC[EOPAIR_IN]]);;

let HOLDS_RESTRICT_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (restrict_form i j k) <=>
             erestrict D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[restrict_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
    `~(k = MAX (MAX i j) k + 1) /\ ~(i = MAX (MAX i j) k + 1) /\
     ~(j = MAX (MAX i j) k + 1) /\ ~(j = MAX (MAX i j) k + 2) /\
     ~(j = MAX (MAX i j) k + 3) /\
     ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2) /\
     ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 3) /\
     ~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 3) /\
     ~(MAX (MAX i j) k + 3 = MAX (MAX i j) k + 2) /\
     ~(MAX (MAX i j) k + 3 = MAX (MAX i j) k + 1) /\
     ~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 1)`] THEN
  SUBGOAL_THEN
   `!z u w:A. z IN D /\ u IN D /\ w IN D
        ==> (holds D E (((MAX (MAX i j) k + 3) |-> w)
                        (((MAX (MAX i j) k + 2) |-> u)
                        (((MAX (MAX i j) k + 1) |-> z) v)))
                   (opair_form (MAX (MAX i j) k + 2) (MAX (MAX i j) k + 3)
                               (MAX (MAX i j) k + 1)) <=>
             eopair D E u w z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((MAX (MAX i j) k + 3) |-> (w:A))
                   (((MAX (MAX i j) k + 2) |-> u)
                   (((MAX (MAX i j) k + 1) |-> z) v)))`
    ASSUME_TAC THENL
     [SUBGOAL_THEN
       `valuation D (((MAX (MAX i j) k + 2) |-> (u:A))
                     (((MAX (MAX i j) k + 1) |-> z) v))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 3) /\
       ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2) /\
       ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 3)`];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN REWRITE_TAC[erestrict] THEN
  ASM_SIMP_TAC[] THEN AP_TERM_TAC THEN ABS_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (q <=> r)) ==> (p ==> q <=> p ==> r)`) THEN
  DISCH_TAC THEN AP_TERM_TAC THEN
  MATCH_MP_TAC(TAUT `(q <=> r) ==> (p /\ q <=> p /\ r)`) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Attempts: g is a q-attempt on a (for recursion data q, a formula with     *)
(* distinguished input variable 0 and output variable 1, parameters via      *)
(* the ambient valuation) iff g is a function with domain a such that        *)
(* g(b) is q-related to g restricted to b, for every b in a. The object      *)
(* formula version takes an explicit fresh base n for its bound variables,   *)
(* with side conditions making its characterization work for any q.          *)
(* ------------------------------------------------------------------------- *)

let eattempt = new_definition
  `eattempt D (E:A->A->bool) q v g a <=>
        eisfun D E g /\ edomain D E g a /\
        !b r y. b IN D /\ r IN D /\ y IN D /\ E b a /\
                erestrict D E g b r /\ eapply D E g b y
                ==> holds D E ((1 |-> y) ((0 |-> r) v)) q`;;

let HOLDS_ATTEMPT_FORM = prove
 (`!D (E:A->A->bool) v q i j n.
        valuation D v /\ i < n /\ j < n /\ 1 < n /\
        (!m. m IN FV q ==> m < n)
        ==> (holds D E v (attempt_form q i j n) <=>
             eattempt D E q v (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `~(n IN FV q) /\ ~(n + 1 IN FV q) /\ ~(n + 2 IN FV q)`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ARITH_RULE `~(n < n) /\ ~(n + 1 < n) /\ ~(n + 2 < n)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(n = j) /\ ~(n = i) /\ ~(i = n) /\ ~(j = n) /\
    ~(i = n + 1) /\ ~(i = n + 2) /\ ~(i = n + 3) /\
    ~(j = n + 1) /\ ~(j = n + 2) /\ ~(j = n + 3) /\
    ~(n = n + 1) /\ ~(n = n + 2) /\ ~(n = n + 3) /\
    ~(n + 1 = n + 2) /\ ~(n + 1 = n + 3) /\ ~(n + 2 = n + 3) /\
    ~(n + 1 = n) /\ ~(n + 2 = n) /\ ~(n + 3 = n) /\
    ~(n + 2 = n + 1) /\ ~(n + 3 = n + 1) /\ ~(n + 3 = n + 2) /\
    ~(n = 0) /\ ~(n = 1) /\ ~(n + 1 = 0) /\ ~(n + 1 = 1) /\
    ~(n + 2 = 0) /\ ~(n + 2 = 1)`
  STRIP_ASSUME_TAC THENL
   [MAP_EVERY UNDISCH_TAC [`i < n`; `j < n`; `1 < n`] THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[attempt_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM; HOLDS_FORALLMEM] THEN
  REWRITE_TAC[holds; HOLDS_AND; HOLDS_EX] THEN
  REWRITE_TAC[eattempt] THEN AP_TERM_TAC THEN AP_TERM_TAC THEN
  SUBGOAL_THEN
   `!a a' a'' a''':A.
        a IN D /\ a' IN D /\ a'' IN D /\ a''' IN D
        ==> valuation D (((n + 2) |-> a'') (((n + 1) |-> a') ((n |-> a) v))) /\
            valuation D (((n + 3) |-> a''') (((n + 2) |-> a'')
                         (((n + 1) |-> a') ((n |-> a) v))))`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((n + 1) |-> (a':A)) ((n |-> a) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a a' a'' a''':A.
        a IN D /\ a' IN D /\ a'' IN D /\ a''' IN D
        ==> (holds D E (((n + 2) |-> a'') (((n + 1) |-> a') ((n |-> a) v)))
                   (restrict_form i n (n + 1)) <=>
             erestrict D E (v i) a a') /\
            (holds D E (((n + 3) |-> a''') (((n + 2) |-> a'')
                        (((n + 1) |-> a') ((n |-> a) v))))
                   (opair_form n (n + 2) (n + 3)) <=>
             eopair D E a a'' a''') /\
            (holds D E (((n + 2) |-> a'') (((n + 1) |-> a') ((n |-> a) v)))
                   (apply2_form q (n + 1) (n + 2)) <=>
             holds D E ((1 |-> a'') ((0 |-> a') v)) q)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [SUBGOAL_THEN
       `valuation D (((n + 2) |-> (a'':A)) (((n + 1) |-> a') ((n |-> a) v)))`
      ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_RESTRICT_FORM] THEN ASM_REWRITE_TAC[VALMOD];
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN ASM_REWRITE_TAC[VALMOD];
      SUBGOAL_THEN
       `valuation D (((n + 2) |-> (a'':A)) (((n + 1) |-> a') ((n |-> a) v)))`
      ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_APPLY2_FORM] THEN ASM_REWRITE_TAC[VALMOD] THEN
      ASM_SIMP_TAC[HOLDS_VALMOD_STRIP2]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[VALMOD] THEN EQ_TAC THENL
   [DISCH_TAC THEN MAP_EVERY X_GEN_TAC [`b:A`; `r:A`; `y:A`] THEN
    STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `b:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `r:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN ASM_REWRITE_TAC[] THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[eapply; EOPAIR_IN];
      ASM_MESON_TAC[]];
    DISCH_TAC THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    X_GEN_TAC `r:A` THEN DISCH_TAC THEN
    X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    ASM_MESON_TAC[eapply]]);;

(* ------------------------------------------------------------------------- *)
(* Graph application as an object formula, and some access lemmas.           *)
(* ------------------------------------------------------------------------- *)

let HOLDS_APPLYTO_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (applyto_form i j k) <=>
             eapply D E (v k) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[applyto_form; HOLDS_EX; HOLDS_AND; holds; eapply] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
    `~(k = MAX (MAX i j) k + 1) /\ ~(i = MAX (MAX i j) k + 1) /\
     ~(j = MAX (MAX i j) k + 1)`] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
        ==> (holds D E (((MAX (MAX i j) k + 1) |-> z) v)
                   (opair_form i j (MAX (MAX i j) k + 1)) <=>
             eopair D E (v i) (v j) z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((MAX (MAX i j) k + 1) |-> (z:A)) v)`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(i = MAX (MAX i j) k + 1) /\ ~(j = MAX (MAX i j) k + 1)`];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN]);;

let EISFUN_IN = prove
 (`!D (E:A->A->bool) f. eisfun D E f ==> f IN D`,
  SIMP_TAC[eisfun]);;

let EATTEMPT_FUN = prove
 (`!D (E:A->A->bool) q v g a. eattempt D E q v g a ==> eisfun D E g`,
  SIMP_TAC[eattempt]);;

let EATTEMPT_DOMAIN = prove
 (`!D (E:A->A->bool) q v g a. eattempt D E q v g a ==> edomain D E g a`,
  SIMP_TAC[eattempt]);;

let ETRANSITIVE_EINTER = prove
 (`!D (E:A->A->bool) a b c.
        etransitive D E a /\ etransitive D E b /\ einter D E a b c
        ==> etransitive D E c`,
  REWRITE_TAC[etransitive; esubset; einter] THEN REPEAT GEN_TAC THEN
  STRIP_TAC THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) y a /\ E y b` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Agreement of attempts: two attempts (with the same functional recursion   *)
(* data q) on ordinals agree wherever both are defined. Proof: separate the  *)
(* disagreement set inside the intersection using applyto_form, take a       *)
(* foundation-minimal disagreement point m, show the restrictions of the     *)
(* two attempts to m coincide (below m they agree, so the same pairs lie in  *)
(* both), and derive a contradiction from functionality of q.                *)
(* ------------------------------------------------------------------------- *)

let EATTEMPT_AGREE_F = prove
 (`!D (E:A->A->bool) q v g a g' a' b y y'.
     model D E zfw_ax /\ valuation D v /\
     (!r w w'. r IN D /\ w IN D /\ w' IN D /\
               holds D E ((1 |-> w) ((0 |-> r) v)) q /\
               holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
     eordinal D E a /\ eordinal D E a' /\
     eattempt D E q v g a /\ eattempt D E q v g' a' /\
     b IN D /\ E b a /\ E b a' /\
     y IN D /\ y' IN D /\ eapply D E g b y /\ eapply D E g' b y'
     ==> y = y'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REFUTE_THEN ASSUME_TAC THEN
  SUBGOAL_THEN
   `(g:A) IN D /\ (g':A) IN D /\ (a:A) IN D /\ (a':A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN; EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EINTER_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `c:A`) THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) c` ASSUME_TAC THENL
   [ASM_MESON_TAC[ETRANSITIVE_EINTER; eordinal]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((2 |-> (g':A)) ((1 |-> g) v))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`?? 3 (?? 4 (applyto_form 0 3 1 && (applyto_form 0 4 2 &&
                  Not(Eq 3 4))))`; `0`;
     `(2 |-> (g':A)) ((1 |-> g) v)`; `c:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!d:A. d IN D
        ==> (holds D E ((0 |-> d) ((2 |-> g') ((1 |-> g) v)))
                   (?? 3 (?? 4 (applyto_form 0 3 1 &&
                                (applyto_form 0 4 2 && Not(Eq 3 4))))) <=>
             ?w1 w2:A. w1 IN D /\ w2 IN D /\
                       eapply D E g d w1 /\ eapply D E g' d w2 /\
                       ~(w1 = w2))`
  ASSUME_TAC THENL
   [X_GEN_TAC `d:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_NOT; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN
     `!w1 w2:A. w1 IN D /\ w2 IN D
        ==> (holds D E ((4 |-> w2) ((3 |-> w1) ((0 |-> d)
                        ((2 |-> g') ((1 |-> g) v)))))
                   (applyto_form 0 3 1) <=>
             eapply D E g d w1) /\
            (holds D E ((4 |-> w2) ((3 |-> w1) ((0 |-> d)
                        ((2 |-> g') ((1 |-> g) v)))))
                   (applyto_form 0 4 2) <=>
             eapply D E g' d w2)`
    ASSUME_TAC THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D ((4 |-> (w2:A)) ((3 |-> w1) ((0 |-> d)
                     ((2 |-> g') ((1 |-> g) v)))))`
      ASSUME_TAC THENL
       [SUBGOAL_THEN
         `valuation D ((3 |-> (w1:A)) ((0 |-> d)
                       ((2 |-> g') ((1 |-> g) v))))`
        ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w1:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC))) THEN
      MAP_EVERY EXISTS_TAC [`w1:A`; `w2:A`] THEN ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `w1:A` (X_CHOOSE_THEN `w2:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `w1:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `w2:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A. d IN D
        ==> ((E:A->A->bool) d s <=>
             E d c /\
             ?w1 w2:A. w1 IN D /\ w2 IN D /\
                       eapply D E g d w1 /\ eapply D E g' d w2 /\
                       ~(w1 = w2))`
  (LABEL_TAC "dis") THENL
   [X_GEN_TAC `d:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b s` ASSUME_TAC THENL
   [USE_THEN "dis" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(b:A) IN D`)]) THEN
    CONJ_TAC THENL [ASM_MESON_TAC[einter]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`y:A`; `y':A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `s:A` o MATCH_MP ZF_FOUNDATION_F) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `(E:A->A->bool) m c /\
    ?w w':A. w IN D /\ w' IN D /\
             eapply D E g m w /\ eapply D E g' m w' /\ ~(w = w')`
  MP_TAC THENL
   [USE_THEN "dis" (fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(m:A) IN D`))) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `(E:A->A->bool) m a /\ E m a'` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!d u u':A. d IN D /\ u IN D /\ u' IN D /\ E d m /\
               eapply D E g d u /\ eapply D E g' d u'
               ==> u = u'`
  (LABEL_TAC "agr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) d c` ASSUME_TAC THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    SUBGOAL_THEN `~((E:A->A->bool) d s)` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "dis" (fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(d:A) IN D`))) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `m:A`]
        ERESTRICT_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g':A`; `m:A`]
        ERESTRICT_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `r':A`) THEN
  SUBGOAL_THEN `(r:A) IN D /\ (r':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
       ==> ((E:A->A->bool) z r <=>
            E z g /\ ?u w. u IN D /\ w IN D /\ E u m /\ eopair D E u w z)`
  (LABEL_TAC "f1") THENL
   [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[erestrict]
      (ASSUME `erestrict D (E:A->A->bool) g m r`)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
       ==> ((E:A->A->bool) z r' <=>
            E z g' /\ ?u w. u IN D /\ w IN D /\ E u m /\ eopair D E u w z)`
  (LABEL_TAC "f2") THENL
   [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[erestrict]
      (ASSUME `erestrict D (E:A->A->bool) g' m r'`)));
    ALL_TAC] THEN
  SUBGOAL_THEN `!d:A. d IN D /\ (E:A->A->bool) d m ==> E d a /\ E d a'`
  (LABEL_TAC "dm") THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u a'
          ==> ?w2. w2 IN D /\ eapply D E g' u w2`
  (LABEL_TAC "dg2") THENL
   [MP_TAC(REWRITE_RULE[edomain]
      (MATCH_MP EATTEMPT_DOMAIN
        (ASSUME `eattempt D (E:A->A->bool) q v g' a'`))) THEN
    REWRITE_TAC[eindom] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u a
          ==> ?w2. w2 IN D /\ eapply D E g u w2`
  (LABEL_TAC "dg1") THENL
   [MP_TAC(REWRITE_RULE[edomain]
      (MATCH_MP EATTEMPT_DOMAIN
        (ASSUME `eattempt D (E:A->A->bool) q v g a`))) THEN
    REWRITE_TAC[eindom] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) = r'` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      USE_THEN "f1" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `u:A`
        (X_CHOOSE_THEN `w1:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g u w1` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u a'` ASSUME_TAC THENL
       [USE_THEN "dm" (fun th ->
          MP_TAC(MATCH_MP th (CONJ (ASSUME `(u:A) IN D`)
                                   (ASSUME `(E:A->A->bool) u m`)))) THEN
        SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `?w2:A. w2 IN D /\ eapply D (E:A->A->bool) g' u w2`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "dg2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `w1:A = w2` SUBST_ALL_TAC THENL
       [USE_THEN "agr" MATCH_MP_TAC THEN EXISTS_TAC `u:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z g'` ASSUME_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) g' u w2` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `z:A = z2` (fun th -> ASM_REWRITE_TAC[th]) THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w2:A`;
                      `z:A`; `z2:A`] EOPAIR_UNIQUE_F) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "f2" (fun th ->
        REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w2:A`] THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      USE_THEN "f2" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `u:A`
        (X_CHOOSE_THEN `w1:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g' u w1` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u a` ASSUME_TAC THENL
       [USE_THEN "dm" (fun th ->
          MP_TAC(MATCH_MP th (CONJ (ASSUME `(u:A) IN D`)
                                   (ASSUME `(E:A->A->bool) u m`)))) THEN
        SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `?w2:A. w2 IN D /\ eapply D (E:A->A->bool) g u w2`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "dg1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `w2:A = w1` SUBST_ALL_TAC THENL
       [USE_THEN "agr" MATCH_MP_TAC THEN EXISTS_TAC `u:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z g` ASSUME_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) g u w1` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `z:A = z2` (fun th -> ASM_REWRITE_TAC[th]) THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w1:A`;
                      `z:A`; `z2:A`] EOPAIR_UNIQUE_F) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "f1" (fun th ->
        REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w1:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `holds D E ((1 |-> (w:A)) ((0 |-> r') v)) q`
  ASSUME_TAC THENL
   [UNDISCH_TAC `eattempt D (E:A->A->bool) q v g a` THEN
    REWRITE_TAC[eattempt] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`m:A`; `r':A`; `w:A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `holds D E ((1 |-> (w':A)) ((0 |-> r') v)) q`
  ASSUME_TAC THENL
   [UNDISCH_TAC `eattempt D (E:A->A->bool) q v g' a'` THEN
    REWRITE_TAC[eattempt] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`m:A`; `r':A`; `w':A`]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  UNDISCH_TAC
   `!r w w'. r IN D /\ w IN D /\ w' IN D /\
             holds D (E:A->A->bool) ((1 |-> w) ((0 |-> r) v)) q /\
             holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w'` THEN
  DISCH_THEN(MP_TAC o SPECL [`r':A`; `w:A`; `w':A`]) THEN
  ASM_REWRITE_TAC[]);;

let EATTEMPT_AGREE = prove
 (`!D (E:A->A->bool) q v g a g' a' b y y'.
     model D E ZF_AX /\ valuation D v /\
     (!r w w'. r IN D /\ w IN D /\ w' IN D /\
               holds D E ((1 |-> w) ((0 |-> r) v)) q /\
               holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
     eordinal D E a /\ eordinal D E a' /\
     eattempt D E q v g a /\ eattempt D E q v g' a' /\
     b IN D /\ E b a /\ E b a' /\
     y IN D /\ y' IN D /\ eapply D E g b y /\ eapply D E g' b y'
     ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EATTEMPT_AGREE_F));;

(* ------------------------------------------------------------------------- *)
(* Attempts only depend on the ambient valuation through the free variables  *)
(* of the recursion data other than the distinguished 0 and 1.               *)
(* ------------------------------------------------------------------------- *)

let EATTEMPT_VALUATION = prove
 (`!D (E:A->A->bool) q v v' g a.
        (!m. m IN FV q /\ ~(m = 0) /\ ~(m = 1) ==> v m = v' m)
        ==> (eattempt D E q v g a <=> eattempt D E q v' g a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eattempt] THEN
  SUBGOAL_THEN
   `!r y:A. holds D E ((1 |-> y) ((0 |-> r) v)) q <=>
            holds D E ((1 |-> y) ((0 |-> r) v')) q`
  (fun th -> REWRITE_TAC[th]) THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC HOLDS_VALUATION THEN
  X_GEN_TAC `m:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN
  COND_CASES_TAC THEN REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MATCH_MP_TAC o check (is_forall o concl)) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Successor extension of attempts: if g is a q-attempt on the ordinal a     *)
(* and the recursion data is defined at g itself, then adjoining the single  *)
(* pair <a, y> (y a q-value of g) gives an attempt on the successor of a.    *)
(* The membership analysis repeatedly uses that a is not a member of         *)
(* itself and that the first components of pairs in g lie in a.              *)
(* ------------------------------------------------------------------------- *)

let EATTEMPT_SUC_F = prove
 (`!D (E:A->A->bool) q v g a t.
     model D E zfw_ax /\ valuation D v /\
     eordinal D E a /\ eattempt D E q v g a /\ esuc D E a t /\
     (?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> g) v)) q)
     ==> ?g'. eattempt D E q v g' t`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(g:A) IN D /\ (a:A) IN D /\ (t:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN; EORDINAL_IN; ESUC_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D ==> ((E:A->A->bool) u t <=> E u a \/ u = a)`
  (LABEL_TAC "tch") THENL
   [ASM_MESON_TAC[ESUC_ALT_F]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D ==> ((E:A->A->bool) u a <=> eindom D E g u)`
  (LABEL_TAC "gdom") THENL
   [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[edomain]
      (MATCH_MP EATTEMPT_DOMAIN
        (ASSUME `eattempt D (E:A->A->bool) q v g a`))));
    ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) g` (LABEL_TAC "gfun") THENL
   [ASM_MESON_TAC[EATTEMPT_FUN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `y:A`]
        EOPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z:A`]
        EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sz:A`) THEN
  SUBGOAL_THEN `(sz:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `sz:A`]
        EBUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `g':A`) THEN
  SUBGOAL_THEN `(g':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w g' <=> E w g \/ w = z)`
  (LABEL_TAC "gch") THENL
   [SUBGOAL_THEN
     `!w:A. w IN D ==> ((E:A->A->bool) w g' <=> E w g \/ E w sz)`
    ASSUME_TAC THENL [ASM_MESON_TAC[EBUNION_ALT_F]; ALL_TAC] THEN
    ASM_MESON_TAC[epair];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z':A. z' IN D /\ (E:A->A->bool) z' g
           ==> ?u w. u IN D /\ w IN D /\ eopair D E u w z' /\ E u a`
  (LABEL_TAC "gpair") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(MATCH_MP (CONJUNCT1(CONJUNCT2(REWRITE_RULE[eisfun]
      (ASSUME `eisfun D (E:A->A->bool) g`))))
      (CONJ (ASSUME `(z':A) IN D`) (ASSUME `(E:A->A->bool) z' g`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "gdom" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(u:A) IN D`)]) THEN
    REWRITE_TAC[eindom; eapply] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) a a)` (LABEL_TAC "nota") THENL
   [ASM_MESON_TAC[E_IRREFL_F]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u a ==> ~(u = a)`
  (LABEL_TAC "nself") THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w w' z1 z2:A.
        u IN D /\ w IN D /\ w' IN D /\
        eopair D (E:A->A->bool) u w z1 /\ E z1 g /\
        eopair D E u w' z2 /\ E z2 g
        ==> w = w'`
  (LABEL_TAC "gfunc") THENL
   [ACCEPT_TAC(CONJUNCT2(CONJUNCT2(REWRITE_RULE[eisfun]
      (ASSUME `eisfun D (E:A->A->bool) g`))));
    ALL_TAC] THEN
  EXISTS_TAC `g':A` THEN REWRITE_TAC[eattempt] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z':A` THEN STRIP_TAC THEN
      USE_THEN "gch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z':A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN DISJ_CASES_TAC THENL
       [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
      MAP_EVERY X_GEN_TAC [`u:A`; `w1:A`; `w2:A`; `z1:A`; `z2:A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(z1:A) IN D /\ (z2:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z1:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN DISJ_CASES_TAC THEN
      USE_THEN "gch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z2:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN DISJ_CASES_TAC THENL
       [ASM_MESON_TAC[];
        SUBGOAL_THEN `u:A = a /\ w2:A = y` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
        ASM_MESON_TAC[EOPAIR_INJ_F];
        SUBGOAL_THEN `u:A = a /\ w1:A = y` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
        ASM_MESON_TAC[EOPAIR_INJ_F];
        ASM_MESON_TAC[EOPAIR_INJ_F]]];
    REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    USE_THEN "tch" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(u:A) IN D`)]) THEN
    EQ_TAC THENL
     [DISCH_THEN DISJ_CASES_TAC THENL
       [USE_THEN "gdom" (fun th ->
          MP_TAC(MATCH_MP th (ASSUME `(u:A) IN D`))) THEN
        ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom; eapply] THEN
        ASM_MESON_TAC[EOPAIR_IN];
        REWRITE_TAC[eindom; eapply] THEN ASM_MESON_TAC[]];
      REWRITE_TAC[eindom; eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `z':A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z':A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN DISJ_CASES_TAC THENL
       [DISJ1_TAC THEN
        USE_THEN "gdom" (fun th ->
          REWRITE_TAC[MATCH_MP th (ASSUME `(u:A) IN D`)]) THEN
        REWRITE_TAC[eindom; eapply] THEN ASM_MESON_TAC[];
        DISJ2_TAC THEN ASM_MESON_TAC[EOPAIR_INJ_F]]];
    MAP_EVERY X_GEN_TAC [`b:A`; `r:A`; `y3:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) b a \/ b:A = a` DISJ_CASES_TAC THENL
     [USE_THEN "tch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(b:A) IN D`))) THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `eapply D (E:A->A->bool) g b y3` ASSUME_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) g' b y3` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z':A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) z' g \/ z':A = z`
        DISJ_CASES_TAC THENL
         [ASM_MESON_TAC[];
          ASM_REWRITE_TAC[];
          ASM_MESON_TAC[EOPAIR_INJ_F]];
        ALL_TAC] THEN
      SUBGOAL_THEN `erestrict D (E:A->A->bool) g b r` ASSUME_TAC THENL
       [REWRITE_TAC[erestrict] THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN
        MP_TAC(SPEC `w:A` (CONJUNCT2(REWRITE_RULE[erestrict]
          (ASSUME `erestrict D (E:A->A->bool) g' b r`)))) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        SUBGOAL_THEN `(E:A->A->bool) w g' <=> E w g \/ w = z`
        ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        EQ_TAC THEN STRIP_TAC THENL
         [SUBGOAL_THEN `(E:A->A->bool) w g` ASSUME_TAC THENL
           [ASM_MESON_TAC[EOPAIR_INJ_F; E_NOCYCLE2_F]; ALL_TAC] THEN
          ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
          ASM_MESON_TAC[]];
        ALL_TAC] THEN
      UNDISCH_TAC `eattempt D (E:A->A->bool) q v g a` THEN
      REWRITE_TAC[eattempt] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPECL [`b:A`; `r:A`; `y3:A`]) THEN
      ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(fun th ->
        if is_eq(concl th) then SUBST_ALL_TAC th else NO_TAC) THEN
      SUBGOAL_THEN `y3:A = y` SUBST_ALL_TAC THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) g' a y3` THEN
        REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z':A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) z' g \/ z':A = z`
        DISJ_CASES_TAC THENL
         [ASM_MESON_TAC[];
          ASM_MESON_TAC[EOPAIR_INJ_F];
          ASM_MESON_TAC[EOPAIR_INJ_F]];
        ALL_TAC] THEN
      SUBGOAL_THEN `r:A = g` SUBST_ALL_TAC THENL
       [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
        ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
        MP_TAC(SPEC `w:A` (CONJUNCT2(REWRITE_RULE[erestrict]
          (ASSUME `erestrict D (E:A->A->bool) g' a r`)))) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        SUBGOAL_THEN `(E:A->A->bool) w g' <=> E w g \/ w = z`
        ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        EQ_TAC THENL
         [STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_INJ_F];
          DISCH_TAC THEN ASM_MESON_TAC[]];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[]]]);;

let EATTEMPT_SUC = prove
 (`!D (E:A->A->bool) q v g a t.
     model D E ZF_AX /\ valuation D v /\
     eordinal D E a /\ eattempt D E q v g a /\ esuc D E a t /\
     (?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> g) v)) q)
     ==> ?g'. eattempt D E q v g' t`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EATTEMPT_SUC_F));;

(* ------------------------------------------------------------------------- *)
(* The replacement-step formula for the recursion theorem: z is the pair     *)
(* <u, y> where some attempt on an ordinal containing u sends u to y. Its    *)
(* characterization is the largest formula-to-semantics conversion so far,   *)
(* combining ordinal_form, attempt_form, applyto_form and opair_form at a    *)
(* five-deep valuation pile.                                                 *)
(* ------------------------------------------------------------------------- *)

let HOLDS_RECSTEP_FORM = prove
 (`!D (E:A->A->bool) v q N u w.
      valuation D v /\ 1 < N /\ (!m. m IN FV q ==> m < N) /\
      u IN D /\ w IN D
      ==> (holds D E (((N + 1) |-> w) ((N |-> u) v)) (recstep_form q N) <=>
           ?t g y. t IN D /\ g IN D /\ y IN D /\
                   eordinal D E t /\ eattempt D E q v g t /\
                   E u t /\ eapply D E g u y /\ eopair D E u y w)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!m:num. m IN FV q
        ==> ~(m = N) /\ ~(m = N + 1) /\ ~(m = N + 2) /\
            ~(m = N + 3) /\ ~(m = N + 4)`
  (LABEL_TAC "fvq") THENL
   [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN `m:num < N` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t g y:A. t IN D /\ g IN D /\ y IN D
        ==> valuation D
             (((N + 4) |-> y) (((N + 3) |-> g) (((N + 2) |-> t)
              (((N + 1) |-> w) ((N |-> u) v)))))`
  (LABEL_TAC "wval") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((N + 2) |-> (t:A)) (((N + 1) |-> w) ((N |-> u) v)))`
    ASSUME_TAC THENL
     [SUBGOAL_THEN `valuation D (((N + 1) |-> (w:A)) ((N |-> u) v))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t g y:A. t IN D /\ g IN D /\ y IN D
      ==> (holds D E (((N + 4) |-> y) (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> w) ((N |-> u) v)))))
                 (ordinal_form (N + 2)) <=> eordinal D E t) /\
          (holds D E (((N + 4) |-> y) (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> w) ((N |-> u) v)))))
                 (attempt_form q (N + 3) (N + 2) (N + 5)) <=>
           eattempt D E q v g t) /\
          (holds D E (((N + 4) |-> y) (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> w) ((N |-> u) v)))))
                 (applyto_form N (N + 4) (N + 3)) <=>
           eapply D E g u y) /\
          (holds D E (((N + 4) |-> y) (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> w) ((N |-> u) v)))))
                 (opair_form N (N + 4) (N + 1)) <=>
           eopair D E u y w)`
  (LABEL_TAC "mac") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((N + 4) |-> (y:A)) (((N + 3) |-> g) (((N + 2) |-> t)
                   (((N + 1) |-> w) ((N |-> u) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N + 2 = N + 3) /\ ~(N + 2 = N + 4)`];
      MP_TAC(SPECL
       [`D:A->bool`; `E:A->A->bool`;
        `((N + 4) |-> (y:A)) (((N + 3) |-> g) (((N + 2) |-> t)
         (((N + 1) |-> w) ((N |-> u) v))))`;
        `q:form`; `N + 3`; `N + 2`; `N + 5`] HOLDS_ATTEMPT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
        TRY ARITH_TAC THEN
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        SUBGOAL_THEN `m:num < N` MP_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ARITH_TAC;
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N + 3 = N + 4) /\ ~(N + 2 = N + 3) /\ ~(N + 2 = N + 4)`] THEN
      MATCH_MP_TAC EATTEMPT_VALUATION THEN
      X_GEN_TAC `m:num` THEN STRIP_TAC THEN
      USE_THEN "fvq" (fun th -> MP_TAC(MATCH_MP th
        (ASSUME `(m:num) IN FV q`))) THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[VALMOD];
      ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N = N + 1) /\ ~(N = N + 2) /\ ~(N = N + 3) /\ ~(N = N + 4) /\
        ~(N + 3 = N + 4)`];
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N = N + 1) /\ ~(N = N + 2) /\ ~(N = N + 3) /\ ~(N = N + 4) /\
        ~(N + 1 = N + 2) /\ ~(N + 1 = N + 3) /\ ~(N + 1 = N + 4)`]];
    ALL_TAC] THEN
  REWRITE_TAC[recstep_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
   `~(N = N + 1) /\ ~(N = N + 2) /\ ~(N = N + 3) /\ ~(N = N + 4) /\
    ~(N + 2 = N + 3) /\ ~(N + 2 = N + 4)`] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `t:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `g:A`; `y:A`] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "mac" (fun th ->
      MP_TAC(SPECL [`t:A`; `g:A`; `y:A`] th)) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
      (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "mac" (fun th ->
      MP_TAC(SPECL [`t:A`; `g:A`; `y:A`] th)) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Existence of attempts on every ordinal: the transfinite recursion         *)
(* theorem's existence half. The induction is EORDINAL_INDUCT with the       *)
(* formula ?? (N+1) (attempt_form q (N+1) N (N+2)); the step collects, by    *)
(* the replacement scheme applied to recstep_form, the set of pairs <b, y>   *)
(* over b in a where the (unique by EATTEMPT_AGREE) attempt value at b is    *)
(* y, totality coming from the induction hypothesis extended one step by     *)
(* EATTEMPT_SUC; the collected set is itself an attempt on a.                *)
(* ------------------------------------------------------------------------- *)

let EATTEMPT_EXISTS_GEN = prove
 (`!D (E:A->A->bool) ax q v N n.
    model D E ax /\ zfw_ax SUBSET ax /\ engine_ready ax q N n /\
    valuation D v /\
    (!r w w'. r IN D /\ w IN D /\ w' IN D /\
              holds D E ((1 |-> w) ((0 |-> r) v)) q /\
              holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
    (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q)
    ==> !a. eordinal D E a ==> ?g. eattempt D E q v g a`,
  REPEAT GEN_TAC THEN REWRITE_TAC[engine_ready] THEN STRIP_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) zfw_ax` ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((N |-> a) v)
                 (?? (N + 1) (attempt_form q (N + 1) N (N + 2))) <=>
           ?g. g IN D /\ eattempt D E q v g a)`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    SUBGOAL_THEN
     `!g:A. g IN D
        ==> (holds D E (((N + 1) |-> g) ((N |-> a) v))
                   (attempt_form q (N + 1) N (N + 2)) <=>
             eattempt D E q v g a)`
    (fun th -> ASM_MESON_TAC[th]) THEN
    X_GEN_TAC `g:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((N + 1) |-> (g:A)) ((N |-> a) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL
     [`D:A->bool`; `E:A->A->bool`;
      `((N + 1) |-> (g:A)) ((N |-> a) v)`;
      `q:form`; `N + 1`; `N:num`; `N + 2`] HOLDS_ATTEMPT_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
      TRY ARITH_TAC THEN
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `m:num < N` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(N = N + 1)`] THEN
    MATCH_MP_TAC EATTEMPT_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    SUBGOAL_THEN `m:num < N` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `~(m:num = N) /\ ~(m = N + 1)` STRIP_ASSUME_TAC THENL
     [POP_ASSUM MP_TAC THEN ARITH_TAC; ALL_TAC] THEN
    ASM_REWRITE_TAC[VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. eordinal D E a
          ==> holds D E ((N |-> a) v)
                    (?? (N + 1) (attempt_form q (N + 1) N (N + 2)))`
  MP_TAC THENL
   [MATCH_MP_TAC EORDINAL_INDUCT_GEN THEN
    MAP_EVERY EXISTS_TAC [`ax:form->bool`; `n:num`] THEN
    ASM_REWRITE_TAC[omega_ready] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!b:A. b IN D /\ (E:A->A->bool) b a
            ==> ?g. g IN D /\ eattempt D E q v g b`
    (LABEL_TAC "IH") THENL
     [REPEAT STRIP_TAC THEN
      USE_THEN "pch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(b:A) IN D`))) THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b:A. b IN D /\ (E:A->A->bool) b a
            ==> ?t g. t IN D /\ g IN D /\ eordinal D E t /\ E b t /\
                      eattempt D E q v g t`
    (LABEL_TAC "sIH") THENL
     [REPEAT STRIP_TAC THEN
      USE_THEN "IH" (fun th ->
        MP_TAC(MATCH_MP th (CONJ (ASSUME `(b:A) IN D`)
                                 (ASSUME `(E:A->A->bool) b a`)))) THEN
      DISCH_THEN(X_CHOOSE_THEN `g0:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER_F]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`] ESUC_EXISTS_F) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `t:A`) THEN
      SUBGOAL_THEN
       `(t:A) IN D /\ eordinal D (E:A->A->bool) t /\ E b t`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC_F; ESUC_MEMBER_F]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                    `g0:A`; `b:A`; `t:A`] EATTEMPT_SUC_F) THEN
      ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
       [ASM_MESON_TAC[EISFUN_IN; EATTEMPT_FUN]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
      MAP_EVERY EXISTS_TAC [`t:A`; `g:A`] THEN
      ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN];
      ALL_TAC] THEN
    MP_TAC(SPECL
      [`D:A->bool`; `E:A->A->bool`; `ax:form->bool`; `recstep_form q N`;
       `N:num`; `N + 1`; `n:num`; `v:num->A`; `a:A`] ZFG_REPLACEMENT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC; ALL_TAC] THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      USE_THEN "sIH" (fun th ->
        MP_TAC(MATCH_MP th (CONJ (ASSUME `(u:A) IN D`)
                                 (ASSUME `(E:A->A->bool) u a`)))) THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `?y:A. y IN D /\ eapply D (E:A->A->bool) g u y`
      STRIP_ASSUME_TAC THENL
       [MP_TAC(CONJUNCT2(REWRITE_RULE[edomain]
          (MATCH_MP EATTEMPT_DOMAIN
            (ASSUME `eattempt D (E:A->A->bool) q v g t`)))) THEN
        DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[] THEN
        REWRITE_TAC[eindom] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `y:A`]
            EOPAIR_EXISTS_F) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
      SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `q:form`;
                    `N:num`; `u:A`; `w':A`] HOLDS_RECSTEP_FORM) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `g':A`
        (X_CHOOSE_THEN `y':A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `y':A = y` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                      `g':A`; `t':A`; `g:A`; `t:A`; `u:A`; `y':A`; `y:A`]
              EATTEMPT_AGREE_F) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE_F];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `B:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `!w:A. w IN D
         ==> ((E:A->A->bool) w B <=>
              ?u. u IN D /\ E u a /\
                  ?t g y. t IN D /\ g IN D /\ y IN D /\
                          eordinal D E t /\ eattempt D E q v g t /\
                          E u t /\ eapply D E g u y /\ eopair D E u y w)`
    (LABEL_TAC "Bch") THENL
     [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
      FIRST_X_ASSUM(fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`)) THEN
        ASSUME_TAC th) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EQ_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `q:form`;
                      `N:num`; `u:A`; `w:A`] HOLDS_RECSTEP_FORM) THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `q:form`;
                      `N:num`; `u:A`; `w:A`] HOLDS_RECSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_MESON_TAC[]];
      ALL_TAC] THEN
    UNDISCH_TAC
     `!w:A. w IN D
          ==> ((E:A->A->bool) w B <=>
               ?u. u IN D /\ E u a /\
                   holds D E (((N + 1) |-> w) ((N |-> u) v))
                         (recstep_form q N))` THEN
    DISCH_THEN(K ALL_TAC) THEN
    USE_THEN "pch" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(a:A) IN D`)]) THEN
    EXISTS_TAC `B:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eattempt] THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
        USE_THEN "Bch" (fun th ->
          MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
        ASM_MESON_TAC[];
        MAP_EVERY X_GEN_TAC [`u:A`; `w1:A`; `w2:A`; `z1:A`; `z2:A`] THEN
        STRIP_TAC THEN
        SUBGOAL_THEN `(z1:A) IN D /\ (z2:A) IN D` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        USE_THEN "Bch" (fun th ->
          MP_TAC(MATCH_MP th (ASSUME `(z1:A) IN D`))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `u1:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t1:A`
            (X_CHOOSE_THEN `g1:A` (X_CHOOSE_THEN `y1:A`
              STRIP_ASSUME_TAC)))))) THEN
        USE_THEN "Bch" (fun th ->
          MP_TAC(MATCH_MP th (ASSUME `(z2:A) IN D`))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `u2:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t2:A`
            (X_CHOOSE_THEN `g2:A` (X_CHOOSE_THEN `y2:A`
              STRIP_ASSUME_TAC)))))) THEN
        SUBGOAL_THEN `u1:A = u /\ y1:A = w1` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
        SUBGOAL_THEN `u2:A = u /\ y2:A = w2` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                      `g1:A`; `t1:A`; `g2:A`; `t2:A`; `u:A`; `w1:A`;
                      `w2:A`] EATTEMPT_AGREE_F) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
        ASM_MESON_TAC[]];
      REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
       [DISCH_TAC THEN
        USE_THEN "sIH" (fun th ->
          MP_TAC(MATCH_MP th (CONJ (ASSUME `(u:A) IN D`)
                                   (ASSUME `(E:A->A->bool) u a`)))) THEN
        DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
          STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `?y:A. y IN D /\ eapply D (E:A->A->bool) g u y`
        STRIP_ASSUME_TAC THENL
         [MP_TAC(CONJUNCT2(REWRITE_RULE[edomain]
            (MATCH_MP EATTEMPT_DOMAIN
              (ASSUME `eattempt D (E:A->A->bool) q v g t`)))) THEN
          DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[] THEN
          REWRITE_TAC[eindom] THEN DISCH_THEN ACCEPT_TAC;
          ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `y:A`]
              EOPAIR_EXISTS_F) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
        SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) w B` ASSUME_TAC THENL
         [USE_THEN "Bch" (fun th ->
            REWRITE_TAC[MATCH_MP th (ASSUME `(w:A) IN D`)]) THEN
          ASM_MESON_TAC[];
          ALL_TAC] THEN
        REWRITE_TAC[eindom; eapply] THEN ASM_MESON_TAC[];
        REWRITE_TAC[eindom; eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        USE_THEN "Bch" (fun th ->
          MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `u1:A` STRIP_ASSUME_TAC) THEN
        ASM_MESON_TAC[EOPAIR_INJ_F]];
      MAP_EVERY X_GEN_TAC [`b:A`; `r:A`; `yv:A`] THEN STRIP_TAC THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) B b yv` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "Bch" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `u1:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t:A`
          (X_CHOOSE_THEN `g:A` (X_CHOOSE_THEN `y1:A`
            STRIP_ASSUME_TAC)))))) THEN
      SUBGOAL_THEN `u1:A = b /\ y1:A = yv` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
      SUBGOAL_THEN `(g:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!x:A. x IN D ==> ((E:A->A->bool) x t <=> eindom D E g x)`
      (LABEL_TAC "gdm") THENL
       [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[edomain]
          (MATCH_MP EATTEMPT_DOMAIN
            (ASSUME `eattempt D (E:A->A->bool) q v g t`))));
        ALL_TAC] THEN
      SUBGOAL_THEN `!d:A. d IN D /\ (E:A->A->bool) d b ==> E d t`
      (LABEL_TAC "bt") THENL
       [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
      SUBGOAL_THEN `!d:A. d IN D /\ (E:A->A->bool) d b ==> E d a`
      (LABEL_TAC "ba") THENL
       [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `b:A`]
            ERESTRICT_EXISTS_F) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `rg:A`) THEN
      SUBGOAL_THEN `(rg:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D
           ==> ((E:A->A->bool) w r <=>
                E w B /\ ?u w2. u IN D /\ w2 IN D /\ E u b /\
                                eopair D E u w2 w)`
      (LABEL_TAC "fr") THENL
       [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[erestrict]
          (ASSUME `erestrict D (E:A->A->bool) B b r`)));
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D
           ==> ((E:A->A->bool) w rg <=>
                E w g /\ ?u w2. u IN D /\ w2 IN D /\ E u b /\
                                eopair D E u w2 w)`
      (LABEL_TAC "fg") THENL
       [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[erestrict]
          (ASSUME `erestrict D (E:A->A->bool) g b rg`)));
        ALL_TAC] THEN
      UNDISCH_TAC `u1:A = b` THEN DISCH_THEN SUBST_ALL_TAC THEN
      UNDISCH_TAC `y1:A = yv` THEN DISCH_THEN SUBST_ALL_TAC THEN
      SUBGOAL_THEN `r:A = rg` SUBST_ALL_TAC THENL
       [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
        ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
        USE_THEN "fr" (fun th ->
          REWRITE_TAC[MATCH_MP th (ASSUME `(w:A) IN D`)]) THEN
        USE_THEN "fg" (fun th ->
          REWRITE_TAC[MATCH_MP th (ASSUME `(w:A) IN D`)]) THEN
        EQ_TAC THEN STRIP_TAC THENL
         [SUBGOAL_THEN `(E:A->A->bool) w g` ASSUME_TAC THENL
           [USE_THEN "Bch" (fun th ->
              MP_TAC(MATCH_MP th (ASSUME `(w:A) IN D`))) THEN
            ASM_REWRITE_TAC[] THEN
            DISCH_THEN(X_CHOOSE_THEN `u3:A` (CONJUNCTS_THEN2 ASSUME_TAC
              (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t3:A`
                (X_CHOOSE_THEN `g3:A` (X_CHOOSE_THEN `y3:A`
                  STRIP_ASSUME_TAC)))))) THEN
            SUBGOAL_THEN `u3:A = u /\ y3:A = w2` STRIP_ASSUME_TAC THENL
             [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
            SUBGOAL_THEN `(E:A->A->bool) u t` ASSUME_TAC THENL
             [ASM_MESON_TAC[]; ALL_TAC] THEN
            SUBGOAL_THEN
             `?y4:A. y4 IN D /\ eapply D (E:A->A->bool) g u y4`
            STRIP_ASSUME_TAC THENL
             [USE_THEN "gdm" (fun th ->
                MP_TAC(MATCH_MP th (ASSUME `(u:A) IN D`))) THEN
              ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
              DISCH_THEN ACCEPT_TAC;
              ALL_TAC] THEN
            SUBGOAL_THEN `w2:A = y4` SUBST_ALL_TAC THENL
             [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`;
                            `v:num->A`; `g3:A`; `t3:A`; `g:A`; `t:A`;
                            `u:A`; `w2:A`; `y4:A`] EATTEMPT_AGREE_F) THEN
              ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
              ASM_MESON_TAC[];
              ALL_TAC] THEN
            UNDISCH_TAC `eapply D (E:A->A->bool) g u y4` THEN
            REWRITE_TAC[eapply] THEN
            DISCH_THEN(X_CHOOSE_THEN `z4:A` STRIP_ASSUME_TAC) THEN
            SUBGOAL_THEN `w:A = z4` (fun th -> ASM_REWRITE_TAC[th]) THEN
            MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `y4:A`;
                          `w:A`; `z4:A`] EOPAIR_UNIQUE_F) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
          SUBGOAL_THEN `(E:A->A->bool) w B` ASSUME_TAC THENL
           [USE_THEN "Bch" (fun th ->
              REWRITE_TAC[MATCH_MP th (ASSUME `(w:A) IN D`)]) THEN
            EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
            SUBGOAL_THEN `(E:A->A->bool) u a` ASSUME_TAC THENL
             [ASM_MESON_TAC[]; ALL_TAC] THEN
            ASM_REWRITE_TAC[] THEN
            MAP_EVERY EXISTS_TAC [`t:A`; `g:A`; `w2:A`] THEN
            ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
             [ASM_MESON_TAC[]; ALL_TAC] THEN
            REWRITE_TAC[eapply] THEN EXISTS_TAC `w:A` THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
        ALL_TAC] THEN
      UNDISCH_TAC `eattempt D (E:A->A->bool) q v g t` THEN
      REWRITE_TAC[eattempt] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPECL [`b:A`; `rg:A`; `yv:A`]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_TAC THEN X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  USE_THEN "pch" (fun th ->
    MP_TAC(MATCH_MP th (ASSUME `(a:A) IN D`))) THEN
  ASM_MESON_TAC[]);;

let EATTEMPT_EXISTS_F = prove
 (`!D (E:A->A->bool) q v N n.
    model D E zfw_ax /\ engine_ready zfw_ax q N n /\ valuation D v /\
    (!r w w'. r IN D /\ w IN D /\ w' IN D /\
              holds D E ((1 |-> w) ((0 |-> r) v)) q /\
              holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
    (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q)
    ==> !a. eordinal D E a ==> ?g. eattempt D E q v g a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EATTEMPT_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`zfw_ax`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let EATTEMPT_EXISTS = prove
 (`!D (E:A->A->bool) q v N.
    model D E ZF_AX /\ valuation D v /\
    (!m. m IN FV q ==> m < N) /\ 1 < N /\
    (!r w w'. r IN D /\ w IN D /\ w' IN D /\
              holds D E ((1 |-> w) ((0 |-> r) v)) q /\
              holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
    (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q)
    ==> !a. eordinal D E a ==> ?g. eattempt D E q v g a`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`q:form`; `N:num`] ENGINE_READY_ZF) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `n:num`) THEN
  MATCH_MP_TAC EATTEMPT_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`ZF_AX`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[ZFW_SUBSET_ZFAX]);;

(* ------------------------------------------------------------------------- *)
(* The transfinite recursion theorem, packaged. The recursively defined      *)
(* class relation erec q v a y holds when some attempt on an ordinal         *)
(* containing a sends a to y; erecres q v a r says r is the set              *)
(* {<b, F(b)> | b in a}. For functional (and, for existence, total)          *)
(* recursion data these have all the expected properties, and the relation   *)
(* is itself definable by the object formula rec_form.                       *)
(* ------------------------------------------------------------------------- *)

let erec = new_definition
  `erec D (E:A->A->bool) q v a y <=>
        ?t g. t IN D /\ g IN D /\ eordinal D E t /\ E a t /\
              eattempt D E q v g t /\ eapply D E g a y`;;

let erecres = new_definition
  `erecres D (E:A->A->bool) q v a r <=>
        r IN D /\
        !w. w IN D
            ==> (E w r <=>
                 ?b y. b IN D /\ y IN D /\ E b a /\ erec D E q v b y /\
                       eopair D E b y w)`;;

let EREC_UNIQUE_F = prove
 (`!D (E:A->A->bool) q v a y y'.
        model D E zfw_ax /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        a IN D /\ y IN D /\ y' IN D /\
        erec D E q v a y /\ erec D E q v a y'
        ==> y = y'`,
  REWRITE_TAC[erec] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                `g:A`; `t:A`; `g':A`; `t':A`; `a:A`; `y:A`; `y':A`]
        EATTEMPT_AGREE_F) THEN
  ASM_REWRITE_TAC[]);;

let EREC_UNIQUE = prove
 (`!D (E:A->A->bool) q v a y y'.
        model D E ZF_AX /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        a IN D /\ y IN D /\ y' IN D /\
        erec D E q v a y /\ erec D E q v a y'
        ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EREC_UNIQUE_F));;

let ERECRES_UNIQUE_F = prove
 (`!D (E:A->A->bool) q v a r r'.
        model D E zfw_ax /\ erecres D E q v a r /\ erecres D E q v a r'
        ==> r = r'`,
  REWRITE_TAC[erecres] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let ERECRES_UNIQUE = prove
 (`!D (E:A->A->bool) q v a r r'.
        model D E ZF_AX /\ erecres D E q v a r /\ erecres D E q v a r'
        ==> r = r'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ERECRES_UNIQUE_F));;

let EREC_ATTEMPT_RESTRICT_F = prove
 (`!D (E:A->A->bool) q v a t g rg.
     model D E zfw_ax /\ valuation D v /\
     (!r w w'. r IN D /\ w IN D /\ w' IN D /\
               holds D E ((1 |-> w) ((0 |-> r) v)) q /\
               holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
     a IN D /\ eordinal D E t /\ E a t /\
     eattempt D E q v g t /\ erestrict D E g a rg
     ==> erecres D E q v a rg`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(g:A) IN D /\ (t:A) IN D /\ (rg:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN; EORDINAL_IN; erestrict];
    ALL_TAC] THEN
  SUBGOAL_THEN `!d:A. d IN D /\ (E:A->A->bool) d a ==> E d t`
  (LABEL_TAC "at") THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x:A. x IN D ==> ((E:A->A->bool) x t <=> eindom D E g x)`
  (LABEL_TAC "gdm") THENL
   [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[edomain]
      (MATCH_MP EATTEMPT_DOMAIN
        (ASSUME `eattempt D (E:A->A->bool) q v g t`))));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D
       ==> ((E:A->A->bool) w rg <=>
            E w g /\ ?u w2. u IN D /\ w2 IN D /\ E u a /\
                            eopair D E u w2 w)`
  (LABEL_TAC "fg") THENL
   [ACCEPT_TAC(CONJUNCT2(REWRITE_RULE[erestrict]
      (ASSUME `erestrict D (E:A->A->bool) g a rg`)));
    ALL_TAC] THEN
  REWRITE_TAC[erecres] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "fg" (fun th ->
    REWRITE_TAC[MATCH_MP th (ASSUME `(w:A) IN D`)]) THEN
  EQ_TAC THEN STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`u:A`; `w2:A`] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[erec] THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `g:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN `(E:A->A->bool) b t` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?y3:A. y3 IN D /\ eapply D (E:A->A->bool) g b y3`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "gdm" (fun th ->
        MP_TAC(MATCH_MP th (ASSUME `(b:A) IN D`))) THEN
      ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `y:A = y3` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                    `b:A`; `y:A`; `y3:A`] EREC_UNIQUE_F) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
      REWRITE_TAC[erec] THEN
      MAP_EVERY EXISTS_TAC [`t:A`; `g:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    UNDISCH_TAC `eapply D (E:A->A->bool) g b y3` THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `z3:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `w:A = z3` (fun th -> ASM_REWRITE_TAC[th]) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `y3:A`;
                    `w:A`; `z3:A`] EOPAIR_UNIQUE_F) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

let EREC_ATTEMPT_RESTRICT = prove
 (`!D (E:A->A->bool) q v a t g rg.
     model D E ZF_AX /\ valuation D v /\
     (!r w w'. r IN D /\ w IN D /\ w' IN D /\
               holds D E ((1 |-> w) ((0 |-> r) v)) q /\
               holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
     a IN D /\ eordinal D E t /\ E a t /\
     eattempt D E q v g t /\ erestrict D E g a rg
     ==> erecres D E q v a rg`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EREC_ATTEMPT_RESTRICT_F));;

let EREC_EXISTS_GEN = prove
 (`!D (E:A->A->bool) ax q v a N n.
        model D E ax /\ zfw_ax SUBSET ax /\ engine_ready ax q N n /\
        valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?y. y IN D /\ erec D E q v a y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) zfw_ax` ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ax:form->bool`; `q:form`;
                `v:num->A`; `N:num`; `n:num`] EATTEMPT_EXISTS_GEN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ESUC_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `t:A`) THEN
  SUBGOAL_THEN
   `(t:A) IN D /\ eordinal D (E:A->A->bool) t /\ E a t`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC_F; ESUC_MEMBER_F]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `t:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
  SUBGOAL_THEN `?y:A. y IN D /\ eapply D (E:A->A->bool) g a y`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(CONJUNCT2(REWRITE_RULE[edomain]
      (MATCH_MP EATTEMPT_DOMAIN
        (ASSUME `eattempt D (E:A->A->bool) q v g t`)))) THEN
    DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eindom] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[erec] THEN
  MAP_EVERY EXISTS_TAC [`t:A`; `g:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EATTEMPT_FUN; EISFUN_IN]);;

let EREC_EXISTS_F = prove
 (`!D (E:A->A->bool) q v a N n.
        model D E zfw_ax /\ engine_ready zfw_ax q N n /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?y. y IN D /\ erec D E q v a y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC EREC_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`zfw_ax`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let EREC_EXISTS = prove
 (`!D (E:A->A->bool) q v a.
        model D E ZF_AX /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?y. y IN D /\ erec D E q v a y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  X_CHOOSE_THEN `N:num` (X_CHOOSE_TAC `n:num`)
    (SPEC `q:form` ENGINE_READY_ZF_EXISTS) THEN
  MATCH_MP_TAC EREC_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`ZF_AX`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[ZFW_SUBSET_ZFAX]);;

let ERECRES_EXISTS_GEN = prove
 (`!D (E:A->A->bool) ax q v a N n.
        model D E ax /\ zfw_ax SUBSET ax /\ engine_ready ax q N n /\
        valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?r. erecres D E q v a r`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model D (E:A->A->bool) zfw_ax` ASSUME_TAC THENL
   [ASM_MESON_TAC[MODEL_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. y IN D /\ erec D E q v a y` STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC EREC_EXISTS_GEN THEN
    MAP_EVERY EXISTS_TAC [`ax:form->bool`; `N:num`; `n:num`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [erec] o
    check (fun th -> can (find_term
      (fun t -> t =
       `erec:(A->bool)->(A->A->bool)->form->(num->A)->A->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `a:A`]
        ERESTRICT_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `rg:A`) THEN
  EXISTS_TAC `rg:A` THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                `a:A`; `t:A`; `g:A`; `rg:A`] EREC_ATTEMPT_RESTRICT_F) THEN
  ASM_REWRITE_TAC[]);;

let ERECRES_EXISTS_F = prove
 (`!D (E:A->A->bool) q v a N n.
        model D E zfw_ax /\ engine_ready zfw_ax q N n /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?r. erecres D E q v a r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN MATCH_MP_TAC ERECRES_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`zfw_ax`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[SUBSET_REFL]);;

let ERECRES_EXISTS = prove
 (`!D (E:A->A->bool) q v a.
        model D E ZF_AX /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        (!x. x IN D ==> ?y. y IN D /\ holds D E ((1 |-> y) ((0 |-> x) v)) q) /\
        eordinal D E a
        ==> ?r. erecres D E q v a r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  X_CHOOSE_THEN `N:num` (X_CHOOSE_TAC `n:num`)
    (SPEC `q:form` ENGINE_READY_ZF_EXISTS) THEN
  MATCH_MP_TAC ERECRES_EXISTS_GEN THEN
  MAP_EVERY EXISTS_TAC [`ZF_AX`; `N:num`; `n:num`] THEN
  ASM_REWRITE_TAC[ZFW_SUBSET_ZFAX]);;

let EREC_EQUATION_F = prove
 (`!D (E:A->A->bool) q v a y r.
        model D E zfw_ax /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        eordinal D E a /\ y IN D /\
        erec D E q v a y /\ erecres D E q v a r
        ==> holds D E ((1 |-> y) ((0 |-> r) v)) q`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [erec] o
    check (fun th -> can (find_term
      (fun t -> t =
       `erec:(A->bool)->(A->A->bool)->form->(num->A)->A->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `a:A`]
        ERESTRICT_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `rg:A`) THEN
  SUBGOAL_THEN `erecres D (E:A->A->bool) q v a rg` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                  `a:A`; `t:A`; `g:A`; `rg:A`] EREC_ATTEMPT_RESTRICT_F) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `r:A = rg` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:form`; `v:num->A`;
                  `a:A`; `r:A`; `rg:A`] ERECRES_UNIQUE_F) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(rg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  UNDISCH_TAC `eattempt D (E:A->A->bool) q v g t` THEN
  REWRITE_TAC[eattempt] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`a:A`; `rg:A`; `y:A`]) THEN
  ASM_REWRITE_TAC[]);;

let EREC_EQUATION = prove
 (`!D (E:A->A->bool) q v a y r.
        model D E ZF_AX /\ valuation D v /\
        (!r w w'. r IN D /\ w IN D /\ w' IN D /\
                  holds D E ((1 |-> w) ((0 |-> r) v)) q /\
                  holds D E ((1 |-> w') ((0 |-> r) v)) q ==> w = w') /\
        eordinal D E a /\ y IN D /\
        erec D E q v a y /\ erecres D E q v a r
        ==> holds D E ((1 |-> y) ((0 |-> r) v)) q`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EREC_EQUATION_F));;

(* ------------------------------------------------------------------------- *)
(* Definability of the recursion relation itself: rec_form q N expresses     *)
(* "v(N+1) = F(v N)" for the function F recursively defined by q.            *)
(* ------------------------------------------------------------------------- *)

let HOLDS_REC_FORM = prove
 (`!D (E:A->A->bool) v q N u y.
      valuation D v /\ 1 < N /\ (!m. m IN FV q ==> m < N) /\
      u IN D /\ y IN D
      ==> (holds D E (((N + 1) |-> y) ((N |-> u) v)) (rec_form q N) <=>
           erec D E q v u y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!m:num. m IN FV q
        ==> ~(m = N) /\ ~(m = N + 1) /\ ~(m = N + 2) /\ ~(m = N + 3)`
  (LABEL_TAC "fvq") THENL
   [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN `m:num < N` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t g:A. t IN D /\ g IN D
        ==> valuation D
             (((N + 3) |-> g) (((N + 2) |-> t)
              (((N + 1) |-> y) ((N |-> u) v))))`
  (LABEL_TAC "wval") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((N + 1) |-> (y:A)) ((N |-> u) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `valuation D (((N + 2) |-> (t:A)) (((N + 1) |-> y) ((N |-> u) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t g:A. t IN D /\ g IN D
      ==> (holds D E (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> y) ((N |-> u) v))))
                 (ordinal_form (N + 2)) <=> eordinal D E t) /\
          (holds D E (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> y) ((N |-> u) v))))
                 (attempt_form q (N + 3) (N + 2) (N + 4)) <=>
           eattempt D E q v g t) /\
          (holds D E (((N + 3) |-> g) (((N + 2) |-> t)
                      (((N + 1) |-> y) ((N |-> u) v))))
                 (applyto_form N (N + 1) (N + 3)) <=>
           eapply D E g u y)`
  (LABEL_TAC "mac") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((N + 3) |-> (g:A)) (((N + 2) |-> t)
                   (((N + 1) |-> y) ((N |-> u) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N + 2 = N + 3)`];
      MP_TAC(SPECL
       [`D:A->bool`; `E:A->A->bool`;
        `((N + 3) |-> (g:A)) (((N + 2) |-> t)
         (((N + 1) |-> y) ((N |-> u) v)))`;
        `q:form`; `N + 3`; `N + 2`; `N + 4`] HOLDS_ATTEMPT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN
        TRY ARITH_TAC THEN
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        SUBGOAL_THEN `m:num < N` MP_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ARITH_TAC;
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N + 2 = N + 3)`] THEN
      MATCH_MP_TAC EATTEMPT_VALUATION THEN
      X_GEN_TAC `m:num` THEN STRIP_TAC THEN
      USE_THEN "fvq" (fun th -> MP_TAC(MATCH_MP th
        (ASSUME `(m:num) IN FV q`))) THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[VALMOD];
      ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(N = N + 1) /\ ~(N = N + 2) /\ ~(N = N + 3) /\
        ~(N + 1 = N + 2) /\ ~(N + 1 = N + 3)`]];
    ALL_TAC] THEN
  REWRITE_TAC[rec_form; HOLDS_EX; HOLDS_AND; holds; erec] THEN
  REWRITE_TAC[VALMOD] THEN
  SIMP_TAC[ARITH_RULE
   `~(N = N + 1) /\ ~(N = N + 2) /\ ~(N = N + 3) /\
    ~(N + 2 = N + 3)`] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `t:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `g:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `g:A`] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "mac" (fun th ->
      MP_TAC(SPECL [`t:A`; `g:A`] th)) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `g:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "mac" (fun th ->
      MP_TAC(SPECL [`t:A`; `g:A`] th)) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* First instantiation of the recursion theorem: the cumulative hierarchy    *)
(* function V(a) = UNION {P(V(b)) | b IN a} on ordinals (used on the         *)
(* members of omega it yields the hereditarily finite levels, where the      *)
(* internal formula codes will live). The recursion data vstep_form says     *)
(* "u IN output iff u is a subset of some value of the input function",      *)
(* which is total (bounded by the powerset of a triple union) and            *)
(* functional (extensionality).                                              *)
(* ------------------------------------------------------------------------- *)

let EREC_VALUATION = prove
 (`!D (E:A->A->bool) q v v' a y.
        (!m. m IN FV q /\ ~(m = 0) /\ ~(m = 1) ==> v m = v' m)
        ==> (erec D E q v a y <=> erec D E q v' a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[erec] THEN
  SUBGOAL_THEN
   `!g t:A. eattempt D (E:A->A->bool) q v g t <=> eattempt D E q v' g t`
  (fun th -> REWRITE_TAC[th]) THEN
  REPEAT GEN_TAC THEN MATCH_MP_TAC EATTEMPT_VALUATION THEN
  ASM_REWRITE_TAC[]);;

let vstep = new_definition
  `vstep D (E:A->A->bool) g y <=>
        y IN D /\
        !u. u IN D
            ==> (E u y <=>
                 ?b w. b IN D /\ w IN D /\ eapply D E g b w /\
                       esubset D E u w)`;;

let HOLDS_VSTEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) vstep_form <=>
           vstep D E g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[vstep_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              HOLDS_SUBSET_FORM; vstep] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!u b w:A. u IN D /\ b IN D /\ w IN D
        ==> (holds D E ((4 |-> w) ((3 |-> b) ((2 |-> u)
                        ((1 |-> y) ((0 |-> g) v)))))
                   (applyto_form 3 4 0) <=>
             eapply D E g b w)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((4 |-> (w:A)) ((3 |-> b) ((2 |-> u)
                   ((1 |-> y) ((0 |-> g) v)))))`
    ASSUME_TAC THENL
     [SUBGOAL_THEN
       `valuation D ((2 |-> (u:A)) ((1 |-> y) ((0 |-> g) v)))`
      ASSUME_TAC THENL
       [SUBGOAL_THEN `valuation D ((1 |-> (y:A)) ((0 |-> g) v))`
        ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `valuation D ((3 |-> (b:A)) ((2 |-> u)
                     ((1 |-> y) ((0 |-> g) v))))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  AP_TERM_TAC THEN ABS_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (q <=> r)) ==> (p ==> q <=> p ==> r)`) THEN
  DISCH_TAC THEN AP_TERM_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let VSTEP_FUN_F = prove
 (`!D (E:A->A->bool) g y y'.
        model D E zfw_ax /\ vstep D E g y /\ vstep D E g y' ==> y = y'`,
  REWRITE_TAC[vstep] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let VSTEP_FUN = prove
 (`!D (E:A->A->bool) g y y'.
        model D E ZF_AX /\ vstep D E g y /\ vstep D E g y' ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW VSTEP_FUN_F));;

let VSTEP_TOTAL_F = prove
 (`!D (E:A->A->bool) g.
      model D E zfw_ax /\ g IN D ==> ?y. vstep D E g y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u1:A`) THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u1:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u2:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u3:A`) THEN
  SUBGOAL_THEN `(u3:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u3:A`] EPOW_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pw:A`) THEN
  SUBGOAL_THEN `(pw:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u b w:A. u IN D /\ b IN D /\ w IN D /\
              eapply D (E:A->A->bool) g b w /\ esubset D E u w
              ==> E u pw`
  (LABEL_TAC "bound") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) g b w` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair] o
        check (fun th -> can (find_term (fun t ->
          t = `eopair:(A->bool)->(A->A->bool)->A->A->A->bool`))
          (concl th))) THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) w p /\ E p z` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[epair]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) p u1` ASSUME_TAC THENL
       [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
      ASM_MESON_TAC[eunion];
      ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) u u3` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) m w` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      ASM_MESON_TAC[eunion];
      ALL_TAC] THEN
    ASM_MESON_TAC[epow];
    ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (g:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`?? 2 (?? 3 (applyto_form 2 3 1 && subset_form 0 3))`; `0`;
     `(1 |-> (g:A)) v0`; `pw:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[vstep] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) ((1 |-> g) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (u:A)) ((1 |-> g) v0))
          (?? 2 (?? 3 (applyto_form 2 3 1 && subset_form 0 3))) <=>
    ?b w:A. b IN D /\ w IN D /\ eapply D (E:A->A->bool) g b w /\
            esubset D E u w`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_SUBSET_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN
     `!b w:A. b IN D /\ w IN D
         ==> (holds D E ((3 |-> w) ((2 |-> b) ((0 |-> u)
                         ((1 |-> g) v0))))
                    (applyto_form 2 3 1) <=>
              eapply D E g b w)`
    ASSUME_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D ((3 |-> (w:A)) ((2 |-> b) ((0 |-> u)
                     ((1 |-> g) v0))))`
      ASSUME_TAC THENL
       [SUBGOAL_THEN
         `valuation D ((2 |-> (b:A)) ((0 |-> u) ((1 |-> g) v0)))`
        ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN ASM_MESON_TAC[];
    STRIP_TAC THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ASM_MESON_TAC[]]]);;

let VSTEP_TOTAL = prove
 (`!D (E:A->A->bool) g.
      model D E ZF_AX /\ g IN D ==> ?y. vstep D E g y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW VSTEP_TOTAL_F));;

let VSTEP_QFUN_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) vstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) vstep_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC VSTEP_FUN_F THEN
  MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_VSTEP_FORM]);;

let VSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) vstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) vstep_form
                     ==> w = w'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW VSTEP_QFUN_F));;

let VSTEP_QTOTAL_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) vstep_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] VSTEP_TOTAL_F) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[vstep]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_VSTEP_FORM]);;

let VSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) vstep_form`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW VSTEP_QTOTAL_F));;

let ehfstage = new_definition
  `ehfstage D (E:A->A->bool) a y <=>
        ?v. valuation D v /\ erec D E vstep_form v a y`;;

let EHFSTAGE_EREC_F = prove
 (`!D (E:A->A->bool) a y v.
        model D E zfw_ax /\ valuation D v
        ==> (ehfstage D E a y <=> erec D E vstep_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ehfstage] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) vstep_form v' a y <=>
      erec D E vstep_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(REWRITE_RULE[SUBSET] FV_VSTEP_FORM) THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY];
    ASM_MESON_TAC[]]);;

let EHFSTAGE_EREC = prove
 (`!D (E:A->A->bool) a y v.
        model D E ZF_AX /\ valuation D v
        ==> (ehfstage D E a y <=> erec D E vstep_form v a y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EHFSTAGE_EREC_F));;

let EHFSTAGE_UNIQUE_F = prove
 (`!D (E:A->A->bool) a y y'.
        model D E zfw_ax /\ a IN D /\ y IN D /\ y' IN D /\
        ehfstage D E a y /\ ehfstage D E a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`; `v:num->A`;
                `a:A`; `y:A`; `y':A`] EREC_UNIQUE_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] VSTEP_QFUN_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EHFSTAGE_EREC_F]);;

let EHFSTAGE_UNIQUE = prove
 (`!D (E:A->A->bool) a y y'.
        model D E ZF_AX /\ a IN D /\ y IN D /\ y' IN D /\
        ehfstage D E a y /\ ehfstage D E a y'
        ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EHFSTAGE_UNIQUE_F));;

let EHFSTAGE_EXISTS_F = prove
 (`!D (E:A->A->bool) a.
        model D E zfw_ax /\ eordinal D E a
        ==> ?y. y IN D /\ ehfstage D E a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`; `v:num->A`;
                `a:A`; `5`; `20`] EREC_EXISTS_F) THEN
  ASM_REWRITE_TAC[ENGINE_READY_VSTEP] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[VSTEP_QFUN_F; VSTEP_QTOTAL_F]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EHFSTAGE_EREC_F]);;

let EHFSTAGE_EXISTS = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?y. y IN D /\ ehfstage D E a y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EHFSTAGE_EXISTS_F));;

let EHFSTAGE_CHAR = prove
 (`!D (E:A->A->bool) a y.
      model D E ZF_AX /\ eordinal D E a /\ y IN D /\ ehfstage D E a y
      ==> !u. u IN D
              ==> (E u y <=>
                   ?b w. b IN D /\ w IN D /\ E b a /\
                         ehfstage D E b w /\ esubset D E u w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) vstep_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VSTEP_QFUN; VSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `vstep D (E:A->A->bool) r y` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `y:A`]
          HOLDS_VSTEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[VSTEP_QFUN; EHFSTAGE_EREC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w:A. b IN D /\ w IN D
        ==> (eapply D (E:A->A->bool) r b w <=>
             E b a /\ erec D E vstep_form v b w)`
  (LABEL_TAC "rap") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THENL
     [REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
        (ASSUME `erecres D (E:A->A->bool) vstep_form v a r`)))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `b':A = b /\ y':A = w` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`]
            EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
        (ASSUME `erecres D (E:A->A->bool) vstep_form v a r`)))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  MP_TAC(SPEC `u:A` (CONJUNCT2(REWRITE_RULE[vstep]
    (ASSUME `vstep D (E:A->A->bool) r y`)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EHFSTAGE_EREC];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EHFSTAGE_EREC]]);;

(* ------------------------------------------------------------------------- *)
(* The set of hereditarily-finite-rank elements: the union of the V-stages   *)
(* over the members of omega, obtained by the replacement scheme applied to  *)
(* rec_form vstep_form 2 (the first definability payoff of the recursion     *)
(* theorem) followed by a union.                                             *)
(* ------------------------------------------------------------------------- *)

let ehfset = new_definition
  `ehfset D (E:A->A->bool) w h <=>
        h IN D /\
        !u. u IN D
            ==> (E u h <=>
                 ?n y. n IN D /\ y IN D /\ E n w /\
                       ehfstage D E n y /\ E u y)`;;

let EHFSET_UNIQUE_F = prove
 (`!D (E:A->A->bool) w h h'.
        model D E zfw_ax /\ ehfset D E w h /\ ehfset D E w h' ==> h = h'`,
  REWRITE_TAC[ehfset] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let EHFSET_UNIQUE = prove
 (`!D (E:A->A->bool) w h h'.
        model D E ZF_AX /\ ehfset D E w h /\ ehfset D E w h' ==> h = h'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EHFSET_UNIQUE_F));;

let EHFSET_EXISTS_F = prove
 (`!D (E:A->A->bool) w.
      model D E zfw_ax /\ eomega D E w ==> ?h. ehfset D E w h`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`rec_form vstep_form 2`; `2`; `3`; `v:num->A`; `w:A`] o
    MATCH_MP ZF_REPLACEMENT_W) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                    FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                    FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                    FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                    IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS_F]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`]
          EHFSTAGE_EXISTS_F) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `erec D (E:A->A->bool) vstep_form v u w'`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                    `vstep_form`; `2`; `u:A`; `w':A`]
            HOLDS_REC_FORM) THEN
      ASM_REWRITE_TAC[FVLT_VSTEP_FORM; ARITH_RULE `1 < 2`] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      ASM_REWRITE_TAC[ARITH_RULE `2 + 1 = 3`];
      ALL_TAC] THEN
    SUBGOAL_THEN `ehfstage D (E:A->A->bool) u w'` ASSUME_TAC THENL
     [ASM_MESON_TAC[EHFSTAGE_EREC_F]; ALL_TAC] THEN
    MATCH_MP_TAC EHFSTAGE_UNIQUE_F THEN
    MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `u:A`] THEN
    ASM_MESON_TAC[EORDINAL_IN];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `B:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
        ==> ((E:A->A->bool) z B <=>
             ?n. n IN D /\ E n w /\ ehfstage D E n z)`
  (LABEL_TAC "Bch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`)) THEN ASSUME_TAC th) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THENL
     [SUBGOAL_THEN `erec D (E:A->A->bool) vstep_form v n z`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                      `vstep_form`; `2`; `n:A`; `z:A`]
              HOLDS_REC_FORM) THEN
        ASM_REWRITE_TAC[FVLT_VSTEP_FORM; ARITH_RULE `1 < 2`] THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN
        ASM_REWRITE_TAC[ARITH_RULE `2 + 1 = 3`];
        ALL_TAC] THEN
      ASM_MESON_TAC[EHFSTAGE_EREC_F];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                    `vstep_form`; `2`; `n:A`; `z:A`]
            HOLDS_REC_FORM) THEN
      ASM_REWRITE_TAC[FVLT_VSTEP_FORM; ARITH_RULE `1 < 2`] THEN
      REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[EHFSTAGE_EREC_F]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  EXISTS_TAC `h:A` THEN
  SUBGOAL_THEN `(h:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ehfset] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(E:A->A->bool) u h <=> ?y. y IN D /\ E y B /\ E u y`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "Bch" (fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(y:A) IN D`))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `y:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "Bch" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(y:A) IN D`)]) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[]]);;

let EHFSET_EXISTS = prove
 (`!D (E:A->A->bool) w.
      model D E ZF_AX /\ eomega D E w ==> ?h. ehfset D E w h`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EHFSET_EXISTS_F));;

(* ------------------------------------------------------------------------- *)
(* Internal numerals (von Neumann naturals coding the metatheoretic ones)    *)
(* and internal codes of object formulas, both by meta-level recursion.      *)
(* Constructor tags 0..4 mirror the five form constructors.                  *)
(* ------------------------------------------------------------------------- *)

let enat = new_recursive_definition num_RECURSION
  `(enat D (E:A->A->bool) 0 x <=> eempty D E x) /\
   (enat D E (SUC n) x <=> ?y. y IN D /\ enat D E n y /\ esuc D E y x)`;;

let ENAT_IN = prove
 (`!D (E:A->A->bool) n x. enat D E n x ==> x IN D`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN
  REWRITE_TAC[enat] THEN MESON_TAC[EEMPTY_IN; ESUC_IN]);;

let ENAT_EXISTS_F = prove
 (`!D (E:A->A->bool) n. model D E zfw_ax ==> ?x. enat D E n x`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[enat] THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS_F];
    FIRST_X_ASSUM(fun th -> MP_TAC(MATCH_MP th
      (ASSUME `model D (E:A->A->bool) zfw_ax`))) THEN
    ASM_MESON_TAC[ESUC_EXISTS_F; ENAT_IN]]);;

let ENAT_EXISTS = prove
 (`!D (E:A->A->bool) n. model D E ZF_AX ==> ?x. enat D E n x`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ENAT_EXISTS_F));;

let ENAT_UNIQUE_F = prove
 (`!D (E:A->A->bool) n x x'.
        model D E zfw_ax /\ enat D E n x /\ enat D E n x' ==> x = x'`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN
  REWRITE_TAC[enat] THENL
   [MESON_TAC[EEMPTY_UNIQUE_F];
    REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `y:A = y'` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[ESUC_UNIQUE_F]]);;

let ENAT_UNIQUE = prove
 (`!D (E:A->A->bool) n x x'.
        model D E ZF_AX /\ enat D E n x /\ enat D E n x' ==> x = x'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ENAT_UNIQUE_F));;

let ENAT_ORDINAL = prove
 (`!D (E:A->A->bool) n x.
        model D E ZF_AX /\ enat D E n x ==> eordinal D E x`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN
  REWRITE_TAC[enat] THEN
  ASM_MESON_TAC[EORDINAL_EEMPTY; EORDINAL_ESUC]);;

let ecode = new_recursive_definition form_RECURSION
  `(ecode D (E:A->A->bool) False z <=>
        ?t. t IN D /\ enat D E 0 t /\ eopair D E t t z) /\
   (ecode D E (i %% j) z <=>
        ?t a b p. t IN D /\ a IN D /\ b IN D /\ p IN D /\
                  enat D E 1 t /\ enat D E i a /\ enat D E j b /\
                  eopair D E a b p /\ eopair D E t p z) /\
   (ecode D E (Eq i j) z <=>
        ?t a b p. t IN D /\ a IN D /\ b IN D /\ p IN D /\
                  enat D E 2 t /\ enat D E i a /\ enat D E j b /\
                  eopair D E a b p /\ eopair D E t p z) /\
   (ecode D E (p --> q) z <=>
        ?t cp cq w. t IN D /\ cp IN D /\ cq IN D /\ w IN D /\
                    enat D E 3 t /\ ecode D E p cp /\ ecode D E q cq /\
                    eopair D E cp cq w /\ eopair D E t w z) /\
   (ecode D E (!! i p) z <=>
        ?t a cp w. t IN D /\ a IN D /\ cp IN D /\ w IN D /\
                   enat D E 4 t /\ enat D E i a /\ ecode D E p cp /\
                   eopair D E a cp w /\ eopair D E t w z)`;;

let ECODE_IN = prove
 (`!D (E:A->A->bool) p z. ecode D E p z ==> z IN D`,
  GEN_TAC THEN GEN_TAC THEN MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[ecode] THEN MESON_TAC[EOPAIR_IN]);;

let ECODE_EXISTS = prove
 (`!D (E:A->A->bool) p. model D E ZF_AX ==> ?z. ecode D E p z`,
  GEN_TAC THEN GEN_TAC THEN MATCH_MP_TAC form_INDUCT THEN
  REPEAT CONJ_TAC THEN REWRITE_TAC[ecode] THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `?t:A. enat D (E:A->A->bool) 0 t`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    ASM_MESON_TAC[EOPAIR_EXISTS];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(?t:A. enat D (E:A->A->bool) 1 t) /\
      (?a:A. enat D E i a) /\ (?b:A. enat D E j b)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D /\ (a:A) IN D /\ (b:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) a b p`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) t p z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `a:A`; `b:A`; `p:A`] THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `j:num`] THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `(?t:A. enat D (E:A->A->bool) 2 t) /\
      (?a:A. enat D E i a) /\ (?b:A. enat D E j b)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D /\ (a:A) IN D /\ (b:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) a b p`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) t p z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `a:A`; `b:A`; `p:A`] THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN STRIP_TAC THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `(?cp:A. ecode D (E:A->A->bool) p cp) /\
      (?cq:A. ecode D E q cq)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?t:A. enat D (E:A->A->bool) 3 t`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D /\ (cp:A) IN D /\ (cq:A) IN D`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN; ECODE_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?w:A. eopair D (E:A->A->bool) cp cq w`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) t w z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `cp:A`; `cq:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`i:num`; `p:form`] THEN STRIP_TAC THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `?cp:A. ecode D (E:A->A->bool) p cp`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(?t:A. enat D (E:A->A->bool) 4 t) /\ (?a:A. enat D E i a)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D /\ (a:A) IN D /\ (cp:A) IN D`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN; ECODE_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?w:A. eopair D (E:A->A->bool) a cp w`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) t w z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN
    MAP_EVERY EXISTS_TAC [`t:A`; `a:A`; `cp:A`; `w:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Cartesian products and function spaces as internal sets. The product      *)
(* lives inside P(P(a UNION b)) since a Kuratowski pair of members of a,b    *)
(* has its two elements among subsets of a UNION b; the function space       *)
(* inside P(a CROSS b). Both then come from separation.                      *)
(* ------------------------------------------------------------------------- *)

let ecross = new_definition
  `ecross D (E:A->A->bool) a b c <=>
        c IN D /\
        !z. z IN D
            ==> (E z c <=>
                 ?u w. u IN D /\ w IN D /\ E u a /\ E w b /\
                       eopair D E u w z)`;;

let ECROSS_UNIQUE_F = prove
 (`!D (E:A->A->bool) a b c c'.
        model D E zfw_ax /\ ecross D E a b c /\ ecross D E a b c'
        ==> c = c'`,
  REWRITE_TAC[ecross] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let ECROSS_UNIQUE = prove
 (`!D (E:A->A->bool) a b c c'.
        model D E ZF_AX /\ ecross D E a b c /\ ecross D E a b c'
        ==> c = c'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ECROSS_UNIQUE_F));;

let EOPAIR_IN_POWPOW_F = prove
 (`!D (E:A->A->bool) a b ab p1 p2 u w z.
        model D E zfw_ax /\ a IN D /\ b IN D /\
        ebunion D E a b ab /\ epow D E ab p1 /\ epow D E p1 p2 /\
        u IN D /\ w IN D /\ E u a /\ E w b /\ eopair D E u w z
        ==> E z p2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(ab:A) IN D /\ (p1:A) IN D /\ (p2:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN; EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u ab /\ E w ab` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_ALT_F]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair]) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D /\ (z:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) s ab /\ esubset D E p ab`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s p1 /\ E p p1` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z p1` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[epair]; ALL_TAC] THEN
  ASM_MESON_TAC[epow]);;

let EOPAIR_IN_POWPOW = prove
 (`!D (E:A->A->bool) a b ab p1 p2 u w z.
        model D E ZF_AX /\ a IN D /\ b IN D /\
        ebunion D E a b ab /\ epow D E ab p1 /\ epow D E p1 p2 /\
        u IN D /\ w IN D /\ E u a /\ E w b /\ eopair D E u w z
        ==> E z p2`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EOPAIR_IN_POWPOW_F));;

let ECROSS_EXISTS_F = prove
 (`!D (E:A->A->bool) a b.
        model D E zfw_ax /\ a IN D /\ b IN D ==> ?c. ecross D E a b c`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
        EBUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ab:A`) THEN
  SUBGOAL_THEN `(ab:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ab:A`] EPOW_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p1:A`) THEN
  SUBGOAL_THEN `(p1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p1:A`] EPOW_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p2:A`) THEN
  SUBGOAL_THEN `(p2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (b:A)) ((1 |-> a) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`?? 3 (?? 4 ((3 %% 1) && (4 %% 2) && opair_form 3 4 0))`; `0`;
     `(2 |-> (b:A)) ((1 |-> a) v0)`; `p2:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[ecross] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (z:A)) ((2 |-> b) ((1 |-> a) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (z:A)) ((2 |-> b) ((1 |-> a) v0)))
          (?? 3 (?? 4 ((3 %% 1) && (4 %% 2) && opair_form 3 4 0))) <=>
    ?u w:A. u IN D /\ w IN D /\ E u a /\ E w b /\ eopair D E u w z`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN
     `!u w:A. u IN D /\ w IN D
         ==> (holds D E
               ((4 |-> w) ((3 |-> u) ((0 |-> z) ((2 |-> b) ((1 |-> a) v0)))))
               (opair_form 3 4 0) <=>
              eopair D E u w z)`
    ASSUME_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D
         ((4 |-> (w:A)) ((3 |-> u) ((0 |-> z) ((2 |-> b) ((1 |-> a) v0)))))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ; ARITH_RULE
        `~(3 = 4) /\ ~(4 = 3) /\ ~(0 = 3) /\ ~(0 = 4)`];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
    STRIP_ASSUME_TAC)) THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `ab:A`;
                  `p1:A`; `p2:A`; `u:A`; `w:A`; `z:A`]
          EOPAIR_IN_POWPOW_F) THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

let ECROSS_EXISTS = prove
 (`!D (E:A->A->bool) a b.
        model D E ZF_AX /\ a IN D /\ b IN D ==> ?c. ecross D E a b c`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ECROSS_EXISTS_F));;

let efuns = new_definition
  `efuns D (E:A->A->bool) a b f <=>
        f IN D /\
        !g. g IN D
            ==> (E g f <=>
                 eisfun D E g /\ edomain D E g a /\
                 !u w. u IN D /\ w IN D /\ eapply D E g u w ==> E w b)`;;

let EFUNS_UNIQUE_F = prove
 (`!D (E:A->A->bool) a b f f'.
        model D E zfw_ax /\ efuns D E a b f /\ efuns D E a b f'
        ==> f = f'`,
  REWRITE_TAC[efuns] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let EFUNS_UNIQUE = prove
 (`!D (E:A->A->bool) a b f f'.
        model D E ZF_AX /\ efuns D E a b f /\ efuns D E a b f'
        ==> f = f'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EFUNS_UNIQUE_F));;

let EFUN_IN_POWCROSS_F = prove
 (`!D (E:A->A->bool) a b cr pab g.
        model D E zfw_ax /\ a IN D /\ b IN D /\
        ecross D E a b cr /\ epow D E cr pab /\
        eisfun D E g /\ edomain D E g a /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w ==> E w b)
        ==> E g pab`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(g:A) IN D /\ (cr:A) IN D /\ (pab:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eisfun; ecross; EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) g cr` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?u w:A. u IN D /\ w IN D /\ eopair D (E:A->A->bool) u w z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g u w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u a` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w b` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[ecross];
    ALL_TAC] THEN
  ASM_MESON_TAC[epow]);;

let EFUN_IN_POWCROSS = prove
 (`!D (E:A->A->bool) a b cr pab g.
        model D E ZF_AX /\ a IN D /\ b IN D /\
        ecross D E a b cr /\ epow D E cr pab /\
        eisfun D E g /\ edomain D E g a /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w ==> E w b)
        ==> E g pab`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EFUN_IN_POWCROSS_F));;

let EFUNS_EXISTS_F = prove
 (`!D (E:A->A->bool) a b.
        model D E zfw_ax /\ a IN D /\ b IN D ==> ?f. efuns D E a b f`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
        ECROSS_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cr:A`) THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cr:A`] EPOW_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pab:A`) THEN
  SUBGOAL_THEN `(pab:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (b:A)) ((1 |-> a) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`fun_form 0 && domain_form 0 1 &&
      !!- 3 0 (!! 4 (!! 5 (opair_form 4 5 3 --> (5 %% 2))))`; `0`;
     `(2 |-> (b:A)) ((1 |-> a) v0)`; `pab:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `f:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[efuns] THEN X_GEN_TAC `g:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (g:A)) ((2 |-> b) ((1 |-> a) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (g:A)) ((2 |-> b) ((1 |-> a) v0)))
          (fun_form 0 && domain_form 0 1 &&
           !!- 3 0 (!! 4 (!! 5 (opair_form 4 5 3 --> (5 %% 2))))) <=>
    eisfun D E g /\ edomain D E g a /\
    (!u w:A. u IN D /\ w IN D /\ eapply D E g u w ==> E w b)`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[HOLDS_AND] THEN
    ASM_SIMP_TAC[HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT
      `(c <=> c') ==> ((a /\ b /\ c) <=> (a /\ b /\ c'))`) THEN
    ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(3 = 0)`] THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN
     `!z u w:A. z IN D /\ u IN D /\ w IN D
        ==> (holds D E
              ((5 |-> w) ((4 |-> u) ((3 |-> z)
                 ((0 |-> g) ((2 |-> b) ((1 |-> a) v0))))))
              (opair_form 4 5 3) <=>
             eopair D E u w z)`
    ASSUME_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D
          ((5 |-> (w:A)) ((4 |-> u) ((3 |-> z)
             ((0 |-> g) ((2 |-> b) ((1 |-> a) v0))))))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eapply] o
        check (fun th -> fst(strip_comb(concl th)) =
          `eapply:(A->bool)->(A->A->bool)->A->A->A->bool`)) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      DISCH_TAC THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `eopair D (E:A->A->bool) u w z` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g u w` ASSUME_TAC THENL
       [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `cr:A`;
                `pab:A`; `g:A`] EFUN_IN_POWCROSS_F) THEN
  ASM_REWRITE_TAC[]);;

let EFUNS_EXISTS = prove
 (`!D (E:A->A->bool) a b.
        model D E ZF_AX /\ a IN D /\ b IN D ==> ?f. efuns D E a b f`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EFUNS_EXISTS_F));;

(* ------------------------------------------------------------------------- *)
(* Pointwise update of an internal function (for rebinding one variable of   *)
(* an internal valuation in the Tarski clause for the quantifier), plus the  *)
(* packaged "internal valuation over structure x" predicate: an internal     *)
(* function om -> x where om will be instantiated to the model's omega.      *)
(* Membership in the function space efuns om x is exactly this predicate.    *)
(* ------------------------------------------------------------------------- *)

let eupdate = new_definition
  `eupdate D (E:A->A->bool) s a u s' <=>
        s' IN D /\
        !z. z IN D
            ==> (E z s' <=>
                 (E z s /\ ~(?w. w IN D /\ eopair D E a w z)) \/
                 eopair D E a u z)`;;

let EUPDATE_UNIQUE = prove
 (`!D (E:A->A->bool) s a u s' s''.
        model D E ZF_AX /\ eupdate D E s a u s' /\ eupdate D E s a u s''
        ==> s' = s''`,
  REWRITE_TAC[eupdate] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EUPDATE_EXISTS_F = prove
 (`!D (E:A->A->bool) s a u.
        model D E zfw_ax /\ s IN D /\ a IN D /\ u IN D
        ==> ?s'. eupdate D E s a u s'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`]
        EOPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `pr:A`; `pr:A`]
        EPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sg:A`) THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `sg:A`]
        EBUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `bun:A`) THEN
  SUBGOAL_THEN `(bun:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> ((E:A->A->bool) z bun <=> E z s \/ z = pr)`
  (LABEL_TAC "bun") THENL
   [ASM_MESON_TAC[EBUNION_ALT_F; epair]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (u:A)) ((2 |-> a) ((1 |-> s) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`((0 %% 1) && Not(?? 4 (opair_form 2 4 0))) || opair_form 2 3 0`;
     `0`; `(3 |-> (u:A)) ((2 |-> a) ((1 |-> s) v0))`; `bun:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `s':A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[eupdate] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((0 |-> (z:A)) ((3 |-> u) ((2 |-> a) ((1 |-> s) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (z:A)) ((3 |-> u) ((2 |-> a) ((1 |-> s) v0))))
          (((0 %% 1) && Not(?? 4 (opair_form 2 4 0))) ||
           opair_form 2 3 0) <=>
    (E z s /\ ~(?w:A. w IN D /\ eopair D E a w z)) \/ eopair D E a u z`
  (fun th -> REWRITE_TAC[th]) THENL
   [REWRITE_TAC[HOLDS_OR; HOLDS_AND; HOLDS_NOT; HOLDS_EX; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN
     `!w:A. w IN D
        ==> (holds D E
              ((4 |-> w) ((0 |-> z) ((3 |-> u) ((2 |-> a) ((1 |-> s) v0)))))
              (opair_form 2 4 0) <=>
             eopair D E a w z)`
    ASSUME_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D
         ((4 |-> (w:A)) ((0 |-> z) ((3 |-> u) ((2 |-> a) ((1 |-> s) v0)))))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(?w:A. w IN D /\
             holds D E
              ((4 |-> w) ((0 |-> z) ((3 |-> u) ((2 |-> a) ((1 |-> s) v0)))))
              (opair_form 2 4 0)) <=>
      (?w:A. w IN D /\ eopair D (E:A->A->bool) a w z)`
    (fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  USE_THEN "bun" (fun th ->
    REWRITE_TAC[MATCH_MP th (ASSUME `(z:A) IN D`)]) THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EOPAIR_UNIQUE_F]);;

let EUPDATE_EXISTS = prove
 (`!D (E:A->A->bool) s a u.
        model D E ZF_AX /\ s IN D /\ a IN D /\ u IN D
        ==> ?s'. eupdate D E s a u s'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EUPDATE_EXISTS_F));;

let EUPDATE_IN = prove
 (`!D (E:A->A->bool) s a u s'. eupdate D E s a u s' ==> s' IN D`,
  SIMP_TAC[eupdate]);;

let EUPDATE_APPLY_SAME = prove
 (`!D (E:A->A->bool) s a u s'.
        model D E ZF_AX /\ s IN D /\ a IN D /\ u IN D /\
        eupdate D E s a u s'
        ==> eapply D E s' a u /\
            !w. w IN D /\ eapply D E s' a w ==> w = u`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`]
          EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
    ASM_MESON_TAC[eupdate];
    X_GEN_TAC `w:A` THEN REWRITE_TAC[eapply] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(E z s /\ ~(?w'. w' IN D /\ eopair D E a w' z)) \/
      eopair D (E:A->A->bool) a u z`
    MP_TAC THENL [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
    STRIP_TAC THENL [ASM_MESON_TAC[]; ASM_MESON_TAC[EOPAIR_INJ]]]);;

let EUPDATE_APPLY_OTHER = prove
 (`!D (E:A->A->bool) s a u s' b w.
        model D E ZF_AX /\ s IN D /\ a IN D /\ u IN D /\
        eupdate D E s a u s' /\ b IN D /\ w IN D /\ ~(b = a)
        ==> (eapply D E s' b w <=> eapply D E s b w)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(E z s /\ ~(?w'. w' IN D /\ eopair D E a w' z)) \/
      eopair D (E:A->A->bool) a u z`
    MP_TAC THENL [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN MP_TAC) THENL
     [MESON_TAC[];
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                    `a:A`; `u:A`; `z:A`] EOPAIR_INJ) THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~(?w'. w' IN D /\ eopair D (E:A->A->bool) a w' z)`
    ASSUME_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                    `a:A`; `w':A`; `z:A`] EOPAIR_INJ) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[eupdate]]);;

let evaluation = new_definition
  `evaluation D (E:A->A->bool) om x s <=>
        eisfun D E s /\ edomain D E s om /\
        !u w. u IN D /\ w IN D /\ eapply D E s u w ==> E w x`;;

let EVALUATION_EFUNS = prove
 (`!D (E:A->A->bool) om x f s.
        efuns D E om x f /\ s IN D
        ==> (E s f <=> evaluation D E om x s)`,
  REWRITE_TAC[efuns; evaluation] THEN MESON_TAC[]);;

let EVALUATION_IN = prove
 (`!D (E:A->A->bool) om x s. evaluation D E om x s ==> s IN D`,
  REWRITE_TAC[evaluation; eisfun] THEN MESON_TAC[]);;

let EUPDATE_ISFUN = prove
 (`!D (E:A->A->bool) s a u s'.
        model D E ZF_AX /\ eisfun D E s /\ a IN D /\ u IN D /\
        eupdate D E s a u s'
        ==> eisfun D E s'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (s':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eisfun; EUPDATE_IN]; ALL_TAC] THEN
  REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E z s /\ ~(?w'. w' IN D /\ eopair D E a w' z)) \/
      eopair D (E:A->A->bool) a u z`
    MP_TAC THENL [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN MP_TAC) THENL
     [ASM_MESON_TAC[eisfun]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`p:A`; `q:A`; `q':A`; `z1:A`; `z2:A`] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `(z1:A) IN D /\ (z2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((E:A->A->bool) z1 s /\ ~(?w'. w' IN D /\ eopair D E a w' z1)) \/
    eopair D (E:A->A->bool) a u z1`
  MP_TAC THENL [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((E:A->A->bool) z2 s /\ ~(?w'. w' IN D /\ eopair D E a w' z2)) \/
    eopair D (E:A->A->bool) a u z2`
  MP_TAC THENL [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THEN
  DISCH_THEN(DISJ_CASES_THEN STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[eisfun];
    SUBGOAL_THEN `p:A = a /\ q:A = u` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    SUBGOAL_THEN `p:A = a /\ q':A = u` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ASM_MESON_TAC[EOPAIR_INJ]]);;

let EVALUATION_UPDATE = prove
 (`!D (E:A->A->bool) om x s a u s'.
        model D E ZF_AX /\ evaluation D E om x s /\
        a IN D /\ E a om /\ u IN D /\ E u x /\
        eupdate D E s a u s'
        ==> evaluation D E om x s'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[evaluation] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (s':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eisfun; EUPDATE_IN]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[EUPDATE_ISFUN];
    REWRITE_TAC[edomain] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    ASM_CASES_TAC `b:A = a` THENL
     [ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[eindom; EUPDATE_APPLY_SAME];
      SUBGOAL_THEN
       `eindom D (E:A->A->bool) s' b <=> eindom D E s b`
      (fun th -> REWRITE_TAC[th]) THENL
       [REWRITE_TAC[eindom] THEN
        ASM_MESON_TAC[EUPDATE_APPLY_OTHER];
        ASM_MESON_TAC[edomain]]];
    MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    ASM_CASES_TAC `b:A = a` THENL
     [SUBGOAL_THEN `w:A = u` SUBST1_TAC THENL
       [ASM_MESON_TAC[EUPDATE_APPLY_SAME]; ASM_REWRITE_TAC[]];
      ASM_MESON_TAC[EUPDATE_APPLY_OTHER]]]);;

(* ------------------------------------------------------------------------- *)
(* The update operation as an object formula, as used inside the             *)
(* satisfaction-step formula: update_form i j k l says v(l) is v(i) with     *)
(* position v(j) remapped to value v(k).                                     *)
(* ------------------------------------------------------------------------- *)

let HOLDS_UPDATE_FORM = prove
 (`!D (E:A->A->bool) v i j k l.
        valuation D v
        ==> (holds D E v (update_form i j k l) <=>
             eupdate D E (v i) (v j) (v k) (v l))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[update_form; holds; HOLDS_IFF; HOLDS_OR; HOLDS_AND;
              HOLDS_NOT; HOLDS_EX] THEN
  REWRITE_TAC[eupdate] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(l = MAX (MAX i j) (MAX k l) + 1) /\
     ~(i = MAX (MAX i j) (MAX k l) + 1)`] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!z:A. z IN D ==> (P z <=> Q z))
     ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((e <=> x) <=> (e <=> y))`) THEN
  SUBGOAL_THEN
   `valuation D (((MAX (MAX i j) (MAX k l) + 1) |-> (z:A)) v)`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E (((MAX (MAX i j) (MAX k l) + 1) |-> (z:A)) v)
          (opair_form j k (MAX (MAX i j) (MAX k l) + 1)) <=>
    eopair D E (v j) (v k) z`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(j = MAX (MAX i j) (MAX k l) + 1) /\
       ~(k = MAX (MAX i j) (MAX k l) + 1)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D
      ==> (holds D E
            (((MAX (MAX i j) (MAX k l) + 2) |-> b)
             (((MAX (MAX i j) (MAX k l) + 1) |-> (z:A)) v))
            (opair_form j (MAX (MAX i j) (MAX k l) + 2)
                        (MAX (MAX i j) (MAX k l) + 1)) <=>
           eopair D E (v j) b z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
        (((MAX (MAX i j) (MAX k l) + 2) |-> (b:A))
         (((MAX (MAX i j) (MAX k l) + 1) |-> z) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(j = MAX (MAX i j) (MAX k l) + 1) /\
       ~(j = MAX (MAX i j) (MAX k l) + 2) /\
       ~(MAX (MAX i j) (MAX k l) + 1 = MAX (MAX i j) (MAX k l) + 2)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(?b:A. b IN D /\
           holds D E
            (((MAX (MAX i j) (MAX k l) + 2) |-> b)
             (((MAX (MAX i j) (MAX k l) + 1) |-> z) v))
            (opair_form j (MAX (MAX i j) (MAX k l) + 2)
                        (MAX (MAX i j) (MAX k l) + 1))) <=>
    (?b:A. b IN D /\ eopair D (E:A->A->bool) (v j) b z)`
  (fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The semantics of the formula macros for the satisfaction machinery:       *)
(* internal numerals as formulas (by meta-recursion over the numeral),       *)
(* function application, membership in the union of the range of a set, and  *)
(* "the verdict-tagged pair <<c,s>,b> appears in some value of the history   *)
(* function g".                                                              *)
(* ------------------------------------------------------------------------- *)

let HOLDS_NAT_FORM_F = prove
 (`!k D (E:A->A->bool) v i.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (nat_form k i) <=> enat D E k (v i))`,
  INDUCT_TAC THEN REPEAT STRIP_TAC THEN REWRITE_TAC[nat_form; enat] THENL
   [ASM_MESON_TAC[HOLDS_EMPTY_FORM]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E (((i + 1) |-> a) v) (nat_form k (i + 1)) <=>
           enat D E k a) /\
          (holds D E (((i + 1) |-> a) v) (suc_form (i + 1) i) <=>
           esuc D E a (v i))`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((i + 1) |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_SUC_FORM_F] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let HOLDS_NAT_FORM = prove
 (`!k D (E:A->A->bool) v i.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (nat_form k i) <=> enat D E k (v i))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_NAT_FORM_F));;

let HOLDS_APPLY_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (apply_form i j k) <=>
             eapply D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[apply_form; HOLDS_EX; HOLDS_AND; holds; eapply] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E (((MAX (MAX i j) k + 1) |-> a) v)
                 (opair_form j k (MAX (MAX i j) k + 1)) <=>
           eopair D E (v j) (v k) a)`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((MAX (MAX i j) k + 1) |-> (a:A)) v)`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(j = MAX (MAX i j) k + 1) /\ ~(k = MAX (MAX i j) k + 1)`];
    ALL_TAC] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(i = MAX (MAX i j) k + 1)`] THEN
  ASM_MESON_TAC[EOPAIR_IN]);;

let eranmem = new_definition
  `eranmem D (E:A->A->bool) w g <=>
        ?val pr ord.
            val IN D /\ pr IN D /\ ord IN D /\
            E w val /\ eopair D E ord val pr /\ E pr g`;;

let HOLDS_RANMEM_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (ranmem_form i j) <=>
             eranmem D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ranmem_form; HOLDS_EX; HOLDS_AND; holds; eranmem] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(i = MAX i j + 1) /\ ~(i = MAX i j + 2) /\ ~(i = MAX i j + 3) /\
     ~(j = MAX i j + 1) /\ ~(j = MAX i j + 2) /\ ~(j = MAX i j + 3) /\
     ~(MAX i j + 1 = MAX i j + 2) /\ ~(MAX i j + 1 = MAX i j + 3) /\
     ~(MAX i j + 2 = MAX i j + 3)`] THEN
  SUBGOAL_THEN
   `!c d e:A. c IN D /\ d IN D /\ e IN D
      ==> (holds D E
            (((MAX i j + 3) |-> e) (((MAX i j + 2) |-> d)
             (((MAX i j + 1) |-> c) v)))
            (opair_form (MAX i j + 3) (MAX i j + 1) (MAX i j + 2)) <=>
           eopair D E e c d)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((MAX i j + 3) |-> (e:A)) (((MAX i j + 2) |-> d)
                   (((MAX i j + 1) |-> c) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX i j + 1 = MAX i j + 2) /\ ~(MAX i j + 1 = MAX i j + 3) /\
       ~(MAX i j + 2 = MAX i j + 3)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `d:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC))))) THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `d:A`; `e:A`] THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `vl:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ord:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let everdict = new_definition
  `everdict D (E:A->A->bool) c s b g <=>
        ?cs w. cs IN D /\ w IN D /\
               eopair D E c s cs /\ eopair D E cs b w /\
               eranmem D E w g`;;

let HOLDS_VERDICT_FORM = prove
 (`!D (E:A->A->bool) v i j k l.
        valuation D v
        ==> (holds D E v (verdict_form i j k l) <=>
             everdict D E (v i) (v j) (v k) (v l))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[verdict_form; HOLDS_EX; HOLDS_AND; everdict] THEN
  SUBGOAL_THEN
   `!cs w:A. cs IN D /\ w IN D
      ==> (holds D E
            (((MAX (MAX i j) (MAX k l) + 2) |-> w)
             (((MAX (MAX i j) (MAX k l) + 1) |-> cs) v))
            (opair_form i j (MAX (MAX i j) (MAX k l) + 1)) <=>
           eopair D E (v i) (v j) cs) /\
          (holds D E
            (((MAX (MAX i j) (MAX k l) + 2) |-> w)
             (((MAX (MAX i j) (MAX k l) + 1) |-> cs) v))
            (opair_form (MAX (MAX i j) (MAX k l) + 1) k
                        (MAX (MAX i j) (MAX k l) + 2)) <=>
           eopair D E cs (v k) w) /\
          (holds D E
            (((MAX (MAX i j) (MAX k l) + 2) |-> w)
             (((MAX (MAX i j) (MAX k l) + 1) |-> cs) v))
            (ranmem_form (MAX (MAX i j) (MAX k l) + 2) l) <=>
           eranmem D E w (v l))`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    (SUBGOAL_THEN
      `valuation D
         (((MAX (MAX i j) (MAX k l) + 2) |-> (w:A))
          (((MAX (MAX i j) (MAX k l) + 1) |-> cs) v))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC]) THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_RANMEM_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(i = MAX (MAX i j) (MAX k l) + 1) /\
       ~(i = MAX (MAX i j) (MAX k l) + 2) /\
       ~(j = MAX (MAX i j) (MAX k l) + 1) /\
       ~(j = MAX (MAX i j) (MAX k l) + 2) /\
       ~(k = MAX (MAX i j) (MAX k l) + 1) /\
       ~(k = MAX (MAX i j) (MAX k l) + 2) /\
       ~(l = MAX (MAX i j) (MAX k l) + 1) /\
       ~(l = MAX (MAX i j) (MAX k l) + 2) /\
       ~(MAX (MAX i j) (MAX k l) + 1 = MAX (MAX i j) (MAX k l) + 2)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `cs:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`cs:A`; `w:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `cs:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The five Tarski cases of the satisfaction step, one per form constructor. *)
(* Convention for the ambient variables at which these formulas sit inside   *)
(* satbody_form: 0 = history function g, 2 = structure x, 6 = verdict bit,   *)
(* 8 = internal valuation s, 9 = constructor tag, 10 = constructor data.     *)
(* A pair <<c,s>,b> is admitted when b is the correct verdict (1/0 = coded   *)
(* formula true/false at s), with subformula verdicts looked up in the       *)
(* range of the history g of earlier stages.                                 *)
(* ------------------------------------------------------------------------- *)

let esatfalse = new_definition
  `esatfalse D (E:A->A->bool) bit tag data <=>
        enat D E 0 tag /\ data = tag /\ enat D E 0 bit`;;

let HOLDS_SATFALSE_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v satfalse_form <=>
             esatfalse D E (v 6) (v 9) (v 10))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[satfalse_form; esatfalse; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN MESON_TAC[]);;

let HOLDS_SATFALSE_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v satfalse_form <=>
             esatfalse D E (v 6) (v 9) (v 10))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SATFALSE_FORM_F));;

let esatmem = new_definition
  `esatmem D (E:A->A->bool) bit s tag data <=>
        enat D E 1 tag /\
        ?a b sa sb.
            a IN D /\ b IN D /\ sa IN D /\ sb IN D /\
            eopair D E a b data /\
            eapply D E s a sa /\ eapply D E s b sb /\
            (enat D E 1 bit /\ E sa sb \/
             enat D E 0 bit /\ ~E sa sb)`;;

let esateq = new_definition
  `esateq D (E:A->A->bool) bit s tag data <=>
        enat D E 2 tag /\
        ?a b sa sb.
            a IN D /\ b IN D /\ sa IN D /\ sb IN D /\
            eopair D E a b data /\
            eapply D E s a sa /\ eapply D E s b sb /\
            (enat D E 1 bit /\ sa = sb \/
             enat D E 0 bit /\ ~(sa = sb))`;;

let HOLDS_SATMEM_FORM_F,HOLDS_SATEQ_FORM_F = (CONJ_PAIR o prove)
 (`(!D (E:A->A->bool) v.
         model D E zfw_ax /\ valuation D v
         ==> (holds D E v satmem_form <=>
              esatmem D E (v 6) (v 8) (v 9) (v 10))) /\
   (!D (E:A->A->bool) v.
         model D E zfw_ax /\ valuation D v
         ==> (holds D E v sateq_form <=>
              esateq D E (v 6) (v 8) (v 9) (v 10)))`,
  CONJ_TAC THEN
  (REPEAT STRIP_TAC THEN
   SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
    [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
   REWRITE_TAC[satmem_form; sateq_form; esatmem; esateq; HOLDS_EX; HOLDS_AND;
               HOLDS_OR; HOLDS_NOT; holds] THEN
   ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN
   REWRITE_TAC[VALMOD; ARITH_EQ] THEN
   MATCH_MP_TAC(TAUT `(x <=> y) ==> ((a /\ x) <=> (a /\ y))`) THEN
   SUBGOAL_THEN
    `!a b sa sb:A. a IN D /\ b IN D /\ sa IN D /\ sb IN D
       ==> (holds D E ((14 |-> sb) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))
                  (opair_form 11 12 10) <=>
            eopair D E a b (v 10)) /\
           (holds D E ((14 |-> sb) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))
                  (apply_form 8 11 13) <=>
            eapply D E (v 8) a sa) /\
           (holds D E ((14 |-> sb) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))
                  (apply_form 8 12 14) <=>
            eapply D E (v 8) b sb) /\
           (holds D E ((14 |-> sb) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))
                  (nat_form 1 6) <=>
            enat D E 1 (v 6)) /\
           (holds D E ((14 |-> sb) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))
                  (nat_form 0 6) <=>
            enat D E 0 (v 6))`
   (LABEL_TAC "piles") THENL
    [REPEAT GEN_TAC THEN DISCH_TAC THEN
     SUBGOAL_THEN
      `valuation D
        ((14 |-> (sb:A)) ((13 |-> sa) ((12 |-> b) ((11 |-> a) v))))`
     ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
     ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_APPLY_FORM; HOLDS_NAT_FORM_F] THEN
     REWRITE_TAC[VALMOD; ARITH_EQ];
     ALL_TAC] THEN
   EQ_TAC THENL
    [INTRO_TAC "@a. h1 @b. h2 @sa. h3 @sb. h4 +" THEN
     USE_THEN "piles" (fun th -> MP_TAC(SPECL
       [`a:A`; `b:A`; `sa:A`; `sb:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
     MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `sa:A`; `sb:A`] THEN
     ASM_REWRITE_TAC[];
     DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
       (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sb:A`
         (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
     EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
     EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
     EXISTS_TAC `sa:A` THEN ASM_REWRITE_TAC[] THEN
     EXISTS_TAC `sb:A` THEN ASM_REWRITE_TAC[] THEN
     USE_THEN "piles" (fun th -> MP_TAC(SPECL
       [`a:A`; `b:A`; `sa:A`; `sb:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[]]));;

let HOLDS_SATMEM_FORM,HOLDS_SATEQ_FORM = (CONJ_PAIR o prove)
 (`(!D (E:A->A->bool) v.
         model D E ZF_AX /\ valuation D v
         ==> (holds D E v satmem_form <=>
              esatmem D E (v 6) (v 8) (v 9) (v 10))) /\
   (!D (E:A->A->bool) v.
         model D E ZF_AX /\ valuation D v
         ==> (holds D E v sateq_form <=>
              esateq D E (v 6) (v 8) (v 9) (v 10)))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW (CONJ HOLDS_SATMEM_FORM_F HOLDS_SATEQ_FORM_F)));;

let esatimp = new_definition
  `esatimp D (E:A->A->bool) bit s tag data g <=>
        enat D E 3 tag /\
        ?c1 c2 zero one.
            c1 IN D /\ c2 IN D /\ zero IN D /\ one IN D /\
            eopair D E c1 c2 data /\
            enat D E 0 zero /\ enat D E 1 one /\
            (enat D E 1 bit /\
             (everdict D E c1 s zero g \/ everdict D E c2 s one g) \/
             enat D E 0 bit /\
             everdict D E c1 s one g /\ everdict D E c2 s zero g)`;;

let HOLDS_SATIMP_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v satimp_form <=>
             esatimp D E (v 6) (v 8) (v 9) (v 10) (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[satimp_form; esatimp; HOLDS_EX; HOLDS_AND; HOLDS_OR;
              HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((a /\ x) <=> (a /\ y))`) THEN
  SUBGOAL_THEN
   `!c1 c2 z0 z1:A.
        c1 IN D /\ c2 IN D /\ z0 IN D /\ z1 IN D
      ==> (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (opair_form 11 12 10) <=>
           eopair D E c1 c2 (v 10)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (nat_form 0 13) <=>
           enat D E 0 z0) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (nat_form 1 14) <=>
           enat D E 1 z1) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (nat_form 1 6) <=>
           enat D E 1 (v 6)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (nat_form 0 6) <=>
           enat D E 0 (v 6)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (verdict_form 11 8 13 0) <=>
           everdict D E c1 (v 8) z0 (v 0)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (verdict_form 12 8 14 0) <=>
           everdict D E c2 (v 8) z1 (v 0)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (verdict_form 11 8 14 0) <=>
           everdict D E c1 (v 8) z1 (v 0)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))
            (verdict_form 12 8 13 0) <=>
           everdict D E c2 (v 8) z0 (v 0))`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((14 |-> (z1:A)) ((13 |-> z0) ((12 |-> c2) ((11 |-> c1) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_VERDICT_FORM; HOLDS_NAT_FORM_F] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@c1. h1 @c2. h2 @z0. h3 @z1. h4 +" THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`c1:A`; `c2:A`; `z0:A`; `z1:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`c1:A`; `c2:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `c2:A`
      (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
    EXISTS_TAC `c1:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c2:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z1:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`c1:A`; `c2:A`; `z0:A`; `z1:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_SATIMP_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v satimp_form <=>
             esatimp D E (v 6) (v 8) (v 9) (v 10) (v 0))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SATIMP_FORM_F));;

let esatall = new_definition
  `esatall D (E:A->A->bool) bit s tag data g x <=>
        enat D E 4 tag /\
        ?a c1 z0 z1.
            a IN D /\ c1 IN D /\ z0 IN D /\ z1 IN D /\
            eopair D E a c1 data /\
            enat D E 0 z0 /\ enat D E 1 z1 /\
            (enat D E 1 bit /\
             (!u. u IN D /\ E u x
                  ==> !s'. s' IN D /\ eupdate D E s a u s'
                           ==> everdict D E c1 s' z1 g) \/
             enat D E 0 bit /\
             (?u. u IN D /\ E u x /\
                  ?s'. s' IN D /\ eupdate D E s a u s' /\
                       everdict D E c1 s' z0 g))`;;

let HOLDS_SATALL_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v satall_form <=>
             esatall D E (v 6) (v 8) (v 9) (v 10) (v 0) (v 2))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[satall_form; esatall; HOLDS_EX; HOLDS_AND; HOLDS_OR;
              HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((a /\ x) <=> (a /\ y))`) THEN
  SUBGOAL_THEN
   `!a c1 z0 z1:A.
        a IN D /\ c1 IN D /\ z0 IN D /\ z1 IN D
      ==> (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (opair_form 11 12 10) <=>
           eopair D E a c1 (v 10)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (nat_form 0 13) <=>
           enat D E 0 z0) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (nat_form 1 14) <=>
           enat D E 1 z1) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (nat_form 1 6) <=>
           enat D E 1 (v 6)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (nat_form 0 6) <=>
           enat D E 0 (v 6)) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (!!- 15 2 (!! 16 (update_form 8 11 15 16 -->
                              verdict_form 12 16 14 0))) <=>
           (!u. u IN D /\ E u (v 2)
                ==> !s'. s' IN D /\ eupdate D E (v 8) a u s'
                         ==> everdict D E c1 s' z1 (v 0))) /\
          (holds D E
            ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))
            (??- 15 2 (?? 16 (update_form 8 11 15 16 &&
                              verdict_form 12 16 13 0))) <=>
           (?u. u IN D /\ E u (v 2) /\
                ?s'. s' IN D /\ eupdate D E (v 8) a u s' /\
                     everdict D E c1 s' z0 (v 0)))`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((14 |-> (z1:A)) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!u s':A. u IN D /\ s' IN D
        ==> (holds D E
              ((16 |-> s') ((15 |-> u)
               ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))))
              (update_form 8 11 15 16) <=>
             eupdate D E (v 8) a u s') /\
            (holds D E
              ((16 |-> s') ((15 |-> u)
               ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))))
              (verdict_form 12 16 14 0) <=>
             everdict D E c1 s' z1 (v 0)) /\
            (holds D E
              ((16 |-> s') ((15 |-> u)
               ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))))
              (verdict_form 12 16 13 0) <=>
             everdict D E c1 s' z0 (v 0))`
    (LABEL_TAC "inner") THENL
     [REPEAT GEN_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D
         ((16 |-> (s':A)) ((15 |-> u)
          ((14 |-> z1) ((13 |-> z0) ((12 |-> c1) ((11 |-> a) v))))))`
      ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_UPDATE_FORM; HOLDS_VERDICT_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_NAT_FORM_F] THEN REWRITE_TAC[VALMOD; ARITH_EQ];
      ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(15 = 2)`] THEN
      REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
      ASM_MESON_TAC[];
      ASM_SIMP_TAC[HOLDS_EXISTSMEM; ARITH_RULE `~(15 = 2)`] THEN
      REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a. h1 @c1. h2 @z0. h3 @z1. h4 +" THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`a:A`; `c1:A`; `z0:A`; `z1:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `c1:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `c1:A`
      (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c1:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z1:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`a:A`; `c1:A`; `z0:A`; `z1:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_SATALL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v satall_form <=>
             esatall D E (v 6) (v 8) (v 9) (v 10) (v 0) (v 2))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SATALL_FORM_F));;

(* ------------------------------------------------------------------------- *)
(* The full Tarski clause: z = <<c,s>,bit> is a correctly-decided verdict    *)
(* given the history g, in the structure x. Then the satisfaction step:      *)
(* y = the set of all such z inside the ambient universe u2 (which will be   *)
(* (hfset CROSS efuns omega x) CROSS 2). This is the recursion data for the  *)
(* stagewise definition of internal satisfaction, with parameter convention  *)
(* 0 = input history g, 1 = output stage y, 2 = structure x, 3 = u2.         *)
(* ------------------------------------------------------------------------- *)

let esatbody = new_definition
  `esatbody D (E:A->A->bool) x g z <=>
        ?cs bit c s.
            cs IN D /\ bit IN D /\ c IN D /\ s IN D /\
            eopair D E cs bit z /\ eopair D E c s cs /\
            ?tag data.
                tag IN D /\ data IN D /\ eopair D E tag data c /\
                (esatfalse D E bit tag data \/
                 esatmem D E bit s tag data \/
                 esateq D E bit s tag data \/
                 esatimp D E bit s tag data g \/
                 esatall D E bit s tag data g x)`;;

let HOLDS_SATBODY_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v satbody_form <=>
             esatbody D E (v 2) (v 0) (v 4))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[satbody_form; esatbody; HOLDS_EX; HOLDS_AND; HOLDS_OR] THEN
  SUBGOAL_THEN
   `!cs bit c s:A. cs IN D /\ bit IN D /\ c IN D /\ s IN D
      ==> (holds D E ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))
                 (opair_form 5 6 4) <=>
           eopair D E cs bit (v 4)) /\
          (holds D E ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))
                 (opair_form 7 8 5) <=>
           eopair D E c s cs)`
  (LABEL_TAC "lev1") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((8 |-> (s:A)) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!cs bit c s tag data:A.
        cs IN D /\ bit IN D /\ c IN D /\ s IN D /\
        tag IN D /\ data IN D
      ==> (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            (opair_form 9 10 7) <=>
           eopair D E tag data c) /\
          (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            satfalse_form <=>
           esatfalse D E bit tag data) /\
          (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            satmem_form <=>
           esatmem D E bit s tag data) /\
          (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            sateq_form <=>
           esateq D E bit s tag data) /\
          (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            satimp_form <=>
           esatimp D E bit s tag data (v 0)) /\
          (holds D E
            ((10 |-> data) ((9 |-> tag)
             ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))
            satall_form <=>
           esatall D E bit s tag data (v 0) (v 2))`
  (LABEL_TAC "lev2") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((10 |-> (data:A)) ((9 |-> tag)
        ((8 |-> s) ((7 |-> c) ((6 |-> bit) ((5 |-> cs) v))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM; HOLDS_SATFALSE_FORM_F;
                 HOLDS_SATMEM_FORM_F; HOLDS_SATEQ_FORM_F;
                 HOLDS_SATIMP_FORM_F; HOLDS_SATALL_FORM_F] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@cs. h1 @bit. h2 @c. h3 @s. h4 +" THEN
    USE_THEN "lev1" (fun th -> MP_TAC(SPECL
      [`cs:A`; `bit:A`; `c:A`; `s:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    INTRO_TAC "@tag. h5 @data. h6 +" THEN
    USE_THEN "lev2" (fun th -> MP_TAC(SPECL
      [`cs:A`; `bit:A`; `c:A`; `s:A`; `tag:A`; `data:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    MAP_EVERY EXISTS_TAC [`cs:A`; `bit:A`; `c:A`; `s:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `bit:A`
      (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
            (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
              (X_CHOOSE_THEN `tag:A` (X_CHOOSE_THEN `data:A`
                (fun th ->
                   MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))))))))))) THEN
    EXISTS_TAC `cs:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `bit:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "lev1" (fun th -> MP_TAC(SPECL
      [`cs:A`; `bit:A`; `c:A`; `s:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `tag:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `data:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "lev2" (fun th -> MP_TAC(SPECL
      [`cs:A`; `bit:A`; `c:A`; `s:A`; `tag:A`; `data:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_SATBODY_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v satbody_form <=>
             esatbody D E (v 2) (v 0) (v 4))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SATBODY_FORM_F));;

let satstep = new_definition
  `satstep D (E:A->A->bool) x u2 g y <=>
        y IN D /\
        !w. w IN D ==> (E w y <=> E w u2 /\ esatbody D E x g w)`;;

let HOLDS_SATSTEP_FORM_F = prove
 (`!D (E:A->A->bool) v g y.
      model D E zfw_ax /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) satstep_form <=>
           satstep D E (v 2) (v 3) g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[satstep_form; holds; HOLDS_IFF; HOLDS_AND; satstep] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!w:A. w IN D ==> (P w <=> Q w))
     ==> ((!w. w IN D ==> P w) <=> (!w. w IN D ==> Q w))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
    `(x <=> y) ==> ((e <=> a /\ x) <=> (e <=> a /\ y))`) THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (w:A)) ((1 |-> y) ((0 |-> g) v)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_SATBODY_FORM_F] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

let HOLDS_SATSTEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) satstep_form <=>
           satstep D E (v 2) (v 3) g y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SATSTEP_FORM_F));;

let SATSTEP_FUN_F = prove
 (`!D (E:A->A->bool) x u2 g y y'.
        model D E zfw_ax /\ satstep D E x u2 g y /\ satstep D E x u2 g y'
        ==> y = y'`,
  REWRITE_TAC[satstep] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let SATSTEP_FUN = prove
 (`!D (E:A->A->bool) x u2 g y y'.
        model D E ZF_AX /\ satstep D E x u2 g y /\ satstep D E x u2 g y'
        ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW SATSTEP_FUN_F));;

let SATSTEP_TOTAL_F = prove
 (`!D (E:A->A->bool) x u2 g.
      model D E zfw_ax /\ x IN D /\ u2 IN D /\ g IN D
      ==> ?y. satstep D E x u2 g y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((0 |-> (g:A)) ((2 |-> x) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`satbody_form`; `4`; `(0 |-> (g:A)) ((2 |-> x) v0)`; `u2:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[satstep] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (w:A)) ((0 |-> g) ((2 |-> x) v0)))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_SATBODY_FORM_F] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ]);;

let SATSTEP_TOTAL = prove
 (`!D (E:A->A->bool) x u2 g.
      model D E ZF_AX /\ x IN D /\ u2 IN D /\ g IN D
      ==> ?y. satstep D E x u2 g y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW SATSTEP_TOTAL_F));;

let SATSTEP_QFUN_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) satstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) satstep_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC SATSTEP_FUN_F THEN
  MAP_EVERY EXISTS_TAC
   [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`; `(v:num->A) 3`;
    `r:A`] THEN
  ASM_MESON_TAC[HOLDS_SATSTEP_FORM_F]);;

let SATSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) satstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) satstep_form
                     ==> w = w'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW SATSTEP_QFUN_F));;

let SATSTEP_QTOTAL_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) satstep_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) 2`;
                `(v:num->A) 3`; `x:A`] SATSTEP_TOTAL_F) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[satstep]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_SATSTEP_FORM_F]);;

let SATSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) satstep_form`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW SATSTEP_QTOTAL_F));;

(* ------------------------------------------------------------------------- *)
(* The satisfaction stages: the universe u2 = (hfset CROSS efuns om x)       *)
(* CROSS 2 for the structure x (unique given x), and the stage function      *)
(* defined by the recursion theorem applied to satstep_form with the         *)
(* parameters plumbed through the ambient valuation at slots 2,3. Finally    *)
(* esat: some stage indexed by a member of omega contains the verdict-1      *)
(* tagged pair <<c,s>,1>.                                                    *)
(* ------------------------------------------------------------------------- *)

let esatuniv = new_definition
  `esatuniv D (E:A->A->bool) x u <=>
        ?om hf vs cs two.
            om IN D /\ hf IN D /\ vs IN D /\ cs IN D /\ two IN D /\
            eomega D E om /\ ehfset D E om hf /\ efuns D E om x vs /\
            ecross D E hf vs cs /\ enat D E 2 two /\
            ecross D E cs two u`;;

let ESATUNIV_IN = prove
 (`!D (E:A->A->bool) x u. esatuniv D E x u ==> u IN D`,
  REWRITE_TAC[esatuniv; ecross] THEN MESON_TAC[]);;

let ESATUNIV_EXISTS_F = prove
 (`!D (E:A->A->bool) x.
        model D E zfw_ax /\ x IN D ==> ?u. esatuniv D E x u`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esatuniv] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] EOMEGA_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `om:A`) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] EHFSET_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `hf:A`) THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`]
        EFUNS_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `vs:A`) THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`]
        ECROSS_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cs:A`) THEN
  SUBGOAL_THEN `(cs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `2`] ENAT_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `two:A`) THEN
  SUBGOAL_THEN `(two:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs:A`; `two:A`]
        ECROSS_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u:A`) THEN
  MAP_EVERY EXISTS_TAC
   [`u:A`; `om:A`; `hf:A`; `vs:A`; `cs:A`; `two:A`] THEN
  ASM_REWRITE_TAC[]);;

let ESATUNIV_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN D ==> ?u. esatuniv D E x u`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATUNIV_EXISTS_F));;

let ESATUNIV_UNIQUE_F = prove
 (`!D (E:A->A->bool) x u u'.
        model D E zfw_ax /\ esatuniv D E x u /\ esatuniv D E x u'
        ==> u = u'`,
  REWRITE_TAC[esatuniv] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `hf':A = hf` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSET_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `vs':A = vs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `cs':A = cs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ECROSS_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `two':A = two` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE_F]; ALL_TAC] THEN
  ASM_MESON_TAC[ECROSS_UNIQUE_F]);;

let ESATUNIV_UNIQUE = prove
 (`!D (E:A->A->bool) x u u'.
        model D E ZF_AX /\ esatuniv D E x u /\ esatuniv D E x u'
        ==> u = u'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATUNIV_UNIQUE_F));;

let esatstage = new_definition
  `esatstage D (E:A->A->bool) x n t <=>
        ?v u2. valuation D v /\ v 2 = x /\ v 3 = u2 /\
               esatuniv D E x u2 /\
               erec D E satstep_form v n t`;;

let ESATSTAGE_EREC_F = prove
 (`!D (E:A->A->bool) x u2 n t v.
        model D E zfw_ax /\ valuation D v /\ v 2 = x /\ v 3 = u2 /\
        esatuniv D E x u2
        ==> (esatstage D E x n t <=> erec D E satstep_form v n t)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esatstage] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` (X_CHOOSE_THEN `u2':A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `u2':A = u2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ESATUNIV_UNIQUE_F]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) satstep_form v' n t <=>
      erec D E satstep_form v n t`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(REWRITE_RULE[SUBSET] FV_SATSTEP_FORM) THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN MAP_EVERY EXISTS_TAC [`v:num->A`; `u2:A`] THEN
    ASM_REWRITE_TAC[]]);;

let ESATSTAGE_EREC = prove
 (`!D (E:A->A->bool) x u2 n t v.
        model D E ZF_AX /\ valuation D v /\ v 2 = x /\ v 3 = u2 /\
        esatuniv D E x u2
        ==> (esatstage D E x n t <=> erec D E satstep_form v n t)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_EREC_F));;

let ESATSTAGE_UNIQUE_F = prove
 (`!D (E:A->A->bool) x n t t'.
        model D E zfw_ax /\ n IN D /\ t IN D /\ t' IN D /\
        esatstage D E x n t /\ esatstage D E x n t'
        ==> t = t'`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `v:num->A` (X_CHOOSE_THEN `u2:A`
    STRIP_ASSUME_TAC) o GEN_REWRITE_RULE I [esatstage] o
    check (fun th -> rand(concl th) = `t':A`)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `satstep_form`;
                `v:num->A`; `n:A`; `t:A`; `t':A`] EREC_UNIQUE_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`]
        SATSTEP_QFUN_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u2:A`;
                `n:A`; `t:A`; `v:num->A`] ESATSTAGE_EREC_F) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let ESATSTAGE_UNIQUE = prove
 (`!D (E:A->A->bool) x n t t'.
        model D E ZF_AX /\ n IN D /\ t IN D /\ t' IN D /\
        esatstage D E x n t /\ esatstage D E x n t'
        ==> t = t'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_UNIQUE_F));;

let ESATSTAGE_EXISTS_F = prove
 (`!D (E:A->A->bool) x n.
        model D E zfw_ax /\ x IN D /\ eordinal D E n
        ==> ?t. t IN D /\ esatstage D E x n t`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] ESATUNIV_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((3 |-> (u2:A)) ((2 |-> x) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((3 |-> (u2:A)) ((2 |-> x) v0)) 2 = x /\
    ((3 |-> (u2:A)) ((2 |-> x) v0)) 3 = u2`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `satstep_form`;
                `(3 |-> (u2:A)) ((2 |-> x) v0)`; `n:A`; `5`; `20`]
        EREC_EXISTS_F) THEN
  ASM_REWRITE_TAC[ENGINE_READY_SATSTEP] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[SATSTEP_QFUN_F; SATSTEP_QTOTAL_F]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u2:A`;
                `n:A`; `t:A`; `(3 |-> (u2:A)) ((2 |-> x) v0)`]
        ESATSTAGE_EREC_F) THEN
  ASM_REWRITE_TAC[]);;

let ESATSTAGE_EXISTS = prove
 (`!D (E:A->A->bool) x n.
        model D E ZF_AX /\ x IN D /\ eordinal D E n
        ==> ?t. t IN D /\ esatstage D E x n t`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_EXISTS_F));;

let ESATSTAGE_CHAR_F = prove
 (`!D (E:A->A->bool) x n t.
      model D E zfw_ax /\ x IN D /\ eordinal D E n /\ t IN D /\
      esatstage D E x n t
      ==> ?u2 r. esatuniv D E x u2 /\ r IN D /\
                 (!w. w IN D
                      ==> (E w r <=>
                           ?b y. b IN D /\ y IN D /\ E b n /\
                                 esatstage D E x b y /\
                                 eopair D E b y w)) /\
                 satstep D E x u2 r t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(n:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `v:num->A` (X_CHOOSE_THEN `u2:A`
    STRIP_ASSUME_TAC) o GEN_REWRITE_RULE I [esatstage]) THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) satstep_form v n r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS_F THEN
    MAP_EVERY EXISTS_TAC [`5`; `20`] THEN
    ASM_REWRITE_TAC[ENGINE_READY_SATSTEP] THEN
    ASM_MESON_TAC[SATSTEP_QFUN_F; SATSTEP_QTOTAL_F];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `satstep D (E:A->A->bool) x u2 r t` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `t:A`]
          HOLDS_SATSTEP_FORM_F) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION_F THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[SATSTEP_QFUN_F];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b y:A. erec D (E:A->A->bool) satstep_form v b y <=>
            esatstage D E x b y`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[ESATSTAGE_EREC_F]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`u2:A`; `r:A`] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  MP_TAC(SPEC `w:A` (CONJUNCT2(REWRITE_RULE[erecres]
    (ASSUME `erecres D (E:A->A->bool) satstep_form v n r`)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let ESATSTAGE_CHAR = prove
 (`!D (E:A->A->bool) x n t.
      model D E ZF_AX /\ x IN D /\ eordinal D E n /\ t IN D /\
      esatstage D E x n t
      ==> ?u2 r. esatuniv D E x u2 /\ r IN D /\
                 (!w. w IN D
                      ==> (E w r <=>
                           ?b y. b IN D /\ y IN D /\ E b n /\
                                 esatstage D E x b y /\
                                 eopair D E b y w)) /\
                 satstep D E x u2 r t`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_CHAR_F));;

let esat = new_definition
  `esat D (E:A->A->bool) x c s <=>
        ?om n t z1 cs w.
            om IN D /\ n IN D /\ t IN D /\ z1 IN D /\ cs IN D /\
            w IN D /\
            eomega D E om /\ E n om /\ esatstage D E x n t /\
            enat D E 1 z1 /\ eopair D E c s cs /\ eopair D E cs z1 w /\
            E w t`;;

(* ------------------------------------------------------------------------- *)
(* Structural facts about numerals, omega and the hf universe needed for     *)
(* the absoluteness bridge: membership of numerals, transitivity and         *)
(* directedness of omega, monotonicity of the V-stages, closure of hfset     *)
(* under pairing, and the payoff that every formula code lies in hfset.      *)
(* ------------------------------------------------------------------------- *)

let ESUC_E = prove
 (`!D (E:A->A->bool) y s w.
        model D E ZF_AX /\ y IN D /\ s IN D /\ w IN D /\ esuc D E y s
        ==> (E w s <=> E w y \/ w = y)`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esuc]) THEN
  DISCH_THEN(X_CHOOSE_THEN `sg:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w s <=> E w y \/ E w sg`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[EBUNION_ALT]; ALL_TAC] THEN
  ASM_MESON_TAC[epair]);;

let ENAT_MEMBERS = prove
 (`!k D (E:A->A->bool) nk w.
        model D E ZF_AX /\ enat D E k nk /\ w IN D
        ==> (E w nk <=> ?j. j < k /\ enat D E j w)`,
  INDUCT_TAC THEN REPEAT STRIP_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [enat]) THEN
    REWRITE_TAC[eempty] THEN ASM_MESON_TAC[ARITH_RULE `~(j < 0)`];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [enat] o
    check (fun th -> can (find_term (fun t -> t = `SUC k`)) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) w nk <=> E w y \/ w = y`
  (fun th -> REWRITE_TAC[th]) THENL
   [MATCH_MP_TAC ESUC_E THEN ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w y <=> ?j. j < k /\ enat D E j w`
  (fun th -> REWRITE_TAC[th]) THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [STRIP_TAC THENL
     [EXISTS_TAC `j:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
      EXISTS_TAC `k:num` THEN ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC];
    DISCH_THEN(X_CHOOSE_THEN `j:num` STRIP_ASSUME_TAC) THEN
    ASM_CASES_TAC `j:num = k` THENL
     [DISJ2_TAC THEN ASM_MESON_TAC[ENAT_UNIQUE];
      DISJ1_TAC THEN EXISTS_TAC `j:num` THEN
      ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC]]);;

let ENAT_IN_OMEGA = prove
 (`!k D (E:A->A->bool) om nk.
        model D E ZF_AX /\ eomega D E om /\ enat D E k nk
        ==> E nk om`,
  INDUCT_TAC THEN REPEAT STRIP_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [enat]) THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eomega]) THEN
    REWRITE_TAC[einductive] THEN ASM_MESON_TAC[EEMPTY_UNIQUE];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [enat] o
    check (fun th -> can (find_term (fun t -> t = `SUC k`)) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) y om` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eomega]) THEN
  REWRITE_TAC[einductive] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `y:A` o check (fun th ->
    can (find_term
      (fun t -> t = `esuc:(A->bool)->(A->A->bool)->A->A->bool`))
      (concl th) &&
    not(can (find_term
      (fun t -> t = `esubset:(A->bool)->(A->A->bool)->A->A->bool`))
      (concl th)))) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `nk:A = s` SUBST1_TAC THENL
   [ASM_MESON_TAC[ESUC_UNIQUE; ESUC_IN]; ASM_REWRITE_TAC[]]);;

let ENAT_MEM_LT = prove
 (`!D (E:A->A->bool) j k nj nk.
        model D E ZF_AX /\ j < k /\ enat D E j nj /\ enat D E k nk
        ==> E nj nk`,
  ASM_MESON_TAC[ENAT_MEMBERS; ENAT_IN]);;

let EOMEGA_TRANS = prove
 (`!D (E:A->A->bool) om n b.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ b IN D /\ E b n
        ==> E b om`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (om:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `subset_form 0 1`;
                `0`; `(1 |-> (om:A)) v0`] EOMEGA_INDUCT) THEN
  ASM_REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[eempty];
      REPEAT STRIP_TAC THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) w u \/ w = u` MP_TAC THENL
       [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
      ASM_MESON_TAC[esubset]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[esubset]);;

let EHFSTAGE_MONO = prove
 (`!D (E:A->A->bool) m n ym yn u.
        model D E ZF_AX /\ eordinal D E m /\ eordinal D E n /\
        E m n /\ ym IN D /\ yn IN D /\
        ehfstage D E m ym /\ ehfstage D E n yn /\
        u IN D /\ E u ym
        ==> E u yn`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D /\ (n:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `ym:A`]
        EHFSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `yn:A`]
        EHFSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `u:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) m n` MP_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN ASM_MESON_TAC[]);;

let EHFSET_E = prove
 (`!D (E:A->A->bool) om hf u.
        ehfset D E om hf /\ u IN D
        ==> (E u hf <=>
             ?n y. n IN D /\ y IN D /\ E n om /\
                   ehfstage D E n y /\ E u y)`,
  REWRITE_TAC[ehfset] THEN MESON_TAC[]);;

let EOMEGA_DIRECTED = prove
 (`!D (E:A->A->bool) om nu nw.
        model D E ZF_AX /\ eomega D E om /\
        nu IN D /\ E nu om /\ nw IN D /\ E nw om
        ==> ?k. k IN D /\ E k om /\ E nu k /\ E nw k`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nu /\ eordinal D E nw`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?b:A. b IN D /\ E b om /\ (E nu b \/ nu = b) /\ (E nw b \/ nw = b)`
  (X_CHOOSE_THEN `b:A` (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))
  THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nu:A`; `nw:A`]
          EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [EXISTS_TAC `nw:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `nw:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `nu:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?s:A. esuc D (E:A->A->bool) b s /\ E s om`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  EXISTS_TAC `s:A` THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ESUC_E]);;

let EHFSET_PAIR = prove
 (`!D (E:A->A->bool) om hf u w p.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        u IN D /\ w IN D /\ E u hf /\ E w hf /\ epair D E u w p
        ==> E p hf`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `u:A`]
        EHFSET_E) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `nu:A` (X_CHOOSE_THEN `yu:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `w:A`]
        EHFSET_E) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `nw:A` (X_CHOOSE_THEN `yw:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `nu:A`; `nw:A`]
        EOMEGA_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) nu /\ eordinal D E nw /\ eordinal D E k`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`] EHFSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `yk:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) u yk /\ E w yk` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nu:A`; `k:A`;
                    `yu:A`; `yk:A`; `u:A`] EHFSTAGE_MONO) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nw:A`; `k:A`;
                    `yw:A`; `yk:A`; `w:A`] EHFSTAGE_MONO) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) p yk` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `?s:A. esuc D (E:A->A->bool) k s /\ E s om`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) s` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`] EHFSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ys:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) p ys` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `ys:A`]
          EHFSTAGE_CHAR) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `p:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`k:A`; `yk:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ESUC_E; EORDINAL_IN];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `p:A`]
        EHFSET_E) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let EHFSET_OPAIR = prove
 (`!D (E:A->A->bool) om hf u w z.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        u IN D /\ w IN D /\ E u hf /\ E w hf /\ eopair D E u w z
        ==> E z hf`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair]) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  ASM_MESON_TAC[EHFSET_PAIR]);;

let ENAT_STAGE = prove
 (`!k D (E:A->A->bool) nk y j nj.
        model D E ZF_AX /\ enat D E k nk /\ ehfstage D E nk y /\
        y IN D /\ j < k /\ enat D E j nj
        ==> E nj y`,
  INDUCT_TAC THEN REPEAT STRIP_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `(nk:A) IN D /\ (nj:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nk` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?nk':A. enat D (E:A->A->bool) k nk'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(nk':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nk'` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_ORDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nk':A`]
        EHFSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `yk:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nk:A`; `y:A`]
        EHFSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `nj:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`nk':A`; `yk:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:num`; `SUC k`;
                  `nk':A`; `nk:A`] ENAT_MEM_LT) THEN
    ASM_REWRITE_TAC[ARITH_RULE `k < SUC k`];
    ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `?i. i < j /\ enat D (E:A->A->bool) i z`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_MEMBERS]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL
    [`D:A->bool`; `E:A->A->bool`; `nk':A`; `yk:A`; `i:num`; `z:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `i:num < k` (fun th -> REWRITE_TAC[th]) THEN
  ASM_ARITH_TAC);;

let ENAT_IN_HFSET = prove
 (`!k D (E:A->A->bool) om hf nk.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        enat D E k nk
        ==> E nk hf`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(nk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?ns:A. enat D (E:A->A->bool) (SUC k) ns`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(ns:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) ns` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_ORDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ns:A`]
        EHFSTAGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `ys:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) nk ys` ASSUME_TAC THENL
   [MP_TAC(SPECL [`SUC k`; `D:A->bool`; `E:A->A->bool`; `ns:A`;
                  `ys:A`; `k:num`; `nk:A`] ENAT_STAGE) THEN
    ASM_REWRITE_TAC[ARITH_RULE `k < SUC k`];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `nk:A`]
        EHFSET_E) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`ns:A`; `ys:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ENAT_IN_OMEGA]);;

let ECODE_IN_HFSET = prove
 (`!p D (E:A->A->bool) om hf c.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        ecode D E p c
        ==> E c hf`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REPEAT GEN_TAC THEN REWRITE_TAC[ecode] THEN STRIP_TAC THEN
    ASM_MESON_TAC[ENAT_IN_HFSET; EHFSET_OPAIR; ENAT_IN];
    REPEAT GEN_TAC THEN REWRITE_TAC[ecode] THEN STRIP_TAC THEN
    ASM_MESON_TAC[ENAT_IN_HFSET; EHFSET_OPAIR; ENAT_IN; EOPAIR_IN];
    REPEAT GEN_TAC THEN REWRITE_TAC[ecode] THEN STRIP_TAC THEN
    ASM_MESON_TAC[ENAT_IN_HFSET; EHFSET_OPAIR; ENAT_IN; EOPAIR_IN];
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[ecode] THEN STRIP_TAC THEN
    ASM_MESON_TAC[ENAT_IN_HFSET; EHFSET_OPAIR; ENAT_IN; EOPAIR_IN;
                  ECODE_IN];
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
    REWRITE_TAC[ecode] THEN STRIP_TAC THEN
    ASM_MESON_TAC[ENAT_IN_HFSET; EHFSET_OPAIR; ENAT_IN; EOPAIR_IN;
                  ECODE_IN]]);;

(* ------------------------------------------------------------------------- *)
(* The shadow of an internal valuation: the meta-level valuation reading     *)
(* off the internal function s at the internal numerals. Updates of s at a   *)
(* numeral correspond exactly to meta-level valuation modification.          *)
(* ------------------------------------------------------------------------- *)

let ENAT_INJ = prove
 (`!D (E:A->A->bool) j k t.
        model D E ZF_AX /\ enat D E j t /\ enat D E k t ==> j = k`,
  REPEAT STRIP_TAC THEN
  MATCH_MP_TAC(ARITH_RULE `~(j:num < k) /\ ~(k < j) ==> j = k`) THEN
  CONJ_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) t t` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_MEM_LT]; ASM_MESON_TAC[E_IRREFL; ENAT_IN];
    ASM_MESON_TAC[ENAT_MEM_LT]; ASM_MESON_TAC[E_IRREFL; ENAT_IN]]);;

let shadowed = new_definition
  `shadowed D (E:A->A->bool) s v <=>
        !i. (v i) IN D /\
            ?ni. ni IN D /\ enat D E i ni /\ eapply D E s ni (v i)`;;

let SHADOWED_VALUATION = prove
 (`!D (E:A->A->bool) s v. shadowed D E s v ==> valuation D v`,
  REWRITE_TAC[shadowed; valuation] THEN MESON_TAC[]);;

let SHADOWED_EXISTS = prove
 (`!D (E:A->A->bool) om x s.
        model D E ZF_AX /\ eomega D E om /\ evaluation D E om x s
        ==> ?v. shadowed D E s v /\ !i. E (v i) x`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!i:num. ?w:A. w IN D /\ E w x /\
                  ?ni. ni IN D /\ enat D E i ni /\ eapply D E s ni w`
  MP_TAC THENL
   [X_GEN_TAC `i:num` THEN
    SUBGOAL_THEN `?ni:A. enat D (E:A->A->bool) i ni`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(ni:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) ni om` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) s ni` MP_TAC THENL
     [ASM_MESON_TAC[evaluation; edomain]; ALL_TAC] THEN
    REWRITE_TAC[eindom] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[evaluation]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[SKOLEM_THM] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `v:num->A` THEN
  REWRITE_TAC[shadowed] THEN MESON_TAC[]);;

let SHADOWED_APPLY = prove
 (`!D (E:A->A->bool) om x s v i ni w.
        model D E ZF_AX /\ eomega D E om /\ evaluation D E om x s /\
        shadowed D E s v /\ enat D E i ni /\ w IN D /\
        eapply D E s ni w
        ==> w = v i`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `i:num` o GEN_REWRITE_RULE I [shadowed]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `ni':A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `ni':A = ni` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE]; ALL_TAC] THEN
  MATCH_MP_TAC(GEN_ALL EAPPLY_UNIQUE) THEN
  MAP_EVERY EXISTS_TAC
   [`D:A->bool`; `E:A->A->bool`; `s:A`; `ni:A`] THEN
  ASM_MESON_TAC[evaluation; ENAT_IN]);;

let SHADOWED_RANGE = prove
 (`!D (E:A->A->bool) om x s v i.
        model D E ZF_AX /\ evaluation D E om x s /\ shadowed D E s v
        ==> E (v i) x`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `i:num` o GEN_REWRITE_RULE I [shadowed]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `ni:A`
    STRIP_ASSUME_TAC)) THEN
  ASM_MESON_TAC[evaluation]);;

let SHADOWED_UPDATE = prove
 (`!D (E:A->A->bool) om x s v i ni u s'.
        model D E ZF_AX /\ eomega D E om /\ evaluation D E om x s /\
        shadowed D E s v /\ enat D E i ni /\ u IN D /\
        eupdate D E s ni u s'
        ==> shadowed D E s' ((i |-> u) v)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (ni:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_IN; ENAT_IN]; ALL_TAC] THEN
  REWRITE_TAC[shadowed] THEN X_GEN_TAC `j:num` THEN
  ASM_CASES_TAC `j:num = i` THENL
   [ASM_REWRITE_TAC[VALMOD_BASIC] THEN
    EXISTS_TAC `ni:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EUPDATE_APPLY_SAME];
    ASM_SIMP_TAC[VALMOD_OTHER] THEN
    FIRST_ASSUM(MP_TAC o SPEC `j:num` o
      GEN_REWRITE_RULE I [shadowed]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `nj:A`
      STRIP_ASSUME_TAC)) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `nj:A` THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `~(nj:A = ni)` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_INJ]; ALL_TAC] THEN
    ASM_MESON_TAC[EUPDATE_APPLY_OTHER]]);;

(* ------------------------------------------------------------------------- *)
(* Bridging lemmas: a verdict recorded via the history r of stage n comes    *)
(* from (and can be planted at) an earlier stage; verdict-tagged pairs lie   *)
(* in the stage universe u2.                                                 *)
(* ------------------------------------------------------------------------- *)

let EVERDICT_STAGE_F = prove
 (`!D (E:A->A->bool) x n r c sg bt.
        model D E zfw_ax /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        everdict D E c sg bt r
        ==> ?b y cs w. b IN D /\ y IN D /\ cs IN D /\ w IN D /\
                       E b n /\ esatstage D E x b y /\
                       eopair D E c sg cs /\ eopair D E cs bt w /\
                       E w y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [everdict]) THEN
  DISCH_THEN(X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
    STRIP_ASSUME_TAC)) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eranmem]) THEN
  DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
    (X_CHOOSE_THEN `ord:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `?b y:A. b IN D /\ y IN D /\ E b n /\ esatstage D E x b y /\
            eopair D E b y pr`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ord:A = b /\ vl:A = y` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `y:A`; `cs:A`; `w:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let EVERDICT_STAGE = prove
 (`!D (E:A->A->bool) x n r c sg bt.
        model D E ZF_AX /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        everdict D E c sg bt r
        ==> ?b y cs w. b IN D /\ y IN D /\ cs IN D /\ w IN D /\
                       E b n /\ esatstage D E x b y /\
                       eopair D E c sg cs /\ eopair D E cs bt w /\
                       E w y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EVERDICT_STAGE_F));;

let EVERDICT_INTRO_F = prove
 (`!D (E:A->A->bool) x n r c sg bt b y cs w.
        model D E zfw_ax /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        b IN D /\ y IN D /\ cs IN D /\ w IN D /\
        E b n /\ esatstage D E x b y /\
        eopair D E c sg cs /\ eopair D E cs bt w /\ E w y
        ==> everdict D E c sg bt r`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[everdict] THEN
  MAP_EVERY EXISTS_TAC [`cs:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[eranmem] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `y:A`]
        EOPAIR_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`y:A`; `pr:A`; `b:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let EVERDICT_INTRO = prove
 (`!D (E:A->A->bool) x n r c sg bt b y cs w.
        model D E ZF_AX /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        b IN D /\ y IN D /\ cs IN D /\ w IN D /\
        E b n /\ esatstage D E x b y /\
        eopair D E c sg cs /\ eopair D E cs bt w /\ E w y
        ==> everdict D E c sg bt r`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EVERDICT_INTRO_F));;

let VERDICTPAIR_IN_U2 = prove
 (`!D (E:A->A->bool) x u2 om p c s cs w z k.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        esatuniv D E x u2 /\
        ecode D E p c /\ evaluation D E om x s /\
        enat D E k z /\ k < 2 /\
        cs IN D /\ w IN D /\ z IN D /\
        eopair D E c s cs /\ eopair D E cs z w
        ==> E w u2`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatuniv]) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `hf:A`
    (X_CHOOSE_THEN `vs:A` (X_CHOOSE_THEN `cst:A`
      (X_CHOOSE_THEN `two:A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c hf` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN_HFSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_EFUNS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cs cst` ASSUME_TAC THENL
   [MP_TAC(SPEC `cs:A` (CONJUNCT2(REWRITE_RULE[ecross]
      (ASSUME `ecross D (E:A->A->bool) hf vs cst`)))) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z two` ASSUME_TAC THENL
   [MP_TAC(SPECL [`2`; `D:A->bool`; `E:A->A->bool`; `two:A`; `z:A`]
          ENAT_MEMBERS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPEC `w:A` (CONJUNCT2(REWRITE_RULE[ecross]
    (ASSUME `ecross D (E:A->A->bool) cst two u2`)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let ESATSTAGE_MEMBER_F = prove
 (`!D (E:A->A->bool) x n t.
      model D E zfw_ax /\ x IN D /\ eordinal D E n /\ t IN D /\
      esatstage D E x n t
      ==> ?u2 r. esatuniv D E x u2 /\ r IN D /\
                 (!w. w IN D
                      ==> (E w r <=>
                           ?b y. b IN D /\ y IN D /\ E b n /\
                                 esatstage D E x b y /\
                                 eopair D E b y w)) /\
                 (!w. w IN D
                      ==> (E w t <=> E w u2 /\ esatbody D E x r w))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
        ESATSTAGE_CHAR_F) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `u2:A` THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `r:A` THEN
  REWRITE_TAC[satstep] THEN MESON_TAC[]);;

let ESATSTAGE_MEMBER = prove
 (`!D (E:A->A->bool) x n t.
      model D E ZF_AX /\ x IN D /\ eordinal D E n /\ t IN D /\
      esatstage D E x n t
      ==> ?u2 r. esatuniv D E x u2 /\ r IN D /\
                 (!w. w IN D
                      ==> (E w r <=>
                           ?b y. b IN D /\ y IN D /\ E b n /\
                                 esatstage D E x b y /\
                                 eopair D E b y w)) /\
                 (!w. w IN D
                      ==> (E w t <=> E w u2 /\ esatbody D E x r w))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_MEMBER_F));;

let SATBODY_CASES_F = prove
 (`!D (E:A->A->bool) x r c s z cs w.
        model D E zfw_ax /\ esatbody D E x r w /\
        c IN D /\ s IN D /\ z IN D /\ cs IN D /\ w IN D /\
        eopair D E c s cs /\ eopair D E cs z w
        ==> ?tag data.
                tag IN D /\ data IN D /\ eopair D E tag data c /\
                (esatfalse D E z tag data \/
                 esatmem D E z s tag data \/
                 esateq D E z s tag data \/
                 esatimp D E z s tag data r \/
                 esatall D E z s tag data r x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatbody]) THEN
  DISCH_THEN(X_CHOOSE_THEN `cs':A` (X_CHOOSE_THEN `bit':A`
    (X_CHOOSE_THEN `c':A` (X_CHOOSE_THEN `s':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `cs':A = cs /\ bit':A = z`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
  SUBGOAL_THEN `c':A = c /\ s':A = s`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th -> is_exists(concl th))) THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `tag:A` THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `data:A` THEN
  REWRITE_TAC[]);;

let SATBODY_CASES = prove
 (`!D (E:A->A->bool) x r c s z cs w.
        model D E ZF_AX /\ esatbody D E x r w /\
        c IN D /\ s IN D /\ z IN D /\ cs IN D /\ w IN D /\
        eopair D E c s cs /\ eopair D E cs z w
        ==> ?tag data.
                tag IN D /\ data IN D /\ eopair D E tag data c /\
                (esatfalse D E z tag data \/
                 esatmem D E z s tag data \/
                 esateq D E z s tag data \/
                 esatimp D E z s tag data r \/
                 esatall D E z s tag data r x)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW SATBODY_CASES_F));;

(* ------------------------------------------------------------------------- *)
(* Soundness of internal satisfaction: any verdict <<code p, s>, b> in any   *)
(* omega-indexed stage is correct against the meta-level satisfaction of p   *)
(* relativized to the members of x, at the shadow valuation of s. By meta    *)
(* induction on p via the SNDP packaging, one lemma per constructor.         *)
(* ------------------------------------------------------------------------- *)

let SNDP = new_definition
  `SNDP D (E:A->A->bool) x om p <=>
        !s v n t c z cs w.
            evaluation D E om x s /\ shadowed D E s v /\
            n IN D /\ E n om /\ t IN D /\ esatstage D E x n t /\
            ecode D E p c /\ z IN D /\ cs IN D /\ w IN D /\
            eopair D E c s cs /\ eopair D E cs z w /\ E w t
            ==> (enat D E 1 z ==> holds (\u. u IN D /\ E u x) E v p) /\
                (enat D E 0 z ==> ~holds (\u. u IN D /\ E u x) E v p)`;;

let ESATFALSE_TAG = prove
 (`!D (E:A->A->bool) bit tag data.
        esatfalse D E bit tag data ==> enat D E 0 tag`,
  SIMP_TAC[esatfalse]);;

let ESATMEM_TAG = prove
 (`!D (E:A->A->bool) bit s tag data.
        esatmem D E bit s tag data ==> enat D E 1 tag`,
  SIMP_TAC[esatmem]);;

let ESATEQ_TAG = prove
 (`!D (E:A->A->bool) bit s tag data.
        esateq D E bit s tag data ==> enat D E 2 tag`,
  SIMP_TAC[esateq]);;

let ESATIMP_TAG = prove
 (`!D (E:A->A->bool) bit s tag data g.
        esatimp D E bit s tag data g ==> enat D E 3 tag`,
  SIMP_TAC[esatimp]);;

let ESATALL_TAG = prove
 (`!D (E:A->A->bool) bit s tag data g x.
        esatall D E bit s tag data g x ==> enat D E 4 tag`,
  SIMP_TAC[esatall]);;

let IN_SUBMODEL = prove
 (`!D (E:A->A->bool) x u. u IN (\u. u IN D /\ E u x) <=> u IN D /\ E u x`,
  REWRITE_TAC[IN]);;

let SAT_SOUND_FALSE = prove
 (`!D (E:A->A->bool) x om.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> SNDP D E x om False`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SNDP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
        ESATSTAGE_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u2 r. h1 h2 rchar tmem" THEN
  SUBGOAL_THEN `esatbody D (E:A->A->bool) x r w` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                `s:A`; `z:A`; `cs:A`; `w:A`] SATBODY_CASES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@tag data. h3 h4 h5 +" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t0:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
  SUBGOAL_THEN `tag:A = t0 /\ data:A = t0`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ; ENAT_IN]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[esatfalse; ENAT_INJ; ARITH_RULE `~(1 = 0)`];
    ASM_MESON_TAC[ESATMEM_TAG; ENAT_INJ; ARITH_RULE `~(0 = 1)`];
    ASM_MESON_TAC[ESATEQ_TAG; ENAT_INJ; ARITH_RULE `~(0 = 2)`];
    ASM_MESON_TAC[ESATIMP_TAG; ENAT_INJ; ARITH_RULE `~(0 = 3)`];
    ASM_MESON_TAC[ESATALL_TAG; ENAT_INJ; ARITH_RULE `~(0 = 4)`]]);;

let SAT_SOUND_MEM = prove
 (`!D (E:A->A->bool) x om i j.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> SNDP D E x om (i %% j)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SNDP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
        ESATSTAGE_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u2 r. h1 h2 rchar tmem" THEN
  SUBGOAL_THEN `esatbody D (E:A->A->bool) x r w` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                `s:A`; `z:A`; `cs:A`; `w:A`] SATBODY_CASES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@tag data. h3 h4 h5 +" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `a':A`
    (X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `p':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `tag:A = t' /\ data:A = p'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[ESATFALSE_TAG; ENAT_INJ; ARITH_RULE `~(1 = 0)`];
    ALL_TAC;
    ASM_MESON_TAC[ESATEQ_TAG; ENAT_INJ; ARITH_RULE `~(1 = 2)`];
    ASM_MESON_TAC[ESATIMP_TAG; ENAT_INJ; ARITH_RULE `~(1 = 3)`];
    ASM_MESON_TAC[ESATALL_TAG; ENAT_INJ; ARITH_RULE `~(1 = 4)`]] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatmem]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
    (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sb:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `a:A = a' /\ b:A = b'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `sa:A = v(i:num)` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `v:num->A`; `i:num`; `a':A`; `sa:A`]
          SHADOWED_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `sb:A = v(j:num)` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `v:num->A`; `j:num`; `b':A`; `sb:A`]
          SHADOWED_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`]);;

let SAT_SOUND_EQ = prove
 (`!D (E:A->A->bool) x om i j.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> SNDP D E x om (Eq i j)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SNDP] THEN
