  INTRO_TAC "@tag data. h3 h4 h5 +" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `a':A`
    (X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `p':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `tag:A = t' /\ data:A = p'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[ESATFALSE_TAG; ENAT_INJ; ARITH_RULE `~(2 = 0)`];
    ASM_MESON_TAC[ESATMEM_TAG; ENAT_INJ; ARITH_RULE `~(2 = 1)`];
    ALL_TAC;
    ASM_MESON_TAC[ESATIMP_TAG; ENAT_INJ; ARITH_RULE `~(2 = 3)`];
    ASM_MESON_TAC[ESATALL_TAG; ENAT_INJ; ARITH_RULE `~(2 = 4)`]] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esateq]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
    (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sb:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `a:A = a' /\ b:A = b'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `sa:A = v(i:num)` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `v:num->A`; `i:num`; `a':A`; `sa:A`]
          SHADOWED_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `sb:A = v(j:num)` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `v:num->A`; `j:num`; `b':A`; `sb:A`]
          SHADOWED_APPLY) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`]);;

let SAT_SOUND_IMP = prove
 (`!D (E:A->A->bool) x om p q.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        SNDP D E x om p /\ SNDP D E x om q
        ==> SNDP D E x om (p --> q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SNDP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
        ESATSTAGE_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u2 r. h1 h2 rchar tmem" THEN
  SUBGOAL_THEN `esatbody D (E:A->A->bool) x r w` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                `s:A`; `z:A`; `cs:A`; `w:A`] SATBODY_CASES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@tag data. h3 h4 h5 +" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th) && is_forall(concl th) = false &&
      can (find_term (fun tm -> tm = `c:A`)) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `cp:A`
    (X_CHOOSE_THEN `cq:A` (X_CHOOSE_THEN `w':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `tag:A = t' /\ data:A = w'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[ESATFALSE_TAG; ENAT_INJ; ARITH_RULE `~(3 = 0)`];
    ASM_MESON_TAC[ESATMEM_TAG; ENAT_INJ; ARITH_RULE `~(3 = 1)`];
    ASM_MESON_TAC[ESATEQ_TAG; ENAT_INJ; ARITH_RULE `~(3 = 2)`];
    ALL_TAC;
    ASM_MESON_TAC[ESATALL_TAG; ENAT_INJ; ARITH_RULE `~(3 = 4)`]] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatimp]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `c1:A`
    (X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `c1:A = cp /\ c2:A = cq`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ck zk. ck IN D /\ zk IN D /\ everdict D (E:A->A->bool) ck s zk r
        ==> ?b y cs1 w1.
                b IN D /\ y IN D /\ cs1 IN D /\ w1 IN D /\
                E b om /\ esatstage D E x b y /\
                eopair D E ck s cs1 /\ eopair D E cs1 zk w1 /\ E w1 y`
  (LABEL_TAC "vstage") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `r:A`;
                  `ck:A`; `s:A`; `zk:A`] EVERDICT_STAGE) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `cs1:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w1:A` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EOMEGA_TRANS; EORDINAL_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(everdict D (E:A->A->bool) cp s z0 r
     ==> ~holds (\u. u IN D /\ E u x) E v p) /\
    (everdict D (E:A->A->bool) cp s z1 r
     ==> holds (\u. u IN D /\ E u x) E v p) /\
    (everdict D (E:A->A->bool) cq s z0 r
     ==> ~holds (\u. u IN D /\ E u x) E v q) /\
    (everdict D (E:A->A->bool) cq s z1 r
     ==> holds (\u. u IN D /\ E u x) E v q)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN DISCH_TAC THENL
     [USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`cp:A`; `z0:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `b:A`; `y:A`; `cp:A`; `z0:A`;
                    `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`cp:A`; `z1:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `b:A`; `y:A`; `cp:A`; `z1:A`;
                    `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`cq:A`; `z0:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `b:A`; `y:A`; `cq:A`; `z0:A`;
                    `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om q`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`cq:A`; `z1:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `b:A`; `y:A`; `cq:A`; `z1:A`;
                    `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om q`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th -> is_disj(concl th))) THEN
  STRIP_TAC THENL
   [CONJ_TAC THENL
     [ASM_MESON_TAC[];
      ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`]];
    CONJ_TAC THENL
     [ASM_MESON_TAC[];
      ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`]];
    CONJ_TAC THENL
     [ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`];
      ASM_MESON_TAC[]]]);;

let SAT_SOUND_ALL = prove
 (`!D (E:A->A->bool) x om i p.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\ SNDP D E x om p
        ==> SNDP D E x om (!! i p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[SNDP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
        ESATSTAGE_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u2 r. h1 h2 rchar tmem" THEN
  SUBGOAL_THEN `esatbody D (E:A->A->bool) x r w` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                `s:A`; `z:A`; `cs:A`; `w:A`] SATBODY_CASES) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@tag data. h3 h4 h5 +" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th) && is_forall(concl th) = false &&
      can (find_term (fun tm -> tm = `c:A`)) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `a':A`
    (X_CHOOSE_THEN `cp:A` (X_CHOOSE_THEN `w':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `tag:A = t' /\ data:A = w'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  REWRITE_TAC[holds; IN_SUBMODEL] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[ESATFALSE_TAG; ENAT_INJ; ARITH_RULE `~(4 = 0)`];
    ASM_MESON_TAC[ESATMEM_TAG; ENAT_INJ; ARITH_RULE `~(4 = 1)`];
    ASM_MESON_TAC[ESATEQ_TAG; ENAT_INJ; ARITH_RULE `~(4 = 2)`];
    ASM_MESON_TAC[ESATIMP_TAG; ENAT_INJ; ARITH_RULE `~(4 = 3)`];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatall]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
    (X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `a:A = a' /\ c1:A = cp`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a' om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!sk ck zk. sk IN D /\ ck IN D /\ zk IN D /\
               everdict D (E:A->A->bool) ck sk zk r
        ==> ?b y cs1 w1.
                b IN D /\ y IN D /\ cs1 IN D /\ w1 IN D /\
                E b om /\ esatstage D E x b y /\
                eopair D E ck sk cs1 /\ eopair D E cs1 zk w1 /\ E w1 y`
  (LABEL_TAC "vstage") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `r:A`;
                  `ck:A`; `sk:A`; `zk:A`] EVERDICT_STAGE) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `cs1:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w1:A` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EOMEGA_TRANS; EORDINAL_IN];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u s'. u IN D /\ E u x /\ s' IN D /\
           eupdate D (E:A->A->bool) s a' u s'
       ==> (everdict D E cp s' z1 r
            ==> holds (\u. u IN D /\ E u x) E ((i |-> u) v) p) /\
           (everdict D E cp s' z0 r
            ==> ~holds (\u. u IN D /\ E u x) E ((i |-> u) v) p)`
  (LABEL_TAC "ihx") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `evaluation D (E:A->A->bool) om x s'` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                    `a':A`; `u:A`; `s':A`] EVALUATION_UPDATE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `shadowed D (E:A->A->bool) s' ((i |-> u) v)`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                    `v:num->A`; `i:num`; `a':A`; `u:A`; `s':A`]
            SHADOWED_UPDATE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THEN DISCH_TAC THENL
     [USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`s':A`; `cp:A`; `z1:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL
             [`s':A`; `((i:num) |-> (u:A)) (v:num->A)`; `b:A`; `y:A`; `cp:A`;
              `z1:A`; `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      USE_THEN "vstage" (fun th ->
        MP_TAC(SPECL [`s':A`; `cp:A`; `z0:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs1:A` (X_CHOOSE_THEN `w1:A`
          STRIP_ASSUME_TAC)))) THEN
      MP_TAC(SPECL
             [`s':A`; `((i:num) |-> (u:A)) (v:num->A)`; `b:A`; `y:A`; `cp:A`;
              `z0:A`; `cs1:A`; `w1:A`]
        (REWRITE_RULE[SNDP] (ASSUME `SNDP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th -> is_disj(concl th))) THEN
  STRIP_TAC THENL
   [CONJ_TAC THENL
     [DISCH_TAC THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `?s'. eupdate D (E:A->A->bool) s a' u s'`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EUPDATE_EXISTS; EVALUATION_IN; ENAT_IN];
        ALL_TAC] THEN
      SUBGOAL_THEN `(s':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
      USE_THEN "ihx" (fun th ->
        MP_TAC(SPECL [`u:A`; `s':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 MATCH_MP_TAC (K ALL_TAC)) THEN
      ASM_MESON_TAC[];
      ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`]];
    CONJ_TAC THENL
     [ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(1 = 0)`];
      SUBGOAL_THEN
       `~holds (\u. u IN D /\ E u x) E ((i |-> (u:A)) v) p`
      ASSUME_TAC THENL
       [USE_THEN "ihx" (fun th ->
          MP_TAC(SPECL [`u:A`; `s':A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_MESON_TAC[]]]);;

let SAT_SOUND = prove
 (`!p D (E:A->A->bool) x om.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> SNDP D E x om p`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THEN
  REPEAT GEN_TAC THEN TRY(DISCH_TAC THEN REPEAT GEN_TAC) THEN
  REPEAT STRIP_TAC THENL
   [MATCH_MP_TAC SAT_SOUND_FALSE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_SOUND_MEM THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_SOUND_EQ THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_SOUND_IMP THEN ASM_MESON_TAC[];
    MATCH_MP_TAC SAT_SOUND_ALL THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Completeness: stage (numeral of the formula depth) contains the correct   *)
(* verdict for every coded formula and internal valuation. The toolkit:      *)
(* everdictat (a b-verdict for (c,s) is present in stage k), the intro rule  *)
(* reducing it to providing the Tarski case content against an arbitrary     *)
(* history of the stage, and the planting rule converting a lower-stage      *)
(* verdict into an everdict through that history.                            *)
(* ------------------------------------------------------------------------- *)

let fdepth = new_recursive_definition form_RECURSION
  `(fdepth False = 0) /\
   (fdepth (i %% j) = 0) /\
   (fdepth (Eq i j) = 0) /\
   (fdepth (p --> q) = MAX (fdepth p) (fdepth q) + 1) /\
   (fdepth (!! i p) = fdepth p + 1)`;;

let everdictat = new_definition
  `everdictat D (E:A->A->bool) x k c s b <=>
      ?nk t z cs w.
          nk IN D /\ t IN D /\ z IN D /\ cs IN D /\ w IN D /\
          enat D E k nk /\ esatstage D E x nk t /\
          enat D E b z /\ eopair D E c s cs /\ eopair D E cs z w /\
          E w t`;;

let ESATBODY_INTRO = prove
 (`!D (E:A->A->bool) x r c s z cs w tag data.
        c IN D /\ s IN D /\ z IN D /\ cs IN D /\ w IN D /\
        tag IN D /\ data IN D /\
        eopair D E c s cs /\ eopair D E cs z w /\
        eopair D E tag data c /\
        (esatfalse D E z tag data \/
         esatmem D E z s tag data \/
         esateq D E z s tag data \/
         esatimp D E z s tag data r \/
         esatall D E z s tag data r x)
        ==> esatbody D E x r w`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esatbody] THEN
  MAP_EVERY EXISTS_TAC [`cs:A`; `z:A`; `c:A`; `s:A`] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
  ASM_REWRITE_TAC[]);;

let EVERDICTAT_INTRO = prove
 (`!D (E:A->A->bool) x om p k c s b.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        ecode D E p c /\ evaluation D E om x s /\ b < 2 /\
        (!nk r. nk IN D /\ r IN D /\ enat D E k nk /\
                (!w. w IN D
                     ==> (E w r <=>
                          ?b' y. b' IN D /\ y IN D /\ E b' nk /\
                                 esatstage D E x b' y /\
                                 eopair D E b' y w))
                ==> ?z tag data.
                        z IN D /\ tag IN D /\ data IN D /\
                        enat D E b z /\ eopair D E tag data c /\
                        (esatfalse D E z tag data \/
                         esatmem D E z s tag data \/
                         esateq D E z s tag data \/
                         esatimp D E z s tag data r \/
                         esatall D E z s tag data r x))
        ==> everdictat D E x k c s b`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(c:A) IN D /\ (s:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_IN; EVALUATION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?nk:A. enat D (E:A->A->bool) k nk`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(nk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nk` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?t:A. t IN D /\ esatstage D (E:A->A->bool) x nk t`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESATSTAGE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `nk:A`; `t:A`]
        ESATSTAGE_MEMBER) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@u2 r. h1 h2 rchar tmem" THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`nk:A`; `r:A`] o check (fun th ->
    is_forall(concl th) &&
    can (find_term
      (fun tm -> tm = `esatfalse:(A->bool)->(A->A->bool)->A->A->A->bool`))
      (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `tag:A`
    (X_CHOOSE_THEN `data:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `s:A`]
        EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cs:A`) THEN
  SUBGOAL_THEN `(cs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs:A`; `z:A`]
        EOPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `esatbody D (E:A->A->bool) x r w` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                  `s:A`; `z:A`; `cs:A`; `w:A`; `tag:A`; `data:A`]
          ESATBODY_INTRO) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u2:A`; `om:A`;
                  `p:form`; `c:A`; `s:A`; `cs:A`; `w:A`; `z:A`;
                  `b:num`] VERDICTPAIR_IN_U2) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w t` ASSUME_TAC THENL
   [USE_THEN "tmem" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[everdictat] THEN
  MAP_EVERY EXISTS_TAC [`nk:A`; `t:A`; `z:A`; `cs:A`; `w:A`] THEN
  ASM_REWRITE_TAC[]);;

let EVERDICTAT_PLANT = prove
 (`!D (E:A->A->bool) x om nk k j c1 s1 b zb r.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        enat D E k nk /\ j < k /\ zb IN D /\ enat D E b zb /\
        r IN D /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' nk /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        everdictat D E x j c1 s1 b
        ==> everdict D E c1 s1 zb r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [everdictat]) THEN
  DISCH_THEN(X_CHOOSE_THEN `nj:A` (X_CHOOSE_THEN `t':A`
    (X_CHOOSE_THEN `z':A` (X_CHOOSE_THEN `cs':A`
      (X_CHOOSE_THEN `w':A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `z':A = zb` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) nj nk` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_MEM_LT]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `nk:A`; `r:A`;
                `c1:A`; `s1:A`; `zb:A`; `nj:A`; `t':A`; `cs':A`;
                `w':A`] EVERDICT_INTRO) THEN
  ASM_REWRITE_TAC[]);;

let CMPP = new_definition
  `CMPP D (E:A->A->bool) x om p <=>
        !s v c. evaluation D E om x s /\ shadowed D E s v /\
                ecode D E p c
                ==> (holds (\u. u IN D /\ E u x) E v p
                     ==> everdictat D E x (fdepth p) c s 1) /\
                    (~holds (\u. u IN D /\ E u x) E v p
                     ==> everdictat D E x (fdepth p) c s 0)`;;

let SAT_COMPLETE_FALSE = prove
 (`!D (E:A->A->bool) x om.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> CMPP D E x om False`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[CMPP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[holds; fdepth] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `False`;
                `0`; `c:A`; `s:A`; `0`] EVERDICTAT_INTRO) THEN
  ASM_REWRITE_TAC[ARITH_RULE `0 < 2`] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`t0:A`; `t0:A`; `t0:A`] THEN
  ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN
  REWRITE_TAC[esatfalse] THEN ASM_REWRITE_TAC[]);;

let SAT_COMPLETE_MEM = prove
 (`!D (E:A->A->bool) x om i j.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> CMPP D E x om (i %% j)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[CMPP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[holds; fdepth] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `a':A`
    (X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `p':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN
   `eapply D (E:A->A->bool) s a' (v(i:num)) /\
    eapply D E s b' (v(j:num)) /\
    (v(i:num)):A IN D /\ (v(j:num)):A IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[shadowed; ENAT_UNIQUE]; ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `(i:num) %% j`; `0`; `c:A`; `s:A`; `1`]
          EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `1 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z1:A. enat D (E:A->A->bool) 1 z1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(z1:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z1:A`; `t':A`; `p':A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN DISJ1_TAC THEN
    REWRITE_TAC[esatmem] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC
     [`a':A`; `b':A`; `(v(i:num)):A`; `(v(j:num)):A`] THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `(i:num) %% j`; `0`; `c:A`; `s:A`; `0`]
          EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `0 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z0:A. enat D (E:A->A->bool) 0 z0`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(z0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z0:A`; `t':A`; `p':A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN DISJ1_TAC THEN
    REWRITE_TAC[esatmem] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC
     [`a':A`; `b':A`; `(v(i:num)):A`; `(v(j:num)):A`] THEN
    ASM_REWRITE_TAC[]]);;

let SAT_COMPLETE_EQ = prove
 (`!D (E:A->A->bool) x om i j.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> CMPP D E x om (Eq i j)`,
