    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `?z1:A. enat D (E:A->A->bool) 1 z1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(z1:A) IN D` ASSUME_TAC THENL
