    DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    REWRITE_TAC[esateq] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC
     [`a':A`; `b':A`; `(v(i:num)):A`; `(v(j:num)):A`] THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
