let SAT_COMPLETE_IMP = prove
 (`!D (E:A->A->bool) x om p q.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        CMPP D E x om p /\ CMPP D E x om q
        ==> CMPP D E x om (p --> q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[CMPP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[holds; fdepth] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th) && is_forall(concl th) = false)) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `cp:A`
    (X_CHOOSE_THEN `cq:A` (X_CHOOSE_THEN `w':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `?z0:A. enat D (E:A->A->bool) 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?z1:A. enat D (E:A->A->bool) 1 z1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z0:A) IN D /\ (z1:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nk r. nk IN D /\ r IN D /\
           enat D (E:A->A->bool) (MAX (fdepth p) (fdepth q) + 1) nk /\
           (!w. w IN D
                ==> (E w r <=>
                     ?b' y. b' IN D /\ y IN D /\ E b' nk /\
                            esatstage D E x b' y /\
                            eopair D E b' y w))
           ==> (holds (\u. u IN D /\ E u x) E v p
                ==> everdict D E cp s z1 r) /\
               (~holds (\u. u IN D /\ E u x) E v p
                ==> everdict D E cp s z0 r) /\
               (holds (\u. u IN D /\ E u x) E v q
                ==> everdict D E cq s z1 r) /\
               (~holds (\u. u IN D /\ E u x) E v q
                ==> everdict D E cq s z0 r)`
  (LABEL_TAC "plant") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THEN
    DISCH_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `MAX (fdepth p) (fdepth q) + 1`; `fdepth p`;
                    `cp:A`; `s:A`; `1`; `z1:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC
        [ARITH_RULE `fdepth p < MAX (fdepth p) (fdepth q) + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `cp:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `MAX (fdepth p) (fdepth q) + 1`; `fdepth p`;
                    `cp:A`; `s:A`; `0`; `z0:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC
        [ARITH_RULE `fdepth p < MAX (fdepth p) (fdepth q) + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `cp:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `MAX (fdepth p) (fdepth q) + 1`; `fdepth q`;
                    `cq:A`; `s:A`; `1`; `z1:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC
        [ARITH_RULE `fdepth q < MAX (fdepth p) (fdepth q) + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `cq:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om q`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `MAX (fdepth p) (fdepth q) + 1`; `fdepth q`;
                    `cq:A`; `s:A`; `0`; `z0:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC
        [ARITH_RULE `fdepth q < MAX (fdepth p) (fdepth q) + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s:A`; `v:num->A`; `cq:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om q`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `p --> q`; `MAX (fdepth p) (fdepth q) + 1`;
                  `c:A`; `s:A`; `1`] EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `1 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    USE_THEN "plant" (fun th ->
      MP_TAC(SPECL [`nk:A`; `r:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`z1:A`; `t':A`; `w':A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    REWRITE_TAC[esatimp] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`cp:A`; `cq:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `holds (\u. u IN D /\ (E:A->A->bool) u x) E v p` THENL
     [DISJ2_TAC THEN ASM_MESON_TAC[]; DISJ1_TAC THEN ASM_MESON_TAC[]];
    FIRST_X_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[NOT_IMP] o
      check (fun th -> is_neg(concl th))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `p --> q`; `MAX (fdepth p) (fdepth q) + 1`;
                  `c:A`; `s:A`; `0`] EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `0 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    USE_THEN "plant" (fun th ->
      MP_TAC(SPECL [`nk:A`; `r:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`z0:A`; `t':A`; `w':A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    REWRITE_TAC[esatimp] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`cp:A`; `cq:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let SAT_COMPLETE_ALL = prove
 (`!D (E:A->A->bool) x om i p.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\ CMPP D E x om p
        ==> CMPP D E x om (!! i p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[CMPP] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[holds; fdepth; IN_SUBMODEL] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ecode] o
    check (fun th -> can (find_term
      (fun tm -> tm = `ecode:(A->bool)->(A->A->bool)->form->A->bool`))
      (concl th) && is_forall(concl th) = false)) THEN
  DISCH_THEN(X_CHOOSE_THEN `t':A` (X_CHOOSE_THEN `a':A`
    (X_CHOOSE_THEN `cp:A` (X_CHOOSE_THEN `w':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `?z0:A. enat D (E:A->A->bool) 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?z1:A. enat D (E:A->A->bool) 1 z1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z0:A) IN D /\ (z1:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a' om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nk r u s'.
        nk IN D /\ r IN D /\
        enat D (E:A->A->bool) (fdepth p + 1) nk /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' nk /\
                         esatstage D E x b' y /\
                         eopair D E b' y w)) /\
        u IN D /\ E u x /\ s' IN D /\ eupdate D E s a' u s'
        ==> (holds (\u. u IN D /\ E u x) E ((i |-> u) v) p
             ==> everdict D E cp s' z1 r) /\
            (~holds (\u. u IN D /\ E u x) E ((i |-> u) v) p
             ==> everdict D E cp s' z0 r)`
  (LABEL_TAC "plant") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `evaluation D (E:A->A->bool) om x s'` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                    `a':A`; `u:A`; `s':A`] EVALUATION_UPDATE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `shadowed D (E:A->A->bool) s' ((i |-> u) v)`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                    `v:num->A`; `i:num`; `a':A`; `u:A`; `s':A`]
            SHADOWED_UPDATE) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    CONJ_TAC THEN DISCH_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `fdepth p + 1`; `fdepth p`;
                    `cp:A`; `s':A`; `1`; `z1:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC[ARITH_RULE `fdepth p < fdepth p + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s':A`; `((i:num) |-> (u:A)) (v:num->A)`; `cp:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`; `nk:A`;
                    `fdepth p + 1`; `fdepth p`;
                    `cp:A`; `s':A`; `0`; `z0:A`; `r:A`]
            EVERDICTAT_PLANT) THEN
      ASM_REWRITE_TAC[ARITH_RULE `fdepth p < fdepth p + 1`] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      MP_TAC(SPECL [`s':A`; `((i:num) |-> (u:A)) (v:num->A)`; `cp:A`]
        (REWRITE_RULE[CMPP] (ASSUME `CMPP D (E:A->A->bool) x om p`))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(MP_TAC o CONJUNCT2) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  CONJ_TAC THEN DISCH_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `!! i p`; `fdepth p + 1`;
                  `c:A`; `s:A`; `1`] EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `1 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`z1:A`; `t':A`; `w':A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    REWRITE_TAC[esatall] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`a':A`; `cp:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    X_GEN_TAC `s':A` THEN STRIP_TAC THEN
    USE_THEN "plant" (fun th ->
      MP_TAC(SPECL [`nk:A`; `r:A`; `u:A`; `s':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `u:A` o check (fun th ->
      is_forall(concl th) &&
      can (find_term (fun tm ->
        tm = `holds:(A->bool)->(A->A->bool)->(num->A)->form->bool`))
        (concl th) &&
      not(can (find_term (fun tm ->
        tm = `everdict:(A->bool)->(A->A->bool)->A->A->A->A->bool`))
        (concl th)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    FIRST_X_ASSUM(MP_TAC o
      REWRITE_RULE[NOT_FORALL_THM; NOT_IMP] o
      check (fun th -> is_neg(concl th))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
    SUBGOAL_THEN `?s'. eupdate D (E:A->A->bool) s a' u s'`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `a':A`; `u:A`]
            EUPDATE_EXISTS) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(s':A) IN D` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `a':A`;
                    `u:A`; `s':A`] EUPDATE_IN) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `!! i p`; `fdepth p + 1`;
                  `c:A`; `s:A`; `0`] EVERDICTAT_INTRO) THEN
    ASM_REWRITE_TAC[fdepth; ARITH_RULE `0 < 2`] THEN
    DISCH_THEN MATCH_MP_TAC THEN
    MAP_EVERY X_GEN_TAC [`nk:A`; `r:A`] THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`z0:A`; `t':A`; `w':A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    REWRITE_TAC[esatall] THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`a':A`; `cp:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "plant" (fun th ->
      MP_TAC(SPECL [`nk:A`; `r:A`; `u:A`; `s':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let SAT_COMPLETE = prove
 (`!p D (E:A->A->bool) x om.
        model D E ZF_AX /\ x IN D /\ eomega D E om
        ==> CMPP D E x om p`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THEN
  REPEAT GEN_TAC THEN TRY(DISCH_TAC THEN REPEAT GEN_TAC) THEN
  REPEAT STRIP_TAC THENL
   [MATCH_MP_TAC SAT_COMPLETE_FALSE THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_COMPLETE_MEM THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_COMPLETE_EQ THEN ASM_REWRITE_TAC[];
    MATCH_MP_TAC SAT_COMPLETE_IMP THEN ASM_MESON_TAC[];
    MATCH_MP_TAC SAT_COMPLETE_ALL THEN ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The absoluteness bridge: internal satisfaction of the code of p at an     *)
(* internal valuation coincides with meta-level satisfaction of p in the     *)
(* set structure (x, E restricted) at the shadow valuation. This is the      *)
(* keystone connecting the object-level Def operation (to come) with the     *)
(* meta-level definability that the L construction manipulates.              *)
(* ------------------------------------------------------------------------- *)

let SAT_BRIDGE = prove
 (`!D (E:A->A->bool) x om p c s v.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        ecode D E p c /\ evaluation D E om x s /\ shadowed D E s v
        ==> (esat D E x c s <=>
             holds (\u. u IN D /\ E u x) E v p)`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [REWRITE_TAC[esat] THEN
    DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
      (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))))) THEN
    SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
    MP_TAC(SPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`]
          SAT_SOUND) THEN
    ASM_REWRITE_TAC[SNDP] THEN
    DISCH_THEN(MP_TAC o SPECL
     [`s:A`; `v:num->A`; `n:A`; `t:A`; `c:A`; `z1:A`; `cs:A`; `w:A`]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_TAC THEN
    MP_TAC(SPECL [`p:form`; `D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`]
          SAT_COMPLETE) THEN
    ASM_REWRITE_TAC[CMPP] THEN
    DISCH_THEN(MP_TAC o SPECL [`s:A`; `v:num->A`; `c:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[everdictat] THEN
    DISCH_THEN(X_CHOOSE_THEN `nk:A` (X_CHOOSE_THEN `t:A`
      (X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `cs:A`
        (X_CHOOSE_THEN `w:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    REWRITE_TAC[esat] THEN
    SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `nk:A`; `t:A`; `z:A`; `cs:A`; `w:A`] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ENAT_IN_OMEGA]]);;

(* ------------------------------------------------------------------------- *)
(* Internalizing the satisfaction apparatus as object formulas, en route to  *)
(* the definable-powerset operation: the semantics of                        *)
(* recapp_form/recapp4_form, which apply a formula with free variables among *)
(* 2,3 (resp. 2..5) at other variables (the rec_form instances have exactly  *)
(* that shape), and of the defining object formulas of the set operations    *)
(* used in the stage universe: omega, cartesian product, function space, the *)
(* hf universe (via rec_form vstep_form 2), the stage universe, satisfaction *)
(* stages (via rec_form satstep_form 4), and esat.                           *)
(* ------------------------------------------------------------------------- *)

let HOLDS_RECAPP_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (recapp_form q i j) <=>
             holds D E ((3 |-> v j) ((2 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(2 = 3)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

let HOLDS_RECAPP4_FORM = prove
 (`!D (E:A->A->bool) v q i j k l.
        valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(i = 4) /\ ~(i = 5) /\
        ~(j = 2) /\ ~(j = 3) /\ ~(j = 4) /\ ~(j = 5) /\
        ~(k = 2) /\ ~(k = 3) /\ ~(k = 4) /\ ~(k = 5) /\
        ~(l = 2) /\ ~(l = 3) /\ ~(l = 4) /\ ~(l = 5)
        ==> (holds D E v (recapp4_form q i j k l) <=>
             holds D E ((5 |-> v l) ((4 |-> v k)
                        ((3 |-> v j) ((2 |-> v i) v)))) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp4_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(2 = 3) /\ ~(2 = 4) /\ ~(2 = 5) /\ ~(3 = 4) /\ ~(3 = 5) /\
     ~(4 = 5)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) k`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) l`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

let HOLDS_OMEGA_FORM_F = prove
 (`!D (E:A->A->bool) v i.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (omega_form i) <=> eomega D E (v i))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[omega_form; holds; HOLDS_AND; eomega] THEN
  ASM_SIMP_TAC[HOLDS_INDUCTIVE_FORM_F] THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((a /\ x) <=> (a /\ y))`) THEN
  SUBGOAL_THEN `!w:A. einductive D (E:A->A->bool) w ==> w IN D`
  ASSUME_TAC THENL [SIMP_TAC[einductive]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E (((i + 1) |-> a) v) (inductive_form (i + 1)) <=>
           einductive D E a) /\
          (holds D E (((i + 1) |-> a) v) (subset_form i (i + 1)) <=>
           esubset D E (v i) a)`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((i + 1) |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_INDUCTIVE_FORM_F; HOLDS_SUBSET_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i = i + 1)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    DISCH_TAC THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    ASM_MESON_TAC[]]);;

let HOLDS_OMEGA_FORM = prove
 (`!D (E:A->A->bool) v i.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (omega_form i) <=> eomega D E (v i))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_OMEGA_FORM_F));;

let HOLDS_CROSS_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (cross_form i j k) <=>
             ecross D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[cross_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              ecross] THEN
  ASM_REWRITE_TAC[] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(i = MAX (MAX i j) k + 1) /\ ~(i = MAX (MAX i j) k + 2) /\
     ~(i = MAX (MAX i j) k + 3) /\
     ~(j = MAX (MAX i j) k + 1) /\ ~(j = MAX (MAX i j) k + 2) /\
     ~(j = MAX (MAX i j) k + 3) /\
     ~(k = MAX (MAX i j) k + 1) /\ ~(k = MAX (MAX i j) k + 2) /\
     ~(k = MAX (MAX i j) k + 3) /\
     ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2) /\
     ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 3) /\
     ~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 3)`] THEN
  MATCH_MP_TAC(MESON[]
    `(!z:A. z IN D ==> (P z <=> Q z))
     ==> ((!z. z IN D ==> P z) <=> (!z. z IN D ==> Q z))`) THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((e <=> x) <=> (e <=> y))`) THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
      ==> (holds D E
            (((MAX (MAX i j) k + 3) |-> w)
             (((MAX (MAX i j) k + 2) |-> u)
              (((MAX (MAX i j) k + 1) |-> (z:A)) v)))
            (opair_form (MAX (MAX i j) k + 2) (MAX (MAX i j) k + 3)
                        (MAX (MAX i j) k + 1)) <=>
           eopair D E u w z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX (MAX i j) k + 3) |-> (w:A))
        (((MAX (MAX i j) k + 2) |-> u)
         (((MAX (MAX i j) k + 1) |-> z) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2) /\
       ~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 3) /\
       ~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 3)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let HOLDS_FUNS_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        valuation D v
        ==> (holds D E v (funs_form i j k) <=>
             efuns D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[funs_form; holds; HOLDS_IFF; HOLDS_AND; efuns] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!g:A. g IN D ==> (P g <=> Q g))
     ==> ((!g. g IN D ==> P g) <=> (!g. g IN D ==> Q g))`) THEN
  X_GEN_TAC `g:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D (((MAX (MAX i j) k + 1) |-> (g:A)) v)`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(i = MAX (MAX i j) k + 1) /\ ~(j = MAX (MAX i j) k + 1) /\
     ~(k = MAX (MAX i j) k + 1)`] THEN
  MATCH_MP_TAC(TAUT
    `(c <=> c') ==> ((e <=> a /\ b /\ c) <=> (e <=> a /\ b /\ c'))`) THEN
  ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE
    `~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 1)`] THEN
  REWRITE_TAC[holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(MAX (MAX i j) k + 1 = MAX (MAX i j) k + 2) /\
     ~(j = MAX (MAX i j) k + 2) /\ ~(j = MAX (MAX i j) k + 3) /\
     ~(j = MAX (MAX i j) k + 4) /\ ~(j = MAX (MAX i j) k + 1)`] THEN
  SUBGOAL_THEN
   `!z u w:A. z IN D /\ u IN D /\ w IN D
      ==> (holds D E
            (((MAX (MAX i j) k + 4) |-> w)
             (((MAX (MAX i j) k + 3) |-> u)
              (((MAX (MAX i j) k + 2) |-> z)
               (((MAX (MAX i j) k + 1) |-> (g:A)) v))))
            (opair_form (MAX (MAX i j) k + 3) (MAX (MAX i j) k + 4)
                        (MAX (MAX i j) k + 2)) <=>
           eopair D E u w z)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX (MAX i j) k + 4) |-> (w:A))
        (((MAX (MAX i j) k + 3) |-> u)
         (((MAX (MAX i j) k + 2) |-> z)
          (((MAX (MAX i j) k + 1) |-> g) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 3) /\
       ~(MAX (MAX i j) k + 2 = MAX (MAX i j) k + 4) /\
       ~(MAX (MAX i j) k + 3 = MAX (MAX i j) k + 4)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eapply] o
      check (fun th -> fst(strip_comb(concl th)) =
        `eapply:(A->bool)->(A->A->bool)->A->A->A->bool`)) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    DISCH_TAC THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) u w z` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g u w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    ASM_MESON_TAC[]]);;

let HOLDS_HFSET_FORM_F = prove
 (`!D (E:A->A->bool) v i j.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (hfset_form i j) <=>
             ehfset D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[hfset_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              ehfset] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
    `(!u:A. u IN D ==> (P u <=> Q u))
     ==> ((!u. u IN D ==> P u) <=> (!u. u IN D ==> Q u))`) THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
    `~(i = MAX (MAX i j) 5 + 1) /\ ~(i = MAX (MAX i j) 5 + 2) /\
     ~(i = MAX (MAX i j) 5 + 3) /\
     ~(j = MAX (MAX i j) 5 + 1) /\ ~(j = MAX (MAX i j) 5 + 2) /\
     ~(j = MAX (MAX i j) 5 + 3) /\
     ~(MAX (MAX i j) 5 + 1 = MAX (MAX i j) 5 + 2) /\
     ~(MAX (MAX i j) 5 + 1 = MAX (MAX i j) 5 + 3) /\
     ~(MAX (MAX i j) 5 + 2 = MAX (MAX i j) 5 + 3)`] THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((e <=> x) <=> (e <=> y))`) THEN
  SUBGOAL_THEN
   `!n y:A. n IN D /\ y IN D
      ==> (holds D E
            (((MAX (MAX i j) 5 + 3) |-> y)
             (((MAX (MAX i j) 5 + 2) |-> n)
              (((MAX (MAX i j) 5 + 1) |-> (u:A)) v)))
            (recapp_form (rec_form vstep_form 2)
                         (MAX (MAX i j) 5 + 2) (MAX (MAX i j) 5 + 3)) <=>
           ehfstage D E n y)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX (MAX i j) 5 + 3) |-> (y:A))
        (((MAX (MAX i j) 5 + 2) |-> n)
         (((MAX (MAX i j) 5 + 1) |-> u) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_RECAPP_FORM; ARITH_RULE
      `~(MAX (MAX i j) 5 + 2 = 2) /\ ~(MAX (MAX i j) 5 + 2 = 3) /\
       ~(MAX (MAX i j) 5 + 3 = 2) /\ ~(MAX (MAX i j) 5 + 3 = 3)`] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX (MAX i j) 5 + 2 = MAX (MAX i j) 5 + 3)`] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `((MAX (MAX i j) 5 + 3) |-> (y:A))
                   (((MAX (MAX i j) 5 + 2) |-> n)
                    (((MAX (MAX i j) 5 + 1) |-> u) v))`;
                  `vstep_form`; `2`; `n:A`; `y:A`] HOLDS_REC_FORM) THEN
    ASM_REWRITE_TAC[FVLT_VSTEP_FORM; ARITH_RULE `1 < 2`;
                    ARITH_RULE `2 + 1 = 3`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(GSYM EHFSTAGE_EREC_F) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `n:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `y:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let HOLDS_HFSET_FORM = prove
 (`!D (E:A->A->bool) v i j.
