let HOLDS_UNIV_FORM_F = prove
 (`!D (E:A->A->bool) v i j.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v (univ_form i j) <=>
             esatuniv D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[univ_form; HOLDS_EX; HOLDS_AND; esatuniv] THEN
  SUBGOAL_THEN
   `!om hf vs cst tw:A.
        om IN D /\ hf IN D /\ vs IN D /\ cst IN D /\ tw IN D
        ==> (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (omega_form (MAX i j + 1)) <=>
             eomega D E om) /\
            (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (hfset_form (MAX i j + 1) (MAX i j + 2)) <=>
             ehfset D E om hf) /\
            (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (funs_form (MAX i j + 1) i (MAX i j + 3)) <=>
             efuns D E om (v i) vs) /\
            (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (cross_form (MAX i j + 2) (MAX i j + 3) (MAX i j + 4)) <=>
             ecross D E hf vs cst) /\
            (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (nat_form 2 (MAX i j + 5)) <=>
             enat D E 2 tw) /\
            (holds D E
              (((MAX i j + 5) |-> tw) (((MAX i j + 4) |-> cst)
               (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
                (((MAX i j + 1) |-> om) v)))))
              (cross_form (MAX i j + 4) (MAX i j + 5) j) <=>
             ecross D E cst tw (v j))`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX i j + 5) |-> (tw:A)) (((MAX i j + 4) |-> cst)
        (((MAX i j + 3) |-> vs) (((MAX i j + 2) |-> hf)
         (((MAX i j + 1) |-> om) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OMEGA_FORM_F; HOLDS_HFSET_FORM_F; HOLDS_FUNS_FORM;
                 HOLDS_CROSS_FORM; HOLDS_NAT_FORM_F] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(i = MAX i j + 1) /\ ~(i = MAX i j + 2) /\
       ~(i = MAX i j + 3) /\ ~(i = MAX i j + 4) /\
       ~(i = MAX i j + 5) /\
       ~(j = MAX i j + 1) /\ ~(j = MAX i j + 2) /\
       ~(j = MAX i j + 3) /\ ~(j = MAX i j + 4) /\
       ~(j = MAX i j + 5) /\
       ~(MAX i j + 1 = MAX i j + 2) /\
       ~(MAX i j + 1 = MAX i j + 3) /\
       ~(MAX i j + 1 = MAX i j + 4) /\
       ~(MAX i j + 1 = MAX i j + 5) /\
       ~(MAX i j + 2 = MAX i j + 3) /\
       ~(MAX i j + 2 = MAX i j + 4) /\
       ~(MAX i j + 2 = MAX i j + 5) /\
       ~(MAX i j + 3 = MAX i j + 4) /\
       ~(MAX i j + 3 = MAX i j + 5) /\
       ~(MAX i j + 4 = MAX i j + 5)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@om. h1 @hf. h2 @vs. h3 @cst. h4 @tw. h5 +" THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`om:A`; `hf:A`; `vs:A`; `cst:A`; `tw:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`om:A`; `hf:A`; `vs:A`; `cst:A`; `tw:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `hf:A`
      (X_CHOOSE_THEN `vs:A` (X_CHOOSE_THEN `cst:A`
        (X_CHOOSE_THEN `tw:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    EXISTS_TAC `om:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `hf:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `vs:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cst:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `tw:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`om:A`; `hf:A`; `vs:A`; `cst:A`; `tw:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

