     ~(k = MAX (MAX i j) (MAX k 5) + 2) /\
     ~(k = MAX (MAX i j) (MAX k 5) + 3) /\
     ~(k = MAX (MAX i j) (MAX k 5) + 4) /\
     ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 2) /\
     ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 3) /\
     ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 4) /\
     ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 3) /\
     ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 4) /\
     ~(MAX (MAX i j) (MAX k 5) + 3 = MAX (MAX i j) (MAX k 5) + 4)`] THEN
  SUBGOAL_THEN
   `!u2 xc nc tc:A.
        u2 IN D /\ xc IN D /\ nc IN D /\ tc IN D
        ==> (holds D E
              (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
               (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
                (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
                 (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))
              (univ_form (MAX (MAX i j) (MAX k 5) + 2)
                         (MAX (MAX i j) (MAX k 5) + 1)) <=>
             esatuniv D E xc u2) /\
            (holds D E
              (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
               (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
                (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
                 (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))
              (recapp4_form (rec_form satstep_form 4)
                            (MAX (MAX i j) (MAX k 5) + 2)
                            (MAX (MAX i j) (MAX k 5) + 1)
                            (MAX (MAX i j) (MAX k 5) + 3)
                            (MAX (MAX i j) (MAX k 5) + 4)) <=>
             erec D E satstep_form
                  ((3 |-> u2) ((2 |-> xc)
                   (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
                    (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
                     (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
                      (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))))
                  nc tc)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX (MAX i j) (MAX k 5) + 4) |-> (tc:A))
        (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
         (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
          (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_UNIV_FORM_F] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
        `~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 2) /\
         ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 3) /\
         ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 4) /\
         ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 3) /\
         ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 4)`];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_RECAPP4_FORM; ARITH_RULE
      `~(MAX (MAX i j) (MAX k 5) + 1 = 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = 5)`] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = MAX (MAX i j) (MAX k 5) + 4)`] THEN
    SUBGOAL_THEN
     `valuation D
       ((3 |-> (u2:A)) ((2 |-> xc)
        (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
         (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
          (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
           (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(3 |-> (u2:A)) ((2 |-> xc)
                   (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
                    (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
                     (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
                      (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v)))))`;
                  `satstep_form`; `4`; `nc:A`; `tc:A`]
          HOLDS_REC_FORM) THEN
    ASM_REWRITE_TAC[FVLT_SATSTEP_FORM; ARITH_RULE `1 < 4`;
                    ARITH_RULE `4 + 1 = 5`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u2 xc nc tc:A.
        u2 IN D /\ xc IN D /\ nc IN D /\ tc IN D /\ esatuniv D E xc u2
        ==> (erec D E satstep_form
                  ((3 |-> u2) ((2 |-> xc)
                   (((MAX (MAX i j) (MAX k 5) + 4) |-> tc)
                    (((MAX (MAX i j) (MAX k 5) + 3) |-> nc)
                     (((MAX (MAX i j) (MAX k 5) + 2) |-> xc)
                      (((MAX (MAX i j) (MAX k 5) + 1) |-> u2) v))))))
                  nc tc <=>
             esatstage D E xc nc tc)`
  (LABEL_TAC "conv") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN CONV_TAC SYM_CONV THEN
    MATCH_MP_TAC ESATSTAGE_EREC_F THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u2:A` THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(2 = 3)`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@u2. h1 @xc. h2 @nc. h3 @tc. h4 +" THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`u2:A`; `xc:A`; `nc:A`; `tc:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    SUBGOAL_THEN `esatuniv D (E:A->A->bool) xc u2` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "conv" (fun th -> MP_TAC(SPECL
      [`u2:A`; `xc:A`; `nc:A`; `tc:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN ASM_MESON_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `?u2:A. esatuniv D (E:A->A->bool) ((v:num->A) i) u2`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC ESATUNIV_EXISTS_F THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
    EXISTS_TAC `u2:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `(v:num->A) i` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `(v:num->A) j` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `(v:num->A) k` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`u2:A`; `(v:num->A) i`; `(v:num->A) j`; `(v:num->A) k`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "conv" (fun th -> MP_TAC(SPECL
      [`u2:A`; `(v:num->A) i`; `(v:num->A) j`; `(v:num->A) k`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

