              (((MAX (MAX i j) (MAX k 5) + 6) |-> w)
               (((MAX (MAX i j) (MAX k 5) + 5) |-> cs)
                (((MAX (MAX i j) (MAX k 5) + 4) |-> z1)
                 (((MAX (MAX i j) (MAX k 5) + 3) |-> t)
                  (((MAX (MAX i j) (MAX k 5) + 2) |-> n)
                   (((MAX (MAX i j) (MAX k 5) + 1) |-> om) v))))))
              (nat_form 1 (MAX (MAX i j) (MAX k 5) + 4)) <=>
             enat D E 1 z1) /\
            (holds D E
              (((MAX (MAX i j) (MAX k 5) + 6) |-> w)
               (((MAX (MAX i j) (MAX k 5) + 5) |-> cs)
                (((MAX (MAX i j) (MAX k 5) + 4) |-> z1)
                 (((MAX (MAX i j) (MAX k 5) + 3) |-> t)
                  (((MAX (MAX i j) (MAX k 5) + 2) |-> n)
                   (((MAX (MAX i j) (MAX k 5) + 1) |-> om) v))))))
              (opair_form j k (MAX (MAX i j) (MAX k 5) + 5)) <=>
             eopair D E (v j) (v k) cs) /\
            (holds D E
              (((MAX (MAX i j) (MAX k 5) + 6) |-> w)
               (((MAX (MAX i j) (MAX k 5) + 5) |-> cs)
                (((MAX (MAX i j) (MAX k 5) + 4) |-> z1)
                 (((MAX (MAX i j) (MAX k 5) + 3) |-> t)
                  (((MAX (MAX i j) (MAX k 5) + 2) |-> n)
                   (((MAX (MAX i j) (MAX k 5) + 1) |-> om) v))))))
              (opair_form (MAX (MAX i j) (MAX k 5) + 5)
                          (MAX (MAX i j) (MAX k 5) + 4)
                          (MAX (MAX i j) (MAX k 5) + 6)) <=>
             eopair D E cs z1 w)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       (((MAX (MAX i j) (MAX k 5) + 6) |-> (w:A))
        (((MAX (MAX i j) (MAX k 5) + 5) |-> cs)
         (((MAX (MAX i j) (MAX k 5) + 4) |-> z1)
          (((MAX (MAX i j) (MAX k 5) + 3) |-> t)
           (((MAX (MAX i j) (MAX k 5) + 2) |-> n)
            (((MAX (MAX i j) (MAX k 5) + 1) |-> om) v))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OMEGA_FORM_F; HOLDS_SATSTAGE_FORM_F;
                 HOLDS_NAT_FORM_F; HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(i = MAX (MAX i j) (MAX k 5) + 1) /\
       ~(i = MAX (MAX i j) (MAX k 5) + 2) /\
       ~(i = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(i = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(i = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(i = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 1) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 2) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(j = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 1) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 2) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(k = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 2) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 1 = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 3) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 2 = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = MAX (MAX i j) (MAX k 5) + 4) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 3 = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = MAX (MAX i j) (MAX k 5) + 5) /\
       ~(MAX (MAX i j) (MAX k 5) + 4 = MAX (MAX i j) (MAX k 5) + 6) /\
       ~(MAX (MAX i j) (MAX k 5) + 5 = MAX (MAX i j) (MAX k 5) + 6)`];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@om. h1 @n. h2 @t. h3 @z1. h4 @cs. h5 @w. h6 +" THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`om:A`; `n:A`; `t:A`; `z1:A`; `cs:A`; `w:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `n:A`; `t:A`; `z1:A`; `cs:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `n:A`
      (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))))) THEN
    EXISTS_TAC `om:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z1:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `cs:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "piles" (fun th -> MP_TAC(SPECL
      [`om:A`; `n:A`; `t:A`; `z1:A`; `cs:A`; `w:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_SAT_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (sat_form i j k) <=>
             esat D E (v i) (v j) (v k))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_SAT_FORM_F));;

(* ------------------------------------------------------------------------- *)
(* The definable-powerset operation Def(x): the set of subsets y of x that   *)
(* are empty or carved out of x by internal satisfaction of some code c at   *)
(* the 0-slot rebindings of some internal valuation s over x. The membership *)
(* condition is a single object formula (with y at variable 0 and x at 1),   *)
(* so Def(x) comes from one application of separation inside P(x).           *)
(* ------------------------------------------------------------------------- *)

let edefmem = new_definition
  `edefmem D (E:A->A->bool) x y <=>
        esubset D E y x /\
        (eempty D E y \/
         ?om vs c s z0.
             om IN D /\ vs IN D /\ c IN D /\ s IN D /\ z0 IN D /\
             eomega D E om /\ efuns D E om x vs /\ E s vs /\
             enat D E 0 z0 /\
             !u. u IN D /\ E u x
                 ==> ?s'. s' IN D /\ eupdate D E s z0 u s' /\
                          (E u y <=> esat D E x c s'))`;;

let HOLDS_DEFMEM_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v defmem_form <=> edefmem D E (v 1) (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[defmem_form; edefmem; HOLDS_AND; HOLDS_OR; HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
  ASM_SIMP_TAC[HOLDS_EMPTY_FORM] THEN
  MATCH_MP_TAC(TAUT
    `(x <=> y) ==> ((a /\ (e \/ x)) <=> (a /\ (e \/ y)))`) THEN
  SUBGOAL_THEN
   `!om vs c s z0:A.
        om IN D /\ vs IN D /\ c IN D /\ s IN D /\ z0 IN D
        ==> (holds D E
              ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
               ((2 |-> om) v)))))
              (omega_form 2) <=>
             eomega D E om) /\
            (holds D E
              ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
               ((2 |-> om) v)))))
              (funs_form 2 1 3) <=>
             efuns D E om (v 1) vs) /\
            (holds D E
              ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
               ((2 |-> om) v)))))
              (nat_form 0 6) <=>
             enat D E 0 z0)`
  (LABEL_TAC "lev1") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((6 |-> (z0:A)) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
        ((2 |-> om) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OMEGA_FORM_F; HOLDS_FUNS_FORM; HOLDS_NAT_FORM_F] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!om vs c s z0 u s':A.
        om IN D /\ vs IN D /\ c IN D /\ s IN D /\ z0 IN D /\
        u IN D /\ s' IN D
        ==> (holds D E
              ((8 |-> s') ((7 |-> u)
               ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
                ((2 |-> om) v)))))))
              (update_form 5 6 7 8) <=>
             eupdate D E s z0 u s') /\
            (holds D E
              ((8 |-> s') ((7 |-> u)
               ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
                ((2 |-> om) v)))))))
              (sat_form 1 4 8) <=>
             esat D E (v 1) c s')`
  (LABEL_TAC "lev2") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((8 |-> (s':A)) ((7 |-> u)
        ((6 |-> z0) ((5 |-> s) ((4 |-> c) ((3 |-> vs)
         ((2 |-> om) v)))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_UPDATE_FORM; HOLDS_SAT_FORM_F] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@om. h1 @vs. h2 @c. h3 @s. h4 @z0. h5 +" THEN
    USE_THEN "lev1" (fun th -> MP_TAC(SPECL
      [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(7 = 1)`] THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_IFF; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    MAP_EVERY EXISTS_TAC [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `u:A` o check (fun th ->
      is_forall(concl th) &&
      can (find_term (fun tm -> is_const tm && name_of tm = "holds"))
          (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s':A` (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    USE_THEN "lev2" (fun th -> MP_TAC(SPECL
      [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`; `u:A`; `s':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `vs:A`
      (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
        (X_CHOOSE_THEN `z0:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    EXISTS_TAC `om:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `vs:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "lev1" (fun th -> MP_TAC(SPECL
      [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    ASM_SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(7 = 1)`] THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_IFF; holds] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `u:A` o check (fun th ->
      is_forall(concl th) &&
      can (find_term (fun tm -> is_const tm && name_of tm = "esat"))
          (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s':A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
    EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "lev2" (fun th -> MP_TAC(SPECL
      [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`; `u:A`; `s':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_DEFMEM_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v defmem_form <=> edefmem D E (v 1) (v 0))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_DEFMEM_FORM_F));;

let edef = new_definition
  `edef D (E:A->A->bool) x d <=>
        d IN D /\
        !y. y IN D ==> (E y d <=> edefmem D E x y)`;;

let EDEF_IN = prove
 (`!D (E:A->A->bool) x d. edef D E x d ==> d IN D`,
  SIMP_TAC[edef]);;

let EDEF_UNIQUE_F = prove
 (`!D (E:A->A->bool) x d d'.
        model D E zfw_ax /\ edef D E x d /\ edef D E x d' ==> d = d'`,
  REWRITE_TAC[edef] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let EDEF_UNIQUE = prove
 (`!D (E:A->A->bool) x d d'.
        model D E ZF_AX /\ edef D E x d /\ edef D E x d' ==> d = d'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EDEF_UNIQUE_F));;

let EDEF_EXISTS_F = prove
 (`!D (E:A->A->bool) x.
        model D E zfw_ax /\ x IN D ==> ?d. edef D E x d`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] EPOW_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pw:A`) THEN
  SUBGOAL_THEN `(pw:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (x:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`defmem_form`; `0`; `(1 |-> (x:A)) v0`; `pw:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `d:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[edef] THEN X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (y:A)) ((1 |-> x) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (y:A)) ((1 |-> x) v0)) defmem_form <=>
    edefmem D E x y`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (y:A)) ((1 |-> x) v0)`]
          HOLDS_DEFMEM_FORM_F) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) y x` ASSUME_TAC THENL
   [ASM_MESON_TAC[edefmem]; ALL_TAC] THEN
  ASM_MESON_TAC[epow]);;

let EDEF_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN D ==> ?d. edef D E x d`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EDEF_EXISTS_F));;

(* ------------------------------------------------------------------------- *)
(* Structural facts about Def: constant internal valuations exist, the       *)
(* carving introduction (a subset of x specified pointwise by relativized    *)
(* meta-satisfaction at the 0-rebindings of a shadowed internal valuation    *)
(* is a definable subset -- via SAT_BRIDGE), hence members of a transitive x *)
(* are in Def(x); members of Def(x) are subsets of x, and Def preserves      *)
(* transitivity and extends x.                                               *)
(* ------------------------------------------------------------------------- *)

let ECONSTFUN = prove
 (`!D (E:A->A->bool) om x u0.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        u0 IN D /\ E u0 x
        ==> ?s. s IN D /\ evaluation D E om x s /\
                !n w. n IN D /\ w IN D /\ eapply D E s n w ==> w = u0`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u0:A`; `u0:A`]
        EPAIR_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sg:A`) THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sg:A`]
        ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `s:A`) THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
        ==> ((E:A->A->bool) z s <=>
             ?n. n IN D /\ E n om /\ eopair D E n u0 z)`
  (LABEL_TAC "smem") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [ecross]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[epair];
    ALL_TAC] THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!n w:A. n IN D /\ w IN D /\ eapply D (E:A->A->bool) s n w
        ==> E n om /\ w = u0`
  (LABEL_TAC "app") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?n':A. n' IN D /\ (E:A->A->bool) n' om /\ eopair D E n' u0 z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `n:A = n' /\ w:A = u0` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL [ALL_TAC; ASM_MESON_TAC[]] THEN
  REWRITE_TAC[evaluation] THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?n:A. n IN D /\ (E:A->A->bool) n om /\ eopair D E n u0 z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      MAP_EVERY X_GEN_TAC [`p:A`; `q:A`; `q':A`; `z1:A`; `z2:A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(z1:A) IN D /\ (z2:A) IN D`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `q:A = u0 /\ q':A = u0` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `n:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `u0:A`]
            EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eindom; eapply] THEN ASM_MESON_TAC[];
      REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[]];
    MAP_EVERY X_GEN_TAC [`n:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `w:A = u0` SUBST1_TAC THENL
     [ASM_MESON_TAC[]; ASM_REWRITE_TAC[]]]);;

let EDEFMEM_CARVE = prove
 (`!D (E:A->A->bool) x y om s v p c.
        model D E ZF_AX /\ x IN D /\ y IN D /\ eomega D E om /\
        evaluation D E om x s /\ shadowed D E s v /\ ecode D E p c /\
        esubset D E y x /\
        (!u. u IN D /\ E u x
             ==> (E u y <=>
                  holds (\u. u IN D /\ E u x) E ((0 |-> u) v) p))
        ==> edefmem D E x y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[edefmem] THEN
  ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (c:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_IN; ECODE_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`]
        EFUNS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `vs:A`) THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN `?z0:A. enat D (E:A->A->bool) 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EVALUATION_EFUNS]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `?s'. eupdate D (E:A->A->bool) s z0 u s'`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `z0:A`; `u:A`]
          EUPDATE_EXISTS) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(s':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
  EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) z0 om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `evaluation D (E:A->A->bool) om x s'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `z0:A`; `u:A`; `s':A`] EVALUATION_UPDATE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `shadowed D (E:A->A->bool) s' ((0 |-> u) v)`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                  `v:num->A`; `0`; `z0:A`; `u:A`; `s':A`]
          SHADOWED_UPDATE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `esat D (E:A->A->bool) x c s' <=>
    holds (\u. u IN D /\ E u x) E ((0 |-> u) v) p`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `om:A`;
                  `p:form`; `c:A`; `s':A`; `(0 |-> (u:A)) v`]
          SAT_BRIDGE) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let EDEFMEM_MEMBER = prove
 (`!D (E:A->A->bool) x om u0.
        model D E ZF_AX /\ x IN D /\ eomega D E om /\
        etransitive D E x /\ u0 IN D /\ E u0 x
        ==> edefmem D E x u0`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `u0:A`]
        ECONSTFUN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`]
        SHADOWED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `v:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(v:num->A) 1 = u0` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `1` o
      GEN_REWRITE_RULE I [shadowed] o
      check (fun th -> fst(strip_comb(concl th)) =
        `shadowed:(A->bool)->(A->A->bool)->A->(num->A)->bool`)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `n1:A`
      STRIP_ASSUME_TAC)) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?c:A. ecode D (E:A->A->bool) (0 %% 1) c`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECODE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u0:A`; `om:A`;
                `s:A`; `v:num->A`; `0 %% 1`; `c:A`]
        EDEFMEM_CARVE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  CONJ_TAC THENL
   [ASM_MESON_TAC[etransitive]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  REWRITE_TAC[holds] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[]);;

let EDEF_MEMBER = prove
 (`!D (E:A->A->bool) x d u.
        model D E ZF_AX /\ x IN D /\ etransitive D E x /\
        edef D E x d /\ u IN D /\ E u x
        ==> E u d`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  ASM_MESON_TAC[edef; EDEFMEM_MEMBER]);;

let EDEF_MEMBER_SUBSET = prove
 (`!D (E:A->A->bool) x d y.
        model D E ZF_AX /\ edef D E x d /\ y IN D /\ E y d
        ==> esubset D E y x`,
  REWRITE_TAC[edef] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[edefmem]);;

let EDEF_TRANSITIVE = prove
 (`!D (E:A->A->bool) x d.
        model D E ZF_AX /\ x IN D /\ etransitive D E x /\
        edef D E x d
        ==> etransitive D E d`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[etransitive] THEN
  X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) y x` ASSUME_TAC THENL
   [ASM_MESON_TAC[EDEF_MEMBER_SUBSET]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u x` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  ASM_MESON_TAC[EDEF_MEMBER]);;

(* ------------------------------------------------------------------------- *)
(* The L hierarchy. The step takes the history g of earlier stages to        *)
(* Def(union of the range of g), so L(a) = Def(UNION {L(b) : b IN a}) --     *)
(* at successors this is Def(L(a)) since the stages will be increasing, and  *)
(* at limits Def of the union, which contains the union (transitivity).      *)
(* eranu is the union-of-range operation (from separation inside a triple    *)
(* union), lstep_form the step formula with FV inside {0,1}, and elstage     *)
(* the stage function via the recursion theorem, exactly like ehfstage.      *)
(* ------------------------------------------------------------------------- *)

let eranu = new_definition
  `eranu D (E:A->A->bool) g w <=>
        w IN D /\
        !u. u IN D ==> (E u w <=> eranmem D E u g)`;;

let ERANU_UNIQUE_F = prove
 (`!D (E:A->A->bool) g w w'.
        model D E zfw_ax /\ eranu D E g w /\ eranu D E g w' ==> w = w'`,
  REWRITE_TAC[eranu] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY_F) THEN
  ASM_SIMP_TAC[]);;

let ERANU_UNIQUE = prove
 (`!D (E:A->A->bool) g w w'.
        model D E ZF_AX /\ eranu D E g w /\ eranu D E g w' ==> w = w'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ERANU_UNIQUE_F));;

let ERANU_EXISTS_F = prove
 (`!D (E:A->A->bool) g.
        model D E zfw_ax /\ g IN D ==> ?w. eranu D E g w`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u1:A`) THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u1:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u2:A`] EUNION_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u3:A`) THEN
  SUBGOAL_THEN `(u3:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ eranmem D (E:A->A->bool) u g ==> E u u3`
  (LABEL_TAC "bound") THENL
   [X_GEN_TAC `u:A` THEN REWRITE_TAC[eranmem] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
        (X_CHOOSE_THEN `ord:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair]) THEN
    DISCH_THEN(X_CHOOSE_THEN `sg:A` (X_CHOOSE_THEN `pp:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(sg:A) IN D /\ (pp:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) pp pr` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) pp u1` ASSUME_TAC THENL
     [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) vl pp` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) vl u2` ASSUME_TAC THENL
     [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    ASM_MESON_TAC[eunion];
    ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((1 |-> (g:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`ranmem_form 0 1`; `0`; `(1 |-> (g:A)) v0`; `u3:A`] o
    MATCH_MP ZF_SEPARATION_W) THEN
  ASM_REWRITE_TAC[ZFW_AX_MEMBERS; FRESH_SATBODY; FRESH_DEFMEM; FRESH_REC; FV;
                  FV_CLAUSES; FV_SUBSET_FORM; FV_OPAIR_FORM; FV_APPLYTO_FORM;
                  FV_FUN_FORM; FV_DOMAIN_FORM; FV_INDUCTIVE_FORM;
                  FV_RANMEM_FORM; FV_ORDINAL_FORM; IN_INSERT; IN_UNION;
                  IN_DELETE; NOT_IN_EMPTY; ARITH_EQ] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[eranu] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) ((1 |-> g) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (u:A)) ((1 |-> g) v0)) (ranmem_form 0 1) <=>
    eranmem D E u g`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (u:A)) ((1 |-> g) v0)`; `0`; `1`]
          HOLDS_RANMEM_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "bound" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let ERANU_EXISTS = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D ==> ?w. eranu D E g w`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ERANU_EXISTS_F));;

let elstep = new_definition
  `elstep D (E:A->A->bool) g y <=>
        ?w. w IN D /\ eranu D E g w /\ edef D E w y`;;

let HOLDS_LSTEP_FORM_F = prove
 (`!D (E:A->A->bool) v g y.
      model D E zfw_ax /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) lstep_form <=>
           elstep D E g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[lstep_form; holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              elstep] THEN
  SUBGOAL_THEN
   `!w u:A. w IN D /\ u IN D
      ==> (holds D E
            ((3 |-> u) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (ranmem_form 3 0) <=>
           eranmem D E u g) /\
          (holds D E
            ((3 |-> u) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))))
            (apply2_form defmem_form 3 2) <=>
           edefmem D E w u)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
       ((3 |-> (u:A)) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [ASM_SIMP_TAC[HOLDS_RANMEM_FORM] THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(3 |-> (u:A)) ((2 |-> w) ((1 |-> y) ((0 |-> g) v)))`;
                  `defmem_form`; `3`; `2`] HOLDS_APPLY2_FORM) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(3 = 0) /\ ~(3 = 1) /\ ~(2 = 0) /\ ~(2 = 1)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `valuation D
       ((1 |-> ((3 |-> (u:A)) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))) 2))
        ((0 |-> ((3 |-> u) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))) 3))
         ((3 |-> u) ((2 |-> w) ((1 |-> y) ((0 |-> g) v))))))`
    ASSUME_TAC THENL
     [REWRITE_TAC[VALMOD; ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_DEFMEM_FORM_F] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MATCH_MP_TAC(MESON[]
    `(!w:A. w IN D ==> (P w <=> Q w))
     ==> ((?w. w IN D /\ P w) <=> (?w. w IN D /\ Q w))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(eranu D (E:A->A->bool) g w <=>
     !u. u IN D ==> (E u w <=> eranmem D E u g)) /\
    (edef D (E:A->A->bool) w y <=>
     !u. u IN D ==> (E u y <=> edefmem D E w u))`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_REWRITE_TAC[eranu; edef]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
  CONJ_TAC THEN
  (MATCH_MP_TAC(MESON[]
    `(!u:A. u IN D ==> (P u <=> Q u))
     ==> ((!u. u IN D ==> P u) <=> (!u. u IN D ==> Q u))`) THEN
   X_GEN_TAC `u:A` THEN DISCH_TAC THEN
   USE_THEN "piles" (fun th -> MP_TAC(SPECL [`w:A`; `u:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   REWRITE_TAC[VALMOD; ARITH_EQ]));;

let HOLDS_LSTEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) lstep_form <=>
           elstep D E g y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_LSTEP_FORM_F));;

let LSTEP_FUN_F = prove
 (`!D (E:A->A->bool) g y y'.
        model D E zfw_ax /\ elstep D E g y /\ elstep D E g y' ==> y = y'`,
  REWRITE_TAC[elstep] THEN REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `w:A = w'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ERANU_UNIQUE_F]; ALL_TAC] THEN
  ASM_MESON_TAC[EDEF_UNIQUE_F]);;

let LSTEP_FUN = prove
 (`!D (E:A->A->bool) g y y'.
        model D E ZF_AX /\ elstep D E g y /\ elstep D E g y' ==> y = y'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW LSTEP_FUN_F));;

let LSTEP_TOTAL_F = prove
 (`!D (E:A->A->bool) g.
      model D E zfw_ax /\ g IN D ==> ?y. elstep D E g y`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[elstep] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] ERANU_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`] EDEF_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let LSTEP_TOTAL = prove
 (`!D (E:A->A->bool) g.
      model D E ZF_AX /\ g IN D ==> ?y. elstep D E g y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW LSTEP_TOTAL_F));;

let LSTEP_QFUN_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) lstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) lstep_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC LSTEP_FUN_F THEN
  MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_LSTEP_FORM_F]);;

let LSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) lstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) lstep_form
                     ==> w = w'`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW LSTEP_QFUN_F));;

let LSTEP_QTOTAL_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) lstep_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] LSTEP_TOTAL_F) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[elstep; EDEF_IN]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_LSTEP_FORM_F]);;

let LSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) lstep_form`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW LSTEP_QTOTAL_F));;

let elstage = new_definition
  `elstage D (E:A->A->bool) a y <=>
        ?v. valuation D v /\ erec D E lstep_form v a y`;;

let ELSTAGE_EREC_F = prove
 (`!D (E:A->A->bool) a y v.
        model D E zfw_ax /\ valuation D v
        ==> (elstage D E a y <=> erec D E lstep_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[elstage] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) lstep_form v' a y <=>
      erec D E lstep_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
    ASM_MESON_TAC[]]);;

let ELSTAGE_EREC = prove
 (`!D (E:A->A->bool) a y v.
        model D E ZF_AX /\ valuation D v
        ==> (elstage D E a y <=> erec D E lstep_form v a y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ELSTAGE_EREC_F));;

let ELSTAGE_UNIQUE = prove
 (`!D (E:A->A->bool) a y y'.
        model D E ZF_AX /\ a IN D /\ y IN D /\ y' IN D /\
        elstage D E a y /\ elstage D E a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lstep_form`; `v:num->A`;
                `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`] LSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ELSTAGE_EREC]);;

let ELSTAGE_EXISTS_F = prove
 (`!D (E:A->A->bool) a.
        model D E zfw_ax /\ eordinal D E a
        ==> ?y. y IN D /\ elstage D E a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lstep_form`; `v:num->A`;
                `a:A`; `5`; `20`] EREC_EXISTS_F) THEN
  ASM_REWRITE_TAC[ENGINE_READY_LSTEP] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[LSTEP_QFUN_F; LSTEP_QTOTAL_F]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ELSTAGE_EREC_F]);;

let ELSTAGE_EXISTS = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?y. y IN D /\ elstage D E a y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ELSTAGE_EXISTS_F));;

let ELSTAGE_CHAR_F = prove
 (`!D (E:A->A->bool) a y.
      model D E zfw_ax /\ eordinal D E a /\ y IN D /\ elstage D E a y
      ==> ?w. w IN D /\
              (!u. u IN D
                   ==> (E u w <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              elstage D E b z /\ E u z)) /\
              edef D E w y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) lstep_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS_F THEN
    MAP_EVERY EXISTS_TAC [`5`; `20`] THEN
    ASM_REWRITE_TAC[ENGINE_READY_LSTEP] THEN
    ASM_MESON_TAC[LSTEP_QFUN_F; LSTEP_QTOTAL_F];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `elstep D (E:A->A->bool) r y` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`; `y:A`]
          HOLDS_LSTEP_FORM_F) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION_F THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[LSTEP_QFUN_F; ELSTAGE_EREC_F];
    ALL_TAC] THEN
  REWRITE_TAC[elstep] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!b z:A. erec D (E:A->A->bool) lstep_form v b z <=>
            elstage D E b z`
  (LABEL_TAC "conv") THENL
   [ASM_MESON_TAC[ELSTAGE_EREC_F]; ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) u w <=> eranmem D E u r`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eranu]; ALL_TAC] THEN
  REWRITE_TAC[eranmem] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `vl:A` (X_CHOOSE_THEN `pr:A`
      (X_CHOOSE_THEN `ord:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))) THEN
    SUBGOAL_THEN
     `?b z:A. b IN D /\ z IN D /\ E b a /\
              erec D (E:A->A->bool) lstep_form v b z /\
              eopair D E b z pr`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erecres]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `ord:A = b /\ vl:A = z` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
          EOPAIR_EXISTS_F) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `pr:A`; `b:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[]]);;

let ELSTAGE_CHAR = prove
 (`!D (E:A->A->bool) a y.
      model D E ZF_AX /\ eordinal D E a /\ y IN D /\ elstage D E a y
      ==> ?w. w IN D /\
              (!u. u IN D
                   ==> (E u w <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              elstage D E b z /\ E u z)) /\
              edef D E w y`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ELSTAGE_CHAR_F));;

(* ------------------------------------------------------------------------- *)
(* Structure of the L hierarchy: the stage-at formula (via the recursion     *)
(* definability layer once more), transitivity of every stage (by internal   *)
(* transfinite induction on ltrans_form), monotonicity, the successor law    *)
(* L(suc a) = Def(L(a)), Delta-0 absoluteness of ordinality for transitive   *)
(* sets, and the ordinal content of the stages:                              *)
(* Ord INTER L(a) = suc a, so in particular a IN L(a). Then the class L      *)
(* (elmem) is transitive, contains all ordinals, and is stage-directed.      *)
(* ------------------------------------------------------------------------- *)

let FVLT_REC_LSTEP = prove
 (`!m. m IN FV(rec_form lstep_form 2) ==> m = 2 \/ m = 3`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MP (SPECL [`lstep_form`; `2`] FV_REC_FORM_SUB)
            (CONJ (ARITH_RULE `1 < 2`) FVLT_LSTEP_FORM)) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let FVLT_RECAPP_LSTEP = prove
 (`!a b m. m IN FV(recapp_form (rec_form lstep_form 2) a b)
           ==> m = a \/ m = b`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`rec_form lstep_form 2`; `a:num`; `b:num`]
        FV_RECAPP_FORM_SUB) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_REC_LSTEP) THEN ASM_REWRITE_TAC[]);;

let HOLDS_RECAPP_LSTEP_F = prove
 (`!D (E:A->A->bool) v i j.
        model D E zfw_ax /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (recapp_form (rec_form lstep_form 2) i j) <=>
             elstage D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `rec_form lstep_form 2`; `i:num`; `j:num`]
        HOLDS_RECAPP_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                `lstep_form`; `2`; `(v:num->A) i`; `(v:num->A) j`]
        HOLDS_REC_FORM) THEN
  ASM_REWRITE_TAC[FVLT_LSTEP_FORM; ARITH_RULE `1 < 2`;
                  ARITH_RULE `2 + 1 = 3`] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
                `(v:num->A) j`; `v:num->A`]
        ELSTAGE_EREC_F) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let HOLDS_RECAPP_LSTEP = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (recapp_form (rec_form lstep_form 2) i j) <=>
             elstage D E (v i) (v j))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_RECAPP_LSTEP_F));;

let ltrans_form = new_definition
  `ltrans_form =
     ?? 4 (recapp_form (rec_form lstep_form 2) 0 4 &&
           transitive_form 4)`;;

let HOLDS_LTRANS_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v ltrans_form <=>
             ?y. y IN D /\ elstage D E (v 0) y /\ etransitive D E y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[ltrans_form; HOLDS_EX; HOLDS_AND;
              HOLDS_TRANSITIVE_FORM] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v)
             (recapp_form (rec_form lstep_form 2) 0 4) <=>
           elstage D E (v 0) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
                  `0`; `4`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(0 = 2) /\ ~(0 = 3) /\ ~(4 = 2) /\ ~(4 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

let ELSTAGE_TRANSITIVE = prove
 (`!D (E:A->A->bool) a y.
        model D E ZF_AX /\ eordinal D E a /\ y IN D /\
        elstage D E a y
        ==> etransitive D E y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ltrans_form`; `0`;
                `v0:num->A`] EORDINAL_INDUCT) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [X_GEN_TAC `a':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!b. b IN D /\ (E:A->A->bool) b a'
          ==> ?yb. yb IN D /\ elstage D E b yb /\ etransitive D E yb`
    (LABEL_TAC "IH") THENL
     [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> b) v0) ltrans_form`
      MP_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (b:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (b:A)) v0`]
            HOLDS_LTRANS_FORM) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((0 |-> (a':A)) v0)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a':A)) v0`]
          HOLDS_LTRANS_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN `?ya:A. ya IN D /\ elstage D (E:A->A->bool) a' ya`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `ya:A`]
          ELSTAGE_CHAR) THEN
    ASM_REWRITE_TAC[] THEN
    INTRO_TAC "@w. h1 wchar h2" THEN
    SUBGOAL_THEN `etransitive D (E:A->A->bool) w` ASSUME_TAC THENL
     [REWRITE_TAC[etransitive] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      REWRITE_TAC[esubset] THEN X_GEN_TAC `u':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?b z:A. b IN D /\ z IN D /\ (E:A->A->bool) b a' /\
                elstage D E b z /\ E u z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `etransitive D (E:A->A->bool) z` ASSUME_TAC THENL
       [USE_THEN "IH" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `yb:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `z:A = yb` SUBST_ALL_TAC THENL
         [ASM_MESON_TAC[ELSTAGE_UNIQUE]; ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u' z` ASSUME_TAC THENL
       [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
      USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    EXISTS_TAC `ya:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EDEF_TRANSITIVE; eranu];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a:A)) v0`]
        HOLDS_LTRANS_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `y':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `y:A = y'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]; ASM_REWRITE_TAC[]]);;

let ELSTAGE_CHAR_TRANS = prove
 (`!D (E:A->A->bool) a y.
      model D E ZF_AX /\ eordinal D E a /\ y IN D /\ elstage D E a y
      ==> ?w. w IN D /\ etransitive D E w /\
              (!u. u IN D
                   ==> (E u w <=>
                        ?b z. b IN D /\ z IN D /\ E b a /\
                              elstage D E b z /\ E u z)) /\
              edef D E w y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `y:A`]
        ELSTAGE_CHAR) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `w:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "wchar") ASSUME_TAC)) THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) w` ASSUME_TAC THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  REWRITE_TAC[etransitive] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `u':A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `?b z:A. b IN D /\ z IN D /\ (E:A->A->bool) b a /\
            elstage D E b z /\ E u z`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) z` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
          ELSTAGE_TRANSITIVE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[EORDINAL_MEMBER];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u' z` ASSUME_TAC THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let ELSTAGE_MONO = prove
 (`!D (E:A->A->bool) a b ya yb u.
        model D E ZF_AX /\ eordinal D E a /\ E b a /\ b IN D /\
        ya IN D /\ yb IN D /\ elstage D E a ya /\ elstage D E b yb /\
        u IN D /\ E u yb
        ==> E u ya`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
        ELSTAGE_CHAR_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. h1 h2 wchar h3" THEN
  SUBGOAL_THEN `(E:A->A->bool) u w` ASSUME_TAC THENL
   [USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[EDEF_MEMBER; eranu]);;

let ELSTAGE_SUC = prove
 (`!D (E:A->A->bool) a s ya ys.
        model D E ZF_AX /\ eordinal D E a /\ esuc D E a s /\
        s IN D /\ ya IN D /\ ys IN D /\
        elstage D E a ya /\ elstage D E s ys
        ==> edef D E ya ys`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) s` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `ys:A`]
        ELSTAGE_CHAR_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. h1 h2 wchar h3" THEN
  SUBGOAL_THEN `w:A = ya` SUBST_ALL_TAC THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
    SUBGOAL_THEN `(E:A->A->bool) b a \/ b = a` MP_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    STRIP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
                    `ya:A`; `z:A`; `u:A`] ELSTAGE_MONO) THEN
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[ELSTAGE_UNIQUE]];
    DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `ya:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ESUC_E]]);;

let EORDINAL_SUBMODEL = prove
 (`!D (E:A->A->bool) w u.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        u IN D /\ E u w
        ==> (eordinal (\z. z IN D /\ E z w) E u <=> eordinal D E u)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!y:A. y IN D /\ (E:A->A->bool) y w ==> !z. z IN D /\ E z y ==> E z w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[eordinal; etransitive; elinear; esubset; IN_SUBMODEL] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT
    `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
  CONJ_TAC THENL
   [EQ_TAC THEN DISCH_TAC THENL
     [X_GEN_TAC `y:A` THEN STRIP_TAC THEN
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      X_GEN_TAC `y:A` THEN STRIP_TAC THEN
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      ASM_MESON_TAC[]];
    EQ_TAC THEN DISCH_TAC THEN
    MAP_EVERY X_GEN_TAC [`y:A`; `z:A`] THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`y:A`; `z:A`]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[]]);;

let lord_form = new_definition
  `lord_form =
     ?? 4 (recapp_form (rec_form lstep_form 2) 0 4 &&
           !! 5 ((5 %% 4 && ordinal_form 5) <-> (5 %% 0 || Eq 5 0)))`;;

let HOLDS_LORD_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lord_form <=>
             ?y. y IN D /\ elstage D E (v 0) y /\
                 !u. u IN D
                     ==> (E u y /\ eordinal D E u <=>
                          E u (v 0) \/ u = v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[lord_form; HOLDS_EX; HOLDS_AND; HOLDS_OR; HOLDS_IFF;
              holds] THEN
  SUBGOAL_THEN
   `!y u:A. y IN D /\ u IN D
      ==> (holds D E ((5 |-> u) ((4 |-> y) v))
             (ordinal_form 5) <=>
           eordinal D E u)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (u:A)) ((4 |-> y) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v)
             (recapp_form (rec_form lstep_form 2) 0 4) <=>
           elstage D E (v 0) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
                  `0`; `4`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(0 = 2) /\ ~(0 = 3) /\ ~(4 = 2) /\ ~(4 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN EQ_TAC THENL
   [INTRO_TAC "@y. h1 h2 body" THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `holds D E ((5 |-> (u:A)) ((4 |-> y) v)) (ordinal_form 5) <=>
      eordinal D E u`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "body" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    INTRO_TAC "@y. h3 h4 body" THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `holds D E ((5 |-> (u:A)) ((4 |-> y) v)) (ordinal_form 5) <=>
      eordinal D E u`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "body" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let ELSTAGE_ORD_STEP = prove
 (`!D (E:A->A->bool) a ya.
        model D E ZF_AX /\ eordinal D E a /\ ya IN D /\
        elstage D E a ya /\
        (!b. b IN D /\ E b a
             ==> ?yb. yb IN D /\ elstage D E b yb /\
                      !u. u IN D
                          ==> (E u yb /\ eordinal D E u <=>
                               E u b \/ u = b))
        ==> !u. u IN D
                ==> (E u ya /\ eordinal D E u <=> E u a \/ u = a)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 IH" THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
        ELSTAGE_CHAR_TRANS) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@w. h5 h6 wchar h7" THEN
  SUBGOAL_THEN
   `!u':A. u' IN D
        ==> ((E:A->A->bool) u' w /\ eordinal D E u' <=> E u' a)`
  (LABEL_TAC "key1") THENL
   [X_GEN_TAC `u':A` THEN DISCH_TAC THEN EQ_TAC THENL
     [STRIP_TAC THEN
      SUBGOAL_THEN
       `?b z:A. b IN D /\ z IN D /\ (E:A->A->bool) b a /\
                elstage D E b z /\ E u' z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        ALL_TAC] THEN
      USE_THEN "IH" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@yb. h8 h9 biff" THEN
      SUBGOAL_THEN `z:A = yb` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[ELSTAGE_UNIQUE]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u' b \/ u' = b` STRIP_ASSUME_TAC THENL
       [USE_THEN "biff" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[eordinal; etransitive; esubset];
        ASM_REWRITE_TAC[]];
      DISCH_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) u'` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "IH" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@yu. h10 h11 uiff" THEN
      SUBGOAL_THEN `(E:A->A->bool) u' yu` ASSUME_TAC THENL
       [USE_THEN "uiff" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "wchar" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) u w` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `ya:A`; `u:A`]
            EDEF_MEMBER_SUBSET) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) u a` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) z'` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z' w` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      USE_THEN "key1" (fun th -> MP_TAC(SPEC `z':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `a:A`]
          EORDINAL_TRICHOTOMY) THEN
    ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(E:A->A->bool) a a` MP_TAC THENL
     [ASM_MESON_TAC[esubset]; ASM_MESON_TAC[E_IRREFL]];
    ALL_TAC] THEN
  STRIP_TAC THENL
   [SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(E:A->A->bool) u w` ASSUME_TAC THENL
     [USE_THEN "key1" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `ya:A`; `u:A`]
          EDEF_MEMBER) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) a w` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `u':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) u'` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    USE_THEN "key1" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o snd o EQ_IMP_RULE) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `edefmem D (E:A->A->bool) w a` ASSUME_TAC THENL
   [ALL_TAC; ASM_MESON_TAC[edef]] THEN
  ASM_CASES_TAC `?u0:A. u0 IN D /\ (E:A->A->bool) u0 w` THENL
   [ALL_TAC;
    REWRITE_TAC[edefmem] THEN ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN
    REWRITE_TAC[eempty] THEN ASM_MESON_TAC[esubset]] THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `u0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `u0:A`]
        ECONSTFUN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`]
        SHADOWED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `vs:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?c:A. ecode D (E:A->A->bool) (ordinal_form 0) c`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECODE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `a:A`; `om:A`;
                `s:A`; `vs:num->A`; `ordinal_form 0`; `c:A`]
        EDEFMEM_CARVE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  X_GEN_TAC `u':A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation (\z. z IN D /\ (E:A->A->bool) z w) ((0 |-> u') vs)`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation; IN_SUBMODEL] THEN X_GEN_TAC `i:num` THEN
    REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[shadowed; SHADOWED_RANGE];
    ALL_TAC] THEN
  MP_TAC(SPECL [`\z. z IN D /\ (E:A->A->bool) z w`; `E:A->A->bool`;
                `(0 |-> (u':A)) vs`; `0`] HOLDS_ORDINAL_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `u':A`]
        EORDINAL_SUBMODEL) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "key1" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[]);;

let ELSTAGE_ORD = prove
 (`!D (E:A->A->bool) a y.
        model D E ZF_AX /\ eordinal D E a /\ y IN D /\
        elstage D E a y
        ==> !u. u IN D
                ==> (E u y /\ eordinal D E u <=> E u a \/ u = a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lord_form`; `0`;
                `v0:num->A`] EORDINAL_INDUCT) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [X_GEN_TAC `a':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!b. b IN D /\ (E:A->A->bool) b a'
          ==> ?yb. yb IN D /\ elstage D E b yb /\
                   !u. u IN D
                       ==> (E u yb /\ eordinal D E u <=>
                            E u b \/ u = b)`
    (LABEL_TAC "IH") THENL
     [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `holds D (E:A->A->bool) ((0 |-> b) v0) lord_form`
      MP_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (b:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (b:A)) v0`]
            HOLDS_LORD_FORM) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD; ARITH_EQ];
      ALL_TAC] THEN
    SUBGOAL_THEN `valuation D ((0 |-> (a':A)) v0)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a':A)) v0`]
          HOLDS_LORD_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    SUBGOAL_THEN `?ya:A. ya IN D /\ elstage D (E:A->A->bool) a' ya`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `ya:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `ya:A`]
          ELSTAGE_ORD_STEP) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    USE_THEN "IH" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a:A)) v0`]
        HOLDS_LORD_FORM) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  DISCH_THEN(X_CHOOSE_THEN `y':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `y:A = y'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]; ASM_REWRITE_TAC[]]);;

let ELSTAGE_ORD_SELF = prove
 (`!D (E:A->A->bool) a y.
        model D E ZF_AX /\ eordinal D E a /\ y IN D /\
        elstage D E a y
        ==> E a y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `y:A`]
        ELSTAGE_ORD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let elmem = new_definition
  `elmem D (E:A->A->bool) u <=>
        ?a y. a IN D /\ y IN D /\ eordinal D E a /\
              elstage D E a y /\ E u y`;;

let ELMEM_ORDINAL = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a ==> elmem D E a`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[elmem] THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?y:A. y IN D /\ elstage D (E:A->A->bool) a y`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `y:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ELSTAGE_ORD_SELF]);;

let ELMEM_MEMBER = prove
 (`!D (E:A->A->bool) u u'.
        model D E ZF_AX /\ u IN D /\ elmem D E u /\
        u' IN D /\ E u' u
        ==> elmem D E u'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[elmem] THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `y:A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) y` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_TRANSITIVE]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) u y` MP_TAC THENL
   [ASM_MESON_TAC[etransitive]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `u':A`) THEN
  ASM_REWRITE_TAC[]);;

let ELMEM_DIRECTED = prove
 (`!D (E:A->A->bool) u u'.
        model D E ZF_AX /\ u IN D /\ u' IN D /\
        elmem D E u /\ elmem D E u'
        ==> ?a y. a IN D /\ y IN D /\ eordinal D E a /\
                  elstage D E a y /\ E u y /\ E u' y`,
  REPEAT GEN_TAC THEN REWRITE_TAC[elmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))
      (X_CHOOSE_THEN `a':A` (X_CHOOSE_THEN `y':A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`a':A`; `y':A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `a:A`;
                  `y':A`; `y:A`; `u:A`] ELSTAGE_MONO) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[EORDINAL_IN];
    MAP_EVERY EXISTS_TAC [`a':A`; `y':A`] THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `y:A = y'` (fun th -> ASM_MESON_TAC[th]) THEN
    ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN];
    MAP_EVERY EXISTS_TAC [`a:A`; `y:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`;
                  `y:A`; `y':A`; `u':A`] ELSTAGE_MONO) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[EORDINAL_IN]]);;

(* ------------------------------------------------------------------------- *)
(* Introduction rule for models of ZF: to show model D E ZF_AX it suffices   *)
(* to establish the nine semantic facts (nonemptiness, extensionality,       *)
(* foundation, pairing, union, powerset, infinity, and the separation and    *)
(* replacement schemes over all meta-level formulas). This is the interface  *)
(* through which L |= ZF will be assembled: each fact is proved for the      *)
(* domain lclass D E below, with no further syntax manipulation.             *)
(* ------------------------------------------------------------------------- *)

let ZF_MODEL_INTRO = prove
 (`!D (E:A->A->bool).
        ~(D = {}) /\
        (!x y. x IN D /\ y IN D /\ (!z. z IN D ==> (E z x <=> E z y))
               ==> x = y) /\
        (!x. x IN D /\ (?u. u IN D /\ E u x)
             ==> ?y. y IN D /\ E y x /\
                     !z. z IN D /\ E z y ==> ~(E z x)) /\
        (!x y. x IN D /\ y IN D
               ==> ?p. p IN D /\ !z. z IN D ==> (E z p <=> z = x \/ z = y)) /\
        (!x. x IN D
             ==> ?u. u IN D /\
                     !z. z IN D ==>
                       (E z u <=> ?w. w IN D /\ E w x /\ E z w)) /\
        (!x. x IN D
             ==> ?pp. pp IN D /\
                      !z. z IN D
                          ==> (E z pp <=> !w. w IN D /\ E w z ==> E w x)) /\
        (?i. i IN D /\
             (?e. e IN D /\ E e i /\ !z. z IN D ==> ~(E z e)) /\
             (!u. u IN D /\ E u i
                  ==> ?s. s IN D /\ E s i /\
                          !z. z IN D ==> (E z s <=> E z u \/ z = u))) /\
        (!p x v a.
             valuation D v /\ a IN D
             ==> ?s. s IN D /\
                     !z. z IN D
                         ==> (E z s <=> E z a /\ holds D E ((x |-> z) v) p)) /\
        (!p x y v a.
             ~(x = y) /\ valuation D v /\ a IN D /\
             (!u. u IN D /\ E u a
                  ==> ?w. w IN D /\
                          !w'. w' IN D /\
                               holds D E ((y |-> w') ((x |-> u) v)) p
                               ==> w' = w)
             ==> ?b. b IN D /\
                     !w. w IN D
                         ==> (E w b <=>
                              ?u. u IN D /\ E u a /\
                                  holds D E ((y |-> w) ((x |-> u) v)) p))
        ==> model D E ZF_AX`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 ext fnd pai uni pow inf sep rep" THEN
  ASM_REWRITE_TAC[model; satisfies] THEN
  X_GEN_TAC `v:num->A` THEN X_GEN_TAC `q:form` THEN
  REWRITE_TAC[ZF_AX; IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_ELIM_THM] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN STRIP_TAC THENL
   [FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "ext" MP_TAC THEN
    REWRITE_TAC[extensionality_ax; holds; HOLDS_IFF; VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "fnd" MP_TAC THEN
    SIMP_TAC[foundation_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT;
             HOLDS_AND; HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM;
             VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "pai" MP_TAC THEN
    SIMP_TAC[pairing_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT;
             HOLDS_AND; HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM;
             VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "uni" MP_TAC THEN
    SIMP_TAC[union_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT;
             HOLDS_AND; HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM;
             VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "pow" MP_TAC THEN
    SIMP_TAC[powerset_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT;
             HOLDS_AND; HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM;
             VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN USE_THEN "inf" MP_TAC THEN
    SIMP_TAC[infinity_ax; holds; HOLDS_IFF; HOLDS_EX; HOLDS_NOT;
             HOLDS_AND; HOLDS_OR; HOLDS_FORALLMEM; HOLDS_EXISTSMEM;
             VALMOD; ARITH_EQ] THEN
    MESON_TAC[];
    FIRST_X_ASSUM SUBST1_TAC THEN
    ASM_SIMP_TAC[separation_ax; holds; HOLDS_EX; HOLDS_IFF; HOLDS_AND;
                 VALMOD_BASIC; VALMOD_OTHER; HOLDS_VALMOD_STRIP1];
    FIRST_X_ASSUM SUBST1_TAC THEN
    SUBGOAL_THEN
     `~(y:num = x) /\ ~(z:num = y) /\ ~(z:num = x) /\
      ~(a:num = x) /\ ~(a:num = y) /\ ~(a:num = z) /\
      ~(b:num = x) /\ ~(b:num = y) /\ ~(b:num = z) /\ ~(b:num = a)`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[replacement_ax; holds; HOLDS_EX; HOLDS_IFF; HOLDS_AND;
                 HOLDS_FORALLMEM; HOLDS_EXISTSMEM; VALMOD_BASIC;
                 VALMOD_OTHER; HOLDS_VALMOD_STRIP1; HOLDS_VALMOD_STRIP2] THEN
    X_GEN_TAC `aa:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `!w u. holds D (E:A->A->bool) ((x |-> u) ((y |-> w) v)) p <=>
            holds D E ((y |-> w) ((x |-> u) v)) p`
    (LABEL_TAC "sw") THENL
     [REPEAT GEN_TAC THEN MATCH_MP_TAC HOLDS_VALMOD_SWAP THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(LABEL_TAC "uq") THEN
    USE_THEN "rep" (MP_TAC o SPECL
      [`p:form`; `x:num`; `y:num`; `v:num->A`; `aa:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      USE_THEN "uq" (fun th -> MESON_TAC[th]);
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      USE_THEN "sw" (fun sw ->
        ACCEPT_TAC(REWRITE_RULE[GSYM sw] th)))]);;

(* ------------------------------------------------------------------------- *)
(* The class L as a domain: lclass D E = the members of D lying in some      *)
(* constructible stage. It is nonempty (the empty set is an ordinal, hence   *)
(* constructible), transitive as a class, and inherits extensionality and    *)
(* foundation from D by restriction. ELMEM_INTRO is the workhorse closure    *)
(* rule: any z SUBSET L(a) in D that is carved from L(a) by an object        *)
(* formula with two parameters from L(a) (via the internal-definability      *)
(* apparatus: constant function + two updates + code) lies in Def(L(a)) =    *)
(* L(suc a), hence in L. Pairs, unions and omega are then constructible,     *)
(* giving the pairing, union and infinity axioms for the L domain.           *)
(* ------------------------------------------------------------------------- *)

let lclass = new_definition
  `lclass D (E:A->A->bool) = {u | u IN D /\ elmem D E u}`;;

let IN_LCLASS = prove
 (`!D (E:A->A->bool) u. u IN lclass D E <=> u IN D /\ elmem D E u`,
  REWRITE_TAC[lclass; IN_ELIM_THM]);;

let LCLASS_SUBSET = prove
 (`!D (E:A->A->bool). lclass D E SUBSET D`,
  REWRITE_TAC[SUBSET; IN_LCLASS] THEN MESON_TAC[]);;

let LCLASS_NONEMPTY = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> ~(lclass D E = {})`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?z:A. eempty D (E:A->A->bool) z` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN lclass D E` MP_TAC THENL
   [REWRITE_TAC[IN_LCLASS] THEN
    ASM_MESON_TAC[EORDINAL_EEMPTY; ELMEM_ORDINAL; eempty];
    ASM_REWRITE_TAC[NOT_IN_EMPTY]]);;

let LCLASS_MEMBER = prove
 (`!D (E:A->A->bool) u w.
        model D E ZF_AX /\ u IN lclass D E /\ w IN D /\ E w u
        ==> w IN lclass D E`,
  REWRITE_TAC[IN_LCLASS] THEN MESON_TAC[ELMEM_MEMBER]);;

let LCLASS_EXTENSIONAL = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x y. x IN lclass D E /\ y IN lclass D E /\
               (!z. z IN lclass D E ==> (E z x <=> E z y))
               ==> x = y`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (y:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) z x` THENL
   [SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ASM_MESON_TAC[]];
    ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) z y` THENL
   [SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ASM_MESON_TAC[]];
    ASM_REWRITE_TAC[]]);;

let LCLASS_FOUNDATION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN lclass D E /\ (?u. u IN lclass D E /\ E u x)
             ==> ?y. y IN lclass D E /\ E y x /\
                     !z. z IN lclass D E /\ E z y ==> ~(E z x)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_FOUNDATION) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; IN_LCLASS]);;

let ELMEM_INTRO = prove
 (`!D (E:A->A->bool) a ya z u1 u2 p.
        model D E ZF_AX /\ eordinal D E a /\ ya IN D /\
        elstage D E a ya /\ z IN D /\
        u1 IN D /\ E u1 ya /\ u2 IN D /\ E u2 ya /\
        esubset D E z ya /\
        (!u v. u IN D /\ E u ya /\ valuation D v /\
               v 1 = u1 /\ v 2 = u2 /\ (!i. E (v i) ya)
               ==> (E u z <=>
                    holds (\t. t IN D /\ E t ya) E ((0 |-> u) v) p))
        ==> elmem D E z`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 char" THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ESUC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `?ys:A. ys IN D /\ elstage D (E:A->A->bool) sa ys`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `edef D (E:A->A->bool) ya ys` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `sa:A`;
                  `ya:A`; `ys:A`] ELSTAGE_SUC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `edefmem D (E:A->A->bool) ya z` ASSUME_TAC THENL
   [ALL_TAC;
    REWRITE_TAC[elmem] THEN
    MAP_EVERY EXISTS_TAC [`sa:A`; `ys:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[edef]] THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ya:A`; `u1:A`]
        ECONSTFUN) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `s0:A` (fun th ->
    MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ya:A`; `s0:A`]
        SHADOWED_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `v0:num->A` (fun th ->
    MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
  SUBGOAL_THEN `?n1:A. enat D (E:A->A->bool) 1 n1` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(n1:A) IN D /\ (E:A->A->bool) n1 om`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN; ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `?s1:A. eupdate D (E:A->A->bool) s0 n1 u1 s1`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `evaluation D (E:A->A->bool) om ya s1` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_UPDATE]; ALL_TAC] THEN
  SUBGOAL_THEN `shadowed D (E:A->A->bool) s1 ((1 |-> u1) v0)`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[SHADOWED_UPDATE]; ALL_TAC] THEN
  SUBGOAL_THEN `(s1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
  SUBGOAL_THEN `?n2:A. enat D (E:A->A->bool) 2 n2` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(n2:A) IN D /\ (E:A->A->bool) n2 om`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN; ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `?s2:A. eupdate D (E:A->A->bool) s1 n2 u2 s2`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `evaluation D (E:A->A->bool) om ya s2` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_UPDATE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `shadowed D (E:A->A->bool) s2 ((2 |-> u2) ((1 |-> u1) v0))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[SHADOWED_UPDATE]; ALL_TAC] THEN
  SUBGOAL_THEN `?c:A. ecode D (E:A->A->bool) p c` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ya:A`; `z:A`; `om:A`;
                `s2:A`; `(2 |-> u2) ((1 |-> u1) (v0:num->A))`;
                `p:form`; `c:A`] EDEFMEM_CARVE) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  USE_THEN "char" (MP_TAC o SPECL
    [`u:A`; `(2 |-> u2) ((1 |-> u1) (v0:num->A))`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD; SHADOWED_VALUATION];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      REWRITE_TAC[VALMOD; ARITH_EQ];
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[])];
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

let ELMEM_EPAIR = prove
 (`!D (E:A->A->bool) u w z.
        model D E ZF_AX /\ u IN D /\ w IN D /\
        elmem D E u /\ elmem D E w /\ epair D E u w z
        ==> elmem D E z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`]
        ELMEM_DIRECTED) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [epair]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "zch")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`; `z:A`;
                `u:A`; `w:A`; `Eq 0 1 || Eq 0 2`] ELMEM_INTRO) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "zch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN X_GEN_TAC `vv:num->A` THEN STRIP_TAC THEN
  REWRITE_TAC[HOLDS_OR; holds; VALMOD; ARITH_EQ] THEN
  USE_THEN "zch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

let ELMEM_EUNION = prove
 (`!D (E:A->A->bool) u z.
        model D E ZF_AX /\ u IN D /\ elmem D E u /\ eunion D E u z
        ==> elmem D E z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elmem]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "zch")) THEN
  SUBGOAL_THEN
   `!s t:A. s IN D /\ t IN D /\ (E:A->A->bool) s t /\ E t ya ==> E s ya`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[ELSTAGE_TRANSITIVE; etransitive; esubset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`; `z:A`;
                `u:A`; `u:A`; `??- 3 1 (0 %% 3)`] ELMEM_INTRO) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "zch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `?w:A. w IN D /\ (E:A->A->bool) w u /\ E t w`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w ya` ASSUME_TAC THENL
     [USE_THEN "tr" (MP_TAC o SPECL [`w:A`; `u:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "tr" (MP_TAC o SPECL [`t:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN X_GEN_TAC `vv:num->A` THEN STRIP_TAC THEN
  SIMP_TAC[HOLDS_EXISTSMEM; ARITH_RULE `~(3 = 1)`] THEN
  REWRITE_TAC[holds; IN_SUBMODEL; VALMOD; ARITH_EQ] THEN
  USE_THEN "zch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `wt:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `wt:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "tr" (MP_TAC o SPECL [`wt:A`; `u:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    DISCH_THEN(X_CHOOSE_THEN `wt:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `wt:A` THEN ASM_REWRITE_TAC[]]);;

let ELMEM_EOMEGA = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ eomega D E om ==> elmem D E om`,
  MESON_TAC[EOMEGA_ORDINAL; ELMEM_ORDINAL]);;

let LCLASS_PAIRING = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x y. x IN lclass D E /\ y IN lclass D E
               ==> ?p. p IN lclass D E /\
                       !z. z IN lclass D E ==> (E z p <=> z = x \/ z = y)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[IN_LCLASS] THEN STRIP_TAC THEN
  SUBGOAL_THEN `?z:A. epair D (E:A->A->bool) x y z` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN];
    ASM_MESON_TAC[ELMEM_EPAIR];
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN ASM_MESON_TAC[epair]]);;

let LCLASS_UNION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN lclass D E
             ==> ?u. u IN lclass D E /\
                     !z. z IN lclass D E
                         ==> (E z u <=>
                              ?w. w IN lclass D E /\ E w x /\ E z w)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `x:A` THEN REWRITE_TAC[IN_LCLASS] THEN STRIP_TAC THEN
  SUBGOAL_THEN `?z:A. eunion D (E:A->A->bool) x z` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  EXISTS_TAC `z:A` THEN REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[EUNION_IN];
    ASM_MESON_TAC[ELMEM_EUNION];
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ELMEM_MEMBER];
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[]]]);;

let LCLASS_INFINITY = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> ?i. i IN lclass D E /\
             (?e. e IN lclass D E /\ E e i /\
                  !z. z IN lclass D E ==> ~(E z e)) /\
             (!u. u IN lclass D E /\ E u i
                  ==> ?s. s IN lclass D E /\ E s i /\
                          !z. z IN lclass D E
                              ==> (E z s <=> E z u \/ z = u))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  EXISTS_TAC `om:A` THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[IN_LCLASS] THEN ASM_MESON_TAC[ELMEM_EOMEGA];
    SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
     [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
    REWRITE_TAC[einductive] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) ASSUME_TAC)) THEN
    EXISTS_TAC `e:A` THEN
    SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
    ASM_REWRITE_TAC[IN_LCLASS] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EORDINAL_EEMPTY; ELMEM_ORDINAL];
      ASM_MESON_TAC[eempty]];
    X_GEN_TAC `u:A` THEN REWRITE_TAC[IN_LCLASS] THEN STRIP_TAC THEN
    SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
     [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
    REWRITE_TAC[einductive] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (K ALL_TAC) (MP_TAC o SPEC `u:A`))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `s:A` THEN
    SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[IN_LCLASS] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS; ELMEM_ORDINAL]; ALL_TAC] THEN
    X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s:A`; `zz:A`]
          ESUC_E) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* The powerset axiom for the L domain. Machinery: lmem_form (an object      *)
(* formula for "x is constructible", via the internalized L-recursion),      *)
(* instage_form and rank_form (x lies in stage a; a is the least such        *)
(* stage index), unions of sets of ordinals are ordinals, every              *)
(* constructible set has a least rank (by foundation on the ranks below a    *)
(* witness, carved by separation with instage_form), and the key bounding    *)
(* lemma: any set in D all of whose members are constructible is covered     *)
(* by a single stage (replacement along rank_form, then the union of the     *)
(* resulting set of ordinals). The relative power set P(u) INTER L is then   *)
(* carved by separation with lmem_form, bounded by a stage, and shown        *)
(* constructible by ELMEM_INTRO with subset_form; relativizing gives the     *)
(* powerset axiom in L (bounded quantifiers are absolute by transitivity).   *)
(* ------------------------------------------------------------------------- *)

let lmem_form = new_definition
  `lmem_form = ?? 4 (ordinal_form 4 &&
                     ?? 5 (recapp_form (rec_form lstep_form 2) 4 5 &&
                           0 %% 5))`;;

let HOLDS_LMEM_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v lmem_form <=> elmem D E (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[lmem_form; HOLDS_EX; HOLDS_AND; holds] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((4 |-> a) v) (ordinal_form 4) <=>
           eordinal D E a)`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a y:A. a IN D /\ y IN D
      ==> (holds D E ((5 |-> y) ((4 |-> a) v))
             (recapp_form (rec_form lstep_form 2) 4 5) <=>
           elstage D E a y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (y:A)) ((4 |-> (a:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(5 |-> (y:A)) ((4 |-> (a:A)) v)`;
                  `4`; `5`] HOLDS_RECAPP_LSTEP_F) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(4 = 2) /\ ~(4 = 3) /\ ~(5 = 2) /\ ~(5 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ; elmem] THEN ASM_MESON_TAC[]);;

let HOLDS_LMEM_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lmem_form <=> elmem D E (v 0))`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW HOLDS_LMEM_FORM_F));;

let instage_form = new_definition
  `instage_form = ?? 4 (recapp_form (rec_form lstep_form 2) 0 4 &&
                        1 %% 4)`;;

let HOLDS_INSTAGE_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v instage_form <=>
             ?y. y IN D /\ elstage D E (v 0) y /\ E (v 1) y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[instage_form; HOLDS_EX; HOLDS_AND; holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v)
             (recapp_form (rec_form lstep_form 2) 0 4) <=>
           elstage D E (v 0) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
                  `0`; `4`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(0 = 2) /\ ~(0 = 3) /\ ~(4 = 2) /\ ~(4 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

let rank_form = new_definition
  `rank_form = ordinal_form 1 &&
               (?? 4 (recapp_form (rec_form lstep_form 2) 1 4 &&
                      0 %% 4)) &&
               (!!- 5 1 (Not(?? 6 (recapp_form (rec_form lstep_form 2) 5 6 &&
                                   0 %% 6))))`;;

let HOLDS_RANK_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v rank_form <=>
             eordinal D E (v 1) /\
             (?y. y IN D /\ elstage D E (v 1) y /\ E (v 0) y) /\
             (!c. c IN D /\ E c (v 1)
                  ==> ~(?y. y IN D /\ elstage D E c y /\ E (v 0) y)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[rank_form] THEN
  SIMP_TAC[HOLDS_AND; HOLDS_EX; HOLDS_NOT; HOLDS_FORALLMEM;
           ARITH_RULE `~(5 = 1)`] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  REWRITE_TAC[holds] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v)
             (recapp_form (rec_form lstep_form 2) 1 4) <=>
           elstage D E (v 1) y)`
  ASSUME_TAC THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
                  `1`; `4`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(1 = 2) /\ ~(1 = 3) /\ ~(4 = 2) /\ ~(4 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c y:A. c IN D /\ y IN D
      ==> (holds D E ((6 |-> y) ((5 |-> c) v))
             (recapp_form (rec_form lstep_form 2) 5 6) <=>
           elstage D E c y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((6 |-> (y:A)) ((5 |-> (c:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(6 |-> (y:A)) ((5 |-> (c:A)) v)`;
                  `5`; `6`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
      `~(5 = 2) /\ ~(5 = 3) /\ ~(6 = 2) /\ ~(6 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_MESON_TAC[]);;

let EORDINAL_SUBSET_MEMBER = prove
 (`!D (E:A->A->bool) a b.
        model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
        esubset D E a b
        ==> E a b \/ a = b`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) b b` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset; eordinal]; ALL_TAC] THEN
  ASM_MESON_TAC[E_IRREFL; eordinal]);;

let EORDINAL_EUNION = prove
 (`!D (E:A->A->bool) b z.
        model D E ZF_AX /\ b IN D /\
        (!c. c IN D /\ E c b ==> eordinal D E c) /\
        eunion D E b z
        ==> eordinal D E z`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "zch")) THEN
  SUBGOAL_THEN
   `!t:A. t IN D /\ (E:A->A->bool) t z ==> eordinal D E t`
  (LABEL_TAC "allord") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "zch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `?c:A. c IN D /\ (E:A->A->bool) c b /\ E t c`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[EORDINAL_MEMBER];
    ALL_TAC] THEN
  REWRITE_TAC[eordinal] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[etransitive] THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    USE_THEN "zch" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    SUBGOAL_THEN `?c:A. c IN D /\ (E:A->A->bool) c b /\ E y c`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s c` ASSUME_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
    USE_THEN "zch" (MP_TAC o SPEC `s:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[];
    REWRITE_TAC[elinear] THEN
    ASM_MESON_TAC[EORDINAL_TRICHOTOMY]]);;

let ELMEM_RANK = prove
 (`!D (E:A->A->bool) z.
        model D E ZF_AX /\ z IN D /\ elmem D E z
        ==> ?a. a IN D /\ eordinal D E a /\
                (?y. y IN D /\ elstage D E a y /\ E z y) /\
                (!c. c IN D /\ E c a
                     ==> ~(?y. y IN D /\ elstage D E c y /\ E z y))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elmem]) THEN
  DISCH_THEN(X_CHOOSE_THEN `a0:A` (X_CHOOSE_THEN `y0:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa0:A`) THEN
  SUBGOAL_THEN `(sa0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a0 sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (z:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`instage_form`; `0`; `(1 |-> (z:A)) v0`; `sa0:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ss:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN
   `!t:A. t IN D
      ==> ((E:A->A->bool) t ss <=>
           E t sa0 /\ ?y. y IN D /\ elstage D E t y /\ E z y)`
  (LABEL_TAC "sch2") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "sch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (t:A)) ((1 |-> (z:A)) v0)`]
          HOLDS_INSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ss:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `a0:A` THEN
    SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sch2" (MP_TAC o SPEC `a0:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@a. h1 h2 min" THEN
  SUBGOAL_THEN
   `(E:A->A->bool) a sa0 /\ ?y. y IN D /\ elstage D E a y /\ E z y`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "sch2" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c sa0` ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  USE_THEN "min" (MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  USE_THEN "sch2" (MP_TAC o SPEC `c:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[]);;

let ELMEM_RANK_UNIQUE = prove
 (`!D (E:A->A->bool) z a a'.
        model D E ZF_AX /\
        eordinal D E a /\
        (?y. y IN D /\ elstage D E a y /\ E z y) /\
        (!c. c IN D /\ E c a
             ==> ~(?y. y IN D /\ elstage D E c y /\ E z y)) /\
        eordinal D E a' /\
        (?y. y IN D /\ elstage D E a' y /\ E z y) /\
        (!c. c IN D /\ E c a'
             ==> ~(?y. y IN D /\ elstage D E c y /\ E z y))
        ==> a = a'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
        EORDINAL_TRICHOTOMY) THEN
  ASM_REWRITE_TAC[] THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EORDINAL_IN]);;

let ELMEM_BOUND = prove
 (`!D (E:A->A->bool) pl.
        model D E ZF_AX /\ pl IN D /\
        (!z. z IN D /\ E z pl ==> elmem D E z)
        ==> ?c yc. c IN D /\ yc IN D /\ eordinal D E c /\
                   elstage D E c yc /\
                   !z. z IN D /\ E z pl ==> E z yc`,
  REPEAT GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "allc"))) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
        ==> (holds D E ((1 |-> w) ((0 |-> z) v0)) rank_form <=>
             eordinal D E w /\
             (?y. y IN D /\ elstage D E w y /\ E z y) /\
             (!c. c IN D /\ E c w
                  ==> ~(?y. y IN D /\ elstage D E c y /\ E z y)))`
  (LABEL_TAC "hrk") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(1 |-> (w:A)) ((0 |-> (z:A)) v0)`]
          HOLDS_RANK_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`rank_form`; `0`; `1`; `v0:num->A`; `pl:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `elmem D (E:A->A->bool) z` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`] ELMEM_RANK) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (fun th ->
      MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) w' /\
      (?y. y IN D /\ elstage D E w' y /\ E z y) /\
      (!c. c IN D /\ E c w'
           ==> ~(?y. y IN D /\ elstage D E c y /\ E z y))`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `w':A`; `a:A`]
          ELMEM_RANK_UNIQUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w bb ==> eordinal D E w`
  (LABEL_TAC "bord") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `w:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?b0:A. eunion D (E:A->A->bool) bb b0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(b0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b0` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bb:A`; `b0:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?yb:A. yb IN D /\ elstage D (E:A->A->bool) b0 yb`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`b0:A`; `yb:A`] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) z` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`] ELMEM_RANK) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `ya:A` STRIP_ASSUME_TAC)
      (LABEL_TAC "amin"))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a bb` ASSUME_TAC THENL
   [USE_THEN "bch" (MP_TAC o SPEC `a:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hrk" (MP_TAC o SPECL [`z:A`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) a b0` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b0:A`]
        EORDINAL_SUBSET_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b0:A`; `a:A`;
                  `yb:A`; `ya:A`; `z:A`] ELSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]]);;

let ELMEM_EPOW = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ u IN D /\ elmem D E u
        ==> ?pl. pl IN D /\ elmem D E pl /\
                 !z. z IN D
                     ==> (E z pl <=> esubset D E z u /\ elmem D E z)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?pp:A. epow D (E:A->A->bool) u pp`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [epow]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (LABEL_TAC "pch")) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`lmem_form`; `0`; `v0:num->A`; `pp:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pl:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "plch"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> ((E:A->A->bool) z pl <=> esubset D E z u /\ elmem D E z)`
  (LABEL_TAC "plch2") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "plch" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(0 |-> (z:A)) v0`] HOLDS_LMEM_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    USE_THEN "pch" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EXISTS_TAC `pl:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `pl:A`] ELMEM_BOUND) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "plch2" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `yc:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  UNDISCH_TAC `elmem D (E:A->A->bool) u` THEN
  GEN_REWRITE_TAC LAND_CONV [elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `au:A` (X_CHOOSE_THEN `yu:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN
   `?d yd:A. d IN D /\ yd IN D /\ eordinal D (E:A->A->bool) d /\
             elstage D E d yd /\ E u yd /\
             !z. z IN D /\ E z pl ==> E z yd`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `au:A`; `c:A`]
          EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `au:A`;
                    `yc:A`; `yu:A`; `u:A`] ELSTAGE_MONO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ELSTAGE_UNIQUE];
      MAP_EVERY EXISTS_TAC [`au:A`; `yu:A`] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `au:A`; `c:A`;
                    `yu:A`; `yc:A`; `z:A`] ELSTAGE_MONO) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) yd` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_TRANSITIVE]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `yd:A`; `pl:A`;
                `u:A`; `u:A`; `subset_form 0 1`] ELMEM_INTRO) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN X_GEN_TAC `vv:num->A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`\s:A. s IN D /\ (E:A->A->bool) s yd`; `E:A->A->bool`;
                `(0 |-> (t:A)) (vv:num->A)`; `0`; `1`]
        HOLDS_SUBSET_FORM) THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "plch2" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) t` ASSUME_TAC THENL
   [REWRITE_TAC[elmem] THEN
    MAP_EVERY EXISTS_TAC [`d:A`; `yd:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset; IN_SUBMODEL] THEN
  EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "sub") THEN X_GEN_TAC `w:A` THEN
    STRIP_TAC THEN
    USE_THEN "sub" (MP_TAC o SPEC `w:A`) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "sub") THEN X_GEN_TAC `w:A` THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w yd` ASSUME_TAC THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    USE_THEN "sub" (MP_TAC o SPEC `w:A`) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let LCLASS_POWERSET = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !x. x IN lclass D E
             ==> ?pp. pp IN lclass D E /\
                      !z. z IN lclass D E
                          ==> (E z pp <=>
                               !w. w IN lclass D E /\ E w z ==> E w x)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `x:A` THEN REWRITE_TAC[IN_LCLASS] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] ELMEM_EPOW) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@pl. h1 h2 plch" THEN
  EXISTS_TAC `pl:A` THEN REWRITE_TAC[IN_LCLASS] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN STRIP_TAC THEN
  USE_THEN "plch" (MP_TAC o SPEC `z:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset; IN_LCLASS] THEN
  EQ_TAC THENL
   [MESON_TAC[];
    DISCH_THEN(LABEL_TAC "sub") THEN X_GEN_TAC `w:A` THEN
    STRIP_TAC THEN
    USE_THEN "sub" (MP_TAC o SPEC `w:A`) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ELMEM_MEMBER]]);;

(* ------------------------------------------------------------------------- *)
(* Relativization of a formula to the class L: lmem_at n is the              *)
(* constructibility formula at an arbitrary variable n (bound variables      *)
(* chosen by MAX to clear both n and the rec_form slots 2,3), and relativ p  *)
(* restricts every quantifier of p by it. The bridge theorem HOLDS_RELATIV   *)
(* identifies satisfaction of relativ p over (D,E) with satisfaction of p    *)
(* over the L domain, for valuations into L. This makes every instance of    *)
(* separation over the class L expressible as a single separation instance   *)
(* in D, which is the engine of the reflection argument to follow.           *)
(* ------------------------------------------------------------------------- *)

let lmem_at = new_definition
  `lmem_at n = ?? (MAX (n+1) 4)
                  (ordinal_form (MAX (n+1) 4) &&
                   ?? (MAX (n+2) 5)
                      (recapp_form (rec_form lstep_form 2)
                                   (MAX (n+1) 4) (MAX (n+2) 5) &&
                       n %% (MAX (n+2) 5)))`;;

let HOLDS_LMEM_AT = prove
 (`!D (E:A->A->bool) v n.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (lmem_at n) <=> elmem D E (v n))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[lmem_at; HOLDS_EX; HOLDS_AND; holds] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((MAX (n+1) 4 |-> a) v)
             (ordinal_form (MAX (n+1) 4)) <=>
           eordinal D E a)`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D ((MAX (n+1) 4 |-> (a:A)) v)`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
    REWRITE_TAC[VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a y:A. a IN D /\ y IN D
      ==> (holds D E ((MAX (n+2) 5 |-> y) ((MAX (n+1) 4 |-> a) v))
             (recapp_form (rec_form lstep_form 2)
                          (MAX (n+1) 4) (MAX (n+2) 5)) <=>
           elstage D E a y)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((MAX (n+2) 5 |-> (y:A)) ((MAX (n+1) 4 |-> (a:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(MAX (n+2) 5 |-> (y:A)) ((MAX (n+1) 4 |-> (a:A)) v)`;
                  `MAX (n+1) 4`; `MAX (n+2) 5`] HOLDS_RECAPP_LSTEP) THEN
    ASM_REWRITE_TAC[ARITH_RULE
     `~(MAX (n+1) 4 = 2) /\ ~(MAX (n+1) 4 = 3) /\
      ~(MAX (n+2) 5 = 2) /\ ~(MAX (n+2) 5 = 3)`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
             ARITH_RULE `~(MAX (n+1) 4 = MAX (n+2) 5)`];
    ALL_TAC] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(n = MAX (n+1) 4) /\ ~(n = MAX (n+2) 5)`] THEN
  REWRITE_TAC[elmem] THEN ASM_MESON_TAC[]);;

let relativ = new_recursive_definition form_RECURSION
  `(relativ False = False) /\
   (!i j. relativ (i %% j) = i %% j) /\
   (!i j. relativ (Eq i j) = Eq i j) /\
   (!p q. relativ (p --> q) = relativ p --> relativ q) /\
   (!n p. relativ (!! n p) = !! n (lmem_at n --> relativ p))`;;

let VALUATION_LCLASS = prove
 (`!D (E:A->A->bool) v.
        valuation (lclass D E) v <=>
        valuation D v /\ !i. elmem D E (v i)`,
  REWRITE_TAC[valuation; IN_LCLASS] THEN MESON_TAC[]);;

let HOLDS_RELATIV = prove
 (`!D (E:A->A->bool). model D E ZF_AX
      ==> !p v. valuation (lclass D E) v
                ==> (holds D E v (relativ p) <=>
                     holds (lclass D E) E v p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[relativ; holds];
    REWRITE_TAC[relativ; holds];
    REWRITE_TAC[relativ; holds];
    REPEAT GEN_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
    REWRITE_TAC[relativ; holds] THEN
    USE_THEN "ihp" (MP_TAC o SPEC `v:num->A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ihq" (MP_TAC o SPEC `v:num->A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`n:num`; `p:form`] THEN
  DISCH_THEN(LABEL_TAC "ih") THEN
  X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (v:num->A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_LCLASS]; ALL_TAC] THEN
  REWRITE_TAC[relativ; holds] THEN
  REWRITE_TAC[IN_LCLASS] THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "lhs") THEN X_GEN_TAC `a:A` THEN
    STRIP_TAC THEN
    USE_THEN "lhs" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `valuation D (((n:num) |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((n:num) |-> (a:A)) v`;
                  `n:num`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ih" (MP_TAC o SPEC `((n:num) |-> (a:A)) v`) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[VALUATION_LCLASS] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[VALUATION_LCLASS];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    DISCH_THEN(LABEL_TAC "rhs") THEN X_GEN_TAC `a:A` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((n:num) |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((n:num) |-> (a:A)) v`;
                  `n:num`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC] THEN DISCH_TAC THEN
    USE_THEN "rhs" (MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "ih" (MP_TAC o SPEC `((n:num) |-> (a:A)) v`) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[VALUATION_LCLASS] THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[VALUATION_LCLASS];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* ------------------------------------------------------------------------- *)
(* Reading a formula's parameters off an internal valuation: fvlist is the   *)
(* free-variable list, valat_form i sv says "variable i has the value of     *)
(* the internal valuation (at variable sv) at the internal numeral of i",    *)
(* and bindfv l sv r binds each variable in l that way around r. The HOLDS   *)
(* characterization trades those bindings for a meta-level valuation         *)
(* agreeing with the shadow of s on l and with the ambient valuation off l.  *)
(* This lets a fixed meta-formula r be evaluated inside an object formula    *)
(* at an argument tuple ranging over an internal function space, which is    *)
(* what the reflection chain needs for its witness-bounding step.            *)
(* ------------------------------------------------------------------------- *)

let fvlist = new_recursive_definition form_RECURSION
  `(fvlist False = []) /\
   (!i j. fvlist (i %% j) = [i; j]) /\
   (!i j. fvlist (Eq i j) = [i; j]) /\
   (!p q. fvlist (p --> q) = APPEND (fvlist p) (fvlist q)) /\
   (!n p. fvlist (!! n p) = FILTER (\i. ~(i = n)) (fvlist p))`;;

let MEM_FVLIST = prove
 (`!p i. MEM i (fvlist p) <=> i IN FV p`,
  MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[fvlist; FV; MEM; MEM_APPEND; MEM_FILTER;
              IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_DELETE] THEN
  MESON_TAC[]);;

let valat_form = new_definition
  `valat_form i sv =
     ?? (MAX i sv + 1) (nat_form i (MAX i sv + 1) &&
                        apply_form sv (MAX i sv + 1) i)`;;

let HOLDS_VALAT_FORM = prove
 (`!D (E:A->A->bool) v i sv.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (valat_form i sv) <=>
             ?m. m IN D /\ enat D E i m /\ eapply D E (v sv) m (v i))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[valat_form; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!m:A. m IN D
      ==> (holds D E (((MAX i sv + 1) |-> m) v)
             (nat_form i (MAX i sv + 1)) <=>
           enat D E i m) /\
          (holds D E (((MAX i sv + 1) |-> m) v)
             (apply_form sv (MAX i sv + 1) i) <=>
           eapply D E (v sv) m (v i))`
  ASSUME_TAC THENL
   [X_GEN_TAC `m:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `valuation D (((MAX i sv + 1) |-> (m:A)) v)`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_NAT_FORM; HOLDS_APPLY_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
             ARITH_RULE `~(i = MAX i sv + 1) /\ ~(sv = MAX i sv + 1)`];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let bindfv = new_recursive_definition list_RECURSION
  `(!sv r. bindfv [] sv r = r) /\
   (!i l sv r. bindfv (CONS i l) sv r =
        ?? i (valat_form i sv && bindfv l sv r))`;;

let HOLDS_BINDFV = prove
 (`!D (E:A->A->bool) om x s vs sv r.
        model D E ZF_AX /\ eomega D E om /\
        evaluation D E om x s /\ shadowed D E s vs
        ==> !l v. valuation D v /\ v sv = s /\ ~(MEM sv l)
                  ==> (holds D E v (bindfv l sv r) <=>
                       ?v'. valuation D v' /\
                            (!i. MEM i l ==> v' i = vs i) /\
                            (!i. ~(MEM i l) ==> v' i = v i) /\
                            holds D E v' r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!j. (vs:num->A) j IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[SHADOWED_VALUATION; valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i a:A. a IN D
      ==> ((?m. m IN D /\ enat D E i m /\ eapply D (E:A->A->bool) s m a)
           <=> a = vs i)`
  (LABEL_TAC "key") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN
       `?ni:A. ni IN D /\ enat D (E:A->A->bool) i ni /\
               eapply D E s ni (vs i)`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[shadowed]; ALL_TAC] THEN
      SUBGOAL_THEN `m:A = ni` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[ENAT_UNIQUE]; ALL_TAC] THEN
      ASM_MESON_TAC[EAPPLY_UNIQUE; evaluation];
      DISCH_THEN SUBST1_TAC THEN ASM_MESON_TAC[shadowed]];
    ALL_TAC] THEN
  LIST_INDUCT_TAC THENL
   [X_GEN_TAC `v:num->A` THEN STRIP_TAC THEN
    REWRITE_TAC[bindfv; MEM] THEN EQ_TAC THENL
     [DISCH_TAC THEN EXISTS_TAC `v:num->A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `v':num->A = v` SUBST_ALL_TAC THENL
       [REWRITE_TAC[FUN_EQ_THM] THEN ASM_REWRITE_TAC[];
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  X_GEN_TAC `v:num->A` THEN REWRITE_TAC[MEM; DE_MORGAN_THM] THEN
  STRIP_TAC THEN REWRITE_TAC[bindfv; HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((h |-> a) v) (valat_form h sv) <=> a = vs h)`
  ASSUME_TAC THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((h:num) |-> (a:A)) v`;
                  `h:num`; `sv:num`] HOLDS_VALAT_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC] THEN
    SUBGOAL_THEN `((h:num) |-> (a:A)) v sv = s` SUBST1_TAC THENL
     [REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
      ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "key" (MP_TAC o SPECL [`h:num`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vs:num->A) h IN D` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(?a. a IN D /\ holds D E ((h |-> a) v) (valat_form h sv) /\
         holds D E ((h |-> a) v) (bindfv t sv r)) <=>
    holds D (E:A->A->bool) (((h:num) |-> vs h) v) (bindfv t sv r)`
  SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `((h:num) |-> (vs h:A)) v` o
    check (fun th -> is_forall(concl th) &&
                     can (find_term (fun t -> is_const t &&
                       fst(dest_const t) = "bindfv")) (concl th))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `j:num` THEN STRIP_TAC THENL
       [ASM_CASES_TAC `MEM (j:num) t` THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(v':num->A) j = ((h |-> vs h) v) j`
        SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[VALMOD_BASIC];
        ASM_MESON_TAC[]];
      X_GEN_TAC `j:num` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(v':num->A) j = ((h |-> vs h) v) j`
      SUBST1_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[VALMOD_OTHER]];
    DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `j:num` THEN DISCH_TAC THEN
    ASM_CASES_TAC `j:num = h` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `(v':num->A) h = vs h` SUBST1_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD_BASIC];
      SUBGOAL_THEN `(v':num->A) j = v j` SUBST1_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[VALMOD_OTHER]]]);;

(* ------------------------------------------------------------------------- *)
(* Structural prerequisites for the reflection chain: free-variable bounds   *)
(* for the new formula constructors, a bound vbound p on all variables of a  *)
(* formula (free and bound), and the subformula relation. Then the internal  *)
(* range-membership relation einran with its object formula, and existence   *)
(* of the union of the L-stages indexed by the ordinal range values of any   *)
(* set (EWRAN_EXISTS: two replacements and a union).                         *)
(* ------------------------------------------------------------------------- *)

let FV_VALAT_FORM = prove
 (`!i sv. FV(valat_form i sv) SUBSET {i, sv}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[valat_form; FV; FV_CLAUSES; FV_NAT_FORM; FV_APPLY_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FV_LMEM_AT = prove
 (`!n. FV(lmem_at n) SUBSET {n}`,
  GEN_TAC THEN REWRITE_TAC[lmem_at; FV; FV_CLAUSES; FV_ORDINAL_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `m:num` THEN
  MP_TAC(SPECL [`MAX (n+1) 4`; `MAX (n+2) 5`; `m:num`]
        FVLT_RECAPP_LSTEP) THEN
  MESON_TAC[]);;

let FV_BINDFV = prove
 (`!l sv r. FV(bindfv l sv r) SUBSET
            sv INSERT {i | i IN FV r /\ ~(MEM i l)}`,
  LIST_INDUCT_TAC THEN REWRITE_TAC[bindfv; MEM] THENL
   [REWRITE_TAC[SUBSET; IN_INSERT; IN_ELIM_THM] THEN MESON_TAC[];
    REPEAT GEN_TAC THEN REWRITE_TAC[FV; FV_CLAUSES] THEN
    MP_TAC(SPECL [`h:num`; `sv:num`] FV_VALAT_FORM) THEN
    FIRST_X_ASSUM(MP_TAC o SPECL [`sv:num`; `r:form`]) THEN
    REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT;
                IN_ELIM_THM; NOT_IN_EMPTY] THEN
    MESON_TAC[]]);;

let FV_RELATIV = prove
 (`!p. FV(relativ p) SUBSET FV p`,
  MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[relativ; FV; SUBSET_REFL] THEN CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    REPEAT(POP_ASSUM MP_TAC) THEN SET_TAC[];
    MAP_EVERY X_GEN_TAC [`n:num`; `p:form`] THEN DISCH_TAC THEN
    MP_TAC(SPEC `n:num` FV_LMEM_AT) THEN
    REPEAT(POP_ASSUM MP_TAC) THEN
    REWRITE_TAC[FV] THEN SET_TAC[]]);;

let vbound = new_recursive_definition form_RECURSION
  `(vbound False = 0) /\
   (!i j. vbound (i %% j) = MAX i j + 1) /\
   (!i j. vbound (Eq i j) = MAX i j + 1) /\
   (!p q. vbound (p --> q) = MAX (vbound p) (vbound q)) /\
   (!n p. vbound (!! n p) = MAX (n + 1) (vbound p))`;;

let VBOUND_FV = prove
 (`!p i. i IN FV p ==> i < vbound p`,
  MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[vbound; FV; IN_UNION; IN_INSERT; IN_DELETE;
              NOT_IN_EMPTY] THEN
  REPEAT CONJ_TAC THEN REPEAT GEN_TAC THEN TRY DISCH_TAC THEN
  TRY(X_GEN_TAC `i:num`) THEN TRY STRIP_TAC THEN
  TRY ASM_ARITH_TAC THEN
  ASM_MESON_TAC[ARITH_RULE `i < a ==> i < MAX a b`;
                ARITH_RULE `i < b ==> i < MAX a b`]);;

let subform_RULES, subform_INDUCT, subform_CASES =
  new_inductive_definition
  `(!p. subform p p) /\
   (!p q r. subform r p ==> subform r (p --> q)) /\
   (!p q r. subform r q ==> subform r (p --> q)) /\
   (!n p r. subform r p ==> subform r (!! n p))`;;

let SUBFORM_REFL = prove
 (`!p. subform p p`,
  REWRITE_TAC[subform_RULES]);;

let SUBFORM_TRANS = prove
 (`!q p. subform q p ==> !r. subform r q ==> subform r p`,
  MATCH_MP_TAC subform_INDUCT THEN MESON_TAC[subform_RULES]);;

let einran = new_definition
  `einran D (E:A->A->bool) b g <=>
        ?pr oo. pr IN D /\ oo IN D /\ eopair D E oo b pr /\ E pr g`;;

let inran_form = new_definition
  `inran_form b g =
     ?? (MAX b g + 1) (?? (MAX b g + 2)
        (opair_form (MAX b g + 2) b (MAX b g + 1) &&
         (MAX b g + 1) %% g))`;;

let HOLDS_INRAN_FORM = prove
 (`!D (E:A->A->bool) v b g.
        valuation D v
        ==> (holds D E v (inran_form b g) <=>
             einran D E (v b) (v g))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[inran_form; HOLDS_EX; HOLDS_AND; holds; einran] THEN
  SUBGOAL_THEN
   `!pr oo:A. pr IN D /\ oo IN D
      ==> (holds D E (((MAX b g + 2) |-> oo) (((MAX b g + 1) |-> pr) v))
             (opair_form (MAX b g + 2) b (MAX b g + 1)) <=>
           eopair D E oo (v b) pr)`
  ASSUME_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D (((MAX b g + 2) |-> (oo:A)) (((MAX b g + 1) |-> (pr:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
             ARITH_RULE `~(b = MAX b g + 2) /\ ~(b = MAX b g + 1) /\
                         ~(MAX b g + 1 = MAX b g + 2)`];
    ALL_TAC] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(g = MAX b g + 1) /\ ~(g = MAX b g + 2)`] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(MAX b g + 1 = MAX b g + 2)`] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `pr:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `oo:A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`pr:A`; `oo:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `oo:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let EWRAN_EXISTS = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D
        ==> ?w. w IN D /\
                !t. t IN D
                    ==> (E t w <=>
                         ?b y. b IN D /\ y IN D /\ eordinal D E b /\
                               einran D E b g /\ elstage D E b y /\
                               E t y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!pr w':A. pr IN D /\ w' IN D
      ==> (holds D E ((1 |-> w') ((0 |-> pr) v0))
             (ordinal_form 1 && (?? 4 (opair_form 4 1 0))) <=>
           eordinal D E w' /\
           ?oo. oo IN D /\ eopair D E oo w' pr)`
  (LABEL_TAC "hro") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (w':A)) ((0 |-> (pr:A)) v0))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_EX; HOLDS_ORDINAL_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT
      `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
    CONJ_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!oo:A. oo IN D
        ==> (holds D E
              ((4 |-> oo) ((1 |-> w') ((0 |-> (pr:A)) v0)))
              (opair_form 4 1 0) <=>
             eopair D E oo w' pr)`
    ASSUME_TAC THENL
     [X_GEN_TAC `oo:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((4 |-> (oo:A)) ((1 |-> (w':A)) ((0 |-> (pr:A)) v0)))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`ordinal_form 1 && (?? 4 (opair_form 4 1 0))`; `0`; `1`;
     `v0:num->A`; `g:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC
      `?bb oo:A. bb IN D /\ oo IN D /\ eordinal D (E:A->A->bool) bb /\
                 eopair D E oo bb u` THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `bb:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`u:A`; `w':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_INJ];
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`u:A`; `w':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      STRIP_TAC THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!b:A. b IN D
      ==> ((E:A->A->bool) b bs <=>
           eordinal D E b /\ einran D E b g)`
  (LABEL_TAC "bch2") THENL
   [X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `b:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[einran] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`pr:A`; `b:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      STRIP_TAC THEN ASM_MESON_TAC[];
      STRIP_TAC THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`pr:A`; `b:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b y:A. b IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> b) v0))
             (recapp_form (rec_form lstep_form 2) 0 1) <=>
           elstage D E b y)`
  (LABEL_TAC "hst") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                  `(1 |-> (y:A)) ((0 |-> (b:A)) v0)`; `0`; `1`]
          HOLDS_RECAPP_LSTEP) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`recapp_form (rec_form lstep_form 2) 0 1`; `0`; `1`;
     `v0:num->A`; `bs:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `?y:A. y IN D /\ elstage D (E:A->A->bool) b y`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `y':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hst" (fun th -> MP_TAC(SPECL [`b:A`; `y':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_TAC THEN ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN `?w:A. eunion D (E:A->A->bool) sb w`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  EXISTS_TAC `w:A` THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "sch" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) u /\ einran D E u g`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "bch2" (MP_TAC o SPEC `u:A`) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `elstage D (E:A->A->bool) u y` ASSUME_TAC THENL
     [USE_THEN "hst" (fun th -> MP_TAC(SPECL [`u:A`; `y:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `y:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sch" (MP_TAC o SPEC `y:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "bch2" (MP_TAC o SPEC `b:A`) THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      USE_THEN "hst" (fun th -> MP_TAC(SPECL [`b:A`; `y:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* The counterexample-bounding condition. HOLDS_BINDWITNESS unfolds one      *)
(* bound witness: satisfaction of (n |-> b) around bindfv of a formula r     *)
(* whose free variables lie in {n} UNION l is equivalent to existence of a   *)
(* meta-valuation sending n to b and reading l off the internal valuation.   *)
(* semceb is the semantic bounding condition: for every internal valuation   *)
(* s into w, a constructible counterexample to any universal subformula      *)
(* (with parameters read off s) yields one inside the stage L(d). ceb_form   *)
(* is its object-formula counterpart, built with the global freshness base   *)
(* vb (all variables of the formula are below vb, the tuple slot is vb+5,    *)
(* auxiliaries vb+6..vb+8, the domain set at wv and the target at dv).       *)
(* ------------------------------------------------------------------------- *)

let HOLDS_BINDWITNESS = prove
 (`!D (E:A->A->bool) om x s vsh sv n l r b Q.
        model D E ZF_AX /\ eomega D E om /\
        evaluation D E om x s /\ shadowed D E s vsh /\
        valuation D Q /\ Q sv = s /\
        ~(MEM sv l) /\ ~(n = sv) /\ ~(MEM n l) /\ b IN D /\
        (!i. i IN FV r ==> i = n \/ MEM i l)
        ==> (holds D E ((n |-> b) Q) (bindfv l sv r) <=>
             ?v'. valuation D v' /\ v' n = b /\
                  (!i. MEM i l
                       ==> ?m. m IN D /\ enat D E i m /\
                               eapply D E s m (v' i)) /\
                  holds D E v' r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!j. (vsh:num->A) j IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[SHADOWED_VALUATION; valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                `vsh:num->A`; `sv:num`; `r:form`] HOLDS_BINDFV) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`l:num list`; `((n:num) |-> (b:A)) Q`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBGOAL_THEN `(v':num->A) n = ((n |-> b) Q) n` SUBST1_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[VALMOD_BASIC];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(v':num->A) i = vsh i` SUBST1_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[shadowed]];
    DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `\i. if MEM i l then (vsh:num->A) i
                    else ((n |-> (b:A)) Q) i` THEN
    REPEAT CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
      REWRITE_TAC[] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
      ASM_MESON_TAC[valuation];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN
       `holds D E (\i. if MEM i l then (vsh:num->A) i
                       else ((n |-> (b:A)) Q) i) r <=>
        holds D E v' r`
      SUBST1_TAC THENL
       [MATCH_MP_TAC HOLDS_VALUATION THEN
        X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[] THEN
        SUBGOAL_THEN `i:num = n \/ MEM i l` MP_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        STRIP_TAC THENL
         [FIRST_X_ASSUM SUBST_ALL_TAC THEN
          ASM_REWRITE_TAC[VALMOD_BASIC];
          ASM_REWRITE_TAC[] THEN
          SUBGOAL_THEN
           `?m:A. m IN D /\ enat D (E:A->A->bool) i m /\
                  eapply D E s m (v' i)`
          STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
          SUBGOAL_THEN
           `?ni:A. ni IN D /\ enat D (E:A->A->bool) i ni /\
                   eapply D E s ni (vsh i)`
          STRIP_ASSUME_TAC THENL
           [ASM_MESON_TAC[shadowed]; ALL_TAC] THEN
          SUBGOAL_THEN `m:A = ni` SUBST_ALL_TAC THENL
           [ASM_MESON_TAC[ENAT_UNIQUE]; ALL_TAC] THEN
          ASM_MESON_TAC[EAPPLY_UNIQUE; evaluation; valuation]];
        ASM_REWRITE_TAC[]]]]);;

let semceb = new_recursive_definition form_RECURSION
  `(!D (E:A->A->bool) w d. semceb D E w d False <=> T) /\
   (!D (E:A->A->bool) w d i j. semceb D E w d (i %% j) <=> T) /\
   (!D (E:A->A->bool) w d i j. semceb D E w d (Eq i j) <=> T) /\
   (!D (E:A->A->bool) w d p q.
        semceb D E w d (p --> q) <=>
        semceb D E w d p /\ semceb D E w d q) /\
   (!D (E:A->A->bool) w d n q.
        semceb D E w d (!! n q) <=>
        semceb D E w d q /\
        !om s. om IN D /\ s IN D /\ eomega D E om /\
               evaluation D E om w s
               ==> ((?b v'. b IN D /\ elmem D E b /\
                            valuation D v' /\ v' n = b /\
                            (!i. MEM i (fvlist (!! n q))
                                 ==> ?m. m IN D /\ enat D E i m /\
                                         eapply D E s m (v' i)) /\
                            holds D E v' (relativ (Not q)))
                    ==> ?y. y IN D /\ elstage D E d y /\
                            ?b v'. b IN D /\ E b y /\
                                   valuation D v' /\ v' n = b /\
                                   (!i. MEM i (fvlist (!! n q))
                                        ==> ?m. m IN D /\
                                                enat D E i m /\
                                                eapply D E s m (v' i)) /\
                                   holds D E v' (relativ (Not q))))`;;

let ceb_form = new_recursive_definition form_RECURSION
  `(!vb wv dv. ceb_form vb wv dv False = True) /\
   (!vb wv dv i j. ceb_form vb wv dv (i %% j) = True) /\
   (!vb wv dv i j. ceb_form vb wv dv (Eq i j) = True) /\
   (!vb wv dv p q. ceb_form vb wv dv (p --> q) =
        ceb_form vb wv dv p && ceb_form vb wv dv q) /\
   (!vb wv dv n q. ceb_form vb wv dv (!! n q) =
        ceb_form vb wv dv q &&
        ?? (vb + 6) (omega_form (vb + 6) &&
        ?? (vb + 7) (funs_form (vb + 6) wv (vb + 7) &&
        !!- (vb + 5) (vb + 7)
           ((?? n (lmem_at n && bindfv (fvlist (!! n q)) (vb + 5)
                                       (relativ (Not q))))
            --> (?? (vb + 8)
                   (recapp_form (rec_form lstep_form 2) dv (vb + 8) &&
                    ??- n (vb + 8)
                       (bindfv (fvlist (!! n q)) (vb + 5)
                               (relativ (Not q)))))))))`;;

(* ------------------------------------------------------------------------- *)
(* The characterization theorem for the counterexample-bounding formula:     *)
(* HOLDS_CEB_QCASE handles one universal-quantifier case (unfolding the      *)
(* omega/function-space/tuple quantifier prefix pointwise, HOLDS_BINDWITNESS *)
(* on both the class-side witness and the stage-side witness, with fully     *)
(* deterministic witness-passing assemblies -- MESON diverges on the nested  *)
(* quantifier structure), and HOLDS_CEB assembles it over the formula by     *)
(* structural induction: satisfaction of ceb_form vb wv dv p is exactly      *)
(* semceb over the sets at wv and dv, provided all variables of p are below  *)
(* vb and wv,dv are below vb+5 and avoid the rec_form slots 2,3.             *)
(* ------------------------------------------------------------------------- *)

let HOLDS_CEB_QCASE = prove
 (`!D (E:A->A->bool) v n q vb wv dv.
        model D E ZF_AX /\ valuation D v /\
        vbound (!! n q) <= vb /\ wv < vb + 5 /\ dv < vb + 5 /\
        ~(dv = 2) /\ ~(dv = 3)
        ==> (holds D E v
              (?? (vb + 6) (omega_form (vb + 6) &&
               ?? (vb + 7) (funs_form (vb + 6) wv (vb + 7) &&
               !!- (vb + 5) (vb + 7)
                  ((?? n (lmem_at n && bindfv (fvlist (!! n q)) (vb + 5)
                                              (relativ (Not q))))
                   --> (?? (vb + 8)
                          (recapp_form (rec_form lstep_form 2) dv (vb + 8) &&
                           ??- n (vb + 8)
                              (bindfv (fvlist (!! n q)) (vb + 5)
                                      (relativ (Not q))))))))) <=>
             !om s. om IN D /\ s IN D /\ eomega D E om /\
                    evaluation D E om (v wv) s
                    ==> ((?b v'. b IN D /\ elmem D E b /\
                                 valuation D v' /\ v' n = b /\
                                 (!i. MEM i (fvlist (!! n q))
                                      ==> ?m. m IN D /\ enat D E i m /\
                                              eapply D E s m (v' i)) /\
                                 holds D E v' (relativ (Not q)))
                         ==> ?y. y IN D /\ elstage D E (v dv) y /\
                                 ?b v'. b IN D /\ E b y /\
                                        valuation D v' /\ v' n = b /\
                                        (!i. MEM i (fvlist (!! n q))
                                             ==> ?m. m IN D /\
                                                     enat D E i m /\
                                                     eapply D E s m (v' i)) /\
                                        holds D E v' (relativ (Not q))))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `!i. MEM i (fvlist (!! n q)) ==> i < vb`
  (LABEL_TAC "la") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    MATCH_MP_TAC LTE_TRANS THEN EXISTS_TAC `vbound (!! n q)` THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VBOUND_FV THEN
    ASM_MESON_TAC[MEM_FVLIST];
    ALL_TAC] THEN
  SUBGOAL_THEN `n:num < vb` (LABEL_TAC "ln") THENL
   [UNDISCH_TAC `vbound (!! n q) <= vb` THEN
    REWRITE_TAC[vbound] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `~(MEM n (fvlist (!! n q)))` ASSUME_TAC THENL
   [REWRITE_TAC[fvlist; MEM_FILTER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i IN FV (relativ (Not q)) ==> i = n \/ MEM i (fvlist (!! n q))`
  (LABEL_TAC "le") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN `i IN FV (Not q)` ASSUME_TAC THENL
     [ASM_MESON_TAC[FV_RELATIV; SUBSET]; ALL_TAC] THEN
