let HOLDS_CEB = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p v vb wv dv.
           valuation D v /\ vbound p <= vb /\
           wv < vb + 5 /\ dv < vb + 5 /\ ~(dv = 2) /\ ~(dv = 3)
           ==> (holds D E v (ceb_form vb wv dv p) <=>
                semceb D E (v wv) (v dv) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[ceb_form; semceb; HOLDS_TRUE];
    REWRITE_TAC[ceb_form; semceb; HOLDS_TRUE];
    REWRITE_TAC[ceb_form; semceb; HOLDS_TRUE];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[ceb_form; semceb; HOLDS_AND] THEN
    USE_THEN "ihp" (MP_TAC o SPECL
      [`v:num->A`; `vb:num`; `wv:num`; `dv:num`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `vbound (p --> q) <= vb` THEN
      REWRITE_TAC[vbound] THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ihq" (MP_TAC o SPECL
      [`v:num->A`; `vb:num`; `wv:num`; `dv:num`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `vbound (p --> q) <= vb` THEN
      REWRITE_TAC[vbound] THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    MAP_EVERY X_GEN_TAC [`n:num`; `q:form`] THEN
    DISCH_THEN(LABEL_TAC "ih") THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[ceb_form; semceb; HOLDS_AND] THEN
    USE_THEN "ih" (MP_TAC o SPECL
      [`v:num->A`; `vb:num`; `wv:num`; `dv:num`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `vbound (!! n q) <= vb` THEN
      REWRITE_TAC[vbound] THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `n:num`;
                  `q:form`; `vb:num`; `wv:num`; `dv:num`]
          HOLDS_CEB_QCASE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

(* ------------------------------------------------------------------------- *)
(* A general least-ordinal principle for object-definable properties (by     *)
(* foundation on a separation carve below any witness), and monotonicity of  *)
(* the semantic bounding condition in the target ordinal (witnesses persist  *)
(* into larger stages).                                                      *)
(* ------------------------------------------------------------------------- *)

let EORDINAL_LEAST = prove
 (`!D (E:A->A->bool) pp v d0.
        model D E ZF_AX /\ valuation D v /\
        d0 IN D /\ eordinal D E d0 /\ holds D E ((0 |-> d0) v) pp
        ==> ?d. d IN D /\ eordinal D E d /\
                holds D E ((0 |-> d) v) pp /\
                !c. c IN D /\ E c d ==> ~(holds D E ((0 |-> c) v) pp)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d0:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sd:A`) THEN
  SUBGOAL_THEN `(sd:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sd` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d0 sd` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`pp:form`; `0`; `v:num->A`; `sd:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ss:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ss:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `d0:A` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sch" (MP_TAC o SPEC `d0:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@d. h1 h2 min" THEN
  SUBGOAL_THEN
   `(E:A->A->bool) d sd /\ holds D E ((0 |-> d) v) pp`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "sch" (MP_TAC o SPEC `d:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c sd` ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  USE_THEN "min" (MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_TAC THEN
  USE_THEN "sch" (MP_TAC o SPEC `c:A`) THEN ANTS_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[]);;

let SEMCEB_MONO = prove
 (`!D (E:A->A->bool). model D E ZF_AX
    ==> !p w d d'.
          eordinal D E d /\ eordinal D E d' /\
          (E d d' \/ d = d') /\ semceb D E w d p
          ==> semceb D E w d' p`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC form_INDUCT THEN
  REWRITE_TAC[semceb] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    REPEAT GEN_TAC THEN
    DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
    CONJ_TAC THENL
     [USE_THEN "ihp" (MP_TAC o SPECL [`w:A`; `d:A`; `d':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "ihq" (MP_TAC o SPECL [`w:A`; `d:A`; `d':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    MAP_EVERY X_GEN_TAC [`n:num`; `q:form`] THEN
    DISCH_THEN(LABEL_TAC "ih") THEN
    REPEAT GEN_TAC THEN
    INTRO_TAC "h1 h2 h3 sq sf" THEN
    CONJ_TAC THENL
     [USE_THEN "ih" (MP_TAC o SPECL [`w:A`; `d:A`; `d':A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "sq" ACCEPT_TAC;
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MAP_EVERY X_GEN_TAC [`om:A`; `s:A`] THEN STRIP_TAC THEN
    DISCH_TAC THEN
    USE_THEN "sf" (MP_TAC o SPECL [`om:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `?y':A. y' IN D /\ elstage D (E:A->A->bool) d' y'`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b y'` ASSUME_TAC THENL
     [FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
        is_disj(concl th))) THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d':A`; `d:A`;
                      `y':A`; `y:A`; `b:A`] ELSTAGE_MONO) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
          DISCH_THEN ACCEPT_TAC];
        ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]];
      ALL_TAC] THEN
    EXISTS_TAC `y':A` THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `v':num->A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Transitivity of ordinal <= and the generic stage-witness characterization *)
(* (the target side of the ceb quantifier case at arbitrary valuation and    *)
(* variable positions) -- the building block for the least-counterexample-   *)
(* rank replacement in the existence proof for the bounding ordinal.         *)
(* ------------------------------------------------------------------------- *)

let EORDINAL_LE_TRANS = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
        eordinal D E c /\
        (E a b \/ a = b) /\ (E b c \/ b = c)
        ==> E a c \/ a = c`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  SUBGOAL_THEN
   `!x y:A. x IN D /\ y IN D /\ (E:A->A->bool) x y /\ E y c ==> E x c`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
  ASM_MESON_TAC[EORDINAL_IN]);;

let HOLDS_CEWITNESS = prove
 (`!D (E:A->A->bool) om x s vsh v n q vb sv dv.
        model D E ZF_AX /\ eomega D E om /\
        evaluation D E om x s /\ shadowed D E s vsh /\
        valuation D v /\ v sv = s /\
        vbound (!! n q) <= vb /\
        ~(dv = 2) /\ ~(dv = 3) /\ ~(dv = vb + 8) /\ ~(sv = vb + 8) /\
        ~(n = vb + 8) /\ ~(n = sv) /\ ~(MEM sv (fvlist (!! n q)))
        ==> (holds D E v
              (?? (vb + 8)
                 (recapp_form (rec_form lstep_form 2) dv (vb + 8) &&
                  ??- n (vb + 8)
                     (bindfv (fvlist (!! n q)) sv (relativ (Not q))))) <=>
             ?y. y IN D /\ elstage D E (v dv) y /\
                 ?b v'. b IN D /\ E b y /\ valuation D v' /\
                        v' n = b /\
                        (!i. MEM i (fvlist (!! n q))
                             ==> ?m. m IN D /\ enat D E i m /\
                                     eapply D E s m (v' i)) /\
                        holds D E v' (relativ (Not q)))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!j. (v:num->A) j IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `~(MEM n (fvlist (!! n q)))` ASSUME_TAC THENL
   [REWRITE_TAC[fvlist; MEM_FILTER]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i IN FV (relativ (Not q)) ==> i = n \/ MEM i (fvlist (!! n q))`
  (LABEL_TAC "le") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    SUBGOAL_THEN `i IN FV (Not q)` ASSUME_TAC THENL
     [ASM_MESON_TAC[FV_RELATIV; SUBSET]; ALL_TAC] THEN
    ASM_CASES_TAC `i:num = n` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[MEM_FVLIST; FV; IN_DELETE] THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o check (fun th ->
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "Not")) (concl th))) THEN
    REWRITE_TAC[Not_DEF; FV; FV_CLAUSES; UNION_EMPTY] THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> valuation D (((vb + 8) |-> y) (v:num->A))`
  (LABEL_TAC "vp") THENL
   [REPEAT STRIP_TAC THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E (((vb + 8) |-> y) v)
             (recapp_form (rec_form lstep_form 2) dv (vb + 8)) <=>
           elstage D E (v dv) y)`
  (LABEL_TAC "pr") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((vb + 8) |-> (y:A)) (v:num->A)`;
      `dv:num`; `vb + 8`] HOLDS_RECAPP_LSTEP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `~(vb + 8 = 2) /\ ~(vb + 8 = 3)`] THEN
      ASM_SIMP_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y b:A. y IN D /\ b IN D
      ==> (holds D E ((n |-> b) (((vb + 8) |-> y) v))
             (bindfv (fvlist (!! n q)) sv (relativ (Not q))) <=>
           ?v'. valuation D v' /\ v' n = b /\
                (!i. MEM i (fvlist (!! n q))
                     ==> ?m. m IN D /\ enat D E i m /\
                             eapply D E s m (v' i)) /\
                holds D E v' (relativ (Not q)))`
  (LABEL_TAC "pb") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
      `vsh:num->A`; `sv:num`; `n:num`; `fvlist (!! n q)`;
      `relativ (Not q)`; `b:A`;
      `((vb + 8) |-> (y:A)) (v:num->A)`] HOLDS_BINDWITNESS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_SIMP_TAC[];
        ASM_SIMP_TAC[VALMOD_OTHER]];
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E (((vb + 8) |-> y) v)
             (??- n (vb + 8)
                (bindfv (fvlist (!! n q)) sv (relativ (Not q)))) <=>
           ?b. b IN D /\ E b y /\
               ?v'. valuation D v' /\ v' n = b /\
                    (!i. MEM i (fvlist (!! n q))
                         ==> ?m. m IN D /\ enat D E i m /\
                                 eapply D E s m (v' i)) /\
                    holds D E v' (relativ (Not q)))`
  (LABEL_TAC "pe") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((vb + 8) |-> (y:A)) (v:num->A)`;
      `n:num`; `vb + 8`;
      `bindfv (fvlist (!! n q)) sv (relativ (Not q))`]
      HOLDS_EXISTSMEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC] THEN EQ_TAC THENL
     [INTRO_TAC "@b. h3 h4 +" THEN
      USE_THEN "pb" (fun pb -> MP_TAC(SPECL [`y:A`; `b:A`] pb)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `v':num->A`
          STRIP_ASSUME_TAC)))) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "pb" (fun pb -> MP_TAC(SPECL [`y:A`; `b:A`] pb)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@y. h5 h1 h2" THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "pr" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun i1 -> USE_THEN "h1" (fun h1 ->
        ACCEPT_TAC(REWRITE_RULE[i1] h1)));
      USE_THEN "pe" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun i2 -> USE_THEN "h2" (fun h2 ->
        MP_TAC(REWRITE_RULE[i2] h2))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `v':num->A`
          STRIP_ASSUME_TAC)))) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `v':num->A`] THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `b:A`
        (X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC))))) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "pr" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      USE_THEN "pe" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `v':num->A` THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Compact abbreviations for the counterexample conditions: cewit (a         *)
(* counterexample witness inside the stage L(d), parameters read off the     *)
(* internal valuation s) and cewitl (a constructible counterexample),        *)
(* with semceb's quantifier case restated through them; HOLDS_CEWIT is the   *)
(* stage-witness characterization in this notation, and RANKCE_HOLDS         *)
(* characterizes the least-counterexample-rank formula (ordinal + witness    *)
(* at the output slot vb+10 + minimality below it, input tuple at vb+9)      *)
(* used as the functional relation of the bounding replacement.              *)
(* ------------------------------------------------------------------------- *)

let cewit = new_definition
  `cewit D (E:A->A->bool) n q s d <=>
        ?y. y IN D /\ elstage D E d y /\
            ?b v'. b IN D /\ E b y /\ valuation D v' /\ v' n = b /\
                   (!i. MEM i (fvlist (!! n q))
                        ==> ?m. m IN D /\ enat D E i m /\
                                eapply D E s m (v' i)) /\
                   holds D E v' (relativ (Not q))`;;

let cewitl = new_definition
  `cewitl D (E:A->A->bool) n q s <=>
        ?b v'. b IN D /\ elmem D E b /\ valuation D v' /\ v' n = b /\
               (!i. MEM i (fvlist (!! n q))
                    ==> ?m. m IN D /\ enat D E i m /\
                            eapply D E s m (v' i)) /\
               holds D E v' (relativ (Not q))`;;

let SEMCEB_ALT = prove
 (`!D (E:A->A->bool) w d n q.
        semceb D E w d (!! n q) <=>
        semceb D E w d q /\
        !om s. om IN D /\ s IN D /\ eomega D E om /\
               evaluation D E om w s
               ==> cewitl D E n q s
               ==> cewit D E n q s d`,
  REWRITE_TAC[semceb; cewit; cewitl]);;

let HOLDS_CEWIT = prove
 (`!D (E:A->A->bool) om x s vsh v n q vb sv dv.
        model D E ZF_AX /\ eomega D E om /\
        evaluation D E om x s /\ shadowed D E s vsh /\
        valuation D v /\ v sv = s /\
        vbound (!! n q) <= vb /\
        ~(dv = 2) /\ ~(dv = 3) /\ ~(dv = vb + 8) /\ ~(sv = vb + 8) /\
        ~(n = vb + 8) /\ ~(n = sv) /\ ~(MEM sv (fvlist (!! n q)))
        ==> (holds D E v
              (?? (vb + 8)
                 (recapp_form (rec_form lstep_form 2) dv (vb + 8) &&
                  ??- n (vb + 8)
                     (bindfv (fvlist (!! n q)) sv (relativ (Not q))))) <=>
             cewit D E n q s (v dv))`,
  REWRITE_TAC[cewit] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `s:A`;
                `vsh:num->A`; `v:num->A`; `n:num`; `q:form`; `vb:num`;
                `sv:num`; `dv:num`] HOLDS_CEWITNESS) THEN
  ASM_REWRITE_TAC[]);;

let RANKCE_HOLDS = prove
 (`!D (E:A->A->bool) om w v0 n q vb s dce.
        model D E ZF_AX /\ eomega D E om /\ valuation D v0 /\
        w IN D /\ s IN D /\ dce IN D /\
        evaluation D E om w s /\ vbound (!! n q) <= vb
        ==> (holds D E
              (((vb + 10) |-> dce) (((vb + 9) |-> s) v0))
              (ordinal_form (vb + 10) &&
               (?? (vb + 8)
                  (recapp_form (rec_form lstep_form 2) (vb + 10) (vb + 8) &&
                   ??- n (vb + 8)
                      (bindfv (fvlist (!! n q)) (vb + 9)
                              (relativ (Not q))))) &&
               (!!- (vb + 11) (vb + 10)
                  (Not (?? (vb + 8)
                     (recapp_form (rec_form lstep_form 2) (vb + 11) (vb + 8) &&
                      ??- n (vb + 8)
                         (bindfv (fvlist (!! n q)) (vb + 9)
                                 (relativ (Not q)))))))) <=>
             eordinal D E dce /\ cewit D E n q s dce /\
             !c. c IN D /\ E c dce ==> ~(cewit D E n q s c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`]
        SHADOWED_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `vsh:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `n:num < vb` ASSUME_TAC THENL
   [UNDISCH_TAC `vbound (!! n q) <= vb` THEN
    REWRITE_TAC[vbound] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `~(n = vb + 8) /\ ~(n = vb + 9) /\ ~(n = vb + 10) /\ ~(n = vb + 11)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(MEM (vb + 9) (fvlist (!! n q)))` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `vb + 9 IN FV (!! n q)` MP_TAC THENL
     [ASM_MESON_TAC[MEM_FVLIST]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o MATCH_MP VBOUND_FV) THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D (((vb + 10) |-> (dce:A)) (((vb + 9) |-> (s:A)) v0))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') /\ (c <=> c')
      ==> ((a /\ b /\ c) <=> (a' /\ b' /\ c'))`) THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((vb + 10) |-> (dce:A)) (((vb + 9) |-> (s:A)) v0)`; `vb + 10`]
      HOLDS_ORDINAL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`;
      `vsh:num->A`;
      `((vb + 10) |-> (dce:A)) (((vb + 9) |-> (s:A)) v0)`;
      `n:num`; `q:form`; `vb:num`; `vb + 9`; `vb + 10`] HOLDS_CEWIT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE
       `~(vb + 10 = 2) /\ ~(vb + 10 = 3) /\ ~(vb + 10 = vb + 8) /\
        ~(vb + 9 = vb + 8)`] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(vb + 9 = vb + 10)`];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((vb + 10) |-> (dce:A)) (((vb + 9) |-> (s:A)) v0)`;
      `vb + 11`; `vb + 10`;
      `Not (?? (vb + 8)
              (recapp_form (rec_form lstep_form 2) (vb + 11) (vb + 8) &&
               ??- n (vb + 8)
                  (bindfv (fvlist (!! n q)) (vb + 9)
                          (relativ (Not q)))))`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[ARITH_RULE `~(vb + 11 = vb + 10)`]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC; HOLDS_NOT] THEN
    SUBGOAL_THEN
     `!c:A. c IN D
        ==> (holds D E (((vb + 11) |-> c) (((vb + 10) |-> (dce:A))
               (((vb + 9) |-> (s:A)) v0)))
               (?? (vb + 8)
                  (recapp_form (rec_form lstep_form 2) (vb + 11) (vb + 8) &&
                   ??- n (vb + 8)
                      (bindfv (fvlist (!! n q)) (vb + 9)
                              (relativ (Not q))))) <=>
             cewit D E n q s c)`
    (LABEL_TAC "pc") THENL
     [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`;
        `vsh:num->A`;
        `((vb + 11) |-> (c:A)) (((vb + 10) |-> (dce:A))
           (((vb + 9) |-> (s:A)) v0))`;
        `n:num`; `q:form`; `vb:num`; `vb + 9`; `vb + 11`] HOLDS_CEWIT) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_RULE
         `~(vb + 11 = 2) /\ ~(vb + 11 = 3) /\ ~(vb + 11 = vb + 8) /\
          ~(vb + 9 = vb + 8)`] THEN CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                   ARITH_RULE `~(vb + 9 = vb + 10) /\
                               ~(vb + 9 = vb + 11)`]];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "hm") THEN X_GEN_TAC `c:A` THEN
      STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "pc" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "hm") THEN X_GEN_TAC `c:A` THEN
      STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "pc" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* The bounding ordinal exists: cewit is monotone in the stage index, a      *)
(* constructible counterexample yields a least stage containing one (via     *)
(* EORDINAL_LEAST on the counterexample formula at slot 0), and by           *)
(* induction on the formula there is an ordinal d with semceb w d p for      *)
(* any set w: atoms take the empty ordinal, implications merge their two     *)
(* bounds by trichotomy and SEMCEB_MONO, and the quantifier case runs        *)
(* ZF_REPLACEMENT along the least-counterexample-rank formula over the       *)
(* internal function space Vals(om,w), takes the union of the resulting      *)
(* set of ordinals, and merges with the inductive bound.                     *)
(* ------------------------------------------------------------------------- *)

let CEWIT_MONO = prove
 (`!D (E:A->A->bool) n q s d d'.
        model D E ZF_AX /\ eordinal D E d /\ eordinal D E d' /\
        (E d d' \/ d = d') /\ cewit D E n q s d
        ==> cewit D E n q s d'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  UNDISCH_TAC `cewit D (E:A->A->bool) n q s d` THEN
  REWRITE_TAC[cewit] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `b:A`
      (X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `?y':A. y' IN D /\ elstage D (E:A->A->bool) d' y'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) b y'` ASSUME_TAC THENL
   [FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
      is_disj(concl th))) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d':A`; `d:A`;
                    `y':A`; `y:A`; `b:A`] ELSTAGE_MONO) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
        DISCH_THEN ACCEPT_TAC];
      ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]];
    ALL_TAC] THEN
  EXISTS_TAC `y':A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `v':num->A`] THEN ASM_REWRITE_TAC[]);;

let CEWIT_LEAST = prove
 (`!D (E:A->A->bool) om w v0 n q vb s.
        model D E ZF_AX /\ eomega D E om /\ valuation D v0 /\
        w IN D /\ s IN D /\ evaluation D E om w s /\
        vbound (!! n q) <= vb /\ cewitl D E n q s
        ==> ?dce. dce IN D /\ eordinal D E dce /\
                  cewit D E n q s dce /\
                  !c. c IN D /\ E c dce ==> ~(cewit D E n q s c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`]
        SHADOWED_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `vsh:num->A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `n:num < vb` ASSUME_TAC THENL
   [UNDISCH_TAC `vbound (!! n q) <= vb` THEN
    REWRITE_TAC[vbound] THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `~(MEM (vb + 9) (fvlist (!! n q)))` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `vb + 9 IN FV (!! n q)` MP_TAC THENL
     [ASM_MESON_TAC[MEM_FVLIST]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o MATCH_MP VBOUND_FV) THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((0 |-> a) (((vb + 9) |-> (s:A)) v0))
             (?? (vb + 8)
                (recapp_form (rec_form lstep_form 2) 0 (vb + 8) &&
                 ??- n (vb + 8)
                    (bindfv (fvlist (!! n q)) (vb + 9)
                            (relativ (Not q))))) <=>
           cewit D E n q s a)`
  (LABEL_TAC "pce") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `s:A`;
      `vsh:num->A`;
      `((0:num) |-> (a:A)) (((vb + 9) |-> (s:A)) v0)`;
      `n:num`; `q:form`; `vb:num`; `vb + 9`; `0`] HOLDS_CEWIT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE
       `~(0 = 2) /\ ~(0 = 3) /\ ~(0 = vb + 8) /\ ~(vb + 9 = vb + 8)`] THEN
      SUBGOAL_THEN `~(n = vb + 8) /\ ~(n = vb + 9)`
      STRIP_ASSUME_TAC THENL
       [REPEAT CONJ_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                 ARITH_RULE `~(vb + 9 = 0)`]];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?a0:A. a0 IN D /\ eordinal D (E:A->A->bool) a0 /\
           cewit D E n q s a0`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `cewitl D (E:A->A->bool) n q s` THEN
    REWRITE_TAC[cewitl] THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `v':num->A`
      STRIP_ASSUME_TAC)) THEN
    FIRST_X_ASSUM(MP_TAC o check (fun th ->
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "elmem")) (concl th))) THEN
    REWRITE_TAC[elmem] THEN
    DISCH_THEN(X_CHOOSE_THEN `a0:A` (X_CHOOSE_THEN `ya:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[cewit] THEN EXISTS_TAC `ya:A` THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `v':num->A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `?? (vb + 8)
       (recapp_form (rec_form lstep_form 2) 0 (vb + 8) &&
        ??- n (vb + 8)
           (bindfv (fvlist (!! n q)) (vb + 9) (relativ (Not q))))`;
    `((vb + 9) |-> (s:A)) v0`; `a0:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      USE_THEN "pce" (MP_TAC o SPEC `a0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@dce. h1 h2 hce hmin" THEN
  EXISTS_TAC `dce:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "pce" (MP_TAC o SPEC `dce:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hce" (fun h ->
      ACCEPT_TAC(REWRITE_RULE[th] h)));
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "hmin" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "pce" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN ACCEPT_TAC]);;

let SEMCEB_EXISTS = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p w. w IN D
               ==> ?d. d IN D /\ eordinal D E d /\ semceb D E w d p`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[semceb] THEN REPEAT STRIP_TAC THEN
    ASM_MESON_TAC[EEMPTY_EXISTS; EORDINAL_EEMPTY; eempty];
    REWRITE_TAC[semceb] THEN REPEAT STRIP_TAC THEN
    ASM_MESON_TAC[EEMPTY_EXISTS; EORDINAL_EEMPTY; eempty];
    REWRITE_TAC[semceb] THEN REPEAT STRIP_TAC THEN
    ASM_MESON_TAC[EEMPTY_EXISTS; EORDINAL_EEMPTY; eempty];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "ihp" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d1:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "ihq" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d2:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d1:A`; `d2:A`]
          EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!dd:A. dd IN D /\ eordinal D (E:A->A->bool) dd /\
             (E d1 dd \/ d1 = dd) /\ (E d2 dd \/ d2 = dd)
             ==> ?d. d IN D /\ eordinal D E d /\
                     semceb D E w d (p --> q)`
    (LABEL_TAC "fin") THENL
     [X_GEN_TAC `dd:A` THEN
      DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
      EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[semceb] THEN
      CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] SEMCEB_MONO) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL
          [`p:form`; `w:A`; `d1:A`; `dd:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] SEMCEB_MONO) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPECL
          [`q:form`; `w:A`; `d2:A`; `dd:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
      ALL_TAC] THEN
    STRIP_TAC THENL
     [USE_THEN "fin" (MP_TAC o SPEC `d2:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "fin" (MP_TAC o SPEC `d2:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "fin" (MP_TAC o SPEC `d1:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`n:num`; `q:form`] THEN
  DISCH_THEN(LABEL_TAC "ih") THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "ih" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?vs:A. efuns D (E:A->A->bool) om w vs`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EFUNS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`ordinal_form (vbound (!! n q) + 10) &&
      (?? (vbound (!! n q) + 8)
         (recapp_form (rec_form lstep_form 2)
            (vbound (!! n q) + 10) (vbound (!! n q) + 8) &&
          ??- n (vbound (!! n q) + 8)
             (bindfv (fvlist (!! n q)) (vbound (!! n q) + 9)
                     (relativ (Not q))))) &&
      (!!- (vbound (!! n q) + 11) (vbound (!! n q) + 10)
         (Not (?? (vbound (!! n q) + 8)
            (recapp_form (rec_form lstep_form 2)
               (vbound (!! n q) + 11) (vbound (!! n q) + 8) &&
             ??- n (vbound (!! n q) + 8)
                (bindfv (fvlist (!! n q)) (vbound (!! n q) + 9)
                        (relativ (Not q)))))))`;
     `vbound (!! n q) + 9`; `vbound (!! n q) + 10`;
     `v0:num->A`; `vs:A`]) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_RULE `~(vb + 9 = vb + 10)`] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `s:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `evaluation D (E:A->A->bool) om w s` ASSUME_TAC THENL
     [ASM_MESON_TAC[EVALUATION_EFUNS]; ALL_TAC] THEN
    ASM_CASES_TAC
      `?dce:A. dce IN D /\ eordinal D (E:A->A->bool) dce /\
               cewit D E n q s dce /\
               !c. c IN D /\ E c dce ==> ~(cewit D E n q s c)` THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `dce:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `dce:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `dce':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`;
        `v0:num->A`; `n:num`; `q:form`; `vbound (!! n q)`; `s:A`;
        `dce':A`] RANKCE_HOLDS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `dce':A`; `dce:A`]
            EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[EORDINAL_IN];
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `dce':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`;
        `v0:num->A`; `n:num`; `q:form`; `vbound (!! n q)`; `s:A`;
        `dce':A`] RANKCE_HOLDS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!b:A. b IN D /\ (E:A->A->bool) b bs
      ==> eordinal D E b /\
          ?s. s IN D /\ E s vs /\ evaluation D E om w s /\
              cewit D E n q s b /\
              !c. c IN D /\ E c b ==> ~(cewit D E n q s c)`
  (LABEL_TAC "bord") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@s. h1 h2 +" THEN
    SUBGOAL_THEN `evaluation D (E:A->A->bool) om w s` ASSUME_TAC THENL
     [ASM_MESON_TAC[EVALUATION_EFUNS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`;
      `v0:num->A`; `n:num`; `q:form`; `vbound (!! n q)`; `s:A`;
      `b:A`] RANKCE_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?b1:A. eunion D (E:A->A->bool) bs b1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(b1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bs:A`; `b1:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      USE_THEN "bord" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN SIMP_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?dd:A. dd IN D /\ eordinal D (E:A->A->bool) dd /\
           (E d0 dd \/ d0 = dd) /\ (E b1 dd \/ b1 = dd)`
  (X_CHOOSE_THEN `dd:A` (fun th ->
     MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d0:A`; `b1:A`]
          EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [EXISTS_TAC `b1:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `b1:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `d0:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[SEMCEB_ALT] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] SEMCEB_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`q:form`; `w:A`; `d0:A`; `dd:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`om':A`; `s:A`] THEN STRIP_TAC THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_EFUNS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`;
    `v0:num->A`; `n:num`; `q:form`; `vbound (!! n q)`; `s:A`]
    CEWIT_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dce:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) dce bs` ASSUME_TAC THENL
   [USE_THEN "bch" (MP_TAC o SPEC `dce:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`;
      `v0:num->A`; `n:num`; `q:form`; `vbound (!! n q)`; `s:A`;
      `dce:A`] RANKCE_HOLDS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[LE_REFL]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) dce b1` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `dce:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) dce b1 \/ dce = b1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `dce:A`; `b1:A`]
          EORDINAL_SUBSET_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) dce dd \/ dce = dd` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `dce:A`; `b1:A`; `dd:A`]
          EORDINAL_LE_TRANS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:num`; `q:form`;
                `s:A`; `dce:A`; `dd:A`] CEWIT_MONO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The counterexample-bounding formula has free variables only at the        *)
(* domain-set and target slots (everything else is bound: the quantified     *)
(* variable by its own quantifier, the parameters by bindfv, the tuple and   *)
(* auxiliary slots by the vb+5..vb+8 quantifiers). This is what makes the    *)
(* chain-step formula's free variables reduce to the erec slots, so the      *)
(* existential valuation packaging of the chain is valuation-independent.    *)
(* ------------------------------------------------------------------------- *)

let FV_CEB = prove
 (`!p vb wv dv. vbound p <= vb
        ==> FV(ceb_form vb wv dv p) SUBSET {wv, dv}`,
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THEN
  REPEAT GEN_TAC THENL
   [REWRITE_TAC[ceb_form; FV_CLAUSES; FV; EMPTY_SUBSET];
    REWRITE_TAC[ceb_form; FV_CLAUSES; FV; EMPTY_SUBSET];
    REWRITE_TAC[ceb_form; FV_CLAUSES; FV; EMPTY_SUBSET];
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[ceb_form; FV_CLAUSES; UNION_SUBSET] THEN CONJ_TAC THENL
     [USE_THEN "ihp" (MP_TAC o SPECL [`vb:num`; `wv:num`; `dv:num`]) THEN
      ANTS_TAC THENL
       [UNDISCH_TAC `vbound (a0 --> a1) <= vb` THEN
        REWRITE_TAC[vbound] THEN ARITH_TAC;
        DISCH_THEN ACCEPT_TAC];
      USE_THEN "ihq" (MP_TAC o SPECL [`vb:num`; `wv:num`; `dv:num`]) THEN
      ANTS_TAC THENL
       [UNDISCH_TAC `vbound (a0 --> a1) <= vb` THEN
        REWRITE_TAC[vbound] THEN ARITH_TAC;
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ih") THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `a0:num < vb` ASSUME_TAC THENL
   [UNDISCH_TAC `vbound (!! a0 a1) <= vb` THEN
    REWRITE_TAC[vbound] THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. m IN FV(bindfv (fvlist (!! a0 a1)) (vb + 5) (relativ (Not a1)))
        ==> m = vb + 5 \/ m = a0`
  (LABEL_TAC "fvb") THENL
   [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    MP_TAC(REWRITE_RULE[SUBSET; IN_INSERT; IN_ELIM_THM; NOT_IN_EMPTY]
      (SPECL [`fvlist (!! a0 a1)`; `vb + 5`; `relativ (Not a1)`]
             FV_BINDFV)) THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `m IN FV a1` ASSUME_TAC THENL
     [ASM_MESON_TAC[FV_RELATIV; SUBSET; FV_CLAUSES]; ALL_TAC] THEN
    UNDISCH_TAC `~(MEM m (fvlist (!! a0 a1)))` THEN
    REWRITE_TAC[MEM_FVLIST; FV; IN_DELETE] THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!m. m IN FV(lmem_at a0) ==> m = a0`
  (LABEL_TAC "fvl") THENL
   [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    MP_TAC(REWRITE_RULE[SUBSET; IN_INSERT; NOT_IN_EMPTY]
      (SPEC `a0:num` FV_LMEM_AT)) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ceb_form; FV_CLAUSES; UNION_SUBSET] THEN CONJ_TAC THENL
   [USE_THEN "ih" (MP_TAC o SPECL [`vb:num`; `wv:num`; `dv:num`]) THEN
    ANTS_TAC THENL
     [UNDISCH_TAC `vbound (!! a0 a1) <= vb` THEN
      REWRITE_TAC[vbound] THEN ARITH_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[FV; FV_CLAUSES; FV_OMEGA_FORM; FV_FUNS_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  TRY(ASM_ARITH_TAC) THEN
  TRY(USE_THEN "fvl" (MP_TAC o SPEC `m:num`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC] THEN
      DISCH_TAC THEN ASM_ARITH_TAC) THEN
  TRY(USE_THEN "fvb" (MP_TAC o SPEC `m:num`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC] THEN
      DISCH_TAC THEN ASM_ARITH_TAC) THEN
  MP_TAC(SPECL [`dv:num`; `vb + 8`; `m:num`] FVLT_RECAPP_LSTEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC] THEN
  DISCH_TAC THEN ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The chain-step formula. semchain D E p g a0 d is the semantic step        *)
(* condition: a0 IN d, every ordinal range-value of the input function g     *)
(* lies in d, and the union W of the stages indexed by those range values    *)
(* has its counterexamples (for every quantifier subformula of p, over all   *)
(* internal tuples from W) bounded by the stage L(d). chaincond is its       *)
(* object formula with parameter slots av (start ordinal), gv (input         *)
(* function) and dv (candidate value); chainstep p vb is the erec step:      *)
(* the output (variable 1) is the least ordinal satisfying the condition     *)
(* for the input (variable 0), with the start ordinal read from the ambient  *)
(* valuation at variable 2.                                                  *)
(* ------------------------------------------------------------------------- *)

let FV_INRAN_FORM = prove
 (`!b g. FV(inran_form b g) = {b, g}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[inran_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT;
              NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let semchain = new_definition
  `semchain D (E:A->A->bool) p g a0 d <=>
        E a0 d /\
        (!b. b IN D /\ einran D E b g /\ eordinal D E b ==> E b d) /\
        (?w'. w' IN D /\
              (!t. t IN D
                   ==> (E t w' <=>
                        ?b y. b IN D /\ y IN D /\ eordinal D E b /\
                              einran D E b g /\ elstage D E b y /\
                              E t y)) /\
              semceb D E w' d p)`;;

let chaincond = new_definition
  `chaincond p vb av gv dv =
     (av %% dv) &&
     ((!! (vb + 4) ((inran_form (vb + 4) gv && ordinal_form (vb + 4))
                    --> (vb + 4) %% dv)) &&
      (?? (vb + 2)
         ((!! (vb + 3)
             ((vb + 3) %% (vb + 2) <->
              ?? (vb + 4) (?? (vb + 9)
                 (inran_form (vb + 4) gv &&
                  (ordinal_form (vb + 4) &&
                   (recapp_form (rec_form lstep_form 2) (vb + 4) (vb + 9) &&
                    (vb + 3) %% (vb + 9))))))) &&
          ceb_form vb (vb + 2) dv p)))`;;

let chainstep = new_definition
  `chainstep p vb =
     ordinal_form 1 &&
     (chaincond p vb 2 0 1 &&
      !!- (vb + 1) 1 (Not (chaincond p vb 2 0 (vb + 1))))`;;

let HOLDS_CHAINCOND = prove
 (`!D (E:A->A->bool) v p vb av gv dv.
        model D E ZF_AX /\ valuation D v /\ vbound p <= vb /\
        ~(gv = vb + 2) /\ ~(gv = vb + 3) /\ ~(gv = vb + 4) /\
        ~(gv = vb + 9) /\
        ~(dv = vb + 2) /\ ~(dv = vb + 4) /\
        ~(dv = 2) /\ ~(dv = 3) /\ dv < vb + 5
        ==> (holds D E v (chaincond p vb av gv dv) <=>
             semchain D E p (v gv) (v av) (v dv))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[chaincond; semchain; HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') /\ (c <=> c')
      ==> ((a /\ b /\ c) <=> (a' /\ b' /\ c'))`) THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[holds];
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER] THEN
    SUBGOAL_THEN
     `!b:A. b IN D
        ==> (holds D E (((vb + 4) |-> b) v)
               (inran_form (vb + 4) gv && ordinal_form (vb + 4)) <=>
             einran D E b (v gv) /\ eordinal D E b)`
    (LABEL_TAC "p2s") THENL
     [X_GEN_TAC `b:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `valuation D (((vb + 4) |-> (b:A)) v)`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 4) |-> (b:A)) v`; `vb + 4`; `gv:num`]
        HOLDS_INRAN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 4) |-> (b:A)) v`; `vb + 4`]
        HOLDS_ORDINAL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "hm") THEN
      X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN
      USE_THEN "p2s" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(LABEL_TAC "hm") THEN
      X_GEN_TAC `b:A` THEN DISCH_TAC THEN
      USE_THEN "p2s" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    SUBGOAL_THEN
     `!w' t b y:A.
          w' IN D /\ t IN D /\ b IN D /\ y IN D
          ==> (holds D E
                (((vb + 9) |-> y) (((vb + 4) |-> b) (((vb + 3) |-> t)
                   (((vb + 2) |-> w') v))))
                (inran_form (vb + 4) gv &&
                 (ordinal_form (vb + 4) &&
                  (recapp_form (rec_form lstep_form 2) (vb + 4) (vb + 9) &&
                   (vb + 3) %% (vb + 9)))) <=>
               einran D E b (v gv) /\ eordinal D E b /\
               elstage D E b y /\ E t y)`
    (LABEL_TAC "pi4") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D (((vb + 9) |-> (y:A)) (((vb + 4) |-> (b:A))
          (((vb + 3) |-> (t:A)) (((vb + 2) |-> (w':A)) v))))`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REWRITE_TAC[HOLDS_AND; holds] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 9) |-> (y:A)) (((vb + 4) |-> (b:A)) (((vb + 3) |-> (t:A))
           (((vb + 2) |-> (w':A)) v)))`;
        `vb + 4`; `gv:num`] HOLDS_INRAN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 9) |-> (y:A)) (((vb + 4) |-> (b:A)) (((vb + 3) |-> (t:A))
           (((vb + 2) |-> (w':A)) v)))`;
        `vb + 4`] HOLDS_ORDINAL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 9) |-> (y:A)) (((vb + 4) |-> (b:A)) (((vb + 3) |-> (t:A))
           (((vb + 2) |-> (w':A)) v)))`;
        `vb + 4`; `vb + 9`] HOLDS_RECAPP_LSTEP) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_RULE
         `~(vb + 4 = 2) /\ ~(vb + 4 = 3) /\ ~(vb + 9 = 2) /\
          ~(vb + 9 = 3)`];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                   ARITH_RULE `~(vb + 4 = vb + 9) /\
                               ~(vb + 3 = vb + 9) /\
                               ~(vb + 3 = vb + 4)`];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!w' t:A.
          w' IN D /\ t IN D
          ==> (holds D E
                (((vb + 3) |-> t) (((vb + 2) |-> w') v))
                (?? (vb + 4) (?? (vb + 9)
                   (inran_form (vb + 4) gv &&
                    (ordinal_form (vb + 4) &&
                     (recapp_form (rec_form lstep_form 2) (vb + 4) (vb + 9) &&
                      (vb + 3) %% (vb + 9)))))) <=>
               ?b y. b IN D /\ y IN D /\ eordinal D E b /\
                     einran D E b (v gv) /\ elstage D E b y /\ E t y)`
    (LABEL_TAC "pin") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      REWRITE_TAC[HOLDS_EX] THEN EQ_TAC THENL
       [INTRO_TAC "@b. h3 @y. h4 +" THEN
        USE_THEN "pi4" (MP_TAC o SPECL
          [`w':A`; `t:A`; `b:A`; `y:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        STRIP_TAC THEN
        MAP_EVERY EXISTS_TAC [`b:A`; `y:A`] THEN ASM_REWRITE_TAC[];
        DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
          STRIP_ASSUME_TAC)) THEN
        EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "pi4" (MP_TAC o SPECL
          [`w':A`; `t:A`; `b:A`; `y:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!w':A. w' IN D
        ==> (holds D E (((vb + 2) |-> w') v)
              (ceb_form vb (vb + 2) dv p) <=>
             semceb D E w' (v dv) p)`
    (LABEL_TAC "pcb") THENL
     [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] HOLDS_CEB) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL
        [`p:form`; `((vb + 2) |-> (w':A)) v`; `vb:num`; `vb + 2`;
         `dv:num`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_RULE `vb + 2 < vb + 5`] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!w':A. w' IN D
        ==> (holds D E (((vb + 2) |-> w') v)
              (!! (vb + 3)
                 ((vb + 3) %% (vb + 2) <->
                  ?? (vb + 4) (?? (vb + 9)
                     (inran_form (vb + 4) gv &&
                      (ordinal_form (vb + 4) &&
                       (recapp_form (rec_form lstep_form 2)
                          (vb + 4) (vb + 9) &&
                        (vb + 3) %% (vb + 9))))))) <=>
             (!t. t IN D
                  ==> (E t w' <=>
                       ?b y. b IN D /\ y IN D /\ eordinal D E b /\
                             einran D E b (v gv) /\ elstage D E b y /\
                             E t y)))`
    (LABEL_TAC "pw") THENL
     [X_GEN_TAC `w':A` THEN DISCH_TAC THEN
      REWRITE_TAC[holds; HOLDS_IFF] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
               ARITH_RULE `~(vb + 2 = vb + 3)`] THEN
      EQ_TAC THENL
       [DISCH_THEN(LABEL_TAC "hm") THEN
        X_GEN_TAC `t:A` THEN DISCH_TAC THEN
        USE_THEN "hm" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "pin" (MP_TAC o SPECL [`w':A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        DISCH_THEN ACCEPT_TAC;
        DISCH_THEN(LABEL_TAC "hm") THEN
        X_GEN_TAC `t:A` THEN DISCH_TAC THEN
        USE_THEN "hm" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "pin" (MP_TAC o SPECL [`w':A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN EQ_TAC THENL
     [INTRO_TAC "@w'. h5 h1 h2" THEN
      EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "pw" (MP_TAC o SPEC `w':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "h1" (fun h ->
          ACCEPT_TAC(REWRITE_RULE[th] h)));
        USE_THEN "pcb" (MP_TAC o SPEC `w':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> USE_THEN "h2" (fun h ->
          ACCEPT_TAC(REWRITE_RULE[th] h)))];
      DISCH_THEN(X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "pw" (MP_TAC o SPEC `w':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        USE_THEN "pcb" (MP_TAC o SPEC `w':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[]]]]);;

let HOLDS_CHAINSTEP = prove
 (`!D (E:A->A->bool) v p vb u d.
        model D E ZF_AX /\ valuation D v /\ vbound p <= vb /\
        3 <= vb /\ u IN D /\ d IN D
        ==> (holds D E ((1 |-> d) ((0 |-> u) v)) (chainstep p vb) <=>
             eordinal D E d /\
             semchain D E p u (v 2) d /\
             !c. c IN D /\ E c d ==> ~(semchain D E p u (v 2) c))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((1 |-> (d:A)) ((0 |-> (u:A)) v))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[chainstep; HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT `(a <=> a') /\ (b <=> b') /\ (c <=> c')
      ==> ((a /\ b /\ c) <=> (a' /\ b' /\ c'))`) THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (d:A)) ((0 |-> (u:A)) v)`; `1`] HOLDS_ORDINAL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (d:A)) ((0 |-> (u:A)) v)`; `p:form`; `vb:num`;
      `2`; `0`; `1`] HOLDS_CHAINCOND) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (d:A)) ((0 |-> (u:A)) v)`;
      `vb + 1`; `1`;
      `Not (chaincond p vb 2 0 (vb + 1))`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL
     [ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD_BASIC; HOLDS_NOT] THEN
    SUBGOAL_THEN
     `!c:A. c IN D
        ==> (holds D E (((vb + 1) |-> c) ((1 |-> (d:A))
               ((0 |-> (u:A)) v)))
               (chaincond p vb 2 0 (vb + 1)) <=>
             semchain D E p u (v 2) c)`
    (LABEL_TAC "pcc") THENL
     [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((vb + 1) |-> (c:A)) ((1 |-> (d:A)) ((0 |-> (u:A)) v))`;
        `p:form`; `vb:num`; `2`; `0`; `vb + 1`] HOLDS_CHAINCOND) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
          REPEAT CONJ_TAC THEN ASM_ARITH_TAC];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN
       `((vb + 1) |-> (c:A)) ((1 |-> (d:A)) ((0 |-> (u:A)) v)) 0 = u /\
        ((vb + 1) |-> (c:A)) ((1 |-> (d:A)) ((0 |-> (u:A)) v)) 2 = v 2 /\
        ((vb + 1) |-> (c:A)) ((1 |-> (d:A)) ((0 |-> (u:A)) v))
          (vb + 1) = c`
      (fun th -> REWRITE_TAC[th]) THEN
      REPEAT CONJ_TAC THEN REWRITE_TAC[VALMOD] THEN
      REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN
      ASM_ARITH_TAC;
      ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "hm") THEN X_GEN_TAC `c:A` THEN
      STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "pcc" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_THEN(LABEL_TAC "hm") THEN X_GEN_TAC `c:A` THEN
      STRIP_TAC THEN
      USE_THEN "hm" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "pcc" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* Free variables of the chain formulas; the set of ordinal range values of  *)
(* any set; transport of ordinal membership along <=; existence of an        *)
(* ordinal satisfying the semantic chain condition (union stage via          *)
(* EWRAN_EXISTS, the counterexample bound via SEMCEB_EXISTS, the start       *)
(* ordinal and range values absorbed by the successor of a union, merged by  *)
(* trichotomy). Then the recursion-theorem instantiation: CHAINSTEP_QFUN is  *)
(* leastness-uniqueness, CHAINSTEP_QTOTAL is SEMCHAIN_EXISTS +               *)
(* EORDINAL_LEAST, echain packages the erec values with the start ordinal as *)
(* ambient parameter (valuation-independent by FV_CHAINSTEP), echaingr is    *)
(* its restriction graph, and ECHAIN_VALUE is the recursion equation: each   *)
(* chain value is the least ordinal satisfying the chain condition for the   *)
(* graph of earlier values.                                                  *)
(* ------------------------------------------------------------------------- *)

let FV_CHAINCOND = prove
 (`!p vb av gv dv.
        vbound p <= vb
        ==> FV(chaincond p vb av gv dv) SUBSET {av, gv, dv}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!m. m IN FV(ceb_form vb (vb + 2) dv p) ==> m = vb + 2 \/ m = dv`
  (LABEL_TAC "fc") THENL
   [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`p:form`; `vb:num`; `vb + 2`; `dv:num`] FV_CEB) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[SUBSET; IN_INSERT; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[chaincond; FV; FV_CLAUSES; FV_INRAN_FORM;
              FV_ORDINAL_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  TRY(ASM_ARITH_TAC) THEN
  TRY(MP_TAC(SPECL [`vb + 4`; `vb + 9`; `m:num`]
        FVLT_RECAPP_LSTEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC] THEN
      DISCH_TAC THEN ASM_ARITH_TAC) THEN
  USE_THEN "fc" (MP_TAC o SPEC `m:num`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC] THEN
  DISCH_TAC THEN ASM_ARITH_TAC);;

let FV_CHAINSTEP = prove
 (`!p vb. vbound p <= vb
          ==> FV(chainstep p vb) SUBSET {0, 1, 2}`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(!m. m IN FV(chaincond p vb 2 0 1) ==> m = 2 \/ m = 0 \/ m = 1) /\
    (!m. m IN FV(chaincond p vb 2 0 (vb + 1))
         ==> m = 2 \/ m = 0 \/ m = vb + 1)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`p:form`; `vb:num`; `2`; `0`; `1`]
        FV_CHAINCOND) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[SUBSET; IN_INSERT; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`p:form`; `vb:num`; `2`; `0`; `vb + 1`]
        FV_CHAINCOND) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[SUBSET; IN_INSERT; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[chainstep; FV; FV_CLAUSES; FV_ORDINAL_FORM] THEN
  REWRITE_TAC[SUBSET; IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  TRY(ASM_ARITH_TAC) THEN
  TRY(FIRST_X_ASSUM(fun th ->
        MP_TAC(SPEC `m:num` th) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
      DISCH_TAC THEN ASM_ARITH_TAC) THEN
  FIRST_X_ASSUM(fun th ->
    MP_TAC(SPEC `m:num` th) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN NO_TAC; ALL_TAC]) THEN
  DISCH_TAC THEN ASM_ARITH_TAC);;

let ERANORD_EXISTS = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D
        ==> ?bs. bs IN D /\
                 !b. b IN D
                     ==> (E b bs <=> eordinal D E b /\ einran D E b g)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!pr w':A. pr IN D /\ w' IN D
      ==> (holds D E ((1 |-> w') ((0 |-> pr) v0))
             (ordinal_form 1 && (?? 4 (opair_form 4 1 0))) <=>
           eordinal D E w' /\
           ?oo. oo IN D /\ eopair D E oo w' pr)`
  (LABEL_TAC "hro") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((1 |-> (w':A)) ((0 |-> (pr:A)) v0))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_AND; HOLDS_EX; HOLDS_ORDINAL_FORM] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
    MATCH_MP_TAC(TAUT
      `(a <=> a') /\ (b <=> b') ==> ((a /\ b) <=> (a' /\ b'))`) THEN
    CONJ_TAC THENL [REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!oo:A. oo IN D
        ==> (holds D E
              ((4 |-> oo) ((1 |-> w') ((0 |-> (pr:A)) v0)))
              (opair_form 4 1 0) <=>
             eopair D E oo w' pr)`
    ASSUME_TAC THENL
     [X_GEN_TAC `oo:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((4 |-> (oo:A)) ((1 |-> (w':A)) ((0 |-> (pr:A)) v0)))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
      SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ];
      ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`ordinal_form 1 && (?? 4 (opair_form 4 1 0))`; `0`; `1`;
     `v0:num->A`; `g:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC
      `?bb oo:A. bb IN D /\ oo IN D /\ eordinal D (E:A->A->bool) bb /\
                 eopair D E oo bb u` THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `bb:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `bb:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`u:A`; `w':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      STRIP_TAC THEN ASM_MESON_TAC[EOPAIR_INJ];
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "hro" (fun th -> MP_TAC(SPECL [`u:A`; `w':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      STRIP_TAC THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  EXISTS_TAC `bs:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `b:A` THEN DISCH_TAC THEN
  USE_THEN "bch" (MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[einran] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "hro" (fun th -> MP_TAC(SPECL [`pr:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    STRIP_TAC THEN EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hro" (fun th -> MP_TAC(SPECL [`pr:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[]]);;

let EORDINAL_MEM_TRANS = prove
 (`!D (E:A->A->bool) x d d'.
        model D E ZF_AX /\ eordinal D E d' /\ x IN D /\ d IN D /\
        E x d /\ (E d d' \/ d = d')
        ==> E x d'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
    is_disj(concl th))) THENL
   [ASM_MESON_TAC[eordinal; etransitive; esubset];
    ASM_MESON_TAC[]]);;

let SEMCHAIN_EXISTS = prove
 (`!D (E:A->A->bool) p g a0.
        model D E ZF_AX /\ g IN D /\ a0 IN D /\ eordinal D E a0
        ==> ?d. d IN D /\ eordinal D E d /\ semchain D E p g a0 d`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] EWRAN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `w':A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "wch"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] SEMCEB_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`p:form`; `w':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d1:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`] ERANORD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`; `a0:A`]
        EPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sg:A`) THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!w:A. w IN D ==> ((E:A->A->bool) w sg <=> w = a0)`
  (LABEL_TAC "sch") THENL
   [FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [epair] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "epair")) (concl th))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) MP_TAC) THEN
    DISCH_TAC THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bs:A`; `sg:A`]
        EBUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `bsa:A`) THEN
  SUBGOAL_THEN `(bsa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w bsa <=> E w bs \/ E w sg)`
  (LABEL_TAC "ach") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bs:A`; `sg:A`; `bsa:A`]
          EBUNION_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `ebunion D (E:A->A->bool) bs sg bsa` THEN
      REWRITE_TAC[th]) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D /\ (E:A->A->bool) b bsa ==> eordinal D E b`
  (LABEL_TAC "bo") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    USE_THEN "ach" (MP_TAC o SPEC `b:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) b bsa` THEN REWRITE_TAC[th]) THEN
    STRIP_TAC THENL
     [USE_THEN "bch" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      SIMP_TAC[];
      USE_THEN "sch" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      DISCH_THEN SUBST1_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?s1:A. eunion D (E:A->A->bool) bsa s1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(s1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) s1` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bsa:A`; `s1:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s1:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `d2:A`) THEN
  SUBGOAL_THEN `(d2:A) IN D /\ eordinal D (E:A->A->bool) d2`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b:A. b IN D /\ (E:A->A->bool) b bsa ==> E b d2`
  (LABEL_TAC "bin") THENL
   [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) b s1` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s1:A`; `d2:A`; `b:A`]
          ESUC_E) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `s1:A`]
          EORDINAL_SUBSET_MEMBER) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      USE_THEN "bo" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?dd:A. dd IN D /\ eordinal D (E:A->A->bool) dd /\
           (E d1 dd \/ d1 = dd) /\ (E d2 dd \/ d2 = dd)`
  (X_CHOOSE_THEN `dd:A` (fun th ->
     MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d1:A`; `d2:A`]
          EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [EXISTS_TAC `d2:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `d2:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `d1:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `dd:A` THEN ASM_REWRITE_TAC[semchain] THEN
  REPEAT CONJ_TAC THENL
   [SUBGOAL_THEN `(E:A->A->bool) a0 d2` ASSUME_TAC THENL
     [USE_THEN "bin" (MP_TAC o SPEC `a0:A`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "ach" (MP_TAC o SPEC `a0:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ2_TAC THEN
        USE_THEN "sch" (MP_TAC o SPEC `a0:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]);
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`; `d2:A`; `dd:A`]
          EORDINAL_MEM_TRANS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) b d2` ASSUME_TAC THENL
     [USE_THEN "bin" (MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "ach" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISJ1_TAC THEN
        USE_THEN "bch" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `d2:A`; `dd:A`]
          EORDINAL_MEM_TRANS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
    TRY(CONJ_TAC THENL [USE_THEN "wch" ACCEPT_TAC; ALL_TAC]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] SEMCEB_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL
      [`p:form`; `w':A`; `d1:A`; `dd:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let CHAINSTEP_QFUN = prove
 (`!D (E:A->A->bool) p vb v.
        model D E ZF_AX /\ valuation D v /\ vbound p <= vb /\ 3 <= vb
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v))
                               (chainstep p vb) /\
                     holds D E ((1 |-> w') ((0 |-> r) v))
                               (chainstep p vb)
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) w /\ semchain D E p r (v 2) w /\
    (!c. c IN D /\ E c w ==> ~(semchain D E p r (v 2) c))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `p:form`;
      `vb:num`; `r:A`; `w:A`] HOLDS_CHAINSTEP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) w' /\ semchain D E p r (v 2) w' /\
    (!c. c IN D /\ E c w' ==> ~(semchain D E p r (v 2) c))`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `p:form`;
      `vb:num`; `r:A`; `w':A`] HOLDS_CHAINSTEP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `w':A`]
        EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let CHAINSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) p vb v.
        model D E ZF_AX /\ valuation D v /\ vbound p <= vb /\
        3 <= vb /\ eordinal D E (v 2)
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v))
                                  (chainstep p vb)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `x:A` THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(v:num->A) 2 IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (((vb + 10) |-> (x:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((0 |-> c) (((vb + 10) |-> (x:A)) v))
             (chaincond p vb 2 (vb + 10) 0) <=>
           semchain D E p x (v 2) c)`
  (LABEL_TAC "pcc") THENL
   [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (c:A)) (((vb + 10) |-> (x:A)) v)`; `p:form`; `vb:num`;
      `2`; `vb + 10`; `0`] HOLDS_CHAINCOND) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        REPEAT CONJ_TAC THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `(0 |-> (c:A)) (((vb + 10) |-> (x:A)) v) (vb + 10) = x /\
      (0 |-> (c:A)) (((vb + 10) |-> (x:A)) v) 2 = v 2 /\
      (0 |-> (c:A)) (((vb + 10) |-> (x:A)) v) 0 = c`
    (fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THEN REWRITE_TAC[VALMOD] THEN
    REPEAT(COND_CASES_TAC THEN ASM_REWRITE_TAC[]) THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `x:A`;
                `(v:num->A) 2`] SEMCHAIN_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `chaincond p vb 2 (vb + 10) 0`;
    `((vb + 10) |-> (x:A)) v`; `d0:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "pcc" (MP_TAC o SPEC `d0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@d. h1 h2 hd hmin" THEN
  EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `p:form`;
    `vb:num`; `x:A`; `d:A`] HOLDS_CHAINSTEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "pcc" (MP_TAC o SPEC `d:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "hd" (fun h ->
      ACCEPT_TAC(REWRITE_RULE[th] h)));
    X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "hmin" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "pcc" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN ACCEPT_TAC]);;

let echain = new_definition
  `echain D (E:A->A->bool) p vb a0 k d <=>
        ?v. valuation D v /\ v 2 = a0 /\
            erec D E (chainstep p vb) v k d`;;

let ECHAIN_EREC = prove
 (`!D (E:A->A->bool) p vb a0 k d v.
        model D E ZF_AX /\ vbound p <= vb /\
        valuation D v /\ v 2 = a0
        ==> (echain D E p vb a0 k d <=>
             erec D E (chainstep p vb) v k d)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[echain] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) (chainstep p vb) v' k d <=>
      erec D E (chainstep p vb) v k d`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`p:form`; `vb:num`] FV_CHAINSTEP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[SUBSET; IN_INSERT; NOT_IN_EMPTY] THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN EXISTS_TAC `v:num->A` THEN ASM_REWRITE_TAC[]]);;

let ECHAIN_EXISTS = prove
 (`!D (E:A->A->bool) p vb a0 k.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\ eordinal D E k
        ==> ?d. d IN D /\ echain D E p vb a0 k d`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a0:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `chainstep p vb`; `(2 |-> (a0:A)) v0`; `k:A`] EREC_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `(2 |-> (a0:A)) v0`] CHAINSTEP_QFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `(2 |-> (a0:A)) v0`] CHAINSTEP_QTOTAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `d:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[echain] THEN
  EXISTS_TAC `(2 |-> (a0:A)) v0` THEN
  ASM_REWRITE_TAC[VALMOD_BASIC]);;

let echaingr = new_definition
  `echaingr D (E:A->A->bool) p vb a0 k r <=>
        r IN D /\
        !w. w IN D
            ==> (E w r <=>
                 ?b y. b IN D /\ y IN D /\ E b k /\
                       echain D E p vb a0 b y /\ eopair D E b y w)`;;

let ECHAINGR_ERECRES = prove
 (`!D (E:A->A->bool) p vb a0 k r v.
        model D E ZF_AX /\ vbound p <= vb /\
        valuation D v /\ v 2 = a0
        ==> (echaingr D E p vb a0 k r <=>
             erecres D E (chainstep p vb) v k r)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[echaingr; erecres] THEN
  SUBGOAL_THEN
   `!b y:A. echain D (E:A->A->bool) p vb a0 b y <=>
            erec D E (chainstep p vb) v b y`
  (fun th -> REWRITE_TAC[th]) THEN
  REPEAT GEN_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
    `a0:A`; `b:A`; `y:A`; `v:num->A`] ECHAIN_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let ECHAIN_UNIQUE = prove
 (`!D (E:A->A->bool) p vb a0 k d d'.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ k IN D /\ d IN D /\ d' IN D /\
        echain D E p vb a0 k d /\ echain D E p vb a0 k d'
        ==> d = d'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a0:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `chainstep p vb`;
    `(2 |-> (a0:A)) v0`; `k:A`; `d:A`; `d':A`] EREC_UNIQUE) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
      `(2 |-> (a0:A)) v0`] CHAINSTEP_QFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `a0:A`; `k:A`; `d:A`; `(2 |-> (a0:A)) v0`] ECHAIN_EREC) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `a0:A`; `k:A`; `d':A`; `(2 |-> (a0:A)) v0`] ECHAIN_EREC) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)))]]);;

let ECHAINGR_EXISTS = prove
 (`!D (E:A->A->bool) p vb a0 k.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\ eordinal D E k
        ==> ?r. echaingr D E p vb a0 k r`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a0:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `chainstep p vb`;
