  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `(2 |-> (a0:A)) v0`] CHAINSTEP_QFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `(2 |-> (a0:A)) v0`] CHAINSTEP_QTOTAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `r:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
    `a0:A`; `k:A`; `r:A`; `(2 |-> (a0:A)) v0`] ECHAINGR_ERECRES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

let ECHAIN_VALUE = prove
 (`!D (E:A->A->bool) p vb a0 k d r.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\ eordinal D E k /\
        d IN D /\ echain D E p vb a0 k d /\
        echaingr D E p vb a0 k r
        ==> eordinal D E d /\ semchain D E p r a0 d /\
            !c. c IN D /\ E c d ==> ~(semchain D E p r a0 c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a0:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[echaingr]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `chainstep p vb`;
    `(2 |-> (a0:A)) v0`; `k:A`; `d:A`; `r:A`] EREC_EQUATION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `(2 |-> (a0:A)) v0`] CHAINSTEP_QFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `a0:A`; `k:A`; `d:A`; `(2 |-> (a0:A)) v0`] ECHAIN_EREC) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
        `a0:A`; `k:A`; `r:A`; `(2 |-> (a0:A)) v0`] ECHAINGR_ERECRES) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(fun h -> ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)))];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (a0:A)) v0`;
    `p:form`; `vb:num`; `r:A`; `d:A`] HOLDS_CHAINSTEP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD_BASIC]);;

(* ------------------------------------------------------------------------- *)
(* Facts about the chain values: semceb persists to subformulas,             *)
(* evaluations are monotone in the codomain, the start ordinal lies in       *)
(* every chain value, values are ordinals, the chain is strictly             *)
(* E-increasing along the index (earlier values are ordinal range values of  *)
(* the restriction graph), and the limit: the union of the replacement       *)
(* image of omega under the chain graph formula is an ordinal c containing   *)
(* a0 and all chain values, and every member of c lies in some chain value.  *)
(* ------------------------------------------------------------------------- *)

let SEMCEB_SUBFORM = prove
 (`!q p. subform q p
         ==> !D (E:A->A->bool) w d.
                semceb D E w d p ==> semceb D E w d q`,
  MATCH_MP_TAC subform_INDUCT THEN REPEAT CONJ_TAC THEN
  REPEAT GEN_TAC THEN TRY DISCH_TAC THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[semceb] THEN
  ASM_MESON_TAC[]);;

let EVALUATION_MONO = prove
 (`!D (E:A->A->bool) om x x' s.
        evaluation D E om x s /\
        (!t. t IN D /\ E t x ==> E t x')
        ==> evaluation D E om x' s`,
  REWRITE_TAC[evaluation] THEN MESON_TAC[eapply; eisfun]);;

let ECHAIN_A0 = prove
 (`!D (E:A->A->bool) p vb a0 k d.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\ eordinal D E k /\
        d IN D /\ echain D E p vb a0 k d
        ==> E a0 d`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`] ECHAINGR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`; `d:A`; `r:A`] ECHAIN_VALUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[semchain] THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  ASM_REWRITE_TAC[]);;

let ECHAIN_INCREASING = prove
 (`!D (E:A->A->bool) p vb a0 j k dj dk.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\
        eordinal D E k /\ j IN D /\ E j k /\
        dj IN D /\ dk IN D /\
        echain D E p vb a0 j dj /\ echain D E p vb a0 k dk
        ==> E dj dk`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`] ECHAINGR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`; `dk:A`; `r:A`] ECHAIN_VALUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[semchain] THEN
  INTRO_TAC "h1 (h2 ir h3) h4" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) dj` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                  `a0:A`; `j:A`] ECHAINGR_EXISTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `rj:A`) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                  `a0:A`; `j:A`; `dj:A`; `rj:A`] ECHAIN_VALUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER];
      ALL_TAC] THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  USE_THEN "ir" (MP_TAC o SPEC `dj:A`) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[einran] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `j:A`; `dj:A`]
        EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `pr:A`) THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`pr:A`; `j:A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) pr r` MP_TAC THENL
   [FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [echaingr] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "echaingr")) (concl th))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `pr:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`j:A`; `dj:A`] THEN ASM_REWRITE_TAC[];
    SIMP_TAC[]]);;

let ECHAIN_ORDINAL = prove
 (`!D (E:A->A->bool) p vb a0 k d.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\ eordinal D E k /\
        d IN D /\ echain D E p vb a0 k d
        ==> eordinal D E d`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`] ECHAINGR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `r:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
                `a0:A`; `k:A`; `d:A`; `r:A`] ECHAIN_VALUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]]);;

let CHAIN_LIMIT = prove
 (`!D (E:A->A->bool) p a0 om.
        model D E ZF_AX /\ a0 IN D /\ eordinal D E a0 /\
        eomega D E om
        ==> ?c. c IN D /\ eordinal D E c /\ E a0 c /\
                (!k dk. k IN D /\ E k om /\ dk IN D /\
                        echain D E p (MAX (vbound p) 3) a0 k dk
                        ==> E dk c) /\
                (!t. t IN D /\ E t c
                     ==> ?k dk. k IN D /\ E k om /\ dk IN D /\
                                echain D E p (MAX (vbound p) 3) a0 k dk /\
                                E t dk)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `vbound p <= MAX (vbound p) 3 /\ 3 <= MAX (vbound p) 3`
  STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a0:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((4 |-> w) ((3 |-> k) ((2 |-> (a0:A)) v0)))
             (rec_form (chainstep p (MAX (vbound p) 3)) 3) <=>
           echain D E p (MAX (vbound p) 3) a0 k w)`
  (LABEL_TAC "hgr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (a0:A)) v0`;
      `chainstep p (MAX (vbound p) 3)`; `3`; `k:A`; `w:A`]
      HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_RULE `1 < 3`] THEN
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`p:form`; `MAX (vbound p) 3`] FV_CHAINSTEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[SUBSET; IN_INSERT; NOT_IN_EMPTY] THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[REWRITE_RULE[ARITH_RULE `3 + 1 = 4`] th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k:A`; `w:A`;
      `(2 |-> (a0:A)) v0`] ECHAIN_EREC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[VALMOD_BASIC]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`rec_form (chainstep p (MAX (vbound p) 3)) 3`; `3`; `4`;
     `(2 |-> (a0:A)) v0`; `om:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) k` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k:A`] ECHAIN_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `dk:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `dk:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `echain D (E:A->A->bool) p (MAX (vbound p) 3) a0 k w'`
    ASSUME_TAC THENL
     [USE_THEN "hgr" (MP_TAC o SPECL [`k:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> FIRST_X_ASSUM(fun h ->
        ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k:A`; `w':A`; `dk:A`]
      ECHAIN_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D
      ==> ((E:A->A->bool) w bb <=>
           ?k. k IN D /\ E k om /\
               echain D E p (MAX (vbound p) 3) a0 k w)`
  (LABEL_TAC "bch2") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "bch" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hgr" (MP_TAC o SPECL [`k:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> FIRST_X_ASSUM(fun h ->
        ACCEPT_TAC(GEN_REWRITE_RULE I [th] h)));
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hgr" (MP_TAC o SPECL [`k:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?c:A. eunion D (E:A->A->bool) bb c`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w bb ==> eordinal D E w`
  (LABEL_TAC "bord") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "bch2" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k:A`; `w:A`] ECHAIN_ORDINAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bb:A`; `c:A`]
          EORDINAL_EUNION) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!k dk:A. k IN D /\ E k om /\ dk IN D /\
             echain D E p (MAX (vbound p) 3) a0 k dk
             ==> (E:A->A->bool) dk c`
  (LABEL_TAC "up") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?sk:A. sk IN D /\ esuc D (E:A->A->bool) k sk /\ E sk om`
    STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
       [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
      REWRITE_TAC[einductive] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (K ALL_TAC) (MP_TAC o SPEC `k:A`))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `sk:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `sk:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ESUC_IN];
      ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) sk` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `sk:A`] ECHAIN_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `dsk:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) dk dsk` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
        `MAX (vbound p) 3`; `a0:A`; `k:A`; `sk:A`; `dk:A`; `dsk:A`]
        ECHAIN_INCREASING) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ESUC_MEMBER];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `dk:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `dsk:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "bch2" (MP_TAC o SPEC `dsk:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `sk:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [(* E a0 c *)
    SUBGOAL_THEN
     `?k0:A. k0 IN D /\ eempty D (E:A->A->bool) k0 /\ E k0 om`
    STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
       [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
      REWRITE_TAC[einductive] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `k0:A` STRIP_ASSUME_TAC) (K ALL_TAC))) THEN
      EXISTS_TAC `k0:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[eempty];
      ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) k0` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k0:A`] ECHAIN_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) a0 d0` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
        `MAX (vbound p) 3`; `a0:A`; `k0:A`; `d0:A`] ECHAIN_A0) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `a0:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `d0:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "bch2" (MP_TAC o SPEC `d0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `k0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eunion]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `t:A`)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
      check (fun h -> can (find_term (fun tm ->
        is_var tm && fst(dest_var tm) = "c")) (concl h) &&
        rator(rator(concl h)) = `(E:A->A->bool)` ))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
  USE_THEN "bch2" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
  DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`k:A`; `u:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* An internal valuation realizing finitely many prescribed slot values      *)
(* (list recursion with ECONSTFUN at the base and eupdate at internal        *)
(* numerals, preservation via numeral injectivity), transport of stage       *)
(* membership along <= of the indices, comparability of chain values, and    *)
(* the finite covering lemma: finitely many members of the limit union       *)
(* stage all lie in a single chain stage (fold with the trichotomy merge     *)
(* over omega indices).                                                      *)
(* ------------------------------------------------------------------------- *)

let EVALUATION_LIST_UPDATE = prove
 (`!D (E:A->A->bool) om x u0.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        u0 IN D /\ E u0 x
        ==> !l v. (!i. MEM i l ==> v i IN D /\ E (v i) x)
                  ==> ?s. s IN D /\ evaluation D E om x s /\
                          !i. MEM i l
                              ==> ?m. m IN D /\ enat D E i m /\
                                      eapply D E s m (v i)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  LIST_INDUCT_TAC THENL
   [X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `u0:A`]
          ECONSTFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `s:A` THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[MEM];
    ALL_TAC] THEN
  X_GEN_TAC `v:num->A` THEN REWRITE_TAC[MEM] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `v:num->A`) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@s. h1 h2 pres" THEN
  SUBGOAL_THEN `?nh:A. enat D (E:A->A->bool) h nh`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(nh:A) IN D /\ (E:A->A->bool) nh om`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN; ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(v:num->A) h IN D /\ (E:A->A->bool) (v h) x`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?s':A. eupdate D (E:A->A->bool) s nh ((v:num->A) h) s'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUPDATE_EXISTS]; ALL_TAC] THEN
  EXISTS_TAC `s':A` THEN
  SUBGOAL_THEN `(s':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
  SUBGOAL_THEN `evaluation D (E:A->A->bool) om x s'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EVALUATION_UPDATE]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `i:num` THEN STRIP_TAC THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    EXISTS_TAC `nh:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `nh:A`;
      `(v:num->A) h`; `s':A`] EUPDATE_APPLY_SAME) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVALUATION_IN];
      SIMP_TAC[]];
    USE_THEN "pres" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_CASES_TAC `m:A = nh` THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `i:num = h` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[ENAT_INJ]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `nh:A`;
        `(v:num->A) h`; `s':A`] EUPDATE_APPLY_SAME) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVALUATION_IN];
        SIMP_TAC[]];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `nh:A`;
        `(v:num->A) h`; `s':A`; `m:A`; `(v:num->A) i`]
        EUPDATE_APPLY_OTHER) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVALUATION_IN];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

let ELSTAGE_LE_MONO = prove
 (`!D (E:A->A->bool) da db ya yb u.
        model D E ZF_AX /\ eordinal D E da /\ eordinal D E db /\
        (E db da \/ db = da) /\ ya IN D /\ yb IN D /\
        elstage D E da ya /\ elstage D E db yb /\
        u IN D /\ E u yb
        ==> E u ya`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
    is_disj(concl th))) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `da:A`; `db:A`;
                  `ya:A`; `yb:A`; `u:A`] ELSTAGE_MONO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
      DISCH_THEN ACCEPT_TAC];
    ASM_MESON_TAC[ELSTAGE_UNIQUE; EORDINAL_IN]]);;

let ECHAIN_LE = prove
 (`!D (E:A->A->bool) p vb a0 j k dj dk.
        model D E ZF_AX /\ vbound p <= vb /\ 3 <= vb /\
        a0 IN D /\ eordinal D E a0 /\
        eordinal D E j /\ eordinal D E k /\ (E j k \/ j = k) /\
        dj IN D /\ dk IN D /\
        echain D E p vb a0 j dj /\ echain D E p vb a0 k dk
        ==> E dj dk \/ dj = dk`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  FIRST_X_ASSUM(DISJ_CASES_TAC o check (fun th ->
    is_disj(concl th))) THENL
   [DISJ1_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
      `a0:A`; `j:A`; `k:A`; `dj:A`; `dk:A`] ECHAIN_INCREASING) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
      DISCH_THEN ACCEPT_TAC];
    DISJ2_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `vb:num`;
      `a0:A`; `k:A`; `dj:A`; `dk:A`] ECHAIN_UNIQUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EORDINAL_IN]; ASM_MESON_TAC[]];
      DISCH_THEN ACCEPT_TAC]]);;

let CHAIN_COVER = prove
 (`!D (E:A->A->bool) p a0 om c w.
        model D E ZF_AX /\ a0 IN D /\ eordinal D E a0 /\
        eomega D E om /\ c IN D /\ eordinal D E c /\
        (!t. t IN D /\ E t c
             ==> ?k dk. k IN D /\ E k om /\ dk IN D /\
                        echain D E p (MAX (vbound p) 3) a0 k dk /\
                        E t dk) /\
        w IN D /\
        (!u. u IN D ==> (E u w <=>
             ?b z. b IN D /\ z IN D /\ E b c /\ elstage D E b z /\
                   E u z))
        ==> !l (v:num->A). (!i. MEM i l ==> v i IN D /\ E (v i) w)
                  ==> ?k dk y. k IN D /\ E k om /\ dk IN D /\
                               echain D E p (MAX (vbound p) 3) a0 k dk /\
                               y IN D /\ elstage D E dk y /\
                               !i. MEM i l ==> E (v i) y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 lim h7 wch" THEN
  SUBGOAL_THEN
   `vbound p <= MAX (vbound p) 3 /\ 3 <= MAX (vbound p) 3`
  STRIP_ASSUME_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k. k IN D /\ (E:A->A->bool) k om ==> eordinal D E k`
  (LABEL_TAC "omo") THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  LIST_INDUCT_TAC THENL
   [X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `?k0:A. k0 IN D /\ eempty D (E:A->A->bool) k0 /\ E k0 om`
    STRIP_ASSUME_TAC THENL
     [SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
       [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
      REWRITE_TAC[einductive] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `k0:A` STRIP_ASSUME_TAC) (K ALL_TAC))) THEN
      EXISTS_TAC `k0:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[eempty];
      ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) k0` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k0:A`] ECHAIN_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) d0` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
        `MAX (vbound p) 3`; `a0:A`; `k0:A`; `d0:A`] ECHAIN_ORDINAL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `?y0:A. y0 IN D /\ elstage D (E:A->A->bool) d0 y0`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`k0:A`; `d0:A`; `y0:A`] THEN
    ASM_REWRITE_TAC[MEM];
    ALL_TAC] THEN
  X_GEN_TAC `v:num->A` THEN REWRITE_TAC[MEM] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `v:num->A`) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@k1 d1 y1. h8 h9 h10 h11 h12 h13 cov1" THEN
  SUBGOAL_THEN `(v:num->A) h IN D /\ (E:A->A->bool) (v h) w`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "wch" (MP_TAC o SPEC `(v:num->A) h`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
    STRIP_ASSUME_TAC)) THEN
  USE_THEN "lim" (MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k2:A` (X_CHOOSE_THEN `d2:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) d1 /\ eordinal D E d2`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
        `MAX (vbound p) 3`; `a0:A`; `k1:A`; `d1:A`] ECHAIN_ORDINAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "omo" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
        `MAX (vbound p) 3`; `a0:A`; `k2:A`; `d2:A`] ECHAIN_ORDINAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "omo" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?y2:A. y2 IN D /\ elstage D (E:A->A->bool) d2 y2`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ((v:num->A) h) y2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d2:A`; `b:A`;
      `y2:A`; `z:A`; `(v:num->A) h`] ELSTAGE_MONO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?kk:A. kk IN D /\ (E:A->A->bool) kk om /\
           (E k1 kk \/ k1 = kk) /\ (E k2 kk \/ k2 = kk)`
  (X_CHOOSE_THEN `kk:A` (fun th ->
     MAP_EVERY ASSUME_TAC (CONJUNCTS th))) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k1:A`; `k2:A`]
          EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "omo" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    STRIP_TAC THENL
     [EXISTS_TAC `k2:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `k2:A` THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `k1:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
    `MAX (vbound p) 3`; `a0:A`; `kk:A`] ECHAIN_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "omo" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dkk:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) dkk` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `kk:A`; `dkk:A`] ECHAIN_ORDINAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "omo" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?yy:A. yy IN D /\ elstage D (E:A->A->bool) dkk yy`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d1 dkk \/ d1 = dkk` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k1:A`; `kk:A`; `d1:A`; `dkk:A`]
      ECHAIN_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "omo" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d2 dkk \/ d2 = dkk` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`;
      `MAX (vbound p) 3`; `a0:A`; `k2:A`; `kk:A`; `d2:A`; `dkk:A`]
      ECHAIN_LE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "omo" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`kk:A`; `dkk:A`; `yy:A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `i:num` THEN STRIP_TAC THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `dkk:A`; `d2:A`;
      `yy:A`; `y2:A`; `(v:num->A) h`] ELSTAGE_LE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `dkk:A`; `d1:A`;
      `yy:A`; `y1:A`; `(v:num->A) i`] ELSTAGE_LE_MONO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[];
        USE_THEN "cov1" (MP_TAC o SPEC `i:num`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
      DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* The reflection theorem.  For any formula p and ordinal a0 there is an     *)
(* ordinal c above a0 (a limit of internal omega-chain values) such that,    *)
(* writing w for the union of the stages L(b), b IN c: every subformula of   *)
(* p is absolute between the class L and the set stage w, for valuations     *)
(* taking all their slots inside w.  The forall case is by contradiction:    *)
(* a counterexample b over w is encoded on an internal valuation s over a    *)
(* single covering chain stage L(dk) (CHAIN_COVER + EVALUATION_LIST_UPDATE), *)
(* giving cewitl; the semceb bound of the next chain value dsk = value(k+1)  *)
(* then produces a least-rank counterexample b' inside L(dsk) SUBSET w,      *)
(* which the induction hypothesis turns back into an L-counterexample        *)
(* below w, contradicting the w-side hypothesis.                             *)
(* ------------------------------------------------------------------------- *)

let REFLECT = prove
 (`!D (E:A->A->bool) p a0.
        model D E ZF_AX /\ a0 IN D /\ eordinal D E a0
        ==> ?c w. c IN D /\ w IN D /\ eordinal D E c /\ E a0 c /\
                  (!u. u IN D
                       ==> (E u w <=>
                            ?b z. b IN D /\ z IN D /\ E b c /\
                                  elstage D E b z /\ E u z)) /\
                  !q v. subform q p /\ valuation D v /\
                        (!i. E (v i) w)
                        ==> (holds (lclass D E) E v q <=>
                             holds (\t. t IN D /\ E t w) E v q)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `a0:A`; `om:A`]
        CHAIN_LIMIT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@c. h1 h2 h3 up lim" THEN
  SUBGOAL_THEN `?yc:A. yc IN D /\ elstage D (E:A->A->bool) c yc`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `yc:A`]
        ELSTAGE_CHAR_TRANS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@w. h4 h5 wch h6" THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u w ==> elmem D E u`
  (LABEL_TAC "wel") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      STRIP_ASSUME_TAC)) THEN
    REWRITE_TAC[elmem] THEN
