(* ------------------------------------------------------------------------- *)
(* Separation in the class L.  Auxiliaries: finitely many constructible      *)
(* elements share one stage (ELMEM_LIST_BOUND, a fold with the ordinal       *)
(* trichotomy merge); and the shadow-parameterized union-stage carve         *)
(* ELMEM_INTRO_WS (EDEFMEM_CARVE with an internal valuation over the union   *)
(* stage W = UNION{L(b) : b IN c} and its shadow, so arbitrarily many        *)
(* parameters are available, not just the two pinned slots of ELMEM_INTRO;   *)
(* the carved set lies in L(c) by ELSTAGE_CHAR_TRANS).  Then                 *)
(* LCLASS_SEPARATION: bound the parameters and the domain a in a stage,      *)
(* reflect p to the union stage w over the limit c, carve                    *)
(* S = {z IN a | relativ p} by D-separation (its lclass members are          *)
(* characterized via HOLDS_RELATIV + HOLDS_VALUATION), and realize S as a    *)
(* definable subset of w via the object formula                              *)
(*   ?? m (Eq m 0 && m %% ja && ?? 0 (Eq 0 j0 && ?? x (Eq x m && p)))        *)
(* at fresh slots ja, j0, m carrying a and the protected 0-parameter through *)
(* the shadow of an internal valuation prescribed on fvlist p.               *)
(* ------------------------------------------------------------------------- *)

let ELMEM_LIST_BOUND = prove
 (`!D (E:A->A->bool) a (v:num->A).
        model D E ZF_AX /\ a IN D /\ elmem D E a
        ==> !l. (!i. MEM i l ==> v i IN D /\ elmem D E (v i))
                ==> ?g y. g IN D /\ y IN D /\ eordinal D E g /\
                          elstage D E g y /\ E a y /\
                          !i. MEM i l ==> E (v i) y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  LIST_INDUCT_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN
     `?g y:A. g IN D /\ y IN D /\ eordinal D (E:A->A->bool) g /\
              elstage D E g y /\ E a y`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[elmem]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`g:A`; `y:A`] THEN ASM_REWRITE_TAC[MEM];
    ALL_TAC] THEN
  REWRITE_TAC[MEM] THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th -> is_imp(concl th))) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g1:A` (X_CHOOSE_THEN `y1:A`
    (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))) THEN
  SUBGOAL_THEN
   `?g2 y2:A. g2 IN D /\ y2 IN D /\ eordinal D (E:A->A->bool) g2 /\
              elstage D E g2 y2 /\ E ((v:num->A) h) y2`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[elmem]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g1:A`; `g2:A`]
        EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [MAP_EVERY EXISTS_TAC [`g2:A`; `y2:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g2:A`; `g1:A`;
        `y2:A`; `y1:A`; `a:A`] ELSTAGE_LE_MONO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      X_GEN_TAC `i:num` THEN STRIP_TAC THENL
       [ASM_REWRITE_TAC[];
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g2:A`; `g1:A`;
          `y2:A`; `y1:A`; `(v:num->A) i`] ELSTAGE_LE_MONO) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
          DISCH_THEN ACCEPT_TAC]]];
    FIRST_X_ASSUM(SUBST_ALL_TAC o check (is_eq o concl)) THEN
    MAP_EVERY EXISTS_TAC [`g2:A`; `y2:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g2:A`; `g2:A`;
        `y2:A`; `y1:A`; `a:A`] ELSTAGE_LE_MONO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      X_GEN_TAC `i:num` THEN STRIP_TAC THENL
       [ASM_REWRITE_TAC[];
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g2:A`; `g2:A`;
          `y2:A`; `y1:A`; `(v:num->A) i`] ELSTAGE_LE_MONO) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
          DISCH_THEN ACCEPT_TAC]]];
    MAP_EVERY EXISTS_TAC [`g1:A`; `y1:A`] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `i:num` THEN STRIP_TAC THENL
     [FIRST_X_ASSUM SUBST_ALL_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g1:A`; `g2:A`;
        `y1:A`; `y2:A`; `(v:num->A) h`] ELSTAGE_LE_MONO) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
        DISCH_THEN ACCEPT_TAC];
      ASM_MESON_TAC[]]]);;

let ELMEM_INTRO_WS = prove
 (`!D (E:A->A->bool) c w z om s vw p.
        model D E ZF_AX /\ eordinal D E c /\ w IN D /\
        (!u. u IN D
             ==> (E u w <=>
                  ?b yb. b IN D /\ yb IN D /\ E b c /\
                         elstage D E b yb /\ E u yb)) /\
        z IN D /\ om IN D /\ eomega D E om /\
        s IN D /\ evaluation D E om w s /\ shadowed D E s vw /\
        esubset D E z w /\
        (!u. u IN D /\ E u w
             ==> (E u z <=>
                  holds (\t. t IN D /\ E t w) E ((0 |-> u) vw) p))
        ==> elmem D E z`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 h3 wch rest" THEN
  SUBGOAL_THEN `?yc:A. yc IN D /\ elstage D (E:A->A->bool) c yc`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `yc:A`]
        ELSTAGE_CHAR_TRANS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@w'. h4 h5 wch2 h6" THEN
  SUBGOAL_THEN `w':A = w` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "wch2" (MP_TAC o SPEC `t:A`) THEN ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  REMOVE_THEN "rest" (fun th ->
    MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  SUBGOAL_THEN `?cd:A. ecode D (E:A->A->bool) p cd` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECODE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `edefmem D (E:A->A->bool) w z` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `z:A`;
                  `om:A`; `s:A`; `vw:num->A`; `p:form`; `cd:A`]
          EDEFMEM_CARVE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  ASM_MESON_TAC[edef]);;

let LCLASS_SEPARATION = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p x v a.
           valuation (lclass D E) v /\ a IN lclass D E
           ==> ?s. s IN lclass D E /\
                   !z. z IN lclass D E
                       ==> (E z s <=> E z a /\
                            holds (lclass D E) E ((x |-> z) v) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_LCLASS] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!i. (v:num->A) i IN D /\ elmem D (E:A->A->bool) (v i)`
  (LABEL_TAC "vl") THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [valuation] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "valuation")) (concl th))) THEN
    REWRITE_TAC[IN_LCLASS] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `v:num->A`]
        ELMEM_LIST_BOUND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `fvlist p`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@g y. h1 h2 h3 h4 h5 pary" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `g:A`]
        REFLECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@c w. h6 h7 h8 h9 wch abs" THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u y ==> E u w`
  (LABEL_TAC "win") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`g:A`; `y:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a w` ASSUME_TAC THENL
   [USE_THEN "win" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. MEM i (fvlist p) ==> (E:A->A->bool) (v i) w`
  (LABEL_TAC "parw") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    USE_THEN "win" MATCH_MP_TAC THEN CONJ_TAC THENL
     [ASM_MESON_TAC[];
      USE_THEN "pary" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u w ==> elmem D E u`
  (LABEL_TAC "wel") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      STRIP_ASSUME_TAC)) THEN
    REWRITE_TAC[elmem] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EORDINAL_MEMBER];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u t:A. u IN D /\ (E:A->A->bool) u w /\ t IN D /\ E t u ==> E t w`
  (LABEL_TAC "wtr") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `t:A`] THEN STRIP_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      STRIP_ASSUME_TAC)) THEN
    USE_THEN "wch" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `etransitive D (E:A->A->bool) z` MP_TAC THENL
     [MATCH_MP_TAC ELSTAGE_TRANSITIVE THEN EXISTS_TAC `b:A` THEN
      ASM_MESON_TAC[EORDINAL_MEMBER];
      ALL_TAC] THEN
    REWRITE_TAC[etransitive] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `v2:num->A = \i. if MEM i (fvlist p) then v i else a` THEN
  SUBGOAL_THEN `valuation D (v2:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN REWRITE_TAC[valuation] THEN
    X_GEN_TAC `i:num` THEN REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!i. (E:A->A->bool) ((v2:num->A) i) w`
  (LABEL_TAC "v2w") THENL
   [EXPAND_TAC "v2" THEN X_GEN_TAC `i:num` THEN REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "parw" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`relativ p`; `x:num`; `v2:num->A`; `a:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D /\ elmem D (E:A->A->bool) z
          ==> (E z S <=> E z a /\ holds (lclass D E) E ((x |-> z) v) p)`
  (LABEL_TAC "main") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "sch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    AP_TERM_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] HOLDS_RELATIV) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:form`; `((x:num) |-> (z:A)) v2`]) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[valuation; IN_LCLASS] THEN X_GEN_TAC `i:num` THEN
      REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THENL
       [ASM_REWRITE_TAC[];
        CONJ_TAC THENL
         [ASM_MESON_TAC[valuation];
          USE_THEN "wel" MATCH_MP_TAC THEN CONJ_TAC THENL
           [ASM_MESON_TAC[valuation]; ASM_REWRITE_TAC[]]]];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `p:form`;
      `((x:num) |-> (z:A)) v`; `((x:num) |-> (z:A)) v2`]
      HOLDS_VALUATION) THEN
    ANTS_TAC THENL
     [X_GEN_TAC `i:num` THEN DISCH_TAC THEN REWRITE_TAC[VALMOD] THEN
      COND_CASES_TAC THEN REWRITE_TAC[] THEN
      EXPAND_TAC "v2" THEN REWRITE_TAC[] THEN
      ASM_REWRITE_TAC[MEM_FVLIST];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) S w` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w' a` ASSUME_TAC THENL
     [USE_THEN "sch" (MP_TAC o SPEC `w':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "wtr" (MP_TAC o SPECL [`a:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `vb = MAX (vbound p) (x + 1)` THEN
  SUBGOAL_THEN
   `~(vb + 1 = 0) /\ ~(vb + 2 = 0) /\ ~(vb + 3 = 0) /\
    ~(vb + 3 = vb + 1) /\ ~(vb + 3 = vb + 2) /\ ~(vb + 1 = vb + 2) /\
    ~(vb + 1 = x) /\ ~(vb + 2 = x) /\ ~(vb + 3 = x) /\
    ~(x = vb + 3) /\ ~(0 = vb + 2) /\ ~(0 = vb + 3) /\ ~(x = vb + 1)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vb" THEN ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i IN FV p ==> ~(i = vb + 1) /\ ~(i = vb + 2) /\ ~(i = vb + 3)`
  (LABEL_TAC "fvfresh") THENL
   [X_GEN_TAC `i:num` THEN DISCH_THEN(MP_TAC o MATCH_MP VBOUND_FV) THEN
    EXPAND_TAC "vb" THEN ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  ABBREV_TAC
   `vf:num->A = \i. if i = vb + 1 then a
                    else if i = vb + 2 then v2 0 else v2 i` THEN
  SUBGOAL_THEN
   `!i. (vf:num->A) i IN D /\ (E:A->A->bool) (vf i) w`
  (LABEL_TAC "vfd") THENL
   [X_GEN_TAC `i:num` THEN EXPAND_TAC "vf" THEN REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[valuation];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `a:A`]
    EVALUATION_LIST_UPDATE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`CONS (vb + 1) (CONS (vb + 2) (fvlist p))`; `vf:num->A`]) THEN
  ANTS_TAC THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@si. h10 h11 ipres" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `w:A`; `si:A`]
    SHADOWED_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `vw:num->A` (CONJUNCTS_THEN2
    (LABEL_TAC "shw") (LABEL_TAC "vww"))) THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) si` ASSUME_TAC THENL
   [ASM_MESON_TAC[evaluation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (vw:num->A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[SHADOWED_VALUATION]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. MEM i (CONS (vb + 1) (CONS (vb + 2) (fvlist p)))
        ==> (vw:num->A) i = (vf:num->A) i`
  (LABEL_TAC "vwp") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    USE_THEN "ipres" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `m1:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "shw" (MP_TAC o SPEC `i:num` o
      GEN_REWRITE_RULE I [shadowed]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `m2:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `m2:A = m1` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ENAT_UNIQUE]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `si:A`; `m1:A`;
      `(vw:num->A) i`; `(vf:num->A) i`] EAPPLY_UNIQUE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(vb + 1 = vb + 3) /\ ~(vb + 2 = vb + 3) /\ ~(vb + 2 = vb + 1) /\
    ~(0 = vb + 1) /\ ~(x = vb + 2)`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "vb" THEN ARITH_TAC; ALL_TAC] THEN
