   [USE_THEN "vwp" (MP_TAC o SPEC `vb + 1`) THEN
    ANTS_TAC THENL [REWRITE_TAC[MEM]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN EXPAND_TAC "vf" THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vw:num->A) (vb + 2) = (v2:num->A) 0` ASSUME_TAC THENL
   [USE_THEN "vwp" (MP_TAC o SPEC `vb + 2`) THEN
    ANTS_TAC THENL [REWRITE_TAC[MEM]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN EXPAND_TAC "vf" THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. MEM i (fvlist p) ==> (vw:num->A) i = (v2:num->A) i`
  (LABEL_TAC "vwv2") THENL
   [X_GEN_TAC `i:num` THEN DISCH_TAC THEN
    USE_THEN "vwp" (MP_TAC o SPEC `i:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[MEM]; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN EXPAND_TAC "vf" THEN
    SUBGOAL_THEN `~(i = vb + 1) /\ ~(i = vb + 2)`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "fvfresh" (MP_TAC o SPEC `i:num`) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[MEM_FVLIST]; ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u w
          ==> (E u S <=> E u a /\
               holds (\t. t IN D /\ E t w) E ((x |-> u) v2) p)`
  (LABEL_TAC "brg") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "sch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN AP_TERM_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] HOLDS_RELATIV) THEN
