    DISCH_THEN(MP_TAC o SPECL [`p:form`; `((x:num) |-> (u:A)) v2`]) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[valuation; IN_LCLASS] THEN X_GEN_TAC `i:num` THEN
