        REWRITE_TAC[] THEN CONJ_TAC THENL
         [ASM_MESON_TAC[valuation];
          USE_THEN "wel" MATCH_MP_TAC THEN CONJ_TAC THENL
           [ASM_MESON_TAC[valuation]; ASM_REWRITE_TAC[]]]];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "abs" (MP_TAC o SPECL
