    ANTS_TAC THENL
     [REWRITE_TAC[subform_RULES] THEN CONJ_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[]];
      DISCH_THEN ACCEPT_TAC];
