(* ------------------------------------------------------------------------- *)
(* Replacement in the class L, and the resulting main theorem MODEL_LCLASS:  *)
(* the constructible class of any model of ZF is itself a model of ZF over   *)
(* the same membership relation.  For replacement the image of a IN L under  *)
(* an L-functional formula is first collected by D-replacement applied to    *)
(* the lmem-guarded relativization (the guard keeps the D-level function     *)
(* single-valued), the image members are bounded in one stage by             *)
(* ELMEM_BOUND, the reflection stage is taken above both that bound and the  *)
(* parameter bound, and the image set is realized as a definable subset of   *)
(* the union stage w via                                                     *)
(*   ?? m (Eq m 0 && ?? 0 (Eq 0 j0 && ?? y (Eq y m && ?? x (x %% ja && p)))) *)
(* with the shadow carrying a at ja and the protected 0-parameter at j0.     *)
(* ------------------------------------------------------------------------- *)

let LCLASS_REPLACEMENT = prove
 (`!D (E:A->A->bool). model D E ZF_AX
     ==> !p x y v a.
           ~(x = y) /\ valuation (lclass D E) v /\ a IN lclass D E /\
           (!u. u IN lclass D E /\ E u a
                ==> ?w. w IN lclass D E /\
                        !w'. w' IN lclass D E /\
                             holds (lclass D E) E
                               ((y |-> w') ((x |-> u) v)) p
                             ==> w' = w)
           ==> ?b. b IN lclass D E /\
                   !w. w IN lclass D E
                       ==> (E w b <=>
                            ?u. u IN lclass D E /\ E u a /\
                                holds (lclass D E) E
                                  ((y |-> w) ((x |-> u) v)) p)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN
  REWRITE_TAC[IN_LCLASS] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))
      (LABEL_TAC "fn")))) THEN
  SUBGOAL_THEN
   `!i. (v:num->A) i IN D /\ elmem D (E:A->A->bool) (v i)`
  (LABEL_TAC "vl") THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [valuation] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "valuation")) (concl th))) THEN
    REWRITE_TAC[IN_LCLASS] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u:A. u IN D /\ (E:A->A->bool) u a ==> elmem D E u`
  (LABEL_TAC "atr") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`]
      ELMEM_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ABBREV_TAC `v2:num->A = \i. if MEM i (fvlist p) then v i else a` THEN
