let MODEL_LCLASS = prove
 (`!D (E:A->A->bool). model D E ZF_AX ==> model (lclass D E) E ZF_AX`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC ZF_MODEL_INTRO THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_NONEMPTY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_EXTENSIONAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_FOUNDATION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_PAIRING) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_UNION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_POWERSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_INFINITY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_SEPARATION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_REPLACEMENT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* The Delta_0 absoluteness layer between the ambient model and its          *)
(* constructible class LL = lclass D E.  LL is transitive (LCLASS_MEMBER);   *)
(* the basic building blocks (subset, empty, pair, union, ordered pair,      *)
(* successor, ordinal-hood, function graphs, applications, domains,          *)
(* restrictions, updates, inductive sets, ranges, omega, numerals) are       *)
(* absolute between (D,E) and (LL,E) at LL-arguments; and LL is closed under *)
(* the corresponding constructions (via the LCLASS_* model facts and         *)
(* uniqueness in D).                                                         *)
(* ------------------------------------------------------------------------- *)

let LCLASS_IN_D = prove
 (`!D (E:A->A->bool) u. u IN lclass D E ==> u IN D`,
  REWRITE_TAC[IN_LCLASS] THEN MESON_TAC[]);;

let ESUBSET_LCLASS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E
        ==> (esubset (lclass D E) E x y <=> esubset D E x y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esubset] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]);;

let EEMPTY_LCLASS = prove
 (`!D (E:A->A->bool) z.
        model D E ZF_AX /\ z IN lclass D E
        ==> (eempty (lclass D E) E z <=> eempty D E z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eempty] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]);;

let EPAIR_LCLASS = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        z IN lclass D E
        ==> (epair (lclass D E) E x y z <=> epair D E x y z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[epair] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]);;

let EUNION_LCLASS = prove
 (`!D (E:A->A->bool) x z.
        model D E ZF_AX /\ x IN lclass D E /\ z IN lclass D E
        ==> (eunion (lclass D E) E x z <=> eunion D E x z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eunion] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]);;

let LCLASS_EPAIR = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        epair D E x y z
        ==> z IN lclass D E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_PAIRING) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `epair (lclass D E) (E:A->A->bool) x y p`
  ASSUME_TAC THENL
   [ASM_REWRITE_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `epair D (E:A->A->bool) x y p` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = p` SUBST1_TAC THENL
   [ASM_MESON_TAC[EPAIR_UNIQUE]; ASM_REWRITE_TAC[]]);;

let LCLASS_EUNION = prove
 (`!D (E:A->A->bool) x z.
        model D E ZF_AX /\ x IN lclass D E /\ eunion D E x z
        ==> z IN lclass D E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_UNION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `eunion (lclass D E) (E:A->A->bool) x p`
  ASSUME_TAC THENL
   [ASM_REWRITE_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `eunion D (E:A->A->bool) x p` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `z:A = p` SUBST1_TAC THENL
   [ASM_MESON_TAC[EUNION_UNIQUE]; ASM_REWRITE_TAC[]]);;

let EOPAIR_LCLASS = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        z IN lclass D E
        ==> (eopair (lclass D E) E x y z <=> eopair D E x y z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopair] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN lclass D E /\ (p:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`; `p:A`] THEN
    ASM_MESON_TAC[EPAIR_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `p:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN lclass D E /\ (p:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EPAIR]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`s:A`; `p:A`] THEN
    ASM_MESON_TAC[EPAIR_LCLASS]]);;

let LCLASS_EOPAIR = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        eopair D E x y z
        ==> z IN lclass D E`,
  REWRITE_TAC[eopair] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[LCLASS_EPAIR]);;

let EBUNION_LCLASS = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        z IN lclass D E
        ==> (ebunion (lclass D E) E x y z <=> ebunion D E x y z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebunion] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN
    ASM_MESON_TAC[EPAIR_LCLASS; EUNION_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EPAIR]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN
    ASM_MESON_TAC[EPAIR_LCLASS; EUNION_LCLASS]]);;

let LCLASS_EBUNION = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        ebunion D E x y z
        ==> z IN lclass D E`,
  REWRITE_TAC[ebunion] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[LCLASS_EPAIR; LCLASS_EUNION]);;

let ESUC_LCLASS = prove
 (`!D (E:A->A->bool) x z.
        model D E ZF_AX /\ x IN lclass D E /\ z IN lclass D E
        ==> (esuc (lclass D E) E x z <=> esuc D E x z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esuc] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(s:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    EXISTS_TAC `s:A` THEN
    ASM_MESON_TAC[EPAIR_LCLASS; EBUNION_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(s:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EPAIR]; ALL_TAC] THEN
    EXISTS_TAC `s:A` THEN
    ASM_MESON_TAC[EPAIR_LCLASS; EBUNION_LCLASS]]);;

let ETRANSITIVE_LCLASS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN lclass D E
        ==> (etransitive (lclass D E) E x <=> etransitive D E x)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[etransitive] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D; ESUBSET_LCLASS]);;

let ELINEAR_LCLASS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN lclass D E
        ==> (elinear (lclass D E) E x <=> elinear D E x)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[elinear] THEN
  ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]);;

let EORDINAL_LCLASS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ x IN lclass D E
        ==> (eordinal (lclass D E) E x <=> eordinal D E x)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eordinal] THEN
  ASM_MESON_TAC[LCLASS_IN_D; ETRANSITIVE_LCLASS; ELINEAR_LCLASS]);;

let LCLASS_EOPAIR_MEMBERS = prove
 (`!D (E:A->A->bool) u w z.
        model D E ZF_AX /\ z IN lclass D E /\ u IN D /\ w IN D /\
        eopair D E u w z
        ==> u IN lclass D E /\ w IN lclass D E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eopair] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN lclass D E /\ (p:A) IN lclass D E`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN MATCH_MP_TAC LCLASS_MEMBER THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[epair];
    ALL_TAC] THEN
  CONJ_TAC THEN MATCH_MP_TAC LCLASS_MEMBER THENL
   [EXISTS_TAC `s:A`; EXISTS_TAC `p:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[epair]);;

let EISFUN_LCLASS = prove
 (`!D (E:A->A->bool) f.
        model D E ZF_AX /\ f IN lclass D E
        ==> (eisfun (lclass D E) E f <=> eisfun D E f)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eisfun] THEN EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "pf") (LABEL_TAC "un"))) THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "pf" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[LCLASS_IN_D; EOPAIR_LCLASS];
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN
       `(z:A) IN lclass D E /\ (z':A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `(u:A) IN lclass D E /\ (w:A) IN lclass D E /\
        (w':A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_EOPAIR_MEMBERS]; ALL_TAC] THEN
      USE_THEN "un" (MP_TAC o SPECL
        [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_LCLASS];
        DISCH_THEN ACCEPT_TAC]];
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      USE_THEN "pf" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_EOPAIR_MEMBERS]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[EOPAIR_LCLASS];
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN
       `(z:A) IN lclass D E /\ (z':A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "un" (MP_TAC o SPECL
        [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[LCLASS_IN_D; EOPAIR_LCLASS];
        DISCH_THEN ACCEPT_TAC]]]);;

let ERESTRICT_LCLASS = prove
 (`!D (E:A->A->bool) g b r.
        model D E ZF_AX /\ g IN lclass D E /\ b IN lclass D E /\
        r IN lclass D E
        ==> (erestrict (lclass D E) E g b r <=> erestrict D E g b r)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[erestrict] THEN EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ch")) THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[LCLASS_IN_D; EOPAIR_LCLASS];
      STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_EOPAIR_MEMBERS]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[EOPAIR_LCLASS]];
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
     [SUBGOAL_THEN `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_EOPAIR_MEMBERS]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[EOPAIR_LCLASS];
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[LCLASS_IN_D; EOPAIR_LCLASS]]]);;

let LCLASS_EAPPLY_RAN = prove
 (`!D (E:A->A->bool) g u w.
        model D E ZF_AX /\ g IN lclass D E /\ u IN D /\ w IN D /\
        eapply D E g u w
        ==> u IN lclass D E /\ w IN lclass D E`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eapply] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
   [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `g:A` THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
    ALL_TAC] THEN
  MATCH_MP_TAC LCLASS_EOPAIR_MEMBERS THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]);;

let EAPPLY_LCLASS = prove
 (`!D (E:A->A->bool) f u w.
        model D E ZF_AX /\ f IN lclass D E /\ u IN lclass D E /\
        w IN lclass D E
        ==> (eapply (lclass D E) E f u w <=> eapply D E f u w)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[eopair; epair]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_MESON_TAC[EOPAIR_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `f:A` THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
      ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_MESON_TAC[EOPAIR_LCLASS]]);;

let EINDOM_LCLASS = prove
 (`!D (E:A->A->bool) g u.
        model D E ZF_AX /\ g IN lclass D E /\ u IN lclass D E
        ==> (eindom (lclass D E) E g u <=> eindom D E g u)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eindom] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN
    ASM_MESON_TAC[LCLASS_IN_D; EAPPLY_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EAPPLY_RAN; LCLASS_IN_D]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN
    ASM_MESON_TAC[LCLASS_IN_D; EAPPLY_LCLASS]]);;

let EDOMAIN_LCLASS = prove
 (`!D (E:A->A->bool) g a.
        model D E ZF_AX /\ g IN lclass D E /\ a IN lclass D E
        ==> (edomain (lclass D E) E g a <=> edomain D E g a)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[edomain] THEN EQ_TAC THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      ASM_MESON_TAC[EINDOM_LCLASS];
      DISCH_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[eindom; LCLASS_EAPPLY_RAN]; ALL_TAC] THEN
      ASM_MESON_TAC[EINDOM_LCLASS]];
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    ASM_MESON_TAC[EINDOM_LCLASS]]);;

let EUPDATE_PAIRCLAUSE_LCLASS = prove
 (`!D (E:A->A->bool) a z.
        model D E ZF_AX /\ a IN lclass D E /\ z IN lclass D E
        ==> ((?w. w IN lclass D E /\ eopair (lclass D E) E a w z) <=>
             (?w. w IN D /\ eopair D E a w z))`,
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN
    ASM_MESON_TAC[LCLASS_IN_D; EOPAIR_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EOPAIR_MEMBERS; LCLASS_IN_D]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_MESON_TAC[EOPAIR_LCLASS]]);;

let EUPDATE_LCLASS = prove
 (`!D (E:A->A->bool) s a u s'.
        model D E ZF_AX /\ s IN lclass D E /\ a IN lclass D E /\
        u IN lclass D E /\ s' IN lclass D E
        ==> (eupdate (lclass D E) E s a u s' <=> eupdate D E s a u s')`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eupdate] THEN EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ch")) THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `z:A`]
        EUPDATE_PAIRCLAUSE_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`; `z:A`]
        EOPAIR_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_TAC THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [FIRST_X_ASSUM(DISJ_CASES_TAC o check (is_disj o concl)) THENL
         [ASM_MESON_TAC[LCLASS_MEMBER]; ASM_MESON_TAC[LCLASS_EOPAIR]];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `z:A`]
        EUPDATE_PAIRCLAUSE_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`; `z:A`]
        EOPAIR_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `z:A`]
      EUPDATE_PAIRCLAUSE_LCLASS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `u:A`; `z:A`]
      EOPAIR_LCLASS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[]]);;

let EINDUCTIVE_LCLASS = prove
 (`!D (E:A->A->bool) i.
        model D E ZF_AX /\ i IN lclass D E
        ==> (einductive (lclass D E) E i <=> einductive D E i)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[einductive] THEN EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) (LABEL_TAC "sc"))) THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    CONJ_TAC THENL
     [EXISTS_TAC `e:A` THEN
      ASM_MESON_TAC[EEMPTY_LCLASS; eempty];
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "sc" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `s:A` THEN
      ASM_MESON_TAC[ESUC_LCLASS; esuc; eunion; ebunion];
      ];
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [EXISTS_TAC `e:A` THEN
      SUBGOAL_THEN `(e:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; eempty]; ALL_TAC] THEN
      ASM_MESON_TAC[EEMPTY_LCLASS];
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      USE_THEN "sc" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(s:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; ESUC_IN]; ALL_TAC] THEN
      EXISTS_TAC `s:A` THEN ASM_MESON_TAC[ESUC_LCLASS]]]);;

let LCLASS_EOMEGA = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ eomega D E om ==> om IN lclass D E`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IN_LCLASS] THEN
  ASM_MESON_TAC[EOMEGA_IN; ELMEM_ORDINAL; EOMEGA_ORDINAL]);;

let EOMEGA_LCLASS = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ om IN lclass D E
        ==> (eomega (lclass D E) E om <=> eomega D E om)`,
  REPEAT STRIP_TAC THEN EQ_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN `?omd:A. eomega D (E:A->A->bool) omd`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(omd:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
    SUBGOAL_THEN `(om:A) IN D /\ (omd:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN `om:A = omd` SUBST1_TAC THENL
     [ALL_TAC; ASM_REWRITE_TAC[]] THEN
    MATCH_MP_TAC ESUBSET_ANTISYM THEN
    MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBGOAL_THEN `esubset (lclass D E) (E:A->A->bool) om omd`
      MP_TAC THENL
       [UNDISCH_TAC `eomega (lclass D E) (E:A->A->bool) om` THEN
        REWRITE_TAC[eomega] THEN
        DISCH_THEN(MP_TAC o CONJUNCT2) THEN
        DISCH_THEN MATCH_MP_TAC THEN
        ASM_MESON_TAC[EINDUCTIVE_LCLASS; eomega];
        ASM_MESON_TAC[ESUBSET_LCLASS]];
      UNDISCH_TAC `eomega D (E:A->A->bool) omd` THEN
      REWRITE_TAC[eomega] THEN
      DISCH_THEN(MP_TAC o CONJUNCT2) THEN
      DISCH_THEN MATCH_MP_TAC THEN
      ASM_MESON_TAC[EINDUCTIVE_LCLASS; eomega]];
    REWRITE_TAC[eomega] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EINDUCTIVE_LCLASS; eomega]; ALL_TAC] THEN
    X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(i:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[einductive]; ALL_TAC] THEN
    SUBGOAL_THEN `einductive D (E:A->A->bool) i` ASSUME_TAC THENL
     [ASM_MESON_TAC[EINDUCTIVE_LCLASS]; ALL_TAC] THEN
    ASM_MESON_TAC[ESUBSET_LCLASS; eomega]]);;

let ENAT_LCLASS = prove
 (`!D (E:A->A->bool) n x.
        model D E ZF_AX /\ x IN lclass D E
        ==> (enat (lclass D E) E n x <=> enat D E n x)`,
  GEN_TAC THEN GEN_TAC THEN INDUCT_TAC THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN REWRITE_TAC[enat] THENL
   [ASM_MESON_TAC[EEMPTY_LCLASS]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `y:A` THEN
    ASM_MESON_TAC[LCLASS_IN_D; ESUC_LCLASS];
    DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(y:A) IN lclass D E` ASSUME_TAC THENL
     [REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ELMEM_ORDINAL; ENAT_ORDINAL];
      ALL_TAC] THEN
    EXISTS_TAC `y:A` THEN
    ASM_MESON_TAC[ESUC_LCLASS]]);;

let LCLASS_ENAT = prove
 (`!D (E:A->A->bool) n x.
        model D E ZF_AX /\ enat D E n x ==> x IN lclass D E`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[IN_LCLASS] THEN
  ASM_MESON_TAC[ENAT_IN; ELMEM_ORDINAL; ENAT_ORDINAL]);;

(* ------------------------------------------------------------------------- *)
(* Internal omega-induction and the finite-sequence closure of L.            *)
(* EOMEGA_INDUCT_HOLDS is the reusable internal induction schema: the set of *)
(* omega-elements satisfying an object formula (carved by separation) is     *)
(* inductive, so omega-minimality gives all of omega -- this works for       *)
(* meta-properties like membership in lclass because lmem_at makes           *)
(* constructibility object-expressible.  The payoff here: every internal     *)
(* function whose domain is an element of omega and whose values are         *)
(* constructible is itself constructible (LCLASS_NAT_FUN), via the empty     *)
(* function (an ordinal) at the base and the decomposition                   *)
(* f = (f restricted to m) union {<m, f(m)>} at successors, carried through  *)
(* the induction by the object formula                                       *)
(*   !!1 ((fun 1 && dom 1 0 && !!2 !!3 (apply 1 2 3 --> lmem 3))             *)
(*        --> lmem 1).                                                       *)
(* Likewise the range of such a function is constructible (LCLASS_NAT_RAN).  *)
(* ------------------------------------------------------------------------- *)

let EOMEGA_INDUCT_HOLDS = prove
 (`!D (E:A->A->bool) om p k v.
    model D E ZF_AX /\ eomega D E om /\ valuation D v /\
    (!e. e IN D /\ eempty D E e ==> holds D E ((k |-> e) v) p) /\
    (!m sm. m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
            holds D E ((k |-> m) v) p
            ==> holds D E ((k |-> sm) v) p)
    ==> !n. n IN D /\ E n om ==> holds D E ((k |-> n) v) p`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 base step" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`p:form`; `k:num`; `v:num->A`; `om:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `S:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN `einductive D (E:A->A->bool) S` ASSUME_TAC THENL
   [REWRITE_TAC[einductive] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
       [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
      REWRITE_TAC[einductive] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) (K ALL_TAC))) THEN
      SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "sch" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN USE_THEN "base" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) u om /\ holds D E ((k |-> u) v) p`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "sch" (MP_TAC o SPEC `u:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
        REWRITE_TAC[] THEN DISCH_THEN(fun th ->
          MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `einductive D (E:A->A->bool) om` MP_TAC THENL
       [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
      REWRITE_TAC[einductive] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (K ALL_TAC) (MP_TAC o SPEC `u:A`))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "sch" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "step" (MP_TAC o SPECL [`u:A`; `s:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  X_GEN_TAC `n:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) om S` MP_TAC THENL
   [ASM_MESON_TAC[eomega]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  USE_THEN "sch" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
  REWRITE_TAC[] THEN DISCH_THEN(fun th ->
    MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  ASM_REWRITE_TAC[]);;

let ERESTRICT_ISFUN = prove
 (`!D (E:A->A->bool) g b r.
        model D E ZF_AX /\ eisfun D E g /\ erestrict D E g b r
        ==> eisfun D E r`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    MP_TAC MP_TAC)) THEN
  REWRITE_TAC[erestrict] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "rch")) THEN
  REWRITE_TAC[eisfun] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "pf") (LABEL_TAC "un"))) THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z g` ASSUME_TAC THENL
     [USE_THEN "rch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "pf" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z g /\ E z' g` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "rch" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
            (fun t -> concl t = `(E:A->A->bool) z r`))) THEN
        SIMP_TAC[];
        USE_THEN "rch" (MP_TAC o SPEC `z':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
            (fun t -> concl t = `(E:A->A->bool) z' r`))) THEN
        SIMP_TAC[]];
      ALL_TAC] THEN
    USE_THEN "un" (MP_TAC o SPECL
      [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let LCLASS_FUN_BASE = prove
 (`!D (E:A->A->bool) e f.
        model D E ZF_AX /\ eempty D E e /\ f IN D /\
        eisfun D E f /\ edomain D E f e
        ==> f IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) f` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `?u w:A. u IN D /\ w IN D /\ eopair D (E:A->A->bool) u w z`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) f u` ASSUME_TAC THENL
     [ASM_MESON_TAC[eindom; eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u e` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    ASM_MESON_TAC[eempty];
    ALL_TAC] THEN
  REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ELMEM_ORDINAL; EORDINAL_EEMPTY]);;

let LCLASS_FUN_STEP = prove
 (`!D (E:A->A->bool) om m sm f.
        model D E ZF_AX /\ eomega D E om /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
        (!g. g IN D /\ eisfun D E g /\ edomain D E g m /\
             (!u w. u IN D /\ w IN D /\ eapply D E g u w
                    ==> w IN lclass D E)
             ==> g IN lclass D E) /\
        f IN D /\ eisfun D E f /\ edomain D E f sm /\
        (!u w. u IN D /\ w IN D /\ eapply D E f u w
               ==> w IN lclass D E)
        ==> f IN lclass D E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 ih h7 h8 dom val" THEN
  SUBGOAL_THEN `?r:A. erestrict D (E:A->A->bool) f m r`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) r` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) r m` ASSUME_TAC THENL
   [REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u sm` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) f u` MP_TAC THENL
       [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
      REWRITE_TAC[eindom; eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[eindom; eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `u2:A`
        (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `u2:A = u` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN lclass D E` ASSUME_TAC THENL
   [USE_THEN "ih" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f u w` ASSUME_TAC THENL
     [UNDISCH_TAC `eapply D (E:A->A->bool) r u w` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) zz f` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPEC `zz:A` o CONJUNCT2 o
          GEN_REWRITE_RULE I [erestrict]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
            (fun t -> concl t = `(E:A->A->bool) zz r`))) THEN
        SIMP_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "val" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) f m` MP_TAC THENL
   [ASM_MESON_TAC[edomain; ESUC_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(w0:A) IN lclass D E` ASSUME_TAC THENL
   [USE_THEN "val" (MP_TAC o SPECL [`m:A`; `w0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN lclass D E` ASSUME_TAC THENL
   [REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ELMEM_ORDINAL; EOMEGA_ORDINALS];
    ALL_TAC] THEN
  SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) m w0 pr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_EXISTS; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(pr:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOPAIR]; ALL_TAC] THEN
  SUBGOAL_THEN `?sg:A. epair D (E:A->A->bool) pr pr sg`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EPAIR]; ALL_TAC] THEN
  SUBGOAL_THEN `?fb:A. ebunion D (E:A->A->bool) r sg fb`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_EXISTS; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(fb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(fb:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EBUNION]; ALL_TAC] THEN
  SUBGOAL_THEN `f:A = fb` SUBST1_TAC THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`; `sg:A`; `fb:A`]
        EBUNION_ALT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o GEN_REWRITE_RULE I [th] o
      check (fun t -> can (find_term (fun tt -> is_const tt &&
        fst(dest_const tt) = "ebunion")) (concl t)))) THEN
  DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(E:A->A->bool) z sg <=> z:A = pr`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN
     `?u2 w2:A. u2 IN D /\ w2 IN D /\
                eopair D (E:A->A->bool) u2 w2 z`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f u2 w2` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u2 sm` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u2 m \/ u2:A = m` MP_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u2:A`; `w2:A`] THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      SUBGOAL_THEN `w2:A = w0` SUBST_ALL_TAC THENL
       [MATCH_MP_TAC EAPPLY_UNIQUE THEN
        MAP_EVERY EXISTS_TAC
          [`D:A->bool`; `E:A->A->bool`; `f:A`; `m:A`] THEN
        ASM_REWRITE_TAC[];
        ASM_MESON_TAC[EOPAIR_UNIQUE]]];
    STRIP_TAC THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
          (fun t -> concl t = `(E:A->A->bool) z r`))) THEN
      SIMP_TAC[];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) f m w0` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z2:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `z2:A = pr` (fun th -> ASM_MESON_TAC[th]) THEN
      ASM_MESON_TAC[EOPAIR_UNIQUE; EOPAIR_IN]]]);;

let HOLDS_APPLY_LMEM_SLOTS = prove
 (`!D (E:A->A->bool) v a a' a''.
     model D E ZF_AX /\ valuation D v /\
     a IN D /\ a' IN D /\ a'' IN D
     ==> (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (apply_form 1 2 3) <=>
          eapply D E a a' a'') /\
         (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (lmem_at 3) <=>
          elmem D E a'')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v))`;
      `1`; `2`; `3`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v))`; `3`]
      HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]]);;

let HOLDS_LMEMFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (!! 1 ((fun_form 1 && (domain_form 1 0 &&
                 !! 2 (!! 3 (apply_form 1 2 3 --> lmem_at 3)))) -->
                lmem_at 1)) <=>
             !f. f IN D /\ eisfun D E f /\ edomain D E f (v 0) /\
                 (!u w. u IN D /\ w IN D /\ eapply D E f u w
                        ==> elmem D E w)
                 ==> elmem D E f)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[holds; HOLDS_AND; HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM;
               HOLDS_APPLY_FORM; HOLDS_LMEM_AT; VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_THEN(LABEL_TAC "mn") THENL
   [X_GEN_TAC `f:A` THEN
    INTRO_TAC "h1 h2 h3 sem" THEN
    USE_THEN "mn" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
        `f:A`; `u:A`; `w:A`] HOLDS_APPLY_LMEM_SLOTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_TAC THEN
      USE_THEN "sem" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `f:A` THEN DISCH_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "hf"))) THEN
    USE_THEN "mn" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      USE_THEN "hf" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
        `f:A`; `u:A`; `w:A`] HOLDS_APPLY_LMEM_SLOTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

let LCLASS_NAT_FUN = prove
 (`!D (E:A->A->bool) om n f.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        f IN D /\ eisfun D E f /\ edomain D E f n /\
        (!u w. u IN D /\ w IN D /\ eapply D E f u w
               ==> w IN lclass D E)
        ==> f IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 ((fun_form 1 && (domain_form 1 0 &&
       !! 2 (!! 3 (apply_form 1 2 3 --> lmem_at 3)))) --> lmem_at 1)`;
    `0`; `v0:num->A`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (e:A)) v0`]
        HOLDS_LMEMFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      X_GEN_TAC `g:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(g:A) IN lclass D E` MP_TAC THENL
       [MATCH_MP_TAC LCLASS_FUN_BASE THEN EXISTS_TAC `e:A` THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (m:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "holds")) (concl th))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (m:A)) v0`]
        HOLDS_LMEMFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      DISCH_THEN(LABEL_TAC "ihs") THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (sm:A)) v0`]
        HOLDS_LMEMFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      X_GEN_TAC `g:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(g:A) IN lclass D E` MP_TAC THENL
       [MATCH_MP_TAC LCLASS_FUN_STEP THEN
        MAP_EVERY EXISTS_TAC [`om:A`; `m:A`; `sm:A`] THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [X_GEN_TAC `g':A` THEN STRIP_TAC THEN
          SUBGOAL_THEN `elmem D (E:A->A->bool) g'` MP_TAC THENL
           [USE_THEN "ihs" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
            MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
            SUBGOAL_THEN `(w:A) IN lclass D E` MP_TAC THENL
             [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
              EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
              REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
            DISCH_TAC THEN REWRITE_TAC[IN_LCLASS] THEN
            ASM_REWRITE_TAC[]];
          MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
          REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[]];
        REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (n:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n:A)) v0`]
    HOLDS_LMEMFUN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  DISCH_THEN(MP_TAC o SPEC `f:A`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(w:A) IN lclass D E` MP_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
    DISCH_TAC THEN REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[]]);;

let HOLDS_INRAN_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (?? 1 (?? 2 (opair_form 2 0 1 && 1 %% 3))) <=>
             einran D E (v 0) (v 3))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
        ==> (holds D E ((2 |-> b) ((1 |-> a) v)) (opair_form 2 0 1) <=>
             eopair D (E:A->A->bool) b (v 0) a)`
  (LABEL_TAC "op") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (b:A)) ((1 |-> (a:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(2 |-> (b:A)) ((1 |-> (a:A)) v)`; `2`; `0`; `1`]
      HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds; einran] THEN
  USE_THEN "op" (fun th -> ASM_SIMP_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN EQ_TAC THENL
   [INTRO_TAC "@a. h1 @b. h2 + h3" THEN
    USE_THEN "op" (fun th -> MP_TAC(SPECL [`a:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `oo:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "op" (fun th -> MP_TAC(SPECL [`pr:A`; `oo:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let EINRAN_SET_EXISTS = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D
        ==> ?r. r IN D /\
                !w. w IN D ==> (E w r <=> einran D E w g)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?u1:A. eunion D (E:A->A->bool) g u1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2:A. eunion D (E:A->A->bool) u1 u2`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (?? 2 (opair_form 2 0 1 && 1 %% 3))`; `0`;
     `(3 |-> (g:A)) v0`; `u2:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rch"))) THEN
  EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (w:A)) ((3 |-> (g:A)) v0))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  USE_THEN "rch" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(0 |-> (w:A)) ((3 |-> (g:A)) v0)`] HOLDS_INRAN_SLOTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL [SIMP_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [einran]) THEN
  DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `?s p:A. epair D (E:A->A->bool) oo oo s /\ epair D E oo w p /\
            epair D E s p pr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eopair]; ALL_TAC] THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) p u1` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `p:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [eunion] o check (fun th ->
        can (find_term ((=) `u1:A`)) (concl th) &&
        can (find_term ((=) `g:A`)) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `pr:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[epair; EPAIR_IN; EOPAIR_IN];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o
    GEN_REWRITE_RULE I [eunion] o check (fun th ->
      can (find_term ((=) `u2:A`)) (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[epair]);;

let ERESTRICT_APPLY = prove
 (`!D (E:A->A->bool) g b gr u w.
        model D E ZF_AX /\ erestrict D E g b gr /\ eapply D E gr u w
        ==> eapply D E g u w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) gr u w` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
    GEN_REWRITE_RULE I [erestrict]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
      (fun t -> concl t = `(E:A->A->bool) z gr`))) THEN
  SIMP_TAC[]);;

let ERESTRICT_DOMAIN_SUC = prove
 (`!D (E:A->A->bool) g m sm gr.
        model D E ZF_AX /\ m IN D /\ sm IN D /\ esuc D E m sm /\
        eisfun D E g /\ edomain D E g sm /\ erestrict D E g m gr
        ==> edomain D E gr m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u sm` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) g u` MP_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erestrict]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[eindom; eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erestrict]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `u2:A`
      (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `u2:A = u` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ASM_REWRITE_TAC[]]]);;

let LCLASS_RAN_BASE = prove
 (`!D (E:A->A->bool) e g r.
        model D E ZF_AX /\ eempty D E e /\ g IN D /\
        eisfun D E g /\ edomain D E g e /\ r IN D /\
        (!w. w IN D ==> (E w r <=> einran D E w g))
        ==> r IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) r` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w:A` THEN REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `einran D (E:A->A->bool) w g` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) g oo` ASSUME_TAC THENL
     [ASM_MESON_TAC[eindom; eapply]; ALL_TAC] THEN
    ASM_MESON_TAC[edomain; eempty];
    ALL_TAC] THEN
  REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ELMEM_ORDINAL; EORDINAL_EEMPTY]);;

let LCLASS_RAN_STEP = prove
 (`!D (E:A->A->bool) om m sm g r.
        model D E ZF_AX /\ eomega D E om /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
        (!g' r'. g' IN D /\ eisfun D E g' /\ edomain D E g' m /\
                 (!u w. u IN D /\ w IN D /\ eapply D E g' u w
                        ==> w IN lclass D E) /\
                 r' IN D /\
                 (!w. w IN D ==> (E w r' <=> einran D E w g'))
                 ==> r' IN lclass D E) /\
        g IN D /\ eisfun D E g /\ edomain D E g sm /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w
               ==> w IN lclass D E) /\
        r IN D /\
        (!w. w IN D ==> (E w r <=> einran D E w g))
        ==> r IN lclass D E`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 ih h7 h8 dom val h9 rch" THEN
  SUBGOAL_THEN `?gr:A. erestrict D (E:A->A->bool) g m gr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(gr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) gr` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) gr m` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_DOMAIN_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?r':A. r' IN D /\
           !w. w IN D ==> ((E:A->A->bool) w r' <=> einran D E w gr)`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EINRAN_SET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(r':A) IN lclass D E` ASSUME_TAC THENL
   [USE_THEN "ih" (MP_TAC o SPECL [`gr:A`; `r':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      USE_THEN "val" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ERESTRICT_APPLY];
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) g m` MP_TAC THENL
   [ASM_MESON_TAC[edomain; ESUC_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(w0:A) IN lclass D E` ASSUME_TAC THENL
   [USE_THEN "val" (MP_TAC o SPECL [`m:A`; `w0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?sg:A. epair D (E:A->A->bool) w0 w0 sg`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EPAIR]; ALL_TAC] THEN
  SUBGOAL_THEN `?rb:A. ebunion D (E:A->A->bool) r' sg rb`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_EXISTS; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(rb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(rb:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EBUNION]; ALL_TAC] THEN
  SUBGOAL_THEN `r:A = rb` SUBST1_TAC THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "rch" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r':A`; `sg:A`; `rb:A`]
        EBUNION_ALT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o GEN_REWRITE_RULE I [th] o
      check (fun t -> can (find_term (fun tt -> is_const tt &&
        fst(dest_const tt) = "ebunion")) (concl t)))) THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(E:A->A->bool) w sg <=> w:A = w0`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ww. ww IN D ==> ((E:A->A->bool) ww r' <=> einran D E ww gr)`
  (LABEL_TAC "rpch") THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g oo w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) oo sm` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) oo m \/ oo:A = m` MP_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN
      USE_THEN "rpch" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[einran] THEN
      MAP_EVERY EXISTS_TAC [`pr:A`; `oo:A`] THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`oo:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      MATCH_MP_TAC EAPPLY_UNIQUE THEN
      MAP_EVERY EXISTS_TAC
        [`D:A->bool`; `E:A->A->bool`; `g:A`; `m:A`] THEN
      ASM_REWRITE_TAC[]];
    STRIP_TAC THENL
     [SUBGOAL_THEN `einran D (E:A->A->bool) w gr` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`pr:A`; `oo:A`] THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
          (fun t -> concl t = `(E:A->A->bool) pr gr`))) THEN
      SIMP_TAC[];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) g m w0` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      REWRITE_TAC[einran] THEN
      MAP_EVERY EXISTS_TAC [`z:A`; `m:A`] THEN
      ASM_MESON_TAC[EOPAIR_IN]]]);;

let HOLDS_RANPROP_SLOTS = prove
 (`!D (E:A->A->bool) v a a' a'' a'''.
     model D E ZF_AX /\ valuation D v /\
     a IN D /\ a' IN D /\ a'' IN D /\ a''' IN D
     ==> (holds D E ((4 |-> a''') ((3 |-> a'')
                     ((2 |-> a') ((1 |-> a) v))))
            (apply_form 1 3 4) <=>
          eapply D E a a'' a''') /\
         (holds D E ((4 |-> a''') ((3 |-> a'')
                     ((2 |-> a') ((1 |-> a) v))))
            (lmem_at 4) <=>
          elmem D E a''') /\
         (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (inran_form 3 1) <=>
          einran D E a'' a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (a''':A)) ((3 |-> (a'':A))
                 ((2 |-> (a':A)) ((1 |-> (a:A)) v))))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (a''':A)) ((3 |-> (a'':A))
        ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`;
      `1`; `3`; `4`] HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (a''':A)) ((3 |-> (a'':A))
        ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`;
      `4`] HOLDS_LMEM_AT) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v))`;
      `3`; `1`] HOLDS_INRAN_FORM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]]);;

let HOLDS_LMEMRAN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (!! 1 (!! 2 ((fun_form 1 && (domain_form 1 0 &&
                 ((!! 3 (!! 4 (apply_form 1 3 4 --> lmem_at 4))) &&
                  (!! 3 ((3 %% 2) <-> inran_form 3 1))))) -->
                lmem_at 2))) <=>
             !g r. g IN D /\ r IN D /\ eisfun D E g /\
                   edomain D E g (v 0) /\
                   (!u w. u IN D /\ w IN D /\ eapply D E g u w
                          ==> elmem D E w) /\
                   (!w. w IN D ==> (E w r <=> einran D E w g))
                   ==> elmem D E r)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[holds; HOLDS_AND; HOLDS_IFF; HOLDS_FUN_FORM;
               HOLDS_DOMAIN_FORM; VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_LMEM_AT; HOLDS_INRAN_FORM;
               VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[HOLDS_RANPROP_SLOTS] THEN
  SUBGOAL_THEN
   `!a a' a''. (a:A) IN D /\ a' IN D /\ a'' IN D
      ==> (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
             (inran_form 3 1) <=>
           einran D E a'' a)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
      `a:A`; `a':A`; `a'':A`; `a'':A`] HOLDS_RANPROP_SLOTS) THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  FIRST_X_ASSUM(K ALL_TAC o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "inran_form")) (concl th))) THEN
  EQ_TAC THEN DISCH_THEN(LABEL_TAC "H") THENL
   [MAP_EVERY X_GEN_TAC [`g:A`; `r:A`] THEN STRIP_TAC THEN
    USE_THEN "H" (MP_TAC o SPEC `g:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(MP_TAC o SPEC `r:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
        ASM_MESON_TAC[]]];
    X_GEN_TAC `g:A` THEN DISCH_TAC THEN
    X_GEN_TAC `r:A` THEN DISCH_TAC THEN STRIP_TAC THEN
    USE_THEN "H" (MP_TAC o SPECL [`g:A`; `r:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

let LCLASS_NAT_RAN = prove
 (`!D (E:A->A->bool) om n g r.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        g IN D /\ eisfun D E g /\ edomain D E g n /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w
               ==> w IN lclass D E) /\
        r IN D /\
        (!w. w IN D ==> (E w r <=> einran D E w g))
        ==> r IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 (!! 2 ((fun_form 1 && (domain_form 1 0 &&
       ((!! 3 (!! 4 (apply_form 1 3 4 --> lmem_at 4))) &&
        (!! 3 ((3 %% 2) <-> inran_form 3 1))))) -->
      lmem_at 2))`;
    `0`; `v0:num->A`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (e:A)) v0`]
        HOLDS_LMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      MAP_EVERY X_GEN_TAC [`gg:A`; `rr:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(rr:A) IN lclass D E` MP_TAC THENL
       [MATCH_MP_TAC LCLASS_RAN_BASE THEN
        MAP_EVERY EXISTS_TAC [`e:A`; `gg:A`] THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (m:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "holds")) (concl th))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (m:A)) v0`]
        HOLDS_LMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      DISCH_THEN(LABEL_TAC "ihs") THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (sm:A)) v0`]
        HOLDS_LMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD_BASIC] THEN
      MAP_EVERY X_GEN_TAC [`gg:A`; `rr:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(rr:A) IN lclass D E` MP_TAC THENL
       [MATCH_MP_TAC LCLASS_RAN_STEP THEN
        MAP_EVERY EXISTS_TAC [`om:A`; `m:A`; `sm:A`; `gg:A`] THEN
        ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [MAP_EVERY X_GEN_TAC [`g':A`; `r':A`] THEN STRIP_TAC THEN
          SUBGOAL_THEN `elmem D (E:A->A->bool) r'` MP_TAC THENL
           [USE_THEN "ihs" (MP_TAC o SPECL [`g':A`; `r':A`]) THEN
            ANTS_TAC THENL
             [ASM_REWRITE_TAC[] THEN
              MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
              SUBGOAL_THEN `(w:A) IN lclass D E` MP_TAC THENL
               [FIRST_X_ASSUM MATCH_MP_TAC THEN
                ASM_REWRITE_TAC[] THEN
                EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
                REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
              DISCH_THEN ACCEPT_TAC];
            DISCH_TAC THEN REWRITE_TAC[IN_LCLASS] THEN
            ASM_REWRITE_TAC[]];
          MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
          REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[]];
        REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (n:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n:A)) v0`]
    HOLDS_LMEMRAN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  DISCH_THEN(MP_TAC o SPECL [`g:A`; `r:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(w:A) IN lclass D E` MP_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[IN_LCLASS] THEN SIMP_TAC[]];
    DISCH_TAC THEN REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Redirect construction: from an internal function g and a target set w     *)
(* with default d0 IN w, carve g' with the same domain whose value at j is   *)
(* g(j) if that lies in w and d0 otherwise. Combined with range closure this *)
(* shows any subset of an enumerated constructible family is constructible.  *)
(* ------------------------------------------------------------------------- *)

let HOLDS_REDIRECT_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (?? 4 (?? 5 (opair_form 4 5 0 &&
                 (apply_form 1 4 5 ||
                  (Eq 5 2 &&
                   Not(?? 6 (apply_form 1 4 6 && (6 %% 3)))))))) <=>
             ?j. j IN D /\
                 ?q. q IN D /\
                     eopair D E j q (v 0) /\
                     (eapply D E (v 1) j q \/
                      q = v 2 /\
                      ~(?z. z IN D /\ eapply D E (v 1) j z /\
                            E z (v 3))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!j q:A. j IN D /\ q IN D
      ==> (holds D E ((5 |-> q) ((4 |-> j) v)) (opair_form 4 5 0) <=>
           eopair D (E:A->A->bool) j q (v 0))`
  (LABEL_TAC "op") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (q:A)) ((4 |-> (j:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (q:A)) ((4 |-> (j:A)) v)`; `4`; `5`; `0`]
      HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!j q:A. j IN D /\ q IN D
      ==> (holds D E ((5 |-> q) ((4 |-> j) v)) (apply_form 1 4 5) <=>
           eapply D (E:A->A->bool) (v 1) j q)`
  (LABEL_TAC "ap") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((5 |-> (q:A)) ((4 |-> (j:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (q:A)) ((4 |-> (j:A)) v)`; `1`; `4`; `5`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!j q z:A. j IN D /\ q IN D /\ z IN D
      ==> (holds D E ((6 |-> z) ((5 |-> q) ((4 |-> j) v)))
             (apply_form 1 4 6) <=>
           eapply D (E:A->A->bool) (v 1) j z)`
  (LABEL_TAC "apz") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (z:A)) ((5 |-> (q:A)) ((4 |-> (j:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (z:A)) ((5 |-> (q:A)) ((4 |-> (j:A)) v))`;
      `1`; `4`; `6`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_OR; HOLDS_NOT; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!a a':A. a IN D /\ a' IN D
      ==> ((holds D E ((5 |-> a') ((4 |-> a) v)) (opair_form 4 5 0) /\
            (holds D E ((5 |-> a') ((4 |-> a) v)) (apply_form 1 4 5) \/
             a' = v 2 /\
             ~(?a''. a'' IN D /\
                     holds D E ((6 |-> a'') ((5 |-> a') ((4 |-> a) v)))
                       (apply_form 1 4 6) /\
                     E a'' (v 3)))) <=>
           (eopair D (E:A->A->bool) a a' (v 0) /\
            (eapply D E (v 1) a a' \/
             a' = v 2 /\
             ~(?z. z IN D /\ eapply D E (v 1) a z /\ E z (v 3)))))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    USE_THEN "op" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ap" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `(?a''. a'' IN D /\
             holds D E ((6 |-> a'') ((5 |-> (a':A)) ((4 |-> (a:A)) v)))
               (apply_form 1 4 6) /\
             E a'' (v 3)) <=>
      (?z. z IN D /\ eapply D (E:A->A->bool) (v 1) a z /\ E z (v 3))`
    (fun th -> REWRITE_TAC[th]) THENL
     [EQ_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "apz" (fun th ->
          MP_TAC(SPECL [`a:A`; `a':A`; `zz:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
        DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "apz" (fun th ->
          MP_TAC(SPECL [`a:A`; `a':A`; `zz:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])]];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@aa. h1 @bb. h2 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`aa:A`; `bb:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    EXISTS_TAC `aa:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `bb:A` THEN ASM_REWRITE_TAC[];
    INTRO_TAC "@aa. h3 @bb. h4 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`aa:A`; `bb:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN DISCH_TAC THEN
    EXISTS_TAC `aa:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `bb:A` THEN ASM_REWRITE_TAC[]]);;

let EREDIRECT_EXISTS = prove
 (`!D (E:A->A->bool) g n w d0.
        model D E ZF_AX /\ g IN D /\ eisfun D E g /\ edomain D E g n /\
        n IN D /\ w IN D /\ d0 IN D /\ E d0 w
        ==> ?g'. g' IN D /\ eisfun D E g' /\ edomain D E g' n /\
                 !j q. j IN D /\ q IN D
                       ==> (eapply D E g' j q <=>
                            E j n /\ E q w /\
                            (eapply D E g j q \/
                             q = d0 /\
                             ~(?z. z IN D /\ eapply D E g j z /\
                                   E z w)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `?cr:A. ecross D (E:A->A->bool) n w cr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 4 (?? 5 (opair_form 4 5 0 &&
        (apply_form 1 4 5 ||
         (Eq 5 2 && Not(?? 6 (apply_form 1 4 6 && (6 %% 3)))))))`;
     `0`;
     `(3 |-> (w:A)) ((2 |-> (d0:A)) ((1 |-> (g:A)) v0))`; `cr:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g':A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sepch"))) THEN
  SUBGOAL_THEN
   `!z. (z:A) IN D
        ==> (E z g' <=>
             E z cr /\
             (?j. j IN D /\
                  ?q. q IN D /\ eopair D E j q z /\
                      (eapply D E g j q \/
                       q = d0 /\
                       ~(?z'. z' IN D /\ eapply D E g j z' /\
                              E z' w))))`
  (LABEL_TAC "gch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "sepch" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (z:A)) ((3 |-> (w:A)) ((2 |-> (d0:A))
        ((1 |-> (g:A)) v0)))`]
      HOLDS_REDIRECT_SLOTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!j q. (j:A) IN D /\ (q:A) IN D
          ==> (eapply D E g' j q <=>
               E j n /\ E q w /\
               (eapply D E g j q \/
                q = d0 /\
                ~(?z. z IN D /\ eapply D E g j z /\ E z w)))`
  (LABEL_TAC "vch") THENL
   [MAP_EVERY X_GEN_TAC [`j:A`; `q:A`] THEN STRIP_TAC THEN EQ_TAC THENL
     [DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gch" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) z g'` THEN REWRITE_TAC[th]) THEN
      INTRO_TAC "h1 @j'. h2 @q'. h3 h4 h5" THEN
      SUBGOAL_THEN `(j':A) = j /\ (q':A) = q` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [ecross] o check (fun th ->
          can (find_term ((=) `cr:A`)) (concl th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) z cr` THEN REWRITE_TAC[th]) THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(u:A) = j /\ (w':A) = q` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) j q z`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "gch" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      CONJ_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
          GEN_REWRITE_RULE I [ecross] o check (fun th ->
            can (find_term ((=) `cr:A`)) (concl th))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`j:A`; `q:A`] THEN ASM_REWRITE_TAC[];
        EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!uu ww ww'. (uu:A) IN D /\ (ww:A) IN D /\ (ww':A) IN D /\
                eapply D E g' uu ww /\ eapply D E g' uu ww'
                ==> ww = ww'`
  (LABEL_TAC "unq") THENL
   [MAP_EVERY X_GEN_TAC [`uu:A`; `ww:A`; `ww':A`] THEN STRIP_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`uu:A`; `ww:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `eapply D (E:A->A->bool) g' uu ww` THEN
      REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`uu:A`; `ww':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `eapply D (E:A->A->bool) g' uu ww'` THEN
      REWRITE_TAC[th]) THEN
    DISCH_TAC THEN
    ASM_MESON_TAC[EAPPLY_UNIQUE];
    ALL_TAC] THEN
  EXISTS_TAC `g':A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
      USE_THEN "gch" (fun th -> MP_TAC(SPEC `zz:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) zz g'` THEN REWRITE_TAC[th]) THEN
      INTRO_TAC "h6 @jj. h7 @qq. h8 h9 h10" THEN
      MAP_EVERY EXISTS_TAC [`jj:A`; `qq:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
        [`uu:A`; `ww:A`; `ww':A`; `zz:A`; `zz':A`] THEN
      STRIP_TAC THEN
      USE_THEN "unq" (fun th ->
        MP_TAC(SPECL [`uu:A`; `ww:A`; `ww':A`] th)) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REWRITE_TAC[eapply] THEN
        CONJ_TAC THENL [EXISTS_TAC `zz:A`; EXISTS_TAC `zz':A`] THEN
        ASM_REWRITE_TAC[];
        DISCH_THEN ACCEPT_TAC]];
    REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `uu:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) g uu` MP_TAC THENL
       [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
      REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
      ASM_CASES_TAC `(E:A->A->bool) vv w` THENL
       [EXISTS_TAC `vv:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`uu:A`; `vv:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        EXISTS_TAC `d0:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`uu:A`; `d0:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN
        ASM_MESON_TAC[EAPPLY_UNIQUE]];
      REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "vch" (fun th ->
        MP_TAC(SPECL [`uu:A`; `vv:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `eapply D (E:A->A->bool) g' uu vv` THEN
        REWRITE_TAC[th]) THEN
      SIMP_TAC[]]]);;

let LCLASS_SUBSET_RAN = prove
 (`!D (E:A->A->bool) om n h w d0.
     model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
     h IN D /\ eisfun D E h /\ edomain D E h n /\
     (!u q. u IN D /\ q IN D /\ eapply D E h u q
            ==> q IN lclass D E) /\
     w IN D /\ d0 IN D /\ E d0 w /\
     (!q. q IN D /\ E q w ==> ?u. u IN D /\ eapply D E h u q)
     ==> w IN lclass D E`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `n:A`;
                `w:A`; `d0:A`] EREDIRECT_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@g'. h1 h2 h3 vch" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                `g':A`; `w:A`] LCLASS_NAT_RAN) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `q:A`] THEN STRIP_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`u:A`; `q:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `eapply D (E:A->A->bool) g' u q` THEN
      REWRITE_TAC[th]) THEN
    STRIP_TAC THEN ASM_MESON_TAC[];
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `?u:A. u IN D /\ eapply D (E:A->A->bool) h u q`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u n` ASSUME_TAC THENL
       [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g' u q` MP_TAC THENL
       [USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`u:A`; `q:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[eapply; einran] THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
        MAP_EVERY EXISTS_TAC [`z:A`; `u:A`] THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN]];
      REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g' oo q` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`oo:A`; `q:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC `eapply D (E:A->A->bool) g' oo q` THEN
          REWRITE_TAC[th]) THEN
        SIMP_TAC[]]]]);;

(* ------------------------------------------------------------------------- *)
(* Internal ordinal addition via the generic recursion machinery: the step   *)
(* formula says the value is a UNION ran(attempt), i.e. a + b is a together  *)
(* with all a + b' for b' < b. Computation rules for zero and successor, an  *)
(* internal-induction proof that omega is closed under addition, and order   *)
(* facts (monotonicity, left cancellation via trichotomy, a SUBSET a + b).   *)
(* ------------------------------------------------------------------------- *)

let addstep_form = new_definition
  `addstep_form = !! 3 ((3 %% 1) <-> ((3 %% 2) || inran_form 3 0))`;;

let FV_ADDSTEP_FORM = prove
 (`FV addstep_form = {0,1,2}`,
  REWRITE_TAC[addstep_form; FV; FV_CLAUSES; FV_INRAN_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT;
              NOT_IN_EMPTY] THEN
  ARITH_TAC);;

let FVLT_ADDSTEP_FORM = prove
 (`!m. m IN FV addstep_form ==> m < 3`,
  REWRITE_TAC[FV_ADDSTEP_FORM; IN_INSERT; NOT_IN_EMPTY] THEN
  GEN_TAC THEN STRIP_TAC THEN ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let HOLDS_ADDSTEP_FORM = prove
 (`!D (E:A->A->bool) v r y.
      model D E ZF_AX /\ valuation D v /\ r IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> r) v)) addstep_form <=>
           !z. z IN D
               ==> (E z y <=> E z (v 2) \/ einran D E z r))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[addstep_form; holds; HOLDS_IFF; HOLDS_OR] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!a. (a:A) IN D
        ==> (holds D E ((3 |-> a) ((1 |-> y) ((0 |-> r) v)))
               (inran_form 3 0) <=>
             einran D (E:A->A->bool) a r)`
  (fun th -> ASM_SIMP_TAC[th]) THENL
   [X_GEN_TAC `aa:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (aa:A)) ((1 |-> (y:A)) ((0 |-> (r:A)) v))`;
      `3`; `0`] HOLDS_INRAN_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]]);;

let ADDSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v))
                       addstep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v))
                       addstep_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[HOLDS_ADDSTEP_FORM]);;

let ADDSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v))
                          addstep_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`]
    EINRAN_SET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r':A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?y:A. ebunion D (E:A->A->bool) (v 2) r' y`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_EXISTS; valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `x:A`;
                `y:A`] HOLDS_ADDSTEP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  ASM_MESON_TAC[EBUNION_ALT; valuation]);;

let eadd = new_definition
  `eadd D (E:A->A->bool) a b c <=>
        ?v. valuation D v /\
            erec D E addstep_form ((2 |-> a) v) b c`;;

let EADD_EREC = prove
 (`!D (E:A->A->bool) a b c v.
        model D E ZF_AX /\ valuation D v /\ a IN D
        ==> (eadd D E a b c <=>
             erec D E addstep_form ((2 |-> a) v) b c)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eadd] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
      `(2 |-> (a:A)) v'`; `(2 |-> (a:A)) v`; `b:A`; `c:A`]
      EREC_VALUATION) THEN
    ANTS_TAC THENL
     [X_GEN_TAC `m:num` THEN STRIP_TAC THEN
      SUBGOAL_THEN `m = 2` SUBST1_TAC THENL
       [MP_TAC(SPEC `m:num` FVLT_ADDSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        REWRITE_TAC[VALMOD_BASIC]];
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th])];
    DISCH_TAC THEN EXISTS_TAC `v:num->A` THEN ASM_REWRITE_TAC[]]);;

let EADD_UNIQUE = prove
 (`!D (E:A->A->bool) a b c c'.
        model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D /\ c' IN D /\
        eadd D E a b c /\ eadd D E a b c'
        ==> c = c'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
                `(2 |-> (a:A)) v`; `b:A`; `c:A`; `c':A`]
        EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (a:A)) v`]
    ADDSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EADD_EREC]);;

let EADD_EXISTS = prove
 (`!D (E:A->A->bool) a b.
        model D E ZF_AX /\ a IN D /\ eordinal D E b
        ==> ?c. c IN D /\ eadd D E a b c`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
                `(2 |-> (a:A)) v`; `b:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[ADDSTEP_QFUN; ADDSTEP_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EADD_EREC]);;

let EADD_CHAR = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ a IN D /\ eordinal D E b /\ c IN D /\
        eadd D E a b c
        ==> !z. z IN D
                ==> (E z c <=>
                     E z a \/
                     ?b'. b' IN D /\ E b' b /\ eadd D E a b' z)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((2 |-> (a:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN `erec D (E:A->A->bool) addstep_form ((2 |-> a) v0) b c`
  ASSUME_TAC THENL [ASM_MESON_TAC[EADD_EREC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?r. erecres D (E:A->A->bool) addstep_form ((2 |-> a) v0) b r`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
      `(2 |-> (a:A)) v0`; `b:A`] ERECRES_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
    ASM_MESON_TAC[ADDSTEP_QFUN; ADDSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
    `(2 |-> (a:A)) v0`; `b:A`; `c:A`; `r:A`] EREC_EQUATION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ADDSTEP_QFUN];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (a:A)) v0`;
    `r:A`; `c:A`] HOLDS_ADDSTEP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD_BASIC] THEN
  DISCH_THEN(LABEL_TAC "chr") THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "chr" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(p <=> q) ==> (r \/ p <=> r \/ q)`) THEN
  REWRITE_TAC[einran] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres] o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "erecres")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) pr r` THEN REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `b'':A` (X_CHOOSE_THEN `y:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(b'':A) = oo /\ (y:A) = z` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    EXISTS_TAC `oo:A` THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) addstep_form ((2 |-> a) v0) oo z`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[EADD_EREC];
    DISCH_THEN(X_CHOOSE_THEN `b':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) addstep_form ((2 |-> a) v0) b' z`
    ASSUME_TAC THENL [ASM_MESON_TAC[EADD_EREC]; ALL_TAC] THEN
    SUBGOAL_THEN `?pr:A. eopair D (E:A->A->bool) b' z pr`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(pr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`pr:A`; `b':A`] THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [erecres] o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "erecres")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b':A`; `z:A`] THEN ASM_REWRITE_TAC[]]);;

let EADD_ZERO = prove
 (`!D (E:A->A->bool) a z0.
        model D E ZF_AX /\ a IN D /\ eempty D E z0
        ==> eadd D E a z0 a`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) z0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `?c:A. c IN D /\ eadd D (E:A->A->bool) a z0 c`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) = a` (fun th -> ASM_MESON_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `z0:A`; `c:A`]
    EADD_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> SIMP_TAC[th]) THEN
  ASM_MESON_TAC[eempty]);;

let EADD_SUC = prove
 (`!D (E:A->A->bool) a b sb c sc.
        model D E ZF_AX /\ a IN D /\ eordinal D E b /\
        esuc D E b sb /\ c IN D /\ eadd D E a b c /\ esuc D E c sc
        ==> eadd D E a sb sc`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(sb:A) IN D /\ (sc:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sb` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `?c':A. c' IN D /\ eadd D (E:A->A->bool) a sb c'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c':A) = sc` (fun th -> ASM_MESON_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!y. (y:A) IN D /\ eadd D (E:A->A->bool) a b y ==> y = c`
  (LABEL_TAC "ueq") THENL
   [ASM_MESON_TAC[EADD_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> ((E:A->A->bool) w sb <=> E w b \/ w = b)`
  (LABEL_TAC "hesb") THENL
   [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> ((E:A->A->bool) w sc <=> E w c \/ w = c)`
  (LABEL_TAC "hesc") THENL
   [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`]
    EADD_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "chb") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `sb:A`; `c':A`]
    EADD_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "chsb") THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "chsb" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "hesc" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "chb" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[]);;

let EADD_OMEGA = prove
 (`!D (E:A->A->bool) om a b c.
        model D E ZF_AX /\ eomega D E om /\
        a IN D /\ E a om /\ b IN D /\ E b om /\
        c IN D /\ eadd D E a b c
        ==> E c om`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((7 |-> (om:A)) ((2 |-> (a:A)) v0))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n y. (n:A) IN D /\ (y:A) IN D
          ==> (holds D E
                ((4 |-> y) ((3 |-> n) ((7 |-> om) ((2 |-> a) v0))))
                (rec_form addstep_form 3) <=>
               eadd D (E:A->A->bool) a n y)`
  (LABEL_TAC "rch") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `y:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (om:A)) ((2 |-> (a:A)) v0)`; `addstep_form`; `3`;
      `n:A`; `y:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC; REWRITE_TAC[FVLT_ADDSTEP_FORM]];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `addstep_form`;
      `(7 |-> (om:A)) ((2 |-> (a:A)) v0)`; `(2 |-> (a:A)) v0`;
      `n:A`; `y:A`] EREC_VALUATION) THEN
    ANTS_TAC THENL
     [X_GEN_TAC `m:num` THEN STRIP_TAC THEN
      SUBGOAL_THEN `m = 2` SUBST1_TAC THENL
       [MP_TAC(SPEC `m:num` FVLT_ADDSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC;
        REWRITE_TAC[VALMOD] THEN
        CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
        REWRITE_TAC[]];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `n:A`; `y:A`;
      `v0:num->A`] EADD_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n. (n:A) IN D
        ==> (holds D E ((3 |-> n) ((7 |-> om) ((2 |-> a) v0)))
              (!! 4 (rec_form addstep_form 3 --> (4 %% 7))) <=>
             !y. (y:A) IN D
                 ==> eadd D (E:A->A->bool) a n y ==> E y om)`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    REWRITE_TAC[holds] THEN
    ASM_SIMP_TAC[] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 4 (rec_form addstep_form 3 --> (4 %% 7))`; `3`;
    `(7 |-> (om:A)) ((2 |-> (a:A)) v0)`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `e:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `y:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `(y:A) = a` SUBST1_TAC THENL
       [ASM_MESON_TAC[EADD_ZERO; EADD_UNIQUE];
        ASM_REWRITE_TAC[]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `sm:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "holds")) (concl th))) THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "ihs") THEN
      X_GEN_TAC `y:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
      SUBGOAL_THEN `?c1:A. c1 IN D /\ eadd D (E:A->A->bool) a m c1`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c1 om` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `?sc1:A. esuc D (E:A->A->bool) c1 sc1`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(sc1:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) sc1 om` ASSUME_TAC THENL
       [ASM_MESON_TAC[eomega; einductive; ESUC_UNIQUE]; ALL_TAC] THEN
      SUBGOAL_THEN `eadd D (E:A->A->bool) a sm sc1` ASSUME_TAC THENL
       [ASM_MESON_TAC[EADD_SUC]; ALL_TAC] THEN
      SUBGOAL_THEN `(y:A) = sc1` SUBST1_TAC THENL
       [ASM_MESON_TAC[EADD_UNIQUE]; ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  SIMP_TAC[]);;

let EADD_MONO = prove
 (`!D (E:A->A->bool) a b c i y.
        model D E ZF_AX /\ a IN D /\ eordinal D E b /\ c IN D /\
        eadd D E a b c /\ i IN D /\ E i b /\ y IN D /\ eadd D E a i y
        ==> E y c`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`]
    EADD_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISJ2_TAC THEN EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[]);;

let EADD_CANCEL = prove
 (`!D (E:A->A->bool) a i i' k.
        model D E ZF_AX /\ a IN D /\
        eordinal D E i /\ eordinal D E i' /\ k IN D /\
        eadd D E a i k /\ eadd D E a i' k
        ==> i = i'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(i:A) IN D /\ (i':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `i:A`; `i':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THENL
   [SUBGOAL_THEN `(E:A->A->bool) k k` MP_TAC THENL
     [MATCH_MP_TAC(GEN_ALL EADD_MONO) THEN
      MAP_EVERY EXISTS_TAC [`D:A->bool`; `a:A`; `i':A`; `i:A`] THEN
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[E_IRREFL]];
    SUBGOAL_THEN `(E:A->A->bool) k k` MP_TAC THENL
     [MATCH_MP_TAC(GEN_ALL EADD_MONO) THEN
      MAP_EVERY EXISTS_TAC [`D:A->bool`; `a:A`; `i:A`; `i':A`] THEN
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[E_IRREFL]]]);;

let EADD_SUBSET = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ a IN D /\ eordinal D E b /\ c IN D /\
        eadd D E a b c
        ==> !z. z IN D /\ E z a ==> E z c`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`]
    EADD_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISJ1_TAC THEN ASM_REWRITE_TAC[]);;

let EADD_NOTIN = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ a IN D /\ eordinal D E b /\ c IN D /\
        eadd D E a b c
        ==> ~(E c a)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c c` MP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`]
      EADD_SUBSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[];
    ASM_MESON_TAC[E_IRREFL]]);;

(* ------------------------------------------------------------------------- *)
(* Slot-generic object formula for eadd (pinning universals around rec_form) *)
(* and the doubling-step function: from f with omega-element domain M and a  *)
(* distinguished element vj, build f2 with domain M+M whose first half       *)
(* copies f and whose second half at M+i has value f(i) with vj adjoined.    *)
(* This is the successor step for enumerating internal power sets.           *)
(* ------------------------------------------------------------------------- *)

let add_form = new_definition
  `add_form i j k =
     !! 2 (!! 3 (!! 4 ((Eq 2 i && (Eq 3 j && Eq 4 k)) -->
                       rec_form addstep_form 3)))`;;

let HOLDS_ADD_FORM = prove
 (`!D (E:A->A->bool) v i j k.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(i = 4) /\
        ~(j = 2) /\ ~(j = 3) /\ ~(j = 4) /\
        ~(k = 2) /\ ~(k = 3) /\ ~(k = 4)
        ==> (holds D E v (add_form i j k) <=>
             eadd D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. (a:A) IN D /\ (b:A) IN D /\ (c:A) IN D
      ==> (holds D E ((4 |-> c) ((3 |-> b) ((2 |-> a) v)))
             (rec_form addstep_form 3) <=>
           eadd D (E:A->A->bool) a b c)`
  (LABEL_TAC "rc") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (a:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (a:A)) v`;
      `addstep_form`; `3`; `b:A`; `c:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC; REWRITE_TAC[FVLT_ADDSTEP_FORM]];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `c:A`;
      `v:num->A`] EADD_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  REWRITE_TAC[add_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
    ARITH_RULE `~(2 = 3) /\ ~(2 = 4) /\ ~(3 = 4)`] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) k`) THEN ASM_SIMP_TAC[] THEN
    USE_THEN "rc" (fun th ->
      MP_TAC(SPECL [`(v:num->A) i`; `(v:num->A) j`; `(v:num->A) k`]
        th)) THEN
    ASM_SIMP_TAC[];
    DISCH_TAC THEN
    X_GEN_TAC `a:A` THEN DISCH_TAC THEN
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN
    X_GEN_TAC `c:A` THEN DISCH_TAC THEN STRIP_TAC THEN
    USE_THEN "rc" (fun th ->
      MP_TAC(SPECL [`a:A`; `b:A`; `c:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_SHIFTIN_SLOTS = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u
              (?? 9 (?? 10 ((9 %% 5) && (add_form 5 9 7 &&
                 (apply_form 1 9 10 &&
                  !! 11 ((11 %% 8) <->
                         ((11 %% 10) || Eq 11 6))))))) <=>
             ?i. i IN D /\
                 ?w0. w0 IN D /\
                      E i (u 5) /\ eadd D E (u 5) i (u 7) /\
                      eapply D E (u 1) i w0 /\
                      !z. z IN D
                          ==> (E z (u 8) <=> E z w0 \/ z = u 6))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i w0:A. i IN D /\ w0 IN D
      ==> (holds D E ((10 |-> w0) ((9 |-> i) u)) (add_form 5 9 7) <=>
           eadd D (E:A->A->bool) (u 5) i (u 7))`
  (LABEL_TAC "ad") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((10 |-> (w0:A)) ((9 |-> (i:A)) u))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(10 |-> (w0:A)) ((9 |-> (i:A)) u)`; `5`; `9`; `7`]
      HOLDS_ADD_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i w0:A. i IN D /\ w0 IN D
      ==> (holds D E ((10 |-> w0) ((9 |-> i) u))
             (apply_form 1 9 10) <=>
           eapply D (E:A->A->bool) (u 1) i w0)`
  (LABEL_TAC "ap") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((10 |-> (w0:A)) ((9 |-> (i:A)) u))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(10 |-> (w0:A)) ((9 |-> (i:A)) u)`; `1`; `9`; `10`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_OR; HOLDS_IFF; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!a a':A. a IN D /\ a' IN D
      ==> ((E a (u 5) /\
            holds D E ((10 |-> a') ((9 |-> a) u)) (add_form 5 9 7) /\
            holds D E ((10 |-> a') ((9 |-> a) u))
              (apply_form 1 9 10) /\
            (!a''. a'' IN D
                   ==> (E a'' (u 8) <=> E a'' a' \/ a'' = u 6))) <=>
           (E a (u 5) /\ eadd D (E:A->A->bool) (u 5) a (u 7) /\
            eapply D E (u 1) a a' /\
            (!z. z IN D ==> (E z (u 8) <=> E z a' \/ z = u 6))))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    USE_THEN "ad" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ap" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a. h1 @b. h2 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`a:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    INTRO_TAC "@a. h3 @b. h4 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`a:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN DISCH_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

let HOLDS_SHIFT_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (?? 7 (?? 8 (opair_form 7 8 0 &&
                 (((7 %% 5) && apply_form 1 7 8) ||
                  ?? 9 (?? 10 ((9 %% 5) && (add_form 5 9 7 &&
                     (apply_form 1 9 10 &&
                      !! 11 ((11 %% 8) <->
                             ((11 %% 10) || Eq 11 6)))))))))) <=>
             ?k. k IN D /\
                 ?w. w IN D /\
                     eopair D E k w (v 0) /\
                     ((E k (v 5) /\ eapply D E (v 1) k w) \/
                      ?i. i IN D /\
                          ?w0. w0 IN D /\
                               E i (v 5) /\ eadd D E (v 5) i k /\
                               eapply D E (v 1) i w0 /\
                               !z. z IN D
                                   ==> (E z w <=>
                                        E z w0 \/ z = v 6)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((8 |-> w) ((7 |-> k) v)) (opair_form 7 8 0) <=>
           eopair D (E:A->A->bool) k w (v 0))`
  (LABEL_TAC "op") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((8 |-> (w:A)) ((7 |-> (k:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (w:A)) ((7 |-> (k:A)) v)`; `7`; `8`; `0`]
      HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((8 |-> w) ((7 |-> k) v)) (apply_form 1 7 8) <=>
           eapply D (E:A->A->bool) (v 1) k w)`
  (LABEL_TAC "ap") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((8 |-> (w:A)) ((7 |-> (k:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (w:A)) ((7 |-> (k:A)) v)`; `1`; `7`; `8`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((8 |-> w) ((7 |-> k) v))
            (?? 9 (?? 10 ((9 %% 5) && (add_form 5 9 7 &&
               (apply_form 1 9 10 &&
                !! 11 ((11 %% 8) <-> ((11 %% 10) || Eq 11 6))))))) <=>
           ?i. i IN D /\
               ?w0. w0 IN D /\
                    E i (v 5) /\ eadd D (E:A->A->bool) (v 5) i k /\
                    eapply D E (v 1) i w0 /\
                    !z. z IN D ==> (E z w <=> E z w0 \/ z = v 6))`
  (LABEL_TAC "sh") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((8 |-> (w:A)) ((7 |-> (k:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (w:A)) ((7 |-> (k:A)) v)`] HOLDS_SHIFTIN_SLOTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; HOLDS_OR; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!a a':A. a IN D /\ a' IN D
      ==> ((holds D E ((8 |-> a') ((7 |-> a) v))
              (opair_form 7 8 0) /\
            (E a (v 5) /\
             holds D E ((8 |-> a') ((7 |-> a) v))
               (apply_form 1 7 8) \/
             holds D E ((8 |-> a') ((7 |-> a) v))
              (?? 9 (?? 10 ((9 %% 5) && (add_form 5 9 7 &&
                 (apply_form 1 9 10 &&
                  !! 11 ((11 %% 8) <->
                         ((11 %% 10) || Eq 11 6))))))))) <=>
           (eopair D (E:A->A->bool) a a' (v 0) /\
            (E a (v 5) /\ eapply D E (v 1) a a' \/
             ?i. i IN D /\
                 ?w0. w0 IN D /\
                      E i (v 5) /\ eadd D E (v 5) i a /\
                      eapply D E (v 1) i w0 /\
                      !z. z IN D
                          ==> (E z a' <=> E z w0 \/ z = v 6))))`
  (LABEL_TAC "body") THENL
   [REPEAT STRIP_TAC THEN
    USE_THEN "op" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ap" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "sh" (fun th -> MP_TAC(SPECL [`a:A`; `a':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@a. h1 @b. h2 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`a:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[];
    INTRO_TAC "@a. h3 @b. h4 +" THEN
    USE_THEN "body" (fun th -> MP_TAC(SPECL [`a:A`; `b:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN DISCH_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

let ESHIFTFUN_EXISTS = prove
 (`!D (E:A->A->bool) f M MM vj.
        model D E ZF_AX /\ f IN D /\ eisfun D E f /\
        edomain D E f M /\ M IN D /\ eordinal D E M /\
        MM IN D /\ eadd D E M M MM /\ vj IN D
        ==> ?f2. f2 IN D /\ eisfun D E f2 /\ edomain D E f2 MM /\
                 !k w. k IN D /\ w IN D
                       ==> (eapply D E f2 k w <=>
                            E k M /\ eapply D E f k w \/
                            ?i w0. i IN D /\ w0 IN D /\ E i M /\
                                   eadd D E M i k /\
                                   eapply D E f i w0 /\
                                   !z. z IN D
                                       ==> (E z w <=>
                                            E z w0 \/ z = vj))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?R. R IN D /\
        !q. q IN D ==> ((E:A->A->bool) q R <=> einran D E q f)`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EINRAN_SET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?u1:A. eunion D (E:A->A->bool) R u1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?sv:A. epair D (E:A->A->bool) vj vj sv`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sv:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?bu:A. ebunion D (E:A->A->bool) u1 sv bu`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(bu:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?pw:A. epow D (E:A->A->bool) bu pw`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pw:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `?cr:A. ecross D (E:A->A->bool) MM pw cr`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(cr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 7 (?? 8 (opair_form 7 8 0 &&
        (((7 %% 5) && apply_form 1 7 8) ||
         ?? 9 (?? 10 ((9 %% 5) && (add_form 5 9 7 &&
            (apply_form 1 9 10 &&
             !! 11 ((11 %% 8) <-> ((11 %% 10) || Eq 11 6)))))))))`;
     `0`;
     `(6 |-> (vj:A)) ((5 |-> (M:A)) ((1 |-> (f:A)) v0))`; `cr:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f2:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sepch"))) THEN
  SUBGOAL_THEN
   `!p. (p:A) IN D
        ==> (E p f2 <=>
             E p cr /\
             (?k. k IN D /\
                  ?w. w IN D /\
                      eopair D E k w p /\
                      ((E k M /\ eapply D E f k w) \/
                       ?i. i IN D /\
                           ?w0. w0 IN D /\
                                E i M /\ eadd D E M i k /\
                                eapply D E f i w0 /\
                                !z. z IN D
                                    ==> (E z w <=>
                                         E z w0 \/ z = vj))))`
  (LABEL_TAC "gch") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    USE_THEN "sepch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (p:A)) ((6 |-> (vj:A)) ((5 |-> (M:A))
        ((1 |-> (f:A)) v0)))`] HOLDS_SHIFT_SLOTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D /\ einran D (E:A->A->bool) w f ==> E w pw`
  (LABEL_TAC "wpw") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w R` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w bu` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z u1` ASSUME_TAC THENL
       [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
      ASM_MESON_TAC[EBUNION_ALT];
      ASM_MESON_TAC[epow]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w0 w. (k:A) IN D /\ (w0:A) IN D /\ (w:A) IN D /\
             einran D (E:A->A->bool) w0 f /\
             (!z. z IN D ==> (E z w <=> E z w0 \/ z = vj))
             ==> E w pw`
  (LABEL_TAC "spw") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `w0:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) w0 R` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w bu` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z w0 \/ (z:A) = vj` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      STRIP_TAC THENL
       [SUBGOAL_THEN `(E:A->A->bool) z u1` ASSUME_TAC THENL
         [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
        ASM_MESON_TAC[EBUNION_ALT];
        SUBGOAL_THEN `(E:A->A->bool) z sv` ASSUME_TAC THENL
         [ASM_MESON_TAC[epair]; ALL_TAC] THEN
        ASM_MESON_TAC[EBUNION_ALT]];
      ASM_MESON_TAC[epow]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w. (k:A) IN D /\ (w:A) IN D
          ==> (eapply D E f2 k w <=>
               E k M /\ eapply D E f k w \/
               ?i. i IN D /\
                   ?w0. w0 IN D /\
                        E i M /\ eadd D E M i k /\
                        eapply D (E:A->A->bool) f i w0 /\
                        !z. z IN D
                            ==> (E z w <=> E z w0 \/ z = vj))`
  (LABEL_TAC "vch") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN EQ_TAC THENL
     [DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) p f2` THEN REWRITE_TAC[th]) THEN
      INTRO_TAC "h1 @k'. h2 @w'. h3 h4 dj" THEN
      SUBGOAL_THEN `(k':A) = k /\ (w':A) = w`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      USE_THEN "dj" ACCEPT_TAC;
      STRIP_TAC THENL
       [SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) k w p`
        STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
        SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) p cr` ASSUME_TAC THENL
         [SUBGOAL_THEN `(E:A->A->bool) k MM` ASSUME_TAC THENL
           [ASM_MESON_TAC[EADD_SUBSET]; ALL_TAC] THEN
          SUBGOAL_THEN `(E:A->A->bool) w pw` ASSUME_TAC THENL
           [USE_THEN "wpw" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
            ASM_MESON_TAC[eapply; einran; EOPAIR_IN];
            ALL_TAC] THEN
          ASM_MESON_TAC[ecross];
          ALL_TAC] THEN
        REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "gch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) k w p`
        STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
        SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) p cr` ASSUME_TAC THENL
         [SUBGOAL_THEN `(E:A->A->bool) k MM` ASSUME_TAC THENL
           [ASM_MESON_TAC[EADD_MONO]; ALL_TAC] THEN
          SUBGOAL_THEN `(E:A->A->bool) w pw` ASSUME_TAC THENL
           [USE_THEN "spw" (fun th ->
              MP_TAC(SPECL [`k:A`; `w0:A`; `w:A`] th)) THEN
