          ASM_MESON_TAC[ecross];
          ALL_TAC] THEN
        REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "gch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN
        EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k ww ww'. (k:A) IN D /\ (ww:A) IN D /\ (ww':A) IN D /\
               eapply D E f2 k ww /\ eapply D (E:A->A->bool) f2 k ww'
               ==> ww = ww'`
  (LABEL_TAC "unq") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `ww:A`; `ww':A`] THEN STRIP_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`k:A`; `ww:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `eapply D (E:A->A->bool) f2 k ww` THEN
      REWRITE_TAC[th]) THEN
    STRIP_TAC THENL
     [USE_THEN "vch" (fun th ->
        MP_TAC(SPECL [`k:A`; `ww':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `eapply D (E:A->A->bool) f2 k ww'` THEN
        REWRITE_TAC[th]) THEN
      STRIP_TAC THENL
       [ASM_MESON_TAC[EAPPLY_UNIQUE];
        ASM_MESON_TAC[EADD_NOTIN; EORDINAL_MEMBER]];
      USE_THEN "vch" (fun th ->
        MP_TAC(SPECL [`k:A`; `ww':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `eapply D (E:A->A->bool) f2 k ww'` THEN
        REWRITE_TAC[th]) THEN
      STRIP_TAC THENL
       [ASM_MESON_TAC[EADD_NOTIN; EORDINAL_MEMBER];
        SUBGOAL_THEN `(i:A) = i'` SUBST_ALL_TAC THENL
         [ASM_MESON_TAC[EADD_CANCEL; EORDINAL_MEMBER]; ALL_TAC] THEN
        SUBGOAL_THEN `(w0:A) = w0'` SUBST_ALL_TAC THENL
         [ASM_MESON_TAC[EAPPLY_UNIQUE]; ALL_TAC] THEN
        FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  EXISTS_TAC `f2:A` THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
