              can (find_term (fun tm -> is_const tm &&
                fst(dest_const tm) = "edomain")) (concl t))) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        REWRITE_TAC[eindom] THEN
        DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `?w:A. ebunion D (E:A->A->bool) vv sv w`
        STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
        SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
        EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`uu:A`; `w:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        DISJ2_TAC THEN
        EXISTS_TAC `b':A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `vv:A` THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `z:A` THEN DISCH_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vv:A`; `sv:A`;
          `w:A`] EBUNION_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
            check (fun t ->
              can (find_term (fun tm -> is_const tm &&
                fst(dest_const tm) = "ebunion")) (concl t) &&
              can (find_term ((=) `vv:A`)) (concl t)))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
          (MP_TAC o SPEC `z:A`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
          GEN_REWRITE_RULE I [epair] o check (fun t ->
            can (find_term (fun tm -> is_const tm &&
              fst(dest_const tm) = "epair")) (concl t))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        CONV_TAC TAUT];
      REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "vch" (fun th ->
        MP_TAC(SPECL [`uu:A`; `vv:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `eapply D (E:A->A->bool) f2 uu vv` THEN
        REWRITE_TAC[th]) THEN
      STRIP_TAC THENL
       [ASM_MESON_TAC[EADD_SUBSET];
        ASM_MESON_TAC[EADD_MONO]]];
    MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> (r \/ p <=> r \/ q)`) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `i:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC))) THEN
      MAP_EVERY EXISTS_TAC [`i:A`; `w0:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `i:A` (X_CHOOSE_THEN `w0:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* The pow-enum induction property: P(j) = "some f with omega-element domain *)
(* enumerates exactly the subsets of the image of j under h" as an object    *)
(* formula (slots 0=j, 1=h, 2=omega), with its HOLDS characterization, plus  *)
(* the singleton function used for the base case. subim_form is a named      *)
(* formula so that rewriting with holds does not unfold it.                  *)
(* ------------------------------------------------------------------------- *)

let HOLDS_SUBIM_SLOTS = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u
              (!! 7 ((7 %% 6) -->
                     ?? 8 ((8 %% 0) && apply_form 1 8 7))) <=>
             !z. z IN D
                 ==> E z (u 6)
                     ==> ?uu. uu IN D /\ E uu (u 0) /\
                              eapply D E (u 1) uu z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z uu:A. z IN D /\ uu IN D
      ==> (holds D E ((8 |-> uu) ((7 |-> z) u)) (apply_form 1 8 7) <=>
           eapply D (E:A->A->bool) (u 1) uu z)`
  (LABEL_TAC "ap") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((8 |-> (uu:A)) ((7 |-> (z:A)) u))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (uu:A)) ((7 |-> (z:A)) u)`; `1`; `8`; `7`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_EX; holds; HOLDS_AND] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  EQ_TAC THEN
  (DISCH_THEN(LABEL_TAC "H") THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  USE_THEN "H" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "ap" (fun th -> MP_TAC(SPECL [`z:A`; `uu:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    ASM_REWRITE_TAC[th] THEN ASM_REWRITE_TAC[GSYM th])));;

let subim_form = new_definition
  `subim_form =
     !! 7 ((7 %% 6) --> ?? 8 ((8 %% 0) && apply_form 1 8 7))`;;

let HOLDS_SUBIM_FORM = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u subim_form <=>
             !z. z IN D
                 ==> E z (u 6)
                     ==> ?uu. uu IN D /\ E uu (u 0) /\
                              eapply D E (u 1) uu z)`,
  REWRITE_TAC[subim_form] THEN
  MATCH_ACCEPT_TAC HOLDS_SUBIM_SLOTS);;

let HOLDS_POWENUM_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (?? 3 ((3 %% 2) &&
                 ?? 4 (fun_form 4 && (domain_form 4 3 &&
                   ((!! 5 (!! 6 (apply_form 4 5 6 --> subim_form))) &&
                    (!! 6 (subim_form -->
                           ?? 5 (apply_form 4 5 6)))))))) <=>
             ?M. M IN D /\ E M (v 2) /\
                 ?f. f IN D /\ eisfun D E f /\ edomain D E f M /\
                     (!k. k IN D
                          ==> !w. w IN D
                                  ==> eapply D E f k w
                                      ==> !z. z IN D
                                              ==> E z w
                                                  ==> ?uu. uu IN D /\
                                                           E uu (v 0) /\
                                                           eapply D E
                                                             (v 1) uu z) /\
                     (!w. w IN D
                          ==> (!z. z IN D
                                   ==> E z w
                                       ==> ?uu. uu IN D /\
                                                E uu (v 0) /\
                                                eapply D E (v 1) uu z)
                              ==> ?k. k IN D /\ eapply D E f k w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f:A. M IN D /\ f IN D
      ==> (holds D E ((4 |-> f) ((3 |-> M) v)) (fun_form 4) <=>
           eisfun D (E:A->A->bool) f)`
  (LABEL_TAC "fn") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (f:A)) ((3 |-> (M:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (f:A)) ((3 |-> (M:A)) v)`; `4`] HOLDS_FUN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f:A. M IN D /\ f IN D
      ==> (holds D E ((4 |-> f) ((3 |-> M) v)) (domain_form 4 3) <=>
           edomain D (E:A->A->bool) f M)`
  (LABEL_TAC "dm") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (f:A)) ((3 |-> (M:A)) v))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (f:A)) ((3 |-> (M:A)) v)`; `4`; `3`]
      HOLDS_DOMAIN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f k w:A. M IN D /\ f IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((6 |-> w) ((5 |-> k) ((4 |-> f) ((3 |-> M) v))))
            (apply_form 4 5 6) <=>
           eapply D (E:A->A->bool) f k w)`
  (LABEL_TAC "apA") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (w:A)) ((5 |-> (k:A)) ((4 |-> (f:A))
        ((3 |-> (M:A)) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (w:A)) ((5 |-> (k:A)) ((4 |-> (f:A))
        ((3 |-> (M:A)) v)))`; `4`; `5`; `6`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f k w:A. M IN D /\ f IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((5 |-> k) ((6 |-> w) ((4 |-> f) ((3 |-> M) v))))
            (apply_form 4 5 6) <=>
           eapply D (E:A->A->bool) f k w)`
  (LABEL_TAC "apB") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((5 |-> (k:A)) ((6 |-> (w:A)) ((4 |-> (f:A))
        ((3 |-> (M:A)) v))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (k:A)) ((6 |-> (w:A)) ((4 |-> (f:A))
        ((3 |-> (M:A)) v)))`; `4`; `5`; `6`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f k w:A. M IN D /\ f IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((6 |-> w) ((5 |-> k) ((4 |-> f) ((3 |-> M) v))))
            subim_form <=>
           !z. z IN D
               ==> E z w
                   ==> ?uu. uu IN D /\ E uu (v 0) /\
                            eapply D (E:A->A->bool) (v 1) uu z)`
  (LABEL_TAC "sbA") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (w:A)) ((5 |-> (k:A)) ((4 |-> (f:A))
        ((3 |-> (M:A)) v)))`] HOLDS_SUBIM_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!M f w:A. M IN D /\ f IN D /\ w IN D
      ==> (holds D E
            ((6 |-> w) ((4 |-> f) ((3 |-> M) v))) subim_form <=>
