    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!M f:A. M IN D /\ f IN D
      ==> (((!a''. a'' IN D
                 ==> !a'''. a''' IN D
                          ==> holds D E
                              ((6 |-> a''') ((5 |-> a'') ((4 |-> f)
                                ((3 |-> M) v))))
                              (apply_form 4 5 6)
                              ==> holds D E
                                  ((6 |-> a''') ((5 |-> a'') ((4 |-> f)
                                    ((3 |-> M) v))))
                                  subim_form)) <=>
           (!k. k IN D
                ==> !w. w IN D
                        ==> eapply D (E:A->A->bool) f k w
                            ==> !z. z IN D
                                    ==> E z w
                                        ==> ?uu. uu IN D /\
                                                 E uu (v 0) /\
                                                 eapply D E (v 1) uu z))`
  (LABEL_TAC "bodyA") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THEN
    (DISCH_THEN(LABEL_TAC "H") THEN
     X_GEN_TAC `k:A` THEN DISCH_TAC THEN
     X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
     USE_THEN "H" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
