   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyA" (fun th -> MP_TAC(SPECL [`M:A`; `f:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyB" (fun th -> MP_TAC(SPECL [`M:A`; `f:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   ASM_REWRITE_TAC[]));;

let ESINGFUN_EXISTS = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN D /\ y IN D
        ==> ?f. f IN D /\ eisfun D E f /\
                (!u. u IN D ==> (eindom D E f u <=> u = x)) /\
                (!k w. k IN D /\ w IN D
                       ==> (eapply D E f k w <=> k = x /\ w = y))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?p0:A. eopair D (E:A->A->bool) x y p0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(p0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?f:A. epair D (E:A->A->bool) p0 p0 f`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `!z. (z:A) IN D ==> ((E:A->A->bool) z f <=> z = p0)`
  (LABEL_TAC "fch") THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w. (k:A) IN D /\ (w:A) IN D
          ==> (eapply D (E:A->A->bool) f k w <=> k = x /\ w = y)`
  (LABEL_TAC "vch") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) = p0` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_INJ];
      STRIP_TAC THEN EXISTS_TAC `p0:A` THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) = p0` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`x:A`; `y:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
        [`uu:A`; `ww:A`; `ww':A`; `zz:A`; `zz':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(zz:A) IN D /\ (zz':A) IN D`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(zz:A) = p0 /\ (zz':A) = p0`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[EOPAIR_INJ]];
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    REWRITE_TAC[eindom] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      ASM_MESON_TAC[];
      DISCH_THEN SUBST_ALL_TAC THEN EXISTS_TAC `y:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "vch" (fun th ->
        MP_TAC(SPECL [`x:A`; `y:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th])]]);;

(* ------------------------------------------------------------------------- *)
(* Small omega facts (empty and successor membership) and the pow-enum       *)
(* induction: for every h and j in omega there is an internal function on an *)
(* omega-element domain enumerating exactly the sets all of whose members    *)
(* are h-values at arguments below j. Base: the one-point function to the    *)
(* empty set; step: the doubling construction at vj = h(m) (or f unchanged   *)
(* when m is outside the domain of h).                                       *)
(* ------------------------------------------------------------------------- *)

let EOMEGA_EMPTY = prove
 (`!D (E:A->A->bool) om e.
        model D E ZF_AX /\ eomega D E om /\ eempty D E e
        ==> E e om`,
  REWRITE_TAC[eomega; einductive] THEN
  MESON_TAC[EEMPTY_UNIQUE]);;

let EOMEGA_SUC = prove
 (`!D (E:A->A->bool) om m sm.
        model D E ZF_AX /\ eomega D E om /\ m IN D /\ E m om /\
        esuc D E m sm
        ==> E sm om`,
  REWRITE_TAC[eomega; einductive] THEN
  MESON_TAC[ESUC_UNIQUE]);;

let POWENUM_ALL = prove
 (`!D (E:A->A->bool) om h j.
        model D E ZF_AX /\ eomega D E om /\ h IN D /\ eisfun D E h /\
        j IN D /\ E j om
        ==> ?M f. M IN D /\ E M om /\ f IN D /\ eisfun D E f /\
                  edomain D E f M /\
                  (!k w. k IN D /\ w IN D
                         ==> eapply D E f k w
                             ==> !z. z IN D
                                     ==> E z w
                                         ==> ?u. u IN D /\ E u j /\
                                                 eapply D E h u z) /\
                  (!w. w IN D
                       ==> (!z. z IN D
                                ==> E z w
                                    ==> ?u. u IN D /\ E u j /\
                                            eapply D E h u z)
                           ==> ?k. k IN D /\ eapply D E f k w)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((2 |-> (om:A)) ((1 |-> (h:A)) v0))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n. (n:A) IN D
        ==> (holds D E ((0 |-> n) ((2 |-> om) ((1 |-> h) v0)))
              (?? 3 ((3 %% 2) &&
                 ?? 4 (fun_form 4 && (domain_form 4 3 &&
                   ((!! 5 (!! 6 (apply_form 4 5 6 --> subim_form))) &&
                    (!! 6 (subim_form -->
                           ?? 5 (apply_form 4 5 6)))))))) <=>
             ?M. M IN D /\ E M om /\
                 ?f. f IN D /\ eisfun D E f /\ edomain D E f M /\
                     (!k. k IN D
                          ==> !w. w IN D
                                  ==> eapply D (E:A->A->bool) f k w
                                      ==> !z. z IN D
                                              ==> E z w
                                                  ==> ?uu. uu IN D /\
                                                           E uu n /\
                                                           eapply D E
                                                             h uu z) /\
                     (!w. w IN D
                          ==> (!z. z IN D
                                   ==> E z w
                                       ==> ?uu. uu IN D /\
                                                E uu n /\
                                                eapply D E h uu z)
                              ==> ?k. k IN D /\ eapply D E f k w))`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (n:A)) ((2 |-> (om:A)) ((1 |-> (h:A)) v0))`]
      HOLDS_POWENUM_SLOTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `?? 3 ((3 %% 2) &&
       ?? 4 (fun_form 4 && (domain_form 4 3 &&
         ((!! 5 (!! 6 (apply_form 4 5 6 --> subim_form))) &&
          (!! 6 (subim_form --> ?? 5 (apply_form 4 5 6)))))))`;
    `0`; `(2 |-> (om:A)) ((1 |-> (h:A)) v0)`]
    EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `e:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `?sd:A. esuc D (E:A->A->bool) e sd`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(sd:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) e om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) sd om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `e:A`]
        ESINGFUN_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@f. h1 h2 dmc vch" THEN
      EXISTS_TAC `sd:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[] THEN
      REPEAT CONJ_TAC THENL
       [REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `u:A` THEN DISCH_TAC THEN
        USE_THEN "dmc" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_MESON_TAC[ESUC_E; eempty];
        X_GEN_TAC `k:A` THEN DISCH_TAC THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        SUBGOAL_THEN `(k:A) = e /\ (w:A) = e`
        (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[eempty];
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        SUBGOAL_THEN `(w:A) = e` SUBST_ALL_TAC THENL
         [SUBGOAL_THEN `eempty D (E:A->A->bool) w` ASSUME_TAC THENL
           [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
            ASM_MESON_TAC[eempty];
            ASM_MESON_TAC[EEMPTY_UNIQUE]];
          ALL_TAC] THEN
        EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `sm:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "holds")) (concl th))) THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  INTRO_TAC "@M. h3 h4 @f. h5 h6 h7 iha ihb" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) M` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  ASM_CASES_TAC `?vj. (vj:A) IN D /\ eapply D (E:A->A->bool) h m vj`
  THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `vj:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `?MM:A. MM IN D /\ eadd D (E:A->A->bool) M M MM`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) MM om` ASSUME_TAC THENL
     [ASM_MESON_TAC[EADD_OMEGA]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `M:A`;
      `MM:A`; `vj:A`] ESHIFTFUN_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@f2. h8 h9 h10 vch2" THEN
    EXISTS_TAC `MM:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `f2:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `k:A` THEN DISCH_TAC THEN
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      USE_THEN "vch2" (fun th ->
        MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun t -> can (find_term (fun tm -> is_const tm &&
            fst(dest_const tm) = "eapply")) (concl t) &&
            can (find_term ((=) `f2:A`)) (concl t)))) THEN
      STRIP_TAC THENL
       [USE_THEN "iha" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
          `eapply D (E:A->A->bool) f k w`))) THEN
        DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[ESUC_E];
        SUBGOAL_THEN `(E:A->A->bool) z w0 \/ (z:A) = vj` MP_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        STRIP_TAC THENL
         [USE_THEN "iha" (fun th -> MP_TAC(SPEC `i:A` th)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(MP_TAC o SPEC `w0:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
            `eapply D (E:A->A->bool) f i w0`))) THEN
          DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
          EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[ESUC_E];
          EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[ESUC_E]]];
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_THEN(LABEL_TAC "sbw") THEN
  ASM_CASES_TAC `(E:A->A->bool) vj w` THENL
   [SUBGOAL_THEN `?sv:A. epair D (E:A->A->bool) vj vj sv`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(sv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?w0:A. ediff D (E:A->A->bool) w sv w0`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!z. (z:A) IN D ==> ((E:A->A->bool) z w0 <=> E z w /\ ~(z = vj))`
    (LABEL_TAC "w0c") THENL
     [ASM_MESON_TAC[ediff; epair]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!z. (z:A) IN D ==> E z w0
          ==> ?uu. uu IN D /\ (E:A->A->bool) uu m /\ eapply D E h uu z`
    ASSUME_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z w /\ ~((z:A) = vj)`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      USE_THEN "sbw" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(E:A->A->bool) uu m \/ (uu:A) = m` MP_TAC THENL
       [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[EAPPLY_UNIQUE];
      ALL_TAC] THEN
    USE_THEN "ihb" (fun th -> MP_TAC(SPEC `w0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) i M` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `?k:A. k IN D /\ eadd D (E:A->A->bool) M i k`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EADD_EXISTS; EORDINAL_MEMBER]; ALL_TAC] THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "vch2" (fun th -> MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISJ2_TAC THEN
    MAP_EVERY EXISTS_TAC [`i:A`; `w0:A`] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "w0c" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_CASES_TAC `(z:A) = vj` THEN ASM_REWRITE_TAC[];
    SUBGOAL_THEN
     `!z. (z:A) IN D ==> E z w
          ==> ?uu. uu IN D /\ (E:A->A->bool) uu m /\ eapply D E h uu z`
    ASSUME_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      USE_THEN "sbw" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(E:A->A->bool) uu m \/ (uu:A) = m` MP_TAC THENL
       [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[EAPPLY_UNIQUE];
      ALL_TAC] THEN
    USE_THEN "ihb" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "vch2" (fun th -> MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[edomain; eindom]]];
    EXISTS_TAC `M:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `k:A` THEN DISCH_TAC THEN
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      USE_THEN "iha" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) f k w`))) THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ESUC_E];
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN
      DISCH_THEN(LABEL_TAC "sbw") THEN
      USE_THEN "ihb" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL
       [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        USE_THEN "sbw" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `uu:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `uu:A` THEN ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `(E:A->A->bool) uu m \/ (uu:A) = m` MP_TAC THENL
         [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
        STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[];
        DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[]]]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `j:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `j:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `M:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `f:A` STRIP_ASSUME_TAC)))) THEN
  MAP_EVERY EXISTS_TAC [`M:A`; `f:A`] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Object formula for the V-hierarchy stage relation (recapp-pinned rec_form *)
(* of vstep_form), the successor-stage characterization (members of V(suc m) *)
(* are exactly the subsets of V(m)), empty-stage and empty-function helpers, *)
(* and the slots characterization of the combined Phi induction property     *)
(* "V(n) is constructible and its members are enumerated by a function on an *)
(* omega-element domain" (slots 0 = n, 8 = omega).                           *)
(* ------------------------------------------------------------------------- *)

let hfstage_form = new_definition
  `hfstage_form i j = recapp_form (rec_form vstep_form 2) i j`;;

let HOLDS_HFSTAGE_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (hfstage_form i j) <=>
             ehfstage D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[hfstage_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `rec_form vstep_form 2`; `i:num`; `j:num`]
    HOLDS_RECAPP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (v:num->A) j) ((2 |-> v i) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `vstep_form`; `2`; `(v:num->A) i`; `(v:num->A) j`]
    HOLDS_REC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ARITH_TAC;
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(REWRITE_RULE[SUBSET] FV_VSTEP_FORM) THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
      ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
    `(v:num->A) j`; `v:num->A`] EHFSTAGE_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let EHFSTAGE_SUC_CHAR = prove
 (`!D (E:A->A->bool) m sm ym ysm.
        model D E ZF_AX /\ eordinal D E m /\ esuc D E m sm /\
        ym IN D /\ ehfstage D E m ym /\
        ysm IN D /\ ehfstage D E sm ysm
        ==> !w. w IN D ==> (E w ysm <=> esubset D E w ym)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(sm:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sm` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`; `ysm:A`]
    EHFSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `yb:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) b m \/ (b:A) = m` MP_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    STRIP_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z yb` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `m:A`;
        `yb:A`; `ym:A`; `z:A`] EHFSTAGE_MONO) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[EORDINAL_MEMBER];
        DISCH_THEN ACCEPT_TAC];
      SUBGOAL_THEN `(yb:A) = ym` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[EHFSTAGE_UNIQUE]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`m:A`; `ym:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ESUC_E]]);;

let EHFSTAGE_EMPTY = prove
 (`!D (E:A->A->bool) e y.
        model D E ZF_AX /\ eempty D E e /\ y IN D /\
        ehfstage D E e y
        ==> eempty D E y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `y:A`]
    EHFSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN REWRITE_TAC[eempty] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[eempty]);;

let EEMPTYFUN = prove
 (`!D (E:A->A->bool) e.
        model D E ZF_AX /\ eempty D E e
        ==> eisfun D E e /\ edomain D E e e /\
            (!k w. k IN D /\ w IN D ==> ~(eapply D E e k w))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w. (k:A) IN D /\ (w:A) IN D ==> ~(eapply D (E:A->A->bool) e k w)`
  ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN
    ASM_MESON_TAC[eempty; EOPAIR_IN];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[eempty; EOPAIR_IN];
    REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[eindom] THEN ASM_MESON_TAC[eempty]]);;

let HOLDS_HFCON_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (?? 4 (hfstage_form 0 4 && (lmem_at 4 &&
                 ?? 5 ((5 %% 8) &&
                   ?? 6 (fun_form 6 && (domain_form 6 5 &&
                     ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
                      (!! 9 ((9 %% 4) -->
                             ?? 7 (apply_form 6 7 9)))))))))) <=>
             ?y. y IN D /\ ehfstage D E (v 0) y /\ elmem D E y /\
                 ?M. M IN D /\ E M (v 8) /\
                     ?hh. hh IN D /\ eisfun D E hh /\
                          edomain D E hh M /\
                          (!k. k IN D
                               ==> !w. w IN D
                                       ==> eapply D E hh k w
                                           ==> E w y) /\
                          (!w. w IN D
                               ==> E w y
                                   ==> ?k. k IN D /\
                                           eapply D E hh k w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v) (hfstage_form 0 4) <=>
           ehfstage D (E:A->A->bool) (v 0) y)`
  (LABEL_TAC "hf") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
      `0`; `4`] HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v) (lmem_at 4) <=>
           elmem D (E:A->A->bool) y)`
  (LABEL_TAC "lm") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
      `4`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> (holds D E ((6 |-> hh) ((5 |-> M) ((4 |-> y) v)))
             (fun_form 6) <=>
           eisfun D (E:A->A->bool) hh)`
  (LABEL_TAC "fn") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v))`; `6`]
      HOLDS_FUN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> (holds D E ((6 |-> hh) ((5 |-> M) ((4 |-> y) v)))
             (domain_form 6 5) <=>
           edomain D (E:A->A->bool) hh M)`
  (LABEL_TAC "dm") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v))`; `6`; `5`]
      HOLDS_DOMAIN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh k w:A. y IN D /\ M IN D /\ hh IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((9 |-> w) ((7 |-> k) ((6 |-> hh) ((5 |-> M)
              ((4 |-> y) v)))))
            (apply_form 6 7 9) <=>
           eapply D (E:A->A->bool) hh k w)`
  (LABEL_TAC "apA") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((9 |-> (w:A)) ((7 |-> (k:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(9 |-> (w:A)) ((7 |-> (k:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v))))`; `6`; `7`; `9`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh k w:A. y IN D /\ M IN D /\ hh IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((7 |-> k) ((9 |-> w) ((6 |-> hh) ((5 |-> M)
              ((4 |-> y) v)))))
            (apply_form 6 7 9) <=>
           eapply D (E:A->A->bool) hh k w)`
  (LABEL_TAC "apB") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((7 |-> (k:A)) ((9 |-> (w:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (k:A)) ((9 |-> (w:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v))))`; `6`; `7`; `9`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> ((!a'''. a''' IN D
                   ==> !a''''. a'''' IN D
                               ==> holds D E
                                   ((9 |-> a'''') ((7 |-> a''')
                                     ((6 |-> hh) ((5 |-> M)
                                       ((4 |-> y) v)))))
                                   (apply_form 6 7 9)
                                   ==> E a'''' y) <=>
           (!k. k IN D
                ==> !w. w IN D
                        ==> eapply D (E:A->A->bool) hh k w
                            ==> E w y))`
  (LABEL_TAC "bodyA") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THEN
    (DISCH_THEN(LABEL_TAC "H") THEN
     X_GEN_TAC `k:A` THEN DISCH_TAC THEN
     X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
     USE_THEN "H" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     USE_THEN "apA" (fun th ->
       MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`; `k:A`; `w:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[] THEN SIMP_TAC[] THEN
     USE_THEN "apA" (fun th ->
       MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`; `k:A`; `w:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
     ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
