    (DISCH_THEN(LABEL_TAC "H") THEN
     X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
     USE_THEN "H" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
     EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
     USE_THEN "apB" (fun th ->
       MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`; `k:A`; `w:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th ->
       ASM_REWRITE_TAC[th] THEN ASM_REWRITE_TAC[GSYM th]));
    ALL_TAC] THEN
  EQ_TAC THEN
  (INTRO_TAC "@y. h1 + + @M. h2 h3 @hh. h4 +" THEN
   USE_THEN "fn" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "dm" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyA" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyB" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "hf" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "lm" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   DISCH_TAC THEN DISCH_TAC THEN DISCH_TAC THEN
   EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
   USE_THEN "hf" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "lm" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   ASM_REWRITE_TAC[] THEN
   EXISTS_TAC `M:A` THEN ASM_REWRITE_TAC[] THEN
   EXISTS_TAC `hh:A` THEN ASM_REWRITE_TAC[] THEN
   USE_THEN "fn" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "dm" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyA" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   USE_THEN "bodyB" (fun th ->
     MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`] th)) THEN
   ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   ASM_REWRITE_TAC[]));;

(* ------------------------------------------------------------------------- *)
(* HF SUBSET L: the Phi induction. Subsets of a constructible stage with an  *)
(* enumeration are constructible (via the redirect/range machinery); the     *)
(* successor stage is then itself constructible because it coincides with    *)
(* the internal L-power set; POWENUM_ALL supplies the next enumeration.      *)
(* Hence every V-stage below omega is in L, and by transitivity every member *)
(* of the hereditarily finite set is constructible.                          *)
(* ------------------------------------------------------------------------- *)

let LCLASS_SUBSETS = prove
 (`!D (E:A->A->bool) om ym M hh.
        model D E ZF_AX /\ eomega D E om /\
        ym IN lclass D E /\ M IN D /\ E M om /\
        hh IN D /\ eisfun D E hh /\ edomain D E hh M /\
        (!k w. k IN D /\ w IN D ==> eapply D E hh k w ==> E w ym) /\
        (!w. w IN D ==> E w ym ==> ?k. k IN D /\ eapply D E hh k w)
        ==> !w. w IN D ==> esubset D E w ym ==> w IN lclass D E`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `?d0:A. d0 IN D /\ (E:A->A->bool) d0 w` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `M:A`;
      `hh:A`; `w:A`; `d0:A`] LCLASS_SUBSET_RAN) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:A`; `q:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[LCLASS_MEMBER];
      X_GEN_TAC `q:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    SUBGOAL_THEN `eempty D (E:A->A->bool) w` ASSUME_TAC THENL
     [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EORDINAL_EEMPTY; ELMEM_ORDINAL]]);;

let LCLASS_STAGE_POW = prove
 (`!D (E:A->A->bool) ym ysm.
        model D E ZF_AX /\ ym IN lclass D E /\ ysm IN D /\
        (!w. w IN D ==> (E w ysm <=> esubset D E w ym)) /\
        (!w. w IN D ==> esubset D E w ym ==> w IN lclass D E)
        ==> ysm IN lclass D E`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 h3 ych sbl" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_POWERSET) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ym:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `pp:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ppc"))) THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(ysm:A) = pp` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "ych" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [USE_THEN "sbl" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    USE_THEN "ppc" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(w':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
    ASM_MESON_TAC[esubset];
    DISCH_TAC THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    USE_THEN "ppc" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun t -> concl t = `(E:A->A->bool) z pp`))) THEN
    DISCH_THEN(LABEL_TAC "zc") THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(w':A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    USE_THEN "zc" (fun th -> MP_TAC(SPEC `w':A` th)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let LCLASS_EHFSTAGE = prove
 (`!D (E:A->A->bool) om n y.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y
        ==> y IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((8 |-> (om:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn. (nn:A) IN D
     ==> (holds D (E:A->A->bool) ((0 |-> nn) ((8 |-> om) v0))
           (?? 4 (hfstage_form 0 4 && (lmem_at 4 &&
              ?? 5 ((5 %% 8) &&
                ?? 6 (fun_form 6 && (domain_form 6 5 &&
                  ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
                   (!! 9 ((9 %% 4) -->
                          ?? 7 (apply_form 6 7 9)))))))))) <=>
          (?yy. yy IN D /\ ehfstage D E nn yy /\ elmem D E yy /\
                (?M. M IN D /\ E M om /\
                     (?hh. hh IN D /\ eisfun D E hh /\
                           edomain D E hh M /\
                           (!k. k IN D
                                ==> (!w. w IN D
                                         ==> eapply D E hh k w
                                             ==> E w yy)) /\
                           (!w. w IN D
                                ==> E w yy
                                    ==> (?k. k IN D /\
                                             eapply D E hh k w))))))`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `nn:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (nn:A)) ((8 |-> (om:A)) v0)`] HOLDS_HFCON_SLOTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `?? 4 (hfstage_form 0 4 && (lmem_at 4 &&
       ?? 5 ((5 %% 8) &&
         ?? 6 (fun_form 6 && (domain_form 6 5 &&
           ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
            (!! 9 ((9 %% 4) -->
                   ?? 7 (apply_form 6 7 9)))))))))`;
    `0`; `(8 |-> (om:A)) v0`]
    EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `e:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) e om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?y0:A. y0 IN D /\ ehfstage D (E:A->A->bool) e y0`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `eempty D (E:A->A->bool) y0` ASSUME_TAC THENL
       [ASM_MESON_TAC[EHFSTAGE_EMPTY]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`]
        EEMPTYFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THEN
      EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC ELMEM_ORDINAL THEN CONJ_TAC THENL
         [FIRST_ASSUM ACCEPT_TAC;
          MATCH_MP_TAC EORDINAL_EEMPTY THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MAP_EVERY X_GEN_TAC [`k:A`] THEN DISCH_TAC THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        ASM_MESON_TAC[];
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        ASM_MESON_TAC[eempty]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `sm:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "holds")) (concl th))) THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  INTRO_TAC "@ym. h1 h2 h3 @M. h4 h5 @hh. h6 h7 h8 iha ihb" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sm` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ysm:A. ysm IN D /\ ehfstage D (E:A->A->bool) sm ysm`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(ym:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> ((E:A->A->bool) w ysm <=> esubset D E w ym)`
  (LABEL_TAC "sch") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `sm:A`;
      `ym:A`; `ysm:A`] EHFSTAGE_SUC_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> esubset D (E:A->A->bool) w ym
        ==> w IN lclass D E`
  (LABEL_TAC "sbl") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ym:A`;
      `M:A`; `hh:A`] LCLASS_SUBSETS) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN
      DISCH_TAC THEN
      USE_THEN "iha" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) hh k w`))) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ysm:A) IN lclass D E` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ym:A`; `ysm:A`]
      LCLASS_STAGE_POW) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hh:A`; `M:A`]
    POWENUM_ALL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@M2 f. h9 h10 h11 h12 h13 pea peb" THEN
  EXISTS_TAC `ysm:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  EXISTS_TAC `M2:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `k:A` THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w ym` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "pea" (fun th -> MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) f k w`))) THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "iha" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) hh u z`))) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "sch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w ym` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "peb" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      USE_THEN "ihb" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[edomain; eindom];
      DISCH_THEN ACCEPT_TAC]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `n:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `yy:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(yy:A) = y` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_UNIQUE]; ALL_TAC] THEN
  ASM_MESON_TAC[IN_LCLASS]);;

let LCLASS_EHFSET = prove
 (`!D (E:A->A->bool) om hf x.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        x IN D /\ E x hf
        ==> x IN lclass D E`,
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ehfset] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "ehfset")) (concl th))) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (MP_TAC o SPEC `x:A`)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
      check (fun t -> concl t = `(E:A->A->bool) x hf`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `yst:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(yst:A) IN lclass D E` ASSUME_TAC THENL
   [MATCH_MP_TAC LCLASS_EHFSTAGE THEN
    MAP_EVERY EXISTS_TAC [`om:A`; `n:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[LCLASS_MEMBER]);;

(* ------------------------------------------------------------------------- *)
(* Preparation for the satisfaction-layer absoluteness: cross products       *)
(* are absolute and L is closed under them; V-stages are transitive sets; an *)
(* ordinal lying in the V-stage at n is below n (internal ordinal            *)
(* induction), so the V-stage index of a code bounds every variable index    *)
(* reachable inside it; components of ordered pairs stay inside a V-stage.   *)
(* ------------------------------------------------------------------------- *)

let ECROSS_LCLASS = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ a IN lclass D E /\ b IN lclass D E /\
        c IN lclass D E
        ==> (ecross (lclass D E) E a b c <=> ecross D E a b c)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ecross] THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN EQ_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THENL
   [ASM_CASES_TAC `(E:A->A->bool) z c` THENL
     [SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?u w. (u:A) IN lclass D E /\ (w:A) IN lclass D E /\
              (E:A->A->bool) u a /\ E w b /\
              eopair (lclass D E) E u w z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[EOPAIR_LCLASS; LCLASS_IN_D];
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN
       `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_EOPAIR]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z c` MP_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o check (fun th ->
          is_forall(concl th))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
        ASM_MESON_TAC[EOPAIR_LCLASS; LCLASS_IN_D];
        ASM_REWRITE_TAC[]]];
    ASM_CASES_TAC `(E:A->A->bool) z c` THENL
     [SUBGOAL_THEN
       `?u w. (u:A) IN D /\ (w:A) IN D /\ (E:A->A->bool) u a /\
              E w b /\ eopair D E u w z`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN
       `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_IN_D]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
      ASM_MESON_TAC[EOPAIR_LCLASS; LCLASS_IN_D];
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) z c` MP_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o check (fun th ->
          is_forall(concl th))) THEN
        ANTS_TAC THENL
         [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`u:A`; `w:A`] THEN
        ASM_MESON_TAC[EOPAIR_LCLASS; LCLASS_IN_D];
        ASM_REWRITE_TAC[]]]]);;

let LCLASS_ECROSS = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ a IN lclass D E /\ b IN lclass D E /\
        ecross D E a b c
        ==> c IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?c'. ecross (lclass D E) (E:A->A->bool) a b c'`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c':A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `ecross D (E:A->A->bool) a b c'` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECROSS_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) = c'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[ECROSS_UNIQUE]);;

let EHFSTAGE_TRANS_E = prove
 (`!D (E:A->A->bool) n y u w.
        model D E ZF_AX /\ eordinal D E n /\ y IN D /\
        ehfstage D E n y /\ u IN D /\ w IN D /\ E u w /\ E w y
        ==> E u y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `y:A`]
    EHFSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ch") THEN
  USE_THEN "ch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
      check (fun t -> concl t = `(E:A->A->bool) w y`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `yb:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) u yb` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `n:A`;
    `yb:A`; `y:A`; `u:A`] EHFSTAGE_MONO) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_MEMBER];
    DISCH_THEN ACCEPT_TAC]);;

let HOLDS_ORDVST = prove
 (`!D (E:A->A->bool) v0 mm.
      model D E ZF_AX /\ valuation D v0 /\ (mm:A) IN D
      ==> (holds D E ((0 |-> mm) v0)
            (!! 4 (!! 5 ((ordinal_form 4 &&
               (hfstage_form 4 5 && (0 %% 5))) --> (0 %% 4)))) <=>
           !nn. nn IN D
                ==> !yy. yy IN D
                         ==> eordinal D (E:A->A->bool) nn /\
                             ehfstage D E nn yy /\ E mm yy
                             ==> E mm nn)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (mm:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn yy. (nn:A) IN D /\ (yy:A) IN D
      ==> (holds D E ((5 |-> yy) ((4 |-> nn) ((0 |-> mm) v0)))
             (ordinal_form 4) <=>
           eordinal D (E:A->A->bool) nn) /\
          (holds D E ((5 |-> yy) ((4 |-> nn) ((0 |-> mm) v0)))
             (hfstage_form 4 5) <=>
           ehfstage D (E:A->A->bool) nn yy)`
  (LABEL_TAC "at") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((5 |-> (yy:A)) ((4 |-> (nn:A))
        ((0 |-> (mm:A)) v0)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (yy:A)) ((4 |-> (nn:A)) ((0 |-> (mm:A)) v0))`;
        `4`] HOLDS_ORDINAL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (yy:A)) ((4 |-> (nn:A)) ((0 |-> (mm:A)) v0))`;
        `4`; `5`] HOLDS_HFSTAGE_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[]);;

let ORDINALS_IN_VSTAGE = prove
 (`!D (E:A->A->bool) m n y.
        model D E ZF_AX /\ eordinal D E m /\ eordinal D E n /\
        y IN D /\ ehfstage D E n y /\ E m y
        ==> E m n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a. eordinal D (E:A->A->bool) a
        ==> holds D E ((0 |-> a) v0)
              (!! 4 (!! 5 ((ordinal_form 4 &&
                 (hfstage_form 4 5 && (0 %% 5))) --> (0 %% 4))))`
  (LABEL_TAC "main") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `!! 4 (!! 5 ((ordinal_form 4 &&
         (hfstage_form 4 5 && (0 %% 5))) --> (0 %% 4)))`;
      `0`; `v0:num->A`] EORDINAL_INDUCT) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `a:A`]
      HOLDS_ORDVST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `nn:A` THEN DISCH_TAC THEN
    X_GEN_TAC `yy:A` THEN DISCH_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nn:A`; `yy:A`]
      EHFSTAGE_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun t -> concl t = `(E:A->A->bool) a yy`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `yb:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) a b` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) k yb` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      SUBGOAL_THEN
       `holds D E ((0 |-> (k:A)) v0)
          (!! 4 (!! 5 ((ordinal_form 4 &&
             (hfstage_form 4 5 && (0 %% 5))) --> (0 %% 4))))`
      MP_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`;
        `k:A`] HOLDS_ORDVST) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(MP_TAC o SPEC `b:A`) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `yb:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
      EORDINAL_SUBSET_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset; EORDINAL_IN];
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  USE_THEN "main" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`; `m:A`]
    HOLDS_ORDVST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let EOPAIR_VSTAGE = prove
 (`!D (E:A->A->bool) n y a b p.
        model D E ZF_AX /\ eordinal D E n /\ y IN D /\
        ehfstage D E n y /\ a IN D /\ b IN D /\ p IN D /\
        eopair D E a b p /\ E p y
        ==> E a y /\ E b y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "eopair")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `pr:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(s:A) IN D /\ (pr:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s p /\ (E:A->A->bool) pr p`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s y /\ (E:A->A->bool) pr y`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_TRANS_E]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a s /\ (E:A->A->bool) b pr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  ASM_MESON_TAC[EHFSTAGE_TRANS_E]);;

(* ------------------------------------------------------------------------- *)
(* Satisfaction stages are cumulative (verdicts transfer to any later stage  *)
(* since esatbody is positive in the verdict graph -- no induction needed),  *)
(* and the object-formula machinery for the assignment-agreement induction:  *)
(* agree_form (two assignments agree at indices below slot 13), agrbody_form *)
(* (any verdict in the stage at slot 5 for a code in the V-stage at slot 12  *)
(* survives replacing its assignment by one in slot-14-funs agreeing below   *)
(* the bound), and their HOLDS characterizations, including the property     *)
(* !!5 (rec_form satstep_form 4 --> agrbody_form) for omega-induction at 4.  *)
(* ------------------------------------------------------------------------- *)

let EVERDICT_TRANSFER_F = prove
 (`!D (E:A->A->bool) x b m rb rm c s bit.
        model D E zfw_ax /\ eordinal D E m /\ b IN D /\ E b m /\
        (!w. w IN D
             ==> (E w rb <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' b /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        (!w. w IN D
             ==> (E w rm <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' m /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        everdict D E c s bit rb
        ==> everdict D E c s bit rm`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `rb:A`;
    `c:A`; `s:A`; `bit:A`] EVERDICT_STAGE_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y:A`
    (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `m:A`; `rm:A`;
    `c:A`; `s:A`; `bit:A`; `b':A`; `y:A`; `cs:A`; `w:A`]
    EVERDICT_INTRO_F) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[eordinal; etransitive; esubset; EORDINAL_IN]);;

let EVERDICT_TRANSFER = prove
 (`!D (E:A->A->bool) x b m rb rm c s bit.
        model D E ZF_AX /\ eordinal D E m /\ b IN D /\ E b m /\
        (!w. w IN D
             ==> (E w rb <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' b /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        (!w. w IN D
             ==> (E w rm <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' m /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        everdict D E c s bit rb
        ==> everdict D E c s bit rm`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW EVERDICT_TRANSFER_F));;

let ESATBODY_TRANSFER_F = prove
 (`!D (E:A->A->bool) x b m rb rm p.
        model D E zfw_ax /\ eordinal D E m /\ b IN D /\ E b m /\
        (!w. w IN D
             ==> (E w rb <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' b /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        (!w. w IN D
             ==> (E w rm <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' m /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        esatbody D E x rb p
        ==> esatbody D E x rm p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!cc ss bt. everdict D (E:A->A->bool) cc ss bt rb
               ==> everdict D E cc ss bt rm`
  (LABEL_TAC "tr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `m:A`;
      `rb:A`; `rm:A`; `cc:A`; `ss:A`; `bt:A`] EVERDICT_TRANSFER_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatbody] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "esatbody")) (concl th))) THEN
  REWRITE_TAC[esatbody] THEN
  DISCH_THEN(X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `bt:A`
    (X_CHOOSE_THEN `cc:A` (X_CHOOSE_THEN `ss:A`
      STRIP_ASSUME_TAC)))) THEN
  MAP_EVERY EXISTS_TAC [`cs:A`; `bt:A`; `cc:A`; `ss:A`] THEN
  ASM_REWRITE_TAC[] THENL
   [MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatimp] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatimp")) (concl th))) THEN
    REWRITE_TAC[esatimp] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `c2:A`
        (X_CHOOSE_THEN `zr0:A` (X_CHOOSE_THEN `on1:A`
          STRIP_ASSUME_TAC))))) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`c1:A`; `c2:A`; `zr0:A`; `on1:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[] THEN
    DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatall] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatall")) (concl th))) THEN
    REWRITE_TAC[esatall] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `c1:A`
        (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
          STRIP_ASSUME_TAC))))) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `c1:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let ESATBODY_TRANSFER = prove
 (`!D (E:A->A->bool) x b m rb rm p.
        model D E ZF_AX /\ eordinal D E m /\ b IN D /\ E b m /\
        (!w. w IN D
             ==> (E w rb <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' b /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        (!w. w IN D
             ==> (E w rm <=>
                  ?b' y. b' IN D /\ y IN D /\ E b' m /\
                         esatstage D E x b' y /\ eopair D E b' y w)) /\
        esatbody D E x rb p
        ==> esatbody D E x rm p`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATBODY_TRANSFER_F));;

let ESATSTAGE_CUMUL_F = prove
 (`!D (E:A->A->bool) x b m yb ym p.
        model D E zfw_ax /\ x IN D /\ eordinal D E b /\
        eordinal D E m /\ E b m /\ yb IN D /\ ym IN D /\
        esatstage D E x b yb /\ esatstage D E x m ym /\
        p IN D /\ E p yb
        ==> E p ym`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `yb:A`]
    ESATSTAGE_MEMBER_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2b rb. h1 h2 rbc ybc" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `m:A`; `ym:A`]
    ESATSTAGE_MEMBER_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2m rm. h3 h4 rmc ymc" THEN
  SUBGOAL_THEN `(u2m:A) = u2b` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_UNIQUE_F]; ALL_TAC] THEN
  USE_THEN "ybc" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
      check (fun t -> concl t = `(E:A->A->bool) p yb`))) THEN
  STRIP_TAC THEN
  USE_THEN "ymc" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `m:A`;
    `rb:A`; `rm:A`; `p:A`] ESATBODY_TRANSFER_F) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "rbc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "rmc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC; DISCH_THEN ACCEPT_TAC]]);;

let ESATSTAGE_CUMUL = prove
 (`!D (E:A->A->bool) x b m yb ym p.
        model D E ZF_AX /\ x IN D /\ eordinal D E b /\
        eordinal D E m /\ E b m /\ yb IN D /\ ym IN D /\
        esatstage D E x b yb /\ esatstage D E x m ym /\
        p IN D /\ E p yb
        ==> E p ym`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATSTAGE_CUMUL_F));;

let agree_form = new_definition
  `agree_form =
     !! 21 (!! 22 ((21 %% 13) -->
        (apply_form 16 21 22 <-> apply_form 17 21 22)))`;;

let HOLDS_AGREE_FORM = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u agree_form <=>
             !i. i IN D
                 ==> !w. w IN D
                         ==> E i (u 13)
                             ==> (eapply D E (u 16) i w <=>
                                  eapply D E (u 17) i w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i w:A. i IN D /\ w IN D
      ==> (holds D E ((22 |-> w) ((21 |-> i) u))
             (apply_form 16 21 22) <=>
           eapply D (E:A->A->bool) (u 16) i w) /\
          (holds D E ((22 |-> w) ((21 |-> i) u))
             (apply_form 17 21 22) <=>
           eapply D (E:A->A->bool) (u 17) i w)`
  (LABEL_TAC "ap") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((22 |-> (w:A)) ((21 |-> (i:A)) u))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (w:A)) ((21 |-> (i:A)) u)`; `16`; `21`; `22`]
        HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (w:A)) ((21 |-> (i:A)) u)`; `17`; `21`; `22`]
        HOLDS_APPLY_FORM)] THEN
    (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[agree_form; holds; HOLDS_IFF] THEN
  ASM_SIMP_TAC[] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[]);;

let agrbody_form = new_definition
  `agrbody_form =
     !! 15 (!! 16 (!! 17 (!! 18 (
       ((15 %% 12) && ((17 %% 14) && agree_form)) -->
       !! 19 (!! 20 ((opair_form 15 16 19 &&
                      (opair_form 19 18 20 && (20 %% 5))) -->
         ?? 23 (?? 24 (opair_form 15 17 23 &&
                       (opair_form 23 18 24 && (24 %% 5))))))))))`;;

let HOLDS_AGRBODY = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u agrbody_form <=>
             !c. c IN D
                 ==> !s1. s1 IN D
                          ==> !s2. s2 IN D
                                   ==> !b. b IN D
             ==> E c (u 12) /\ E s2 (u 14) /\
                 (!i. i IN D
                      ==> !w. w IN D
                              ==> E i (u 13)
                                  ==> (eapply D E s1 i w <=>
                                       eapply D E s2 i w))
                 ==> !cs1. cs1 IN D
                           ==> !p1. p1 IN D
                 ==> eopair D E c s1 cs1 /\ eopair D E cs1 b p1 /\
                     E p1 (u 5)
                     ==> ?cs2. cs2 IN D /\
                               ?p2. p2 IN D /\
                                    eopair D E c s2 cs2 /\
                                    eopair D E cs2 b p2 /\
                                    E p2 (u 5))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c s1 s2 b:A. c IN D /\ s1 IN D /\ s2 IN D /\ b IN D
      ==> (holds D E ((18 |-> b) ((17 |-> s2) ((16 |-> s1)
             ((15 |-> c) u)))) agree_form <=>
           !i. i IN D
               ==> !w. w IN D
                       ==> E i (u 13)
                           ==> (eapply D (E:A->A->bool) s1 i w <=>
                                eapply D E s2 i w))`
  (LABEL_TAC "agC") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(18 |-> (b:A)) ((17 |-> (s2:A)) ((16 |-> (s1:A))
        ((15 |-> (c:A)) u)))`] HOLDS_AGREE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c s1 s2 b cs1 p1:A.
      c IN D /\ s1 IN D /\ s2 IN D /\ b IN D /\ cs1 IN D /\ p1 IN D
      ==> (holds D E ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
             ((17 |-> s2) ((16 |-> s1) ((15 |-> c) u))))))
             (opair_form 15 16 19) <=>
           eopair D (E:A->A->bool) c s1 cs1) /\
          (holds D E ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
             ((17 |-> s2) ((16 |-> s1) ((15 |-> c) u))))))
             (opair_form 19 18 20) <=>
           eopair D (E:A->A->bool) cs1 b p1)`
  (LABEL_TAC "opA") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((20 |-> (p1:A)) ((19 |-> (cs1:A)) ((18 |-> (b:A))
        ((17 |-> (s2:A)) ((16 |-> (s1:A)) ((15 |-> (c:A)) u))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(20 |-> (p1:A)) ((19 |-> (cs1:A)) ((18 |-> (b:A))
          ((17 |-> (s2:A)) ((16 |-> (s1:A)) ((15 |-> (c:A)) u)))))`;
        `15`; `16`; `19`] HOLDS_OPAIR_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(20 |-> (p1:A)) ((19 |-> (cs1:A)) ((18 |-> (b:A))
          ((17 |-> (s2:A)) ((16 |-> (s1:A)) ((15 |-> (c:A)) u)))))`;
        `19`; `18`; `20`] HOLDS_OPAIR_FORM)] THEN
    (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c s1 s2 b cs1 p1:A.
      c IN D /\ s1 IN D /\ s2 IN D /\ b IN D /\ cs1 IN D /\ p1 IN D
      ==> ((?cs2. cs2 IN D /\
                  ?p2. p2 IN D /\
                       holds D E ((24 |-> p2) ((23 |-> cs2)
                         ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
                         ((17 |-> s2) ((16 |-> s1) ((15 |-> c)
                           u))))))))
                         (opair_form 15 17 23) /\
                       holds D E ((24 |-> p2) ((23 |-> cs2)
                         ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
                         ((17 |-> s2) ((16 |-> s1) ((15 |-> c)
                           u))))))))
                         (opair_form 23 18 24) /\
                       E p2 (u 5)) <=>
           (?cs2. cs2 IN D /\
                  ?p2. p2 IN D /\
                       eopair D (E:A->A->bool) c s2 cs2 /\
                       eopair D E cs2 b p2 /\
                       E p2 (u 5)))`
  (LABEL_TAC "exC") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `!cs2 p2:A. cs2 IN D /\ p2 IN D
        ==> (holds D E ((24 |-> p2) ((23 |-> cs2)
               ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
               ((17 |-> s2) ((16 |-> s1) ((15 |-> c) u))))))))
               (opair_form 15 17 23) <=>
             eopair D (E:A->A->bool) c s2 cs2) /\
            (holds D E ((24 |-> p2) ((23 |-> cs2)
               ((20 |-> p1) ((19 |-> cs1) ((18 |-> b)
               ((17 |-> s2) ((16 |-> s1) ((15 |-> c) u))))))))
               (opair_form 23 18 24) <=>
             eopair D (E:A->A->bool) cs2 b p2)`
    (LABEL_TAC "opB") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `valuation D ((24 |-> (p2:A)) ((23 |-> (cs2:A))
          ((20 |-> (p1:A)) ((19 |-> (cs1:A)) ((18 |-> (b:A))
          ((17 |-> (s2:A)) ((16 |-> (s1:A)) ((15 |-> (c:A)) u))))))))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
          `(24 |-> (p2:A)) ((23 |-> (cs2:A)) ((20 |-> (p1:A))
            ((19 |-> (cs1:A)) ((18 |-> (b:A)) ((17 |-> (s2:A))
            ((16 |-> (s1:A)) ((15 |-> (c:A)) u)))))))`;
          `15`; `17`; `23`] HOLDS_OPAIR_FORM);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
          `(24 |-> (p2:A)) ((23 |-> (cs2:A)) ((20 |-> (p1:A))
            ((19 |-> (cs1:A)) ((18 |-> (b:A)) ((17 |-> (s2:A))
            ((16 |-> (s1:A)) ((15 |-> (c:A)) u)))))))`;
          `23`; `18`; `24`] HOLDS_OPAIR_FORM)] THEN
      (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
       REWRITE_TAC[VALMOD] THEN
       CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
       REWRITE_TAC[]);
      ALL_TAC] THEN
    EQ_TAC THEN
    (DISCH_THEN(X_CHOOSE_THEN `cs2:A` (CONJUNCTS_THEN2 ASSUME_TAC
       (X_CHOOSE_THEN `p2:A` (CONJUNCTS_THEN2 ASSUME_TAC
         STRIP_ASSUME_TAC)))) THEN
     EXISTS_TAC `cs2:A` THEN ASM_REWRITE_TAC[] THEN
     EXISTS_TAC `p2:A` THEN ASM_REWRITE_TAC[] THEN
     USE_THEN "opB" (fun th ->
       MP_TAC(SPECL [`cs2:A`; `p2:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(CONJUNCTS_THEN(fun th ->
       ASM_REWRITE_TAC[th] THEN ASM_REWRITE_TAC[GSYM th])));
    ALL_TAC] THEN
  REWRITE_TAC[agrbody_form; holds; HOLDS_AND; HOLDS_EX] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[]);;

let HOLDS_AGRPROP = prove
 (`!D (E:A->A->bool) u n.
        model D E ZF_AX /\ valuation D u /\
        esatuniv D E (u 2) (u 3) /\ n IN D
        ==> (holds D E ((4 |-> n) u)
              (!! 5 (rec_form satstep_form 4 --> agrbody_form)) <=>
             !t. t IN D
                 ==> esatstage D E (u 2) n t
                     ==> !c. c IN D
                 ==> !s1. s1 IN D
                          ==> !s2. s2 IN D
                                   ==> !b. b IN D
             ==> E c (u 12) /\ E s2 (u 14) /\
                 (!i. i IN D
                      ==> !w. w IN D
                              ==> E i (u 13)
                                  ==> (eapply D E s1 i w <=>
                                       eapply D E s2 i w))
                 ==> !cs1. cs1 IN D
                           ==> !p1. p1 IN D
                 ==> eopair D E c s1 cs1 /\ eopair D E cs1 b p1 /\
                     E p1 t
                     ==> ?cs2. cs2 IN D /\
                               ?p2. p2 IN D /\
                                    eopair D E c s2 cs2 /\
                                    eopair D E cs2 b p2 /\
                                    E p2 t)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((4 |-> (n:A)) u)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. (t:A) IN D
        ==> (holds D E ((5 |-> t) ((4 |-> n) u))
               (rec_form satstep_form 4) <=>
             esatstage D (E:A->A->bool) (u 2) n t)`
  (LABEL_TAC "rc") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:num->A`;
      `satstep_form`; `4`; `n:A`; `t:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC;
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        MP_TAC(REWRITE_RULE[SUBSET] FV_SATSTEP_FORM) THEN
        DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
        ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(u:num->A) 2`;
      `(u:num->A) 3`; `n:A`; `t:A`; `u:num->A`] ESATSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t. (t:A) IN D
        ==> (holds D E ((5 |-> t) ((4 |-> n) u)) agrbody_form <=>
             !c. c IN D
                 ==> !s1. s1 IN D
                          ==> !s2. s2 IN D
                                   ==> !b. b IN D
             ==> E c (u 12) /\ E s2 (u 14) /\
                 (!i. i IN D
                      ==> !w. w IN D
                              ==> E i (u 13)
                                  ==> (eapply D (E:A->A->bool)
                                         s1 i w <=>
                                       eapply D E s2 i w))
                 ==> !cs1. cs1 IN D
                           ==> !p1. p1 IN D
                 ==> eopair D E c s1 cs1 /\ eopair D E cs1 b p1 /\
                     E p1 t
                     ==> ?cs2. cs2 IN D /\
                               ?p2. p2 IN D /\
                                    eopair D E c s2 cs2 /\
                                    eopair D E cs2 b p2 /\
                                    E p2 t)`
  (LABEL_TAC "agb") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (t:A)) ((4 |-> (n:A)) u)`] HOLDS_AGRBODY) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[holds] THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Assignment agreement: if two assignments s1, s2 (functions omega -> x)    *)
(* agree at all indices below nc, and a code c lies in the hf V-stage ync    *)
(* at nc (so every variable index it mentions is an ordinal in ync, hence    *)
(* below nc), then any satisfaction verdict for <<c,s1>,b> against a stage   *)
(* graph transfers to <<c,s2>,b>, provided verdicts for subcodes already     *)
(* transfer (a hypothesis supplied by omega-induction on the verdict         *)
(* stage).  Support lemmas: updates stay inside the function space, members  *)
(* of the satisfaction universe decompose into code/assignment/bit parts,    *)
(* actual verdicts pin their assignment into the function space (giving      *)
(* a IN om in the esatall case), and pointwise updates preserve agreement.   *)
(* ------------------------------------------------------------------------- *)

let EUPDATE_FUNS = prove
 (`!D (E:A->A->bool) om x vs s a u s'.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        efuns D E om x vs /\ s IN D /\ E s vs /\
        a IN D /\ E a om /\ u IN D /\ E u x /\
        eupdate D E s a u s'
        ==> E s' vs`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(s':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) s /\ edomain D E s om /\
    !p q. p IN D /\ q IN D /\ eapply D E s p q ==> E q x`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) s'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) s' om` ASSUME_TAC THENL
   [REWRITE_TAC[edomain] THEN
    SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(z:A) = a` THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[eindom] THEN
      ASM_MESON_TAC[EUPDATE_APPLY_SAME];
      EQ_TAC THENL
       [DISCH_TAC THEN
        SUBGOAL_THEN `eindom D (E:A->A->bool) s z` MP_TAC THENL
         [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
        REWRITE_TAC[eindom] THEN
        ASM_MESON_TAC[EUPDATE_APPLY_OTHER];
        REWRITE_TAC[eindom] THEN
        DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `eapply D (E:A->A->bool) s z w` ASSUME_TAC THENL
         [ASM_MESON_TAC[EUPDATE_APPLY_OTHER]; ALL_TAC] THEN
        ASM_MESON_TAC[edomain; eindom]]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!p q. (p:A) IN D /\ (q:A) IN D /\ eapply D (E:A->A->bool) s' p q
          ==> E q x`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    ASM_CASES_TAC `(p:A) = a` THENL
     [ASM_MESON_TAC[EUPDATE_APPLY_SAME];
      ASM_MESON_TAC[EUPDATE_APPLY_OTHER]];
    ALL_TAC] THEN
  ASM_MESON_TAC[efuns]);;

let ECROSS_MEMBER = prove
 (`!D (E:A->A->bool) a b c z.
        ecross D E a b c /\ z IN D
        ==> (E z c <=>
             ?u w. u IN D /\ w IN D /\ E u a /\ E w b /\
                   eopair D E u w z)`,
  REWRITE_TAC[ecross] THEN MESON_TAC[]);;

let ESATUNIV_PAIR_DECOMP_F = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s b cs p.
        model D E zfw_ax /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p /\ E p u2
        ==> E c hf /\ E s vs /\ E b two`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatuniv] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "esatuniv")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `hf':A`
    (X_CHOOSE_THEN `vs':A` (X_CHOOSE_THEN `cs2u:A`
      (X_CHOOSE_THEN `two':A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf':A) = hf` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSET_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs':A) = vs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(two':A) = two` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?csp bt. (csp:A) IN D /\ (bt:A) IN D /\ E csp cs2u /\
             E bt two /\ eopair D (E:A->A->bool) csp bt p`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs2u:A`; `two:A`;
      `u2:A`; `p:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) p u2` THEN REWRITE_TAC[th]) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `csp:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `bt:A` THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(csp:A) = cs /\ (bt:A) = b`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `?cc ssp. (cc:A) IN D /\ (ssp:A) IN D /\ E cc hf /\
             E ssp vs /\ eopair D (E:A->A->bool) cc ssp cs`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`;
      `cs2u:A`; `cs:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) cs cs2u` THEN REWRITE_TAC[th]) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `cc:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `ssp:A` THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(cc:A) = c /\ (ssp:A) = s`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ_F]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let ESATUNIV_PAIR_DECOMP = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s b cs p.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p /\ E p u2
        ==> E c hf /\ E s vs /\ E b two`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATUNIV_PAIR_DECOMP_F));;

let ESATUNIV_PAIR_INTRO_F = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s b cs p.
        model D E zfw_ax /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p /\
        E c hf /\ E s vs /\ E b two
        ==> E p u2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatuniv] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "esatuniv")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `hf':A`
    (X_CHOOSE_THEN `vs':A` (X_CHOOSE_THEN `cs2u:A`
      (X_CHOOSE_THEN `two':A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf':A) = hf` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSET_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs':A) = vs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(two':A) = two` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cs cs2u` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`;
      `cs2u:A`; `cs:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`c:A`; `s:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs2u:A`; `two:A`;
    `u2:A`; `p:A`] ECROSS_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`cs:A`; `b:A`] THEN ASM_REWRITE_TAC[]);;

let ESATUNIV_PAIR_INTRO = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s b cs p.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p /\
        E c hf /\ E s vs /\ E b two
        ==> E p u2`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATUNIV_PAIR_INTRO_F));;

let EFUNS_APPLY = prove
 (`!D (E:A->A->bool) om x vs g u w.
        model D E ZF_AX /\ efuns D E om x vs /\
        g IN D /\ E g vs /\ u IN D /\ w IN D /\ eapply D E g u w
        ==> E u om /\ E w x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) g /\ edomain D E g om /\
    !u w. u IN D /\ w IN D /\ eapply D E g u w ==> E w x`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  CONJ_TAC THENL [ASM_MESON_TAC[edomain; eindom]; ASM_MESON_TAC[]]);;

let EUPDATE_AGREE = prove
 (`!D (E:A->A->bool) s1 s2 a u s1' s2' i w.
        model D E ZF_AX /\
        s1 IN D /\ s2 IN D /\ a IN D /\ u IN D /\
        eupdate D E s1 a u s1' /\ eupdate D E s2 a u s2' /\
        i IN D /\ w IN D /\
        (i = a \/ (eapply D E s1 i w <=> eapply D E s2 i w))
        ==> (eapply D E s1' i w <=> eapply D E s2' i w)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  ASM_CASES_TAC `(i:A) = a` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s1:A`; `a:A`; `u:A`;
                  `s1':A`] EUPDATE_APPLY_SAME) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "a1") (LABEL_TAC "u1")) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s2:A`; `a:A`; `u:A`;
                  `s2':A`] EUPDATE_APPLY_SAME) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "a2") (LABEL_TAC "u2")) THEN
    EQ_TAC THEN DISCH_TAC THENL
     [SUBGOAL_THEN `(w:A) = u` SUBST1_TAC THENL
       [USE_THEN "u1" (MP_TAC o SPEC `w:A`) THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        USE_THEN "a2" ACCEPT_TAC];
      SUBGOAL_THEN `(w:A) = u` SUBST1_TAC THENL
       [USE_THEN "u2" (MP_TAC o SPEC `w:A`) THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        USE_THEN "a1" ACCEPT_TAC]];
    SUBGOAL_THEN
     `eapply D (E:A->A->bool) s1 i w <=> eapply D E s2 i w`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s2:A`; `a:A`; `u:A`;
                  `s2':A`; `i:A`; `w:A`] EUPDATE_APPLY_OTHER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s1:A`; `a:A`; `u:A`;
                  `s1':A`; `i:A`; `w:A`] EUPDATE_APPLY_OTHER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let EVERDICT_VS = prove
 (`!D (E:A->A->bool) om x hf vs two u2 n r c sg bt.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        n IN D /\ eordinal D E n /\ r IN D /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        c IN D /\ sg IN D /\ bt IN D /\
        everdict D E c sg bt r
        ==> E c hf /\ E sg vs /\ E bt two`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `r:A`;
                `c:A`; `sg:A`; `bt:A`] EVERDICT_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
    (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`; `y:A`]
        ESATSTAGE_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u2':A` (X_CHOOSE_THEN `r':A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `u2':A = u2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o SPEC `w:A` o check (fun th ->
      is_forall(concl th) &&
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatbody")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) w y` THEN REWRITE_TAC[th]) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `c:A`; `sg:A`; `bt:A`;
                `cs:A`; `w:A`] ESATUNIV_PAIR_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let ESATMEM_AGREE,ESATEQ_AGREE = (CONJ_PAIR o prove)
 (`(!D (E:A->A->bool) om x vs nc ync s1 s2 bb tag data.
         model D E ZF_AX /\ eomega D E om /\ x IN D /\
         efuns D E om x vs /\
         nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
         s1 IN D /\ s2 IN D /\ E s1 vs /\ E s2 vs /\
         (!i. i IN D ==> E i nc
              ==> !w. w IN D
                      ==> (eapply D E s1 i w <=> eapply D E s2 i w)) /\
         bb IN D /\ tag IN D /\ data IN D /\ E data ync /\
         esatmem D E bb s1 tag data
         ==> esatmem D E bb s2 tag data) /\
   (!D (E:A->A->bool) om x vs nc ync s1 s2 bb tag data.
         model D E ZF_AX /\ eomega D E om /\ x IN D /\
         efuns D E om x vs /\
         nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
         s1 IN D /\ s2 IN D /\ E s1 vs /\ E s2 vs /\
         (!i. i IN D ==> E i nc
              ==> !w. w IN D
                      ==> (eapply D E s1 i w <=> eapply D E s2 i w)) /\
         bb IN D /\ tag IN D /\ data IN D /\ E data ync /\
         esateq D E bb s1 tag data
         ==> esateq D E bb s2 tag data)`,
  CONJ_TAC THEN
  (REPEAT GEN_TAC THEN STRIP_TAC THEN
   FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatmem; esateq]) THEN
   DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
   DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
     (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `sb:A`
       (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
   SUBGOAL_THEN `(E:A->A->bool) a om /\ E sa x` STRIP_ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `vs:A`;
                   `s1:A`; `a:A`; `sa:A`] EFUNS_APPLY) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `(E:A->A->bool) b om /\ E sb x` STRIP_ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `vs:A`;
                   `s1:A`; `b:A`; `sb:A`] EFUNS_APPLY) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `eordinal D (E:A->A->bool) a` ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `a:A`]
       EOMEGA_ORDINALS) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `b:A`]
       EOMEGA_ORDINALS) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `(E:A->A->bool) a ync /\ E b ync` STRIP_ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `ync:A`;
                   `a:A`; `b:A`; `data:A`] EOPAIR_VSTAGE) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `(E:A->A->bool) a nc` ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `nc:A`; `ync:A`]
       ORDINALS_IN_VSTAGE) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `(E:A->A->bool) b nc` ASSUME_TAC THENL
    [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `nc:A`; `ync:A`]
       ORDINALS_IN_VSTAGE) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
     ALL_TAC] THEN
   SUBGOAL_THEN `eapply D (E:A->A->bool) s2 a sa` ASSUME_TAC THENL
    [FIRST_ASSUM(MP_TAC o SPEC `a:A` o check (fun th ->
       is_forall(concl th) && can (find_term (fun t -> is_const t &&
         fst(dest_const t) = "eapply")) (concl th))) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(MP_TAC o SPEC `sa:A`) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
     ALL_TAC] THEN
   SUBGOAL_THEN `eapply D (E:A->A->bool) s2 b sb` ASSUME_TAC THENL
    [FIRST_ASSUM(MP_TAC o SPEC `b:A` o check (fun th ->
       is_forall(concl th) && can (find_term (fun t -> is_const t &&
         fst(dest_const t) = "eapply")) (concl th))) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(MP_TAC o SPEC `sb:A`) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
     ALL_TAC] THEN
   REWRITE_TAC[esatmem; esateq] THEN ASM_REWRITE_TAC[] THEN
   MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `sa:A`; `sb:A`] THEN
   ASM_REWRITE_TAC[]));;

let ESATIMP_AGREE = prove
 (`!D (E:A->A->bool) vs r nc ync s1 s2 bb tag data.
        model D E ZF_AX /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
        s1 IN D /\ s2 IN D /\ E s1 vs /\ E s2 vs /\
        (!i. i IN D ==> E i nc
             ==> !w. w IN D
                     ==> (eapply D E s1 i w <=> eapply D E s2 i w)) /\
        (!c' t1 t2 b'. c' IN D /\ t1 IN D /\ t2 IN D /\ b' IN D /\
                       E c' ync /\ E t1 vs /\ E t2 vs /\
                       (!i. i IN D ==> E i nc
                            ==> !w. w IN D
                                    ==> (eapply D E t1 i w <=>
                                         eapply D E t2 i w)) /\
                       everdict D E c' t1 b' r
                       ==> everdict D E c' t2 b' r) /\
        bb IN D /\ tag IN D /\ data IN D /\ E data ync /\
        esatimp D E bb s1 tag data r
        ==> esatimp D E bb s2 tag data r`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatimp]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `c2:A`
    (X_CHOOSE_THEN `zr:A` (X_CHOOSE_THEN `on1:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) c1 ync /\ E c2 ync` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `ync:A`;
                  `c1:A`; `c2:A`; `data:A`] EOPAIR_VSTAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!cx bx. cx IN D /\ bx IN D /\ E cx ync /\
            everdict D (E:A->A->bool) cx s1 bx r
            ==> everdict D E cx s2 bx r`
  (LABEL_TAC "tr") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o
      SPECL [`cx:A`; `s1:A`; `s2:A`; `bx:A`] o check (fun th ->
        is_forall(concl th) && can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "everdict")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[esatimp] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`c1:A`; `c2:A`; `zr:A`; `on1:A`] THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN STRIP_ASSUME_TAC o check (fun th ->
    is_disj(concl th))) THENL
   [USE_THEN "tr" (MP_TAC o SPECL [`c1:A`; `zr:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "tr" (MP_TAC o SPECL [`c2:A`; `on1:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
    USE_THEN "tr" (MP_TAC o SPECL [`c1:A`; `on1:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    USE_THEN "tr" (MP_TAC o SPECL [`c2:A`; `zr:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]]);;

let ESATALL_AGREE = prove
 (`!D (E:A->A->bool) om x hf vs two u2 n r nc ync s1 s2 bb tag data.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        n IN D /\ eordinal D E n /\ r IN D /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
        s1 IN D /\ s2 IN D /\ E s1 vs /\ E s2 vs /\
        (!i. i IN D ==> E i nc
             ==> !w. w IN D
                     ==> (eapply D E s1 i w <=> eapply D E s2 i w)) /\
        (!c' t1 t2 b'. c' IN D /\ t1 IN D /\ t2 IN D /\ b' IN D /\
                       E c' ync /\ E t1 vs /\ E t2 vs /\
                       (!i. i IN D ==> E i nc
                            ==> !w. w IN D
                                    ==> (eapply D E t1 i w <=>
                                         eapply D E t2 i w)) /\
                       everdict D E c' t1 b' r
                       ==> everdict D E c' t2 b' r) /\
        bb IN D /\ tag IN D /\ data IN D /\ E data ync /\
        esatall D E bb s1 tag data r x
        ==> esatall D E bb s2 tag data r x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatall]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `c1:A`
    (X_CHOOSE_THEN `z0:A` (X_CHOOSE_THEN `z1:A`
      (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) a ync /\ E c1 ync` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `ync:A`;
                  `a:A`; `c1:A`; `data:A`] EOPAIR_VSTAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[esatall] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `c1:A`; `z0:A`; `z1:A`] THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN2
    (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "s1all"))
    (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) o
    check (fun th -> is_disj(concl th))) THENL
   [DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    X_GEN_TAC `s2':A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s1:A`; `a:A`; `u:A`]
      EUPDATE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `s1':A`) THEN
    SUBGOAL_THEN `(s1':A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
    USE_THEN "s1all" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `s1':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                  `vs:A`; `two:A`; `u2:A`; `n:A`; `r:A`; `c1:A`;
