let ESATBODY_AGREE = prove
 (`!D (E:A->A->bool) om x hf vs two u2 n r nc ync c s1 s2 bb
    cs1 cs2 p1 p2.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        n IN D /\ eordinal D E n /\ r IN D /\
        (!w. w IN D
             ==> (E w r <=>
                  ?b y. b IN D /\ y IN D /\ E b n /\
                        esatstage D E x b y /\ eopair D E b y w)) /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
        (!c' t1 t2 b'. c' IN D /\ t1 IN D /\ t2 IN D /\ b' IN D /\
                       E c' ync /\ E t1 vs /\ E t2 vs /\
                       (!i. i IN D ==> E i nc
                            ==> !w. w IN D
                                    ==> (eapply D E t1 i w <=>
                                         eapply D E t2 i w)) /\
                       everdict D E c' t1 b' r
                       ==> everdict D E c' t2 b' r) /\
        c IN D /\ s1 IN D /\ s2 IN D /\ bb IN D /\
        cs1 IN D /\ cs2 IN D /\ p1 IN D /\ p2 IN D /\
        E c ync /\ E s1 vs /\ E s2 vs /\
        (!i. i IN D ==> E i nc
             ==> !w. w IN D
                     ==> (eapply D E s1 i w <=> eapply D E s2 i w)) /\
        eopair D E c s1 cs1 /\ eopair D E cs1 bb p1 /\
        eopair D E c s2 cs2 /\ eopair D E cs2 bb p2 /\
        esatbody D E x r p1
        ==> esatbody D E x r p2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `c:A`;
                `s1:A`; `bb:A`; `cs1:A`; `p1:A`] SATBODY_CASES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@tag data. h1 h2 h3 +" THEN
  SUBGOAL_THEN `(E:A->A->bool) tag ync /\ E data ync`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `ync:A`;
                  `tag:A`; `data:A`; `c:A`] EOPAIR_VSTAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(esatfalse D (E:A->A->bool) bb tag data \/
     esatmem D E bb s2 tag data \/
     esateq D E bb s2 tag data \/
     esatimp D E bb s2 tag data r \/
     esatall D E bb s2 tag data r x)
    ==> esatbody D E x r p2`
  (LABEL_TAC "rb") THENL
   [DISCH_TAC THEN REWRITE_TAC[esatbody] THEN
    MAP_EVERY EXISTS_TAC [`cs2:A`; `bb:A`; `c:A`; `s2:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [USE_THEN "rb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `vs:A`;
                  `nc:A`; `ync:A`; `s1:A`; `s2:A`; `bb:A`; `tag:A`;
                  `data:A`] ESATMEM_AGREE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN USE_THEN "rb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `vs:A`;
                  `nc:A`; `ync:A`; `s1:A`; `s2:A`; `bb:A`; `tag:A`;
                  `data:A`] ESATEQ_AGREE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN USE_THEN "rb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vs:A`; `r:A`;
                  `nc:A`; `ync:A`; `s1:A`; `s2:A`; `bb:A`; `tag:A`;
                  `data:A`] ESATIMP_AGREE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN USE_THEN "rb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                  `vs:A`; `two:A`; `u2:A`; `n:A`; `r:A`; `nc:A`;
                  `ync:A`; `s1:A`; `s2:A`; `bb:A`; `tag:A`;
                  `data:A`] ESATALL_AGREE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN USE_THEN "rb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The agreement theorem itself, by omega-induction on the verdict stage     *)
(* inside the model (via EOMEGA_INDUCT_HOLDS on the object formula           *)
(* !!5 (rec_form satstep_form 4 --> agrbody_form) at induction slot 4,       *)
(* characterized by HOLDS_AGRPROP).  eagrprop packages the semantic          *)
(* property; the shared per-stage lemma derives it at any single stage from  *)
(* verdict transfer over the stage graph (vacuous at the empty stage; at a   *)
(* successor stage every recorded verdict lives in some earlier stage, is    *)
(* moved up to the stage at the predecessor by cumulativity, transferred     *)
(* there by the induction hypothesis, and reinjected).  Finally ESAT_AGREE:  *)
(* internal satisfaction only depends on the assignment below the code's     *)
(* variable bound.                                                           *)
(* ------------------------------------------------------------------------- *)

let eagrprop = new_definition
  `eagrprop D (E:A->A->bool) ync nc vs t <=>
        !c. c IN D
            ==> !s1. s1 IN D
                     ==> !s2. s2 IN D
                              ==> !b. b IN D
            ==> E c ync /\ E s2 vs /\
                (!i. i IN D
                     ==> !w. w IN D
                             ==> E i nc
                                 ==> (eapply D E s1 i w <=>
                                      eapply D E s2 i w))
                ==> !cs1. cs1 IN D
                          ==> !p1. p1 IN D
                ==> eopair D E c s1 cs1 /\ eopair D E cs1 b p1 /\
                    E p1 t
                    ==> ?cs2. cs2 IN D /\
                              ?p2. p2 IN D /\
                                   eopair D E c s2 cs2 /\
                                   eopair D E cs2 b p2 /\
                                   E p2 t`;;

let ESATSTAGE_AGREE_LEMMA = prove
 (`!D (E:A->A->bool) om x hf vs two u2 nc ync n t.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
        n IN D /\ eordinal D E n /\ t IN D /\ esatstage D E x n t /\
        (!r. r IN D /\
             (!w. w IN D
                  ==> (E w r <=>
                       ?b y. b IN D /\ y IN D /\ E b n /\
                             esatstage D E x b y /\ eopair D E b y w))
             ==> !c' t1 t2 b'.
                     c' IN D /\ t1 IN D /\ t2 IN D /\ b' IN D /\
                     E c' ync /\ E t1 vs /\ E t2 vs /\
                     (!i. i IN D ==> E i nc
                          ==> !w. w IN D
                                  ==> (eapply D E t1 i w <=>
                                       eapply D E t2 i w)) /\
                     everdict D E c' t1 b' r
                     ==> everdict D E c' t2 b' r)
        ==> eagrprop D E ync nc vs t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
    ESATSTAGE_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2' r. h1 h2 rch tch" THEN
  SUBGOAL_THEN `u2':A = u2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_UNIQUE]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `r:A` o check (fun th ->
    is_forall(concl th) && can (find_term (fun tm -> is_const tm &&
      fst(dest_const tm) = "everdict")) (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "vtr") THEN
  REWRITE_TAC[eagrprop] THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  X_GEN_TAC `s1:A` THEN DISCH_TAC THEN
  X_GEN_TAC `s2:A` THEN DISCH_TAC THEN
  X_GEN_TAC `b:A` THEN DISCH_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sag"))) THEN
  X_GEN_TAC `cs1:A` THEN DISCH_TAC THEN
  X_GEN_TAC `p1:A` THEN DISCH_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    MP_TAC)) THEN
  USE_THEN "tch" (fun th -> MP_TAC(SPEC `p1:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `c:A`; `s1:A`; `b:A`;
                `cs1:A`; `p1:A`] ESATUNIV_PAIR_DECOMP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `!i. i IN D ==> E i nc
        ==> !w. w IN D
                ==> (eapply D (E:A->A->bool) s1 i w <=>
                     eapply D E s2 i w)`
  (LABEL_TAC "sag2") THENL
   [X_GEN_TAC `i:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "sag" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `s2:A`]
    EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `cs2:A`) THEN
  SUBGOAL_THEN `(cs2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs2:A`; `b:A`]
    EOPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `p2:A`) THEN
  SUBGOAL_THEN `(p2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `n:A`; `r:A`; `nc:A`;
                `ync:A`; `c:A`; `s1:A`; `s2:A`; `b:A`; `cs1:A`;
                `cs2:A`; `p1:A`; `p2:A`] ESATBODY_AGREE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `c:A`; `s2:A`; `b:A`;
                `cs2:A`; `p2:A`] ESATUNIV_PAIR_INTRO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) p2 t` ASSUME_TAC THENL
   [USE_THEN "tch" (fun th -> MP_TAC(SPEC `p2:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `cs2:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `p2:A` THEN ASM_REWRITE_TAC[]);;

let ESATSTAGE_AGREE = prove
 (`!D (E:A->A->bool) om x hf vs two u2 nc ync.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync
        ==> !n. n IN D /\ E n om
                ==> !t. t IN D
                        ==> esatstage D E x n t
                            ==> eagrprop D E ync nc vs t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs:A) IN D /\ (u2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns; ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((14 |-> (vs:A)) ((13 |-> nc) ((12 |-> ync)
       ((3 |-> u2) ((2 |-> x) v0)))))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n. (n:A) IN D
        ==> (holds D E ((4 |-> n) ((14 |-> (vs:A)) ((13 |-> nc)
               ((12 |-> ync) ((3 |-> u2) ((2 |-> x) v0))))))
              (!! 5 (rec_form satstep_form 4 --> agrbody_form)) <=>
             !t. t IN D
                 ==> esatstage D E x n t
                     ==> eagrprop D E ync nc vs t)`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(14 |-> (vs:A)) ((13 |-> nc) ((12 |-> ync)
         ((3 |-> u2) ((2 |-> x) v0))))`; `n:A`] HOLDS_AGRPROP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[eagrprop] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
                `!! 5 (rec_form satstep_form 4 --> agrbody_form)`; `4`;
                `(14 |-> (vs:A)) ((13 |-> nc) ((12 |-> ync)
                   ((3 |-> u2) ((2 |-> x) v0))))`]
     EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `t:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `nc:A`; `ync:A`;
                    `e:A`; `t:A`] ESATSTAGE_AGREE_LEMMA) THEN
