      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
