      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `tm:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) b m \/ (b:A) = m` MP_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `sm:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
