        ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
       [SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
         [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) w tm` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `b:A`;
                        `m:A`; `y:A`; `tm:A`; `w:A`]
            ESATSTAGE_CUMUL) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          ALL_TAC];
        FIRST_X_ASSUM SUBST_ALL_TAC THEN
        SUBGOAL_THEN `(y:A) = tm` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `m:A`;
                        `y:A`; `tm:A`] ESATSTAGE_UNIQUE) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          SUBGOAL_THEN `(E:A->A->bool) w tm` ASSUME_TAC THENL
           [ASM_REWRITE_TAC[]; ALL_TAC]]] THEN
      (SUBGOAL_THEN
       `!i. i IN D
            ==> !w'. w' IN D
                     ==> E i nc
                         ==> (eapply D (E:A->A->bool) t1 i w' <=>
                              eapply D E t2 i w')`
      ASSUME_TAC THENL
       [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
        X_GEN_TAC `w':A` THEN DISCH_TAC THEN DISCH_TAC THEN
