      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `b':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `cs:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `cs2':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `w2:A` STRIP_ASSUME_TAC))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `sm:A`;
                    `r:A`; `c':A`; `t2:A`; `b':A`; `m:A`; `tm:A`;
                    `cs2':A`; `w2:A`] EVERDICT_INTRO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC])];
    ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ind") THEN
  X_GEN_TAC `n:A` THEN STRIP_TAC THEN
  USE_THEN "pch" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    USE_THEN "ind" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [th]) THEN
    DISCH_THEN ACCEPT_TAC));;

let ESAT_AGREE = prove
 (`!D (E:A->A->bool) om x hf vs two u2 nc ync c s1 s2.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        nc IN D /\ eordinal D E nc /\ ync IN D /\ ehfstage D E nc ync /\
        c IN D /\ s1 IN D /\ s2 IN D /\ E c ync /\ E s2 vs /\
        (!i. i IN D
             ==> !w. w IN D
                     ==> E i nc
                         ==> (eapply D E s1 i w <=> eapply D E s2 i w))
        ==> esat D E x c s1
        ==> esat D E x c s2`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[esat] THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
    (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
      (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `nc:A`; `ync:A`]
    ESATSTAGE_AGREE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `c:A` o REWRITE_RULE[eagrprop]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `s1:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `s2:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `z1:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `cs:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cs2:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `p2:A` STRIP_ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC
   [`om:A`; `n:A`; `t:A`; `z1:A`; `cs2:A`; `p2:A`] THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Toward satisfaction absoluteness: the constructible class is closed       *)
(* under set difference (carve in the L-model, transfer the characterization *)
(* to D by transitivity, identify by uniqueness); the padding construction:  *)
(* any assignment s : om -> x with x constructible can be replaced by a      *)
(* constructible assignment agreeing with s below any finite bound nc --     *)
(* the restriction s|nc is a finite function with values in the transitive   *)
(* set x, hence constructible (LCLASS_NAT_FUN), and the tail is the          *)
(* constant d0 on the constructible set om \ nc; and the relation between    *)
(* the L-model's function space funs_L(om,x) and the real one: it consists   *)
(* of exactly the constructible members of funs(om,x).                       *)
(* ------------------------------------------------------------------------- *)

let LCLASS_EDIFF = prove
 (`!D (E:A->A->bool) x y z.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E /\
        ediff D E x y z
        ==> z IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `?z'. ediff (lclass D E) (E:A->A->bool) x y z'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z':A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `ediff D (E:A->A->bool) x y z'` ASSUME_TAC THENL
   [REWRITE_TAC[ediff] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      ASM_MESON_TAC[ediff];
      STRIP_TAC THEN
      SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      ASM_MESON_TAC[ediff]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = z'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[EDIFF_UNIQUE]);;

let PADDED_ASSIGNMENT = prove
 (`!D (E:A->A->bool) om x vs s nc d0.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        efuns D E om x vs /\ s IN D /\ E s vs /\
        nc IN D /\ E nc om /\ d0 IN D /\ E d0 x
        ==> ?st. st IN lclass D E /\ E st vs /\
                 !i w. i IN D /\ w IN D /\ E i nc
                       ==> (eapply D E st i w <=> eapply D E s i w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D /\ (x:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) s /\ edomain D E s om /\
    !u w. u IN D /\ w IN D /\ eapply D E s u w ==> E w x`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN D ==> ((E:A->A->bool) u om <=> eindom D E s u)`
  (LABEL_TAC "sdm") THENL [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  SUBGOAL_THEN `?r1. erestrict D (E:A->A->bool) s nc r1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(r1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z r1 <=>
             E z s /\ ?u w. u IN D /\ w IN D /\ E u nc /\
                            eopair D E u w z)`
  (LABEL_TAC "r1ch") THENL [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) r1` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i w. i IN D /\ w IN D
          ==> (eapply D (E:A->A->bool) r1 i w <=>
