let LCLASS_EFUNS_MEMBER = prove
 (`!D (E:A->A->bool) om x vs vsL s.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        efuns D E om x vs /\ efuns (lclass D E) E om x vsL /\
        s IN D
        ==> (E s vsL <=> E s vs /\ s IN lclass D E)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D /\ (x:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(vsL:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(s:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "lclass")) (concl a) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vsL`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC (LABEL_TAC "vl"))) THEN
    SUBGOAL_THEN `eisfun D (E:A->A->bool) s` ASSUME_TAC THENL
     [ASM_MESON_TAC[EISFUN_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `edomain D (E:A->A->bool) s om` ASSUME_TAC THENL
     [ASM_MESON_TAC[EDOMAIN_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!u w. u IN D /\ w IN D /\ eapply D (E:A->A->bool) s u w
            ==> E w x`
    ASSUME_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
          GEN_REWRITE_RULE I [eapply] o check (fun a ->
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "eapply")) (concl a))) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
         [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `s:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`;
                      `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "vl" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `u:A`;
                    `w:A`] EAPPLY_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        not(can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "lclass")) (concl a)) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        not(can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "lclass")) (concl a)) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vs`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC (LABEL_TAC "vd"))) THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "lclass")) (concl a) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[EISFUN_LCLASS];
      ASM_MESON_TAC[EDOMAIN_LCLASS];
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      USE_THEN "vd" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
      SUBGOAL_THEN `(u:A) IN D /\ (w:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `u:A`;
                    `w:A`] EAPPLY_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Absoluteness of the hereditarily finite universe between the model and    *)
(* its constructible class.  Subsets of V-stages are constructible (they     *)
(* are members of the next stage, which is constructible).  vstep transfers  *)
(* between the models whenever subsets of the input's values are             *)
(* constructible.  A V-stage of the model is a V-stage of the L-model: the   *)
(* witnessing attempt can be taken to be the recursion graph on suc n, a     *)
(* finite function with constructible values, hence itself constructible,    *)
(* and its step instances transfer by the vstep lemma; the converse (for a   *)
(* constructible candidate) follows by uniqueness inside the L-model.  The   *)
(* hf universe itself is then literally the same set in both models.         *)
(* ------------------------------------------------------------------------- *)

let EHFSTAGE_SUBSET_LCLASS = prove
 (`!D (E:A->A->bool) om n y u.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y /\ u IN D /\ esubset D E u y
        ==> u IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `?sn. esuc D (E:A->A->bool) n sn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ysn. (ysn:A) IN D /\ ehfstage D (E:A->A->bool) sn ysn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u ysn` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`;
                  `y:A`; `ysn:A`] EHFSTAGE_SUC_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(ysn:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSTAGE]; ALL_TAC] THEN
  MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `ysn:A` THEN
  ASM_REWRITE_TAC[]);;

let VSTEP_LCLASS = prove
 (`!D (E:A->A->bool) r y.
        model D E ZF_AX /\ r IN lclass D E /\ y IN lclass D E /\
        (!u b w. u IN D /\ b IN D /\ w IN D /\
                 eapply D E r b w /\ esubset D E u w
                 ==> u IN lclass D E)
        ==> (vstep (lclass D E) E r y <=> vstep D E r y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[vstep] THEN
  EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ch")) THENL
   [CONJ_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `y:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) u y`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      SUBGOAL_THEN `(b:A) IN D /\ (w:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EAPPLY_LCLASS]; ASM_MESON_TAC[ESUBSET_LCLASS]];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPECL [`u:A`; `b:A`; `w:A`] o
          check (fun a -> is_forall(concl a) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "esubset")) (concl a) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "lclass")) (concl a))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(b:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [SUBGOAL_THEN
         `?z. z IN D /\ eopair D (E:A->A->bool) b w z /\ E z r`
        STRIP_ASSUME_TAC THENL
         [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
            GEN_REWRITE_RULE I [eapply] o check (fun a ->
              concl a = `eapply D (E:A->A->bool) r b w`)) THEN
          EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[EOPAIR_IN];
          ALL_TAC] THEN
        SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
         [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `r:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                      `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EAPPLY_LCLASS]; ASM_MESON_TAC[ESUBSET_LCLASS]]];
    CONJ_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b:A) IN lclass D E /\ (w:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [SUBGOAL_THEN
         `?z. z IN D /\ eopair D (E:A->A->bool) b w z /\ E z r`
        STRIP_ASSUME_TAC THENL
         [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
            GEN_REWRITE_RULE I [eapply] o check (fun a ->
              concl a = `eapply D (E:A->A->bool) r b w`)) THEN
          EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[EOPAIR_IN];
          ALL_TAC] THEN
        SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
         [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `r:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                      `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EAPPLY_LCLASS]; ASM_MESON_TAC[ESUBSET_LCLASS]];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b:A) IN D /\ (w:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EAPPLY_LCLASS]; ASM_MESON_TAC[ESUBSET_LCLASS]]]]);;

let LCLASS_EHFSTAGE_ABS = prove
 (`!D (E:A->A->bool) om n y.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y
        ==> ehfstage (lclass D E) E n y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(n:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSTAGE]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\k:num. (om:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation (lclass D E) (\k:num. (om:A))`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?sn. esuc D (E:A->A->bool) n sn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`]
    VSTEP_QFUN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "qf") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`]
    VSTEP_QTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "qt") THEN
  SUBGOAL_THEN
   `?rg. erecres D (E:A->A->bool) vstep_form (\k:num. (om:A)) sn rg`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(rg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. w IN D
        ==> ((E:A->A->bool) w rg <=>
             ?b y'. b IN D /\ y' IN D /\ E b sn /\
                    erec D E vstep_form (\k:num. (om:A)) b y' /\
                    eopair D E b y' w)`
  (LABEL_TAC "rgch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w. b IN D /\ w IN D
          ==> (eapply D (E:A->A->bool) rg b w <=>
               E b sn /\ erec D E vstep_form (\k:num. (om:A)) b w)`
  (LABEL_TAC "rap") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
        GEN_REWRITE_RULE I [eapply]) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z rg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b':A) = b /\ (y':A) = w`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) rg` ASSUME_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z rg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b':A`; `y':A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
       [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `((E:A->A->bool) u sn /\
         erec D E vstep_form (\k:num. (om:A)) u w) /\
        (E u sn /\ erec D E vstep_form (\k:num. (om:A)) u w')`
      (DESTRUCT_TAC "(_ h1) _ h2") THENL
       [CONJ_TAC THENL
         [USE_THEN "rap" (MP_TAC o SPECL [`u:A`; `w:A`]);
          USE_THEN "rap" (MP_TAC o SPECL [`u:A`; `w':A`])] THEN
        (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
         REWRITE_TAC[eapply]) THENL
         [EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`;
                    `\k:num. (om:A)`; `u:A`; `w:A`; `w':A`]
        EREC_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) rg sn` ASSUME_TAC THENL
   [REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?w. (w:A) IN D /\
            erec D (E:A->A->bool) vstep_form (\k:num. (om:A)) b w`
      STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC EREC_EXISTS THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a ->
            concl a = `eapply D (E:A->A->bool) rg b w`))) THEN
      SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w. b IN D /\ w IN D /\ eapply D (E:A->A->bool) rg b w
          ==> w IN lclass D E`
  (LABEL_TAC "rgvl") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) b sn /\
      erec D E vstep_form (\k:num. (om:A)) b w`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      ALL_TAC] THEN
    SUBGOAL_THEN `ehfstage D (E:A->A->bool) b w` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                    `\k:num. (om:A)`] EHFSTAGE_EREC) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b om` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sn:A`;
                    `b:A`] EOMEGA_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `b:A`;
                  `w:A`] LCLASS_EHFSTAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(rg:A) IN lclass D E` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sn:A`;
                  `rg:A`] LCLASS_NAT_FUN) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    USE_THEN "rgvl" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eattempt (lclass D E) (E:A->A->bool) vstep_form (\k:num. (om:A))
             rg sn`
  ASSUME_TAC THENL
   [REWRITE_TAC[eattempt] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rg:A`]
        EISFUN_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rg:A`; `sn:A`]
        EDOMAIN_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`b:A`; `r':A`; `y2:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(b:A) IN D /\ (r':A) IN D /\ (y2:A) IN D`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      SUBGOAL_THEN `erestrict D (E:A->A->bool) rg b r'`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rg:A`; `b:A`;
                      `r':A`] ERESTRICT_LCLASS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) rg b y2` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rg:A`; `b:A`;
                      `y2:A`] EAPPLY_LCLASS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(E:A->A->bool) b sn /\
        erec D E vstep_form (\k:num. (om:A)) b y2`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `y2:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `!d. d IN D /\ (E:A->A->bool) d b ==> E d sn`
      (LABEL_TAC "bt") THENL
       [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
      SUBGOAL_THEN
       `erecres D (E:A->A->bool) vstep_form (\k:num. (om:A)) b r'`
      ASSUME_TAC THENL
       [REWRITE_TAC[erecres] THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN
        FIRST_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o
          GEN_REWRITE_RULE I [erestrict] o check (fun a ->
            concl a = `erestrict D (E:A->A->bool) rg b r'`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "rgch" (MP_TAC o SPEC `w:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EQ_TAC THENL
         [DISCH_THEN(CONJUNCTS_THEN2
            (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `y3:A`
              STRIP_ASSUME_TAC))
            (X_CHOOSE_THEN `u':A` (X_CHOOSE_THEN `w2:A`
              STRIP_ASSUME_TAC))) THEN
          SUBGOAL_THEN `(u':A) = b2 /\ (w2:A) = y3`
          (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
           [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
          MAP_EVERY EXISTS_TAC [`b2:A`; `y3:A`] THEN
          ASM_REWRITE_TAC[];
          DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `y3:A`
            STRIP_ASSUME_TAC)) THEN
          CONJ_TAC THENL
           [MAP_EVERY EXISTS_TAC [`c:A`; `y3:A`] THEN
            ASM_REWRITE_TAC[] THEN
            USE_THEN "bt" (MP_TAC o SPEC `c:A`) THEN
            ANTS_TAC THENL
             [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
            MAP_EVERY EXISTS_TAC [`c:A`; `y3:A`] THEN
            ASM_REWRITE_TAC[]]];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`;
                    `\k:num. (om:A)`; `b:A`; `y2:A`; `r':A`]
        EREC_EQUATION) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN `vstep D (E:A->A->bool) r' y2` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`;
                      `r':A`; `y2:A`] HOLDS_VSTEP_FORM) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `vstep (lclass D E) (E:A->A->bool) r' y2`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r':A`; `y2:A`]
          VSTEP_LCLASS) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN
          MAP_EVERY X_GEN_TAC [`u:A`; `b2:A`; `w2:A`] THEN
          STRIP_TAC THEN
          SUBGOAL_THEN `eapply D (E:A->A->bool) rg b2 w2`
          ASSUME_TAC THENL
           [ASM_MESON_TAC[ERESTRICT_APPLY]; ALL_TAC] THEN
          SUBGOAL_THEN
           `(E:A->A->bool) b2 sn /\
            erec D E vstep_form (\k:num. (om:A)) b2 w2`
          STRIP_ASSUME_TAC THENL
           [USE_THEN "rap" (MP_TAC o SPECL [`b2:A`; `w2:A`]) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
            ALL_TAC] THEN
          SUBGOAL_THEN `ehfstage D (E:A->A->bool) b2 w2`
          ASSUME_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b2:A`;
                          `w2:A`; `\k:num. (om:A)`]
              EHFSTAGE_EREC) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          SUBGOAL_THEN `(E:A->A->bool) b2 om` ASSUME_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
                          `sn:A`; `b2:A`] EOMEGA_TRANS) THEN
            ANTS_TAC THENL
             [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
            ALL_TAC] THEN
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `b2:A`;
                        `w2:A`; `u:A`] EHFSTAGE_SUBSET_LCLASS) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL
             [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `\k:num. (om:A)`;
              `r':A`; `y2:A`] HOLDS_VSTEP_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[ehfstage] THEN EXISTS_TAC `\k:num. (om:A)` THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[erec] THEN
  MAP_EVERY EXISTS_TAC [`sn:A`; `rg:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sn:A`]
      EORDINAL_LCLASS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rg:A`; `n:A`;
                  `y:A`] EAPPLY_LCLASS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "rap" (MP_TAC o SPECL [`n:A`; `y:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `y:A`;
                  `\k:num. (om:A)`] EHFSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[]]);;

let EHFSTAGE_LCLASS_BACK = prove
 (`!D (E:A->A->bool) om n y.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        y IN lclass D E /\ ehfstage (lclass D E) E n y
        ==> ehfstage D E n y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?y0. (y0:A) IN D /\ ehfstage D (E:A->A->bool) n y0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `ehfstage (lclass D E) (E:A->A->bool) n y0`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                  `y0:A`] LCLASS_EHFSTAGE_ABS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y0:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSTAGE]; ALL_TAC] THEN
  SUBGOAL_THEN `(n:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA; LCLASS_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) = y0` SUBST1_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `n:A`;
                  `y:A`; `y0:A`] EHFSTAGE_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ASM_REWRITE_TAC[]]);;

let EHFSET_LCLASS_ABS = prove
 (`!D (E:A->A->bool) om h.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om h
        ==> h IN lclass D E /\ ehfset (lclass D E) E om h`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D /\ (h:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN; ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `eomega (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?hL. ehfset (lclass D E) (E:A->A->bool) om hL`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(hL:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `(hL:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN lclass D E
        ==> ((E:A->A->bool) u hL <=>
             ?n y. n IN lclass D E /\ y IN lclass D E /\ E n om /\
                   ehfstage (lclass D E) E n y /\ E u y)`
  (LABEL_TAC "hLch") THENL [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN D
        ==> ((E:A->A->bool) u h <=>
             ?n y. n IN D /\ y IN D /\ E n om /\
                   ehfstage D E n y /\ E u y)`
  (LABEL_TAC "hch") THENL [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `(h:A) = hL` SUBST1_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
      check (fun a -> concl a = `model D (E:A->A->bool) ZF_AX`)) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN
    USE_THEN "hch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `y:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `ehfstage (lclass D E) (E:A->A->bool) n y`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                      `y:A`] LCLASS_EHFSTAGE_ABS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(n:A) IN lclass D E /\ (y:A) IN lclass D E /\
        (u:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER; LCLASS_EHFSTAGE]; ALL_TAC] THEN
      USE_THEN "hLch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "hLch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) u hL`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `y:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(n:A) IN D /\ (y:A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      SUBGOAL_THEN `ehfstage D (E:A->A->bool) n y` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                      `y:A`] EHFSTAGE_LCLASS_BACK) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Comparison of the satisfaction body between the model and its             *)
(* constructible class, over the L-satisfaction universe (codes in the same  *)
(* hf set, assignments in the constructible part of the function space,      *)
(* bits in the same two).  L is closed under function update (build the      *)
(* update in the L-model, transfer, identify by uniqueness).  Membership in  *)
(* the L-satisfaction universe u2L of a chained pair amounts to membership   *)
(* in the D-universe plus constructibility of the assignment.  The five      *)
(* tag-cases transfer: atomic ones by absoluteness of enat/eapply/eopair     *)
(* (witnesses are constructible by transitivity), the imp and all cases      *)
(* against verdict-transfer hypotheses in both directions (the backward one  *)
(* conditioned on code IN hf, constructible assignment, bit IN two, which    *)
(* the omega induction will discharge); the esatall case moves updates       *)
(* across with EUPDATE_LCLASS/LCLASS_EUPDATE.  Components of hf codes are    *)
(* again hf codes (V-stage transitivity), so subcode side conditions         *)
(* propagate, and the dispatcher ESATBODY_RESTRICT glues the five cases      *)
(* after decomposing the pair via ESATUNIV_PAIR_EXISTS in the L-model.       *)
(* ------------------------------------------------------------------------- *)

let LCLASS_EUPDATE = prove
 (`!D (E:A->A->bool) s a u s'.
        model D E ZF_AX /\ s IN lclass D E /\ a IN lclass D E /\
        u IN lclass D E /\ eupdate D E s a u s'
        ==> s' IN lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?s2. eupdate (lclass D E) (E:A->A->bool) s a u s2`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EUPDATE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(s2:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[eupdate]; ALL_TAC] THEN
  SUBGOAL_THEN `eupdate D (E:A->A->bool) s a u s2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `a:A`; `u:A`;
                  `s2:A`] EUPDATE_LCLASS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(s':A) = s2` SUBST1_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `a:A`; `u:A`;
                  `s':A`; `s2:A`] EUPDATE_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ASM_REWRITE_TAC[]]);;

let ESATUNIV_PAIR_EXISTS_F = prove
 (`!D (E:A->A->bool) om x hf vs two u2 p.
        model D E zfw_ax /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\ p IN D /\ E p u2
        ==> ?c s b cs. c IN D /\ s IN D /\ b IN D /\ cs IN D /\
                       E c hf /\ E s vs /\ E b two /\
                       eopair D E c s cs /\ eopair D E cs b p`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatuniv] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "esatuniv")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `hf':A`
    (X_CHOOSE_THEN `vs':A` (X_CHOOSE_THEN `cs2u:A`
      (X_CHOOSE_THEN `two':A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf':A) = hf` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSET_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs':A) = vs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(two':A) = two` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ENAT_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?cs bt. (cs:A) IN D /\ (bt:A) IN D /\ E cs cs2u /\
            E bt two /\ eopair D (E:A->A->bool) cs bt p`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cs2u:A`; `two:A`;
      `u2:A`; `p:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) p u2` THEN REWRITE_TAC[th]) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `cs:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `bt:A` THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?c s. (c:A) IN D /\ (s:A) IN D /\ E c hf /\
          E s vs /\ eopair D (E:A->A->bool) c s cs`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`;
      `cs2u:A`; `cs:A`] ECROSS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) cs cs2u` THEN REWRITE_TAC[th]) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `c:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `s:A` THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `s:A`; `bt:A`; `cs:A`] THEN
  ASM_REWRITE_TAC[]);;

let ESATUNIV_PAIR_EXISTS = prove
 (`!D (E:A->A->bool) om x hf vs two u2 p.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\ p IN D /\ E p u2
        ==> ?c s b cs. c IN D /\ s IN D /\ b IN D /\ cs IN D /\
                       E c hf /\ E s vs /\ E b two /\
                       eopair D E c s cs /\ eopair D E cs b p`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESATUNIV_PAIR_EXISTS_F));;

let ESATUNIV_LCLASS_MEMBER = prove
 (`!D (E:A->A->bool) om x hf vs two u2 vsL u2L c s b cs p.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        efuns (lclass D E) E om x vsL /\
        esatuniv (lclass D E) E x u2L /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p
        ==> (E p u2L <=> E p u2 /\ s IN lclass D E)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (om:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `eomega (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(hf:A) IN lclass D E /\ ehfset (lclass D E) (E:A->A->bool) om hf`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSET_LCLASS_ABS]; ALL_TAC] THEN
  SUBGOAL_THEN `(two:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
  SUBGOAL_THEN `enat (lclass D E) (E:A->A->bool) 2 two`
  ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `om:A`;
                  `x:A`; `hf:A`; `vsL:A`; `two:A`; `u2L:A`; `p:A`]
      ESATUNIV_PAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `s2:A`
      (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `cs2:A`
        STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN
     `(c2:A) IN D /\ (s2:A) IN D /\ (b2:A) IN D /\ (cs2:A) IN D`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) c2 s2 cs2 /\ eopair D E cs2 b2 p`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `(cs2:A) = cs /\ (b2:A) = b`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `(c2:A) = c /\ (s2:A) = s`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s vs /\ s IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `vs:A`; `vsL:A`; `s:A`] LCLASS_EFUNS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `c:A`; `s:A`;
                  `b:A`; `cs:A`; `p:A`] ESATUNIV_PAIR_INTRO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `c:A`; `s:A`;
                  `b:A`; `cs:A`; `p:A`] ESATUNIV_PAIR_DECOMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) s vsL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `vs:A`; `vsL:A`; `s:A`] LCLASS_EFUNS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(c:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
    SUBGOAL_THEN `(b:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `(cs:A) IN lclass D E` ASSUME_TAC THENL
     [MATCH_MP_TAC LCLASS_EOPAIR THEN
      MAP_EVERY EXISTS_TAC [`c:A`; `s:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [MATCH_MP_TAC LCLASS_EOPAIR THEN
      MAP_EVERY EXISTS_TAC [`cs:A`; `b:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair (lclass D E) (E:A->A->bool) c s cs /\
      eopair (lclass D E) E cs b p`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `om:A`;
                  `x:A`; `hf:A`; `vsL:A`; `two:A`; `u2L:A`; `c:A`;
                  `s:A`; `b:A`; `cs:A`; `p:A`]
      ESATUNIV_PAIR_INTRO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let ESATFALSE_RESTRICT = prove
 (`!D (E:A->A->bool) bb tag data.
        model D E ZF_AX /\ bb IN lclass D E /\ tag IN lclass D E /\
        data IN lclass D E
        ==> (esatfalse (lclass D E) E bb tag data <=>
             esatfalse D E bb tag data)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esatfalse] THEN
  ASM_MESON_TAC[ENAT_LCLASS]);;

let ESATMEM_RESTRICT,ESATEQ_RESTRICT = (CONJ_PAIR o prove)
 (`(!D (E:A->A->bool) s bb tag data.
         model D E ZF_AX /\ s IN lclass D E /\ bb IN lclass D E /\
         tag IN lclass D E /\ data IN lclass D E
         ==> (esatmem (lclass D E) E bb s tag data <=>
              esatmem D E bb s tag data)) /\
   (!D (E:A->A->bool) s bb tag data.
         model D E ZF_AX /\ s IN lclass D E /\ bb IN lclass D E /\
         tag IN lclass D E /\ data IN lclass D E
         ==> (esateq (lclass D E) E bb s tag data <=>
              esateq D E bb s tag data))`,
  CONJ_TAC THEN
  (REPEAT STRIP_TAC THEN REWRITE_TAC[esatmem; esateq] THEN
   SUBGOAL_THEN
    `!n. (enat (lclass D E) (E:A->A->bool) n tag <=> enat D E n tag) /\
         (enat (lclass D E) E n bb <=> enat D E n bb)`
   (fun th -> REWRITE_TAC[th]) THENL
    [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
   EQ_TAC THENL
    [DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
       (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `sa:A`
         (X_CHOOSE_THEN `sb:A`
           (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
     ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN
      `(a:A) IN D /\ (b:A) IN D /\ (sa:A) IN D /\ (sb:A) IN D`
     STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
     MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `sa:A`; `sb:A`] THEN
     ASM_REWRITE_TAC[] THEN
     ASM_MESON_TAC[EOPAIR_LCLASS; EAPPLY_LCLASS];
     DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
       (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `sa:A`
         (X_CHOOSE_THEN `sb:A`
           (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
     ASM_REWRITE_TAC[] THEN
     SUBGOAL_THEN `(a:A) IN lclass D E /\ (b:A) IN lclass D E`
     STRIP_ASSUME_TAC THENL
      [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
                     `data:A`] LCLASS_EOPAIR_MEMBERS) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
       ALL_TAC] THEN
     SUBGOAL_THEN `(sa:A) IN lclass D E` ASSUME_TAC THENL
      [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
         GEN_REWRITE_RULE I [eapply] o check (fun th ->
           concl th = `eapply D (E:A->A->bool) s a sa`)) THEN
       SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
        [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `s:A` THEN
         ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
         ALL_TAC] THEN
       MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `sa:A`;
                     `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
       ANTS_TAC THENL
        [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
         SIMP_TAC[]];
       ALL_TAC] THEN
     SUBGOAL_THEN `(sb:A) IN lclass D E` ASSUME_TAC THENL
      [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
         GEN_REWRITE_RULE I [eapply] o check (fun th ->
           concl th = `eapply D (E:A->A->bool) s b sb`)) THEN
       SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
        [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `s:A` THEN
         ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
         ALL_TAC] THEN
       MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `sb:A`;
                     `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
       ANTS_TAC THENL
        [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN];
         SIMP_TAC[]];
       ALL_TAC] THEN
     MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `sa:A`; `sb:A`] THEN
     ASM_REWRITE_TAC[] THEN
     ASM_MESON_TAC[EOPAIR_LCLASS; EAPPLY_LCLASS]]));;

let ESATIMP_RESTRICT = prove
 (`!D (E:A->A->bool) hf vs two rD rL s bb tag data.
        model D E ZF_AX /\ rD IN D /\ rL IN lclass D E /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    c' IN lclass D E /\ s' IN lclass D E /\
                    b' IN lclass D E /\
                    everdict (lclass D E) E c' s' b' rL
                    ==> everdict D E c' s' b' rD) /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    E c' hf /\ E s' vs /\ s' IN lclass D E /\
                    E b' two /\ everdict D E c' s' b' rD
                    ==> everdict (lclass D E) E c' s' b' rL) /\
        s IN lclass D E /\ bb IN lclass D E /\ tag IN lclass D E /\
        data IN lclass D E /\ enat D E 2 two /\ E s vs /\
        (!a b. a IN D /\ b IN D /\ eopair D E a b data
               ==> E a hf /\ E b hf)
        ==> (esatimp (lclass D E) E bb s tag data rL <=>
             esatimp D E bb s tag data rD)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[esatimp] THEN
  SUBGOAL_THEN `(s:A) IN D /\ (bb:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `enat (lclass D E) (E:A->A->bool) 3 tag <=> enat D E 3 tag`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(enat (lclass D E) (E:A->A->bool) 1 bb <=> enat D E 1 bb) /\
    (enat (lclass D E) E 0 bb <=> enat D E 0 bb)`
  (CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THENL
   [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!cx bx. cx IN D /\ bx IN D /\
            cx IN lclass D E /\ bx IN lclass D E /\
            everdict (lclass D E) (E:A->A->bool) cx s bx rL
            ==> everdict D E cx s bx rD`
  (LABEL_TAC "trf") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPECL [`cx:A`; `s:A`; `bx:A`] o
      check (fun th -> is_forall(concl th) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "everdict")) (concl th) &&
        not(can (find_term ((=) `hf:A`)) (concl th)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!cx bx. cx IN D /\ bx IN D /\ E cx hf /\ E bx two /\
            everdict D (E:A->A->bool) cx s bx rD
            ==> everdict (lclass D E) E cx s bx rL`
  (LABEL_TAC "trb") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPECL [`cx:A`; `s:A`; `bx:A`] o
      check (fun th -> is_forall(concl th) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "everdict")) (concl th) &&
        can (find_term ((=) `hf:A`)) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `c1:A`
      (X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `zr:A`
        (X_CHOOSE_THEN `on1:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(c1:A) IN D /\ (c2:A) IN D /\ (zr:A) IN D /\ (on1:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) c1 c2 data`
    ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `enat D (E:A->A->bool) 0 zr /\ enat D E 1 on1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`c1:A`; `c2:A`; `zr:A`; `on1:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN STRIP_ASSUME_TAC o
      check (fun th -> is_disj(concl th))) THENL
     [SUBGOAL_THEN `enat D (E:A->A->bool) 1 bb` ASSUME_TAC THENL
       [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c1:A`; `zr:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `enat D (E:A->A->bool) 1 bb` ASSUME_TAC THENL
       [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c2:A`; `on1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `enat D (E:A->A->bool) 0 bb` ASSUME_TAC THENL
       [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c1:A`; `on1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c2:A`; `zr:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `c1:A`
      (X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `zr:A`
        (X_CHOOSE_THEN `on1:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(c1:A) IN lclass D E /\ (c2:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c1:A`; `c2:A`;
                    `data:A`] LCLASS_EOPAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(zr:A) IN lclass D E /\ (on1:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) c1 hf /\ E c2 hf`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPECL [`c1:A`; `c2:A`] o
        check (fun th -> is_forall(concl th) &&
          can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "eopair")) (concl th) &&
          not(can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "everdict")) (concl th)))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) zr two /\ E on1 two`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `0`; `2`;
                      `zr:A`; `two:A`] ENAT_MEM_LT);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `1`; `2`;
                      `on1:A`; `two:A`] ENAT_MEM_LT)] THEN
      (ANTS_TAC THENL
        [ASM_REWRITE_TAC[] THEN ARITH_TAC; DISCH_THEN ACCEPT_TAC]);
      ALL_TAC] THEN
    SUBGOAL_THEN `eopair (lclass D E) (E:A->A->bool) c1 c2 data`
    ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `enat (lclass D E) (E:A->A->bool) 0 zr /\
