    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`c1:A`; `c2:A`; `zr:A`; `on1:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN STRIP_ASSUME_TAC o
      check (fun th -> is_disj(concl th))) THENL
     [USE_THEN "trb" (MP_TAC o SPECL [`c1:A`; `zr:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "trb" (MP_TAC o SPECL [`c2:A`; `on1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
      USE_THEN "trb" (MP_TAC o SPECL [`c1:A`; `on1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "trb" (MP_TAC o SPECL [`c2:A`; `zr:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]]]);;

let ESATALL_RESTRICT = prove
 (`!D (E:A->A->bool) hf two x rD rL s bb tag data.
        model D E ZF_AX /\ x IN lclass D E /\
        rD IN D /\ rL IN lclass D E /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    c' IN lclass D E /\ s' IN lclass D E /\
                    b' IN lclass D E /\
                    everdict (lclass D E) E c' s' b' rL
                    ==> everdict D E c' s' b' rD) /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    E c' hf /\ s' IN lclass D E /\ E b' two /\
                    everdict D E c' s' b' rD
                    ==> everdict (lclass D E) E c' s' b' rL) /\
        s IN lclass D E /\ bb IN lclass D E /\ tag IN lclass D E /\
        data IN lclass D E /\ enat D E 2 two /\
        (!a b. a IN D /\ b IN D /\ eopair D E a b data
               ==> E a hf /\ E b hf)
        ==> (esatall (lclass D E) E bb s tag data rL x <=>
             esatall D E bb s tag data rD x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[esatall] THEN
  SUBGOAL_THEN `(s:A) IN D /\ (bb:A) IN D /\ (x:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `enat (lclass D E) (E:A->A->bool) 4 tag <=> enat D E 4 tag`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(enat (lclass D E) (E:A->A->bool) 1 bb <=> enat D E 1 bb) /\
    (enat (lclass D E) E 0 bb <=> enat D E 0 bb)`
  (CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THENL
   [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!cx sx bx. cx IN D /\ sx IN D /\ bx IN D /\
               cx IN lclass D E /\ sx IN lclass D E /\
               bx IN lclass D E /\
               everdict (lclass D E) (E:A->A->bool) cx sx bx rL
               ==> everdict D E cx sx bx rD`
  (LABEL_TAC "trf") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPECL [`cx:A`; `sx:A`; `bx:A`] o
      check (fun th -> is_forall(concl th) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "everdict")) (concl th) &&
        not(can (find_term ((=) `hf:A`)) (concl th)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!cx sx bx. cx IN D /\ sx IN D /\ bx IN D /\ E cx hf /\
               sx IN lclass D E /\ E bx two /\
               everdict D (E:A->A->bool) cx sx bx rD
               ==> everdict (lclass D E) E cx sx bx rL`
  (LABEL_TAC "trb") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_ASSUM(MP_TAC o SPECL [`cx:A`; `sx:A`; `bx:A`] o
      check (fun th -> is_forall(concl th) &&
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "everdict")) (concl th) &&
        can (find_term ((=) `hf:A`)) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
      (X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `z0:A`
        (X_CHOOSE_THEN `z1:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `(a:A) IN D /\ (c1:A) IN D /\ (z0:A) IN D /\ (z1:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) a c1 data`
    ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `enat D (E:A->A->bool) 0 z0 /\ enat D E 1 z1`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `c1:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) o
      check (fun th -> is_disj(concl th))) THENL
     [SUBGOAL_THEN `enat D (E:A->A->bool) 1 bb` ASSUME_TAC THENL
       [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
      DISCH_THEN(LABEL_TAC "allL") THEN DISJ1_TAC THEN
      ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      X_GEN_TAC `s':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `(s':A) IN lclass D E` ASSUME_TAC THENL
       [MATCH_MP_TAC LCLASS_EUPDATE THEN
        MAP_EVERY EXISTS_TAC [`s:A`; `a:A`; `u:A`] THEN
