      USE_THEN "trb" (MP_TAC o SPECL [`c1:A`; `s':A`; `z0:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

let EHFSET_PAIR_MEMBERS = prove
 (`!D (E:A->A->bool) om hf a b p.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        a IN D /\ b IN D /\ p IN D /\ eopair D E a b p /\ E p hf
        ==> E a hf /\ E b hf`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN D
        ==> ((E:A->A->bool) u hf <=>
             ?n y. n IN D /\ y IN D /\ E n om /\
                   ehfstage D E n y /\ E u y)`
  (LABEL_TAC "hch") THENL [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?n y. (n:A) IN D /\ (y:A) IN D /\ E n om /\
          ehfstage D (E:A->A->bool) n y /\ E p y`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "hch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) p hf` THEN REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a y /\ E b y` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `y:A`;
                  `a:A`; `b:A`; `p:A`] EOPAIR_VSTAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [USE_THEN "hch" (MP_TAC o SPEC `a:A`);
    USE_THEN "hch" (MP_TAC o SPEC `b:A`)] THEN
  (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_REWRITE_TAC[]));;

let ESATBODY_RESTRICT = prove
 (`!D (E:A->A->bool) om x hf vs two u2 vsL u2L rD rL p.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        efuns (lclass D E) E om x vsL /\
        esatuniv (lclass D E) E x u2L /\
        rD IN D /\ rL IN lclass D E /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    c' IN lclass D E /\ s' IN lclass D E /\
                    b' IN lclass D E /\
                    everdict (lclass D E) E c' s' b' rL
                    ==> everdict D E c' s' b' rD) /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    E c' hf /\ s' IN lclass D E /\ E b' two /\
                    everdict D E c' s' b' rD
                    ==> everdict (lclass D E) E c' s' b' rL) /\
        p IN D /\ E p u2L
        ==> (esatbody (lclass D E) E x rL p <=> esatbody D E x rD p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (om:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `eomega (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(hf:A) IN lclass D E /\ ehfset (lclass D E) (E:A->A->bool) om hf`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSET_LCLASS_ABS]; ALL_TAC] THEN
  SUBGOAL_THEN `(two:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
  SUBGOAL_THEN `enat (lclass D E) (E:A->A->bool) 2 two`
  ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `om:A`;
                `x:A`; `hf:A`; `vsL:A`; `two:A`; `u2L:A`; `p:A`]
    ESATUNIV_PAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
    (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `cs:A`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ (s:A) IN D /\ (b2:A) IN D /\ (cs:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eopair D (E:A->A->bool) c s cs /\ eopair D E cs b2 p`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `vs:A`; `vsL:A`; `s:A`] LCLASS_EFUNS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vsL`))) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `x:A`;
                  `rL:A`; `c:A`; `s:A`; `b2:A`; `cs:A`; `p:A`]
      SATBODY_CASES) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@tag data. h1 h2 h3 +" THEN
    SUBGOAL_THEN `(tag:A) IN D /\ (data:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) tag data c`
    ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) tag hf /\ E data hf`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
                    `tag:A`; `data:A`; `c:A`] EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(tag:A) IN lclass D E /\ (data:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!a b. a IN D /\ b IN D /\ eopair D (E:A->A->bool) a b data
            ==> E a hf /\ E b hf`
    (LABEL_TAC "cmp") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
                    `a:A`; `b:A`; `data:A`] EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
    REWRITE_TAC[esatbody] THEN
    MAP_EVERY EXISTS_TAC [`cs:A`; `b2:A`; `c:A`; `s:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[] THENL
     [DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b2:A`; `tag:A`;
                    `data:A`] ESATFALSE_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATMEM_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATEQ_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`;
                    `two:A`; `rD:A`; `rL:A`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATIMP_RESTRICT) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
        FIRST_ASSUM(MP_TAC o SPECL [`c':A`; `s':A`; `b':A`] o
          check (fun th -> is_forall(concl th) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "everdict")) (concl th) &&
            can (find_term ((=) `hf:A`)) (concl th))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      REPLICATE_TAC 4 DISJ2_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `two:A`;
                    `x:A`; `rD:A`; `rL:A`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATALL_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th])];
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`;
                  `rD:A`; `c:A`; `s:A`; `b2:A`; `cs:A`; `p:A`]
      SATBODY_CASES) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@tag data. h4 h5 h6 +" THEN
    SUBGOAL_THEN `(E:A->A->bool) tag hf /\ E data hf`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
                    `tag:A`; `data:A`; `c:A`] EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(tag:A) IN lclass D E /\ (data:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair (lclass D E) (E:A->A->bool) tag data c`
    ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!a b. a IN D /\ b IN D /\ eopair D (E:A->A->bool) a b data
            ==> E a hf /\ E b hf`
    (LABEL_TAC "cmp") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
                    `a:A`; `b:A`; `data:A`] EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
    REWRITE_TAC[esatbody] THEN
    MAP_EVERY EXISTS_TAC [`cs:A`; `b2:A`; `c:A`; `s:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[] THENL
     [DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b2:A`; `tag:A`;
                    `data:A`] ESATFALSE_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATMEM_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATEQ_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `vs:A`;
                    `two:A`; `rD:A`; `rL:A`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATIMP_RESTRICT) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
        FIRST_ASSUM(MP_TAC o SPECL [`c':A`; `s':A`; `b':A`] o
          check (fun th -> is_forall(concl th) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "everdict")) (concl th) &&
            can (find_term ((=) `hf:A`)) (concl th))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      REPLICATE_TAC 4 DISJ2_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `two:A`;
                    `x:A`; `rD:A`; `rL:A`; `s:A`; `b2:A`;
                    `tag:A`; `data:A`] ESATALL_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])]]);;

(* ------------------------------------------------------------------------- *)
(* Both satisfaction-stage hierarchies packaged as internal recursion        *)
(* graphs on omega (the erecres of satstep_form at om in each model), so     *)
(* that the restriction induction below can speak about them with            *)
(* apply_form alone.  The L-graph is constructible, and its D-level apply    *)
(* relation captures exactly the L-stages (membership of the components in   *)
(* lclass comes for free from transitivity).                                 *)
(* ------------------------------------------------------------------------- *)

let ESATSTAGE_GRAPHS = prove
 (`!D (E:A->A->bool) om x u2 u2L.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        esatuniv D E x u2 /\ esatuniv (lclass D E) E x u2L
        ==> ?FD FL.
              FD IN D /\ FL IN lclass D E /\
              (!n t. n IN D /\ t IN D
                     ==> (eapply D E FD n t <=>
                          E n om /\ esatstage D E x n t)) /\
              (!n t. n IN D /\ t IN D
                     ==> (eapply D E FL n t <=>
                          E n om /\ t IN lclass D E /\
                          esatstage (lclass D E) E x n t))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (om:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D /\ (u2L:A) IN lclass D E`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A))))`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
    REWRITE_TAC[VALMOD] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (u2L:A)) ((2 |-> x) (\k:num. (om:A)))) /\
    valuation (lclass D E) ((3 |-> (u2L:A)) ((2 |-> x)
       (\k:num. (om:A))))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
    REWRITE_TAC[VALMOD] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?FD. erecres D (E:A->A->bool) satstep_form
           ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A)))) om FD`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[SATSTEP_QFUN; SATSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FD:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. w IN D
        ==> ((E:A->A->bool) w FD <=>
             ?b y. b IN D /\ y IN D /\ E b om /\
                   erec D E satstep_form
                     ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A))))
                     b y /\
                   eopair D E b y w)`
  (LABEL_TAC "fdch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n t. n IN D /\ t IN D
          ==> (eapply D (E:A->A->bool) FD n t <=>
               E n om /\ esatstage D E x n t)`
  (LABEL_TAC "fdap") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `t:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u2:A`;
                  `n:A`; `t:A`;
                  `(3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A)))`]
      ESATSTAGE_EREC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
        GEN_REWRITE_RULE I [eapply]) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "fdch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z FD`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b:A) = n /\ (y:A) = t`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `t:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "fdch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `t:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?FL. erecres (lclass D E) (E:A->A->bool) satstep_form
           ((3 |-> (u2L:A)) ((2 |-> x) (\k:num. (om:A)))) om FL`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[SATSTEP_QFUN; SATSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FL:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `(FL:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. w IN lclass D E
        ==> ((E:A->A->bool) w FL <=>
             ?b y. b IN lclass D E /\ y IN lclass D E /\ E b om /\
                   erec (lclass D E) E satstep_form
                     ((3 |-> (u2L:A)) ((2 |-> x) (\k:num. (om:A))))
                     b y /\
                   eopair (lclass D E) E b y w)`
  (LABEL_TAC "flch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n t. n IN lclass D E /\ t IN lclass D E
          ==> (eapply (lclass D E) (E:A->A->bool) FL n t <=>
               E n om /\ esatstage (lclass D E) E x n t)`
  (LABEL_TAC "flapL") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `t:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `x:A`;
                  `u2L:A`; `n:A`; `t:A`;
                  `(3 |-> (u2L:A)) ((2 |-> x) (\k:num. (om:A)))`]
      ESATSTAGE_EREC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
        GEN_REWRITE_RULE I [eapply]) THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "flch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z FL`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `y:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b:A) = n /\ (y:A) = t`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`]
          EOPAIR_INJ) THEN ASM_MESON_TAC[];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                    `n:A`; `t:A`] EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "flch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `t:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n t. n IN D /\ t IN D
          ==> (eapply D (E:A->A->bool) FL n t <=>
               E n om /\ t IN lclass D E /\
               esatstage (lclass D E) E x n t)`
  (LABEL_TAC "flap") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `t:A`] THEN STRIP_TAC THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(n:A) IN lclass D E /\ (t:A) IN lclass D E`
      STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
          GEN_REWRITE_RULE I [eapply] o check (fun a ->
            concl a = `eapply D (E:A->A->bool) FL n t`)) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
         [MATCH_MP_TAC LCLASS_MEMBER THEN EXISTS_TAC `FL:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `t:A`;
                      `z:A`] LCLASS_EOPAIR_MEMBERS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `eapply (lclass D E) (E:A->A->bool) FL n t`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `FL:A`; `n:A`;
                      `t:A`] EAPPLY_LCLASS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "flapL" (MP_TAC o SPECL [`n:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a ->
            concl a = `eapply (lclass D E) (E:A->A->bool) FL n t`))) THEN
      SIMP_TAC[];
      STRIP_TAC THEN
      SUBGOAL_THEN `(n:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply (lclass D E) (E:A->A->bool) FL n t`
      ASSUME_TAC THENL
       [USE_THEN "flapL" (MP_TAC o SPECL [`n:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `FL:A`; `n:A`;
                    `t:A`] EAPPLY_LCLASS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`FD:A`; `FL:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* One stage of the restriction: given that verdicts transfer between the    *)
(* two stage graphs at n (forward for constructible triples, backward under  *)
(* the hf/vs/two conditions), the L-stage at n consists of exactly the       *)
(* members of the D-stage that lie in the L-satisfaction universe.           *)
(* ------------------------------------------------------------------------- *)

let ESATSTAGE_RESTRICT_LEMMA = prove
 (`!D (E:A->A->bool) om x hf vs two u2 vsL u2L n t tL.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        efuns (lclass D E) E om x vsL /\
        esatuniv (lclass D E) E x u2L /\
        n IN lclass D E /\ eordinal D E n /\
        t IN D /\ esatstage D E x n t /\
        tL IN lclass D E /\ esatstage (lclass D E) E x n tL /\
        (!rD rL.
             rD IN D /\ rL IN lclass D E /\
             (!w. w IN D
                  ==> (E w rD <=>
                       ?b y. b IN D /\ y IN D /\ E b n /\
                             esatstage D E x b y /\
                             eopair D E b y w)) /\
             (!w. w IN lclass D E
                  ==> (E w rL <=>
                       ?b y. b IN lclass D E /\ y IN lclass D E /\
                             E b n /\
                             esatstage (lclass D E) E x b y /\
                             eopair (lclass D E) E b y w))
             ==> (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                             c' IN lclass D E /\ s' IN lclass D E /\
                             b' IN lclass D E /\
                             everdict (lclass D E) E c' s' b' rL
                             ==> everdict D E c' s' b' rD) /\
                 (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                             E c' hf /\ s' IN lclass D E /\
                             E b' two /\
                             everdict D E c' s' b' rD
                             ==> everdict (lclass D E) E c' s' b' rL))
        ==> !p. p IN D ==> (E p tL <=> E p t /\ E p u2L)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (n:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) n`
  ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
    ESATSTAGE_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2' rD. h1 h2 rdch tch" THEN
  SUBGOAL_THEN `u2':A = u2` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_UNIQUE]; ALL_TAC] THEN
  MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `x:A`;
                `n:A`; `tL:A`] ESATSTAGE_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2L' rL. h3 h4 rlch tlch" THEN
  SUBGOAL_THEN `u2L':A = u2L` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `x:A`;
                  `u2L':A`; `u2L:A`] ESATUNIV_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPECL [`rD:A`; `rL:A`] o
    check (fun th -> is_forall(concl th) &&
      can (find_term (fun tm -> is_const tm &&
        fst(dest_const tm) = "everdict")) (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "trf") (LABEL_TAC "trb")) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(esatbody (lclass D E) (E:A->A->bool) x rL p <=>
     esatbody D E x rD p) \/ ~(E p u2L)`
  MP_TAC THENL
   [ASM_CASES_TAC `(E:A->A->bool) p u2L` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`; `u2L:A`;
                  `rD:A`; `rL:A`; `p:A`] ESATBODY_RESTRICT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(E:A->A->bool) p u2L /\
      esatbody (lclass D E) E x rL p`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "tlch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) p tL` THEN REWRITE_TAC[th]) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `esatbody D (E:A->A->bool) x rD p` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) p u2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                    `om:A`; `x:A`; `hf:A`; `vsL:A`; `two:A`;
                    `u2L:A`; `p:A`] ESATUNIV_PAIR_EXISTS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[LCLASS_EOMEGA; EOMEGA_LCLASS;
                      EHFSET_LCLASS_ABS; LCLASS_ENAT; ENAT_LCLASS];
        ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
        (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `cs:A`
          STRIP_ASSUME_TAC)))) THEN
      SUBGOAL_THEN
       `(c:A) IN D /\ (s:A) IN D /\ (b2:A) IN D /\ (cs:A) IN D`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      SUBGOAL_THEN
       `eopair D (E:A->A->bool) c s cs /\ eopair D E cs b2 p`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                    `u2L:A`; `c:A`; `s:A`; `b2:A`; `cs:A`; `p:A`]
        ESATUNIV_LCLASS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) p u2L`))) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "tch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(E:A->A->bool) p u2 /\ esatbody D E x rD p`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "tch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) p t` THEN REWRITE_TAC[th]) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `esatbody (lclass D E) (E:A->A->bool) x rL p`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "tlch" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The restriction theorem and satisfaction absoluteness.  The induction     *)
(* property (over the verdict stage index at slot 20) is expressed purely    *)
(* with apply_form against the two precomputed stage graphs (slots 16,17)    *)
(* and the L-universe (slot 18): any L-stage and D-stage at the same index   *)
(* satisfy tL = t INTER u2L.  Base: both stage graphs at the empty ordinal   *)
(* are empty, so verdicts are impossible.  Step: each verdict over the       *)
(* graph at suc m lives in some stage below, moves up to the stage at m by   *)
(* cumulativity (in the appropriate model), crosses by the induction         *)
(* hypothesis, and is reinjected at index m; the per-stage lemma with the    *)
(* body comparison ESATBODY_RESTRICT then gives the successor instance.      *)
(* Finally ESAT_ABSOLUTE: for hf codes and constructible assignments in the  *)
(* function space, internal satisfaction in the L-model agrees with the      *)
(* real one -- witnessing stages transfer through the restriction theorem    *)
(* in both directions.                                                       *)
(* ------------------------------------------------------------------------- *)

let resprop_form = new_definition
  `resprop_form =
     !! 21 (!! 22 (!! 23
        ((apply_form 16 20 21 && apply_form 17 20 22) -->
         ((23 %% 21) <-> (23 %% 22) && (23 %% 18)))))`;;

let HOLDS_RESPROP_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v resprop_form <=>
             !tL. tL IN D
                  ==> !t. t IN D
                          ==> !p. p IN D
                  ==> eapply D E (v 16) (v 20) tL /\
                      eapply D E (v 17) (v 20) t
                      ==> (E p tL <=> E p t /\ E p (v 18)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. a IN D /\ b IN D /\ c IN D
        ==> (holds D E ((23 |-> (c:A)) ((22 |-> b) ((21 |-> a) v)))
               (apply_form 16 20 21) <=>
             eapply D (E:A->A->bool) (v 16) (v 20) a)`
  (LABEL_TAC "ap1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(23 |-> (c:A)) ((22 |-> (b:A)) ((21 |-> (a:A)) v))`;
      `16`; `20`; `21`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. a IN D /\ b IN D /\ c IN D
        ==> (holds D E ((23 |-> (c:A)) ((22 |-> b) ((21 |-> a) v)))
               (apply_form 17 20 22) <=>
             eapply D (E:A->A->bool) (v 17) (v 20) b)`
  (LABEL_TAC "ap2") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(23 |-> (c:A)) ((22 |-> (b:A)) ((21 |-> (a:A)) v))`;
      `17`; `20`; `22`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[resprop_form; holds; HOLDS_AND; HOLDS_IFF] THEN
  USE_THEN "ap1" (fun th1 ->
    USE_THEN "ap2" (fun th2 -> ASM_SIMP_TAC[th1; th2])) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[]);;

let ESATSTAGE_RESTRICT = prove
 (`!D (E:A->A->bool) om x hf vs two u2 vsL u2L.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        efuns (lclass D E) E om x vsL /\
        esatuniv (lclass D E) E x u2L
        ==> !n. n IN D /\ E n om
                ==> !t tL. t IN D /\ esatstage D E x n t /\
                           tL IN lclass D E /\
                           esatstage (lclass D E) E x n tL
                           ==> !p. p IN D
                                   ==> (E p tL <=> E p t /\ E p u2L)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (om:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2L:A) IN D /\ (u2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; ESATUNIV_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `u2:A`;
                `u2L:A`] ESATSTAGE_GRAPHS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@FD FL. h1 h2 fdap flap" THEN
  SUBGOAL_THEN `(FL:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((18 |-> (u2L:A)) ((17 |-> FD) ((16 |-> FL) v0)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n. (n:A) IN D
        ==> (holds D E ((20 |-> n) ((18 |-> (u2L:A)) ((17 |-> FD)
               ((16 |-> FL) v0)))) resprop_form <=>
             !tL. tL IN D
                  ==> !t. t IN D
                          ==> !p. p IN D
                  ==> eapply D E FL n tL /\ eapply D E FD n t
                      ==> (E p tL <=> E p t /\ E p u2L))`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(20 |-> (n:A)) ((18 |-> (u2L:A)) ((17 |-> FD)
         ((16 |-> FL) v0)))`] HOLDS_RESPROP_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `resprop_form`;
                `20`;
                `(18 |-> (u2L:A)) ((17 |-> FD) ((16 |-> FL) v0))`]
     EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `tL:A` THEN DISCH_TAC THEN
      X_GEN_TAC `t:A` THEN DISCH_TAC THEN
      X_GEN_TAC `p:A` THEN DISCH_TAC THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) e om /\ tL IN lclass D E /\
        esatstage (lclass D E) E x e tL`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "flap" (MP_TAC o SPECL [`e:A`; `tL:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `esatstage D (E:A->A->bool) x e t`
      ASSUME_TAC THENL
       [USE_THEN "fdap" (MP_TAC o SPECL [`e:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
            check (fun a ->
              concl a = `eapply D (E:A->A->bool) FD e t`))) THEN
        SIMP_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(e:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                    `u2L:A`; `e:A`; `t:A`; `tL:A`]
        ESATSTAGE_RESTRICT_LEMMA) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        MAP_EVERY X_GEN_TAC [`rD:A`; `rL:A`] THEN
        INTRO_TAC "h3 h4 rdch rlch" THEN
        CONJ_TAC THENL
         [MAP_EVERY X_GEN_TAC [`c':A`; `s':A`; `b':A`] THEN
          STRIP_TAC THEN
          MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                        `x:A`; `e:A`; `rL:A`; `c':A`; `s':A`;
                        `b':A`] EVERDICT_STAGE) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(X_CHOOSE_THEN `bL:A` (X_CHOOSE_THEN `yL:A`
            (X_CHOOSE_THEN `csw:A` (X_CHOOSE_THEN `w:A`
              STRIP_ASSUME_TAC)))) THEN
          SUBGOAL_THEN `(bL:A) IN D` ASSUME_TAC THENL
           [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
          FIRST_ASSUM(MP_TAC o SPEC `bL:A` o CONJUNCT2 o
            GEN_REWRITE_RULE I [eempty] o check (fun th ->
              can (find_term (fun tm -> is_const tm &&
                fst(dest_const tm) = "eempty")) (concl th))) THEN
          ASM_REWRITE_TAC[];
          MAP_EVERY X_GEN_TAC [`c':A`; `s':A`; `b':A`] THEN
          STRIP_TAC THEN
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
