     SUBGOAL_THEN `(csw:A) IN lclass D E` ASSUME_TAC THENL
      [MATCH_MP_TAC LCLASS_EOPAIR THEN
       MAP_EVERY EXISTS_TAC [`c':A`; `s':A`] THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
      [MATCH_MP_TAC LCLASS_EOPAIR THEN
