  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC])]);;

let ESAT_ABSOLUTE = prove
 (`!D (E:A->A->bool) om x hf vs two u2 vsL u2L c s.
        model D E ZF_AX /\ eomega D E om /\ x IN lclass D E /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\
        efuns (lclass D E) E om x vsL /\
        esatuniv (lclass D E) E x u2L /\
        c IN D /\ s IN D /\ E c hf /\ E s vs /\ s IN lclass D E
        ==> (esat (lclass D E) E x c s <=> esat D E x c s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (om:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D; EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `eomega (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
  REWRITE_TAC[esat] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
      (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
          STRIP_ASSUME_TAC)))))) THEN
    SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                    `om':A`; `om:A`] EOMEGA_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(n:A) IN D /\ (t:A) IN D /\ (z1:A) IN D /\ (cs:A) IN D /\
      (w:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) c s cs /\ eopair D E cs z1 w`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `enat D (E:A->A->bool) 1 z1` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?tD. (tD:A) IN D /\ esatstage D (E:A->A->bool) x n tD`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ESATSTAGE_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w tD` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                    `u2L:A`] ESATSTAGE_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`tD:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) w t` THEN REWRITE_TAC[th]) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `n:A`; `tD:A`; `z1:A`; `cs:A`; `w:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
      (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
          STRIP_ASSUME_TAC)))))) THEN
    SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    SUBGOAL_THEN `(n:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) n`
    ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?tL. (tL:A) IN lclass D E /\
           esatstage (lclass D E) (E:A->A->bool) x n tL`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                    `x:A`; `n:A`] ESATSTAGE_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(tL:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`;
                    `t:A`] ESATSTAGE_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@u2'' r''. h1 h2 _ tch" THEN
      SUBGOAL_THEN `u2'':A = u2` SUBST_ALL_TAC THENL
       [ASM_MESON_TAC[ESATUNIV_UNIQUE]; ALL_TAC] THEN
      USE_THEN "tch" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) w t` THEN REWRITE_TAC[th]) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w u2L` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                    `u2L:A`; `c:A`; `s:A`; `z1:A`; `cs:A`; `w:A`]
        ESATUNIV_LCLASS_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w tL` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                    `u2L:A`] ESATSTAGE_RESTRICT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`t:A`; `tL:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(z1:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
    SUBGOAL_THEN `(cs:A) IN lclass D E` ASSUME_TAC THENL
     [MATCH_MP_TAC LCLASS_EOPAIR THEN
      MAP_EVERY EXISTS_TAC [`c:A`; `s:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(w:A) IN lclass D E` ASSUME_TAC THENL
     [MATCH_MP_TAC LCLASS_EOPAIR THEN
      MAP_EVERY EXISTS_TAC [`cs:A`; `z1:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair (lclass D E) (E:A->A->bool) c s cs /\
      eopair (lclass D E) E cs z1 w`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOPAIR_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `enat (lclass D E) (E:A->A->bool) 1 z1`
    ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `n:A`; `tL:A`; `z1:A`; `cs:A`; `w:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Definability is absolute.  A satisfaction fact pins its code into hf and  *)
(* its assignment into the function space (ESAT_MEMBERS).  Then              *)
(* EDEFMEM_ABSOLUTE: edefmem (lclass D E) E x y <=> edefmem D E x y for      *)
(* constructible x,y: an L-witness is a D-witness directly (satisfaction     *)
(* transfers by ESAT_ABSOLUTE, with ESAT_MEMBERS supplying the               *)
(* hf/function-space memberships on whichever side is inhabited); conversely *)
(* a D-witness assignment s -- possibly not constructible -- is replaced by  *)
(* the padded constructible assignment st agreeing with s below the V-stage  *)
(* bound nc of the witness code (the code is an hf set, witnessed by any     *)
(* actual member of the nonempty y), and per element u the two updated       *)
(* assignments s[0:=u], st[0:=u] still agree below nc, so ESAT_AGREE and     *)
(* then ESAT_ABSOLUTE carry the defining property across.  The empty case is *)
(* covered by the eempty disjunct.                                           *)
(* ------------------------------------------------------------------------- *)

let ESAT_MEMBERS_F = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s.
        model D E zfw_ax /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\ c IN D /\ s IN D /\
        esat D E x c s
        ==> E c hf /\ E s vs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esat] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "esat")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
    (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
      (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE_F]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS_F]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`;
                  `t:A`] ESATSTAGE_MEMBER_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@u2'' r''. h1 h2 _ tch" THEN
    SUBGOAL_THEN `u2'':A = u2` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ESATUNIV_UNIQUE_F]; ALL_TAC] THEN
    USE_THEN "tch" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `(E:A->A->bool) w t` THEN REWRITE_TAC[th]) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `c:A`; `s:A`; `z1:A`;
                `cs:A`; `w:A`] ESATUNIV_PAIR_DECOMP_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SIMP_TAC[]);;

let ESAT_MEMBERS = prove
 (`!D (E:A->A->bool) om x hf vs two u2 c s.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        ehfset D E om hf /\ efuns D E om x vs /\ enat D E 2 two /\
        esatuniv D E x u2 /\ c IN D /\ s IN D /\
        esat D E x c s
        ==> E c hf /\ E s vs`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ESAT_MEMBERS_F));;

let EDEFMEM_ABSOLUTE = prove
 (`!D (E:A->A->bool) x y.
        model D E ZF_AX /\ x IN lclass D E /\ y IN lclass D E
        ==> (edefmem (lclass D E) E x y <=> edefmem D E x y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN D /\ (y:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `?om. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `eomega (lclass D E) (E:A->A->bool) om`
  ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `?hf. ehfset D (E:A->A->bool) om hf`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(hf:A) IN lclass D E /\ ehfset (lclass D E) (E:A->A->bool) om hf`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSET_LCLASS_ABS]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `?vs. efuns D (E:A->A->bool) om x vs`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EFUNS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN `?two. enat D (E:A->A->bool) 2 two`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(two:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2. esatuniv D (E:A->A->bool) x u2`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESATUNIV_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?vsL. efuns (lclass D E) (E:A->A->bool) om x vsL`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `om:A`; `x:A`] EFUNS_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(vsL:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?u2L. esatuniv (lclass D E) (E:A->A->bool) x u2L`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `x:A`] ESATUNIV_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!sx. sx IN D
         ==> ((E:A->A->bool) sx vsL <=> E sx vs /\ sx IN lclass D E)`
  (LABEL_TAC "vsm") THENL
   [X_GEN_TAC `sx:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `vs:A`; `vsL:A`; `sx:A`] LCLASS_EFUNS_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[edefmem] THEN
  SUBGOAL_THEN
   `(esubset (lclass D E) (E:A->A->bool) y x <=> esubset D E y x) /\
    (eempty (lclass D E) E y <=> eempty D E y)`
  (CONJUNCTS_THEN (fun th -> REWRITE_TAC[th])) THENL
   [ASM_MESON_TAC[ESUBSET_LCLASS; EEMPTY_LCLASS]; ALL_TAC] THEN
  EQ_TAC THENL
   [(DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (fun th -> DISJ1_TAC THEN ACCEPT_TAC th) MP_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `omw:A` (X_CHOOSE_THEN `vsw:A`
    (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
      (X_CHOOSE_THEN `z0:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `omw:A = om` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `omw:A`; `om:A`] EOMEGA_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `vsw:A = vsL` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `om:A`; `x:A`; `vsw:A`; `vsL:A`]
      EFUNS_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISJ2_TAC THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ (s:A) IN D /\ (z0:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
   [USE_THEN "vsm" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vsL`))) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `enat D (E:A->A->bool) 0 z0` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `vs:A`; `c:A`; `s:A`; `z0:A`] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `u:A` o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "eupdate")) (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@s''. h1 h2 ifL" THEN
  SUBGOAL_THEN `(s'':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `eupdate D (E:A->A->bool) s z0 u s''`
  ASSUME_TAC THENL [ASM_MESON_TAC[EUPDATE_LCLASS]; ALL_TAC] THEN
  EXISTS_TAC `s'':A` THEN ASM_REWRITE_TAC[] THEN
    EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) c hf /\ E s'' vsL`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                    `om:A`; `x:A`; `hf:A`; `vsL:A`; `two:A`;
                    `u2L:A`; `c:A`; `s'':A`] ESAT_MEMBERS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ENAT_LCLASS];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s'' vs` ASSUME_TAC THENL
     [USE_THEN "vsm" (MP_TAC o SPEC `s'':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) s'' vsL`))) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                  `u2L:A`; `c:A`; `s'':A`] ESAT_ABSOLUTE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) c hf /\ E s'' vs`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
                    `om:A`; `x:A`; `hf:A`; `vs:A`; `two:A`;
                    `u2:A`; `c:A`; `s'':A`] ESAT_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                  `u2L:A`; `c:A`; `s'':A`] ESAT_ABSOLUTE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    FIRST_ASSUM ACCEPT_TAC]);
    (DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (fun th -> DISJ1_TAC THEN ACCEPT_TAC th) MP_TAC) THEN
  DISCH_THEN(X_CHOOSE_THEN `omw:A` (X_CHOOSE_THEN `vsw:A`
    (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
      (X_CHOOSE_THEN `z0:A`
        (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
  SUBGOAL_THEN `omw:A = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `vsw:A = vs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE]; ALL_TAC] THEN
  ASM_CASES_TAC `eempty D (E:A->A->bool) y` THENL
   [DISJ1_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISJ2_TAC THEN
  SUBGOAL_THEN `?d0. (d0:A) IN D /\ (E:A->A->bool) d0 y`
  STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `~eempty D (E:A->A->bool) y` THEN
    REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d0 x` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `d0:A` o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "eupdate")) (concl th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@s0. h3 h4 +" THEN
  DISCH_THEN(fun th ->
    MP_TAC(REWRITE_RULE[ASSUME `(E:A->A->bool) d0 y`] th)) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c hf /\ E s0 vs`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `hf:A`; `vs:A`; `two:A`; `u2:A`; `c:A`; `s0:A`]
      ESAT_MEMBERS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?nc ync. (nc:A) IN D /\ (ync:A) IN D /\ (E:A->A->bool) nc om /\
             ehfstage D E nc ync /\ E c ync`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `c:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [ehfset] o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "ehfset")) (concl th) &&
        not(can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "lclass")) (concl th)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(REWRITE_RULE[ASSUME `(E:A->A->bool) c hf`] th)) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `nc:A` THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `ync:A` THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nc` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `vs:A`;
                `s:A`; `nc:A`; `d0:A`] PADDED_ASSIGNMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@st. h5 h6 pag" THEN
  SUBGOAL_THEN `(st:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) st vsL` ASSUME_TAC THENL
   [USE_THEN "vsm" (MP_TAC o SPEC `st:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z0:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_ENAT]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EHFSET]; ALL_TAC] THEN
  SUBGOAL_THEN `enat (lclass D E) (E:A->A->bool) 0 z0`
  ASSUME_TAC THENL [ASM_MESON_TAC[ENAT_LCLASS]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `vsL:A`; `c:A`; `st:A`; `z0:A`] THEN
  ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPEC `u:A` o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "eupdate")) (concl th) &&
    not(can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "lclass")) (concl th)))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@su. h7 h8 ifD" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `st:A`; `z0:A`; `u:A`]
    EUPDATE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `s'':A`) THEN
  SUBGOAL_THEN `(s'':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(s'':A) IN lclass D E` ASSUME_TAC THENL
   [MATCH_MP_TAC LCLASS_EUPDATE THEN
    MAP_EVERY EXISTS_TAC [`st:A`; `z0:A`; `u:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eupdate (lclass D E) (E:A->A->bool) st z0 u s''`
  ASSUME_TAC THENL [ASM_MESON_TAC[EUPDATE_LCLASS]; ALL_TAC] THEN
  EXISTS_TAC `s'':A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) z0 om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) su vs` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `vs:A`; `s:A`; `z0:A`; `u:A`; `su:A`]
      EUPDATE_FUNS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s'' vs` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                  `vs:A`; `st:A`; `z0:A`; `u:A`; `s'':A`]
      EUPDATE_FUNS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(su:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i IN D
        ==> !w. w IN D
                ==> E i nc
                    ==> (eapply D (E:A->A->bool) su i w <=>
                         eapply D E s'' i w)`
  (LABEL_TAC "agr2") THENL
   [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `st:A`;
                  `z0:A`; `u:A`; `su:A`; `s'':A`; `i:A`; `w:A`]
      EUPDATE_AGREE) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN ASM_CASES_TAC `(i:A) = z0` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "pag" (MP_TAC o SPECL [`i:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `esat D (E:A->A->bool) x c su <=> esat D E x c s''`
  (LABEL_TAC "ag") THENL
   [EQ_TAC THENL
     [DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `nc:A`;
                    `ync:A`; `c:A`; `su:A`; `s'':A`]
        ESAT_AGREE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(C MP (ASSUME
        `esat D (E:A->A->bool) x c su`) th)) THEN
      SIMP_TAC[];
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `nc:A`;
                    `ync:A`; `c:A`; `s'':A`; `su:A`]
        ESAT_AGREE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `i:A` THEN DISCH_TAC THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        USE_THEN "agr2" (MP_TAC o SPEC `i:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]);
        ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(C MP (ASSUME
        `esat D (E:A->A->bool) x c s''`) th)) THEN
      SIMP_TAC[]];
    ALL_TAC] THEN
  USE_THEN "ifD" (fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "ag" (fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsL:A`;
                `u2L:A`; `c:A`; `s'':A`] ESAT_ABSOLUTE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]))]);;

(* ------------------------------------------------------------------------- *)
(* The constructible hierarchy is absolute, and L |= V = L.  The transfinite *)
(* induction runs inside the model via EORDINAL_INDUCT on the object formula *)
(* labs_form, which pairs the real L-recursion (rec_form lstep_form          *)
(* at slot 4, output 5) against the L-model's own L-recursion (the same      *)
(* rec_form relativized, at slots 6/7, guarded by lmem_at so the             *)
(* relativization lemma applies), asserting the outputs equal.  lstep_form   *)
(* has no parameter slots, so the two recursions coexist without slot        *)
(* surgery; the characterization HOLDS_LABS_FORM is proved for an arbitrary  *)
(* base valuation lying in the constructible class, and the free variables   *)
(* of the relativized recursion are computed once (FV_LREC_CASES).  The      *)
(* semantic content of the step is ELSTAGE_ABS_STEP: with all earlier stages *)
(* identified, the union-of-earlier-stages sets agree by extensionality, and *)
(* the Def operators agree because definability is absolute                  *)
(* (EDEFMEM_ABSOLUTE) and every member of either Def is constructible (as a  *)
(* member of an L-stage).  ELSTAGE_ABSOLUTE then identifies the L-model's    *)
(* L-hierarchy with the real one at every ordinal, and LCLASS_IDEMPOTENT     *)
(* concludes lclass (lclass D E) E = lclass D E: the constructible class of  *)
(* the constructible class is itself, i.e. the inner model L believes every  *)
(* set is constructible.                                                     *)
(* ------------------------------------------------------------------------- *)

let labs_form = new_definition
  `labs_form =
     !! 5 (rec_form lstep_form 4 -->
       !! 6 (lmem_at 6 -->
         !! 7 (lmem_at 7 -->
           ((Eq 6 4 && relativ (rec_form lstep_form 6)) -->
            Eq 7 5))))`;;

let FV_LREC_CASES = prove
 (`!m. m IN FV(relativ(rec_form lstep_form 6)) ==> m = 6 \/ m = 7`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `rec_form lstep_form 6` FV_RELATIV) THEN
  REWRITE_TAC[SUBSET] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`lstep_form`; `6`] FV_REC_FORM_SUB) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ARITH_TAC;
      X_GEN_TAC `m2:num` THEN DISCH_TAC THEN
      MP_TAC(SPEC `m2:num` FVLT_LSTEP_FORM) THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[IN_UNION; IN_INSERT; NOT_IN_EMPTY; IN_DELETE] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
  ASM_REWRITE_TAC[] THEN ASM_ARITH_TAC);;

let HOLDS_LABS_FORM = prove
 (`!D (E:A->A->bool) v0 a.
        model D E ZF_AX /\ valuation D v0 /\
        valuation (lclass D E) v0 /\ a IN D /\ elmem D E a
        ==> (holds D E ((4 |-> a) v0) labs_form <=>
             !yD. yD IN D
                  ==> erec D E lstep_form v0 a yD
                      ==> !a6. a6 IN D
                               ==> elmem D E a6
                  ==> !yL. yL IN D
                           ==> elmem D E yL
                  ==> a6 = a /\
                      erec (lclass D E) E lstep_form v0
                           a6 yL
                      ==> yL = yD)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!yD. yD IN D
         ==> (holds D E ((5 |-> (yD:A)) ((4 |-> a) v0))
                (rec_form lstep_form 4) <=>
              erec D (E:A->A->bool) lstep_form v0 a yD)`
  (LABEL_TAC "recd") THENL
   [X_GEN_TAC `yD:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`;
                  `lstep_form`; `4`; `a:A`; `yD:A`]
      HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC;
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!yD a6 yL. yD IN D /\ a6 IN D /\ yL IN D /\
               elmem D (E:A->A->bool) a6 /\ elmem D E yL
        ==> (holds D E ((7 |-> yL) ((6 |-> a6) ((5 |-> yD)
               ((4 |-> a) v0))))
               (relativ (rec_form lstep_form 6)) <=>
             erec (lclass D E) E lstep_form v0 a6 yL)`
  (LABEL_TAC "recl") THENL
   [MAP_EVERY X_GEN_TAC [`yD:A`; `a6:A`; `yL:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL
           [`D:A->bool`; `E:A->A->bool`; `relativ (rec_form lstep_form 6)`;
            `(7 |-> (yL:A)) ((6 |-> (a6:A)) (v0:num->A))`;
                  `(7 |-> (yL:A)) ((6 |-> (a6:A)) ((5 |-> (yD:A))
                     ((4 |-> (a:A)) v0)))`]
      HOLDS_VALUATION) THEN
    ANTS_TAC THENL
     [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `m = 6 \/ m = 7` MP_TAC THENL
       [MP_TAC(SPEC `m:num` FV_LREC_CASES) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `valuation (lclass D E)
        ((7 |-> (yL:A)) ((6 |-> (a6:A)) (v0:num->A)))`
    ASSUME_TAC THENL
     [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
      REWRITE_TAC[VALMOD] THEN REPEAT COND_CASES_TAC THEN
      REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[valuation; IN_LCLASS];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] HOLDS_RELATIV) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`rec_form lstep_form 6`;
      `(7 |-> (yL:A)) ((6 |-> (a6:A)) (v0:num->A))`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN `(a6:A) IN lclass D E /\ (yL:A) IN lclass D E`
    STRIP_ASSUME_TAC THENL
     [REWRITE_TAC[IN_LCLASS] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `v0:num->A`; `lstep_form`; `6`; `a6:A`;
                  `yL:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC;
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u b c. u IN D /\ b IN D /\ c IN D
        ==> (holds D E ((7 |-> (c:A)) ((6 |-> b) ((5 |-> u)
               ((4 |-> a) v0)))) (lmem_at 6) <=>
             elmem D (E:A->A->bool) b)`
  (LABEL_TAC "lm6") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (c:A)) ((6 |-> (b:A)) ((5 |-> (u:A))
         ((4 |-> (a:A)) v0)))`; `6`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[valuation] THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[valuation];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u b c. u IN D /\ b IN D /\ c IN D
        ==> (holds D E ((7 |-> (c:A)) ((6 |-> b) ((5 |-> u)
               ((4 |-> a) v0)))) (lmem_at 7) <=>
             elmem D (E:A->A->bool) c)`
  (LABEL_TAC "lm7") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (c:A)) ((6 |-> (b:A)) ((5 |-> (u:A))
         ((4 |-> (a:A)) v0)))`; `7`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[valuation] THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[valuation];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[labs_form; holds; HOLDS_AND] THEN
  USE_THEN "recd" (fun t1 ->
    USE_THEN "recl" (fun t2 ->
      USE_THEN "lm6" (fun t3 ->
        USE_THEN "lm7" (fun t4 ->
          ASM_SIMP_TAC[t1; t2; t3; t4])))) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!u b. u IN D /\ b IN D
        ==> (holds D E ((6 |-> (b:A)) ((5 |-> u)
               ((4 |-> a) v0))) (lmem_at 6) <=>
             elmem D (E:A->A->bool) b)`
  (LABEL_TAC "lm6b") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (b:A)) ((5 |-> (u:A))
         ((4 |-> (a:A)) v0))`; `6`] HOLDS_LMEM_AT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[valuation] THEN
      X_GEN_TAC `i:num` THEN REWRITE_TAC[VALMOD] THEN
      REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[valuation];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "recl" (fun t2 ->
    USE_THEN "lm6b" (fun t3 -> ASM_SIMP_TAC[t2; t3])));;

let ELSTAGE_ABS_STEP = prove
 (`!D (E:A->A->bool) a yD yL.
        model D E ZF_AX /\ eordinal D E a /\
        (!b yb yLb. b IN D /\ E b a /\ yb IN D /\
                    elstage D E b yb /\ yLb IN lclass D E /\
                    elstage (lclass D E) E b yLb
                    ==> yLb = yb) /\
        yD IN D /\ elstage D E a yD /\
        yL IN lclass D E /\ elstage (lclass D E) E a yL
        ==> yL = yD`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 ih h3 h4 h5 h6" THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELMEM_ORDINAL; IN_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) a`
  ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `(yL:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `yD:A`]
    ELSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@wD. h7 wdch h8" THEN
  MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `a:A`;
                `yL:A`] ELSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@wL. h9 wlch h10" THEN
  SUBGOAL_THEN `(wL:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `(wD:A) = wL` ASSUME_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
      check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN
       `?b z. (b:A) IN D /\ (z:A) IN D /\ (E:A->A->bool) b a /\
              elstage D E b z /\ E u z`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "wdch" (MP_TAC o SPEC `u:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC `(E:A->A->bool) u wD` THEN REWRITE_TAC[th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `(b:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[ELMEM_ORDINAL; IN_LCLASS]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) b`
      ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?zL. (zL:A) IN lclass D E /\
             elstage (lclass D E) (E:A->A->bool) b zL`
      STRIP_ASSUME_TAC THENL
       [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                      `b:A`] ELSTAGE_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(zL:A) = z` SUBST_ALL_TAC THENL
       [USE_THEN "ih" (MP_TAC o SPECL [`b:A`; `z:A`; `zL:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      USE_THEN "wlch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      SUBGOAL_THEN `(u:A) IN lclass D E` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?b zL. (b:A) IN lclass D E /\ (zL:A) IN lclass D E /\
               (E:A->A->bool) b a /\
               elstage (lclass D E) E b zL /\ E u zL`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "wlch" (MP_TAC o SPEC `u:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC `(E:A->A->bool) u wL` THEN REWRITE_TAC[th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `(b:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?zD. (zD:A) IN D /\ elstage D (E:A->A->bool) b zD`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(zL:A) = zD` SUBST_ALL_TAC THENL
       [USE_THEN "ih" (MP_TAC o SPECL [`b:A`; `zD:A`; `zL:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "wdch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `zD:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    if concl th = `(wD:A) = wL` then SUBST_ALL_TAC th
    else failwith "notit") THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
    check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z yD <=> edefmem D E wL z)`
  (LABEL_TAC "ydch") THENL [ASM_MESON_TAC[edef]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN lclass D E
        ==> ((E:A->A->bool) z yL <=>
             edefmem (lclass D E) E wL z)`
  (LABEL_TAC "ylch") THENL [ASM_MESON_TAC[edef]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[LCLASS_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) wL z` ASSUME_TAC THENL
     [USE_THEN "ylch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z yL`))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wL:A`; `z:A`]
        EDEFMEM_ABSOLUTE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "ydch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `elmem D (E:A->A->bool) z` ASSUME_TAC THENL
     [REWRITE_TAC[elmem] THEN
      MAP_EVERY EXISTS_TAC [`a:A`; `yD:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) IN lclass D E` ASSUME_TAC THENL
     [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) wL z` ASSUME_TAC THENL
     [USE_THEN "ydch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z yD`))) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "ylch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wL:A`; `z:A`]
      EDEFMEM_ABSOLUTE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let ELSTAGE_ABSOLUTE = prove
 (`!D (E:A->A->bool) a yD yL.
        model D E ZF_AX /\ eordinal D E a /\
        yD IN D /\ elstage D E a yD /\
        yL IN lclass D E /\ elstage (lclass D E) E a yL
        ==> yL = yD`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?om. eomega D (E:A->A->bool) om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_EOMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D (\k:num. (om:A)) /\
    valuation (lclass D E) (\k:num. (om:A))`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a'. eordinal D (E:A->A->bool) a'
         ==> holds D E ((4 |-> a') (\k:num. (om:A))) labs_form`
  (LABEL_TAC "ind") THENL
   [(MATCH_MP_TAC EORDINAL_INDUCT THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a':A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ihh")) THEN
  SUBGOAL_THEN `(a':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) a'` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELMEM_ORDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`;
                `a':A`] HOLDS_LABS_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `yD':A` THEN DISCH_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `a6:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  X_GEN_TAC `yL':A` THEN DISCH_TAC THEN DISCH_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 MP_TAC ASSUME_TAC) THEN
  DISCH_THEN SUBST_ALL_TAC THEN
    SUBGOAL_THEN `elstage D (E:A->A->bool) a' yD'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `yD':A`;
                  `\k:num. (om:A)`] ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `elstage (lclass D E) (E:A->A->bool) a' yL'`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `a':A`; `yL':A`; `\k:num. (om:A)`]
      ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(yL':A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `yD':A`;
                `yL':A`] ELSTAGE_ABS_STEP) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`b:A`; `yb:A`; `yLb:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELMEM_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(yLb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) yLb` ASSUME_TAC THENL
   [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  USE_THEN "ihh" (MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`;
                `b:A`] HOLDS_LABS_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `yb:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `yb:A`;
                  `\k:num. (om:A)`] ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `b:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `yLb:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[] THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `b:A`; `yLb:A`; `\k:num. (om:A)`]
      ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);
    (USE_THEN "ind" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `elmem D (E:A->A->bool) a` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELMEM_ORDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`;
                `a:A`] HOLDS_LABS_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `yD:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `yD:A`;
                  `\k:num. (om:A)`] ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `yL:A`) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[LCLASS_IN_D]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_MESON_TAC[IN_LCLASS]; ALL_TAC] THEN
  ANTS_TAC THENL
   [REWRITE_TAC[] THEN
    MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `a:A`; `yL:A`; `\k:num. (om:A)`]
      ELSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC])]);;

let LCLASS_IDEMPOTENT = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX ==> lclass (lclass D E) E = lclass D E`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX`
  ASSUME_TAC THENL [ASM_MESON_TAC[MODEL_LCLASS]; ALL_TAC] THEN
  REWRITE_TAC[EXTENSION] THEN X_GEN_TAC `u:A` THEN
  REWRITE_TAC[IN_LCLASS] THEN EQ_TAC THENL
   [SIMP_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elmem] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "elmem")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(a:A) IN lclass D E` ASSUME_TAC THENL
   [ASM_MESON_TAC[ELMEM_ORDINAL; IN_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (lclass D E) (E:A->A->bool) a`
  ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_LCLASS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?yL. (yL:A) IN lclass D E /\
         elstage (lclass D E) (E:A->A->bool) a yL`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`;
                  `a:A`] ELSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(yL:A) = y` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `y:A`;
                  `yL:A`] ELSTAGE_ABSOLUTE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  MAP_EVERY EXISTS_TAC [`a:A`; `y:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Internal linear-order plumbing for the wellordering of L:                 *)
(* erel r u v (the pair <u,v> is in the relation-set r), least/greatest      *)
(* elements, and the object-formula counterpart rel_form.                    *)
(* ------------------------------------------------------------------------- *)

let erel = new_definition
  `erel D (E:A->A->bool) r u v <=>
        u IN D /\ v IN D /\ ?p. p IN D /\ eopair D E u v p /\ E p r`;;

let EREL_IN_IFF = prove
 (`!D (E:A->A->bool) r z z'.
        z IN D /\ z' IN D
        ==> (erel D E r z z' <=>
             ?p. p IN D /\ eopair D E z z' p /\ E p r)`,
  REWRITE_TAC[erel] THEN MESON_TAC[]);;

let rel_form = new_definition
  `rel_form r i j =
     ?? (MAX r (MAX i j) + 1)
        (opair_form i j (MAX r (MAX i j) + 1) &&
         ((MAX r (MAX i j) + 1) %% r))`;;

let FV_REL_FORM = prove
 (`!r i j. FV(rel_form r i j) = {r,i,j}`,
  REPEAT GEN_TAC THEN
  REWRITE_TAC[rel_form; FV; FV_CLAUSES; FV_OPAIR_FORM] THEN
  REWRITE_TAC[EXTENSION; IN_DELETE; IN_UNION; IN_INSERT;
              NOT_IN_EMPTY] THEN
  GEN_TAC THEN ARITH_TAC);;

let HOLDS_REL_FORM = prove
 (`!D (E:A->A->bool) v r i j.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (rel_form r i j) <=>
             erel D E (v r) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p. p IN D
        ==> (holds D E (((MAX r (MAX i j) + 1) |-> (p:A)) v)
               (opair_form i j (MAX r (MAX i j) + 1)) <=>
             eopair D (E:A->A->bool) (v i) (v j) p)`
  (LABEL_TAC "op") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX r (MAX i j) + 1) |-> (p:A)) v`; `i:num`; `j:num`;
      `MAX r (MAX i j) + 1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    REWRITE_TAC[ARITH_RULE `~(i = MAX r (MAX i j) + 1) /\
                            ~(j = MAX r (MAX i j) + 1)`];
    ALL_TAC] THEN
  REWRITE_TAC[rel_form; HOLDS_EX; HOLDS_AND; holds; erel] THEN
  USE_THEN "op" (fun th -> ASM_SIMP_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  REWRITE_TAC[ARITH_RULE `~(r = MAX r (MAX i j) + 1)`] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "op" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "holds")) (concl a)))) THEN
    SIMP_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "op" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let mmcon_form = new_definition
  `mmcon_form =
     (?? 5 ((5 %% 4) &&
            !! 6 (((6 %% 4) && Not (Eq 6 5)) --> rel_form 3 5 6))) &&
     (?? 5 ((5 %% 4) &&
            !! 6 (((6 %% 4) && Not (Eq 6 5)) --> rel_form 3 6 5)))`;;

let HOLDS_MMCON_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v mmcon_form <=>
             (?m. m IN D /\ E m (v 4) /\
                  !t. t IN D /\ E t (v 4) /\ ~(t = m)
                      ==> erel D E (v 3) m t) /\
             (?m. m IN D /\ E m (v 4) /\
                  !t. t IN D /\ E t (v 4) /\ ~(t = m)
                      ==> erel D E (v 3) t m))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!m t. m IN D /\ t IN D
      ==> (holds D E ((6 |-> (t:A)) ((5 |-> m) v))
             (rel_form 3 5 6) <=>
           erel D (E:A->A->bool) (v 3) m t) /\
          (holds D E ((6 |-> t) ((5 |-> m) v))
             (rel_form 3 6 5) <=>
           erel D E (v 3) t m)`
  (LABEL_TAC "rl") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (t:A)) ((5 |-> (m:A)) v)`; `3`; `5`; `6`]
        HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (t:A)) ((5 |-> (m:A)) v)`; `3`; `6`; `5`]
        HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[mmcon_form; HOLDS_EX; HOLDS_AND; HOLDS_NOT; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  USE_THEN "rl" (fun th -> ASM_SIMP_TAC[th]) THEN
  MATCH_MP_TAC(TAUT
    `(a <=> c) /\ (b <=> d) ==> (a /\ b <=> c /\ d)`) THEN
  CONJ_TAC THENL
   [EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "rl" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (fun th -> REWRITE_TAC[GSYM th]) (K ALL_TAC)) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `t:A` o check (fun th ->
        is_forall(concl th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN DISCH_TAC THEN STRIP_TAC THEN
      USE_THEN "rl" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (fun th -> REWRITE_TAC[th]) (K ALL_TAC)) THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "rl" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (K ALL_TAC) (fun th -> REWRITE_TAC[GSYM th])) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `t:A` o check (fun th ->
        is_forall(concl th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `a:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN DISCH_TAC THEN STRIP_TAC THEN
      USE_THEN "rl" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2
        (K ALL_TAC) (fun th -> REWRITE_TAC[th])) THEN
      FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]]);;

let fmmhyp_form = new_definition
  `fmmhyp_form =
     fun_form 1 &&
     (domain_form 1 0 &&
      ((!!6 ((6 %% 4) --> ?? 5 (apply_form 1 5 6))) &&
       ((!!5 (!!6 (!!7 ((rel_form 3 5 6 && rel_form 3 6 7) -->
                        rel_form 3 5 7)))) &&
        ((!!5 (!!6 (((5 %% 4) && ((6 %% 4) && Not (Eq 5 6))) -->
                    (rel_form 3 5 6 || rel_form 3 6 5)))) &&
         ?? 5 (5 %% 4)))))`;;

let fminmax_form = new_definition
  `fminmax_form = !!1 (!!3 (!!4 (fmmhyp_form --> mmcon_form)))`;;

let HOLDS_FMMHYP_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v fmmhyp_form <=>
             eisfun D E (v 1) /\ edomain D E (v 1) (v 0) /\
             (!t. t IN D ==> E t (v 4)
                  ==> ?k. k IN D /\ eapply D E (v 1) k t) /\
             (!a b c. a IN D /\ b IN D /\ c IN D /\
                      erel D E (v 3) a b /\ erel D E (v 3) b c
                      ==> erel D E (v 3) a c) /\
             (!a b. a IN D /\ b IN D /\ E a (v 4) /\ E b (v 4) /\
                    ~(a = b)
                    ==> erel D E (v 3) a b \/ erel D E (v 3) b a) /\
             (?t. t IN D /\ E t (v 4)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t k. t IN D /\ k IN D
      ==> (holds D E ((5 |-> (k:A)) ((6 |-> t) v))
             (apply_form 1 5 6) <=>
           eapply D (E:A->A->bool) (v 1) k t)`
  (LABEL_TAC "ap2") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (k:A)) ((6 |-> (t:A)) v)`; `1`; `5`; `6`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. a IN D /\ b IN D /\ c IN D
      ==> (holds D E ((7 |-> (c:A)) ((6 |-> b) ((5 |-> a) v)))
             (rel_form 3 5 6) <=>
           erel D (E:A->A->bool) (v 3) a b) /\
          (holds D E ((7 |-> c) ((6 |-> b) ((5 |-> a) v)))
             (rel_form 3 6 7) <=>
           erel D E (v 3) b c) /\
          (holds D E ((7 |-> c) ((6 |-> b) ((5 |-> a) v)))
             (rel_form 3 5 7) <=>
           erel D E (v 3) a c)`
  (LABEL_TAC "rl3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (c:A)) ((6 |-> (b:A)) ((5 |-> (a:A)) v))`;
        `3`; `5`; `6`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (c:A)) ((6 |-> (b:A)) ((5 |-> (a:A)) v))`;
        `3`; `6`; `7`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (c:A)) ((6 |-> (b:A)) ((5 |-> (a:A)) v))`;
        `3`; `5`; `7`] HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b. a IN D /\ b IN D
      ==> (holds D E ((6 |-> (b:A)) ((5 |-> a) v))
             (rel_form 3 5 6) <=>
           erel D (E:A->A->bool) (v 3) a b) /\
          (holds D E ((6 |-> b) ((5 |-> a) v))
             (rel_form 3 6 5) <=>
           erel D E (v 3) b a)`
  (LABEL_TAC "rl2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (b:A)) ((5 |-> (a:A)) v)`; `3`; `5`; `6`]
        HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (b:A)) ((5 |-> (a:A)) v)`; `3`; `6`; `5`]
        HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E v (!!6 (6 %% 4 --> ?? 5 (apply_form 1 5 6))) <=>
    (!t. t IN D ==> E t (v 4)
         ==> ?k. k IN D /\ eapply D (E:A->A->bool) (v 1) k t)`
  (LABEL_TAC "c4") THENL
   [REWRITE_TAC[holds; HOLDS_EX] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `t:A` THEN
    DISCH_TAC THEN DISCH_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `t:A`) THEN ASM_REWRITE_TAC[] THENL
     [DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ap2" (fun th -> MP_TAC(SPECL [`t:A`; `k:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ap2" (fun th -> MP_TAC(SPECL [`t:A`; `k:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E v
      (!!5 (!!6 (!!7 (rel_form 3 5 6 && rel_form 3 6 7 -->
                      rel_form 3 5 7)))) <=>
    (!a b c. a IN D /\ b IN D /\ c IN D /\
             erel D (E:A->A->bool) (v 3) a b /\ erel D E (v 3) b c
             ==> erel D E (v 3) a c)`
  (LABEL_TAC "c5") THENL
   [REWRITE_TAC[holds; HOLDS_AND] THEN
    USE_THEN "rl3" (fun th -> ASM_SIMP_TAC[th]) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E v
      (!!5 (!!6 (5 %% 4 && 6 %% 4 && Not (Eq 5 6) -->
                 rel_form 3 5 6 || rel_form 3 6 5))) <=>
    (!a b. a IN D /\ b IN D /\ E a (v 4) /\ E b (v 4) /\ ~(a = b)
           ==> erel D (E:A->A->bool) (v 3) a b \/
               erel D E (v 3) b a)`
  (LABEL_TAC "c6") THENL
   [REWRITE_TAC[holds; HOLDS_AND; HOLDS_NOT; HOLDS_OR] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    USE_THEN "rl2" (fun th -> ASM_SIMP_TAC[th]) THEN MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E v (?? 5 (5 %% 4)) <=>
    (?t:A. t IN D /\ E t (v 4))`
  (LABEL_TAC "c8") THENL
   [REWRITE_TAC[holds; HOLDS_EX] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "c4" (fun t4 ->
    USE_THEN "c5" (fun t5 -> USE_THEN "c6" (fun t6 ->
      USE_THEN "c8" (fun t8 ->
        REWRITE_TAC[fmmhyp_form; HOLDS_AND; t4; t5; t6; t8])))) THEN
  ASM_SIMP_TAC[HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM]);;

let HOLDS_FMINMAX_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v fminmax_form <=>
          !h r z. h IN D /\ r IN D /\ z IN D /\
                eisfun D E h /\ edomain D E h (v 0) /\
                (!t. t IN D ==> E t z
                     ==> ?k. k IN D /\ eapply D E h k t) /\
                (!a b c. a IN D /\ b IN D /\ c IN D /\
                         erel D E r a b /\ erel D E r b c
                         ==> erel D E r a c) /\
                (!a b. a IN D /\ b IN D /\ E a z /\ E b z /\ ~(a = b)
                       ==> erel D E r a b \/ erel D E r b a) /\
                (?t. t IN D /\ E t z)
                ==> (?m. m IN D /\ E m z /\
                         !t. t IN D /\ E t z /\ ~(t = m)
                             ==> erel D E r m t) /\
                    (?m. m IN D /\ E m z /\
                         !t. t IN D /\ E t z /\ ~(t = m)
                             ==> erel D E r t m))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!h r z. h IN D /\ r IN D /\ z IN D
      ==> valuation D ((4 |-> (z:A)) ((3 |-> r) ((1 |-> h) v)))`
  (LABEL_TAC "v3") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REWRITE_TAC[fminmax_form; holds] THEN
  USE_THEN "v3" (fun tv ->
    ASM_SIMP_TAC[tv; HOLDS_FMMHYP_FORM; HOLDS_MMCON_FORM]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_IMP_FORALL_THM]);;

let ERESTRICT_EAPPLY = prove
 (`!D (E:A->A->bool) g b r u w.
        model D E ZF_AX /\ erestrict D E g b r /\ u IN D /\ w IN D
        ==> (eapply D E r u w <=> E u b /\ eapply D E g u w)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `E z g /\ ?u' w'. u' IN D /\ w' IN D /\ (E:A->A->bool) u' b /\
                       eopair D E u' w' z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
    SUBGOAL_THEN `u':A = u /\ w':A = w` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    STRIP_TAC THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    ASM_MESON_TAC[erestrict]]);;

let ERESTRICT_EDOMAIN = prove
 (`!D (E:A->A->bool) g a b r.
        model D E ZF_AX /\ erestrict D E g b r /\ edomain D E g a /\
        b IN D /\ (!u. u IN D /\ E u b ==> E u a)
        ==> edomain D E r b`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[edomain] THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `eindom D (E:A->A->bool) r u <=> E u b /\ eindom D E g u`
  SUBST1_TAC THENL
   [REWRITE_TAC[eindom] THEN ASM_MESON_TAC[ERESTRICT_EAPPLY];
    ALL_TAC] THEN
  ASM_MESON_TAC[edomain]);;

(* ------------------------------------------------------------------------- *)
(* The internal finite min/max principle: any nonempty set z covered by a    *)
(* function whose domain is an internal natural number (a finite internal    *)
(* enumeration), linearly ordered by a relation-set r on z, has both an      *)
(* r-least and an r-greatest element.  Proved by the internal omega          *)
(* induction EOMEGA_INDUCT_HOLDS applied to fminmax_form at slot 0; the      *)
(* semantic content of that formula is the predicate eminmax.  The           *)
(* successor step restricts the enumeration to the predecessor domain and    *)
(* removes the extra value h(m) from z, then reinserts it by a totality      *)
(* comparison (COMBINE_LEAST, used once for least and once, with the         *)
(* relation reversed, for greatest).                                         *)
(* ------------------------------------------------------------------------- *)

let eminmax = new_definition
  `eminmax D (E:A->A->bool) n <=>
     !h r z. h IN D /\ r IN D /\ z IN D /\
             eisfun D E h /\ edomain D E h n /\
             (!t. t IN D ==> E t z ==> ?k. k IN D /\ eapply D E h k t) /\
             (!a b c. a IN D /\ b IN D /\ c IN D /\
                      erel D E r a b /\ erel D E r b c
                      ==> erel D E r a c) /\
             (!a b. a IN D /\ b IN D /\ E a z /\ E b z /\ ~(a = b)
                    ==> erel D E r a b \/ erel D E r b a) /\
             (?t. t IN D /\ E t z)
             ==> (?m. m IN D /\ E m z /\
                      !t. t IN D /\ E t z /\ ~(t = m)
                          ==> erel D E r m t) /\
                 (?m. m IN D /\ E m z /\
                      !t. t IN D /\ E t z /\ ~(t = m)
                          ==> erel D E r t m)`;;

let HOLDS_FMINMAX_EMINMAX = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v fminmax_form <=> eminmax D E (v 0))`,
  SIMP_TAC[HOLDS_FMINMAX_FORM; eminmax]);;

let COMBINE_LEAST = prove
 (`!D (E:A->A->bool) (RR:A->A->bool) z z' hm m1.
     (!a b c. a IN D /\ b IN D /\ c IN D /\ RR a b /\ RR b c
              ==> RR a c) /\
     (!a b. a IN D /\ b IN D /\ E a z /\ E b z /\ ~(a = b)
            ==> RR a b \/ RR b a) /\
     hm IN D /\ m1 IN D /\
     (!w. w IN D ==> (E w z' <=> E w z /\ ~(w = hm))) /\
     E m1 z' /\
     (!t. t IN D /\ E t z' /\ ~(t = m1) ==> RR m1 t)
     ==> ?mm. mm IN D /\ E mm z /\
              !t. t IN D /\ E t z /\ ~(t = mm) ==> RR mm t`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) m1 z /\ ~(m1 = hm)` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) hm z` THENL
   [SUBGOAL_THEN `(RR:A->A->bool) m1 hm \/ RR hm m1` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC; ALL_TAC] THENL
     [EXISTS_TAC `m1:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      ASM_CASES_TAC `t:A = hm` THEN ASM_MESON_TAC[];
      EXISTS_TAC `hm:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      ASM_CASES_TAC `t:A = m1` THEN ASM_MESON_TAC[]];
    EXISTS_TAC `m1:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC `t:A = hm` THEN ASM_MESON_TAC[]]);;

let EFIN_MINMAX_BASE = prove
 (`!D (E:A->A->bool) e.
        model D E ZF_AX /\ e IN D /\ eempty D E e
        ==> eminmax D E e`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eminmax] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?k:A. k IN D /\ eapply D (E:A->A->bool) h k t`
  (X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) h k` ASSUME_TAC THENL
   [REWRITE_TAC[eindom] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) k e` ASSUME_TAC THENL
   [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  ASM_MESON_TAC[eempty]);;

let EFIN_MINMAX_STEP = prove
 (`!D (E:A->A->bool) m sm.
        model D E ZF_AX /\ m IN D /\ sm IN D /\ esuc D E m sm /\
        eminmax D E m
        ==> eminmax D E sm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!u:A. u IN D ==> ((E:A->A->bool) u sm <=> E u m \/ u = m)`
  (LABEL_TAC "suc") THENL [ASM_MESON_TAC[ESUC_ALT]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) m sm` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[eminmax] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?hm:A. hm IN D /\ eapply D (E:A->A->bool) h m hm`
  (X_CHOOSE_THEN `hm:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
  SUBGOAL_THEN `?h':A. erestrict D (E:A->A->bool) h m h'`
  (X_CHOOSE_THEN `h':A` ASSUME_TAC) THENL
   [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(h':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) h'` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) h' m` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `sm:A`;
                  `m:A`; `h':A`] ERESTRICT_EDOMAIN) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?s:A. epair D (E:A->A->bool) hm hm s`
  (X_CHOOSE_THEN `s:A` ASSUME_TAC) THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?z':A. ediff D (E:A->A->bool) z s z'`
  (X_CHOOSE_THEN `z':A` ASSUME_TAC) THENL
   [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w z' <=> E w z /\ ~(w = hm))`
  (LABEL_TAC "zc") THENL
   [ASM_MESON_TAC[ediff; epair]; ALL_TAC] THEN
  ASM_CASES_TAC `?u:A. u IN D /\ (E:A->A->bool) u z'` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `u0:A` STRIP_ASSUME_TAC) THEN
    UNDISCH_TAC `eminmax D (E:A->A->bool) m` THEN
    REWRITE_TAC[eminmax] THEN
    DISCH_THEN(MP_TAC o SPECL [`h':A`; `r:A`; `z':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [X_GEN_TAC `tt:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        SUBGOAL_THEN `(E:A->A->bool) tt z /\ ~(tt = hm)`
        STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `?k:A. k IN D /\ eapply D (E:A->A->bool) h k tt`
        (X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) k sm` ASSUME_TAC THENL
         [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) k m` ASSUME_TAC THENL
         [ASM_MESON_TAC[EAPPLY_UNIQUE]; ALL_TAC] THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        ASM_MESON_TAC[ERESTRICT_EAPPLY];
        CONJ_TAC THENL
         [REPEAT GEN_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[];
          EXISTS_TAC `u0:A` THEN ASM_REWRITE_TAC[]]];
      ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `mn:A` STRIP_ASSUME_TAC)
      (X_CHOOSE_THEN `mx:A` STRIP_ASSUME_TAC)) THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `erel D (E:A->A->bool) r`; `z:A`; `z':A`; `hm:A`; `mn:A`]
        COMBINE_LEAST) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; REWRITE_TAC[]];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `\a b:A. erel D (E:A->A->bool) r b a`; `z:A`; `z':A`;
        `hm:A`; `mx:A`] COMBINE_LEAST) THEN
      REWRITE_TAC[] THEN ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
        REWRITE_TAC[]]];
    SUBGOAL_THEN `!w. w IN D ==> (E:A->A->bool) w z ==> w = hm`
    ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) hm z` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    CONJ_TAC THEN EXISTS_TAC `hm:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

let EFIN_MINMAX = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ eomega D E om
        ==> !n. n IN D /\ E n om ==> eminmax D E n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\i:num. (om:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `fminmax_form`;
                `0`; `\i:num. (om:A)`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (e:A)) (\i:num. (om:A)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_FMINMAX_EMINMAX] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[] THEN ASM_MESON_TAC[EFIN_MINMAX_BASE];
    REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) (\i:num. (om:A))) /\
                  valuation D ((0 |-> (m:A)) (\i:num. (om:A)))`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o check (can (find_term (fun t ->
      is_const t && fst(dest_const t) = "holds")) o concl)) THEN
    ASM_SIMP_TAC[HOLDS_FMINMAX_EMINMAX] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[] THEN ASM_MESON_TAC[EFIN_MINMAX_STEP]];
   DISCH_TAC THEN X_GEN_TAC `n:A` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (n:A)) (\i:num. (om:A)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_FMINMAX_EMINMAX] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Every hf stage V(n), n a member of om, admits an internal finite          *)
(* enumeration: a function h with domain some j in om whose values are       *)
(* exactly the members of V(n) (eenum).  Internal omega induction on         *)
(* enum_form (slot 0 = n, slot 9 = om as a parameter): the base stage is     *)
(* empty and enumerated by the empty function (EEMPTYFUN); the successor     *)
(* stage V(suc m) = P(V(m)) is enumerated by the powerset enumeration        *)
(* provided by POWENUM_ALL applied to the enumeration of V(m), using         *)
(* EHFSTAGE_SUC_CHAR to identify members of V(suc m) with subsets of V(m).   *)
(* ------------------------------------------------------------------------- *)

let enum_form = new_definition
  `enum_form =
     !! 4 (hfstage_form 0 4 -->
           ?? 5 ((5 %% 9) &&
                 ?? 1 (fun_form 1 &&
                       (domain_form 1 5 &&
                        ((!! 6 (!! 7 (apply_form 1 6 7 --> (7 %% 4)))) &&
                         (!! 7 ((7 %% 4) -->
                                ?? 6 (apply_form 1 6 7))))))))`;;

let HOLDS_ENUM_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v enum_form <=>
             !y. y IN D /\ ehfstage D E (v 0) y
                 ==> ?j h. j IN D /\ E j (v 9) /\ h IN D /\
                           eisfun D E h /\ edomain D E h j /\
                           (!k w. k IN D /\ w IN D /\
                                  eapply D E h k w ==> E w y) /\
                           (!w. w IN D ==> E w y
                                ==> ?k. k IN D /\ eapply D E h k w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v) (hfstage_form 0 4) <=>
           ehfstage D (E:A->A->bool) (v 0) y)`
  (LABEL_TAC "st") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
      `0`; `4`] HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y j h. y IN D /\ j IN D /\ h IN D
      ==> (holds D E ((1 |-> (h:A)) ((5 |-> j) ((4 |-> y) v)))
             (fun_form 1 &&
              (domain_form 1 5 &&
               ((!! 6 (!! 7 (apply_form 1 6 7 --> (7 %% 4)))) &&
                (!! 7 ((7 %% 4) --> ?? 6 (apply_form 1 6 7)))))) <=>
           eisfun D (E:A->A->bool) h /\ edomain D E h j /\
           (!k w. k IN D /\ w IN D /\ eapply D E h k w ==> E w y) /\
           (!w. w IN D ==> E w y
                ==> ?k. k IN D /\ eapply D E h k w))`
  (LABEL_TAC "bod") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    ABBREV_TAC `V3 = (1 |-> (h:A)) ((5 |-> j) ((4 |-> y) v))` THEN
    SUBGOAL_THEN `valuation D (V3:num->A)` ASSUME_TAC THENL
     [EXPAND_TAC "V3" THEN ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    SUBGOAL_THEN
     `(V3:num->A) 1 = h /\ V3 4 = y /\ V3 5 = j`
    STRIP_ASSUME_TAC THENL
     [EXPAND_TAC "V3" THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!k w. k IN D /\ w IN D
        ==> (holds D E ((7 |-> (w:A)) ((6 |-> k) V3))
               (apply_form 1 6 7) <=>
             eapply D (E:A->A->bool) h k w)`
    (LABEL_TAC "api") THENL
     [REPEAT STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (w:A)) ((6 |-> (k:A)) V3)`; `1`; `6`; `7`]
        HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!w k. w IN D /\ k IN D
        ==> (holds D E ((6 |-> (k:A)) ((7 |-> w) V3))
               (apply_form 1 6 7) <=>
             eapply D (E:A->A->bool) h k w)`
    (LABEL_TAC "apo") THENL
     [REPEAT STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (k:A)) ((7 |-> (w:A)) V3)`; `1`; `6`; `7`]
        HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E (V3:num->A)
        (!! 6 (!! 7 (apply_form 1 6 7 --> (7 %% 4)))) <=>
      (!k w. k IN D /\ w IN D /\ eapply D (E:A->A->bool) h k w
             ==> E w y)`
    (LABEL_TAC "cimg") THENL
     [REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "api" (fun th -> ASM_SIMP_TAC[th]) THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E (V3:num->A)
        (!! 7 ((7 %% 4) --> ?? 6 (apply_form 1 6 7))) <=>
      (!w. w IN D ==> E w y
           ==> ?k. k IN D /\ eapply D (E:A->A->bool) h k w)`
    (LABEL_TAC "conto") THENL
     [REWRITE_TAC[holds; HOLDS_EX] THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[] THEN
      EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `w:A` THEN
      DISCH_TAC THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `w:A`) THEN ASM_REWRITE_TAC[] THENL
       [DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "apo" (fun th ->
          MP_TAC(SPECL [`w:A`; `k:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "apo" (fun th ->
          MP_TAC(SPECL [`w:A`; `k:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "cimg" (fun t1 -> USE_THEN "conto" (fun t2 ->
      REWRITE_TAC[HOLDS_AND; t1; t2])) THEN
    ASM_SIMP_TAC[HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[enum_form; holds] THEN EQ_TAC THENL
   [DISCH_THEN(LABEL_TAC "H") THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    REMOVE_THEN "H" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "st" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[HOLDS_EX] THEN REWRITE_TAC[HOLDS_AND] THEN
  REWRITE_TAC[HOLDS_EX] THEN REWRITE_TAC[holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  INTRO_TAC "@j. h1 h2 @h. h3 +" THEN
  USE_THEN "bod" (fun th ->
    MP_TAC(SPECL [`y:A`; `j:A`; `h:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`j:A`; `h:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(LABEL_TAC "H") THEN X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  USE_THEN "st" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
  REMOVE_THEN "H" (MP_TAC o SPEC `y:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:A` (X_CHOOSE_THEN `h:A`
    STRIP_ASSUME_TAC)) THEN
  REWRITE_TAC[HOLDS_EX] THEN REWRITE_TAC[HOLDS_AND] THEN
  REWRITE_TAC[HOLDS_EX] THEN REWRITE_TAC[holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "bod" (fun th ->
    MP_TAC(SPECL [`y:A`; `j:A`; `h:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let eenum = new_definition
  `eenum D (E:A->A->bool) om n <=>
     !y. y IN D /\ ehfstage D E n y
         ==> ?j h. j IN D /\ E j om /\ h IN D /\
                   eisfun D E h /\ edomain D E h j /\
                   (!k w. k IN D /\ w IN D /\ eapply D E h k w
                          ==> E w y) /\
                   (!w. w IN D ==> E w y
                        ==> ?k. k IN D /\ eapply D E h k w)`;;

let HOLDS_ENUM_EENUM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v enum_form <=> eenum D E (v 9) (v 0))`,
  SIMP_TAC[HOLDS_ENUM_FORM; eenum]);;

let EHFSTAGE_ENUM_BASE = prove
 (`!D (E:A->A->bool) om e.
        model D E ZF_AX /\ eomega D E om /\ e IN D /\ eempty D E e
        ==> eenum D E om e`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eenum] THEN
  X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  MAP_EVERY EXISTS_TAC [`e:A`; `e:A`] THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) y` ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_EMPTY]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[EOMEGA_EMPTY];
    ASM_MESON_TAC[EEMPTYFUN];
    ASM_MESON_TAC[EEMPTYFUN];
    ASM_MESON_TAC[EEMPTYFUN];
    ASM_MESON_TAC[eempty]]);;

let EHFSTAGE_ENUM_STEP = prove
 (`!D (E:A->A->bool) om m sm.
        model D E ZF_AX /\ eomega D E om /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
        eenum D E om m
        ==> eenum D E om sm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL; EORDINAL_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[eenum] THEN X_GEN_TAC `ysm:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `?ym:A. ym IN D /\ ehfstage D (E:A->A->bool) m ym`
  (X_CHOOSE_THEN `ym:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w ysm <=> esubset D E w ym)`
  (LABEL_TAC "sc") THENL
   [ASM_MESON_TAC[EHFSTAGE_SUC_CHAR]; ALL_TAC] THEN
  UNDISCH_TAC `eenum D (E:A->A->bool) om m` THEN
  REWRITE_TAC[eenum] THEN
  DISCH_THEN(MP_TAC o SPEC `ym:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:A` (X_CHOOSE_THEN `h:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `h:A`; `j:A`]
    POWENUM_ALL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:A` (X_CHOOSE_THEN `f:A`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`M:A`; `f:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [REPEAT STRIP_TAC THEN
    USE_THEN "sc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) w ym` MP_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[esubset] THEN DISCH_TAC THEN
  UNDISCH_TAC
   `!w. w IN D
        ==> (!z. z IN D
                 ==> E z w
                 ==> (?u. u IN D /\ E u j /\
                          eapply D (E:A->A->bool) h u z))
        ==> (?k. k IN D /\ eapply D E f k w)` THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z ym` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?k:A. k IN D /\ eapply D (E:A->A->bool) h k z`
    (X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[eindom; edomain];
    DISCH_THEN ACCEPT_TAC]);;

let EHFSTAGE_ENUM = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ eomega D E om
        ==> !n. n IN D /\ E n om ==> eenum D E om n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\i:num. (om:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `enum_form`;
                `0`; `\i:num. (om:A)`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) (\i:num. (om:A)))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_ENUM_EENUM] THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN ASM_MESON_TAC[EHFSTAGE_ENUM_BASE];
      REPEAT STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) (\i:num. (om:A))) /\
                    valuation D ((0 |-> (m:A)) (\i:num. (om:A)))`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (find_term (fun t ->
        is_const t && fst(dest_const t) = "holds")) o concl)) THEN
      ASM_SIMP_TAC[HOLDS_ENUM_EENUM] THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN ASM_MESON_TAC[EHFSTAGE_ENUM_STEP]];
    DISCH_TAC THEN X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D ((0 |-> (n:A)) (\i:num. (om:A)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_ENUM_EENUM] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The canonical wellordering of the hf stages, defined by internal          *)
(* recursion (the same erec machinery as ehfstage).  The carried value at    *)
(* stage a is just the order, a set of ordered pairs: u is below u' iff for  *)
(* some earlier stage b (with order wr = the recursion history at b and      *)
(* stage set ys = V(b), the latter referenced by nesting hfstage_form        *)
(* inside the step formula), u and u' are distinct subsets of ys and the     *)
(* wr-maximal element of the symmetric difference of u and u' lies in u'     *)
(* (the "binary number" comparison, cumulated over all earlier stages).      *)
(* wolt_form (slots 2 = the candidate pair p, 0 = the history g) is used     *)
(* both for the separation defining the step operation and, wrapped as       *)
(* ewostep_form = !!2 ((2 %% 1) <-> wolt_form), as the erec step formula.    *)
(* Totality of the step: the values live inside the cross product of the     *)
(* powerset of the union of the stages named by the history, the stage       *)
(* collection being obtained by replacement along hfstage_form.              *)
(* ------------------------------------------------------------------------- *)

let wolt_form = new_definition
  `wolt_form =
     ?? 4 (?? 5 (?? 6 (
        apply_form 0 4 5 &&
        (hfstage_form 4 6 &&
         ?? 7 (?? 8 (opair_form 7 8 2 &&
           (subset_form 7 6 &&
            (subset_form 8 6 &&
             (Not (Eq 7 8) &&
              ?? 9 (((9 %% 7) <-> Not (9 %% 8)) &&
                    ((!! 10 (((10 %% 7) <-> Not (10 %% 8)) -->
                             (Eq 10 9 || rel_form 5 10 9))) &&
                     (9 %% 8))))))))))))`;;

let FV_WOLT_FORM = prove
 (`!m. m IN FV(wolt_form) ==> m = 0 \/ m = 2`,
  GEN_TAC THEN
  REWRITE_TAC[wolt_form; hfstage_form; FV; FV_CLAUSES;
              FV_APPLY_FORM; FV_OPAIR_FORM; FV_SUBSET_FORM;
              FV_REL_FORM] THEN
  REWRITE_TAC[IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  TRY(MP_TAC(SPECL [`4`; `6`; `m:num`] FVLT_RECAPP_VSTEP) THEN
      ASM_REWRITE_TAC[] THEN STRIP_TAC) THEN
  ASM_ARITH_TAC);;

let HOLDS_WOLT_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v wolt_form <=>
             ?b. b IN D /\
                 ?wr. wr IN D /\
                      ?ys. ys IN D /\
                           eapply D E (v 0) b wr /\
                           ehfstage D E b ys /\
                           ?u. u IN D /\
                               ?u'. u' IN D /\
                                    eopair D E u u' (v 2) /\
                                    esubset D E u ys /\
                                    esubset D E u' ys /\
                                    ~(u = u') /\
                                    ?mx. mx IN D /\
                                         (E mx u <=> ~E mx u') /\
                                         (!t. t IN D /\
                                              (E t u <=> ~E t u')
                                              ==> t = mx \/
                                                  erel D E wr t mx) /\
                                         E mx u')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr ys. b IN D /\ wr IN D /\ ys IN D
      ==> valuation D ((6 |-> (ys:A)) ((5 |-> wr) ((4 |-> b) v)))`
  (LABEL_TAC "v3") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr ys u u'. b IN D /\ wr IN D /\ ys IN D /\ u IN D /\ u' IN D
      ==> valuation D ((8 |-> (u':A)) ((7 |-> u)
            ((6 |-> ys) ((5 |-> wr) ((4 |-> b) v)))))`
  (LABEL_TAC "v5") THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr ys. b IN D /\ wr IN D /\ ys IN D
      ==> (holds D E ((6 |-> (ys:A)) ((5 |-> wr) ((4 |-> b) v)))
             (apply_form 0 4 5) <=>
           eapply D (E:A->A->bool) (v 0) b wr) /\
          (holds D E ((6 |-> ys) ((5 |-> wr) ((4 |-> b) v)))
             (hfstage_form 4 6) <=>
           ehfstage D E b ys)`
  (LABEL_TAC "r36") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (ys:A)) ((5 |-> (wr:A)) ((4 |-> (b:A)) v))`;
        `0`; `4`; `5`] HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL
       [USE_THEN "v3" (fun th -> ASM_SIMP_TAC[th]); ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (ys:A)) ((5 |-> (wr:A)) ((4 |-> (b:A)) v))`;
        `4`; `6`] HOLDS_HFSTAGE_FORM) THEN
      ANTS_TAC THENL
       [USE_THEN "v3" (fun th -> ASM_SIMP_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC]] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr ys u u'.
      b IN D /\ wr IN D /\ ys IN D /\ u IN D /\ u' IN D
      ==> (holds D E ((8 |-> (u':A)) ((7 |-> u) ((6 |-> ys)
             ((5 |-> wr) ((4 |-> b) v))))) (opair_form 7 8 2) <=>
           eopair D (E:A->A->bool) u u' (v 2)) /\
          (holds D E ((8 |-> u') ((7 |-> u) ((6 |-> ys)
             ((5 |-> wr) ((4 |-> b) v))))) (subset_form 7 6) <=>
           esubset D E u ys) /\
          (holds D E ((8 |-> u') ((7 |-> u) ((6 |-> ys)
             ((5 |-> wr) ((4 |-> b) v))))) (subset_form 8 6) <=>
           esubset D E u' ys)`
  (LABEL_TAC "r5") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) ((6 |-> (ys:A))
           ((5 |-> (wr:A)) ((4 |-> (b:A)) v))))`;
        `7`; `8`; `2`] HOLDS_OPAIR_FORM) THEN
      ANTS_TAC THENL
       [USE_THEN "v5" (fun th -> ASM_SIMP_TAC[th]); ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) ((6 |-> (ys:A))
           ((5 |-> (wr:A)) ((4 |-> (b:A)) v))))`;
        `7`; `6`] HOLDS_SUBSET_FORM) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) ((6 |-> (ys:A))
           ((5 |-> (wr:A)) ((4 |-> (b:A)) v))))`;
        `8`; `6`] HOLDS_SUBSET_FORM) THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr ys u u' mx t.
      b IN D /\ wr IN D /\ ys IN D /\ u IN D /\ u' IN D /\
      mx IN D /\ t IN D
      ==> (holds D E ((10 |-> (t:A)) ((9 |-> mx) ((8 |-> u')
             ((7 |-> u) ((6 |-> ys) ((5 |-> wr) ((4 |-> b) v)))))))
             (rel_form 5 10 9) <=>
           erel D (E:A->A->bool) wr t mx)`
  (LABEL_TAC "r7") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(10 |-> (t:A)) ((9 |-> (mx:A)) ((8 |-> (u':A)) ((7 |-> (u:A))
         ((6 |-> (ys:A)) ((5 |-> (wr:A)) ((4 |-> (b:A)) v))))))`;
      `5`; `10`; `9`] HOLDS_REL_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[wolt_form; HOLDS_EX; HOLDS_AND; HOLDS_IFF; HOLDS_NOT;
              HOLDS_OR; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `b:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `wr:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `ys:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r36" (fun th -> ASM_SIMP_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `u':A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r5" (fun th -> ASM_SIMP_TAC[th]) THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
               `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `mx:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r7" (fun th -> ASM_SIMP_TAC[th]) THEN
  REWRITE_TAC[IMP_CONJ]);;

let ewostep = new_definition
  `ewostep D (E:A->A->bool) g y <=>
        y IN D /\
        !p. p IN D
            ==> (E p y <=>
                 ?b. b IN D /\
                     ?wr. wr IN D /\
                          ?ys. ys IN D /\
                               eapply D E g b wr /\
                               ehfstage D E b ys /\
                               ?u. u IN D /\
                                   ?u'. u' IN D /\
                                        eopair D E u u' p /\
                                        esubset D E u ys /\
                                        esubset D E u' ys /\
                                        ~(u = u') /\
                                        ?mx. mx IN D /\
                                             (E mx u <=> ~E mx u') /\
                                             (!t. t IN D /\
                                                  (E t u <=> ~E t u')
                                                  ==> t = mx \/
                                                      erel D E wr t mx) /\
                                             E mx u')`;;

let EWOSTEP_FUN = prove
 (`!D (E:A->A->bool) g y y'.
        model D E ZF_AX /\ ewostep D E g y /\ ewostep D E g y'
        ==> y = y'`,
  REWRITE_TAC[ewostep] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EWOSTEP_TOTAL = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D ==> ?y. ewostep D E g y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `?u1:A. eunion D (E:A->A->bool) g u1`
  (X_CHOOSE_TAC `u1:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2:A. eunion D (E:A->A->bool) u1 u2`
  (X_CHOOSE_TAC `u2:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr:A. b IN D /\ wr IN D /\ eapply D (E:A->A->bool) g b wr
             ==> E b u2`
  (LABEL_TAC "bu2") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "eopair")) (concl th))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `pr:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (pr:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b s` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s z` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s u1` ASSUME_TAC THENL
     [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    ASM_MESON_TAC[eunion];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w:A. b IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> b) v0))
             (hfstage_form 0 1) <=>
           ehfstage D (E:A->A->bool) b w)`
  (LABEL_TAC "hfr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (b:A)) v0)`; `0`; `1`]
      HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`hfstage_form 0 1`; `0`; `1`; `v0:num->A`; `u2:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC `eordinal D (E:A->A->bool) b` THENL
     [SUBGOAL_THEN `?w:A. w IN D /\ ehfstage D (E:A->A->bool) b w`
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
       [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `ehfstage D (E:A->A->bool) b w'` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[EHFSTAGE_UNIQUE];
      EXISTS_TAC `(v0:num->A) 0` THEN
      SUBGOAL_THEN `(v0:num->A) 0 IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `w':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `ehfstage D (E:A->A->bool) b w'` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ehfstage] o
          check (fun th -> can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "ehfstage")) (concl th))) THEN
        REWRITE_TAC[erec] THEN
        REPEAT STRIP_TAC THEN ASM_MESON_TAC[EORDINAL_MEMBER];
        ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN `?uB:A. eunion D (E:A->A->bool) bb uB`
  (X_CHOOSE_TAC `uB:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(uB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `?pB:A. epow D (E:A->A->bool) uB pB`
  (X_CHOOSE_TAC `pB:A`) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `?X:A. ecross D (E:A->A->bool) pB pB X`
  (X_CHOOSE_TAC `X:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(X:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`wolt_form`; `2`; `(0 |-> (g:A)) v0`; `X:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yr:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `yr:A` THEN REWRITE_TAC[ewostep] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(2 |-> (p:A)) ((0 |-> (g:A)) v0)`] HOLDS_WOLT_FORM) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL
   [DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    POP_ASSUM STRIP_ASSUME_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) ys bb` ASSUME_TAC THENL
     [USE_THEN "bch" (fun th -> MP_TAC(SPEC `ys:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `esubset D (E:A->A->bool) u uB /\ esubset D E u' uB`
    STRIP_ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN CONJ_TAC THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      ASM_MESON_TAC[eunion; esubset];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u pB /\ E u' pB`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[epow]; ALL_TAC] THEN
    ASM_MESON_TAC[ecross]]);;

let ewostep_form = new_definition
  `ewostep_form = !! 2 ((2 %% 1) <-> wolt_form)`;;

let FV_EWOSTEP_FORM = prove
 (`!m. m IN FV ewostep_form ==> m = 0 \/ m = 1`,
  GEN_TAC THEN REWRITE_TAC[ewostep_form; FV; FV_CLAUSES] THEN
  REWRITE_TAC[IN_DELETE; IN_UNION; IN_INSERT; NOT_IN_EMPTY] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FV_WOLT_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let HOLDS_EWOSTEP_FORM = prove
 (`!D (E:A->A->bool) v g y.
      model D E ZF_AX /\ valuation D v /\ g IN D /\ y IN D
      ==> (holds D E ((1 |-> y) ((0 |-> g) v)) ewostep_form <=>
           ewostep D E g y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((1 |-> (y:A)) ((0 |-> (g:A)) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p:A. p IN D
      ==> (holds D E ((2 |-> p) ((1 |-> (y:A)) ((0 |-> (g:A)) v)))
             wolt_form <=>
           ?b. b IN D /\
               ?wr. wr IN D /\
                    ?ys. ys IN D /\
                         eapply D (E:A->A->bool) g b wr /\
                         ehfstage D E b ys /\
                         ?u. u IN D /\
                             ?u'. u' IN D /\
                                  eopair D E u u' p /\
                                  esubset D E u ys /\
                                  esubset D E u' ys /\
                                  ~(u = u') /\
                                  ?mx. mx IN D /\
                                       (E mx u <=> ~E mx u') /\
                                       (!t. t IN D /\
                                            (E t u <=> ~E t u')
                                            ==> t = mx \/
                                                erel D E wr t mx) /\
                                       E mx u')`
  (LABEL_TAC "wr") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(2 |-> (p:A)) ((1 |-> (y:A)) ((0 |-> (g:A)) v))`]
      HOLDS_WOLT_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ewostep_form; holds; HOLDS_IFF] THEN
  REWRITE_TAC[ewostep] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `p:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "wr" (fun th -> ASM_SIMP_TAC[th]));;

let EWOSTEP_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v)) ewostep_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v)) ewostep_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC EWOSTEP_FUN THEN
  MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_EWOSTEP_FORM]);;

let EWOSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v)) ewostep_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] EWOSTEP_TOTAL) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ewostep]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_EWOSTEP_FORM]);;

let evwo = new_definition
  `evwo D (E:A->A->bool) a y <=>
        ?v. valuation D v /\ erec D E ewostep_form v a y`;;

let EVWO_EREC = prove
 (`!D (E:A->A->bool) a y v.
        model D E ZF_AX /\ valuation D v
        ==> (evwo D E a y <=> erec D E ewostep_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[evwo] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) ewostep_form v' a y <=>
      erec D E ewostep_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FV_EWOSTEP_FORM) THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

let EVWO_UNIQUE = prove
 (`!D (E:A->A->bool) a y y'.
        model D E ZF_AX /\ a IN D /\ y IN D /\ y' IN D /\
        evwo D E a y /\ evwo D E a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ewostep_form`;
                `v:num->A`; `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`]
        EWOSTEP_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[EVWO_EREC]);;

let EVWO_EXISTS = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?y. y IN D /\ evwo D E a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ewostep_form`;
                `v:num->A`; `a:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[EWOSTEP_QFUN; EWOSTEP_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVWO_EREC]);;

let EVWO_CHAR = prove
 (`!D (E:A->A->bool) a y.
      model D E ZF_AX /\ eordinal D E a /\ y IN D /\ evwo D E a y
      ==> !p. p IN D
              ==> (E p y <=>
                   ?b. b IN D /\
                       ?wr. wr IN D /\
                            ?ys. ys IN D /\
                                 (E b a /\ evwo D E b wr) /\
                                 ehfstage D E b ys /\
                                 ?u. u IN D /\
                                     ?u'. u' IN D /\
                                          eopair D E u u' p /\
                                          esubset D E u ys /\
                                          esubset D E u' ys /\
                                          ~(u = u') /\
                                          ?mx. mx IN D /\
                                               (E mx u <=> ~E mx u') /\
                                               (!t. t IN D /\
                                                    (E t u <=> ~E t u')
                                                    ==> t = mx \/
                                                        erel D E wr t mx) /\
                                               E mx u')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) ewostep_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EWOSTEP_QFUN; EWOSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `ewostep D (E:A->A->bool) r y` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`;
                  `y:A`] HOLDS_EWOSTEP_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EWOSTEP_QFUN; EVWO_EREC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr:A. b IN D /\ wr IN D
        ==> (eapply D (E:A->A->bool) r b wr <=>
             E b a /\ erec D E ewostep_form v b wr)`
  (LABEL_TAC "rap") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THENL
     [REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
        (ASSUME `erecres D (E:A->A->bool) ewostep_form v a r`)))) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `b':A = b /\ y':A = wr` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `wr:A`]
            EOPAIR_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
        (ASSUME `erecres D (E:A->A->bool) ewostep_form v a r`)))) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `wr:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MP_TAC(SPEC `p:A` (CONJUNCT2(REWRITE_RULE[ewostep]
    (ASSUME `ewostep D (E:A->A->bool) r y`)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "@b. h1 @wr. h2 @ys. h3 + tl" THEN
  DISCH_TAC THEN
  EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `wr:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `ys:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "rap" (fun th -> MP_TAC(SPECL [`b:A`; `wr:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) b a /\ erec D E ewostep_form v b wr`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVWO_EREC];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `wr:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `ys:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 STRIP_ASSUME_TAC (LABEL_TAC "tl")))))))) THEN
  EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `wr:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `ys:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "rap" (fun th -> MP_TAC(SPECL [`b:A`; `wr:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EVWO_EREC]]);;

(* ------------------------------------------------------------------------- *)
(* Theory of the induced subset order.  vwo_form names the evwo recursion    *)
(* inside object formulas (mirroring hfstage_form).  EVWO_SUC_NORMALIZE:     *)
(* given coherence of the history below n, membership in evwo (suc n) is     *)
(* equivalent to being a wolt-pair over the single top layer (evwo n, V n).  *)
(* ewoltrel packages that pair relation; ESYMDIFF_EXISTS constructs the      *)
(* symmetric difference; WOLTREL_ASYM / WOLTREL_TOTAL / WOLTREL_TRANS are    *)
(* the pure order facts (totality and transitivity use the maximum of the    *)
(* symmetric difference, whose existence is STAGE_MAXHYP, i.e. EFIN_MINMAX   *)
(* fed by the stage enumeration EHFSTAGE_ENUM; transitivity is the classic   *)
(* binary-number comparison case analysis, done as an explicit case tree     *)
(* because a single MESON call is too deep).  WOLTREL_SIS_CORE is            *)
(* the stage-initial-segment transfer: if everything in yc precedes          *)
(* everything in ys outside yc, u is a subset of yc and u' meets the         *)
(* outside, then u comes before u' (the maximum of the difference lies       *)
(* outside yc, hence in u').                                                 *)
(* ------------------------------------------------------------------------- *)

let vwo_form = new_definition
  `vwo_form i j = recapp_form (rec_form ewostep_form 2) i j`;;

let HOLDS_VWO_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (vwo_form i j) <=>
             evwo D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vwo_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `rec_form ewostep_form 2`; `i:num`; `j:num`]
    HOLDS_RECAPP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (v:num->A) j) ((2 |-> v i) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `ewostep_form`; `2`; `(v:num->A) i`; `(v:num->A) j`]
    HOLDS_REC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ARITH_TAC;
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(SPEC `m:num` FV_EWOSTEP_FORM) THEN
      ASM_REWRITE_TAC[] THEN ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
    `(v:num->A) j`; `v:num->A`] EVWO_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let FVLT_EWOSTEP_FORM = prove
 (`!m. m IN FV ewostep_form ==> m < 2`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC `m:num` FV_EWOSTEP_FORM) THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let EVWO_SUC_NORMALIZE = prove
 (`!D (E:A->A->bool) n sn rn ys y.
        model D E ZF_AX /\ eordinal D E n /\ esuc D E n sn /\
        rn IN D /\ evwo D E n rn /\
        ys IN D /\ ehfstage D E n ys /\
        y IN D /\ evwo D E sn y /\
        (!b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b n /\
                   evwo D E b rb /\ ehfstage D E b yb
                   ==> !u u'. u IN D /\ u' IN D /\ E u yb /\ E u' yb
                              ==> (erel D E rn u u' <=>
                                   erel D E rb u u'))
        ==> !p. p IN D
                ==> (E p y <=>
                     ?u. u IN D /\
                         ?u'. u' IN D /\
                              eopair D E u u' p /\
                              esubset D E u ys /\
                              esubset D E u' ys /\
                              ~(u = u') /\
                              ?mx. mx IN D /\
                                   (E mx u <=> ~E mx u') /\
                                   (!t. t IN D /\ (E t u <=> ~E t u')
                                        ==> t = mx \/
                                            erel D E rn t mx) /\
                                   E mx u')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(LABEL_TAC "coh" o check (is_forall o concl)) THEN
  SUBGOAL_THEN `(n:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D ==> ((E:A->A->bool) u sn <=> E u n \/ u = n)`
  (LABEL_TAC "suc") THENL [ASM_MESON_TAC[ESUC_ALT]; ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sn:A`; `y:A`]
    EVWO_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL [ALL_TAC;
    DISCH_THEN STRIP_ASSUME_TAC THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `rn:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ys:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[]] THEN
  DISCH_THEN STRIP_ASSUME_TAC THEN
  USE_THEN "suc" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
   [ALL_TAC;
    SUBGOAL_THEN `wr:A = rn` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EVWO_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `ys':A = ys` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EHFSTAGE_UNIQUE]; ALL_TAC] THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[]] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ (E:A->A->bool) t ys' ==> E t ys`
  (LABEL_TAC "mono") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `n:A`;
                  `ys':A`; `ys:A`; `t:A`] EHFSTAGE_MONO) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN D /\ ((E:A->A->bool) t u <=> ~E t u') ==> E t ys'`
  (LABEL_TAC "din") THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) u ys /\ esubset D E u' ys`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `t:A = mx \/ erel D (E:A->A->bool) wr t mx`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC; ALL_TAC] THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISJ2_TAC THEN
  USE_THEN "coh" (fun th ->
    MP_TAC(SPECL [`b:A`; `wr:A`; `ys':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`t:A`; `mx:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    USE_THEN "din" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

let ewoltrel = new_definition
  `ewoltrel D (E:A->A->bool) r ys u u' <=>
        u IN D /\ u' IN D /\ esubset D E u ys /\ esubset D E u' ys /\
        ~(u = u') /\
        ?mx. mx IN D /\ (E mx u <=> ~E mx u') /\
             (!t. t IN D /\ (E t u <=> ~E t u')
                  ==> t = mx \/ erel D E r t mx) /\
             E mx u'`;;

let ESYMDIFF_EXISTS = prove
 (`!D (E:A->A->bool) u u'.
        model D E ZF_AX /\ u IN D /\ u' IN D
        ==> ?z. z IN D /\
                !t. t IN D ==> (E t z <=> (E t u <=> ~E t u'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?d1:A. ediff D (E:A->A->bool) u u' d1`
  (X_CHOOSE_TAC `d1:A`) THENL
   [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(d1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `?d2:A. ediff D (E:A->A->bool) u' u d2`
  (X_CHOOSE_TAC `d2:A`) THENL
   [ASM_MESON_TAC[EDIFF_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(d2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `?z:A. ebunion D (E:A->A->bool) d1 d2 z`
  (X_CHOOSE_TAC `z:A`) THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) t z <=> E t d1 \/ E t d2`
  SUBST1_TAC THENL [ASM_MESON_TAC[EBUNION_ALT]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((E:A->A->bool) t d1 <=> E t u /\ ~E t u') /\
    (E t d2 <=> E t u' /\ ~E t u)`
  (CONJUNCTS_THEN SUBST1_TAC) THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  CONV_TAC TAUT);;

let WOLTREL_ASYM = prove
 (`!D (E:A->A->bool) r ys u u'.
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        ewoltrel D E r ys u u' /\ ewoltrel D E r ys u' u
        ==> F`,
  REWRITE_TAC[ewoltrel] THEN REPEAT STRIP_TAC THEN
  ASM_CASES_TAC `mx':A = mx` THENL
   [ASM_MESON_TAC[]; ASM_MESON_TAC[]]);;

let STAGE_MAXHYP = prove
 (`!D (E:A->A->bool) om n ys r.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        ys IN D /\ ehfstage D E n ys /\ r IN D /\
        (!a b c. a IN D /\ b IN D /\ c IN D /\
                 erel D E r a b /\ erel D E r b c
                 ==> erel D E r a c) /\
        (!a b. a IN D /\ b IN D /\ E a ys /\ E b ys /\ ~(a = b)
               ==> erel D E r a b \/ erel D E r b a)
        ==> !z. z IN D /\ esubset D E z ys /\ (?t. t IN D /\ E t z)
                ==> ?m. m IN D /\ E m z /\
                        !t. t IN D /\ E t z /\ ~(t = m)
                            ==> erel D E r t m`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EHFSTAGE_ENUM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[eenum] THEN DISCH_THEN(MP_TAC o SPEC `ys:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:A` (X_CHOOSE_THEN `h:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EFIN_MINMAX) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `j:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[eminmax] THEN
  DISCH_THEN(MP_TAC o SPECL [`h:A`; `r:A`; `z:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `tt:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      ASM_MESON_TAC[esubset];
      CONJ_TAC THENL
       [ASM_MESON_TAC[esubset]; ASM_MESON_TAC[]]];
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN
    MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

let WOLTREL_TOTAL = prove
 (`!D (E:A->A->bool) r ys u u'.
        model D E ZF_AX /\ ys IN D /\
        (!z. z IN D /\ esubset D E z ys /\ (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r t m) /\
        u IN D /\ u' IN D /\ esubset D E u ys /\ esubset D E u' ys /\
        ~(u = u')
        ==> ewoltrel D E r ys u u' \/ ewoltrel D E r ys u' u`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(LABEL_TAC "mh" o check (is_forall o concl) o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "erel")) (concl th))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`]
    ESYMDIFF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "zc"))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z ys` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `?t:A. t IN D /\ (E:A->A->bool) t z`
  STRIP_ASSUME_TAC THENL
   [REFUTE_THEN(ASSUME_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN
    SUBGOAL_THEN `u:A = u'` (fun th -> ASM_MESON_TAC[th]) THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "zc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `w:A` o check (fun th ->
      can (find_term is_neg) (concl th) && is_forall(concl th))) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT;
    ALL_TAC] THEN
  USE_THEN "mh" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) m u <=> ~E m u'` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) m u'` THENL
   [DISJ1_TAC THEN REWRITE_TAC[ewoltrel] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `m:A` THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[];
    DISJ2_TAC THEN REWRITE_TAC[ewoltrel] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `m:A` THEN
    SUBGOAL_THEN `(E:A->A->bool) m u` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w:A` THEN STRIP_TAC THEN ASM_MESON_TAC[]]);;

let WOLTREL_TRANS = prove
 (`!D (E:A->A->bool) r ys u v w.
        model D E ZF_AX /\ ys IN D /\
        (!a b c. a IN D /\ b IN D /\ c IN D /\
                 erel D E r a b /\ erel D E r b c
                 ==> erel D E r a c) /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        (!z. z IN D /\ esubset D E z ys /\ (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r t m) /\
        ewoltrel D E r ys u v /\ ewoltrel D E r ys v w
        ==> ewoltrel D E r ys u w`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `~(u:A = w)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    ASM_MESON_TAC[WOLTREL_ASYM];
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ewoltrel] o
    check (fun th -> can (find_term ((=) `v:A`)) (concl th) &&
      can (find_term ((=) `w:A`)) (concl th))) THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `m2:A` STRIP_ASSUME_TAC o
    check (is_exists o concl)) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [ewoltrel] o
    check (fun th -> can (find_term ((=) `u:A`)) (concl th) &&
      can (find_term ((=) `v:A`)) (concl th) &&
      not(is_neg(concl th)))) THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `m1:A` STRIP_ASSUME_TAC o
    check (is_exists o concl)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`]
    ESYMDIFF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "zc"))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z ys` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `?t:A. t IN D /\ (E:A->A->bool) t z`
  STRIP_ASSUME_TAC THENL
   [REFUTE_THEN(ASSUME_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN
    SUBGOAL_THEN `u:A = w` (fun th -> ASM_MESON_TAC[th]) THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `q:A` THEN DISCH_TAC THEN
    USE_THEN "zc" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `q:A` o check (fun th ->
      can (find_term is_neg) (concl th) && is_forall(concl th))) THEN
    ASM_REWRITE_TAC[] THEN CONV_TAC TAUT;
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun tm -> is_const tm &&
      fst(dest_const tm) = "esubset")) (concl th))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) m u <=> ~E m w` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) m w` THENL
   [REWRITE_TAC[ewoltrel] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) m u /\ ~E m1 u /\ ~E m2 v`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `F` CONTR_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) m v` THENL
   [SUBGOAL_THEN `erel D (E:A->A->bool) r m m2` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `(E:A->A->bool) m2 u` THENL
     [SUBGOAL_THEN `erel D (E:A->A->bool) r m2 m1` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_CASES_TAC `(E:A->A->bool) m1 w` THENL
       [SUBGOAL_THEN `erel D (E:A->A->bool) r m1 m` ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[];
        SUBGOAL_THEN `erel D (E:A->A->bool) r m1 m2` ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[]];
      SUBGOAL_THEN `erel D (E:A->A->bool) r m2 m` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    SUBGOAL_THEN `erel D (E:A->A->bool) r m m1` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_CASES_TAC `(E:A->A->bool) m1 w` THENL
     [SUBGOAL_THEN `erel D (E:A->A->bool) r m1 m` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      SUBGOAL_THEN `erel D (E:A->A->bool) r m1 m2` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_CASES_TAC `(E:A->A->bool) m2 u` THENL
       [SUBGOAL_THEN `erel D (E:A->A->bool) r m2 m1` ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[];
        SUBGOAL_THEN `erel D (E:A->A->bool) r m2 m` ASSUME_TAC THENL
         [ASM_MESON_TAC[]; ALL_TAC] THEN
        ASM_MESON_TAC[]]]]);;

let WOLTREL_SIS_CORE = prove
 (`!D (E:A->A->bool) r ys yc u u'.
        model D E ZF_AX /\ ys IN D /\ yc IN D /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        (!z. z IN D /\ esubset D E z ys /\ (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r t m) /\
        (!m t'. m IN D /\ t' IN D /\ E m yc /\ E t' ys /\ ~(E t' yc)
                ==> erel D E r m t') /\
        (!t. t IN D /\ E t yc ==> E t ys) /\
        u IN D /\ u' IN D /\ esubset D E u yc /\ esubset D E u' ys /\
        (?t'. t' IN D /\ E t' u' /\ ~(E t' yc))
        ==> ewoltrel D E r ys u u'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `t':A` STRIP_ASSUME_TAC o
    check (is_exists o concl)) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) u ys` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) t' u)` ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `~(u:A = u')` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`]
    ESYMDIFF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "zc"))) THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) z ys` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) t' z` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun tm -> is_const tm &&
      fst(dest_const tm) = "esubset")) (concl th) &&
    can (find_term is_exists) (concl th))) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) m u <=> ~E m u'` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) m u'` ASSUME_TAC THENL
   [ASM_CASES_TAC `(E:A->A->bool) m u'` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(E:A->A->bool) m u` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) r m t'` ASSUME_TAC THENL
     [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) r t' m` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ewoltrel] THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN STRIP_TAC THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The evwo invariant: at every om-stage n, the order evwo n is a strict     *)
(* linear order on the members of V(n) consisting exactly of pairs of        *)
(* members of V(n) (clause a), transitive (b), asymmetric (c), total (d),    *)
(* coherent with every earlier stage's order (e), and with the stage-        *)
(* initial-segment property: members of an earlier stage V(b) precede all    *)
(* members of V(n) outside V(b) (f).  EVWO_TOPCOH turns coherence below n    *)
(* into agreement of erel (evwo n) with the induced comparison ewoltrel on   *)
(* V(n)-members (the essential coherence content); EVWO_SUC_REL identifies   *)
(* erel (evwo (suc n)) with ewoltrel (evwo n) (V n) outright.  The           *)
(* successor step assembles the WOLTREL_* order facts through these two      *)
(* bridges, with STAGE_MAXHYP supplying maxima and WOLTREL_SIS_CORE the      *)
(* initial-segment transfer (the covering stage for u obtained from          *)
(* EHFSTAGE_CHAR, the outside witness from its negation via                  *)
(* EHFSTAGE_SUC_CHAR).  The induction itself is EOMEGA_INDUCT_HOLDS on       *)
(* vwoinv_form (slot 0 = n, the invariant internalized with                  *)
(* vwo_form/hfstage_form guards), whose HOLDS characterization reduces to    *)
(* evwoinv by the congruence-descent method after a single global            *)
(* conditional simplification with the eight leaf translation rules.         *)
(* ------------------------------------------------------------------------- *)

let evwoinv = new_definition
  `evwoinv D (E:A->A->bool) n <=>
     !rn ys. rn IN D /\ ys IN D /\ evwo D E n rn /\ ehfstage D E n ys
        ==> (!p. p IN D /\ E p rn
                 ==> ?u u'. u IN D /\ u' IN D /\ E u ys /\ E u' ys /\
                            ~(u = u') /\ eopair D E u u' p) /\
            (!x y z. x IN D /\ y IN D /\ z IN D /\
                     erel D E rn x y /\ erel D E rn y z
                     ==> erel D E rn x z) /\
            (!x y. x IN D /\ y IN D /\ erel D E rn x y
                   ==> ~(erel D E rn y x)) /\
            (!u u'. u IN D /\ u' IN D /\ E u ys /\ E u' ys /\
                    ~(u = u')
                    ==> erel D E rn u u' \/ erel D E rn u' u) /\
            (!b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b n /\
                       evwo D E b rb /\ ehfstage D E b yb
                       ==> !u u'. u IN D /\ u' IN D /\
                                  E u yb /\ E u' yb
                                  ==> (erel D E rn u u' <=>
                                       erel D E rb u u')) /\
            (!b yb. b IN D /\ yb IN D /\ E b n /\ ehfstage D E b yb
                    ==> !u u'. u IN D /\ u' IN D /\ E u yb /\
                               E u' ys /\ ~(E u' yb)
                               ==> erel D E rn u u')`;;

let EVWO_TOPCOH = prove
 (`!D (E:A->A->bool) n rn ys.
        model D E ZF_AX /\ eordinal D E n /\
        rn IN D /\ evwo D E n rn /\ ys IN D /\ ehfstage D E n ys /\
        (!b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b n /\
                   evwo D E b rb /\ ehfstage D E b yb
                   ==> !u u'. u IN D /\ u' IN D /\ E u yb /\ E u' yb
                              ==> (erel D E rn u u' <=>
                                   erel D E rb u u')) /\
        (!x y. x IN D /\ y IN D /\ erel D E rn x y
               ==> ~(erel D E rn y x)) /\
        (!u u'. u IN D /\ u' IN D /\ E u ys /\ E u' ys /\ ~(u = u')
                ==> erel D E rn u u' \/ erel D E rn u' u)
        ==> !u u'. u IN D /\ u' IN D /\ E u ys /\ E u' ys
                   ==> (erel D E rn u u' <=>
                        ewoltrel D E rn ys u u')`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(LABEL_TAC "tot" o check (fun th ->
    can (find_term is_disj) (concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "asym" o check (fun th ->
    can (find_term is_neg) (concl th) && is_forall(concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "coh" o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "evwo")) (concl th) &&
    is_forall(concl th))) THEN
  SUBGOAL_THEN `(n:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u'. u IN D /\ u' IN D /\ (E:A->A->bool) u ys /\ E u' ys /\
           erel D E rn u u'
           ==> ewoltrel D E rn ys u u'`
  (LABEL_TAC "fwd") THENL [ALL_TAC;
    REPEAT STRIP_TAC THEN EQ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `~(u:A = u')` ASSUME_TAC THENL
     [ASM_MESON_TAC[ewoltrel]; ALL_TAC] THEN
    SUBGOAL_THEN `~(erel D (E:A->A->bool) rn u' u)`
    ASSUME_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `ewoltrel D (E:A->A->bool) rn ys u' u`
      ASSUME_TAC THENL
       [USE_THEN "fwd" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      ASM_MESON_TAC[WOLTREL_ASYM];
      ALL_TAC] THEN
    ASM_MESON_TAC[]] THEN
  REPEAT STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o CONJUNCT2 o GEN_REWRITE_RULE I [erel] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "erel")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `rn:A`]
    EVWO_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
    check (fun a -> can (find_term ((=) `rn:A`)) (concl a) &&
      can (find_term ((=) `p:A`)) (concl a) &&
      not(can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "eopair")) (concl a))))) THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `yc:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 STRIP_ASSUME_TAC
          (CONJUNCTS_THEN2 ASSUME_TAC
            (X_CHOOSE_THEN `u1:A` (CONJUNCTS_THEN2 ASSUME_TAC
              (X_CHOOSE_THEN `u1':A` STRIP_ASSUME_TAC))))))))))) THEN
  SUBGOAL_THEN `u1:A = u /\ u1':A = u'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `!t:A. t IN D /\ (E:A->A->bool) t yc ==> E t ys`
  (LABEL_TAC "mono") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `n:A`;
                  `yc:A`; `ys:A`; `t:A`] EHFSTAGE_MONO) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ewoltrel] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `esubset D (E:A->A->bool) u ys /\ esubset D E u' ys`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN EXISTS_TAC `mx:A` THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `q:A = mx \/ erel D (E:A->A->bool) rc q mx`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC; ALL_TAC] THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISJ2_TAC THEN
  USE_THEN "coh" (fun th ->
    MP_TAC(SPECL [`c:A`; `rc:A`; `yc:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`q:A`; `mx:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    USE_THEN "mono" (fun th -> ALL_TAC) THEN
    ASM_MESON_TAC[esubset];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]);;

let EVWO_SUC_REL = prove
 (`!D (E:A->A->bool) n sn rn ys y.
        model D E ZF_AX /\ eordinal D E n /\ esuc D E n sn /\
        rn IN D /\ evwo D E n rn /\
        ys IN D /\ ehfstage D E n ys /\
        y IN D /\ evwo D E sn y /\
        (!b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b n /\
                   evwo D E b rb /\ ehfstage D E b yb
                   ==> !u u'. u IN D /\ u' IN D /\ E u yb /\ E u' yb
                              ==> (erel D E rn u u' <=>
                                   erel D E rb u u'))
        ==> !u u'. u IN D /\ u' IN D
                   ==> (erel D E y u u' <=>
                        ewoltrel D E rn ys u u')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`; `rn:A`;
                `ys:A`; `y:A`] EVWO_SUC_NORMALIZE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "nm") THEN
  REPEAT STRIP_TAC THEN EQ_TAC THENL
   [REWRITE_TAC[erel] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC o CONJUNCT2 o
               CONJUNCT2) THEN
    USE_THEN "nm" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> FIRST_X_ASSUM(MP_TAC o
      GEN_REWRITE_RULE I [th] o
      check (fun a -> can (find_term ((=) `p:A`)) (concl a) &&
        can (find_term ((=) `y:A`)) (concl a)))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u1:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `u1':A` STRIP_ASSUME_TAC))) THEN
    SUBGOAL_THEN `u1:A = u /\ u1':A = u'`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    REWRITE_TAC[ewoltrel] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [ewoltrel]) THEN
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REWRITE_TAC[erel] THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `p:A` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "nm" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `mx:A` THEN ASM_REWRITE_TAC[]]);;

let EVWOINV_BASE = prove
 (`!D (E:A->A->bool) e.
        model D E ZF_AX /\ e IN D /\ eempty D E e
        ==> evwoinv D E e`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
  REWRITE_TAC[evwoinv] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `!p:A. p IN D ==> ~((E:A->A->bool) p rn)`
  (LABEL_TAC "rne") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `rn:A`]
      EVWO_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[eempty];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D ==> ~((E:A->A->bool) u ys)`
  (LABEL_TAC "yse") THENL
   [ASM_MESON_TAC[EHFSTAGE_EMPTY; eempty]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y:A. ~(erel D (E:A->A->bool) rn x y)`
  (LABEL_TAC "rel0") THENL
   [REWRITE_TAC[erel] THEN ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[];
    ASM_MESON_TAC[eempty];
    ASM_MESON_TAC[eempty]]);;

let EVWOINV_STEP = prove
 (`!D (E:A->A->bool) om n sn.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ sn IN D /\ esuc D E n sn /\
        evwoinv D E n
        ==> evwoinv D E sn`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL; EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `!b:A. b IN D ==> ((E:A->A->bool) b sn <=> E b n \/ b = n)`
  (LABEL_TAC "suc") THENL [ASM_MESON_TAC[ESUC_ALT]; ALL_TAC] THEN
  SUBGOAL_THEN `?rn:A. rn IN D /\ evwo D (E:A->A->bool) n rn`
  (X_CHOOSE_THEN `rn:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EVWO_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?ys:A. ys IN D /\ ehfstage D (E:A->A->bool) n ys`
  (X_CHOOSE_THEN `ys:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  UNDISCH_TAC `evwoinv D (E:A->A->bool) n` THEN
  REWRITE_TAC[evwoinv] THEN
  DISCH_THEN(MP_TAC o SPECL [`rn:A`; `ys:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "an bn cn dn en fn" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`; `ys:A`;
                `rn:A`] STAGE_MAXHYP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "bn" ACCEPT_TAC; USE_THEN "dn" ACCEPT_TAC];
    DISCH_THEN(LABEL_TAC "mh")] THEN
  X_GEN_TAC `rsn:A` THEN X_GEN_TAC `ysn:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!u u'. u IN D /\ u' IN D
           ==> (erel D (E:A->A->bool) rsn u u' <=>
                ewoltrel D E rn ys u u')`
  (LABEL_TAC "rc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`; `rn:A`;
                  `ys:A`; `rsn:A`] EVWO_SUC_REL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "en" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u'. u IN D /\ u' IN D /\ (E:A->A->bool) u ys /\ E u' ys
           ==> (erel D E rn u u' <=> ewoltrel D E rn ys u u')`
  (LABEL_TAC "tc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `rn:A`;
                  `ys:A`] EVWO_TOPCOH) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
       [USE_THEN "en" ACCEPT_TAC; USE_THEN "cn" ACCEPT_TAC;
        USE_THEN "dn" ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w ysn <=> esubset D E w ys)`
  (LABEL_TAC "sc") THENL
   [ASM_MESON_TAC[EHFSTAGE_SUC_CHAR]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p. p IN D
        ==> ((E:A->A->bool) p rsn <=>
             ?u. u IN D /\
                 ?u'. u' IN D /\
                      eopair D E u u' p /\
                      esubset D E u ys /\ esubset D E u' ys /\
                      ~(u = u') /\
                      ?mx. mx IN D /\ (E mx u <=> ~E mx u') /\
                           (!t. t IN D /\ (E t u <=> ~E t u')
                                ==> t = mx \/ erel D E rn t mx) /\
                           E mx u')`
  (LABEL_TAC "nm") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`; `rn:A`;
                  `ys:A`; `rsn:A`] EVWO_SUC_NORMALIZE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "en" ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `p:A` THEN STRIP_TAC THEN
    USE_THEN "nm" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `u':A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sc" (fun th -> ASM_SIMP_TAC[th]);
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `ewoltrel D (E:A->A->bool) rn ys x y /\ ewoltrel D E rn ys y z`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
    SUBGOAL_THEN `ewoltrel D (E:A->A->bool) rn ys x z`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rn:A`; `ys:A`;
                    `x:A`; `y:A`; `z:A`] WOLTREL_TRANS) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
         [USE_THEN "bn" ACCEPT_TAC; USE_THEN "cn" ACCEPT_TAC;
          USE_THEN "mh" ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
