let vwoinv_form = new_definition
  `vwoinv_form =
     !!11 (!!12
           ((vwo_form 0 11 && hfstage_form 0 12) -->
            (!!4 ((4 %% 11) -->
                  ??5 (??6 ((5 %% 12) &&
                            ((6 %% 12) &&
                             (Not(Eq 5 6) && opair_form 5 6 4)))))) &&
            ((!!4 (!!5
                   (!!6 ((rel_form 11 4 5 && rel_form 11 5 6) -->
                         rel_form 11 4 6)))) &&
             ((!!4 (!!5 (rel_form 11 4 5 --> Not(rel_form 11 5 4)))) &&
              ((!!4 (!!5
                     (((4 %% 12) && ((5 %% 12) && Not(Eq 4 5))) -->
                      (rel_form 11 4 5 || rel_form 11 5 4)))) &&
               ((!!7 (!!13
                      (!!14 (((7 %% 0) && (vwo_form 7 13 && hfstage_form 7 14))
                             --> !!4 (!!5
                                      (((4 %% 14) && (5 %% 14)) -->
                                       (rel_form 11 4 5 <->
                                        rel_form 13 4 5))))))) &&
                (!!7 (!!14
                      (((7 %% 0) && hfstage_form 7 14) -->
                       !!4 (!!5 (((4 %% 14) && ((5 %% 12) && Not(5 %% 14))) -->
                                 rel_form 11 4 5)))))))))))`;;

let HOLDS_VWOINV_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v vwoinv_form <=> evwoinv D E (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
