   `!rn ys:A. rn IN D /\ ys IN D
      ==> (holds D E ((12 |-> ys) ((11 |-> rn) v))
             (vwo_form 0 11) <=>
           evwo D (E:A->A->bool) (v 0) rn) /\
          (holds D E ((12 |-> ys) ((11 |-> rn) v))
             (hfstage_form 0 12) <=>
           ehfstage D E (v 0) ys)`
  (LABEL_TAC "gd") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((12 |-> (ys:A)) ((11 |-> (rn:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(12 |-> (ys:A)) ((11 |-> (rn:A)) v)`; `0`; `11`]
        HOLDS_VWO_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(12 |-> (ys:A)) ((11 |-> (rn:A)) v)`; `0`; `12`]
        HOLDS_HFSTAGE_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!rn ys p u u':A.
      rn IN D /\ ys IN D /\ p IN D /\ u IN D /\ u' IN D
      ==> (holds D E ((6 |-> u') ((5 |-> u) ((4 |-> p)
             ((12 |-> ys) ((11 |-> rn) v))))) (opair_form 5 6 4) <=>
           eopair D (E:A->A->bool) u u' p)`
  (LABEL_TAC "ra") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (u':A)) ((5 |-> (u:A)) ((4 |-> (p:A))
         ((12 |-> (ys:A)) ((11 |-> (rn:A)) v))))`;
      `5`; `6`; `4`] HOLDS_OPAIR_FORM) THEN
