      `11`; `4`; `5`] HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[vwoinv_form; HOLDS_EX; HOLDS_AND; HOLDS_IFF; HOLDS_NOT;
              HOLDS_OR; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN REWRITE_TAC[evwoinv] THEN
  USE_THEN "gd" (fun t1 -> USE_THEN "rb3" (fun t2 ->
    USE_THEN "rb2" (fun t3 -> USE_THEN "ge" (fun t4 ->
      USE_THEN "re" (fun t5 -> USE_THEN "gf" (fun t6 ->
        USE_THEN "rf" (fun t7 ->
          ASM_SIMP_TAC[t1; t2; t3; t4; t5; t6; t7]))))))) THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `rn:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `ys:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a <=> c) /\ (b <=> d) ==> ((a /\ b) <=> (c /\ d))`) THEN
  CONJ_TAC THENL [ALL_TAC; REWRITE_TAC[]] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `p:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `u':A` STRIP_ASSUME_TAC))) THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ra" (fun th ->
      MP_TAC(SPECL [`rn:A`; `ys:A`; `p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ra" (fun th ->
      MP_TAC(SPECL [`rn:A`; `ys:A`; `p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let EVWO_INVARIANT = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ eomega D E om
        ==> !n. n IN D /\ E n om ==> evwoinv D E n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\i:num. (om:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `vwoinv_form`;
                `0`; `\i:num. (om:A)`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REPEAT STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) (\i:num. (om:A)))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      ASM_SIMP_TAC[HOLDS_VWOINV_FORM] THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN ASM_MESON_TAC[EVWOINV_BASE];
      REPEAT STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) (\i:num. (om:A))) /\
                    valuation D ((0 |-> (m:A)) (\i:num. (om:A)))`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o check (can (find_term (fun t ->
        is_const t && fst(dest_const t) = "holds")) o concl)) THEN
      ASM_SIMP_TAC[HOLDS_VWOINV_FORM] THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN ASM_MESON_TAC[EVWOINV_STEP]];
    DISCH_TAC THEN X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `valuation D ((0 |-> (n:A)) (\i:num. (om:A)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_VWOINV_FORM] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The canonical order on all hereditarily finite elements: ehford om is     *)
(* the union of the stage orders evwo n over n in om (existence by           *)
(* replacement along rec_form ewostep_form 2, mirroring EHFSET_EXISTS).      *)
(* EHFORD_EREL characterizes its erel as holding at some stage; by           *)
(* coherence (EVWO_MONO_REL, from clause (e) of the invariant, membership    *)
(* of related elements in the stage from clause (a) via EVWO_REL_IN) any     *)
(* two stages embed in a common one (EVWO_COMMON, ordinal trichotomy), so    *)
(* the union is transitive, asymmetric, and total on the members of the hf   *)
(* set (EHFORD_TRANS/ASYM/TOTAL).                                            *)
(* ------------------------------------------------------------------------- *)

let ehford = new_definition
  `ehford D (E:A->A->bool) w h <=>
        h IN D /\
        !p. p IN D
            ==> (E p h <=>
                 ?n r. n IN D /\ r IN D /\ E n w /\
                       evwo D E n r /\ E p r)`;;

let EHFORD_UNIQUE = prove
 (`!D (E:A->A->bool) w h h'.
        model D E ZF_AX /\ ehford D E w h /\ ehford D E w h'
        ==> h = h'`,
  REWRITE_TAC[ehford] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let EHFORD_EXISTS = prove
 (`!D (E:A->A->bool) w.
      model D E ZF_AX /\ eomega D E w ==> ?h. ehford D E w h`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`rec_form ewostep_form 2`; `2`; `3`; `v:num->A`; `w:A`] o
    MATCH_MP ZF_REPLACEMENT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`]
          EVWO_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `erec D (E:A->A->bool) ewostep_form v u w'`
    ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                    `ewostep_form`; `2`; `u:A`; `w':A`]
            HOLDS_REC_FORM) THEN
      ASM_REWRITE_TAC[FVLT_EWOSTEP_FORM; ARITH_RULE `1 < 2`] THEN
      DISCH_THEN(SUBST1_TAC o SYM) THEN
      ASM_REWRITE_TAC[ARITH_RULE `2 + 1 = 3`];
      ALL_TAC] THEN
    SUBGOAL_THEN `evwo D (E:A->A->bool) u w'` ASSUME_TAC THENL
     [ASM_MESON_TAC[EVWO_EREC]; ALL_TAC] THEN
    MATCH_MP_TAC EVWO_UNIQUE THEN
    MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `u:A`] THEN
    ASM_MESON_TAC[EORDINAL_IN];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `B:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
        ==> ((E:A->A->bool) z B <=>
             ?n. n IN D /\ E n w /\ evwo D E n z)`
  (LABEL_TAC "Bch") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    FIRST_X_ASSUM(fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(z:A) IN D`)) THEN
      ASSUME_TAC th) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THENL
     [SUBGOAL_THEN `erec D (E:A->A->bool) ewostep_form v n z`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                      `ewostep_form`; `2`; `n:A`; `z:A`]
              HOLDS_REC_FORM) THEN
        ASM_REWRITE_TAC[FVLT_EWOSTEP_FORM; ARITH_RULE `1 < 2`] THEN
        DISCH_THEN(SUBST1_TAC o SYM) THEN
        ASM_REWRITE_TAC[ARITH_RULE `2 + 1 = 3`];
        ALL_TAC] THEN
      ASM_MESON_TAC[EVWO_EREC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
                    `ewostep_form`; `2`; `n:A`; `z:A`]
            HOLDS_REC_FORM) THEN
      ASM_REWRITE_TAC[FVLT_EWOSTEP_FORM; ARITH_RULE `1 < 2`] THEN
      REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[EVWO_EREC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(B:A) IN D` ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `B:A`]
        EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  EXISTS_TAC `h:A` THEN
  SUBGOAL_THEN `(h:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  ASM_REWRITE_TAC[ehford] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(E:A->A->bool) u h <=> ?y. y IN D /\ E y B /\ E u y`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "Bch" (fun th ->
      MP_TAC(MATCH_MP th (ASSUME `(y:A) IN D`))) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `y:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `y:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "Bch" (fun th ->
      REWRITE_TAC[MATCH_MP th (ASSUME `(y:A) IN D`)]) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[]]);;

let EVWO_REL_IN = prove
 (`!D (E:A->A->bool) om n rn ys u u'.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        rn IN D /\ evwo D E n rn /\ ys IN D /\ ehfstage D E n ys /\
        u IN D /\ u' IN D /\ erel D E rn u u'
        ==> E u ys /\ E u' ys /\ ~(u = u')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EVWO_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[evwoinv] THEN
  DISCH_THEN(MP_TAC o SPECL [`rn:A`; `ys:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN(LABEL_TAC "aa") THEN
  FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o CONJUNCT2 o GEN_REWRITE_RULE I [erel] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "erel")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  USE_THEN "aa" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u1:A` (X_CHOOSE_THEN `u1':A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `u1:A = u /\ u1':A = u'`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let EVWO_MONO_REL = prove
 (`!D (E:A->A->bool) om n n' rn rn' u u'.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ n' IN D /\ E n' om /\ E n n' /\
        rn IN D /\ evwo D E n rn /\ rn' IN D /\ evwo D E n' rn' /\
        u IN D /\ u' IN D /\ erel D E rn u u'
        ==> erel D E rn' u u'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `?ys:A. ys IN D /\ ehfstage D (E:A->A->bool) n ys`
  (X_CHOOSE_THEN `ys:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?ys':A. ys' IN D /\ ehfstage D (E:A->A->bool) n' ys'`
  (X_CHOOSE_THEN `ys':A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u ys /\ E u' ys /\ ~(u = u')`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                  `rn:A`; `ys:A`; `u:A`; `u':A`] EVWO_REL_IN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EVWO_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n':A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[evwoinv] THEN
  DISCH_THEN(MP_TAC o SPECL [`rn':A`; `ys':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
             CONJUNCT2 o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPECL [`n:A`; `rn:A`; `ys:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`u:A`; `u':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]));;

let EHFORD_EREL = prove
 (`!D (E:A->A->bool) om ho u u'.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        u IN D /\ u' IN D
        ==> (erel D E ho u u' <=>
             ?n rn. n IN D /\ rn IN D /\ E n om /\ evwo D E n rn /\
                    erel D E rn u u')`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[EREL_IN_IFF] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `?n rn. n IN D /\ rn IN D /\ (E:A->A->bool) n om /\
             evwo D E n rn /\ E p rn`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ehford]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `rn:A`] THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `rn:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ehford]]);;

let EVWO_COMMON = prove
 (`!D (E:A->A->bool) om n n'.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ n' IN D /\ E n' om
        ==> ?N. N IN D /\ E N om /\
                (E n N \/ n = N) /\ (E n' N \/ n' = N)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) n /\ eordinal D E n'`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `n':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [EXISTS_TAC `n':A` THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `n':A` THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[]]);;

let EVWO_LE_REL = prove
 (`!D (E:A->A->bool) om n N rn rN u u'.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ N IN D /\ E N om /\
        (E n N \/ n = N) /\
        rn IN D /\ evwo D E n rn /\ rN IN D /\ evwo D E N rN /\
        u IN D /\ u' IN D /\ erel D E rn u u'
        ==> erel D E rN u u'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC o
    check (is_disj o concl)) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`; `N:A`;
                  `rn:A`; `rN:A`; `u:A`; `u':A`] EVWO_MONO_REL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    SUBGOAL_THEN `rn:A = rN` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EVWO_UNIQUE]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let EHFSTAGE_LE = prove
 (`!D (E:A->A->bool) om n N ys yN u.
        model D E ZF_AX /\ eomega D E om /\
        n IN D /\ E n om /\ N IN D /\ E N om /\
        (E n N \/ n = N) /\
        ys IN D /\ ehfstage D E n ys /\ yN IN D /\
        ehfstage D E N yN /\ u IN D /\ E u ys
        ==> E u yN`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC o
    check (is_disj o concl)) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `N:A`;
                  `ys:A`; `yN:A`; `u:A`] EHFSTAGE_MONO) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
      DISCH_THEN ACCEPT_TAC];
    SUBGOAL_THEN `ys:A = yN` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EHFSTAGE_UNIQUE]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let EHFORD_TRANS = prove
 (`!D (E:A->A->bool) om ho x y z.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        x IN D /\ y IN D /\ z IN D /\
