let EHFORD_TOTAL = prove
 (`!D (E:A->A->bool) om ho hf u u'.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        ehfset D E om hf /\
        u IN D /\ u' IN D /\ E u hf /\ E u' hf /\ ~(u = u')
        ==> erel D E ho u u' \/ erel D E ho u' u`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `?n1 y1. n1 IN D /\ y1 IN D /\ (E:A->A->bool) n1 om /\
            ehfstage D E n1 y1 /\ E u y1`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?n2 y2. n2 IN D /\ y2 IN D /\ (E:A->A->bool) n2 om /\
            ehfstage D E n2 y2 /\ E u' y2`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n1:A`; `n2:A`]
    EVWO_COMMON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@N. h1 h2 h3 h4" THEN
  SUBGOAL_THEN `?rN:A. rN IN D /\ evwo D (E:A->A->bool) N rN`
  (X_CHOOSE_THEN `rN:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EVWO_EXISTS; EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `?yN:A. yN IN D /\ ehfstage D (E:A->A->bool) N yN`
  (X_CHOOSE_THEN `yN:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS; EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u yN /\ E u' yN`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n1:A`;
        `N:A`; `y1:A`; `yN:A`; `u:A`] EHFSTAGE_LE);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n2:A`;
        `N:A`; `y2:A`; `yN:A`; `u':A`] EHFSTAGE_LE)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) rN u u' \/ erel D E rN u' u`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
      EVWO_INVARIANT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `N:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[evwoinv] THEN
    DISCH_THEN(MP_TAC o SPECL [`rN:A`; `yN:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
               CONJUNCT2) THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `u':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC; ALL_TAC] THENL
   [DISJ1_TAC; DISJ2_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`]
    EHFORD_EREL) THENL
   [DISCH_THEN(MP_TAC o SPECL [`u:A`; `u':A`]);
    DISCH_THEN(MP_TAC o SPECL [`u':A`; `u:A`])] THEN
  (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
   DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
   MAP_EVERY EXISTS_TAC [`N:A`; `rN:A`] THEN ASM_REWRITE_TAC[]));;

(* ------------------------------------------------------------------------- *)
(* Least elements: STAGE_MINHYP is the least-element counterpart of          *)
(* STAGE_MAXHYP (the first conjunct of eminmax), and meetstage_form          *)
(* internalizes "some member of z lies in stage V(n)" for the least-stage    *)
(* argument.                                                                 *)
(* ------------------------------------------------------------------------- *)

let STAGE_MINHYP = prove
 (`!D (E:A->A->bool) om n ys r.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om /\
        ys IN D /\ ehfstage D E n ys /\ r IN D /\
        (!a b c. a IN D /\ b IN D /\ c IN D /\
                 erel D E r a b /\ erel D E r b c
                 ==> erel D E r a c) /\
        (!a b. a IN D /\ b IN D /\ E a ys /\ E b ys /\ ~(a = b)
               ==> erel D E r a b \/ erel D E r b a)
        ==> !z. z IN D /\ esubset D E z ys /\ (?t. t IN D /\ E t z)
                ==> ?m. m IN D /\ E m z /\
                        !t. t IN D /\ E t z /\ ~(t = m)
                            ==> erel D E r m t`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EHFSTAGE_ENUM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[eenum] THEN DISCH_THEN(MP_TAC o SPEC `ys:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `j:A` (X_CHOOSE_THEN `h:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EFIN_MINMAX) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `j:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[eminmax] THEN
  DISCH_THEN(MP_TAC o SPECL [`h:A`; `r:A`; `z:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `tt:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      ASM_MESON_TAC[esubset];
      CONJ_TAC THENL
       [ASM_MESON_TAC[esubset]; ASM_MESON_TAC[]]];
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN
    MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

let meetstage_form = new_definition
  `meetstage_form =
     ??8 (hfstage_form 0 8 && ??9 ((9 %% 1) && (9 %% 8)))`;;

let HOLDS_MEETSTAGE_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v meetstage_form <=>
             ?y. y IN D /\ ehfstage D E (v 0) y /\
                 ?t. t IN D /\ E t (v 1) /\ E t y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((8 |-> y) v) (hfstage_form 0 8) <=>
           ehfstage D (E:A->A->bool) (v 0) y)`
  (LABEL_TAC "st") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(8 |-> (y:A)) v`;
      `0`; `8`] HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[meetstage_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `y:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "st" (fun th -> ASM_SIMP_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* The least-element principle: every nonempty subset z of the hf set has    *)
(* an hford-least element.  The least stage d meeting z comes from           *)
(* EORDINAL_LEAST applied to meetstage_form (d lies in om since it is at     *)
(* most the witness stage, by minimality plus trichotomy and the             *)
(* transitivity of om); the evwo d-least element m of z inter V(d) comes     *)
(* from STAGE_MINHYP; and m precedes every other member of z: within V(d)    *)
(* by leastness, outside V(d) by the stage-initial-segment clause of the     *)
(* invariant at the member's own stage (which contains d by minimality of    *)
(* d and trichotomy).  So ehford om is a wellordering of the hereditarily    *)
(* finite elements.                                                          *)
(* ------------------------------------------------------------------------- *)

let EHFORD_LEAST = prove
 (`!D (E:A->A->bool) om ho hf z.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        ehfset D E om hf /\ z IN D /\
        (!t. t IN D /\ E t z ==> E t hf) /\
        (?t. t IN D /\ E t z)
        ==> ?m. m IN D /\ E m z /\
                !t. t IN D /\ E t z /\ ~(t = m)
                    ==> erel D E ho m t`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC o
    check (is_exists o concl)) THEN
  FIRST_ASSUM(LABEL_TAC "hfc" o CONJUNCT2 o
    GEN_REWRITE_RULE I [ehfset] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "ehfset")) (concl th)) o
    check (fun th -> not(is_forall(concl th)))) THEN
  SUBGOAL_THEN `(E:A->A->bool) t0 hf` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "hfc" (fun th -> MP_TAC(SPEC `t0:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `n0:A` (X_CHOOSE_THEN `y0:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v' = (1 |-> (z:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v':num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v'" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v':num->A) 1 = z` ASSUME_TAC THENL
   [EXPAND_TAC "v'" THEN REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:A. n IN D
      ==> (holds D E ((0 |-> n) v') meetstage_form <=>
           ?y. y IN D /\ ehfstage D (E:A->A->bool) n y /\
               ?t. t IN D /\ E t z /\ E t y)`
  (LABEL_TAC "ms") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n:A)) v'`]
      HOLDS_MEETSTAGE_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `meetstage_form`;
                `v':num->A`; `n0:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "ms" (fun th -> MP_TAC(SPEC `n0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `t0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@d. h1 h2 hd mind" THEN
  USE_THEN "hd" MP_TAC THEN
  USE_THEN "ms" (fun th -> MP_TAC(SPEC `d:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `td:A`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `?zd:A. einter D (E:A->A->bool) z yd zd`
  (X_CHOOSE_TAC `zd:A`) THENL
   [ASM_MESON_TAC[EINTER_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(zd:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w zd <=> E w z /\ E w yd)`
  (LABEL_TAC "zdc") THENL
   [ASM_MESON_TAC[einter]; ALL_TAC] THEN
  SUBGOAL_THEN `?rd:A. rd IN D /\ evwo D (E:A->A->bool) d rd`
  (X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EVWO_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) n0 d)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN
     `holds D (E:A->A->bool) ((0 |-> n0) v') meetstage_form`
    ASSUME_TAC THENL
     [USE_THEN "ms" (fun th -> MP_TAC(SPEC `n0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `t0:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REMOVE_THEN "mind" (MP_TAC o SPEC `n0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d om` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `n0:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
      ASM_MESON_TAC[eordinal; etransitive; esubset];
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
    EVWO_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `d:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[evwoinv] THEN
  DISCH_THEN(MP_TAC o SPECL [`rd:A`; `yd:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "_ bd _ dd _" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `d:A`;
                `yd:A`; `rd:A`] STAGE_MINHYP) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "bd" ACCEPT_TAC; USE_THEN "dd" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `zd:A`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[esubset] THEN
      X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      USE_THEN "zdc" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> can (find_term ((=) `zd:A`)) (concl a) &&
            not(is_forall(concl a)) &&
            not(can (find_term (fun tm -> is_const tm &&
              fst(dest_const tm) = "einter")) (concl a)) &&
            not(can (find_term (fun tm -> is_const tm &&
              fst(dest_const tm) = "IN")) (concl a))))) THEN
      SIMP_TAC[];
      EXISTS_TAC `td:A` THEN
      USE_THEN "zdc" (fun th -> MP_TAC(SPEC `td:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@m. h3 h4 mls" THEN
  EXISTS_TAC `m:A` THEN
  SUBGOAL_THEN `(E:A->A->bool) m z /\ E m yd` STRIP_ASSUME_TAC THENL
   [USE_THEN "zdc" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m zd`))) THEN
    SIMP_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) t yd` THENL
   [SUBGOAL_THEN `(E:A->A->bool) t zd` ASSUME_TAC THENL
     [USE_THEN "zdc" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) rd m t` ASSUME_TAC THENL
     [USE_THEN "mls" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
                  `m:A`; `t:A`] EHFORD_EREL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`d:A`; `rd:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) t hf` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  USE_THEN "hfc" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `nt:A` (X_CHOOSE_THEN `yt:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) d nt` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `nt:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
      ALL_TAC] THEN
    STRIP_TAC THENL
     [ASM_MESON_TAC[EHFSTAGE_UNIQUE];
      SUBGOAL_THEN
       `holds D (E:A->A->bool) ((0 |-> nt) v') meetstage_form`
      ASSUME_TAC THENL
       [USE_THEN "ms" (fun th -> MP_TAC(SPEC `nt:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `yt:A` THEN ASM_REWRITE_TAC[] THEN
        EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      REMOVE_THEN "mind" (MP_TAC o SPEC `nt:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?rt:A. rt IN D /\ evwo D (E:A->A->bool) nt rt`
  (X_CHOOSE_THEN `rt:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EVWO_EXISTS; EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rt m t` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
      EVWO_INVARIANT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `nt:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[evwoinv] THEN
    DISCH_THEN(MP_TAC o SPECL [`rt:A`; `yt:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2 o CONJUNCT2 o CONJUNCT2 o
               CONJUNCT2 o CONJUNCT2) THEN
    DISCH_THEN(MP_TAC o SPECL [`d:A`; `yd:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`m:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
                `m:A`; `t:A`] EHFORD_EREL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`nt:A`; `rt:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The first-difference lexicographic comparison of internal functions on an *)
(* ordinal domain (the parameter-tuple order for the Def-step of the L       *)
(* wellordering).  etlex r s s' holds when at some index k the values        *)
(* differ, are r-related left-to-right, and the two functions agree at all   *)
(* earlier indices.  EFUN_EXT is extensionality for internal functions;      *)
(* EORDINAL_SUBSET_LEAST extracts the least element of a nonempty subset of  *)
(* an ordinal directly from foundation (an E-minimal element is least by     *)
(* trichotomy); E_NOCYCLE2 likewise from foundation on a pair.               *)
(* ETLEX_ASYM/TRANS by trichotomy on the two witness indices (composing the  *)
(* agreement zones through the middle function, using EORDINAL_TRANS_E);     *)
(* ETLEX_TOTAL by taking the least differing index, obtained by separation   *)
(* along fneq_form.                                                          *)
(* ------------------------------------------------------------------------- *)

let EFUN_EXT = prove
 (`!D (E:A->A->bool) f g a.
        model D E ZF_AX /\ eisfun D E f /\ eisfun D E g /\
        edomain D E f a /\ edomain D E g a /\
        (!k w w'. k IN D /\ w IN D /\ w' IN D /\
                  eapply D E f k w /\ eapply D E g k w'
                  ==> w = w')
        ==> f = g`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  SUBGOAL_THEN `(f:A) IN D /\ (g:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  EQ_TAC THEN DISCH_TAC THENL
   [SUBGOAL_THEN
     `?u w. u IN D /\ w IN D /\ eopair D (E:A->A->bool) u w z`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) f u w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `?w'. w' IN D /\ eapply D (E:A->A->bool) g u w'`
    (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `w':A = w` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[eapply; EOPAIR_UNIQUE];
    SUBGOAL_THEN
     `?u w. u IN D /\ w IN D /\ eopair D (E:A->A->bool) u w z`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g u w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `?w'. w' IN D /\ eapply D (E:A->A->bool) f u w'`
    (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `w':A = w` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[eapply; EOPAIR_UNIQUE]]);;

let EORDINAL_SUBSET_LEAST = prove
 (`!D (E:A->A->bool) n z.
        model D E ZF_AX /\ eordinal D E n /\ z IN D /\
        (!t. t IN D /\ E t z ==> E t n) /\
        (?t. t IN D /\ E t z)
        ==> ?k. k IN D /\ E k z /\
                !j. j IN D /\ E j z /\ ~(j = k) ==> E k j`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MP_TAC o SPEC `z:A` o MATCH_MP ZF_FOUNDATION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `j:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) k /\ eordinal D E j`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `j:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let etlex = new_definition
  `etlex D (E:A->A->bool) r s s' <=>
        ?k w w'. k IN D /\ w IN D /\ w' IN D /\
                 eapply D E s k w /\ eapply D E s' k w' /\
                 ~(w = w') /\ erel D E r w w' /\
                 (!j v v'. j IN D /\ v IN D /\ v' IN D /\ E j k /\
                           eapply D E s j v /\ eapply D E s' j v'
                           ==> v = v')`;;

let ETLEX_ASYM = prove
 (`!D (E:A->A->bool) r n s s'.
        model D E ZF_AX /\ eordinal D E n /\
        eisfun D E s /\ edomain D E s n /\
        eisfun D E s' /\ edomain D E s' n /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        etlex D E r s s'
        ==> ~(etlex D E r s' s)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `k:A` (X_CHOOSE_THEN `w:A`
    (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC)) o
    GEN_REWRITE_RULE I [etlex]) THEN
  REWRITE_TAC[etlex] THEN
  DISCH_THEN(X_CHOOSE_THEN `k':A` (X_CHOOSE_THEN `v':A`
    (X_CHOOSE_THEN `v:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `(E:A->A->bool) k n /\ E k' n` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) k /\ eordinal D E k'`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `k':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [ASM_MESON_TAC[];
    ASM_MESON_TAC[EAPPLY_UNIQUE];
    ASM_MESON_TAC[]]);;

let EAPPLY_DOM = prove
 (`!D (E:A->A->bool) f n k.
        model D E ZF_AX /\ eisfun D E f /\ edomain D E f n /\
        k IN D /\ E k n
        ==> ?w. w IN D /\ eapply D E f k w`,
  REWRITE_TAC[edomain; eindom] THEN MESON_TAC[]);;

let EORDINAL_TRANS_E = prove
 (`!D (E:A->A->bool) n j k.
        model D E ZF_AX /\ eordinal D E n /\
        j IN D /\ k IN D /\ E j k /\ E k n
        ==> E j n`,
  REWRITE_TAC[eordinal; etransitive] THEN
  MESON_TAC[esubset]);;

let ETLEX_TRANS = prove
 (`!D (E:A->A->bool) r n s s' s''.
        model D E ZF_AX /\ eordinal D E n /\
        eisfun D E s /\ edomain D E s n /\
        eisfun D E s' /\ edomain D E s' n /\
        eisfun D E s'' /\ edomain D E s'' n /\
        (!a b c. a IN D /\ b IN D /\ c IN D /\
                 erel D E r a b /\ erel D E r b c
                 ==> erel D E r a c) /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        etlex D E r s s' /\ etlex D E r s' s''
        ==> etlex D E r s s''`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `k2:A`
  (DESTRUCT_TAC "@u' u''. h1 h2 h3 h4 h5 h6 ag2")  o
    GEN_REWRITE_RULE I [etlex] o
    check (fun th -> can (find_term ((=) `s'':A`)) (concl th))) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `k1:A`
  (DESTRUCT_TAC "@w w'. h7 h8 h9 h10 h11 h12 ag1")  o
    GEN_REWRITE_RULE I [etlex] o
    check (fun th -> can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "etlex")) (concl th))) THEN
  SUBGOAL_THEN `(E:A->A->bool) k1 n /\ E k2 n` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) k1 /\ eordinal D E k2`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[etlex] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k1:A`; `k2:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
  [SUBGOAL_THEN `?v. v IN D /\ eapply D (E:A->A->bool) s'' k1 v`
  (X_CHOOSE_THEN `v0:A` STRIP_ASSUME_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s'':A`; `n:A`;
                  `k1:A`] EAPPLY_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `v0:A = w'` SUBST_ALL_TAC THENL
   [USE_THEN "ag2" (fun th ->
      MP_TAC(SPECL [`k1:A`; `w':A`; `v0:A`] (CONJUNCT2 th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`k1:A`; `w:A`; `w':A`] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) j n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) j k2` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
  SUBGOAL_THEN `?vm. vm IN D /\ eapply D (E:A->A->bool) s' j vm`
  (X_CHOOSE_THEN `vm:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EAPPLY_DOM]; ALL_TAC] THEN
  USE_THEN "ag1" (fun t1 -> USE_THEN "ag2" (fun t2 ->
    ASM_MESON_TAC[CONJUNCT2 t1; CONJUNCT2 t2]));
   UNDISCH_TAC `k1:A = k2` THEN DISCH_THEN SUBST_ALL_TAC THEN
  SUBGOAL_THEN `w':A = u'` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EAPPLY_UNIQUE]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`k2:A`; `w:A`; `u'':A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "ag1" (fun t1 -> USE_THEN "ag2" (fun t2 ->
      ASM_MESON_TAC[CONJUNCT1 t1; CONJUNCT1 t2]));
    USE_THEN "ag1" (fun t1 -> USE_THEN "ag2" (fun t2 ->
      ASM_MESON_TAC[CONJUNCT1 t1; CONJUNCT1 t2]));
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) j n` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
    SUBGOAL_THEN `?vm. vm IN D /\ eapply D (E:A->A->bool) s' j vm`
    (X_CHOOSE_THEN `vm:A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[EAPPLY_DOM]; ALL_TAC] THEN
    USE_THEN "ag1" (fun t1 -> USE_THEN "ag2" (fun t2 ->
      ASM_MESON_TAC[CONJUNCT2 t1; CONJUNCT2 t2]))];
   SUBGOAL_THEN `?v. v IN D /\ eapply D (E:A->A->bool) s k2 v`
  (X_CHOOSE_THEN `v0:A` STRIP_ASSUME_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `n:A`; `k2:A`]
      EAPPLY_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `v0:A = u'` SUBST_ALL_TAC THENL
   [USE_THEN "ag1" (fun th ->
      MP_TAC(SPECL [`k2:A`; `v0:A`; `u':A`] (CONJUNCT2 th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MESON_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`k2:A`; `u':A`; `u'':A`] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) j n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) j k1` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
  SUBGOAL_THEN `?vm. vm IN D /\ eapply D (E:A->A->bool) s' j vm`
  (X_CHOOSE_THEN `vm:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EAPPLY_DOM]; ALL_TAC] THEN
  USE_THEN "ag1" (fun t1 -> USE_THEN "ag2" (fun t2 ->
    ASM_MESON_TAC[CONJUNCT2 t1; CONJUNCT2 t2]))]);;

let fneq_form = new_definition
  `fneq_form =
     Not(!!3 (!!4 ((apply_form 1 0 3 && apply_form 2 0 4) -->
                   Eq 3 4)))`;;

let HOLDS_FNEQ_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v fneq_form <=>
             ~(!w w'. w IN D /\ w' IN D /\
                      eapply D E (v 1) (v 0) w /\
                      eapply D E (v 2) (v 0) w'
                      ==> w = w'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w w':A. w IN D /\ w' IN D
      ==> (holds D E ((4 |-> w') ((3 |-> w) v))
             (apply_form 1 0 3) <=>
           eapply D (E:A->A->bool) (v 1) (v 0) w) /\
          (holds D E ((4 |-> w') ((3 |-> w) v))
             (apply_form 2 0 4) <=>
           eapply D E (v 2) (v 0) w')`
  (LABEL_TAC "ap") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (w':A)) ((3 |-> (w:A)) v)`; `1`; `0`; `3`]
        HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (w':A)) ((3 |-> (w:A)) v)`; `2`; `0`; `4`]
        HOLDS_APPLY_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[fneq_form; HOLDS_NOT; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  AP_TERM_TAC THEN REWRITE_TAC[IMP_CONJ] THEN
  REWRITE_TAC[RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `w:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `w':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "ap" (fun th -> ASM_SIMP_TAC[th]));;

let ETLEX_TOTAL = prove
 (`!D (E:A->A->bool) r n X s s'.
        model D E ZF_AX /\ eordinal D E n /\ X IN D /\
        eisfun D E s /\ edomain D E s n /\
        eisfun D E s' /\ edomain D E s' n /\
        (!k w. k IN D /\ w IN D /\ eapply D E s k w ==> E w X) /\
        (!k w. k IN D /\ w IN D /\ eapply D E s' k w ==> E w X) /\
        (!a b. a IN D /\ b IN D /\ E a X /\ E b X /\ ~(a = b)
               ==> erel D E r a b \/ erel D E r b a) /\
        ~(s = s')
        ==> etlex D E r s s' \/ etlex D E r s' s`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(n:A) IN D /\ (s:A) IN D /\ (s':A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN; eisfun]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`fneq_form`; `0`; `(2 |-> (s':A)) ((1 |-> (s:A)) v0)`; `n:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dz:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "dzc"))) THEN
  SUBGOAL_THEN
   `!k:A. k IN D
      ==> ((E:A->A->bool) k dz <=>
           E k n /\
           ~(!w w'. w IN D /\ w' IN D /\
                    eapply D E s k w /\ eapply D E s' k w'
                    ==> w = w'))`
  (LABEL_TAC "dch") THENL
   [X_GEN_TAC `k:A` THEN DISCH_TAC THEN
    USE_THEN "dzc" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (k:A)) ((2 |-> (s':A)) ((1 |-> (s:A)) v0))`]
      HOLDS_FNEQ_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?k:A. k IN D /\ (E:A->A->bool) k dz`
  STRIP_ASSUME_TAC THENL
   [REFUTE_THEN(ASSUME_TAC o REWRITE_RULE[NOT_EXISTS_THM]) THEN
    SUBGOAL_THEN `s:A = s'` (fun th -> ASM_MESON_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `s':A`; `n:A`]
      EFUN_EXT) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) k n` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `~((E:A->A->bool) k dz)` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "dch" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `dz:A`]
    EORDINAL_SUBSET_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `j:A` THEN STRIP_TAC THEN
      USE_THEN "dch" (fun th -> ASM_MESON_TAC[th]);
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `k0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `(E:A->A->bool) k0 n /\
    ~(!w w'. w IN D /\ w' IN D /\
             eapply D E s k0 w /\ eapply D E s' k0 w'
             ==> w = w')`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "dch" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `?w. w IN D /\ eapply D (E:A->A->bool) s k0 w`
  (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EAPPLY_DOM]; ALL_TAC] THEN
  SUBGOAL_THEN `?w'. w' IN D /\ eapply D (E:A->A->bool) s' k0 w'`
  (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[EAPPLY_DOM]; ALL_TAC] THEN
  SUBGOAL_THEN `~(w:A = w')` ASSUME_TAC THENL
   [ASM_MESON_TAC[EAPPLY_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!j v v'. j IN D /\ v IN D /\ v' IN D /\ (E:A->A->bool) j k0 /\
             eapply D E s j v /\ eapply D E s' j v'
             ==> v = v'`
  (LABEL_TAC "agl") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) j n` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `~((E:A->A->bool) j dz)` ASSUME_TAC THENL
     [ASM_MESON_TAC[E_NOCYCLE2; E_IRREFL]; ALL_TAC] THEN
    USE_THEN "dch" (fun th -> MP_TAC(SPEC `j:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `erel D (E:A->A->bool) r w w' \/ erel D E r w' w`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC; ALL_TAC] THENL
   [DISJ1_TAC; DISJ2_TAC] THEN
  REWRITE_TAC[etlex] THENL
   [MAP_EVERY EXISTS_TAC [`k0:A`; `w:A`; `w':A`];
    MAP_EVERY EXISTS_TAC [`k0:A`; `w':A`; `w:A`]] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  USE_THEN "agl" (fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* Internal statement of the tuple-lexicographic least-element principle.    *)
(* tlexf_form: slots 4,5 = the two functions, 12 = the wellordering of the   *)
(* value carrier; says s4 <_tlex s5 (first-difference comparison).           *)
(* tll_form: slot 0 = the common domain n; says every nonempty set S of      *)
(* functions with domain n into a carrier X wellordered (least-element       *)
(* principle for nonempty subsets) by rX has an etlex-least element.         *)
(* ------------------------------------------------------------------------- *)

let tlexf_form = new_definition
  `tlexf_form =
     ??7 (??8 (??9
               (apply_form 4 7 8 &&
                (apply_form 5 7 9 &&
                 (Not(Eq 8 9) &&
                  (rel_form 12 8 9 &&
                   !!10 (!!14
                         (!!15 (((10 %% 7) &&
                                 (apply_form 4 10 14 && apply_form 5 10 15))
                                --> Eq 14 15)))))))))`;;

let tll_form = new_definition
  `tll_form =
     !!11 (!!12
           (!!13 (((!!4
                    (((!!5 ((5 %% 4) --> (5 %% 11))) && (?? 5 (5 %% 4))) -->
                     ?? 5 ((5 %% 4) &&
                           (!!6 (((6 %% 4) && Not(Eq 6 5)) -->
                                 rel_form 12 5 6))))) &&
                   ((!!4 ((4 %% 13) -->
                          (fun_form 4 &&
                           (domain_form 4 0 &&
                            !!5 (!!6 (apply_form 4 5 6 --> (6 %% 11))))))) &&
                    (?? 4 (4 %% 13)))) -->
                  (?? 4 ((4 %% 13) &&
                         (!!5 (((5 %% 13) && Not(Eq 5 4)) -->
                               tlexf_form)))))))`;;

let etll = new_definition
  `etll D (E:A->A->bool) n <=>
     !X rX S. X IN D /\ rX IN D /\ S IN D /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t X) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E rX m t) /\
        (!s. s IN D /\ E s S
             ==> eisfun D E s /\ edomain D E s n /\
                 (!k w. k IN D /\ w IN D /\ eapply D E s k w
                        ==> E w X)) /\
        (?s. s IN D /\ E s S)
        ==> ?s'. s' IN D /\ E s' S /\
                 !s. s IN D /\ E s S /\ ~(s = s')
                     ==> etlex D E rX s' s`;;

let HOLDS_TLEXF_FORM = prove
 (`!D (E:A->A->bool) u.
        model D E ZF_AX /\ valuation D u
        ==> (holds D E u tlexf_form <=>
             etlex D E (u 12) (u 4) (u 5))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (u:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w w':A. k IN D /\ w IN D /\ w' IN D
      ==> (holds D E ((9 |-> w') ((8 |-> w) ((7 |-> k) u)))
             (apply_form 4 7 8) <=>
           eapply D (E:A->A->bool) (u 4) k w) /\
          (holds D E ((9 |-> w') ((8 |-> w) ((7 |-> k) u)))
             (apply_form 5 7 9) <=>
           eapply D E (u 5) k w') /\
          (holds D E ((9 |-> w') ((8 |-> w) ((7 |-> k) u)))
             (rel_form 12 8 9) <=>
           erel D E (u 12) w w')`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (w':A)) ((8 |-> (w:A)) ((7 |-> (k:A)) u))`;
        `4`; `7`; `8`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (w':A)) ((8 |-> (w:A)) ((7 |-> (k:A)) u))`;
        `5`; `7`; `9`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (w':A)) ((8 |-> (w:A)) ((7 |-> (k:A)) u))`;
        `12`; `8`; `9`] HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w w' j v v':A.
      k IN D /\ w IN D /\ w' IN D /\ j IN D /\ v IN D /\ v' IN D
      ==> (holds D E ((15 |-> v') ((14 |-> v) ((10 |-> j)
             ((9 |-> w') ((8 |-> w) ((7 |-> k) u))))))
             (apply_form 4 10 14) <=>
           eapply D (E:A->A->bool) (u 4) j v) /\
          (holds D E ((15 |-> v') ((14 |-> v) ((10 |-> j)
             ((9 |-> w') ((8 |-> w) ((7 |-> k) u))))))
             (apply_form 5 10 15) <=>
           eapply D E (u 5) j v')`
  (LABEL_TAC "r6") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(15 |-> (v':A)) ((14 |-> (v:A)) ((10 |-> (j:A))
           ((9 |-> (w':A)) ((8 |-> (w:A)) ((7 |-> (k:A)) u)))))`;
        `4`; `10`; `14`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(15 |-> (v':A)) ((14 |-> (v:A)) ((10 |-> (j:A))
           ((9 |-> (w':A)) ((8 |-> (w:A)) ((7 |-> (k:A)) u)))))`;
        `5`; `10`; `15`] HOLDS_APPLY_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[tlexf_form; etlex; HOLDS_EX; HOLDS_AND; HOLDS_NOT;
              holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL
   [INTRO_TAC "@k. h1 @w. h2 @w'. h3 h4 h5 h6 h7 tl" THEN
  MAP_EVERY EXISTS_TAC [`k:A`; `w:A`; `w':A`] THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "r3" (fun th ->
    MP_TAC(SPECL [`k:A`; `w:A`; `w':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  USE_THEN "tl" (fun th -> MP_TAC(SPEC `j:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `v:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `v':A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN
  USE_THEN "r6" (fun th -> MP_TAC(SPECL
    [`k:A`; `w:A`; `w':A`; `j:A`; `v:A`; `v':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[];
    INTRO_TAC "@k w w'. h8 h9 h10 h11 h12 h13 h14 tl" THEN
  EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `w':A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "r3" (fun th ->
    MP_TAC(SPECL [`k:A`; `w:A`; `w':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `j:A` THEN DISCH_TAC THEN
  X_GEN_TAC `v:A` THEN DISCH_TAC THEN
  X_GEN_TAC `v':A` THEN DISCH_TAC THEN STRIP_TAC THEN
  USE_THEN "r6" (fun th -> MP_TAC(SPECL
    [`k:A`; `w:A`; `w':A`; `j:A`; `v:A`; `v':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
  USE_THEN "tl" (fun th ->
    MP_TAC(SPECL [`j:A`; `v:A`; `v':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

let HOLDS_TLL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v tll_form <=> etll D E (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!X rX S z m t:A.
      X IN D /\ rX IN D /\ S IN D /\ z IN D /\ m IN D /\ t IN D
      ==> (holds D E ((6 |-> t) ((5 |-> m) ((4 |-> z)
             ((13 |-> S) ((12 |-> rX) ((11 |-> X) v))))))
             (rel_form 12 5 6) <=>
           erel D (E:A->A->bool) rX m t)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (t:A)) ((5 |-> (m:A)) ((4 |-> (z:A))
         ((13 |-> (S:A)) ((12 |-> (rX:A)) ((11 |-> (X:A)) v)))))`;
      `12`; `5`; `6`] HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X rX S s:A.
      X IN D /\ rX IN D /\ S IN D /\ s IN D
      ==> (holds D E ((4 |-> s)
             ((13 |-> S) ((12 |-> rX) ((11 |-> X) v))))
             (fun_form 4) <=>
           eisfun D (E:A->A->bool) s) /\
          (holds D E ((4 |-> s)
             ((13 |-> S) ((12 |-> rX) ((11 |-> X) v))))
             (domain_form 4 0) <=>
           edomain D E s (v 0))`
  (LABEL_TAC "rf") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (s:A))
           ((13 |-> (S:A)) ((12 |-> (rX:A)) ((11 |-> (X:A)) v)))`;
        `4`] HOLDS_FUN_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (s:A))
           ((13 |-> (S:A)) ((12 |-> (rX:A)) ((11 |-> (X:A)) v)))`;
        `4`; `0`] HOLDS_DOMAIN_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!X rX S s k w:A.
      X IN D /\ rX IN D /\ S IN D /\ s IN D /\ k IN D /\ w IN D
      ==> (holds D E ((6 |-> w) ((5 |-> k) ((4 |-> s)
             ((13 |-> S) ((12 |-> rX) ((11 |-> X) v))))))
             (apply_form 4 5 6) <=>
           eapply D (E:A->A->bool) s k w)`
  (LABEL_TAC "ra") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (w:A)) ((5 |-> (k:A)) ((4 |-> (s:A))
         ((13 |-> (S:A)) ((12 |-> (rX:A)) ((11 |-> (X:A)) v)))))`;
      `4`; `5`; `6`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
