  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  USE_THEN "rr" (fun t1 -> USE_THEN "rf" (fun t2 ->
    USE_THEN "ra" (fun t3 -> USE_THEN "rt" (fun t4 ->
