(* ------------------------------------------------------------------------- *)
(* The tuple-lexicographic least-element principle, by internal induction    *)
(* on the (internal) natural number n = the common domain of the tuples.     *)
(* Base: all functions on the empty domain coincide (EFUN_EXT). Step: given  *)
(* a nonempty family S of functions on suc m, restrict to m (replacement     *)
(* along rst_form), take the etlex-least restriction t' (IH), then among     *)
(* the members of S restricting to t' (separation) take one whose value at   *)
(* the top index m is rX-least (separation via vsel_form + the least-        *)
(* element hypothesis); first-difference comparison transfers through the    *)
(* restrictions, using transitivity of the internal natural m.               *)
(* ------------------------------------------------------------------------- *)

let ERESTRICT_APPLY_IN = prove
 (`!D (E:A->A->bool) g b gr u w.
        model D E ZF_AX /\ erestrict D E g b gr /\
        u IN D /\ w IN D /\ E u b /\ eapply D E g u w
        ==> eapply D E gr u w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) g u w` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `z:A` o CONJUNCT2 o
    GEN_REWRITE_RULE I [erestrict]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

let rst_form = new_definition
  `rst_form =
     !!3 ((3 %% 1) <->
          ((3 %% 0) && ?? 4 (?? 5 ((4 %% 2) && opair_form 4 5 3))))`;;

let HOLDS_RST_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v rst_form <=>
             erestrict D E (v 0) (v 2) (v 1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z u w:A. z IN D /\ u IN D /\ w IN D
      ==> (holds D E ((5 |-> w) ((4 |-> u) ((3 |-> z) v)))
             (opair_form 4 5 3) <=>
           eopair D (E:A->A->bool) u w z)`
  (LABEL_TAC "op") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (w:A)) ((4 |-> (u:A)) ((3 |-> (z:A)) v))`;
      `4`; `5`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[rst_form; erestrict; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `z:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "op" (fun th -> ASM_MESON_TAC[th]));;

let vsel_form = new_definition
  `vsel_form = ?? 3 ((3 %% 1) && apply_form 3 2 0)`;;

let HOLDS_VSEL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v vsel_form <=>
             ?s. s IN D /\ E s (v 1) /\ eapply D E s (v 2) (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!s:A. s IN D
      ==> (holds D E ((3 |-> s) v) (apply_form 3 2 0) <=>
           eapply D (E:A->A->bool) s (v 2) (v 0))`
  (LABEL_TAC "ap") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (s:A)) v`; `3`; `2`; `0`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[vsel_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  USE_THEN "ap" (fun th -> ASM_MESON_TAC[th]));;

let ETLL_EMPTY = prove
 (`!D (E:A->A->bool) n.
        model D E ZF_AX /\ n IN D /\ eempty D E n ==> etll D E n`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[etll] THEN
  MAP_EVERY X_GEN_TAC [`X:A`; `rX:A`; `S:A`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "lh")
      (CONJUNCTS_THEN2 (LABEL_TAC "mf")
        (X_CHOOSE_THEN `s0:A` STRIP_ASSUME_TAC)))))) THEN
  EXISTS_TAC `s0:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `s:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `s0:A`; `n:A`]
    EFUN_EXT) THEN
  ANTS_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      USE_THEN "mf" (fun th -> ASM_MESON_TAC[th]);
      USE_THEN "mf" (fun th -> ASM_MESON_TAC[th]);
      USE_THEN "mf" (fun th -> ASM_MESON_TAC[th]);
      USE_THEN "mf" (fun th -> ASM_MESON_TAC[th]);
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      USE_THEN "mf" (fun th -> MP_TAC(SPEC `s:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN STRIP_TAC THEN
      ASM_MESON_TAC[eindom; edomain; eempty]];
    DISCH_THEN(fun th -> ASM_MESON_TAC[th])]);;

let ETLL_SUC = prove
 (`!D (E:A->A->bool) om m sm.
        model D E ZF_AX /\ eomega D E om /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\ etll D E m
        ==> etll D E sm`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 IH" THEN
  REWRITE_TAC[etll] THEN
