let ETLL_OMEGA = prove
 (`!D (E:A->A->bool) om n.
        model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om
        ==> etll D E n`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `tll_form`;
                `0`; `v0:num->A`] EOMEGA_INDUCT_HOLDS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (e:A)) v0`]
        HOLDS_TLL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_MESON_TAC[ETLL_EMPTY];
      MAP_EVERY X_GEN_TAC [`u:A`; `su:A`] THEN
      INTRO_TAC "h1 h2 h3 h4 hu" THEN
      SUBGOAL_THEN
       `valuation D ((0 |-> (u:A)) v0) /\
        valuation D ((0 |-> (su:A)) v0)`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN `etll D (E:A->A->bool) u` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
          `(0 |-> (u:A)) v0`] HOLDS_TLL_FORM) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          USE_THEN "hu" (MP_TAC o GEN_REWRITE_RULE I [th])) THEN
        REWRITE_TAC[VALMOD] THEN
        CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN SIMP_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (su:A)) v0`] HOLDS_TLL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_MESON_TAC[ETLL_SUC]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (n:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n:A)) v0`]
    HOLDS_TLL_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Towards the least defining key of a definable set: edefby c s y says the  *)
(* code c with parameter assignment s (a total om -> x function) defines y   *)
(* over the carrier x, i.e. y = {u in x | sat(x, c, s[0:=u])}.  For a        *)
(* nonempty definable y every defining code lies in the hf set               *)
(* (ESAT_CODE_VS via the satstage universe (hf x vs) x 2), so EHFORD_LEAST   *)
(* picks the hford-least defining code (EDEFCODE_LEAST, separation from hf   *)
(* along dfby_form).  ECODE_LEASTSTAGE then picks the least V-stage of that  *)
(* code (EORDINAL_LEAST on meetstage_form with a singleton), the bound below *)
(* which ESAT_AGREE reads parameter assignments.                             *)
(* ------------------------------------------------------------------------- *)

let ESAT_CODE_VS = prove
 (`!D (E:A->A->bool) om hf x vs c s.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        x IN D /\ efuns D E om x vs /\ c IN D /\ s IN D /\
        esat D E x c s
        ==> E c hf /\ E s vs`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esat]) THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
    (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A` (X_CHOOSE_THEN `cs:A`
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `n:A`; `t:A`]
    ESATSTAGE_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@u2 rr. h1 h2 h3 tch" THEN
  SUBGOAL_THEN `(E:A->A->bool) w u2` ASSUME_TAC THENL
   [USE_THEN "tch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
    ALL_TAC] THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [esatuniv] o check
    (fun th -> can (find_term (fun tm -> is_const tm &&
      fst(dest_const tm) = "esatuniv")) (concl th))) THEN
  DISCH_THEN(X_CHOOSE_THEN `om2:A` (X_CHOOSE_THEN `hf2:A`
    (X_CHOOSE_THEN `vs2:A` (X_CHOOSE_THEN `csx:A`
      (X_CHOOSE_THEN `two:A` STRIP_ASSUME_TAC))))) THEN
  SUBGOAL_THEN `(om2:A) = om /\ (hf2:A) = hf /\ (vs2:A) = vs`
  (REPEAT_TCL CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE; EHFSET_UNIQUE; EFUNS_UNIQUE];
    ALL_TAC] THEN
  SUBGOAL_THEN `?p b:A. p IN D /\ b IN D /\ E p csx /\ E b two /\
                        eopair D (E:A->A->bool) p b w`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `(p:A) = cs` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  SUBGOAL_THEN `?c2 s2:A. c2 IN D /\ s2 IN D /\ E c2 hf /\
                          E s2 vs /\ eopair D (E:A->A->bool) c2 s2 cs`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  ASM_MESON_TAC[EOPAIR_INJ]);;

let edefby = new_definition
  `edefby D (E:A->A->bool) x vs z0 y c s <=>
        c IN D /\ s IN D /\ E s vs /\
        !u. u IN D /\ E u x
            ==> ?s'. s' IN D /\ eupdate D E s z0 u s' /\
                     (E u y <=> esat D E x c s')`;;

let dfby_form = new_definition
  `dfby_form =
     ?? 5 ((5 %% 3) &&
           !!- 7 1 (?? 8 (update_form 5 6 7 8 &&
                          ((7 %% 9) <-> sat_form 1 4 8))))`;;

let HOLDS_DFBY_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v dfby_form <=>
             ?s. edefby D E (v 1) (v 3) (v 6) (v 9) (v 4) s)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!s u s':A. s IN D /\ u IN D /\ s' IN D
      ==> (holds D E ((8 |-> s') ((7 |-> u) ((5 |-> s) v)))
             (update_form 5 6 7 8) <=>
           eupdate D (E:A->A->bool) s (v 6) u s') /\
          (holds D E ((8 |-> s') ((7 |-> u) ((5 |-> s) v)))
             (sat_form 1 4 8) <=>
           esat D (E:A->A->bool) (v 1) (v 4) s')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (s':A)) ((7 |-> (u:A)) ((5 |-> (s:A)) v))`;
        `5`; `6`; `7`; `8`] HOLDS_UPDATE_FORM) THEN
      ANTS_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (s':A)) ((7 |-> (u:A)) ((5 |-> (s:A)) v))`;
        `1`; `4`; `8`] HOLDS_SAT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC]] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[dfby_form; edefby; HOLDS_EX; HOLDS_AND; HOLDS_IFF;
              holds] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_EQ] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_IFF; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `s:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `s':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r2" (fun th -> ASM_SIMP_TAC[th]));;

let EDEFCODE_LEAST = prove
 (`!D (E:A->A->bool) om ho hf x vs z0 y.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        ehfset D E om hf /\ x IN D /\ efuns D E om x vs /\
        enat D E 0 z0 /\ y IN D /\ esubset D E y x /\
        ~(eempty D E y) /\
        (?c s. edefby D E x vs z0 y c s)
        ==> ?c. c IN D /\ E c hf /\
                (?s. edefby D E x vs z0 y c s) /\
                !c'. c' IN D /\ (?s'. edefby D E x vs z0 y c' s') /\
                     ~(c' = c)
                     ==> erel D E ho c c'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(vs:A) IN D /\ (z0:A) IN D /\ (hf:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns; ENAT_IN; ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `?u0:A. u0 IN D /\ (E:A->A->bool) u0 y`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c' s':A. edefby D (E:A->A->bool) x vs z0 y c' s' ==> E c' hf`
  (LABEL_TAC "chf") THENL
   [REPEAT GEN_TAC THEN DISCH_TAC THEN
    FIRST_ASSUM(MP_TAC o SPEC `u0:A` o CONJUNCT2 o CONJUNCT2 o
      CONJUNCT2 o GEN_REWRITE_RULE I [edefby]) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s'':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `esat D (E:A->A->bool) x c' s''` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[ESAT_CODE_VS; edefby];
    ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN
   `valuation D ((9 |-> (y:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A))
       ((1 |-> (x:A)) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`dfby_form`; `4`;
     `(9 |-> (y:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A))
        ((1 |-> (x:A)) v0)))`;
     `hf:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `C:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "Cchh"))) THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> ((E:A->A->bool) c C <=>
           E c hf /\ ?s. edefby D E x vs z0 y c s)`
  (LABEL_TAC "Cch") THENL
   [X_GEN_TAC `cc:A` THEN DISCH_TAC THEN
    USE_THEN "Cchh" (fun th -> MP_TAC(SPEC `cc:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (cc:A)) ((9 |-> (y:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A))
         ((1 |-> (x:A)) v0))))`] HOLDS_DFBY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
                `hf:A`; `C:A`] EHFORD_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "Cch" (fun th -> ASM_MESON_TAC[th]);
      USE_THEN "Cch" (fun th -> USE_THEN "chf" (fun th2 ->
        ASM_MESON_TAC[th; th2; edefby]))];
    ALL_TAC] THEN
  INTRO_TAC "@m. h1 h2 mleast" THEN
  EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) m hf /\ ?s. edefby D E x vs z0 y m s`
  (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THENL
   [USE_THEN "Cch" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c':A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) c' C` ASSUME_TAC THENL
   [USE_THEN "Cch" (fun th -> USE_THEN "chf" (fun th2 ->
      ASM_MESON_TAC[th; th2]));
    ALL_TAC] THEN
  USE_THEN "mleast" (fun th -> ASM_MESON_TAC[th]));;

let ECODE_LEASTSTAGE = prove
 (`!D (E:A->A->bool) om hf c.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        c IN D /\ E c hf
        ==> ?nc ync. nc IN D /\ E nc om /\ eordinal D E nc /\
                     ync IN D /\ ehfstage D E nc ync /\ E c ync /\
                     !n' y'. n' IN D /\ y' IN D /\ E n' nc /\
                             ehfstage D E n' y'
                             ==> ~(E c y')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `?n0 y0:A. n0 IN D /\ y0 IN D /\ (E:A->A->bool) n0 om /\
              ehfstage D E n0 y0 /\ E c y0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `?sc:A. epair D (E:A->A->bool) c c sc`
  (X_CHOOSE_TAC `sc:A`) THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sc:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN D ==> ((E:A->A->bool) t sc <=> t = c)`
  (LABEL_TAC "scc") THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v' = (1 |-> (sc:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v':num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v'" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v':num->A) 1 = sc` ASSUME_TAC THENL
   [EXPAND_TAC "v'" THEN REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:A. n IN D
      ==> (holds D E ((0 |-> n) v') meetstage_form <=>
           ?y. y IN D /\ ehfstage D (E:A->A->bool) n y /\ E c y)`
  (LABEL_TAC "ms") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n:A)) v'`]
      HOLDS_MEETSTAGE_FORM) THEN
    ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(MESON[]
     `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
    X_GEN_TAC `y:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "scc" (fun th -> ASM_MESON_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n0` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `meetstage_form`;
                `v':num->A`; `n0:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "ms" (fun th -> MP_TAC(SPEC `n0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@d. h1 h2 hd mind" THEN
  SUBGOAL_THEN `~((E:A->A->bool) n0 d)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    USE_THEN "mind" (fun th -> MP_TAC(SPEC `n0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[] THEN
    USE_THEN "ms" (fun th -> MP_TAC(SPEC `n0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) d om` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `n0:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E; EOMEGA_ORDINAL];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  USE_THEN "hd" MP_TAC THEN
  USE_THEN "ms" (fun th -> MP_TAC(SPEC `d:A` th)) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[eordinal]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC [`d:A`; `yd:A`] THEN
  ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`n':A`; `y':A`] THEN STRIP_TAC THEN
  DISCH_TAC THEN
  USE_THEN "mind" (fun th -> MP_TAC(SPEC `n':A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[] THEN
  USE_THEN "ms" (fun th -> MP_TAC(SPEC `n':A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `y':A` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The etlex-least nc-restriction of a defining assignment for (c, y):       *)
(* separate the defining assignments from vs (dfbys_form = dfby_form's body, *)
(* separation variable in slot 5), map to nc-restrictions by replacement     *)
(* along rst_form, and apply ETLL_OMEGA with the carrier wellordering.       *)
(* ------------------------------------------------------------------------- *)

let dfbys_form = new_definition
  `dfbys_form =
     !!- 7 1 (?? 8 (update_form 5 6 7 8 &&
                    ((7 %% 9) <-> sat_form 1 4 8)))`;;

let HOLDS_DFBYS_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v dfbys_form <=>
             !u. u IN D /\ E u (v 1)
                 ==> ?s'. s' IN D /\
                          eupdate D E (v 5) (v 6) u s' /\
                          (E u (v 9) <=> esat D E (v 1) (v 4) s'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u s':A. u IN D /\ s' IN D
      ==> (holds D E ((8 |-> s') ((7 |-> u) v))
             (update_form 5 6 7 8) <=>
           eupdate D (E:A->A->bool) (v 5) (v 6) u s') /\
          (holds D E ((8 |-> s') ((7 |-> u) v))
             (sat_form 1 4 8) <=>
           esat D (E:A->A->bool) (v 1) (v 4) s')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (s':A)) ((7 |-> (u:A)) v)`;
        `5`; `6`; `7`; `8`] HOLDS_UPDATE_FORM) THEN
      ANTS_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (s':A)) ((7 |-> (u:A)) v)`;
        `1`; `4`; `8`] HOLDS_SAT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC]] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[dfbys_form] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_EQ] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_IFF; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `s':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r2" (fun th -> ASM_SIMP_TAC[th]));;

let EDEFTUPLE_LEAST = prove
 (`!D (E:A->A->bool) om x vs z0 r y c nc.
        model D E ZF_AX /\ eomega D E om /\ x IN D /\
        efuns D E om x vs /\ enat D E 0 z0 /\ r IN D /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r m t) /\
        y IN D /\ c IN D /\ nc IN D /\ E nc om /\
        (?s. edefby D E x vs z0 y c s)
        ==> ?rt. rt IN D /\
                 (?s. edefby D E x vs z0 y c s /\
                      erestrict D E s nc rt) /\
                 !rt'. rt' IN D /\
                       (?s'. edefby D E x vs z0 y c s' /\
                             erestrict D E s' nc rt') /\
                       ~(rt' = rt)
                       ==> etlex D E r rt rt'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 lh h7 h8 h9 h10 @s0. h11" THEN
  SUBGOAL_THEN `(vs:A) IN D /\ (z0:A) IN D /\ (s0:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns; ENAT_IN; edefby]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((9 |-> (y:A)) ((6 |-> (z0:A)) ((4 |-> (c:A))
       ((1 |-> (x:A)) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`dfbys_form`; `5`;
     `(9 |-> (y:A)) ((6 |-> (z0:A)) ((4 |-> (c:A))
        ((1 |-> (x:A)) v0)))`;
     `vs:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Sd:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "Schh"))) THEN
  SUBGOAL_THEN
   `!s:A. s IN D
      ==> ((E:A->A->bool) s Sd <=> edefby D E x vs z0 y c s)`
  (LABEL_TAC "Sch") THENL
   [X_GEN_TAC `ss:A` THEN DISCH_TAC THEN
    USE_THEN "Schh" (fun th -> MP_TAC(SPEC `ss:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (ss:A)) ((9 |-> (y:A)) ((6 |-> (z0:A)) ((4 |-> (c:A))
         ((1 |-> (x:A)) v0))))`] HOLDS_DFBYS_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    REWRITE_TAC[edefby] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (nc:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`rst_form`; `0`; `1`; `(2 |-> (nc:A)) v0`; `Sd:A`]) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_EQ] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `nc:A`]
      ERESTRICT_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `rr:A`) THEN
    EXISTS_TAC `rr:A` THEN
    SUBGOAL_THEN `(rr:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w':A)) ((0 |-> (u:A)) ((2 |-> (nc:A)) v0))`]
      HOLDS_RST_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    ASM_MESON_TAC[ERESTRICT_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `R:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "imgh"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D
        ==> ((E:A->A->bool) w R <=>
             ?s:A. s IN D /\ E s Sd /\ erestrict D E s nc w)`
  (LABEL_TAC "img") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "imgh" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
    X_GEN_TAC `u:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (u:A)) ((2 |-> (nc:A)) v0))`]
      HOLDS_RST_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ E w R
        ==> eisfun D (E:A->A->bool) w /\ edomain D E w nc /\
            (!k v. k IN D /\ v IN D /\ eapply D E w k v ==> E v x)`
  (LABEL_TAC "mf2") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "img" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
     [USE_THEN "Sch" (fun th -> ASM_MESON_TAC[th; edefby]);
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eisfun D (E:A->A->bool) s /\ edomain D E s om /\
      (!u v. u IN D /\ v IN D /\ eapply D E s u v ==> E v x)`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[ERESTRICT_ISFUN];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `om:A`;
                    `nc:A`; `w:A`] ERESTRICT_EDOMAIN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
        ASM_MESON_TAC[EORDINAL_TRANS_E; EOMEGA_ORDINAL];
        SIMP_TAC[]];
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      ASM_MESON_TAC[ERESTRICT_APPLY]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?r0:A. r0 IN D /\ (E:A->A->bool) r0 R`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s0:A`; `nc:A`]
      ERESTRICT_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `rr0:A`) THEN
    SUBGOAL_THEN `(rr0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
    EXISTS_TAC `rr0:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "img" (fun th -> USE_THEN "Sch" (fun th2 ->
      ASM_MESON_TAC[th; th2]));
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `nc:A`]
    ETLL_OMEGA) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[etll] THEN
  DISCH_THEN(MP_TAC o SPECL [`x:A`; `r:A`; `R:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@rt. h12 h13 rtleast" THEN
  EXISTS_TAC `rt:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [USE_THEN "img" (fun th -> USE_THEN "Sch" (fun th2 ->
      ASM_MESON_TAC[th; th2]));
    X_GEN_TAC `rt':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) rt' R` ASSUME_TAC THENL
     [USE_THEN "img" (fun th -> USE_THEN "Sch" (fun th2 ->
        ASM_MESON_TAC[th; th2; edefby]));
      ALL_TAC] THEN
    USE_THEN "rtleast" (fun th -> ASM_MESON_TAC[th])]);;

(* ------------------------------------------------------------------------- *)
(* The key determines the set: if (c, rt) arises as (code, nc-restriction    *)
(* of a defining assignment) for both y and y', then y = y'.  Update both    *)
(* assignments at slot 0 with a candidate u: the updates agree below nc      *)
(* (EUPDATE_AGREE at 0, restriction agreement elsewhere), so ESAT_AGREE      *)
(* transfers satisfaction both ways and extensionality closes.               *)
(* ------------------------------------------------------------------------- *)

let EDEFKEY_DETERMINES = prove
 (`!D (E:A->A->bool) om hf x vs z0 y y' c nc ync rt.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        x IN D /\ efuns D E om x vs /\ enat D E 0 z0 /\
        y IN D /\ y' IN D /\ esubset D E y x /\ esubset D E y' x /\
        c IN D /\ nc IN D /\ eordinal D E nc /\
        ync IN D /\ ehfstage D E nc ync /\ E c ync /\ rt IN D /\
        (?s. edefby D E x vs z0 y c s /\ erestrict D E s nc rt) /\
        (?s'. edefby D E x vs z0 y' c s' /\ erestrict D E s' nc rt)
        ==> y = y'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  REPEAT(FIRST_X_ASSUM(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC o
    check (fun th -> is_exists(concl th) &&
      fst(dest_var(fst(dest_exists(concl th)))) = "s"))) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `s':A` STRIP_ASSUME_TAC o
    check (fun th -> is_exists(concl th))) THEN
  SUBGOAL_THEN
   `(s:A) IN D /\ (s':A) IN D /\ (E:A->A->bool) s vs /\ E s' vs /\
    (vs:A) IN D /\ (z0:A) IN D`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[edefby; efuns; ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z0 om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2:A. esatuniv D (E:A->A->bool) x u2`
  (X_CHOOSE_TAC `u2:A`) THENL
   [ASM_MESON_TAC[ESATUNIV_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?two:A. enat D (E:A->A->bool) 2 two`
  (X_CHOOSE_TAC `two:A`) THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) u x` THENL
   [ALL_TAC; ASM_MESON_TAC[esubset]] THEN
  SUBGOAL_THEN
   `?su:A. su IN D /\ eupdate D (E:A->A->bool) s z0 u su /\
           ((E:A->A->bool) u y <=> esat D E x c su)`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o CONJUNCT2 o
      CONJUNCT2 o GEN_REWRITE_RULE I [edefby] o
      check (fun th -> can (find_term (fun tm -> is_var tm &&
        fst(dest_var tm) = "y")) (concl th)) o
      check (fun th -> can (find_term (fun tm -> is_const tm &&
        fst(dest_const tm) = "edefby")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?su':A. su' IN D /\ eupdate D (E:A->A->bool) s' z0 u su' /\
            ((E:A->A->bool) u y' <=> esat D E x c su')`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o CONJUNCT2 o CONJUNCT2 o
      CONJUNCT2 o GEN_REWRITE_RULE I [edefby] o
      check (fun th -> can (find_term (fun tm -> is_var tm &&
        fst(dest_var tm) = "y'")) (concl th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) su vs /\ (E:A->A->bool) su' vs`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EUPDATE_FUNS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i. i IN D
        ==> !w. w IN D
                ==> E i nc
                    ==> (eapply D (E:A->A->bool) su i w <=>
                         eapply D E su' i w)`
  (LABEL_TAC "agr") THENL
   [X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `s':A`;
                  `z0:A`; `u:A`; `su:A`; `su':A`; `i:A`; `w:A`]
      EUPDATE_AGREE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      ASM_CASES_TAC `(i:A) = z0` THEN ASM_REWRITE_TAC[] THEN
      EQ_TAC THENL
       [ASM_MESON_TAC[ERESTRICT_APPLY; ERESTRICT_APPLY_IN];
        ASM_MESON_TAC[ERESTRICT_APPLY; ERESTRICT_APPLY_IN]];
      SIMP_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `nc:A`; `ync:A`; `c:A`;
                `su:A`; `su':A`] ESAT_AGREE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "agr" (fun th -> ACCEPT_TAC th);
    ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `nc:A`; `ync:A`; `c:A`;
                `su':A`; `su:A`] ESAT_AGREE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    REPEAT STRIP_TAC THEN
    USE_THEN "agr" (fun th -> ASM_MESON_TAC[th]);
    ALL_TAC] THEN
  DISCH_TAC THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* lstage_form: internal "j = L(i)" via the rec_form nesting of lstep_form   *)
(* (same trick as hfstage_form for the V-stages).                            *)
(* ------------------------------------------------------------------------- *)

let lstage_form = new_definition
  `lstage_form i j = recapp_form (rec_form lstep_form 2) i j`;;

let HOLDS_LSTAGE_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (lstage_form i j) <=>
             elstage D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lstage_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `rec_form lstep_form 2`; `i:num`; `j:num`]
    HOLDS_RECAPP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (v:num->A) j) ((2 |-> v i) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `lstep_form`; `2`; `(v:num->A) i`; `(v:num->A) j`]
    HOLDS_REC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ARITH_TAC;
      X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      MP_TAC(REWRITE_RULE[SUBSET] FV_LSTEP_FORM_SUB) THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
      ASM_REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN ARITH_TAC];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
    `(v:num->A) j`; `v:num->A`] ELSTAGE_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* The least defining key of a (nonempty) definable subset y of the carrier  *)
(* x: c = the hford-least defining code, nc = the least V-stage of c, rt =   *)
(* the etlex-least nc-restriction of the defining assignments (etlex over    *)
(* the carrier wellordering r).  ELKEY_EXISTS chains EDEFCODE_LEAST,         *)
(* ECODE_LEASTSTAGE and EDEFTUPLE_LEAST; the accessors re-expose its         *)
(* clauses; ELKEY_UNIQUE makes the key a function of y (hford asymmetry,     *)
(* stage minimality vs trichotomy, ETLEX_ASYM); ELKEY_INJ makes it injective *)
(* (EDEFKEY_DETERMINES).                                                     *)
(* ------------------------------------------------------------------------- *)

let elkey = new_definition
  `elkey D (E:A->A->bool) om hf ho x r y c nc rt <=>
     ?vs z0 ync.
        vs IN D /\ z0 IN D /\ ync IN D /\
        efuns D E om x vs /\ enat D E 0 z0 /\
        c IN D /\ E c hf /\
        (?s. edefby D E x vs z0 y c s) /\
        (!c'. c' IN D /\ (?s'. edefby D E x vs z0 y c' s') /\
              ~(c' = c)
              ==> erel D E ho c c') /\
        nc IN D /\ E nc om /\ ehfstage D E nc ync /\ E c ync /\
        (!n' y'. n' IN D /\ y' IN D /\ E n' nc /\
                 ehfstage D E n' y'
                 ==> ~(E c y')) /\
        rt IN D /\
        (?s. edefby D E x vs z0 y c s /\ erestrict D E s nc rt) /\
        (!rt'. rt' IN D /\
               (?s'. edefby D E x vs z0 y c s' /\
                     erestrict D E s' nc rt') /\
               ~(rt' = rt)
               ==> etlex D E r rt rt')`;;

let ELKEY_EXISTS = prove
 (`!D (E:A->A->bool) om hf ho x r y.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        ehford D E om ho /\ x IN D /\ r IN D /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r m t) /\
        y IN D /\ esubset D E y x /\ ~(eempty D E y) /\
        (?vs z0 c s. efuns D E om x vs /\ enat D E 0 z0 /\
                     edefby D E x vs z0 y c s)
        ==> ?c nc rt. elkey D E om hf ho x r y c nc rt`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `vs:A` (X_CHOOSE_THEN `z0:A`
    (X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `s0:A`
      STRIP_ASSUME_TAC)))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
                `hf:A`; `x:A`; `vs:A`; `z0:A`; `y:A`]
    EDEFCODE_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@c. h1 h2 h3 cleast" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `c:A`]
    ECODE_LEASTSTAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@nc ync. h4 h5 h6 h7 h8 h9 ncleast" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`;
                `vs:A`; `z0:A`; `r:A`; `y:A`; `c:A`; `nc:A`]
    EDEFTUPLE_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@rt. h10 h11 rtleast" THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `nc:A`; `rt:A`] THEN
  REWRITE_TAC[elkey] THEN
  MAP_EVERY EXISTS_TAC [`vs:A`; `z0:A`; `ync:A`] THEN
  ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[efuns; ENAT_IN]);;

let ELKEY_IN = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt.
        elkey D E om hf ho x r y c nc rt
        ==> c IN D /\ E c hf /\ nc IN D /\ E nc om /\ rt IN D`,
  REWRITE_TAC[elkey] THEN MESON_TAC[]);;

let ELKEY_DEFBY = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt vs z0.
        model D E ZF_AX /\
        elkey D E om hf ho x r y c nc rt /\
        efuns D E om x vs /\ enat D E 0 z0
        ==> ?s. edefby D E x vs z0 y c s /\ erestrict D E s nc rt`,
  REWRITE_TAC[elkey] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[EFUNS_UNIQUE; ENAT_UNIQUE]);;

let ELKEY_CODE_LEAST = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt vs z0 c''.
        model D E ZF_AX /\
        elkey D E om hf ho x r y c nc rt /\
        efuns D E om x vs /\ enat D E 0 z0 /\
        c'' IN D /\ (?s. edefby D E x vs z0 y c'' s) /\ ~(c'' = c)
        ==> erel D E ho c c''`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elkey]) THEN
  DISCH_THEN(X_CHOOSE_THEN `vs2:A` (X_CHOOSE_THEN `z02:A`
    (X_CHOOSE_THEN `ync2:A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(vs2:A) = vs /\ (z02:A) = z0`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE; ENAT_UNIQUE]; ALL_TAC] THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let ELKEY_RT_LEAST = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt vs z0 rt''.
        model D E ZF_AX /\
        elkey D E om hf ho x r y c nc rt /\
        efuns D E om x vs /\ enat D E 0 z0 /\
        rt'' IN D /\
        (?s. edefby D E x vs z0 y c s /\ erestrict D E s nc rt'') /\
        ~(rt'' = rt)
        ==> etlex D E r rt rt''`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elkey]) THEN
  DISCH_THEN(X_CHOOSE_THEN `vs2:A` (X_CHOOSE_THEN `z02:A`
    (X_CHOOSE_THEN `ync2:A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
  SUBGOAL_THEN `(vs2:A) = vs /\ (z02:A) = z0`
  (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE; ENAT_UNIQUE]; ALL_TAC] THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let ELKEY_STAGE = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt.
        elkey D E om hf ho x r y c nc rt
        ==> ?ync. ync IN D /\ ehfstage D E nc ync /\ E c ync /\
                  !n' y'. n' IN D /\ y' IN D /\ E n' nc /\
                          ehfstage D E n' y'
                          ==> ~(E c y')`,
  REWRITE_TAC[elkey] THEN MESON_TAC[]);;

let ELKEY_UNIQUE = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt c' nc' rt'.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        elkey D E om hf ho x r y c nc rt /\
        elkey D E om hf ho x r y c' nc' rt'
        ==> c = c' /\ nc = nc' /\ rt = rt'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `?vs z0:A. efuns D (E:A->A->bool) om x vs /\
                          enat D E 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[elkey]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ (E:A->A->bool) c hf /\ nc IN D /\ E nc om /\
    rt IN D /\ c' IN D /\ E c' hf /\ nc' IN D /\ E nc' om /\
    rt' IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?s1:A. edefby D (E:A->A->bool) x vs z0 y c s1 /\
           erestrict D E s1 nc rt`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_DEFBY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?s2:A. edefby D (E:A->A->bool) x vs z0 y c' s2 /\
           erestrict D E s2 nc' rt'`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_DEFBY]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) = c'` ASSUME_TAC THENL
   [ASM_CASES_TAC `(c:A) = c'` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) ho c c'` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `y:A`; `c:A`; `nc:A`; `rt:A`;
        `vs:A`; `z0:A`; `c':A`] ELKEY_CODE_LEAST) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) ho c' c` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `y:A`; `c':A`; `nc':A`; `rt':A`;
        `vs:A`; `z0:A`; `c:A`] ELKEY_CODE_LEAST) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; SIMP_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
      `c:A`; `c':A`] EHFORD_ASYM) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  SUBGOAL_THEN
   `?ync1:A. ync1 IN D /\ ehfstage D (E:A->A->bool) nc ync1 /\
             E c' ync1`
  (X_CHOOSE_THEN `ync1:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ync2:A. ync2 IN D /\ ehfstage D (E:A->A->bool) nc' ync2 /\
             E c' ync2`
  (X_CHOOSE_THEN `ync2:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!n' y':A. n' IN D /\ y' IN D /\ (E:A->A->bool) n' nc /\
               ehfstage D E n' y' ==> ~(E c' y'))`
  (LABEL_TAC "min1") THENL [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!n' y':A. n' IN D /\ y' IN D /\ (E:A->A->bool) n' nc' /\
               ehfstage D E n' y' ==> ~(E c' y'))`
  (LABEL_TAC "min2") THENL [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN `(nc:A) = nc'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `nc':A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
      ALL_TAC] THEN
    STRIP_TAC THENL
     [USE_THEN "min2" (fun th ->
        MP_TAC(SPECL [`nc:A`; `ync1:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      USE_THEN "min1" (fun th ->
        MP_TAC(SPECL [`nc':A`; `ync2:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  FIRST_X_ASSUM SUBST_ALL_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) nc'` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  ASM_CASES_TAC `(rt:A) = rt'` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `etlex D (E:A->A->bool) r rt rt'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
      `ho:A`; `x:A`; `r:A`; `y:A`; `c':A`; `nc':A`; `rt:A`;
      `vs:A`; `z0:A`; `rt':A`] ELKEY_RT_LEAST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `etlex D (E:A->A->bool) r rt' rt` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
      `ho:A`; `x:A`; `r:A`; `y:A`; `c':A`; `nc':A`; `rt':A`;
      `vs:A`; `z0:A`; `rt:A`] ELKEY_RT_LEAST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) rt /\ edomain D E rt nc' /\
    eisfun D E rt' /\ edomain D E rt' nc'`
  STRIP_ASSUME_TAC THENL
   [SUBGOAL_THEN
     `eisfun D (E:A->A->bool) s1 /\ edomain D E s1 om /\
      eisfun D E s2 /\ edomain D E s2 om`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[efuns; edefby]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!u:A. u IN D /\ (E:A->A->bool) u nc' ==> E u om`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_TRANS_E; EOMEGA_ORDINAL]; ALL_TAC] THEN
    ASM_MESON_TAC[ERESTRICT_ISFUN; ERESTRICT_EDOMAIN];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`; `nc':A`;
                `rt:A`; `rt':A`] ETLEX_ASYM) THEN
  ASM_REWRITE_TAC[]);;

let ELKEY_INJ = prove
 (`!D (E:A->A->bool) om hf ho x r y y' c nc rt.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        x IN D /\ y IN D /\ y' IN D /\
        esubset D E y x /\ esubset D E y' x /\
        elkey D E om hf ho x r y c nc rt /\
        elkey D E om hf ho x r y' c nc rt
        ==> y = y'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `?vs z0:A. efuns D (E:A->A->bool) om x vs /\
                          enat D E 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[elkey]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ (E:A->A->bool) c hf /\ nc IN D /\ E nc om /\
    rt IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ync:A. ync IN D /\ ehfstage D (E:A->A->bool) nc ync /\
            E c ync`
  (X_CHOOSE_THEN `ync:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(?s:A. edefby D (E:A->A->bool) x vs z0 y c s /\
           erestrict D E s nc rt) /\
    (?s':A. edefby D (E:A->A->bool) x vs z0 y' c s' /\
            erestrict D E s' nc rt)`
  (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `y:A`; `c:A`; `nc:A`; `rt:A`;
        `vs:A`; `z0:A`] ELKEY_DEFBY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `y':A`; `c:A`; `nc:A`; `rt:A`;
        `vs:A`; `z0:A`] ELKEY_DEFBY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
    `x:A`; `vs:A`; `z0:A`; `y:A`; `y':A`; `c:A`; `nc:A`; `ync:A`;
    `rt:A`] EDEFKEY_DETERMINES) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
    SIMP_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The new-element order for an L successor step: u < u' iff the least keys  *)
(* compare (hford on the codes, then etlex over the carrier order on the     *)
(* restrictions).  ELKEY_STAGE_UNIQUE: the least stage depends only on the   *)
(* code; ELKEY_RT_FUN: the restriction component is a function nc -> x.      *)
(* Asymmetry/transitivity/totality of elnewlt over keyed elements follow     *)
(* from the hford and etlex order theory plus key uniqueness/injectivity.    *)
(* ------------------------------------------------------------------------- *)

let ELKEY_STAGE_UNIQUE = prove
 (`!D (E:A->A->bool) om hf ho x r y y' c nc rt nc' rt'.
        model D E ZF_AX /\ eomega D E om /\
        elkey D E om hf ho x r y c nc rt /\
        elkey D E om hf ho x r y' c nc' rt'
        ==> nc = nc'`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `(nc:A) IN D /\ (E:A->A->bool) nc om /\
                (nc':A) IN D /\ E nc' om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ync1:A. ync1 IN D /\ ehfstage D (E:A->A->bool) nc ync1 /\
             E c ync1`
  (X_CHOOSE_THEN `ync1:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ync2:A. ync2 IN D /\ ehfstage D (E:A->A->bool) nc' ync2 /\
             E c ync2`
  (X_CHOOSE_THEN `ync2:A` STRIP_ASSUME_TAC) THENL
   [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!n' y''. n' IN D /\ y'' IN D /\ (E:A->A->bool) n' nc /\
              ehfstage D E n' y'' ==> ~(E c y''))`
  (LABEL_TAC "min1") THENL [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(!n' y''. n' IN D /\ y'' IN D /\ (E:A->A->bool) n' nc' /\
              ehfstage D E n' y'' ==> ~(E c y''))`
  (LABEL_TAC "min2") THENL [ASM_MESON_TAC[ELKEY_STAGE]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `nc:A`; `nc':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOMEGA_ORDINALS];
    ALL_TAC] THEN
  STRIP_TAC THENL
   [USE_THEN "min2" (fun th ->
      MP_TAC(SPECL [`nc:A`; `ync1:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    USE_THEN "min1" (fun th ->
      MP_TAC(SPECL [`nc':A`; `ync2:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let ELKEY_RT_FUN = prove
 (`!D (E:A->A->bool) om hf ho x r y c nc rt.
        model D E ZF_AX /\ eomega D E om /\
        elkey D E om hf ho x r y c nc rt
        ==> eisfun D E rt /\ edomain D E rt nc /\
            (!k w. k IN D /\ w IN D /\ eapply D E rt k w ==> E w x)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `?vs z0:A. efuns D (E:A->A->bool) om x vs /\
                          enat D E 0 z0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[elkey]; ALL_TAC] THEN
  SUBGOAL_THEN `(nc:A) IN D /\ (E:A->A->bool) nc om`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?s:A. edefby D (E:A->A->bool) x vs z0 y c s /\
          erestrict D E s nc rt`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_DEFBY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) s /\ edomain D E s om /\
    (!u v. u IN D /\ v IN D /\ eapply D E s u v ==> E v x)`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[efuns; edefby]; ALL_TAC] THEN
  SUBGOAL_THEN `!u:A. u IN D /\ (E:A->A->bool) u nc ==> E u om`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_TRANS_E; EOMEGA_ORDINAL]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN];
    ASM_MESON_TAC[ERESTRICT_EDOMAIN];
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    ASM_MESON_TAC[ERESTRICT_APPLY]]);;

let elnewlt = new_definition
  `elnewlt D (E:A->A->bool) om hf ho x r u u' <=>
        ?c nc rt c' nc' rt'.
            elkey D E om hf ho x r u c nc rt /\
            elkey D E om hf ho x r u' c' nc' rt' /\
            (erel D E ho c c' \/ c = c' /\ etlex D E r rt rt')`;;

let ELNEWLT_ASYM = prove
 (`!D (E:A->A->bool) om hf ho x r u u'.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        elnewlt D E om hf ho x r u u'
        ==> ~(elnewlt D E om hf ho x r u' u)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elnewlt]) THEN
  INTRO_TAC "@c1 nc1 rt1 c2 nc2 rt2. h1 h2 d1" THEN
  REWRITE_TAC[elnewlt] THEN
  INTRO_TAC "@c nc rt c' nc' rt'. h3 h4 d2" THEN
  SUBGOAL_THEN
   `(c:A) = c2 /\ (nc:A) = nc2 /\ (rt:A) = rt2`
  (REPEAT_TCL CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
      `ho:A`; `x:A`; `r:A`; `u':A`; `c:A`; `nc:A`; `rt:A`;
      `c2:A`; `nc2:A`; `rt2:A`] ELKEY_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c':A) = c1 /\ (nc':A) = nc1 /\ (rt':A) = rt1`
  (REPEAT_TCL CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
      `ho:A`; `x:A`; `r:A`; `u:A`; `c':A`; `nc':A`; `rt':A`;
      `c1:A`; `nc1:A`; `rt1:A`] ELKEY_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(c1:A) IN D /\ (c2:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  USE_THEN "d1" (DISJ_CASES_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 SUBST_ALL_TAC ASSUME_TAC)) THENL
   [USE_THEN "d2" (DISJ_CASES_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 SUBST_ALL_TAC ASSUME_TAC)) THENL
     [ASM_MESON_TAC[EHFORD_ASYM];
      ASM_MESON_TAC[EHFORD_ASYM]];
    USE_THEN "d2" (DISJ_CASES_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 (K ALL_TAC) ASSUME_TAC)) THENL
     [ASM_MESON_TAC[EHFORD_ASYM];
      ALL_TAC] THEN
    SUBGOAL_THEN `(nc1:A) = nc2` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `u:A`; `u':A`; `c2:A`; `nc1:A`;
        `rt1:A`; `nc2:A`; `rt2:A`] ELKEY_STAGE_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eisfun D (E:A->A->bool) rt1 /\ edomain D E rt1 nc2 /\
      eisfun D E rt2 /\ edomain D E rt2 nc2`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ELKEY_RT_FUN]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) nc2` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELKEY_IN; EOMEGA_ORDINALS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`; `nc2:A`;
                  `rt2:A`; `rt1:A`] ETLEX_ASYM) THEN
    ASM_REWRITE_TAC[]]);;

let ELNEWLT_TRANS = prove
 (`!D (E:A->A->bool) om hf ho x r u u' u''.
        model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
        (!a b c. a IN D /\ b IN D /\ c IN D /\
                 erel D E r a b /\ erel D E r b c
                 ==> erel D E r a c) /\
        (!a b. a IN D /\ b IN D /\ erel D E r a b
               ==> ~(erel D E r b a)) /\
        elnewlt D E om hf ho x r u u' /\
        elnewlt D E om hf ho x r u' u''
        ==> elnewlt D E om hf ho x r u u''`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elnewlt] o
    check (fun th -> can (find_term (fun tm -> is_var tm &&
      fst(dest_var tm) = "u''")) (concl th))) THEN
  INTRO_TAC "@c3 nc3 rt3 c4 nc4 rt4. h1 h2 d2" THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elnewlt] o
    check (fun th -> can (find_term (fun tm -> is_const tm &&
      fst(dest_const tm) = "elnewlt")) (concl th))) THEN
  INTRO_TAC "@c1 nc1 rt1 c2 nc2 rt2. h3 h4 d1" THEN
  SUBGOAL_THEN
   `(c3:A) = c2 /\ (nc3:A) = nc2 /\ (rt3:A) = rt2`
  (REPEAT_TCL CONJUNCTS_THEN SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
      `ho:A`; `x:A`; `r:A`; `u':A`; `c3:A`; `nc3:A`; `rt3:A`;
      `c2:A`; `nc2:A`; `rt2:A`] ELKEY_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(c1:A) IN D /\ (c2:A) IN D /\ (c4:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  REWRITE_TAC[elnewlt] THEN
  MAP_EVERY EXISTS_TAC
   [`c1:A`; `nc1:A`; `rt1:A`; `c4:A`; `nc4:A`; `rt4:A`] THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "d1" (DISJ_CASES_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 SUBST_ALL_TAC ASSUME_TAC)) THENL
   [USE_THEN "d2" (DISJ_CASES_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 SUBST_ALL_TAC ASSUME_TAC)) THENL
     [DISJ1_TAC THEN ASM_MESON_TAC[EHFORD_TRANS];
      DISJ1_TAC THEN ASM_REWRITE_TAC[]];
    USE_THEN "d2" (DISJ_CASES_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 SUBST_ALL_TAC ASSUME_TAC)) THENL
     [DISJ1_TAC THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(nc1:A) = nc2` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
          `ho:A`; `x:A`; `r:A`; `u:A`; `u':A`; `c4:A`; `nc1:A`;
          `rt1:A`; `nc2:A`; `rt2:A`] ELKEY_STAGE_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN `(nc2:A) = nc4` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
          `ho:A`; `x:A`; `r:A`; `u':A`; `u'':A`; `c4:A`; `nc2:A`;
          `rt2:A`; `nc4:A`; `rt4:A`] ELKEY_STAGE_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `eisfun D (E:A->A->bool) rt1 /\ edomain D E rt1 nc4 /\
        eisfun D E rt2 /\ edomain D E rt2 nc4 /\
        eisfun D E rt4 /\ edomain D E rt4 nc4`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ELKEY_RT_FUN]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) nc4` ASSUME_TAC THENL
       [ASM_MESON_TAC[ELKEY_IN; EOMEGA_ORDINALS]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`; `nc4:A`;
                    `rt1:A`; `rt2:A`; `rt4:A`] ETLEX_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]]]]);;

let ELNEWLT_TOTAL = prove
 (`!D (E:A->A->bool) om hf ho x r u u'.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        ehford D E om ho /\ x IN D /\
        (!a b. a IN D /\ b IN D /\ E a x /\ E b x /\ ~(a = b)
               ==> erel D E r a b \/ erel D E r b a) /\
        u IN D /\ u' IN D /\ esubset D E u x /\ esubset D E u' x /\
        ~(u = u') /\
        (?c nc rt. elkey D E om hf ho x r u c nc rt) /\
        (?c' nc' rt'. elkey D E om hf ho x r u' c' nc' rt')
        ==> elnewlt D E om hf ho x r u u' \/
            elnewlt D E om hf ho x r u' u`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `nc2:A`
    (X_CHOOSE_THEN `rt2:A` ASSUME_TAC)) o
    check (is_exists o concl)) THEN
  FIRST_X_ASSUM(X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `nc1:A`
    (X_CHOOSE_THEN `rt1:A` ASSUME_TAC)) o
    check (is_exists o concl)) THEN
  SUBGOAL_THEN
   `(c1:A) IN D /\ (E:A->A->bool) c1 hf /\
    (c2:A) IN D /\ E c2 hf`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  REWRITE_TAC[elnewlt] THEN
  ASM_CASES_TAC `(c1:A) = c2` THENL
   [FIRST_X_ASSUM SUBST_ALL_TAC THEN
    SUBGOAL_THEN `(nc1:A) = nc2` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `u:A`; `u':A`; `c2:A`; `nc1:A`;
        `rt1:A`; `nc2:A`; `rt2:A`] ELKEY_STAGE_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; SIMP_TAC[]];
      ALL_TAC] THEN
    SUBGOAL_THEN `~((rt1:A) = rt2)` ASSUME_TAC THENL
     [DISCH_THEN SUBST_ALL_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `x:A`; `r:A`; `u:A`; `u':A`; `c2:A`; `nc2:A`;
        `rt2:A`] ELKEY_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eisfun D (E:A->A->bool) rt1 /\ edomain D E rt1 nc2 /\
      (!k w. k IN D /\ w IN D /\ eapply D E rt1 k w ==> E w x) /\
      eisfun D E rt2 /\ edomain D E rt2 nc2 /\
      (!k w. k IN D /\ w IN D /\ eapply D E rt2 k w ==> E w x)`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ELKEY_RT_FUN]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) nc2` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELKEY_IN; EOMEGA_ORDINALS]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r:A`; `nc2:A`;
                  `x:A`; `rt1:A`; `rt2:A`] ETLEX_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN MAP_EVERY EXISTS_TAC
       [`c2:A`; `nc2:A`; `rt1:A`; `c2:A`; `nc2:A`; `rt2:A`] THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN MAP_EVERY EXISTS_TAC
       [`c2:A`; `nc2:A`; `rt2:A`; `c2:A`; `nc2:A`; `rt1:A`] THEN
      ASM_REWRITE_TAC[]];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ho:A`;
      `hf:A`; `c1:A`; `c2:A`] EHFORD_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN MAP_EVERY EXISTS_TAC
       [`c1:A`; `nc1:A`; `rt1:A`; `c2:A`; `nc2:A`; `rt2:A`] THEN
      ASM_REWRITE_TAC[];
      DISJ2_TAC THEN MAP_EVERY EXISTS_TAC
       [`c2:A`; `nc2:A`; `rt2:A`; `c1:A`; `nc1:A`; `rt1:A`] THEN
      ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Internalizing the least-key relation.  Reused fixed-slot subformulas are  *)
(* re-pointed with the Eq-link trick: ?? k (Eq k j && body) makes body's     *)
(* fixed slot k read the value of slot j (collapsed by the conditional       *)
(* unwind rewrite t IN D ==> ((?a. a IN D /\ a = t /\ P a) <=> P t)).        *)
(* Slot convention for lkey_form: 1 = carrier x, 4 = code c, 9 = element y,  *)
(* 12 = carrier order r, 17 = hford ho, 18 = om, 19 = hf set, 20 = stage nc, *)
(* 21 = restriction rt; vs/z0/ync are existentially bound inside (3/6/22).   *)
(* ------------------------------------------------------------------------- *)

let lrstx_form = new_definition
  `lrstx_form j =
     ?? 0 (Eq 0 5 && ?? 2 (Eq 2 20 && ?? 1 (Eq 1 j && rst_form)))`;;

let HOLDS_LRSTX_FORM = prove
 (`!D (E:A->A->bool) v j.
        model D E ZF_AX /\ valuation D v /\
        ~(j = 0) /\ ~(j = 1) /\ ~(j = 2)
        ==> (holds D E v (lrstx_form j) <=>
             erestrict D E (v 5) (v 20) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[lrstx_form; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  SUBGOAL_THEN
   `!a b c:A. a IN D /\ b IN D /\ c IN D
      ==> (holds D E ((1 |-> c) ((2 |-> b) ((0 |-> a) v)))
             rst_form <=>
           erestrict D (E:A->A->bool) a b c)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (c:A)) ((2 |-> (b:A)) ((0 |-> (a:A)) v))`]
      HOLDS_RST_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[MESON[]
   `t IN D ==> ((?a:A. a IN D /\ a = t /\ P a) <=> P t)`] THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let ltlex_form = new_definition
  `ltlex_form i j =
     ?? 4 (Eq 4 i && ?? 5 (Eq 5 j && tlexf_form))`;;

let HOLDS_LTLEX_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 4) /\ ~(j = 4) /\ ~(j = 5) /\ ~(i = 12) /\ ~(j = 12)
        ==> (holds D E v (ltlex_form i j) <=>
             etlex D E (v 12) (v i) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((5 |-> b) ((4 |-> a) v)) tlexf_form <=>
           etlex D (E:A->A->bool) (v 12) a b)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(5 |-> (b:A)) ((4 |-> (a:A)) v)`]
      HOLDS_TLEXF_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[ltlex_form; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_SIMP_TAC[MESON[]
   `t IN D ==> ((?a:A. a IN D /\ a = t /\ P a) <=> P t)`] THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let ldef_form = new_definition
  `ldef_form j = ?? 5 ((5 %% 3) && (dfbys_form && lrstx_form j))`;;

let HOLDS_LDEF_FORM = prove
 (`!D (E:A->A->bool) v j.
        model D E ZF_AX /\ valuation D v /\
        ~(j = 0) /\ ~(j = 1) /\ ~(j = 2) /\ ~(j = 3) /\ ~(j = 5)
        ==> (holds D E v (ldef_form j) <=>
             ?s. edefby D E (v 1) (v 3) (v 6) (v 9) (v 4) s /\
                 erestrict D E s (v 20) (v j))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!s:A. s IN D
      ==> (holds D E ((5 |-> s) v) dfbys_form <=>
           !u. u IN D /\ E u (v 1)
               ==> ?s'. s' IN D /\
                        eupdate D (E:A->A->bool) s (v 6) u s' /\
                        (E u (v 9) <=> esat D E (v 1) (v 4) s')) /\
          (holds D E ((5 |-> s) v) (lrstx_form j) <=>
           erestrict D (E:A->A->bool) s (v 20) (v j))`
  (LABEL_TAC "rr") THENL
   [X_GEN_TAC `s:A` THEN DISCH_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (s:A)) v`] HOLDS_DFBYS_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (s:A)) v`; `j:num`] HOLDS_LRSTX_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[ldef_form; HOLDS_EX; HOLDS_AND; holds; edefby] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `s:A` THEN
  ASM_CASES_TAC `(s:A) IN D` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]) THEN
  CONV_TAC TAUT);;

let lkcl_form = new_definition
  `lkcl_form =
     !! 10 (((?? 4 (Eq 4 10 && dfby_form)) && Not(Eq 10 4))
            --> rel_form 17 4 10)`;;

let HOLDS_LKCL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lkcl_form <=>
             !c'. c' IN D /\
                  (?s. edefby D E (v 1) (v 3) (v 6) (v 9) c' s) /\
                  ~(c' = v 4)
                  ==> erel D E (v 17) (v 4) c')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((10 |-> a) v) (?? 4 (Eq 4 10 && dfby_form)) <=>
           ?s. edefby D (E:A->A->bool) (v 1) (v 3) (v 6) (v 9) a s) /\
          (holds D E ((10 |-> a) v) (rel_form 17 4 10) <=>
           erel D (E:A->A->bool) (v 17) (v 4) a)`
  (LABEL_TAC "rr") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN CONJ_TAC THENL
     [REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_SIMP_TAC[MESON[]
       `t IN D ==> ((?a:A. a IN D /\ a = t /\ P a) <=> P t)`] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (a:A)) ((10 |-> (a:A)) v)`] HOLDS_DFBY_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(10 |-> (a:A)) v`; `17`; `4`; `10`] HOLDS_REL_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[lkcl_form] THEN
  ONCE_REWRITE_TAC[holds] THEN
  REWRITE_TAC[HOLDS_AND; HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[IMP_CONJ] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `a:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let lsmin_form = new_definition
  `lsmin_form =
     !! 13 (!! 14 (((13 %% 20) && hfstage_form 13 14)
                   --> Not(4 %% 14)))`;;

let HOLDS_LSMIN_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lsmin_form <=>
             !n' y'. n' IN D /\ y' IN D /\ E n' (v 20) /\
                     ehfstage D E n' y'
                     ==> ~(E (v 4) y'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ b IN D
      ==> (holds D E ((14 |-> b) ((13 |-> a) v))
             (hfstage_form 13 14) <=>
           ehfstage D (E:A->A->bool) a b)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(14 |-> (b:A)) ((13 |-> (a:A)) v)`; `13`; `14`]
      HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[lsmin_form; HOLDS_AND; HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[RIGHT_IMP_FORALL_THM; IMP_CONJ] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `a:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `b:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let lrtl_form = new_definition
  `lrtl_form =
     !! 11 ((ldef_form 11 && Not(Eq 11 21)) --> ltlex_form 21 11)`;;

let HOLDS_LRTL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lrtl_form <=>
             !rt'. rt' IN D /\
                   (?s. edefby D E (v 1) (v 3) (v 6) (v 9) (v 4) s /\
                        erestrict D E s (v 20) rt') /\
                   ~(rt' = v 21)
                   ==> etlex D E (v 12) (v 21) rt')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((11 |-> a) v) (ldef_form 11) <=>
           ?s. edefby D (E:A->A->bool) (v 1) (v 3) (v 6) (v 9)
                       (v 4) s /\
               erestrict D E s (v 20) a) /\
          (holds D E ((11 |-> a) v) (ltlex_form 21 11) <=>
           etlex D (E:A->A->bool) (v 12) (v 21) a)`
  (LABEL_TAC "rr") THENL
   [X_GEN_TAC `a:A` THEN DISCH_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(11 |-> (a:A)) v`; `11`] HOLDS_LDEF_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(11 |-> (a:A)) v`; `21`; `11`] HOLDS_LTLEX_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[lrtl_form; HOLDS_AND; HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[IMP_CONJ] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `a:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let lkey_form = new_definition
  `lkey_form =
     ?? 3 (funs_form 18 1 3 &&
       ?? 6 (nat_form 0 6 &&
         ?? 22 (hfstage_form 20 22 &&
           ((4 %% 19) &&
            (dfby_form &&
             (lkcl_form &&
              ((20 %% 18) &&
               ((4 %% 22) &&
                (lsmin_form &&
                 (ldef_form 21 && lrtl_form))))))))))`;;

let HOLDS_LKEY_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lkey_form <=>
             elkey D E (v 18) (v 19) (v 17) (v 1) (v 12) (v 9)
                       (v 4) (v 20) (v 21))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vs:A. vs IN D
      ==> (holds D E ((3 |-> vs) v) (funs_form 18 1 3) <=>
           efuns D (E:A->A->bool) (v 18) (v 1) vs)`
  (LABEL_TAC "r1") THENL
   [X_GEN_TAC `vs:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (vs:A)) v`; `18`; `1`; `3`] HOLDS_FUNS_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!vs z0:A. vs IN D /\ z0 IN D
      ==> (holds D E ((6 |-> z0) ((3 |-> vs) v)) (nat_form 0 6) <=>
           enat D (E:A->A->bool) 0 z0)`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`0`; `D:A->bool`; `E:A->A->bool`;
      `(6 |-> (z0:A)) ((3 |-> (vs:A)) v)`; `6`]
      HOLDS_NAT_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!vs z0 ync:A. vs IN D /\ z0 IN D /\ ync IN D
      ==> (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             (hfstage_form 20 22) <=>
           ehfstage D (E:A->A->bool) (v 20) ync) /\
          (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             dfby_form <=>
           ?s. edefby D E (v 1) vs z0 (v 9) (v 4) s) /\
          (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             lkcl_form <=>
           !c'. c' IN D /\
                (?s. edefby D E (v 1) vs z0 (v 9) c' s) /\
                ~(c' = v 4)
                ==> erel D E (v 17) (v 4) c') /\
          (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             lsmin_form <=>
           !n' y'. n' IN D /\ y' IN D /\ E n' (v 20) /\
                   ehfstage D E n' y'
                   ==> ~(E (v 4) y')) /\
          (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             (ldef_form 21) <=>
           ?s. edefby D E (v 1) vs z0 (v 9) (v 4) s /\
               erestrict D E s (v 20) (v 21)) /\
          (holds D E ((22 |-> ync) ((6 |-> z0) ((3 |-> vs) v)))
             lrtl_form <=>
           !rt'. rt' IN D /\
                 (?s. edefby D E (v 1) vs z0 (v 9) (v 4) s /\
                      erestrict D E s (v 20) rt') /\
                 ~(rt' = v 21)
                 ==> etlex D E (v 12) (v 21) rt')`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((22 |-> (ync:A)) ((6 |-> (z0:A))
        ((3 |-> (vs:A)) v)))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`;
        `20`; `22`] HOLDS_HFSTAGE_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`]
        HOLDS_DFBY_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`]
        HOLDS_LKCL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`]
        HOLDS_LSMIN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`;
        `21`] HOLDS_LDEF_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(22 |-> (ync:A)) ((6 |-> (z0:A)) ((3 |-> (vs:A)) v))`]
        HOLDS_LRTL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]] THEN
    (DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[lkey_form; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  EQ_TAC THENL
   [INTRO_TAC "@vs. h4 h1 @z0. h5 h2 @ync. h6 h3" THEN
