(* ------------------------------------------------------------------------- *)
(* Internal new-element comparison: two Eq-linked lkey_form instances (the   *)
(* second re-points y/c/nc/rt to slots 23/24/25/26) plus the                 *)
(* code/restriction comparison.  Free slots: 1 = carrier, 9 = u, 23 = u',    *)
(* 12 = carrier order, 17 = hford, 18 = om, 19 = hf.                         *)
(* ------------------------------------------------------------------------- *)

let elnewlt_form = new_definition
  `elnewlt_form =
     ?? 4 (?? 20 (?? 21 (lkey_form &&
       ?? 24 (?? 25 (?? 26 (
         (?? 9 (Eq 9 23 && ?? 4 (Eq 4 24 && ?? 20 (Eq 20 25 &&
            ?? 21 (Eq 21 26 && lkey_form))))) &&
         (rel_form 17 4 24 ||
          (Eq 4 24 && ltlex_form 21 26))))))))`;;

let HOLDS_ELNEWLT_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v elnewlt_form <=>
             elnewlt D E (v 18) (v 19) (v 17) (v 1) (v 12)
                         (v 9) (v 23))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c nc rt:A. c IN D /\ nc IN D /\ rt IN D
      ==> (holds D E ((21 |-> rt) ((20 |-> nc) ((4 |-> c) v)))
             lkey_form <=>
           elkey D (E:A->A->bool) (v 18) (v 19) (v 17) (v 1)
                 (v 12) (v 9) c nc rt)`
  (LABEL_TAC "k1") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v))`]
      HOLDS_LKEY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c nc rt c' nc' rt':A.
      c IN D /\ nc IN D /\ rt IN D /\
      c' IN D /\ nc' IN D /\ rt' IN D
      ==> (holds D E ((26 |-> rt') ((25 |-> nc') ((24 |-> c')
             ((21 |-> rt) ((20 |-> nc) ((4 |-> c) v))))))
             (?? 9 (Eq 9 23 && ?? 4 (Eq 4 24 && ?? 20 (Eq 20 25 &&
                ?? 21 (Eq 21 26 && lkey_form))))) <=>
           elkey D (E:A->A->bool) (v 18) (v 19) (v 17) (v 1)
                 (v 12) (v 23) c' nc' rt') /\
          (holds D E ((26 |-> rt') ((25 |-> nc') ((24 |-> c')
             ((21 |-> rt) ((20 |-> nc) ((4 |-> c) v))))))
             (rel_form 17 4 24) <=>
           erel D (E:A->A->bool) (v 17) c c') /\
          (holds D E ((26 |-> rt') ((25 |-> nc') ((24 |-> c')
             ((21 |-> rt) ((20 |-> nc) ((4 |-> c) v))))))
             (ltlex_form 21 26) <=>
           etlex D (E:A->A->bool) (v 12) rt rt')`
  (LABEL_TAC "k2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [REWRITE_TAC[HOLDS_EX; HOLDS_AND; holds] THEN
      ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_SIMP_TAC[MESON[]
       `t IN D ==> ((?a:A. a IN D /\ a = t /\ P a) <=> P t)`] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(21 |-> (rt':A)) ((20 |-> (nc':A)) ((4 |-> (c':A))
           ((9 |-> ((v:num->A) 23)) ((26 |-> (rt':A))
           ((25 |-> (nc':A)) ((24 |-> (c':A)) ((21 |-> (rt:A))
           ((20 |-> (nc:A)) ((4 |-> (c:A)) v)))))))))`]
        HOLDS_LKEY_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(26 |-> (rt':A)) ((25 |-> (nc':A)) ((24 |-> (c':A))
           ((21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v)))))`;
        `17`; `4`; `24`] HOLDS_REL_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(26 |-> (rt':A)) ((25 |-> (nc':A)) ((24 |-> (c':A))
           ((21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v)))))`;
        `21`; `26`] HOLDS_LTLEX_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_EQ] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[elnewlt_form; HOLDS_EX; HOLDS_AND; HOLDS_OR; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  EQ_TAC THENL
   [INTRO_TAC "@c. h4 @nc. h5 @rt. h6 h1 @c'. h7 @nc'. h8 @rt'. h9 h2 h3" THEN
    USE_THEN "k1" (fun th ->
      MP_TAC(SPECL [`c:A`; `nc:A`; `rt:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun rr -> USE_THEN "h1" (fun h ->
      ASSUME_TAC(REWRITE_RULE[rr] h))) THEN
    USE_THEN "k2" (fun th -> MP_TAC(SPECL
      [`c:A`; `nc:A`; `rt:A`; `c':A`; `nc':A`; `rt':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun rr ->
      USE_THEN "h2" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "h3" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h))) THEN
    REWRITE_TAC[elnewlt] THEN
    MAP_EVERY EXISTS_TAC
     [`c:A`; `nc:A`; `rt:A`; `c':A`; `nc':A`; `rt':A`] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
   `holds D E ((21 |-> (rt':A)) ((20 |-> (nc':A)) ((4 |-> (c':A))
      ((9 |-> ((v:num->A) 23)) ((26 |-> (rt':A)) ((25 |-> (nc':A))
      ((24 |-> (c':A)) ((21 |-> (rt:A)) ((20 |-> (nc:A))
      ((4 |-> (c:A)) v))))))))))
      lkey_form <=>
    elkey D (E:A->A->bool) (v 18) (v 19) (v 17) (v 1) (v 12)
          (v 23) c' nc' rt'`
  (LABEL_TAC "k3") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(21 |-> (rt':A)) ((20 |-> (nc':A)) ((4 |-> (c':A))
        ((9 |-> ((v:num->A) 23)) ((26 |-> (rt':A)) ((25 |-> (nc':A))
        ((24 |-> (c':A)) ((21 |-> (rt:A)) ((20 |-> (nc:A))
        ((4 |-> (c:A)) v)))))))))`] HOLDS_LKEY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
    USE_THEN "h2" MP_TAC THEN
  INTRO_TAC "@a1. h10 e1 @a2. h11 e2 @a3. h12 e3 @a4. h13 e4 hin" THEN
  USE_THEN "e1" (fun e1 -> USE_THEN "e2" (fun e2 ->
    USE_THEN "e3" (fun e3 -> USE_THEN "e4" (fun e4 ->
      USE_THEN "hin" (fun h ->
        MP_TAC(REWRITE_RULE[e1; e2; e3; e4] h)))))) THEN
  USE_THEN "k3" (fun th -> REWRITE_TAC[th]) THEN
  SIMP_TAC[];
    REWRITE_TAC[elnewlt] THEN
    INTRO_TAC "@c nc rt c' nc' rt'. h14 h15 h3" THEN
    SUBGOAL_THEN
     `(c:A) IN D /\ (nc:A) IN D /\ (rt:A) IN D /\
      (c':A) IN D /\ (nc':A) IN D /\ (rt':A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `nc:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `rt:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "k1" (fun th -> ASM_SIMP_TAC[th]) THEN
    EXISTS_TAC `c':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `nc':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `rt':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "k2" (fun th -> ASM_SIMP_TAC[th]) THEN
    SUBGOAL_THEN
   `holds D E ((21 |-> (rt':A)) ((20 |-> (nc':A)) ((4 |-> (c':A))
      ((9 |-> ((v:num->A) 23)) ((26 |-> (rt':A)) ((25 |-> (nc':A))
      ((24 |-> (c':A)) ((21 |-> (rt:A)) ((20 |-> (nc:A))
      ((4 |-> (c:A)) v))))))))))
      lkey_form <=>
    elkey D (E:A->A->bool) (v 18) (v 19) (v 17) (v 1) (v 12)
          (v 23) c' nc' rt'`
  (LABEL_TAC "k3") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(21 |-> (rt':A)) ((20 |-> (nc':A)) ((4 |-> (c':A))
        ((9 |-> ((v:num->A) 23)) ((26 |-> (rt':A)) ((25 |-> (nc':A))
        ((24 |-> (c':A)) ((21 |-> (rt:A)) ((20 |-> (nc:A))
        ((4 |-> (c:A)) v)))))))))`] HOLDS_LKEY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  EXISTS_TAC `(v:num->A) 23` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `c':A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `nc':A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `rt':A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "k3" (fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* hford_form says that slot 17 holds the canonical order ehford on the      *)
(* hereditarily finite elements over the omega at slot 18 (the union of the  *)
(* stage orders, read through vwo_form by the rec_form nesting trick); it is *)
(* used in the step comparison of the L wellordering below.                  *)
(* ------------------------------------------------------------------------- *)

let hford_form = new_definition
  `hford_form =
     !! 30 ((30 %% 17) <->
            ?? 31 ((31 %% 18) && ?? 32 (vwo_form 31 32 &&
                                        (30 %% 32))))`;;

let HOLDS_HFORD_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v hford_form <=>
             ehford D E (v 18) (v 17))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p n r:A. p IN D /\ n IN D /\ r IN D
      ==> (holds D E ((32 |-> r) ((31 |-> n) ((30 |-> p) v)))
             (vwo_form 31 32) <=>
           evwo D (E:A->A->bool) n r)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(32 |-> (r:A)) ((31 |-> (n:A)) ((30 |-> (p:A)) v))`;
      `31`; `32`] HOLDS_VWO_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[hford_form; ehford; HOLDS_IFF; HOLDS_EX; HOLDS_AND;
              holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `p:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a <=> p) <=> (a <=> q))`) THEN
  USE_THEN "rr" (fun th -> ASM_MESON_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* Free-variable bounds for the formulas above (the vwo_form recursion, the  *)
(* least-key formulas, elnewlt_form and hford_form), needed for              *)
(* FV_LWOLTU_FORM_SUB below: FV(lwoltu_form) SUBSET {0,2}, the side          *)
(* condition for feeding the step comparison into the erec recursion         *)
(* machinery.                                                                *)
(* ------------------------------------------------------------------------- *)

let FVLT_REC_EWOSTEP = prove
 (`!m. m IN FV(rec_form ewostep_form 2) ==> m = 2 \/ m = 3`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(MP (SPECL [`ewostep_form`; `2`] FV_REC_FORM_SUB)
            (CONJ (ARITH_RULE `1 < 2`) FVLT_EWOSTEP_FORM)) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `2 + 1 = 3`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_EWOSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let FVLT_RECAPP_EWOSTEP = prove
 (`!a b m. m IN FV(recapp_form (rec_form ewostep_form 2) a b)
           ==> m = a \/ m = b`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`rec_form ewostep_form 2`; `a:num`; `b:num`]
        FV_RECAPP_FORM_SUB) THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
