(* ------------------------------------------------------------------------- *)
(* Internalization of the clauses of the wellordering invariant (elwoinvu    *)
(* below), over the free slots 0 = the ordinal a, 4 = the order ra and       *)
(* 5 = the stage ya: linv1_form (every member of ra is an ordered pair of    *)
(* distinct members of ya), linv2_form (transitivity), linv3_form            *)
(* (asymmetry), linv4_form (totality on ya), linv6_form (members of an       *)
(* earlier stage L(b) precede all members of ya outside L(b)) and linv7_form *)
(* (every nonempty subset of ya has an ra-least member), each with a HOLDS   *)
(* characterization; the coherence clause linv5u_form is given with the      *)
(* invariant itself.  linv6_form states its hypotheses with the membership   *)
(* guards first (the shape the !!-guards produce); the bridge                *)
(* HOLDS_LWOINVU_FORM reorders them against the corresponding clause of      *)
(* elwoinvu.                                                                 *)
(* ------------------------------------------------------------------------- *)

let linv1_form = new_definition
  `linv1_form =
     !!- 6 4 (?? 7 (?? 8 ((7 %% 5) && ((8 %% 5) &&
                          (Not(Eq 7 8) && opair_form 7 8 6)))))`;;

let linv2_form = new_definition
  `linv2_form =
     !! 7 (!! 8 (!! 9 ((rel_form 4 7 8 && rel_form 4 8 9)
                       --> rel_form 4 7 9)))`;;

let HOLDS_LINV1_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v linv1_form <=>
             !p. p IN D /\ E p (v 4)
                 ==> ?u u'. u IN D /\ u' IN D /\ E u (v 5) /\
                            E u' (v 5) /\ ~(u = u') /\
                            eopair D E u u' p)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!p u u':A. p IN D /\ u IN D /\ u' IN D
      ==> (holds D E ((8 |-> u') ((7 |-> u) ((6 |-> p) v)))
             (opair_form 7 8 6) <=>
           eopair D (E:A->A->bool) u u' p)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (u':A)) ((7 |-> (u:A)) ((6 |-> (p:A)) v))`;
      `7`; `8`; `6`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[linv1_form] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_EQ] THEN
  REWRITE_TAC[HOLDS_EX; HOLDS_AND; HOLDS_NOT; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[IMP_CONJ] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `p:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  EQ_TAC THENL
   [INTRO_TAC "@u. h1 @u'. h2 h3 h4 h5 +" THEN
    USE_THEN "rr" (fun th ->
      MP_TAC(SPECL [`p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "rr" (fun th ->
      MP_TAC(SPECL [`p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let HOLDS_LINV2_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v linv2_form <=>
             !u u' u''. u IN D /\ u' IN D /\ u'' IN D /\
                        erel D E (v 4) u u' /\ erel D E (v 4) u' u''
                        ==> erel D E (v 4) u u'')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u' u'':A. u IN D /\ u' IN D /\ u'' IN D
      ==> (holds D E ((9 |-> u'') ((8 |-> u') ((7 |-> u) v)))
             (rel_form 4 7 8) <=>
           erel D (E:A->A->bool) (v 4) u u') /\
          (holds D E ((9 |-> u'') ((8 |-> u') ((7 |-> u) v)))
             (rel_form 4 8 9) <=>
           erel D (E:A->A->bool) (v 4) u' u'') /\
          (holds D E ((9 |-> u'') ((8 |-> u') ((7 |-> u) v)))
             (rel_form 4 7 9) <=>
           erel D (E:A->A->bool) (v 4) u u'')`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (u'':A)) ((8 |-> (u':A)) ((7 |-> (u:A)) v))`;
        `4`; `7`; `8`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (u'':A)) ((8 |-> (u':A)) ((7 |-> (u:A)) v))`;
        `4`; `8`; `9`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(9 |-> (u'':A)) ((8 |-> (u':A)) ((7 |-> (u:A)) v))`;
        `4`; `7`; `9`] HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[linv2_form; HOLDS_AND; holds] THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u':A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u'':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let linv3_form = new_definition
  `linv3_form =
     !! 7 (!! 8 (rel_form 4 7 8 --> Not(rel_form 4 8 7)))`;;

let HOLDS_LINV3_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v linv3_form <=>
             !u u'. u IN D /\ u' IN D /\ erel D E (v 4) u u'
                    ==> ~(erel D E (v 4) u' u))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u':A. u IN D /\ u' IN D
      ==> (holds D E ((8 |-> u') ((7 |-> u) v))
             (rel_form 4 7 8) <=>
           erel D (E:A->A->bool) (v 4) u u') /\
          (holds D E ((8 |-> u') ((7 |-> u) v))
             (rel_form 4 8 7) <=>
           erel D (E:A->A->bool) (v 4) u' u)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) v)`;
        `4`; `7`; `8`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) v)`;
        `4`; `8`; `7`] HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[linv3_form; HOLDS_NOT; holds] THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `u':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  USE_THEN "rr" (fun th -> ASM_SIMP_TAC[th]));;

let linv4_form = new_definition
  `linv4_form =
     !! 7 (!! 8 (((7 %% 5) && ((8 %% 5) && Not(Eq 7 8)))
                 --> (rel_form 4 7 8 || rel_form 4 8 7)))`;;

let HOLDS_LINV4_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v linv4_form <=>
             !u u'. u IN D /\ u' IN D /\ E u (v 5) /\ E u' (v 5) /\
                    ~(u = u')
                    ==> erel D E (v 4) u u' \/ erel D E (v 4) u' u)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u':A. u IN D /\ u' IN D
      ==> (holds D E ((8 |-> u') ((7 |-> u) v))
             (rel_form 4 7 8) <=>
           erel D (E:A->A->bool) (v 4) u u') /\
          (holds D E ((8 |-> u') ((7 |-> u) v))
             (rel_form 4 8 7) <=>
           erel D (E:A->A->bool) (v 4) u' u)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) v)`;
        `4`; `7`; `8`] HOLDS_REL_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (u':A)) ((7 |-> (u:A)) v)`;
        `4`; `8`; `7`] HOLDS_REL_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
