(* ------------------------------------------------------------------------- *)
(* The L-order recursion.  Since the lstep recursion is the unified          *)
(* L(a) = Def(union of L(b), b < a), new elements can appear at limit stages *)
(* as well as at successors.  So the step compares pairs of Def(w)-members,  *)
(* where w is the union of the stages over the history's domain and R the    *)
(* union of the recorded orders: elwoltu g p says that p = <u,u'> for        *)
(* distinct members u, u' of Def(w) and either p IN R, or u is old (in w)    *)
(* and u' new, or both are new and u precedes u' by elnewlt over (w, R).     *)
(* wch/rch/dch internalize the three set characterizations (w, R, Def(w));   *)
(* slots line up with elnewlt_form (carrier 1, order 12).  The step formula  *)
(* lwostepu_form = !!2 ((2 %% 1) <-> lwoltu_form) (FV in {0,1}) defines      *)
(* elwostepu g y (y is the set of elwoltu-pairs over g), functional by       *)
(* extensionality and total since all such pairs lie in                      *)
(* pow(U bb) x pow(U bb), where bb is the set of L-stages over UU g          *)
(* (replacement along lstage_form 0 1).  Finally elwou := erec               *)
(* lwostepu_form, with uniqueness and existence at every ordinal             *)
(* (ELWOU_UNIQUE, ELWOU_EXISTS) and the membership characterization          *)
(* ELWOU_CHAR.                                                               *)
(* ------------------------------------------------------------------------- *)

let wch_form = new_definition
  `wch_form =
     !! 31 ((31 %% 1) <->
            ?? 27 (?? 11 (apply_form 0 27 11 &&
                          ?? 30 (lstage_form 27 30 &&
                                 (31 %% 30)))))`;;

let HOLDS_WCH_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v wch_form <=>
             !t. t IN D
                 ==> (E t (v 1) <=>
                      ?b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                                eapply D E (v 0) b rb /\
                                elstage D E b yb /\ E t yb))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t b rb yb:A. t IN D /\ b IN D /\ rb IN D /\ yb IN D
      ==> (holds D E ((30 |-> yb) ((11 |-> rb) ((27 |-> b)
             ((31 |-> t) v))))
             (apply_form 0 27 11) <=>
           eapply D (E:A->A->bool) (v 0) b rb) /\
          (holds D E ((30 |-> yb) ((11 |-> rb) ((27 |-> b)
             ((31 |-> t) v))))
             (lstage_form 27 30) <=>
           elstage D (E:A->A->bool) b yb)`
  (LABEL_TAC "rr") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(30 |-> (yb:A)) ((11 |-> (rb:A)) ((27 |-> (b:A))
           ((31 |-> (t:A)) v)))`;
        `0`; `27`; `11`] HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(30 |-> (yb:A)) ((11 |-> (rb:A)) ((27 |-> (b:A))
           ((31 |-> (t:A)) v)))`;
        `27`; `30`] HOLDS_LSTAGE_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_EQ] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC]] THEN
    (DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[wch_form; HOLDS_IFF; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `t:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a <=> p) <=> (a <=> q))`) THEN EQ_TAC THENL
   [INTRO_TAC "@b. h1 @rb. h2 f1 @yb. h3 f2 h4" THEN
    USE_THEN "rr" (fun th -> MP_TAC(SPECL
    [`t:A`; `b:A`; `rb:A`; `yb:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun rr ->
    USE_THEN "f1" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
    USE_THEN "f2" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h))) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `rb:A`; `yb:A`] THEN
  ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(11 |-> (rb:A)) ((27 |-> (b:A)) ((31 |-> (t:A)) v))`;
    `0`; `27`; `11`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(fun th -> USE_THEN "f1" (fun h ->
    MP_TAC(REWRITE_RULE[th] h))) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN SIMP_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
    (X_CHOOSE_THEN `yb:A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
  EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `rb:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(11 |-> (rb:A)) ((27 |-> (b:A)) ((31 |-> (t:A)) v))`;
    `0`; `27`; `11`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `yb:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "rr" (fun th -> MP_TAC(SPECL
    [`t:A`; `b:A`; `rb:A`; `yb:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[]]);;

