let elwoltu = new_definition
  `elwoltu D (E:A->A->bool) g p <=>
     ?om hf ho w R dw u u'.
        om IN D /\ hf IN D /\ ho IN D /\ w IN D /\ R IN D /\
        dw IN D /\ u IN D /\ u' IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        (!t. t IN D
             ==> (E t w <=>
                  ?b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                            eapply D E g b rb /\
                            elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q R <=>
                  ?b rb. b IN D /\ rb IN D /\
                         eapply D E g b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y dw <=> edefmem D E w y)) /\
        eopair D E u u' p /\ E u dw /\ E u' dw /\ ~(u = u') /\
        (E p R \/
         (E u w /\ ~(E u' w)) \/
         (~(E u w) /\ ~(E u' w) /\
          elnewlt D E om hf ho w R u u'))`;;

let lwoltu_form = new_definition
  `lwoltu_form =
     ?? 18 ((omega_form 18 &&
             ?? 19 ((hfset_form 18 19 &&
                     ?? 17 ((hford_form &&
                             ?? 1 ((wch_form &&
                                    ?? 12 ((rch_form &&
                                            ?? 29 ((dch_form &&
               ?? 9 (?? 23
                     ((opair_form 9 23 2 &&
                       ((9 %% 29) &&
                        ((23 %% 29) &&
                         (Not(Eq 9 23) &&
                          ((2 %% 12) ||
                           (((9 %% 1) && Not(23 %% 1)) ||
                            (Not(9 %% 1) &&
                             (Not(23 %% 1) &&
                              elnewlt_form))))))))))))))))))))))`;;

