        ==> y = y'`,
  REWRITE_TAC[elwostepu] THEN REPEAT STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_SIMP_TAC[]);;

let ELWOSTEPU_TOTAL = prove
 (`!D (E:A->A->bool) g.
        model D E ZF_AX /\ g IN D ==> ?y. elwostepu D E g y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `?u1:A. eunion D (E:A->A->bool) g u1`
  (X_CHOOSE_TAC `u1:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2:A. eunion D (E:A->A->bool) u1 u2`
  (X_CHOOSE_TAC `u2:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr:A. b IN D /\ wr IN D /\ eapply D (E:A->A->bool) g b wr
             ==> E b u2`
  (LABEL_TAC "bu2") THENL
   [REPEAT STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [eopair] o
      check (fun th -> can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "eopair")) (concl th))) THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `pr:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (pr:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b s` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s z` ASSUME_TAC THENL
     [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s u1` ASSUME_TAC THENL
     [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
    ASM_MESON_TAC[eunion];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w:A. b IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> b) v0))
             (lstage_form 0 1) <=>
           elstage D (E:A->A->bool) b w)`
  (LABEL_TAC "hfr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (b:A)) v0)`; `0`; `1`]
      HOLDS_LSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`lstage_form 0 1`; `0`; `1`; `v0:num->A`; `u2:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC `eordinal D (E:A->A->bool) b` THENL
     [SUBGOAL_THEN `?w:A. w IN D /\ elstage D (E:A->A->bool) b w`
      (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
       [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `elstage D (E:A->A->bool) b w'` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[ELSTAGE_UNIQUE];
      EXISTS_TAC `(v0:num->A) 0` THEN
      SUBGOAL_THEN `(v0:num->A) 0 IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `w':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `elstage D (E:A->A->bool) b w'` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elstage] o
          check (fun th -> can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "elstage")) (concl th))) THEN
        REWRITE_TAC[erec] THEN
        REPEAT STRIP_TAC THEN ASM_MESON_TAC[EORDINAL_MEMBER];
        ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN `?uB:A. eunion D (E:A->A->bool) bb uB`
  (X_CHOOSE_TAC `uB:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(uB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `?pB:A. epow D (E:A->A->bool) uB pB`
  (X_CHOOSE_TAC `pB:A`) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pB:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  SUBGOAL_THEN `?X:A. ecross D (E:A->A->bool) pB pB X`
  (X_CHOOSE_TAC `X:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(X:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
    [`lwoltu_form`; `2`; `(0 |-> (g:A)) v0`; `X:A`] o
    MATCH_MP ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yr:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `yr:A` THEN REWRITE_TAC[elwostepu] THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  USE_THEN "sep" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(2 |-> (p:A)) ((0 |-> (g:A)) v0)`] HOLDS_LWOLTU_FORM) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL
   [DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT2 th));
    DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
    POP_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elwoltu]) THEN
    DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `hf:A`
      (X_CHOOSE_THEN `ho:A` (X_CHOOSE_THEN `w:A`
        (X_CHOOSE_THEN `R:A` (X_CHOOSE_THEN `dw:A`
          (X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
            (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))))))))) THEN
    SUBGOAL_THEN
     `esubset D (E:A->A->bool) u w /\ esubset D E u' w`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[edefmem]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!t:A. t IN D /\ (E:A->A->bool) t w ==> E t uB`
    (LABEL_TAC "wub") THENL
     [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `t:A` o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "elstage")) (concl th) &&
        not(can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "holds")) (concl th)))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) t w`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
        (X_CHOOSE_THEN `yb:A`
          (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
      SUBGOAL_THEN `(E:A->A->bool) yb bb` ASSUME_TAC THENL
       [USE_THEN "bch" (fun th -> MP_TAC(SPEC `yb:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [ASM_MESON_TAC[]; ASM_MESON_TAC[]];
        ALL_TAC] THEN
      ASM_MESON_TAC[eunion];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `esubset D (E:A->A->bool) u uB /\ esubset D E u' uB`
    STRIP_ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN CONJ_TAC THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "wub" MATCH_MP_TAC THEN
      ASM_MESON_TAC[esubset];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u pB /\ E u' pB`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[epow]; ALL_TAC] THEN
    ASM_MESON_TAC[ecross]]);;

let ELWOSTEPU_QFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !r w w'. r IN D /\ w IN D /\ w' IN D /\
                     holds D E ((1 |-> w) ((0 |-> r) v))
                           lwostepu_form /\
                     holds D E ((1 |-> w') ((0 |-> r) v))
                           lwostepu_form
                     ==> w = w'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  STRIP_TAC THEN
  MATCH_MP_TAC ELWOSTEPU_FUN THEN
  MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `r:A`] THEN
  ASM_MESON_TAC[HOLDS_LWOSTEPU_FORM]);;

let ELWOSTEPU_QTOTAL = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> !x. x IN D
                ==> ?y. y IN D /\
                        holds D E ((1 |-> y) ((0 |-> x) v))
                              lwostepu_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`]
    ELWOSTEPU_TOTAL) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[elwostepu]; ALL_TAC] THEN
  ASM_MESON_TAC[HOLDS_LWOSTEPU_FORM]);;

let elwou = new_definition
  `elwou D (E:A->A->bool) a y <=>
        ?v. valuation D v /\ erec D E lwostepu_form v a y`;;

let ELWOU_EREC = prove
 (`!D (E:A->A->bool) a y v.
        model D E ZF_AX /\ valuation D v
        ==> (elwou D E a y <=> erec D E lwostepu_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[elwou] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) lwostepu_form v' a y <=>
      erec D E lwostepu_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FV_LWOSTEPU_FORM) THEN
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[]]);;

let ELWOU_UNIQUE = prove
 (`!D (E:A->A->bool) a y y'.
        model D E ZF_AX /\ a IN D /\ y IN D /\ y' IN D /\
        elwou D E a y /\ elwou D E a y'
        ==> y = y'`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lwostepu_form`;
                `v:num->A`; `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`]
        ELWOSTEPU_QFUN) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[ELWOU_EREC]);;

let ELWOU_EXISTS = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?y. y IN D /\ elwou D E a y`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lwostepu_form`;
                `v:num->A`; `a:A`] EREC_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN ANTS_TAC THENL
   [ASM_MESON_TAC[ELWOSTEPU_QFUN; ELWOSTEPU_QTOTAL]; ALL_TAC] THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `y:A` THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ELWOU_EREC]);;

let ELWOU_CHAR = prove
 (`!D (E:A->A->bool) a y.
      model D E ZF_AX /\ eordinal D E a /\ y IN D /\ elwou D E a y
      ==> !p. p IN D
              ==> (E p y <=>
                   ?om hf ho w R dw u u'.
                      om IN D /\ hf IN D /\ ho IN D /\ w IN D /\
                      R IN D /\ dw IN D /\ u IN D /\ u' IN D /\
                      eomega D E om /\ ehfset D E om hf /\
                      ehford D E om ho /\
                      (!t. t IN D
                           ==> (E t w <=>
                                ?b rb yb. b IN D /\ rb IN D /\
                                          yb IN D /\
                                          (E b a /\ elwou D E b rb) /\
                                          elstage D E b yb /\
                                          E t yb)) /\
                      (!q. q IN D
                           ==> (E q R <=>
                                ?b rb. b IN D /\ rb IN D /\
                                       (E b a /\ elwou D E b rb) /\
                                       E q rb)) /\
                      (!y'. y' IN D
                            ==> (E y' dw <=> edefmem D E w y')) /\
                      eopair D E u u' p /\ E u dw /\ E u' dw /\
                      ~(u = u') /\
                      (E p R \/
                       (E u w /\ ~(E u' w)) \/
                       (~(E u w) /\ ~(E u' w) /\
                        elnewlt D E om hf ho w R u u')))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `?r:A. erecres D (E:A->A->bool) lwostepu_form v a r`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ELWOSTEPU_QFUN; ELWOSTEPU_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(r:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `elwostepu D (E:A->A->bool) r y` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `r:A`;
                  `y:A`] HOLDS_LWOSTEPU_FORM) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(SUBST1_TAC o SYM) THEN
    MATCH_MP_TAC EREC_EQUATION THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[ELWOSTEPU_QFUN; ELWOU_EREC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b wr:A. b IN D /\ wr IN D
        ==> (eapply D (E:A->A->bool) r b wr <=>
             E b a /\ elwou D E b wr)`
  (LABEL_TAC "rap") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `eapply D (E:A->A->bool) r b wr <=>
      E b a /\ erec D E lwostepu_form v b wr`
    (fun th -> REWRITE_TAC[th]) THENL
     [EQ_TAC THENL
       [REWRITE_TAC[eapply] THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
          (ASSUME
            `erecres D (E:A->A->bool) lwostepu_form v a r`)))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
          STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `b':A = b /\ y':A = wr` STRIP_ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
        ASM_MESON_TAC[];
        STRIP_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `wr:A`]
              EOPAIR_EXISTS) THEN
        ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(SPEC `z:A` (CONJUNCT2(REWRITE_RULE[erecres]
          (ASSUME
            `erecres D (E:A->A->bool) lwostepu_form v a r`)))) THEN
        ASM_REWRITE_TAC[] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`b:A`; `wr:A`] THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ASM_MESON_TAC[ELWOU_EREC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. (!t. t IN D
               ==> ((E:A->A->bool) t w <=>
                    ?b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                              eapply D E r b rb /\
                              elstage D E b yb /\ E t yb)) <=>
          (!t. t IN D
               ==> (E t w <=>
                    ?b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                              (E b a /\ elwou D E b rb) /\
                              elstage D E b yb /\ E t yb))`
  (LABEL_TAC "wiff") THENL
   [GEN_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(p <=> q) ==> ((a <=> p) <=> (a <=> q))`) THEN
    EQ_TAC THEN
    (DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
       (X_CHOOSE_THEN `yb:A`
         (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))) THEN
     MAP_EVERY EXISTS_TAC [`b:A`; `rb:A`; `yb:A`] THEN
     ASM_REWRITE_TAC[] THEN
     USE_THEN "rap" (fun th ->
       MP_TAC(SPECL [`b:A`; `rb:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[] THEN
     TRY(USE_THEN "rap" (fun th ->
       MP_TAC(SPECL [`b:A`; `rb:A`] th)) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th])));
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!R:A. (!q. q IN D
               ==> ((E:A->A->bool) q R <=>
                    ?b rb. b IN D /\ rb IN D /\
                           eapply D E r b rb /\ E q rb)) <=>
          (!q. q IN D
               ==> (E q R <=>
                    ?b rb. b IN D /\ rb IN D /\
                           (E b a /\ elwou D E b rb) /\ E q rb))`
  (LABEL_TAC "riff") THENL
   [GEN_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
    X_GEN_TAC `q:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(p <=> q) ==> ((a <=> p) <=> (a <=> q))`) THEN
    EQ_TAC THEN
    (DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
       (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
     MAP_EVERY EXISTS_TAC [`b:A`; `rb:A`] THEN
     ASM_REWRITE_TAC[] THEN
     USE_THEN "rap" (fun th ->
       MP_TAC(SPECL [`b:A`; `rb:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[] THEN
     TRY(USE_THEN "rap" (fun th ->
       MP_TAC(SPECL [`b:A`; `rb:A`] th)) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th])));
    ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MP_TAC(SPEC `p:A` (CONJUNCT2(REWRITE_RULE[elwostepu]
    (ASSUME `elwostepu D (E:A->A->bool) r y`)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[elwoltu] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `om:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `hf:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `ho:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `w:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `R:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `dw:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `u:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((?x. P x) <=> (?x. Q x))`) THEN
  X_GEN_TAC `u':A` THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> p') /\ (r <=> r') ==> ((p /\ r) <=> (p' /\ r'))`) THEN
  CONJ_TAC THENL
   [USE_THEN "wiff" (fun th -> MATCH_ACCEPT_TAC th);
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
   `(p <=> p') /\ (r <=> r') ==> ((p /\ r) <=> (p' /\ r'))`) THEN
  CONJ_TAC THENL
   [USE_THEN "riff" (fun th -> MATCH_ACCEPT_TAC th);
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* lwou_form: internal "j = the L order at stage i" (recapp_form nesting of  *)
(* the step lwostepu_form).  elwoinvu a is the transfinite wellordering      *)
(* invariant: with ra = elwou a and ya = L(a), (1) every member of ra is an  *)
(* ordered pair of distinct members of ya, (2) ra is transitive,             *)
(* (3) asymmetric and (4) total on ya, (5) it is coherent with every earlier *)
(* stage (rb is exactly ra restricted to L(b) x L(b) for b IN a),            *)
(* (6) members of an earlier stage L(b) precede all members of ya outside    *)
(* L(b), and (7) every nonempty subset of ya has an ra-least member.         *)
(* linv5u_form internalizes the coherence clause (5) with the b-indexed      *)
(* elwou, lwoinvu_form binds ra/ya over lwou_form 0 4 and lstage_form 0 5    *)
(* and conjoins the seven clauses, and HOLDS_LWOINVU_FORM bridges it to      *)
(* elwoinvu (v 0).                                                           *)
(* ------------------------------------------------------------------------- *)

let lwou_form = new_definition
  `lwou_form i j = recapp_form (rec_form lwostepu_form 2) i j`;;

let HOLDS_LWOU_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 2) /\ ~(i = 3) /\ ~(j = 2) /\ ~(j = 3)
        ==> (holds D E v (lwou_form i j) <=>
             elwou D E (v i) (v j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[lwou_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `rec_form lwostepu_form 2`; `i:num`; `j:num`]
    HOLDS_RECAPP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (v:num->A) j) ((2 |-> v i) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `lwostepu_form`; `2`; `(v:num->A) i`; `(v:num->A) j`]
    HOLDS_REC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ARITH_TAC; ACCEPT_TAC FVLT_LWOSTEPU_FORM];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
    `(v:num->A) j`; `v:num->A`] ELWOU_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let elwoinvu = new_definition
  `elwoinvu D (E:A->A->bool) a <=>
     ?ra ya.
        ra IN D /\ ya IN D /\ elwou D E a ra /\ elstage D E a ya /\
        (!p. p IN D /\ E p ra
             ==> ?u u'. u IN D /\ u' IN D /\ E u ya /\ E u' ya /\
                        ~(u = u') /\ eopair D E u u' p) /\
        (!u u' u''. u IN D /\ u' IN D /\ u'' IN D /\
                    erel D E ra u u' /\ erel D E ra u' u''
                    ==> erel D E ra u u'') /\
        (!u u'. u IN D /\ u' IN D /\ erel D E ra u u'
                ==> ~(erel D E ra u' u)) /\
        (!u u'. u IN D /\ u' IN D /\ E u ya /\ E u' ya /\
                ~(u = u')
                ==> erel D E ra u u' \/ erel D E ra u' u) /\
        (!b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b a /\
                   elwou D E b rb /\ elstage D E b yb
                   ==> !p. p IN D
                           ==> (E p rb <=>
                                E p ra /\
                                ?u u'. u IN D /\ u' IN D /\
                                       E u yb /\ E u' yb /\
                                       eopair D E u u' p)) /\
        (!b yb u u'. b IN D /\ yb IN D /\ E b a /\
                     elstage D E b yb /\
                     u IN D /\ u' IN D /\ E u yb /\ E u' ya /\
                     ~(E u' yb)
                     ==> erel D E ra u u') /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t ya) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E ra m t)`;;

let linv5u_form = new_definition
  `linv5u_form =
     !! 10 (!! 11 (!! 12
       (((10 %% 0) && (lwou_form 10 11 && lstage_form 10 12))
        --> !! 6 ((6 %% 11) <->
                  ((6 %% 4) &&
                   ?? 7 (?? 8 ((7 %% 12) && ((8 %% 12) &&
                               opair_form 7 8 6))))))))`;;

let HOLDS_LINV5U_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v linv5u_form <=>
             !b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                       E b (v 0) /\ elwou D E b rb /\
                       elstage D E b yb
                       ==> !p. p IN D
                               ==> (E p rb <=>
                                    E p (v 4) /\
                                    ?u u'. u IN D /\ u' IN D /\
                                           E u yb /\ E u' yb /\
                                           eopair D E u u' p))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b rb yb:A. b IN D /\ rb IN D /\ yb IN D
      ==> (holds D E ((12 |-> yb) ((11 |-> rb) ((10 |-> b) v)))
             (lwou_form 10 11) <=>
           elwou D (E:A->A->bool) b rb) /\
          (holds D E ((12 |-> yb) ((11 |-> rb) ((10 |-> b) v)))
             (lstage_form 10 12) <=>
           elstage D (E:A->A->bool) b yb)`
  (LABEL_TAC "r1") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(12 |-> (yb:A)) ((11 |-> (rb:A)) ((10 |-> (b:A)) v))`;
        `10`; `11`] HOLDS_LWOU_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(12 |-> (yb:A)) ((11 |-> (rb:A)) ((10 |-> (b:A)) v))`;
        `10`; `12`] HOLDS_LSTAGE_FORM)] THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       ASM_MESON_TAC[VALUATION_VALMOD];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b rb yb p u u':A.
      b IN D /\ rb IN D /\ yb IN D /\ p IN D /\ u IN D /\ u' IN D
      ==> (holds D E ((8 |-> u') ((7 |-> u) ((6 |-> p)
             ((12 |-> yb) ((11 |-> rb) ((10 |-> b) v))))))
             (opair_form 7 8 6) <=>
           eopair D (E:A->A->bool) u u' p)`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (u':A)) ((7 |-> (u:A)) ((6 |-> (p:A))
         ((12 |-> (yb:A)) ((11 |-> (rb:A)) ((10 |-> (b:A)) v)))))`;
      `7`; `8`; `6`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[linv5u_form; HOLDS_IFF; HOLDS_EX; HOLDS_AND; holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_EQ] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_IMP_FORALL_THM] THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `b:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `rb:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `yb:A` THEN
  MATCH_MP_TAC(MESON[]
   `(!x:A. P x <=> Q x) ==> ((!x. P x) <=> (!x. Q x))`) THEN
  X_GEN_TAC `p:A` THEN
  REPLICATE_TAC 7
   (MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a <=> p) <=> (a <=> q))`) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
  EQ_TAC THENL
   [INTRO_TAC "@u. h1 @u'. h2 h3 h4 +" THEN
    USE_THEN "r2" (fun th -> MP_TAC(SPECL
      [`b:A`; `rb:A`; `yb:A`; `p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `u':A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "r2" (fun th -> MP_TAC(SPECL
      [`b:A`; `rb:A`; `yb:A`; `p:A`; `u:A`; `u':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[]]);;

let lwoinvu_form = new_definition
  `lwoinvu_form =
     ?? 4 (lwou_form 0 4 &&
       ?? 5 (lstage_form 0 5 &&
         (linv1_form &&
          (linv2_form &&
           (linv3_form &&
            (linv4_form &&
             (linv5u_form &&
              (linv6_form && linv7_form))))))))`;;

let HOLDS_LWOINVU_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v lwoinvu_form <=> elwoinvu D E (v 0))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ra:A. ra IN D
      ==> (holds D E ((4 |-> ra) v) (lwou_form 0 4) <=>
           elwou D (E:A->A->bool) (v 0) ra)`
  (LABEL_TAC "q1") THENL
   [X_GEN_TAC `ra:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (ra:A)) v`; `0`; `4`] HOLDS_LWOU_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!ra ya:A. ra IN D /\ ya IN D
      ==> (holds D E ((5 |-> ya) ((4 |-> ra) v))
             (lstage_form 0 5) <=>
           elstage D (E:A->A->bool) (v 0) ya) /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv1_form <=>
           !p. p IN D /\ E p ra
               ==> ?u u'. u IN D /\ u' IN D /\ E u ya /\
                          E u' ya /\ ~(u = u') /\
                          eopair D (E:A->A->bool) u u' p) /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv2_form <=>
           !u u' u''. u IN D /\ u' IN D /\ u'' IN D /\
                      erel D (E:A->A->bool) ra u u' /\
                      erel D E ra u' u''
                      ==> erel D E ra u u'') /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv3_form <=>
           !u u'. u IN D /\ u' IN D /\
                  erel D (E:A->A->bool) ra u u'
                  ==> ~(erel D E ra u' u)) /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv4_form <=>
           !u u'. u IN D /\ u' IN D /\ E u ya /\ E u' ya /\
                  ~(u = u')
                  ==> erel D (E:A->A->bool) ra u u' \/
                      erel D E ra u' u) /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv5u_form <=>
           !b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                     E b (v 0) /\ elwou D (E:A->A->bool) b rb /\
                     elstage D E b yb
                     ==> !p. p IN D
                             ==> (E p rb <=>
                                  E p ra /\
                                  ?u u'. u IN D /\ u' IN D /\
                                         E u yb /\ E u' yb /\
                                         eopair D E u u' p)) /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv6_form <=>
           !b yb u u'. b IN D /\ yb IN D /\ u IN D /\ u' IN D /\
                       E b (v 0) /\
                       elstage D (E:A->A->bool) b yb /\
                       E u yb /\ E u' ya /\ ~(E u' yb)
                       ==> erel D E ra u u') /\
          (holds D E ((5 |-> ya) ((4 |-> ra) v)) linv7_form <=>
           !z. z IN D /\ (!t. t IN D /\ E t z ==> E t ya) /\
               (?t. t IN D /\ E t z)
               ==> ?m. m IN D /\ E m z /\
                       !t. t IN D /\ E t z /\ ~(t = m)
                           ==> erel D (E:A->A->bool) ra m t)`
  (LABEL_TAC "q2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((5 |-> (ya:A)) ((4 |-> (ra:A)) v))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`; `0`; `5`]
        HOLDS_LSTAGE_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV1_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV2_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV3_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV4_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV5U_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV6_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (ya:A)) ((4 |-> (ra:A)) v)`] HOLDS_LINV7_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC]] THEN
    (DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[lwoinvu_form; HOLDS_EX; HOLDS_AND] THEN
  EQ_TAC THENL
   [INTRO_TAC "@ra. h3 h1 @ya. h4 h2 c1 c2 c3 c4 c5 c6 c7" THEN
    USE_THEN "q1" (fun th -> MP_TAC(SPEC `ra:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun rr -> USE_THEN "h1" (fun h ->
      ASSUME_TAC(REWRITE_RULE[rr] h))) THEN
    USE_THEN "q2" (fun th -> MP_TAC(SPECL [`ra:A`; `ya:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun rr ->
      USE_THEN "h2" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c1" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c2" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c3" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c4" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c5" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c7" (fun h -> ASSUME_TAC(REWRITE_RULE[rr] h)) THEN
      USE_THEN "c6" (fun h ->
        LABEL_TAC "d6" (REWRITE_RULE[rr] h))) THEN
    REWRITE_TAC[elwoinvu] THEN
    MAP_EVERY EXISTS_TAC [`ra:A`; `ya:A`] THEN
    ASM_REWRITE_TAC[] THEN
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    USE_THEN "d6" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[elwoinvu] THEN
  INTRO_TAC "@ra ya. h5 h6 h7 h8 e1 e2 e3 e4 e5 e6 e7" THEN
  EXISTS_TAC `ra:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "q1" (fun th -> ASM_SIMP_TAC[th]) THEN
  EXISTS_TAC `ya:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "q2" (fun th -> ASM_SIMP_TAC[th]) THEN
    CONJ_TAC THENL
   [USE_THEN "e2" ACCEPT_TAC;
    CONJ_TAC THENL
     [USE_THEN "e5" ACCEPT_TAC;
      REPEAT GEN_TAC THEN STRIP_TAC THEN
      USE_THEN "e6" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN
      ASM_REWRITE_TAC[]]]]);;

(* ------------------------------------------------------------------------- *)
(* Support lemmas for the wellordering invariant induction: existence of the *)
(* union-of-orders set R_a, edefmem over an empty carrier, successor bounds, *)
(* the canonical-parameter membership characterization of elwou (normalizing *)
(* the existential witnesses of ELWOU_CHAR via uniqueness/extensionality),   *)
(* the bundled canonical-parameter package, and monotonicity of elwou.       *)
(* ------------------------------------------------------------------------- *)

let ERAU_EXISTS = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?R. R IN D /\
                !q. q IN D
                    ==> (E q R <=>
                         ?b rb. b IN D /\ rb IN D /\ E b a /\
                                elwou D E b rb /\ E q rb)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w:A. b IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> b) v0)) (lwou_form 0 1) <=>
           elwou D (E:A->A->bool) b w)`
  (LABEL_TAC "lr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (b:A)) v0)`; `0`; `1`]
      HOLDS_LWOU_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`lwou_form 0 1`; `0`; `1`; `v0:num->A`; `a:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `?w:A. w IN D /\ elwou D (E:A->A->bool) b w`
    (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[ELWOU_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `elwou D (E:A->A->bool) b w'` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    ASM_MESON_TAC[ELWOU_UNIQUE];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `bb:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "bch"))) THEN
  SUBGOAL_THEN `?R:A. eunion D (E:A->A->bool) bb R`
  (X_CHOOSE_TAC `R:A`) THENL
   [ASM_MESON_TAC[EUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(R:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  EXISTS_TAC `R:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `q:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `(E:A->A->bool) q R <=> ?r'. r' IN D /\ E r' bb /\ E q r'`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `r':A` STRIP_ASSUME_TAC) THEN
    USE_THEN "bch" (fun th -> MP_TAC(SPEC `r':A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) r' bb`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `r':A`] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "lr" (fun th -> ASM_MESON_TAC[th]);
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `rb:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "bch" (fun th -> MP_TAC(SPEC `rb:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "lr" (fun th -> ASM_MESON_TAC[th])]);;

let EDEFMEM_EMPTY = prove
 (`!D (E:A->A->bool) w u.
        model D E ZF_AX /\ w IN D /\ u IN D /\ eempty D E w /\
        edefmem D E w u
        ==> eempty D E u`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) u w` ASSUME_TAC THENL
   [ASM_MESON_TAC[edefmem]; ALL_TAC] THEN
  REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[esubset; eempty]);;

let EORDINAL_SUC_LE = prove
 (`!D (E:A->A->bool) a b sb.
        model D E ZF_AX /\ eordinal D E a /\ b IN D /\ E b a /\
        esuc D E b sb
        ==> E sb a \/ sb = a`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(sb:A) IN D /\ (a:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN; EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sb` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER; EORDINAL_ESUC]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sb:A`; `a:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(E:A->A->bool) a b \/ (a:A) = b` MP_TAC THENL
   [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
  ASM_MESON_TAC[E_NOCYCLE2]);;

let ELWOU_MEMBER = prove
 (`!D (E:A->A->bool) om hf ho a ra wa Ra ya.
        model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
        ehford D E om ho /\ eordinal D E a /\ ra IN D /\
        elwou D E a ra /\ wa IN D /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        Ra IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        ya IN D /\ elstage D E a ya
        ==> !p. p IN D
                ==> (E p ra <=>
                     ?u u'. u IN D /\ u' IN D /\
                            eopair D E u u' p /\ E u ya /\
                            E u' ya /\ ~(u = u') /\
                            (E p Ra \/
                             (E u wa /\ ~(E u' wa)) \/
                             (~(E u wa) /\ ~(E u' wa) /\
                              elnewlt D E om hf ho wa Ra u u')))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 wach h9 rach h10 h11" THEN
  SUBGOAL_THEN
   `!y:A. y IN D ==> ((E:A->A->bool) y ya <=> edefmem D E wa y)`
  (LABEL_TAC "yach") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
      ELSTAGE_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@w''. h12 w2ch h13" THEN
    SUBGOAL_THEN `(w'':A) = wa` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
      USE_THEN "w2ch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "wach" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[];
      ALL_TAC] THEN
    ASM_MESON_TAC[edef];
    ALL_TAC] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`]
    ELWOU_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `om':A`
               (X_CHOOSE_THEN `hf':A`
                (X_CHOOSE_THEN `ho':A`
                 (X_CHOOSE_THEN `w':A`
                  (X_CHOOSE_THEN `R':A`
                   (X_CHOOSE_THEN `dw':A`
                    (X_CHOOSE_THEN `u:A`
                     (X_CHOOSE_THEN `u':A`
                      (CONJUNCTS_THEN2 ASSUME_TAC
                       (CONJUNCTS_THEN2 ASSUME_TAC
                        (CONJUNCTS_THEN2 ASSUME_TAC
                         (CONJUNCTS_THEN2 ASSUME_TAC
                          (CONJUNCTS_THEN2 ASSUME_TAC
                           (CONJUNCTS_THEN2 ASSUME_TAC
                            (CONJUNCTS_THEN2 ASSUME_TAC
                             (CONJUNCTS_THEN2 ASSUME_TAC
                              (CONJUNCTS_THEN2 ASSUME_TAC
                               (CONJUNCTS_THEN2 ASSUME_TAC
                                (CONJUNCTS_THEN2 ASSUME_TAC
                                 (CONJUNCTS_THEN2 (LABEL_TAC "w1")
                                  (CONJUNCTS_THEN2 (LABEL_TAC "r1")
                                   (CONJUNCTS_THEN2 (LABEL_TAC "d1")
                                    (REPEAT_TCL CONJUNCTS_THEN
                                     ASSUME_TAC))))))))))))))))))))))) THEN
    SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `(hf':A) = hf` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EHFSET_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `(ho':A) = ho` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EHFORD_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `(w':A) = wa` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `t:A` THEN DISCH_TAC THEN
      USE_THEN "w1" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "wach" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[ELWOU_EXISTS; EORDINAL_MEMBER];
      ALL_TAC] THEN
    SUBGOAL_THEN `(R':A) = Ra` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `q:A` THEN DISCH_TAC THEN
      USE_THEN "r1" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "rach" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(dw':A) = ya` SUBST_ALL_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `y0:A` THEN DISCH_TAC THEN
      USE_THEN "d1" (fun th -> MP_TAC(SPEC `y0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "yach" (fun th -> MP_TAC(SPEC `y0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
    SUBGOAL_THEN
     `!t. t IN D
          ==> ((E:A->A->bool) t wa <=>
               ?b rb yb. b IN D /\ rb IN D /\ yb IN D /\
                         (E b a /\ elwou D E b rb) /\
                         elstage D E b yb /\ E t yb)`
    ASSUME_TAC THENL
     [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
      USE_THEN "wach" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_MESON_TAC[ELWOU_EXISTS; EORDINAL_MEMBER];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!q. q IN D
          ==> ((E:A->A->bool) q Ra <=>
               ?b rb. b IN D /\ rb IN D /\
                      (E b a /\ elwou D E b rb) /\ E q rb)`
    ASSUME_TAC THENL
     [X_GEN_TAC `q:A` THEN DISCH_TAC THEN
      USE_THEN "rach" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN MESON_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `u:A`;
      `u':A`] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EOMEGA_IN; ehfset; ehford]]);;

let ELWOU_CANON = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a
        ==> ?om hf ho wa Ra ya.
               om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\
               Ra IN D /\ ya IN D /\
               eomega D E om /\ ehfset D E om hf /\
               ehford D E om ho /\
               (!t. t IN D
                    ==> (E t wa <=>
                         ?b yb. b IN D /\ yb IN D /\ E b a /\
                                elstage D E b yb /\ E t yb)) /\
               (!q. q IN D
                    ==> (E q Ra <=>
                         ?b rb. b IN D /\ rb IN D /\ E b a /\
                                elwou D E b rb /\ E q rb)) /\
               elstage D E a ya /\
               (!y. y IN D ==> (E y ya <=> edefmem D E wa y))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?om:A. eomega D (E:A->A->bool) om`
  (X_CHOOSE_TAC `om:A`) THENL
   [ASM_MESON_TAC[EOMEGA_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?hf:A. ehfset D (E:A->A->bool) om hf`
  (X_CHOOSE_TAC `hf:A`) THENL
   [ASM_MESON_TAC[EHFSET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?ho:A. ehford D (E:A->A->bool) om ho`
  (X_CHOOSE_TAC `ho:A`) THENL
   [ASM_MESON_TAC[EHFORD_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ya:A. ya IN D /\ elstage D (E:A->A->bool) a ya`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
    ELSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@wa. h1 h2 +" THEN
  REWRITE_TAC[edef] THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ERAU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Ra:A` STRIP_ASSUME_TAC) THEN
  MAP_EVERY EXISTS_TAC
   [`om:A`; `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ehfset; ehford]);;

let ELWOU_MONO = prove
 (`!D (E:A->A->bool) a b ra rb.
        model D E ZF_AX /\ eordinal D E a /\ b IN D /\ E b a /\
        ra IN D /\ rb IN D /\ elwou D E a ra /\ elwou D E b rb
        ==> !q. q IN D /\ E q rb ==> E q ra`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ELWOU_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@om hf ho wa Ra ya. h1 h2 h3 h4 h5 h6 h7 h8 h9 wacha racha h10
             yacha" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`] ELWOU_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `om2:A`
             (X_CHOOSE_THEN `hf2:A`
              (X_CHOOSE_THEN `ho2:A`
               (X_CHOOSE_THEN `wb:A`
                (X_CHOOSE_THEN `Rb:A`
                 (X_CHOOSE_THEN `yb:A` (STRIP_ASSUME_TAC))))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
    `ho:A`; `a:A`; `ra:A`; `wa:A`; `Ra:A`; `ya:A`] ELWOU_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "mema") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om2:A`; `hf2:A`;
    `ho2:A`; `b:A`; `rb:A`; `wb:A`; `Rb:A`; `yb:A`] ELWOU_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "memb") THEN
  X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  USE_THEN "mema" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "memb" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
    (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) u ya /\ (E:A->A->bool) u' ya`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN
    MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
      `ya:A`; `yb:A`] ELSTAGE_MONO) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN
  USE_THEN "racha" (fun th -> MP_TAC(SPEC `q:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `rb:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* IH plumbing for the wellordering-invariant induction: normalizing the     *)
(* invariant to given (rb,yb), max of two ordinals below a, non-strict       *)
(* monotonicity, stage linearity, and the union order R_a inheriting         *)
(* transitivity, asymmetry and totality-on-old from the inductive            *)
(* hypothesis.                                                               *)
(* ------------------------------------------------------------------------- *)

let ELWOINVU_NORM = prove
 (`!D (E:A->A->bool) b rb yb.
        model D E ZF_AX /\ b IN D /\ rb IN D /\ yb IN D /\
        elwoinvu D E b /\ elwou D E b rb /\ elstage D E b yb
        ==> (!p. p IN D /\ E p rb
                 ==> ?u u'. u IN D /\ u' IN D /\ E u yb /\
                            E u' yb /\ ~(u = u') /\
                            eopair D E u u' p) /\
            (!u u' u''. u IN D /\ u' IN D /\ u'' IN D /\
                        erel D E rb u u' /\ erel D E rb u' u''
                        ==> erel D E rb u u'') /\
            (!u u'. u IN D /\ u' IN D /\ erel D E rb u u'
                    ==> ~(erel D E rb u' u)) /\
            (!u u'. u IN D /\ u' IN D /\ E u yb /\ E u' yb /\
                    ~(u = u')
                    ==> erel D E rb u u' \/ erel D E rb u' u) /\
            (!c rc yc. c IN D /\ rc IN D /\ yc IN D /\ E c b /\
                       elwou D E c rc /\ elstage D E c yc
                       ==> !p. p IN D
                               ==> (E p rc <=>
                                    E p rb /\
                                    ?u u'. u IN D /\ u' IN D /\
                                           E u yc /\ E u' yc /\
                                           eopair D E u u' p)) /\
            (!c yc u u'. c IN D /\ yc IN D /\ E c b /\
                         elstage D E c yc /\
                         u IN D /\ u' IN D /\ E u yc /\
                         E u' yb /\ ~(E u' yc)
                         ==> erel D E rb u u') /\
            (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t yb) /\
                 (?t. t IN D /\ E t z)
                 ==> ?m. m IN D /\ E m z /\
                         !t. t IN D /\ E t z /\ ~(t = m)
                             ==> erel D E rb m t)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [elwoinvu]) THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` (X_CHOOSE_THEN `ya:A`
    (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
  SUBGOAL_THEN `(ra:A) = rb` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELWOU_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(ya:A) = yb` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[ELSTAGE_UNIQUE]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let EORDINAL_MAX2 = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ eordinal D E a /\ b IN D /\ c IN D /\
        E b a /\ E c a
        ==> ?d. d IN D /\ E d a /\ (E b d \/ b = d) /\
                (E c d \/ c = d)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) b /\ eordinal D E c`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `c:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [EXISTS_TAC `c:A`; EXISTS_TAC `c:A`; EXISTS_TAC `b:A`] THEN
  ASM_REWRITE_TAC[]);;

let ELWOU_LE = prove
 (`!D (E:A->A->bool) d b rb rd.
        model D E ZF_AX /\ eordinal D E d /\ b IN D /\
        (E b d \/ b = d) /\ rb IN D /\ rd IN D /\
        elwou D E b rb /\ elwou D E d rd
        ==> !q. q IN D /\ E q rb ==> E q rd`,
  ASM_MESON_TAC[ELWOU_MONO; ELWOU_UNIQUE; EORDINAL_IN]);;

let ELSTAGE_LINEAR = prove
 (`!D (E:A->A->bool) b c yb yc t.
        model D E ZF_AX /\ eordinal D E b /\ eordinal D E c /\
        yb IN D /\ yc IN D /\ elstage D E b yb /\
        elstage D E c yc /\ t IN D /\ E t yc /\ ~(E t yb)
        ==> E b c`,
  ASM_MESON_TAC[EORDINAL_TRICHOTOMY; ELSTAGE_UNIQUE; ELSTAGE_MONO;
                EORDINAL_IN]);;

let ELSTAGE_LE = prove
 (`!D (E:A->A->bool) d b yb yd.
        model D E ZF_AX /\ eordinal D E d /\ b IN D /\
        (E b d \/ b = d) /\ yb IN D /\ yd IN D /\
        elstage D E b yb /\ elstage D E d yd
        ==> !t. t IN D /\ E t yb ==> E t yd`,
  ASM_MESON_TAC[ELSTAGE_MONO; ELSTAGE_UNIQUE; EORDINAL_IN]);;

let RA_DROP = prove
 (`!D (E:A->A->bool) a Ra x y.
        model D E ZF_AX /\ Ra IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        x IN D /\ y IN D /\ erel D E Ra x y
        ==> ?b rb. b IN D /\ rb IN D /\ E b a /\
                   elwou D E b rb /\ erel D E rb x y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ch h3 h4 +" THEN
  REWRITE_TAC[erel] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC o CONJUNCT2 o CONJUNCT2) THEN
  USE_THEN "ch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `rb:A`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `rb:A`] THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]);;

let RA_LIFT = prove
 (`!D (E:A->A->bool) a Ra d rd x y.
        model D E ZF_AX /\ Ra IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        d IN D /\ rd IN D /\ E d a /\ elwou D E d rd /\
        x IN D /\ y IN D /\ erel D E rd x y
        ==> erel D E Ra x y`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "ch") (REPEAT_TCL CONJUNCTS_THEN
      ASSUME_TAC)))) THEN
  FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o CONJUNCT2 o GEN_REWRITE_RULE I
                [erel]) THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
  REWRITE_TAC[erel] THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `p:A` THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "ch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`d:A`; `rd:A`] THEN ASM_REWRITE_TAC[]);;

let EREL_SUBSET = prove
 (`!D (E:A->A->bool) r r' x y.
        erel D E r x y /\ (!q. q IN D /\ E q r ==> E q r')
        ==> erel D E r' x y`,
  REWRITE_TAC[erel] THEN MESON_TAC[]);;

let RA_TRANS = prove
 (`!D (E:A->A->bool) a Ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        Ra IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb))
        ==> !u u' u''. u IN D /\ u' IN D /\ u'' IN D /\
                       erel D E Ra u u' /\ erel D E Ra u' u''
                       ==> erel D E Ra u u''`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 ih h3 ch" THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
    `u:A`; `u':A`] RA_DROP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `rb1:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
    `u':A`; `u'':A`] RA_DROP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `rb2:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b1:A`;
    `b2:A`] EORDINAL_MAX2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) d` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `d:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rd u u'` ASSUME_TAC THENL
   [MATCH_MP_TAC EREL_SUBSET THEN EXISTS_TAC `rb1:A` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b1:A`;
      `rb1:A`; `rd:A`] ELWOU_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rd u' u''` ASSUME_TAC THENL
   [MATCH_MP_TAC EREL_SUBSET THEN EXISTS_TAC `rb2:A` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b2:A`;
      `rb2:A`; `rd:A`] ELWOU_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `rd:A`; `yd:A`]
    ELWOINVU_NORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPECL [`u:A`; `u':A`; `u'':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`; `d:A`;
    `rd:A`; `u:A`; `u'':A`] RA_LIFT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let RA_ASYM = prove
 (`!D (E:A->A->bool) a Ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        Ra IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb))
        ==> !u u'. u IN D /\ u' IN D /\ erel D E Ra u u'
                   ==> ~(erel D E Ra u' u)`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 ih h3 ch" THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
    `u:A`; `u':A`] RA_DROP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `rb1:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
    `u':A`; `u:A`] RA_DROP) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `rb2:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b1:A`;
    `b2:A`] EORDINAL_MAX2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) d` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `d:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rd u u'` ASSUME_TAC THENL
   [MATCH_MP_TAC EREL_SUBSET THEN EXISTS_TAC `rb1:A` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b1:A`;
      `rb1:A`; `rd:A`] ELWOU_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `erel D (E:A->A->bool) rd u' u` ASSUME_TAC THENL
   [MATCH_MP_TAC EREL_SUBSET THEN EXISTS_TAC `rb2:A` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b2:A`;
      `rb2:A`; `rd:A`] ELWOU_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `rd:A`; `yd:A`]
    ELWOINVU_NORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPECL [`u:A`; `u':A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let RA_TOTAL_WA = prove
 (`!D (E:A->A->bool) a Ra wa.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        Ra IN D /\ wa IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb))
        ==> !x y. x IN D /\ y IN D /\ E x wa /\ E y wa /\ ~(x = y)
                  ==> erel D E Ra x y \/ erel D E Ra y x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 ch wch" THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  USE_THEN "wch" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b1:A` (X_CHOOSE_THEN `yb1:A`
    STRIP_ASSUME_TAC)) THEN
  USE_THEN "wch" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `yb2:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b1:A`;
    `b2:A`] EORDINAL_MAX2) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) d` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `d:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rd:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) x yd` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b1:A`;
      `yb1:A`; `yd:A`] ELSTAGE_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) y yd` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b2:A`;
      `yb2:A`; `yd:A`] ELSTAGE_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `rd:A`; `yd:A`]
    ELWOINVU_NORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2 o CONJUNCT2 o
             CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPECL [`x:A`; `y:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [DISJ1_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`; `d:A`;
    `rd:A`; `x:A`; `y:A`] RA_LIFT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC;
    DISJ2_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`; `d:A`;
    `rd:A`; `y:A`; `x:A`] RA_LIFT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The least stage meeting a given set z (via EORDINAL_LEAST on an internal  *)
(* meet formula), and wellfoundedness of the union order R_a on the old part *)
(* w_a: combine the least meeting stage b0, the inductive wellfoundedness at *)
(* b0 on z INTER L(b0), and the stage-in-stage clause at later stages.       *)
(* ------------------------------------------------------------------------- *)

let meetz_form = new_definition
  `meetz_form = ?? 5 (?? 6 (lstage_form 0 5 && ((6 %% 1) && (6 %% 5))))`;;

let HOLDS_MEETZ_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v meetz_form <=>
             ?yd s. yd IN D /\ s IN D /\ elstage D E (v 0) yd /\
                    E s (v 1) /\ E s yd)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!yd s:A. yd IN D /\ s IN D
      ==> (holds D E ((6 |-> s) ((5 |-> yd) v)) (lstage_form 0 5) <=>
           elstage D (E:A->A->bool) (v 0) yd)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (s:A)) ((5 |-> (yd:A)) v)`; `0`; `5`]
      HOLDS_LSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[meetz_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL
   [INTRO_TAC "@yd. h1 @s. h2 +" THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]) THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`yd:A`; `s:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `yd:A` (X_CHOOSE_THEN `s:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `yd:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th])]);;

let MEETSTAGE_LEAST = prove
 (`!D (E:A->A->bool) a z b yb t.
        model D E ZF_AX /\ eordinal D E a /\ z IN D /\
        b IN D /\ yb IN D /\ t IN D /\ E b a /\
        elstage D E b yb /\ E t z /\ E t yb
        ==> ?b0 yb0. b0 IN D /\ yb0 IN D /\ E b0 a /\
                     elstage D E b0 yb0 /\
                     (?s. s IN D /\ E s z /\ E s yb0) /\
                     !c yc s. c IN D /\ yc IN D /\ s IN D /\
                              E c b0 /\ elstage D E c yc /\ E s z
                              ==> ~(E s yc)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (1 |-> (z:A)) v0` THEN
  SUBGOAL_THEN `valuation D (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 1 = z` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A. d IN D
      ==> (holds D E ((0 |-> d) v1) meetz_form <=>
           ?yd s. yd IN D /\ s IN D /\ elstage D (E:A->A->bool) d yd /\
                  E s z /\ E s yd)`
  (LABEL_TAC "hm") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (d:A)) v1`] HOLDS_MEETZ_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `meetz_form`;
    `v1:num->A`; `b:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "hm" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`yb:A`; `t:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@d. h1 h2 + min" THEN
  USE_THEN "hm" (fun th -> ASM_SIMP_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `yd0:A` (X_CHOOSE_THEN `s0:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `(E:A->A->bool) d a` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `b:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [ASM_MESON_TAC[eordinal; etransitive; esubset];
      ASM_MESON_TAC[];
      USE_THEN "min" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "hm" (fun th -> ASM_SIMP_TAC[th]) THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN
      DISCH_THEN(MP_TAC o SPECL [`yb:A`; `t:A`]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`d:A`; `yd0:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [EXISTS_TAC `s0:A` THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  USE_THEN "min" (fun th -> MP_TAC(SPEC `c:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "hm" (fun th -> ASM_SIMP_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`yc:A`; `s:A`] THEN ASM_REWRITE_TAC[]);;

let RA_WF = prove
 (`!D (E:A->A->bool) a Ra wa.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        Ra IN D /\ wa IN D /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb))
        ==> !z. z IN D /\ (!t. t IN D /\ E t z ==> E t wa) /\
                (?t. t IN D /\ E t z)
                ==> ?m. m IN D /\ E m z /\
                        !t. t IN D /\ E t z /\ ~(t = m)
                            ==> erel D E Ra m t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 ch wch" THEN
  X_GEN_TAC `z:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "zsub") (X_CHOOSE_THEN `t0:A`
      STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `(E:A->A->bool) t0 wa` ASSUME_TAC THENL
   [USE_THEN "zsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?b yb. b IN D /\ yb IN D /\ (E:A->A->bool) b a /\
           elstage D E b yb /\ E t0 yb`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "wch" (fun th -> MP_TAC(SPEC `t0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `z:A`; `b:A`;
    `yb:A`; `t0:A`] MEETSTAGE_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b0:A` (X_CHOOSE_THEN `yb0:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 (X_CHOOSE_THEN `s0:A` STRIP_ASSUME_TAC)
          (LABEL_TAC "min")))))))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b0` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b0:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b0:A`]
    ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rb0:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `yb0:A`]
    EINTER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z0:A` MP_TAC) THEN
  REWRITE_TAC[einter] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "z0ch")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b0:A`; `rb0:A`;
    `yb0:A`] ELWOINVU_NORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    MP_TAC(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
      (CONJUNCT2 th))))))) THEN
  DISCH_THEN(MP_TAC o SPEC `z0:A`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "z0ch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[CONJUNCT2 th]);
      EXISTS_TAC `s0:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "z0ch" (fun th -> MP_TAC(SPEC `s0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  INTRO_TAC "@m. h5 h6 mlt" THEN
  SUBGOAL_THEN
   `(E:A->A->bool) m z /\ (E:A->A->bool) m yb0`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "z0ch" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) t yb0` THENL
   [SUBGOAL_THEN `(E:A->A->bool) t z0` ASSUME_TAC THENL
     [USE_THEN "z0ch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) rb0 m t` ASSUME_TAC THENL
     [USE_THEN "mlt" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
      `b0:A`; `rb0:A`; `m:A`; `t:A`] RA_LIFT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    SUBGOAL_THEN `(E:A->A->bool) t wa` ASSUME_TAC THENL
     [USE_THEN "zsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `?c yc. c IN D /\ yc IN D /\ (E:A->A->bool) c a /\
             elstage D E c yc /\ E t yc`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "wch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `c:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b0 c` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b0:A`; `c:A`;
        `yb0:A`; `yc:A`; `t:A`] ELSTAGE_LINEAR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`]
      ELWOU_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rc:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rc:A`;
      `yc:A`] ELWOINVU_NORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(CONJUNCT1(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
        (CONJUNCT2 th))))))) THEN
    DISCH_THEN(MP_TAC o SPECL [`b0:A`; `yb0:A`; `m:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
      `c:A`; `rc:A`; `m:A`; `t:A`] RA_LIFT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* Edge classification for the union order at stage a: every ra-edge is      *)
(* old-old (inherited via R_a), old-new, or new-new (elnewlt); and the       *)
(* converse edge builders via the canonical membership characterization.     *)
(* ------------------------------------------------------------------------- *)

let WA_SUB_YA = prove
 (`!D (E:A->A->bool) a wa ya.
        model D E ZF_AX /\ eordinal D E a /\ wa IN D /\ ya IN D /\
        elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb))
        ==> !t. t IN D /\ E t wa ==> E t ya`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 wch" THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `?b yb. b IN D /\ yb IN D /\ (E:A->A->bool) b a /\
           elstage D E b yb /\ E t yb`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "wch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `ya:A`;
    `yb:A`; `t:A`] ELSTAGE_MONO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let ELWOU_PAIRSHAPE = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !p. p IN D /\ E p ra
                ==> ?u u'. u IN D /\ u' IN D /\ E u ya /\
                           E u' ya /\ ~(u = u') /\
                           eopair D E u u' p`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
    `ho:A`; `a:A`; `ra:A`; `wa:A`; `Ra:A`; `ya:A`] ELWOU_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "mem") THEN
  X_GEN_TAC `p:A` THEN STRIP_TAC THEN
  USE_THEN "mem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
    (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
  MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN ASM_REWRITE_TAC[]);;

let ELWOU_EDGE_OLD = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !x y. x IN D /\ y IN D /\ erel D E Ra x y
                  ==> erel D E ra x y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
