let ELWOU_EDGE = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !x y. x IN D /\ y IN D /\ erel D E ra x y
                  ==> E x ya /\ E y ya /\ ~(x = y) /\
                      (E x wa /\ E y wa /\ erel D E Ra x y \/
                       E x wa /\ ~(E y wa) \/
                       ~(E x wa) /\ ~(E y wa) /\
                       elnewlt D E om hf ho wa Ra x y)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
    `ho:A`; `a:A`; `ra:A`; `wa:A`; `Ra:A`; `ya:A`] ELWOU_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "mem") THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o CONJUNCT2 o GEN_REWRITE_RULE I
                [erel]) THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` (REPEAT_TCL CONJUNCTS_THEN
    ASSUME_TAC)) THEN
  USE_THEN "mem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
    (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`;
    `x:A`; `y:A`; `p:A`] EOPAIR_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  FIRST_X_ASSUM(MP_TAC o check (is_disj o concl)) THEN
  STRIP_TAC THENL
   [DISJ1_TAC THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) Ra x y` ASSUME_TAC THENL
     [REWRITE_TAC[erel] THEN ASM_REWRITE_TAC[] THEN EXISTS_TAC `p:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
      `x:A`; `y:A`] RA_DROP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@c rc. h15 h16 h17 h18 +" THEN
    REWRITE_TAC[erel] THEN
    DISCH_THEN(X_CHOOSE_THEN `p2:A` (REPEAT_TCL CONJUNCTS_THEN
      ASSUME_TAC) o CONJUNCT2 o CONJUNCT2) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `c:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`]
      ELSTAGE_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `yc:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rc:A`;
      `yc:A`] ELWOINVU_NORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN
    DISCH_THEN(MP_TAC o SPEC `p2:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A` (X_CHOOSE_THEN `v':A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:A`; `v':A`;
      `x:A`; `y:A`; `p2:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    SUBGOAL_THEN
     `(E:A->A->bool) x wa /\ (E:A->A->bool) y wa`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "wch" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN
        ASM_REWRITE_TAC[];
        USE_THEN "wch" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`c:A`; `yc:A`] THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `p:A` THEN
    ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[];
    DISJ2_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The empty set is old (in every stage), so new elements are nonempty and   *)
(* have least defining keys; totality, asymmetry and transitivity of the     *)
(* stage-a order from the edge classification, the R_a facts and the         *)
(* elnewlt order theory.                                                     *)
(* ------------------------------------------------------------------------- *)

let EMPTY_IN_STAGE = prove
 (`!D (E:A->A->bool) b yb.
        model D E ZF_AX /\ eordinal D E b /\ yb IN D /\
        elstage D E b yb
        ==> ?e. e IN D /\ eempty D E e /\ E e yb`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?e:A. eempty D (E:A->A->bool) e`
  (X_CHOOSE_TAC `e:A`) THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `yb:A`]
    ELSTAGE_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@w'. h1 h2 +" THEN
  REWRITE_TAC[edef] THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `e:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[edefmem] THEN CONJ_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[eempty];
    DISJ1_TAC THEN ASM_REWRITE_TAC[]]);;

let NEW_NONEMPTY = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !u t. u IN D /\ E u ya /\ ~(E u wa) /\ t IN D /\
                  E t wa
                  ==> ~(eempty D E u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `?b yb. b IN D /\ yb IN D /\ (E:A->A->bool) b a /\
           elstage D E b yb /\ E t yb`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "wch" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `yb:A`]
    EMPTY_IN_STAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(u:A) = e` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EEMPTY_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e wa` ASSUME_TAC THENL
   [USE_THEN "wch" (fun th -> MP_TAC(SPEC `e:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let NEW_KEY = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !u. u IN D /\ E u ya /\ ~(E u wa) /\
                (?t. t IN D /\ E t wa)
                ==> ?c nc rt. elkey D E om hf ho wa Ra u c nc rt`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  X_GEN_TAC `u:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `t:A`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `~(eempty D (E:A->A->bool) u)` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
      `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
      NEW_NONEMPTY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`u:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `edefmem D (E:A->A->bool) wa u` MP_TAC THENL
   [USE_THEN "ych" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[edefmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `vs:A`
    (X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `s0:A`
      (X_CHOOSE_THEN `z0:A` (REPEAT_TCL CONJUNCTS_THEN
        ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
  MATCH_MP_TAC ELKEY_EXISTS THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`;
      `wa:A`] RA_WF) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`vs:A`; `z0:A`; `c0:A`; `s0:A`] THEN
  ASM_REWRITE_TAC[edefby] THEN
  SUBGOAL_THEN `(c0:A) IN D /\ (s0:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let ELWOU_TOTAL_A = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !u u'. u IN D /\ u' IN D /\ E u ya /\ E u' ya /\
                   ~(u = u')
                   ==> erel D E ra u u' \/ erel D E ra u' u`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_EDGE_OLD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "eo") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
