let ELWOU_ASYM_A = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !u u'. u IN D /\ u' IN D /\ erel D E ra u u'
                   ==> ~(erel D E ra u' u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`] ELWOU_EDGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ed") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`]
    RA_ASYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ras") THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_TAC THEN
  USE_THEN "ed" (fun th -> MP_TAC(SPECL [`u:A`; `u':A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "h15 h16 h17 d1" THEN
  USE_THEN "ed" (fun th -> MP_TAC(SPECL [`u':A`; `u:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "h18 h19 h20 d2" THEN
  USE_THEN "d1" MP_TAC THEN STRIP_TAC THENL
   [USE_THEN "d2" MP_TAC THEN STRIP_TAC THENL
     [USE_THEN "ras" (fun th ->
        MP_TAC(SPECL [`u:A`; `u':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    USE_THEN "d2" MP_TAC THEN STRIP_TAC THENL
     [ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]];
    USE_THEN "d2" MP_TAC THEN STRIP_TAC THENL
     [ASM_MESON_TAC[];
      ASM_MESON_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
        `ho:A`; `wa:A`; `Ra:A`; `u:A`; `u':A`] ELNEWLT_ASYM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
