(* ------------------------------------------------------------------------- *)
(* Wellfoundedness of the stage-a order: the code image of an all-new set    *)
(* (replacement along lkey_form), selection of the least-code block, the     *)
(* restriction image, the elnewlt-least element via EHFORD_LEAST and         *)
(* ETLL_OMEGA, and the two-case assembly (least meeting the old part via     *)
(* R_a-wellfoundedness, or all-new via the key order).                       *)
(* ------------------------------------------------------------------------- *)

let HOLDS_LKEY_EX_FORM = prove
 (`!D (E:A->A->bool) vv.
        model D E ZF_AX /\ valuation D vv
        ==> (holds D E vv (?? 20 (?? 21 lkey_form)) <=>
             ?nc rt. nc IN D /\ rt IN D /\
                     elkey D E (vv 18) (vv 19) (vv 17) (vv 1)
                               (vv 12) (vv 9) (vv 4) nc rt)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX] THEN
  SUBGOAL_THEN
   `!nc rt:A. nc IN D /\ rt IN D
      ==> (holds D E ((21 |-> rt) ((20 |-> nc) vv)) lkey_form <=>
           elkey D (E:A->A->bool) (vv 18) (vv 19) (vv 17) (vv 1)
                 (vv 12) (vv 9) (vv 4) nc rt)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(21 |-> (rt:A)) ((20 |-> (nc:A)) vv)`] HOLDS_LKEY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  EQ_TAC THENL
   [INTRO_TAC "@nc. h1 @rt. h2 +" THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]) THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`nc:A`; `rt:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `nc:A` (X_CHOOSE_THEN `rt:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `nc:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `rt:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th])]);;

let NEWZ_CODE_IMAGE = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !z. z IN D /\
                (!t. t IN D /\ E t z ==> E t ya) /\
                (!t. t IN D /\ E t z ==> ~(E t wa)) /\
                (?t. t IN D /\ E t wa)
                ==> ?K. K IN D /\
                        !w. w IN D
                            ==> (E w K <=>
                                 ?u nc rt. u IN D /\ nc IN D /\
                                           rt IN D /\ E u z /\
                                           elkey D E om hf ho wa
                                                 Ra u w nc rt)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`] NEW_KEY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "nk") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `Ra:A`]
    RA_ASYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ras") THEN
  X_GEN_TAC `z:A` THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "zsub") (CONJUNCTS_THEN2 (LABEL_TAC "znew")
      STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
   `v1 = (12 |-> (Ra:A)) ((1 |-> wa) ((17 |-> ho)
            ((19 |-> hf) ((18 |-> om) v0))))` THEN
  SUBGOAL_THEN `valuation D (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(v1:num->A) 18 = om /\ v1 19 = hf /\ v1 17 = ho /\
    v1 1 = wa /\ v1 12 = Ra /\ v1 9 = v0 9 /\ v1 4 = v0 4`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u c:A. u IN D /\ c IN D
      ==> (holds D E ((4 |-> c) ((9 |-> u) v1))
             (?? 20 (?? 21 lkey_form)) <=>
           ?nc rt. nc IN D /\ rt IN D /\
                   elkey D (E:A->A->bool) om hf ho wa Ra u c
                         nc rt)`
  (LABEL_TAC "hk") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (c:A)) ((9 |-> (u:A)) v1)`] HOLDS_LKEY_EX_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 20 (?? 21 lkey_form)`; `9`; `4`; `v1:num->A`; `z:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "nk" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [USE_THEN "zsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
        CONJ_TAC THENL
         [USE_THEN "znew" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]]];
      ALL_TAC] THEN
    INTRO_TAC "@c nc rt. h15" THEN
    SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `c':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?nc' rt'. nc' IN D /\ rt' IN D /\
                elkey D (E:A->A->bool) om hf ho wa Ra u c' nc' rt'`
