let NEWZ_CODE_SELECT = prove
 (`!D (E:A->A->bool) om hf ho wa Ra z c0.
        model D E ZF_AX /\ om IN D /\ hf IN D /\ ho IN D /\
        wa IN D /\ Ra IN D /\ z IN D /\ c0 IN D
        ==> ?z1. z1 IN D /\
                 !w. w IN D
                     ==> (E w z1 <=>
                          E w z /\
                          ?nc rt. nc IN D /\ rt IN D /\
                                  elkey D E om hf ho wa Ra w c0
                                        nc rt)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
   `v2 = (4 |-> (c0:A)) ((12 |-> Ra) ((1 |-> wa) ((17 |-> ho)
            ((19 |-> hf) ((18 |-> om) v0)))))` THEN
  SUBGOAL_THEN `valuation D (v2:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(v2:num->A) 18 = om /\ v2 19 = hf /\ v2 17 = ho /\
    v2 1 = wa /\ v2 12 = Ra /\ v2 4 = c0`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D
      ==> (holds D E ((9 |-> w) v2) (?? 20 (?? 21 lkey_form)) <=>
           ?nc rt. nc IN D /\ rt IN D /\
                   elkey D (E:A->A->bool) om hf ho wa Ra w c0
                         nc rt)`
  (LABEL_TAC "hk") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(9 |-> (w:A)) v2`] HOLDS_LKEY_EX_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
