  EXISTS_TAC `z1:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "sch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "hk" (fun th -> ASM_SIMP_TAC[th]));;

let NEWZ_RT_IMAGE = prove
 (`!D (E:A->A->bool) om hf ho wa Ra z1 c0 nc0.
        model D E ZF_AX /\ om IN D /\ hf IN D /\ ho IN D /\
        wa IN D /\ Ra IN D /\ z1 IN D /\ c0 IN D /\ nc0 IN D /\
        eomega D E om /\ ehford D E om ho /\
        (!x y. x IN D /\ y IN D /\ erel D E Ra x y
               ==> ~(erel D E Ra y x)) /\
        (!u. u IN D /\ E u z1
             ==> ?rt. rt IN D /\
                      elkey D E om hf ho wa Ra u c0 nc0 rt)
        ==> ?RT. RT IN D /\
                 !w. w IN D
