(* ------------------------------------------------------------------------- *)
(* The stage-in-stage and coherence clauses at stage a, the assembled        *)
(* induction step, and the wellordering invariant ELWOU_INVARIANT: in any    *)
(* model of ZF every ordinal stage carries the recursive L-order elwou as a  *)
(* wellordering of L(a) coherent with all earlier stages (by EORDINAL_INDUCT *)
(* on the internalized invariant formula lwoinvu_form).                      *)
(* ------------------------------------------------------------------------- *)

let ELWOU_SIS_A = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !b yb u u'. b IN D /\ yb IN D /\ E b a /\
                        elstage D E b yb /\ u IN D /\ u' IN D /\
                        E u yb /\ E u' ya /\ ~(E u' yb)
                        ==> erel D E ra u u'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_EDGE_OLDNEW) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "eon") THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) u wa` ASSUME_TAC THENL
   [USE_THEN "wch" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_CASES_TAC `(E:A->A->bool) u' wa` THENL
   [SUBGOAL_THEN
     `?c yc. c IN D /\ yc IN D /\ (E:A->A->bool) c a /\
             elstage D E c yc /\ E u' yc`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "wch" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) b /\ eordinal D E c`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b c` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `c:A`;
        `yb:A`; `yc:A`; `u':A`] ELSTAGE_LINEAR) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`]
      ELWOU_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `rc:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rc:A`;
      `yc:A`] ELWOINVU_NORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(CONJUNCT1(CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
        (CONJUNCT2 th))))))) THEN
    DISCH_THEN(MP_TAC o SPECL [`b:A`; `yb:A`; `u:A`; `u':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MATCH_MP_TAC EREL_SUBSET THEN EXISTS_TAC `rc:A` THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `c:A`;
      `ra:A`; `rc:A`] ELWOU_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    USE_THEN "eon" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let ELWOU_COH_A = prove
 (`!D (E:A->A->bool) a om hf ho wa Ra ya ra.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b) /\
        om IN D /\ hf IN D /\ ho IN D /\ wa IN D /\ Ra IN D /\
        ya IN D /\ ra IN D /\
        eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
        elwou D E a ra /\ elstage D E a ya /\
        (!t. t IN D
             ==> (E t wa <=>
                  ?b yb. b IN D /\ yb IN D /\ E b a /\
                         elstage D E b yb /\ E t yb)) /\
        (!q. q IN D
             ==> (E q Ra <=>
                  ?b rb. b IN D /\ rb IN D /\ E b a /\
                         elwou D E b rb /\ E q rb)) /\
        (!y. y IN D ==> (E y ya <=> edefmem D E wa y))
        ==> !b rb yb. b IN D /\ rb IN D /\ yb IN D /\ E b a /\
                      elwou D E b rb /\ elstage D E b yb
                      ==> !p. p IN D
                              ==> (E p rb <=>
                                   E p ra /\
                                   ?u u'. u IN D /\ u' IN D /\
                                          E u yb /\ E u' yb /\
                                          eopair D E u u' p)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 ih h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14 wch rch
             ych" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`;
    `ho:A`; `a:A`; `ra:A`; `wa:A`; `Ra:A`; `ya:A`] ELWOU_MEMBER) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "mem") THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `rb:A`;
    `yb:A`] ELWOINVU_NORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1) THEN
  DISCH_THEN(LABEL_TAC "ps1") THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
        `ra:A`; `rb:A`] ELWOU_MONO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      USE_THEN "ps1" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
        (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `u:A`
      (X_CHOOSE_THEN `u':A` (REPEAT_TCL CONJUNCTS_THEN
        ASSUME_TAC)))) THEN
    SUBGOAL_THEN
     `(E:A->A->bool) u wa /\ (E:A->A->bool) u' wa`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "wch" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN
        ASM_REWRITE_TAC[];
        USE_THEN "wch" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MAP_EVERY EXISTS_TAC [`b:A`; `yb:A`] THEN
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    USE_THEN "mem" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A` (X_CHOOSE_THEN `v':A`
      (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:A`; `v':A`;
      `u:A`; `u':A`; `p:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    FIRST_X_ASSUM(MP_TAC o check (is_disj o concl)) THEN
    STRIP_TAC THENL
     [SUBGOAL_THEN
       `?c rc. c IN D /\ rc IN D /\ (E:A->A->bool) c a /\
               elwou D E c rc /\ E p rc`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `b:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `c:A`;
          `rb:A`; `rc:A`] ELWOU_MONO) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        SUBGOAL_THEN `(rc:A) = rb` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`;
            `rc:A`; `rb:A`] ELWOU_UNIQUE) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
            ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC;
          ALL_TAC] THEN
        ASM_REWRITE_TAC[];
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`]
          ELSTAGE_EXISTS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `yc:A` STRIP_ASSUME_TAC) THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rc:A`;
          `yc:A`] ELWOINVU_NORM) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN USE_THEN "ih" MATCH_MP_TAC THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        DISCH_THEN(fun th ->
          MP_TAC(CONJUNCT1(CONJUNCT2(CONJUNCT2(CONJUNCT2
            (CONJUNCT2 th)))))) THEN
        DISCH_THEN(MP_TAC o SPECL [`b:A`; `rb:A`; `yb:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN
        MAP_EVERY EXISTS_TAC [`u:A`; `u':A`] THEN
        ASM_REWRITE_TAC[]];
      ASM_MESON_TAC[];
      ASM_MESON_TAC[]]]);;

let ELWOU_INVARIANT_STEP = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a /\
        (!b. b IN D /\ E b a ==> elwoinvu D E b)
        ==> elwoinvu D E a`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ELWOU_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `om:A` (X_CHOOSE_THEN `hf:A`
    (X_CHOOSE_THEN `ho:A` (X_CHOOSE_THEN `wa:A`
      (X_CHOOSE_THEN `Ra:A` (X_CHOOSE_THEN `ya:A`
        (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_PAIRSHAPE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_TRANS_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_ASYM_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_TOTAL_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_COH_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_SIS_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `om:A`;
    `hf:A`; `ho:A`; `wa:A`; `Ra:A`; `ya:A`; `ra:A`]
    ELWOU_WF_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  REWRITE_TAC[elwoinvu] THEN
  MAP_EVERY EXISTS_TAC [`ra:A`; `ya:A`] THEN
  ASM_REWRITE_TAC[]);;

let ELWOU_INVARIANT = prove
 (`!D (E:A->A->bool) a.
        model D E ZF_AX /\ eordinal D E a ==> elwoinvu D E a`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `lwoinvu_form`; `0`;
    `v0:num->A`] EORDINAL_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `a':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (a':A)) v0)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD; EORDINAL_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (a':A)) v0`] HOLDS_LWOINVU_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`]
      ELWOU_INVARIANT_STEP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `b:A` o
        check (fun th -> is_forall(concl th) &&
          can (find_term (fun tm ->
            is_const tm && fst(dest_const tm) = "holds"))
          (concl th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (b:A)) v0)` ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (b:A)) v0`] HOLDS_LWOINVU_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (a:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD; EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (a:A)) v0`]
    HOLDS_LWOINVU_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD]);;

(* ------------------------------------------------------------------------- *)
(* The constructible class satisfies AC.  The choice-set selector formula    *)
(* (the ra-least element of a member of the family), the semantic choice     *)
(* theorem for any model of ZF + V=L (wellorder the stage containing the     *)
(* family by ELWOU_INVARIANT and pick least elements by separation), the     *)
(* object-level choice axiom in Zermelo's disjoint-family form, and: every   *)
(* model of ZF has a submodel over the same membership relation satisfying   *)
(* ZF + AC, namely its constructible class.                                  *)
(* ------------------------------------------------------------------------- *)

let chsel_form = new_definition
  `chsel_form =
     ?? 5 ((5 %% 1) &&
           ((0 %% 5) &&
            !! 6 (((6 %% 5) && Not(Eq 6 0)) --> rel_form 2 0 6)))`;;

let HOLDS_CHSEL_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v chsel_form <=>
             ?y. y IN D /\ E y (v 1) /\ E (v 0) y /\
                 !z'. z' IN D /\ E z' y /\ ~(z' = v 0)
                      ==> erel D E (v 2) (v 0) z')`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y z':A. y IN D /\ z' IN D
      ==> (holds D E ((6 |-> z') ((5 |-> y) v))
             (rel_form 2 0 6) <=>
           erel D (E:A->A->bool) (v 2) (v 0) z')`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (z':A)) ((5 |-> (y:A)) v)`; `2`; `0`; `6`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[chsel_form; HOLDS_EX; HOLDS_AND; HOLDS_NOT;
              holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  EQ_TAC THENL
   [INTRO_TAC "@y. h1 h2 h3 q4" THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z':A` THEN STRIP_TAC THEN
    USE_THEN "q4" (fun th -> MP_TAC(SPEC `z':A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]) THEN
      USE_THEN "q4" (fun th -> MP_TAC(SPEC `z':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "r1" (fun th ->
        MP_TAC(SPECL [`y:A`; `z':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun eq ->
        DISCH_THEN(fun h -> ACCEPT_TAC(EQ_MP eq h)));
    INTRO_TAC "@y. h4 h5 h6 q4" THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z':A` THEN DISCH_TAC THEN STRIP_TAC THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]) THEN
    USE_THEN "q4" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

let ELMEM_CHOICE = prove
 (`!N (E:A->A->bool) x.
        model N E ZF_AX /\ (!u. u IN N ==> elmem N E u) /\
        x IN N /\
        (!y. y IN N /\ E y x ==> ?z. z IN N /\ E z y) /\
        (!y y'. y IN N /\ y' IN N /\ E y x /\ E y' x /\
                ~(y = y')
                ==> ~(?z. z IN N /\ E z y /\ E z y'))
        ==> ?c. c IN N /\
                !y. y IN N /\ E y x
                    ==> ?z. z IN N /\ E z y /\ E z c /\
                            !z'. z' IN N /\ E z' y /\ E z' c
                                 ==> z' = z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 vl h2 ne dj" THEN
  SUBGOAL_THEN `elmem N (E:A->A->bool) x` MP_TAC THENL
   [USE_THEN "vl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`]
    ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`]
    ELWOU_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`;
    `ya:A`] ELWOINVU_NORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    LABEL_TAC "c3" (CONJUNCT1(CONJUNCT2(CONJUNCT2 th))) THEN
    LABEL_TAC "c7" (CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
      (CONJUNCT2(CONJUNCT2 th))))))) THEN
  SUBGOAL_THEN `etransitive N (E:A->A->bool) ya` MP_TAC THENL
   [MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
      ELSTAGE_TRANSITIVE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[etransitive; esubset] THEN
  DISCH_THEN(LABEL_TAC "ytr") THEN
  SUBGOAL_THEN
   `!y:A. y IN N /\ (E:A->A->bool) y x ==> E y ya`
  (LABEL_TAC "yin") THENL
   [X_GEN_TAC `y:A` THEN STRIP_TAC THEN
    USE_THEN "ytr" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y z:A. y IN N /\ (E:A->A->bool) y x /\ z IN N /\ E z y ==> E z ya`
  (LABEL_TAC "zin") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) y ya` ASSUME_TAC THENL
     [USE_THEN "yin" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "ytr" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation N v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (2 |-> (ra:A)) ((1 |-> x) v0)` THEN
  SUBGOAL_THEN `valuation N (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 1 = x /\ v1 2 = ra`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN N
      ==> (holds N E ((0 |-> w) v1) chsel_form <=>
           ?y. y IN N /\ (E:A->A->bool) y x /\ E w y /\
               !z'. z' IN N /\ E z' y /\ ~(z' = w)
                    ==> erel N E ra w z')`
  (LABEL_TAC "hc") THENL
