      USE_THEN "ne" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  INTRO_TAC "@m. h3 h4 mlt" THEN
  SUBGOAL_THEN `(E:A->A->bool) m ya` ASSUME_TAC THENL
