let choice_ax = new_definition
  `choice_ax =
      !! 0 (((!! 1 ((1 %% 0) --> ?? 2 (2 %% 1))) &&
             (!! 1 (!! 2 (((1 %% 0) && ((2 %% 0) && Not(Eq 1 2)))
                          --> Not(?? 3 ((3 %% 1) && (3 %% 2))))))) -->
            ?? 4 (!! 1 ((1 %% 0) -->
                        ?? 2 ((2 %% 1) && ((2 %% 4) &&
                              !! 3 (((3 %% 1) && (3 %% 4)) -->
                                    Eq 3 2))))))`;;

let HOLDS_CHOICE_AX_INTRO = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v /\
        (!x. x IN D /\
             (!y. y IN D /\ E y x ==> ?z. z IN D /\ E z y) /\
             (!y y'. y IN D /\ y' IN D /\ E y x /\ E y' x /\
                     ~(y = y')
                     ==> ~(?z. z IN D /\ E z y /\ E z y'))
             ==> ?c. c IN D /\
                     !y. y IN D /\ E y x
                         ==> ?z. z IN D /\ E z y /\ E z c /\
                                 !z'. z' IN D /\ E z' y /\
                                      E z' c
                                      ==> z' = z)
        ==> holds D E v choice_ax`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    ASSUME_TAC (LABEL_TAC "sc"))) THEN
  REWRITE_TAC[choice_ax; HOLDS_EX; HOLDS_AND; HOLDS_NOT;
              holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "h1") (LABEL_TAC "h2")) THEN
  USE_THEN "sc" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `y:A` THEN STRIP_TAC THEN
      USE_THEN "h1" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      X_GEN_TAC `y:A` THEN X_GEN_TAC `y':A` THEN STRIP_TAC THEN
      USE_THEN "h2" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `y':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "cp"))) THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  USE_THEN "cp" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@z. h3 h4 h5 uq" THEN
  EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z':A` THEN DISCH_TAC THEN STRIP_TAC THEN
  USE_THEN "uq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let MODEL_VL_CHOICE = prove
 (`!N (E:A->A->bool).
        model N E ZF_AX /\ (!u. u IN N ==> elmem N E u)
        ==> model N E (choice_ax INSERT ZF_AX)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!x. x IN N /\
        (!y. y IN N /\ (E:A->A->bool) y x
             ==> ?z. z IN N /\ E z y) /\
        (!y y'. y IN N /\ y' IN N /\ E y x /\ E y' x /\
                ~(y = y')
                ==> ~(?z. z IN N /\ E z y /\ E z y'))
        ==> ?c. c IN N /\
                !y. y IN N /\ E y x
                    ==> ?z. z IN N /\ E z y /\ E z c /\
                            !z'. z' IN N /\ E z' y /\ E z' c
                                 ==> z' = z`
  (LABEL_TAC "scp") THENL
   [X_GEN_TAC `x:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `x:A`]
      ELMEM_CHOICE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN CONJ_TAC THENL
   [ASM_MESON_TAC[MODEL_NONEMPTY]; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THENL
   [FIRST_X_ASSUM SUBST1_TAC THEN
    MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `v:num->A`]
      HOLDS_CHOICE_AX_INTRO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ASM_MESON_TAC[model; satisfies]]);;

let LCLASS_MODEL_VL = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> model (lclass D E) E ZF_AX /\
            !u. u IN lclass D E ==> elmem (lclass D E) E u`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN ASM_SIMP_TAC[MODEL_LCLASS] THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `(u:A) IN lclass (lclass D E) E` MP_TAC THENL
   [ASM_MESON_TAC[LCLASS_IDEMPOTENT]; SIMP_TAC[IN_LCLASS]]);;

let ZF_MODEL_AC_MODEL = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> ?D'. D' SUBSET D /\
                 model D' E (choice_ax INSERT ZF_AX)`,
  REPEAT STRIP_TAC THEN EXISTS_TAC `lclass D (E:A->A->bool)` THEN
  ASM_SIMP_TAC[LCLASS_SUBSET; MODEL_VL_CHOICE; LCLASS_MODEL_VL]);;

(* ------------------------------------------------------------------------- *)
(* Toward condensation and cardinal arithmetic: Burali-Forti (no set of all  *)
(* ordinals), and the enumeration step for the ordertype construction: the   *)
(* r-least element of x not yet in the range of the attempt, or x itself as  *)
(* a dummy once exhausted (x IN x being impossible).                         *)
(* ------------------------------------------------------------------------- *)

let EORDINALS_NOSET = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> ~(?s. s IN D /\
                  !a. a IN D /\ eordinal D E a ==> E a s)`,
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "alls"))) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`ordinal_form 0`; `0`; `v0:num->A`; `s:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s0:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w s0 <=> eordinal D E w)`
  (LABEL_TAC "s0ch") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "sch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (w:A)) v0`; `0`] HOLDS_ORDINAL_FORM) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN EQ_TAC THENL
     [DISCH_THEN(MP_TAC o CONJUNCT2) THEN DISCH_THEN ACCEPT_TAC;
      DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "alls" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) s0` ASSUME_TAC THENL
   [REWRITE_TAC[eordinal] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[etransitive] THEN X_GEN_TAC `y:A` THEN
      STRIP_TAC THEN REWRITE_TAC[esubset] THEN
      X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) y` ASSUME_TAC THENL
       [USE_THEN "s0ch" (fun th -> MP_TAC(SPEC `y:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "s0ch" (fun th ->
        MP_TAC(SPEC `w:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `y:A`; `w:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      REWRITE_TAC[elinear] THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `w:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [USE_THEN "s0ch" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
          ASM_REWRITE_TAC[];
          USE_THEN "s0ch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s0 s0` ASSUME_TAC THENL
   [USE_THEN "s0ch" (fun th -> MP_TAC(SPEC `s0:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s0:A`] E_IRREFL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let eenumstep = new_definition
  `eenumstep D (E:A->A->bool) x r g w <=>
     (?t. t IN D /\ E t x /\
          ~(?k. k IN D /\ eapply D E g k t) /\
          (!t'. t' IN D /\ E t' x /\
                ~(?k. k IN D /\ eapply D E g k t') /\ ~(t' = t)
                ==> erel D E r t t') /\
          w = t) \/
     ~(?t. t IN D /\ E t x /\
           ~(?k. k IN D /\ eapply D E g k t) /\
           (!t'. t' IN D /\ E t' x /\
                 ~(?k. k IN D /\ eapply D E g k t') /\ ~(t' = t)
                 ==> erel D E r t t')) /\
     w = x`;;

let enumstep_form = new_definition
  `enumstep_form =
     (?? 6 ((6 %% 4) &&
            (Not(?? 8 (apply_form 0 8 6)) &&
             ((!! 7 (((7 %% 4) &&
                      (Not(?? 8 (apply_form 0 8 7)) &&
                       Not(Eq 7 6)))
                     --> rel_form 5 6 7)) &&
              Eq 1 6)))) ||
     ((Not(?? 6 ((6 %% 4) &&
                 (Not(?? 8 (apply_form 0 8 6)) &&
                  !! 7 (((7 %% 4) &&
                         (Not(?? 8 (apply_form 0 8 7)) &&
                          Not(Eq 7 6)))
                        --> rel_form 5 6 7))))) &&
      Eq 1 4)`;;

(* ------------------------------------------------------------------------- *)
(* The ordinal enumeration of an internal wellorder: HOLDS characterization  *)
(* of the enumeration step (slots 0=attempt, 1=value, 4=carrier, 5=order),   *)
(* functionality under asymmetry and unconditional totality of the step,     *)
(* the enumeration eoenum by ordinal recursion, and its existence and        *)
(* valuation-independent uniqueness.                                         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_ENUMSTEP_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v enumstep_form <=>
             eenumstep D E (v 4) (v 5) (v 0) (v 1))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t k:A. t IN D /\ k IN D
      ==> (holds D E ((8 |-> k) ((6 |-> t) v)) (apply_form 0 8 6) <=>
           eapply D (E:A->A->bool) (v 0) k t)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (k:A)) ((6 |-> (t:A)) v)`; `0`; `8`; `6`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t t' k:A. t IN D /\ t' IN D /\ k IN D
      ==> (holds D E ((8 |-> k) ((7 |-> t') ((6 |-> t) v)))
             (apply_form 0 8 7) <=>
           eapply D (E:A->A->bool) (v 0) k t')`
  (LABEL_TAC "r2") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(8 |-> (k:A)) ((7 |-> (t':A)) ((6 |-> (t:A)) v))`;
      `0`; `8`; `7`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t t':A. t IN D /\ t' IN D
      ==> (holds D E ((7 |-> t') ((6 |-> t) v))
             (rel_form 5 6 7) <=>
           erel D (E:A->A->bool) (v 5) t t')`
  (LABEL_TAC "r3") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (t':A)) ((6 |-> (t:A)) v)`; `5`; `6`; `7`]
      HOLDS_REL_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN D
      ==> (((E:A->A->bool) t (v 4) /\
            ~(?k. k IN D /\
                  holds D E ((8 |-> k) ((6 |-> t) v))
                        (apply_form 0 8 6)) /\
            (!t'. t' IN D
                  ==> E t' (v 4) /\
                      ~(?k. k IN D /\
                            holds D E
                              ((8 |-> k) ((7 |-> t') ((6 |-> t) v)))
                              (apply_form 0 8 7)) /\
                      ~(t' = t)
                  ==> holds D E ((7 |-> t') ((6 |-> t) v))
                            (rel_form 5 6 7))) <=>
           (E t (v 4) /\
            ~(?k. k IN D /\ eapply D E (v 0) k t) /\
            (!t'. t' IN D /\ E t' (v 4) /\
                  ~(?k. k IN D /\ eapply D E (v 0) k t') /\
                  ~(t' = t)
                  ==> erel D E (v 5) t t')))`
  (LABEL_TAC "core") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') /\ (q <=> q')
      ==> ((a /\ p /\ q) <=> (a /\ p' /\ q'))`) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(MESON[]
       `((?k:A. P k) <=> (?k:A. Q k))
        ==> (~(?k:A. P k) <=> ~(?k:A. Q k))`) THEN
      MATCH_MP_TAC(MESON[]
       `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
      X_GEN_TAC `k:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
      DISCH_TAC THEN
      USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]);
      MATCH_MP_TAC(MESON[]
       `(!t':A. P t' <=> Q t')
        ==> ((!t':A. P t') <=> (!t':A. Q t'))`) THEN
      X_GEN_TAC `t':A` THEN REWRITE_TAC[IMP_CONJ] THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(TAUT
       `(a <=> a') /\ (a' ==> (p <=> q))
        ==> ((a ==> p) <=> (a' ==> q))`) THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC(MESON[]
         `((?k:A. P k) <=> (?k:A. Q k))
          ==> (~(?k:A. P k) <=> ~(?k:A. Q k))`) THEN
        MATCH_MP_TAC(MESON[]
         `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
        X_GEN_TAC `k:A` THEN
        MATCH_MP_TAC(TAUT
         `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
        DISCH_TAC THEN
        USE_THEN "r2" (fun th -> ASM_SIMP_TAC[th]);
        DISCH_TAC THEN
        MATCH_MP_TAC(TAUT
         `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
        DISCH_TAC THEN
        USE_THEN "r3" (fun th -> ASM_SIMP_TAC[th])]];
    ALL_TAC] THEN
  REWRITE_TAC[enumstep_form; eenumstep; HOLDS_OR; HOLDS_EX;
              HOLDS_AND; HOLDS_NOT; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT
   `(p <=> p') /\ (q <=> q')
    ==> ((p \/ q' /\ w) <=> (p' \/ q /\ w))`) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `((x /\ y /\ z) <=> (x' /\ y' /\ z'))
      ==> ((x /\ y /\ z /\ w) <=> (x' /\ y' /\ z' /\ w))`) THEN
    USE_THEN "core" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MATCH_MP_TAC(MESON[]
     `((?t:A. P t) <=> (?t:A. Q t))
      ==> (~(?t:A. P t) <=> ~(?t:A. Q t))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "core" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(GSYM th) ORELSE MP_TAC th) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

let EENUMSTEP_QFUN = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u))
        ==> !g w w'. g IN D /\ w IN D /\ w' IN D /\
                     eenumstep D E x r g w /\
                     eenumstep D E x r g w'
                     ==> w = w'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym" THEN
  REPEAT GEN_TAC THEN
  INTRO_TAC "h4 h5 h6 + +" THEN
  REWRITE_TAC[eenumstep] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (X_CHOOSE_THEN `t2:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "n2")
        (CONJUNCTS_THEN2 (LABEL_TAC "l2") SUBST_ALL_TAC)))))
    (CONJUNCTS_THEN2 (LABEL_TAC "no2") SUBST_ALL_TAC)) THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (X_CHOOSE_THEN `t1:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "n1")
        (CONJUNCTS_THEN2 (LABEL_TAC "l1") SUBST_ALL_TAC)))))
    (CONJUNCTS_THEN2 (LABEL_TAC "no1") SUBST_ALL_TAC)) THENL
   [ASM_CASES_TAC `(t1:A) = t2` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) r t1 t2` ASSUME_TAC THENL
     [USE_THEN "l1" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> MP_TAC(SYM th)) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `erel D (E:A->A->bool) r t2 t1` ASSUME_TAC THENL
     [USE_THEN "l2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "asym" (fun th ->
      MP_TAC(SPECL [`t1:A`; `t2:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    USE_THEN "no1" (fun th -> MP_TAC th) THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `t2:A`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM NOT_EXISTS_THM] THEN ASM_REWRITE_TAC[];
    USE_THEN "no2" (fun th -> MP_TAC th) THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `t1:A`) THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[GSYM NOT_EXISTS_THM] THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[]]);;

let EENUMSTEP_QTOTAL = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D
        ==> !g. g IN D
                ==> ?w. w IN D /\ eenumstep D E x r g w`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eenumstep] THEN
  ASM_CASES_TAC
   `?t. t IN D /\ (E:A->A->bool) t x /\
        ~(?k. k IN D /\ eapply D E g k t) /\
        (!t'. t' IN D /\ E t' x /\
              ~(?k. k IN D /\ eapply D E g k t') /\ ~(t' = t)
              ==> erel D E r t t')` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN DISJ1_TAC THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
    EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]]);;

let FV_ENUMSTEP_FORM = prove
 (`FV enumstep_form SUBSET {0, 1, 4, 5}`,
  REWRITE_TAC[enumstep_form; Or_DEF; Not_DEF; And_DEF; Iff_DEF;
              Exists_DEF; FV; FV_APPLY_FORM; FV_REL_FORM] THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT;
              NOT_IN_EMPTY] THEN
  GEN_TAC THEN ARITH_TAC);;

let eoenum = new_definition
  `eoenum D (E:A->A->bool) x r a y <=>
     ?v. valuation D v /\ v 4 = x /\ v 5 = r /\
         erec D E enumstep_form v a y`;;

let EENUMSTEP_HOLDS_OBLIG = prove
 (`!D (E:A->A->bool) x r v.
        model D E ZF_AX /\ valuation D v /\ v 4 = x /\ v 5 = r /\
        x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u))
        ==> (!g w w'. g IN D /\ w IN D /\ w' IN D /\
                      holds D E ((1 |-> w) ((0 |-> g) v))
                            enumstep_form /\
                      holds D E ((1 |-> w') ((0 |-> g) v))
                            enumstep_form
                      ==> w = w') /\
            (!g. g IN D
                 ==> ?w. w IN D /\
                         holds D E ((1 |-> w) ((0 |-> g) v))
                               enumstep_form)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!g w:A. g IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> g) v)) enumstep_form <=>
           eenumstep D (E:A->A->bool) x r g w)`
  (LABEL_TAC "hs") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (g:A)) v)`] HOLDS_ENUMSTEP_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
      EENUMSTEP_QFUN) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`g:A`; `w:A`; `w':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
      USE_THEN "hs" (fun th -> ASM_SIMP_TAC[GSYM th]);
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `g:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
      EENUMSTEP_QTOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `g:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hs" (fun th -> ASM_SIMP_TAC[th])]);;

let EOENUM_EXISTS = prove
 (`!D (E:A->A->bool) x r a.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a
        ==> ?y. y IN D /\ eoenum D E x r a y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (5 |-> (r:A)) ((4 |-> x) v0)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 4 = x /\ v1 5 = r`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `v1:num->A`] EENUMSTEP_HOLDS_OBLIG) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qf") (LABEL_TAC "qt")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `enumstep_form`;
    `v1:num->A`; `a:A`] EREC_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "qf" ACCEPT_TAC; USE_THEN "qt" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[eoenum] THEN
  EXISTS_TAC `v1:num->A` THEN ASM_REWRITE_TAC[]);;

let EOENUM_UNIQUE = prove
 (`!D (E:A->A->bool) x r a y y'.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        a IN D /\ y IN D /\ y' IN D /\
        eoenum D E x r a y /\ eoenum D E x r a y'
        ==> y = y'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym h4 h5 h6 + +" THEN
  REWRITE_TAC[eoenum] THEN
  INTRO_TAC "@v'. h7 h8 h9 h10" THEN
  INTRO_TAC "@v. h11 h12 h13 h14" THEN
  SUBGOAL_THEN `erec D (E:A->A->bool) enumstep_form v a y'`
  ASSUME_TAC THENL
   [SUBGOAL_THEN
     `erec D (E:A->A->bool) enumstep_form v' a y' <=>
      erec D E enumstep_form v a y'`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC FV_ENUMSTEP_FORM THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `v:num->A`] EENUMSTEP_HOLDS_OBLIG) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qf") (LABEL_TAC "qt")) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `enumstep_form`;
    `v:num->A`; `a:A`; `y:A`; `y':A`] EREC_UNIQUE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "qf" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* The recursion equation for the enumeration (the value is the enumeration  *)
(* step applied to the graph of earlier values), the value dichotomy (the    *)
(* dummy x once exhausted, else the r-least not-yet-enumerated element of    *)
(* x), and injectivity below exhaustion.                                     *)
(* ------------------------------------------------------------------------- *)

let EOENUM_CHAR = prove
 (`!D (E:A->A->bool) x r a y.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a /\ y IN D /\ eoenum D E x r a y
        ==> ?rr. rr IN D /\
                 (!w. w IN D
                      ==> (E w rr <=>
                           ?b z. b IN D /\ z IN D /\ E b a /\
                                 eoenum D E x r b z /\
                                 eopair D E b z w)) /\
                 eenumstep D E x r rr y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym h4 h5 +" THEN
  REWRITE_TAC[eoenum] THEN
  INTRO_TAC "@v. h6 h7 h8 h9" THEN
  SUBGOAL_THEN
   `!b z:A. b IN D /\ z IN D
      ==> (erec D (E:A->A->bool) enumstep_form v b z <=>
           eoenum D E x r b z)`
  (LABEL_TAC "tr") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN REWRITE_TAC[eoenum] THEN
      EXISTS_TAC `v:num->A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[eoenum] THEN
      INTRO_TAC "@v'. h10 h11 h12 h13" THEN
      SUBGOAL_THEN
       `erec D (E:A->A->bool) enumstep_form v' b z <=>
        erec D E enumstep_form v b z`
      (fun th -> ASM_MESON_TAC[th]) THEN
      MATCH_MP_TAC EREC_VALUATION THEN
      X_GEN_TAC `m:num` THEN STRIP_TAC THEN
      MP_TAC FV_ENUMSTEP_FORM THEN REWRITE_TAC[SUBSET] THEN
      DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `v:num->A`] EENUMSTEP_HOLDS_OBLIG) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "qf") (LABEL_TAC "qt")) THEN
  REWRITE_TAC[GSYM eoenum] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `enumstep_form`;
    `v:num->A`; `a:A`] ERECRES_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "qf" ACCEPT_TAC; USE_THEN "qt" ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `rr:A`) THEN
  SUBGOAL_THEN `(rr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  EXISTS_TAC `rr:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [erecres] o
      check (fun th -> can (find_term (fun tm -> is_const tm &&
        fst(dest_const tm) = "erecres")) (concl th))) THEN
    DISCH_THEN(MP_TAC o SPEC `w:A` o CONJUNCT2) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "tr" (fun th -> ASM_SIMP_TAC[GSYM th]);
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "tr" (fun th -> ASM_SIMP_TAC[th])];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `enumstep_form`;
    `v:num->A`; `a:A`; `y:A`; `rr:A`] EREC_EQUATION) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "qf" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(1 |-> (y:A)) ((0 |-> (rr:A)) v)`] HOLDS_ENUMSTEP_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[]);;

let EOENUM_VAL = prove
 (`!D (E:A->A->bool) x r a y.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a /\ y IN D /\ eoenum D E x r a y
        ==> y = x \/
            E y x /\
            (!b. b IN D /\ E b a
                 ==> ~(eoenum D E x r b y)) /\
            (!t'. t' IN D /\ E t' x /\
                  (!b. b IN D /\ E b a
                       ==> ~(eoenum D E x r b t')) /\
                  ~(t' = y)
                  ==> erel D E r y t')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `a:A`;
    `y:A`] EOENUM_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@rr. h1 rch +" THEN
  REWRITE_TAC[eenumstep] THEN
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D
      ==> (eapply D (E:A->A->bool) rr k t <=>
           E k a /\ eoenum D E x r k t)`
  (LABEL_TAC "apch") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?b z. b IN D /\ z IN D /\ (E:A->A->bool) b a /\
              eoenum D E x r b z /\ eopair D E b z p`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`;
        `k:A`; `t:A`; `p:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM)
        (SUBST_ALL_TAC o SYM)) THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "rch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`k:A`; `t:A`] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  STRIP_TAC THENL
   [DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `b:A` THEN STRIP_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) rr b t` MP_TAC THENL
       [USE_THEN "apch" (fun th -> ASM_SIMP_TAC[th]);
        ALL_TAC] THEN
      STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `b:A` o
        REWRITE_RULE[NOT_EXISTS_THM] o check (fun th ->
          is_neg(concl th) &&
          can (find_term (fun tm -> is_const tm &&
            fst(dest_const tm) = "eapply")) (concl th) &&
          is_exists(dest_neg(concl th)))) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `t':A` THEN STRIP_TAC THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "erel")) (concl th) &&
        can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "eapply")) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `k:A` THEN
      DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o check (is_conj o concl)) THEN
      STRIP_TAC THEN
      USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `t':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `k:A` o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "eoenum")) (concl th))) THEN
      ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN ASM_REWRITE_TAC[]]);;

let EOENUM_INJ = prove
 (`!D (E:A->A->bool) x r a a' y.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a' /\ a IN D /\ E a a' /\ y IN D /\
        eoenum D E x r a' y /\ ~(y = x)
        ==> ~(eoenum D E x r a y)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `a':A`; `y:A`] EOENUM_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o CONJUNCT1 o CONJUNCT2) THEN
  DISCH_THEN(MP_TAC o SPEC `a:A`) THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Internalization of the enumeration (recapp6_form wrapper around the N = 6 *)
(* recursion form, parameters at slots 4, 5) and the exhaustion theorem:     *)
(* the enumeration along any asymmetric relation reaches the dummy x at some *)
(* ordinal, else its ordinal inverse over x collects the class of all        *)
(* ordinals into a set (replacement), contradicting Burali-Forti.            *)
(* ------------------------------------------------------------------------- *)

let recapp6_form = new_definition
  `recapp6_form q i j = !! 6 (!! 7 ((Eq 6 i && Eq 7 j) --> q))`;;

let HOLDS_RECAPP6_FORM = prove
 (`!D (E:A->A->bool) v q i j.
        valuation D v /\ ~(i = 6) /\ ~(i = 7) /\ ~(j = 6) /\
        ~(j = 7)
        ==> (holds D E v (recapp6_form q i j) <=>
             holds D E ((7 |-> v j) ((6 |-> v i) v)) q)`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[recapp6_form; holds; HOLDS_AND] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(6 = 7)`] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `(v:num->A) i`) THEN ASM_SIMP_TAC[] THEN
    DISCH_THEN(MP_TAC o SPEC `(v:num->A) j`) THEN ASM_SIMP_TAC[];
    MESON_TAC[]]);;

let FVLT_ENUMSTEP_FORM = prove
 (`!m. m IN FV enumstep_form ==> m < 6`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC FV_ENUMSTEP_FORM THEN REWRITE_TAC[SUBSET] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN ARITH_TAC);;

let EOENUM_EREC = prove
 (`!D (E:A->A->bool) a y v.
        model D E ZF_AX /\ valuation D v
        ==> (eoenum D E (v 4) (v 5) a y <=>
             erec D E enumstep_form v a y)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eoenum] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `v':num->A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `erec D (E:A->A->bool) enumstep_form v' a y <=>
      erec D E enumstep_form v a y`
    (fun th -> ASM_MESON_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC FV_ENUMSTEP_FORM THEN REWRITE_TAC[SUBSET] THEN
    DISCH_THEN(MP_TAC o SPEC `m:num`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[IN_INSERT; NOT_IN_EMPTY] THEN STRIP_TAC THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[];
    DISCH_TAC THEN EXISTS_TAC `v:num->A` THEN
    ASM_REWRITE_TAC[]]);;

let enumat_form = new_definition
  `enumat_form i j = recapp6_form (rec_form enumstep_form 6) i j`;;

let HOLDS_ENUMAT_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v /\
        ~(i = 6) /\ ~(i = 7) /\ ~(j = 6) /\ ~(j = 7)
        ==> (holds D E v (enumat_form i j) <=>
             eoenum D E (v 4) (v 5) (v i) (v j))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[enumat_form] THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `rec_form enumstep_form 6`; `i:num`; `j:num`]
    HOLDS_RECAPP6_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN
   `valuation D ((7 |-> (v:num->A) j) ((6 |-> v i) v))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
    `enumstep_form`; `6`; `(v:num->A) i`; `(v:num->A) j`]
    HOLDS_REC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ARITH_TAC; ACCEPT_TAC FVLT_ENUMSTEP_FORM];
    ALL_TAC] THEN
  DISCH_THEN(fun th ->
    REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(v:num->A) i`;
    `(v:num->A) j`; `v:num->A`] EOENUM_EREC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let EOENUM_FUNCTIONAL = prove
 (`!D (E:A->A->bool) x r t.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        t IN D /\ E t x
        ==> ?w. w IN D /\
                !w'. w' IN D /\ eordinal D E w' /\
                     eoenum D E x r w' t
                     ==> w' = w`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym h4 h5" THEN
  SUBGOAL_THEN `~((t:A) = x)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[E_IRREFL];
    ALL_TAC] THEN
  ASM_CASES_TAC
   `?d. d IN D /\ eordinal D (E:A->A->bool) d /\
        eoenum D E x r d t` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `d:A` STRIP_ASSUME_TAC o
      check (is_exists o concl)) THEN
    EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `d':A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d':A`; `d:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
        `d':A`; `d:A`; `t:A`] EOENUM_INJ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
        `d:A`; `d':A`; `t:A`] EOENUM_INJ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
        ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `d':A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `d':A` o
      REWRITE_RULE[NOT_EXISTS_THM] o check (fun th ->
        is_neg(concl th) && is_exists(dest_neg(concl th)) &&
        can (find_term (fun tm -> tm = `t:A`)) (concl th))) THEN
    ASM_REWRITE_TAC[]]);;

let EOENUM_INVSET = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u))
        ==> ?s. s IN D /\
                !w. w IN D
                    ==> (E w s <=>
                         ?u. u IN D /\ E u x /\
                             eordinal D E w /\
                             eoenum D E x r w u)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym" THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (5 |-> (r:A)) ((4 |-> x) v0)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 4 = x /\ v1 5 = r`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t w:A. t IN D /\ w IN D
      ==> (holds D E ((10 |-> w) ((9 |-> t) v1))
             (ordinal_form 10 && enumat_form 10 9) <=>
           eordinal D (E:A->A->bool) w /\ eoenum D E x r w t)`
  (LABEL_TAC "hp") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `valuation D ((10 |-> (w:A)) ((9 |-> (t:A)) v1))`
    ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(10 |-> (w:A)) ((9 |-> (t:A)) v1)`; `10`]
      HOLDS_ORDINAL_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(10 |-> (w:A)) ((9 |-> (t:A)) v1)`; `10`; `9`]
      HOLDS_ENUMAT_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONV_TAC(ONCE_DEPTH_CONV
        NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`ordinal_form 10 && enumat_form 10 9`; `9`; `10`;
     `v1:num->A`; `x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `t:A`] EOENUM_FUNCTIONAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "uq"))) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    USE_THEN "uq" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hp" (fun th ->
      MP_TAC(SPECL [`t:A`; `w':A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "sch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
   [INTRO_TAC "@u. h4 h5 +" THEN
    USE_THEN "hp" (fun th -> ASM_SIMP_TAC[th]) THEN STRIP_TAC THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hp" (fun th -> ASM_SIMP_TAC[th])]);;

let EOENUM_EXHAUSTS = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u))
        ==> ?d. d IN D /\ eordinal D E d /\ eoenum D E x r d x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym" THEN
  REFUTE_THEN (LABEL_TAC "nx") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
    EOENUM_INVSET) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "sch"))) THEN
  FIRST_ASSUM(fun mth ->
    MP_TAC(SPEC `s:A` (REWRITE_RULE[NOT_EXISTS_THM]
      (MATCH_MP EORDINALS_NOSET mth)))) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `d:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `d:A`] EOENUM_EXISTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yd:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `~((yd:A) = x)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
      is_eq(concl th) && lhs(concl th) = `yd:A`)) THEN
    USE_THEN "nx" (fun th ->
      MP_TAC(SPEC `d:A` (REWRITE_RULE[NOT_EXISTS_THM] th))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) yd x` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `d:A`; `yd:A`] EOENUM_VAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  USE_THEN "sch" (fun th -> MP_TAC(SPEC `d:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `yd:A` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The least exhaustion ordinal of the enumeration, via EORDINAL_LEAST on    *)
(* the internal formula ?? 8 (enumat_form 0 8 && Eq 8 4).                    *)
(* ------------------------------------------------------------------------- *)

let EOENUM_LEAST_EXHAUST = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u))
        ==> ?d. d IN D /\ eordinal D E d /\ eoenum D E x r d x /\
                !c. c IN D /\ E c d
                    ==> ~(eoenum D E x r c x)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
    EOENUM_EXHAUSTS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC `v1 = (5 |-> (r:A)) ((4 |-> x) v0)` THEN
  SUBGOAL_THEN `valuation D (v1:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN ASM_MESON_TAC[VALUATION_VALMOD];
    ALL_TAC] THEN
  SUBGOAL_THEN `(v1:num->A) 4 = x /\ v1 5 = r`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v1" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((0 |-> c) v1)
             (?? 8 (enumat_form 0 8 && Eq 8 4)) <=>
           eoenum D (E:A->A->bool) x r c x)`
  (LABEL_TAC "hq") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    SUBGOAL_THEN
     `!y:A. y IN D
        ==> (holds D E ((8 |-> y) ((0 |-> c) v1))
               (enumat_form 0 8) <=>
             eoenum D (E:A->A->bool) x r c y)`
    (LABEL_TAC "he") THENL
     [REPEAT STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (y:A)) ((0 |-> (c:A)) v1)`; `0`; `8`]
        HOLDS_ENUMAT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_EQ] THEN
        ASM_MESON_TAC[VALUATION_VALMOD];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `y:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 MP_TAC SUBST_ALL_TAC))) THEN
      USE_THEN "he" (fun th -> ASM_SIMP_TAC[th]);
      DISCH_TAC THEN EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "he" (fun th -> ASM_SIMP_TAC[th])];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `?? 8 (enumat_form 0 8 && Eq 8 4)`; `v1:num->A`; `d0:A`]
    EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "hq" (fun th -> ASM_SIMP_TAC[th]);
    ALL_TAC] THEN
  INTRO_TAC "@d. h4 h5 + min" THEN
  USE_THEN "hq" (fun th -> ASM_SIMP_TAC[th]) THEN DISCH_TAC THEN
  EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  USE_THEN "min" (fun th -> MP_TAC(SPEC `c:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "hq" (fun th -> ASM_SIMP_TAC[th]));;

(* ------------------------------------------------------------------------- *)
(* The ordertype bijection.  The enumeration graph with its apply            *)
(* characterization; surjectivity onto the carrier under wellfoundedness     *)
(* (no r-least un-enumerated element remains at the exhaustion stage, so by  *)
(* the wf-least property none is un-enumerated at all); two-sided            *)
(* injectivity and order preservation; and EOENUM_BIJ packages the least     *)
(* exhaustion ordinal with the graph as an internal bijection.               *)
(* ------------------------------------------------------------------------- *)

let EOENUM_GRAPH = prove
 (`!D (E:A->A->bool) x r a y.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a /\ y IN D /\ eoenum D E x r a y
        ==> ?rr. rr IN D /\
                 (!k t. k IN D /\ t IN D
                        ==> (eapply D E rr k t <=>
                             E k a /\ eoenum D E x r k t)) /\
                 eenumstep D E x r rr y`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `a:A`;
    `y:A`] EOENUM_CHAR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@rr. h1 rch h2" THEN
  EXISTS_TAC `rr:A` THEN ASM_REWRITE_TAC[] THEN
  REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?b z. b IN D /\ z IN D /\ (E:A->A->bool) b a /\
            eoenum D E x r b z /\ eopair D E b z p`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`;
      `k:A`; `t:A`; `p:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM)
      (SUBST_ALL_TAC o SYM)) THEN
    ASM_REWRITE_TAC[];
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "rch" (fun th -> MP_TAC(SPEC `p:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`k:A`; `t:A`] THEN
    ASM_REWRITE_TAC[]]);;

let EOENUM_ONTO = prove
 (`!D (E:A->A->bool) x r d.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r m t) /\
        eordinal D E d /\ eoenum D E x r d x
        ==> !t. t IN D /\ E t x
                ==> ?b. b IN D /\ E b d /\ eoenum D E x r b t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym wf h4 h5" THEN
  SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `d:A`;
    `x:A`] EOENUM_GRAPH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  INTRO_TAC "@rr. h6 apch +" THEN
  REWRITE_TAC[eenumstep] THEN
  DISCH_THEN(DISJ_CASES_THEN2
    (X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC)
    (LABEL_TAC "nolst")) THENL
   [ASM_MESON_TAC[E_IRREFL]; ALL_TAC] THEN
  X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  REFUTE_THEN (LABEL_TAC "nt") THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
  (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
   `v2 = (11 |-> (d:A)) ((5 |-> r) ((4 |-> x) v0))` THEN
  SUBGOAL_THEN `valuation D (v2:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(v2:num->A) 4 = x /\ v2 5 = r /\ v2 11 = d`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v2" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t':A. t' IN D
      ==> (holds D E ((0 |-> t') v2)
             (Not(?? 10 ((10 %% 11) && enumat_form 10 0))) <=>
           ~(?b. b IN D /\ (E:A->A->bool) b d /\
                 eoenum D E x r b t'))`
  (LABEL_TAC "hz") THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[HOLDS_NOT; HOLDS_EX; HOLDS_AND] THEN
    SUBGOAL_THEN
     `!b:A. b IN D
        ==> (holds D E ((10 |-> b) ((0 |-> t') v2))
               (enumat_form 10 0) <=>
             eoenum D (E:A->A->bool) x r b t')`
    (LABEL_TAC "he") THENL
     [REPEAT STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(10 |-> (b:A)) ((0 |-> (t':A)) v2)`; `10`; `0`]
        HOLDS_ENUMAT_FORM) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[ARITH_EQ] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC(MESON[]
     `((?b:A. P b) <=> (?b:A. Q b))
      ==> (~(?b:A. P b) <=> ~(?b:A. Q b))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!b:A. P b <=> Q b) ==> ((?b:A. P b) <=> (?b:A. Q b))`) THEN
    X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "he" (fun th -> ASM_SIMP_TAC[th]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`Not(?? 10 ((10 %% 11) && enumat_form 10 0))`; `0`;
     `v2:num->A`; `x:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "zch"))) THEN
  SUBGOAL_THEN
   `!w:A. w IN D
      ==> ((E:A->A->bool) w z <=>
           E w x /\
           ~(?b. b IN D /\ E b d /\ eoenum D E x r b w))`
  (LABEL_TAC "zch2") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "zch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "hz" (fun th -> ASM_SIMP_TAC[th]);
    ALL_TAC] THEN
  USE_THEN "wf" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
      USE_THEN "zch2" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN ACCEPT_TAC;
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "zch2" (fun th -> MP_TAC(SPEC `t:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN USE_THEN "nt" ACCEPT_TAC];
    ALL_TAC] THEN
  INTRO_TAC "@m. h7 h8 mlt" THEN
  SUBGOAL_THEN
   `(E:A->A->bool) m x /\
    ~(?b. b IN D /\ (E:A->A->bool) b d /\ eoenum D E x r b m)`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "zch2" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(fst(EQ_IMP_RULE th))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `~(?k. k IN D /\ eapply D (E:A->A->bool) rr k m)`
  ASSUME_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN
     `(E:A->A->bool) k d /\ eoenum D E x r k m`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `m:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `k:A` o
      REWRITE_RULE[NOT_EXISTS_THM] o check (fun th ->
        is_neg(concl th) && is_exists(dest_neg(concl th)) &&
        can (find_term (fun tm -> is_const tm &&
          fst(dest_const tm) = "eoenum")) (concl th))) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t'. t' IN D /\ (E:A->A->bool) t' x /\
         ~(?k. k IN D /\ eapply D E rr k t') /\ ~(t' = m)
         ==> erel D E r m t'`
  ASSUME_TAC THENL
   [X_GEN_TAC `t':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) t' z` ASSUME_TAC THENL
     [USE_THEN "zch2" (fun th -> MP_TAC(SPEC `t':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `b:A` o
        REWRITE_RULE[NOT_EXISTS_THM] o check (fun th ->
          is_neg(concl th) && is_exists(dest_neg(concl th)) &&
          can (find_term (fun tm -> is_const tm &&
            fst(dest_const tm) = "eapply")) (concl th))) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`b:A`; `t':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    USE_THEN "mlt" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "nolst" (fun th ->
    MP_TAC(SPEC `m:A` (REWRITE_RULE[NOT_EXISTS_THM] th))) THEN
  ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[GSYM NOT_EXISTS_THM] THEN ASM_REWRITE_TAC[]);;

let EORDINAL_TRANS_MEM = prove
 (`!D (E:A->A->bool) a b c.
        model D E ZF_AX /\ eordinal D E a /\ b IN D /\ c IN D /\
        E b a /\ E c b
        ==> E c a`,
  REWRITE_TAC[eordinal; etransitive; esubset] THEN MESON_TAC[]);;

let EOENUM_INJ2 = prove
 (`!D (E:A->A->bool) x r a a' t.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E a /\ eordinal D E a' /\ t IN D /\
        ~(t = x) /\ eoenum D E x r a t /\ eoenum D E x r a' t
        ==> a = a'`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `a':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `a:A`; `a':A`; `t:A`] EOENUM_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `a':A`; `a:A`; `t:A`] EOENUM_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EORDINAL_IN];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let EOENUM_ORDER = prove
 (`!D (E:A->A->bool) x r b b' y y'.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        eordinal D E b' /\ b IN D /\ E b b' /\
        y IN D /\ y' IN D /\
        eoenum D E x r b y /\ eoenum D E x r b' y' /\
        ~(y = x) /\ ~(y' = x)
        ==> erel D E r y y'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `b:A`; `y:A`] EOENUM_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "nb") (LABEL_TAC "lstb"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `b':A`; `y':A`] EOENUM_VAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "nb2") (LABEL_TAC "lstb2"))) THEN
  USE_THEN "lstb" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `c:A` THEN STRIP_TAC THEN
    USE_THEN "nb2" MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b':A`; `b:A`;
      `c:A`] EORDINAL_TRANS_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    DISCH_TAC THEN
    FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
      is_eq(concl th) && lhs(concl th) = `y':A`)) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `b:A`; `b':A`; `y:A`] EOENUM_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[]]);;

let EOENUM_BIJ = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r m t)
        ==> ?d f. d IN D /\ eordinal D E d /\ f IN D /\
                  (!k t. k IN D /\ t IN D
                         ==> (eapply D E f k t <=>
                              E k d /\ eoenum D E x r k t)) /\
                  (!k t. k IN D /\ t IN D /\ eapply D E f k t
                         ==> E k d /\ E t x) /\
                  (!k. k IN D /\ E k d
                       ==> ?t. t IN D /\ E t x /\
                               eapply D E f k t) /\
                  (!k k' t. k IN D /\ k' IN D /\ t IN D /\
                            eapply D E f k t /\ eapply D E f k' t
                            ==> k = k') /\
                  (!t. t IN D /\ E t x
                       ==> ?k. k IN D /\ E k d /\
                               eapply D E f k t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym wf" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
    EOENUM_LEAST_EXHAUST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  INTRO_TAC "@d. h4 h5 h6 min" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `d:A`;
    `x:A`] EOENUM_GRAPH) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `f:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 (LABEL_TAC "apch") (fun th -> ALL_TAC)))) THEN
  SUBGOAL_THEN
   `!k y:A. k IN D /\ y IN D /\ (E:A->A->bool) k d /\
            eoenum D E x r k y
            ==> ~(y = x) /\ E y x`
  (LABEL_TAC "vx") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `~((y:A) = x)` ASSUME_TAC THENL
     [DISCH_TAC THEN
      FIRST_X_ASSUM(SUBST_ALL_TAC o check (fun th ->
        is_eq(concl th) && lhs(concl th) = `y:A`)) THEN
      USE_THEN "min" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) k` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `k:A`; `y:A`] EOENUM_VAL) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`d:A`; `f:A`] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) k d /\ eoenum D E x r k t`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "vx" (fun th ->
      MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT2) THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  CONJ_TAC THENL
   [X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) k` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
      `k:A`] EOENUM_EXISTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `~((y:A) = x) /\ (E:A->A->bool) y x`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "vx" (fun th ->
        MP_TAC(SPECL [`k:A`; `y:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "apch" (fun th ->
      MP_TAC(SPECL [`k:A`; `y:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  CONJ_TAC THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `((E:A->A->bool) k d /\ eoenum D E x r k t) /\
    ((E:A->A->bool) k' d /\ eoenum D E x r k' t)`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k':A`; `t:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `~((t:A) = x)` ASSUME_TAC THENL
   [USE_THEN "vx" (fun th ->
      MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o CONJUNCT1) THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `k:A`; `k':A`; `t:A`] EOENUM_INJ2) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN
    ASM_MESON_TAC[EORDINAL_MEMBER];
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`; `d:A`]
    EOENUM_ONTO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
  EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "apch" (fun th ->
    MP_TAC(SPECL [`b:A`; `t:A`] th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Internal bijections: the ebij predicate (bounds, totality,                *)
(* single-valuedness, injectivity, surjectivity), the enumeration graph as   *)
(* an internal bijection with the least exhaustion ordinal (EOENUM_EBIJ),    *)
(* and: in any model of ZF + V=L every set is in internal bijection with an  *)
(* ordinal (ESET_EBIJ: wellorder a stage containing the set by               *)
(* ELWOU_INVARIANT and enumerate).                                           *)
(* ------------------------------------------------------------------------- *)

let ebij = new_definition
  `ebij D (E:A->A->bool) f x y <=>
     f IN D /\
     (!k t. k IN D /\ t IN D /\ eapply D E f k t
            ==> E k x /\ E t y) /\
     (!k. k IN D /\ E k x
          ==> ?t. t IN D /\ E t y /\ eapply D E f k t) /\
     (!k t t'. k IN D /\ t IN D /\ t' IN D /\
               eapply D E f k t /\ eapply D E f k t'
               ==> t = t') /\
     (!k k' t. k IN D /\ k' IN D /\ t IN D /\
               eapply D E f k t /\ eapply D E f k' t
               ==> k = k') /\
     (!t. t IN D /\ E t y
          ==> ?k. k IN D /\ E k x /\ eapply D E f k t)`;;

let EOENUM_EBIJ = prove
 (`!D (E:A->A->bool) x r.
        model D E ZF_AX /\ x IN D /\ r IN D /\
        (!u u'. u IN D /\ u' IN D /\ erel D E r u u'
                ==> ~(erel D E r u' u)) /\
        (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
             (?t. t IN D /\ E t z)
             ==> ?m. m IN D /\ E m z /\
                     !t. t IN D /\ E t z /\ ~(t = m)
                         ==> erel D E r m t)
        ==> ?d f. d IN D /\ eordinal D E d /\
                  ebij D E f d x`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 asym wf" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`]
    EOENUM_BIJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "asym" ACCEPT_TAC; USE_THEN "wf" ACCEPT_TAC];
    ALL_TAC] THEN
  INTRO_TAC "@d f. h4 h5 h6 apch bnd tot inj ont" THEN
  MAP_EVERY EXISTS_TAC [`d:A`; `f:A`] THEN
  ASM_REWRITE_TAC[ebij] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `((E:A->A->bool) k d /\ eoenum D E x r k t) /\
    ((E:A->A->bool) k d /\ eoenum D E x r k t')`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `t:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      USE_THEN "apch" (fun th ->
        MP_TAC(SPECL [`k:A`; `t':A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `r:A`;
    `k:A`; `t:A`; `t':A`] EOENUM_UNIQUE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "asym" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let ESET_EBIJ = prove
 (`!N (E:A->A->bool) x.
        model N E ZF_AX /\ (!u. u IN N ==> elmem N E u) /\
        x IN N
        ==> ?d f. d IN N /\ eordinal N E d /\ ebij N E f d x`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
    (LABEL_TAC "vl") ASSUME_TAC)) THEN
  SUBGOAL_THEN `elmem N (E:A->A->bool) x` MP_TAC THENL
   [USE_THEN "vl" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[elmem] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `ya:A`
    STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`]
    ELWOU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`]
    ELWOU_INVARIANT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`;
    `ya:A`] ELWOINVU_NORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    LABEL_TAC "c3" (CONJUNCT1(CONJUNCT2(CONJUNCT2 th))) THEN
    LABEL_TAC "c7" (CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2
      (CONJUNCT2(CONJUNCT2 th))))))) THEN
  SUBGOAL_THEN `etransitive N (E:A->A->bool) ya` MP_TAC THENL
   [MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`]
      ELSTAGE_TRANSITIVE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[etransitive; esubset] THEN
  DISCH_THEN(LABEL_TAC "ytr") THEN
  SUBGOAL_THEN
   `!t:A. t IN N /\ (E:A->A->bool) t x ==> E t ya`
  (LABEL_TAC "xsub") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "ytr" (fun th -> MP_TAC(SPEC `x:A` th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `x:A`; `ra:A`]
    EOENUM_EBIJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (LABEL_TAC "zsubx") (X_CHOOSE_THEN `t0:A`
        STRIP_ASSUME_TAC))) THEN
    USE_THEN "c7" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
        USE_THEN "xsub" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "zsubx" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        EXISTS_TAC `t0:A` THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Internal cardinality: "there is a bijection between x0 and x1" as a       *)
(* formula (bijex_form), its semantic characterization, and the cardinal     *)
(* |x| = least ordinal in internal bijection with x (ecardof), which exists  *)
(* (in models where every set is constructible, via the wellordering).       *)
(* ------------------------------------------------------------------------- *)

let bijex_form = new_definition
  `bijex_form =
     ?? 5 ((!! 6 (!! 7 (apply_form 5 6 7 -->
                        ((6 %% 0) && (7 %% 1))))) &&
           ((!! 6 ((6 %% 0) -->
                   ?? 7 ((7 %% 1) && apply_form 5 6 7))) &&
            ((!! 6 (!! 7 (!! 8 ((apply_form 5 6 7 &&
                                 apply_form 5 6 8) -->
                                Eq 7 8)))) &&
             ((!! 6 (!! 9 (!! 7 ((apply_form 5 6 7 &&
                                  apply_form 5 9 7) -->
                                 Eq 6 9)))) &&
              (!! 7 ((7 %% 1) -->
                     ?? 6 ((6 %% 0) && apply_form 5 6 7)))))))`;;

let HOLDS_BIJEX_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v bijex_form <=>
             ?f. f IN D /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> eapply D E f k t
                                  ==> E k (v 0) /\ E t (v 1)) /\
                 (!k. k IN D
                      ==> E k (v 0)
                          ==> ?t. t IN D /\
                                  E t (v 1) /\ eapply D E f k t) /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> !t'. t' IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k t'
                                           ==> t = t') /\
                 (!k. k IN D
                      ==> !k'. k' IN D
                               ==> !t. t IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k' t
                                           ==> k = k') /\
                 (!t. t IN D
                      ==> E t (v 1)
                          ==> ?k. k IN D /\
                                  E k (v 0) /\ eapply D E f k t))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t:A. f IN D /\ k IN D /\ t IN D
      ==> (holds D E ((7 |-> t) ((6 |-> k) ((5 |-> f) v)))
             (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (t:A)) ((6 |-> (k:A)) ((5 |-> (f:A)) v))`;
      `5`; `6`; `7`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t t':A. f IN D /\ k IN D /\ t IN D /\ t' IN D
      ==> (holds D E ((8 |-> t') ((7 |-> t) ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E ((8 |-> t') ((7 |-> t) ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 8) <=>
           eapply D E f k t')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (t':A)) ((7 |-> (t:A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `7`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (t':A)) ((7 |-> (t:A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `8`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k k' t:A. f IN D /\ k IN D /\ k' IN D /\ t IN D
      ==> (holds D E ((7 |-> t) ((9 |-> k') ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E ((7 |-> t) ((9 |-> k') ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 9 7) <=>
           eapply D E f k' t)`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (t:A)) ((9 |-> (k':A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `7`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (t:A)) ((9 |-> (k':A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `9`; `7`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[bijex_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!f:A. P f <=> Q f) ==> ((?f. P f) <=> (?f. Q f))`) THEN
  X_GEN_TAC `f:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r1" (fun th1 -> USE_THEN "r2" (fun th2 ->
    USE_THEN "r3" (fun th3 -> ASM_SIMP_TAC[th1; th2; th3]))) THEN
  SUBGOAL_THEN
   `!f k t:A. f IN D /\ k IN D /\ t IN D
      ==> (holds D E ((6 |-> k) ((7 |-> t) ((5 |-> f) v)))
             (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t)`
  (LABEL_TAC "r4") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (k:A)) ((7 |-> (t:A)) ((5 |-> (f':A)) v))`;
      `5`; `6`; `7`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
   `(b <=> b') /\ (e <=> e')
    ==> ((a /\ b /\ c /\ d /\ e) <=> (a /\ b' /\ c /\ d /\ e'))`) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]);
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((!t:A. P t) <=> (!t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r4" (fun th -> ASM_SIMP_TAC[th])]);;

let HOLDS_BIJEX_EBIJ = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v bijex_form <=> ?f. ebij D E f (v 0) (v 1))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`]
    HOLDS_BIJEX_FORM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ebij; IMP_CONJ; RIGHT_IMP_FORALL_THM]);;

let ecardof = new_definition
  `ecardof D (E:A->A->bool) x c <=>
     c IN D /\ eordinal D E c /\ (?f. ebij D E f c x) /\
     (!c'. c' IN D /\ E c' c ==> ~(?f. ebij D E f c' x))`;;

let ECARDOF_EXISTS = prove
 (`!D (E:A->A->bool) x.
        model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ x IN D
        ==> ?c. ecardof D E x c`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] ESET_EBIJ) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (X_CHOOSE_THEN `ff:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `valuation D (\n:num. x:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A. e IN D
      ==> (holds D E ((0 |-> e) (\n:num. x:A)) bijex_form <=>
           (?f. ebij D E f e x))`
  (LABEL_TAC "br") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (e:A)) (\n:num. x:A)`] HOLDS_BIJEX_EBIJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bijex_form`;
    `(\n:num. x:A)`; `d:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "br" (MP_TAC o SPEC `d:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `ff:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@c. h1 h2 hc mn" THEN
  EXISTS_TAC `c:A` THEN REWRITE_TAC[ecardof] THEN ASM_REWRITE_TAC[] THEN
  CONJ_TAC THENL
   [USE_THEN "br" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "hc" ACCEPT_TAC;
    X_GEN_TAC `e:A` THEN STRIP_TAC THEN
    USE_THEN "br" (MP_TAC o SPEC `e:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    USE_THEN "mn" (MP_TAC o SPEC `e:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The equivalence structure of internal bijections: identity (via the       *)
(* replacement image of u |-> <u,u>), converse (image of <m,n> |-> <n,m>)    *)
(* and composition (image of u |-> <u,g(f(u))>), all as sets of pairs used   *)
(* through eapply.  Consequently the cardinal of a cardinal is itself        *)
(* (ECARDOF_CARD).                                                           *)
(* ------------------------------------------------------------------------- *)

let EIDF_EXISTS = prove
 (`!D (E:A->A->bool) x.
     model D E ZF_AX /\ x IN D
     ==> ?h. h IN D /\
             !k t. k IN D /\ t IN D
                   ==> (eapply D E h k t <=> E k x /\ t = k)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\n:num. x:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> u) (\n:num. x:A)))
             (opair_form 0 0 1) <=>
           eopair D (E:A->A->bool) u u w)`
  (LABEL_TAC "hop") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (u:A)) (\n:num. x:A))`;
      `0`; `0`; `1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`opair_form 0 0 1`; `0`; `1`; `(\n:num. x:A)`; `x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "hop" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u:A`;
                  `w':A`; `w:A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "hch"))) THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A`
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "hch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u. h1 h2 +" THEN
    USE_THEN "hop" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`;
                  `u:A`; `u:A`; `z:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN STRIP_ASSUME_TAC THEN ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `k:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hop" (MP_TAC o SPECL [`k:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let EBIJ_ID = prove
 (`!D (E:A->A->bool) x.
     model D E ZF_AX /\ x IN D ==> ?h. ebij D E h x x`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] EIDF_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ch"))) THEN
  EXISTS_TAC `h:A` THEN REWRITE_TAC[ebij] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN EXISTS_TAC `k:A` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN
    INTRO_TAC "h1 h2 h3 +" THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN
    INTRO_TAC "h4 h5 h6 +" THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k':A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (CONJUNCTS_THEN2 ASSUME_TAC (SUBST1_TAC o SYM))
      (CONJUNCTS_THEN2 ASSUME_TAC (SUBST1_TAC o SYM))) THEN
    REFL_TAC;
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN EXISTS_TAC `t:A` THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let ESWAPF_EXISTS = prove
 (`!D (E:A->A->bool) f.
     model D E ZF_AX /\ f IN D
     ==> ?g. g IN D /\
             !k t. k IN D /\ t IN D
                   ==> (eapply D E g t k <=> eapply D E f k t)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\i:num. f:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> u) (\i:num. f:A)))
             (?? 2 (?? 3 (opair_form 2 3 0 && opair_form 3 2 1))) <=>
           (?m. m IN D /\
                ?n. n IN D /\
                    eopair D (E:A->A->bool) m n u /\ eopair D E n m w))`
  (LABEL_TAC "swc") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!m:A. P m <=> Q m) ==> ((?m:A. P m) <=> (?m:A. Q m))`) THEN
    X_GEN_TAC `m:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!n:A. P n <=> Q n) ==> ((?n:A. P n) <=> (?n:A. Q n))`) THEN
    X_GEN_TAC `n:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (n:A)) ((2 |-> (m:A)) ((1 |-> (w:A))
         ((0 |-> (u:A)) (\i:num. f:A))))`;
      `2`; `3`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (n:A)) ((2 |-> (m:A)) ((1 |-> (w:A))
         ((0 |-> (u:A)) (\i:num. f:A))))`;
      `3`; `2`; `1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 2 (?? 3 (opair_form 2 3 0 && opair_form 3 2 1))`;
     `0`; `1`; `(\i:num. f:A)`; `f:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    ASM_CASES_TAC
      `?m n:A. m IN D /\ n IN D /\ eopair D (E:A->A->bool) m n u`
    THENL
     [FIRST_X_ASSUM(X_CHOOSE_THEN `m:A` (X_CHOOSE_THEN `n:A`
        STRIP_ASSUME_TAC)) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `m:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
      SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "swc" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "@m'. h1 @n'. h2 h3 h4" THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m':A`; `n':A`;
                    `m:A`; `n:A`; `u:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `m:A`;
                    `w':A`; `w:A`] EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `w':A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
      USE_THEN "swc" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "@m. h5 @n. h6 h7 _" THEN
      FIRST_X_ASSUM(MP_TAC o check (is_neg o concl)) THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN
      DISCH_THEN(MP_TAC o SPECL [`m:A`; `n:A`]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "cch"))) THEN
  EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A`
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u. h8 h9 +" THEN
    USE_THEN "swc" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@m. h10 @n. h11 h12 h13" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `m:A`;
                  `t:A`; `k:A`; `z:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `u:A`
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
    SUBGOAL_THEN `(u:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `t:A`; `k:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "cch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "swc" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]]);;

let EBIJ_SYM = prove
 (`!D (E:A->A->bool) f x y.
     model D E ZF_AX /\ ebij D E f x y ==> ?g. ebij D E g y x`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebij] THEN
  INTRO_TAC "h1 h2 bnd tot sv inj ont" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`] ESWAPF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ch"))) THEN
  EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    USE_THEN "bnd" (MP_TAC o SPECL [`t:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "ont" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ch" (MP_TAC o SPECL [`w:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN
    INTRO_TAC "h3 h4 h5 +" THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t':A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    USE_THEN "inj" (MP_TAC o SPECL [`t:A`; `t':A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN
    INTRO_TAC "h6 h7 h8 +" THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `k:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `k':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN STRIP_TAC THEN
    USE_THEN "sv" (MP_TAC o SPECL [`t:A`; `k:A`; `k':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "tot" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ch" (MP_TAC o SPECL [`t:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let ECOMPF_EXISTS = prove
 (`!D (E:A->A->bool) f g x y z.
     model D E ZF_AX /\ x IN D /\ ebij D E f x y /\ ebij D E g y z
     ==> ?h. h IN D /\
             !k s. k IN D /\ s IN D
                   ==> (eapply D E h k s <=>
                        E k x /\ ?t. t IN D /\ eapply D E f k t /\
                                     eapply D E g t s)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebij] THEN
  INTRO_TAC "h1 h2 (h3 fb ft fs fi fo) h4 gb gt gs gi go" THEN
  SUBGOAL_THEN
   `valuation D ((5 |-> (g:A)) ((4 |-> (f:A)) (\i:num. f:A)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> u)
             ((5 |-> (g:A)) ((4 |-> (f:A)) (\i:num. f:A)))))
             (?? 2 (?? 3 (apply_form 4 0 2 &&
                          (apply_form 5 2 3 && opair_form 0 3 1)))) <=>
           (?t. t IN D /\
                ?s. s IN D /\
                    eapply D (E:A->A->bool) f u t /\
                    eapply D E g t s /\
                    eopair D E u s w))`
  (LABEL_TAC "cpc") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. P s <=> Q s) ==> ((?s:A. P s) <=> (?s:A. Q s))`) THEN
    X_GEN_TAC `s:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> (s:A)) ((2 |-> (t:A)) ((1 |-> (w:A))
        ((0 |-> (u:A)) ((5 |-> (g:A)) ((4 |-> (f:A))
           (\i:num. f:A)))))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (s:A)) ((2 |-> (t:A)) ((1 |-> (w:A))
        ((0 |-> (u:A)) ((5 |-> (g:A)) ((4 |-> (f:A))
           (\i:num. f:A))))))`;
      `4`; `0`; `2`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (s:A)) ((2 |-> (t:A)) ((1 |-> (w:A))
        ((0 |-> (u:A)) ((5 |-> (g:A)) ((4 |-> (f:A))
           (\i:num. f:A))))))`;
      `5`; `2`; `3`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (s:A)) ((2 |-> (t:A)) ((1 |-> (w:A))
        ((0 |-> (u:A)) ((5 |-> (g:A)) ((4 |-> (f:A))
           (\i:num. f:A))))))`;
      `0`; `3`; `1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 2 (?? 3 (apply_form 4 0 2 &&
                  (apply_form 5 2 3 && opair_form 0 3 1)))`;
     `0`; `1`; `(5 |-> (g:A)) ((4 |-> (f:A)) (\i:num. f:A))`;
     `x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "ft" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "gt" (MP_TAC o SPEC `t0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s0:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "cpc" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@t'. h5 @s'. h6 h7 h8 h9" THEN
    USE_THEN "fs" (MP_TAC o SPECL [`u:A`; `t':A`; `t0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "gs" (MP_TAC o SPECL [`t0:A`; `s':A`; `s0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s0:A`;
                  `w':A`; `w:A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "hcc"))) THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`k:A`; `s:A`] THEN STRIP_TAC THEN
  EQ_TAC THENL
   [DISCH_THEN(MP_TAC o REWRITE_RULE[eapply]) THEN
    DISCH_THEN(X_CHOOSE_THEN `zz:A`
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    USE_THEN "hcc" (MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u. h10 h11 +" THEN
    USE_THEN "cpc" (MP_TAC o SPECL [`u:A`; `zz:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@t'. h12 @s'. h13 h14 h15 h16" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s':A`;
                  `k:A`; `s:A`; `zz:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `t':A` THEN ASM_REWRITE_TAC[];
    INTRO_TAC "h17 @t'. h18 h19 h20" THEN
    REWRITE_TAC[eapply] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `s:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `zz:A`) THEN
    SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hcc" (MP_TAC o SPEC `zz:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "cpc" (MP_TAC o SPECL [`k:A`; `zz:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `t':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[]]);;

let EBIJ_COMPOSE = prove
 (`!D (E:A->A->bool) f g x y z.
     model D E ZF_AX /\ x IN D /\ ebij D E f x y /\ ebij D E g y z
     ==> ?h. ebij D E h x z`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `g:A`;
                `x:A`; `y:A`; `z:A`] ECOMPF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ch"))) THEN
  UNDISCH_TAC `ebij D (E:A->A->bool) g y z` THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "h5 gb gt gs gi go" THEN
  UNDISCH_TAC `ebij D (E:A->A->bool) f x y` THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "h6 fb ft fs fi fo" THEN
  EXISTS_TAC `h:A` THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `s:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "h7 @t. h8 h9 h10" THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "gb" (MP_TAC o SPECL [`t:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "gt" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:A`; `s:A`; `s':A`] THEN
    INTRO_TAC "h11 h12 h13 +" THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `s:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `s':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "(h14 @t. h15 h16 h17) h18 @t'. h19 h20 h21" THEN
    USE_THEN "fs" (MP_TAC o SPECL [`k:A`; `t:A`; `t':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN SUBST_ALL_TAC THEN
    USE_THEN "gs" (MP_TAC o SPECL [`t':A`; `s:A`; `s':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `s:A`] THEN
