let ECARDOF_CARD = prove
 (`!D (E:A->A->bool) x c.
     model D E ZF_AX /\ ecardof D E x c ==> ecardof D E c c`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ecardof] THEN
  INTRO_TAC "h1 h2 h3 (@f. h4) m1" THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `e:A` THEN STRIP_TAC THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `g:A` THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `f:A`;
                  `e:A`; `c:A`; `x:A`] EBIJ_COMPOSE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
    USE_THEN "m1" (MP_TAC o SPEC `e:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `h:A` o REWRITE_RULE[NOT_EXISTS_THM]) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Cardinals proper: the cardinal predicate, minimality of the cardinal      *)
(* among ordinals in bijection, Cantor's theorem (no injection of the power  *)
(* set back into the set, by the diagonal via separation), a cardinal above  *)
(* every ordinal, and (via a slot-2/0 variant of bijex_form to express       *)
(* "is a cardinal" as a formula) the least cardinal above every ordinal,     *)
(* i.e. successor cardinals, in models where every set is constructible.     *)
(* ------------------------------------------------------------------------- *)

let ecardinal = new_definition
  `ecardinal D (E:A->A->bool) c <=> ecardof D E c c`;;

let ECARDOF_CARDINAL = prove
