     model D E ZF_AX /\ x IN D /\ p IN D /\ epow D E x p /\ f IN D /\
     (!k. k IN D /\ E k p ==> ?t. t IN D /\ E t x /\ eapply D E f k t) /\
     (!k k' t. k IN D /\ k' IN D /\ t IN D /\
