(* ------------------------------------------------------------------------- *)
(* omega is a cardinal.  The core is the finite pigeonhole principle, proved *)
(* by an internal least-counterexample argument: injex_form/einj express     *)
(* "there is a (total, single-valued) injection from slot 0 into slot 1";    *)
(* EINJ_DROP repairs an injection suc a --> suc b into one a --> b (the      *)
(* value b is rerouted through f(a) by a piecewise replacement image);       *)
(* EINJ_PIGEONHOLE kills any injection from n into a member of n for n in    *)
(* omega; and restricting the inverse of a putative bijection n <-> omega    *)
(* to suc n then contradicts the pigeonhole.                                 *)
(* ------------------------------------------------------------------------- *)

let EOMEGA_CASES = prove
 (`!D (E:A->A->bool) om n.
     model D E ZF_AX /\ eomega D E om /\ n IN D /\ E n om
     ==> eempty D E n \/
         ?m. m IN D /\ E m om /\ esuc D E m n`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (om:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!j:A. j IN D
      ==> (holds D E ((0 |-> j) ((2 |-> (om:A)) v0))
             (empty_form 0 || ?? 1 ((1 %% 2) && suc_form 1 0)) <=>
           eempty D E j \/
           ?m. m IN D /\ E m om /\ esuc D (E:A->A->bool) m j)`
  (LABEL_TAC "br") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((0 |-> (j:A)) ((2 |-> (om:A)) v0))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OR; HOLDS_EX; HOLDS_AND; HOLDS_EMPTY_FORM;
                 HOLDS_SUC_FORM; VALUATION_VALMOD] THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((e \/ p) <=> (e \/ q))`) THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. P a <=> Q a) ==> ((?a:A. P a) <=> (?a:A. Q a))`) THEN
  X_GEN_TAC `m:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(1 |-> (m:A)) ((0 |-> (j:A)) ((2 |-> (om:A)) v0))`; `1`; `0`]
    HOLDS_SUC_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `empty_form 0 || ?? 1 ((1 %% 2) && suc_form 1 0)`; `0`;
    `(2 |-> (om:A)) v0`] EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      USE_THEN "br" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISJ1_TAC THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "br" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISJ2_TAC THEN EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "br" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun eq -> DISCH_THEN(MP_TAC o REWRITE_RULE[eq])) THEN
  DISCH_THEN ACCEPT_TAC);;

let injex_form = new_definition
  `injex_form =
     ?? 5 ((!! 6 (!! 7 (apply_form 5 6 7 -->
                        ((6 %% 0) && (7 %% 1))))) &&
           ((!! 6 ((6 %% 0) -->
                   ?? 7 ((7 %% 1) && apply_form 5 6 7))) &&
            ((!! 6 (!! 7 (!! 8 ((apply_form 5 6 7 &&
                                 apply_form 5 6 8) -->
                                Eq 7 8)))) &&
             (!! 6 (!! 9 (!! 7 ((apply_form 5 6 7 &&
                                 apply_form 5 9 7) -->
                                Eq 6 9)))))))`;;

let einj = new_definition
  `einj D (E:A->A->bool) f x y <=>
     f IN D /\
     (!k t. k IN D /\ t IN D /\ eapply D E f k t ==> E k x /\ E t y) /\
     (!k. k IN D /\ E k x ==> ?t. t IN D /\ E t y /\ eapply D E f k t) /\
     (!k t t'. k IN D /\ t IN D /\ t' IN D /\
               eapply D E f k t /\ eapply D E f k t' ==> t = t') /\
     (!k k' t. k IN D /\ k' IN D /\ t IN D /\
               eapply D E f k t /\ eapply D E f k' t ==> k = k')`;;

let HOLDS_INJEX_FORM = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v injex_form <=>
             ?f. f IN D /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> eapply D E f k t
                                  ==> E k (v 0) /\ E t (v 1)) /\
                 (!k. k IN D
                      ==> E k (v 0)
                          ==> ?t. t IN D /\
                                  E t (v 1) /\ eapply D E f k t) /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> !t'. t' IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k t'
                                           ==> t = t') /\
                 (!k. k IN D
                      ==> !k'. k' IN D
                               ==> !t. t IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k' t
                                           ==> k = k'))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t:A. f IN D /\ k IN D /\ t IN D
      ==> (holds D E ((7 |-> t) ((6 |-> k) ((5 |-> f) v)))
             (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (t:A)) ((6 |-> (k:A)) ((5 |-> (f:A)) v))`;
      `5`; `6`; `7`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t t':A. f IN D /\ k IN D /\ t IN D /\ t' IN D
      ==> (holds D E ((8 |-> t') ((7 |-> t) ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E ((8 |-> t') ((7 |-> t) ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 8) <=>
           eapply D E f k t')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (t':A)) ((7 |-> (t:A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `7`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(8 |-> (t':A)) ((7 |-> (t:A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `8`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k k' t:A. f IN D /\ k IN D /\ k' IN D /\ t IN D
      ==> (holds D E ((7 |-> t) ((9 |-> k') ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 6 7) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E ((7 |-> t) ((9 |-> k') ((6 |-> k)
             ((5 |-> f) v)))) (apply_form 5 9 7) <=>
           eapply D E f k' t)`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (t:A)) ((9 |-> (k':A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `6`; `7`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(7 |-> (t:A)) ((9 |-> (k':A)) ((6 |-> (k:A))
           ((5 |-> (f:A)) v)))`; `5`; `9`; `7`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [ASM_REWRITE_TAC[ARITH_EQ] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     REWRITE_TAC[VALMOD] THEN
     CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
     REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[injex_form; HOLDS_EX; HOLDS_AND; holds] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(MESON[]
   `(!f:A. P f <=> Q f) ==> ((?f. P f) <=> (?f. Q f))`) THEN
  X_GEN_TAC `f:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r1" (fun th1 -> USE_THEN "r2" (fun th2 ->
    USE_THEN "r3" (fun th3 -> ASM_SIMP_TAC[th1; th2; th3]))) THEN
  MATCH_MP_TAC(TAUT
   `(b <=> b')
    ==> ((a /\ b /\ c /\ d) <=> (a /\ b' /\ c /\ d))`) THEN
  MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]));;

let HOLDS_INJEX_EINJ = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v injex_form <=> ?f. einj D E f (v 0) (v 1))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`]
