  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> u) (\i:num. f:A)))
             (?? 2 (apply_form 3 0 2 && opair_form 0 2 1)) <=>
