     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((2 |-> (t:A)) ((1 |-> (w:A)) ((0 |-> (u:A))
        (\i:num. f:A))))`
