      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "rc" (MP_TAC o SPECL [`k:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `h:A` THEN REWRITE_TAC[einj] THEN ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "fb" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) k x` ASSUME_TAC THENL
     [USE_THEN "sub" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN
    INTRO_TAC "h12 h13 h14 +" THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k:A`; `t':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN
    USE_THEN "fs" (MP_TAC o SPECL [`k:A`; `t:A`; `t':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`k:A`; `k':A`; `t:A`] THEN
    INTRO_TAC "h15 h16 h17 +" THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "gih" (MP_TAC o SPECL [`k':A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    STRIP_TAC THEN
    USE_THEN "fi" (MP_TAC o SPECL [`k:A`; `k':A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

let EOMEGA_CARDINAL = prove
 (`!D (E:A->A->bool) om.
     model D E ZF_AX /\ eomega D E om ==> ecardof D E om om`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  REWRITE_TAC[ecardof] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `g:A` THEN
    DISCH_TAC THEN
    SUBGOAL_THEN `?sn:A. esuc D (E:A->A->bool) n sn`
      (X_CHOOSE_TAC `sn:A`) THENL
     [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) sn om` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
                    `sn:A`] EOMEGA_SUC) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) n sn` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`]
        ESUC_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `n:A`; `om:A`]
      EBIJ_SYM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `g':A`) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g':A`; `om:A`; `n:A`;
                  `sn:A`] EBIJ_SUBSET_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sn:A`;
                    `k:A`] EOMEGA_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sn:A`; `n:A`]
      EINJ_PIGEONHOLE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `h:A` o
      REWRITE_RULE[NOT_EXISTS_THM]) THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Small bijection/cardinal corollaries and the cartesian product set: each  *)
(* fiber {<k,t> : t IN y} is a replacement image, the set of fibers is a     *)
(* second replacement image (functional by extensionality), and the product  *)
(* is its union.                                                             *)
(* ------------------------------------------------------------------------- *)

let EBIJ_EINJ = prove
 (`!D (E:A->A->bool) f x y.
     ebij D E f x y ==> einj D E f x y`,
  REWRITE_TAC[ebij; einj] THEN REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 _" THEN
  ASM_REWRITE_TAC[]);;

let EGRAPH_EXISTS = prove
 (`!D (E:A->A->bool) k y.
     model D E ZF_AX /\ k IN D /\ y IN D
     ==> ?g. g IN D /\
             !z. z IN D
                 ==> (E z g <=> ?t. t IN D /\ E t y /\
                                    eopair D E k t z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\i:num. k:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!t w:A. t IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> t) (\i:num. k:A)))
             (opair_form 2 0 1) <=>
           eopair D (E:A->A->bool) k t w)`
  (LABEL_TAC "gr") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (t:A)) (\i:num. k:A))`;
      `2`; `0`; `1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`opair_form 2 0 1`; `0`; `1`; `(\i:num. k:A)`; `y:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "gr" (MP_TAC o SPECL [`t:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `t:A`;
                  `w':A`; `w:A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "gg"))) THEN
  EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "gg" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "@t. h1 h2 +" THEN
    USE_THEN "gr" (MP_TAC o SPECL [`t:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[];
    INTRO_TAC "@t. h3 h4 h5" THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "gr" (MP_TAC o SPECL [`t:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let EPROD_EXISTS = prove
 (`!D (E:A->A->bool) x y.
     model D E ZF_AX /\ x IN D /\ y IN D
     ==> ?p. p IN D /\
             !z. z IN D
                 ==> (E z p <=>
                      ?k t. k IN D /\ t IN D /\ E k x /\ E t y /\
                            eopair D E k t z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\i:num. y:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> k) (\i:num. y:A)))
             (!! 2 ((2 %% 1) <->
                    ?? 6 ((6 %% 4) && opair_form 0 6 2))) <=>
           !z. z IN D
               ==> (E z w <=>
                    ?t. t IN D /\ E t y /\
                        eopair D (E:A->A->bool) k t z))`
  (LABEL_TAC "cc") THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[holds; HOLDS_IFF; HOLDS_EX; HOLDS_AND] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(MESON[]
     `(!z:A. P z <=> Q z) ==> ((!z:A. P z) <=> (!z:A. Q z))`) THEN
    X_GEN_TAC `z:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(q <=> q') ==> ((p <=> q) <=> (p <=> q'))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (t:A)) ((2 |-> (z:A)) ((1 |-> (w:A)) ((0 |-> (k:A))
         (\i:num. y:A))))`;
      `0`; `6`; `2`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`!! 2 ((2 %% 1) <-> ?? 6 ((6 %% 4) && opair_form 0 6 2))`;
     `0`; `1`; `(\i:num. y:A)`; `x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `y:A`]
      EGRAPH_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `gg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "gc"))) THEN
    EXISTS_TAC `gg:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "cc" (MP_TAC o SPECL [`k:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(LABEL_TAC "wc") THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`]
      ZF_EXTENSIONALITY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`w':A`; `gg:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      USE_THEN "wc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "gc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cset:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "csc"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cset:A`]
    EUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` MP_TAC) THEN
  REWRITE_TAC[eunion] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "un")) THEN
  EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "un" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "@u. h1 + h2" THEN
    USE_THEN "csc" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@k. h3 h4 +" THEN
    USE_THEN "cc" (MP_TAC o SPECL [`k:A`; `u:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) z u`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`k:A`; `t:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `k:A` (X_CHOOSE_THEN `t:A`
      STRIP_ASSUME_TAC)) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `y:A`]
      EGRAPH_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `gg:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "gc"))) THEN
    EXISTS_TAC `gg:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "csc" (MP_TAC o SPEC `gg:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "cc" (MP_TAC o SPECL [`k:A`; `gg:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `z':A` THEN DISCH_TAC THEN
      USE_THEN "gc" (MP_TAC o SPEC `z':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
      USE_THEN "gc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Groundwork for the Godel (max-lex) wellordering of pairs of ordinals:     *)
(* binary union as a formula (for ordinals, union of two is their maximum),  *)
(* the comparison formula mlex_form on coded pairs-of-pairs (slot 0 is       *)
(* <<a,b>,<c,d>> and the comparison is max-then-first-then-second), and the  *)
(* order set carved out of any set of such codes by separation.              *)
(* ------------------------------------------------------------------------- *)

let bunion_form = new_definition
  `bunion_form i j k =
     !! (MAX (MAX i j) k + 1)
        (((MAX (MAX i j) k + 1) %% k) <->
         (((MAX (MAX i j) k + 1) %% i) ||
          ((MAX (MAX i j) k + 1) %% j)))`;;

let HOLDS_BUNION_FORM = prove
 (`!D (E:A->A->bool) v i j k.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v (bunion_form i j k) <=>
          ebunion D E (v i) (v j) (v k))`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(ASSUME_TAC o REWRITE_RULE[valuation]) THEN
  REWRITE_TAC[bunion_form; holds; HOLDS_IFF; HOLDS_OR] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = MAX (MAX i j) k + 1) /\
                       ~(j = MAX (MAX i j) k + 1) /\
                       ~(k = MAX (MAX i j) k + 1)`] THEN
  ASM_SIMP_TAC[EBUNION_ALT] THEN ASM_MESON_TAC[]);;

let EBUNION_ORDINAL_MAX = prove
 (`!D (E:A->A->bool) a b m.
     model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
     ebunion D E a b m
     ==> m = a \/ m = b`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D /\ (b:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(m:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w m <=> E w a \/ E w b)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "mc")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `m:A`]
      EBUNION_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `ebunion D (E:A->A->bool) a b m`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "ext") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [DISJ2_TAC THEN USE_THEN "ext" (MP_TAC o SPECL [`m:A`; `b:A`]) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "mc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(DISJ_CASES_THEN2 MP_TAC ACCEPT_TAC) THEN
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `a:A`; `z:A`]
        EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_TAC THEN DISJ2_TAC THEN ASM_REWRITE_TAC[]];
    DISJ2_TAC THEN USE_THEN "ext" (MP_TAC o SPECL [`m:A`; `b:A`]) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "mc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `(a:A) = b` THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN
    EQ_TAC THENL
     [DISCH_THEN(DISJ_CASES_THEN ACCEPT_TAC);
      DISCH_TAC THEN ASM_REWRITE_TAC[]];
    DISJ1_TAC THEN USE_THEN "ext" (MP_TAC o SPECL [`m:A`; `a:A`]) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "mc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(DISJ_CASES_THEN2 ACCEPT_TAC MP_TAC) THEN
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `z:A`]
        EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_TAC THEN DISJ1_TAC THEN ASM_REWRITE_TAC[]]]);;

let mlex_form = new_definition
  `mlex_form =
     ?? 1 (?? 2
           (opair_form 1 2 0 &&
            ?? 3 (?? 4
                  (opair_form 3 4 1 &&
                   ?? 5 (?? 6
                         (opair_form 5 6 2 &&
                          ?? 7 (?? 8
                                (bunion_form 3 4 7 &&
                                 (bunion_form 5 6 8 &&
                                  ((7 %% 8) ||
                                   ((Eq 7 8) &&
                                    ((3 %% 5) ||
                                     ((Eq 3 5) && (4 %% 6))))))))))))))`;;

let HOLDS_MLEX_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v mlex_form <=>
          ?z. z IN D /\
              ?z'. z' IN D /\
                   eopair D E z z' (v 0) /\
                   ?a. a IN D /\
                       ?b. b IN D /\
                           eopair D E a b z /\
                           ?c. c IN D /\
                               ?d. d IN D /\
                                   eopair D E c d z' /\
                                   ?m. m IN D /\
                                       ?m'. m' IN D /\
                                            ebunion D E a b m /\
                                            (ebunion D E c d m' /\
                                             (E m m' \/
                                              m = m' /\
                                              (E a c \/
                                               a = c /\ E b d))))`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[mlex_form; HOLDS_EX; HOLDS_AND; HOLDS_OR] THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `z:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `z':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((2 |-> (z':A)) ((1 |-> (z:A)) v))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(2 |-> (z':A)) ((1 |-> (z:A)) v)`;
    `1`; `2`; `0`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((c /\ p) <=> (c /\ q))`) THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `a:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `b:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (b:A)) ((3 |-> (a:A)) ((2 |-> (z':A))
      ((1 |-> (z:A)) v))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(4 |-> (b:A)) ((3 |-> (a:A)) ((2 |-> (z':A))
       ((1 |-> (z:A)) v)))`;
    `3`; `4`; `1`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((c /\ p) <=> (c /\ q))`) THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `c:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `d:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((6 |-> (d:A)) ((5 |-> (c:A)) ((4 |-> (b:A))
      ((3 |-> (a:A)) ((2 |-> (z':A)) ((1 |-> (z:A)) v))))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(6 |-> (d:A)) ((5 |-> (c:A)) ((4 |-> (b:A)) ((3 |-> (a:A))
       ((2 |-> (z':A)) ((1 |-> (z:A)) v)))))`;
    `5`; `6`; `2`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((c /\ p) <=> (c /\ q))`) THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `m:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `m':A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((8 |-> (m':A)) ((7 |-> (m:A)) ((6 |-> (d:A))
      ((5 |-> (c:A)) ((4 |-> (b:A)) ((3 |-> (a:A))
        ((2 |-> (z':A)) ((1 |-> (z:A)) v))))))))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(8 |-> (m':A)) ((7 |-> (m:A)) ((6 |-> (d:A)) ((5 |-> (c:A))
       ((4 |-> (b:A)) ((3 |-> (a:A)) ((2 |-> (z':A))
         ((1 |-> (z:A)) v)))))))`;
    `3`; `4`; `7`] HOLDS_BUNION_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(8 |-> (m':A)) ((7 |-> (m:A)) ((6 |-> (d:A)) ((5 |-> (c:A))
       ((4 |-> (b:A)) ((3 |-> (a:A)) ((2 |-> (z':A))
         ((1 |-> (z:A)) v)))))))`;
    `5`; `6`; `8`] HOLDS_BUNION_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

let EMLEX_EXISTS = prove
 (`!D (E:A->A->bool) s.
     model D E ZF_AX /\ s IN D
     ==> ?r. r IN D /\
             !w. w IN D
                 ==> (E w r <=>
                      E w s /\
                      ?z. z IN D /\
                          ?z'. z' IN D /\
                               eopair D E z z' w /\
                               ?a. a IN D /\
                                   ?b. b IN D /\
                                       eopair D E a b z /\
                                       ?c. c IN D /\
                                           ?d. d IN D /\
                                               eopair D E c d z' /\
                                               ?m. m IN D /\
                                                   ?m'. m' IN D /\
                                                        ebunion D E a b m /\
                                                        (ebunion D E c d m' /\
                                                         (E m m' \/
                                                          m = m' /\
                                                          (E a c \/
                                                           a = c /\
                                                           E b d))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D (\i:num. s:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`mlex_form`; `0`; `(\i:num. s:A)`; `s:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rc"))) THEN
  EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "rc" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(TAUT
   `(p <=> q) ==> ((c /\ p) <=> (c /\ q))`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(0 |-> (w:A)) (\i:num. s:A)`] HOLDS_MLEX_FORM) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The semantic max-lex comparison emlex on coded pairs, the packaged order  *)
(* (the pair set q = x * x and the relation set r with its erel              *)
(* characterization), the canonical-decomposition lemma, and asymmetry on    *)
(* pairs of ordinals.                                                        *)
(* ------------------------------------------------------------------------- *)

let emlex = new_definition
  `emlex D (E:A->A->bool) z z' <=>
     ?a. a IN D /\ ?b. b IN D /\ eopair D E a b z /\
         ?c. c IN D /\ ?d. d IN D /\ eopair D E c d z' /\
             ?m. m IN D /\ ?m'. m' IN D /\
                 ebunion D E a b m /\
                 (ebunion D E c d m' /\
                  (E m m' \/ m = m' /\ (E a c \/ a = c /\ E b d)))`;;

let EMLEX_ORDER_EXISTS = prove
 (`!D (E:A->A->bool) x.
     model D E ZF_AX /\ x IN D
     ==> ?q r. q IN D /\ r IN D /\
               (!z. z IN D
                    ==> (E z q <=>
                         ?a b. a IN D /\ b IN D /\ E a x /\ E b x /\
                               eopair D E a b z)) /\
               (!z z'. z IN D /\ z' IN D
                       ==> (erel D E r z z' <=>
                            E z q /\ E z' q /\ emlex D E z z'))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `x:A`]
    EPROD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "qc"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `q:A`]
    EPROD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `qq:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "qqc"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `qq:A`]
    EMLEX_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rc"))) THEN
  MAP_EVERY EXISTS_TAC [`q:A`; `r:A`] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`z:A`; `z':A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`z:A`;`z':A`]
         EREL_IN_IFF) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  EQ_TAC THENL
   [INTRO_TAC "@p. h1 h2 +" THEN
    USE_THEN "rc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "+ @z0. h3 @z0'. h4 h5 cmp" THEN
    SUBGOAL_THEN `(z0:A) = z /\ (z0':A) = z'`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z0:A`; `z0':A`;
                    `z:A`; `z':A`; `p:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_TAC THEN
    USE_THEN "qqc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) p qq`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `u':A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(u:A) = z /\ (u':A) = z'`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`;
                    `z:A`; `z':A`; `p:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    ASM_REWRITE_TAC[emlex] THEN
    USE_THEN "cmp" ACCEPT_TAC;
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    REWRITE_TAC[emlex] THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z':A`]
      EOPAIR_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "rc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN CONJ_TAC THENL
     [USE_THEN "qqc" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`z:A`; `z':A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY EXISTS_TAC [`z:A`] THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[]]]);;

let EMLEX_CANON = prove
 (`!D (E:A->A->bool) z z' a b c d m m'.
     model D E ZF_AX /\ a IN D /\ b IN D /\ c IN D /\ d IN D /\
     m IN D /\ m' IN D /\
     eopair D E a b z /\ eopair D E c d z' /\
     ebunion D E a b m /\ ebunion D E c d m'
     ==> (emlex D E z z' <=>
          E m m' \/ m = m' /\ (E a c \/ a = c /\ E b d))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  REWRITE_TAC[emlex] THEN EQ_TAC THENL
   [
   INTRO_TAC "@a0. h1 @b0. h2 h3 @c0. h4 @d0. h5 h6 @m0. h7 @m1. h8 h9 h10
              +" THEN
    SUBGOAL_THEN `(a0:A) = a /\ (b0:A) = b`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`; `b0:A`;
                    `a:A`; `b:A`; `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(c0:A) = c /\ (d0:A) = d`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c0:A`; `d0:A`;
                    `c:A`; `d:A`; `z':A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(m0:A) = m` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
                    `m0:A`; `m:A`] EBUNION_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(m1:A) = m'` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `d:A`;
                    `m1:A`; `m':A`] EBUNION_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    DISCH_TAC THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `m':A` THEN ASM_REWRITE_TAC[]]);;

let EMLEX_ASYM = prove
 (`!D (E:A->A->bool) a b c d z z'.
     model D E ZF_AX /\ eordinal D E a /\ eordinal D E b /\
     eordinal D E c /\ eordinal D E d /\
     eopair D E a b z /\ eopair D E c d z'
     ==> ~(emlex D E z z' /\ emlex D E z' z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(a:A) IN D /\ (b:A) IN D /\ (c:A) IN D /\ (d:A) IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?m:A. ebunion D (E:A->A->bool) a b m`
    (X_CHOOSE_TAC `m:A`) THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?m':A. ebunion D (E:A->A->bool) c d m'`
    (X_CHOOSE_TAC `m':A`) THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(m:A) IN D /\ (m':A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  UNDISCH_TAC `emlex D (E:A->A->bool) z' z` THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z':A`; `z:A`; `c:A`;
    `d:A`; `a:A`; `b:A`; `m':A`; `m:A`] EMLEX_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  UNDISCH_TAC `emlex D (E:A->A->bool) z z'` THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z':A`; `a:A`;
    `b:A`; `c:A`; `d:A`; `m:A`; `m':A`] EMLEX_CANON) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (DISJ_CASES_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)))) THEN
  DISCH_THEN(DISJ_CASES_THEN2 MP_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (DISJ_CASES_THEN2 MP_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)))) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  ASM_MESON_TAC[E_NOCYCLE2; E_IRREFL]);;

(* ------------------------------------------------------------------------- *)
(* The max-lex order has a least element on every nonempty set of coded      *)
(* ordinal pairs: form the set of maxima (replacement), take its least       *)
(* element (EORDINAL_LEAST_IN, a reusable least-member-of-a-set lemma),      *)
(* then among pairs with that maximum the least first component, then the    *)
(* least second component; canonical decomposition transfers minimality.     *)
(* ------------------------------------------------------------------------- *)

let EMLEX_MAXSET = prove
 (`!D (E:A->A->bool) S.
     model D E ZF_AX /\ S IN D /\
     (!z. z IN D /\ E z S
          ==> ?a b. a IN D /\ b IN D /\ eordinal D E a /\
                    eordinal D E b /\ eopair D E a b z)
     ==> ?M. M IN D /\
             !m. m IN D
                 ==> (E m M <=>
                      ?z a b. z IN D /\ a IN D /\ b IN D /\
                              E z S /\ eopair D E a b z /\
                              ebunion D E a b m)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "dec"))) THEN
  SUBGOAL_THEN `valuation D (\i:num. S:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> z) (\i:num. S:A)))
             (?? 2 (?? 3 (opair_form 2 3 0 && bunion_form 2 3 1))) <=>
           ?a. a IN D /\
               ?b. b IN D /\ eopair D (E:A->A->bool) a b z /\
                   ebunion D E a b w)`
  (LABEL_TAC "mb") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!a:A. P a <=> Q a) ==> ((?a:A. P a) <=> (?a:A. Q a))`) THEN
    X_GEN_TAC `a:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!b:A. P b <=> Q b) ==> ((?b:A. P b) <=> (?b:A. Q b))`) THEN
    X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> (b:A)) ((2 |-> (a:A)) ((1 |-> (w:A))
        ((0 |-> (z:A)) (\i:num. S:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (b:A)) ((2 |-> (a:A)) ((1 |-> (w:A))
         ((0 |-> (z:A)) (\i:num. S:A))))`;
      `2`; `3`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (b:A)) ((2 |-> (a:A)) ((1 |-> (w:A))
         ((0 |-> (z:A)) (\i:num. S:A))))`;
      `2`; `3`; `1`] HOLDS_BUNION_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 2 (?? 3 (opair_form 2 3 0 && bunion_form 2 3 1))`;
     `0`; `1`; `(\i:num. S:A)`; `S:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "dec" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `?m:A. ebunion D (E:A->A->bool) a b m`
      (X_CHOOSE_TAC `m:A`) THENL
     [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(m:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
    EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "mb" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@a0. h1 @b0. h2 h3 h4" THEN
    SUBGOAL_THEN `(a0:A) = a /\ (b0:A) = b`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`; `b0:A`;
                    `a:A`; `b:A`; `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
                  `w':A`; `m:A`] EBUNION_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `M:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "Mc"))) THEN
  EXISTS_TAC `M:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  USE_THEN "Mc" (MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "@z. h5 h6 +" THEN
    USE_THEN "mb" (MP_TAC o SPECL [`z:A`; `m:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@a. h7 @b. h8 h9 h10" THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `a:A`; `b:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `a:A`
      (X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC))) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "mb" (MP_TAC o SPECL [`z:A`; `m:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

let EMLEX_FSTSET = prove
 (`!D (E:A->A->bool) S m0.
     model D E ZF_AX /\ S IN D /\ m0 IN D /\
     (!z. z IN D /\ E z S
          ==> ?a b. a IN D /\ b IN D /\ eordinal D E a /\
                    eordinal D E b /\ eopair D E a b z)
     ==> ?AS. AS IN D /\
              !a. a IN D
                  ==> (E a AS <=>
                       ?z b. z IN D /\ b IN D /\ E z S /\
                             eopair D E a b z /\
                             ebunion D E a b m0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 dec" THEN
  SUBGOAL_THEN `valuation D ((2 |-> (m0:A)) (\i:num. S:A))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> z)
             ((2 |-> (m0:A)) (\i:num. S:A))))
             (?? 3 (opair_form 1 3 0 && bunion_form 1 3 2)) <=>
           ?b. b IN D /\ eopair D (E:A->A->bool) w b z /\
               ebunion D E w b m0)`
  (LABEL_TAC "fb") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!b:A. P b <=> Q b) ==> ((?b:A. P b) <=> (?b:A. Q b))`) THEN
    X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> (b:A)) ((1 |-> (w:A)) ((0 |-> (z:A))
        ((2 |-> (m0:A)) (\i:num. S:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (b:A)) ((1 |-> (w:A)) ((0 |-> (z:A))
         ((2 |-> (m0:A)) (\i:num. S:A))))`;
      `1`; `3`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (b:A)) ((1 |-> (w:A)) ((0 |-> (z:A))
         ((2 |-> (m0:A)) (\i:num. S:A))))`;
      `1`; `3`; `2`] HOLDS_BUNION_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 3 (opair_form 1 3 0 && bunion_form 1 3 2)`;
     `0`; `1`; `(2 |-> (m0:A)) (\i:num. S:A)`; `S:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "dec" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `a:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "fb" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@b0. h4 h5 h6" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w':A`; `b0:A`;
                  `a:A`; `b:A`; `z:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `AS:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "Ac"))) THEN
  EXISTS_TAC `AS:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `a:A` THEN DISCH_TAC THEN
  USE_THEN "Ac" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "@z. h7 h8 +" THEN
    USE_THEN "fb" (MP_TAC o SPECL [`z:A`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `b:A`] THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `z:A` (X_CHOOSE_THEN `b:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "fb" (MP_TAC o SPECL [`z:A`; `a:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[]]);;

let EMLEX_SNDSET = prove
 (`!D (E:A->A->bool) S a0 m0.
     model D E ZF_AX /\ S IN D /\ a0 IN D /\ m0 IN D /\
     (!z. z IN D /\ E z S
          ==> ?a b. a IN D /\ b IN D /\ eordinal D E a /\
                    eordinal D E b /\ eopair D E a b z)
     ==> ?BS. BS IN D /\
              !b. b IN D
                  ==> (E b BS <=>
                       ?z. z IN D /\ E z S /\
                           eopair D E a0 b z /\
                           ebunion D E a0 b m0)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 dec" THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (m0:A)) ((2 |-> (a0:A)) (\i:num. S:A)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> z)
             ((3 |-> (m0:A)) ((2 |-> (a0:A)) (\i:num. S:A)))))
             (opair_form 2 1 0 && bunion_form 2 1 3) <=>
           eopair D (E:A->A->bool) a0 w z /\ ebunion D E a0 w m0)`
  (LABEL_TAC "sb") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_AND] THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (w:A)) ((0 |-> (z:A))
        ((3 |-> (m0:A)) ((2 |-> (a0:A)) (\i:num. S:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (z:A)) ((3 |-> (m0:A))
         ((2 |-> (a0:A)) (\i:num. S:A))))`;
      `2`; `1`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (z:A)) ((3 |-> (m0:A))
         ((2 |-> (a0:A)) (\i:num. S:A))))`;
      `2`; `1`; `3`] HOLDS_BUNION_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`opair_form 2 1 0 && bunion_form 2 1 3`;
     `0`; `1`; `(3 |-> (m0:A)) ((2 |-> (a0:A)) (\i:num. S:A))`;
     `S:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "dec" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
      STRIP_ASSUME_TAC)) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "sb" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC)) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a0:A`; `w':A`;
                  `a:A`; `b:A`; `z:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
