let EORDINAL_LEAST_IN = prove
 (`!D (E:A->A->bool) X d0.
     model D E ZF_AX /\ X IN D /\ d0 IN D /\ eordinal D E d0 /\
     E d0 X
     ==> ?d. d IN D /\ eordinal D E d /\ E d X /\
             !c. c IN D /\ E c d ==> ~(E c X)`,
  REPEAT STRIP_TAC THEN
