   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!e:A. holds D E ((0 |-> e) (\i:num. X:A)) (0 %% 1) <=>
          (E:A->A->bool) e X`
  (LABEL_TAC "hb") THENL
   [GEN_TAC THEN REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
