  USE_THEN "hb" (fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
  EXISTS_TAC `d:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  USE_THEN "mn" (MP_TAC o SPEC `c:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "hb" (fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN ACCEPT_TAC);;

