(* ------------------------------------------------------------------------- *)
(* The ordertype of a subset of an ordinal is at most that ordinal.  The     *)
(* membership order on an ordinal is an internal order set; enumerating a    *)
(* subset s of c along it (EOENUM_BIJ; least elements from                   *)
(* EORDINAL_LEAST_IN) gives an ordinal e and a bijection e <-> s, and the    *)
(* internal transfinite induction "the enumeration dominates its index"      *)
(* (EORDINAL_INDUCT on !! 2 (apply_form 1 0 2 --> Eq 0 2 || 0 %% 2)) forces  *)
(* e <= c.  Hence the cardinal of a subset of an ordinal is at most it.      *)
(* ------------------------------------------------------------------------- *)

let EMEM_ORDER_EXISTS = prove
 (`!D (E:A->A->bool) c.
     model D E ZF_AX /\ c IN D
     ==> ?r. r IN D /\
             !u v. u IN D /\ v IN D
                   ==> (erel D E r u v <=>
                        E u c /\ E v c /\ E u v)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `c:A`]
    EPROD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "qc"))) THEN
  SUBGOAL_THEN `valuation D (\i:num. q:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D
      ==> (holds D E ((0 |-> w) (\i:num. q:A))
             (?? 1 (?? 2 (opair_form 1 2 0 && (1 %% 2)))) <=>
           ?u. u IN D /\
               ?v. v IN D /\ eopair D (E:A->A->bool) u v w /\
                   E u v)`
  (LABEL_TAC "mb") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!u:A. P u <=> Q u) ==> ((?u:A. P u) <=> (?u:A. Q u))`) THEN
    X_GEN_TAC `u:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!v:A. P v <=> Q v) ==> ((?v:A. P v) <=> (?v:A. Q v))`) THEN
    X_GEN_TAC `v:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((2 |-> (v:A)) ((1 |-> (u:A)) ((0 |-> (w:A))
        (\i:num. q:A))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(2 |-> (v:A)) ((1 |-> (u:A)) ((0 |-> (w:A))
         (\i:num. q:A)))`;
      `1`; `2`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 1 (?? 2 (opair_form 1 2 0 && (1 %% 2)))`; `0`;
     `(\i:num. q:A)`; `q:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rc"))) THEN
  EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`u:A`; `v:A`] THEN STRIP_TAC THEN
  MP_TAC(ISPECL[`D:A->bool`;`E:A->A->bool`;`r:A`;`u:A`;`v:A`] EREL_IN_IFF) THEN
  ANTS_TAC THENL
  [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  EQ_TAC THENL
   [INTRO_TAC "@p. h1 h2 +" THEN
    USE_THEN "rc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 MP_TAC MP_TAC) THEN
    USE_THEN "mb" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@u0. h3 @v0. h4 h5 h6" THEN
    SUBGOAL_THEN `(u0:A) = u /\ (v0:A) = v`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u0:A`; `v0:A`;
                    `u:A`; `v:A`; `p:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC) THEN
    USE_THEN "qc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(X_CHOOSE_THEN `u1:A` (X_CHOOSE_THEN `v1:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(u1:A) = u /\ (v1:A) = v`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u1:A`; `v1:A`;
                    `u:A`; `v:A`; `p:A`] EOPAIR_INJ) THEN
