let ESUBSET_ORDINAL_ENUM = prove
 (`!D (E:A->A->bool) c s.
     model D E ZF_AX /\ eordinal D E c /\ s IN D /\
     (!t. t IN D /\ E t s ==> E t c)
     ==> ?r e f.
           r IN D /\
           (!u v. u IN D /\ v IN D
                  ==> (erel D E r u v <=> E u c /\ E v c /\ E u v)) /\
           e IN D /\ eordinal D E e /\ f IN D /\
           (!k t. k IN D /\ t IN D
                  ==> (eapply D E f k t <=>
                       E k e /\ eoenum D E s r k t)) /\
           (!k t. k IN D /\ t IN D /\ eapply D E f k t
                  ==> E k e /\ E t s) /\
           (!k. k IN D /\ E k e
                ==> ?t. t IN D /\ E t s /\ eapply D E f k t) /\
           (!k k' t. k IN D /\ k' IN D /\ t IN D /\
                     eapply D E f k t /\ eapply D E f k' t
                     ==> k = k') /\
           (!t. t IN D /\ E t s
                ==> ?k. k IN D /\ E k e /\ eapply D E f k t)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 ssub" THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`]
    EMEM_ORDER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `r:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rc"))) THEN
  SUBGOAL_THEN
   `!t:A. t IN D /\ (E:A->A->bool) t s ==> eordinal D E t`
  (LABEL_TAC "sord") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `t:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "ssub" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `r:A`]
    EOENUM_BIJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:A`; `u':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) u c /\ E u' c /\ E u u'`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rc" (MP_TAC o SPECL [`u:A`; `u':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `erel D (E:A->A->bool) r u u'`))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "rc" (MP_TAC o SPECL [`u':A`; `u:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
      ASM_MESON_TAC[E_NOCYCLE2];
      X_GEN_TAC `z:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (LABEL_TAC "zsub") (X_CHOOSE_THEN `tw:A`
          STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(E:A->A->bool) tw s` ASSUME_TAC THENL
       [USE_THEN "zsub" (MP_TAC o SPEC `tw:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `tw:A`]
        EORDINAL_LEAST_IN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "sord" (MP_TAC o SPEC `tw:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      INTRO_TAC "@m. h4 h5 h6 mmin" THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(E:A->A->bool) m s` ASSUME_TAC THENL
       [USE_THEN "zsub" (MP_TAC o SPEC `m:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) m c` ASSUME_TAC THENL
       [USE_THEN "ssub" (MP_TAC o SPEC `m:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) t s` ASSUME_TAC THENL
       [USE_THEN "zsub" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t c` ASSUME_TAC THENL
       [USE_THEN "ssub" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "rc" (MP_TAC o SPECL [`m:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `t:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "sord" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_REWRITE_TAC[];
        UNDISCH_TAC `~((t:A) = m)` THEN ASM_REWRITE_TAC[];
        USE_THEN "mmin" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ASM_REWRITE_TAC[]]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `f:A`
    STRIP_ASSUME_TAC)) THEN
  MAP_EVERY EXISTS_TAC [`r:A`; `e:A`; `f:A`] THEN
  ASM_REWRITE_TAC[]);;

let ESUBSET_EBIJ_LE = prove
 (`!D (E:A->A->bool) c s.
     model D E ZF_AX /\ eordinal D E c /\ s IN D /\
     (!t. t IN D /\ E t s ==> E t c)
     ==> ?e f. e IN D /\ eordinal D E e /\ (E e c \/ e = c) /\
               ebij D E f e s`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 ssub" THEN
  SUBGOAL_THEN `(c:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `s:A`]
    ESUBSET_ORDINAL_ENUM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@r e f. h4 rc h5 h6 h7 ch bnd tot inj ont" THEN
  SUBGOAL_THEN
   `!u u':A. u IN D /\ u' IN D /\ erel D (E:A->A->bool) r u u'
      ==> ~(erel D E r u' u)`
  (LABEL_TAC "asym") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `u':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) u c /\ E u' c /\ E u u'`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rc" (MP_TAC o SPECL [`u:A`; `u':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `erel D (E:A->A->bool) r u u'`))) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "rc" (MP_TAC o SPECL [`u':A`; `u:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `u':A`]
      E_NOCYCLE2) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN D /\ (E:A->A->bool) t s ==> eordinal D E t`
  (LABEL_TAC "sord") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `t:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "ssub" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w s ==> ~(w = s)`
  (LABEL_TAC "nots") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN DISCH_TAC THEN
    UNDISCH_TAC `(E:A->A->bool) w s` THEN ASM_REWRITE_TAC[] THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`] E_IRREFL) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. a IN D
      ==> (holds D E ((0 |-> a) (\i:num. f:A))
             (!! 2 (apply_form 1 0 2 --> ((Eq 0 2) || (0 %% 2)))) <=>
           !t. t IN D
               ==> eapply D (E:A->A->bool) f a t
               ==> (a = t \/ E a t))`
  (LABEL_TAC "dom") THENL
   [REPEAT STRIP_TAC THEN
    REWRITE_TAC[holds; HOLDS_OR] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((!t:A. P t) <=> (!t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') ==> ((p ==> q) <=> (p' ==> q))`) THEN
    SUBGOAL_THEN
     `valuation D ((2 |-> (t:A)) ((0 |-> (a:A)) (\i:num. f:A)))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(2 |-> (t:A)) ((0 |-> (a:A)) (\i:num. f:A))`;
      `1`; `0`; `2`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\i:num. f:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a:A. eordinal D (E:A->A->bool) a
      ==> !t. t IN D ==> eapply D E f a t ==> (a = t \/ E a t)`
  (LABEL_TAC "gdom") THENL
   [X_GEN_TAC `a0:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    USE_THEN "dom" (MP_TAC o SPEC `a0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `!! 2 (apply_form 1 0 2 --> ((Eq 0 2) || (0 %% 2)))`;
      `0`; `(\i:num. f:A)`] EORDINAL_INDUCT) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `a:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "IH")) THEN
      SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
      USE_THEN "dom" (MP_TAC o SPEC `a:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `t:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) a e /\ eoenum D E s r a t`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "ch" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `eapply D (E:A->A->bool) f a t`))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) t s` ASSUME_TAC THENL
       [USE_THEN "bnd" (MP_TAC o SPECL [`a:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) t` ASSUME_TAC THENL
       [USE_THEN "sord" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) a t` ASSUME_TAC THENL
       [REWRITE_TAC[esubset] THEN X_GEN_TAC `b:A` THEN
        STRIP_TAC THEN
        SUBGOAL_THEN `(E:A->A->bool) b e` ASSUME_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `a:A`;
                        `b:A`] EORDINAL_TRANS_MEM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC;
          ALL_TAC] THEN
        USE_THEN "tot" (MP_TAC o SPEC `b:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `tb:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `eoenum D (E:A->A->bool) s r b tb`
        ASSUME_TAC THENL
         [USE_THEN "ch" (MP_TAC o SPECL [`b:A`; `tb:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
            (ASSUME `eapply D (E:A->A->bool) f b tb`))) THEN
          DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
          ALL_TAC] THEN
        SUBGOAL_THEN `erel D (E:A->A->bool) r tb t` MP_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `r:A`;
            `b:A`; `a:A`; `tb:A`; `t:A`] EOENUM_ORDER) THEN
          ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
          ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
           [USE_THEN "nots" (MP_TAC o SPEC `tb:A`) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN ACCEPT_TAC;
            USE_THEN "nots" (MP_TAC o SPEC `t:A`) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        USE_THEN "rc" (MP_TAC o SPECL [`tb:A`; `t:A`]) THEN
