        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
          (K ALL_TAC) ASSUME_TAC)) THEN
        SUBGOAL_THEN `(b:A) = tb \/ (E:A->A->bool) b tb`
        (DISJ_CASES_THEN ASSUME_TAC) THENL
         [USE_THEN "IH" (MP_TAC o SPEC `b:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          USE_THEN "dom" (MP_TAC o SPEC `b:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun eq -> DISCH_THEN(MP_TAC o
            REWRITE_RULE[eq])) THEN
          DISCH_THEN(MP_TAC o SPEC `tb:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC;
          ASM_REWRITE_TAC[];
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `t:A`; `tb:A`;
                        `b:A`] EORDINAL_TRANS_MEM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `t:A`]
        EORDINAL_SUBSET_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
       [DISJ2_TAC THEN ASM_REWRITE_TAC[];
        DISJ1_TAC THEN ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `a0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`e:A`; `f:A`] THEN REWRITE_TAC[ebij] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `c:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
     [ASM_REWRITE_TAC[]; ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "tot" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "gdom" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) t c` ASSUME_TAC THENL
     [USE_THEN "ssub" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [UNDISCH_TAC `(c:A) = t` THEN DISCH_THEN SUBST_ALL_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `t:A`]
        E_IRREFL) THEN
      ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `t:A`]
        E_NOCYCLE2) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`k:A`; `t:A`; `t':A`] THEN
    INTRO_TAC "h8 h9 h10 h11 h12" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `r:A`; `k:A`;
                  `t:A`; `t':A`] EOENUM_UNIQUE) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `eapply D (E:A->A->bool) f k t`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
      USE_THEN "ch" (MP_TAC o SPECL [`k:A`; `t':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `eapply D (E:A->A->bool) f k t'`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]]);;

(* ------------------------------------------------------------------------- *)
(* The image of an internal injection is a set (replacement along            *)
(* apply_form 2 0 1) and the injection is a bijection onto it; hence an      *)
(* injection into an ordinal bounds the cardinal: |x| <= e whenever x        *)
(* injects into the ordinal e (image, subset-of-ordinal ordertype,           *)
(* composition, cardinal minimality).                                        *)
(* ------------------------------------------------------------------------- *)

let EINJ_IMAGE = prove
 (`!D (E:A->A->bool) f x y.
     model D E ZF_AX /\ x IN D /\ einj D E f x y
     ==> ?img. img IN D /\
               (!t. t IN D
                    ==> (E t img <=>
                         ?k. k IN D /\ E k x /\ eapply D E f k t)) /\
               (!t. t IN D /\ E t img ==> E t y) /\
               ebij D E f x img`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    MP_TAC)) THEN
  REWRITE_TAC[einj] THEN
  INTRO_TAC "h1 fb ft fs fi" THEN
  SUBGOAL_THEN `valuation D (\i:num. f:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k w:A. k IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> k) (\i:num. f:A)))
             (apply_form 2 0 1) <=>
           eapply D (E:A->A->bool) f k w)`
  (LABEL_TAC "ib") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(1 |-> (w:A)) ((0 |-> (k:A)) (\i:num. f:A))`;
      `2`; `0`; `1`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`apply_form 2 0 1`; `0`; `1`; `(\i:num. f:A)`; `x:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t0:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t0:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "ib" (MP_TAC o SPECL [`k:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN DISCH_TAC THEN
    USE_THEN "fs" (MP_TAC o SPECL [`k:A`; `w':A`; `t0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `img:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ic"))) THEN
  SUBGOAL_THEN
   `!t:A. t IN D
      ==> ((E:A->A->bool) t img <=>
           ?k. k IN D /\ E k x /\ eapply D E f k t)`
  (LABEL_TAC "imc") THENL
   [X_GEN_TAC `t:A` THEN DISCH_TAC THEN
    USE_THEN "ic" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "ib" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t:A. t IN D /\ (E:A->A->bool) t img ==> E t y`
  (LABEL_TAC "sub") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    USE_THEN "imc" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) t img`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "fb" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN `ebij D (E:A->A->bool) f x img` ASSUME_TAC THENL
   [REWRITE_TAC[ebij] THEN REPEAT CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        ASSUME_TAC ASSUME_TAC)) THEN
      CONJ_TAC THENL
       [USE_THEN "fb" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
        USE_THEN "imc" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "fb" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (fun th -> REWRITE_TAC[th])
          (K ALL_TAC))];
      X_GEN_TAC `k:A` THEN STRIP_TAC THEN
      USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "imc" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[];
      USE_THEN "fs" ACCEPT_TAC;
      USE_THEN "fi" ACCEPT_TAC;
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "imc" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) t img`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `img:A` THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    USE_THEN "imc" ACCEPT_TAC;
    USE_THEN "sub" ACCEPT_TAC;
    ASM_REWRITE_TAC[]]);;

let EINJ_ORDINAL_CARD_LE = prove
 (`!D (E:A->A->bool) f x e cx.
     model D E ZF_AX /\ x IN D /\ eordinal D E e /\
     einj D E f x e /\ ecardof D E x cx
     ==> E cx e \/ cx = e`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(cx:A) IN D` ASSUME_TAC THENL
   [MP_TAC(REWRITE_RULE[ecardof]
      (ASSUME `ecardof D (E:A->A->bool) x cx`)) THEN
    DISCH_THEN(ASSUME_TAC o CONJUNCT1) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `x:A`; `e:A`]
    EINJ_IMAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@img. h1 _ sub h2" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `img:A`]
    ESUBSET_EBIJ_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "sub" ACCEPT_TAC;
    ALL_TAC] THEN
  INTRO_TAC "@e' g. h3 h4 h5 h6" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `e':A`;
                `img:A`] EBIJ_SYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `g':A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `g':A`; `x:A`;
                `img:A`; `e':A`] EBIJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `x:A`; `e':A`]
    EBIJ_SYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h':A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `cx:A`; `e':A`]
    ECARDOF_MIN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `h':A` THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [UNDISCH_TAC `(E:A->A->bool) e' e \/ e' = e` THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [DISJ1_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `e':A`;
                    `cx:A`] EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      UNDISCH_TAC `(E:A->A->bool) cx e'` THEN
      ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Infinite cardinals are limit ordinals.  The key is the shift bijection    *)
(* suc g <-> g for g >= omega: g maps to the empty set, finite ordinals n    *)
(* to suc n, everything else to itself (a piecewise replacement image; the   *)
(* case analysis is packaged in the standalone SHIFTVAL lemmas, each a       *)
(* small-context MESON over the three cases).  Hence no infinite cardinal    *)
(* is a successor, and infinite cardinals are closed under ordinal           *)
(* successor -- the fact the kappa*kappa argument needs.                     *)
(* ------------------------------------------------------------------------- *)

let ESUC_INJ = prove
 (`!D (E:A->A->bool) x x' w.
     model D E ZF_AX /\ x IN D /\ x' IN D /\
     esuc D E x w /\ esuc D E x' w
     ==> x = x'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `((E:A->A->bool) x x' \/ x = x') /\ (E x' x \/ x' = x)`
  (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THENL
   [CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x':A`; `w:A`]
        ESUC_ALT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
        (ASSUME `esuc D (E:A->A->bool) x' w`)))) THEN
      DISCH_THEN(MP_TAC o SPEC `x:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `w:A`]
        ESUC_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `w:A`]
        ESUC_ALT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
        (ASSUME `esuc D (E:A->A->bool) x w`)))) THEN
      DISCH_THEN(MP_TAC o SPEC `x':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x':A`; `w:A`]
        ESUC_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  UNDISCH_TAC `(E:A->A->bool) x x' \/ x = x'` THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [UNDISCH_TAC `(E:A->A->bool) x' x \/ x' = x` THEN
    DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `x':A`]
        E_NOCYCLE2) THEN
      ASM_REWRITE_TAC[];
      UNDISCH_TAC `(x':A) = x` THEN DISCH_THEN SUBST_ALL_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`]
        E_IRREFL) THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[]]);;

let EOMEGA_NOT_SUC = prove
 (`!D (E:A->A->bool) om g.
     model D E ZF_AX /\ eomega D E om /\ g IN D /\ esuc D E g om
     ==> F`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) g om` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `om:A`]
      ESUC_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `g:A`; `om:A`]
    EOMEGA_SUC) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] E_IRREFL) THEN
  ASM_REWRITE_TAC[]);;

let EOMEGA_LE_PRED = prove
 (`!D (E:A->A->bool) om g k.
     model D E ZF_AX /\ eomega D E om /\ g IN D /\ esuc D E g k /\
     (E om k \/ om = k)
     ==> E om g \/ om = g`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (DISJ_CASES_THEN ASSUME_TAC))))) THENL
   [SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `k:A`]
      ESUC_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
      (ASSUME `esuc D (E:A->A->bool) g k`)))) THEN
    DISCH_THEN(MP_TAC o SPEC `om:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) om k`))) THEN
    DISCH_THEN ACCEPT_TAC;
    UNDISCH_TAC `(om:A) = k` THEN DISCH_THEN SUBST_ALL_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `g:A`]
      EOMEGA_NOT_SUC) THEN
    ASM_REWRITE_TAC[]]);;

let SHIFTVAL_UNIQUE = prove
 (`!D (E:A->A->bool) om g x v v'.
     model D E ZF_AX /\ eomega D E om /\ g IN D /\ x IN D /\
     v IN D /\ v' IN D /\ ~(E g om) /\
     ((x = g /\ eempty D E v) \/
      ((E x om /\ esuc D E x v) \/
       (~(x = g) /\ ~(E x om) /\ v = x))) /\
     ((x = g /\ eempty D E v') \/
      ((E x om /\ esuc D E x v') \/
       (~(x = g) /\ ~(E x om) /\ v' = x)))
     ==> v = v'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[EEMPTY_UNIQUE; ESUC_UNIQUE]);;

let SHIFTVAL_EXISTS = prove
 (`!D (E:A->A->bool) om g x.
     model D E ZF_AX /\ eomega D E om /\ g IN D /\ x IN D
     ==> ?v. v IN D /\
             ((x = g /\ eempty D E v) \/
              ((E x om /\ esuc D E x v) \/
               (~(x = g) /\ ~(E x om) /\ v = x)))`,
  REPEAT STRIP_TAC THEN ASM_CASES_TAC `(x:A) = g` THENL
   [SUBGOAL_THEN `?ee:A. eempty D (E:A->A->bool) ee`
      (X_CHOOSE_TAC `ee:A`) THENL
     [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `ee:A` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[eempty];
    ASM_CASES_TAC `(E:A->A->bool) x om` THENL
     [SUBGOAL_THEN `?sx:A. esuc D (E:A->A->bool) x sx`
        (X_CHOOSE_TAC `sx:A`) THENL
       [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
      EXISTS_TAC `sx:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ESUC_IN];
      EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]]]);;

let SHIFTVAL_BOUND = prove
 (`!D (E:A->A->bool) om g x v.
     model D E ZF_AX /\ eomega D E om /\ eordinal D E g /\
     (E om g \/ om = g) /\ x IN D /\ v IN D /\
     (E x g \/ x = g) /\
     ((x = g /\ eempty D E v) \/
      ((E x om /\ esuc D E x v) \/
       (~(x = g) /\ ~(E x om) /\ v = x)))
     ==> E v g`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[EOMEGA_EMPTY; EOMEGA_SUC; EORDINAL_TRANS_MEM;
                eomega; einductive]);;

let SHIFTVAL_INJ = prove
 (`!D (E:A->A->bool) om g x x' v.
     model D E ZF_AX /\ eomega D E om /\ g IN D /\ x IN D /\
     x' IN D /\ v IN D /\
     ((x = g /\ eempty D E v) \/
      ((E x om /\ esuc D E x v) \/
       (~(x = g) /\ ~(E x om) /\ v = x))) /\
     ((x' = g /\ eempty D E v) \/
      ((E x' om /\ esuc D E x' v) \/
       (~(x' = g) /\ ~(E x' om) /\ v = x')))
     ==> x = x'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[ESUC_INJ; ESUC_MEMBER; EOMEGA_EMPTY; EOMEGA_SUC;
                eempty]);;

let ESHIFT_EBIJ = prove
 (`!D (E:A->A->bool) om g k.
     model D E ZF_AX /\ eomega D E om /\ eordinal D E g /\
     (E om g \/ om = g) /\ esuc D E g k
     ==> ?h. ebij D E h k g`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
