   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `k:A`]
      ESUC_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w k <=> E w g \/ w = g)`
