let ECARD_INFINITE_NOT_SUC = prove
 (`!D (E:A->A->bool) om kk g.
     model D E ZF_AX /\ eomega D E om /\ ecardinal D E kk /\
     (E om kk \/ om = kk) /\ g IN D /\ esuc D E g kk
     ==> F`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 + h3 h4 h5" THEN
  REWRITE_TAC[ecardinal; ecardof] THEN
  INTRO_TAC "h6 h7 _ mn" THEN
  SUBGOAL_THEN `(E:A->A->bool) g kk` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `kk:A`]
      ESUC_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) g` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `g:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `g:A`; `kk:A`]
    EOMEGA_LE_PRED) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `g:A`; `kk:A`]
    ESHIFT_EBIJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `kk:A`; `g:A`]
    EBIJ_SYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h':A`) THEN
  USE_THEN "mn" (MP_TAC o SPEC `g:A`) THEN
