  DISCH_THEN(MP_TAC o SPEC `h':A` o
    REWRITE_RULE[NOT_EXISTS_THM]) THEN
  ASM_REWRITE_TAC[]);;

let ECARD_INFINITE_SUC_MEM = prove
 (`!D (E:A->A->bool) om kk m sm.
     model D E ZF_AX /\ eomega D E om /\ ecardinal D E kk /\
     (E om kk \/ om = kk) /\ m IN D /\ E m kk /\ esuc D E m sm
     ==> E sm kk`,
  REPEAT GEN_TAC THEN
