      (ASSUME `ecardinal D (E:A->A->bool) kk`)) THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
      ACCEPT_TAC (K ALL_TAC)));
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `m:A`; `sm:A`]
    EORDINAL_SUC_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`;
                  `m:A`] ECARD_INFINITE_NOT_SUC) THEN
    ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `esuc D (E:A->A->bool) m sm` THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Products respect bijections: a bijection u : a <-> b lifts to the         *)
(* cartesian products, <x,y> |-> <u(x),u(y)> : a*a <-> b*b. The products     *)
(* are given by their membership characterizations, so this applies to any   *)
(* sets qa, qb standing in the product relation to a, b.                     *)
(* ------------------------------------------------------------------------- *)

let EBIJ_PRODMAP = prove
 (`!D (E:A->A->bool) u a b qa qb.
     model D E ZF_AX /\ qa IN D /\ qb IN D /\ ebij D E u a b /\
     (!z. z IN D
          ==> (E z qa <=>
               ?x y. x IN D /\ y IN D /\ E x a /\ E y a /\
                     eopair D E x y z)) /\
     (!z. z IN D
          ==> (E z qb <=>
               ?x y. x IN D /\ y IN D /\ E x b /\ E y b /\
                     eopair D E x y z))
     ==> ?h. ebij D E h qa qb`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 + qa qb" THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "h4 ub ut us ui uo" THEN
  SUBGOAL_THEN `valuation D (\i:num. u:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> z) (\i:num. u:A)))
             (?? 3 (?? 4 (opair_form 3 4 0 &&
               ?? 5 (?? 6 (apply_form 2 3 5 &&
                 (apply_form 2 4 6 &&
                  ?? 7 (opair_form 5 6 7 &&
                        opair_form 0 7 1))))))) <=>
           ?x. x IN D /\
               ?y. y IN D /\ eopair D (E:A->A->bool) x y z /\
                   ?s. s IN D /\
                       ?t. t IN D /\ eapply D E u x s /\
                           (eapply D E u y t /\
                            ?p. p IN D /\ eopair D E s t p /\
                                eopair D E z p w))`
  (LABEL_TAC "pm") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!x:A. P x <=> Q x) ==> ((?x:A. P x) <=> (?x:A. Q x))`) THEN
    X_GEN_TAC `x:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!y:A. P y <=> Q y) ==> ((?y:A. P y) <=> (?y:A. Q y))`) THEN
    X_GEN_TAC `y:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((4 |-> (y:A)) ((3 |-> (x:A)) ((1 |-> (w:A))
        ((0 |-> (z:A)) (\i:num. u:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (y:A)) ((3 |-> (x:A)) ((1 |-> (w:A))
         ((0 |-> (z:A)) (\i:num. u:A))))`;
      `3`; `4`; `0`] HOLDS_OPAIR_FORM) THEN
