     `(p <=> q) ==> ((c /\ p) <=> (c /\ q))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!s:A. P s <=> Q s) ==> ((?s:A. P s) <=> (?s:A. Q s))`) THEN
    X_GEN_TAC `s:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
