(* ------------------------------------------------------------------------- *)
(* Ordering properties of internal ordinal addition: a + b extends a         *)
(* (EADD_SUBSET), never falls inside a (EADD_NOTIN), is strictly             *)
(* monotone and injective in the second argument over omega                  *)
(* (EADD_MONO_OMEGA, EADD_INJ), and every element of a + m is either in a or *)
(* of the form a + j with j in m (EADD_SEG). These power the finite          *)
(* (disjoint-union) cardinal arithmetic needed for |m x n| below omega.      *)
(* ------------------------------------------------------------------------- *)

let EADD_MONO_OMEGA = prove
 (`!D (E:A->A->bool) om p j j' k k'.
     model D E ZF_AX /\ eomega D E om /\ p IN D /\
     j IN D /\ j' IN D /\ E j' om /\ E j j' /\
     k IN D /\ k' IN D /\ eadd D E p j k /\ eadd D E p j' k'
     ==> E k k'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11" THEN
  SUBGOAL_THEN `valuation D ((5 |-> (p:A)) (\i:num. p:A))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:A. n IN D
      ==> (holds D E ((0 |-> n) ((5 |-> (p:A)) (\i:num. p:A)))
             (!! 1 (!! 6 (!! 7 (((1 %% 0) &&
                (add_form 5 1 6 && add_form 5 0 7)) -->
                (6 %% 7))))) <=>
           !ja. ja IN D
                ==> !ka. ka IN D
                         ==> !kb. kb IN D
                                  ==> (E ja n /\
                                       eadd D (E:A->A->bool) p ja ka /\
                                       eadd D E p n kb
                                       ==> E ka kb))`
  (LABEL_TAC "madd") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    REWRITE_TAC[holds; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!j:A. P j <=> Q j) ==> ((!j:A. P j) <=> (!j:A. Q j))`) THEN
    X_GEN_TAC `ja:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `ka:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `kb:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((7 |-> (kb:A)) ((6 |-> (ka:A)) ((1 |-> (ja:A))
        ((0 |-> (n:A)) ((5 |-> (p:A)) (\i:num. p:A))))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (kb:A)) ((6 |-> (ka:A)) ((1 |-> (ja:A))
         ((0 |-> (n:A)) ((5 |-> (p:A)) (\i:num. p:A)))))`;
      `5`; `1`; `6`] HOLDS_ADD_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (kb:A)) ((6 |-> (ka:A)) ((1 |-> (ja:A))
         ((0 |-> (n:A)) ((5 |-> (p:A)) (\i:num. p:A)))))`;
      `5`; `0`; `7`] HOLDS_ADD_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 (!! 6 (!! 7 (((1 %% 0) &&
       (add_form 5 1 6 && add_form 5 0 7)) --> (6 %% 7))))`;
    `0`; `(5 |-> (p:A)) (\i:num. p:A)`] EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `ee:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      USE_THEN "madd" (MP_TAC o SPEC `ee:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `ja:A` THEN DISCH_TAC THEN
      X_GEN_TAC `ka:A` THEN DISCH_TAC THEN
      X_GEN_TAC `kb:A` THEN DISCH_TAC THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `~((E:A->A->bool) ja ee)` MP_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN
      INTRO_TAC "h12 h13 + h14" THEN
      USE_THEN "madd" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "IH") THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "madd" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
      SUBGOAL_THEN `?c:A. c IN D /\ eadd D (E:A->A->bool) p u c`
        (X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THENL
       [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `?sc:A. esuc D (E:A->A->bool) c sc`
        (X_CHOOSE_TAC `sc:A`) THENL
       [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(sc:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `eadd D (E:A->A->bool) p s sc` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `u:A`;
          `s:A`; `c:A`; `sc:A`] EADD_SUC) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D ==> ((E:A->A->bool) w sc <=> E w c \/ w = c)`
      (LABEL_TAC "scc") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `sc:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
          (ASSUME `esuc D (E:A->A->bool) c sc`)))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D ==> ((E:A->A->bool) w s <=> E w u \/ w = u)`
      (LABEL_TAC "suc") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
          (ASSUME `esuc D (E:A->A->bool) u s`)))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `ja:A` THEN DISCH_TAC THEN
      X_GEN_TAC `ka:A` THEN DISCH_TAC THEN
      X_GEN_TAC `kb:A` THEN DISCH_TAC THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `(kb:A) = sc` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `s:A`;
          `kb:A`; `sc:A`] EADD_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "scc" (MP_TAC o SPEC `ka:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "suc" (MP_TAC o SPEC `ja:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) ja s`))) THEN
      DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
       [DISJ1_TAC THEN
        USE_THEN "IH" (MP_TAC o SPEC `ja:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `ka:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `c:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        DISJ2_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `u:A`;
          `ka:A`; `c:A`] EADD_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `j':A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "madd" (MP_TAC o SPEC `j':A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `j:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `k:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `k':A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let EADD_INJ = prove
 (`!D (E:A->A->bool) om p j j' k.
     model D E ZF_AX /\ eomega D E om /\ p IN D /\
     j IN D /\ E j om /\ j' IN D /\ E j' om /\
     k IN D /\ eadd D E p j k /\ eadd D E p j' k
     ==> j = j'`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) j /\ eordinal D E j'`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `j:A`; `j':A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC (DISJ_CASES_THEN2
    ACCEPT_TAC ASSUME_TAC)) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`;
      `j:A`; `j':A`; `k:A`; `k:A`] EADD_MONO_OMEGA) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`] E_IRREFL) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`;
      `j':A`; `j:A`; `k:A`; `k:A`] EADD_MONO_OMEGA) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`] E_IRREFL) THEN
    ASM_REWRITE_TAC[]]);;

let EADD_SEG = prove
 (`!D (E:A->A->bool) om p m c k.
     model D E ZF_AX /\ eomega D E om /\ p IN D /\
     m IN D /\ E m om /\ c IN D /\ eadd D E p m c /\
     k IN D /\ E k c
     ==> E k p \/ ?j. j IN D /\ E j m /\ eadd D E p j k`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9" THEN
  SUBGOAL_THEN `valuation D ((5 |-> (p:A)) (\i:num. p:A))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:A. n IN D
      ==> (holds D E ((0 |-> n) ((5 |-> (p:A)) (\i:num. p:A)))
             (!! 1 (!! 6 (((add_form 5 0 1) && (6 %% 1)) -->
                ((6 %% 5) ||
                 ?? 7 ((7 %% 0) && add_form 5 7 6))))) <=>
           !ca. ca IN D
                ==> !ka. ka IN D
                         ==> (eadd D (E:A->A->bool) p n ca /\
                              E ka ca
                              ==> E ka p \/
                                  ?ja. ja IN D /\ E ja n /\
                                       eadd D E p ja ka))`
  (LABEL_TAC "sadd") THENL
   [X_GEN_TAC `n:A` THEN DISCH_TAC THEN
    REWRITE_TAC[holds; HOLDS_AND; HOLDS_OR; HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!c:A. P c <=> Q c) ==> ((!c:A. P c) <=> (!c:A. Q c))`) THEN
    X_GEN_TAC `ca:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `ka:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (ka:A)) ((1 |-> (ca:A))
        ((0 |-> (n:A)) ((5 |-> (p:A)) (\i:num. p:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') /\ (q <=> q')
      ==> ((p ==> q) <=> (p' ==> q'))`) THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(6 |-> (ka:A)) ((1 |-> (ca:A)) ((0 |-> (n:A))
           ((5 |-> (p:A)) (\i:num. p:A))))`;
        `5`; `0`; `1`] HOLDS_ADD_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') /\ (q <=> q')
      ==> ((p \/ q) <=> (p' \/ q'))`) THEN
    CONJ_TAC THENL
     [REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(MESON[]
     `(!j:A. P j <=> Q j) ==> ((?j:A. P j) <=> (?j:A. Q j))`) THEN
    X_GEN_TAC `ja:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (ja:A)) ((6 |-> (ka:A)) ((1 |-> (ca:A))
         ((0 |-> (n:A)) ((5 |-> (p:A)) (\i:num. p:A)))))`;
      `5`; `7`; `6`] HOLDS_ADD_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[ARITH_EQ] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 (!! 6 (((add_form 5 0 1) && (6 %% 1)) -->
       ((6 %% 5) || ?? 7 ((7 %% 0) && add_form 5 7 6))))`;
    `0`; `(5 |-> (p:A)) (\i:num. p:A)`] EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `ee:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      USE_THEN "sadd" (MP_TAC o SPEC `ee:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `ca:A` THEN DISCH_TAC THEN
      X_GEN_TAC `ka:A` THEN DISCH_TAC THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
      SUBGOAL_THEN `eadd D (E:A->A->bool) p ee p` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `ee:A`]
          EADD_ZERO) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(ca:A) = p` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `ee:A`;
          `ca:A`; `p:A`] EADD_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      DISJ1_TAC THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN
      INTRO_TAC "h10 h11 + h12" THEN
      USE_THEN "sadd" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "IH") THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "sadd" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) u` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
      SUBGOAL_THEN `?cu:A. cu IN D /\ eadd D (E:A->A->bool) p u cu`
        (X_CHOOSE_THEN `cu:A` STRIP_ASSUME_TAC) THENL
       [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `?scu:A. esuc D (E:A->A->bool) cu scu`
        (X_CHOOSE_TAC `scu:A`) THENL
       [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(scu:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `eadd D (E:A->A->bool) p s scu` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `u:A`;
          `s:A`; `cu:A`; `scu:A`] EADD_SUC) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D ==> ((E:A->A->bool) w scu <=> E w cu \/ w = cu)`
      (LABEL_TAC "scc") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `cu:A`; `scu:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
          (ASSUME `esuc D (E:A->A->bool) cu scu`)))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D ==> ((E:A->A->bool) w s <=> E w u \/ w = u)`
      (LABEL_TAC "suc") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
          (ASSUME `esuc D (E:A->A->bool) u s`)))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      X_GEN_TAC `ca:A` THEN DISCH_TAC THEN
      X_GEN_TAC `ka:A` THEN DISCH_TAC THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
      SUBGOAL_THEN `(ca:A) = scu` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `s:A`;
          `ca:A`; `scu:A`] EADD_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "scc" (MP_TAC o SPEC `ka:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) ka scu`))) THEN
      DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
       [USE_THEN "IH" (MP_TAC o SPEC `cu:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(MP_TAC o SPEC `ka:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC MP_TAC) THENL
         [DISJ1_TAC THEN ASM_REWRITE_TAC[];
          INTRO_TAC "@ja. h13 h14 h15" THEN
          DISJ2_TAC THEN EXISTS_TAC `ja:A` THEN
          ASM_REWRITE_TAC[] THEN
          USE_THEN "suc" (MP_TAC o SPEC `ja:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          DISJ1_TAC THEN ASM_REWRITE_TAC[]];
        DISJ2_TAC THEN EXISTS_TAC `u:A` THEN
        ASM_REWRITE_TAC[] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s:A`]
          ESUC_MEMBER) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th])]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "sadd" (MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `c:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `k:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Disjoint unions of finite sets: if s and t are disjoint with s ~ p and    *)
(* t ~ m (p, m naturals), then s UNION t ~ p + m, via k |-> f(k) for k in p  *)
(* and p + j |-> g(j) for j in m. UNIONVAL_* are the case lemmas for that    *)
(* piecewise map; EOMEGA_TRANS is transitivity of omega used throughout.     *)
(* ------------------------------------------------------------------------- *)

let UNIONVAL_UNIQUE = prove
 (`!D (E:A->A->bool) om p m f g s t k v v'.
     model D E ZF_AX /\ eomega D E om /\
     p IN D /\ E p om /\ m IN D /\ E m om /\
     s IN D /\ t IN D /\ ebij D E f p s /\ ebij D E g m t /\
     k IN D /\ v IN D /\ v' IN D /\
     ((E k p /\ eapply D E f k v) \/
      (?j. j IN D /\ E j m /\ eadd D E p j k /\
           eapply D E g j v)) /\
     ((E k p /\ eapply D E f k v') \/
      (?j. j IN D /\ E j m /\ eadd D E p j k /\
           eapply D E g j v'))
     ==> v = v'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebij] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[EADD_INJ; EADD_NOTIN; EOMEGA_ORDINALS;
                EOMEGA_TRANS]);;

let UNIONVAL_EXISTS = prove
 (`!D (E:A->A->bool) om p m c f g s t k.
     model D E ZF_AX /\ eomega D E om /\
     p IN D /\ E p om /\ m IN D /\ E m om /\
     c IN D /\ eadd D E p m c /\ s IN D /\ t IN D /\
     ebij D E f p s /\ ebij D E g m t /\ k IN D /\ E k c
     ==> ?v. v IN D /\
             ((E k p /\ eapply D E f k v) \/
              (?j. j IN D /\ E j m /\ eadd D E p j k /\
                   eapply D E g j v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 + + h11 h12" THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "h13 _ gt _ _ _" THEN
  INTRO_TAC "h14 _ ft _ _ _" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`; `m:A`;
                `c:A`; `k:A`] EADD_SEG) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC MP_TAC) THENL
   [USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `j:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "gt" (MP_TAC o SPEC `j:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `v:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `v:A` THEN ASM_REWRITE_TAC[] THEN DISJ2_TAC THEN
    EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[]]);;

let UNIONVAL_BOUND = prove
 (`!D (E:A->A->bool) om p m f g s t st k v.
     model D E ZF_AX /\ eomega D E om /\
     p IN D /\ E p om /\ m IN D /\ E m om /\
     s IN D /\ t IN D /\ st IN D /\
     ebij D E f p s /\ ebij D E g m t /\
     (!z. z IN D ==> (E z st <=> E z s \/ E z t)) /\
     k IN D /\ v IN D /\
     ((E k p /\ eapply D E f k v) \/
      (?j. j IN D /\ E j m /\ eadd D E p j k /\
           eapply D E g j v))
     ==> E v st`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebij] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let UNIONVAL_INJ = prove
 (`!D (E:A->A->bool) om p m f g s t k k' v.
     model D E ZF_AX /\ eomega D E om /\
     p IN D /\ E p om /\ m IN D /\ E m om /\
     s IN D /\ t IN D /\
     ebij D E f p s /\ ebij D E g m t /\
     (!z. z IN D ==> ~(E z s /\ E z t)) /\
     k IN D /\ k' IN D /\ v IN D /\
     ((E k p /\ eapply D E f k v) \/
      (?j. j IN D /\ E j m /\ eadd D E p j k /\
           eapply D E g j v)) /\
     ((E k' p /\ eapply D E f k' v) \/
      (?j. j IN D /\ E j m /\ eadd D E p j k' /\
           eapply D E g j v))
     ==> k = k'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ebij] THEN REPEAT STRIP_TAC THEN
  ASM_MESON_TAC[EADD_UNIQUE; EOMEGA_TRANS]);;

let UNIONVAL_ONTO = prove
 (`!D (E:A->A->bool) om p m c f g s t st v.
     model D E ZF_AX /\ eomega D E om /\
     p IN D /\ E p om /\ m IN D /\ E m om /\
     c IN D /\ eadd D E p m c /\
     s IN D /\ t IN D /\ st IN D /\
     ebij D E f p s /\ ebij D E g m t /\
     (!z. z IN D ==> (E z st <=> E z s \/ E z t)) /\
     v IN D /\ E v st
     ==> ?k. k IN D /\ E k c /\
             ((E k p /\ eapply D E f k v) \/
              (?j. j IN D /\ E j m /\ eadd D E p j k /\
                   eapply D E g j v))`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 + + stc h12 h13" THEN
  REWRITE_TAC[ebij] THEN
  INTRO_TAC "h14 _ _ _ _ go" THEN
  INTRO_TAC "h15 _ _ _ _ fo" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  USE_THEN "stc" (MP_TAC o SPEC `v:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
    (ASSUME `(E:A->A->bool) v st`))) THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [USE_THEN "fo" (MP_TAC o SPEC `v:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `m:A`; `c:A`]
      EADD_SUBSET) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `k:A`) THEN ASM_REWRITE_TAC[];
    USE_THEN "go" (MP_TAC o SPEC `v:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `j:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) j om` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_TRANS]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) j` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    SUBGOAL_THEN `?k:A. k IN D /\ eadd D (E:A->A->bool) p j k`
      (X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THENL
     [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
    EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`;
        `j:A`; `m:A`; `k:A`; `c:A`] EADD_MONO_OMEGA) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      DISJ2_TAC THEN EXISTS_TAC `j:A` THEN ASM_REWRITE_TAC[]]]);;

let EFIN_UNION_BIJ = prove
