(* ------------------------------------------------------------------------- *)
(* Finite products are finite: m x n ~ some p in omega, by internal          *)
(* induction on n via the strip decomposition m x suc(n) = m x n U m x {n}   *)
(* and the disjoint-union bijection. Then injection composition glue         *)
(* (EINJ_WEAKEN, EINJ_COMPOSE) and the omega bound: an ordinal injecting     *)
(* into a set equinumerous with a natural is itself a natural                *)
(* (EINJ_OMEGA_LT), since omega cannot inject into any natural.              *)
(* ------------------------------------------------------------------------- *)

let EBIJ_EMPTY_ANY = prove
 (`!D (E:A->A->bool) ee q.
     model D E ZF_AX /\ eempty D E ee /\ q IN D /\
     (!z. z IN D ==> ~(E z q))
     ==> ebij D E ee ee q`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D ==> ~((E:A->A->bool) z ee)`
  ASSUME_TAC THENL [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  REWRITE_TAC[ebij] THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[eapply] THEN REPEAT CONJ_TAC THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  ASM_MESON_TAC[EOPAIR_IN]);;

let EPROD_NAT_FINITE = prove
 (`!D (E:A->A->bool) om m n q.
     model D E ZF_AX /\ eomega D E om /\ m IN D /\ E m om /\
     n IN D /\ E n om /\ ecross D E m n q
     ==> ?p h. p IN D /\ E p om /\ ebij D E h p q`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((4 |-> (om:A)) ((2 |-> (m:A))
    (\i:num. m:A)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn:A. nn IN D
      ==> (holds D E ((3 |-> nn) ((4 |-> (om:A)) ((2 |-> (m:A))
             (\i:num. m:A))))
             (!! 1 (cross_form 2 3 1 -->
                    ?? 0 ((0 %% 4) && bijex_form))) <=>
           !qq. qq IN D
                ==> (ecross D (E:A->A->bool) m nn qq
                     ==> ?pp. pp IN D /\
                              (E pp om /\
                               ?f. ebij D E f pp qq)))`
  (LABEL_TAC "pfin") THENL
   [X_GEN_TAC `nn:A` THEN DISCH_TAC THEN
    REWRITE_TAC[holds; HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!q:A. P q <=> Q q) ==> ((!q:A. P q) <=> (!q:A. Q q))`) THEN
    X_GEN_TAC `qq:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((1 |-> (qq:A)) ((3 |-> (nn:A)) ((4 |-> (om:A))
        ((2 |-> (m:A)) (\i:num. m:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') /\ (q <=> q')
      ==> ((p ==> q) <=> (p' ==> q'))`) THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (qq:A)) ((3 |-> (nn:A)) ((4 |-> (om:A))
           ((2 |-> (m:A)) (\i:num. m:A))))`;
        `2`; `3`; `1`] HOLDS_CROSS_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(MESON[]
     `(!p:A. P p <=> Q p) ==> ((?p:A. P p) <=> (?p:A. Q p))`) THEN
    X_GEN_TAC `pp:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (pp:A)) ((1 |-> (qq:A)) ((3 |-> (nn:A))
        ((4 |-> (om:A)) ((2 |-> (m:A)) (\i:num. m:A))))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (pp:A)) ((1 |-> (qq:A)) ((3 |-> (nn:A))
         ((4 |-> (om:A)) ((2 |-> (m:A)) (\i:num. m:A)))))`]
      HOLDS_BIJEX_EBIJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 (cross_form 2 3 1 --> ?? 0 ((0 %% 4) && bijex_form))`;
    `3`; `(4 |-> (om:A)) ((2 |-> (m:A)) (\i:num. m:A))`]
    EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `ee:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      USE_THEN "pfin" (MP_TAC o SPEC `ee:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `qq:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `!z:A. z IN D ==> ~((E:A->A->bool) z qq)`
      ASSUME_TAC THENL
       [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
        UNDISCH_TAC `ecross D (E:A->A->bool) m ee qq` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
          (MP_TAC o SPEC `z:A`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[NOT_EXISTS_THM] THEN
        MAP_EVERY X_GEN_TAC [`xx:A`; `yy:A`] THEN
        STRIP_TAC THEN ASM_MESON_TAC[eempty];
        ALL_TAC] THEN
      EXISTS_TAC `ee:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
      EXISTS_TAC `ee:A` THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ee:A`; `qq:A`]
        EBIJ_EMPTY_ANY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN
      INTRO_TAC "h8 h9 + h10" THEN
      USE_THEN "pfin" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "IH") THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "pfin" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `qq:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `!z:A. z IN D
          ==> ((E:A->A->bool) z qq <=>
               ?xx yy. xx IN D /\ yy IN D /\ E xx m /\ E yy s /\
                       eopair D E xx yy z)`
      (LABEL_TAC "qqc") THENL
       [UNDISCH_TAC `ecross D (E:A->A->bool) m s qq` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!w:A. w IN D ==> ((E:A->A->bool) w s <=> E w u \/ w = u)`
      (LABEL_TAC "suc") THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `s:A`]
          ESUC_ALT) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
          (ASSUME `esuc D (E:A->A->bool) u s`)))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u s` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN `?qu:A. ecross D (E:A->A->bool) m u qu`
        (X_CHOOSE_TAC `qu:A`) THENL
       [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(qu:A) IN D /\
        !z:A. z IN D
              ==> ((E:A->A->bool) z qu <=>
                   ?xx yy. xx IN D /\ yy IN D /\ E xx m /\
                           E yy u /\ eopair D E xx yy z)`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "quc")) THENL
       [UNDISCH_TAC `ecross D (E:A->A->bool) m u qu` THEN
        REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "IH" (MP_TAC o SPEC `qu:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@pp. h11 h12 @f. h13" THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `u:A`]
        ECROSS_SINGLE_BIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      INTRO_TAC "@st hst. h14 stc h15" THEN
      SUBGOAL_THEN
       `!z:A. z IN D
          ==> ((E:A->A->bool) z qq <=> E z qu \/ E z st)`
      (LABEL_TAC "un") THENL
       [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
        USE_THEN "qqc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "quc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "stc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EQ_TAC THENL
         [DISCH_THEN(X_CHOOSE_THEN `xx:A` (X_CHOOSE_THEN `yy:A`
            STRIP_ASSUME_TAC)) THEN
          SUBGOAL_THEN `(E:A->A->bool) yy u \/ (yy:A) = u`
          MP_TAC THENL
           [USE_THEN "suc" (MP_TAC o SPEC `yy:A`) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC
            SUBST_ALL_TAC) THENL
           [DISJ1_TAC THEN
            MAP_EVERY EXISTS_TAC [`xx:A`; `yy:A`] THEN
            ASM_REWRITE_TAC[];
            DISJ2_TAC THEN EXISTS_TAC `xx:A` THEN
            ASM_REWRITE_TAC[]];
          DISCH_THEN(DISJ_CASES_THEN MP_TAC) THENL
           [DISCH_THEN(X_CHOOSE_THEN `xx:A` (X_CHOOSE_THEN `yy:A`
              STRIP_ASSUME_TAC)) THEN
            MAP_EVERY EXISTS_TAC [`xx:A`; `yy:A`] THEN
            ASM_REWRITE_TAC[] THEN
            USE_THEN "suc" (MP_TAC o SPEC `yy:A`) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
            DISJ1_TAC THEN ASM_REWRITE_TAC[];
            DISCH_THEN(X_CHOOSE_THEN `xx:A` STRIP_ASSUME_TAC) THEN
            MAP_EVERY EXISTS_TAC [`xx:A`; `u:A`] THEN
            ASM_REWRITE_TAC[]]];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `!z:A. z IN D ==> ~((E:A->A->bool) z qu /\ E z st)`
      (LABEL_TAC "dis") THENL
       [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
        USE_THEN "quc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "stc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        DISCH_THEN(CONJUNCTS_THEN2
          (X_CHOOSE_THEN `xx:A` (X_CHOOSE_THEN `yy:A`
            STRIP_ASSUME_TAC))
          (X_CHOOSE_THEN `xz:A` STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `(yy:A) = u` SUBST_ALL_TAC THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `xx:A`;
            `yy:A`; `xz:A`; `u:A`; `z:A`] EOPAIR_INJ) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
          ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`]
          E_IRREFL) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
      SUBGOAL_THEN `?c:A. c IN D /\ eadd D (E:A->A->bool) pp m c`
        (X_CHOOSE_THEN `c:A` STRIP_ASSUME_TAC) THENL
       [ASM_MESON_TAC[EADD_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) c om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EADD_OMEGA]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `pp:A`;
        `m:A`; `c:A`; `f:A`; `hst:A`; `qu:A`; `st:A`; `qq:A`]
        EFIN_UNION_BIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `hh:A`) THEN
      EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `hh:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pfin" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@pp. h16 h17 @ff. h18" THEN
  MAP_EVERY EXISTS_TAC [`pp:A`; `ff:A`] THEN ASM_REWRITE_TAC[]);;

let EINJ_WEAKEN = prove
 (`!D (E:A->A->bool) f x y z.
     einj D E f x y /\ (!t. t IN D /\ E t y ==> E t z)
     ==> einj D E f x z`,
  REPEAT GEN_TAC THEN REWRITE_TAC[einj] THEN
  INTRO_TAC "(h1 fb ft fs fi) sub" THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`k:A`; `t:A`] THEN STRIP_TAC THEN
    USE_THEN "fb" (MP_TAC o SPECL [`k:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "sub" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "ft" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sub" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

let EINJ_COMPOSE = prove
 (`!D (E:A->A->bool) f g x y z.
     model D E ZF_AX /\ x IN D /\ y IN D /\ z IN D /\
     einj D E f x y /\ einj D E g y z
     ==> ?h. einj D E h x z`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `x:A`; `y:A`]
    EINJ_IMAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@imf. h1 _ fsub h2" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `y:A`; `z:A`]
    EINJ_IMAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@img. h3 _ gsub h4" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `y:A`; `img:A`;
                `imf:A`] EBIJ_SUBSET_INJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `k:A` THEN STRIP_TAC THEN
    USE_THEN "fsub" (MP_TAC o SPEC `k:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h1:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h1:A`; `imf:A`;
                `img:A`] EINJ_IMAGE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@im1. h5 _ h1sub h6" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f:A`; `h1:A`; `x:A`;
                `imf:A`; `im1:A`] EBIJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h2:A`) THEN
  EXISTS_TAC `h2:A` THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h2:A`; `x:A`;
                `im1:A`; `z:A`] EINJ_WEAKEN) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [MATCH_MP_TAC EBIJ_EINJ THEN ASM_REWRITE_TAC[];
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) t img` ASSUME_TAC THENL
       [USE_THEN "h1sub" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "gsub" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let EINJ_OMEGA_ABSURD = prove
 (`!D (E:A->A->bool) om p h.
     model D E ZF_AX /\ eomega D E om /\ p IN D /\ E p om /\
     einj D E h om p
     ==> F`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) p` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardof D (E:A->A->bool) om om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_CARDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `om:A`; `p:A`;
                `om:A`] EINJ_ORDINAL_CARD_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`]
      E_NOCYCLE2) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`] E_IRREFL) THEN
    ASM_REWRITE_TAC[]]);;

let EINJ_OMEGA_LT = prove
 (`!D (E:A->A->bool) om d q p f0 g0.
     model D E ZF_AX /\ eomega D E om /\ eordinal D E d /\
     q IN D /\ einj D E f0 d q /\ p IN D /\ E p om /\
     ebij D E g0 p q
     ==> E d om`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?g1:A. ebij D (E:A->A->bool) g1 q p`
    (X_CHOOSE_TAC `g1:A`) THENL
   [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `?h:A. einj D (E:A->A->bool) h d p`
    (X_CHOOSE_TAC `h:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `f0:A`; `g1:A`;
      `d:A`; `q:A`; `p:A`] EINJ_COMPOSE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `om:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ACCEPT_TAC MP_TAC) THEN
  DISCH_THEN(DISJ_CASES_THEN2 SUBST_ALL_TAC ASSUME_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`;
      `h:A`] EINJ_OMEGA_ABSURD) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[];
    SUBGOAL_THEN `?h0:A. einj D (E:A->A->bool) h0 om d`
      (X_CHOOSE_TAC `h0:A`) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`]
        EBIJ_ID) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `idd:A`) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `idd:A`; `d:A`;
        `d:A`; `om:A`] EBIJ_SUBSET_INJ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN X_GEN_TAC `k:A` THEN STRIP_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `d:A`; `om:A`;
          `k:A`] EORDINAL_TRANS_MEM) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `?h1:A. einj D (E:A->A->bool) h1 om p`
      (X_CHOOSE_TAC `h1:A`) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h0:A`; `h:A`;
        `om:A`; `d:A`; `p:A`] EINJ_COMPOSE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `p:A`;
      `h1:A`] EINJ_OMEGA_ABSURD) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* The mlex enumeration of kappa x kappa keeping its order data: EPRODK_ENUM *)
(* returns the product q, the mlex order-set r with its characterization,    *)
(* and the enumerating bijection f : d <-> q together with the eoenum        *)
(* characterization (so order-preservation is available via EOENUM_ORDER).   *)
(* EDIAG_INJ: the diagonal injection a |-> <a,a> of kappa into the product.  *)
(* ------------------------------------------------------------------------- *)

let EPRODK_ENUM = prove
 (`!D (E:A->A->bool) k.
     model D E ZF_AX /\ eordinal D E k
     ==> ?q r d f.
           q IN D /\
           (!z. z IN D
                ==> (E z q <=>
                     ?a b. a IN D /\ b IN D /\ E a k /\ E b k /\
                           eopair D E a b z)) /\
           r IN D /\
           (!z z'. z IN D /\ z' IN D
                   ==> (erel D E r z z' <=>
                        E z q /\ E z' q /\ emlex D E z z')) /\
           d IN D /\ eordinal D E d /\ f IN D /\
           (!w t. w IN D /\ t IN D
                  ==> (eapply D E f w t <=>
                       E w d /\ eoenum D E q r w t)) /\
           (!z t. z IN D /\ t IN D /\ eapply D E f z t
                  ==> E z d /\ E t q) /\
           (!z. z IN D /\ E z d
                ==> ?t. t IN D /\ E t q /\ eapply D E f z t) /\
           (!z z' t. z IN D /\ z' IN D /\ t IN D /\
                     eapply D E f z t /\ eapply D E f z' t
                     ==> z = z') /\
           (!t. t IN D /\ E t q
                ==> ?z. z IN D /\ E z d /\ eapply D E f z t)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(k:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`]
    EMLEX_ORDER_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@q r. h1 h2 qc rc" THEN
  SUBGOAL_THEN
   `!z:A. z IN D /\ (E:A->A->bool) z q
      ==> ?a b. a IN D /\ b IN D /\ eordinal D E a /\
                eordinal D E b /\ eopair D E a b z`
  (LABEL_TAC "qdec") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "qc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) z q`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
      STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `b:A`] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `a:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `b:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `q:A`; `r:A`]
    EOENUM_BIJ) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`z:A`; `z':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `(E:A->A->bool) z q /\ E z' q /\ emlex D E z z'`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rc" (MP_TAC o SPECL [`z:A`; `z':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `erel D (E:A->A->bool) r z z'`))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "rc" (MP_TAC o SPECL [`z':A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "qdec" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
        STRIP_ASSUME_TAC)) THEN
      USE_THEN "qdec" (MP_TAC o SPEC `z':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `dd:A`
        STRIP_ASSUME_TAC)) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
        `c:A`; `dd:A`; `z:A`; `z':A`] EMLEX_ASYM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o REWRITE_RULE[DE_MORGAN_THM]) THEN
      DISCH_THEN(DISJ_CASES_THEN MP_TAC) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `s:A` THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        (LABEL_TAC "ssub") (X_CHOOSE_THEN `tw:A`
          STRIP_ASSUME_TAC))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`]
        EMLEX_LEAST) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
          USE_THEN "qdec" (MP_TAC o SPEC `z:A`) THEN
          ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
          ASM_REWRITE_TAC[] THEN
          USE_THEN "ssub" (MP_TAC o SPEC `z:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC;
          EXISTS_TAC `tw:A` THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      INTRO_TAC "@z0. h3 h4 z0min" THEN
      EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "rc" (MP_TAC o SPECL [`z0:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REPEAT CONJ_TAC THENL
       [USE_THEN "ssub" (MP_TAC o SPEC `z0:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        USE_THEN "ssub" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        USE_THEN "z0min" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `d:A` (X_CHOOSE_THEN `f:A`
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "enc")
        STRIP_ASSUME_TAC)))))) THEN
  MAP_EVERY EXISTS_TAC [`q:A`; `r:A`; `d:A`; `f:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "qc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
