    USE_THEN "rc" ACCEPT_TAC;
    USE_THEN "enc" ACCEPT_TAC]);;

let EDIAG_INJ = prove
 (`!D (E:A->A->bool) k q.
     model D E ZF_AX /\ k IN D /\ q IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a k /\ E b k /\
                     eopair D E a b z))
     ==> ?h. einj D E h k q`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 qc" THEN
  SUBGOAL_THEN `valuation D (\i:num. k:A)` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> z) (\i:num. k:A)))
             (?? 3 (opair_form 0 0 3 && opair_form 0 3 1)) <=>
           ?v. v IN D /\ eopair D (E:A->A->bool) z z v /\
               eopair D E z v w)`
  (LABEL_TAC "pm") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    MATCH_MP_TAC(MESON[]
     `(!v:A. P v <=> Q v) ==> ((?v:A. P v) <=> (?v:A. Q v))`) THEN
    X_GEN_TAC `v:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> (v:A)) ((1 |-> (w:A)) ((0 |-> (z:A))
        (\i:num. k:A))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (v:A)) ((1 |-> (w:A)) ((0 |-> (z:A)) (\i:num. k:A)))`;
      `0`; `0`; `3`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (v:A)) ((1 |-> (w:A)) ((0 |-> (z:A)) (\i:num. k:A)))`;
      `0`; `3`; `1`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 3 (opair_form 0 0 3 && opair_form 0 3 1)`;
     `0`; `1`; `(\i:num. k:A)`; `k:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?v:A. eopair D (E:A->A->bool) z z v`
      (X_CHOOSE_TAC `v:A`) THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(v:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `?w:A. eopair D (E:A->A->bool) z v w`
      (X_CHOOSE_TAC `w:A`) THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(w:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "pm" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    INTRO_TAC "@v'. h4 h5 h6" THEN
    SUBGOAL_THEN `(v':A) = v` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z:A`;
                    `v':A`; `v:A`] EOPAIR_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `v:A`;
                  `w':A`; `w:A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `h:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "hch"))) THEN
  SUBGOAL_THEN
   `!z t:A. z IN D /\ t IN D
      ==> (eapply D (E:A->A->bool) h z t <=>
           E z k /\ eopair D E z z t)`
  (LABEL_TAC "hc") THENL
   [MAP_EVERY X_GEN_TAC [`z:A`; `t:A`] THEN STRIP_TAC THEN
    EQ_TAC THENL
     [DISCH_THEN(MP_TAC o REWRITE_RULE[eapply]) THEN
      DISCH_THEN(X_CHOOSE_THEN `zz:A`
        (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC)) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "hch" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "@z0. h7 h8 +" THEN
      USE_THEN "pm" (MP_TAC o SPECL [`z0:A`; `zz:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      INTRO_TAC "@v0. h9 h10 h11" THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z0:A`; `v0:A`;
                    `z:A`; `t:A`; `zz:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
      REWRITE_TAC[eapply] THEN
      SUBGOAL_THEN `?zz:A. eopair D (E:A->A->bool) z t zz`
        (X_CHOOSE_TAC `zz:A`) THENL
       [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hch" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "pm" (MP_TAC o SPECL [`z:A`; `zz:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `h:A` THEN REWRITE_TAC[einj] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`z:A`; `t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC MP_TAC)) THEN
    USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `t:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "qc" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`z:A`; `z:A`] THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?t:A. eopair D (E:A->A->bool) z z t`
      (X_CHOOSE_TAC `t:A`) THENL
     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "qc" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`z:A`; `z:A`] THEN ASM_REWRITE_TAC[];
      USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    MAP_EVERY X_GEN_TAC [`z:A`; `t:A`; `t':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) z z t /\ eopair D E z z t'`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `eapply D (E:A->A->bool) h z t`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `t':A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `eapply D (E:A->A->bool) h z t'`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z:A`;
                  `t:A`; `t':A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`z:A`; `z':A`; `t:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) z z t /\ eopair D E z' z' t`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `eapply D (E:A->A->bool) h z t`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        USE_THEN "hc" (MP_TAC o SPECL [`z':A`; `t:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `eapply D (E:A->A->bool) h z' t`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `z:A`; `z:A`;
                  `z':A`; `z':A`; `t:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC))]);;

(* ------------------------------------------------------------------------- *)
(* The segment bound for the Jech argument: if the mlex ordertype d of       *)
(* kappa x kappa exceeds the infinite cardinal kappa (E kk d), then kappa    *)
(* injects into sm x sm for some sm < kappa: take t = f(kappa) = <a,b>,      *)
(* sm = suc(max(a,b)) (still < kappa since infinite cardinals are limits),   *)
(* and restrict the enumeration f to kappa -- every f(z) with z < kappa is   *)
(* mlex-below t, so both components are <= max(a,b) < sm.                    *)
(* ------------------------------------------------------------------------- *)

let EPRODK_SEG_INJ = prove
 (`!D (E:A->A->bool) om kk q r d f.
     model D E ZF_AX /\ eomega D E om /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\
     q IN D /\
     (!z. z IN D
          ==> (E z q <=>
               ?a b. a IN D /\ b IN D /\ E a kk /\ E b kk /\
                     eopair D E a b z)) /\
     r IN D /\
     (!z z'. z IN D /\ z' IN D
             ==> (erel D E r z z' <=>
                  E z q /\ E z' q /\ emlex D E z z')) /\
     d IN D /\ eordinal D E d /\ f IN D /\
     (!w t. w IN D /\ t IN D
            ==> (eapply D E f w t <=> E w d /\ eoenum D E q r w t)) /\
     (!z t. z IN D /\ t IN D /\ eapply D E f z t
            ==> E z d /\ E t q) /\
     (!z. z IN D /\ E z d
          ==> ?t. t IN D /\ E t q /\ eapply D E f z t) /\
     (!z z' t. z IN D /\ z' IN D /\ t IN D /\
               eapply D E f z t /\ eapply D E f z' t
               ==> z = z') /\
     E kk d
     ==> ?sm smq h. sm IN D /\ E sm kk /\ ecross D E sm sm smq /\
                    einj D E h kk smq`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 qc h6 rc h7 h8 h9 enc fb ft fi h10" THEN
  SUBGOAL_THEN `(kk:A) IN D /\ eordinal D (E:A->A->bool) kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u u':A. u IN D /\ u' IN D /\ erel D (E:A->A->bool) r u u'
      ==> ~(erel D E r u' u)`
  (LABEL_TAC "asym") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `u':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) u q /\ E u' q /\ emlex D E u u'`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rc" (MP_TAC o SPECL [`u:A`; `u':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `erel D (E:A->A->bool) r u u'`))) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "qc" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) u q`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `ua:A` (X_CHOOSE_THEN `ub:A`
      STRIP_ASSUME_TAC)) THEN
    USE_THEN "qc" (MP_TAC o SPEC `u':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) u' q`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `va:A` (X_CHOOSE_THEN `vb:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) ua /\ eordinal D E ub /\
      eordinal D E va /\ eordinal D E vb`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    USE_THEN "rc" (MP_TAC o SPECL [`u':A`; `u:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ua:A`; `ub:A`;
      `va:A`; `vb:A`; `u:A`; `u':A`] EMLEX_ASYM) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  USE_THEN "ft" (MP_TAC o SPEC `kk:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@t. h11 h12 h13" THEN
  USE_THEN "qc" (MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
    (ASSUME `(E:A->A->bool) t q`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `b:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `eordinal D (E:A->A->bool) a /\ eordinal D E b`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `?mx:A. ebunion D (E:A->A->bool) a b mx`
    (X_CHOOSE_TAC `mx:A`) THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(mx:A) IN D /\ eordinal D (E:A->A->bool) mx /\ E mx kk`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`;
      `mx:A`] EBUNION_ORDINAL_MAX) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?sm:A. esuc D (E:A->A->bool) mx sm`
    (X_CHOOSE_TAC `sm:A`) THENL
   [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sm:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sm kk` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`;
      `mx:A`; `sm:A`] ECARD_INFINITE_SUC_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w sm <=> E w mx \/ w = mx)`
  (LABEL_TAC "smc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `mx:A`; `sm:A`]
      ESUC_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
      (ASSUME `esuc D (E:A->A->bool) mx sm`)))) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?smq:A. ecross D (E:A->A->bool) sm sm smq`
    (X_CHOOSE_TAC `smq:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(smq:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z smq <=>
               ?xx yy. xx IN D /\ yy IN D /\ E xx sm /\ E yy sm /\
                       eopair D E xx yy z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "smqc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) sm sm smq` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `eoenum D (E:A->A->bool) q r kk t` ASSUME_TAC THENL
