(* ------------------------------------------------------------------------- *)
(* Jech 3.5: kappa (x) kappa = kappa for every infinite cardinal, in the     *)
(* global-wellorder (elmem) context. EPRODK_SEG_CONTRA derives the           *)
(* contradiction from a too-small segment bound (finite case via             *)
(* EPROD_NAT_FINITE/EINJ_OMEGA_LT, infinite case via |sm|, EBIJ_PRODMAP      *)
(* and the induction hypothesis). EPRODK_CARD packages the least-bad-        *)
(* cardinal argument: the bad-cardinal formula (ordinal, >= omega, cardinal  *)
(* via bijex20_form, product-bijection failure via bijex_form under          *)
(* cross_form), EORDINAL_LEAST, the enumeration EPRODK_ENUM made bijective,  *)
(* the diagonal injection for kappa <= d, and the segment machinery for      *)
(* kappa < d.                                                                *)
(* ------------------------------------------------------------------------- *)

let EPRODK_SEG_CONTRA = prove
 (`!D (E:A->A->bool) om kk sm smq h.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\
     sm IN D /\ E sm kk /\ ecross D E sm sm smq /\
     einj D E h kk smq /\
     (!c. c IN D /\ E c kk /\ ecardinal D E c /\ (E om c \/ om = c)
          ==> !q'. q' IN D /\ ecross D E c c q'
                   ==> ?g. ebij D E g c q')
     ==> F`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 ge h4 h5 h6 h7 IH" THEN
  SUBGOAL_THEN `(kk:A) IN D /\ eordinal D (E:A->A->bool) kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(smq:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sm` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `~((E:A->A->bool) kk om)` ASSUME_TAC THENL
   [DISCH_TAC THEN
    USE_THEN "ge" (DISJ_CASES_THEN2 ASSUME_TAC MP_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `om:A`]
        E_NOCYCLE2) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`]
        E_IRREFL) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`; `om:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC (LABEL_TAC "inf")) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sm:A`;
      `sm:A`; `smq:A`] EPROD_NAT_FINITE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `p:A` (X_CHOOSE_THEN `g:A`
      STRIP_ASSUME_TAC)) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`;
      `smq:A`; `p:A`; `h:A`; `g:A`] EINJ_OMEGA_LT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    UNDISCH_TAC `~((E:A->A->bool) kk om)` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D /\ (E:A->A->bool) w om ==> E w sm`
  (LABEL_TAC "omsub") THENL
   [X_GEN_TAC `w:A` THEN STRIP_TAC THEN
    USE_THEN "inf" (DISJ_CASES_THEN2 SUBST_ALL_TAC ASSUME_TAC) THENL
     [ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`; `om:A`;
        `w:A`] EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?csm:A. ecardof D (E:A->A->bool) sm csm`
    (X_CHOOSE_TAC `csm:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`]
      ECARDOF_EXISTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN USE_THEN "lm" ACCEPT_TAC;
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `(csm:A) IN D /\ eordinal D (E:A->A->bool) csm /\
    (?g1. ebij D E g1 csm sm) /\
    (!c'. c' IN D /\ E c' csm ==> ~(?g1. ebij D E g1 c' sm))`
  (DESTRUCT_TAC "h8 h9 (@g1. h10) csmin") THENL
   [UNDISCH_TAC `ecardof D (E:A->A->bool) sm csm` THEN
    REWRITE_TAC[ecardof] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) csm` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECARDOF_CARDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) csm sm \/ (csm:A) = sm`
  (LABEL_TAC "csmle") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `csm:A`; `sm:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (fun th -> DISJ1_TAC THEN ACCEPT_TAC th)
      (DISJ_CASES_THEN2 (fun th -> DISJ2_TAC THEN ACCEPT_TAC th)
        ASSUME_TAC)) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `idd:A`) THEN
    USE_THEN "csmin" (MP_TAC o SPEC `sm:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[NOT_EXISTS_THM] THEN
    DISCH_THEN(MP_TAC o SPEC `idd:A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) om csm \/ (om:A) = csm`
  (LABEL_TAC "csminf") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `csm:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN2
      (fun th -> DISJ1_TAC THEN ACCEPT_TAC th)
      (DISJ_CASES_THEN2 (fun th -> DISJ2_TAC THEN ACCEPT_TAC th)
        ASSUME_TAC)) THEN
    SUBGOAL_THEN `?h0:A. einj D (E:A->A->bool) h0 om sm`
      (X_CHOOSE_TAC `h0:A`) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sm:A`]
        EBIJ_ID) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `idd:A`) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `idd:A`; `sm:A`;
        `sm:A`; `om:A`] EBIJ_SUBSET_INJ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "omsub" ACCEPT_TAC;
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `?g1s:A. ebij D (E:A->A->bool) g1s sm csm`
      (X_CHOOSE_TAC `g1s:A`) THENL
     [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
    SUBGOAL_THEN `?h1:A. einj D (E:A->A->bool) h1 om csm`
      (X_CHOOSE_TAC `h1:A`) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h0:A`; `g1s:A`;
        `om:A`; `sm:A`; `csm:A`] EINJ_COMPOSE) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `csm:A`;
      `h1:A`] EINJ_OMEGA_ABSURD) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) csm kk` ASSUME_TAC THENL
   [USE_THEN "csmle" (DISJ_CASES_THEN2 ASSUME_TAC
      SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `sm:A`;
        `csm:A`] EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?qcsm:A. ecross D (E:A->A->bool) csm csm qcsm`
    (X_CHOOSE_TAC `qcsm:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(qcsm:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  USE_THEN "IH" (MP_TAC o SPEC `csm:A`) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "csminf" ACCEPT_TAC;
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `qcsm:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `g2:A`) THEN
  SUBGOAL_THEN `?g3:A. ebij D (E:A->A->bool) g3 qcsm smq`
    (X_CHOOSE_TAC `g3:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g1:A`; `csm:A`;
      `sm:A`; `qcsm:A`; `smq:A`] EBIJ_PRODMAP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [UNDISCH_TAC `ecross D (E:A->A->bool) csm csm qcsm` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        UNDISCH_TAC `ecross D (E:A->A->bool) sm sm smq` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?g4:A. ebij D (E:A->A->bool) g4 smq qcsm`
    (X_CHOOSE_TAC `g4:A`) THENL
   [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `?g5:A. ebij D (E:A->A->bool) g5 qcsm csm`
    (X_CHOOSE_TAC `g5:A`) THENL
   [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
  SUBGOAL_THEN `?h2:A. einj D (E:A->A->bool) h2 kk qcsm`
    (X_CHOOSE_TAC `h2:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `g4:A`;
      `kk:A`; `smq:A`; `qcsm:A`] EINJ_COMPOSE) THEN
