     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?h3:A. einj D (E:A->A->bool) h3 kk csm`
    (X_CHOOSE_TAC `h3:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h2:A`; `g5:A`;
      `kk:A`; `qcsm:A`; `csm:A`] EINJ_COMPOSE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `ecardof D (E:A->A->bool) kk kk` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h3:A`; `kk:A`;
    `csm:A`; `kk:A`] EINJ_ORDINAL_CARD_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `csm:A`]
      E_NOCYCLE2) THEN
    ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `csm:A`]
      E_IRREFL) THEN
    ASM_REWRITE_TAC[]]);;

let EPRODK_CARD = prove
 (`!D (E:A->A->bool) om kk q.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\
     ecross D E kk kk q
     ==> ?h. ebij D E h kk q`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 ge h4" THEN
  SUBGOAL_THEN `(kk:A) IN D /\ eordinal D (E:A->A->bool) kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
  DISCH_THEN(LABEL_TAC "nob") THEN
  SUBGOAL_THEN `valuation D ((10 |-> (om:A)) (\i:num. om:A))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c:A. c IN D
      ==> (holds D E ((0 |-> c) ((10 |-> (om:A)) (\i:num. om:A)))
             (ordinal_form 0 &&
              (((10 %% 0) || Eq 10 0) &&
               ((!! 2 ((2 %% 0) --> Not bijex20_form)) &&
                (!! 1 (cross_form 0 0 1 --> Not bijex_form))))) <=>
           eordinal D (E:A->A->bool) c /\
           ((E om c \/ om = c) /\
            ((!g. g IN D
                  ==> (E g c ==> ~(?f. ebij D E f g c))) /\
             (!q'. q' IN D
                   ==> (ecross D E c c q'
                        ==> ~(?f. ebij D E f c q'))))))`
  (LABEL_TAC "bb") THENL
   [X_GEN_TAC `c:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (c:A)) ((10 |-> (om:A)) (\i:num. om:A)))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_OR; HOLDS_NOT; holds] THEN
    MATCH_MP_TAC(TAUT
     `(p1 <=> q1) /\ (p2 <=> q2)
      ==> ((p1 /\ p2) <=> (q1 /\ q2))`) THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (c:A)) ((10 |-> (om:A)) (\i:num. om:A))`; `0`]
        HOLDS_ORDINAL_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p1 <=> q1) /\ (p2 <=> q2)
      ==> ((p1 /\ p2) <=> (q1 /\ q2))`) THEN CONJ_TAC THENL
     [REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p1 <=> q1) /\ (p2 <=> q2)
      ==> ((p1 /\ p2) <=> (q1 /\ q2))`) THEN CONJ_TAC THENL
     [MATCH_MP_TAC(MESON[]
       `(!g:A. P g <=> Q g) ==> ((!g:A. P g) <=> (!g:A. Q g))`) THEN
      X_GEN_TAC `g:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((2 |-> (g:A)) ((0 |-> (c:A))
          ((10 |-> (om:A)) (\i:num. om:A))))`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(2 |-> (g:A)) ((0 |-> (c:A)) ((10 |-> (om:A))
           (\i:num. om:A)))`] HOLDS_BIJEX20_EBIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MATCH_MP_TAC(MESON[]
       `(!x:A. P x <=> Q x) ==> ((!x:A. P x) <=> (!x:A. Q x))`) THEN
      X_GEN_TAC `q':A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((1 |-> (q':A)) ((0 |-> (c:A))
          ((10 |-> (om:A)) (\i:num. om:A))))`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (q':A)) ((0 |-> (c:A)) ((10 |-> (om:A))
           (\i:num. om:A)))`;
        `0`; `0`; `1`] HOLDS_CROSS_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (q':A)) ((0 |-> (c:A)) ((10 |-> (om:A))
           (\i:num. om:A)))`] HOLDS_BIJEX_EBIJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((0 |-> (kk:A)) ((10 |-> (om:A)) (\i:num. om:A)))
      (ordinal_form 0 &&
       (((10 %% 0) || Eq 10 0) &&
        ((!! 2 ((2 %% 0) --> Not bijex20_form)) &&
         (!! 1 (cross_form 0 0 1 --> Not bijex_form)))))`
  ASSUME_TAC THENL
   [USE_THEN "bb" (MP_TAC o SPEC `kk:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `g:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN
       `!c'. c' IN D /\ (E:A->A->bool) c' kk
             ==> ~(?f. ebij D E f c' kk)`
      MP_TAC THENL
       [UNDISCH_TAC `ecardinal D (E:A->A->bool) kk` THEN
        REWRITE_TAC[ecardinal; ecardof] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
          (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)));
        ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `g:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      X_GEN_TAC `q':A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `(q':A) = q` SUBST1_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `kk:A`;
          `q':A`; `q:A`] ECROSS_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      USE_THEN "nob" ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `ordinal_form 0 &&
     (((10 %% 0) || Eq 10 0) &&
      ((!! 2 ((2 %% 0) --> Not bijex20_form)) &&
       (!! 1 (cross_form 0 0 1 --> Not bijex_form))))`;
    `(10 |-> (om:A)) (\i:num. om:A)`; `kk:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@c0. h5 h6 + min" THEN
  USE_THEN "bb" (MP_TAC o SPEC `c0:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  INTRO_TAC "h7 gec cmin pbad" THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) c0` ASSUME_TAC THENL
   [REWRITE_TAC[ecardinal; ecardof] THEN ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c0:A`]
        EBIJ_ID) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      X_GEN_TAC `c':A` THEN STRIP_TAC THEN
      USE_THEN "cmin" (MP_TAC o SPEC `c':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!c. c IN D /\ (E:A->A->bool) c c0 /\ ecardinal D E c /\
        (E om c \/ om = c)
        ==> !q'. q' IN D /\ ecross D E c c q'
                 ==> ?g. ebij D E g c q'`
  (LABEL_TAC "IH2") THENL
   [X_GEN_TAC `c:A` THEN
    INTRO_TAC "h8 h9 h10 gec2" THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c` ASSUME_TAC THENL
     [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!g. g IN D ==> ((E:A->A->bool) g c ==> ~(?f. ebij D E f g c))`
    ASSUME_TAC THENL
     [X_GEN_TAC `g:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      UNDISCH_TAC `ecardinal D (E:A->A->bool) c` THEN
      REWRITE_TAC[ecardinal; ecardof] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
        (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
          (MP_TAC o SPEC `g:A`)))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "min" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "bb" (MP_TAC o SPEC `c:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[NOT_FORALL_THM] THEN
    DISCH_THEN(X_CHOOSE_THEN `q'':A` MP_TAC) THEN
    REWRITE_TAC[NOT_IMP; TAUT `~ ~p <=> p`] THEN
    INTRO_TAC "h11 h12 @g. h13" THEN
    X_GEN_TAC `q':A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `(q':A) = q''` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `c:A`;
        `q':A`; `q'':A`] ECROSS_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    EXISTS_TAC `g:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c0:A`]
    EPRODK_ENUM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@q1 r1 d1 f1. h14 q1c h15 r1c h16 h17 h18 enc1 f1b f1t f1i
             f1o" THEN
  SUBGOAL_THEN
   `!u u':A. u IN D /\ u' IN D /\ erel D (E:A->A->bool) r1 u u'
      ==> ~(erel D E r1 u' u)`
  (LABEL_TAC "asym1") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `u':A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) u q1 /\ E u' q1 /\ emlex D E u u'`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "r1c" (MP_TAC o SPECL [`u:A`; `u':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `erel D (E:A->A->bool) r1 u u'`))) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "q1c" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) u q1`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `ua:A` (X_CHOOSE_THEN `ub:A`
      STRIP_ASSUME_TAC)) THEN
    USE_THEN "q1c" (MP_TAC o SPEC `u':A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) u' q1`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `va:A` (X_CHOOSE_THEN `vb:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN
     `eordinal D (E:A->A->bool) ua /\ eordinal D E ub /\
      eordinal D E va /\ eordinal D E vb`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    USE_THEN "r1c" (MP_TAC o SPECL [`u':A`; `u:A`]) THEN
