(* ------------------------------------------------------------------------- *)
(* Injections lift to products: u : a >-> b and v : a' >-> b' give           *)
(* qa = a x a' >-> b x b' = qb via <x,y> |-> <u(x),v(y)> (EINJ_PRODMAP),     *)
(* and hence |a x b| <= kappa whenever a and b inject into an infinite       *)
(* cardinal kappa, by composing with the Jech bijection kappa x kappa ~      *)
(* kappa (ECROSS_CARD_LE).                                                   *)
(* ------------------------------------------------------------------------- *)

let EINJ_PRODMAP = prove
 (`!D (E:A->A->bool) u v a b a' b' qa qb.
     model D E ZF_AX /\ qa IN D /\ qb IN D /\
     einj D E u a b /\ einj D E v a' b' /\
     (!z. z IN D
          ==> (E z qa <=>
               ?x y. x IN D /\ y IN D /\ E x a /\ E y a' /\
                     eopair D E x y z)) /\
     (!z. z IN D
          ==> (E z qb <=>
               ?x y. x IN D /\ y IN D /\ E x b /\ E y b' /\
                     eopair D E x y z))
     ==> ?h. einj D E h qa qb`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 + + qa qb" THEN
  REWRITE_TAC[einj] THEN
  INTRO_TAC "h4 vb vt vs vi" THEN
  INTRO_TAC "h5 ub ut us ui" THEN
  SUBGOAL_THEN `valuation D ((8 |-> (v:A)) ((2 |-> (u:A)) (\i:num. u:A)))`
    ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!z w:A. z IN D /\ w IN D
      ==> (holds D E
           ((1 |-> w)
            ((0 |-> z) ((8 |-> (v:A)) ((2 |-> (u:A)) (\i:num. u:A)))))
           (?? 3 (?? 4 (opair_form 3 4 0 &&
               ?? 5 (?? 6 (apply_form 2 3 5 &&
                 (apply_form 8 4 6 &&
                  ?? 7 (opair_form 5 6 7 &&
                        opair_form 0 7 1))))))) <=>
           ?x. x IN D /\
               ?y. y IN D /\ eopair D (E:A->A->bool) x y z /\
                   ?s. s IN D /\
                       ?t. t IN D /\ eapply D E u x s /\
                           (eapply D E v y t /\
                            ?p. p IN D /\ eopair D E s t p /\
                                eopair D E z p w))`
  (LABEL_TAC "pm") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
