      REWRITE_TAC[eapply] THEN
      SUBGOAL_THEN `?pz:A. eopair D (E:A->A->bool) z w pz`
        (X_CHOOSE_TAC `pz:A`) THENL
       [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(pz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `pz:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "hch" (MP_TAC o SPEC `pz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "pm" (MP_TAC o SPECL [`z:A`; `pz:A`]) THEN
