    MAP_EVERY X_GEN_TAC [`z:A`; `w:A`; `w':A`] THEN
    INTRO_TAC "h28 h29 h30 + +" THEN
    USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `w':A`]) THEN
