      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(s':A) = s` SUBST_ALL_TAC THENL
     [USE_THEN "us" (MP_TAC o SPECL [`x:A`; `s':A`; `s:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(t':A) = t` SUBST_ALL_TAC THENL
     [USE_THEN "vs" (MP_TAC o SPECL [`y:A`; `t':A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s:A`; `t:A`;
                  `w:A`; `w':A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`z:A`; `z':A`; `w:A`] THEN
    INTRO_TAC "h31 h32 h33 + +" THEN
    USE_THEN "hc" (MP_TAC o SPECL [`z':A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `x':A`
      (X_CHOOSE_THEN `y':A` (X_CHOOSE_THEN `s':A`
        (X_CHOOSE_THEN `t':A` STRIP_ASSUME_TAC))))) THEN
    USE_THEN "hc" (MP_TAC o SPECL [`z:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `x:A`
      (X_CHOOSE_THEN `y:A` (X_CHOOSE_THEN `s:A` (X_CHOOSE_THEN `t:A`
        STRIP_ASSUME_TAC))))) THEN
    SUBGOAL_THEN `(s':A) = s /\ (t':A) = t`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s':A`; `t':A`;
                    `s:A`; `t:A`; `w:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
