      ALL_TAC] THEN
    SUBGOAL_THEN `(y':A) = y` SUBST_ALL_TAC THENL
     [USE_THEN "vi" (MP_TAC o SPECL [`y':A`; `y:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `y:A`;
                  `z':A`; `z:A`] EOPAIR_UNIQUE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

let ECROSS_CARD_LE = prove
 (`!D (E:A->A->bool) om kk a b q u v.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\
     a IN D /\ b IN D /\ q IN D /\ ecross D E a b q /\
     einj D E u a kk /\ einj D E v b kk
     ==> ?h. einj D E h q kk`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 h4 h5 h6 h7 h8 h9 h10" THEN
  SUBGOAL_THEN `(kk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `?qk:A. ecross D (E:A->A->bool) kk kk qk`
    (X_CHOOSE_TAC `qk:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(qk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `?h1:A. einj D (E:A->A->bool) h1 q qk`
    (X_CHOOSE_TAC `h1:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `v:A`;
      `a:A`; `kk:A`; `b:A`; `kk:A`; `q:A`; `qk:A`]
      EINJ_PRODMAP) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [UNDISCH_TAC `ecross D (E:A->A->bool) a b q` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        UNDISCH_TAC `ecross D (E:A->A->bool) kk kk qk` THEN
        REWRITE_TAC[ecross] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)];
      ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?g:A. ebij D (E:A->A->bool) g kk qk`
    (X_CHOOSE_TAC `g:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`;
      `qk:A`] EPRODK_CARD) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?g':A. ebij D (E:A->A->bool) g' qk kk`
    (X_CHOOSE_TAC `g':A`) THENL
   [ASM_MESON_TAC[EBIJ_SYM]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h1:A`; `g':A`;
    `q:A`; `qk:A`; `kk:A`] EINJ_COMPOSE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Sets of finite sequences: for any x and n the set of functions n -> x     *)
(* (with values in x) exists, by separation from P(n x x); likewise the set  *)
(* of all finite sequences from x (functions with domain some n in omega),   *)
(* by separation from P(omega x x). These carry the valuation-restriction    *)
(* keys of definable sets, en route to |Def(x)| <= max(|x|, omega).          *)
(* ------------------------------------------------------------------------- *)

let ESEQSET_EXISTS = prove
 (`!D (E:A->A->bool) x n.
     model D E ZF_AX /\ x IN D /\ n IN D
     ==> ?q. q IN D /\
             !r. r IN D
                 ==> (E r q <=>
                      eisfun D E r /\ edomain D E r n /\
                      !i u. i IN D /\ u IN D /\ eapply D E r i u
                            ==> E u x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?prod:A. ecross D (E:A->A->bool) n x prod`
    (X_CHOOSE_TAC `prod:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(prod:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z prod <=>
               ?i u. i IN D /\ u IN D /\ E i n /\ E u x /\
                     eopair D E i u z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "pc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) n x prod` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?pws:A. epow D (E:A->A->bool) prod pws`
    (X_CHOOSE_TAC `pws:A`) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pws:A) IN D /\
    !w:A. w IN D
          ==> ((E:A->A->bool) w pws <=> esubset D E w prod)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "powc")) THENL
   [UNDISCH_TAC `epow D (E:A->A->bool) prod pws` THEN
    REWRITE_TAC[epow] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((5 |-> (x:A)) ((2 |-> (n:A)) v0))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r:A. r IN D
      ==> (holds D E ((0 |-> r) ((5 |-> (x:A)) ((2 |-> (n:A)) v0)))
             (fun_form 0 &&
              (domain_form 0 2 &&
               !! 3 (!! 4 (apply_form 0 3 4 --> (4 %% 5))))) <=>
           eisfun D (E:A->A->bool) r /\ edomain D E r n /\
           !i. i IN D
               ==> !u. u IN D
                       ==> (eapply D E r i u ==> E u x))`
  (LABEL_TAC "sb") THENL
   [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (r:A)) ((5 |-> (x:A)) ((2 |-> (n:A))
        v0)))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; holds] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (r:A)) ((5 |-> (x:A)) ((2 |-> (n:A)) v0))`;
      `0`] HOLDS_FUN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (r:A)) ((5 |-> (x:A)) ((2 |-> (n:A)) v0))`;
      `0`; `2`] HOLDS_DOMAIN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> q) ==> ((c1 /\ c2 /\ p) <=> (c1 /\ c2 /\ q))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!i:A. P i <=> Q i) ==> ((!i:A. P i) <=> (!i:A. Q i))`) THEN
    X_GEN_TAC `i:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!u:A. P u <=> Q u) ==> ((!u:A. P u) <=> (!u:A. Q u))`) THEN
    X_GEN_TAC `u:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') ==> ((p ==> q) <=> (p' ==> q))`) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (u:A)) ((3 |-> (i:A)) ((0 |-> (r:A)) ((5 |-> (x:A))
         ((2 |-> (n:A)) v0))))`;
      `0`; `3`; `4`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`fun_form 0 &&
      (domain_form 0 2 &&
       !! 3 (!! 4 (apply_form 0 3 4 --> (4 %% 5))))`;
     `0`; `(5 |-> (x:A)) ((2 |-> (n:A)) v0)`; `pws:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `q:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "qch"))) THEN
  EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `r:A` THEN DISCH_TAC THEN
  USE_THEN "qch" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "sb" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "_ h1 h2 vals" THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`i:A`; `u:A`] THEN STRIP_TAC THEN
    USE_THEN "vals" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC (LABEL_TAC "vals"))) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "powc" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[esubset] THEN
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?i u:A. i IN D /\ u IN D /\ eopair D (E:A->A->bool) i u z`
      (X_CHOOSE_THEN `i:A` (X_CHOOSE_THEN `u:A`
        STRIP_ASSUME_TAC)) THENL
       [UNDISCH_TAC `eisfun D (E:A->A->bool) r` THEN
        REWRITE_TAC[eisfun] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
          (MP_TAC o SPEC `z:A`) (K ALL_TAC))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) r i u` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "pc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`i:A`; `u:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [UNDISCH_TAC `edomain D (E:A->A->bool) r n` THEN
        REWRITE_TAC[edomain] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
          (MP_TAC o SPEC `i:A`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        REWRITE_TAC[eindom] THEN EXISTS_TAC `u:A` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "vals" (MP_TAC o SPECL [`i:A`; `u:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC];
      X_GEN_TAC `i:A` THEN DISCH_TAC THEN
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      USE_THEN "vals" (MP_TAC o SPECL [`i:A`; `u:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC]]);;

let EFINSEQ_EXISTS = prove
 (`!D (E:A->A->bool) om x.
     model D E ZF_AX /\ eomega D E om /\ x IN D
     ==> ?fs. fs IN D /\
              !r. r IN D
                  ==> (E r fs <=>
                       eisfun D E r /\
                       (?n. n IN D /\ E n om /\ edomain D E r n) /\
                       !i u. i IN D /\ u IN D /\ eapply D E r i u
                             ==> E u x)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `?prod:A. ecross D (E:A->A->bool) om x prod`
    (X_CHOOSE_TAC `prod:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(prod:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z prod <=>
               ?i u. i IN D /\ u IN D /\ E i om /\ E u x /\
                     eopair D E i u z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "pc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) om x prod` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?pws:A. epow D (E:A->A->bool) prod pws`
    (X_CHOOSE_TAC `pws:A`) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pws:A) IN D /\
    !w:A. w IN D
          ==> ((E:A->A->bool) w pws <=> esubset D E w prod)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "powc")) THENL
   [UNDISCH_TAC `epow D (E:A->A->bool) prod pws` THEN
    REWRITE_TAC[epow] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((6 |-> (om:A)) ((5 |-> (x:A)) v0))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r:A. r IN D
      ==> (holds D E ((0 |-> r) ((6 |-> (om:A)) ((5 |-> (x:A))
             v0)))
             (fun_form 0 &&
              ((?? 2 ((2 %% 6) && domain_form 0 2)) &&
               !! 3 (!! 4 (apply_form 0 3 4 --> (4 %% 5))))) <=>
           eisfun D (E:A->A->bool) r /\
           (?n. n IN D /\ E n om /\ edomain D E r n) /\
           !i. i IN D
               ==> !u. u IN D
                       ==> (eapply D E r i u ==> E u x))`
  (LABEL_TAC "sb") THENL
   [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (r:A)) ((6 |-> (om:A)) ((5 |-> (x:A))
        v0)))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND; HOLDS_EX; holds] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (r:A)) ((6 |-> (om:A)) ((5 |-> (x:A)) v0))`;
      `0`] HOLDS_FUN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT
     `(p1 <=> q1) /\ (p2 <=> q2)
      ==> ((c /\ p1 /\ p2) <=> (c /\ q1 /\ q2))`) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(MESON[]
       `(!n:A. P n <=> Q n) ==> ((?n:A. P n) <=> (?n:A. Q n))`) THEN
      X_GEN_TAC `nn:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((2 |-> (nn:A)) ((0 |-> (r:A)) ((6 |-> (om:A))
          ((5 |-> (x:A)) v0))))`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(2 |-> (nn:A)) ((0 |-> (r:A)) ((6 |-> (om:A))
           ((5 |-> (x:A)) v0)))`;
        `0`; `2`] HOLDS_DOMAIN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MATCH_MP_TAC(MESON[]
       `(!i:A. P i <=> Q i) ==> ((!i:A. P i) <=> (!i:A. Q i))`) THEN
      X_GEN_TAC `i:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(MESON[]
       `(!u:A. P u <=> Q u) ==> ((!u:A. P u) <=> (!u:A. Q u))`) THEN
      X_GEN_TAC `u:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(TAUT
       `(p <=> p') ==> ((p ==> q) <=> (p' ==> q))`) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(4 |-> (u:A)) ((3 |-> (i:A)) ((0 |-> (r:A))
           ((6 |-> (om:A)) ((5 |-> (x:A)) v0))))`;
        `0`; `3`; `4`] HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`fun_form 0 &&
      ((?? 2 ((2 %% 6) && domain_form 0 2)) &&
       !! 3 (!! 4 (apply_form 0 3 4 --> (4 %% 5))))`;
     `0`; `(6 |-> (om:A)) ((5 |-> (x:A)) v0)`; `pws:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "qch"))) THEN
  EXISTS_TAC `fs:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `r:A` THEN DISCH_TAC THEN
  USE_THEN "qch" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "sb" (MP_TAC o SPEC `r:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [INTRO_TAC "_ h1 h2 vals" THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`i:A`; `u:A`] THEN STRIP_TAC THEN
    USE_THEN "vals" (MP_TAC o SPEC `i:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      (X_CHOOSE_THEN `n:A` STRIP_ASSUME_TAC)
      (LABEL_TAC "vals"))) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [USE_THEN "powc" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[esubset] THEN
      X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `?i u:A. i IN D /\ u IN D /\ eopair D (E:A->A->bool) i u z`
      (X_CHOOSE_THEN `i:A` (X_CHOOSE_THEN `u:A`
        STRIP_ASSUME_TAC)) THENL
       [UNDISCH_TAC `eisfun D (E:A->A->bool) r` THEN
        REWRITE_TAC[eisfun] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
          (MP_TAC o SPEC `z:A`) (K ALL_TAC))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) r i u` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "pc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`i:A`; `u:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [SUBGOAL_THEN `(E:A->A->bool) i n` ASSUME_TAC THENL
         [UNDISCH_TAC `edomain D (E:A->A->bool) r n` THEN
          REWRITE_TAC[edomain] THEN
          DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
            (MP_TAC o SPEC `i:A`)) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          REWRITE_TAC[eindom] THEN EXISTS_TAC `u:A` THEN
          ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `n:A`;
          `i:A`] EOMEGA_TRANS) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        USE_THEN "vals" (MP_TAC o SPECL [`i:A`; `u:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC];
      CONJ_TAC THENL
       [EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[];
        X_GEN_TAC `i:A` THEN DISCH_TAC THEN
        X_GEN_TAC `u:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        USE_THEN "vals" (MP_TAC o SPECL [`i:A`; `u:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC]]]);;

(* ------------------------------------------------------------------------- *)
(* The append bijection: sequences of length suc(n) from x correspond to     *)
(* pairs (sequence of length n, top value) via r |-> <r|n, r(n)>. ESEQ_EXT   *)
(* (two length-suc(n) functions with the same restriction and top value are  *)
(* equal, by extensionality) gives injectivity; ESEQ_EXTEND (adjoin <n,vl>   *)
(* to a length-n sequence) gives surjectivity.                               *)
(* ------------------------------------------------------------------------- *)

let ESEQ_EXT = prove
 (`!D (E:A->A->bool) n sn r r' rs vl.
     model D E ZF_AX /\ n IN D /\ esuc D E n sn /\
     r IN D /\ r' IN D /\ rs IN D /\ vl IN D /\
     eisfun D E r /\ edomain D E r sn /\
     eisfun D E r' /\ edomain D E r' sn /\
     erestrict D E r n rs /\ erestrict D E r' n rs /\
     eapply D E r n vl /\ eapply D E r' n vl
     ==> r = r'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!rr rr':A.
      rr IN D /\ rr' IN D /\
      eisfun D (E:A->A->bool) rr /\ edomain D E rr sn /\
      eisfun D E rr' /\ edomain D E rr' sn /\
      erestrict D E rr n rs /\ erestrict D E rr' n rs /\
      eapply D E rr n vl /\ eapply D E rr' n vl
      ==> !z. z IN D /\ E z rr ==> E z rr'`
  (LABEL_TAC "half") THENL
   [MAP_EVERY X_GEN_TAC [`rr:A`; `rr':A`] THEN STRIP_TAC THEN
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `?i u:A. i IN D /\ u IN D /\ eopair D (E:A->A->bool) i u z`
    (X_CHOOSE_THEN `i:A` (X_CHOOSE_THEN `u:A`
      STRIP_ASSUME_TAC)) THENL
     [UNDISCH_TAC `eisfun D (E:A->A->bool) rr` THEN
      REWRITE_TAC[eisfun] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
        (MP_TAC o SPEC `z:A`) (K ALL_TAC))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) rr i u` ASSUME_TAC THENL
     [REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) i sn` ASSUME_TAC THENL
     [UNDISCH_TAC `edomain D (E:A->A->bool) rr sn` THEN
      REWRITE_TAC[edomain] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (MP_TAC o SPEC `i:A`)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `u:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) i n \/ (i:A) = n` MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`]
        ESUC_ALT) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
        (ASSUME `esuc D (E:A->A->bool) n sn`)))) THEN
      DISCH_THEN(MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
     [SUBGOAL_THEN `(E:A->A->bool) z rs` ASSUME_TAC THENL
       [UNDISCH_TAC `erestrict D (E:A->A->bool) rr n rs` THEN
        REWRITE_TAC[erestrict] THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
          (MP_TAC o SPEC `z:A`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[] THEN
        MAP_EVERY EXISTS_TAC [`i:A`; `u:A`] THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      UNDISCH_TAC `erestrict D (E:A->A->bool) rr' n rs` THEN
      REWRITE_TAC[erestrict] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (MP_TAC o SPEC `z:A`)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) z rs`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC));
      SUBGOAL_THEN `(u:A) = vl` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `rr:A`; `n:A`;
          `u:A`; `vl:A`] EAPPLY_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) rr' n vl` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z':A`
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z':A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) = z'` SUBST1_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `vl:A`;
          `z:A`; `z':A`] EOPAIR_UNIQUE) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
   [DISCH_TAC THEN
    USE_THEN "half" (MP_TAC o SPECL [`r:A`; `r':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    DISCH_TAC THEN
    USE_THEN "half" (MP_TAC o SPECL [`r':A`; `r:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

let ESEQ_EXTEND = prove
 (`!D (E:A->A->bool) x n sn rs vl.
     model D E ZF_AX /\ x IN D /\ n IN D /\ esuc D E n sn /\
     rs IN D /\ vl IN D /\ E vl x /\
     eisfun D E rs /\ edomain D E rs n /\
     (!i u. i IN D /\ u IN D /\ eapply D E rs i u ==> E u x)
     ==> ?r. r IN D /\ eisfun D E r /\ edomain D E r sn /\
             (!i u. i IN D /\ u IN D /\ eapply D E r i u
                    ==> E u x) /\
             erestrict D E r n rs /\ eapply D E r n vl`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 rsv" THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w sn <=> E w n \/ w = n)`
  (LABEL_TAC "snc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`]
      ESUC_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
      (ASSUME `esuc D (E:A->A->bool) n sn`)))) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!i:A. i IN D ==> ((E:A->A->bool) i n <=> eindom D E rs i)`
  (LABEL_TAC "rsd") THENL
   [UNDISCH_TAC `edomain D (E:A->A->bool) rs n` THEN
    REWRITE_TAC[edomain] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ~(eapply D (E:A->A->bool) rs n w)`
  (LABEL_TAC "nind") THENL
   [X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) n n` ASSUME_TAC THENL
     [USE_THEN "rsd" (MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `w:A` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
