               eisfun D E r /\ edomain D E r n /\
               !i u. i IN D /\ u IN D /\ eapply D E r i u
                     ==> E u x)) /\
     qsn IN D /\
     (!r. r IN D
          ==> (E r qsn <=>
               eisfun D E r /\ edomain D E r sn /\
               !i u. i IN D /\ u IN D /\ eapply D E r i u
                     ==> E u x)) /\
     pq IN D /\
     (!z. z IN D
          ==> (E z pq <=>
               ?r u. r IN D /\ u IN D /\ E r qn /\ E u x /\
                     eopair D E r u z))
     ==> ?h. ebij D E h qsn pq`,
