    SUBGOAL_THEN `(E:A->A->bool) r qsn` ASSUME_TAC THENL
     [USE_THEN "qsc" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN USE_THEN "rv2" ACCEPT_TAC;
      ALL_TAC] THEN
    EXISTS_TAC `r:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "hc" (MP_TAC o SPECL [`r:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`rt:A`; `vl:A`] THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Every finite power x^n injects into an infinite cardinal kappa that x     *)
(* injects into: internal omega-induction with the injex_form bridge; base   *)
(* via the subsingleton x^0 = {empty function} (ESEQ_ZERO_SUB/ESUBSING_INJ), *)
(* step via the append bijection and ECROSS_CARD_LE.                         *)
(* ------------------------------------------------------------------------- *)

let ESEQ_ZERO_SUB = prove
 (`!D (E:A->A->bool) x z0 q.
     model D E ZF_AX /\ x IN D /\ eempty D E z0 /\ q IN D /\
     (!r. r IN D
          ==> (E r q <=>
               eisfun D E r /\ edomain D E r z0 /\
               !i u. i IN D /\ u IN D /\ eapply D E r i u
                     ==> E u x))
     ==> !r r'. r IN D /\ r' IN D /\ E r q /\ E r' q ==> r = r'`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 qc" THEN
  SUBGOAL_THEN
   `!rr:A. rr IN D /\ (E:A->A->bool) rr q
      ==> !z. z IN D ==> ~(E z rr)`
  (LABEL_TAC "emp") THENL
   [X_GEN_TAC `rr:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `eisfun D (E:A->A->bool) rr /\ edomain D E rr z0`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "qc" (MP_TAC o SPEC `rr:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) rr q`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
        ASSUME_TAC (K ALL_TAC))) THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `?i u:A. i IN D /\ u IN D /\ eopair D (E:A->A->bool) i u z`
    (X_CHOOSE_THEN `i:A` (X_CHOOSE_THEN `u:A`
      STRIP_ASSUME_TAC)) THENL
     [UNDISCH_TAC `eisfun D (E:A->A->bool) rr` THEN
      REWRITE_TAC[eisfun] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2
        (MP_TAC o SPEC `z:A`) (K ALL_TAC))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) i z0` ASSUME_TAC THENL
     [UNDISCH_TAC `edomain D (E:A->A->bool) rr z0` THEN
      REWRITE_TAC[edomain] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
        (MP_TAC o SPEC `i:A`)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[eindom] THEN EXISTS_TAC `u:A` THEN
      REWRITE_TAC[eapply] THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    UNDISCH_TAC `eempty D (E:A->A->bool) z0` THEN
    REWRITE_TAC[eempty] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (MP_TAC o SPEC `i:A`)) THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`r:A`; `r':A`] THEN STRIP_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `~((E:A->A->bool) z r) /\ ~(E z r')`
  STRIP_ASSUME_TAC THENL
   [CONJ_TAC THENL
     [USE_THEN "emp" (MP_TAC o SPEC `r:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      USE_THEN "emp" (MP_TAC o SPEC `r':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let ESUBSING_INJ = prove
 (`!D (E:A->A->bool) q y c.
     model D E ZF_AX /\ q IN D /\ y IN D /\ c IN D /\ E c y /\
     (!r r'. r IN D /\ r' IN D /\ E r q /\ E r' q ==> r = r')
     ==> ?e. einj D E e q y`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 ss" THEN
  SUBGOAL_THEN `?sg:A. epair D (E:A->A->bool) c c sg`
    (X_CHOOSE_TAC `sg:A`) THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w sg <=> w = c)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sgc")) THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) c c sg` THEN
    REWRITE_TAC[epair] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ec")) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "ec" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?ec:A. ecross D (E:A->A->bool) q sg ec`
    (X_CHOOSE_TAC `ec:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(ec:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z ec <=>
               ?r u. r IN D /\ u IN D /\ E r q /\ E u sg /\
                     eopair D E r u z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ecc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) q sg ec` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r w:A. r IN D /\ w IN D
      ==> (eapply D (E:A->A->bool) ec r w <=> E r q /\ w = c)`
  (LABEL_TAC "apc") THENL
   [MAP_EVERY X_GEN_TAC [`r:A`; `w:A`] THEN STRIP_TAC THEN
    EQ_TAC THENL
     [REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A`
        (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "ecc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) z ec`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `r0:A` (X_CHOOSE_THEN `u0:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(u0:A) = c` SUBST_ALL_TAC THENL
       [USE_THEN "sgc" (MP_TAC o SPEC `u0:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `(E:A->A->bool) u0 sg`))) THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r0:A`; `c:A`;
        `r:A`; `w:A`; `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 SUBST_ALL_TAC
        (SUBST_ALL_TAC o SYM)) THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
      REWRITE_TAC[eapply] THEN
      SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) r c z`
        (X_CHOOSE_TAC `z:A`) THENL
       [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ecc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`r:A`; `c:A`] THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "sgc" (MP_TAC o SPEC `c:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `ec:A` THEN REWRITE_TAC[einj] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`r:A`; `w:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC MP_TAC)) THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
    ASM_REWRITE_TAC[];
    X_GEN_TAC `r:A` THEN STRIP_TAC THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r:A`; `c:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`r:A`; `w:A`; `w':A`] THEN
    INTRO_TAC "h6 h7 h8 + +" THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC SUBST1_TAC) THEN
    REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`r:A`; `r':A`; `w:A`] THEN
    INTRO_TAC "h9 h10 h11 + +" THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r':A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC)) THEN
    USE_THEN "apc" (MP_TAC o SPECL [`r:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (K ALL_TAC)) THEN
    USE_THEN "ss" (MP_TAC o SPECL [`r:A`; `r':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC]);;

let ESEQ_INJEX = prove
 (`!D (E:A->A->bool) om x kk ei n q.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\
     x IN D /\ einj D E ei x kk /\
     n IN D /\ E n om /\ q IN D /\
     (!r. r IN D
          ==> (E r q <=>
               eisfun D E r /\ edomain D E r n /\
               !i u. i IN D /\ u IN D /\ eapply D E r i u
                     ==> E u x))
     ==> ?e. einj D E e q kk`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 ge h4 h5 h6 h7 h8 qc" THEN
  SUBGOAL_THEN `(kk:A) IN D /\ eordinal D (E:A->A->bool) kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((6 |-> (x:A)) ((1 |-> (kk:A)) (\i:num. kk:A)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn:A. nn IN D
      ==> (holds D E ((2 |-> nn) ((6 |-> (x:A)) ((1 |-> (kk:A))
             (\i:num. kk:A))))
             (!! 0 ((!! 3 ((3 %% 0) <->
                (fun_form 3 &&
                 (domain_form 3 2 &&
                  !! 4 (!! 5 (apply_form 3 4 5 --> (5 %% 6)))))))
               --> injex_form)) <=>
           !qq. qq IN D
                ==> ((!r. r IN D
                          ==> (E r qq <=>
                               eisfun D (E:A->A->bool) r /\
                               (edomain D E r nn /\
                                !i. i IN D
                                    ==> !u. u IN D
                                            ==> (eapply D E r i u
                                                 ==> E u x))))
                     ==> ?f. einj D E f qq kk))`
  (LABEL_TAC "sq") THENL
   [X_GEN_TAC `nn:A` THEN DISCH_TAC THEN
    REWRITE_TAC[holds; HOLDS_AND; HOLDS_IFF] THEN
    MATCH_MP_TAC(MESON[]
     `(!q:A. P q <=> Q q) ==> ((!q:A. P q) <=> (!q:A. Q q))`) THEN
    X_GEN_TAC `qq:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (qq:A)) ((2 |-> (nn:A)) ((6 |-> (x:A))
        ((1 |-> (kk:A)) (\i:num. kk:A)))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> p') /\ (q <=> q')
      ==> ((p ==> q) <=> (p' ==> q'))`) THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(MESON[]
       `(!r:A. P r <=> Q r) ==> ((!r:A. P r) <=> (!r:A. Q r))`) THEN
      X_GEN_TAC `rr:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      SUBGOAL_THEN
       `valuation D ((3 |-> (rr:A)) ((0 |-> (qq:A)) ((2 |-> (nn:A))
          ((6 |-> (x:A)) ((1 |-> (kk:A)) (\i:num. kk:A))))))`
      ASSUME_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MATCH_MP_TAC(TAUT
       `(l <=> l') /\ (r <=> r')
        ==> ((l <=> r) <=> (l' <=> r'))`) THEN
      CONJ_TAC THENL
       [REWRITE_TAC[VALMOD] THEN
        CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
        REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(3 |-> (rr:A)) ((0 |-> (qq:A)) ((2 |-> (nn:A))
           ((6 |-> (x:A)) ((1 |-> (kk:A)) (\i:num. kk:A)))))`;
        `3`] HOLDS_FUN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(3 |-> (rr:A)) ((0 |-> (qq:A)) ((2 |-> (nn:A))
           ((6 |-> (x:A)) ((1 |-> (kk:A)) (\i:num. kk:A)))))`;
        `3`; `2`] HOLDS_DOMAIN_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[] THEN
      MATCH_MP_TAC(TAUT
       `(p <=> q) ==> ((c1 /\ c2 /\ p) <=> (c1 /\ c2 /\ q))`) THEN
      MATCH_MP_TAC(MESON[]
       `(!i:A. P i <=> Q i) ==> ((!i:A. P i) <=> (!i:A. Q i))`) THEN
      X_GEN_TAC `i:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(MESON[]
       `(!u:A. P u <=> Q u) ==> ((!u:A. P u) <=> (!u:A. Q u))`) THEN
      X_GEN_TAC `u:A` THEN
      MATCH_MP_TAC(TAUT
       `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
      DISCH_TAC THEN
      MATCH_MP_TAC(TAUT
       `(p <=> p') ==> ((p ==> q) <=> (p' ==> q))`) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(5 |-> (u:A)) ((4 |-> (i:A)) ((3 |-> (rr:A))
           ((0 |-> (qq:A)) ((2 |-> (nn:A)) ((6 |-> (x:A))
              ((1 |-> (kk:A)) (\i:num. kk:A)))))))`;
        `3`; `4`; `5`] HOLDS_APPLY_FORM) THEN
      ANTS_TAC THENL
       [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
        MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (qq:A)) ((2 |-> (nn:A)) ((6 |-> (x:A))
           ((1 |-> (kk:A)) (\i:num. kk:A))))`]
        HOLDS_INJEX_EINJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
      REWRITE_TAC[]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 0 ((!! 3 ((3 %% 0) <->
       (fun_form 3 &&
        (domain_form 3 2 &&
         !! 4 (!! 5 (apply_form 3 4 5 --> (5 %% 6)))))))
      --> injex_form)`;
    `2`; `(6 |-> (x:A)) ((1 |-> (kk:A)) (\i:num. kk:A))`]
    EOMEGA_INDUCT) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `ee:A` THEN DISCH_TAC THEN
      SUBGOAL_THEN `(ee:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
      USE_THEN "sq" (MP_TAC o SPEC `ee:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `qq:A` THEN DISCH_TAC THEN
      DISCH_THEN(LABEL_TAC "cc") THEN
      SUBGOAL_THEN
       `!r:A. r IN D
          ==> ((E:A->A->bool) r qq <=>
               eisfun D E r /\ edomain D E r ee /\
               !i w. i IN D /\ w IN D /\ eapply D E r i w
                     ==> E w x)`
      (LABEL_TAC "cf") THENL
       [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
        USE_THEN "cc" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MESON_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) ee kk` ASSUME_TAC THENL
       [SUBGOAL_THEN `(E:A->A->bool) ee om` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
        USE_THEN "ge" (DISJ_CASES_THEN2 ASSUME_TAC
          (SUBST_ALL_TAC o SYM)) THENL
         [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`;
            `om:A`; `ee:A`] EORDINAL_TRANS_MEM) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN ACCEPT_TAC;
          ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `ee:A`;
        `qq:A`] ESEQ_ZERO_SUB) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "cf" ACCEPT_TAC;
        ALL_TAC] THEN
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `qq:A`; `kk:A`;
        `ee:A`] ESUBSING_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      MAP_EVERY X_GEN_TAC [`u:A`; `s:A`] THEN
      INTRO_TAC "h9 h10 + h11" THEN
      USE_THEN "sq" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN(LABEL_TAC "IH") THEN
      SUBGOAL_THEN `(s:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
      USE_THEN "sq" (MP_TAC o SPEC `s:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      X_GEN_TAC `qq:A` THEN DISCH_TAC THEN
      DISCH_THEN(LABEL_TAC "cc") THEN
      SUBGOAL_THEN
       `!r:A. r IN D
          ==> ((E:A->A->bool) r qq <=>
               eisfun D E r /\ edomain D E r s /\
               !i w. i IN D /\ w IN D /\ eapply D E r i w
                     ==> E w x)`
      (LABEL_TAC "cf") THENL
       [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
        USE_THEN "cc" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MESON_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u:A`]
        ESEQSET_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `qu:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (LABEL_TAC "quf"))) THEN
      SUBGOAL_THEN
       `!r:A. r IN D
          ==> ((E:A->A->bool) r qu <=>
               eisfun D E r /\
               (edomain D E r u /\
                !i. i IN D
                    ==> !w. w IN D
                            ==> (eapply D E r i w ==> E w x)))`
      (LABEL_TAC "quc") THENL
       [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
        USE_THEN "quf" (MP_TAC o SPEC `r:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        MESON_TAC[];
        ALL_TAC] THEN
      USE_THEN "IH" (MP_TAC o SPEC `qu:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [USE_THEN "quc" ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `en:A`) THEN
      SUBGOAL_THEN `?pq:A. ecross D (E:A->A->bool) qu x pq`
        (X_CHOOSE_TAC `pq:A`) THENL
       [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(pq:A) IN D /\
        !z:A. z IN D
              ==> ((E:A->A->bool) z pq <=>
                   ?r w. r IN D /\ w IN D /\ E r qu /\ E w x /\
                         eopair D E r w z)`
      (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "pqc")) THENL
       [UNDISCH_TAC `ecross D (E:A->A->bool) qu x pq` THEN
        REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u:A`;
        `s:A`; `qu:A`; `qq:A`; `pq:A`] ESEQ_SUC_BIJ) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN
        FIRST [ASM_REWRITE_TAC[] THEN NO_TAC;
               USE_THEN "quf" ACCEPT_TAC;
               USE_THEN "cf" ACCEPT_TAC;
               USE_THEN "pqc" ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `hb:A`) THEN
      SUBGOAL_THEN `?hp:A. einj D (E:A->A->bool) hp pq kk`
        (X_CHOOSE_TAC `hp:A`) THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`;
          `qu:A`; `x:A`; `pq:A`; `en:A`; `ei:A`]
          ECROSS_CARD_LE) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN
          FIRST [ASM_REWRITE_TAC[] THEN NO_TAC;
                 USE_THEN "lm" ACCEPT_TAC;
                 USE_THEN "ge" ACCEPT_TAC];
          ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `?hq:A. einj D (E:A->A->bool) hq qq pq`
        (X_CHOOSE_TAC `hq:A`) THENL
       [EXISTS_TAC `hb:A` THEN MATCH_MP_TAC EBIJ_EINJ THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hq:A`; `hp:A`;
        `qq:A`; `pq:A`; `kk:A`] EINJ_COMPOSE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "sq" (MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(MP_TAC o SPEC `q:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL
   [X_GEN_TAC `r:A` THEN DISCH_TAC THEN
    USE_THEN "qc" (MP_TAC o SPEC `r:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MESON_TAC[];
    ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* Union bound for an infinite cardinal kk (EGEN_UNION_CARD_LE): if a >-> kk *)
(* and ff is a function graph such that every ff(b) with b<a is a subset of  *)
(* ya and injects into kk, then UNION_{b<a} ff(b) >-> kk.  The finite        *)
(* sequences FS(x) = UNION_{n<om} x^n (EFINSEQ_CARD_LE) and the union        *)
(* UNION_{b<a} L(b) of earlier L-stages (ESLWU_CARD_LE) are instances.       *)
(* ------------------------------------------------------------------------- *)

(* ------------------------------------------------------------------------- *)
(* The internal formula injform internalizes "e injects x into y" (with e,   *)
(* x, y in slots 30, 32, 33). HOLDS_INJFORM: its satisfaction under a        *)
(* valuation coincides with the semantic injection predicate einj on the     *)
(* parameter values.                                                         *)
(* ------------------------------------------------------------------------- *)

let injform = new_definition
  `injform =
     (!! 0 (!! 1 (apply_form 30 0 1 --> (0 %% 32) && (1 %% 33)))) &&
     (!! 0 ((0 %% 32) --> ?? 1 ((1 %% 33) && apply_form 30 0 1))) &&
     (!! 0 (!! 1
            (!! 3 (apply_form 30 0 1 && apply_form 30 0 3 --> Eq 1 3)))) &&
     (!! 0 (!! 2
            (!! 1 (apply_form 30 0 1 && apply_form 30 2 1 --> Eq 0 2))))`;;

let HOLDS_INJFORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v injform <=> einj D E (v 30) (v 32) (v 33))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a a'. a IN D /\ a' IN D
           ==> (holds D E ((1 |-> (a':A)) ((0 |-> (a:A)) (v:num->A)))
                (apply_form 30 0 1) <=>
                eapply D E (v 30) a a')`
  (LABEL_TAC "bA") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL
           [`D:A->bool`; `E:A->A->bool`;
            `(1 |-> (a':A)) ((0 |-> (a:A)) (v:num->A))`;
            `30`; `0`; `1`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(30 = 1) /\ ~(30 = 0) /\ ~(0 = 1)`];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. a IN D /\ b IN D /\ c IN D
            ==> (holds D E
                 ((3 |-> (c:A)) ((1 |-> (b:A)) ((0 |-> (a:A)) (v:num->A))))
                 (apply_form 30 0 1) <=> eapply D E (v 30) a b) /\
                (holds D E
                 ((3 |-> (c:A)) ((1 |-> (b:A)) ((0 |-> (a:A)) (v:num->A))))
                 (apply_form 30 0 3) <=> eapply D E (v 30) a c)`
  (LABEL_TAC "bSV") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(3 |-> (c:A)) ((1 |-> (b:A)) ((0 |-> (a:A)) (v:num->A)))`; `30`; `0`;
        `1`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(3 |-> (c:A)) ((1 |-> (b:A)) ((0 |-> (a:A)) (v:num->A)))`; `30`; `0`;
        `3`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(30 = 3) /\ ~(30 = 1) /\ ~(30 = 0) /\ ~(0 = 3) /\ ~(0 = 1) /\
        ~(1 = 3)`]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b c. a IN D /\ b IN D /\ c IN D
            ==> (holds D E
                 ((1 |-> (c:A)) ((2 |-> (b:A)) ((0 |-> (a:A)) (v:num->A))))
                 (apply_form 30 0 1) <=> eapply D E (v 30) a c) /\
                (holds D E
                 ((1 |-> (c:A)) ((2 |-> (b:A)) ((0 |-> (a:A)) (v:num->A))))
                 (apply_form 30 2 1) <=> eapply D E (v 30) b c)`
  (LABEL_TAC "bINJ") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (c:A)) ((2 |-> (b:A)) ((0 |-> (a:A)) (v:num->A)))`; `30`; `0`;
        `1`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(1 |-> (c:A)) ((2 |-> (b:A)) ((0 |-> (a:A)) (v:num->A)))`; `30`; `2`;
        `1`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(30 = 1) /\ ~(30 = 2) /\ ~(30 = 0) /\ ~(2 = 1) /\ ~(0 = 1) /\
        ~(0 = 2)`]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) (v:num->A)
    (!! 0 (!! 1 (apply_form 30 0 1 --> (0 %% 32) && (1 %% 33)))) <=>
    (!k t. k IN D /\ t IN D /\ eapply D E (v 30) k t ==> E k (v 32) /\
     E t (v 33))`
  (LABEL_TAC "hc1") THENL
   [REWRITE_TAC[holds; HOLDS_AND] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(0 = 1) /\ ~(32 = 0) /\ ~(32 = 1) /\ ~(33 = 0) /\ ~(33 = 1)`] THEN
    EQ_TAC THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) (v:num->A)
    (!! 0 ((0 %% 32) --> ?? 1 ((1 %% 33) && apply_form 30 0 1))) <=>
    (!k. k IN D /\ E k (v 32) ==> ?t. t IN D /\ E t (v 33) /\
     eapply D E (v 30) k t)`
  (LABEL_TAC "hc2") THENL
   [REWRITE_TAC[holds; HOLDS_AND; HOLDS_EX] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(0 = 1) /\ ~(32 = 0) /\ ~(32 = 1) /\ ~(33 = 0) /\ ~(33 = 1)`] THEN
    EQ_TAC THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) (v:num->A)
    (!! 0 (!! 1
           (!! 3 (apply_form 30 0 1 && apply_form 30 0 3 --> Eq 1 3)))) <=>
    (!k t t'. k IN D /\ t IN D /\ t' IN D /\
              eapply D E (v 30) k t /\ eapply D E (v 30) k t' ==> t = t')`
  (LABEL_TAC "hc3") THENL
   [REWRITE_TAC[holds; HOLDS_AND] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(1 = 3)`] THEN
    EQ_TAC THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) (v:num->A)
    (!! 0 (!! 2
           (!! 1 (apply_form 30 0 1 && apply_form 30 2 1 --> Eq 0 2)))) <=>
    (!k k' t. k IN D /\ k' IN D /\ t IN D /\
              eapply D E (v 30) k t /\ eapply D E (v 30) k' t ==> k = k')`
  (LABEL_TAC "hc4") THENL
   [REWRITE_TAC[holds; HOLDS_AND] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(0 = 1) /\ ~(0 = 2) /\ ~(2 = 1)`] THEN
    EQ_TAC THEN REPEAT STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[injform; HOLDS_AND] THEN
  GEN_REWRITE_TAC RAND_CONV [einj] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Canonicalisation (EINJ_CANON): any injection einj e x y can be replaced   *)
(* by a graph-form injection ge whose every element is an ordered pair <r,w> *)
(* with r in x and w in y (so ge SUBSET x cross y). This is needed to bound  *)
(* families of injections by a power set for separation, in the union bound  *)
(* below.                                                                    *)
(* ------------------------------------------------------------------------- *)

let EINJ_CANON = prove
 (`!D (E:A->A->bool) e x y.
     model D E ZF_AX /\ x IN D /\ y IN D /\ einj D E e x y
     ==> ?ge. ge IN D /\
              (!z. z IN D /\ E z ge
                   ==> ?r w. r IN D /\ w IN D /\ E r x /\ E w y /\
                             eopair D E r w z) /\
              einj D E ge x y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[einj]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t:A. k IN D /\ t IN D /\ eapply D (E:A->A->bool) e k t
            ==> E k x /\ E t y`
  (LABEL_TAC "e2") THENL
   [MP_TAC(ASSUME `einj D (E:A->A->bool) e x y`) THEN REWRITE_TAC[einj] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
      (CONJUNCTS_THEN2 ACCEPT_TAC (K ALL_TAC)));
    ALL_TAC] THEN
  SUBGOAL_THEN `?fc:A. ecross D (E:A->A->bool) x y fc`
    (X_CHOOSE_TAC `fc:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(fc:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z fc <=>
               ?r w. r IN D /\ w IN D /\ E r x /\ E w y /\ eopair D E r w z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "fcc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) x y fc` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((10 |-> (e:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D
      ==> (holds D E ((0 |-> z) ((10 |-> (e:A)) v0))
             (?? 5 (?? 6 (opair_form 5 6 0 && apply_form 10 5 6))) <=>
           ?r. r IN D /\ ?w. w IN D /\
               eopair D (E:A->A->bool) r w z /\ eapply D E e r w)`
  (LABEL_TAC "tb") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!r:A. P r <=> Q r) ==> ((?r:A. P r) <=> (?r:A. Q r))`) THEN
    X_GEN_TAC `r:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!w:A. P w <=> Q w) ==> ((?w:A. P w) <=> (?w:A. Q w))`) THEN
    X_GEN_TAC `w:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (w:A)) ((5 |-> (r:A)) ((0 |-> (z:A))
        ((10 |-> (e:A)) v0))))`
    ASSUME_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (w:A)) ((5 |-> (r:A)) ((0 |-> (z:A)) ((10 |-> (e:A)) v0)))`;
      `5`; `6`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (w:A)) ((5 |-> (r:A)) ((0 |-> (z:A)) ((10 |-> (e:A)) v0)))`;
      `10`; `5`; `6`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(5 = 6) /\ ~(0 = 6) /\ ~(0 = 5) /\ ~(10 = 6) /\ ~(10 = 5) /\
       ~(10 = 0)`];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 5 (?? 6 (opair_form 5 6 0 && apply_form 10 5 6))`;
     `0`; `(10 |-> (e:A)) v0`; `fc:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ge:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "gch"))) THEN
  SUBGOAL_THEN
   `!z:A. z IN D
          ==> ((E:A->A->bool) z ge <=>
               ?r w. r IN D /\ w IN D /\ eopair D E r w z /\ eapply D E e r w)`
  (LABEL_TAC "gm") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "gch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "tb" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THEN STRIP_TAC THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!r w:A. r IN D /\ w IN D
            ==> (eapply D (E:A->A->bool) ge r w <=> eapply D E e r w)`
  (LABEL_TAC "crux") THENL
   [MAP_EVERY X_GEN_TAC [`r:A`; `w:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gm" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN
      DISCH_THEN(X_CHOOSE_THEN `r':A` (X_CHOOSE_THEN `w':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(r:A) = r' /\ (w:A) = w'` STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC EOPAIR_INJ THEN
        MAP_EVERY EXISTS_TAC [`D:A->bool`; `E:A->A->bool`; `zz:A`] THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) e r' w'` THEN
      ASM_REWRITE_TAC[eapply];
      DISCH_THEN(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `zz:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "gm" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`r:A`; `w:A`] THEN ASM_REWRITE_TAC[eapply] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  EXISTS_TAC `ge:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    USE_THEN "gm" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `r:A` (X_CHOOSE_THEN `w:A`
      STRIP_ASSUME_TAC)) THEN
    MAP_EVERY EXISTS_TAC [`r:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[];
    UNDISCH_TAC `einj D (E:A->A->bool) e x y` THEN
    REWRITE_TAC[einj] THEN ASM_REWRITE_TAC[] THEN
    STRIP_TAC THEN REPEAT CONJ_TAC THEN REPEAT STRIP_TAC THEN
    ASM_MESON_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* Choice of one tag per index.  ESLICE_FAMILY_A: the set ww of the          *)
(* index-slices {p IN tt | p = <n,e> for some e} (n<a) of a tagged set tt.   *)
(* ECHOOSE_INJ_GEN: if every slice is nonempty, ELMEM_CHOICE picks one tag   *)
(* e_n with P n e_n for each index n<a (existence + uniqueness).             *)
(* ------------------------------------------------------------------------- *)

let ESLICE_FAMILY_A = prove
 (`!D (E:A->A->bool) a tt.
     model D E ZF_AX /\ a IN D /\ tt IN D
     ==> ?ww. ww IN D /\
              !w. w IN D
                  ==> (E w ww <=>
                       ?n. n IN D /\ E n a /\
                           !p. p IN D
                               ==> (E p w <=>
                                    E p tt /\
                                    ?e. e IN D /\
                                        eopair D E n e p))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    ASSUME_TAC)) THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((2 |-> (tt:A)) v0)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn p:A. nn IN D /\ p IN D
      ==> (holds D E ((0 |-> p) ((2 |-> (nn:A)) v0))
             (?? 7 (opair_form 2 7 0)) <=>
           ?e. e IN D /\ eopair D (E:A->A->bool) nn e p)`
  (LABEL_TAC "pb") THENL
   [MAP_EVERY X_GEN_TAC [`nn:A`; `p:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!e:A. P e <=> Q e) ==> ((?e:A. P e) <=> (?e:A. Q e))`) THEN
    X_GEN_TAC `e:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (e:A)) ((0 |-> (p:A)) ((2 |-> (nn:A)) v0))`;
      `2`; `7`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn w:A. nn IN D /\ w IN D
      ==> (holds D E ((1 |-> w) ((0 |-> (nn:A)) ((2 |-> (tt:A))
             v0)))
             (!! 6 ((6 %% 1) <->
                ((6 %% 2) && ?? 7 (opair_form 0 7 6)))) <=>
           !p. p IN D
               ==> ((E:A->A->bool) p w <=>
                    E p tt /\
                    ?e. e IN D /\ eopair D E nn e p))`
  (LABEL_TAC "sb") THENL
   [MAP_EVERY X_GEN_TAC [`nn:A`; `w:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[holds] THEN
    MATCH_MP_TAC(MESON[]
     `(!p:A. P p <=> Q p) ==> ((!p:A. P p) <=> (!p:A. Q p))`) THEN
    X_GEN_TAC `p:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    REWRITE_TAC[HOLDS_IFF; HOLDS_AND; HOLDS_EX] THEN
    REWRITE_TAC[holds] THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[] THEN
    MATCH_MP_TAC(TAUT
     `(p <=> q) ==> ((l <=> a /\ p) <=> (l <=> a /\ q))`) THEN
    MATCH_MP_TAC(MESON[]
     `(!e:A. P e <=> Q e) ==> ((?e:A. P e) <=> (?e:A. Q e))`) THEN
    X_GEN_TAC `e:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (e:A)) ((6 |-> (p:A)) ((1 |-> (w:A)) ((0 |-> (nn:A))
         ((2 |-> (tt:A)) v0))))`;
      `0`; `7`; `6`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`!! 6 ((6 %% 1) <-> ((6 %% 2) && ?? 7 (opair_form 0 7 6)))`;
     `0`; `1`; `(2 |-> (tt:A)) v0`; `a:A`]) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[ARITH_EQ] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL
      [`?? 7 (opair_form 2 7 0)`; `0`;
       `(2 |-> (u:A)) v0`; `tt:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `sl:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "slc"))) THEN
    EXISTS_TAC `sl:A` THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `w':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) THEN
    USE_THEN "sb" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    DISCH_THEN(LABEL_TAC "wc") THEN
    FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "wc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "slc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "pb" (MP_TAC o SPECL [`u:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "wwc"))) THEN
  EXISTS_TAC `ww:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "wwc" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
   `(!n:A. P n <=> Q n) ==> ((?n:A. P n) <=> (?n:A. Q n))`) THEN
  X_GEN_TAC `n:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ b /\ p) <=> (a /\ b /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "sb" (MP_TAC o SPECL [`n:A`; `w:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]));;

let ECHOOSE_INJ_GEN = prove
 (`!D (E:A->A->bool) a kk tt ww (P:A->A->bool).
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\ kk IN D /\
     tt IN D /\
     (!p. p IN D
          ==> (E p tt <=>
               ?n e. n IN D /\ e IN D /\ E n a /\
                     eopair D E n e p /\ (P:A->A->bool) n e)) /\
     ww IN D /\
     (!w. w IN D
          ==> (E w ww <=>
               ?n. n IN D /\ E n a /\
                   !p. p IN D
                       ==> (E p w <=>
                            E p tt /\ ?e. e IN D /\ eopair D E n e p))) /\
     (!n. n IN D /\ E n a
          ==> ?e p. e IN D /\ p IN D /\ E p tt /\ eopair D E n e p)
     ==> ?c. c IN D /\
             (!n. n IN D /\ E n a
                  ==> ?e p. e IN D /\ p IN D /\ eopair D E n e p /\
                            E p c /\ (P:A->A->bool) n e) /\
             (!n e e' p p'.
                  n IN D /\ E n a /\ e IN D /\ e' IN D /\
                  p IN D /\ p' IN D /\
                  eopair D E n e p /\ E p c /\ (P:A->A->bool) n e /\
                  eopair D E n e' p' /\ E p' c /\ (P:A->A->bool) n e'
                  ==> e = e')`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 ttc h4 wwc ne" THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn p:A. nn IN D /\ p IN D
      ==> (holds D E ((0 |-> p) ((2 |-> (nn:A)) v0))
             (?? 7 (opair_form 2 7 0)) <=>
           ?e. e IN D /\ eopair D (E:A->A->bool) nn e p)`
  (LABEL_TAC "pb") THENL
   [MAP_EVERY X_GEN_TAC [`nn:A`; `p:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!e:A. P e <=> Q e) ==> ((?e:A. P e) <=> (?e:A. Q e))`) THEN
    X_GEN_TAC `e:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (e:A)) ((0 |-> (p:A)) ((2 |-> (nn:A)) v0))`;
      `2`; `7`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!n:A. n IN D /\ E n a
      ==> ?s. s IN D /\ E s ww /\
              !p. p IN D
                  ==> ((E:A->A->bool) p s <=>
                       E p tt /\ ?e. e IN D /\ eopair D E n e p)`
  (LABEL_TAC "slice") THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((2 |-> (n:A)) v0)` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL
      [`?? 7 (opair_form 2 7 0)`; `0`; `(2 |-> (n:A)) v0`; `tt:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "sc0"))) THEN
    SUBGOAL_THEN
     `!p. p IN D
          ==> ((E:A->A->bool) p s <=>
               E p tt /\ ?e. e IN D /\ eopair D E n e p)`
    (LABEL_TAC "sc") THENL
     [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
      USE_THEN "sc0" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "pb" (MP_TAC o SPECL [`n:A`; `p:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      ALL_TAC] THEN
    EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "wwc" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "sc" ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ww:A`] ELMEM_CHOICE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `y:A` THEN STRIP_TAC THEN
      USE_THEN "wwc" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) y ww`))) THEN
      INTRO_TAC "@n. h5 h6 yc" THEN
      USE_THEN "ne" (MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `e0:A` (X_CHOOSE_THEN `z:A`
        STRIP_ASSUME_TAC)) THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "yc" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN EXISTS_TAC `e0:A` THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`y:A`; `y':A`] THEN STRIP_TAC THEN
      REWRITE_TAC[NOT_EXISTS_THM] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "wwc" (MP_TAC o SPEC `y:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) y ww`))) THEN
      INTRO_TAC "@n. h7 h8 yc" THEN
      USE_THEN "wwc" (MP_TAC o SPEC `y':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) y' ww`))) THEN
      INTRO_TAC "@n'. h9 h10 yc'" THEN
      SUBGOAL_THEN `?e:A. e IN D /\ eopair D (E:A->A->bool) n e z`
        (X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THENL
       [USE_THEN "yc" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `(E:A->A->bool) z y`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        ALL_TAC] THEN
      SUBGOAL_THEN `?e':A. e' IN D /\ eopair D (E:A->A->bool) n' e' z`
        (X_CHOOSE_THEN `e':A` STRIP_ASSUME_TAC) THENL
       [USE_THEN "yc'" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
          (ASSUME `(E:A->A->bool) z y'`))) THEN
        DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `e:A`;
        `n':A`; `e':A`; `z:A`] EOPAIR_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (K ALL_TAC)) THEN
      SUBGOAL_THEN `(y:A) = y'` (fun th -> ASM_MESON_TAC[th]) THEN
      FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `p:A` THEN DISCH_TAC THEN
      USE_THEN "yc" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "yc'" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ch"))) THEN
  EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    USE_THEN "slice" (MP_TAC o SPEC `n:A`) THEN
