      `n0:A`; `e0:A`; `z:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM)
      (SUBST_ALL_TAC o SYM)) THEN
    MAP_EVERY EXISTS_TAC [`e:A`; `z:A`] THEN ASM_REWRITE_TAC[];
    MAP_EVERY X_GEN_TAC [`n:A`; `e:A`; `e':A`; `p:A`; `p':A`] THEN
    STRIP_TAC THEN
    USE_THEN "slice" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@s. h16 h17 sc" THEN
    SUBGOAL_THEN `(E:A->A->bool) p s /\ E p' s` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "sc" (MP_TAC o SPEC `p:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        CONJ_TAC THENL
         [USE_THEN "ttc" (MP_TAC o SPEC `p:A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          MAP_EVERY EXISTS_TAC [`n:A`; `e:A`] THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[]];
        USE_THEN "sc" (MP_TAC o SPEC `p':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        CONJ_TAC THENL
         [USE_THEN "ttc" (MP_TAC o SPEC `p':A`) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
          MAP_EVERY EXISTS_TAC [`n:A`; `e':A`] THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `e':A` THEN ASM_REWRITE_TAC[]]];
      ALL_TAC] THEN
    USE_THEN "ch" (MP_TAC o SPEC `s:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@z. h18 h19 h20 uz" THEN
    SUBGOAL_THEN `(p:A) = z /\ (p':A) = z` STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN USE_THEN "uz" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) = p'` ASSUME_TAC THENL
     [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `e:A`;
      `n:A`; `e':A`; `p:A`] EOPAIR_INJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      UNDISCH_TAC `eopair D (E:A->A->bool) n e' p'` THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC)]);;

(* ------------------------------------------------------------------------- *)
(* Proof of EGEN_UNION_CARD_LE: ETAGINJ_GEN tags each b<a with the           *)
(* graph-form injections of ff(b) into kk; ESLICE_FAMILY_A and               *)
(* ECHOOSE_INJ_GEN choose one such injection e_b for each b<a; genrank_form  *)
(* and GENRANK_LEAST give the least b<a with u IN ff(b); genumap_form        *)
(* internalizes the map u |-> <rank u, e_{rank u}(u)>, which injects the     *)
(* union into a x kk; and a x kk >-> kk by ECROSS_CARD_LE.                   *)
(* ------------------------------------------------------------------------- *)

let ffinst_form = new_definition
  `ffinst_form ffs i j k = ?? k (apply_form ffs i k && (j %% k))`;;

let HOLDS_FFINST = prove
 (`!D (E:A->A->bool) v ffs i j k.
     valuation D v /\ ~(ffs = k) /\ ~(i = k) /\ ~(j = k)
     ==> (holds D E v (ffinst_form ffs i j k) <=>
          ?z. z IN D /\ eapply D E (v ffs) (v i) z /\ E (v j) z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ffinst_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!z:A. P z <=> Q z) ==> ((?z:A. P z) <=> (?z:A. Q z))`) THEN
  X_GEN_TAC `z:A` THEN
  MATCH_MP_TAC(TAUT `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((k:num) |-> (z:A)) (v:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((k:num) |-> (z:A)) (v:num->A)`;
    `ffs:num`; `i:num`; `k:num`] HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER]);;

let genrank_form = new_definition
  `genrank_form =
     ffinst_form 40 42 41 43 && !!- 45 42 (Not (ffinst_form 40 45 41 44))`;;

let HOLDS_GENRANK_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v genrank_form <=>
          (?z. z IN D /\ eapply D E (v 40) (v 42) z /\ E (v 41) z) /\
          (!nn. nn IN D /\ E nn (v 42)
                ==> ~(?z. z IN D /\ eapply D E (v 40) nn z /\ E (v 41) z)))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[genrank_form; HOLDS_AND] THEN
  MATCH_MP_TAC(TAUT
   `(p1 <=> q1) /\ (p2 <=> q2) ==> (p1 /\ p2 <=> q1 /\ q2)`) THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `40`; `42`; `41`;
      `43`] HOLDS_FFINST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `45`; `42`;
      `Not (ffinst_form 40 45 41 44)`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!nn:A. P nn <=> Q nn) ==> ((!nn:A. P nn) <=> (!nn:A. Q nn))`) THEN
    X_GEN_TAC `nn:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((45 |-> (nn:A)) (v:num->A))` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[HOLDS_NOT] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(45 |-> (nn:A)) (v:num->A)`;
      `40`; `45`; `41`; `44`] HOLDS_FFINST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                 ARITH_RULE `~(40 = 45) /\ ~(41 = 45)`]]);;

(* ------------------------------------------------------------------------- *)
(* Choice layer for the general union bound. genslstinj: e is a graph-form   *)
(* injection (e SUBSET fc) of the slice ff(b) into kk. ETAGINJ_GEN: the      *)
(* tagged set of pairs <b,e> with b < a and e such an injection.             *)
(* ------------------------------------------------------------------------- *)

let genslstinj = new_definition
  `genslstinj D (E:A->A->bool) ff kk fc b e <=>
     ?z. z IN D /\ eapply D E ff b z /\ esubset D E e fc /\ einj D E e z kk`;;

let ETAGINJ_GEN = prove
 (`!D (E:A->A->bool) a ya kk ff.
     model D E ZF_AX /\ a IN D /\ ya IN D /\ kk IN D /\ ff IN D
     ==> ?tt fc. tt IN D /\ fc IN D /\ ecross D E ya kk fc /\
                 !p. p IN D
                     ==> (E p tt <=>
                          ?b. b IN D /\ ?e. e IN D /\ ?yb. yb IN D /\
                              eopair D E b e p /\ E b a /\
                                eapply D E ff b yb /\
                              esubset D E e fc /\ einj D E e yb kk)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?fc:A. ecross D (E:A->A->bool) ya kk fc`
    (X_CHOOSE_TAC `fc:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(fc:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z fc <=>
               ?r w. r IN D /\ w IN D /\ E r ya /\ E w kk /\ eopair D E r w z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "fcc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) ya kk fc` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?pw:A. epow D (E:A->A->bool) fc pw`
    (X_CHOOSE_TAC `pw:A`) THENL
   [ASM_MESON_TAC[EPOW_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pw:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w pw <=> esubset D E w fc)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "pwc")) THENL
   [UNDISCH_TAC `epow D (E:A->A->bool) fc pw` THEN
    REWRITE_TAC[epow] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?omc:A. ecross D (E:A->A->bool) a pw omc`
    (X_CHOOSE_TAC `omc:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(omc:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z omc <=>
               ?b e. b IN D /\ e IN D /\ E b a /\ E e pw /\ eopair D E b e z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "omcc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) a pw omc` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D
    ((34 |-> (fc:A)) ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0))))`
  ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  SUBGOAL_THEN
   `!p:A. p IN D
      ==> (holds D E
           ((0 |-> p)
            ((34 |-> (fc:A))
             ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0)))))
           (?? 5 (?? 30 (?? 32 (opair_form 5 30 0 &&
                ((5 %% 1) && (apply_form 35 5 32 &&
                   (subset_form 30 34 && injform))))))) <=>
           ?b. b IN D /\ ?e. e IN D /\ ?yb. yb IN D /\
               eopair D (E:A->A->bool) b e p /\ E b a /\ eapply D E ff b yb /\
               esubset D E e fc /\ einj D E e yb kk)`
  (LABEL_TAC "tb") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!b:A. P b <=> Q b) ==> ((?b:A. P b) <=> (?b:A. Q b))`) THEN
    X_GEN_TAC `b:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!e:A. P e <=> Q e) ==> ((?e:A. P e) <=> (?e:A. Q e))`) THEN
    X_GEN_TAC `e:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN DISCH_TAC THEN
    REWRITE_TAC[HOLDS_EX] THEN
    MATCH_MP_TAC(MESON[]
     `(!yb:A. P yb <=> Q yb) ==> ((?yb:A. P yb) <=> (?yb:A. Q yb))`) THEN
    X_GEN_TAC `yb:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D
      ((32 |-> (yb:A)) ((30 |-> (e:A)) ((5 |-> (b:A)) ((0 |-> (p:A))
        ((34 |-> (fc:A))
         ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0))))))))`
    ASSUME_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      ALL_TAC] THEN
    REWRITE_TAC[HOLDS_AND] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(32 |-> (yb:A)) ((30 |-> (e:A)) ((5 |-> (b:A)) ((0 |-> (p:A))
        ((34 |-> (fc:A))
         ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0)))))))`;
      `5`; `30`; `0`] HOLDS_OPAIR_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(32 |-> (yb:A)) ((30 |-> (e:A)) ((5 |-> (b:A)) ((0 |-> (p:A))
        ((34 |-> (fc:A))
         ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0)))))))`;
      `35`; `5`; `32`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_SUBSET_FORM] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(32 |-> (yb:A)) ((30 |-> (e:A)) ((5 |-> (b:A)) ((0 |-> (p:A))
        ((34 |-> (fc:A))
         ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0)))))))`]
      HOLDS_INJFORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[holds] THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
      `~(5 = 32) /\ ~(5 = 30) /\ ~(30 = 32) /\ ~(0 = 32) /\ ~(0 = 30) /\
       ~(0 = 5) /\ ~(1 = 32) /\ ~(1 = 30) /\ ~(1 = 5) /\ ~(1 = 0) /\
       ~(1 = 34) /\ ~(1 = 33) /\ ~(34 = 32) /\ ~(34 = 30) /\ ~(34 = 5) /\
       ~(34 = 0) /\ ~(33 = 32) /\ ~(33 = 30) /\ ~(33 = 5) /\ ~(33 = 0) /\
       ~(33 = 34) /\ ~(35 = 32) /\ ~(35 = 30) /\ ~(35 = 5) /\ ~(35 = 0) /\
         ~(35 = 1) /\ ~(35 = 34) /\ ~(35 = 33)`];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 5 (?? 30 (?? 32 (opair_form 5 30 0 &&
        ((5 %% 1) &&
         (apply_form 35 5 32 && (subset_form 30 34 && injform))))))`;
     `0`; `(34 |-> (fc:A))
           ((33 |-> (kk:A)) ((35 |-> (ff:A)) ((1 |-> (a:A)) v0)))`;
     `omc:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `tt:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "tch"))) THEN
  MAP_EVERY EXISTS_TAC [`tt:A`; `fc:A`] THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  USE_THEN "tch" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  USE_THEN "tb" (MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC)
     (X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `e:A`
       (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `yb:A`
         STRIP_ASSUME_TAC)))))) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `yb:A` THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `e:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `yb:A` STRIP_ASSUME_TAC))))) THEN
    CONJ_TAC THENL
     [USE_THEN "omcc" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `e:A`] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "pwc" (MP_TAC o SPEC `e:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `yb:A` THEN ASM_REWRITE_TAC[]]]);;

let genumap_form = new_definition
  `genumap_form =
     ?? 42 (?? 49 (?? 48 (?? 50 (?? 51
       (genrank_form &&
        ((42 %% 52) &&
         (opair_form 42 49 48 &&
          ((48 %% 47) &&
           ((48 %% 53) &&
            (apply_form 49 41 50 &&
             (opair_form 42 50 51 && opair_form 41 51 46)))))))))))`;;

let HOLDS_GENUMAP_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v genumap_form <=>
          ?n. n IN D /\ ?e. e IN D /\ ?p. p IN D /\ ?w. w IN D /\
              ?m. m IN D /\
                  (?z. z IN D /\ eapply D E (v 40) n z /\ E (v 41) z) /\
                  (!nn. nn IN D /\ E nn n
                        ==> ~(?z. z IN D /\ eapply D E (v 40) nn z /\
                                  E (v 41) z)) /\
                  E n (v 52) /\
                  eopair D E n e p /\
                  E p (v 47) /\
                  E p (v 53) /\
                  eapply D E e (v 41) w /\
                  eopair D E n w m /\
                  eopair D E (v 41) m (v 46))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[genumap_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `n:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `e:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
      ((49 |-> (e:A)) ((42 |-> (n:A)) v)))))`
  ASSUME_TAC THENL
   [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
       ((49 |-> (e:A)) ((42 |-> (n:A)) v))))`]
    HOLDS_GENRANK_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
       ((49 |-> (e:A)) ((42 |-> (n:A)) v))))`; `42`; `49`; `48`]
    HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
       ((49 |-> (e:A)) ((42 |-> (n:A)) v))))`; `49`; `41`; `50`]
    HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
       ((49 |-> (e:A)) ((42 |-> (n:A)) v))))`; `42`; `50`; `51`]
    HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(51 |-> (m:A)) ((50 |-> (w:A)) ((48 |-> (p:A))
       ((49 |-> (e:A)) ((42 |-> (n:A)) v))))`; `41`; `51`; `46`]
    HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[holds] THEN REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN CONV_TAC TAUT);;

(* ------------------------------------------------------------------------- *)
(* GENRANK_LEAST: every u in the union of the slices ff(b), b < a, has a     *)
(* least index b0 whose slice contains it.                                   *)
(* ------------------------------------------------------------------------- *)

let GENRANK_LEAST = prove
 (`!D (E:A->A->bool) a ff u.
     model D E ZF_AX /\ eordinal D E a /\ ff IN D /\ u IN D /\
     (?b z. b IN D /\ z IN D /\ E b a /\ eapply D E ff b z /\ E u z)
     ==> ?b0 z0. b0 IN D /\ eordinal D E b0 /\ E b0 a /\ z0 IN D /\
                 eapply D E ff b0 z0 /\ E u z0 /\
                 (!b' z'. b' IN D /\ z' IN D /\ E b' b0 /\ eapply D E ff b' z'
                          ==> ~(E u z'))`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
     (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `valuation D (\m:num. (u:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((40 |-> (ff:A)) (\m:num. (u:A)))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!d:A. d IN D
          ==> (holds D E ((0 |-> d) ((40 |-> (ff:A)) (\m:num. (u:A))))
                 (ffinst_form 40 0 1 43) <=>
               ?y. y IN D /\ eapply D E ff d y /\ E u y)`
  (LABEL_TAC "ic") THENL
   [X_GEN_TAC `d:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN
     `valuation D ((0 |-> (d:A)) ((40 |-> (ff:A)) (\m:num. (u:A))))`
    ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (d:A)) ((40 |-> (ff:A)) (\m:num. (u:A)))`; `40`; `0`; `1`; `43`]
      HOLDS_FFINST) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[ARITH_EQ]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `ffinst_form 40 0 1 43`;
    `(40 |-> (ff:A)) (\m:num. (u:A))`; `b:A`] EORDINAL_LEAST) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    USE_THEN "ic"
      (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(b:A) IN D`)]) THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@b0. h1 h2 hb0 minb0" THEN
  USE_THEN "ic" (fun th ->
    USE_THEN "hb0"
      (MP_TAC o REWRITE_RULE[MATCH_MP th (ASSUME `(b0:A) IN D`)])) THEN
  DISCH_THEN(X_CHOOSE_THEN `z0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) (b0:A) (a:A)` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b0:A`; `b:A`]
      EORDINAL_TRICHOTOMY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    STRIP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `b0:A`]
        EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
      ASM_REWRITE_TAC[];
      USE_THEN "minb0" (MP_TAC o SPEC `b:A`) THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "ic"
        (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(b:A) IN D`)]) THEN
        ASM_MESON_TAC[]];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`b0:A`; `z0:A`] THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`b':A`; `z':A`] THEN STRIP_TAC THEN
  USE_THEN "minb0" (MP_TAC o SPEC `b':A`) THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "ic"
    (fun th -> REWRITE_TAC[MATCH_MP th (ASSUME `(b':A) IN D`)]) THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* genslval: the value relation of the union map for the general family.     *)
(* ------------------------------------------------------------------------- *)

let genslval = new_definition
  `genslval D (E:A->A->bool) a ff tt c u t <=>
     ?n e p w. n IN D /\ e IN D /\ p IN D /\ w IN D /\
               E n a /\
               (?z. z IN D /\ eapply D E ff n z /\ E u z) /\
               (!nn. nn IN D /\ E nn n
                     ==> ~(?z. z IN D /\ eapply D E ff nn z /\ E u z)) /\
               eopair D E n e p /\ E p tt /\ E p c /\ eapply D E e u w /\
               eopair D E n w t`;;

(* ------------------------------------------------------------------------- *)
(* The general union bound EGEN_UNION_CARD_LE: if a >-> kk for an infinite   *)
(* cardinal kk, ff is single-valued, and every slice ff(b) with b < a is a   *)
(* subset of ya that injects into kk, then the union wun of the slices       *)
(* injects into kk.                                                          *)
(* ------------------------------------------------------------------------- *)

let EGEN_UNION_CARD_LE = prove
 (`!D (E:A->A->bool) om a kk ea ya ff wun.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\ kk IN D /\
     eordinal D E a /\ a IN D /\ einj D E ea a kk /\
     ya IN D /\ ff IN D /\
     (!n z z'. n IN D /\ z IN D /\ z' IN D /\
               eapply D E ff n z /\ eapply D E ff n z' ==> z = z') /\
     wun IN D /\
     (!u. u IN D
          ==> (E u wun <=>
               ?b z. b IN D /\ z IN D /\ E b a /\
                 eapply D E ff b z /\ E u z)) /\
     (!b. b IN D /\ E b a
          ==> ?z. z IN D /\ eapply D E ff b z /\
                  (!u. u IN D /\ E u z ==> E u ya) /\
                  (?e. e IN D /\ einj D E e z kk))
     ==> ?e. einj D E e wun kk`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 h4 h5 h6 h7 h8 h9 h10 sv h11 wc ih" THEN
  (* --- tagged set tt and its bound fc --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ya:A`; `kk:A`; `ff:A`]
    ETAGINJ_GEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@tt fc. h12 h13 h14 tag" THEN
  SUBGOAL_THEN
   `(fc:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z fc <=>
               ?r w. r IN D /\ w IN D /\ E r ya /\ E w kk /\ eopair D E r w z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "fcc")) THENL
   [ASM_REWRITE_TAC[] THEN
    UNDISCH_TAC `ecross D (E:A->A->bool) ya kk fc` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  (* --- ttc in ECHOOSE_INJ_GEN form --- *)
  SUBGOAL_THEN
   `!p:A. p IN D
      ==> (E p tt <=>
           ?n e. n IN D /\ e IN D /\ E n a /\ eopair D (E:A->A->bool) n e p /\
                 genslstinj D E ff kk fc n e)`
  (LABEL_TAC "ttc") THENL
   [X_GEN_TAC `p:A` THEN DISCH_TAC THEN
    USE_THEN "tag" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[genslstinj] THEN MESON_TAC[];
    ALL_TAC] THEN
  (* --- slice family ww --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `tt:A`]
    ESLICE_FAMILY_A) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ww:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "wwc"))) THEN
  (* --- nonemptiness of slices (from each-slice hyp + EINJ_CANON) --- *)
  SUBGOAL_THEN
   `!n:A. n IN D /\ E n a
      ==> ?e p. e IN D /\ p IN D /\ E p tt /\ eopair D (E:A->A->bool) n e p`
  (LABEL_TAC "ne") THENL
   [X_GEN_TAC `n:A` THEN STRIP_TAC THEN
    USE_THEN "ih" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@z. h15 h16 zsub @e0. h17 h18" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e0:A`; `z:A`; `kk:A`]
           EINJ_CANON) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@ge. h19 gesub h20" THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) ge fc` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `zz:A` THEN STRIP_TAC THEN
      USE_THEN "gesub" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `r:A`
                 (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "fcc" (MP_TAC o SPEC `zz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`r:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "zsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `?p:A. eopair D (E:A->A->bool) n ge p`
      (X_CHOOSE_TAC `p:A`) THENL
      [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`ge:A`; `p:A`] THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "ttc" (MP_TAC o SPEC `p:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `ge:A`] THEN
    ASM_REWRITE_TAC[genslstinj] THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* --- choice set c --- *)
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `kk:A`; `tt:A`; `ww:A`;
    `genslstinj (D:A->bool) (E:A->A->bool) (ff:A) (kk:A) (fc:A)`]
      ECHOOSE_INJ_GEN) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN
    CONJ_TAC THENL [USE_THEN "ttc" ACCEPT_TAC; ALL_TAC] THEN
    CONJ_TAC THENL [USE_THEN "wwc" ACCEPT_TAC; USE_THEN "ne" ACCEPT_TAC];
    ALL_TAC] THEN
  INTRO_TAC "@c. h21 ctot cfun" THEN
  (* --- product a x kk --- *)
  SUBGOAL_THEN `?qc:A. ecross D (E:A->A->bool) a kk qc`
    (X_CHOOSE_TAC `qc:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(qc:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z qc <=>
               ?r w. r IN D /\ w IN D /\ E r a /\ E w kk /\ eopair D E r w z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "qcc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) a kk qc` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  ABBREV_TAC
    `vp = (47 |-> (c:A))
     ((53 |-> (tt:A)) ((52 |-> (a:A)) ((40 |-> (ff:A)) v0)))` THEN
  SUBGOAL_THEN `valuation D (vp:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vp" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  (* --- fmb : genumap_form bridge to genslval --- *)
  SUBGOAL_THEN
   `!u out:A. u IN D /\ out IN D
      ==> (holds D E ((46 |-> out) ((41 |-> (u:A)) vp)) genumap_form <=>
           ?m. m IN D /\ genslval D E a ff tt c u m /\
               eopair D (E:A->A->bool) u m out)`
  (LABEL_TAC "fmb") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `out:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(46 |-> (out:A)) ((41 |-> (u:A)) vp)`] HOLDS_GENUMAP_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "vp" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[genslval] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `n:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC
                  (X_CHOOSE_THEN `e:A`
                   (CONJUNCTS_THEN2 ASSUME_TAC
                    (X_CHOOSE_THEN `p:A`
                     (CONJUNCTS_THEN2 ASSUME_TAC
                      (X_CHOOSE_THEN `w:A`
                       (CONJUNCTS_THEN2 ASSUME_TAC
                        (X_CHOOSE_THEN `m:A`
                         (CONJUNCTS_THEN2 ASSUME_TAC
                          (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC))))))))))) THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `e:A`; `p:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `m:A`
                 (CONJUNCTS_THEN2 ASSUME_TAC
                  (CONJUNCTS_THEN2
                   (X_CHOOSE_THEN `n:A`
                    (X_CHOOSE_THEN `e:A`
                     (X_CHOOSE_THEN `p:A`
                      (X_CHOOSE_THEN `w:A`
                       (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))))
                   ASSUME_TAC))) THEN
      EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `m:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  (* --- vwex : totality of genslval on wun --- *)
  SUBGOAL_THEN
   `!u:A. u IN D /\ E u wun ==> ?t. t IN D /\ genslval D E a ff tt c u t`
  (LABEL_TAC "vwex") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "wc" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
      (ASSUME `(E:A->A->bool) u wun`))) THEN
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ff:A`; `u:A`]
      GENRANK_LEAST) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY (fun l -> TRY(REMOVE_THEN l (K ALL_TAC)))
      ["lm";"wc";"ih";"tag";"fcc";"ttc";"wwc";"ne";"ctot";"cfun";"qcc";"fmb";
       "vwex";"efun";"vrng";"g0c";"apc";"g0r"] THEN ASM_MESON_TAC[];
      ALL_TAC] THEN
    INTRO_TAC "@n0 z0. h22 h23 h24 h25 h26 h27 min0" THEN
    USE_THEN "ctot" (MP_TAC o SPEC `n0:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@e p. h28 h29 h30 h31 esl" THEN
    SUBGOAL_THEN `(E:A->A->bool) p tt` ASSUME_TAC THENL
     [USE_THEN "ttc" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
