    (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
     [UNDISCH_TAC `einj D (E:A->A->bool) e z0 kk` THEN
      REWRITE_TAC[einj] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (CONJUNCTS_THEN2 (K ALL_TAC)
