     [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(t:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[genslval] THEN
    MAP_EVERY EXISTS_TAC [`n0:A`; `e:A`; `p:A`; `w:A`] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [EXISTS_TAC `z0:A` THEN ASM_REWRITE_TAC[];
      REWRITE_TAC[NOT_EXISTS_THM] THEN
      MAP_EVERY (fun l -> TRY(REMOVE_THEN l (K ALL_TAC)))
        ["lm";"wc";"ih";"tag";"fcc";"ttc";"wwc";"ne";"ctot";"cfun";"qcc";
         "fmb";"vwex";"efun";"vrng";"g0c";"apc";"g0r"] THEN
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  (* --- efun : functionality of genslval --- *)
  SUBGOAL_THEN
   `!u t t':A. u IN D /\ E u wun /\ t IN D /\ t' IN D /\
               genslval D E a ff tt c u t /\ genslval D E a ff tt c u t'
