  (LABEL_TAC "efun") THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `t:A`; `t':A`] THEN
    REWRITE_TAC[genslval] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2
          (X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `p:A`
            (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC))))
          (X_CHOOSE_THEN `n':A` (X_CHOOSE_THEN `e':A` (X_CHOOSE_THEN `p':A`
            (X_CHOOSE_THEN `w':A` STRIP_ASSUME_TAC))))))))) THEN
