(* ------------------------------------------------------------------------- *)
(* The graph n |-> x^n (the set of functions from n to x) on a set a         *)
(* (EFUNS_GRAPH).  Finite sequences over an infinite cardinal kk: if         *)
(* x >-> kk then FS(x) >-> kk (Jech-style |x^{<om}| = kk), the instance      *)
(* a = om, ff = (n |-> x^n) of EGEN_UNION_CARD_LE, with ESEQ_INJEX giving    *)
(* x^n >-> kk.                                                               *)
(* ------------------------------------------------------------------------- *)

let EFUNS_GRAPH = prove
 (`!D (E:A->A->bool) a x.
     model D E ZF_AX /\ a IN D /\ x IN D
     ==> ?ff. ff IN D /\
              !n q. n IN D /\ q IN D
                    ==> (eapply D E ff n q <=> E n a /\ efuns D E n x q)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u w:A. u IN D /\ w IN D
            ==> (holds D E ((1 |-> w) ((0 |-> u) ((2 |-> x) v0)))
                   (?? 3 (funs_form 0 2 3 && opair_form 0 3 1)) <=>
                 ?q. q IN D /\ efuns D (E:A->A->bool) u x q /\
                     eopair D E u q w)`
  (LABEL_TAC "hp") THENL
   [REPEAT STRIP_TAC THEN REWRITE_TAC[HOLDS_EX; HOLDS_AND] THEN
    AP_TERM_TAC THEN REWRITE_TAC[FUN_EQ_THM] THEN X_GEN_TAC `q:A` THEN
    ASM_CASES_TAC `(q:A) IN D` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN
     `valuation D ((3 |-> q) ((1 |-> w) ((0 |-> u) ((2 |-> (x:A)) v0))))`
    ASSUME_TAC THENL
     [REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
      ASM_SIMP_TAC[HOLDS_FUNS_FORM; HOLDS_OPAIR_FORM; VALMOD; ARITH_EQ]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_REPLACEMENT) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 3 (funs_form 0 2 3 && opair_form 0 3 1)`; `0`; `1`;
     `(2 |-> (x:A)) v0`; `a:A`]) THEN
  ASM_SIMP_TAC[VALUATION_VALMOD; ARITH_EQ] THEN ANTS_TAC THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `x:A`] EFUNS_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `q:A`) THEN
    SUBGOAL_THEN `(q:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `w:A`) THEN
    EXISTS_TAC `w:A` THEN CONJ_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    X_GEN_TAC `w':A` THEN STRIP_TAC THEN
    REMOVE_THEN "hp" (MP_TAC o SPECL [`u:A`; `w':A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `q':A = q` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EFUNS_UNIQUE]; ASM_MESON_TAC[EOPAIR_UNIQUE]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ff:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "ffc"))) THEN
  EXISTS_TAC `ff:A` THEN ASM_REWRITE_TAC[] THEN
  MAP_EVERY X_GEN_TAC [`n:A`; `q:A`] THEN STRIP_TAC THEN
  REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REMOVE_THEN "ffc" (MP_TAC o SPEC `p:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    REMOVE_THEN "hp" (MP_TAC o SPECL [`u:A`; `p:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `q':A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `q:A`; `u:A`; `q':A`;
      `p:A`] EOPAIR_INJ) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(CONJUNCTS_THEN SUBST_ALL_TAC) THEN ASM_REWRITE_TAC[];
    STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `q:A`]
      EOPAIR_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `p:A`) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    REMOVE_THEN "ffc" (MP_TAC o SPEC `p:A`) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN EXISTS_TAC `n:A` THEN ASM_REWRITE_TAC[] THEN
    REMOVE_THEN "hp" (MP_TAC o SPECL [`n:A`; `p:A`]) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN EXISTS_TAC `q:A` THEN ASM_REWRITE_TAC[]]);;

let EFINSEQ_CARD_LE = prove
 (`!D (E:A->A->bool) om x kk ei fs.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
     eomega D E om /\ ecardinal D E kk /\ (E om kk \/ om = kk) /\
     x IN D /\ einj D E ei x kk /\ fs IN D /\ kk IN D /\
     (!r. r IN D
          ==> (E r fs <=>
               eisfun D E r /\
               (?m. m IN D /\ E m om /\ edomain D E r m) /\
               !i u. i IN D /\ u IN D /\ eapply D E r i u
                     ==> E u x))
     ==> ?e. einj D E e fs kk`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN
   `(om:A) IN D /\ eordinal D (E:A->A->bool) om /\ eordinal D E kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive; EOMEGA_ORDINAL; ecardinal; ecardof];
    ALL_TAC] THEN
  SUBGOAL_THEN `?ea. einj D (E:A->A->bool) ea om kk` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] EBIJ_ID) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
    EXISTS_TAC `h:A` THEN MATCH_MP_TAC EINJ_WEAKEN THEN
    EXISTS_TAC `om:A` THEN ASM_SIMP_TAC[EBIJ_EINJ] THEN
    ASM_MESON_TAC[EORDINAL_TRANS_MEM];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`] EFUNS_GRAPH) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `ff:A` STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC EGEN_UNION_CARD_LE THEN
  MAP_EVERY EXISTS_TAC [`om:A`; `om:A`; `ea:A`; `fs:A`; `ff:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [ASM_MESON_TAC[EFUNS_UNIQUE];
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN ASM_SIMP_TAC[] THEN EQ_TAC THENL
     [STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `x:A`]
        EFUNS_EXISTS) THEN
      ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      MAP_EVERY EXISTS_TAC [`m:A`; `z:A`] THEN ASM_MESON_TAC[efuns];
      ASM_MESON_TAC[efuns]];
    X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `x:A`]
      EFUNS_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
    FIRST_ASSUM(STRIP_ASSUME_TAC o GEN_REWRITE_RULE I [efuns]) THEN
    EXISTS_TAC `z:A` THEN ASM_SIMP_TAC[] THEN CONJ_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `kk:A`;
      `ei:A`; `b:A`; `z:A`] ESEQ_INJEX) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[einj]]);;

(* ------------------------------------------------------------------------- *)
(* Toward |Def(x)| <= max(|x|,om): internalize the canonical-key map.        *)
(* keymap_form (out = <c,rt>) bridges to elkey via HOLDS_LKEY_FORM (slots    *)
(* om=18,hf=19,ho=17,x=1,r=12,y=9,c=4,nc=20,rt=21); keymapg_form wraps one   *)
(* more pair so out = <y,<c,rt>> is the graph pair, and ekeyval is the value *)
(* relation t=<c,rt> of the key map.  These feed the Def-injection graph     *)
(* (built by ZF_REPLACEMENT along keymapg_form, like EFINSEQ_CARD_LE).       *)
(* ------------------------------------------------------------------------- *)

let keymap_form = new_definition
  `keymap_form =
     ?? 4 (?? 20 (?? 21 (lkey_form && opair_form 4 21 2)))`;;

let HOLDS_KEYMAP_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v keymap_form <=>
          ?c. c IN D /\ ?nc. nc IN D /\ ?rt. rt IN D /\
              elkey D E (v 18) (v 19) (v 17) (v 1) (v 12) (v 9)
                    c nc rt /\
              eopair D E c rt (v 2))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[keymap_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `nc:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `rt:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v))`]
    HOLDS_LKEY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(21 |-> (rt:A)) ((20 |-> (nc:A)) ((4 |-> (c:A)) v))`;
    `4`; `21`; `2`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]);;

let ekeyval = new_definition
  `ekeyval D (E:A->A->bool) om hf ho x r y t <=>
     ?c nc rt. c IN D /\ nc IN D /\ rt IN D /\
               elkey D E om hf ho x r y c nc rt /\
               eopair D E c rt t`;;

let keymapg_form = new_definition
  `keymapg_form = ?? 2 (keymap_form && opair_form 9 2 25)`;;

let HOLDS_KEYMAPG_FORM = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v keymapg_form <=>
          ?p. p IN D /\
              ekeyval D E (v 18) (v 19) (v 17) (v 1) (v 12) (v 9) p /\
              eopair D E (v 9) p (v 25))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[keymapg_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((2 |-> (p:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (p:A)) v`]
    HOLDS_KEYMAP_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(2 |-> (p:A)) v`;
    `9`; `2`; `25`] HOLDS_OPAIR_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[ekeyval] THEN MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Adding one point to a kk-injection, kk an infinite cardinal: if a >-> kk  *)
(* and b = a cup {pt} with pt notin a, then b >-> kk.  Uses succ(kk) ~ kk    *)
(* (ESHIFT_EBIJ) to free a slot: map a via f into kk subset succ(kk), pt to  *)
(* kk itself, then compose with the bijection succ(kk) -> kk.  (Handles the  *)
(* empty set in |Def(x)| <= kk, which has no elkey.)                         *)
(* ------------------------------------------------------------------------- *)

let EINJ_INSERT_INFINITE = prove
 (`!D (E:A->A->bool) om kk a b f pt.
     model D E ZF_AX /\ eomega D E om /\ ecardinal D E kk /\
     (E om kk \/ om = kk) /\
     a IN D /\ b IN D /\ pt IN D /\ ~(E pt a) /\ einj D E f a kk /\
     (!z. z IN D ==> (E z b <=> E z a \/ z = pt))
     ==> ?e. einj D E e b kk`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 ge h4 h5 h6 npt fi bc" THEN
  USE_THEN "fi" (fun th ->
    let t = REWRITE_RULE[einj] th in
    MAP_EVERY (fun (l,c) -> LABEL_TAC l c)
     ["fbd",CONJUNCT1 t;
      "fmaps",CONJUNCT1(CONJUNCT2 t);
      "ftot",CONJUNCT1(CONJUNCT2(CONJUNCT2 t));
      "fsv",CONJUNCT1(CONJUNCT2(CONJUNCT2(CONJUNCT2 t)));
      "finj",CONJUNCT2(CONJUNCT2(CONJUNCT2(CONJUNCT2 t)))]) THEN
  SUBGOAL_THEN `(kk:A) IN D /\ eordinal D (E:A->A->bool) kk`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `?k:A. esuc D (E:A->A->bool) kk k`
    (X_CHOOSE_TAC `k:A`) THENL
   [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(k:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w:A. w IN D ==> ((E:A->A->bool) w k <=> E w kk \/ w = kk)`
  (LABEL_TAC "kc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `k:A`]
      ESUC_ALT) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(CONJUNCT2(REWRITE_RULE[th]
      (ASSUME `esuc D (E:A->A->bool) kk k`)))) THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) kk k` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`; `k:A`]
    ESHIFT_EBIJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) h k kk` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBIJ_EINJ]; ALL_TAC] THEN
  SUBGOAL_THEN `?pp:A. eopair D (E:A->A->bool) pt kk pp`
    (X_CHOOSE_TAC `pp:A`) THENL
   [ASM_MESON_TAC[EOPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `?sg:A. epair D (E:A->A->bool) pp pp sg`
    (X_CHOOSE_TAC `sg:A`) THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D /\
    !w:A. w IN D ==> ((E:A->A->bool) w sg <=> w = pp)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sgc")) THENL
   [UNDISCH_TAC `epair D (E:A->A->bool) pp pp sg` THEN
    REWRITE_TAC[epair] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ec")) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `w:A` THEN DISCH_TAC THEN
    USE_THEN "ec" (MP_TAC o SPEC `w:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    ALL_TAC] THEN
  SUBGOAL_THEN `?g1:A. ebunion D (E:A->A->bool) f sg g1`
    (X_CHOOSE_TAC `g1:A`) THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(g1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D ==> ((E:A->A->bool) z g1 <=> E z f \/ z = pp)`
  (LABEL_TAC "g1c") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    UNDISCH_TAC `ebunion D (E:A->A->bool) f sg g1` THEN
    REWRITE_TAC[ebunion] THEN
    DISCH_THEN(X_CHOOSE_THEN `pfs:A` (CONJUNCTS_THEN2 (LABEL_TAC "epfs")
      (LABEL_TAC "eun"))) THEN
    SUBGOAL_THEN `(f:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!t:A. t IN D ==> ((E:A->A->bool) t pfs <=> t = f \/ t = sg)`
    (LABEL_TAC "pfsc") THENL
     [UNDISCH_TAC `epair D (E:A->A->bool) f sg pfs` THEN
      REWRITE_TAC[epair] THEN
      DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) ACCEPT_TAC);
      ALL_TAC] THEN
    USE_THEN "eun" MP_TAC THEN REWRITE_TAC[eunion] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (K ALL_TAC) (MP_TAC o SPEC `z:A`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_MESON_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!bb w:A. bb IN D /\ w IN D
      ==> (eapply D (E:A->A->bool) g1 bb w <=>
           eapply D E f bb w \/ (bb = pt /\ w = kk))`
  (LABEL_TAC "apc") THENL
   [MAP_EVERY X_GEN_TAC [`bb:A`; `w:A`] THEN STRIP_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `?z:A. eopair D (E:A->A->bool) bb w z /\ E z g1`
      (X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THENL
       [UNDISCH_TAC `eapply D (E:A->A->bool) g1 bb w` THEN
        REWRITE_TAC[eapply] THEN DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "g1c" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(REWRITE_RULE[th]
        (ASSUME `(E:A->A->bool) z g1`))) THEN
      DISCH_THEN(DISJ_CASES_THEN2 ASSUME_TAC SUBST_ALL_TAC) THENL
       [DISJ1_TAC THEN REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
        ASM_REWRITE_TAC[];
        DISJ2_TAC THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `bb:A`; `w:A`;
          `pt:A`; `kk:A`; `pp:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN(DISJ_CASES_THEN2 (LABEL_TAC "ef")
        (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC)) THENL
       [REWRITE_TAC[eapply] THEN
        USE_THEN "ef" (MP_TAC o REWRITE_RULE[eapply]) THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` (CONJUNCTS_THEN2 ASSUME_TAC
          ASSUME_TAC)) THEN
        EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
        SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
         [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
        USE_THEN "g1c" (MP_TAC o SPEC `z:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        REWRITE_TAC[eapply] THEN EXISTS_TAC `pp:A` THEN
        ASM_REWRITE_TAC[] THEN
        USE_THEN "g1c" (MP_TAC o SPEC `pp:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th])]];
    ALL_TAC] THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) g1 b k` ASSUME_TAC THENL
   [REWRITE_TAC[einj] THEN ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`bb:A`; `w:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) f bb w \/ (bb = pt /\ w = kk)`
      (LABEL_TAC "d1") THENL
       [USE_THEN "apc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      USE_THEN "bc" (fun b -> USE_THEN "kc" (fun k -> USE_THEN "fmaps"
        (fun m -> ASM_MESON_TAC[b; k; m])));
      X_GEN_TAC `bb:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) (bb:A) a \/ bb = pt` (LABEL_TAC "cse") THENL
       [USE_THEN "bc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      USE_THEN "cse"
        (DISJ_CASES_THEN2 (LABEL_TAC "iba") (LABEL_TAC "ispt")) THENL
        [SUBGOAL_THEN
         `?w:A. w IN D /\ E w kk /\ eapply D (E:A->A->bool) f bb w`
        (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THENL
         [USE_THEN "ftot" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        EXISTS_TAC `w:A` THEN REPEAT CONJ_TAC THENL
         [ASM_REWRITE_TAC[];
          USE_THEN "kc" (fun th -> ASM_MESON_TAC[th]);
          USE_THEN "apc" (MP_TAC o SPECL [`bb:A`; `w:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
        EXISTS_TAC `kk:A` THEN REPEAT CONJ_TAC THENL
         [ASM_REWRITE_TAC[];
          USE_THEN "kc" (fun th -> ASM_MESON_TAC[th]);
          USE_THEN "ispt" SUBST1_TAC THEN
          USE_THEN "apc" (MP_TAC o SPECL [`pt:A`; `kk:A`]) THEN
          ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
          DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]];
      MAP_EVERY X_GEN_TAC [`bb:A`; `w:A`; `w':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) f bb w \/ (bb = pt /\ w = kk)`
      (LABEL_TAC "d1") THENL
       [USE_THEN "apc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) f bb w' \/ (bb = pt /\ w' = kk)`
      (LABEL_TAC "d2") THENL
       [USE_THEN "apc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      USE_THEN "d1" (DISJ_CASES_THEN2 (LABEL_TAC "a1")
        (CONJUNCTS_THEN2 (LABEL_TAC "e1") (LABEL_TAC "v1"))) THEN
      USE_THEN "d2" (DISJ_CASES_THEN2 (LABEL_TAC "a2")
        (CONJUNCTS_THEN2 (LABEL_TAC "e2") (LABEL_TAC "v2"))) THENL
       [USE_THEN "fsv" MATCH_MP_TAC THEN EXISTS_TAC `bb:A` THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(E:A->A->bool) bb a` MP_TAC THENL
         [USE_THEN "fmaps" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
        USE_THEN "e2" SUBST1_TAC THEN ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(E:A->A->bool) bb a` MP_TAC THENL
         [USE_THEN "fmaps" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
        USE_THEN "e1" SUBST1_TAC THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[]];
      MAP_EVERY X_GEN_TAC [`bb:A`; `bb':A`; `w:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) f bb w \/ (bb = pt /\ w = kk)`
      (LABEL_TAC "d1") THENL
       [USE_THEN "apc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) f bb' w \/ (bb' = pt /\ w = kk)`
      (LABEL_TAC "d2") THENL
       [USE_THEN "apc" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
      USE_THEN "d1" (DISJ_CASES_THEN2 (LABEL_TAC "a1")
        (CONJUNCTS_THEN2 (LABEL_TAC "e1") (LABEL_TAC "v1"))) THEN
      USE_THEN "d2" (DISJ_CASES_THEN2 (LABEL_TAC "a2")
        (CONJUNCTS_THEN2 (LABEL_TAC "e2") (LABEL_TAC "v2"))) THENL
       [USE_THEN "finj" MATCH_MP_TAC THEN EXISTS_TAC `w:A` THEN
        ASM_REWRITE_TAC[];
        SUBGOAL_THEN `(E:A->A->bool) w kk` MP_TAC THENL
         [USE_THEN "fmaps" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
        USE_THEN "v2" SUBST1_TAC THEN ASM_MESON_TAC[E_IRREFL];
        SUBGOAL_THEN `(E:A->A->bool) w kk` MP_TAC THENL
         [USE_THEN "fmaps" (fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
        USE_THEN "v1" SUBST1_TAC THEN ASM_MESON_TAC[E_IRREFL];
        ASM_MESON_TAC[]]];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g1:A`; `h:A`; `b:A`;
    `k:A`; `kk:A`] EINJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e:A`) THEN
  EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* ekeyval helper lemmas for |Def(x)| <= kk.  ekeyval D E om hf ho x r y t   *)
(* means t = <c,rt> is the canonical key of the (nonempty, definable) subset *)
(* y of x.  EKEYVAL_EXISTS: every nonempty y in Def(x) has a key (bridges    *)
(* edefmem to ELKEY_EXISTS via EOMEGA_UNIQUE + edefby).  EKEYVAL_FUN: the    *)
(* key is functional in y (ELKEY_UNIQUE, needs r asymmetric).  EKEYVAL_INJ:  *)
(* the key determines y (ELKEY_INJ + ELKEY_STAGE_UNIQUE + EOPAIR_INJ).       *)
(* EKEYVAL_RANGE: the key lies in hf x FS(x) (ELKEY_IN c in hf, ELKEY_RT_FUN *)
(* rt a finite sequence over x).                                             *)
(* ------------------------------------------------------------------------- *)

let EKEYVAL_EXISTS = prove
 (`!D (E:A->A->bool) om hf ho x r y.
     model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
     ehford D E om ho /\ x IN D /\ r IN D /\
     (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
          (?t. t IN D /\ E t z)
          ==> ?m. m IN D /\ E m z /\
                  !t. t IN D /\ E t z /\ ~(t = m)
                      ==> erel D E r m t) /\
     y IN D /\ edefmem D E x y /\ ~(eempty D E y)
     ==> ?c nc rt. elkey D E om hf ho x r y c nc rt`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 rcond h7 dm nemp" THEN
  USE_THEN "dm" MP_TAC THEN REWRITE_TAC[edefmem] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "sub") (DISJ_CASES_THEN2
    (fun ee -> USE_THEN "nemp" (fun n -> ASM_MESON_TAC[ee; n]))
    (X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `vs:A` (X_CHOOSE_THEN `c0:A`
      (X_CHOOSE_THEN `s0:A` (X_CHOOSE_THEN `z0:A`
        STRIP_ASSUME_TAC))))))) THEN
  SUBGOAL_THEN `(om':A) = om` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC EOMEGA_UNIQUE THEN MAP_EVERY EXISTS_TAC
      [`D:A->bool`; `E:A->A->bool`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MATCH_MP_TAC ELKEY_EXISTS THEN REPEAT CONJ_TAC THEN
  FIRST [ASM_REWRITE_TAC[] THEN NO_TAC;
         USE_THEN "rcond" ACCEPT_TAC;
         USE_THEN "sub" ACCEPT_TAC;
         USE_THEN "nemp" ACCEPT_TAC;
         (MAP_EVERY EXISTS_TAC [`vs:A`; `z0:A`; `c0:A`; `s0:A`] THEN
          ASM_REWRITE_TAC[] THEN REWRITE_TAC[edefby] THEN
          ASM_REWRITE_TAC[])]);;

let EKEYVAL_FUN = prove
 (`!D (E:A->A->bool) om hf ho x r y t t'.
     model D E ZF_AX /\ eomega D E om /\ ehford D E om ho /\
     (!a b. a IN D /\ b IN D /\ erel D E r a b ==> ~(erel D E r b a)) /\
     ekeyval D E om hf ho x r y t /\ ekeyval D E om hf ho x r y t'
     ==> t = t'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ekeyval] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 (LABEL_TAC "rasym")
      (CONJUNCTS_THEN2
        (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `nc:A` (X_CHOOSE_THEN `rt:A`
          STRIP_ASSUME_TAC)))
        (X_CHOOSE_THEN `c':A` (X_CHOOSE_THEN `nc':A` (X_CHOOSE_THEN `rt':A`
          STRIP_ASSUME_TAC)))))))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `ho:A`;
    `x:A`; `r:A`; `y:A`; `c:A`; `nc:A`; `rt:A`; `c':A`; `nc':A`; `rt':A`]
    ELKEY_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (CONJUNCTS_THEN2
    (K ALL_TAC) (SUBST_ALL_TAC o SYM))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rt:A`;
    `t:A`; `t':A`] EOPAIR_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let EKEYVAL_INJ = prove
 (`!D (E:A->A->bool) om hf ho x r y y' t.
     model D E ZF_AX /\ eomega D E om /\ ehfset D E om hf /\
     x IN D /\ y IN D /\ y' IN D /\
     esubset D E y x /\ esubset D E y' x /\
     ekeyval D E om hf ho x r y t /\ ekeyval D E om hf ho x r y' t
     ==> y = y'`,
  REPEAT GEN_TAC THEN REWRITE_TAC[ekeyval] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2
            (X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `nc:A` (X_CHOOSE_THEN `rt:A`
              STRIP_ASSUME_TAC)))
            (X_CHOOSE_THEN `c':A` (X_CHOOSE_THEN `nc':A`
              (X_CHOOSE_THEN `rt':A` STRIP_ASSUME_TAC)))))))))))) THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ nc IN D /\ rt IN D /\ c' IN D /\ nc' IN D /\ rt' IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `rt:A`;
    `c':A`; `rt':A`; `t:A`] EOPAIR_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (SUBST_ALL_TAC o SYM) (SUBST_ALL_TAC o SYM)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `ho:A`;
    `x:A`; `r:A`; `y:A`; `y':A`; `c:A`; `nc:A`; `rt:A`; `nc':A`; `rt:A`]
    ELKEY_STAGE_UNIQUE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(SUBST_ALL_TAC o SYM) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `ho:A`;
    `x:A`; `r:A`; `y:A`; `y':A`; `c:A`; `nc:A`; `rt:A`] ELKEY_INJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN ACCEPT_TAC);;

let EKEYVAL_RANGE = prove
 (`!D (E:A->A->bool) om hf ho x r fs y t.
     model D E ZF_AX /\ eomega D E om /\ x IN D /\ fs IN D /\
     (!rr. rr IN D
           ==> (E rr fs <=>
                eisfun D E rr /\
                (?n. n IN D /\ E n om /\ edomain D E rr n) /\
                !i u. i IN D /\ u IN D /\ eapply D E rr i u
                      ==> E u x)) /\
     ekeyval D E om hf ho x r y t
     ==> ?a b. a IN D /\ b IN D /\ E a hf /\ E b fs /\
               eopair D E a b t`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 fsc +" THEN
  REWRITE_TAC[ekeyval] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `nc:A`
    (X_CHOOSE_THEN `rt:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN
   `(c:A) IN D /\ (E:A->A->bool) c hf /\ nc IN D /\ E nc om /\ rt IN D`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELKEY_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) rt /\ edomain D E rt nc /\
    (!i u. i IN D /\ u IN D /\ eapply D E rt i u ==> E u x)`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ELKEY_RT_FUN THEN
    MAP_EVERY EXISTS_TAC [`om:A`; `hf:A`; `ho:A`; `r:A`; `y:A`; `c:A`] THEN
    ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rt fs` ASSUME_TAC THENL
   [USE_THEN "fsc" (MP_TAC o SPEC `rt:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN EXISTS_TAC `nc:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `rt:A`] THEN ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* |Def(x)| <= kk for an infinite cardinal kk with x >-> kk and hf >-> kk.   *)
(* Each nonempty definable subset y of x has a canonical key <c,rt> (c an hf *)
(* code in hf, rt its r-least parameter tuple, a finite function into x, so  *)
(* rt in FS(x)); this key determines y (EKEYVAL_INJ) and is functional in y  *)
(* (EKEYVAL_FUN).  The key map y |-> <y,<c,rt>> is internalized by           *)
(* keymapg_form; its graph over the nonempty definable subsets is built by   *)
(* ZF_REPLACEMENT, giving Def(x)\{empty} >-> hf x FS(x) >-> kk x kk ~ kk     *)
(* (EFINSEQ_CARD_LE + ECROSS_CARD_LE).  The empty set is inserted by         *)
(* EINJ_INSERT_INFINITE.  r must wellorder the subsets of x and be           *)
(* asymmetric (both available from the definable wellorder in the elmem/L    *)
(* context).                                                                 *)
(* ------------------------------------------------------------------------- *)

let EDEF_CARD_LE = prove
 (`!D (E:A->A->bool) om hf ho x r kk ei ehf d.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
     eomega D E om /\ ehfset D E om hf /\ ehford D E om ho /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\
     x IN D /\ einj D E ei x kk /\ hf IN D /\ einj D E ehf hf kk /\
     r IN D /\
     (!z. z IN D /\ (!t. t IN D /\ E t z ==> E t x) /\
          (?t. t IN D /\ E t z)
          ==> ?m. m IN D /\ E m z /\
                  !t. t IN D /\ E t z /\ ~(t = m) ==> erel D E r m t) /\
     (!a b. a IN D /\ b IN D /\ erel D E r a b ==> ~(erel D E r b a)) /\
     edef D E x d
     ==> ?e. einj D E e d kk`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 lm h2 h3 h4 h5 ge h6 eic h7 ehfc h8 rcond rasym dc" THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `(kk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[edef]; ALL_TAC] THEN
  SUBGOAL_THEN `(ho:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehford]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`]
    EFINSEQ_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `fs:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "fsc"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`; `kk:A`;
    `ei:A`; `fs:A`] EFINSEQ_CARD_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "fsc" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ef:A`) THEN
  SUBGOAL_THEN `?hpr:A. ecross D (E:A->A->bool) hf fs hpr`
    (X_CHOOSE_TAC `hpr:A`) THENL
   [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(hpr:A) IN D /\
    !z:A. z IN D
          ==> ((E:A->A->bool) z hpr <=>
               ?a b. a IN D /\ b IN D /\ E a hf /\ E b fs /\
                     eopair D E a b z)`
  (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "hprc")) THENL
   [UNDISCH_TAC `ecross D (E:A->A->bool) hf fs hpr` THEN
    REWRITE_TAC[ecross] THEN DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `kk:A`; `hf:A`;
    `fs:A`; `hpr:A`; `ehf:A`; `ef:A`] ECROSS_CARD_LE) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN USE_THEN "lm" ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ehpr:A`) THEN
  SUBGOAL_THEN `?e0:A. eempty D (E:A->A->bool) e0`
    (X_CHOOSE_TAC `e0:A`) THENL
   [ASM_MESON_TAC[EEMPTY_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(e0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `esubset D (E:A->A->bool) e0 x` ASSUME_TAC THENL
   [REWRITE_TAC[esubset] THEN ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e0 d` ASSUME_TAC THENL
   [USE_THEN "dc" (fun th ->
      MP_TAC(SPEC `e0:A` (CONJUNCT2(REWRITE_RULE[edef] th)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[edefmem] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0`
    (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`?? 1 (1 %% 0)`; `0`; `v0:num->A`; `d:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `dne:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "dne0"))) THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> ((E:A->A->bool) y dne <=> E y d /\ ~(eempty D E y))`
  (LABEL_TAC "dnec") THENL
   [X_GEN_TAC `y:A` THEN DISCH_TAC THEN
    USE_THEN "dne0" (MP_TAC o SPEC `y:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[HOLDS_EX; holds] THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    MATCH_MP_TAC(TAUT `(p <=> q) ==> ((a /\ p) <=> (a /\ q))`) THEN
    REWRITE_TAC[eempty] THEN ASM_MESON_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
