(* ------------------------------------------------------------------------- *)
(* Towards EFUNIMAGE_CARD_LE. achievedval_form and HOLDS_ACHIEVEDVAL: d      *)
(* (slot 0) is an achieved ed-value of u (slot 9), for EORDINAL_LEAST.       *)
(* EFUNIMG_NOMIN unpacks the E-least achievedval condition. EFUNIMG_FUN: the *)
(* ZF_REPLACEMENT functionality condition for funimg_form, i.e. each u in    *)
(* the range maps to a unique <u, min-ed(u)> (the minimum exists by          *)
(* EORDINAL_LEAST, and is unique by ordinal trichotomy and eisfun f).        *)
(* ------------------------------------------------------------------------- *)

let achievedval_form = new_definition
  `achievedval_form = ?? 6
   ((6 %% 4) && (apply_form 3 6 0 && apply_form 2 6 9))`;;

let HOLDS_ACHIEVEDVAL = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v achievedval_form <=>
          ?k. k IN D /\ E k (v 4) /\ eapply D E (v 3) k (v 0) /\
              eapply D E (v 2) k (v 9))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[achievedval_form; HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. a IN D ==> (P a <=> Q a))
    ==> ((?a. a IN D /\ P a) <=> (?a. a IN D /\ Q a))`) THEN
  X_GEN_TAC `kk1:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((6 |-> (kk1:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[HOLDS_AND] THEN
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `(6 |-> (kk1:A)) v`; `3`; `6`; `0`]
         HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL
         [`D:A->bool`; `E:A->A->bool`; `(6 |-> (kk1:A)) v`; `2`; `6`; `9`]
         HOLDS_APPLY_FORM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
   `~(0 = 2) /\
      ~(0 = 3) /\
      ~(0 = 4) /\
      ~(0 = 6) /\
      ~(0 = 9) /\
      ~(2 = 3) /\
      ~(2 = 4) /\
      ~(2 = 6) /\
      ~(2 = 9) /\
      ~(3 = 4) /\
      ~(3 = 6) /\
      ~(3 = 9) /\
      ~(4 = 6) /\
      ~(4 = 9) /\
      ~(6 = 9)`]);;

let EFUNIMG_NOMIN = prove
 (`!D (E:A->A->bool) kk dm ed f v u n0.
     model D E ZF_AX /\ kk IN D /\ eordinal D E kk /\
     dm IN D /\ einj D E ed dm kk /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = f /\ v 3 = ed /\ v 4 = dm /\ u IN D /\ n0 IN D /\
     valuation D ((9 |-> u) v) /\
     (!c. c IN D /\ E c n0
          ==> ~holds D E ((0 |-> c) ((9 |-> u) v)) achievedval_form)
     ==> (!c. c IN D /\ E c n0
              ==> ~(?kx. kx IN D /\ E kx dm /\ eapply D E ed kx c /\
                         eapply D E f kx u))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  X_GEN_TAC `c:A` THEN STRIP_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `c:A`) THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (c:A)) ((9 |-> u) v)`]
    HOLDS_ACHIEVEDVAL) THEN
  ANTS_TAC THENL
   [CONJ_TAC THENL
     [ASM_REWRITE_TAC[];
      REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[])];
    ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(0 = 1) /\
      ~(0 = 2) /\
      ~(0 = 3) /\
      ~(0 = 4) /\
      ~(0 = 9) /\
      ~(1 = 2) /\
      ~(1 = 3) /\
      ~(1 = 4) /\
      ~(1 = 9) /\
      ~(2 = 3) /\
      ~(2 = 4) /\
      ~(2 = 9) /\
      ~(3 = 4) /\
      ~(3 = 9) /\
      ~(4 = 9)`]);;

let EFUNIMG_FUN = prove
 (`!D (E:A->A->bool) kk dm ed f v u.
     model D E ZF_AX /\ kk IN D /\ eordinal D E kk /\
     dm IN D /\ einj D E ed dm kk /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = f /\ v 3 = ed /\ v 4 = dm /\
     u IN D /\ (?k. k IN D /\ E k dm /\ eapply D E f k u)
     ==> ?w. w IN D /\
             !w'. w' IN D /\
                  holds D E ((1 |-> w') ((0 |-> u) v)) funimg_form ==> w' = w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?d0. d0 IN D /\ (E:A->A->bool) d0 kk /\ eapply D E ed k d0`
