(* EFUNIMG_EX: the existence half of the image-counting replacement: the     *)
(* min-preimage witness <u, min-ed(u)> satisfies funimg_form (so it lands in *)
(* the replacement image). This is needed for the totality of the injection. *)
(* ------------------------------------------------------------------------- *)

let EFUNIMG_EX = prove
 (`!D (E:A->A->bool) kk dm ed f v u.
     model D E ZF_AX /\ kk IN D /\ eordinal D E kk /\
     dm IN D /\ einj D E ed dm kk /\ f IN D /\ eisfun D E f /\
     valuation D v /\ v 2 = f /\ v 3 = ed /\ v 4 = dm /\
     u IN D /\ (?k. k IN D /\ E k dm /\ eapply D E f k u)
     ==> ?w. w IN D /\ holds D E ((1 |-> w) ((0 |-> u) v)) funimg_form`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?d0. d0 IN D /\ (E:A->A->bool) d0 kk /\ eapply D E ed k d0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[einj]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) d0` ASSUME_TAC THENL
   [MATCH_MP_TAC EORDINAL_MEMBER THEN EXISTS_TAC `kk:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((9 |-> (u:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `holds D E ((0 |-> (d0:A)) ((9 |-> u) v)) achievedval_form`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (d0:A)) ((9 |-> u) v)`]
      HOLDS_ACHIEVEDVAL) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[])];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXISTS_TAC `k:A` THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(0 = 1) /\
      ~(0 = 2) /\
      ~(0 = 3) /\
      ~(0 = 4) /\
      ~(0 = 9) /\
      ~(1 = 2) /\
      ~(1 = 3) /\
      ~(1 = 4) /\
      ~(1 = 9) /\
      ~(2 = 3) /\
      ~(2 = 4) /\
      ~(2 = 9) /\
      ~(3 = 4) /\
      ~(3 = 9) /\
      ~(4 = 9)`];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `achievedval_form`;
    `(9 |-> (u:A)) v`; `d0:A`] EORDINAL_LEAST) THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@n0. h1 h2 n0ach n0min" THEN
  SUBGOAL_THEN
   `?k1. k1 IN D /\ (E:A->A->bool) k1 dm /\ eapply D E ed k1 n0 /\
         eapply D E f k1 u`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (n0:A)) ((9 |-> u) v)`]
      HOLDS_ACHIEVEDVAL) THEN
    ANTS_TAC THENL
     [CONJ_TAC THENL
       [ASM_REWRITE_TAC[];
        REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[])];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> USE_THEN "n0ach" (MP_TAC o REWRITE_RULE[th])) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
       `~(0 = 1) /\
      ~(0 = 2) /\
      ~(0 = 3) /\
      ~(0 = 4) /\
      ~(0 = 9) /\
      ~(1 = 2) /\
      ~(1 = 3) /\
      ~(1 = 4) /\
      ~(1 = 9) /\
      ~(2 = 3) /\
      ~(2 = 4) /\
      ~(2 = 9) /\
      ~(3 = 4) /\
      ~(3 = 9) /\
      ~(4 = 9)`] THEN
    DISCH_THEN(X_CHOOSE_THEN `k1:A` STRIP_ASSUME_TAC) THEN
