    X_GEN_TAC `m:A` THEN STRIP_TAC THEN
    DISCH_THEN(X_CHOOSE_THEN `kx:A` STRIP_ASSUME_TAC) THEN
    USE_THEN "n0min2" (MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[] THEN
