let pdclstep_form = new_definition
  `pdclstep_form =
     !! 2 (2 %% 1 <->
        ((2 %% 5) ||
         (?? 3 (?? 4 (applyto_form 3 4 0 && pdclmem_form)))))`;;

let HOLDS_PDCLSTEP = prove
 (`!D (E:A->A->bool) v.
     model D E ZF_AX /\ valuation D v
     ==> (holds D E v pdclstep_form <=>
          (!u. u IN D
