                               (E u (v 6) /\
                                (?ww. ww IN D /\ eupdate D E r' (v 8) u ww /\
                                      (?pv. pv IN D /\
                                       (!b. b IN D ==> !u. u IN D ==>
                                        eapply D E ww b u ==>
