let GACC_MEM = prove
 (`!D (E:A->A->bool) X e r gacc w.
      model D E ZF_AX /\ X IN D /\ r IN D /\ gacc IN D /\ w IN D /\
      (!pp. pp IN D
            ==> (E pp r <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' e /\
                         ecolltower D E X b' z' /\ eopair D E b' z' pp)) /\
      (!ww. ww IN D
            ==> (E ww gacc <=>
                 ?b. b IN D /\ ?p. p IN D /\ ?l. l IN D /\ ?g. g IN D /\
                     eapply D E r b p /\ eopair D E l g p /\ E ww g))
      ==> (E w gacc <=>
           ?c zc lc gc. c IN D /\ zc IN D /\ lc IN D /\ gc IN D /\
                        E c e /\ ecolltower D E X c zc /\
                        eopair D E lc gc zc /\ E w gc)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 rch gch" THEN
  USE_THEN "gch" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `l:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `g:A` (CONJUNCTS_THEN2 ASSUME_TAC
            STRIP_ASSUME_TAC)))))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) b e /\ ecolltower D E X b p`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `ecolltower D (E:A->A->bool) X`;`e:A`;`r:A`;`b:A`;`p:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`b:A`;`p:A`;`l:A`;`g:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `zc:A`
      (X_CHOOSE_THEN `lc:A` (X_CHOOSE_THEN `gc:A`
        STRIP_ASSUME_TAC)))) THEN
    EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `zc:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `lc:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `gc:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `ecolltower D (E:A->A->bool) X`;`e:A`;`r:A`;`c:A`;`zc:A`]
      EGRAPH_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let goodf2 = new_definition
  `goodf2 =
     ?? 87 (?? 88 (?? 89
       (apply_form 81 0 87 && (opair_form 88 89 87 &&
        !!- 86 0 (?? 90 (?? 91 (?? 92
          (apply_form 81 86 90 && (opair_form 91 92 90 &&
           subset_form 92 89)))))))))`;;

let HOLDS_GOODF2 = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v goodf2 <=>
          ?pb. pb IN D /\ ?lb. lb IN D /\ ?gb. gb IN D /\
               eapply D E (v 81) (v 0) pb /\ eopair D E lb gb pb /\
               !c. c IN D /\ E c (v 0)
                   ==> ?pc. pc IN D /\ ?lc. lc IN D /\ ?gc. gc IN D /\
                            eapply D E (v 81) c pc /\
                            eopair D E lc gc pc /\
                            esubset D E gc gb)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[goodf2; holds; HOLDS_EX; HOLDS_AND] THEN
  SIMP_TAC[HOLDS_FORALLMEM; ARITH_RULE `~(86 = 0)`] THEN
  REWRITE_TAC[holds; HOLDS_EX; HOLDS_AND] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!pb lb gb:A. pb IN D /\ lb IN D /\ gb IN D
     ==> (holds D E ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))
            (apply_form 81 0 87) <=> eapply D E (v 81) (v 0) pb) /\
         (holds D E ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))
            (opair_form 88 89 87) <=> eopair D E lb gb pb)`
  (LABEL_TAC "piles1") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((89 |-> (gb:A))((88 |-> lb)((87 |-> pb) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!pb lb gb c pc lc gc:A.
      pb IN D /\ lb IN D /\ gb IN D /\ c IN D /\ pc IN D /\ lc IN D /\
      gc IN D
      ==> (holds D E ((92 |-> gc)((91 |-> lc)((90 |-> pc)((86 |-> c)
               ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))))))
             (apply_form 81 86 90) <=> eapply D E (v 81) c pc) /\
          (holds D E ((92 |-> gc)((91 |-> lc)((90 |-> pc)((86 |-> c)
               ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))))))
             (opair_form 91 92 90) <=> eopair D E lc gc pc) /\
          (holds D E ((92 |-> gc)((91 |-> lc)((90 |-> pc)((86 |-> c)
               ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))))))
             (subset_form 92 89) <=> esubset D E gc gb)`
  (LABEL_TAC "piles2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((92 |-> (gc:A))((91 |-> lc)((90 |-> pc)((86 |-> c)
        ((89 |-> gb)((88 |-> lb)((87 |-> pb) v)))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM; HOLDS_SUBSET_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `pb:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `lb:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `gb:A` THEN DISCH_TAC THEN
  USE_THEN "piles1" (MP_TAC o SPECL [`pb:A`;`lb:A`;`gb:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (fun th -> REWRITE_TAC[th])
    (fun th -> REWRITE_TAC[th])) THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
  MATCH_MP_TAC(TAUT `(y <=> z) ==> ((x /\ y) <=> (x /\ z))`) THEN
