  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((!s. s IN D ==> P s) <=> (!s. s IN D ==> Q s))`) THEN
  X_GEN_TAC `c:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (y <=> z)) ==> ((p ==> y) <=> (p ==> z))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `pc:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `lc:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
