                   E c b' /\ ecolltower D E X c zc /\ eopair D E lc gc zc /\
                   ecolltower D E X b' zb /\ eopair D E lb gb zb
                   ==> esubset D E gc gb)
      ==> !c zc lc gc zd ld gd.
             c IN D /\ zc IN D /\ lc IN D /\ gc IN D /\
             zd IN D /\ ld IN D /\ gd IN D /\
             E c d /\ ecolltower D E X c zc /\ eopair D E lc gc zc /\
             ecolltower D E X d zd /\ eopair D E ld gd zd
