  EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[] THEN
  TRY(X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      USE_THEN "ich" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
