      USE_THEN "trans" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]));;

let ECOLLTOWER_COHERE = prove
 (`!D (E:A->A->bool) X a c zc lc gc za la ga.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      c IN D /\ zc IN D /\ lc IN D /\ gc IN D /\
      za IN D /\ la IN D /\ ga IN D /\
      E c a /\ ecolltower D E X c zc /\ eopair D E lc gc zc /\
      ecolltower D E X a za /\ eopair D E la ga za
      ==> esubset D E gc ga`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sa:A`) THEN
  SUBGOAL_THEN `(sa:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) a sa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`sa:A`]
    ECOLLTOWER_RESGRAPH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "rcc"))) THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((81 |-> (rc:A)) v0)`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!dd. dd IN D /\ E dd sa
         ==> holds D E ((0 |-> dd) ((81 |-> (rc:A)) v0)) goodf2`
  (LABEL_TAC "good") THENL
   [GEN_TAC THEN STRIP_TAC THEN
    MATCH_MP_TAC(TAUT `(~p ==> F) ==> p`) THEN
    DISCH_THEN(LABEL_TAC "bad0") THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) dd` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Not goodf2`;
                  `(81 |-> (rc:A)) v0`;`dd:A`]
      EORDINAL_LEAST) THEN
    ASM_REWRITE_TAC[HOLDS_NOT] THEN
    INTRO_TAC "@d. h1 h2 dbad dmin" THEN
    SUBGOAL_THEN `(d:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) d sa` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`dd:A`]
        EORDINAL_TRICHOTOMY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E];
        ASM_MESON_TAC[];
        USE_THEN "dmin" (MP_TAC o SPEC `dd:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        USE_THEN "bad0" (fun th -> REWRITE_TAC[th])];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b'. b' IN D /\ E b' d
           ==> !c zc lc gc zb lb gb.
                  c IN D /\ zc IN D /\ lc IN D /\ gc IN D /\
                  zb IN D /\ lb IN D /\ gb IN D /\
                  E c b' /\ ecolltower D (E:A->A->bool) X c zc /\
                  eopair D E lc gc zc /\
                  ecolltower D E X b' zb /\ eopair D E lb gb zb
                  ==> esubset D E gc gb`
    ASSUME_TAC THENL
     [X_GEN_TAC `b':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b' sa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`sa:A`;`rc:A`;
                    `v0:num->A`;`b':A`] GOODF2_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
      ANTS_TAC THENL
       [USE_THEN "dmin" (MP_TAC o SPEC `b':A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `holds D E ((0 |-> (d:A)) ((81 |-> (rc:A)) v0)) goodf2`
    MP_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`sa:A`;`rc:A`;
                    `v0:num->A`;`d:A`] GOODF2_SEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`d:A`]
        ECOLLTOWER_COHERE_STEP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      USE_THEN "dbad" (fun th -> REWRITE_TAC[th])];
    ALL_TAC] THEN
  USE_THEN "good" (MP_TAC o SPEC `a:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`sa:A`;`rc:A`;
                `v0:num->A`;`a:A`] GOODF2_SEM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o fst o EQ_IMP_RULE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`c:A`;`zc:A`;`lc:A`;`gc:A`;`za:A`;`la:A`;`ga:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The collapse map pi is the top collapse graph ga.                         *)
(* ECOLLTOWER_PI_RECURRENCE: E z pi(x) <=> ?y IN X INTER x. z = pi(y) (the   *)
(* characterization of gacc_a transfers to ga itself in both directions via  *)
(* GACC_MEM, ECOLLTOWER_COHERE, the rank, GD_DOM and GD_FUN).                *)
(* ECOLLTOWER_PI_TOTAL: pi is defined on X INTER la. ECOLLTOWER_PI_MONO:     *)
(* x IN y ==> pi x IN pi y. badinj (slots d = 0, X = 67, rc = 81, ga = 82;   *)
(* scratch 93-98) says that two distinct X-elements of fst(rc d) share a     *)
(* pi-value; HOLDS_BADINJ and BADINJ_SEM are the usual layers.               *)
(* BADPAIR_DESCEND: from a shared-value pair at level d and an X-witness u   *)
(* distinguishing them, produce a shared-value pair at some level c < d (the *)
(* ranks of u and of the recurrence partner u2 via ELSTAGE_MEM_MEM_D, a      *)
(* common level by trichotomy and ELSTAGE_MONO). ECOLLTOWER_PI_INJ: pi is    *)
(* injective on any extensional X (least bad ordinal on badinj; the initial  *)
(* bad pair lives at level a). ECOLLTOWER_PI_ISO: E (pi x) (pi y) <=> E x y  *)
(* on extensional X.                                                         *)
(* ------------------------------------------------------------------------- *)

let ECOLLTOWER_PI_RECURRENCE = prove
 (`!D (E:A->A->bool) X a za la ga x i.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      x IN D /\ i IN D /\ eapply D E ga x i
      ==> !z. z IN D
              ==> (E z i <=>
                   ?y. y IN D /\ E y X /\ E y x /\ eapply D E ga y z)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ra lda gacca gda. h1 h2 h3 h4 rcha h5 gaccha gdcha h6" THEN
  SUBGOAL_THEN `lda:A = la /\ gda:A = ga`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) ga x i` THEN
  REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `wxi:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(wxi:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "gdcha" (MP_TAC o SPEC `wxi:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  INTRO_TAC "@x1. h7 @img1. h8 h9 h10 h11 ich" THEN
  SUBGOAL_THEN `x1:A = x /\ img1:A = i`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "ich" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `y:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (y <=> z)) ==> ((p /\ y) <=> (p /\ z))`) THEN
  DISCH_TAC THEN
  MATCH_MP_TAC(TAUT `(p ==> (y <=> z)) ==> ((p /\ y) <=> (p /\ z))`) THEN
  DISCH_TAC THEN
  EQ_TAC THENL
   [REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `wyz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(wyz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`ra:A`;
                  `gacca:A`;`wyz:A`] GACC_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) wyz gacca`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `c':A` (X_CHOOSE_THEN `zc':A`
      (X_CHOOSE_THEN `lc':A` (X_CHOOSE_THEN `gc':A`
        STRIP_ASSUME_TAC)))) THEN
    SUBGOAL_THEN `(E:A->A->bool) wyz ga` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`c':A`;`zc':A`;
        `lc':A`;`gc':A`;`za:A`;`la:A`;`ga:A`] ECOLLTOWER_COHERE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `wyz:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `wyz:A` THEN ASM_REWRITE_TAC[];
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `wyz:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(wyz:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`la:A`;`x:A`;`y:A`]
      ELSTAGE_MEM_MEM_D) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c0:A` (X_CHOOSE_THEN `z0ld:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) c0` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`c0:A`]
      ECOLLTOWER_EXISTS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `zc0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`c0:A`;`zc0:A`]
      ECOLLTOWER_SND) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@r0 ld0 gacc0 gd0. h12 h13 h14 h15 rch0 h16 gacch0 gdch0
               h17" THEN
    SUBGOAL_THEN `ld0:A = z0ld` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[ELSTAGE_UNIQUE]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`z0ld:A`;`gacc0:A`;
                  `gd0:A`;`y:A`] GD_DOM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `i0:A` (CONJUNCTS_THEN2 ASSUME_TAC
      MP_TAC)) THEN
    REWRITE_TAC[eapply] THEN
    DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(w0:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) w0 ga` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`c0:A`;`zc0:A`;
        `z0ld:A`;`gd0:A`;`za:A`;`la:A`;`ga:A`] ECOLLTOWER_COHERE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `w0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `i0:A = z` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`la:A`;
        `gacca:A`;`ga:A`;`y:A`;`z:A`;`i0:A`] GD_FUN) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN CONJ_TAC THEN REWRITE_TAC[eapply] THENL
         [EXISTS_TAC `wyz:A` THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
