     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`ra:A`;
                    `gacca:A`;`w0:A`] GACC_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`c0:A`;`zc0:A`;`z0ld:A`;`gd0:A`] THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `w0:A` THEN ASM_REWRITE_TAC[]]);;

let ECOLLTOWER_PI_TOTAL = prove
 (`!D (E:A->A->bool) X a za la ga x.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      x IN D /\ E x X /\ E x la
      ==> ?i. i IN D /\ eapply D E ga x i`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ra lda gacca gda. h1 h2 h3 h4 rcha h5 gaccha gdcha h6" THEN
  SUBGOAL_THEN `lda:A = la /\ gda:A = ga`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`la:A`;`gacca:A`;
                `ga:A`;`x:A`] GD_DOM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let ECOLLTOWER_PI_MONO = prove
 (`!D (E:A->A->bool) X a za la ga x y ix iy.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      x IN D /\ y IN D /\ ix IN D /\ iy IN D /\
      E x X /\ eapply D E ga x ix /\ eapply D E ga y iy /\
      E x y
      ==> E ix iy`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                `ga:A`;`y:A`;`iy:A`] ECOLLTOWER_PI_RECURRENCE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `ix:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[]);;

let badinj = new_definition
  `badinj =
     ?? 93 (?? 94 (?? 95 (?? 96 (?? 97 (?? 98
       (apply_form 81 0 96 &&
        (opair_form 97 98 96 &&
         ((93 %% 67) &&
          ((94 %% 67) &&
           ((93 %% 97) &&
            ((94 %% 97) &&
             (Not(Eq 93 94) &&
              (apply_form 82 93 95 && apply_form 82 94 95)))))))))))))`;;

let HOLDS_BADINJ = prove
 (`!D (E:A->A->bool) v.
     valuation D v
     ==> (holds D E v badinj <=>
          ?x. x IN D /\ ?x'. x' IN D /\ ?ix. ix IN D /\ ?pd. pd IN D /\
          ?ld. ld IN D /\ ?gd. gd IN D /\
              eapply D E (v 81) (v 0) pd /\
              (eopair D E ld gd pd /\
               (E x (v 67) /\
                (E x' (v 67) /\
                 (E x ld /\
                  (E x' ld /\
                   (~(x = x') /\
                    (eapply D E (v 82) x ix /\
                     eapply D E (v 82) x' ix))))))))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!w. (v:num->A) w IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[badinj; holds; HOLDS_EX; HOLDS_AND; HOLDS_NOT] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!x x' ix pd ld gd:A.
      x IN D /\ x' IN D /\ ix IN D /\ pd IN D /\ ld IN D /\ gd IN D
      ==> (holds D E ((98 |-> gd)((97 |-> ld)((96 |-> pd)((95 |-> ix)
              ((94 |-> x')((93 |-> x) v))))))
             (apply_form 81 0 96) <=> eapply D E (v 81) (v 0) pd) /\
          (holds D E ((98 |-> gd)((97 |-> ld)((96 |-> pd)((95 |-> ix)
              ((94 |-> x')((93 |-> x) v))))))
             (opair_form 97 98 96) <=> eopair D E ld gd pd) /\
          (holds D E ((98 |-> gd)((97 |-> ld)((96 |-> pd)((95 |-> ix)
              ((94 |-> x')((93 |-> x) v))))))
             (apply_form 82 93 95) <=> eapply D E (v 82) x ix) /\
          (holds D E ((98 |-> gd)((97 |-> ld)((96 |-> pd)((95 |-> ix)
              ((94 |-> x')((93 |-> x) v))))))
             (apply_form 82 94 95) <=> eapply D E (v 82) x' ix)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((98 |-> (gd:A))((97 |-> ld)((96 |-> pd)((95 |-> ix)
        ((94 |-> x')((93 |-> x) v))))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_OPAIR_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `x:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `x':A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `ix:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `pd:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `ld:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `gd:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL
    [`x:A`;`x':A`;`ix:A`;`pd:A`;`ld:A`;`gd:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let BADINJ_SEM = prove
 (`!D (E:A->A->bool) X sa rc ga v0 b.
      model D E ZF_AX /\ X IN D /\ eordinal D E sa /\
      rc IN D /\ ga IN D /\ valuation D v0 /\
      (!pp. pp IN D
            ==> (E pp rc <=>
                 ?b' z'. b' IN D /\ z' IN D /\ E b' sa /\
                         ecolltower D E X b' z' /\ eopair D E b' z' pp)) /\
      b IN D /\ E b sa
      ==> (holds D E ((0 |-> b) ((67 |-> X) ((81 |-> rc) ((82 |-> ga) v0))))
                badinj <=>
           ?x x' ix zb lb gb.
              x IN D /\ x' IN D /\ ix IN D /\ zb IN D /\ lb IN D /\
              gb IN D /\
              ecolltower D E X b zb /\ eopair D E lb gb zb /\
              E x X /\ E x' X /\ E x lb /\ E x' lb /\ ~(x = x') /\
              eapply D E ga x ix /\ eapply D E ga x' ix)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 rcc h7 h8" THEN
  SUBGOAL_THEN
   `valuation D
      ((0 |-> (b:A)) ((67 |-> (X:A)) ((81 |-> (rc:A)) ((82 |-> (ga:A)) v0))))`
  ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
    `(0 |-> (b:A)) ((67 |-> (X:A)) ((81 |-> (rc:A)) ((82 |-> (ga:A)) v0)))`]
    HOLDS_BADINJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `x:A` (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `x':A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `ix:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `pd:A` (CONJUNCTS_THEN2 ASSUME_TAC
            (X_CHOOSE_THEN `ld:A` (CONJUNCTS_THEN2 ASSUME_TAC
              (X_CHOOSE_THEN `gd:A` (CONJUNCTS_THEN2 ASSUME_TAC
                STRIP_ASSUME_TAC)))))))))))) THEN
    SUBGOAL_THEN `(E:A->A->bool) b sa /\ ecolltower D E X b pd`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
        `ecolltower D (E:A->A->bool) X`;`sa:A`;`rc:A`;`b:A`;`pd:A`]
        EGRAPH_APPLY) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
      [`x:A`;`x':A`;`ix:A`;`pd:A`;`ld:A`;`gd:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `x:A` (X_CHOOSE_THEN `x':A`
      (X_CHOOSE_THEN `ix:A` (X_CHOOSE_THEN `zb:A`
        (X_CHOOSE_THEN `lb:A` (X_CHOOSE_THEN `gb:A`
          STRIP_ASSUME_TAC)))))) THEN
    EXISTS_TAC `x:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `x':A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `ix:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `zb:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `lb:A` THEN ASM_REWRITE_TAC[] THEN
    EXISTS_TAC `gb:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;
      `ecolltower D (E:A->A->bool) X`;`sa:A`;`rc:A`;`b:A`;`zb:A`]
      EGRAPH_APPLY) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let BADPAIR_DESCEND = prove
 (`!D (E:A->A->bool) X a za la ga d zb lb gb x x' i u.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      d IN D /\ eordinal D E d /\
      zb IN D /\ lb IN D /\ gb IN D /\
      ecolltower D E X d zb /\ eopair D E lb gb zb /\
      x IN D /\ x' IN D /\ i IN D /\
      E x X /\ E x' X /\ E x lb /\ E x' lb /\
      eapply D E ga x i /\ eapply D E ga x' i /\
      u IN D /\ E u X /\ E u x /\ ~(E u x')
      ==> (!e. e IN D /\ E e d ==> E e a)
      ==> ?c zc lc gc u1 u2 iu.
             c IN D /\ zc IN D /\ lc IN D /\ gc IN D /\
             u1 IN D /\ u2 IN D /\ iu IN D /\ E c d /\
             ecolltower D E X c zc /\ eopair D E lc gc zc /\
             E u1 X /\ E u2 X /\ E u1 lc /\ E u2 lc /\ ~(u1 = u2) /\
             eapply D E ga u1 iu /\ eapply D E ga u2 iu`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN DISCH_THEN(LABEL_TAC "lea") THEN
  SUBGOAL_THEN `(a:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`d:A`;`zb:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `rdd:A` (X_CHOOSE_THEN `ldd:A`
    (X_CHOOSE_THEN `gaccdd:A` (X_CHOOSE_THEN `gddd:A`
      STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `ldd:A = lb /\ gddd:A = gb`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@raa lda gacca gdaa. h1 h2 h3 h4 rcha h5 gaccha gdcha h6" THEN
  SUBGOAL_THEN `lda:A = la /\ gdaa:A = ga`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`lb:A`;`x:A`;`u:A`]
    ELSTAGE_MEM_MEM_D) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cu:A` (X_CHOOSE_THEN `zu:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) cu` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cu a` ASSUME_TAC THENL
   [USE_THEN "lea" (MP_TAC o SPEC `cu:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u la` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`cu:A`;`la:A`;`zu:A`;
                  `u:A`] ELSTAGE_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`la:A`;`gacca:A`;
                `ga:A`;`u:A`] GD_DOM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `iu:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) iu i` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                  `ga:A`;`u:A`;`x:A`;`iu:A`;`i:A`] ECOLLTOWER_PI_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                `ga:A`;`x':A`;`i:A`] ECOLLTOWER_PI_RECURRENCE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `iu:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) iu i`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `u2:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `~(u:A = u2)` ASSUME_TAC THENL
   [DISCH_THEN SUBST_ALL_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`d:A`;`lb:A`;`x':A`;`u2:A`]
    ELSTAGE_MEM_MEM_D) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cu2:A` (X_CHOOSE_THEN `zu2:A`
