let ECOLLTOWER_PI_ISO = prove
 (`!D (E:A->A->bool) X a za la ga x y ix iy.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y X /\ E y' X /\ ~(y = y')
              ==> ?u. u IN D /\ E u X /\ ~(E u y <=> E u y')) /\
      x IN D /\ y IN D /\ ix IN D /\ iy IN D /\
      E x X /\ E y X /\
      eapply D E ga x ix /\ eapply D E ga y iy
      ==> (E ix iy <=> E x y)`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
          (CONJUNCTS_THEN2 (LABEL_TAC "ext")
            (REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC)))))))))) THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                  `ga:A`;`y:A`;`iy:A`] ECOLLTOWER_PI_RECURRENCE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `ix:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> MP_TAC(EQ_MP th
      (ASSUME `(E:A->A->bool) ix iy`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `u:A = x` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
        `ga:A`;`u:A`;`x:A`;`ix:A`] ECOLLTOWER_PI_INJ) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN
        USE_THEN "ext" (fun th -> REWRITE_TAC[th]);
        DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                  `ga:A`;`x:A`;`y:A`;`ix:A`;`iy:A`] ECOLLTOWER_PI_MONO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]);;

(* ========================================================================= *)
(* The collapse range M' = range(ga) = {v : ?u. <u,v> IN ga} exists as a set *)
(* in D (ECOLLRANGE_EXISTS: the snd-projection of the graph ga, bounded by   *)
(* UNION^2 ga). sndproj_form is the separation predicate.                    *)
(* ========================================================================= *)

let sndproj_form = new_definition
  `sndproj_form iz ir =
     ?? 52 (?? 55 (?? 56
       ((52 %% ir) && opair_form 55 56 52 && Eq iz 56)))`;;

let HOLDS_SNDPROJ = prove
 (`!D (E:A->A->bool) v iz ir.
     valuation D v /\
     ~(iz=52)/\ ~(iz=55)/\ ~(iz=56)/\ ~(iz=57)/\ ~(iz=58)/\
     ~(ir=52)/\ ~(ir=55)/\ ~(ir=56)/\ ~(ir=57)/\ ~(ir=58)
     ==> (holds D E v (sndproj_form iz ir) <=>
          ?p. p IN D /\ ?u. u IN D /\ ?g. g IN D /\
              E p (v ir) /\ eopair D E u g p /\ v iz = g)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[sndproj_form; holds; HOLDS_EX; HOLDS_AND] THEN
  ASM_REWRITE_TAC[VALMOD; ARITH_EQ] THEN
  SUBGOAL_THEN
   `!p u g:A. p IN D /\ u IN D /\ g IN D
     ==> (holds D E ((56 |-> g)((55 |-> u)((52 |-> p) v)))
            (opair_form 55 56 52) <=> eopair D E u g p)`
  (LABEL_TAC "piles") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((56 |-> (g:A))((55 |-> u)((52 |-> p) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_OPAIR_FORM] THEN
    ASM_SIMP_TAC[VALMOD; ARITH_EQ]; ALL_TAC] THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `p:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  MATCH_MP_TAC(MESON[]
    `(!s:A. s IN D ==> (P s <=> Q s)) ==>
     ((?s. s IN D /\ P s) <=> (?s. s IN D /\ Q s))`) THEN
  X_GEN_TAC `g:A` THEN DISCH_TAC THEN
  USE_THEN "piles" (MP_TAC o SPECL [`p:A`;`u:A`;`g:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN ASM_REWRITE_TAC[]);;

let ECOLLRANGE_EXISTS = prove
 (`!D (E:A->A->bool) ga.
     model D E ZF_AX /\ ga IN D
     ==> ?m. m IN D /\
             !v. v IN D
                 ==> (E v m <=>
                      ?p. p IN D /\ ?u. u IN D /\
                          E p ga /\ eopair D E u v p)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ga:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `u1:A`) THEN
  SUBGOAL_THEN `(u1:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u1:A`] EUNION_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[EUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vv:A. vv IN D /\
          (?p. p IN D /\ ?u. u IN D /\ E p ga /\ eopair D E u vv p)
          ==> E vv u2`
  (LABEL_TAC "bound") THENL
   [X_GEN_TAC `vv:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC)))) THEN
    UNDISCH_TAC `eopair D (E:A->A->bool) u vv p` THEN REWRITE_TAC[eopair] THEN
    DISCH_THEN(X_CHOOSE_THEN `s2:A`
               (X_CHOOSE_THEN `pr:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s2:A) IN D /\ (pr:A) IN D`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `E (pr:A) p /\ E (vv:A) pr`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[epair]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (pr:A) (u1:A)` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`ga:A`;`u1:A`;`p:A`;`pr:A`]
             EUNION_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`u1:A`;`u2:A`;`pr:A`;`vv:A`]
           EUNION_MEM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `v0:num->A` o MATCH_MP VALUATION_EXISTS o MATCH_MP
              MODEL_NONEMPTY) THEN
  SUBGOAL_THEN `valuation D ((0 |-> (ga:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o SPECL
              [`sndproj_form 50 0`; `50`; `(0 |-> (ga:A)) v0`; `u2:A`] o
              MATCH_MP ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `m:A` THEN
  STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `vv:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((50 |-> (vv:A)) ((0 |-> ga) v0))` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  SUBGOAL_THEN
   `holds D E ((50 |-> (vv:A)) ((0 |-> ga) v0)) (sndproj_form 50 0) <=>
    ?p. p IN D /\ ?u. u IN D /\ E p ga /\ eopair D E u vv p`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;
            `(50 |-> (vv:A)) ((0 |-> ga) v0)`;`50`;`0`]
           HOLDS_SNDPROJ) THEN
    ASM_REWRITE_TAC[ARITH_EQ] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD; ARITH_EQ] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `g:A` STRIP_ASSUME_TAC))))) THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC))) THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `vv:A` THEN ASM_REWRITE_TAC[]]; ALL_TAC] THEN
  EQ_TAC THENL [MESON_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN ASM_REWRITE_TAC[] THEN
  USE_THEN "bound" (fun th -> MP_TAC(SPEC `vv:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ========================================================================= *)
(* M' = range(ga) is transitive (ECOLLRANGE_TRANS). If v IN M' (v = pi(u)    *)
(* for some u) and w IN v, then by the pi-recurrence w = pi(y) for some      *)
(* y IN X with E y u; hence w IN M'. (X SUBSET L(a) is not needed: the       *)
(* recurrence is unconditional given eapply ga u v.) ISO_HOLDS: an           *)
(* isomorphism ga of X onto Mp (total, single-valued, onto, injective and    *)
(* preserving membership) transfers holds between the two structures.        *)
(* ========================================================================= *)

let ECOLLRANGE_TRANS = prove
 (`!D (E:A->A->bool) X a za la ga m.
     model D E ZF_AX /\ X IN D /\ eordinal D E a /\
     za IN D /\ la IN D /\ ga IN D /\
     ecolltower D E X a za /\ eopair D E la ga za /\ m IN D /\
     (!v. v IN D
          ==> (E v m <=>
               ?p. p IN D /\ ?u. u IN D /\ E p ga /\ eopair D E u v p))
     ==> !w v. w IN D /\ v IN D /\ E v m /\ E w v ==> E w m`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 mch" THEN
  MAP_EVERY X_GEN_TAC [`w:A`;`v:A`] THEN STRIP_TAC THEN
  USE_THEN "mch" (MP_TAC o SPEC `v:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) v m`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `p:A` (CONJUNCTS_THEN2 ASSUME_TAC
    (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `eapply D (E:A->A->bool) ga u v` ASSUME_TAC THENL
   [REWRITE_TAC[eapply] THEN EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
                `u:A`;`v:A`] ECOLLTOWER_PI_RECURRENCE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) w v`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
  UNDISCH_TAC `eapply D (E:A->A->bool) ga y w` THEN REWRITE_TAC[eapply] THEN
  DISCH_THEN(X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(pp:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  USE_THEN "mch" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `pp:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `y:A` THEN ASM_REWRITE_TAC[]);;

let ISO_HOLDS = prove
 (`!D (E:A->A->bool) X Mp ga.
        model D E ZF_AX /\ X IN D /\ Mp IN D /\
        (!x. x IN D /\ E x X ==> ?i. i IN D /\ E i Mp /\ eapply D E ga x i) /\
        (!x i i'. x IN D /\ E x X /\ i IN D /\ i' IN D /\
                  eapply D E ga x i /\ eapply D E ga x i'
                  ==> i = i') /\
        (!i. i IN D /\ E i Mp ==> ?x. x IN D /\ E x X /\ eapply D E ga x i) /\
        (!x x' i. x IN D /\ x' IN D /\ i IN D /\ E x X /\ E x' X /\
                  eapply D E ga x i /\ eapply D E ga x' i ==> x = x') /\
        (!x y ix iy. x IN D /\ y IN D /\ ix IN D /\ iy IN D /\
         E x X /\ E y X /\
         eapply D E ga x ix /\ eapply D E ga y iy
                     ==> (E ix iy <=> E x y))
        ==> !p v v'.
                (!k. v k IN D /\ E (v k) X) /\
                (!k. v' k IN D /\ E (v' k) Mp) /\
                (!k. eapply D E ga (v k) (v' k))
                ==> (holds (\z. z IN D /\ E z X) E v p <=>
                     holds (\z. z IN D /\ E z Mp) E v' p)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl XD MpD tot sv onto inj iso" THEN
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [(* False *)
    REWRITE_TAC[holds];
    (* i %% j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`;`v:num->A`;`v':num->A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vX")
      (CONJUNCTS_THEN2 (LABEL_TAC "vM") (LABEL_TAC "vga"))) THEN
    REWRITE_TAC[holds] THEN
    USE_THEN "iso" (fun iso -> MP_TAC(SPECL
      [`(v:num->A) i`;`(v:num->A) j`;`(v':num->A) i`;
       `(v':num->A) j`] iso)) THEN
    ANTS_TAC THENL
     [ASM_MESON_TAC[]; DISCH_THEN(fun th -> REWRITE_TAC[th])];
    (* Eq i j *)
    MAP_EVERY X_GEN_TAC [`i:num`;`j:num`;`v:num->A`;`v':num->A`] THEN
    STRIP_TAC THEN
    REWRITE_TAC[holds] THEN EQ_TAC THEN DISCH_TAC THEN ASM_MESON_TAC[];
    (* p --> q *)
    REPEAT GEN_TAC THEN STRIP_TAC THEN
    MAP_EVERY X_GEN_TAC [`v:num->A`;`v':num->A`] THEN STRIP_TAC THEN
    REWRITE_TAC[holds] THEN
    MATCH_MP_TAC(TAUT
                 `(p <=> r) /\ (q <=> s) ==> ((p ==> q) <=> (r ==> s))`) THEN
    CONJ_TAC THEN
    FIRST_X_ASSUM(fun ih ->
      MP_TAC(SPECL [`v:num->A`;`v':num->A`] ih) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);
    (* !! a0 a1 *)
    REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "ih") THEN
    MAP_EVERY X_GEN_TAC [`v:num->A`;`v':num->A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "vX")
      (CONJUNCTS_THEN2 (LABEL_TAC "vM") (LABEL_TAC "vga"))) THEN
    REWRITE_TAC[holds; IN_SUBMODEL] THEN EQ_TAC THENL
     [DISCH_THEN(LABEL_TAC "lhs") THEN
      X_GEN_TAC `u':A` THEN STRIP_TAC THEN
      USE_THEN "onto" (fun th -> MP_TAC(SPEC `u':A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `x0:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "ih" (fun ih -> MP_TAC(SPECL
         [`((a0:num) |-> (x0:A)) (v:num->A)`;
          `((a0:num) |-> (u':A)) (v':num->A)`] ih)) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "lhs" (fun th -> MP_TAC(SPEC `x0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
      ASM_MESON_TAC[];
      DISCH_THEN(LABEL_TAC "rhs") THEN
      X_GEN_TAC `x0:A` THEN STRIP_TAC THEN
      USE_THEN "tot" (fun th -> MP_TAC(SPEC `x0:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "ih" (fun ih -> MP_TAC(SPECL
         [`((a0:num) |-> (x0:A)) (v:num->A)`;
          `((a0:num) |-> (b:A)) (v':num->A)`] ih)) THEN
      ANTS_TAC THENL
       [REPEAT CONJ_TAC THEN GEN_TAC THEN REWRITE_TAC[VALMOD] THEN
        COND_CASES_TAC THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "rhs" (fun th -> MP_TAC(SPEC `b:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_TAC] THEN
      ASM_MESON_TAC[]]]);;

(* ========================================================================= *)
(* Absoluteness of set operations for an abstract transitive submodel        *)
(* W = (\u. u IN D /\ E u w). These mirror the corresponding lemmas for the  *)
(* constructible class lclass, but take the closure facts as hypotheses:     *)
(* EBUNION_SUBMODEL, ESUC_SUBMODEL and ENAT_SUBMODEL carry an explicit       *)
(* pairing-closure hypothesis (an arbitrary transitive W need not satisfy    *)
(* the analogue of LCLASS_EPAIR), and transitivity of w replaces             *)
(* LCLASS_MEMBER. For a transitive W satisfying zfw_ax, the pairing-closure  *)
(* hypothesis is discharged by PAIR_CLOSED_SUBMODEL_F below.                 *)
(* ========================================================================= *)

let EEMPTY_SUBMODEL = prove
 (`!D (E:A->A->bool) w z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\ z IN D /\ E z w
        ==> (eempty (\u. u IN D /\ E u w) E z <=> eempty D E z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!y:A. y IN D /\ (E:A->A->bool) y w ==> !z. z IN D /\ E z y ==> E z w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[eempty; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let EPAIR_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ z IN D /\ E z w
        ==> (epair (\u. u IN D /\ E u w) E x y z <=> epair D E x y z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!p:A. p IN D /\ (E:A->A->bool) p w ==> !q. q IN D /\ E q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[epair; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let EUNION_SUBMODEL = prove
 (`!D (E:A->A->bool) w x z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        x IN D /\ E x w /\ z IN D /\ E z w
        ==> (eunion (\u. u IN D /\ E u w) E x z <=> eunion D E x z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!p:A. p IN D /\ (E:A->A->bool) p w ==> !q. q IN D /\ E q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[eunion; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `q:A` THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let EBUNION_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ z IN D /\ E z w
        ==> (ebunion (\u. u IN D /\ E u w) E x y z <=> ebunion D E x y z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ebunion] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D /\ (E:A->A->bool) p w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `epair (\u. u IN D /\ (E:A->A->bool) u w) E x y p` THEN
      REWRITE_TAC[epair; IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN
    ASM_MESON_TAC[EPAIR_SUBMODEL; EUNION_SUBMODEL];
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(p:A) IN D /\ (E:A->A->bool) p w` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN
    ASM_MESON_TAC[EPAIR_SUBMODEL; EUNION_SUBMODEL]]);;

let ESUC_SUBMODEL = prove
 (`!D (E:A->A->bool) w x z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        x IN D /\ E x w /\ z IN D /\ E z w
        ==> (esuc (\u. u IN D /\ E u w) E x z <=> esuc D E x z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[esuc] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (E:A->A->bool) s w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `epair (\u. u IN D /\ (E:A->A->bool) u w) E x x s` THEN
      REWRITE_TAC[epair; IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`x:A`;`s:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`s:A`;`z:A`]
           EBUNION_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    EXISTS_TAC `s:A` THEN ASM_MESON_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (E:A->A->bool) s w` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`x:A`;`s:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`s:A`;`z:A`]
           EBUNION_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_TAC THEN
    EXISTS_TAC `s:A` THEN ASM_MESON_TAC[]]);;

let ENAT_SUBMODEL = prove
 (`!D (E:A->A->bool) w n x.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        x IN D /\ E x w
        ==> (enat (\u. u IN D /\ E u w) E n x <=> enat D E n x)`,
  GEN_TAC THEN GEN_TAC THEN GEN_TAC THEN
  INDUCT_TAC THEN X_GEN_TAC `x:A` THEN STRIP_TAC THEN
  REWRITE_TAC[enat] THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`]
           EEMPTY_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    SUBGOAL_THEN
     `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
    (LABEL_TAC "tr") THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(y:A) IN D /\ (E:A->A->bool) y w` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(MP_TAC o MATCH_MP ENAT_IN) THEN
        REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `enat (\u. u IN D /\ (E:A->A->bool) u w) E n y <=> enat D E n y`
        ASSUME_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`y:A`;`x:A`]
             ESUC_SUBMODEL) THEN
      ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_TAC THEN EXISTS_TAC `y:A` THEN
      UNDISCH_TAC `esuc (\u. u IN D /\ (E:A->A->bool) u w) E y x` THEN
      UNDISCH_TAC `enat (\u. u IN D /\ (E:A->A->bool) u w) E n y` THEN
      ASM_REWRITE_TAC[] THEN MESON_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(y:A) IN D` ASSUME_TAC THENL
       [FIRST_ASSUM(ACCEPT_TAC o MATCH_MP ENAT_IN); ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) y x` ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`y:A`;`x:A`]
                     ESUC_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) y w` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
        `enat (\u. u IN D /\ (E:A->A->bool) u w) E n y <=> enat D E n y`
        ASSUME_TAC THENL
       [FIRST_X_ASSUM MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
        FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`y:A`;`x:A`]
             ESUC_SUBMODEL) THEN
      ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_TAC THEN EXISTS_TAC `y:A` THEN
      UNDISCH_TAC `esuc D (E:A->A->bool) y x` THEN
      UNDISCH_TAC `enat D (E:A->A->bool) n y` THEN
      ASM_REWRITE_TAC[IN_SUBMODEL] THEN MESON_TAC[]]]);;

(* ------------------------------------------------------------------------- *)
(* Absoluteness at an abstract transitive submodel                           *)
(* W = (\u. u IN D /\ E u w), continued: eopair, eapply and eupdate          *)
(* (EOPAIR_SUBMODEL, EAPPLY_SUBMODEL, EUPDATE_SUBMODEL and helpers), and the *)
(* five clauses of internal satisfaction (ESATFALSE_RESTRICT_W to            *)
(* ESATALL_RESTRICT_W), the W-analogues of the corresponding results for L.  *)
(* ------------------------------------------------------------------------- *)

let EOPAIR_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ z IN D /\ E z w
        ==> (eopair (\u. u IN D /\ E u w) E x y z <=> eopair D E x y z)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eopair] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `s:A`
               (X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (E:A->A->bool) s w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `epair (\u. u IN D /\ (E:A->A->bool) u w) E x x s` THEN
      REWRITE_TAC[epair; IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(pp:A) IN D /\ (E:A->A->bool) pp w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `epair (\u. u IN D /\ (E:A->A->bool) u w) E x y pp` THEN
      REWRITE_TAC[epair; IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`x:A`;`s:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`y:A`;`pp:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`pp:A`;`z:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`pp:A`] THEN ASM_MESON_TAC[];
    SUBGOAL_THEN
     `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
    (LABEL_TAC "tr") THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `s:A`
               (X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(s:A) IN D /\ (pp:A) IN D` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s z` ASSUME_TAC THENL
     [UNDISCH_TAC `epair D (E:A->A->bool) s pp z` THEN REWRITE_TAC[epair] THEN
      DISCH_THEN(MP_TAC o SPEC `s:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) pp z` ASSUME_TAC THENL
     [UNDISCH_TAC `epair D (E:A->A->bool) s pp z` THEN REWRITE_TAC[epair] THEN
      DISCH_THEN(MP_TAC o SPEC `pp:A` o CONJUNCT2) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) pp w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`x:A`;`s:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`y:A`;`pp:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`pp:A`;`z:A`]
           EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    MAP_EVERY EXISTS_TAC [`s:A`;`pp:A`] THEN ASM_REWRITE_TAC[]]);;

let EAPPLY_SUBMODEL = prove
 (`!D (E:A->A->bool) w f a b.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        f IN D /\ E f w /\ a IN D /\ E a w /\ b IN D /\ E b w
        ==> (eapply (\u. u IN D /\ E u w) E f a b <=> eapply D E f a b)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[eapply] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `eopair (\u. u IN D /\ (E:A->A->bool) u w) E a b z` THEN
      REWRITE_TAC[eopair] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A`
                 (X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC)) THEN
      UNDISCH_TAC `epair (\u. u IN D /\ (E:A->A->bool) u w) E s p z` THEN
      REWRITE_TAC[epair; IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`b:A`;`z:A`]
           EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    EXISTS_TAC `z:A` THEN ASM_MESON_TAC[];
    SUBGOAL_THEN
     `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
    (LABEL_TAC "tr") THENL
     [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `f:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`b:A`;`z:A`]
           EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
    EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]]);;

let EOPAIR_MEMBERS_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        z IN D /\ E z w /\ x IN D /\ y IN D /\ eopair D E x y z
        ==> E x w /\ E y w`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eopair] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(s:A) IN D /\ (p:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s w /\ (E:A->A->bool) p w`
    STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `z:A` THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[epair]; ALL_TAC] THEN
  CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THENL
   [EXISTS_TAC `s:A`; EXISTS_TAC `p:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[epair]);;

let EOPAIR_CLOSED_SUBMODEL = prove
 (`!D (E:A->A->bool) w.
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w)
        ==> (!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\ eopair D E c d p
                     ==> E p w)`,
  REPEAT GEN_TAC THEN DISCH_THEN(LABEL_TAC "epc") THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[eopair] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (X_CHOOSE_THEN `sa:A` (X_CHOOSE_THEN `pp:A` STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(sa:A) IN D /\ (pp:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sa w` ASSUME_TAC THENL
   [USE_THEN "epc" MATCH_MP_TAC THEN MAP_EVERY EXISTS_TAC [`c:A`; `c:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) pp w` ASSUME_TAC THENL
   [USE_THEN "epc" MATCH_MP_TAC THEN MAP_EVERY EXISTS_TAC [`c:A`; `d:A`] THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "epc" MATCH_MP_TAC THEN MAP_EVERY EXISTS_TAC [`sa:A`; `pp:A`] THEN
  ASM_REWRITE_TAC[]);;

let EUPDATE_PAIRCLAUSE_SUBMODEL = prove
 (`!D (E:A->A->bool) w a z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        a IN D /\ E a w /\ z IN D /\ E z w
        ==> ((?p. (p IN D /\ E p w) /\
                  eopair (\u. u IN D /\ E u w) E a p z) <=>
             (?p. p IN D /\ eopair D E a p z))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`p:A`;`z:A`]
      EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
    DISCH_THEN(X_CHOOSE_THEN `p:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) a w /\ E p w` STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`p:A`;`z:A`]
        EOPAIR_MEMBERS_SUBMODEL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`p:A`;`z:A`]
      EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th])]);;

let EUPDATE_SUBMODEL = prove
 (`!D (E:A->A->bool) w s a uu s'.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
                 eopair D E c d p ==> E p w) /\
        s IN D /\ E s w /\ a IN D /\ E a w /\
        uu IN D /\ E uu w /\ s' IN D /\ E s' w
        ==> (eupdate (\u. u IN D /\ E u w) E s a uu s' <=>
             eupdate D E s a uu s')`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[eupdate] THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
   (LABEL_TAC "tr") THENL [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[IN_SUBMODEL] THEN
  EQ_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ch")) THENL
   [CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `z:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `s':A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`z:A`]
        EUPDATE_PAIRCLAUSE_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`uu:A`;`z:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
       [FIRST_X_ASSUM(DISJ_CASES_TAC o check (is_disj o concl)) THENL
         [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `s:A` THEN
          ASM_REWRITE_TAC[];
          FIRST_ASSUM(MATCH_MP_TAC o check (fun th ->
             is_forall(concl th) &&
             can (find_term (fun t -> is_const t &&
               fst(dest_const t) = "eopair")) (concl th))) THEN
          MAP_EVERY EXISTS_TAC [`a:A`;`uu:A`] THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`z:A`]
        EUPDATE_PAIRCLAUSE_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`uu:A`;`z:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`z:A`]
      EUPDATE_PAIRCLAUSE_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`uu:A`;`z:A`]
      EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN REWRITE_TAC[]]);;

let ESATFALSE_RESTRICT_W = prove
 (`!D (E:A->A->bool) w bb tag data.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        bb IN D /\ E bb w /\ tag IN D /\ E tag w /\ data IN D /\ E data w
        ==> (esatfalse (\u. u IN D /\ E u w) E bb tag data <=>
             esatfalse D E bb tag data)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[esatfalse] THEN
  SUBGOAL_THEN
   `enat (\u. u IN D /\ (E:A->A->bool) u w) E 0 tag <=> enat D E 0 tag`
  ASSUME_TAC THENL
   [MATCH_MP_TAC ENAT_SUBMODEL THEN REPEAT CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN
   `enat (\u. u IN D /\ (E:A->A->bool) u w) E 0 bb <=> enat D E 0 bb`
  ASSUME_TAC THENL
   [MATCH_MP_TAC ENAT_SUBMODEL THEN REPEAT CONJ_TAC THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let ESATMEM_RESTRICT_W,ESATEQ_RESTRICT_W = (CONJ_PAIR o prove)
 (`(!D (E:A->A->bool) w s bb tag data.
         model D E ZF_AX /\ w IN D /\ etransitive D E w /\
         (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                  ==> E p w) /\
         s IN D /\ E s w /\ bb IN D /\ E bb w /\
         tag IN D /\ E tag w /\ data IN D /\ E data w
         ==> (esatmem (\u. u IN D /\ E u w) E bb s tag data <=>
              esatmem D E bb s tag data)) /\
   (!D (E:A->A->bool) w s bb tag data.
         model D E ZF_AX /\ w IN D /\ etransitive D E w /\
         (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                  ==> E p w) /\
         s IN D /\ E s w /\ bb IN D /\ E bb w /\
         tag IN D /\ E tag w /\ data IN D /\ E data w
         ==> (esateq (\u. u IN D /\ E u w) E bb s tag data <=>
              esateq D E bb s tag data))`,
  CONJ_TAC THEN
  (REPEAT GEN_TAC THEN STRIP_TAC THEN
   SUBGOAL_THEN
    `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
   (LABEL_TAC "tr") THENL
    [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
   REWRITE_TAC[esatmem; esateq; IN_SUBMODEL] THEN
   SUBGOAL_THEN
    `!n. (enat (\u. u IN D /\ (E:A->A->bool) u w) E n tag <=>
          enat D E n tag) /\
         (enat (\u. u IN D /\ E u w) E n bb <=> enat D E n bb)`
   ASSUME_TAC THENL
    [GEN_TAC THEN CONJ_TAC THEN MATCH_MP_TAC ENAT_SUBMODEL THEN
     REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
   ASM_REWRITE_TAC[] THEN EQ_TAC THENL
    [DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
       (X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `sa:A`
         (X_CHOOSE_THEN `sb:A`
           (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
     ASM_REWRITE_TAC[] THEN
     MAP_EVERY EXISTS_TAC [`a:A`; `b:A`; `sa:A`; `sb:A`] THEN
     ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
      [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`b:A`;`data:A`]
         EOPAIR_SUBMODEL) THEN
       ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[];
       MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`a:A`;`sa:A`]
         EAPPLY_SUBMODEL) THEN
