          can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "eupdate")) (concl th) &&
          not(can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "everdict")) (concl th)))) THEN
        MAP_EVERY EXISTS_TAC [`s:A`; `a:A`; `u:A`] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `eupdate (\u. u IN D /\ (E:A->A->bool) u w) E s a u s'`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`a:A`;`u:A`;
          `s':A`] EUPDATE_SUBMODEL) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "allL" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `s':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c1:A`; `s':A`; `z1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 STRIP_ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `s':A`
          STRIP_ASSUME_TAC)))) THEN
      DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `eupdate D (E:A->A->bool) s a u s'` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`a:A`;`u:A`;
          `s':A`] EUPDATE_SUBMODEL) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "trf" (MP_TAC o SPECL [`c1:A`; `s':A`; `z0:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `a:A`
      (X_CHOOSE_THEN `c1:A` (X_CHOOSE_THEN `z0:A`
        (X_CHOOSE_THEN `z1:A`
          (fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th))))))) THEN
    ASM_REWRITE_TAC[] THEN
    SUBGOAL_THEN `(E:A->A->bool) a w /\ (E:A->A->bool) c1 w`
    STRIP_ASSUME_TAC THENL
     [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`c1:A`;
        `data:A`] EOPAIR_MEMBERS_SUBMODEL) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) a hf /\ E c1 hf`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o SPECL [`a:A`; `c1:A`] o
        check (fun th -> is_forall(concl th) &&
          can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "eopair")) (concl th) &&
          not(can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "everdict")) (concl th)) &&
          can (find_term ((=) `hf:A`)) (concl th))) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z0 two /\ E z1 two`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `0`; `2`;
                      `z0:A`; `two:A`] ENAT_MEM_LT);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `1`; `2`;
                      `z1:A`; `two:A`] ENAT_MEM_LT)] THEN
      (ANTS_TAC THENL
        [ASM_REWRITE_TAC[] THEN ARITH_TAC; DISCH_THEN ACCEPT_TAC]);
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z0 w /\ E z1 w`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `two:A` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `two:A` THEN
        ASM_REWRITE_TAC[]]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E a c1 data`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`c1:A`;`data:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `enat (\u. u IN D /\ (E:A->A->bool) u w) E 0 z0 <=> enat D E 0 z0`
    ASSUME_TAC THENL
     [MATCH_MP_TAC ENAT_SUBMODEL THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    SUBGOAL_THEN
     `enat (\u. u IN D /\ (E:A->A->bool) u w) E 1 z1 <=> enat D E 1 z1`
    ASSUME_TAC THENL
     [MATCH_MP_TAC ENAT_SUBMODEL THEN REPEAT CONJ_TAC THEN
      FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC [`a:A`; `c1:A`; `z0:A`; `z1:A`] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(DISJ_CASES_THEN (CONJUNCTS_THEN2 ASSUME_TAC MP_TAC) o
      check (fun th -> is_disj(concl th))) THENL
     [DISCH_THEN(LABEL_TAC "allD") THEN DISJ1_TAC THEN ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `u:A` THEN STRIP_TAC THEN
      X_GEN_TAC `s':A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `eupdate D (E:A->A->bool) s a u s'` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`a:A`;`u:A`;
          `s':A`] EUPDATE_SUBMODEL) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "allD" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `s':A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      USE_THEN "trb" (MP_TAC o SPECL [`c1:A`; `s':A`; `z1:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN(X_CHOOSE_THEN `u:A` (CONJUNCTS_THEN2 ASSUME_TAC
        (CONJUNCTS_THEN2 ASSUME_TAC (X_CHOOSE_THEN `s':A`
          STRIP_ASSUME_TAC)))) THEN
      DISJ2_TAC THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `(E:A->A->bool) u w` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `x:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) s' w` ASSUME_TAC THENL
       [FIRST_ASSUM(MATCH_MP_TAC o check (fun th ->
          is_forall(concl th) &&
          can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "eupdate")) (concl th) &&
          not(can (find_term (fun t -> is_const t &&
            fst(dest_const t) = "everdict")) (concl th)))) THEN
        MAP_EVERY EXISTS_TAC [`s:A`; `a:A`; `u:A`] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `eupdate (\u. u IN D /\ (E:A->A->bool) u w) E s a u s'`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`a:A`;`u:A`;
          `s':A`] EUPDATE_SUBMODEL) THEN
        ANTS_TAC THENL
         [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `u:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `s':A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "trb" (MP_TAC o SPECL [`c1:A`; `s':A`; `z0:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

(* ------------------------------------------------------------------------- *)
(* Absoluteness of membership in the function spaces efuns at the transitive *)
(* submodel W = (\u. u IN D /\ E u w): the eisfun, eindom, edomain and efuns *)
(* clauses of the decomposition of the satisfaction universe, needed for     *)
(* ESATBODY_RESTRICT_W_F. These are the W-analogues of LCLASS_EAPPLY_RAN,    *)
(* EISFUN_LCLASS, EINDOM_LCLASS, EDOMAIN_LCLASS and LCLASS_EFUNS_MEMBER.     *)
(* ------------------------------------------------------------------------- *)

let EAPPLY_RAN_SUBMODEL = prove
 (`!D (E:A->A->bool) w g u b.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        g IN D /\ E g w /\ u IN D /\ b IN D /\ eapply D E g u b
        ==> E u w /\ E b w`,
  REPEAT GEN_TAC THEN REWRITE_TAC[eapply] THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `g:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;`z:A`]
    EOPAIR_MEMBERS_SUBMODEL) THEN ASM_REWRITE_TAC[]);;

let EISFUN_SUBMODEL = prove
 (`!D (E:A->A->bool) w f.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\ f IN D /\ E f w
        ==> (eisfun (\u. u IN D /\ E u w) E f <=> eisfun D E f)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[eisfun; IN_SUBMODEL] THEN EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC (CONJUNCTS_THEN2
      (LABEL_TAC "pf") (LABEL_TAC "un"))) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `f:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "pf" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `b:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `eopair D (E:A->A->bool) u b z` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;`z:A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `b:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `b:A`; `b':A`; `z:A`; `z':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (z':A) IN D` STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z w /\ (E:A->A->bool) z' w`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `f:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u w /\ (E:A->A->bool) b w`
      STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;
          `z:A`] EOPAIR_MEMBERS_SUBMODEL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) b' w` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b':A`;
          `z':A`] EOPAIR_MEMBERS_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
        ALL_TAC] THEN
      SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E u b z`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;`z:A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
      SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E u b' z'`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b':A`;`z':A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
      USE_THEN "un" (MP_TAC o SPECL
        [`u:A`; `b:A`; `b':A`; `z:A`; `z':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC (CONJUNCTS_THEN2
      (LABEL_TAC "pf") (LABEL_TAC "un"))) THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "pf" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `b:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) u w /\ (E:A->A->bool) b w`
      STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;
          `z:A`] EOPAIR_MEMBERS_SUBMODEL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E u b z`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;`z:A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `b:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`u:A`; `b:A`; `b':A`; `z:A`; `z':A`] THEN
      STRIP_TAC THEN
      SUBGOAL_THEN `(z:A) IN D /\ (E:A->A->bool) z w` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
          `E:A->A->bool`;`u:A`;`b:A`;`z:A`] EOPAIR_IN) THEN
        ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
      SUBGOAL_THEN `(z':A) IN D /\ (E:A->A->bool) z' w` STRIP_ASSUME_TAC THENL
       [MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
          `E:A->A->bool`;`u:A`;`b':A`;`z':A`] EOPAIR_IN) THEN
        ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
      SUBGOAL_THEN `eopair D (E:A->A->bool) u b z` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b:A`;`z:A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eopair D (E:A->A->bool) u b' z'` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`b':A`;`z':A`]
          EOPAIR_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "un" (MP_TAC o SPECL
        [`u:A`; `b:A`; `b':A`; `z:A`; `z':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

let EINDOM_SUBMODEL = prove
 (`!D (E:A->A->bool) w g u.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        g IN D /\ E g w /\ u IN D /\ E u w
        ==> (eindom (\v. v IN D /\ E v w) E g u <=> eindom D E g u)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REWRITE_TAC[eindom; IN_SUBMODEL] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`;`b:A`]
      EAPPLY_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `(E:A->A->bool) b w` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`;`b:A`]
        EAPPLY_RAN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT2)];
      ALL_TAC] THEN
    EXISTS_TAC `b:A` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`;`b:A`]
      EAPPLY_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_REWRITE_TAC[th])]);;

let EDOMAIN_SUBMODEL = prove
 (`!D (E:A->A->bool) w g a.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        g IN D /\ E g w /\ a IN D /\ E a w
        ==> (edomain (\v. v IN D /\ E v w) E g a <=> edomain D E g a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[edomain; IN_SUBMODEL] THEN EQ_TAC THENL
   [DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC (LABEL_TAC "ch")) THEN
    CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u w` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `a:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`]
        EINDOM_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u w` ASSUME_TAC THENL
       [UNDISCH_TAC `eindom D (E:A->A->bool) g u` THEN
        REWRITE_TAC[eindom] THEN
        DISCH_THEN(X_CHOOSE_THEN `b:A` STRIP_ASSUME_TAC) THEN
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`;`b:A`]
          EAPPLY_RAN_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN(ACCEPT_TAC o CONJUNCT1)];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`]
        EINDOM_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ch")) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`g:A`;`u:A`]
      EINDOM_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th])]);;

let EFUNS_MEMBER_SUBMODEL = prove
 (`!D (E:A->A->bool) w om x vs vsW s.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        eomega D E om /\ om IN D /\ E om w /\ x IN D /\ E x w /\
        efuns D E om x vs /\ efuns (\v. v IN D /\ E v w) E om x vsW /\
        s IN D
        ==> (E s vsW <=> E s vs /\ E s w)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(vsW:A) IN D /\ (E:A->A->bool) vsW w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o GEN_REWRITE_RULE I [efuns] o
      check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a) &&
        can (find_term is_abs) (concl a))) THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) s w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `vsW:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a) &&
        can (find_term is_abs) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vsW`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC (LABEL_TAC "vl"))) THEN
    SUBGOAL_THEN `eisfun D (E:A->A->bool) s` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`]
             EISFUN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `edomain D (E:A->A->bool) s om` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`om:A`]
        EDOMAIN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!u b. u IN D /\ b IN D /\ eapply D (E:A->A->bool) s u b ==> E b x`
    ASSUME_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:A`; `b:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u w /\ (E:A->A->bool) b w`
      STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`u:A`;
          `b:A`] EAPPLY_RAN_SUBMODEL) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply (\v. v IN D /\ (E:A->A->bool) v w) E s u b`
      ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`u:A`;`b:A`]
          EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
      USE_THEN "vl" (MP_TAC o SPECL [`u:A`; `b:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a) &&
        not(can (find_term is_abs) (concl a)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a) &&
        not(can (find_term is_abs) (concl a)))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vs`))) THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC (LABEL_TAC "vd"))) THEN
    FIRST_ASSUM(MP_TAC o SPEC `s:A` o CONJUNCT2 o
      GEN_REWRITE_RULE I [efuns] o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "efuns")) (concl a) &&
        can (find_term is_abs) (concl a))) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REPEAT CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`]
             EISFUN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`om:A`]
        EDOMAIN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      MAP_EVERY X_GEN_TAC [`u:A`; `b:A`] THEN
      REWRITE_TAC[IN_SUBMODEL] THEN STRIP_TAC THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) s u b` ASSUME_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`u:A`;`b:A`]
          EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(SUBST1_TAC o GSYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "vd" (MP_TAC o SPECL [`u:A`; `b:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]]]);;

(* ------------------------------------------------------------------------- *)
(* ESUBSET_SUBMODEL: esubset is absolute at the transitive submodel          *)
(* W = (\u. u IN D /\ E u w), the analogue of ESUBSET_LCLASS. No closure     *)
(* hypothesis is needed (a subset test only quantifies over members, which   *)
(* stay in w by transitivity). Used for EDEFMEM_ABSOLUTE_W_F.                *)
(* ------------------------------------------------------------------------- *)

let ESUBSET_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        x IN D /\ E x w /\ y IN D /\ E y w
        ==> (esubset (\u. u IN D /\ E u w) E x y <=> esubset D E x y)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!y:A. y IN D /\ (E:A->A->bool) y w ==> !z. z IN D /\ E z y ==> E z w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[esubset; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Closure of w under the operations needed for the padded-assignment        *)
(* construction at the transitive submodel W = (\u. u IN D /\ E u w).        *)
(* HOLDS_APPLY_WMEM_SLOTS and HOLDS_WMEMFUN: the object formula saying that  *)
(*   every finite function with w-valued graph is in w (slot 0 = domain,     *)
(*   slot 9 = w), the analogue of HOLDS_LMEMFUN with the plain membership    *)
(*   _ %% 9 in place of the definability predicate lmem_at. It drives        *)
(*   NAT_FUN_SUBMODEL_F below.                                               *)
(* Closure of w under binary union (EBUNION_CLOSED_SUBMODEL_F, below) is     *)
(*   obtained by building the union in W (EBUNION_EXISTS_F), identifying it  *)
(*   with the union in D (EBUNION_SUBMODEL) and concluding by                *)
(*   EBUNION_UNIQUE.                                                         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_APPLY_WMEM_SLOTS = prove
 (`!D (E:A->A->bool) v a a' a''.
     model D E ZF_AX /\ valuation D v /\
     a IN D /\ a' IN D /\ a'' IN D
     ==> (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (apply_form 1 2 3) <=>
          eapply D E a a' a'') /\
         (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (3 %% 9) <=>
          E a'' (v 9))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v))`;
      `1`; `2`; `3`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]]);;

let HOLDS_WMEMFUN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (!! 1 ((fun_form 1 && (domain_form 1 0 &&
                 !! 2 (!! 3 (apply_form 1 2 3 --> (3 %% 9))))) -->
                (1 %% 9))) <=>
             !f. f IN D /\ eisfun D E f /\ edomain D E f (v 0) /\
                 (!u w. u IN D /\ w IN D /\ eapply D E f u w
                        ==> E w (v 9))
                 ==> E f (v 9))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[holds; HOLDS_AND; HOLDS_FUN_FORM; HOLDS_DOMAIN_FORM;
               HOLDS_APPLY_FORM; VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_THEN(LABEL_TAC "mn") THENL
   [X_GEN_TAC `f:A` THEN
    INTRO_TAC "h1 h2 h3 sem" THEN
    USE_THEN "mn" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      X_GEN_TAC `u:A` THEN DISCH_TAC THEN
      X_GEN_TAC `w:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
        `f:A`; `u:A`; `w:A`] HOLDS_APPLY_WMEM_SLOTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_TAC THEN
      USE_THEN "sem" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    X_GEN_TAC `f:A` THEN DISCH_TAC THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
      (LABEL_TAC "hf"))) THEN
    USE_THEN "mn" (MP_TAC o SPEC `f:A`) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      USE_THEN "hf" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
        `f:A`; `u:A`; `w:A`] HOLDS_APPLY_WMEM_SLOTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

(* ------------------------------------------------------------------------- *)
(* A finite function with w-valued graph is a member of the transitive set   *)
(* w: the analogues of LCLASS_FUN_BASE, LCLASS_FUN_STEP and LCLASS_NAT_FUN   *)
(* for W = (\u. u IN D /\ E u w), with plain membership E _ w in place of    *)
(* the definability predicate lmem_at.                                       *)
(* FUN_BASE_SUBMODEL: the empty function is in w (it is the empty set, which *)
(*   lies in om SUBSET w by transitivity, ENAT_IN_OMEGA at 0).               *)
(* FUN_STEP_SUBMODEL_F (below): if every w-valued function with domain m is  *)
(*   in w, then so is every w-valued function f with domain suc m:           *)
(*   f = r UNION {<m,f(m)>} with r its restriction to m, r is in w by        *)
(*   hypothesis, the added pair by closure under ordered pairs, the          *)
(*   singleton by the pairing-closure hypothesis, and the union by           *)
(*   EBUNION_CLOSED_SUBMODEL_F.                                              *)
(* NAT_FUN_SUBMODEL_F (below): EOMEGA_INDUCT_HOLDS on the HOLDS_WMEMFUN      *)
(*   object formula (slot 0 = domain, slot 9 = w) combines the two. This is  *)
(*   the crux of the padded-assignment construction PADDED_ASSIGNMENT_W_F.   *)
(* ------------------------------------------------------------------------- *)

let FUN_BASE_SUBMODEL = prove
 (`!D (E:A->A->bool) w om e f.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        eomega D E om /\ om IN D /\ E om w /\
        eempty D E e /\ f IN D /\ eisfun D E f /\ edomain D E f e
        ==> E f w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(e:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) f` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `z:A` THEN REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `?u v:A. u IN D /\ v IN D /\ eopair D (E:A->A->bool) u v z`
    STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[eisfun]; ALL_TAC] THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) f u` ASSUME_TAC THENL
     [ASM_MESON_TAC[eindom; eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u e` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
    ASM_MESON_TAC[eempty]; ALL_TAC] THEN
  SUBGOAL_THEN `(f:A) = e` SUBST1_TAC THENL
   [ASM_MESON_TAC[EEMPTY_UNIQUE]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) e om` ASSUME_TAC THENL
   [MP_TAC(SPECL [`0`; `D:A->bool`; `E:A->A->bool`; `om:A`; `e:A`]
      ENAT_IN_OMEGA) THEN
    ASM_REWRITE_TAC[enat]; ALL_TAC] THEN
  USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* Closure of w under set difference and cartesian product, for the constant *)
(* tail (om \ nc) x {d0} of the padded assignment.                           *)
(* EDIFF_SUBMODEL and ECROSS_SUBMODEL: absoluteness at                       *)
(*   W = (\u. u IN D /\ E u w). EDIFF_SUBMODEL only quantifies over members  *)
(*   (like ESUBSET_SUBMODEL), while ECROSS_SUBMODEL reconstructs the ordered *)
(*   pairs via EOPAIR_SUBMODEL, both components lying in w by transitivity.  *)
(* The closure lemmas EDIFF_CLOSED_SUBMODEL_F and ECROSS_CLOSED_SUBMODEL_F   *)
(*   (below) build the operation in W (by the _EXISTS_F lemma), identify it  *)
(*   with the operation in D by the _SUBMODEL absoluteness, and conclude by  *)
(*   the _UNIQUE lemma; ECROSS_CLOSED_SUBMODEL_F needs the pairing-closure   *)
(*   hypothesis.                                                             *)
(* ------------------------------------------------------------------------- *)

let EDIFF_SUBMODEL = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ z IN D /\ E z w
        ==> (ediff (\u. u IN D /\ E u w) E x y z <=> ediff D E x y z)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[ediff; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  ASM_MESON_TAC[]);;

let ECROSS_SUBMODEL = prove
 (`!D (E:A->A->bool) w a b c.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        (!p q r. p IN D /\ E p w /\ q IN D /\ E q w /\ epair D E p q r
                 ==> E r w) /\
        a IN D /\ E a w /\ b IN D /\ E b w /\ c IN D /\ E c w
        ==> (ecross (\u. u IN D /\ E u w) E a b c <=> ecross D E a b c)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!p q:A. p IN D /\ E p w /\ q IN D /\ (E:A->A->bool) q p ==> E q w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
            eopair D (E:A->A->bool) c d p ==> E p w`
  (LABEL_TAC "opc") THENL
   [MATCH_MP_TAC EOPAIR_CLOSED_SUBMODEL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z:A. z IN D /\ E z w
          ==> ((?u vv. (u IN D /\ E u w) /\ (vv IN D /\ E vv w) /\
                       E u a /\ E vv b /\
                       eopair (\u. u IN D /\ E u w) E u vv z) <=>
               (?u vv. u IN D /\ vv IN D /\ E u a /\ E vv b /\
                       eopair D (E:A->A->bool) u vv z))`
  (LABEL_TAC "tf") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `vv:A`
        STRIP_ASSUME_TAC)) THEN
      RULE_ASSUM_TAC(REWRITE_RULE[IN_SUBMODEL]) THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `vv:A`] THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`vv:A`;`z:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
      DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `vv:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) u w /\ (E:A->A->bool) vv w`
      STRIP_ASSUME_TAC THENL
       [CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THENL
         [EXISTS_TAC `a:A`; EXISTS_TAC `b:A`] THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`u:A`; `vv:A`] THEN
      REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`u:A`;`vv:A`;`z:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
    ALL_TAC] THEN
  REWRITE_TAC[ecross; IN_SUBMODEL] THEN ASM_REWRITE_TAC[] THEN
  EQ_TAC THEN DISCH_TAC THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    ASM_CASES_TAC `(E:A->A->bool) z w` THENL
     [FIRST_X_ASSUM(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      USE_THEN "tf" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]);
      MATCH_MP_TAC(TAUT `~p /\ ~q ==> (p <=> q)`) THEN CONJ_TAC THENL
       [DISCH_TAC THEN UNDISCH_TAC `~((E:A->A->bool) z w)` THEN
        REWRITE_TAC[] THEN USE_THEN "tr" MATCH_MP_TAC THEN
        EXISTS_TAC `c:A` THEN ASM_REWRITE_TAC[];
        DISCH_THEN(X_CHOOSE_THEN `u:A` (X_CHOOSE_THEN `vv:A`
          STRIP_ASSUME_TAC)) THEN
        SUBGOAL_THEN `(E:A->A->bool) u w /\ (E:A->A->bool) vv w`
        STRIP_ASSUME_TAC THENL
         [CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THENL
           [EXISTS_TAC `a:A`; EXISTS_TAC `b:A`] THEN ASM_REWRITE_TAC[];
          ALL_TAC] THEN
        UNDISCH_TAC `~((E:A->A->bool) z w)` THEN REWRITE_TAC[] THEN
        USE_THEN "opc" MATCH_MP_TAC THEN
        MAP_EVERY EXISTS_TAC [`u:A`; `vv:A`] THEN ASM_REWRITE_TAC[]]];
    X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "tf" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th])]);;

(* ------------------------------------------------------------------------- *)
(* Relativization of a formula's bound quantifiers to membership in a set w  *)
(* (slot `wslot`), for the transitive-submodel absoluteness of the L         *)
(* hierarchy.  Analogue of `relativ` (which relativizes to the lclass        *)
(* constructibility predicate lmem_at); here each `!!x p` gets the guard     *)
(* `x %% wslot`, i.e. "x IN w".  formvars collects all variables (free and   *)
(* bound) so that the correctness lemma can exclude wslot-capture in the     *)
(* bound-variable case.                                                      *)
(* ------------------------------------------------------------------------- *)

let formvars = new_recursive_definition form_RECURSION
  `(formvars False = {}) /\
   (formvars (i %% j) = {i,j}) /\
   (formvars (Eq i j) = {i,j}) /\
   (formvars (p --> q) = formvars p UNION formvars q) /\
   (formvars (!! x p) = x INSERT formvars p)`;;

let relativ_w = new_recursive_definition form_RECURSION
  `(relativ_w wslot False = False) /\
   (relativ_w wslot (i %% j) = i %% j) /\
   (relativ_w wslot (Eq i j) = Eq i j) /\
   (relativ_w wslot (p --> q) = relativ_w wslot p --> relativ_w wslot q) /\
   (relativ_w wslot (!! x p) = !! x ((x %% wslot) --> relativ_w wslot p))`;;

let HOLDS_RELATIV_W = prove
 (`!D (E:A->A->bool) w wslot p v.
        ~(wslot IN formvars p) /\ v wslot = w
        ==> (holds D E v (relativ_w wslot p) <=>
             holds (\u. u IN D /\ E u w) E v p)`,
  GEN_TAC THEN GEN_TAC THEN GEN_TAC THEN GEN_TAC THEN
  MATCH_MP_TAC form_INDUCT THEN REPEAT CONJ_TAC THENL
   [REWRITE_TAC[relativ_w; holds];
    REWRITE_TAC[relativ_w; holds];
    REWRITE_TAC[relativ_w; holds];
    MAP_EVERY X_GEN_TAC [`p:form`; `q:form`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ihp") (LABEL_TAC "ihq")) THEN
    X_GEN_TAC `v:num->A` THEN
    REWRITE_TAC[formvars; IN_UNION; DE_MORGAN_THM] THEN STRIP_TAC THEN
    REWRITE_TAC[relativ_w; holds] THEN
    USE_THEN "ihp" (MP_TAC o SPEC `v:num->A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "ihq" (MP_TAC o SPEC `v:num->A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]);
    MAP_EVERY X_GEN_TAC [`x:num`; `p:form`] THEN
    DISCH_THEN(LABEL_TAC "ih") THEN
    X_GEN_TAC `v:num->A` THEN
    REWRITE_TAC[formvars; IN_INSERT; DE_MORGAN_THM] THEN STRIP_TAC THEN
    REWRITE_TAC[relativ_w; holds; IN_SUBMODEL] THEN
    SUBGOAL_THEN
     `!a:A. holds D E (((x:num) |-> a) (v:num->A)) (relativ_w wslot p) <=>
            holds (\u. u IN D /\ E u w) E (((x:num) |-> a) (v:num->A)) p`
    (LABEL_TAC "ih2") THENL
     [GEN_TAC THEN USE_THEN "ih" (MP_TAC o SPEC `((x:num) |-> (a:A)) v`) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]); ALL_TAC] THEN
    ASM_REWRITE_TAC[VALMOD; IMP_IMP]]);;

(* ------------------------------------------------------------------------- *)
(* Freshness of slot 26 for the L-recursion body (FORMVARS_LREC6_FRESH): 26  *)
(* exceeds every variable, free or bound, of rec_form lstep_form 6, so       *)
(* relativ_w can safely use slot 26 as the w-membership guard without        *)
(* variable capture (the side condition of HOLDS_RELATIV_W). Proved by fully *)
(* reducing formvars of the large formula to a concrete numeral set and      *)
(* deciding membership. FV_LREC6_CASES: the free variables of rec_form       *)
(* lstep_form 6 are among 6 and 7.                                           *)
(* ------------------------------------------------------------------------- *)

let FORMVARS_LREC6_FRESH = prove
 (`~(26 IN formvars(rec_form lstep_form 6))`,
  let macros = [And_DEF; Or_DEF; Iff_DEF; Exists_DEF; Not_DEF; True_DEF;
                Forallmem_DEF; Existsmem_DEF] in
  let natform_conv = TOP_DEPTH_CONV (fun tm -> match tm with
        Comb(Comb(Const("nat_form",_),k),i)
          when is_numeral k && not(k = `0`) ->
            (RATOR_CONV(RAND_CONV num_CONV) THENC
             REWR_CONV(CONJUNCT2 nat_form)) tm
      | _ -> failwith "natform_conv") in
  let fvsetconv =
    (REWRITE_CONV ([apply2_form; apply_form; applyto_form; attempt_form;
                    cross_form; defmem_form; domain_form; empty_form; fun_form;
                    functional_form; funs_form; hfset_form; inductive_form;
                    ispair_form; linear_form; lstep_form; nat_form; omega_form;
                    opair_form; ordinal_form; pair_form; ranmem_form; rec_form;
                    recapp4_form; recapp_form; relset_form; restrict_form;
                    sat_form; satall_form; satbody_form; sateq_form;
                    satfalse_form; satimp_form; satmem_form; satstage_form;
                    satstep_form; subset_form; suc_form; transitive_form;
                    univ_form; update_form; verdict_form; vstep_form] @ macros)
     THENC ONCE_DEPTH_CONV NUM_REDUCE_CONV THENC natform_conv
     THENC REWRITE_CONV([nat_form; empty_form; suc_form] @ macros)
     THENC ONCE_DEPTH_CONV NUM_REDUCE_CONV
     THENC REWRITE_CONV([formvars] @ macros)
     THENC ONCE_DEPTH_CONV NUM_REDUCE_CONV
     THENC REWRITE_CONV([formvars] @ macros)
     THENC ONCE_DEPTH_CONV NUM_REDUCE_CONV) in
  CONV_TAC(RAND_CONV(RAND_CONV fvsetconv)) THEN
  REWRITE_TAC[IN_INSERT; IN_UNION; NOT_IN_EMPTY] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[]);;

let FV_LREC6_CASES = prove
 (`!m. m IN FV(rec_form lstep_form 6) ==> m = 6 \/ m = 7`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`lstep_form`; `6`] FV_REC_FORM_SUB) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[ARITH_RULE `1 < 6`] THEN
    X_GEN_TAC `k:num` THEN DISCH_TAC THEN
    MP_TAC(SPEC `k:num` FVLT_LSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[SUBSET; IN_UNION; IN_DELETE; IN_INSERT; NOT_IN_EMPTY] THEN
  DISCH_THEN(MP_TAC o SPEC `m:num`) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `6 + 1 = 7`] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The L-stages as the L-recursion with no constraint on the valuation       *)
(* (ELSTAGE_EREC_NV): erec of lstep_form is valuation-independent            *)
(* (FV lstep_form SUBSET {0,1}), so the elstage/erec bridge holds for any    *)
(* valuation. This is essential at W, where the valuation for labs_form_wcl  *)
(* carries w in slot 26 and is not a valuation into W.                       *)
(* ------------------------------------------------------------------------- *)

let ELSTAGE_EREC_NV_F = prove
 (`!M (E:A->A->bool) a y v.
        model M E zfw_ax ==> (elstage M E a y <=> erec M E lstep_form v a y)`,
  REPEAT STRIP_TAC THEN
  FIRST_ASSUM(X_CHOOSE_TAC `vv:num->A` o MATCH_MP VALUATION_EXISTS o
              MATCH_MP MODEL_NONEMPTY) THEN
  MP_TAC(SPECL [`M:A->bool`; `E:A->A->bool`; `a:A`; `y:A`; `vv:num->A`]
    ELSTAGE_EREC_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MATCH_MP_TAC EREC_VALUATION THEN
  X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
  ASM_ARITH_TAC);;

let ELSTAGE_EREC_NV = prove
 (`!M (E:A->A->bool) a y v.
        model M E ZF_AX ==> (elstage M E a y <=> erec M E lstep_form v a y)`,
  MATCH_ACCEPT_TAC(ZF_OF_ZFW ELSTAGE_EREC_NV_F));;

(* ========================================================================= *)
(* ISO_HOLDS_COLL: transfer of holds across the Mostowski collapse pi = ga   *)
(* of the hull Som (X = Som). Given the collapse tower for Som, holds over   *)
(* the hull Som is equivalent to holds over the collapse range M' = Mp under *)
(* the isomorphism, for valuations v' = pi o v. (The single-valuedness,      *)
(* injectivity and isomorphism hypotheses of ISO_HOLDS are strengthened with *)
(* image-in-D conditions: the collapse has fixed points, so eapply gd x i    *)
(* holds for junk i, and raw single-valuedness is false.)                    *)
(* ========================================================================= *)

let ISO_HOLDS_COLL = prove
 (`!D (E:A->A->bool) Som a za la ga ya Mp.
      model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ ya IN D /\
      elstage D E a ya /\
      (!w. w IN D /\ E w Som ==> E w ya) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p))
      ==> !p v v'.
              (!k. v k IN D /\ E (v k) Som) /\
              (!k. v' k IN D /\ E (v' k) Mp) /\
              (!k. eapply D E ga (v k) (v' k))
              ==> (holds (\z. z IN D /\ E z Som) E v p <=>
                   holds (\z. z IN D /\ E z Mp) E v' p)`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl SomD ord yaD elya sub zaD laD gaD tow pza ext MpD rng" THEN
  SUBGOAL_THEN `(a:A) IN D` (LABEL_TAC "aD") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] EORDINAL_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ra ld gacc gd. raD ldD gaccD gdD rch elld gaccch gdch
             eopSND" THEN
  SUBGOAL_THEN `la:A = ld /\ ga:A = gd`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `la:A`; `ga:A`; `ld:A`; `gd:A`;
                  `za:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ld:A = ya` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ld:A`; `ya:A`]
      ELSTAGE_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `Mp:A`; `gd:A`]
    ISO_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [(* tot *)
      X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`] ECOLLTOWER_PI_TOTAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "sub" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[] THEN
      FIRST_ASSUM(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC o
        REWRITE_RULE[eapply] o
        check (fun th ->
          (try fst(dest_const(fst(strip_comb(concl th)))) = "eapply"
           with Failure _ -> false))) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `i:A`; `zz:A`]
          EOPAIR_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "rng" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`zz:A`; `x:A`] THEN ASM_REWRITE_TAC[];
      (* sv *)
      MAP_EVERY X_GEN_TAC [`x:A`; `i:A`; `i':A`] THEN STRIP_TAC THEN
      FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
        check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`; `i:A`]
          ECOLLTOWER_PI_RECURRENCE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`; `i':A`]
            ECOLLTOWER_PI_RECURRENCE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN ASM_REWRITE_TAC[] THEN
      DISCH_TAC THEN
      ASM_REWRITE_TAC[];
      (* onto *)
      X_GEN_TAC `i:A` THEN STRIP_TAC THEN
      USE_THEN "rng" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) (i:A) Mp`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A`
                 (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "gdch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) (p:A) gd`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `xx:A`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `img:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `u:A = xx` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `i:A`; `xx:A`;
                      `img:A`; `p:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[]; STRIP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      EXISTS_TAC `xx:A` THEN ASM_REWRITE_TAC[eapply] THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[];
      (* inj *)
      MAP_EVERY X_GEN_TAC [`x:A`; `x':A`; `i:A`] THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`; `x':A`; `i:A`]
          ECOLLTOWER_PI_INJ) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      (* iso *)
      MAP_EVERY X_GEN_TAC [`x:A`; `y:A`; `ix:A`; `iy:A`] THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`; `y:A`; `ix:A`; `iy:A`]
        ECOLLTOWER_PI_ISO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    DISCH_THEN ACCEPT_TAC]);;

(* ========================================================================= *)
(* COLL_TOTAL and COLL_ONTO: the collapse map ga is total on the hull Som,   *)
(* and maps it onto the collapse range M' = Mp. These are the totality and   *)
(* surjectivity parts of ISO_HOLDS_COLL as separate lemmas. With             *)
(* ISO_HOLDS_COLL and the transport of valuations along the collapse         *)
(* isomorphism (by SELECT), they give MODEL_MPRIME_F below:                  *)
(* M' = (\z. z IN D /\ E z Mp) is a model of zfw_ax iff the hull Som is.     *)
(* ========================================================================= *)

let COLL_TOTAL = prove
 (`!D (E:A->A->bool) Som a za la ga ya Mp.
      model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ ya IN D /\
      elstage D E a ya /\
      (!w. w IN D /\ E w Som ==> E w ya) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p))
      ==> !x. x IN D /\ E x Som ==> ?i. i IN D /\ E i Mp /\ eapply D E ga x i`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl SomD ord yaD elya sub zaD laD gaD tow pza ext MpD rng" THEN
  SUBGOAL_THEN `(a:A) IN D` (LABEL_TAC "aD") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] EORDINAL_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ra ld gacc gd. raD ldD gaccD gdD rch elld gaccch gdch
             eopSND" THEN
  SUBGOAL_THEN `la:A = ld /\ ga:A = gd`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `la:A`; `ga:A`; `ld:A`; `gd:A`;
                  `za:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ld:A = ya` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ld:A`; `ya:A`]
      ELSTAGE_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `x:A` THEN STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                    `ya:A`; `gd:A`; `x:A`] ECOLLTOWER_PI_TOTAL) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "sub" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `i:A` THEN ASM_REWRITE_TAC[] THEN
      FIRST_ASSUM(X_CHOOSE_THEN `zz:A` STRIP_ASSUME_TAC o
        REWRITE_RULE[eapply] o
        check (fun th ->
          (try fst(dest_const(fst(strip_comb(concl th)))) = "eapply"
           with Failure _ -> false))) THEN
      SUBGOAL_THEN `(zz:A) IN D` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `i:A`; `zz:A`]
          EOPAIR_IN) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "rng" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`zz:A`; `x:A`] THEN ASM_REWRITE_TAC[]);;

let COLL_ONTO = prove
 (`!D (E:A->A->bool) Som a za la ga ya Mp.
      model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ ya IN D /\
      elstage D E a ya /\
      (!w. w IN D /\ E w Som ==> E w ya) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p))
      ==> !i. i IN D /\ E i Mp ==> ?x. x IN D /\ E x Som /\ eapply D E ga x i`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "modl SomD ord yaD elya sub zaD laD gaD tow pza ext MpD rng" THEN
  SUBGOAL_THEN `(a:A) IN D` (LABEL_TAC "aD") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`] EORDINAL_IN) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`]
    ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@ra ld gacc gd. raD ldD gaccD gdD rch elld gaccch gdch
             eopSND" THEN
  SUBGOAL_THEN `la:A = ld /\ ga:A = gd`
  (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `la:A`; `ga:A`; `ld:A`; `gd:A`;
                  `za:A`] EOPAIR_INJ) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ld:A = ya` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ld:A`; `ya:A`]
      ELSTAGE_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  X_GEN_TAC `i:A` THEN STRIP_TAC THEN
      USE_THEN "rng" (MP_TAC o SPEC `i:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) (i:A) Mp`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `p:A`
                 (X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC)) THEN
      USE_THEN "gdch" (MP_TAC o SPEC `p:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun bic ->
                 MP_TAC(EQ_MP bic (ASSUME `(E:A->A->bool) (p:A) gd`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `xx:A`
        (CONJUNCTS_THEN2 ASSUME_TAC
          (X_CHOOSE_THEN `img:A` STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `u:A = xx` SUBST_ALL_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `u:A`; `i:A`; `xx:A`;
                      `img:A`; `p:A`] EOPAIR_INJ) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[]; STRIP_TAC THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      EXISTS_TAC `xx:A` THEN ASM_REWRITE_TAC[eapply] THEN
      EXISTS_TAC `p:A` THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* Towards the transfer of modelhood from ya to the hull and its collapse.   *)
(* SHADOWED_MATCH: any finite assignment of Som-elements to slots extends to *)
(* a shadowed valuation (FINITE_INDUCT_STRONG over SHADOWED_EXISTS,          *)
(* SHADOWED_UPDATE and EVALUATION_UPDATE). It is used to lift the            *)
(* elementarity of the hull from shadowed valuations to all valuations into  *)
(* Som (MODEL_SOM_ELEM_WA below, via HOLDS_VALUATION on FV p), so that a     *)
(* model ya of zfw_ax gives a model Som (MODEL_SOM_FROM_YA_WA_F) and hence a *)
(* model M'. Then object formulas and absoluteness lemmas for transitive     *)
(* submodels (HOLDS_WRANPROP_SLOTS, HOLDS_WMEMRAN, HOLDS_WHFCON_SLOTS,       *)
(* ERESTRICT_SUBMODEL, VSTEP_SUBMODEL), the formula labs_form_wcl for the    *)
(* absoluteness of the L-stages at a transitive w (HOLDS_LABS_FORM_WCL), and *)
(* STAGE_UNION_TRANSITIVE: a union of L-stages is transitive.                *)
(* ========================================================================= *)

let SHADOWED_MATCH = prove
 (`!D (E:A->A->bool) om Som s0 v.
        model D E ZF_AX /\ eomega D E om /\ evaluation D E om Som s0 /\
        (!i. v i IN D /\ E (v i) Som)
        ==> !s. FINITE s
                ==> ?sv v'. evaluation D E om Som sv /\ shadowed D E sv v' /\
                            (!i. i IN s ==> v' i = v i)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Som:A`; `s0:A`]
      SHADOWED_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `v0:num->A` STRIP_ASSUME_TAC) THEN
    MAP_EVERY EXISTS_TAC [`s0:A`; `v0:num->A`] THEN
    ASM_REWRITE_TAC[NOT_IN_EMPTY];
    MAP_EVERY X_GEN_TAC [`a:num`; `t:num->bool`] THEN
    DISCH_THEN(CONJUNCTS_THEN2
      (X_CHOOSE_THEN `sv:A` (X_CHOOSE_THEN `vv:num->A` STRIP_ASSUME_TAC))
      STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:num`] ENAT_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `ni:A`) THEN
    SUBGOAL_THEN `(ni:A) IN D /\ (E:A->A->bool) ni om` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN; ENAT_IN_OMEGA]; ALL_TAC] THEN
    SUBGOAL_THEN `(sv:A) IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EVALUATION_IN]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `sv:A`; `ni:A`; `(v:num->A) a`]
      EUPDATE_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `sv':A`) THEN
    MAP_EVERY EXISTS_TAC [`sv':A`; `(a |-> (v:num->A) a) vv`] THEN
    REPEAT CONJ_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Som:A`;
                          `sv:A`; `ni:A`; `(v:num->A) a`; `sv':A`]
        EVALUATION_UPDATE) THEN
      ASM_REWRITE_TAC[];
      MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Som:A`;
                          `sv:A`; `vv:num->A`; `a:num`; `ni:A`; `(v:num->A) a`;
                          `sv':A`] SHADOWED_UPDATE) THEN
      ASM_REWRITE_TAC[];
      X_GEN_TAC `i:num` THEN REWRITE_TAC[IN_INSERT; VALMOD] THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
      COND_CASES_TAC THEN ASM_MESON_TAC[]]]);;

let HOLDS_WRANPROP_SLOTS = prove
 (`!D (E:A->A->bool) v a a' a'' a'''.
     model D E ZF_AX /\ valuation D v /\
     a IN D /\ a' IN D /\ a'' IN D /\ a''' IN D
     ==> (holds D E ((4 |-> a''') ((3 |-> a'')
                     ((2 |-> a') ((1 |-> a) v))))
            (apply_form 1 3 4) <=>
          eapply D E a a'' a''') /\
         (holds D E ((4 |-> a''') ((3 |-> a'')
                     ((2 |-> a') ((1 |-> a) v))))
            (4 %% 9) <=>
          E a''' (v 9)) /\
         (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
            (inran_form 3 1) <=>
          einran D E a'' a)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((4 |-> (a''':A)) ((3 |-> (a'':A))
                 ((2 |-> (a':A)) ((1 |-> (a:A)) v))))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(4 |-> (a''':A)) ((3 |-> (a'':A))
        ((2 |-> (a':A)) ((1 |-> (a:A)) v)))`;
      `1`; `3`; `4`] HOLDS_APPLY_FORM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    REWRITE_TAC[holds; VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(3 |-> (a'':A)) ((2 |-> (a':A)) ((1 |-> (a:A)) v))`;
      `3`; `1`] HOLDS_INRAN_FORM) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN SUBST1_TAC THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[]]);;

let HOLDS_WMEMRAN = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (!! 1 (!! 2 ((fun_form 1 && (domain_form 1 0 &&
                 ((!! 3 (!! 4 (apply_form 1 3 4 --> (4 %% 9)))) &&
                  (!! 3 ((3 %% 2) <-> inran_form 3 1))))) -->
                (2 %% 9)))) <=>
             !g r. g IN D /\ r IN D /\ eisfun D E g /\
                   edomain D E g (v 0) /\
                   (!u w. u IN D /\ w IN D /\ eapply D E g u w
                          ==> E w (v 9)) /\
                   (!w. w IN D ==> (E w r <=> einran D E w g))
                   ==> E r (v 9))`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[holds; HOLDS_AND; HOLDS_IFF; HOLDS_FUN_FORM;
               HOLDS_DOMAIN_FORM; VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[HOLDS_APPLY_FORM; HOLDS_INRAN_FORM;
               VALUATION_VALMOD] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[HOLDS_WRANPROP_SLOTS] THEN
  SUBGOAL_THEN
   `!a a' a''. (a:A) IN D /\ a' IN D /\ a'' IN D
      ==> (holds D E ((3 |-> a'') ((2 |-> a') ((1 |-> a) v)))
             (inran_form 3 1) <=>
           einran D E a'' a)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`;
      `a:A`; `a':A`; `a'':A`; `a'':A`] HOLDS_WRANPROP_SLOTS) THEN
    ASM_REWRITE_TAC[] THEN SIMP_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[] THEN
  FIRST_X_ASSUM(K ALL_TAC o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "inran_form")) (concl th))) THEN
  EQ_TAC THEN DISCH_THEN(LABEL_TAC "H") THENL
   [MAP_EVERY X_GEN_TAC [`g:A`; `r:A`] THEN STRIP_TAC THEN
    USE_THEN "H" (MP_TAC o SPEC `g:A`) THEN ANTS_TAC THENL
     [FIRST_ASSUM ACCEPT_TAC;
      DISCH_THEN(MP_TAC o SPEC `r:A`) THEN ANTS_TAC THENL
       [FIRST_ASSUM ACCEPT_TAC;
        DISCH_THEN MATCH_MP_TAC THEN REPEAT CONJ_TAC THEN
        ASM_MESON_TAC[]]];
    X_GEN_TAC `g:A` THEN DISCH_TAC THEN
    X_GEN_TAC `r:A` THEN DISCH_TAC THEN STRIP_TAC THEN
    USE_THEN "H" (MP_TAC o SPECL [`g:A`; `r:A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THEN ASM_MESON_TAC[];
      DISCH_THEN ACCEPT_TAC]]);;

let HOLDS_WHFCON_SLOTS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v
              (?? 4 (hfstage_form 0 4 && ((4 %% 10) &&
                 ?? 5 ((5 %% 8) &&
                   ?? 6 (fun_form 6 && (domain_form 6 5 &&
                     ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
                      (!! 9 ((9 %% 4) -->
                             ?? 7 (apply_form 6 7 9)))))))))) <=>
             ?y. y IN D /\ ehfstage D E (v 0) y /\ E y (v 10) /\
                 ?M. M IN D /\ E M (v 8) /\
                     ?hh. hh IN D /\ eisfun D E hh /\
                          edomain D E hh M /\
                          (!k. k IN D
                               ==> !w. w IN D
                                       ==> eapply D E hh k w
                                           ==> E w y) /\
                          (!w. w IN D
                               ==> E w y
                                   ==> ?k. k IN D /\
                                           eapply D E hh k w))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!y:A. y IN D
      ==> (holds D E ((4 |-> y) v) (hfstage_form 0 4) <=>
           ehfstage D (E:A->A->bool) (v 0) y)`
  (LABEL_TAC "hf") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `valuation D ((4 |-> (y:A)) v)` ASSUME_TAC THENL
     [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(4 |-> (y:A)) v`;
      `0`; `4`] HOLDS_HFSTAGE_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> (holds D E ((6 |-> hh) ((5 |-> M) ((4 |-> y) v)))
             (fun_form 6) <=>
           eisfun D (E:A->A->bool) hh)`
  (LABEL_TAC "fn") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v))`; `6`]
      HOLDS_FUN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> (holds D E ((6 |-> hh) ((5 |-> M) ((4 |-> y) v)))
             (domain_form 6 5) <=>
           edomain D (E:A->A->bool) hh M)`
  (LABEL_TAC "dm") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v)))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(6 |-> (hh:A)) ((5 |-> (M:A)) ((4 |-> (y:A)) v))`; `6`; `5`]
      HOLDS_DOMAIN_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh k w:A. y IN D /\ M IN D /\ hh IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((9 |-> w) ((7 |-> k) ((6 |-> hh) ((5 |-> M)
              ((4 |-> y) v)))))
            (apply_form 6 7 9) <=>
           eapply D (E:A->A->bool) hh k w)`
  (LABEL_TAC "apA") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((9 |-> (w:A)) ((7 |-> (k:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(9 |-> (w:A)) ((7 |-> (k:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v))))`; `6`; `7`; `9`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh k w:A. y IN D /\ M IN D /\ hh IN D /\ k IN D /\ w IN D
      ==> (holds D E
            ((7 |-> k) ((9 |-> w) ((6 |-> hh) ((5 |-> M)
              ((4 |-> y) v)))))
            (apply_form 6 7 9) <=>
           eapply D (E:A->A->bool) hh k w)`
  (LABEL_TAC "apB") THENL
   [REPEAT STRIP_TAC THEN
    SUBGOAL_THEN
     `valuation D ((7 |-> (k:A)) ((9 |-> (w:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v)))))`
    ASSUME_TAC THENL [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(7 |-> (k:A)) ((9 |-> (w:A)) ((6 |-> (hh:A))
        ((5 |-> (M:A)) ((4 |-> (y:A)) v))))`; `6`; `7`; `9`]
      HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
    ALL_TAC] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[HOLDS_AND; holds] THEN
  ONCE_REWRITE_TAC[HOLDS_EX] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> ((!a'''. a''' IN D
                   ==> !a''''. a'''' IN D
                               ==> holds D E
                                   ((9 |-> a'''') ((7 |-> a''')
                                     ((6 |-> hh) ((5 |-> M)
                                       ((4 |-> y) v)))))
                                   (apply_form 6 7 9)
                                   ==> E a'''' y) <=>
           (!k. k IN D
                ==> !w. w IN D
                        ==> eapply D (E:A->A->bool) hh k w
                            ==> E w y))`
  (LABEL_TAC "bodyA") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THEN
    (DISCH_THEN(LABEL_TAC "H") THEN
     X_GEN_TAC `k:A` THEN DISCH_TAC THEN
     X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
     USE_THEN "H" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     USE_THEN "apA" (fun th ->
       MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`; `k:A`; `w:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     ASM_REWRITE_TAC[] THEN SIMP_TAC[] THEN
     USE_THEN "apA" (fun th ->
       MP_TAC(SPECL [`y:A`; `M:A`; `hh:A`; `k:A`; `w:A`] th)) THEN
     ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
     DISCH_THEN(fun th -> RULE_ASSUM_TAC(REWRITE_RULE[th])) THEN
     ASM_REWRITE_TAC[] THEN SIMP_TAC[]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!y M hh:A. y IN D /\ M IN D /\ hh IN D
      ==> ((!a'''. a''' IN D
                   ==> E a''' y
                       ==> ?a''''. a'''' IN D /\
                                   holds D E
                                     ((7 |-> a'''') ((9 |-> a''')
                                       ((6 |-> hh) ((5 |-> M)
                                         ((4 |-> y) v)))))
                                     (apply_form 6 7 9)) <=>
           (!w. w IN D
                ==> E w y
                    ==> ?k. k IN D /\
                            eapply D (E:A->A->bool) hh k w))`
  (LABEL_TAC "bodyB") THENL
   [REPEAT STRIP_TAC THEN EQ_TAC THEN
    (DISCH_THEN(LABEL_TAC "H") THEN
