     DISCH_THEN(fun th ->
       ASM_REWRITE_TAC[th] THEN ASM_REWRITE_TAC[GSYM th]));
    ALL_TAC] THEN
  EQ_TAC THEN
  (INTRO_TAC "@y. h1 + + @M. h2 h3 @hh. h4 +" THEN
