let VSTEP_SUBMODEL = prove
 (`!D (E:A->A->bool) wm r y.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        r IN D /\ E r wm /\ y IN D /\ E y wm /\
        (!u b w. u IN D /\ b IN D /\ w IN D /\
                 eapply D E r b w /\ esubset D E u w
                 ==> E u wm)
        ==> (vstep (\u. u IN D /\ E u wm) E r y <=> vstep D E r y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  REWRITE_TAC[vstep; IN_ELIM_THM] THEN
  EQ_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 STRIP_ASSUME_TAC (LABEL_TAC "ch")) THENL
   [CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u wm` ASSUME_TAC THENL
       [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `y:A` THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) u y`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r:A`; `b:A`;
                      `w:A`] EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `u:A`; `w:A`]
          ESUBSET_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) u wm` ASSUME_TAC THENL
       [FIRST_X_ASSUM(MP_TAC o SPECL [`u:A`; `b:A`; `w:A`] o
          check (fun a -> is_forall(concl a) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "esubset")) (concl a) &&
            not(can (find_term is_iff) (concl a)))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) b wm /\ (E:A->A->bool) w wm`
      STRIP_ASSUME_TAC THENL
       [SUBGOAL_THEN
         `?z. z IN D /\ eopair D (E:A->A->bool) b w z /\ E z r`
        STRIP_ASSUME_TAC THENL
         [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
            GEN_REWRITE_RULE I [eapply] o check (fun a ->
              concl a = `eapply D (E:A->A->bool) r b w`)) THEN
          EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[EOPAIR_IN];
          ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) z wm` ASSUME_TAC THENL
         [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `r:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `b:A`; `w:A`;
                      `z:A`] EOPAIR_MEMBERS_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
