      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r:A`; `b:A`;
                      `w:A`] EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `u:A`; `w:A`]
          ESUBSET_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th])]];
    CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "ch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(E:A->A->bool) b wm /\ (E:A->A->bool) w wm`
      STRIP_ASSUME_TAC THENL
       [SUBGOAL_THEN
         `?z. z IN D /\ eopair D (E:A->A->bool) b w z /\ E z r`
        STRIP_ASSUME_TAC THENL
         [FIRST_ASSUM(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
            GEN_REWRITE_RULE I [eapply] o check (fun a ->
              concl a = `eapply D (E:A->A->bool) r b w`)) THEN
          EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
          ASM_MESON_TAC[EOPAIR_IN];
          ALL_TAC] THEN
        SUBGOAL_THEN `(E:A->A->bool) z wm` ASSUME_TAC THENL
         [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `r:A` THEN
          ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `b:A`; `w:A`;
                      `z:A`] EOPAIR_MEMBERS_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r:A`; `b:A`;
                      `w:A`] EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `u:A`; `w:A`]
          ESUBSET_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th])];
      DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `w:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN
      ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r:A`; `b:A`;
                      `w:A`] EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th]);
        MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `u:A`; `w:A`]
