        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_MESON_TAC[th])]]]);;

let labs_form_wcl = new_definition
  `labs_form_wcl =
     !! 5 (rec_form lstep_form 4 -->
       (((4 %% 26) --> (5 %% 26)) &&
        !! 6 ((6 %% 26) -->
          !! 7 ((7 %% 26) -->
            ((Eq 6 4 && relativ_w 26 (rec_form lstep_form 6)) -->
             Eq 7 5)))))`;;

let HOLDS_LABS_FORM_WCL = prove
 (`!D (E:A->A->bool) w v0 a.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        valuation D v0 /\ (!i. ~(i = 26) ==> E (v0 i) w) /\ v0 26 = w /\
        a IN D
        ==> (holds D E ((4 |-> a) v0) labs_form_wcl <=>
             !yD. yD IN D
                  ==> erec D E lstep_form v0 a yD
                      ==> (E a w ==> E yD w) /\
                          (!a6. a6 IN D
                                ==> E a6 w
                                ==> !yL. yL IN D
                                         ==> E yL w
                                         ==> a6 = a /\
                                             erec (\u. u IN D /\
                                                (E:A->A->bool) u w)
                                                  E lstep_form v0 a6 yL
                                             ==> yL = yD))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `!yD. yD IN D
         ==> (holds D E ((5 |-> (yD:A)) ((4 |-> a) v0))
                (rec_form lstep_form 4) <=>
              erec D (E:A->A->bool) lstep_form v0 a yD)`
  (LABEL_TAC "recd") THENL
   [X_GEN_TAC `yD:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v0:num->A`;
                  `lstep_form`; `4`; `a:A`; `yD:A`] HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [ARITH_TAC;
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      REWRITE_TAC[CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!yD a6 yL. yD IN D /\ a6 IN D /\ yL IN D /\ E a6 w /\ E yL w
        ==> (holds D E ((7 |-> yL) ((6 |-> a6) ((5 |-> yD)
               ((4 |-> a) v0))))
               (relativ_w 26 (rec_form lstep_form 6)) <=>
             erec (\u. u IN D /\ (E:A->A->bool) u w) E lstep_form v0 a6 yL)`
  (LABEL_TAC "recl") THENL
   [MAP_EVERY X_GEN_TAC [`yD:A`; `a6:A`; `yL:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `26`;
                  `rec_form lstep_form 6`;
                  `(7 |-> (yL:A)) ((6 |-> (a6:A)) ((5 |-> (yD:A))
                     ((4 |-> (a:A)) v0)))`] HOLDS_RELATIV_W) THEN
    ANTS_TAC THENL
     [REWRITE_TAC[FORMVARS_LREC6_FRESH; VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
                  `rec_form lstep_form 6`;
                  `(7 |-> (yL:A)) ((6 |-> (a6:A)) ((26 |-> (a6:A)) v0))`;
                  `(7 |-> (yL:A)) ((6 |-> (a6:A)) ((5 |-> (yD:A))
                     ((4 |-> (a:A)) v0)))`] HOLDS_VALUATION) THEN
    ANTS_TAC THENL
     [X_GEN_TAC `m:num` THEN DISCH_TAC THEN
      SUBGOAL_THEN `m = 6 \/ m = 7` MP_TAC THENL
       [ASM_MESON_TAC[FV_LREC6_CASES]; ALL_TAC] THEN
      DISCH_THEN(DISJ_CASES_THEN SUBST1_TAC) THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SUBGOAL_THEN
     `valuation (\u. u IN D /\ (E:A->A->bool) u w) ((26 |-> (a6:A)) v0)`
    ASSUME_TAC THENL
     [REWRITE_TAC[valuation; IN_ELIM_THM] THEN X_GEN_TAC `i:num` THEN
      REWRITE_TAC[VALMOD] THEN COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
      CONJ_TAC THENL [ASM_MESON_TAC[valuation]; ASM_MESON_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
                  `(26 |-> (a6:A)) v0`; `lstep_form`; `6`; `a6:A`; `yL:A`]
      HOLDS_REC_FORM) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
       [ARITH_TAC;
        X_GEN_TAC `m:num` THEN DISCH_TAC THEN
        MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN
        ASM_REWRITE_TAC[] THEN ARITH_TAC];
      ALL_TAC] THEN
    DISCH_THEN(fun th ->
      MP_TAC(CONV_RULE(ONCE_DEPTH_CONV NUM_REDUCE_CONV) th)) THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC EREC_VALUATION THEN
    X_GEN_TAC `m:num` THEN STRIP_TAC THEN
    MP_TAC(SPEC `m:num` FVLT_LSTEP_FORM) THEN ASM_REWRITE_TAC[] THEN
    ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[labs_form_wcl; holds; HOLDS_AND] THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
  ASM_REWRITE_TAC[] THEN
  USE_THEN "recd" (fun t1 -> USE_THEN "recl" (fun t2 ->
    ASM_SIMP_TAC[t1; t2])));;

let STAGE_UNION_TRANSITIVE = prove
 (`!D (E:A->A->bool) c w.
        model D E ZF_AX /\ eordinal D E c /\ w IN D /\
        (!u. u IN D
             ==> (E u w <=>
                  ?b z. b IN D /\ z IN D /\ E b c /\
                        elstage D E b z /\ E u z))
        ==> etransitive D E w`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 wch" THEN
  REWRITE_TAC[etransitive] THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  REWRITE_TAC[esubset] THEN X_GEN_TAC `t:A` THEN STRIP_TAC THEN
  USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
      check (fun a -> concl a = `(E:A->A->bool) u w`))) THEN
  DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) z` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `z:A`]
      ELSTAGE_TRANSITIVE) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `b:A`]
        EORDINAL_MEMBER) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) t z` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o SPEC `u:A` o GEN_REWRITE_RULE I [etransitive] o
      check (fun th -> concl th = `etransitive D (E:A->A->bool) z`)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[esubset] THEN DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "wch" (MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* The condensation argument in models of the finite fragment zfw_ax. The    *)
(* basic theory for models of zfw_ax (the lemmas NAME_F) is developed        *)
(* together with the general lemmas, from the definition of zfw_ax on; what  *)
(* follows is specific to submodels: reflection for the fragment,            *)
(* absoluteness for and closure of a transitive submodel that is only        *)
(* assumed to satisfy zfw_ax, and the hull over a union of stages and its    *)
(* collapse.                                                                 *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* Reflection for the finite fragment: zfw_conj is the conjunction of the    *)
(* members of zfw_ax, each of which is a subformula of it (SUBFORM_ZFW).     *)
(* ------------------------------------------------------------------------- *)

let SUBFORM_AND_L = prove
 (`!p q. subform p (p && q)`,
  REWRITE_TAC[And_DEF; Not_DEF] THEN MESON_TAC[subform_RULES]);;

let SUBFORM_AND_INTO_R = prove
 (`!p q r. subform r q ==> subform r (p && q)`,
  REWRITE_TAC[And_DEF; Not_DEF] THEN MESON_TAC[subform_RULES]);;

let zfw_conj = new_definition
 `zfw_conj =
     (extensionality_ax) &&
     (foundation_ax) &&
     (pairing_ax) &&
     (union_ax) &&
     (powerset_ax) &&
     (infinity_ax) &&
     (separation_ax 0 10 11 False) &&
     (separation_ax 0 10 11 (0 %% 1)) &&
     (separation_ax 0 10 11 (Not(0 %% 1))) &&
     (separation_ax 0 10 11 (!! 1 (inductive_form 1 --> (0 %% 1)))) &&
     (separation_ax 0 10 11 (ordinal_form 0)) &&
     (separation_ax 0 10 11 (subset_form 0 1)) &&
     (separation_ax 0 10 11 (?? 3 (?? 4 ((3 %% 1) && opair_form 3 4 0)))) &&
     (separation_ax 0 10 11
      (?? 3 (?? 4
             (applyto_form 0 3 1 && (applyto_form 0 4 2 && Not(Eq 3 4)))))) &&
     (separation_ax 0 10 11
      (?? 2 (?? 3 (applyto_form 2 3 1 && subset_form 0 3)))) &&
     (separation_ax 0 10 11
      (?? 3 (?? 4 ((3 %% 1) && (4 %% 2) && opair_form 3 4 0)))) &&
     (separation_ax 0 10 11
      (fun_form 0 && domain_form 0 1 &&
       !!- 3 0 (!! 4 (!! 5 (opair_form 4 5 3 --> (5 %% 2)))))) &&
     (separation_ax 0 10 11
      (((0 %% 1) && Not(?? 4 (opair_form 2 4 0))) || opair_form 2 3 0)) &&
     (separation_ax 0 10 11 defmem_form) &&
     (separation_ax 0 10 11 (ranmem_form 0 1)) &&
     (separation_ax 4 10 11 satbody_form) &&
     (replacement_ax 2 3 10 11 12 (rec_form vstep_form 2)) &&
     (separation_ax 5 20 21 (Not(?? 6 (attempt_form lstep_form 6 5 7)))) &&
     (separation_ax 5 20 21 (Not(?? 6 (attempt_form vstep_form 6 5 7)))) &&
     (separation_ax 5 20 21 (Not(?? 6 (attempt_form satstep_form 6 5 7)))) &&
     (replacement_ax 5 6 20 21 22 (recstep_form lstep_form 5)) &&
     (replacement_ax 5 6 20 21 22 (recstep_form vstep_form 5)) &&
     (replacement_ax 5 6 20 21 22 (recstep_form satstep_form 5)) &&
     (separation_ax 7 10 11 (?? 8 (update_form 5 6 7 8 && sat_form 1 4 8)))`;;

let SUBFORM_ZFW = prove
 (`!q. q IN zfw_ax ==> subform q zfw_conj`,
  REWRITE_TAC[zfw_conj; zfw_ax; IN_INSERT; NOT_IN_EMPTY] THEN
  REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[] THEN
  REPEAT (MATCH_ACCEPT_TAC SUBFORM_AND_L ORELSE
          MATCH_ACCEPT_TAC SUBFORM_REFL ORELSE
          MATCH_MP_TAC SUBFORM_AND_INTO_R));;

(* ========================================================================= *)
(* Absoluteness at a transitive submodel W = (\u. u IN D /\ E u w) that is   *)
(* only assumed to satisfy zfw_ax (the ambient model still satisfies ZF_AX), *)
(* so that this hypothesis can be discharged by reflection, at a reflected   *)
(* union of stages (WVL_REFLECT). In turn: absoluteness of internal          *)
(* satisfaction (ESAT_ABSOLUTE_W_F); closure of w under binary union, finite *)
(* functions, difference and product, and the padded assignment              *)
(* PADDED_ASSIGNMENT_W_F; absoluteness of definability                       *)
(* (EDEFMEM_ABSOLUTE_W_F) and of the L-stages (ELSTAGE_ABS_STEP_W_F); the    *)
(* collapse M' satisfies zfw_ax iff the hull does (MODEL_MPRIME_F); the      *)
(* closure facts that follow from zfw_ax in W (pairs, updates, omega, the HF *)
(* stages and hf); and closure under Def (DEF_CLOSED_SUBMODEL_F,             *)
(* DEFCL_SUBMODEL_F), giving ELSTAGE_ABSOLUTE_WCL_W_F: for a IN w, the stage *)
(* L(a) is in w and is the same when computed in W.                          *)
(* ========================================================================= *)

let ESATBODY_RESTRICT_W_F = prove
 (`!D (E:A->A->bool) w om x hf vs two u2 vsW u2W rD rW p.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        ehfset D E om hf /\ E hf w /\
        efuns D E om x vs /\
        enat D E 2 two /\ two IN D /\ E two w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        efuns (\u. u IN D /\ E u w) E om x vsW /\
        esatuniv (\u. u IN D /\ E u w) E x u2W /\
        rD IN D /\ rW IN D /\ E rW w /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        (!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                        u0 IN D /\ E u0 w /\ s0' IN D /\
                        eupdate D E s0 a0 u0 s0' ==> E s0' w) /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    E c' w /\ E s' w /\ E b' w /\
                    everdict (\u. u IN D /\ E u w) E c' s' b' rW
                    ==> everdict D E c' s' b' rD) /\
        (!c' s' b'. c' IN D /\ s' IN D /\ b' IN D /\
                    E c' hf /\ E s' w /\ E b' two /\
                    everdict D E c' s' b' rD
                    ==> everdict (\u. u IN D /\ E u w) E c' s' b' rW) /\
        p IN D /\ E p u2W
        ==> (esatbody (\u. u IN D /\ E u w) E x rW p <=>
             esatbody D E x rD p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `enat (\u. u IN D /\ (E:A->A->bool) u w) E 2 two`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`2`;`two:A`]
           ENAT_SUBMODEL) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `(u2W:A) IN D /\ (E:A->A->bool) u2W w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ESATUNIV_IN o check (fun a ->
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatuniv")) (concl a) &&
      can (find_term is_abs) (concl a))) THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) p w` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `u2W:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
                 `om:A`; `x:A`; `hf:A`; `vsW:A`; `two:A`; `u2W:A`; `p:A`]
    ESATUNIV_PAIR_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `s:A`
    (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `cs:A` STRIP_ASSUME_TAC)))) THEN
  RULE_ASSUM_TAC(REWRITE_RULE[IN_SUBMODEL]) THEN
  SUBGOAL_THEN `eopair D (E:A->A->bool) c s cs` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c:A`;`s:A`;`cs:A`]
      EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `eopair D (E:A->A->bool) cs b2 p` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`cs:A`;`b2:A`;`p:A`]
      EOPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s vs` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`om:A`;`x:A`;
                  `vs:A`;`vsW:A`;`s:A`] EFUNS_MEMBER_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) s vsW`))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [UNDISCH_TAC `ehfset D (E:A->A->bool) om hf` THEN
    REWRITE_TAC[ehfset] THEN SIMP_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    MP_TAC(ISPECL
           [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
            `x:A`; `rW:A`; `c:A`; `s:A`; `b2:A`; `cs:A`; `p:A`]
      SATBODY_CASES_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
    INTRO_TAC "@tag data. h1 h2 h3 +" THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_SUBMODEL]) THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) tag data c` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`tag:A`;`data:A`;`c:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) tag hf /\ E data hf` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`om:A`;`hf:A`;`tag:A`;`data:A`;`c:A`]
             EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN
     `!a b. a IN D /\ b IN D /\ eopair D (E:A->A->bool) a b data
            ==> E a hf /\ E b hf`
    (LABEL_TAC "cmp") THENL
     [REPEAT GEN_TAC THEN STRIP_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`om:A`;`hf:A`;`a:A`;`b:A`;`data:A`]
             EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THEN
    REWRITE_TAC[esatbody] THEN
    MAP_EVERY EXISTS_TAC [`cs:A`; `b2:A`; `c:A`; `s:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN ASM_REWRITE_TAC[] THENL
     [DISJ1_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`b2:A`;`tag:A`;`data:A`]
        ESATFALSE_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
             ESATMEM_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
             ESATEQ_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      DISJ2_TAC THEN DISJ2_TAC THEN DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`hf:A`;`vs:A`;`two:A`;
                     `rD:A`;`rW:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
               ESATIMP_RESTRICT_W) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN
        FIRST_ASSUM(MP_TAC o SPECL [`c':A`;`s':A`;`b':A`] o
          check (fun th -> is_forall(concl th) &&
            can (find_term (fun t -> is_const t &&
              fst(dest_const t) = "everdict")) (concl th) &&
            can (find_term ((=) `hf:A`)) (concl th))) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
        ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      REPLICATE_TAC 4 DISJ2_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`hf:A`;`two:A`;`x:A`;
                     `rD:A`;`rW:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
          ESATALL_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th])];
    DISCH_TAC THEN
    MP_TAC(ISPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `rD:A`;
                   `c:A`; `s:A`; `b2:A`; `cs:A`; `p:A`] SATBODY_CASES) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    INTRO_TAC "@tag data. h4 h5 h6 +" THEN
    SUBGOAL_THEN `(E:A->A->bool) tag hf /\ E data hf` STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`om:A`;`hf:A`;`tag:A`;`data:A`;`c:A`]
             EHFSET_PAIR_MEMBERS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) tag w /\ (E:A->A->bool) data w`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THEN USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `hf:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E tag data c`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`tag:A`;`data:A`;`c:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
