    MAP_EVERY EXISTS_TAC [`cs:A`; `b2:A`; `c:A`; `s:A`] THEN
    ASM_REWRITE_TAC[IN_SUBMODEL] THEN
    MAP_EVERY EXISTS_TAC [`tag:A`; `data:A`] THEN
    ASM_REWRITE_TAC[IN_SUBMODEL] THENL
     [DISJ1_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`b2:A`;`tag:A`;`data:A`]
        ESATFALSE_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]);
      DISJ2_TAC THEN DISJ1_TAC THEN
      MP_TAC(ISPECL
             [`D:A->bool`;`E:A->A->bool`;`w:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
