      REPLICATE_TAC 4 DISJ2_TAC THEN
      MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`hf:A`;`two:A`;`x:A`;
                     `rD:A`;`rW:A`;`s:A`;`b2:A`;`tag:A`;`data:A`]
          ESATALL_RESTRICT_W) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
