let ESATUNIV_MEMBER_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om x hf vs two u2 vsW u2W c s b cs p.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        ehfset D E om hf /\ E hf w /\
        efuns D E om x vs /\
        enat D E 2 two /\ two IN D /\ E two w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        efuns (\u. u IN D /\ E u w) E om x vsW /\
        enat (\u. u IN D /\ E u w) E 2 two /\
        esatuniv (\u. u IN D /\ E u w) E x u2W /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        c IN D /\ s IN D /\ b IN D /\ cs IN D /\ p IN D /\
        eopair D E c s cs /\ eopair D E cs b p
        ==> (E p u2W <=>
             E p u2 /\ s IN (\u. u IN D /\ E u w))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
            eopair D (E:A->A->bool) c d p ==> E p w`
  (LABEL_TAC "opc") THENL
   [MATCH_MP_TAC EOPAIR_CLOSED_SUBMODEL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [UNDISCH_TAC `ehfset D (E:A->A->bool) om hf` THEN
    REWRITE_TAC[ehfset] THEN SIMP_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(u2W:A) IN D /\ (E:A->A->bool) u2W w`
    STRIP_ASSUME_TAC THENL
     [FIRST_ASSUM(MP_TAC o MATCH_MP ESATUNIV_IN o check (fun a ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "esatuniv")) (concl a) &&
        can (find_term is_abs) (concl a))) THEN
      REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) p w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `u2W:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                   `E:A->A->bool`; `om:A`; `x:A`; `hf:A`; `vsW:A`;
                   `two:A`; `u2W:A`; `p:A`] ESATUNIV_PAIR_EXISTS_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `c2:A` (X_CHOOSE_THEN `s2:A`
      (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `cs2:A` STRIP_ASSUME_TAC)))) THEN
    RULE_ASSUM_TAC(REWRITE_RULE[IN_SUBMODEL]) THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) c2 s2 cs2` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c2:A`;`s2:A`;`cs2:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `eopair D (E:A->A->bool) cs2 b2 p` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`cs2:A`;`b2:A`;`p:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(cs2:A) = cs /\ (b2:A) = b`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `(c2:A) = c /\ (s2:A) = s`
    (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
     [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s vs /\ (E:A->A->bool) s w`
    STRIP_ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`om:A`;`x:A`;
                    `vs:A`;`vsW:A`;`s:A`] EFUNS_MEMBER_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) s vsW`))) THEN
      SIMP_TAC[]; ALL_TAC] THEN
    CONJ_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`x:A`;`hf:A`;
                     `vs:A`;`two:A`;`u2:A`;`c:A`;`s:A`;`b:A`;`cs:A`;`p:A`]
        ESATUNIV_PAIR_INTRO) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]];
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
      (STRIP_ASSUME_TAC o REWRITE_RULE[IN_SUBMODEL])) THEN
    MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`x:A`;`hf:A`;
                   `vs:A`;`two:A`;`u2:A`;`c:A`;`s:A`;`b:A`;`cs:A`;`p:A`]
      ESATUNIV_PAIR_DECOMP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2
      ASSUME_TAC ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) c w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `hf:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `two:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) cs w` ASSUME_TAC THENL
     [USE_THEN "opc" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`c:A`;`s:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) p w` ASSUME_TAC THENL
     [USE_THEN "opc" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`cs:A`;`b:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) s vsW` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`om:A`;`x:A`;
                    `vs:A`;`vsW:A`;`s:A`] EFUNS_MEMBER_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
    SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E c s cs`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c:A`;`s:A`;`cs:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
    SUBGOAL_THEN `eopair (\u. u IN D /\ (E:A->A->bool) u w) E cs b p`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`cs:A`;`b:A`;`p:A`]
        EOPAIR_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
    MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                   `E:A->A->bool`; `om:A`; `x:A`; `hf:A`; `vsW:A`;
                   `two:A`; `u2W:A`; `c:A`; `s:A`; `b:A`; `cs:A`; `p:A`]
      ESATUNIV_PAIR_INTRO_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; DISCH_THEN ACCEPT_TAC]]);;

let ESATSTAGE_GRAPHS_W_F = prove
 (`!D (E:A->A->bool) w om x u2 u2W.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        esatuniv (\u. u IN D /\ E u w) E x u2W
        ==> ?FD FW.
              FD IN D /\ FW IN (\u. u IN D /\ E u w) /\
              (!n t. n IN D /\ t IN D
                     ==> (eapply D E FD n t <=>
                          E n om /\ esatstage D E x n t)) /\
              (!n t. n IN D /\ t IN D
                     ==> (eapply D E FW n t <=>
                          E n om /\ t IN (\u. u IN D /\ E u w) /\
                          esatstage (\u. u IN D /\ E u w) E x n t))`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (\u. u IN D /\ (E:A->A->bool) u w) E om`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                   `E:A->A->bool`; `om:A`] EOMEGA_ORDINAL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2W:A) IN D /\ (E:A->A->bool) u2W w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ESATUNIV_IN o check (fun a ->
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatuniv")) (concl a) &&
      can (find_term is_abs) (concl a))) THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2W:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation D ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A))))`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
    REWRITE_TAC[VALMOD] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation (\u. u IN D /\ (E:A->A->bool) u w)
      ((3 |-> (u2W:A)) ((2 |-> x) (\k:num. (om:A))))`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN X_GEN_TAC `i:num` THEN
    REWRITE_TAC[VALMOD; IN_SUBMODEL] THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?FD. erecres D (E:A->A->bool) satstep_form
           ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A)))) om FD`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[SATSTEP_QFUN; SATSTEP_QTOTAL];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FD:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ww. ww IN D
        ==> ((E:A->A->bool) ww FD <=>
             ?b y. b IN D /\ y IN D /\ E b om /\
                   erec D E satstep_form
                     ((3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A))))
                     b y /\
                   eopair D E b y ww)`
  (LABEL_TAC "fdch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n t. n IN D /\ t IN D
          ==> (eapply D (E:A->A->bool) FD n t <=>
               E n om /\ esatstage D E x n t)`
  (LABEL_TAC "fdap") THENL
   [MAP_EVERY X_GEN_TAC [`n:A`; `t:A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`; `u2:A`;
                  `n:A`; `t:A`;
                  `(3 |-> (u2:A)) ((2 |-> x) (\k:num. (om:A)))`]
      ESATSTAGE_EREC) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
