      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`n:A`; `t:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `?FW. erecres (\u. u IN D /\ (E:A->A->bool) u w) E satstep_form
           ((3 |-> (u2W:A)) ((2 |-> x) (\k:num. (om:A)))) om FW`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS_F THEN
    MAP_EVERY EXISTS_TAC [`5`; `20`] THEN
    ASM_REWRITE_TAC[ENGINE_READY_SATSTEP] THEN
    ASM_MESON_TAC[SATSTEP_QFUN_F; SATSTEP_QTOTAL_F];
    ALL_TAC] THEN
  SUBGOAL_THEN `(FW:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
  ASSUME_TAC THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN `(FW:A) IN D /\ (E:A->A->bool) FW w` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(FW:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ww. ww IN (\u. u IN D /\ (E:A->A->bool) u w)
        ==> ((E:A->A->bool) ww FW <=>
             ?b y. b IN (\u. u IN D /\ E u w) /\
                   y IN (\u. u IN D /\ E u w) /\ E b om /\
                   erec (\u. u IN D /\ E u w) E satstep_form
                     ((3 |-> (u2W:A)) ((2 |-> x) (\k:num. (om:A))))
                     b y /\
                   eopair (\u. u IN D /\ E u w) E b y ww)`
  (LABEL_TAC "fwch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!n t. n IN (\u. u IN D /\ (E:A->A->bool) u w) /\
          t IN (\u. u IN D /\ E u w)
          ==> (eapply (\u. u IN D /\ E u w) (E:A->A->bool) FW n t <=>
