       SIMP_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `(E:A->A->bool) wv u2W` ASSUME_TAC THENL
      [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `x:A`;
                     `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsW:A`;
                     `u2W:A`; `c':A`; `s':A`; `b':A`; `csw:A`;
                     `wv:A`] ESATUNIV_MEMBER_SUBMODEL_F) THEN
