      [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `two:A` THEN
       ASM_REWRITE_TAC[]; ALL_TAC] THEN
     SUBGOAL_THEN `(E:A->A->bool) csw w` ASSUME_TAC THENL
      [USE_THEN "opc" MATCH_MP_TAC THEN
       MAP_EVERY EXISTS_TAC [`c':A`; `s':A`] THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN `(E:A->A->bool) wv w` ASSUME_TAC THENL
      [USE_THEN "opc" MATCH_MP_TAC THEN
       MAP_EVERY EXISTS_TAC [`csw:A`; `b':A`] THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     SUBGOAL_THEN
      `(c':A) IN (\u. u IN D /\ E u w) /\
       (s':A) IN (\u. u IN D /\ E u w) /\
       (b':A) IN (\u. u IN D /\ E u w) /\
       (csw:A) IN (\u. u IN D /\ E u w) /\
       (wv:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
     STRIP_ASSUME_TAC THENL
      [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
     SUBGOAL_THEN
      `eopair (\u. u IN D /\ E u w) (E:A->A->bool) c' s' csw /\
       eopair (\u. u IN D /\ E u w) E csw b' wv`
     STRIP_ASSUME_TAC THENL
      [CONJ_TAC THENL
        [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c':A`;`s':A`;
                        `csw:A`] EOPAIR_SUBMODEL);
         MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`csw:A`;`b':A`;
                        `wv:A`] EOPAIR_SUBMODEL)] THEN
       (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]));
       ALL_TAC] THEN
     MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                   `E:A->A->bool`;
                   `x:A`; `sm:A`; `rW:A`; `c':A`; `s':A`; `b':A`;
                   `m:A`; `tWm:A`; `csw:A`; `wv:A`]
