  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    USE_THEN "ind" (MP_TAC o SPEC `n:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o GEN_REWRITE_RULE I [th])) THEN
  DISCH_THEN(MP_TAC o SPEC `tW:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `t:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `p:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC])]);;

let ESAT_ABSOLUTE_W_F = prove
 (`!D (E:A->A->bool) w om x hf vs two u2 vsW u2W c s.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        ehfset D E om hf /\ E hf w /\
        efuns D E om x vs /\
        enat D E 2 two /\ two IN D /\ E two w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        efuns (\u. u IN D /\ E u w) E om x vsW /\
        esatuniv (\u. u IN D /\ E u w) E x u2W /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        (!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                        u0 IN D /\ E u0 w /\ s0' IN D /\
                        eupdate D E s0 a0 u0 s0' ==> E s0' w) /\
        c IN D /\ s IN D /\ E c hf /\ E s vs /\
        s IN (\u. u IN D /\ E u w)
        ==> (esat (\u. u IN D /\ E u w) E x c s <=> esat D E x c s)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
            eopair D (E:A->A->bool) c d p ==> E p w`
  (LABEL_TAC "opc") THENL
   [MATCH_MP_TAC EOPAIR_CLOSED_SUBMODEL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `enat (\u. u IN D /\ (E:A->A->bool) u w) E 2 two`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`2`;`two:A`]
      ENAT_SUBMODEL) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [UNDISCH_TAC `ehfset D (E:A->A->bool) om hf` THEN
    REWRITE_TAC[ehfset] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2W:A) IN D /\ (E:A->A->bool) u2W w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP ESATUNIV_IN o check (fun a ->
      can (find_term (fun t -> is_const t &&
        fst(dest_const t) = "esatuniv")) (concl a) &&
      can (find_term is_abs) (concl a))) THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2W:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(u2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESATUNIV_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) c w` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `hf:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) s w` ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [IN_SUBMODEL] o check (fun a ->
      concl a = `(s:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`)) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[esat] THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
      (X_CHOOSE_THEN `t:A` (X_CHOOSE_THEN `z1:A`
        (X_CHOOSE_THEN `cs:A` (X_CHOOSE_THEN `wv:A`
          STRIP_ASSUME_TAC)))))) THEN
    SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
     [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                    `E:A->A->bool`; `om':A`; `om:A`] EOMEGA_UNIQUE_F) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `(n:A) IN D /\ E n w /\ (t:A) IN D /\ E t w /\ (z1:A) IN D /\ E z1 w /\
      (cs:A) IN D /\ E cs w /\ (wv:A) IN D /\ (E:A->A->bool) wv w`
    STRIP_ASSUME_TAC THENL
     [RULE_ASSUM_TAC(REWRITE_RULE[IN_SUBMODEL]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair D (E:A->A->bool) c s cs /\ eopair D E cs z1 wv`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c:A`;`s:A`;`cs:A`]
          EOPAIR_SUBMODEL);
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`cs:A`;`z1:A`;`wv:A`]
          EOPAIR_SUBMODEL)] THEN
      (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[]);
      ALL_TAC] THEN
    SUBGOAL_THEN `enat D (E:A->A->bool) 1 z1` ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`1`;`z1:A`]
        ENAT_SUBMODEL) THEN
      ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a =
            `enat (\u. u IN D /\ (E:A->A->bool) u w) E 1 z1`))) THEN
      SIMP_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    SUBGOAL_THEN
     `?tD. (tD:A) IN D /\ esatstage D (E:A->A->bool) x n tD`
    STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[ESATSTAGE_EXISTS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) wv tD` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsW:A`;
                    `u2W:A`] ESATSTAGE_RESTRICT_W_F) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPECL [`tD:A`; `t:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `wv:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        UNDISCH_TAC `(E:A->A->bool) wv t` THEN REWRITE_TAC[th]) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `n:A`; `tD:A`; `z1:A`; `cs:A`; `wv:A`] THEN
    ASM_REWRITE_TAC[];
    DISCH_THEN(X_CHOOSE_THEN `om':A` (X_CHOOSE_THEN `n:A`
