          STRIP_ASSUME_TAC)))))) THEN
    SUBGOAL_THEN `om':A = om` SUBST_ALL_TAC THENL
     [ASM_MESON_TAC[EOMEGA_UNIQUE]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
     [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) n w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(n:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
    ASSUME_TAC THENL
     [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `eordinal (\u. u IN D /\ E u w) (E:A->A->bool) n`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`n:A`]
