      ALL_TAC] THEN
    SUBGOAL_THEN
     `?tW. (tW:A) IN (\u. u IN D /\ E u w) /\
           esatstage (\u. u IN D /\ E u w) (E:A->A->bool) x n tW`
    STRIP_ASSUME_TAC THENL
