    SUBGOAL_THEN `(E:A->A->bool) z1 om` ASSUME_TAC THENL
     [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) z1 w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z1:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
    ASSUME_TAC THENL
     [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) cs w` ASSUME_TAC THENL
     [USE_THEN "opc" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`c:A`; `s:A`] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(cs:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
    ASSUME_TAC THENL
     [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) wv w` ASSUME_TAC THENL
     [USE_THEN "opc" MATCH_MP_TAC THEN
      MAP_EVERY EXISTS_TAC [`cs:A`; `z1:A`] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(wv:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
    ASSUME_TAC THENL
     [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN
     `eopair (\u. u IN D /\ E u w) (E:A->A->bool) c s cs /\
      eopair (\u. u IN D /\ E u w) E cs z1 wv`
    STRIP_ASSUME_TAC THENL
     [CONJ_TAC THENL
       [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`c:A`;`s:A`;`cs:A`]
          EOPAIR_SUBMODEL);
        MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`cs:A`;`z1:A`;`wv:A`]
          EOPAIR_SUBMODEL)] THEN
      (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
       DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]));
      ALL_TAC] THEN
    SUBGOAL_THEN `enat (\u. u IN D /\ (E:A->A->bool) u w) E 1 z1`
    ASSUME_TAC THENL
     [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`1`;`z1:A`]
        ENAT_SUBMODEL) THEN
      ANTS_TAC THENL
      [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
    MAP_EVERY EXISTS_TAC
     [`om:A`; `n:A`; `tW:A`; `z1:A`; `cs:A`; `wv:A`] THEN
    ASM_REWRITE_TAC[]]);;

let EBUNION_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ ebunion D E x y z
        ==> E z w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w) /\
    (y:A) IN (\u. u IN D /\ E u w)`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                 `E:A->A->bool`; `x:A`; `y:A`] EBUNION_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `z':A`) THEN
  SUBGOAL_THEN `(z':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(z':A) IN D /\ (E:A->A->bool) z' w` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(z':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ebunion D (E:A->A->bool) x y z'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`y:A`;`z':A`]
      EBUNION_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = z'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[EBUNION_UNIQUE]);;

let FUN_STEP_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om m sm f.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        eomega D E om /\ om IN D /\ E om w /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
        (!g. g IN D /\ eisfun D E g /\ edomain D E g m /\
             (!u vv. u IN D /\ vv IN D /\ eapply D E g u vv
                    ==> E vv w)
             ==> E g w) /\
        f IN D /\ eisfun D E f /\ edomain D E f sm /\
        (!u vv. u IN D /\ vv IN D /\ eapply D E f u vv
               ==> E vv w)
        ==> E f w`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 pc h5 h6 h7 h8 h9 h10 h11 ih h12 h13 h14 val" THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
