      MATCH_MP_TAC FUN_BASE_SUBMODEL THEN
      MAP_EVERY EXISTS_TAC [`D:A->bool`; `om:A`; `e:A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (m:A)) ((9 |-> (w:A)) v0))`
