  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPEC `f:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let EDIFF_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w x y z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        x IN D /\ E x w /\ y IN D /\ E y w /\ ediff D E x y z
        ==> E z w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(x:A) IN (\u. u IN D /\ E u w) /\
    (y:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                 `E:A->A->bool`; `x:A`; `y:A`] EDIFF_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `z':A`) THEN
  SUBGOAL_THEN `(z':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `(z':A) IN D /\ (E:A->A->bool) z' w` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(z':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ediff D (E:A->A->bool) x y z'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`x:A`;`y:A`;`z':A`]
      EDIFF_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(z:A) = z'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[EDIFF_UNIQUE]);;

let ECROSS_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w a b c.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        (!p q r. p IN D /\ E p w /\ q IN D /\ E q w /\ epair D E p q r
                 ==> E r w) /\
        a IN D /\ E a w /\ b IN D /\ E b w /\ ecross D E a b c
        ==> E c w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN
   `(a:A) IN (\u. u IN D /\ E u w) /\
    (b:A) IN (\u. u IN D /\ (E:A->A->bool) u w)`
  STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(ISPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                 `E:A->A->bool`; `a:A`; `b:A`] ECROSS_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `c':A`) THEN
  SUBGOAL_THEN `(c':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecross]; ALL_TAC] THEN
  SUBGOAL_THEN `(c':A) IN D /\ (E:A->A->bool) c' w` STRIP_ASSUME_TAC THENL
   [UNDISCH_TAC `(c':A) IN (\u. u IN D /\ (E:A->A->bool) u w)` THEN
    REWRITE_TAC[IN_SUBMODEL] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecross D (E:A->A->bool) a b c'` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`a:A`;`b:A`;`c':A`]
      ECROSS_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(c:A) = c'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  ASM_MESON_TAC[ECROSS_UNIQUE]);;

let PADDED_ASSIGNMENT_W_F = prove
 (`!D (E:A->A->bool) w om x vs vsW s nc d0.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        efuns D E om x vs /\ efuns (\u. u IN D /\ E u w) E om x vsW /\
        s IN D /\ E s vs /\
        nc IN D /\ E nc om /\ d0 IN D /\ E d0 x
        ==> ?st. st IN D /\ E st w /\ E st vsW /\
                 !i vv. i IN D /\ vv IN D /\ E i nc
                       ==> (eapply D E st i vv <=> eapply D E s i vv)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  FIRST_X_ASSUM(LABEL_TAC "pc" o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "epair")) (concl th))) THEN
  SUBGOAL_THEN `(om:A) IN D /\ (x:A) IN D` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN; LCLASS_IN_D]; ALL_TAC] THEN
  SUBGOAL_THEN
   `eisfun D (E:A->A->bool) s /\ edomain D E s om /\
    !u vv. u IN D /\ vv IN D /\ eapply D E s u vv ==> E vv x`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN D ==> ((E:A->A->bool) u om <=> eindom D E s u)`
  (LABEL_TAC "sdm") THENL [ASM_MESON_TAC[edomain]; ALL_TAC] THEN
  SUBGOAL_THEN `?r1. erestrict D (E:A->A->bool) s nc r1`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(r1:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN D
        ==> ((E:A->A->bool) z r1 <=>
             E z s /\ ?u vv. u IN D /\ vv IN D /\ E u nc /\
                            eopair D E u vv z)`
  (LABEL_TAC "r1ch") THENL [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) r1` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!i vv. i IN D /\ vv IN D
          ==> (eapply D (E:A->A->bool) r1 i vv <=>
               E i nc /\ eapply D E s i vv)`
  (LABEL_TAC "r1ap") THENL
   [MAP_EVERY X_GEN_TAC [`i:A`; `vv:A`] THEN STRIP_TAC THEN
    REWRITE_TAC[eapply] THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "r1ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z r1`))) THEN
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `u':A` (X_CHOOSE_THEN `vv':A`
          STRIP_ASSUME_TAC))) THEN
      SUBGOAL_THEN `(u':A) = i /\ (vv':A) = vv`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_REWRITE_TAC[] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[];
      DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC
        (X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "r1ch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`i:A`; `vv:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) r1 nc` ASSUME_TAC THENL
   [REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `u:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) u om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_TRANS]; ALL_TAC] THEN
      SUBGOAL_THEN `eindom D (E:A->A->bool) s u` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[eindom] THEN
      DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `vv:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "r1ap" (MP_TAC o SPECL [`u:A`; `vv:A`]) THEN
