      DISCH_THEN(X_CHOOSE_THEN `vv:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "r1ap" (MP_TAC o SPECL [`u:A`; `vv:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
