            concl a = `eapply D (E:A->A->bool) r1 u vv`))) THEN
      SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) r1 w` ASSUME_TAC THENL
