  SUBGOAL_THEN `(dm:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vv. vv IN D ==> ((E:A->A->bool) vv dm <=> E vv om /\ ~E vv nc)`
  (LABEL_TAC "dmch") THENL [ASM_MESON_TAC[ediff]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) nc w` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) dm w` ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`om:A`;`nc:A`;`dm:A`]
      EDIFF_CLOSED_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?sg. epair D (E:A->A->bool) d0 d0 sg`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!vv. vv IN D ==> ((E:A->A->bool) vv sg <=> vv = d0)`
