    MAP_EVERY EXISTS_TAC [`d0:A`; `d0:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `?tl. ecross D (E:A->A->bool) dm sg tl`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ECROSS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(tl:A) IN D` ASSUME_TAC THENL
