        ASM_MESON_TAC[eisfun];
        ASM_MESON_TAC[]];
      MAP_EVERY X_GEN_TAC
       [`u:A`; `vv:A`; `vv':A`; `z:A`; `z':A`] THEN STRIP_TAC THEN
