    REWRITE_TAC[ehfset] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(two:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[efuns] o check (fun th ->
      can (find_term (fun t -> is_const t && fst(dest_const t) = "efuns"))
