    ALL_TAC] THEN
  SUBGOAL_THEN `enat (\u. u IN D /\ (E:A->A->bool) u w) E 2 two`
  ASSUME_TAC THENL
   [MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`2`;`two:A`]
      ENAT_SUBMODEL) THEN
    ANTS_TAC THENL [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `(vsW:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [FIRST_ASSUM(ACCEPT_TAC o CONJUNCT1 o REWRITE_RULE[efuns] o check (fun th ->
