   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal (Wm:A->bool) (E:A->A->bool) a` ASSUME_TAC THENL
   [EXPAND_TAC "Wm" THEN
