   [EXPAND_TAC "Wm" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`Wm:A->bool`; `E:A->A->bool`; `a:A`; `yL:A`]
         ELSTAGE_CHAR_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@wL. h3 wlch h4" THEN
  SUBGOAL_THEN `(wL:A) IN D /\ (E:A->A->bool) wL w` STRIP_ASSUME_TAC THENL
