        ASM_REWRITE_TAC[] THEN
        USE_THEN "tr" (fun th -> MATCH_MP_TAC(SPECL [`u:A`; `wL:A`] th)) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?b zL. (b:A) IN Wm /\ (zL:A) IN Wm /\ (E:A->A->bool) b a /\
               elstage (Wm:A->bool) E b zL /\ E u zL`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "wlch" (MP_TAC o SPEC `u:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC `(E:A->A->bool) u wL` THEN REWRITE_TAC[th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `(b:A) IN D /\ (E:A->A->bool) b w` STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `(b:A) IN Wm` THEN EXPAND_TAC "Wm" THEN
        REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      SUBGOAL_THEN `(zL:A) IN D /\ (E:A->A->bool) zL w` STRIP_ASSUME_TAC THENL
       [UNDISCH_TAC `(zL:A) IN Wm` THEN EXPAND_TAC "Wm" THEN
        REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?zD. (zD:A) IN D /\ elstage D (E:A->A->bool) b zD`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `(zL:A) = zD` SUBST_ALL_TAC THENL
       [USE_THEN "ih"
        (fun th -> MATCH_MP_TAC(SPECL [`b:A`; `zD:A`; `zL:A`] th)) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "wdch" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `zD:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    if concl th = `(wD:A) = wL` then SUBST_ALL_TAC th
    else failwith "notit") THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
    check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
  ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `!z. z IN D ==> ((E:A->A->bool) z yD <=> edefmem D E wL z)`
  (LABEL_TAC "ydch") THENL [ASM_MESON_TAC[edef]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!z. z IN Wm ==> ((E:A->A->bool) z yL <=> edefmem (Wm:A->bool) E wL z)`
  (LABEL_TAC "ylch") THENL [ASM_MESON_TAC[edef]; ALL_TAC] THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
     [USE_THEN "tr" (fun th -> MATCH_MP_TAC(SPECL [`z:A`; `yL:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) IN Wm` ASSUME_TAC THENL
     [EXPAND_TAC "Wm" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) wL z` ASSUME_TAC THENL
     [USE_THEN "ylch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z yL`))) THEN
      USE_THEN "defabs" (MP_TAC o SPECL [`wL:A`; `z:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "ydch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z w` ASSUME_TAC THENL
     [USE_THEN "tr" (fun th -> MATCH_MP_TAC(SPECL [`z:A`; `yD:A`] th)) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(z:A) IN Wm` ASSUME_TAC THENL
     [EXPAND_TAC "Wm" THEN REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) wL z` ASSUME_TAC THENL
     [USE_THEN "ydch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z yD`))) THEN
      SIMP_TAC[];
      ALL_TAC] THEN
    USE_THEN "ylch" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "defabs" (MP_TAC o SPECL [`wL:A`; `z:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let MODEL_MPRIME_F = prove
 (`!D (E:A->A->bool) Som a za la ga ya Mp.
      model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ ya IN D /\
      elstage D E a ya /\
      (!w. w IN D /\ E w Som ==> E w ya) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p))
      ==> (model (\z. z IN D /\ E z Mp) E zfw_ax <=>
           model (\z. z IN D /\ E z Som) E zfw_ax)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                `la:A`; `ga:A`; `ya:A`; `Mp:A`] ISO_HOLDS_COLL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "iso") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                `la:A`; `ga:A`; `ya:A`; `Mp:A`] COLL_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "tot") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`;
                `la:A`; `ga:A`; `ya:A`; `Mp:A`] COLL_ONTO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "onto") THEN
  REWRITE_TAC[model; satisfies] THEN EQ_TAC THEN STRIP_TAC THENL
   [(* Mp ==> Som *)
    CONJ_TAC THENL
     [(* nonempty Som *)
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        concl th = `~((\z. z IN D /\ (E:A->A->bool) z Mp) = {})`)) THEN
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      DISCH_THEN(X_CHOOSE_THEN `i0:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "onto" (MP_TAC o SPEC `i0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `x0:A` STRIP_ASSUME_TAC) THEN
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `x0:A` THEN ASM_REWRITE_TAC[];
      (* satisfies Som *)
      MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN
      REWRITE_TAC[valuation; IN_ELIM_THM] THEN STRIP_TAC THEN
      ABBREV_TAC
       `vp = \k. @i. i IN D /\ E i Mp /\
                     eapply D (E:A->A->bool) ga ((v:num->A) k) i` THEN
      SUBGOAL_THEN
       `!k. (vp:num->A) k IN D /\ E (vp k) Mp /\ eapply D E ga (v k) (vp k)`
       ASSUME_TAC THENL
       [GEN_TAC THEN
        SUBGOAL_THEN
         `?i. i IN D /\ E i Mp /\ eapply D (E:A->A->bool) ga ((v:num->A) k) i`
         ASSUME_TAC THENL
         [USE_THEN "tot" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        EXPAND_TAC "vp" THEN
        FIRST_X_ASSUM(fun th -> BETA_TAC THEN ACCEPT_TAC(SELECT_RULE th));
        ALL_TAC] THEN
      USE_THEN "iso" (MP_TAC o SPECL [`p:form`; `v:num->A`; `vp:num->A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun t -> t = `Mp:A`)) (concl th))) THEN
      ASM_REWRITE_TAC[valuation; IN_ELIM_THM]];
    (* Som ==> Mp *)
    CONJ_TAC THENL
     [(* nonempty Mp *)
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        concl th = `~((\z. z IN D /\ (E:A->A->bool) z Som) = {})`)) THEN
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      DISCH_THEN(X_CHOOSE_THEN `x0:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "tot" (MP_TAC o SPEC `x0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `i0:A` STRIP_ASSUME_TAC) THEN
      REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `i0:A` THEN ASM_REWRITE_TAC[];
      (* satisfies Mp *)
      MAP_EVERY X_GEN_TAC [`v':num->A`; `p:form`] THEN
      REWRITE_TAC[valuation; IN_ELIM_THM] THEN STRIP_TAC THEN
      ABBREV_TAC
       `vm = \k. @x. x IN D /\ E x Som /\
                     eapply D (E:A->A->bool) ga x ((v':num->A) k)` THEN
      SUBGOAL_THEN
       `!k. (vm:num->A) k IN D /\ E (vm k) Som /\ eapply D E ga (vm k) (v' k)`
       ASSUME_TAC THENL
       [GEN_TAC THEN
        SUBGOAL_THEN
         `?x. x IN D /\ E x Som /\
          eapply D (E:A->A->bool) ga x ((v':num->A) k)`
         ASSUME_TAC THENL
         [USE_THEN "onto" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        EXPAND_TAC "vm" THEN
        FIRST_X_ASSUM(fun th -> BETA_TAC THEN ACCEPT_TAC(SELECT_RULE th));
        ALL_TAC] THEN
      USE_THEN "iso" (MP_TAC o SPECL [`p:form`; `vm:num->A`; `v':num->A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
      FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
        is_forall(concl th) &&
        can (find_term (fun t -> t = `Som:A`)) (concl th))) THEN
      ASM_REWRITE_TAC[valuation; IN_ELIM_THM]]]);;

let PAIR_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax
        ==> !a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                    ==> E p w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`;
                `a:A`; `b:A`] EPAIR_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `p':A`) THEN
  SUBGOAL_THEN `(p':A) IN D /\ (E:A->A->bool) p' w` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`;
                  `a:A`; `b:A`; `p':A`] EPAIR_IN) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  SUBGOAL_THEN `epair D (E:A->A->bool) a b p'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `a:A`; `b:A`; `p':A`]
      EPAIR_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `p:A = p'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `b:A`; `p:A`; `p':A`]
    EPAIR_UNIQUE) THEN ASM_REWRITE_TAC[]);;

let UPDATE_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax
        ==> !s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                           u0 IN D /\ E u0 w /\ s0' IN D /\
                           eupdate D E s0 a0 u0 s0'
                           ==> E s0' w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
            eopair D (E:A->A->bool) c d p ==> E p w`
   (LABEL_TAC "eopc") THENL
   [MATCH_MP_TAC EOPAIR_CLOSED_SUBMODEL THEN
    MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`;
                `s0:A`; `a0:A`; `u0:A`] EUPDATE_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `s2:A`) THEN
  SUBGOAL_THEN `(s2:A) IN D /\ (E:A->A->bool) s2 w` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`;
                  `s0:A`; `a0:A`; `u0:A`; `s2:A`] EUPDATE_IN) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  SUBGOAL_THEN `eupdate D (E:A->A->bool) s0 a0 u0 s2` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `s0:A`; `a0:A`;
                  `u0:A`; `s2:A`] EUPDATE_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `s0':A = s2` (fun th -> ASM_REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `s0:A`; `a0:A`; `u0:A`;
                `s0':A`; `s2:A`] EUPDATE_UNIQUE) THEN ASM_REWRITE_TAC[]);;

let NAT_ABSOLUTE_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w n x.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\ enat D E n x
        ==> E x w /\ enat (\u. u IN D /\ E u w) E n x`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\
            epair D (E:A->A->bool) a b p ==> E p w`
   (LABEL_TAC "epc") THENL
   [MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`; `n:num`]
    ENAT_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `x':A`) THEN
  SUBGOAL_THEN `(x':A) IN D /\ (E:A->A->bool) x' w` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`;
                  `n:num`; `x':A`] ENAT_IN) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  SUBGOAL_THEN `enat D (E:A->A->bool) n x'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `n:num`; `x':A`]
      ENAT_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `x:A = x'` SUBST_ALL_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:num`; `x:A`; `x':A`]
      ENAT_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let EINDUCTIVE_ABSOLUTE_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w x.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\ x IN D /\ E x w
        ==> (einductive (\u. u IN D /\ E u w) E x <=> einductive D E x)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\
            epair D (E:A->A->bool) a b p ==> E p w`
   (LABEL_TAC "epc") THENL
   [MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!z:A. z IN D /\ (E:A->A->bool) z x ==> E z w`
   (LABEL_TAC "tr") THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `etransitive D (E:A->A->bool) w` THEN
    REWRITE_TAC[etransitive] THEN
    DISCH_THEN(MP_TAC o SPEC `x:A`) THEN ASM_REWRITE_TAC[esubset] THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[einductive; IN_ELIM_THM] THEN ASM_REWRITE_TAC[] THEN
  BINOP_TAC THENL
   [(* empty clause *)
    EQ_TAC THEN DISCH_THEN(X_CHOOSE_THEN `e:A` STRIP_ASSUME_TAC) THEN
    EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THENL
     [SUBGOAL_THEN `(e:A) IN D /\ (E:A->A->bool) e w` STRIP_ASSUME_TAC THENL
       [FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[eempty; IN_ELIM_THM] o
          check (fun th -> is_comb(concl th) &&
            (try fst(dest_const(fst(strip_comb(concl th)))) = "eempty"
             with Failure _ -> false))) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `e:A`]
             EEMPTY_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      FIRST_ASSUM(ASSUME_TAC o CONJUNCT1 o REWRITE_RULE[eempty] o
        check (fun th -> is_comb(concl th) &&
          (try fst(dest_const(fst(strip_comb(concl th)))) = "eempty"
           with Failure _ -> false))) THEN
      SUBGOAL_THEN `(e:A) IN D /\ (E:A->A->bool) e w` STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "tr" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `e:A`]
             EEMPTY_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]];
    (* successor clause *)
    REWRITE_TAC[IN_ELIM_THM] THEN EQ_TAC THEN DISCH_THEN(LABEL_TAC "ind") THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THENL
     [SUBGOAL_THEN `(u:A) IN D /\ (E:A->A->bool) u w` STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "tr" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      USE_THEN "ind" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[IN_ELIM_THM] o
                  MATCH_MP ESUC_IN o
                  check (fun th -> is_comb(concl th) &&
          (try fst(dest_const(fst(strip_comb(concl th)))) = "esuc"
           with Failure _ -> false))) THEN
      SUBGOAL_THEN `(s:A) IN D /\ (E:A->A->bool) s w` STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "tr" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `u:A`; `s:A`]
        ESUC_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(u:A) IN D /\ (E:A->A->bool) u w` STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      USE_THEN "ind" (MP_TAC o SPEC `u:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `s:A` STRIP_ASSUME_TAC) THEN
      FIRST_ASSUM(STRIP_ASSUME_TAC o REWRITE_RULE[IN_ELIM_THM] o
                  MATCH_MP ESUC_IN o
                  check (fun th -> is_comb(concl th) &&
          (try fst(dest_const(fst(strip_comb(concl th)))) = "esuc"
           with Failure _ -> false))) THEN
      SUBGOAL_THEN `(s:A) IN D /\ (E:A->A->bool) s w` STRIP_ASSUME_TAC THENL
       [ASM_REWRITE_TAC[] THEN USE_THEN "tr" MATCH_MP_TAC THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `s:A` THEN ASM_REWRITE_TAC[IN_ELIM_THM] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `u:A`; `s:A`]
        ESUC_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ONCE_REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]]);;

let OM_IN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\ eomega D E om
        ==> E om w /\ eomega (\u. u IN D /\ E u w) E om`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`]
    EOMEGA_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `om':A`) THEN
  SUBGOAL_THEN `(om':A) IN D /\ (E:A->A->bool) om' w` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`; `om':A`]
           EOMEGA_IN) THEN ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  (* om' is a D-ordinal *)
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om':A`]
      EORDINAL_SUBMODEL) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    MATCH_MP_TAC EOMEGA_ORDINAL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [MATCH_MP_TAC EOMEGA_ORDINAL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* einductive D om' from einductive W om' *)
  SUBGOAL_THEN `einductive D (E:A->A->bool) om'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om':A`]
      EINDUCTIVE_ABSOLUTE_SUBMODEL_F) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    UNDISCH_TAC `eomega (\u. u IN D /\ (E:A->A->bool) u w) E om'` THEN
    REWRITE_TAC[eomega] THEN STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  (* om subset om' *)
  SUBGOAL_THEN `esubset D (E:A->A->bool) om om'` ASSUME_TAC THENL
   [UNDISCH_TAC `eomega D (E:A->A->bool) om` THEN REWRITE_TAC[eomega] THEN
    STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  (* E om w *)
  SUBGOAL_THEN `(E:A->A->bool) (om:A) w` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `om':A`]
      EORDINAL_TRICHOTOMY) THEN ASM_REWRITE_TAC[] THEN STRIP_TAC THENL
     [UNDISCH_TAC `etransitive D (E:A->A->bool) w` THEN
      REWRITE_TAC[etransitive] THEN
      DISCH_THEN(MP_TAC o SPEC `om':A`) THEN ASM_REWRITE_TAC[esubset] THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ASM_REWRITE_TAC[];
      SUBGOAL_THEN `(E:A->A->bool) (om':A) om'` MP_TAC THENL
       [UNDISCH_TAC `esubset D (E:A->A->bool) om om'` THEN
        REWRITE_TAC[esubset] THEN
        DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[E_IRREFL]]; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  (* eomega W om *)
  REWRITE_TAC[eomega] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`]
      EINDUCTIVE_ABSOLUTE_SUBMODEL_F) THEN ASM_REWRITE_TAC[] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `eomega D (E:A->A->bool) om` THEN REWRITE_TAC[eomega] THEN
    STRIP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `i:A` THEN DISCH_TAC THEN
    SUBGOAL_THEN `(i:A) IN D /\ (E:A->A->bool) i w` STRIP_ASSUME_TAC THENL
     [UNDISCH_TAC `einductive (\u. u IN D /\ (E:A->A->bool) u w) E i` THEN
      REWRITE_TAC[einductive; IN_ELIM_THM] THEN STRIP_TAC THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `einductive D (E:A->A->bool) i` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `i:A`]
        EINDUCTIVE_ABSOLUTE_SUBMODEL_F) THEN ASM_REWRITE_TAC[] THEN
      DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) om i` MP_TAC THENL
     [UNDISCH_TAC `eomega D (E:A->A->bool) om` THEN REWRITE_TAC[eomega] THEN
      STRIP_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    REWRITE_TAC[esubset; IN_ELIM_THM] THEN MESON_TAC[]]);;

let EMPTY_IN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w e.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\ eempty D E e
        ==> E e w`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`]
    EEMPTY_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `e':A`) THEN
  SUBGOAL_THEN `(e':A) IN D /\ (E:A->A->bool) e' w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o REWRITE_RULE[eempty; IN_ELIM_THM] o
      check (fun th -> is_comb(concl th) &&
        (try fst(dest_const(fst(strip_comb(concl th)))) = "eempty"
         with Failure _ -> false))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) e'` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `e':A`]
      EEMPTY_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
  SUBGOAL_THEN `e:A = e'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`; `e':A`] EEMPTY_UNIQUE) THEN
  ASM_REWRITE_TAC[]);;

let RAN_BASE_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w e g r.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eempty D E e /\ g IN D /\
        eisfun D E g /\ edomain D E g e /\ r IN D /\
        (!q. q IN D ==> (E q r <=> einran D E q g))
        ==> E r w`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eempty D (E:A->A->bool) r` ASSUME_TAC THENL
   [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `q:A` THEN REPEAT STRIP_TAC THEN
    SUBGOAL_THEN `einran D (E:A->A->bool) q g` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eindom D (E:A->A->bool) g oo` ASSUME_TAC THENL
     [ASM_MESON_TAC[eindom; eapply]; ALL_TAC] THEN
    ASM_MESON_TAC[edomain; eempty];
    ALL_TAC] THEN
  MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `r:A`]
    EMPTY_IN_SUBMODEL_F) THEN
  ASM_REWRITE_TAC[]);;

let RAN_STEP_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om m sm g r.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\ eomega D E om /\
        m IN D /\ E m om /\ sm IN D /\ esuc D E m sm /\
        (!g' r'. g' IN D /\ eisfun D E g' /\ edomain D E g' m /\
                 (!u w. u IN D /\ w IN D /\ eapply D E g' u w
                        ==> E w wm) /\
                 r' IN D /\
                 (!w. w IN D ==> (E w r' <=> einran D E w g'))
                 ==> E r' wm) /\
        g IN D /\ eisfun D E g /\ edomain D E g sm /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w
               ==> E w wm) /\
        r IN D /\
        (!w. w IN D ==> (E w r <=> einran D E w g))
        ==> E r wm`,
  REPEAT GEN_TAC THEN
  INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 h8 h9 ih h10 h11 dom val h12 rch" THEN
  SUBGOAL_THEN
   `!a b p. a IN D /\ E a wm /\ b IN D /\ E b wm /\
            epair D (E:A->A->bool) a b p ==> E p wm`
   (LABEL_TAC "epc") THENL
   [MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?gr:A. erestrict D (E:A->A->bool) g m gr`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(gr:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erestrict]; ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) gr` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_ISFUN]; ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) gr m` ASSUME_TAC THENL
   [ASM_MESON_TAC[ERESTRICT_DOMAIN_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?r':A. r' IN D /\
           !w. w IN D ==> ((E:A->A->bool) w r' <=> einran D E w gr)`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EINRAN_SET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) r' wm` ASSUME_TAC THENL
   [USE_THEN "ih" (MP_TAC o SPECL [`gr:A`; `r':A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`u:A`; `w:A`] THEN STRIP_TAC THEN
      USE_THEN "val" (MP_TAC o SPECL [`u:A`; `w:A`]) THEN
      ANTS_TAC THENL
       [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[ERESTRICT_APPLY];
        DISCH_THEN ACCEPT_TAC];
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `eindom D (E:A->A->bool) g m` MP_TAC THENL
   [ASM_MESON_TAC[edomain; ESUC_MEMBER]; ALL_TAC] THEN
  REWRITE_TAC[eindom] THEN
  DISCH_THEN(X_CHOOSE_THEN `w0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) w0 wm` ASSUME_TAC THENL
   [USE_THEN "val" (MP_TAC o SPECL [`m:A`; `w0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `?sg:A. epair D (E:A->A->bool) w0 w0 sg`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPAIR_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sg wm` ASSUME_TAC THENL
   [USE_THEN "epc" (fun th -> MATCH_MP_TAC(SPECL
      [`w0:A`; `w0:A`; `sg:A`] th)) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?rb:A. ebunion D (E:A->A->bool) r' sg rb`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(rb:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EBUNION_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rb wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r':A`; `sg:A`;
                  `rb:A`] EBUNION_CLOSED_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `r:A = rb` SUBST1_TAC THENL
   [ALL_TAC; ASM_REWRITE_TAC[]] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_EXTENSIONALITY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN
  USE_THEN "rch" (MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `r':A`; `sg:A`; `rb:A`]
        EBUNION_ALT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th ->
    FIRST_X_ASSUM(MP_TAC o CONJUNCT2 o GEN_REWRITE_RULE I [th] o
      check (fun t -> can (find_term (fun tt -> is_const tt &&
        fst(dest_const tt) = "ebunion")) (concl t)))) THEN
  DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  SUBGOAL_THEN `(E:A->A->bool) w sg <=> w:A = w0`
  (fun th -> REWRITE_TAC[th]) THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!ww. ww IN D ==> ((E:A->A->bool) ww r' <=> einran D E ww gr)`
  (LABEL_TAC "rpch") THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  EQ_TAC THENL
   [REWRITE_TAC[einran] THEN
    DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `eapply D (E:A->A->bool) g oo w` ASSUME_TAC THENL
     [ASM_MESON_TAC[eapply]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) oo sm` ASSUME_TAC THENL
     [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) oo m \/ oo:A = m` MP_TAC THENL
     [ASM_MESON_TAC[ESUC_E]; ALL_TAC] THEN
    STRIP_TAC THENL
     [DISJ1_TAC THEN
      USE_THEN "rpch" (MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[einran] THEN
      MAP_EVERY EXISTS_TAC [`pr:A`; `oo:A`] THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY EXISTS_TAC [`oo:A`; `w:A`] THEN ASM_REWRITE_TAC[];
      DISJ2_TAC THEN FIRST_X_ASSUM SUBST_ALL_TAC THEN
      MATCH_MP_TAC EAPPLY_UNIQUE THEN
      MAP_EVERY EXISTS_TAC
        [`D:A->bool`; `E:A->A->bool`; `g:A`; `m:A`] THEN
      ASM_REWRITE_TAC[]];
    STRIP_TAC THENL
     [SUBGOAL_THEN `einran D (E:A->A->bool) w gr` MP_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`pr:A`; `oo:A`] THEN
      ASM_REWRITE_TAC[] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `pr:A` o CONJUNCT2 o
        GEN_REWRITE_RULE I [erestrict]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o check
          (fun t -> concl t = `(E:A->A->bool) pr gr`))) THEN
      SIMP_TAC[];
      FIRST_X_ASSUM SUBST_ALL_TAC THEN
      UNDISCH_TAC `eapply D (E:A->A->bool) g m w0` THEN
      REWRITE_TAC[eapply] THEN
      DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
      REWRITE_TAC[einran] THEN
      MAP_EVERY EXISTS_TAC [`z:A`; `m:A`] THEN
      ASM_MESON_TAC[EOPAIR_IN]]]);;

let NAT_RAN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om n g r.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ n IN D /\ E n om /\
        g IN D /\ eisfun D E g /\ edomain D E g n /\
        (!u w. u IN D /\ w IN D /\ eapply D E g u w
               ==> E w wm) /\
        r IN D /\
        (!w. w IN D ==> (E w r <=> einran D E w g))
        ==> E r wm`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((9 |-> (wm:A)) v0)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `!! 1 (!! 2 ((fun_form 1 && (domain_form 1 0 &&
       ((!! 3 (!! 4 (apply_form 1 3 4 --> (4 %% 9)))) &&
        (!! 3 ((3 %% 2) <-> inran_form 3 1))))) -->
      (2 %% 9)))`;
    `0`; `(9 |-> (wm:A)) v0`] EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (e:A)) ((9 |-> (wm:A)) v0))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (e:A)) ((9 |-> (wm:A)) v0)`] HOLDS_WMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`gg:A`; `rr:A`] THEN STRIP_TAC THEN
      MATCH_MP_TAC RAN_BASE_SUBMODEL_F THEN
      MAP_EVERY EXISTS_TAC [`D:A->bool`; `e:A`; `gg:A`] THEN
      ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `valuation D ((0 |-> (m:A)) ((9 |-> (wm:A)) v0))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      SUBGOAL_THEN `valuation D ((0 |-> (sm:A)) ((9 |-> (wm:A)) v0))`
      ASSUME_TAC THENL
       [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
      FIRST_X_ASSUM(MP_TAC o check (fun th ->
        can (find_term (fun t -> is_const t &&
          fst(dest_const t) = "holds")) (concl th))) THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (m:A)) ((9 |-> (wm:A)) v0)`] HOLDS_WMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
      DISCH_THEN(LABEL_TAC "ihs") THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `(0 |-> (sm:A)) ((9 |-> (wm:A)) v0)`] HOLDS_WMEMRAN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      REWRITE_TAC[VALMOD] THEN
      CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`gg:A`; `rr:A`] THEN STRIP_TAC THEN
      MATCH_MP_TAC RAN_STEP_SUBMODEL_F THEN
      MAP_EVERY EXISTS_TAC [`D:A->bool`; `om:A`; `m:A`; `sm:A`; `gg:A`] THEN
      ASM_REWRITE_TAC[] THEN
      MAP_EVERY X_GEN_TAC [`g':A`; `r':A`] THEN STRIP_TAC THEN
      USE_THEN "ihs" (MP_TAC o SPECL [`g':A`; `r':A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((0 |-> (n:A)) ((9 |-> (wm:A)) v0))`
  ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
    `(0 |-> (n:A)) ((9 |-> (wm:A)) v0)`] HOLDS_WMEMRAN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[VALMOD] THEN
  CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`g:A`; `r:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let SUBSET_RAN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om n h w d0.
     model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
     model (\u. u IN D /\ E u wm) E zfw_ax /\
     eomega D E om /\ n IN D /\ E n om /\
     h IN D /\ eisfun D E h /\ edomain D E h n /\
     (!u q. u IN D /\ q IN D /\ eapply D E h u q
            ==> E q wm) /\
     w IN D /\ d0 IN D /\ E d0 w /\
     (!q. q IN D /\ E q w ==> ?u. u IN D /\ eapply D E h u q)
     ==> E w wm`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `h:A`; `n:A`;
                `w:A`; `d0:A`] EREDIRECT_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@g'. h1 h2 h3 vch" THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                `g':A`; `w:A`] NAT_RAN_SUBMODEL_F) THEN
  ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
  ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [MAP_EVERY X_GEN_TAC [`u:A`; `q:A`] THEN STRIP_TAC THEN
    USE_THEN "vch" (fun th -> MP_TAC(SPECL [`u:A`; `q:A`] th)) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      UNDISCH_TAC `eapply D (E:A->A->bool) g' u q` THEN
      REWRITE_TAC[th]) THEN
    STRIP_TAC THEN ASM_MESON_TAC[];
    X_GEN_TAC `q:A` THEN DISCH_TAC THEN EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `?u:A. u IN D /\ eapply D (E:A->A->bool) h u q`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) u n` ASSUME_TAC THENL
       [ASM_MESON_TAC[edomain; eindom]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g' u q` MP_TAC THENL
       [USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`u:A`; `q:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        ASM_REWRITE_TAC[];
        REWRITE_TAC[eapply; einran] THEN
        DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC) THEN
        MAP_EVERY EXISTS_TAC [`z:A`; `u:A`] THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[EOPAIR_IN]];
      REWRITE_TAC[einran] THEN
      DISCH_THEN(X_CHOOSE_THEN `pr:A` (X_CHOOSE_THEN `oo:A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) g' oo q` ASSUME_TAC THENL
       [REWRITE_TAC[eapply] THEN EXISTS_TAC `pr:A` THEN
        ASM_REWRITE_TAC[];
        USE_THEN "vch" (fun th ->
          MP_TAC(SPECL [`oo:A`; `q:A`] th)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th ->
          UNDISCH_TAC `eapply D (E:A->A->bool) g' oo q` THEN
          REWRITE_TAC[th]) THEN
        SIMP_TAC[]]]]);;

let SUBSETS_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om ym M hh.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\ eomega D E om /\
        ym IN D /\ E ym wm /\ M IN D /\ E M om /\
        hh IN D /\ eisfun D E hh /\ edomain D E hh M /\
        (!k w. k IN D /\ w IN D ==> eapply D E hh k w ==> E w ym) /\
        (!w. w IN D ==> E w ym ==> ?k. k IN D /\ eapply D E hh k w)
        ==> !w. w IN D ==> esubset D E w ym ==> E w wm`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
  ASM_CASES_TAC `?d0:A. d0 IN D /\ (E:A->A->bool) d0 w` THENL
   [FIRST_X_ASSUM(X_CHOOSE_THEN `d0:A` STRIP_ASSUME_TAC) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `M:A`;
      `hh:A`; `w:A`; `d0:A`] SUBSET_RAN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [MAP_EVERY X_GEN_TAC [`u:A`; `q:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[]; ALL_TAC] THEN
      ASM_MESON_TAC[];
      X_GEN_TAC `q:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) q ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      ASM_MESON_TAC[]];
    SUBGOAL_THEN `eempty D (E:A->A->bool) w` ASSUME_TAC THENL
     [REWRITE_TAC[eempty] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[];
      ALL_TAC] THEN
    MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `w:A`]
      EMPTY_IN_SUBMODEL_F) THEN
    ASM_REWRITE_TAC[]]);;

let STAGE_POW_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm ym ysm.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        ym IN D /\ E ym wm /\ ysm IN D /\
        (!q. q IN D ==> (E q ysm <=> esubset D E q ym)) /\
        (!q. q IN D ==> esubset D E q ym ==> E q wm)
        ==> E ysm wm`,
  REPEAT GEN_TAC THEN INTRO_TAC "h1 h2 h3 h4 h5 h6 h7 ych sbl" THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u wm)`; `E:A->A->bool`;
                `ym:A`] EPOW_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `pp:A`) THEN
  SUBGOAL_THEN `(pp:A) IN D /\ (E:A->A->bool) pp wm` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u wm)`; `E:A->A->bool`;
                  `ym:A`; `pp:A`] EPOW_IN) THEN
    ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[epow; IN_ELIM_THM] o
    check (fun th -> is_comb(concl th) &&
      (try fst(dest_const(fst(strip_comb(concl th)))) = "epow"
       with Failure _ -> false))) THEN
  DISCH_THEN(LABEL_TAC "ppc") THEN
  SUBGOAL_THEN `(ysm:A) = pp` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
    check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  USE_THEN "ych" (MP_TAC o SPEC `z:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z wm` ASSUME_TAC THENL
     [USE_THEN "sbl" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN MATCH_MP_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    USE_THEN "ppc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `z:A`; `ym:A`]
      ESUBSET_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC;
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) z wm` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `pp:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "ppc" (MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun t -> concl t = `(E:A->A->bool) z pp`))) THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `z:A`; `ym:A`]
      ESUBSET_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN SIMP_TAC[]]);;

let EHFSTAGE_IN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om n y.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y
        ==> E y wm`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `?v0:num->A. valuation D v0` STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D ((10 |-> (wm:A)) ((8 |-> (om:A)) v0))`
    ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!nn. (nn:A) IN D
     ==> (holds D (E:A->A->bool) ((0 |-> nn) ((10 |-> wm) ((8 |-> om) v0)))
           (?? 4 (hfstage_form 0 4 && ((4 %% 10) &&
              ?? 5 ((5 %% 8) &&
                ?? 6 (fun_form 6 && (domain_form 6 5 &&
                  ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
                   (!! 9 ((9 %% 4) -->
                          ?? 7 (apply_form 6 7 9)))))))))) <=>
          (?yy. yy IN D /\ ehfstage D E nn yy /\ E yy wm /\
                (?M. M IN D /\ E M om /\
                     (?hh. hh IN D /\ eisfun D E hh /\
                           edomain D E hh M /\
                           (!k. k IN D
                                ==> (!w. w IN D
                                         ==> eapply D E hh k w
                                             ==> E w yy)) /\
                           (!w. w IN D
                                ==> E w yy
                                    ==> (?k. k IN D /\
                                             eapply D E hh k w))))))`
  (LABEL_TAC "pch") THENL
   [X_GEN_TAC `nn:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `(0 |-> (nn:A)) ((10 |-> (wm:A)) ((8 |-> (om:A)) v0))`]
            HOLDS_WHFCON_SLOTS) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[VALUATION_VALMOD];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN
    REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
    `?? 4 (hfstage_form 0 4 && ((4 %% 10) &&
       ?? 5 ((5 %% 8) &&
         ?? 6 (fun_form 6 && (domain_form 6 5 &&
           ((!! 7 (!! 9 (apply_form 6 7 9 --> (9 %% 4)))) &&
            (!! 9 ((9 %% 4) -->
                   ?? 7 (apply_form 6 7 9)))))))))`;
    `0`; `(10 |-> (wm:A)) ((8 |-> (om:A)) v0)`]
    EOMEGA_INDUCT_HOLDS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `e:A` THEN STRIP_TAC THEN
      USE_THEN "pch" (fun th -> MP_TAC(SPEC `e:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) e` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_EEMPTY]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) e om` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOMEGA_EMPTY]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?y0:A. y0 IN D /\ ehfstage D (E:A->A->bool) e y0`
      STRIP_ASSUME_TAC THENL
       [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
      SUBGOAL_THEN `eempty D (E:A->A->bool) y0` ASSUME_TAC THENL
       [ASM_MESON_TAC[EHFSTAGE_EMPTY]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `e:A`]
        EEMPTYFUN) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      STRIP_TAC THEN
      EXISTS_TAC `y0:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MATCH_MP_TAC EMPTY_IN_SUBMODEL_F THEN
        EXISTS_TAC `D:A->bool` THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN
      EXISTS_TAC `e:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
       [MAP_EVERY X_GEN_TAC [`k:A`] THEN DISCH_TAC THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        ASM_MESON_TAC[];
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
        ASM_MESON_TAC[eempty]];
      MAP_EVERY X_GEN_TAC [`m:A`; `sm:A`] THEN STRIP_TAC THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `sm:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM(MP_TAC o check (fun th ->
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "holds")) (concl th))) THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `m:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  INTRO_TAC "@ym. h1 h2 h3 @M. h4 h5 @hh. h6 h7 h8 iha ihb" THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) m` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sm` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_ESUC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ysm:A. ysm IN D /\ ehfstage D (E:A->A->bool) sm ysm`
  STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> ((E:A->A->bool) w ysm <=> esubset D E w ym)`
  (LABEL_TAC "sch") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `m:A`; `sm:A`;
      `ym:A`; `ysm:A`] EHFSTAGE_SUC_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. (w:A) IN D ==> esubset D (E:A->A->bool) w ym
        ==> E w wm`
  (LABEL_TAC "sbl") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `ym:A`;
      `M:A`; `hh:A`] SUBSETS_SUBMODEL_F) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN TRY(FIRST_ASSUM ACCEPT_TAC) THEN
      MAP_EVERY X_GEN_TAC [`k:A`; `w:A`] THEN STRIP_TAC THEN
      DISCH_TAC THEN
      USE_THEN "iha" (fun th -> MP_TAC(SPEC `k:A` th)) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `w:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) hh k w`))) THEN
      DISCH_THEN ACCEPT_TAC;
      DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ysm wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `ym:A`; `ysm:A`]
      STAGE_POW_SUBMODEL_F) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hh:A`; `M:A`]
    POWENUM_ALL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@M2 f. h9 h10 h11 h12 h13 pea peb" THEN
  EXISTS_TAC `ysm:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `M2:A` THEN ASM_REWRITE_TAC[] THEN
  EXISTS_TAC `f:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
   [X_GEN_TAC `k:A` THEN DISCH_TAC THEN
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w ym` ASSUME_TAC THENL
     [REWRITE_TAC[esubset] THEN X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "pea" (fun th -> MP_TAC(SPECL [`k:A`; `w:A`] th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) f k w`))) THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `u:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "iha" (fun th -> MP_TAC(SPEC `u:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(MP th (ASSUME
        `eapply D (E:A->A->bool) hh u z`))) THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    USE_THEN "sch" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    FIRST_ASSUM ACCEPT_TAC;
    X_GEN_TAC `w:A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `esubset D (E:A->A->bool) w ym` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "peb" (fun th -> MP_TAC(SPEC `w:A` th)) THEN
    ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    ANTS_TAC THENL
     [X_GEN_TAC `z:A` THEN DISCH_TAC THEN DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z ym` ASSUME_TAC THENL
       [ASM_MESON_TAC[esubset]; ALL_TAC] THEN
      USE_THEN "ihb" (fun th -> MP_TAC(SPEC `z:A` th)) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_THEN `k:A` STRIP_ASSUME_TAC) THEN
      EXISTS_TAC `k:A` THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[edomain; eindom];
      DISCH_THEN ACCEPT_TAC]]];
    ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `n:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  USE_THEN "pch" (fun th -> MP_TAC(SPEC `n:A` th)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  DISCH_THEN(X_CHOOSE_THEN `yy:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(yy:A) = y` SUBST_ALL_TAC THENL
   [ASM_MESON_TAC[EHFSTAGE_UNIQUE]; ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

let EHFSTAGE_SUBSET_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om n y u.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y /\ u IN D /\ esubset D E u y
        ==> E u wm`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `?sn. esuc D (E:A->A->bool) n sn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?ysn. (ysn:A) IN D /\ ehfstage D (E:A->A->bool) sn ysn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) u ysn` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `sn:A`;
                  `y:A`; `ysn:A`] EHFSTAGE_SUC_CHAR) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) ysn wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `sn:A`;
                  `ysn:A`] EHFSTAGE_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  UNDISCH_TAC `etransitive D (E:A->A->bool) wm` THEN
  REWRITE_TAC[etransitive] THEN DISCH_THEN(MP_TAC o SPEC `ysn:A`) THEN
  ASM_REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN
  ASM_REWRITE_TAC[]);;

let EHFSTAGE_ABSOLUTE_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om n y.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ ehfstage D E n y
        ==> ehfstage (\u. u IN D /\ E u wm) E n y`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b p. a IN D /\ E a wm /\ b IN D /\ E b wm /\
            epair D (E:A->A->bool) a b p ==> E p wm`
   (LABEL_TAC "epc") THENL
   [MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) om wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`]
      OM_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT1 th))];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n wm` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) y wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                  `y:A`] EHFSTAGE_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `valuation D (\k:num. (om:A))` ASSUME_TAC THENL
   [REWRITE_TAC[valuation] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `valuation (\u. u IN D /\ (E:A->A->bool) u wm) (\k:num. (om:A))`
  ASSUME_TAC THENL
   [REWRITE_TAC[valuation; IN_ELIM_THM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?sn. esuc D (E:A->A->bool) n sn`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ESUC_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(sn:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_SUC]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) sn wm` ASSUME_TAC THENL
   [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n sn` ASSUME_TAC THENL
   [ASM_MESON_TAC[ESUC_MEMBER]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`]
    VSTEP_QFUN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "qf") THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`]
    VSTEP_QTOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "qt") THEN
  SUBGOAL_THEN
   `?rg. erecres D (E:A->A->bool) vstep_form (\k:num. (om:A)) sn rg`
  STRIP_ASSUME_TAC THENL
   [MATCH_MP_TAC ERECRES_EXISTS THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `(rg:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!w. w IN D
        ==> ((E:A->A->bool) w rg <=>
             ?b y'. b IN D /\ y' IN D /\ E b sn /\
                    erec D E vstep_form (\k:num. (om:A)) b y' /\
                    eopair D E b y' w)`
  (LABEL_TAC "rgch") THENL [ASM_MESON_TAC[erecres]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w. b IN D /\ w IN D
          ==> (eapply D (E:A->A->bool) rg b w <=>
               E b sn /\ erec D E vstep_form (\k:num. (om:A)) b w)`
  (LABEL_TAC "rap") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `z:A` STRIP_ASSUME_TAC o
        GEN_REWRITE_RULE I [eapply]) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z rg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      SUBGOAL_THEN `(b':A) = b /\ (y':A) = w`
      (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
       [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`]
        EOPAIR_EXISTS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `z:A`) THEN
      SUBGOAL_THEN `(z:A) IN D` ASSUME_TAC THENL
       [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
      REWRITE_TAC[eapply] THEN EXISTS_TAC `z:A` THEN
      ASM_REWRITE_TAC[] THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`b:A`; `w:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `eisfun D (E:A->A->bool) rg` ASSUME_TAC THENL
   [REWRITE_TAC[eisfun] THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `z:A` THEN STRIP_TAC THEN
      USE_THEN "rgch" (MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) z rg`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `b':A` (X_CHOOSE_THEN `y':A`
        STRIP_ASSUME_TAC)) THEN
      MAP_EVERY EXISTS_TAC [`b':A`; `y':A`] THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC
       [`u:A`; `w:A`; `w':A`; `z:A`; `z':A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN
       `((E:A->A->bool) u sn /\
         erec D E vstep_form (\k:num. (om:A)) u w) /\
        (E u sn /\ erec D E vstep_form (\k:num. (om:A)) u w')`
      (DESTRUCT_TAC "(_ h1) _ h2") THENL
       [CONJ_TAC THENL
         [USE_THEN "rap" (MP_TAC o SPECL [`u:A`; `w:A`]);
          USE_THEN "rap" (MP_TAC o SPECL [`u:A`; `w':A`])] THEN
        (ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
         DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
         REWRITE_TAC[eapply]) THENL
         [EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[];
          EXISTS_TAC `z':A` THEN ASM_REWRITE_TAC[]];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`;
                    `\k:num. (om:A)`; `u:A`; `w:A`; `w':A`]
        EREC_UNIQUE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]];
    ALL_TAC] THEN
  SUBGOAL_THEN `edomain D (E:A->A->bool) rg sn` ASSUME_TAC THENL
   [REWRITE_TAC[edomain] THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `b:A` THEN DISCH_TAC THEN REWRITE_TAC[eindom] THEN
    EQ_TAC THENL
     [DISCH_TAC THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_MEMBER]; ALL_TAC] THEN
      SUBGOAL_THEN
       `?w. (w:A) IN D /\
            erec D (E:A->A->bool) vstep_form (\k:num. (om:A)) b w`
      STRIP_ASSUME_TAC THENL
       [MATCH_MP_TAC EREC_EXISTS THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      EXISTS_TAC `w:A` THEN ASM_REWRITE_TAC[] THEN
      USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      DISCH_THEN(X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC) THEN
      USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th ->
        FIRST_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a ->
            concl a = `eapply D (E:A->A->bool) rg b w`))) THEN
      SIMP_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!b w. b IN D /\ w IN D /\ eapply D (E:A->A->bool) rg b w
          ==> E w wm`
  (LABEL_TAC "rgvl") THENL
   [MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN
     `(E:A->A->bool) b sn /\
      erec D E vstep_form (\k:num. (om:A)) b w`
    STRIP_ASSUME_TAC THENL
     [USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
      ALL_TAC] THEN
    SUBGOAL_THEN `ehfstage D (E:A->A->bool) b w` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b:A`; `w:A`;
                    `\k:num. (om:A)`] EHFSTAGE_EREC) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) b om` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `sn:A`;
                    `b:A`] EOMEGA_TRANS) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `b:A`;
                  `w:A`] EHFSTAGE_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) rg wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `sn:A`;
                  `rg:A`] NAT_FUN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ALL_TAC; DISCH_THEN ACCEPT_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`b:A`; `w:A`] THEN STRIP_TAC THEN
    USE_THEN "rgvl" (MP_TAC o SPECL [`b:A`; `w:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `eattempt (\u. u IN D /\ (E:A->A->bool) u wm) E vstep_form
             (\k:num. (om:A)) rg sn`
  ASSUME_TAC THENL
   [REWRITE_TAC[eattempt; IN_ELIM_THM] THEN REPEAT CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `rg:A`]
        EISFUN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `rg:A`; `sn:A`]
        EDOMAIN_SUBMODEL) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      MAP_EVERY X_GEN_TAC [`b:A`; `r':A`; `y2:A`] THEN STRIP_TAC THEN
      SUBGOAL_THEN `erestrict D (E:A->A->bool) rg b r'`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `rg:A`; `b:A`;
                      `r':A`] ERESTRICT_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) rg b y2` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `rg:A`; `b:A`;
                      `y2:A`] EAPPLY_SUBMODEL) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `(E:A->A->bool) b sn /\
        erec D E vstep_form (\k:num. (om:A)) b y2`
      STRIP_ASSUME_TAC THENL
       [USE_THEN "rap" (MP_TAC o SPECL [`b:A`; `y2:A`]) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
        ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) b` ASSUME_TAC THENL
