      SUBGOAL_THEN `!d. d IN D /\ (E:A->A->bool) d b ==> E d sn`
      (LABEL_TAC "bt") THENL
       [ASM_MESON_TAC[eordinal; etransitive; esubset]; ALL_TAC] THEN
      SUBGOAL_THEN
       `erecres D (E:A->A->bool) vstep_form (\k:num. (om:A)) b r'`
      ASSUME_TAC THENL
       [REWRITE_TAC[erecres] THEN ASM_REWRITE_TAC[] THEN
        X_GEN_TAC `w:A` THEN DISCH_TAC THEN
        FIRST_ASSUM(MP_TAC o SPEC `w:A` o CONJUNCT2 o
          GEN_REWRITE_RULE I [erestrict] o check (fun a ->
            concl a = `erestrict D (E:A->A->bool) rg b r'`)) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        USE_THEN "rgch" (MP_TAC o SPEC `w:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
        EQ_TAC THENL
         [DISCH_THEN(CONJUNCTS_THEN2
            (X_CHOOSE_THEN `b2:A` (X_CHOOSE_THEN `y3:A`
              STRIP_ASSUME_TAC))
            (X_CHOOSE_THEN `u':A` (X_CHOOSE_THEN `w2:A`
              STRIP_ASSUME_TAC))) THEN
          SUBGOAL_THEN `(u':A) = b2 /\ (w2:A) = y3`
          (CONJUNCTS_THEN SUBST_ALL_TAC) THENL
           [ASM_MESON_TAC[EOPAIR_INJ]; ALL_TAC] THEN
          MAP_EVERY EXISTS_TAC [`b2:A`; `y3:A`] THEN
          ASM_REWRITE_TAC[];
          DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `y3:A`
            STRIP_ASSUME_TAC)) THEN
          CONJ_TAC THENL
           [MAP_EVERY EXISTS_TAC [`c:A`; `y3:A`] THEN
            ASM_REWRITE_TAC[] THEN
            USE_THEN "bt" (MP_TAC o SPEC `c:A`) THEN
            ANTS_TAC THENL
             [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
            MAP_EVERY EXISTS_TAC [`c:A`; `y3:A`] THEN
            ASM_REWRITE_TAC[]]];
        ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `vstep_form`;
                    `\k:num. (om:A)`; `b:A`; `y2:A`; `r':A`]
        EREC_EQUATION) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_TAC THEN
      SUBGOAL_THEN `vstep D (E:A->A->bool) r' y2` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `\k:num. (om:A)`;
                      `r':A`; `y2:A`] HOLDS_VSTEP_FORM) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
        ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      SUBGOAL_THEN
       `vstep (\u. u IN D /\ (E:A->A->bool) u wm) E r' y2`
      ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `r':A`; `y2:A`]
          VSTEP_SUBMODEL) THEN
        ANTS_TAC THENL
         [ASM_REWRITE_TAC[] THEN
          MAP_EVERY X_GEN_TAC [`u:A`; `b2:A`; `w2:A`] THEN
          STRIP_TAC THEN
          SUBGOAL_THEN `eapply D (E:A->A->bool) rg b2 w2`
          ASSUME_TAC THENL
           [ASM_MESON_TAC[ERESTRICT_APPLY]; ALL_TAC] THEN
          SUBGOAL_THEN
           `(E:A->A->bool) b2 sn /\
            erec D E vstep_form (\k:num. (om:A)) b2 w2`
          STRIP_ASSUME_TAC THENL
           [USE_THEN "rap" (MP_TAC o SPECL [`b2:A`; `w2:A`]) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> ASM_REWRITE_TAC[GSYM th]);
            ALL_TAC] THEN
          SUBGOAL_THEN `ehfstage D (E:A->A->bool) b2 w2`
          ASSUME_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `b2:A`;
                          `w2:A`; `\k:num. (om:A)`]
              EHFSTAGE_EREC) THEN
            ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
            DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
            ASM_REWRITE_TAC[];
            ALL_TAC] THEN
          SUBGOAL_THEN `(E:A->A->bool) b2 om` ASSUME_TAC THENL
           [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`;
                          `sn:A`; `b2:A`] EOMEGA_TRANS) THEN
            ANTS_TAC THENL
             [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
            ALL_TAC] THEN
          MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `b2:A`;
                        `w2:A`; `u:A`] EHFSTAGE_SUBSET_SUBMODEL_F) THEN
          ANTS_TAC THENL
           [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
          ALL_TAC] THEN
        DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
        ALL_TAC] THEN
      MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u wm)`; `E:A->A->bool`;
                    `\k:num. (om:A)`; `r':A`; `y2:A`] HOLDS_VSTEP_FORM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[IN_ELIM_THM]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[ehfstage] THEN EXISTS_TAC `\k:num. (om:A)` THEN
  ASM_REWRITE_TAC[] THEN REWRITE_TAC[erec; IN_ELIM_THM] THEN
  MAP_EVERY EXISTS_TAC [`sn:A`; `rg:A`] THEN
  ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `sn:A`]
      EORDINAL_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `rg:A`; `n:A`;
                  `y:A`] EAPPLY_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "rap" (MP_TAC o SPECL [`n:A`; `y:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `n:A`; `y:A`;
                  `\k:num. (om:A)`] EHFSTAGE_EREC) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    ASM_REWRITE_TAC[]]);;

let EHFSTAGE_SUBMODEL_BACK_F = prove
 (`!D (E:A->A->bool) wm om n y.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ n IN D /\ E n om /\
        y IN D /\ E y wm /\ ehfstage (\u. u IN D /\ E u wm) E n y
        ==> ehfstage D E n y`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) n` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINALS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `?y0. (y0:A) IN D /\ ehfstage D (E:A->A->bool) n y0`
  STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[EHFSTAGE_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `ehfstage (\u. u IN D /\ (E:A->A->bool) u wm) E n y0`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                  `y0:A`] EHFSTAGE_ABSOLUTE_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) om wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`]
      OM_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[]; DISCH_THEN(fun th -> ACCEPT_TAC(CONJUNCT1 th))];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "trb") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) n wm` ASSUME_TAC THENL
   [USE_THEN "trb" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) y0 wm` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                  `y0:A`] EHFSTAGE_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    ALL_TAC] THEN
  SUBGOAL_THEN `(y:A) = y0` SUBST1_TAC THENL
   [MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u wm)`; `E:A->A->bool`;
                  `n:A`; `y:A`; `y0:A`] EHFSTAGE_UNIQUE_F) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[IN_ELIM_THM]; DISCH_THEN ACCEPT_TAC];
    ASM_REWRITE_TAC[]]);;

let HF_IN_SUBMODEL_F = prove
 (`!D (E:A->A->bool) wm om hf.
        model D E ZF_AX /\ wm IN D /\ etransitive D E wm /\
        model (\u. u IN D /\ E u wm) E zfw_ax /\
        eomega D E om /\ ehfset D E om hf
        ==> E hf wm /\ ehfset (\u. u IN D /\ E u wm) E om hf`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s wm /\ E t s ==> E t wm`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) om wm /\ eomega (\u. u IN D /\ E u wm) E om`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`]
      OM_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u wm)`; `E:A->A->bool`;
                `om:A`] EHFSET_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `hf':A`) THEN
  SUBGOAL_THEN `(hf':A) IN D /\ (E:A->A->bool) hf' wm` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o REWRITE_RULE[ehfset; IN_ELIM_THM] o
      check (fun th -> is_comb(concl th) &&
        (try fst(dest_const(fst(strip_comb(concl th)))) = "ehfset"
         with Failure _ -> false) &&
        not(concl th = `ehfset D (E:A->A->bool) om hf`))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[ehfset; IN_ELIM_THM] o
    check (fun th ->
      concl th = `ehfset (\u. u IN D /\ (E:A->A->bool) u wm) E om hf'`)) THEN
  DISCH_THEN(LABEL_TAC "wch") THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[ehfset] o
    check (fun th -> concl th = `ehfset D (E:A->A->bool) om hf`)) THEN
  DISCH_THEN(LABEL_TAC "dch") THEN
  SUBGOAL_THEN `hf:A = hf'` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
    check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    USE_THEN "dch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) u hf`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `yst:A`
      STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `(E:A->A->bool) yst wm` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                    `yst:A`] EHFSTAGE_IN_SUBMODEL_F) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) n wm` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `om:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) u wm` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `yst:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `yst:A`] THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                  `yst:A`] EHFSTAGE_ABSOLUTE_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) u wm` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `hf':A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) u hf'`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `n:A` (X_CHOOSE_THEN `yst:A` MP_TAC)) THEN
    REWRITE_TAC[IN_ELIM_THM] THEN STRIP_TAC THEN
    SUBGOAL_THEN `ehfstage D (E:A->A->bool) n yst` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `wm:A`; `om:A`; `n:A`;
                    `yst:A`] EHFSTAGE_SUBMODEL_BACK_F) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    USE_THEN "dch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`n:A`; `yst:A`] THEN ASM_REWRITE_TAC[]]);;

let DEFABS_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om hf two.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ ehfset D E om hf /\ enat D E 2 two
        ==> !x y. x IN D /\ E x w /\ y IN D /\ E y w
                  ==> (edefmem (\u. u IN D /\ E u w) E x y <=>
                       edefmem D E x y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(two:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) om w /\ eomega (\u. u IN D /\ E u w) E om`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`]
      OM_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) hf w /\ ehfset (\u. u IN D /\ E u w) E om hf`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `hf:A`]
      HF_IN_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(E:A->A->bool) two w /\ enat (\u. u IN D /\ E u w) E 2 two`
  STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `2`; `two:A`]
      NAT_ABSOLUTE_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\
            epair D (E:A->A->bool) a b p ==> E p w`
   (LABEL_TAC "epc") THENL
   [MATCH_MP_TAC PAIR_CLOSED_SUBMODEL_F THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                   u0 IN D /\ E u0 w /\ s0' IN D /\
                   eupdate D (E:A->A->bool) s0 a0 u0 s0' ==> E s0' w`
   (LABEL_TAC "upc") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`]
      UPDATE_CLOSED_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `hf:A`;
                `two:A`] EDEFMEM_ABSOLUTE_W_ALL_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let DEFMEM_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om x hf vs two u2 vsW u2W z.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        ehfset D E om hf /\ E hf w /\
        efuns D E om x vs /\
        enat D E 2 two /\ two IN D /\ E two w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        efuns (\u. u IN D /\ E u w) E om x vsW /\
        esatuniv (\u. u IN D /\ E u w) E x u2W /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        (!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                        u0 IN D /\ E u0 w /\ s0' IN D /\
                        eupdate D E s0 a0 u0 s0' ==> E s0' w) /\
        z IN D /\ edefmem D E x z
        ==> E z w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [REPEAT STRIP_TAC THEN
    UNDISCH_TAC `etransitive D (E:A->A->bool) w` THEN
    REWRITE_TAC[etransitive] THEN DISCH_THEN(MP_TAC o SPEC `a:A`) THEN
    ASM_REWRITE_TAC[] THEN REWRITE_TAC[esubset] THEN
    DISCH_THEN(MP_TAC o SPEC `b:A`) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(LABEL_TAC "pc" o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "epair")) (concl th))) THEN
  FIRST_X_ASSUM(LABEL_TAC "uc" o check (fun th ->
    is_forall(concl th) &&
    can (find_term (fun t -> is_const t &&
      fst(dest_const t) = "eupdate")) (concl th))) THEN
  SUBGOAL_THEN
   `!c d p. c IN D /\ E c w /\ d IN D /\ E d w /\
            eopair D (E:A->A->bool) c d p ==> E p w`
  (LABEL_TAC "opc") THENL
   [MATCH_MP_TAC EOPAIR_CLOSED_SUBMODEL THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [UNDISCH_TAC `ehfset D (E:A->A->bool) om hf` THEN
    REWRITE_TAC[ehfset] THEN SIMP_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_SUBMODEL] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
