let DEF_CLOSED_SUBMODEL_F = prove
 (`!D (E:A->A->bool) w om x hf vs two u2 vsW u2W yd.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        x IN D /\ E x w /\
        ehfset D E om hf /\ E hf w /\
        efuns D E om x vs /\
        enat D E 2 two /\ two IN D /\ E two w /\
        esatuniv D E x u2 /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        efuns (\u. u IN D /\ E u w) E om x vsW /\
        esatuniv (\u. u IN D /\ E u w) E x u2W /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        (!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                        u0 IN D /\ E u0 w /\ s0' IN D /\
                        eupdate D E s0 a0 u0 s0' ==> E s0' w) /\
        yd IN D /\ edef D E x yd
        ==> E yd w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!a b:A. a IN D /\ E a w /\ b IN D /\ (E:A->A->bool) b a ==> E b w`
  (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w)`; `E:A->A->bool`; `x:A`]
    EDEF_EXISTS_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[IN_SUBMODEL]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `dW:A`) THEN
  SUBGOAL_THEN `(dW:A) IN D /\ (E:A->A->bool) dW w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o CONJUNCT1 o REWRITE_RULE[edef; IN_SUBMODEL] o
      check (fun th -> is_comb(concl th) &&
        (try fst(dest_const(fst(strip_comb(concl th)))) = "edef"
         with Failure _ -> false) &&
        can (find_term is_abs) (concl th))) THEN
    SIMP_TAC[]; ALL_TAC] THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[edef; IN_SUBMODEL] o
    check (fun th -> is_comb(concl th) &&
      (try fst(dest_const(fst(strip_comb(concl th)))) = "edef"
       with Failure _ -> false) &&
      can (find_term is_abs) (concl th))) THEN
  DISCH_THEN(LABEL_TAC "dwch") THEN
  FIRST_ASSUM(MP_TAC o CONJUNCT2 o REWRITE_RULE[edef] o
    check (fun th -> concl th = `edef D (E:A->A->bool) x yd`)) THEN
  DISCH_THEN(LABEL_TAC "ydch") THEN
  SUBGOAL_THEN
   `!q y. q IN D /\ E q w /\ y IN D /\ (E:A->A->bool) y w
          ==> (edefmem (\u. u IN D /\ E u w) E q y <=> edefmem D E q y)`
  (LABEL_TAC "dabs") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `hf:A`;
                  `two:A`] EDEFMEM_ABSOLUTE_W_ALL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `yd:A = dW` (fun th -> ASM_REWRITE_TAC[th]) THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY o
    check (fun th -> concl th = `model D (E:A->A->bool) ZF_AX`)) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `q:A` THEN DISCH_TAC THEN
  EQ_TAC THENL
   [DISCH_TAC THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) x q` ASSUME_TAC THENL
     [USE_THEN "ydch" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> ASM_MESON_TAC[th]); ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) q w` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `x:A`;
                    `hf:A`; `vs:A`; `two:A`; `u2:A`; `vsW:A`; `u2W:A`;
                    `q:A`] DEFMEM_CLOSED_SUBMODEL_F) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
    USE_THEN "dwch" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    USE_THEN "dabs" (MP_TAC o SPECL [`x:A`; `q:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
    DISCH_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) q w` ASSUME_TAC THENL
     [USE_THEN "tr" MATCH_MP_TAC THEN EXISTS_TAC `dW:A` THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `edefmem D (E:A->A->bool) x q` ASSUME_TAC THENL
     [USE_THEN "dwch" (MP_TAC o SPEC `q:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
