        FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
          check (fun a -> concl a = `(E:A->A->bool) q dW`))) THEN
      USE_THEN "dabs" (MP_TAC o SPECL [`x:A`; `q:A`]) THEN
