    USE_THEN "ydch" (MP_TAC o SPEC `q:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]]);;

let DEF_CLOSED_SUBMODEL_ALL_F = prove
 (`!D (E:A->A->bool) w om hf two.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ om IN D /\ E om w /\
        ehfset D E om hf /\ E hf w /\
        enat D E 2 two /\ two IN D /\ E two w /\
        eomega (\u. u IN D /\ E u w) E om /\
        ehfset (\u. u IN D /\ E u w) E om hf /\
        (!a b p. a IN D /\ E a w /\ b IN D /\ E b w /\ epair D E a b p
                 ==> E p w) /\
        (!s0 a0 u0 s0'. s0 IN D /\ E s0 w /\ a0 IN D /\ E a0 w /\
                        u0 IN D /\ E u0 w /\ s0' IN D /\
                        eupdate D E s0 a0 u0 s0' ==> E s0' w)
        ==> !x y. x IN D /\ E x w /\ y IN D /\ edef D E x y
                  ==> E y w`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MAP_EVERY X_GEN_TAC [`x:A`; `y:A`] THEN STRIP_TAC THEN
  SUBGOAL_THEN `(x:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN (\u. u IN D /\ (E:A->A->bool) u w)` ASSUME_TAC THENL
   [REWRITE_TAC[IN_ELIM_THM] THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `x:A`] EFUNS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `vs:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `x:A`] ESATUNIV_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2:A`) THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
                `om:A`; `x:A`] EFUNS_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `vsW:A`) THEN
  MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`; `E:A->A->bool`;
                `x:A`] ESATUNIV_EXISTS_F) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `u2W:A`) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `x:A`; `hf:A`;
                `vs:A`; `two:A`; `u2:A`; `vsW:A`; `u2W:A`; `y:A`]
    DEF_CLOSED_SUBMODEL_F) THEN
  ASM_REWRITE_TAC[]);;

