                `two:A`] DEF_CLOSED_SUBMODEL_ALL_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

let ELSTAGE_ABSOLUTE_WCL_W_F = prove
 (`!D (E:A->A->bool) w om hf two a yD.
        model D E ZF_AX /\ w IN D /\ etransitive D E w /\
        model (\u. u IN D /\ E u w) E zfw_ax /\
        eomega D E om /\ ehfset D E om hf /\ enat D E 2 two /\
        eordinal D E a /\ E a w /\
        yD IN D /\ elstage D E a yD
        ==> E yD w /\
            !yL. yL IN D /\ E yL w /\
                 elstage (\u. u IN D /\ E u w) E a yL
                 ==> yL = yD`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!t s:A. t IN D /\ s IN D /\ (E:A->A->bool) s w /\ E t s ==> E t w`
   (LABEL_TAC "tr") THENL
   [ASM_MESON_TAC[etransitive; esubset]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x y. x IN D /\ E x w /\ y IN D /\ E y w
          ==> (edefmem (\u. u IN D /\ (E:A->A->bool) u w) E x y <=>
               edefmem D E x y)`
  (LABEL_TAC "defabs") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `hf:A`;
                  `two:A`] DEFABS_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!x yd. x IN D /\ E x w /\ yd IN D /\ edef D (E:A->A->bool) x yd
           ==> E yd w`
  (LABEL_TAC "defcl") THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `om:A`; `hf:A`;
                  `two:A`] DEFCL_SUBMODEL_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `?c0:A. c0 IN D /\ (E:A->A->bool) c0 w` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MODEL_NONEMPTY o check (fun th ->
      can (find_term (fun t -> t = `(\u. u IN D /\ (E:A->A->bool) u w)`))
        (concl th))) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM]; ALL_TAC] THEN
  ABBREV_TAC `v0 = (26 |-> w) (\k:num. c0:A)` THEN
  SUBGOAL_THEN `valuation D (v0:num->A) /\
                (!i. ~(i = 26) ==>
                 (E:A->A->bool) ((v0:num->A) i) w) /\ v0 26 = w`
  STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v0" THEN REWRITE_TAC[valuation; VALMOD] THEN
    REPEAT CONJ_TAC THEN X_GEN_TAC `i:num` THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!a'. eordinal D (E:A->A->bool) a'
         ==> holds D E ((4 |-> a') (v0:num->A)) labs_form_wcl`
  (LABEL_TAC "ind") THENL
   [MATCH_MP_TAC EORDINAL_INDUCT THEN ASM_REWRITE_TAC[] THEN
    X_GEN_TAC `a':A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "ihh")) THEN
    SUBGOAL_THEN `(a':A) IN D` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`] EORDINAL_IN) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `v0:num->A`; `a':A`]
      HOLDS_LABS_FORM_WCL) THEN
    ANTS_TAC THENL
     [REPEAT CONJ_TAC THEN FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    X_GEN_TAC `yD':A` THEN DISCH_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `elstage D (E:A->A->bool) a' yD'` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a':A`; `yD':A`;
                    `v0:num->A`] ELSTAGE_EREC_NV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    SUBGOAL_THEN
     `!b yb yLb. b IN D /\ E b a' /\ E b w /\ yb IN D /\
                 elstage D (E:A->A->bool) b yb /\ yLb IN D /\ E yLb w /\
                 elstage (\u. u IN D /\ E u w) E b yLb
                 ==> yLb = yb`
    (LABEL_TAC "ihagr") THENL
