    SUBGOAL_THEN `(E:A->A->bool) yD' w` ASSUME_TAC THENL
     [USE_THEN "clos" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `w:A`; `a':A`; `yD':A`;
                  `yL':A`] ELSTAGE_ABS_STEP_W_F) THEN
    DISCH_THEN MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[] THEN
    MAP_EVERY X_GEN_TAC [`b:A`; `yb:A`; `yLb:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) b w` ASSUME_TAC THENL
