   [REWRITE_TAC[] THEN
    MP_TAC(SPECL [`(\u. u IN D /\ (E:A->A->bool) u w):A->bool`;
                  `E:A->A->bool`; `a:A`; `yL:A`; `v0:num->A`]
      ELSTAGE_EREC_NV_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    DISCH_THEN ACCEPT_TAC]);;

(* ========================================================================= *)
(* The hull over a union of stages. Here the ambient set ya of the hull is   *)
(* the union of the stages L(b), b < a, and the wellorder ra is the union of *)
(* the corresponding wellorders elwou b, so that the hypothesis that ya      *)
(* satisfies zfw_ax can be discharged by reflection (WVL_REFLECT gives such  *)
(* a union). ELWO_SELECT_W: ra-least elements of nonempty subsets of ya.     *)
(* Then the padded Skolem witnesses (ESKOLEM_VALUE_GEN_WA,                   *)
(* EHULL_WITNESS_GEN_WA), the meta-level Tarski-Vaught bridge                *)
(* EHULL_WITNESS_HOLDS_WA with the quantifier steps TV_BACKWARD_WA and       *)
(* TV_FORWARD_WA, the elementarity of the hull Som (SUBMODEL_ELEM_WA,        *)
(* MODEL_SOM_ELEM_WA), its extensionality (SOM_EXTENSIONAL_WA), and the      *)
(* transfer of zfw_ax from ya to Som and to the collapse M'                  *)
(* (MODEL_SOM_FROM_YA_WA_F, MODEL_MPRIME_FROM_YA_WA_F; the latter separates  *)
(* the hull union ya from a single stage yc = L(a) containing Som, which     *)
(* bounds the collapse).                                                     *)
(* ========================================================================= *)

let ELWO_SELECT_W = prove
 (`!D (E:A->A->bool) c Rc w z.
     model D E ZF_AX /\ eordinal D E c /\ Rc IN D /\ w IN D /\
     (!q. q IN D
          ==> (E q Rc <=>
               ?b rb. b IN D /\ rb IN D /\ E b c /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t w <=>
               ?b yb. b IN D /\ yb IN D /\ E b c /\
                 elstage D E b yb /\ E t yb)) /\
     z IN D /\ (!t. t IN D /\ E t z ==> E t w) /\ (?t. t IN D /\ E t z)
     ==> ?m. m IN D /\ E m z /\
             (!t. t IN D /\ E t z /\ ~(t = m) ==> erel D E Rc m t)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `Rc:A`; `w:A`] RA_WF) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
    ASM_MESON_TAC[ELWOU_INVARIANT; EORDINAL_MEMBER];
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]]);;

let ESKOLEM_VALUE_GEN_WA = prove
 (`!D (E:A->A->bool) a ra ya om c s z0 v0.
     model D E ZF_AX /\ eordinal D E a /\ ra IN D /\ ya IN D /\
     (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ c IN D /\ s IN D /\ z0 IN D /\
     valuation D v0 /\
     (?u. u IN D /\ E u ya /\
          ?s'. s' IN D /\ eupdate D E s z0 u s' /\
            (?pv. pv IN D /\
             (!b. b IN D ==> !uu. uu IN D ==> eapply D E s' b uu ==>
              eapply D E pv b uu) /\ esat D E ya c pv))
     ==> ?m. m IN D /\ E m ya /\
             (?s'. s' IN D /\ eupdate D E s z0 m s' /\
              (?pv. pv IN D /\
               (!b. b IN D ==> !uu. uu IN D ==> eapply D E s' b uu ==>
                eapply D E pv b uu) /\ esat D E ya c pv)) /\
             (!t. t IN D /\ E t ya /\
                  (?s'. s' IN D /\ eupdate D E s z0 t s' /\
                   (?pv. pv IN D /\
                    (!b. b IN D ==> !uu. uu IN D ==> eapply D E s' b uu ==>
                     eapply D E pv b uu) /\ esat D E ya c pv)) /\
                  ~(t = m)
                  ==> erel D E ra m t)`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `ya:A`; `c:A`; `s:A`;
    `z0:A`; `v0:num->A`] EWITSET_EXISTS_GEN) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "wc"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`; `ya:A`; `W:A`]
    ELWO_SELECT_W) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
      USE_THEN "wc" (MP_TAC o SPEC `t:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) t W`))) THEN
      STRIP_TAC THEN ASM_REWRITE_TAC[];
      FIRST_X_ASSUM(X_CHOOSE_THEN `u0:A` STRIP_ASSUME_TAC o
        check (is_exists o concl)) THEN
      EXISTS_TAC `u0:A` THEN
      USE_THEN "wc" (MP_TAC o SPEC `u0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[]];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN
   `E (m:A) ya /\
    (?s'. s' IN D /\ eupdate D E s z0 m s' /\
     (?pv. pv IN D /\
      (!b. b IN D ==> !uu. uu IN D ==> eapply D E s' b uu ==>
       eapply D E pv b uu) /\ esat D E ya c pv))`
  STRIP_ASSUME_TAC THENL
   [USE_THEN "wc" (MP_TAC o SPEC `m:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> ACCEPT_TAC(EQ_MP th (ASSUME `(E:A->A->bool) m W`)));
    ALL_TAC] THEN
  EXISTS_TAC `m:A` THEN REPEAT CONJ_TAC THENL
   [ASM_REWRITE_TAC[];
    ASM_REWRITE_TAC[];
    ASM_MESON_TAC[];
    X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o
      check (fun th -> is_forall (concl th) && free_in `W:A` (concl th))) THEN
    ASM_REWRITE_TAC[] THEN
    USE_THEN "wc" (MP_TAC o SPEC `t:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_MESON_TAC[]]);;

let EHULL_WITNESS_GEN_WA = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som c s v0.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\ (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
