     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     (!sv' v'. evaluation D E om Som sv' /\ shadowed D E sv' v'
               ==> (holds (\z. z IN D /\ E z Som) E v' p1 <=>
                    holds (\z. z IN D /\ E z ya) E v' p1)) /\
     evaluation D E om Som sv /\ shadowed D E sv v /\
     (!u. u IN D /\ E u ya ==> holds (\z. z IN D /\ E z ya) E ((x |-> u) v) p1)
     ==> (!u. u IN D /\ E u Som
              ==> holds (\z. z IN D /\ E z Som) E ((x |-> u) v) p1)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) (u:A) (ya:A)` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x:num`] ENAT_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `nx:A`) THEN
  SUBGOAL_THEN `(nx:A) IN D` ASSUME_TAC THENL
  [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (nx:A) (om:A)` ASSUME_TAC THENL
  [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`sv:A`;`nx:A`;`u:A`]
         EUPDATE_EXISTS) THEN
  ANTS_TAC THENL [ASM_MESON_TAC[EVALUATION_IN]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `su:A`) THEN
  SUBGOAL_THEN `evaluation D (E:A->A->bool) om Som su` ASSUME_TAC THENL
   [MATCH_MP_TAC EVALUATION_UPDATE THEN
    MAP_EVERY EXISTS_TAC [`sv:A`;`nx:A`;`u:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `shadowed D (E:A->A->bool) su ((x |-> u) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC SHADOWED_UPDATE THEN
    MAP_EVERY EXISTS_TAC [`om:A`;`Som:A`;`sv:A`;`nx:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM(fun ih ->
                MP_TAC(SPECL [`su:A`;`(x |-> (u:A)) (v:num->A)`] ih)) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]);;

let TV_FORWARD_WA = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som vs u2 two v0 zeta p1 x sv v.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\ (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ om IN D /\ valuation D v0 /\ Som IN D /\
     pdclstage D E g0 ya hf z0 fsY ra om Som /\
     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     (!sv' v'. evaluation D E om Som sv' /\ shadowed D E sv' v'
               ==> (holds (\z. z IN D /\ E z Som) E v' p1 <=>
                    holds (\z. z IN D /\ E z ya) E v' p1)) /\
     evaluation D E om Som sv /\ shadowed D E sv v /\
     (!u. u IN D /\ E u Som ==>
      holds (\z. z IN D /\ E z Som) E ((x |-> u) v) p1)
     ==> (!u. u IN D /\ E u ya
              ==> holds (\z. z IN D /\ E z ya) E ((x |-> u) v) p1)`,
