  X_GEN_TAC `u0:A` THEN STRIP_TAC THEN
  ASM_CASES_TAC
    `holds (\z. z IN (D:A->bool) /\ E z ya) E ((x |-> (u0:A)) v) p1` THEN
  ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`x:num`] ENAT_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `nx:A`) THEN
  SUBGOAL_THEN `(nx:A) IN D /\ (E:A->A->bool) (nx:A) (om:A)`
    STRIP_ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN; ENAT_IN_OMEGA]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`Som:A`;`sv:A`;`v:num->A`;
