  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`hf:A`;`z0:A`;
                `swapform x zeta p1 --> False`] ECODE_RANK_ABOVE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `nc:A`
    (X_CHOOSE_THEN `ync:A` STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;`fsY:A`;
                `ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`nc:A`;`ync:A`;
                `swapform x zeta p1 --> False`;`c:A`;`sv':A`;
                `\j. (v:num->A)(swapv x zeta j)`;`v0:num->A`;`zeta:num`;
                `u2:A`;`two:A`]
    EHULL_WITNESS_HOLDS_WA) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN EXISTS_TAC `u0:A` THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[holds; HOLDS_SWAPFORM; VALMOD_UNSWAP] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  INTRO_TAC "@w. h1 h2 gconc" THEN
  SUBGOAL_THEN `holds (\z. z IN (D:A->bool) /\ E z ya) E ((x |-> (w:A)) v) p1`
