    REWRITE_TAC[holds];
    REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN STRIP_TAC THEN
    REWRITE_TAC[holds] THEN
    MATCH_MP_TAC(TAUT
                 `(p <=> r) /\ (q <=> s) ==> ((p ==> q) <=> (r ==> s))`) THEN
    CONJ_TAC THEN
    FIRST_X_ASSUM(fun ih ->
      MP_TAC(SPECL [`sv:A`;`v:num->A`] ih) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);
    REPEAT GEN_TAC THEN DISCH_TAC THEN REPEAT GEN_TAC THEN DISCH_TAC THEN
    REWRITE_TAC[holds; IN_SUBMODEL] THEN EQ_TAC THEN DISCH_TAC THENL
     [MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;`fsY:A`;
              `ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;`v0:num->A`;
              `zeta:num`;`a1:form`;`a0:num`;`sv:A`;`v:num->A`]
             TV_FORWARD_WA) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC];
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;`fsY:A`;
              `ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;`v0:num->A`;
