    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;
                `fsY:A`;`ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;
                `v0:num->A`;`zeta:num`] SUBMODEL_ELEM_WA) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL
    [`?? 2 (Not((2 %% 0) <-> (2 %% 1)))`;`s1:A`;`v:num->A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[holds; HOLDS_EX; HOLDS_NOT; HOLDS_IFF] THEN
  REWRITE_TAC[IN] THEN REWRITE_TAC[VALMOD; ARITH_EQ; GSYM CONJ_ASSOC] THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  EXISTS_TAC `u0:A` THEN ASM_REWRITE_TAC[] THEN
  UNDISCH_TAC `(u0:A) IN D` THEN REWRITE_TAC[IN]);;

let MODEL_SOM_ELEM_WA = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som vs u2 two v0 zeta s0.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\ (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ om IN D /\ valuation D v0 /\ Som IN D /\
     pdclstage D E g0 ya hf z0 fsY ra om Som /\
     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     evaluation D E om Som s0
     ==> !p v. (!i. v i IN D /\ E (v i) Som)
               ==> (holds (\z. z IN D /\ E z Som) E v p <=>
                    holds (\z. z IN D /\ E z ya) E v p)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  REPEAT GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Som:A`; `s0:A`;
                `v:num->A`] SHADOWED_MATCH) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `FV(p:form)`) THEN
  ANTS_TAC THENL [REWRITE_TAC[FV_FINITE]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `sv:A` (X_CHOOSE_THEN `w:num->A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN
   `holds (\z. z IN D /\ (E:A->A->bool) z Som) E w p <=>
    holds (\z. z IN D /\ E z Som) E v p` ASSUME_TAC THENL
   [MATCH_MP_TAC HOLDS_VALUATION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds (\z. z IN D /\ (E:A->A->bool) z ya) E w p <=>
    holds (\z. z IN D /\ E z ya) E v p` ASSUME_TAC THENL
   [MATCH_MP_TAC HOLDS_VALUATION THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g0:A`; `ya:A`; `hf:A`; `z0:A`;
                `fsY:A`; `ra:A`; `a:A`; `om:A`; `Som:A`; `vs:A`; `u2:A`;
                `two:A`; `v0:num->A`; `zeta:num`] SUBMODEL_ELEM_WA) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPECL [`p:form`; `sv:A`; `w:num->A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[]);;

let MODEL_SOM_FROM_YA_WA_F = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som vs u2 two v0 zeta s0.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\ (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ om IN D /\ valuation D v0 /\ Som IN D /\
     pdclstage D E g0 ya hf z0 fsY ra om Som /\
     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     evaluation D E om Som s0 /\
     model (\z. z IN D /\ E z ya) E zfw_ax
     ==> model (\z. z IN D /\ E z Som) E zfw_ax`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REWRITE_TAC[model] THEN CONJ_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Som:A`; `s0:A`]
      SHADOWED_EXISTS) THEN
    ASM_REWRITE_TAC[] THEN
    DISCH_THEN(X_CHOOSE_THEN `v1:num->A` STRIP_ASSUME_TAC) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
    EXISTS_TAC `(v1:num->A) 0` THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[SHADOWED_VALUATION; valuation];
    REWRITE_TAC[satisfies] THEN MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN
    REWRITE_TAC[valuation; IN_ELIM_THM] THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g0:A`; `ya:A`; `hf:A`; `z0:A`;
                  `fsY:A`; `ra:A`; `a:A`; `om:A`; `Som:A`; `vs:A`; `u2:A`;
                  `two:A`; `v0:num->A`; `zeta:num`; `s0:A`]
        MODEL_SOM_ELEM_WA) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`p:form`; `v:num->A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    UNDISCH_TAC `model (\z. z IN D /\ (E:A->A->bool) z ya) E zfw_ax` THEN
    REWRITE_TAC[model; satisfies] THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[valuation; IN_ELIM_THM] THEN
    X_GEN_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN
    FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
      concl th = `!w. w IN D /\ (E:A->A->bool) w Som ==> E w ya`)) THEN
    ASM_REWRITE_TAC[]]);;

let MODEL_MPRIME_FROM_YA_WA_F = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som vs u2 two v0 zeta s0 za
   la ga yc Mp.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\
     (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ om IN D /\ valuation D v0 /\ Som IN D /\
     pdclstage D E g0 ya hf z0 fsY ra om Som /\
     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     evaluation D E om Som s0 /\
     model (\z. z IN D /\ E z ya) E zfw_ax /\
     model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ yc IN D /\
      elstage D E a yc /\
      (!w. w IN D /\ E w Som ==> E w yc) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p))
     ==> model (\z. z IN D /\ E z Mp) E zfw_ax`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g0:A`; `ya:A`; `hf:A`; `z0:A`;
                `fsY:A`; `ra:A`; `a:A`; `om:A`; `Som:A`; `vs:A`; `u2:A`;
                `two:A`; `v0:num->A`; `zeta:num`; `s0:A`]
       MODEL_SOM_FROM_YA_WA_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `Som:A`; `a:A`; `za:A`; `la:A`;
                `ga:A`; `yc:A`; `Mp:A`] MODEL_MPRIME_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN FIRST_ASSUM ACCEPT_TAC);;

(* ========================================================================= *)
(* The collapse M' satisfies V=L: the object sentence vl_form, and its       *)
(* transfer from ya through the hull Som to M'.                              *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* The sentence V=L: vl_form = !! 0 lmem_form. HOLDS_VL_FORM_F: in a model   *)
(* of zfw_ax, vl_form holds iff every set is constructible.                  *)
(* ------------------------------------------------------------------------- *)

let vl_form = new_definition `vl_form = !! 0 lmem_form`;;

let HOLDS_VL_FORM_F = prove
 (`!D (E:A->A->bool) v.
        model D E zfw_ax /\ valuation D v
        ==> (holds D E v vl_form <=> (!u. u IN D ==> elmem D E u))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vl_form; holds] THEN
  SUBGOAL_THEN
   `!u:A. u IN D
      ==> (holds D E ((0 |-> u) v) lmem_form <=> elmem D E u)`
   (fun th -> MESON_TAC[th]) THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> (u:A)) v)` ASSUME_TAC THENL
   [ASM_MESON_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(0 |-> (u:A)) v`]
    HOLDS_LMEM_FORM_F) THEN
  ASM_REWRITE_TAC[VALMOD]);;

(* ------------------------------------------------------------------------- *)
(* REFLECT_MODEL_PLUS: reflection of a set s of axioms, all subformulas of   *)
(* p, together with one more subformula r of p that holds in L, to a union w *)
(* of stages L(b), b < c, for an ordinal c above a given a0.                 *)
(* ------------------------------------------------------------------------- *)

let REFLECT_MODEL_PLUS = prove
 (`!D (E:A->A->bool) p s r a0.
        model D E ZF_AX /\ a0 IN D /\ eordinal D E a0 /\
        (!q. q IN s ==> subform q p /\ q IN ZF_AX) /\
        subform r p /\
        (!v. valuation (lclass D E) v ==> holds (lclass D E) E v r)
        ==> ?c w. c IN D /\ w IN D /\ eordinal D E c /\ E a0 c /\
                  (!u. u IN D
                       ==> (E u w <=>
                            ?b z. b IN D /\ z IN D /\ E b c /\
                                  elstage D E b z /\ E u z)) /\
                  model (\t. t IN D /\ E t w) E s /\
                  (!v. (!i. (v:num->A) i IN D /\ E (v i) w)
                       ==> holds (\t. t IN D /\ E t w) E v r)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:form`; `a0:A`] REFLECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@c w. h1 h2 h3 h4 wch refl" THEN
  MAP_EVERY EXISTS_TAC [`c:A`; `w:A`] THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN
   `!u. u IN D /\ (E:A->A->bool) u w ==> elmem D E u`
  (LABEL_TAC "wlm") THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    USE_THEN "wch" (MP_TAC o SPEC `u:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th ->
      FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [th] o
        check (fun a -> concl a = `(E:A->A->bool) u w`))) THEN
    DISCH_THEN(X_CHOOSE_THEN `b:A` (X_CHOOSE_THEN `z:A`
      STRIP_ASSUME_TAC)) THEN
    REWRITE_TAC[elmem] THEN MAP_EVERY EXISTS_TAC [`b:A`; `z:A`] THEN
    ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `c:A`; `b:A`]
      EORDINAL_MEMBER) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  CONJ_TAC THENL
   [REWRITE_TAC[model] THEN CONJ_TAC THENL
     [REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN
      EXISTS_TAC `a0:A` THEN ASM_REWRITE_TAC[] THEN
      SUBGOAL_THEN `?y0. (y0:A) IN D /\ elstage D (E:A->A->bool) a0 y0`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[ELSTAGE_EXISTS]; ALL_TAC] THEN
      USE_THEN "wch" (MP_TAC o SPEC `a0:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`a0:A`; `y0:A`] THEN ASM_REWRITE_TAC[] THEN
      ASM_MESON_TAC[ELSTAGE_ORD_SELF];
      ALL_TAC] THEN
    REWRITE_TAC[satisfies] THEN
    MAP_EVERY X_GEN_TAC [`v:num->A`; `q:form`] THEN
    REWRITE_TAC[valuation; IN_ELIM_THM] THEN STRIP_TAC THEN
    SUBGOAL_THEN `subform q p /\ q IN ZF_AX` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    USE_THEN "refl" (MP_TAC o SPECL [`q:form`; `v:num->A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[valuation] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    SUBGOAL_THEN `model (lclass D E) (E:A->A->bool) ZF_AX` MP_TAC THENL
     [MATCH_MP_TAC MODEL_LCLASS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[model; satisfies] THEN STRIP_TAC THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[] THEN
    REWRITE_TAC[valuation; IN_LCLASS] THEN
    X_GEN_TAC `i:num` THEN ASM_REWRITE_TAC[] THEN
    USE_THEN "wlm" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    X_GEN_TAC `v:num->A` THEN DISCH_TAC THEN
    USE_THEN "refl" (MP_TAC o SPECL [`r:form`; `v:num->A`]) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[valuation] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN
    REWRITE_TAC[valuation; IN_LCLASS] THEN
    X_GEN_TAC `i:num` THEN
    ASM_REWRITE_TAC[] THEN USE_THEN "wlm" MATCH_MP_TAC THEN
    ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* LCLASS_VL_HOLDS: L satisfies vl_form.                                     *)
(* ------------------------------------------------------------------------- *)

let LCLASS_VL_HOLDS = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation (lclass D E) v
        ==> holds (lclass D E) E v vl_form`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`lclass D (E:A->A->bool)`; `E:A->A->bool`; `v:num->A`]
    HOLDS_VL_FORM_F) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC MODEL_ZFW THEN
    MATCH_MP_TAC MODEL_LCLASS THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  X_GEN_TAC `u:A` THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] LCLASS_IDEMPOTENT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun eq ->
    SUBGOAL_THEN `(u:A) IN lclass (lclass D E) (E:A->A->bool)` MP_TAC THENL
     [ASM_REWRITE_TAC[eq]; ALL_TAC]) THEN
  REWRITE_TAC[IN_LCLASS] THEN
  DISCH_THEN(MP_TAC o CONJUNCT2) THEN DISCH_THEN ACCEPT_TAC);;

(* ------------------------------------------------------------------------- *)
(* WVL_REFLECT: for every ordinal a0 there is a union w of stages L(b),      *)
(* b < c, with a0 < c, that is a model of zfw_ax and satisfies vl_form.      *)
(* ------------------------------------------------------------------------- *)

let WVL_REFLECT = prove
 (`!D (E:A->A->bool) a0.
        model D E ZF_AX /\ a0 IN D /\ eordinal D E a0
        ==> ?c w. c IN D /\ w IN D /\ eordinal D E c /\ E a0 c /\
                  (!u. u IN D
                       ==> (E u w <=>
                            ?b z. b IN D /\ z IN D /\ E b c /\
                                  elstage D E b z /\ E u z)) /\
                  model (\t. t IN D /\ E t w) E zfw_ax /\
                  (!v. (!i. (v:num->A) i IN D /\ E (v i) w)
                       ==> holds (\t. t IN D /\ E t w) E v vl_form)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `zfw_conj && vl_form`;
                `zfw_ax`; `vl_form`; `a0:A`] REFLECT_MODEL_PLUS) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN REPEAT CONJ_TAC THENL
     [X_GEN_TAC `q:form` THEN DISCH_TAC THEN CONJ_TAC THENL
       [MATCH_MP_TAC(MATCH_MP SUBFORM_TRANS
           (ISPECL [`zfw_conj`; `vl_form`] SUBFORM_AND_L)) THEN
        MATCH_MP_TAC SUBFORM_ZFW THEN ASM_REWRITE_TAC[];
        ASM_MESON_TAC[REWRITE_RULE[SUBSET] ZFW_SUBSET_ZFAX]];
      MATCH_MP_TAC SUBFORM_AND_INTO_R THEN REWRITE_TAC[SUBFORM_REFL];
      REPEAT STRIP_TAC THEN MATCH_MP_TAC LCLASS_VL_HOLDS THEN
      ASM_REWRITE_TAC[]];
    DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* MPRIME_VL_FROM_YA: if ya satisfies zfw_ax and V=L, then so does the       *)
(* collapse M' of the hull Som (via the hull and the collapse isomorphism).  *)
(* ------------------------------------------------------------------------- *)

let MPRIME_VL_FROM_YA = prove
 (`!D (E:A->A->bool) g0 ya hf z0 fsY ra a om Som vs u2 two v0 zeta s0 za
   la ga yc Mp.
     model D E ZF_AX /\ g0 IN D /\ ya IN D /\ hf IN D /\ z0 IN D /\ fsY IN D /\
     ra IN D /\ eordinal D E a /\
     (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b a /\
                 elwou D E b rb /\ E q rb)) /\
     (!t. t IN D
          ==> (E t ya <=>
               ?b yb. b IN D /\ yb IN D /\ E b a /\
                 elstage D E b yb /\ E t yb)) /\
     eomega D E om /\ om IN D /\ valuation D v0 /\ Som IN D /\
     pdclstage D E g0 ya hf z0 fsY ra om Som /\
     (!r. r IN D
          ==> (E r fsY <=> eisfun D E r /\
               (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!j uu. j IN D /\ uu IN D /\ eapply D E r j uu ==> E uu ya))) /\
     (!w. w IN D /\ E w Som ==> E w ya) /\
     ehfset D E om hf /\ efuns D E om ya vs /\ vs IN D /\
     esatuniv D E ya u2 /\ enat D E 2 two /\
     enat D E zeta z0 /\ E z0 om /\
     evaluation D E om Som s0 /\
     model (\z. z IN D /\ E z ya) E zfw_ax /\
     model D E ZF_AX /\ Som IN D /\ eordinal D E a /\ yc IN D /\
      elstage D E a yc /\
      (!w. w IN D /\ E w Som ==> E w yc) /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E Som a za /\ eopair D E la ga za /\
      (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
              ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
      Mp IN D /\
      (!v. v IN D
           ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p ga /\
                eopair D E u v p)) /\
     (!v. (!i. (v:num->A) i IN D /\ E (v i) ya)
          ==> holds (\z. z IN D /\ E z ya) E v vl_form)
     ==> model (\z. z IN D /\ E z Mp) E zfw_ax /\
         (!u. u IN D /\ E u Mp ==> elmem (\z. z IN D /\ E z Mp) E u)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `model (\z. z IN D /\ (E:A->A->bool) z Mp) E zfw_ax`
    ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;`fsY:A`;
            `ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;`v0:num->A`;
                  `zeta:num`;`s0:A`;`za:A`;`la:A`;`ga:A`;`yc:A`;`Mp:A`]
       MODEL_MPRIME_FROM_YA_WA_F) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  CONJ_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `?m0:A. m0 IN D /\ (E:A->A->bool) m0 Mp` STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP MODEL_NONEMPTY o
       check (fun th -> free_in `Mp:A` (concl th))) THEN
    REWRITE_TAC[GSYM MEMBER_NOT_EMPTY; IN_ELIM_THM] THEN MESON_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
                `yc:A`;`Mp:A`] COLL_ONTO) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `m0:A`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `u0:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) (u0:A) ya` ASSUME_TAC THENL
   [FIRST_X_ASSUM(MATCH_MP_TAC o check (fun th ->
       concl th = `!w. w IN D /\ (E:A->A->bool) w Som ==> E w ya`)) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds (\z. z IN D /\ (E:A->A->bool) z ya) E (\k:num. u0:A) vl_form`
   ASSUME_TAC THENL
   [FIRST_X_ASSUM(fun th -> if is_forall(concl th) &&
                  free_in `vl_form` (concl th)
                  then MATCH_MP_TAC th else NO_TAC) THEN
    GEN_TAC THEN BETA_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds (\z. z IN D /\ (E:A->A->bool) z Som) E (\k:num. u0:A) vl_form`
   ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`g0:A`;`ya:A`;`hf:A`;`z0:A`;`fsY:A`;
            `ra:A`;`a:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;`v0:num->A`;
                  `zeta:num`;`s0:A`] MODEL_SOM_ELEM_WA) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`vl_form`; `\k:num. u0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds (\z. z IN D /\ (E:A->A->bool) z Mp) E (\k:num. m0:A) vl_form`
   ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
            `yc:A`;`Mp:A`] ISO_HOLDS_COLL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPECL [`vl_form`; `\k:num. u0:A`; `\k:num. m0:A`]) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`(\z. z IN D /\ (E:A->A->bool) z Mp)`; `E:A->A->bool`;
                `\k:num. m0:A`] HOLDS_VL_FORM_F) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[valuation; IN_ELIM_THM]; ALL_TAC] THEN
  DISCH_THEN(fun th -> MP_TAC(EQ_MP th (ASSUME
    `holds (\z. z IN D /\ (E:A->A->bool) z Mp) E (\k:num. m0:A)
     vl_form`))) THEN
  REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[]);;

(* ========================================================================= *)
(* The Mostowski collapse of a hull fixes the ordinals below the critical    *)
(* point; this is the crux of GCH. If Som is the hull (the X of the          *)
(* recurrence), la = L(a) the collapse domain, ga the graph of the collapse  *)
(* map, and kappa SUBSET Som, then the collapse sends every ordinal          *)
(* xi < kappa to itself: pi(xi) = xi. Hence a set X SUBSET kappa seeded into *)
(* the hull survives the collapse.                                           *)
(*                                                                           *)
(* Three lemmas: ECOLLTOWER_PI_SV, the collapse map is single-valued on Som; *)
(* HOLDS_COLLFIX_PROP, the property pi(xi) = xi is expressed by the formula  *)
(* (0 %% 1) --> applyto_form 0 0 2 under the base valuation v with           *)
(* v 1 = kappa and v 2 = ga; and COLL_FIXES_ORDINALS, the induction itself,  *)
(* via the formula-based EORDINAL_INDUCT since the model need not be         *)
(* wellfounded.                                                              *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* ECOLLTOWER_PI_SV: the collapse map ga is single-valued on the hull, i.e.  *)
(* pi(x) is unique.                                                          *)
(* ------------------------------------------------------------------------- *)

let ECOLLTOWER_PI_SV = prove
 (`!D (E:A->A->bool) X a za la ga x i i'.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      x IN D /\ i IN D /\ i' IN D /\
      eapply D E ga x i /\ eapply D E ga x i'
      ==> i = i'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
                `x:A`;`i:A`] ECOLLTOWER_PI_RECURRENCE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
                `x:A`;`i':A`] ECOLLTOWER_PI_RECURRENCE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_TAC THEN
  FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
  ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* HOLDS_COLLFIX_PROP: the object formula (0 %% 1) --> applyto_form 0 0 2    *)
(* under the base valuation v (v 1 = kappa, v 2 = ga) expresses the property *)
(* xi < kappa ==> pi(xi) = xi of the induction variable in slot 0.           *)
(* ------------------------------------------------------------------------- *)

let HOLDS_COLLFIX_PROP = prove
 (`!D (E:A->A->bool) kappa ga xi.
     kappa IN D /\ ga IN D /\ xi IN D
     ==> (holds D E ((0 |-> xi) (\n. if n = 2 then ga else (kappa:A)))
                  ((0 %% 1) --> applyto_form 0 0 2) <=>
          (E xi kappa ==> eapply D E ga xi xi))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `valuation D ((0 |-> xi) (\n. if n = 2 then ga else (kappa:A)))`
   ASSUME_TAC THENL
   [REWRITE_TAC[valuation; VALMOD] THEN GEN_TAC THEN
    REPEAT COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[holds; VALMOD] THEN CONV_TAC NUM_REDUCE_CONV THEN
  ASM_SIMP_TAC[HOLDS_APPLYTO_FORM] THEN
  REWRITE_TAC[VALMOD] THEN CONV_TAC NUM_REDUCE_CONV);;

(* ------------------------------------------------------------------------- *)
(* COLL_FIXES_ORDINALS: the collapse fixes every ordinal below kappa. Proof: *)
(* formula-based EORDINAL_INDUCT on the property pi(xi) = xi (as in          *)
(* HOLDS_COLLFIX_PROP). For an ordinal c < kappa, the members of pi(c) are   *)
(* the pi(y) for y IN Som INTER c (ECOLLTOWER_PI_RECURRENCE); by the         *)
(* induction hypothesis each such y < c < kappa has pi(y) = y, and           *)
(* single-valuedness (ECOLLTOWER_PI_SV) forces pi(c) = c by extensionality:  *)
(* a member z of pi(c) comes from some y with pi(y) = z, so z = y IN c;      *)
(* conversely each y IN c is < kappa, hence in Som, and y = pi(y) IN pi(c).  *)
(* ------------------------------------------------------------------------- *)

let COLL_FIXES_ORDINALS = prove
 (`!D (E:A->A->bool) X a za la ga kappa.
      model D E ZF_AX /\ X IN D /\ eordinal D E a /\
      za IN D /\ la IN D /\ ga IN D /\
      ecolltower D E X a za /\ eopair D E la ga za /\
      eordinal D E kappa /\ kappa IN D /\
      (!xi. xi IN D /\ E xi kappa ==> E xi X) /\
      (!w. w IN D /\ E w X ==> E w la)
      ==> !xi. xi IN D /\ eordinal D E xi /\ E xi kappa
               ==> eapply D E ga xi xi`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN
   `!xi. eordinal D (E:A->A->bool) xi
         ==> holds D E ((0 |-> xi) (\n. if n = 2 then ga else (kappa:A)))
                    ((0 %% 1) --> applyto_form 0 0 2)`
  ASSUME_TAC THENL
   [MATCH_MP_TAC EORDINAL_INDUCT THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [REWRITE_TAC[valuation] THEN GEN_TAC THEN
      COND_CASES_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    X_GEN_TAC `c:A` THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "ordc") (LABEL_TAC "rawIH")) THEN
    SUBGOAL_THEN `(c:A) IN D` (LABEL_TAC "cD") THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    ASM_SIMP_TAC[HOLDS_COLLFIX_PROP] THEN DISCH_TAC THEN
    SUBGOAL_THEN `!b:A. b IN D /\ (E:A->A->bool) b c ==> eapply D E ga b b`
     (LABEL_TAC "IH") THENL
     [X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) b kappa` ASSUME_TAC THENL
       [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
      SUBGOAL_THEN `holds D (E:A->A->bool)
                     ((0 |-> b) (\n. if n = 2 then ga else (kappa:A)))
                     ((0 %% 1) --> applyto_form 0 0 2)` ASSUME_TAC THENL
       [USE_THEN "rawIH" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`ga:A`;`b:A`]
        HOLDS_COLLFIX_PROP) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> FIRST_X_ASSUM(MP_TAC o EQ_MP th)) THEN
      DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (c:A) X /\ E (c:A) la` STRIP_ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
                  `c:A`] ECOLLTOWER_PI_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `i:A` STRIP_ASSUME_TAC) THEN
    SUBGOAL_THEN `i:A = c` ASSUME_TAC THENL
     [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;`ga:A`;
              `c:A`;`i:A`] ECOLLTOWER_PI_RECURRENCE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      EQ_TAC THENL
       [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
        SUBGOAL_THEN `eapply D (E:A->A->bool) ga (y:A) y` ASSUME_TAC THENL
         [USE_THEN "IH" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
        MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`X:A`;`a:A`;`za:A`;`la:A`;
                      `ga:A`;`y:A`;`z:A`;`y:A`] ECOLLTOWER_PI_SV) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[];
        DISCH_TAC THEN
        SUBGOAL_THEN `(E:A->A->bool) (z:A) kappa` ASSUME_TAC THENL
         [ASM_MESON_TAC[EORDINAL_TRANS_E]; ALL_TAC] THEN
        EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
         [ASM_MESON_TAC[]; USE_THEN "IH" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]];
      ASM_MESON_TAC[]];
    X_GEN_TAC `xi:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `holds D (E:A->A->bool)
                   ((0 |-> xi) (\n. if n = 2 then ga else (kappa:A)))
                   ((0 %% 1) --> applyto_form 0 0 2)` ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`ga:A`;`xi:A`]
      HOLDS_COLLFIX_PROP) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> FIRST_X_ASSUM(MP_TAC o EQ_MP th)) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ========================================================================= *)
(* Condensation: a subset of kappa in L survives the Mostowski collapse of a *)
(* hull into a transitive M' covered by the stages of D.                     *)
(*                                                                           *)
(* MPRIME_STAGES_OF_VL: a transitive M' IN D that satisfies zfw_ax and V=L   *)
(*   has every element inside a stage L(a) of D, with a an ordinal of M'.    *)
(* MPRIME_X_SURVIVES: if XX SUBSET kappa and kappa SUBSET hull, the collapse *)
(*   fixes XX (pi(XX) = XX), so E XX Mp. COLL_TOTAL gives iX = pi(XX) IN Mp; *)
(*   ECOLLTOWER_PI_RECURRENCE describes the members of iX as                 *)
(*   {pi(y) : y IN hull INTER XX}; COLL_FIXES_ORDINALS fixes each such       *)
(*   ordinal y < kappa, and ECOLLTOWER_PI_SV forces iX = XX by               *)
(*   extensionality.                                                         *)
(* ========================================================================= *)

let MPRIME_STAGES_OF_VL = prove
 (`!D (E:A->A->bool) Mp.
     model D E ZF_AX /\ Mp IN D /\ etransitive D E Mp /\
     model (\z. z IN D /\ E z Mp) E zfw_ax /\
     (!u. u IN D /\ E u Mp ==> elmem (\z. z IN D /\ E z Mp) E u)
     ==> (!u. u IN D /\ E u Mp
              ==> ?a y. a IN D /\ E a Mp /\ y IN D /\
                        eordinal D E a /\ elstage D E a y /\ E u y)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`] EOMEGA_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `om:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`om:A`] EHFSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `hf:A`) THEN
  MP_TAC(ISPECL [`D:A->bool`;`E:A->A->bool`;`2`] ENAT_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `two:A`) THEN
  X_GEN_TAC `u:A` THEN STRIP_TAC THEN
  SUBGOAL_THEN `elmem (\z. z IN D /\ (E:A->A->bool) z Mp) E u` MP_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  REWRITE_TAC[elmem; IN_SUBMODEL] THEN
  DISCH_THEN(X_CHOOSE_THEN `a:A` (X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Mp:A`;`a:A`]
           EORDINAL_SUBMODEL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(SUBST1_TAC o SYM) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `yD:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Mp:A`;`om:A`;`hf:A`;`two:A`;
                `a:A`;`yD:A`] ELSTAGE_ABSOLUTE_WCL_W_F) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  STRIP_TAC THEN
  SUBGOAL_THEN `(y:A) = yD` SUBST_ALL_TAC THENL
   [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`a:A`;`yD:A`] THEN ASM_REWRITE_TAC[]);;

let MPRIME_X_SURVIVES = prove
 (`!D (E:A->A->bool) Som za ld gd c Mp kappa XX.
     model D E ZF_AX /\ eordinal D E c /\
     Som IN D /\ za IN D /\ ld IN D /\ gd IN D /\ Mp IN D /\
     elstage D E c ld /\
     (!u. u IN D /\ E u Som ==> E u ld) /\
     ecolltower D E Som c za /\ eopair D E ld gd za /\
     (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
             ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
     (!v. v IN D
          ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p gd /\
               eopair D E u v p)) /\
     eordinal D E kappa /\ kappa IN D /\
     XX IN D /\ E XX Som /\
     (!xi. xi IN D /\ E xi XX ==> E xi kappa) /\
     (!xi. xi IN D /\ E xi kappa ==> E xi Som)
     ==> E XX Mp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
                `ld:A`;`Mp:A`] COLL_TOTAL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `XX:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `iX:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
                `kappa:A`] COLL_FIXES_ORDINALS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(LABEL_TAC "FIX") THEN
  SUBGOAL_THEN `iX:A = XX` SUBST_ALL_TAC THENL
   [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
    ASM_REWRITE_TAC[] THEN X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
            `XX:A`;`iX:A`] ECOLLTOWER_PI_RECURRENCE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(MP_TAC o SPEC `z:A`) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN EQ_TAC THENL
     [DISCH_THEN(X_CHOOSE_THEN `y:A` STRIP_ASSUME_TAC) THEN
      SUBGOAL_THEN `(E:A->A->bool) y kappa` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) y` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`y:A`]
               EORDINAL_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) gd y y` ASSUME_TAC THENL
       [USE_THEN "FIX" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
              `y:A`;`z:A`;`y:A`] ECOLLTOWER_PI_SV) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN SUBST_ALL_TAC THEN ASM_REWRITE_TAC[];
      DISCH_TAC THEN
      SUBGOAL_THEN `(E:A->A->bool) z kappa` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `(E:A->A->bool) z Som` ASSUME_TAC THENL
       [FIRST_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eordinal D (E:A->A->bool) z` ASSUME_TAC THENL
       [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`z:A`]
               EORDINAL_MEMBER) THEN
        ASM_REWRITE_TAC[]; ALL_TAC] THEN
      SUBGOAL_THEN `eapply D (E:A->A->bool) gd z z` ASSUME_TAC THENL
       [USE_THEN "FIX" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      EXISTS_TAC `z:A` THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* The Mostowski collapse map gd is a bijection from the hull Som onto its   *)
(* transitive image Mp, hence |Mp| = |Som|, and any injection of Som into kk *)
(* gives one of Mp into kk.                                                  *)
(*                                                                           *)
(* MPRIME_COLLAPSE_BIJ: ebij D E gd Som Mp from the collapse data (for an    *)
(*   extensional hull): the graph condition from the characterization of gd  *)
(*   (ECOLLTOWER_SND), EOPAIR_INJ and the membership characterization of Mp; *)
(*   totality is COLL_TOTAL, single-valuedness ECOLLTOWER_PI_SV, injectivity *)
(*   ECOLLTOWER_PI_INJ and surjectivity COLL_ONTO.                           *)
(* MPRIME_MP_CARD_LE: einj D E e Som kk ==> ?e'. einj D E e' Mp kk, via      *)
(*   EBIJ_SYM (gd^-1 : Mp -> Som), EBIJ_EINJ and EINJ_COMPOSE.               *)
(* ========================================================================= *)

let MPRIME_COLLAPSE_BIJ = prove
 (`!D (E:A->A->bool) Som za ld gd c Mp.
     model D E ZF_AX /\ eordinal D E c /\
     Som IN D /\ za IN D /\ ld IN D /\ gd IN D /\ Mp IN D /\
     elstage D E c ld /\
     (!u. u IN D /\ E u Som ==> E u ld) /\
     ecolltower D E Som c za /\ eopair D E ld gd za /\
     (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
             ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
     (!v. v IN D
          ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p gd /\
               eopair D E u v p))
     ==> ebij D E gd Som Mp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`]
         ECOLLTOWER_SND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  INTRO_TAC "@r ld' gacc gd'. rD ldD' gaccD gdD' rch elld' gacch gdch
             eopSND" THEN
  SUBGOAL_THEN `ld':A = ld /\ gd':A = gd`
    (CONJUNCTS_THEN2 SUBST_ALL_TAC SUBST_ALL_TAC) THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`ld':A`;`gd':A`;`ld:A`;`gd:A`;`za:A`]
           EOPAIR_INJ) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D /\ eapply D (E:A->A->bool) gd k t ==>
    E k Som /\ E t Mp`
   (LABEL_TAC "BND") THENL
   [MAP_EVERY X_GEN_TAC [`k:A`;`t:A`] THEN
    DISCH_THEN(CONJUNCTS_THEN2 (LABEL_TAC "kD")
               (CONJUNCTS_THEN2 (LABEL_TAC "tD")
                (MP_TAC o REWRITE_RULE[eapply]))) THEN
    DISCH_THEN(X_CHOOSE_THEN `pp:A`
               (CONJUNCTS_THEN2 (LABEL_TAC "eop") (LABEL_TAC "epg"))) THEN
    SUBGOAL_THEN `(pp:A) IN D` (LABEL_TAC "ppD") THENL
     [ASM_MESON_TAC[EOPAIR_IN]; ALL_TAC] THEN
    CONJ_TAC THENL
     [USE_THEN "gdch" (MP_TAC o SPEC `pp:A`) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th ->
                 MP_TAC(EQ_MP th (ASSUME `(E:A->A->bool) pp gd`))) THEN
      DISCH_THEN(X_CHOOSE_THEN `xx:A` (CONJUNCTS_THEN2 (LABEL_TAC "xxD")
        (X_CHOOSE_THEN `img:A`
         (CONJUNCTS_THEN2 (LABEL_TAC "imgD") STRIP_ASSUME_TAC)))) THEN
      SUBGOAL_THEN `k:A = xx` SUBST1_TAC THENL
       [MP_TAC(SPECL
               [`D:A->bool`;`E:A->A->bool`;`k:A`;`t:A`;`xx:A`;`img:A`;`pp:A`]
               EOPAIR_INJ) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(ACCEPT_TAC o CONJUNCT1); ALL_TAC] THEN
      FIRST_ASSUM ACCEPT_TAC;
      FIRST_ASSUM(fun th -> if is_forall(concl th) && free_in `Mp:A` (concl th)
                            then MP_TAC(SPEC `t:A` th) else NO_TAC) THEN
      ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
      DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
      MAP_EVERY EXISTS_TAC [`pp:A`;`k:A`] THEN ASM_REWRITE_TAC[]];
    ALL_TAC] THEN
  REWRITE_TAC[ebij] THEN REPEAT CONJ_TAC THENL
   [FIRST_ASSUM ACCEPT_TAC;
    USE_THEN "BND" ACCEPT_TAC;
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
            `ld:A`;`Mp:A`] COLL_TOTAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`k:A`;`t:A`;`t':A`] THEN STRIP_TAC THEN
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
            `k:A`;`t:A`;`t':A`] ECOLLTOWER_PI_SV) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    MAP_EVERY X_GEN_TAC [`k:A`;`k':A`;`t:A`] THEN STRIP_TAC THEN
    SUBGOAL_THEN `(E:A->A->bool) k Som /\ E t Mp`
      (ASSUME_TAC o CONJUNCT1) THENL
     [USE_THEN "BND" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) k' Som /\ E t Mp`
      (ASSUME_TAC o CONJUNCT1) THENL
     [USE_THEN "BND" MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
            `k:A`;`k':A`;`t:A`] ECOLLTOWER_PI_INJ) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC;
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;`gd:A`;
            `ld:A`;`Mp:A`] COLL_ONTO) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN DISCH_THEN ACCEPT_TAC]);;

let MPRIME_MP_CARD_LE = prove
 (`!D (E:A->A->bool) Som za ld gd c Mp kk e.
     model D E ZF_AX /\ eordinal D E c /\
     Som IN D /\ za IN D /\ ld IN D /\ gd IN D /\ Mp IN D /\
     elstage D E c ld /\
     (!u. u IN D /\ E u Som ==> E u ld) /\
     ecolltower D E Som c za /\ eopair D E ld gd za /\
     (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
             ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
     (!v. v IN D
          ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p gd /\
               eopair D E u v p)) /\
     kk IN D /\ einj D E e Som kk
     ==> ?e'. einj D E e' Mp kk`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`Som:A`;`za:A`;`ld:A`;`gd:A`;`c:A`;`Mp:A`]
         MPRIME_COLLAPSE_BIJ) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gd:A`;`Som:A`;`Mp:A`]
         EBIJ_SYM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `g:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`Mp:A`;`Som:A`]
         EBIJ_EINJ) THEN
  ASM_REWRITE_TAC[] THEN DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`e:A`;`Mp:A`;`Som:A`;`kk:A`]
    EINJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN EXISTS_TAC `h:A` THEN
  ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* Cardinality of the hull over an arbitrary transitive set. The counting    *)
(* lemmas for the hull only need the ambient set ya to be transitive         *)
(* (etransitive D E ya), not an L-stage: the wellorder ra is used only       *)
(* through its asymmetry, and the selection of least witnesses               *)
(* (ELWO_SELECT_W) is only needed for elementarity. This gives               *)
(* |Som| <= kappa for the collapse hull Som, which is built over the stage   *)
(* union w = UNION_{b<c} L(b) (transitive by STAGE_UNION_TRANSITIVE) rather  *)
(* than a single stage. The chain is EDCL_STEP_TR, EDCL_TOTAL_TR,            *)
(* DCL_TOTAL_CARD_TR, DCLSLICE_CARD_TR and DCLSTAGE_CARD_TR.                 *)
(* ========================================================================= *)

let EDCL_STEP_TR = prove
 (`!D (E:A->A->bool) a ra ya om hf z0 Y fsY v0.
     model D E ZF_AX /\ eordinal D E a /\ ra IN D /\ ya IN D /\
     etransitive D E ya /\ eomega D E om /\ hf IN D /\
     z0 IN D /\ Y IN D /\ fsY IN D /\ valuation D v0
     ==> ?W. W IN D /\
             !m. m IN D
                 ==> (E m W <=>
                      E m ya /\
                      (E m Y \/
                       ?c. c IN D /\ ?r. r IN D /\ E c hf /\ E r fsY /\
                             (E m ya /\
                              (?w. w IN D /\ eupdate D E r z0 m w /\
                                   (?pv. pv IN D /\
                                    (!b. b IN D ==> !u. u IN D ==>
                                     eapply D E w b u ==> eapply D E pv b u) /\
                                    esat D E ya c pv))) /\
                             (!aa. aa IN D
                                   ==> (E aa ya /\
                                        (?w. w IN D /\ eupdate D E r z0 aa w /\
                                             (?pv. pv IN D /\
                                                (!b. b IN D ==> !u. u IN D ==>
                                                eapply D E w b u ==>
                                                eapply D E pv b u) /\
                                                esat D E ya c pv))) /\
                                       ~(aa = m)
                                       ==> erel D E ra m aa)))`,
  REPEAT STRIP_TAC THEN
  ABBREV_TAC `vv = (43 |-> (ya:A)) ((44 |-> (z0:A)) ((45 |-> (ra:A))
                     ((53 |-> (Y:A)) ((54 |-> (hf:A)) ((55 |-> (fsY:A))
                       (v0:num->A))))))` THEN
  SUBGOAL_THEN `valuation D (vv:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "vv" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]);
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`] ZF_SEPARATION) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(MP_TAC o SPECL [`pdclf`; `40`; `vv:num->A`; `ya:A`]) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "sep"))) THEN
  EXISTS_TAC `W:A` THEN ASM_REWRITE_TAC[] THEN
  X_GEN_TAC `m:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN `valuation D ((40 |-> (m:A)) (vv:num->A))` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `holds D E ((40 |-> (m:A)) vv) pdclf <=>
    E m Y \/
    (?c. c IN D /\ ?r. r IN D /\ E c hf /\ E r fsY /\
           (E m ya /\
            (?w. w IN D /\ eupdate D E r z0 m w /\
             (?pv. pv IN D /\
              (!b. b IN D ==> !u. u IN D ==> eapply D E w b u ==>
               eapply D E pv b u) /\ esat D E ya c pv))) /\
           (!aa. aa IN D
                 ==> (E aa ya /\
                      (?w. w IN D /\ eupdate D E r z0 aa w /\
                       (?pv. pv IN D /\
                        (!b. b IN D ==> !u. u IN D ==> eapply D E w b u ==>
                         eapply D E pv b u) /\ esat D E ya c pv))) /\
                     ~(aa = m)
                     ==> erel D E ra m aa))`
  ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `(40 |-> (m:A)) vv`]
      HOLDS_PDCLF) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    EXPAND_TAC "vv" THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE
     `~(40 = 43) /\ ~(40 = 44) /\ ~(40 = 45) /\ ~(40 = 53) /\ ~(40 = 54) /\
      ~(40 = 55) /\ ~(43 = 44) /\ ~(43 = 45) /\ ~(43 = 53) /\ ~(43 = 54) /\
      ~(43 = 55) /\ ~(44 = 45) /\ ~(44 = 53) /\ ~(44 = 54) /\ ~(44 = 55) /\
      ~(45 = 53) /\ ~(45 = 54) /\ ~(45 = 55) /\ ~(53 = 54) /\ ~(53 = 55) /\
      ~(54 = 55)`];
    ALL_TAC] THEN
  USE_THEN "sep" (MP_TAC o SPEC `m:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(fun th -> ASM_REWRITE_TAC[th]));;

let EDCL_TOTAL_TR = prove
 (`!D (E:A->A->bool) a ra ya om hf z0 Y v0.
     model D E ZF_AX /\ eordinal D E a /\ ra IN D /\ ya IN D /\
     etransitive D E ya /\ eomega D E om /\ hf IN D /\
     z0 IN D /\ Y IN D /\ (!m. m IN D /\ E m Y ==> E m ya) /\ valuation D v0
     ==> ?W fsY.
             W IN D /\ fsY IN D /\
             (!r. r IN D
                  ==> (E r fsY <=>
                       eisfun D E r /\
                       (?n. n IN D /\ E n om /\ edomain D E r n) /\
                       (!i u. i IN D /\ u IN D /\
                        eapply D E r i u ==> E u Y))) /\
             (!m. m IN D
                  ==> (E m W <=>
                       E m ya /\
                       (E m Y \/
                        ?c. c IN D /\ ?r. r IN D /\ E c hf /\ E r fsY /\
                            (E m ya /\
                             (?w. w IN D /\ eupdate D E r z0 m w /\
                                  (?pv. pv IN D /\
                                   (!b. b IN D ==> !u. u IN D ==>
                                    eapply D E w b u ==> eapply D E pv b u) /\
                                   esat D E ya c pv))) /\
                            (!aa. aa IN D
                                  ==> (E aa ya /\
                                       (?w. w IN D /\ eupdate D E r z0 aa w /\
                                            (?pv. pv IN D /\
                                                (!b. b IN D ==> !u. u IN D ==>
                                                eapply D E w b u ==>
                                                eapply D E pv b u) /\
                                                esat D E ya c pv))) /\
                                      ~(aa = m)
                                      ==> erel D E ra m aa)))) /\
             (!m. m IN D /\ E m Y ==> E m W) /\
             (!m. m IN D /\ E m W ==> E m ya)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `Y:A`]
         EFINSEQ_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `fsY:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "fs"))) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`; `ya:A`; `om:A`;
    `hf:A`; `z0:A`; `Y:A`; `fsY:A`; `v0:num->A`] EDCL_STEP_TR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A`
             (CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "dc"))) THEN
  MAP_EVERY EXISTS_TAC [`W:A`; `fsY:A`] THEN
  ASM_REWRITE_TAC[] THEN
  REPEAT CONJ_TAC THEN X_GEN_TAC `m:A` THEN STRIP_TAC THEN
  USE_THEN "dc" (MP_TAC o SPEC `m:A`) THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

let DCL_TOTAL_CARD_TR = prove
 (`!D (E:A->A->bool) om hf ho a ra ya kk eY Y zr on v0.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\ eomega D E om /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\ kk IN D /\
     ehfset D E om hf /\ ehford D E om ho /\ hf IN D /\
     eordinal D E a /\ ra IN D /\ ya IN D /\
     etransitive D E ya /\
     (!p q. p IN D /\ q IN D /\ erel D E ra p q ==> ~(erel D E ra q p)) /\
     z0 IN D /\ Y IN D /\ einj D E eY Y kk /\
     (!m. m IN D /\ E m Y ==> E m ya) /\
     zr IN D /\ on IN D /\ E zr kk /\ E on kk /\ ~(zr = on) /\ valuation D v0
     ==> ?W fsY.
             W IN D /\ fsY IN D /\
             (!r. r IN D
                  ==> (E r fsY <=>
                       eisfun D E r /\
                       (?n. n IN D /\ E n om /\ edomain D E r n) /\
                       (!i u. i IN D /\ u IN D /\
                        eapply D E r i u ==> E u Y))) /\
             (!m. m IN D
                  ==> (E m W <=>
                       E m ya /\
                       (E m Y \/
                        ?c. c IN D /\ ?r. r IN D /\ E c hf /\ E r fsY /\
                            (E m ya /\
                             (?w. w IN D /\ eupdate D E r z0 m w /\
                                  (?pv. pv IN D /\
                                   (!b. b IN D ==> !u. u IN D ==>
                                    eapply D E w b u ==> eapply D E pv b u) /\
                                   esat D E ya c pv))) /\
                            (!aa. aa IN D
                                  ==> (E aa ya /\
                                       (?w. w IN D /\ eupdate D E r z0 aa w /\
                                            (?pv. pv IN D /\
                                                (!b. b IN D ==> !u. u IN D ==>
                                                eapply D E w b u ==>
                                                eapply D E pv b u) /\
                                                esat D E ya c pv))) /\
                                      ~(aa = m)
                                      ==> erel D E ra m aa)))) /\
             (!m. m IN D /\ E m Y ==> E m W) /\
             (!m. m IN D /\ E m W ==> E m ya) /\
             (?e. einj D E e W kk)`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `a:A`; `ra:A`; `ya:A`; `om:A`;
    `hf:A`; `z0:A`; `Y:A`; `v0:num->A`] EDCL_TOTAL_TR) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `W:A` (X_CHOOSE_THEN `fsY:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `hf:A`; `fsY:A`]
         ECROSS_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_TAC `cp:A`) THEN
  SUBGOAL_THEN `(cp:A) IN D` ASSUME_TAC THENL
   [ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[ecross]
      (ASSUME `ecross D (E:A->A->bool) hf fsY cp`))); ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`W:A`; `fsY:A`] THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `ho:A`; `Y:A`;
    `kk:A`; `eY:A`; `fsY:A`; `cp:A`; `ya:A`; `ra:A`; `z0:A`; `zr:A`; `on:A`;
    `W:A`] DCL_CARD_PAD) THEN
  ASM_REWRITE_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* DCLSLICE_CARD_TR: if Y >-> kk then the slice W = dcl(Y) of the hull       *)
(* family injects into kk (by DCL_TOTAL_CARD_TR). DCLSTAGE_CARD_TR, the      *)
(* cardinality bound for the hull: for every ordinal a, if a >-> kk then     *)
(* pdclstage(a) >-> kk. By EORDINAL_INDUCT on pdclcard_form: the induction   *)
(* hypothesis restricted to the earlier stages (EINJ_RESTRICT_DOM,           *)
(* EORDINAL_TRANS_MEM) gives the family of slices (EDCLIMG_FAMILY_PAD) and   *)
(* its union (EDCLIMG_WUN_PAD); each slice is bounded by DCLSLICE_CARD_TR,   *)
(* the union by EGEN_UNION_CARD_LE, and the decomposition DCLSTAGE_CHAR_PAD  *)
(* with EINJ_UNION2 finishes the step. The valuation carries g0, ya, hf, z0, *)
(* fs(ya) and ra in slots 5 to 10, and kk in slot 33.                        *)
(* ------------------------------------------------------------------------- *)

let DCLSLICE_CARD_TR = prove
 (`!D (E:A->A->bool) om hf ho a ra ya kk eY Y zr on z0 v0 v b W.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\ eomega D E om /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\ kk IN D /\
     ehfset D E om hf /\ ehford D E om ho /\ hf IN D /\
     eordinal D E a /\ ra IN D /\ ya IN D /\
     etransitive D E ya /\
     (!p q. p IN D /\ q IN D /\ erel D E ra p q ==> ~(erel D E ra q p)) /\
     z0 IN D /\ Y IN D /\ einj D E eY Y kk /\
     (!m. m IN D /\ E m Y ==> E m ya) /\
     zr IN D /\ on IN D /\ E zr kk /\ E on kk /\ ~(zr = on) /\
       valuation D v0 /\
     valuation D v /\ v 6 = ya /\ v 7 = hf /\ v 8 = z0 /\ v 10 = ra /\
     (!r. r IN D
          ==> (E r (v 9) <=>
               eisfun D E r /\ (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!i u. i IN D /\ u IN D /\ eapply D E r i u ==> E u ya))) /\
     b IN D /\ W IN D /\
     (!m. m IN D
          ==> (E m W <=>
               holds D E ((4 |-> Y) ((2 |-> m) ((63 |-> W) ((11 |-> b) v))))
                 pdclmem_form))
     ==> ?e. einj D E e W kk`,
