let DCLSTAGE_CARD_TR = prove
 (`!D (E:A->A->bool) om hf ho alpha ra ya kk g0 fsY eg0 zr on z0 v0 v.
     model D E ZF_AX /\ (!w. w IN D ==> elmem D E w) /\
       eomega D E om /\ om IN D /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\ kk IN D /\
     ehfset D E om hf /\ ehford D E om ho /\ hf IN D /\
     eordinal D E alpha /\ ra IN D /\ ya IN D /\
     etransitive D E ya /\
     (!p q. p IN D /\ q IN D /\ erel D E ra p q ==> ~(erel D E ra q p)) /\
     z0 IN D /\ g0 IN D /\ fsY IN D /\
     einj D E eg0 g0 kk /\ (!u. u IN D /\ E u g0 ==> E u ya) /\
     zr IN D /\ on IN D /\ E zr kk /\ E on kk /\ ~(zr = on) /\
       valuation D v0 /\
     valuation D v /\ v 5 = g0 /\ v 6 = ya /\ v 7 = hf /\ v 8 = z0 /\
     v 9 = fsY /\ v 10 = ra /\ v 33 = kk /\
     (!r. r IN D
          ==> (E r fsY <=>
               eisfun D E r /\ (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!i u. i IN D /\ u IN D /\ eapply D E r i u ==> E u ya)))
     ==> !a. eordinal D E a
             ==> (?e. e IN D /\ einj D E e a kk)
                 ==> ?y. y IN D /\ pdclstage D E g0 ya hf z0 fsY ra a y /\
                         ?e. e IN D /\ einj D E e y kk`,
