(* ========================================================================= *)
(* The collapse of the hull, with the cardinality bound. SOM_CARD_LE: the    *)
(* hull Som over a transitive w, seeded with g0 >-> kk, injects into kk (by  *)
(* DCLSTAGE_CARD_TR).                                                        *)
(* MPRIME_COLLAPSE_EXISTS_WA: in a model of V=L, for a union w of stages     *)
(*   L(b), b < c, that satisfies zfw_ax and V=L, and a nonempty seed         *)
(*   g0 SUBSET w with g0 >-> kk, there is a hull Som containing g0 whose     *)
(*   collapse Mp is transitive, satisfies zfw_ax and V=L, and has            *)
(*   |Mp| <= kk. The conclusion exposes the whole collapse data (Mp, the     *)
(*   hull Som, the tower za, the domain stage ld = L(c) and the map graph    *)
(*   gd) with the ecolltower/eopair bundle, the extensionality of the hull,  *)
(*   the membership characterization of Mp, hull SUBSET ld and seed SUBSET   *)
(*   hull, as needed by MPRIME_X_SURVIVES.                                   *)
(* MPRIME_COLLAPSE_EXISTS: the same for a seed g0 inside the stages below    *)
(*   a0: WVL_REFLECT and ERAU_EXISTS build c, w and ra from a0, and the      *)
(*   conclusion also gives the ordinal c.                                    *)
(* ========================================================================= *)

let SOM_CARD_LE = prove
 (`!D (E:A->A->bool) w ra g0 om hf z0 fsY Som kk eg0 v0.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ om IN D /\
     ecardinal D E kk /\ (E om kk \/ om = kk) /\ kk IN D /\
     ehfset D E om hf /\ hf IN D /\
     ra IN D /\ w IN D /\ etransitive D E w /\
     (!p q. p IN D /\ q IN D /\ erel D E ra p q ==> ~(erel D E ra q p)) /\
     z0 IN D /\ g0 IN D /\ fsY IN D /\
     einj D E eg0 g0 kk /\ (!u. u IN D /\ E u g0 ==> E u w) /\
       valuation D v0 /\
     (!r. r IN D
          ==> (E r fsY <=>
               eisfun D E r /\ (?n. n IN D /\ E n om /\ edomain D E r n) /\
               (!i u. i IN D /\ u IN D /\ eapply D E r i u ==> E u w))) /\
     Som IN D /\ pdclstage D E g0 w hf z0 fsY ra om Som
     ==> ?e. e IN D /\ einj D E e Som kk`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kk` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `!t. t IN D /\ (E:A->A->bool) t om ==> E t kk`
   (LABEL_TAC "omsub") THENL
   [X_GEN_TAC `t:A` THEN STRIP_TAC THEN
    UNDISCH_TAC `(E:A->A->bool) om kk \/ om = kk` THEN STRIP_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `kk:A`; `om:A`; `t:A`]
        EORDINAL_TRANS_MEM) THEN ASM_REWRITE_TAC[];
      ASM_MESON_TAC[]];
    ALL_TAC] THEN
  SUBGOAL_THEN `?ho:A. ehford D (E:A->A->bool) om ho`
    (X_CHOOSE_TAC `ho:A`) THENL
   [ASM_MESON_TAC[EHFORD_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?zr:A. enat D (E:A->A->bool) 0 zr` (X_CHOOSE_TAC `zr:A`) THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `?on:A. enat D (E:A->A->bool) 1 on` (X_CHOOSE_TAC `on:A`) THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN
   `(zr:A) IN D /\ (E:A->A->bool) zr om /\ (on:A) IN D /\
    E on om /\ ~(zr = on)`
   STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THENL
     [ASM_MESON_TAC[ENAT_IN];
      ASM_MESON_TAC[ENAT_IN_OMEGA];
      ASM_MESON_TAC[ENAT_IN];
      ASM_MESON_TAC[ENAT_IN_OMEGA];
      ASM_MESON_TAC[ENAT_INJ; ARITH_RULE `~(0 = 1)`]];
    ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) zr kk /\ E on kk` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN USE_THEN "omsub" MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ABBREV_TAC
   `v = (5 |-> (g0:A)) ((6 |-> w) ((7 |-> hf) ((8 |-> z0)
        ((9 |-> fsY) ((10 |-> ra) ((33 |-> kk) (v0:num->A)))))))` THEN
  SUBGOAL_THEN `valuation D (v:num->A)` ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN
    REPEAT(MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]); ALL_TAC] THEN
  SUBGOAL_THEN
   `(v:num->A) 5 = g0 /\ v 6 = w /\ v 7 = hf /\ v 8 = z0 /\
    v 9 = fsY /\ v 10 = ra /\ v 33 = kk`
   STRIP_ASSUME_TAC THENL
   [EXPAND_TAC "v" THEN REWRITE_TAC[VALMOD] THEN
    CONV_TAC(ONCE_DEPTH_CONV NUM_REDUCE_CONV) THEN REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `hf:A`; `ho:A`; `om:A`;
     `ra:A`; `w:A`; `kk:A`; `g0:A`; `fsY:A`; `eg0:A`; `zr:A`; `on:A`; `z0:A`;
     `v0:num->A`; `v:num->A`] DCLSTAGE_CARD_TR) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `om:A`) THEN
  ANTS_TAC THENL [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  ANTS_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `idom:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `einj D (E:A->A->bool) idom om kk` ASSUME_TAC THENL
     [MATCH_MP_TAC EINJ_WEAKEN THEN EXISTS_TAC `om:A` THEN CONJ_TAC THENL
       [MATCH_MP_TAC EBIJ_EINJ THEN ASM_REWRITE_TAC[];
        USE_THEN "omsub" ACCEPT_TAC];
      ALL_TAC] THEN
    EXISTS_TAC `idom:A` THEN ASM_REWRITE_TAC[] THEN
    FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[einj] th)));
    ALL_TAC] THEN
  INTRO_TAC "@y. h1 psy h2" THEN
  SUBGOAL_THEN `(y:A) = Som` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `om:A`; `y:A`;
      `Som:A`] DCLSTAGE_UNIQUE_PAD) THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  FIRST_X_ASSUM ACCEPT_TAC);;

let MPRIME_COLLAPSE_EXISTS_WA = prove
 (`!D (E:A->A->bool) c w ra g0 kk eg0.
     model D E ZF_AX /\ eordinal D E c /\ w IN D /\
     (!u. u IN D
          ==> (E u w <=>
               ?b z. b IN D /\ z IN D /\ E b c /\ elstage D E b z /\ E u z)) /\
     model (\z. z IN D /\ E z w) E zfw_ax /\
     (!v. (!i. (v:num->A) i IN D /\ E (v i) w)
          ==> holds (\z. z IN D /\ E z w) E v vl_form) /\
     ra IN D /\
     (!q. q IN D
          ==> (E q ra <=>
               ?b rb. b IN D /\ rb IN D /\ E b c /\
                 elwou D E b rb /\ E q rb)) /\
     g0 IN D /\ (!u. u IN D /\ E u g0 ==> E u w) /\
       (?u0. u0 IN D /\ E u0 g0) /\
     (!u. u IN D ==> elmem D E u) /\
     ecardinal D E kk /\ kk IN D /\
     (!oi. eomega D E oi ==> E oi kk \/ oi = kk) /\
     einj D E eg0 g0 kk
     ==> ?Mp Som za ld gd.
              Mp IN D /\ etransitive D E Mp /\
              model (\z. z IN D /\ E z Mp) E zfw_ax /\
              (!u. u IN D /\ E u Mp ==> elmem (\z. z IN D /\ E z Mp) E u) /\
              Som IN D /\ za IN D /\ ld IN D /\ gd IN D /\
              elstage D E c ld /\
              (!u. u IN D /\ E u Som ==> E u ld) /\
              ecolltower D E Som c za /\ eopair D E ld gd za /\
              (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
                      ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
              (!v. v IN D
                   ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p gd /\
                        eopair D E u v p)) /\
              (!u. u IN D /\ E u g0 ==> E u Som) /\
              (?e. e IN D /\ einj D E e Mp kk)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `?vv:num->A. valuation D vv` (X_CHOOSE_TAC `v0:num->A`) THENL
   [ASM_MESON_TAC[VALUATION_EXISTS; MODEL_NONEMPTY]; ALL_TAC] THEN
  FIRST_ASSUM(X_CHOOSE_TAC `om:A` o MATCH_MP EOMEGA_EXISTS) THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[EOMEGA_ORDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `?hf:A. ehfset D E om hf` (X_CHOOSE_TAC `hf:A`) THENL
   [ASM_MESON_TAC[EHFSET_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(hf:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ehfset]; ALL_TAC] THEN
  SUBGOAL_THEN `?z0:A. enat D E 0 z0` (X_CHOOSE_TAC `z0:A`) THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(z0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (z0:A) om` ASSUME_TAC THENL
   [ASM_MESON_TAC[ENAT_IN_OMEGA]; ALL_TAC] THEN
  SUBGOAL_THEN `?two:A. enat D E 2 two` (X_CHOOSE_TAC `two:A`) THENL
   [ASM_MESON_TAC[ENAT_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`w:A`] EFINSEQ_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `fsY:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `?vs:A. efuns D E om w vs` (X_CHOOSE_TAC `vs:A`) THENL
   [ASM_MESON_TAC[EFUNS_EXISTS]; ALL_TAC] THEN
  SUBGOAL_THEN `(vs:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[efuns]; ALL_TAC] THEN
  SUBGOAL_THEN `?u2:A. esatuniv D E w u2` (X_CHOOSE_TAC `u2:A`) THENL
   [ASM_MESON_TAC[ESATUNIV_EXISTS]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;
                `fsY:A`;`ra:A`;`om:A`] DCLSTAGE_EXISTS_PAD) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `Som:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u Som ==> E u w` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;
                       `fsY:A`;`ra:A`;`om:A`;`Som:A`] DCLSTAGE_SUB_PAD) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) (u0:A) Som` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;
                 `fsY:A`;`ra:A`;`om:A`;`Som:A`;`u0:A`]
                  DCLSTAGE_CHAR_CONV_PAD) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?s0:A. evaluation D (E:A->A->bool) om Som s0`
    (X_CHOOSE_TAC `s0:A`) THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`Som:A`;`u0:A`]
           ECONSTFUN) THEN
    ASM_REWRITE_TAC[] THEN MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`]
         ECOLLTOWER_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `za:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`]
         ECOLLTOWER_SND) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_THEN `rc:A` (X_CHOOSE_THEN `ld:A` (X_CHOOSE_THEN `gacc:A`
    (X_CHOOSE_THEN `gd:A` STRIP_ASSUME_TAC)))) THEN
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u w ==> E u ld` ASSUME_TAC THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?b z. b IN D /\ z IN D /\ E b c /\
                        elstage D (E:A->A->bool) b z /\ E u z`
      STRIP_ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`b:A`;`z:A`;`ld:A`]
           ELSTAGE_LE) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u Som ==> E u ld` ASSUME_TAC THENL
   [MP_TAC(ASSUME `!u. u IN D /\ (E:A->A->bool) u Som ==> E u w`) THEN
    MP_TAC(ASSUME `!u. u IN D /\ (E:A->A->bool) u w ==> E u ld`) THEN
    MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`gd:A`] ECOLLRANGE_EXISTS) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(X_CHOOSE_THEN `Mp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `!x x'. x IN D /\ x' IN D /\ (E:A->A->bool) x Som /\ E x' Som /\
                       ~(x = x')
                       ==> ?u. u IN D /\ E u Som /\ ~(E u x <=> E u x')`
    ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;
                       `fsY:A`;`ra:A`;`c:A`;`om:A`;`Som:A`;`vs:A`;
                       `u2:A`;`two:A`;
                       `v0:num->A`;`0`] SOM_EXTENSIONAL_WA) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!v. v IN D ==> ((E:A->A->bool) v Mp <=>
                    ?p u. p IN D /\ u IN D /\ E p gd /\ eopair D E u v p)`
    ASSUME_TAC THENL
   [RULE_ASSUM_TAC(REWRITE_RULE[RIGHT_AND_EXISTS_THM]) THEN
    FIRST_X_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `model (\z. z IN D /\ (E:A->A->bool) z Mp) E zfw_ax /\
                (!u. u IN D /\ E u Mp ==> elmem (\z. z IN D /\ E z Mp) E u)`
   STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;`fsY:A`;
            `ra:A`;`c:A`;`om:A`;`Som:A`;`vs:A`;`u2:A`;`two:A`;`v0:num->A`;`0`;
                  `s0:A`;`za:A`;`ld:A`;`gd:A`;`ld:A`;`Mp:A`]
             MPRIME_VL_FROM_YA) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]; ALL_TAC] THEN
  SUBGOAL_THEN `etransitive D (E:A->A->bool) Mp` ASSUME_TAC THENL
   [REWRITE_TAC[etransitive; esubset] THEN
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`c:A`;`za:A`;`ld:A`;
            `gd:A`;`Mp:A`]
           ECOLLRANGE_TRANS) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!u. u IN D /\ (E:A->A->bool) u g0 ==> E u Som` ASSUME_TAC THENL
   [X_GEN_TAC `uu:A` THEN STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`;`w:A`;`hf:A`;`z0:A`;
                  `fsY:A`;`ra:A`;`om:A`;`Som:A`;`uu:A`]
             DCLSTAGE_CHAR_CONV_PAD) THEN
    DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?e. e IN D /\ einj (D:A->bool) (E:A->A->bool) e Mp kk`
    ASSUME_TAC THENL
   [SUBGOAL_THEN `etransitive D (E:A->A->bool) w` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`w:A`]
        STAGE_UNION_TRANSITIVE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) om kk \/ om = kk` ASSUME_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `!p q. p IN D /\ q IN D /\ erel D (E:A->A->bool) ra p q
                        ==> ~(erel D E ra q p)` ASSUME_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`ra:A`]
                   RA_ASYM) THEN
      ASM_REWRITE_TAC[] THEN X_GEN_TAC `b:A` THEN STRIP_TAC THEN
      MATCH_MP_TAC ELWOU_INVARIANT THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`b:A`]
                   EORDINAL_MEMBER) THEN
      ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`w:A`;`ra:A`;`g0:A`;`om:A`;`hf:A`;
                  `z0:A`;`fsY:A`;`Som:A`;`kk:A`;`eg0:A`;`v0:num->A`]
        SOM_CARD_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `es:A`
               (CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC)) THEN
    MP_TAC(SPECL
           [`D:A->bool`;`E:A->A->bool`;`Som:A`;`za:A`;`ld:A`;`gd:A`;`c:A`;
            `Mp:A`;`kk:A`;`es:A`] MPRIME_MP_CARD_LE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_TAC `em:A`) THEN EXISTS_TAC `em:A` THEN
    CONJ_TAC THENL
     [FIRST_ASSUM(fun th -> ACCEPT_TAC(CONJUNCT1(REWRITE_RULE[einj] th)));
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`Mp:A`;`Som:A`;`za:A`;`ld:A`;`gd:A`] THEN
  ASM_REWRITE_TAC[]);;

let MPRIME_COLLAPSE_EXISTS = prove
 (`!D (E:A->A->bool) a0 g0 kk eg0.
     model D E ZF_AX /\ eordinal D E a0 /\ a0 IN D /\
     g0 IN D /\ (?u0. u0 IN D /\ E u0 g0) /\
     (!u. u IN D /\ E u g0
          ==> ?b y. b IN D /\ y IN D /\ E b a0 /\ elstage D E b y /\ E u y) /\
     (!u. u IN D ==> elmem D E u) /\
     ecardinal D E kk /\ kk IN D /\
     (!oi. eomega D E oi ==> E oi kk \/ oi = kk) /\
     einj D E eg0 g0 kk
     ==> ?Mp Som za ld gd c.
              eordinal D E c /\
              Mp IN D /\ etransitive D E Mp /\
              model (\z. z IN D /\ E z Mp) E zfw_ax /\
              (!u. u IN D /\ E u Mp ==> elmem (\z. z IN D /\ E z Mp) E u) /\
              Som IN D /\ za IN D /\ ld IN D /\ gd IN D /\
              elstage D E c ld /\
              (!u. u IN D /\ E u Som ==> E u ld) /\
              ecolltower D E Som c za /\ eopair D E ld gd za /\
              (!y y'. y IN D /\ y' IN D /\ E y Som /\ E y' Som /\ ~(y = y')
                      ==> ?u. u IN D /\ E u Som /\ ~(E u y <=> E u y')) /\
              (!v. v IN D
                   ==> (E v Mp <=> ?p u. p IN D /\ u IN D /\ E p gd /\
                        eopair D E u v p)) /\
              (!u. u IN D /\ E u g0 ==> E u Som) /\
              (?e. e IN D /\ einj D E e Mp kk)`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`] WVL_REFLECT) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `c:A` (X_CHOOSE_THEN `w:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`] ERAU_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ra:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`c:A`;`w:A`;`ra:A`;`g0:A`;`kk:A`;`eg0:A`]
         MPRIME_COLLAPSE_EXISTS_WA) THEN
  ANTS_TAC THENL
   [ASM_REWRITE_TAC[] THEN CONJ_TAC THENL
     [ALL_TAC; ASM_MESON_TAC[]] THEN
    X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `?b y. b IN D /\ y IN D /\ E b a0 /\
                        elstage D (E:A->A->bool) b y /\ E u y`
      STRIP_ASSUME_TAC THENL
     [FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `(E:A->A->bool) (b:A) (c:A)` ASSUME_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`c:A`;`b:A`;`a0:A`]
        EORDINAL_TRANS_E) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_X_ASSUM(fun th ->
       if is_forall(concl th) && free_in `w:A` (concl th) &&
          not(free_in `ra:A` (concl th)) && not(free_in `g0:A` (concl th))
       then MP_TAC(SPEC `u:A` th) else NO_TAC) THEN
    ASM_REWRITE_TAC[] THEN DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MAP_EVERY EXISTS_TAC [`b:A`;`y:A`] THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Mp:A` (X_CHOOSE_THEN `Som:A` (X_CHOOSE_THEN `za:A`
    (X_CHOOSE_THEN `ld:A` (X_CHOOSE_THEN `gd:A` STRIP_ASSUME_TAC))))) THEN
  MAP_EVERY EXISTS_TAC [`Mp:A`;`Som:A`;`za:A`;`ld:A`;`gd:A`;`c:A`] THEN
  ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* An ordinal a that injects into an infinite cardinal kk lies below the     *)
(* successor cardinal kp = kk+ (EORDINAL_INJ_LT_SUCCARD):                    *)
(* einj a kk ==> a < kk+. Proof by trichotomy on a and kp. If ~E a kp then   *)
(* kp SUBSET a, so the identity gives einj kp a (EBIJ_ID, EINJ_WEAKEN);      *)
(* composing with einj a kk gives einj kp kk; EINJ_ORDINAL_CARD_LE with      *)
(* ecardof kp = kp forces E kp kk or kp = kk; with E kk kp and transitivity  *)
(* this yields E kk kk, contradicting E_IRREFL.                              *)
(* ------------------------------------------------------------------------- *)

let EORDINAL_INJ_LT_SUCCARD = prove
 (`!D (E:A->A->bool) a kk kp f.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     a IN D /\ eordinal D E a /\
     kk IN D /\
     kp IN D /\ ecardinal D E kp /\ E kk kp /\
     einj D E f a kk
     ==> E a kp`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kk` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kp:A`;`kk:A`]
                 EORDINAL_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardof D (E:A->A->bool) kp kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a:A`;`kp:A`]
         EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  ASM_CASES_TAC `(E:A->A->bool) a kp` THENL
   [FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `!t. t IN D /\ (E:A->A->bool) t kp ==> E t a` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_MEM_TRANS]; ALL_TAC] THEN
  SUBGOAL_THEN `?g. einj D (E:A->A->bool) g kp kk` STRIP_ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kp:A`] EBIJ_ID) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `h:A` ASSUME_TAC) THEN
    SUBGOAL_THEN `einj D (E:A->A->bool) h kp a` ASSUME_TAC THENL
     [MATCH_MP_TAC EINJ_WEAKEN THEN EXISTS_TAC `kp:A` THEN CONJ_TAC THENL
       [MATCH_MP_TAC EBIJ_EINJ THEN FIRST_ASSUM ACCEPT_TAC;
        ASM_REWRITE_TAC[]];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`h:A`;`f:A`;`kp:A`;`a:A`;`kk:A`]
      EINJ_COMPOSE) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g:A`;`kp:A`;`kk:A`;`kp:A`]
    EINJ_ORDINAL_CARD_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `(E:A->A->bool) kk kk` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kk:A`;`kp:A`;`kk:A`]
      EORDINAL_MEM_TRANS) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[E_IRREFL]);;

(* ------------------------------------------------------------------------- *)
(* The condensation seed g0 = kappa UNION {XX} (GCH_SEED_EXISTS). For an     *)
(* infinite cardinal kappa and any XX IN D, there is g0 IN D whose members   *)
(* are exactly the members of kappa together with XX, with an injection of   *)
(* g0 into kappa (|kappa UNION {XX}| = kappa). g0 = UNION {kappa, {XX}} via  *)
(* EPAIR_EXISTS and EUNION_EXISTS; the injection is the identity on kappa    *)
(* when XX IN kappa (then g0 = kappa by extensionality), and otherwise comes *)
(* from EINJ_INSERT_INFINITE.                                                *)
(* ------------------------------------------------------------------------- *)

let GCH_SEED_EXISTS = prove
 (`!D (E:A->A->bool) kappa XX om.
     model D E ZF_AX /\
     eomega D E om /\ (E om kappa \/ om = kappa) /\
     ecardinal D E kappa /\ kappa IN D /\ XX IN D
     ==> ?g0 eg0. g0 IN D /\
                  (!z. z IN D ==> (E z g0 <=> E z kappa \/ z = XX)) /\
                  (?u0. u0 IN D /\ E u0 g0) /\
                  einj D E eg0 g0 kappa`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`XX:A`;`XX:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `sX:A`) THEN
  SUBGOAL_THEN `(sX:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`sX:A`] EPAIR_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `p2:A`) THEN
  SUBGOAL_THEN `(p2:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epair]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`p2:A`] EUNION_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `g0:A`) THEN
  SUBGOAL_THEN `(g0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eunion]; ALL_TAC] THEN
  SUBGOAL_THEN `!z. z IN D ==> ((E:A->A->bool) z g0 <=> E z kappa \/ z = XX)`
   (LABEL_TAC "g0char") THENL
   [X_GEN_TAC `z:A` THEN DISCH_TAC THEN
    UNDISCH_TAC `eunion D (E:A->A->bool) p2 g0` THEN
    UNDISCH_TAC `epair D (E:A->A->bool) kappa sX p2` THEN
    UNDISCH_TAC `epair D (E:A->A->bool) XX XX sX` THEN
    REWRITE_TAC[eunion; epair] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) XX g0` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `?eg0. einj D (E:A->A->bool) eg0 g0 kappa`
    STRIP_ASSUME_TAC THENL
   [ASM_CASES_TAC `(E:A->A->bool) XX kappa` THENL
     [SUBGOAL_THEN `(g0:A) = kappa` ASSUME_TAC THENL
       [FIRST_ASSUM(MATCH_MP_TAC o MATCH_MP ZF_EXTENSIONALITY) THEN
        ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`] EBIJ_ID) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `h:A`) THEN EXISTS_TAC `h:A` THEN
      MATCH_MP_TAC EBIJ_EINJ THEN ASM_REWRITE_TAC[];
      MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`] EBIJ_ID) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `idk:A`) THEN
      SUBGOAL_THEN `einj D (E:A->A->bool) idk kappa kappa` ASSUME_TAC THENL
       [MATCH_MP_TAC EBIJ_EINJ THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
      MP_TAC(SPECL
             [`D:A->bool`;`E:A->A->bool`;`om:A`;`kappa:A`;`kappa:A`;`g0:A`;
              `idk:A`;`XX:A`] EINJ_INSERT_INFINITE) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN(X_CHOOSE_TAC `e:A`) THEN EXISTS_TAC `e:A` THEN
      FIRST_ASSUM ACCEPT_TAC];
    ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`g0:A`;`eg0:A`] THEN ASM_REWRITE_TAC[] THEN
  ASM_MESON_TAC[]);;

(* ------------------------------------------------------------------------- *)
(* The main condensation step (GCH_SUBSET_IN_SUCCARD_STAGE). In a model of   *)
(* ZF + V=L, every subset XX of an infinite cardinal kappa is in the L-stage *)
(* of the successor cardinal kappa+: XX SUBSET kappa ==> XX IN L(kappa+).    *)
(*                                                                           *)
(* Proof: the seed g0 = kappa UNION {XX} has |g0| <= kappa                   *)
(* (GCH_SEED_EXISTS); g0 lies inside a single L-stage L(cb) (ELMEM_BOUND),   *)
(* and we take a0 = cb + 1. Collapsing a definable hull over the reflected   *)
(* stage union gives a transitive M' = Mp IN D with |Mp| <= kappa and        *)
(* g0 SUBSET Som (MPRIME_COLLAPSE_EXISTS); XX survives the collapse          *)
(* (E XX Mp, MPRIME_X_SURVIVES). Since M' |= V=L, XX is in a stage L(aX)     *)
(* with aX IN Mp (MPRIME_STAGES_OF_VL); Mp is transitive, so aX SUBSET Mp    *)
(* and einj aX kappa (EINJ_RESTRICT_DOM on the injection of Mp), hence       *)
(* aX < kappa+ (EORDINAL_INJ_LT_SUCCARD); ELSTAGE_MONO lifts XX into         *)
(* L(kappa+).                                                                *)
(* ------------------------------------------------------------------------- *)

let GCH_SUBSET_IN_SUCCARD_STAGE = prove
 (`!D (E:A->A->bool) kappa XX om.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ (E om kappa \/ om = kappa) /\
     ecardinal D E kappa /\ kappa IN D /\
     XX IN D /\ (!xi. xi IN D /\ E xi XX ==> E xi kappa)
     ==> ?kp y. kp IN D /\ ecardinal D E kp /\ E kappa kp /\
                (!c'. c' IN D /\ E c' kp
                      ==> ~(ecardinal D E c' /\ E kappa c')) /\
                y IN D /\ elstage D E kp y /\ E XX y`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kappa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`] ESUCCARD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `kp:A` STRIP_ASSUME_TAC) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`XX:A`;`om:A`]
    GCH_SEED_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `g0:A`
             (X_CHOOSE_THEN `eg0:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!z. z IN D /\ (E:A->A->bool) z g0 ==> elmem D E z`
    ASSUME_TAC THENL
   [X_GEN_TAC `z:A` THEN STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`g0:A`] ELMEM_BOUND) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `cb:A`
             (X_CHOOSE_THEN `ycb:A` STRIP_ASSUME_TAC)) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`cb:A`] ESUC_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `a0:A`) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) a0` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`cb:A`;`a0:A`]
                 EORDINAL_ESUC) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(a0:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) cb a0` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`cb:A`;`a0:A`]
                 ESUC_MEMBER) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!u. u IN D /\ (E:A->A->bool) u g0
        ==> ?b y. b IN D /\ y IN D /\ E b a0 /\ elstage D E b y /\ E u y`
   ASSUME_TAC THENL
   [X_GEN_TAC `u:A` THEN STRIP_TAC THEN
    MAP_EVERY EXISTS_TAC [`cb:A`;`ycb:A`] THEN
    ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!oi. eomega D (E:A->A->bool) oi ==> E oi kappa \/ oi = kappa`
   ASSUME_TAC THENL
   [X_GEN_TAC `oi:A` THEN DISCH_TAC THEN ASM_MESON_TAC[EOMEGA_UNIQUE];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`a0:A`;`g0:A`;`kappa:A`;`eg0:A`]
    MPRIME_COLLAPSE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[] THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `Mp:A` (X_CHOOSE_THEN `Som:A` (X_CHOOSE_THEN `za:A`
    (X_CHOOSE_THEN `ld:A` (X_CHOOSE_THEN `gd:A` (X_CHOOSE_THEN `cc:A`
     STRIP_ASSUME_TAC)))))) THEN
  SUBGOAL_THEN `(E:A->A->bool) XX g0` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) XX Som` ASSUME_TAC THENL
   [ASM_MESON_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `!xi. xi IN D /\ (E:A->A->bool) xi kappa ==> E xi Som`
    ASSUME_TAC THENL
   [X_GEN_TAC `xi:A` THEN STRIP_TAC THEN ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Som:A`;`za:A`;`ld:A`;`gd:A`;`cc:A`;
                `Mp:A`;`kappa:A`;`XX:A`] MPRIME_X_SURVIVES) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Mp:A`] MPRIME_STAGES_OF_VL) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(MP_TAC o SPEC `XX:A`) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `aX:A`
             (X_CHOOSE_THEN `yaX:A` STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `!k. k IN D /\ (E:A->A->bool) k aX ==> E k Mp` ASSUME_TAC THENL
   [REWRITE_TAC[GSYM esubset] THEN
    FIRST_ASSUM(MATCH_MP_TAC o REWRITE_RULE[etransitive]) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!k t. k IN D /\ t IN D /\ (E:A->A->bool) k aX /\ eapply D E e k t
          ==> E t kappa`
   ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`k:A`;`t:A`] (CONJUNCT1(CONJUNCT2(REWRITE_RULE[einj]
      (ASSUME `einj D (E:A->A->bool) e Mp kappa`))))) THEN
    ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL
         [`D:A->bool`;`E:A->A->bool`;`e:A`;`Mp:A`;`kappa:A`;`aX:A`;`kappa:A`]
         EINJ_RESTRICT_DOM) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `einjaX:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`aX:A`;`kappa:A`;`kp:A`;`einjaX:A`]
    EORDINAL_INJ_LT_SUCCARD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kp:A`] ELSTAGE_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `ykp:A` STRIP_ASSUME_TAC) THEN
  SUBGOAL_THEN `(E:A->A->bool) XX ykp` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL
                 [`D:A->bool`;`E:A->A->bool`;`kp:A`;`aX:A`;`ykp:A`;`yaX:A`;
                  `XX:A`] ELSTAGE_MONO) THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY EXISTS_TAC [`kp:A`;`ykp:A`] THEN ASM_REWRITE_TAC[]);;

(* ========================================================================= *)
(* The power-set formula pow_form and its characterization HOLDS_POW_FORM.   *)
(* ========================================================================= *)

let pow_form = new_definition
  `pow_form i j =
     !! (MAX i j + 1)
        (((MAX i j + 1) %% i) <-> subset_form (MAX i j + 1) j)`;;

let HOLDS_POW_FORM = prove
 (`!D (E:A->A->bool) v i j.
        valuation D v
        ==> (holds D E v (pow_form i j) <=> epow D E (v j) (v i))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[pow_form; holds; HOLDS_IFF; HOLDS_SUBSET_FORM] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
           ARITH_RULE `~(i = MAX i j + 1)`;
           ARITH_RULE `~(j = MAX i j + 1)`] THEN
  REWRITE_TAC[epow] THEN ASM_REWRITE_TAC[] THEN MESON_TAC[]);;

(* ========================================================================= *)
(* The bijection formula bijform, with the disequalities of its slots        *)
(* (BIJFORM_DISEQ) and its characterizations HOLDS_BIJFORM and               *)
(* HOLDS_BIJFORM_EBIJ.                                                       *)
(* ========================================================================= *)

let bijform = new_definition
  `bijform a b =
     ?? (MAX a b + 1)
       ((!! (MAX a b + 2) (!! (MAX a b + 3)
            (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3) -->
               (((MAX a b + 2) %% a) && ((MAX a b + 3) %% b))))) &&
        ((!! (MAX a b + 2)
            (((MAX a b + 2) %% a) -->
               ?? (MAX a b + 3)
                  (((MAX a b + 3) %% b) &&
                   apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3)))) &&
         ((!! (MAX a b + 2) (!! (MAX a b + 3) (!! (MAX a b + 4)
             ((apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3) &&
               apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 4)) -->
              Eq (MAX a b + 3) (MAX a b + 4))))) &&
          ((!! (MAX a b + 2) (!! (MAX a b + 5) (!! (MAX a b + 3)
              ((apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3) &&
                apply_form (MAX a b + 1) (MAX a b + 5) (MAX a b + 3)) -->
               Eq (MAX a b + 2) (MAX a b + 5))))) &&
           (!! (MAX a b + 3)
              (((MAX a b + 3) %% b) -->
               ?? (MAX a b + 2)
                  (((MAX a b + 2) %% a) &&
                   apply_form (MAX a b + 1) (MAX a b + 2)
                     (MAX a b + 3))))))))`;;

let BIJFORM_DISEQ = ARITH_RULE
 `~(MAX a b + 1 = MAX a b + 2) /\ ~(MAX a b + 2 = MAX a b + 1) /\
  ~(MAX a b + 1 = MAX a b + 3) /\ ~(MAX a b + 3 = MAX a b + 1) /\
  ~(MAX a b + 1 = MAX a b + 4) /\ ~(MAX a b + 4 = MAX a b + 1) /\
  ~(MAX a b + 1 = MAX a b + 5) /\ ~(MAX a b + 5 = MAX a b + 1) /\
  ~(MAX a b + 2 = MAX a b + 3) /\ ~(MAX a b + 3 = MAX a b + 2) /\
  ~(MAX a b + 2 = MAX a b + 4) /\ ~(MAX a b + 4 = MAX a b + 2) /\
  ~(MAX a b + 2 = MAX a b + 5) /\ ~(MAX a b + 5 = MAX a b + 2) /\
  ~(MAX a b + 3 = MAX a b + 4) /\ ~(MAX a b + 4 = MAX a b + 3) /\
  ~(MAX a b + 3 = MAX a b + 5) /\ ~(MAX a b + 5 = MAX a b + 3) /\
  ~(MAX a b + 4 = MAX a b + 5) /\ ~(MAX a b + 5 = MAX a b + 4) /\
  ~(a = MAX a b + 1) /\ ~(a = MAX a b + 2) /\ ~(a = MAX a b + 3) /\
  ~(a = MAX a b + 4) /\ ~(a = MAX a b + 5) /\
  ~(b = MAX a b + 1) /\ ~(b = MAX a b + 2) /\ ~(b = MAX a b + 3) /\
  ~(b = MAX a b + 4) /\ ~(b = MAX a b + 5)`;;

let HOLDS_BIJFORM = prove
 (`!D (E:A->A->bool) v a b.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bijform a b) <=>
             ?f. f IN D /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> eapply D E f k t
                                  ==> E k (v a) /\ E t (v b)) /\
                 (!k. k IN D
                      ==> E k (v a)
                          ==> ?t. t IN D /\
                                  E t (v b) /\ eapply D E f k t) /\
                 (!k. k IN D
                      ==> !t. t IN D
                              ==> !t'. t' IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k t'
                                           ==> t = t') /\
                 (!k. k IN D
                      ==> !k'. k' IN D
                               ==> !t. t IN D
                                       ==> eapply D E f k t /\
                                           eapply D E f k' t
                                           ==> k = k') /\
                 (!t. t IN D
                      ==> E t (v b)
                          ==> ?k. k IN D /\
                                  E k (v a) /\ eapply D E f k t))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t:A. f IN D /\ k IN D /\ t IN D
      ==> (holds D E (((MAX a b + 3) |-> t) (((MAX a b + 2) |-> k)
             (((MAX a b + 1) |-> f) v)))
             (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3)) <=>
           eapply D (E:A->A->bool) f k t)`
  (LABEL_TAC "r1") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX a b + 3) |-> (t:A)) (((MAX a b + 2) |-> (k:A))
         (((MAX a b + 1) |-> (f:A)) v))`;
      `MAX a b + 1`; `MAX a b + 2`; `MAX a b + 3`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFORM_DISEQ];
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k t t':A. f IN D /\ k IN D /\ t IN D /\ t' IN D
      ==> (holds D E (((MAX a b + 4) |-> t') (((MAX a b + 3) |-> t)
             (((MAX a b + 2) |-> k) (((MAX a b + 1) |-> f) v))))
             (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3)) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E (((MAX a b + 4) |-> t') (((MAX a b + 3) |-> t)
             (((MAX a b + 2) |-> k) (((MAX a b + 1) |-> f) v))))
             (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 4)) <=>
           eapply D E f k t')`
  (LABEL_TAC "r2") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX a b + 4) |-> (t':A)) (((MAX a b + 3) |-> (t:A))
           (((MAX a b + 2) |-> (k:A)) (((MAX a b + 1) |-> (f:A)) v)))`;
        `MAX a b + 1`; `MAX a b + 2`; `MAX a b + 3`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX a b + 4) |-> (t':A)) (((MAX a b + 3) |-> (t:A))
           (((MAX a b + 2) |-> (k:A)) (((MAX a b + 1) |-> (f:A)) v)))`;
        `MAX a b + 1`; `MAX a b + 2`; `MAX a b + 4`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFORM_DISEQ]);
    ALL_TAC] THEN
  SUBGOAL_THEN
   `!f k k' t:A. f IN D /\ k IN D /\ k' IN D /\ t IN D
      ==> (holds D E (((MAX a b + 3) |-> t) (((MAX a b + 5) |-> k')
             (((MAX a b + 2) |-> k) (((MAX a b + 1) |-> f) v))))
             (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3)) <=>
           eapply D (E:A->A->bool) f k t) /\
          (holds D E (((MAX a b + 3) |-> t) (((MAX a b + 5) |-> k')
             (((MAX a b + 2) |-> k) (((MAX a b + 1) |-> f) v))))
             (apply_form (MAX a b + 1) (MAX a b + 5) (MAX a b + 3)) <=>
           eapply D E f k' t)`
  (LABEL_TAC "r3") THENL
   [REPEAT GEN_TAC THEN STRIP_TAC THEN CONJ_TAC THENL
     [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX a b + 3) |-> (t:A)) (((MAX a b + 5) |-> (k':A))
           (((MAX a b + 2) |-> (k:A)) (((MAX a b + 1) |-> (f:A)) v)))`;
        `MAX a b + 1`; `MAX a b + 2`; `MAX a b + 3`] HOLDS_APPLY_FORM);
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
        `((MAX a b + 3) |-> (t:A)) (((MAX a b + 5) |-> (k':A))
           (((MAX a b + 2) |-> (k:A)) (((MAX a b + 1) |-> (f:A)) v)))`;
        `MAX a b + 1`; `MAX a b + 5`; `MAX a b + 3`] HOLDS_APPLY_FORM)]
    THEN
    (ANTS_TAC THENL
      [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
       MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
       ALL_TAC] THEN
     DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
     SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFORM_DISEQ]);
    ALL_TAC] THEN
  REWRITE_TAC[bijform; HOLDS_EX; HOLDS_AND; holds] THEN
  SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFORM_DISEQ] THEN
  MATCH_MP_TAC(MESON[]
   `(!f:A. P f <=> Q f) ==> ((?f. P f) <=> (?f. Q f))`) THEN
  X_GEN_TAC `f:A` THEN
  MATCH_MP_TAC(TAUT
   `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
  DISCH_TAC THEN
  USE_THEN "r1" (fun th1 -> USE_THEN "r2" (fun th2 ->
    USE_THEN "r3" (fun th3 -> ASM_SIMP_TAC[th1; th2; th3]))) THEN
  SUBGOAL_THEN
   `!f k t:A. f IN D /\ k IN D /\ t IN D
      ==> (holds D E (((MAX a b + 2) |-> k) (((MAX a b + 3) |-> t)
             (((MAX a b + 1) |-> f) v)))
             (apply_form (MAX a b + 1) (MAX a b + 2) (MAX a b + 3)) <=>
           eapply D (E:A->A->bool) f k t)`
  (LABEL_TAC "r4") THENL
   [REPEAT STRIP_TAC THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`;
      `((MAX a b + 2) |-> (k:A)) (((MAX a b + 3) |-> (t:A))
         (((MAX a b + 1) |-> (f':A)) v))`;
      `MAX a b + 1`; `MAX a b + 2`; `MAX a b + 3`] HOLDS_APPLY_FORM) THEN
    ANTS_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
      MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; BIJFORM_DISEQ];
    ALL_TAC] THEN
  MATCH_MP_TAC(TAUT
   `(b <=> b') /\ (e <=> e')
    ==> ((a /\ b /\ c /\ d /\ e) <=> (a /\ b' /\ c /\ d /\ e'))`) THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((!k:A. P k) <=> (!k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((?t:A. P t) <=> (?t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r1" (fun th -> ASM_SIMP_TAC[th]);
    MATCH_MP_TAC(MESON[]
     `(!t:A. P t <=> Q t) ==> ((!t:A. P t) <=> (!t:A. Q t))`) THEN
    X_GEN_TAC `t:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a ==> p) <=> (a ==> q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(MESON[]
     `(!k:A. P k <=> Q k) ==> ((?k:A. P k) <=> (?k:A. Q k))`) THEN
    X_GEN_TAC `k:A` THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    MATCH_MP_TAC(TAUT
     `(a ==> (p <=> q)) ==> ((a /\ p) <=> (a /\ q))`) THEN
    DISCH_TAC THEN
    USE_THEN "r4" (fun th -> ASM_SIMP_TAC[th])]);;

let HOLDS_BIJFORM_EBIJ = prove
 (`!D (E:A->A->bool) v a b.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (bijform a b) <=> ?f. ebij D E f (v a) (v b))`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `a:num`; `b:num`]
    HOLDS_BIJFORM) THEN
  ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
  REWRITE_TAC[ebij; IMP_CONJ; RIGHT_IMP_FORALL_THM]);;

(* ========================================================================= *)
(* 2^kappa = kappa+: for an infinite cardinal kappa in a model of ZF + V=L,  *)
(* the power set P(kappa) has cardinality exactly the successor cardinal     *)
(* kappa+.                                                                   *)
(*                                                                           *)
(*   ESUCCARD_UNIQUE  - the successor cardinal is unique (minimality).       *)
(*   GCH_POW_CARD_LE  - 2^kappa <= kappa+: P(kappa) injects into kappa+      *)
(*                      (every subset of kappa lands in L(kappa+), of        *)
(*                      size <= kappa+).                                     *)
(*   ECARDOF_POW_GT   - sharp Cantor: kappa < |P(kappa)| as ordinals.        *)
(*   GCH_POW_CARDOF   - 2^kappa = kappa+: |P(kappa)| = kappa+ (as            *)
(*                      ecardof).                                            *)
(* ========================================================================= *)

let ESUCCARD_UNIQUE = prove
 (`!D (E:A->A->bool) k kp kp'.
     model D E ZF_AX /\ eordinal D E k /\
     kp IN D /\ ecardinal D E kp /\ E k kp /\
     (!c'. c' IN D /\ E c' kp ==> ~(ecardinal D E c' /\ E k c')) /\
     kp' IN D /\ ecardinal D E kp' /\ E k kp' /\
     (!c'. c' IN D /\ E c' kp' ==> ~(ecardinal D E c' /\ E k c'))
     ==> kp = kp'`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp'` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kp:A`;`kp':A`]
         EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [ASM_MESON_TAC[]; FIRST_ASSUM ACCEPT_TAC; ASM_MESON_TAC[]]);;

let GCH_POW_CARD_LE = prove
 (`!D (E:A->A->bool) kappa om.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ (E om kappa \/ om = kappa) /\
     ecardinal D E kappa /\ kappa IN D
     ==> ?kp Pk f. kp IN D /\ ecardinal D E kp /\ E kappa kp /\
                   (!c'. c' IN D /\ E c' kp
                         ==> ~(ecardinal D E c' /\ E kappa c')) /\
                   epow D E kappa Pk /\ Pk IN D /\
                   einj D E f Pk kp`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kappa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`] EHFSET_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `hf:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`] EHFORD_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `ho:A`) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`om:A`;`hf:A`;`ho:A`;`kappa:A`]
    ELSUCCARD_STAGE_CARD) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `kp:A` (X_CHOOSE_THEN `e:A` (X_CHOOSE_THEN `ya:A`
    STRIP_ASSUME_TAC))) THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`] EPOW_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `Pk:A`) THEN
  SUBGOAL_THEN `(Pk:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EPOW_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `!X. X IN D /\ (E:A->A->bool) X Pk ==> E X ya` ASSUME_TAC THENL
   [X_GEN_TAC `X:A` THEN STRIP_TAC THEN
    SUBGOAL_THEN `!xi. xi IN D /\ (E:A->A->bool) xi X ==> E xi kappa`
      ASSUME_TAC THENL
      [X_GEN_TAC `xi:A` THEN STRIP_TAC THEN
      SUBGOAL_THEN `esubset D (E:A->A->bool) X kappa` MP_TAC THENL
       [ASM_MESON_TAC[epow]; ALL_TAC] THEN
      REWRITE_TAC[esubset] THEN DISCH_THEN MATCH_MP_TAC THEN ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`X:A`;`om:A`]
      GCH_SUBSET_IN_SUCCARD_STAGE) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `kp2:A`
               (X_CHOOSE_THEN `y2:A` STRIP_ASSUME_TAC)) THEN
    SUBGOAL_THEN `kp2:A = kp` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`kp2:A`;`kp:A`]
        ESUCCARD_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    SUBGOAL_THEN `y2:A = ya` SUBST_ALL_TAC THENL
     [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kp:A`;`y2:A`;`ya:A`]
        ELSTAGE_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    FIRST_ASSUM ACCEPT_TAC; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Pk:A`] EBIJ_ID) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `idP:A`) THEN
  SUBGOAL_THEN `einj D (E:A->A->bool) idP Pk ya` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL
                 [`D:A->bool`;`E:A->A->bool`;`idP:A`;`Pk:A`;`Pk:A`;`ya:A`]
                 EINJ_WEAKEN) THEN
    ASM_REWRITE_TAC[] THEN MATCH_MP_TAC EBIJ_EINJ THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`idP:A`;`e:A`;`Pk:A`;`ya:A`;`kp:A`]
    EINJ_COMPOSE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `f:A`) THEN
  MAP_EVERY EXISTS_TAC [`kp:A`;`Pk:A`;`f:A`] THEN ASM_REWRITE_TAC[]);;

let ECARDOF_POW_GT = prove
 (`!D (E:A->A->bool) k p c.
     model D E ZF_AX /\ eordinal D E k /\ epow D E k p /\ ecardof D E p c
     ==> E k c`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN
  SUBGOAL_THEN `(k:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
  SUBGOAL_THEN `(p:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[epow]; ALL_TAC] THEN
  MP_TAC(REWRITE_RULE[ecardof] (ASSUME `ecardof D (E:A->A->bool) p c`)) THEN
  INTRO_TAC "h1 h2 (@g. h3) _" THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) c` ASSUME_TAC THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `p:A`; `c:A`]
      ECARDOF_CARDINAL) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN ACCEPT_TAC;
    ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `c:A`]
    EORDINAL_TRICHOTOMY) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN ASSUME_TAC) THENL
   [FIRST_ASSUM ACCEPT_TAC;
    SUBGOAL_THEN
     `!t:A. t IN D /\ E t c ==> (E:A->A->bool) t k`
    (LABEL_TAC "ts") THENL
     [REPEAT STRIP_TAC THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `c:A`; `p:A`]
      EBIJ_SYM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `g':A` MP_TAC) THEN REWRITE_TAC[ebij] THEN
    INTRO_TAC "h4 _ st _ si _" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `p:A`; `g':A`]
      ECANTOR_INJ) THEN
    ANTS_TAC THENL
     [SUBGOAL_THEN
       `!q:A. q IN D /\ E q p
          ==> ?t. t IN D /\ E t k /\ eapply D (E:A->A->bool) g' q t`
      ASSUME_TAC THENL
       [X_GEN_TAC `q:A` THEN STRIP_TAC THEN
        USE_THEN "st" (MP_TAC o SPEC `q:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "ts" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[]];
    SUBGOAL_THEN
     `!t:A. t IN D /\ E t c ==> (E:A->A->bool) t k`
    (LABEL_TAC "ts") THENL
     [REPEAT STRIP_TAC THEN
      MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `c:A`; `t:A`]
        EORDINAL_TRANS_MEM) THEN
      ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
      DISCH_THEN ACCEPT_TAC;
      ALL_TAC] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `g:A`; `c:A`; `p:A`]
      EBIJ_SYM) THEN
    ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
    DISCH_THEN(X_CHOOSE_THEN `g':A` MP_TAC) THEN REWRITE_TAC[ebij] THEN
    INTRO_TAC "h5 _ st _ si _" THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `k:A`; `p:A`; `g':A`]
      ECANTOR_INJ) THEN
    ANTS_TAC THENL
     [SUBGOAL_THEN
       `!q:A. q IN D /\ E q p
          ==> ?t. t IN D /\ E t k /\ eapply D (E:A->A->bool) g' q t`
      ASSUME_TAC THENL
       [X_GEN_TAC `q:A` THEN STRIP_TAC THEN
        USE_THEN "st" (MP_TAC o SPEC `q:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN(X_CHOOSE_THEN `t:A` STRIP_ASSUME_TAC) THEN
        EXISTS_TAC `t:A` THEN ASM_REWRITE_TAC[] THEN
        USE_THEN "ts" (MP_TAC o SPEC `t:A`) THEN
        ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
        DISCH_THEN ACCEPT_TAC;
        ALL_TAC] THEN
      ASM_REWRITE_TAC[];
      REWRITE_TAC[]]]);;

let GCH_POW_CARDOF = prove
 (`!D (E:A->A->bool) kappa om.
     model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\
     eomega D E om /\ (E om kappa \/ om = kappa) /\
     ecardinal D E kappa /\ kappa IN D
     ==> ?kp Pk. kp IN D /\ ecardinal D E kp /\ E kappa kp /\
                 (!c'. c' IN D /\ E c' kp
                       ==> ~(ecardinal D E c' /\ E kappa c')) /\
                 epow D E kappa Pk /\ Pk IN D /\ ecardof D E Pk kp`,
  REPEAT GEN_TAC THEN DISCH_THEN(REPEAT_TCL CONJUNCTS_THEN ASSUME_TAC) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kappa` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`om:A`]
         GCH_POW_CARD_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `kp:A` (X_CHOOSE_THEN `Pk:A` (X_CHOOSE_THEN `f:A`
    STRIP_ASSUME_TAC))) THEN
  SUBGOAL_THEN `eordinal D (E:A->A->bool) kp` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`Pk:A`] ECARDOF_EXISTS) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_TAC `cP:A`) THEN
  SUBGOAL_THEN `(cP:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) cP` ASSUME_TAC THENL
   [ASM_MESON_TAC[ECARDOF_CARDINAL]; ALL_TAC] THEN
  SUBGOAL_THEN `(E:A->A->bool) kappa cP` ASSUME_TAC THENL
   [MATCH_MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`kappa:A`;`Pk:A`;`cP:A`]
      ECARDOF_POW_GT) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`;`E:A->A->bool`;`f:A`;`Pk:A`;`kp:A`;`cP:A`]
    EINJ_ORDINAL_CARD_LE) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(DISJ_CASES_THEN ASSUME_TAC) THENL
   [SUBGOAL_THEN `F` MP_TAC THENL
     [ASM_MESON_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[];
    MAP_EVERY EXISTS_TAC [`kp:A`;`Pk:A`] THEN ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[]]);;

(* ========================================================================= *)
(* Object formulas for cardinals: iscard_form, infcard_form and              *)
(* succard_form, with their characterizations. iscard_form i: v i is a       *)
(* cardinal.                                                                 *)
(* ========================================================================= *)

let iscard_form = new_definition
  `iscard_form i = ordinal_form i && !!- (i + 1) i (Not (bijform (i + 1) i))`;;

let HOLDS_ISCARD_FORM = prove
 (`!D (E:A->A->bool) v i.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (iscard_form i) <=> ecardinal D E (v i))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[iscard_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ORDINAL_FORM] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v (!!- (i + 1) i (Not (bijform (i + 1) i))) <=>
    (!a. a IN D /\ E a (v i) ==> ~(?f. ebij D E f a (v i)))`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `i + 1`; `i:num`;
                  `Not (bijform (i + 1) i)`] HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!a:A. P a <=> Q a) ==> ((!a. P a) <=> (!a. Q a))`) THEN
    X_GEN_TAC `a:A` THEN
    MATCH_MP_TAC(TAUT `(c ==> (p <=> q)) ==> ((c ==> p) <=> (c ==> q))`) THEN
    STRIP_TAC THEN
    REWRITE_TAC[HOLDS_NOT] THEN
    MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `((i + 1) |-> (a:A)) v`;
                  `i + 1`; `i:num`] HOLDS_BIJFORM_EBIJ) THEN
    ANTS_TAC THENL
     [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC VALUATION_VALMOD THEN
      ASM_REWRITE_TAC[];
      ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i:num = i + 1)`];
    ALL_TAC] THEN
  REWRITE_TAC[ecardinal; ecardof] THEN
  EQ_TAC THENL
   [STRIP_TAC THEN
    SUBGOAL_THEN `(v:num->A) i IN D` ASSUME_TAC THENL
     [ASM_MESON_TAC[EORDINAL_IN]; ALL_TAC] THEN
    ASM_REWRITE_TAC[] THEN
    ASM_MESON_TAC[EBIJ_ID];
    STRIP_TAC THEN ASM_REWRITE_TAC[]]);;

(* ------------------------------------------------------------------------- *)
(* infcard_form i: "v i is an infinite cardinal".                            *)
(* ------------------------------------------------------------------------- *)

let infcard_form = new_definition
  `infcard_form i =
     iscard_form i &&
     ?? (i + 1) (omega_form (i + 1) && (((i + 1) %% i) || Eq (i + 1) i))`;;

let HOLDS_INFCARD_FORM = prove
 (`!D (E:A->A->bool) v i.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (infcard_form i) <=>
             ecardinal D E (v i) /\
             (?om. om IN D /\ eomega D E om /\ (E om (v i) \/ om = v i)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[infcard_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ISCARD_FORM] THEN
  MATCH_MP_TAC(TAUT `(x <=> y) ==> ((a /\ x) <=> (a /\ y))`) THEN
  REWRITE_TAC[HOLDS_EX] THEN
  MATCH_MP_TAC(MESON[]
   `(!a:A. P a <=> Q a) ==> ((?a. P a) <=> (?a. Q a))`) THEN
  X_GEN_TAC `a:A` THEN
  MATCH_MP_TAC(TAUT `(c ==> (p <=> q)) ==> ((c /\ p) <=> (c /\ q))`) THEN
  DISCH_TAC THEN
  SUBGOAL_THEN `valuation D (((i + 1) |-> (a:A)) v)` ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_OR; HOLDS_OMEGA_FORM] THEN
  REWRITE_TAC[holds] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; ARITH_RULE `~(i:num = i + 1)`]);;

(* ------------------------------------------------------------------------- *)
(* succard_form i j: "v i is the successor cardinal of v j".                 *)
(* ------------------------------------------------------------------------- *)

let succard_form = new_definition
  `succard_form i j =
     iscard_form i &&
     ((j %% i) &&
      !!- (MAX i j + 1) i
         ((j %% (MAX i j + 1)) --> Not (iscard_form (MAX i j + 1))))`;;

let HOLDS_SUCCARD_FORM = prove
 (`!D (E:A->A->bool) v i j.
        model D E ZF_AX /\ valuation D v
        ==> (holds D E v (succard_form i j) <=>
             ecardinal D E (v i) /\ E (v j) (v i) /\
             (!c. c IN D /\ E c (v i) ==> E (v j) c ==> ~(ecardinal D E c)))`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[succard_form; HOLDS_AND] THEN
  ASM_SIMP_TAC[HOLDS_ISCARD_FORM] THEN
  SUBGOAL_THEN
   `holds D (E:A->A->bool) v
       (!!- (MAX i j + 1) i
          ((j %% (MAX i j + 1)) --> Not (iscard_form (MAX i j + 1)))) <=>
    (!c. c IN D /\ E c (v i) ==> E (v j) c ==> ~(ecardinal D E c))`
  (fun th -> REWRITE_TAC[th]) THENL
   [MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `v:num->A`; `MAX i j + 1`;
                  `i:num`;
                  `(j %% (MAX i j + 1)) --> Not (iscard_form (MAX i j + 1))`]
      HOLDS_FORALLMEM) THEN
    ANTS_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[th]) THEN
    MATCH_MP_TAC(MESON[]
     `(!c:A. P c <=> Q c) ==> ((!c. P c) <=> (!c. Q c))`) THEN
    X_GEN_TAC `c:A` THEN
    MATCH_MP_TAC(TAUT `(g ==> (p <=> q)) ==> ((g ==> p) <=> (g ==> q))`) THEN
    STRIP_TAC THEN
    SUBGOAL_THEN `valuation D (((MAX i j + 1) |-> (c:A)) v)` ASSUME_TAC THENL
     [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
    REWRITE_TAC[holds; HOLDS_NOT] THEN
    ASM_SIMP_TAC[HOLDS_ISCARD_FORM] THEN
    ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER;
                 ARITH_RULE `~(j:num = MAX i j + 1)`];
    ALL_TAC] THEN
  REWRITE_TAC[holds]);;

(* ========================================================================= *)
(* The object-language GCH axiom gch_ax, and its introduction rule.          *)
(* ========================================================================= *)

let gch_ax = new_definition
  `gch_ax =
     !! 0 (!! 1 (!! 2
        ((infcard_form 0 && (succard_form 1 0 && pow_form 2 0))
         --> bijform 1 2)))`;;

let GCH_SLOT_DISEQ = ARITH_RULE
 `~(0 = 1) /\ ~(1 = 0) /\ ~(0 = 2) /\ ~(2 = 0) /\ ~(1 = 2) /\ ~(2 = 1)`;;

(* ------------------------------------------------------------------------- *)
(* Syntactic reduction of gch_ax to its semantic content, packaged as an     *)
(* introduction rule: given the semantic GCH property, gch_ax holds.         *)
(* ------------------------------------------------------------------------- *)

let HOLDS_GCH_AX_INTRO = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v /\
        (!k kp P. k IN D /\ kp IN D /\ P IN D /\
                  ecardinal D E k /\
                  (?om. om IN D /\ eomega D E om /\ (E om k \/ om = k)) /\
                  ecardinal D E kp /\ E k kp /\
                  (!c. c IN D /\ E c kp ==> E k c ==> ~(ecardinal D E c)) /\
                  epow D E k P
                  ==> ?f. ebij D E f kp P)
        ==> holds D E v gch_ax`,
  REPEAT GEN_TAC THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (CONJUNCTS_THEN2 ASSUME_TAC
    (LABEL_TAC "gp"))) THEN
  SUBGOAL_THEN `!x. (v:num->A) x IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[valuation]; ALL_TAC] THEN
  REWRITE_TAC[gch_ax] THEN REWRITE_TAC[holds] THEN
  X_GEN_TAC `k:A` THEN DISCH_TAC THEN
  X_GEN_TAC `kp:A` THEN DISCH_TAC THEN
  X_GEN_TAC `P:A` THEN DISCH_TAC THEN
  SUBGOAL_THEN
   `valuation D ((2 |-> (P:A)) ((1 |-> (kp:A)) ((0 |-> (k:A)) v)))`
  ASSUME_TAC THENL
   [MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VALUATION_VALMOD THEN ASM_REWRITE_TAC[];
    ALL_TAC] THEN
  ASM_SIMP_TAC[HOLDS_AND; HOLDS_INFCARD_FORM; HOLDS_SUCCARD_FORM;
               HOLDS_POW_FORM; HOLDS_BIJFORM_EBIJ] THEN
  ASM_SIMP_TAC[VALMOD_BASIC; VALMOD_OTHER; GCH_SLOT_DISEQ] THEN
  DISCH_TAC THEN
  USE_THEN "gp" (MP_TAC o SPECL [`k:A`; `kp:A`; `P:A`]) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ========================================================================= *)
(* The main results: GCH and CH in a model of ZF + V=L, and hence a model of *)
(* ZFC + GCH inside any model of ZF (Con(ZF) ==> Con(ZFC + GCH)).            *)
(* ========================================================================= *)

(* ------------------------------------------------------------------------- *)
(* The semantic GCH property of a model of ZF + V=L (VL_GCH_PROPERTY): for   *)
(* an infinite cardinal k with successor cardinal kp, the power set P(k) is  *)
(* in bijection with kp.                                                     *)
(* ------------------------------------------------------------------------- *)

let VL_GCH_PROPERTY = prove
 (`!N (E:A->A->bool).
        model N E ZF_AX /\ (!u. u IN N ==> elmem N E u)
        ==> !k kp P. k IN N /\ kp IN N /\ P IN N /\
                     ecardinal N E k /\
                     (?om. om IN N /\ eomega N E om /\ (E om k \/ om = k)) /\
                     ecardinal N E kp /\ E k kp /\
                     (!c. c IN N /\ E c kp ==> E k c ==> ~(ecardinal N E c)) /\
                     epow N E k P
                     ==> ?f. ebij N E f kp P`,
  REPEAT GEN_TAC THEN STRIP_TAC THEN REPEAT GEN_TAC THEN
  DISCH_THEN(fun th -> MAP_EVERY ASSUME_TAC (CONJUNCTS th)) THEN
  FIRST_X_ASSUM(X_CHOOSE_TAC `om:A`) THEN
  SUBGOAL_THEN `eordinal N (E:A->A->bool) k` ASSUME_TAC THENL
   [ASM_MESON_TAC[ecardinal; ecardof]; ALL_TAC] THEN
  SUBGOAL_THEN
   `!c'. c' IN N /\ (E:A->A->bool) c' kp ==> ~(ecardinal N E c' /\ E k c')`
  ASSUME_TAC THENL [ASM_MESON_TAC[]; ALL_TAC] THEN
  MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `k:A`; `om:A`]
         GCH_POW_CARDOF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(X_CHOOSE_THEN `kp0:A` (X_CHOOSE_THEN `Pk0:A`
    STRIP_ASSUME_TAC)) THEN
  SUBGOAL_THEN `kp:A = kp0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `k:A`; `kp:A`; `kp0:A`]
      ESUCCARD_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `P:A = Pk0` SUBST_ALL_TAC THENL
   [MATCH_MP_TAC(SPECL [`N:A->bool`; `E:A->A->bool`; `k:A`; `P:A`; `Pk0:A`]
      EPOW_UNIQUE) THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  ASM_MESON_TAC[ecardof]);;

let MODEL_VL_GCH = prove
 (`!N (E:A->A->bool).
        model N E ZF_AX /\ (!u. u IN N ==> elmem N E u)
        ==> model N E (gch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `model N (E:A->A->bool) (choice_ax INSERT ZF_AX)`
    (fun th -> MP_TAC(REWRITE_RULE[model; satisfies; IN_INSERT] th)) THENL
   [MATCH_MP_TAC MODEL_VL_CHOICE THEN ASM_REWRITE_TAC[]; ALL_TAC] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC (LABEL_TAC "scz")) THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN
  CONJ_TAC THENL [ASM_REWRITE_TAC[]; ALL_TAC] THEN
  MAP_EVERY X_GEN_TAC [`v:num->A`; `p:form`] THEN
  DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC ASSUME_TAC) THEN
  ASM_CASES_TAC `p:form = gch_ax` THENL
   [ASM_REWRITE_TAC[] THEN MATCH_MP_TAC HOLDS_GCH_AX_INTRO THEN
    ASM_REWRITE_TAC[] THEN
    MATCH_MP_TAC VL_GCH_PROPERTY THEN ASM_REWRITE_TAC[];
    USE_THEN "scz" MATCH_MP_TAC THEN ASM_MESON_TAC[]]);;

let ZF_MODEL_GCH_MODEL = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> ?D'. D' SUBSET D /\
                 model D' E (gch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT STRIP_TAC THEN EXISTS_TAC `lclass D (E:A->A->bool)` THEN
  ASM_SIMP_TAC[LCLASS_SUBSET; MODEL_VL_GCH; LCLASS_MODEL_VL]);;

let MODEL_VL_CH = prove
 (`!D (E:A->A->bool) om.
        model D E ZF_AX /\ (!u. u IN D ==> elmem D E u) /\ eomega D E om
        ==> ?kp Pk. kp IN D /\ ecardinal D E kp /\ E om kp /\
                    (!c'. c' IN D /\ E c' kp
                          ==> ~(ecardinal D E c' /\ E om c')) /\
                    epow D E om Pk /\ Pk IN D /\ ecardof D E Pk kp`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `ecardinal D (E:A->A->bool) om` ASSUME_TAC THENL
   [REWRITE_TAC[ecardinal] THEN MATCH_MP_TAC EOMEGA_CARDINAL THEN
    ASM_REWRITE_TAC[]; ALL_TAC] THEN
  SUBGOAL_THEN `(om:A) IN D` ASSUME_TAC THENL
   [ASM_MESON_TAC[eomega; einductive]; ALL_TAC] THEN
  MP_TAC(SPECL [`D:A->bool`; `E:A->A->bool`; `om:A`; `om:A`]
         GCH_POW_CARDOF) THEN
  ANTS_TAC THENL [ASM_REWRITE_TAC[]; DISCH_THEN ACCEPT_TAC]);;

(* ------------------------------------------------------------------------- *)
(* CH as an object-language axiom: the instance of gch_ax at omega. It holds *)
(* in L, so every model of ZF has a submodel of ZF + AC + CH. Its negation   *)
(* not_ch_ax is what Cohen forcing makes true in godel_forcing.ml.           *)
(* ------------------------------------------------------------------------- *)

let ch_ax = new_definition
  `ch_ax =
     !! 0 (!! 1 (!! 2
        ((omega_form 0 && (succard_form 1 0 && pow_form 2 0))
         --> bijform 1 2)))`;;

let not_ch_ax = new_definition
  `not_ch_ax = Not ch_ax`;;

let HOLDS_GCH_IMP_CH = prove
 (`!D (E:A->A->bool) v.
        model D E ZF_AX /\ valuation D v /\ holds D E v gch_ax
        ==> holds D E v ch_ax`,
  REPEAT GEN_TAC THEN REWRITE_TAC[gch_ax; ch_ax; holds; HOLDS_AND] THEN
  STRIP_TAC THEN X_GEN_TAC `k:A` THEN DISCH_TAC THEN
  X_GEN_TAC `kp:A` THEN DISCH_TAC THEN X_GEN_TAC `P:A` THEN DISCH_TAC THEN
  STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o SPEC `k:A`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `kp:A`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN(MP_TAC o SPEC `P:A`) THEN
  ASM_REWRITE_TAC[] THEN DISCH_THEN MATCH_MP_TAC THEN
  SUBGOAL_THEN `valuation D ((2 |-> (P:A)) ((1 |-> kp) ((0 |-> k) v)))`
  ASSUME_TAC THENL [ASM_SIMP_TAC[VALUATION_VALMOD]; ALL_TAC] THEN
  UNDISCH_TAC `holds D (E:A->A->bool) ((2 |-> P) ((1 |-> kp) ((0 |-> k) v)))
                 (omega_form 0)` THEN
  ASM_SIMP_TAC[HOLDS_OMEGA_FORM; HOLDS_INFCARD_FORM; ecardinal] THEN
  ASM_MESON_TAC[EOMEGA_CARDINAL; valuation]);;

let ZF_MODEL_CH_MODEL = prove
 (`!D (E:A->A->bool).
        model D E ZF_AX
        ==> ?D'. D' SUBSET D /\
                 model D' E (ch_ax INSERT choice_ax INSERT ZF_AX)`,
  REPEAT GEN_TAC THEN DISCH_THEN(MP_TAC o MATCH_MP ZF_MODEL_GCH_MODEL) THEN
  MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `N:A->bool` THEN
  REWRITE_TAC[model; satisfies; IN_INSERT] THEN STRIP_TAC THEN
  ASM_REWRITE_TAC[] THEN REPEAT STRIP_TAC THEN ASM_SIMP_TAC[] THEN
  MATCH_MP_TAC HOLDS_GCH_IMP_CH THEN ASM_SIMP_TAC[model; satisfies]);;
